add_action( 'elementor/query/vacatures_bij_beroep', function ( $query ) {

    // Alleen op een individuele beroep-pagina.
    if ( ! is_singular( 'beroep' ) ) {
        return;
    }

    // Functienamen ophalen die bij het huidige beroep zijn geselecteerd.
    $terms = get_the_terms(
        get_queried_object_id(),
        'functienaam'
    );

    // Geen functienamen geselecteerd: geen vacatures tonen.
    if ( empty( $terms ) || is_wp_error( $terms ) ) {
        $query->set( 'post__in', [ 0 ] );
        return;
    }

    $term_ids = wp_list_pluck( $terms, 'term_id' );

    // Alleen vacatures tonen met één van dezelfde functienamen.
    $query->set( 'post_type', 'vacature' );

    $query->set(
        'tax_query',
        [
            [
                'taxonomy' => 'functienaam',
                'field'    => 'term_id',
                'terms'    => $term_ids,
                'operator' => 'IN',
            ],
        ]
    );

} );

add_shortcode( 'functienaam_url', function () {

    if ( ! is_singular( 'beroep' ) ) {
        return '';
    }

    $terms = get_the_terms(
        get_queried_object_id(),
        'functienaam'
    );

    if ( empty( $terms ) || is_wp_error( $terms ) ) {
        return '';
    }

    // Gebruik de eerste geselecteerde functienaam.
    $url = get_term_link( $terms[0] );

    if ( is_wp_error( $url ) ) {
        return '';
    }

    return esc_url( $url );
} );

add_action( 'pre_get_posts', function ( $query ) {

    if (
        ! is_admin()
        && $query->is_main_query()
        && $query->is_tax( 'functienaam' )
    ) {
        $query->set( 'post_type', 'vacature' );
    }

} );

add_action( 'pre_get_posts', function ( $query ) {

    if ( is_admin() || ! $query->is_main_query() || ! $query->is_tax() ) {
        return;
    }

    // Alle taxonomieën ophalen die aan het CPT 'vacature' zijn gekoppeld.
    $vacature_taxonomieen = get_object_taxonomies( 'vacature', 'names' );

    $huidige_term = get_queried_object();

    if (
        $huidige_term instanceof WP_Term
        && in_array( $huidige_term->taxonomy, $vacature_taxonomieen, true )
    ) {
        // Op deze taxonomy-archieven uitsluitend vacatures tonen.
        $query->set( 'post_type', 'vacature' );
    }

} );

/**
 * Dynamische Elementor taxonomy-loops vanuit Pods relationshipvelden.
 *
 * Naamgeving:
 * - Taxonomy:        functienaam
 * - Pods-veld:       gerelateerde_functienaam
 * - Elementor Query ID: gerelateerde_functienaam
 */
add_action( 'init', function () {

    if ( ! function_exists( 'pods' ) ) {
        return;
    }

    // Maak automatisch een Elementor-queryhook voor iedere taxonomy.
    $taxonomies = get_taxonomies( [], 'names' );

    foreach ( $taxonomies as $taxonomy ) {

        $query_id  = 'gerelateerde_' . $taxonomy;
        $field_name = $query_id;

        add_action(
            'elementor/query/' . $query_id,
            function ( $query ) use ( $taxonomy, $field_name ) {

                if ( ! is_singular() ) {
                    return;
                }

                $post_id   = get_queried_object_id();
                $post_type = get_post_type( $post_id );

                if ( ! $post_id || ! $post_type ) {
                    return;
                }

                $pod = pods( $post_type, $post_id );

                if ( ! $pod || ! $pod->exists() ) {
                    return;
                }

                // Lees het gelijknamige Pods relationshipveld.
                $relations = $pod->field( $field_name );

                $term_ids = [];

                if ( ! empty( $relations ) ) {

                    // Eén resultaat ook als lijst verwerken.
                    if (
                        is_array( $relations )
                        && (
                            isset( $relations['term_id'] )
                            || isset( $relations['id'] )
                            || isset( $relations['ID'] )
                        )
                    ) {
                        $relations = [ $relations ];
                    }

                    foreach ( (array) $relations as $relation ) {

                        if ( is_numeric( $relation ) ) {
                            $term_ids[] = (int) $relation;
                            continue;
                        }

                        if ( is_array( $relation ) ) {
                            $term_ids[] = (int) (
                                $relation['term_id']
                                ?? $relation['id']
                                ?? $relation['ID']
                                ?? 0
                            );
                            continue;
                        }

                        if ( is_object( $relation ) ) {
                            $term_ids[] = (int) (
                                $relation->term_id
                                ?? $relation->id
                                ?? $relation->ID
                                ?? 0
                            );
                        }
                    }
                }

                $term_ids = array_values(
                    array_unique(
                        array_filter( $term_ids )
                    )
                );

                // Zonder geselecteerde relaties geen termen tonen.
                if ( empty( $term_ids ) ) {
                    $term_ids = [ 0 ];
                }

                /*
                 * Elementor-versies kunnen intern een iets ander
                 * queryobject gebruiken. Beide varianten ondersteunen.
                 */
                if ( method_exists( $query, 'set' ) ) {
                    $query->set( 'taxonomy', $taxonomy );
                    $query->set( 'include', $term_ids );
                    $query->set( 'hide_empty', false );
                    $query->set( 'orderby', 'include' );
                } elseif ( isset( $query->query_vars ) ) {
                    $query->query_vars['taxonomy']   = $taxonomy;
                    $query->query_vars['include']    = $term_ids;
                    $query->query_vars['hide_empty'] = false;
                    $query->query_vars['orderby']    = 'include';
                }
            }
        );
    }
}, 20 );

/**
 * Elementor taxonomy-loop met gerelateerde functienamen.
 *
 * Huidige posttype: beroep
 * Pods relationshipveld: relationship_functienamen
 * Taxonomy: functienaam
 * Elementor Query ID: gerelateerde_functienamen
 */
add_filter(
    'elementor/loop_taxonomy/args',
    function ( $args, $settings, $display_settings ) {

        // Alleen deze specifieke Elementor taxonomy-loop aanpassen.
        $query_id = $settings['term_taxonomy_id'] ?? '';

        if ( 'gerelateerde_functienamen' !== $query_id ) {
            return $args;
        }

        /*
         * Elementor gebruikt dit veld intern ook als term_taxonomy_id.
         * De tekstuele Query ID moet eruit, anders zoekt WordPress naar
         * een niet-bestaand numeriek term-taxonomy-ID.
         */
        unset( $args['term_taxonomy_id'] );

        // Alleen op een individuele beroep-pagina.
        if ( ! is_singular( 'beroep' ) || ! function_exists( 'pods' ) ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $post_id = get_queried_object_id();

        if ( ! $post_id ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $pod = pods( 'beroep', $post_id );

        if ( ! $pod || ! $pod->exists() ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        // Alleen het aparte relationshipveld uitlezen.
        $relations = $pod->field( 'relationship_functienamen' );

        if ( empty( $relations ) ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        /*
         * Bij één selectie kan Pods één associatieve array teruggeven.
         * Die zetten we om naar een lijst met één item.
         */
        if (
            is_array( $relations )
            && (
                isset( $relations['term_id'] )
                || isset( $relations['id'] )
                || isset( $relations['ID'] )
            )
        ) {
            $relations = [ $relations ];
        }

        $term_ids = [];

        foreach ( (array) $relations as $relation ) {
            $term_id = 0;

            if ( is_numeric( $relation ) ) {
                $term_id = (int) $relation;
            } elseif ( is_array( $relation ) ) {
                $term_id = (int) (
                    $relation['term_id']
                    ?? $relation['id']
                    ?? $relation['ID']
                    ?? 0
                );
            } elseif ( is_object( $relation ) ) {
                $term_id = (int) (
                    $relation->term_id
                    ?? $relation->id
                    ?? $relation->ID
                    ?? 0
                );
            }

            if ( ! $term_id ) {
                continue;
            }

            // Controleren dat de relatie echt een functienaam-term is.
            $term = get_term( $term_id, 'functienaam' );

            if ( $term instanceof WP_Term ) {
                $term_ids[] = $term_id;
            }
        }

        $term_ids = array_values(
            array_unique(
                array_filter( $term_ids )
            )
        );

        $args['taxonomy']   = 'functienaam';
        $args['include']    = $term_ids ?: [ 0 ];
        $args['hide_empty'] = false;
        $args['orderby']    = 'include';

        return $args;
    },
    20,
    3
);

/**
 * Generieke Elementor taxonomy-loop vanuit Pods relationshipvelden.
 *
 * Naamconventie:
 *
 * Taxonomy:
 * {taxonomy_name}
 *
 * Pods relationshipveld:
 * relationship_{taxonomy_name}
 *
 * Elementor Query ID:
 * relationship_{taxonomy_name}
 *
 * Voorbeeld:
 * functienaam
 * relationship_functienaam
 * relationship_functienaam
 */
add_filter(
    'elementor/loop_taxonomy/args',
    function ( $args, $settings, $display_settings ) {

        /*
         * Elementor plaatst de Query ID van een taxonomy-loop
         * momenteel in term_taxonomy_id.
         */
        $query_id = $args['term_taxonomy_id'] ?? '';

        if ( ! is_string( $query_id ) ) {
            return $args;
        }

        $query_id = sanitize_key( $query_id );
        $prefix   = 'relationship_';

        // Alleen onze relationship-queries verwerken.
        if ( strpos( $query_id, $prefix ) !== 0 ) {
            return $args;
        }

        /*
         * relationship_functienaam
         * wordt taxonomy functienaam.
         */
        $taxonomy = substr( $query_id, strlen( $prefix ) );

        if (
            empty( $taxonomy )
            || ! taxonomy_exists( $taxonomy )
            || ! function_exists( 'pods' )
        ) {
            return $args;
        }

        /*
         * De tekstuele Query ID mag niet als een numeriek
         * term_taxonomy_id naar WP_Term_Query gaan.
         */
        unset( $args['term_taxonomy_id'] );

        $post_id = get_queried_object_id();

        // Fallback voor de Elementor-preview.
        if ( ! $post_id ) {
            $post_id = get_the_ID();
        }

        $post_type = $post_id ? get_post_type( $post_id ) : false;

        if ( ! $post_id || ! $post_type ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $pod = pods( $post_type, $post_id );

        if ( ! $pod || ! $pod->exists() ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        /*
         * De Pods-veldnaam is exact gelijk aan de Query ID.
         */
        $relations = $pod->field( $query_id );

        if ( empty( $relations ) ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        /*
         * Bij één selectie kan Pods één associatieve array
         * teruggeven in plaats van een lijst.
         */
        if (
            is_array( $relations )
            && (
                isset( $relations['term_id'] )
                || isset( $relations['id'] )
                || isset( $relations['ID'] )
            )
        ) {
            $relations = [ $relations ];
        }

        $term_ids = [];

        foreach ( (array) $relations as $relation ) {

            $term_id = 0;

            if ( is_numeric( $relation ) ) {
                $term_id = (int) $relation;
            } elseif ( is_array( $relation ) ) {
                $term_id = (int) (
                    $relation['term_id']
                    ?? $relation['id']
                    ?? $relation['ID']
                    ?? 0
                );
            } elseif ( is_object( $relation ) ) {
                $term_id = (int) (
                    $relation->term_id
                    ?? $relation->id
                    ?? $relation->ID
                    ?? 0
                );
            }

            if ( ! $term_id ) {
                continue;
            }

            // Alleen termen uit de afgeleide taxonomy accepteren.
            $term = get_term( $term_id, $taxonomy );

            if ( $term instanceof WP_Term ) {
                $term_ids[] = $term_id;
            }
        }

        $term_ids = array_values(
            array_unique(
                array_filter( $term_ids )
            )
        );

        $args['taxonomy']   = $taxonomy;
        $args['include']    = $term_ids ?: [ 0 ];
        $args['hide_empty'] = false;
        $args['orderby']    = 'include';

        return $args;
    },
    20,
    3
);

/**
 * TFSC - Titel shortcodes
 *
 * [post_title]
 * Toont de titel van de huidige post/CPT.
 *
 * [archive_title]
 * Toont de titel van het huidige archief.
 */


/**
 * Huidige posttitel.
 */
add_shortcode('post_title', function () {
    return esc_html(get_the_title());
});


/**
 * Huidige archieftitel.
 */
add_shortcode('archive_title', function () {
    return esc_html(get_the_archive_title());
});

/**
 * TFSC — Featured image ALT en TITLE, versie 2.0.
 * Code Snippets ID: 9; locatie: overal uitvoeren.
 * WordPress en Elementor, inclusief afbeeldingsresolutie Custom.
 * Alleen de featured image van het huidige afzonderlijke bericht.
 */

function tfsc_featured_image_text_context() {
    if ( ! is_singular() ) {
        return null;
    }

    $post_id = get_queried_object_id();
    $image_id = $post_id ? (int) get_post_thumbnail_id( $post_id ) : 0;

    if ( ! $image_id ) {
        return null;
    }

    // De HTML API verwacht ongeëscapete tekst en verzorgt zelf de escaping.
    $title = trim( html_entity_decode(
        wp_strip_all_tags( get_the_title( $post_id ) ),
        ENT_QUOTES,
        get_bloginfo( 'charset' ) ?: 'UTF-8'
    ) );

    if ( '' === $title ) {
        return null;
    }

    return [ 'image_id' => $image_id, 'title' => $title ];
}

// Normale WordPress-afbeeldingen, ongeacht de gekozen afbeeldingsgrootte.
add_filter( 'wp_get_attachment_image_attributes', function( $attr, $attachment, $size ) {
    $context = tfsc_featured_image_text_context();

    if ( ! $context || (int) $attachment->ID !== $context['image_id'] ) {
        return $attr;
    }

    $attr['alt'] = $context['title'];
    $attr['title'] = $context['title'];

    return $attr;
}, 10, 3 );

// Elementor bouwt bij Custom zelf HTML en slaat de WordPress-filter over.
add_filter( 'elementor/image_size/get_attachment_image_html', function( $html, $settings, $image_size_key, $image_key ) {
    if ( ! is_string( $html ) || '' === $html || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $html;
    }

    $image_key = $image_key ?: $image_size_key;
    $image = $settings[ $image_key ] ?? null;

    if ( ! is_array( $image ) || empty( $image['id'] ) ) {
        return $html;
    }

    $context = tfsc_featured_image_text_context();

    if ( ! $context || (int) $image['id'] !== $context['image_id'] ) {
        return $html;
    }

    $processor = new WP_HTML_Tag_Processor( $html );

    if ( ! $processor->next_tag( 'IMG' ) ) {
        return $html;
    }

    $processor->set_attribute( 'alt', $context['title'] );
    $processor->set_attribute( 'title', $context['title'] );

    return $processor->get_updated_html();
}, 10, 4 );

add_filter( 'elementor/loop_taxonomy/args', function( $args, $settings, $display_settings ) {

    if ( empty( $settings['term_taxonomy_id'] ) ) {
        return $args;
    }

    $query_id = sanitize_key( $settings['term_taxonomy_id'] );

    // Verwacht:
    // taxonomy_level_0
    // taxonomy_level_1
    // taxonomy_level_2
    if ( ! preg_match( '/^taxonomy_level_([0-9]+)$/', $query_id, $matches ) ) {
        return $args;
    }

    $wanted_level = (int) $matches[1];

    // Taxonomy komt gewoon uit de Elementor Source instelling.
    if ( empty( $args['taxonomy'] ) ) {
        return $args;
    }

    $taxonomy = is_array( $args['taxonomy'] )
        ? reset( $args['taxonomy'] )
        : $args['taxonomy'];

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return $args;
    }

    // Query ID niet als taxonomy ID laten behandelen.
    unset( $args['term_taxonomy_id'] );

    $all_terms = get_terms([
        'taxonomy'   => $taxonomy,
        'hide_empty' => false,
    ]);

    if ( is_wp_error( $all_terms ) || empty( $all_terms ) ) {
        $args['include'] = [ 0 ];
        return $args;
    }

    $include = [];

    foreach ( $all_terms as $term ) {

        $level = count(
            get_ancestors(
                $term->term_id,
                $taxonomy,
                'taxonomy'
            )
        );

        if ( $level === $wanted_level ) {
            $include[] = $term->term_id;
        }
    }

    $args['include'] = ! empty( $include ) ? $include : [ 0 ];

    return $args;

}, 20, 3 );

/**
 * Elementor Taxonomy Loop filters
 *
 * Algemene taxonomy levels:
 * taxonomy_level_0
 * taxonomy_level_1
 * taxonomy_level_2
 *
 * Gerelateerde locaties op basis van huidige functienaam:
 * related_locaties_level_0
 * related_locaties_level_1
 * related_locaties_level_2
 */

add_filter( 'elementor/loop_taxonomy/args', function( $args, $settings, $display_settings ) {

    if ( empty( $settings['term_taxonomy_id'] ) ) {
        return $args;
    }

    $query_id = sanitize_key( $settings['term_taxonomy_id'] );


    /*
     * =========================================================
     * 1. NORMALE TAXONOMY LEVEL FILTER
     * =========================================================
     *
     * Query ID:
     * taxonomy_level_0
     * taxonomy_level_1
     * taxonomy_level_2
     */

    if ( preg_match( '/^taxonomy_level_([0-9]+)$/', $query_id, $matches ) ) {

        $wanted_level = (int) $matches[1];

        if ( empty( $args['taxonomy'] ) ) {
            return $args;
        }

        $taxonomy = is_array( $args['taxonomy'] )
            ? reset( $args['taxonomy'] )
            : $args['taxonomy'];

        if ( ! taxonomy_exists( $taxonomy ) ) {
            return $args;
        }

        unset( $args['term_taxonomy_id'] );

        $all_terms = get_terms( [
            'taxonomy'   => $taxonomy,
            'hide_empty' => false,
        ] );

        if ( is_wp_error( $all_terms ) || empty( $all_terms ) ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $include = [];

        foreach ( $all_terms as $term ) {

            $level = count(
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                )
            );

            if ( $level === $wanted_level ) {
                $include[] = $term->term_id;
            }
        }

        $args['include'] = ! empty( $include )
            ? $include
            : [ 0 ];

        return $args;
    }


    /*
     * =========================================================
     * 2. GERELATEERDE LOCATIES VOOR HUIDIG BEROEP
     * =========================================================
     *
     * Query ID:
     * related_locaties_level_0
     * related_locaties_level_1
     * related_locaties_level_2
     *
     * Werking:
     *
     * Huidig beroep
     *      ↓
     * functienaam taxonomy
     *      ↓
     * vacatures met dezelfde functienaam
     *      ↓
     * locaties van die vacatures
     *      ↓
     * alleen gekozen locatie-level tonen
     */

    if ( preg_match( '/^related_locaties_level_([0-9]+)$/', $query_id, $matches ) ) {

        $wanted_level = (int) $matches[1];

        $current_post_id = get_queried_object_id();

        if ( ! $current_post_id ) {
            return $args;
        }

        /*
         * Functienaam van huidige Beroep ophalen.
         */
        $functie_terms = wp_get_post_terms(
            $current_post_id,
            'functienaam',
            [
                'fields' => 'ids',
            ]
        );

        if ( is_wp_error( $functie_terms ) || empty( $functie_terms ) ) {
            $args['include'] = [ 0 ];
            return $args;
        }


        /*
         * Automatisch bepalen welke post types zowel
         * functienaam als locatie gebruiken.
         *
         * Daardoor hoeft de vacature-CPT slug niet
         * hardcoded in deze snippet te staan.
         */

        $functie_taxonomy = get_taxonomy( 'functienaam' );
        $locatie_taxonomy = get_taxonomy( 'locatie' );

        if ( ! $functie_taxonomy || ! $locatie_taxonomy ) {
            return $args;
        }

        $vacature_post_types = array_values(
            array_intersect(
                $functie_taxonomy->object_type,
                $locatie_taxonomy->object_type
            )
        );

        if ( empty( $vacature_post_types ) ) {
            $args['include'] = [ 0 ];
            return $args;
        }


        /*
         * Alle vacatures met dezelfde functienaam ophalen.
         */
        $vacature_ids = get_posts( [
            'post_type'      => $vacature_post_types,
            'post_status'    => 'publish',
            'posts_per_page' => -1,
            'fields'         => 'ids',

            'tax_query' => [
                [
                    'taxonomy' => 'functienaam',
                    'field'    => 'term_id',
                    'terms'    => $functie_terms,
                ],
            ],
        ] );


        if ( empty( $vacature_ids ) ) {
            $args['include'] = [ 0 ];
            return $args;
        }


        /*
         * Locaties verzamelen van gevonden vacatures.
         */
        $location_ids = [];

        foreach ( $vacature_ids as $vacature_id ) {

            $locations = wp_get_post_terms(
                $vacature_id,
                'locatie',
                [
                    'fields' => 'ids',
                ]
            );

            if ( ! is_wp_error( $locations ) ) {
                $location_ids = array_merge(
                    $location_ids,
                    $locations
                );
            }
        }

        $location_ids = array_unique(
            array_map( 'intval', $location_ids )
        );


        if ( empty( $location_ids ) ) {
            $args['include'] = [ 0 ];
            return $args;
        }


        /*
         * Alleen het gewenste niveau behouden.
         */
        $include = [];

        foreach ( $location_ids as $location_id ) {

            $level = count(
                get_ancestors(
                    $location_id,
                    'locatie',
                    'taxonomy'
                )
            );

            if ( $level === $wanted_level ) {
                $include[] = $location_id;
            }
        }


        /*
         * Elementor Query ID verwijderen.
         */
        unset( $args['term_taxonomy_id'] );


        /*
         * Elementor moet locatie-termen renderen.
         */
        $args['taxonomy'] = 'locatie';

        $args['include'] = ! empty( $include )
            ? array_unique( $include )
            : [ 0 ];

        $args['hide_empty'] = false;
        $args['orderby']    = 'name';
        $args['order']      = 'ASC';

        return $args;
    }


    return $args;

}, 20, 3 );

/**
 * ============================================================
 * TFSC - GENERIEKE GECOMBINEERDE VACATURE-ARCHIEVEN
 * ============================================================
 *
 * URL:
 * /vacatures/{taxonomy1}/{term1}/{taxonomy2}/{term2}/
 *
 * Voorbeelden:
 *
 * /vacatures/functienaam/field-service-engineer/locatie/noord-brabant/
 * /vacatures/functienaam/field-service-engineer/branche/maritiem/
 * /vacatures/branche/maritiem/locatie/noord-brabant/
 *
 *
 * Voorwaarden:
 * - beide taxonomies bestaan;
 * - beide taxonomies zijn publicly_queryable;
 * - beide taxonomies zijn gekoppeld aan het Vacature CPT;
 * - beide termen bestaan;
 * - taxonomies moeten verschillend zijn.
 *
 *
 * Elementor:
 * Theme Builder → Archive Template
 * Display Conditions:
 * Include → Combined Vacancy Archives
 *
 * Elementor Loop Grid Query ID:
 * combined_vacancies
 */


/**
 * ============================================================
 * CONFIGURATIE
 * ============================================================
 */

define( 'TFSC_COMBO_BASE', 'vacatures' );

/*
 * Controleer of dit daadwerkelijk de slug
 * van jouw Vacatures CPT is.
 */
define( 'TFSC_VACANCY_POST_TYPE', 'vacature' );


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter( 'query_vars', function( $vars ) {

    $vars[] = 'tfsc_combo_archive';

    $vars[] = 'combo_tax_1';
    $vars[] = 'combo_term_1';

    $vars[] = 'combo_tax_2';
    $vars[] = 'combo_term_2';

    return $vars;
});


/**
 * ============================================================
 * 2. REWRITE RULE
 * ============================================================
 *
 * /vacatures/{tax1}/{term1}/{tax2}/{term2}/
 */

add_action( 'init', function() {

    add_rewrite_rule(
        '^' . preg_quote( TFSC_COMBO_BASE, '/' ) . '/([^/]+)/([^/]+)/([^/]+)/([^/]+)/?$',
        'index.php'
            . '?tfsc_combo_archive=1'
            . '&combo_tax_1=$matches[1]'
            . '&combo_term_1=$matches[2]'
            . '&combo_tax_2=$matches[3]'
            . '&combo_term_2=$matches[4]',
        'top'
    );

});


/**
 * ============================================================
 * 3. IS DIT EEN COMBINATIE-ARCHIEF?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (bool) get_query_var( 'tfsc_combo_archive' );
}


/**
 * ============================================================
 * 4. MAG DE TAXONOMY GEBRUIKT WORDEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return false;
    }

    $tax_object = get_taxonomy( $taxonomy );

    if ( ! $tax_object ) {
        return false;
    }

    /*
     * Pods / WordPress publicly_queryable moet actief zijn.
     */
    if ( ! $tax_object->publicly_queryable ) {
        return false;
    }

    /*
     * Taxonomy moet gekoppeld zijn aan het Vacatures CPT.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }

    return true;
}


/**
 * ============================================================
 * 5. COMBINATIE UITLEZEN EN VALIDEREN
 * ============================================================
 */

function tfsc_get_combo_archive() {

    static $cache = null;

    if ( $cache !== null ) {
        return $cache;
    }

    if ( ! tfsc_is_combo_archive() ) {
        $cache = false;
        return false;
    }

    $taxonomy_1 = sanitize_key(
        get_query_var( 'combo_tax_1' )
    );

    $taxonomy_2 = sanitize_key(
        get_query_var( 'combo_tax_2' )
    );

    $term_slug_1 = sanitize_title(
        get_query_var( 'combo_term_1' )
    );

    $term_slug_2 = sanitize_title(
        get_query_var( 'combo_term_2' )
    );


    /*
     * Geen lege onderdelen.
     */
    if (
        ! $taxonomy_1 ||
        ! $taxonomy_2 ||
        ! $term_slug_1 ||
        ! $term_slug_2
    ) {
        $cache = false;
        return false;
    }


    /*
     * Geen twee termen uit exact dezelfde taxonomy.
     */
    if ( $taxonomy_1 === $taxonomy_2 ) {
        $cache = false;
        return false;
    }


    /*
     * Beide taxonomies moeten toegestaan zijn.
     */
    if (
        ! tfsc_combo_taxonomy_allowed( $taxonomy_1 ) ||
        ! tfsc_combo_taxonomy_allowed( $taxonomy_2 )
    ) {
        $cache = false;
        return false;
    }


    /*
     * Termen ophalen.
     */
    $term_1 = get_term_by(
        'slug',
        $term_slug_1,
        $taxonomy_1
    );

    $term_2 = get_term_by(
        'slug',
        $term_slug_2,
        $taxonomy_2
    );


    if (
        ! $term_1 ||
        is_wp_error( $term_1 ) ||
        ! $term_2 ||
        is_wp_error( $term_2 )
    ) {
        $cache = false;
        return false;
    }


    $cache = [

        'taxonomy_1' => $taxonomy_1,
        'term_1'     => $term_1,

        'taxonomy_2' => $taxonomy_2,
        'term_2'     => $term_2,

    ];

    return $cache;
}


/**
 * ============================================================
 * 6. WORDPRESS REQUEST ALS ARCHIVE MARKEREN
 * ============================================================
 */

add_action( 'wp', function() {

    if ( ! tfsc_is_combo_archive() ) {
        return;
    }

    $combo = tfsc_get_combo_archive();

    if ( ! $combo ) {
        return;
    }

    global $wp_query;

    /*
     * Dit is geen singular/page/home/search.
     */
    $wp_query->is_home       = false;
    $wp_query->is_front_page = false;
    $wp_query->is_page       = false;
    $wp_query->is_single     = false;
    $wp_query->is_singular   = false;
    $wp_query->is_search     = false;
    $wp_query->is_404        = false;

    /*
     * Wel een archive.
     */
    $wp_query->is_archive = true;
});


/**
 * ============================================================
 * 7. ONGELDIGE COMBINATIE → 404
 * ============================================================
 */

add_action( 'template_redirect', function() {

    if ( ! tfsc_is_combo_archive() ) {
        return;
    }

    if ( tfsc_get_combo_archive() ) {
        return;
    }

    global $wp_query;

    $wp_query->set_404();

    status_header( 404 );
    nocache_headers();

});


/**
 * ============================================================
 * 8. MAIN QUERY FILTEREN
 * ============================================================
 *
 * Hiermee is de WordPress archive-query zelf ook al
 * daadwerkelijk de combinatie van beide taxonomies.
 */

add_action( 'pre_get_posts', function( $query ) {

    if ( is_admin() || ! $query->is_main_query() ) {
        return;
    }

    if ( ! tfsc_is_combo_archive() ) {
        return;
    }

    $combo = tfsc_get_combo_archive();

    if ( ! $combo ) {
        return;
    }

    $query->set(
        'post_type',
        TFSC_VACANCY_POST_TYPE
    );

    $query->set(
        'tax_query',
        [
            'relation' => 'AND',

            [
                'taxonomy' => $combo['taxonomy_1'],
                'field'    => 'term_id',
                'terms'    => [
                    $combo['term_1']->term_id,
                ],
            ],

            [
                'taxonomy' => $combo['taxonomy_2'],
                'field'    => 'term_id',
                'terms'    => [
                    $combo['term_2']->term_id,
                ],
            ],
        ]
    );

});


