/**
 * ============================================================
 * 10. ELEMENTOR CUSTOM ARCHIVE CONDITION
 * ============================================================
 *
 * Theme Builder:
 *
 * Include
 * → Combined Vacancy Archives
 */

add_action(
    'elementor/theme/register_conditions',
    function( $conditions_manager ) {

        /*
         * Alleen uitvoeren wanneer Elementor Pro's
         * Condition_Base beschikbaar is.
         */
        if (
            ! class_exists(
                '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base'
            )
        ) {
            return;
        }


        if ( ! class_exists( 'TFSC_Combined_Vacancy_Archive_Condition' ) ) {

            class TFSC_Combined_Vacancy_Archive_Condition
                extends \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type(): string {
                    return 'archive';
                }

                public static function get_priority(): int {
                    return 40;
                }

                public function get_name(): string {
                    return 'tfsc_combined_vacancy_archive';
                }

                public function get_label(): string {
                    return 'Combined Vacancy Archives';
                }

                public function check( $args ): bool {

                    return (
                        tfsc_is_combo_archive() &&
                        false !== tfsc_get_combo_archive()
                    );
                }
            }
        }


        /*
         * Onder de bestaande Elementor "Archives" condition
         * registreren.
         */
        $archive_condition =
            $conditions_manager->get_condition( 'archive' );

        if ( $archive_condition ) {

            $archive_condition->register_sub_condition(
                new TFSC_Combined_Vacancy_Archive_Condition()
            );
        }
    }
);


