/**
 * ============================================================
 * 12. URL HELPER
 * ============================================================
 *
 * PHP:
 *
 * tfsc_combo_url(
 *     'functienaam',
 *     'field-service-engineer',
 *     'locatie',
 *     'noord-brabant'
 * );
 */

function tfsc_combo_url(
    $taxonomy_1,
    $term_1,
    $taxonomy_2,
    $term_2
) {

    $taxonomy_1 = sanitize_key( $taxonomy_1 );
    $taxonomy_2 = sanitize_key( $taxonomy_2 );

    $term_1 = sanitize_title( $term_1 );
    $term_2 = sanitize_title( $term_2 );


    if (
        $taxonomy_1 === $taxonomy_2 ||
        ! tfsc_combo_taxonomy_allowed( $taxonomy_1 ) ||
        ! tfsc_combo_taxonomy_allowed( $taxonomy_2 )
    ) {
        return '';
    }


    /*
     * Ook controleren of de termen daadwerkelijk bestaan.
     */

    if (
        ! get_term_by(
            'slug',
            $term_1,
            $taxonomy_1
        ) ||
        ! get_term_by(
            'slug',
            $term_2,
            $taxonomy_2
        )
    ) {
        return '';
    }


    return home_url(
        sprintf(
            '/%s/%s/%s/%s/%s/',
            TFSC_COMBO_BASE,
            $taxonomy_1,
            $term_1,
            $taxonomy_2,
            $term_2
        )
    );
}

/**
 * ============================================================
 * TFSC - GECOMBINEERDE VACATURE-ARCHIEVEN
 * ============================================================
 *
 * Ondersteunt:
 *
 * - 2 of 3 taxonomies
 * - hiërarchische termen binnen een taxonomy
 *
 * Voorbeelden:
 *
 * /vacatures/functienaam/field-service-engineer/locatie/noord-brabant/
 *
 * /vacatures/functienaam/field-service-engineer/locatie/noord-brabant/tilburg/
 *
 * /vacatures/functienaam/field-service-engineer/branche/maritiem/locatie/noord-brabant/tilburg/
 *
 *
 * Elementor:
 *
 * Archive Condition:
 * Combined Vacancy Archives
 *
 * Loop Grid Query ID:
 * combined_vacancies
 *
 * Heading:
 * [combo_heading]
 */


/**
 * ============================================================
 * CONFIGURATIE
 * ============================================================
 */

define( 'TFSC_COMBO_BASE', 'vacatures' );
define( 'TFSC_VACANCY_POST_TYPE', 'vacature' );


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter( 'query_vars', function( $vars ) {

    $vars[] = 'tfsc_combo_archive';

    $vars[] = 'combo_tax_1';
    $vars[] = 'combo_path_1';

    $vars[] = 'combo_tax_2';
    $vars[] = 'combo_path_2';

    $vars[] = 'combo_tax_3';
    $vars[] = 'combo_path_3';

    return $vars;
});


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return false;
    }

    $tax_object = get_taxonomy( $taxonomy );

    if ( ! $tax_object ) {
        return false;
    }

    // Moet publiek bevraagbaar zijn.
    if ( ! $tax_object->publicly_queryable ) {
        return false;
    }

    // Moet gekoppeld zijn aan het Vacature CPT.
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }

    return true;
}


/**
 * ============================================================
 * 3. TOEGESTANE TAXONOMIES OPHALEN
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies = get_object_taxonomies(
        TFSC_VACANCY_POST_TYPE,
        'objects'
    );

    $allowed = [];

    foreach ( $taxonomies as $taxonomy => $object ) {

        if ( tfsc_combo_taxonomy_allowed( $taxonomy ) ) {
            $allowed[] = $taxonomy;
        }
    }

    return $allowed;
}


/**
 * ============================================================
 * 4. REWRITE RULES
 * ============================================================
 *
 * De taxonomy-namen zelf worden in de regex opgenomen.
 *
 * Daardoor grijpt deze code niet zomaar iedere willekeurige
 * URL onder /vacatures/.
 */

add_action( 'init', function() {

    $taxonomies = tfsc_get_allowed_combo_taxonomies();

    if ( count( $taxonomies ) < 2 ) {
        return;
    }

    $escaped = array_map(
        function( $taxonomy ) {
            return preg_quote( $taxonomy, '/' );
        },
        $taxonomies
    );

    $tax_regex = '(?:' . implode( '|', $escaped ) . ')';


    /**
     * --------------------------------------------------------
     * 3 TAXONOMIES
     * --------------------------------------------------------
     *
     * Bijvoorbeeld:
     *
     * functienaam/field-service-engineer/
     * branche/maritiem/
     * locatie/noord-brabant/tilburg/
     */

    add_rewrite_rule(
        '^' . preg_quote( TFSC_COMBO_BASE, '/' ) .
        '/(' . $tax_regex . ')' .
        '/(.+?)' .
        '/(' . $tax_regex . ')' .
        '/(.+?)' .
        '/(' . $tax_regex . ')' .
        '/(.+?)/?$',

        'index.php'
            . '?tfsc_combo_archive=1'
            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]'
            . '&combo_tax_2=$matches[3]'
            . '&combo_path_2=$matches[4]'
            . '&combo_tax_3=$matches[5]'
            . '&combo_path_3=$matches[6]',

        'top'
    );


    /**
     * --------------------------------------------------------
     * 2 TAXONOMIES
     * --------------------------------------------------------
     *
     * Bijvoorbeeld:
     *
     * functienaam/field-service-engineer/
     * locatie/noord-brabant/tilburg/
     */

    add_rewrite_rule(
        '^' . preg_quote( TFSC_COMBO_BASE, '/' ) .
        '/(' . $tax_regex . ')' .
        '/(.+?)' .
        '/(' . $tax_regex . ')' .
        '/(.+?)/?$',

        'index.php'
            . '?tfsc_combo_archive=1'
            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]'
            . '&combo_tax_2=$matches[3]'
            . '&combo_path_2=$matches[4]',

        'top'
    );

}, 99 );


/**
 * ============================================================
 * 5. IS COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (bool) get_query_var( 'tfsc_combo_archive' );
}


/**
 * ============================================================
 * 6. TERM-PAD VALIDEREN
 * ============================================================
 *
 * Voor locatie bijvoorbeeld:
 *
 * noord-brabant
 *
 * of:
 *
 * noord-brabant/tilburg
 *
 * of eventueel:
 *
 * nederland/noord-brabant/tilburg
 *
 *
 * De code controleert dat iedere volgende term werkelijk
 * een child is van de vorige term.
 *
 * De diepste term wordt uiteindelijk gebruikt als filter.
 */

function tfsc_resolve_term_path( $taxonomy, $path ) {

    $tax_object = get_taxonomy( $taxonomy );

    if ( ! $tax_object ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            array_map(
                'sanitize_title',
                explode( '/', trim( $path, '/' ) )
            )
        )
    );

    if ( empty( $segments ) ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomies mogen maar één term
     * in het pad hebben.
     */
    if (
        ! $tax_object->hierarchical &&
        count( $segments ) > 1
    ) {
        return false;
    }


    $resolved_terms = [];

    $parent_id = 0;


    foreach ( $segments as $index => $slug ) {

        $term = get_term_by(
            'slug',
            $slug,
            $taxonomy
        );

        if (
            ! $term ||
            is_wp_error( $term )
        ) {
            return false;
        }


        /**
         * Vanaf het tweede segment controleren we
         * daadwerkelijk de parent-child relatie.
         */
        if ( $index > 0 ) {

            if ( (int) $term->parent !== (int) $parent_id ) {
                return false;
            }
        }


        $resolved_terms[] = $term;

        $parent_id = $term->term_id;
    }


    return [
        'path' => $resolved_terms,

        // De diepste term wordt het daadwerkelijke filter.
        'term' => end( $resolved_terms ),
    ];
}


/**
 * ============================================================
 * 7. COMBINATIE UITLEZEN
 * ============================================================
 */

function tfsc_get_combo_archive() {

    static $cache_set = false;
    static $cache     = false;


    if ( $cache_set ) {
        return $cache;
    }

    $cache_set = true;


    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }


    $raw_items = [

        [
            'taxonomy' => get_query_var( 'combo_tax_1' ),
            'path'     => get_query_var( 'combo_path_1' ),
        ],

        [
            'taxonomy' => get_query_var( 'combo_tax_2' ),
            'path'     => get_query_var( 'combo_path_2' ),
        ],

    ];


    /**
     * Eventuele derde taxonomy.
     */
    if (
        get_query_var( 'combo_tax_3' ) &&
        get_query_var( 'combo_path_3' )
    ) {

        $raw_items[] = [
            'taxonomy' => get_query_var( 'combo_tax_3' ),
            'path'     => get_query_var( 'combo_path_3' ),
        ];
    }


    $items = [];
    $used_taxonomies = [];


    foreach ( $raw_items as $raw_item ) {

        $taxonomy = sanitize_key(
            $raw_item['taxonomy']
        );

        $path = trim(
            (string) $raw_item['path'],
            '/'
        );


        if (
            ! $taxonomy ||
            ! $path
        ) {
            return false;
        }


        /**
         * Taxonomy niet dubbel gebruiken.
         */
        if (
            in_array(
                $taxonomy,
                $used_taxonomies,
                true
            )
        ) {
            return false;
        }


        if (
            ! tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return false;
        }


        /**
         * Volledig hiërarchisch pad controleren.
         */
        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $path
            );


        if ( ! $resolved ) {
            return false;
        }


        $items[] = [

            'taxonomy' => $taxonomy,

            // Diepste term.
            'term'     => $resolved['term'],

            // Volledige hiërarchie bewaren.
            'path'     => $resolved['path'],
        ];


        $used_taxonomies[] =
            $taxonomy;
    }


    if ( count( $items ) < 2 ) {
        return false;
    }


    $cache = $items;

    return $cache;
}


/**
 * ============================================================
 * 8. TAX QUERY BOUWEN
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $combo = tfsc_get_combo_archive();

    if ( ! $combo ) {
        return false;
    }


    $tax_query = [
        'relation' => 'AND',
    ];


    foreach ( $combo as $item ) {

        $tax_object =
            get_taxonomy(
                $item['taxonomy']
            );


        $tax_query[] = [

            'taxonomy' =>
                $item['taxonomy'],

            'field' =>
                'term_id',

            'terms' => [
                $item['term']->term_id,
            ],

            'operator' =>
                'IN',

            /**
             * Provincie:
             * ook vacatures uit child-plaatsen meenemen.
             *
             * Tilburg:
             * eventuele children van Tilburg zouden ook
             * meegenomen worden.
             */
            'include_children' =>
                $tax_object &&
                $tax_object->hierarchical,
        ];
    }


    return $tax_query;
}


