/**
 * ============================================================
 * TFSC - DYNAMISCHE VACATURE ARCHIEVEN
 * ============================================================
 *
 * Ondersteunt 1, 2 of 3 taxonomies.
 *
 * Ook hiërarchische termen aan het einde:
 *
 * /vacatures/functienaam/commissioning-engineer/
 *
 * /vacatures/functienaam/field-service-engineer/locatie/noord-brabant/
 *
 * /vacatures/functienaam/field-service-engineer/locatie/noord-brabant/tilburg/
 *
 * /vacatures/functienaam/field-service-engineer/kennisgebied/elektrotechniek/locatie/noord-brabant/tilburg/
 *
 *
 * Elementor:
 * Condition: Combined Vacancy Archives
 * Query ID: combined_vacancies
 *
 * Shortcodes:
 * [combo_heading]
 * [combo_term taxonomy="locatie"]
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

define( 'TFSC_COMBO_BASE', 'vacatures' );
define( 'TFSC_VACANCY_POST_TYPE', 'vacature' );


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter( 'query_vars', function( $vars ) {

    $vars[] = 'tfsc_combo_archive';

    $vars[] = 'combo_tax_1';
    $vars[] = 'combo_path_1';

    $vars[] = 'combo_tax_2';
    $vars[] = 'combo_path_2';

    $vars[] = 'combo_tax_3';
    $vars[] = 'combo_path_3';

    return $vars;
});


/**
 * ============================================================
 * 2. TAXONOMY TOEGESTAAN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return false;
    }

    $tax_object = get_taxonomy( $taxonomy );

    if ( ! $tax_object ) {
        return false;
    }

    if ( ! $tax_object->publicly_queryable ) {
        return false;
    }

    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }

    return true;
}


/**
 * ============================================================
 * 3. TOEGESTANE TAXONOMIES
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies = get_object_taxonomies(
        TFSC_VACANCY_POST_TYPE,
        'objects'
    );

    $allowed = [];

    foreach ( $taxonomies as $taxonomy => $object ) {

        if ( tfsc_combo_taxonomy_allowed( $taxonomy ) ) {
            $allowed[] = $taxonomy;
        }
    }

    return $allowed;
}


/**
 * ============================================================
 * 4. REWRITE RULES
 * ============================================================
 *
 * Ondersteunt:
 *
 * 1 taxonomy
 * 2 taxonomies
 * 3 taxonomies
 *
 * De laatste taxonomy mag een hiërarchisch pad bevatten.
 */

add_action( 'init', function() {

    $taxonomies = tfsc_get_allowed_combo_taxonomies();

    if ( empty( $taxonomies ) ) {
        return;
    }

    $escaped = array_map(
        function( $taxonomy ) {
            return preg_quote( $taxonomy, '/' );
        },
        $taxonomies
    );

    $tax_regex = '(?:' . implode( '|', $escaped ) . ')';


    /**
     * 3 TAXONOMIES
     */
    add_rewrite_rule(
        '^' . preg_quote( TFSC_COMBO_BASE, '/' ) .
        '/(' . $tax_regex . ')/([^/]+)' .
        '/(' . $tax_regex . ')/([^/]+)' .
        '/(' . $tax_regex . ')/(.+?)/?$',

        'index.php'
            . '?tfsc_combo_archive=1'
            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]'
            . '&combo_tax_2=$matches[3]'
            . '&combo_path_2=$matches[4]'
            . '&combo_tax_3=$matches[5]'
            . '&combo_path_3=$matches[6]',

        'top'
    );


    /**
     * 2 TAXONOMIES
     */
    add_rewrite_rule(
        '^' . preg_quote( TFSC_COMBO_BASE, '/' ) .
        '/(' . $tax_regex . ')/([^/]+)' .
        '/(' . $tax_regex . ')/(.+?)/?$',

        'index.php'
            . '?tfsc_combo_archive=1'
            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]'
            . '&combo_tax_2=$matches[3]'
            . '&combo_path_2=$matches[4]',

        'top'
    );


    /**
     * 1 TAXONOMY
     */
    add_rewrite_rule(
        '^' . preg_quote( TFSC_COMBO_BASE, '/' ) .
        '/(' . $tax_regex . ')/(.+?)/?$',

        'index.php'
            . '?tfsc_combo_archive=1'
            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]',

        'top'
    );

}, 99 );


/**
 * ============================================================
 * 5. IS DIT EEN DYNAMISCH ARCHIEF?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (bool) get_query_var( 'tfsc_combo_archive' );
}


/**
 * ============================================================
 * 6. HIËRARCHISCH TERMPAD VALIDEREN
 * ============================================================
 */

function tfsc_resolve_term_path( $taxonomy, $path ) {

    $tax_object = get_taxonomy( $taxonomy );

    if ( ! $tax_object ) {
        return false;
    }


    $segments = array_values(
        array_filter(
            array_map(
                'sanitize_title',
                explode( '/', trim( $path, '/' ) )
            )
        )
    );


    if ( empty( $segments ) ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     * maximaal één term.
     */
    if (
        ! $tax_object->hierarchical &&
        count( $segments ) > 1
    ) {
        return false;
    }


    $resolved_terms = [];
    $parent_id      = 0;


    foreach ( $segments as $index => $slug ) {

        $term = get_term_by(
            'slug',
            $slug,
            $taxonomy
        );


        if (
            ! $term ||
            is_wp_error( $term )
        ) {
            return false;
        }


        /**
         * Vanaf segment 2 moet het echt een child
         * van de vorige term zijn.
         */
        if ( $index > 0 ) {

            if (
                (int) $term->parent !==
                (int) $parent_id
            ) {
                return false;
            }
        }


        $resolved_terms[] = $term;

        $parent_id = $term->term_id;
    }


    return [
        'path' => $resolved_terms,
        'term' => end( $resolved_terms ),
    ];
}


/**
 * ============================================================
 * 7. ARCHIEF UITLEZEN
 * ============================================================
 *
 * BELANGRIJK:
 *
 * Er is GEEN minimum van 2 taxonomies.
 * Eén taxonomy is gewoon geldig.
 */

function tfsc_get_combo_archive() {

    static $cache_set = false;
    static $cache     = false;


    if ( $cache_set ) {
        return $cache;
    }

    $cache_set = true;


    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }


    $raw_items = [];


    for ( $i = 1; $i <= 3; $i++ ) {

        $taxonomy = get_query_var(
            'combo_tax_' . $i
        );

        $path = get_query_var(
            'combo_path_' . $i
        );


        if ( $taxonomy && $path ) {

            $raw_items[] = [
                'taxonomy' => $taxonomy,
                'path'     => $path,
            ];
        }
    }


    /**
     * Eén taxonomy is voldoende.
     */
    if ( empty( $raw_items ) ) {
        return false;
    }


    $items = [];
    $used_taxonomies = [];


    foreach ( $raw_items as $raw_item ) {

        $taxonomy = sanitize_key(
            $raw_item['taxonomy']
        );

        $path = trim(
            (string) $raw_item['path'],
            '/'
        );


        if (
            ! $taxonomy ||
            ! $path
        ) {
            return false;
        }


        /**
         * Dezelfde taxonomy niet dubbel.
         */
        if (
            in_array(
                $taxonomy,
                $used_taxonomies,
                true
            )
        ) {
            return false;
        }


        if (
            ! tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return false;
        }


        $resolved = tfsc_resolve_term_path(
            $taxonomy,
            $path
        );


        if ( ! $resolved ) {
            return false;
        }


        $items[] = [
            'taxonomy' => $taxonomy,
            'term'     => $resolved['term'],
            'path'     => $resolved['path'],
        ];


        $used_taxonomies[] = $taxonomy;
    }


    $cache = $items;

    return $cache;
}


/**
 * ============================================================
 * 8. TAX QUERY
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $combo = tfsc_get_combo_archive();

    if ( ! $combo ) {
        return false;
    }


    $tax_query = [
        'relation' => 'AND',
    ];


    foreach ( $combo as $item ) {

        $tax_object = get_taxonomy(
            $item['taxonomy']
        );


        $tax_query[] = [

            'taxonomy' => $item['taxonomy'],

            'field' => 'term_id',

            'terms' => [
                $item['term']->term_id,
            ],

            'operator' => 'IN',

            /**
             * Provincie toont dus ook vacatures
             * uit onderliggende plaatsen.
             */
            'include_children' =>
                $tax_object &&
                $tax_object->hierarchical,
        ];
    }


    return $tax_query;
}


