            is_array( $existing_tax_query ) &&
            ! empty( $existing_tax_query )
        ) {

            $query->set(
                'tax_query',
                [
                    'relation' => 'AND',

                    $existing_tax_query,

                    $combo_tax_query,
                ]
            );

        } else {

            $query->set(
                'tax_query',
                $combo_tax_query
            );
        }
    }
