        }


        $combo = tfsc_get_combo_archive();


        if ( ! $combo ) {
            return $title;
        }


        $functienaam = '';
        $other_terms = [];


        foreach ( $combo as $item ) {

            if (
                $item['taxonomy'] ===
                'functienaam'
            ) {

                $functienaam =
                    $item['term']->name;

            } else {

                $other_terms[] =
                    $item['term']->name;
            }
        }


        if ( $functienaam ) {

            $parts = array_merge(
                [
                    $functienaam .
                    ' vacatures'
                ],
                $other_terms
            );


            return implode(
                ' - ',
                $parts
            );
        }


        if ( ! empty( $other_terms ) ) {

            $first =
                array_shift(
                    $other_terms
                );


            $parts = array_merge(
                [
                    $first .
                    ' vacatures'
                ],
                $other_terms
            );


            return implode(
                ' - ',
                $parts
            );
        }


        return $title;
    }
);


