                $item['term']->name;


            switch ( $item['taxonomy'] ) {

                case 'functienaam':

                    $functienaam =
                        $name;

                    break;


                case 'kennisgebied':

                    $kennisgebied =
                        $name;

                    break;


                case 'locatie':

                    $locatie =
                        $name;

                    break;


                case 'branche':

                    $branche =
                        $name;

                    break;
            }
        }


        $parts = [];


        if ( $functienaam ) {

            $parts[] =
                $functienaam .
                ' vacatures';

        } else {

            $parts[] =
                'Vacatures';
        }


        if ( $kennisgebied ) {

            $parts[] =
                'in ' .
                $kennisgebied;
        }


        if ( $branche ) {

            $parts[] =
                'binnen ' .
                $branche;
        }


        if ( $locatie ) {

            $parts[] =
                'in ' .
                $locatie;
        }


        return
            implode( ' ', $parts ) .
            '. Bekijk actuele vacatures en solliciteer direct.';
    }
);

/**
 * ============================================================
 * TFSC - DYNAMISCHE VACATURE ARCHIEVEN
 * + SEARCH & FILTER PRO V3 CUSTOM QUERY INTEGRATION
 * ============================================================
 *
 * ARCHITECTUUR:
 *
 * Virtuele archive URL
 *      ↓
 * WordPress MAIN QUERY
 *      ↓
 * Search & Filter Query #1
 *      ↓
 * Elementor Loop Grid → Current Query
 *
 *
 * Voorbeelden:
 *
 * /vacatures/functienaam/commissioning-engineer/
 *
 * /vacatures/functienaam/field-service-engineer/locatie/noord-brabant/
 *
 * /vacatures/functienaam/field-service-engineer/locatie/noord-brabant/tilburg/
 *
 * /vacatures/functienaam/field-service-engineer/kennisgebied/elektrotechniek/locatie/noord-brabant/tilburg/
 *
 *
 * Elementor:
 *
 * Archive Condition:
 * Combined Vacancy Archives
 *
 * Loop Grid:
 * Source = Current Query
 *
 * Advanced → CSS ID:
 * tfsc-vacancy-results
 *
 *
 * Search & Filter:
 *
 * Query ID = 1
 *
 * Location / Integration:
 * TFSC Combined Vacancy Archive
 *
 *
 * Shortcodes:
 *
 * [combo_heading]
 * [combo_term taxonomy="locatie"]
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

define( 'TFSC_COMBO_BASE', 'vacatures' );

define(
    'TFSC_VACANCY_POST_TYPE',
    'vacature'
);

define(
    'TFSC_SEARCH_FILTER_QUERY_ID',
    1
);

define(
    'TFSC_SEARCH_FILTER_INTEGRATION',
    'tfsc/combined-vacancy-archive'
);


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';

        $vars[] = 'combo_tax_1';
        $vars[] = 'combo_path_1';

        $vars[] = 'combo_tax_2';
        $vars[] = 'combo_path_2';

        $vars[] = 'combo_tax_3';
        $vars[] = 'combo_path_3';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY TOEGESTAAN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return false;
    }


    $tax_object =
        get_taxonomy( $taxonomy );


    if ( ! $tax_object ) {
        return false;
    }


    if ( ! $tax_object->publicly_queryable ) {
        return false;
    }


    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. TOEGESTANE TAXONOMIES
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed = [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * 4. REWRITE RULES
 * ============================================================
 *
 * Ondersteunt:
 *
 * 1 taxonomy
 * 2 taxonomies
 * 3 taxonomies
 *
 * Alleen de laatste taxonomy mag meerdere
 * hiërarchische padsegmenten bevatten.
 */

add_action(
    'init',
    function() {

        $taxonomies =
            tfsc_get_allowed_combo_taxonomies();


        if ( empty( $taxonomies ) ) {
            return;
        }


        $escaped =
            array_map(
                function( $taxonomy ) {

                    return preg_quote(
                        $taxonomy,
                        '/'
                    );
                },
                $taxonomies
            );


        $tax_regex =
            '(?:'
            .
            implode(
                '|',
                $escaped
            )
            .
            ')';


        /**
         * ----------------------------------------------------
         * 3 TAXONOMIES
         * ----------------------------------------------------
         */

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )

            . '/('
            . $tax_regex
            . ')/([^/]+)'

            . '/('
            . $tax_regex
            . ')/([^/]+)'

            . '/('
            . $tax_regex
            . ')/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'

            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]'

            . '&combo_tax_2=$matches[3]'
            . '&combo_path_2=$matches[4]'

            . '&combo_tax_3=$matches[5]'
            . '&combo_path_3=$matches[6]',

            'top'
        );


        /**
         * ----------------------------------------------------
         * 2 TAXONOMIES
         * ----------------------------------------------------
         */

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )

            . '/('
            . $tax_regex
            . ')/([^/]+)'

            . '/('
            . $tax_regex
            . ')/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'

            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]'

            . '&combo_tax_2=$matches[3]'
            . '&combo_path_2=$matches[4]',

            'top'
        );


        /**
         * ----------------------------------------------------
         * 1 TAXONOMY
         * ----------------------------------------------------
         */

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )

            . '/('
            . $tax_regex
            . ')/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'

            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * 5. IS DIT EEN COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (bool)
        get_query_var(
            'tfsc_combo_archive'
        );
}


/**
 * ============================================================
 * 6. HIËRARCHISCH TERMPAD VALIDEREN
 * ============================================================
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $path
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if ( ! $tax_object ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',

                    explode(
                        '/',
                        trim(
                            $path,
                            '/'
                        )
                    )
                )
            )
        );


    if ( empty( $segments ) ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     * maximaal één termsegment.
     */
    if (
        ! $tax_object->hierarchical
        &&
        count( $segments ) > 1
    ) {
        return false;
    }


    $resolved_terms = [];

    $parent_id = 0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term
            ||
            is_wp_error( $term )
        ) {
            return false;
        }


        /**
         * Segment 2 en verder moeten werkelijk
         * children van de vorige term zijn.
         */
        if (
            $index > 0
            &&
            (int) $term->parent
                !==
            (int) $parent_id
        ) {
            return false;
        }


        $resolved_terms[] =
            $term;


        $parent_id =
            $term->term_id;
    }


    return [

        'path' =>
            $resolved_terms,

        /**
         * Alleen de diepste term wordt voor filtering
         * gebruikt.
         */
        'term' =>
            end(
                $resolved_terms
            ),
    ];
}


/**
 * ============================================================
 * 7. COMBO ARCHIVE UITLEZEN
 * ============================================================
 */

function tfsc_get_combo_archive() {

    static $cache_set =
        false;

    static $cache =
        false;


    if ( $cache_set ) {
        return $cache;
    }


    $cache_set =
        true;


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    $raw_items =
        [];


    for (
        $i = 1;
        $i <= 3;
        $i++
    ) {

        $taxonomy =
            get_query_var(
                'combo_tax_'
                .
                $i
            );


        $path =
            get_query_var(
                'combo_path_'
                .
                $i
            );


        if (
            $taxonomy
            &&
            $path
        ) {

            $raw_items[] = [

                'taxonomy' =>
                    $taxonomy,

                'path' =>
                    $path,
            ];
        }
    }


    /**
     * Eén taxonomy is voldoende.
     */
    if (
        empty(
            $raw_items
        )
    ) {
        return false;
    }


    $items =
        [];

    $used_taxonomies =
        [];


    foreach (
        $raw_items
        as $raw_item
    ) {

        $taxonomy =
            sanitize_key(
                $raw_item[
                    'taxonomy'
                ]
            );


        $path =
            trim(
                (string)
                $raw_item[
                    'path'
                ],
                '/'
            );


        if (
            ! $taxonomy
            ||
            ! $path
        ) {
            return false;
        }


        /**
         * Taxonomy niet dubbel toestaan.
         */
        if (
            in_array(
                $taxonomy,
                $used_taxonomies,
                true
            )
        ) {
            return false;
        }


        if (
            ! tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return false;
        }


        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $path
            );


        if ( ! $resolved ) {
            return false;
        }


        $items[] = [

            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved[
                    'term'
                ],

            'path' =>
                $resolved[
                    'path'
                ],
        ];


        $used_taxonomies[] =
            $taxonomy;
    }


    $cache =
        $items;


    return $cache;
}


/**
 * ============================================================
 * 8. TAX QUERY BOUWEN
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! is_array( $combo )
        ||
        empty( $combo )
    ) {
        return false;
    }


    $tax_query = [

        'relation' =>
            'AND',
    ];


    foreach (
        $combo
        as $item
    ) {

        $tax_object =
            get_taxonomy(
                $item[
                    'taxonomy'
                ]
            );


        $tax_query[] = [

            'taxonomy' =>
                $item[
                    'taxonomy'
                ],

            'field' =>
                'term_id',

            'terms' => [

                (int)
                $item[
                    'term'
                ]
                ->term_id,
            ],

            'operator' =>
                'IN',

            /**
             * Provincie neemt dus ook childplaatsen mee.
             */
            'include_children' =>
                (
                    $tax_object
                    &&
                    $tax_object
                        ->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/**
 * ============================================================
 * 9. SEARCH & FILTER CUSTOM INTEGRATION REGISTREREN
 * ============================================================
 *
 * Hierdoor verschijnt:
 *
 * TFSC Combined Vacancy Archive
 *
 * als query integration in Search & Filter.
 */

add_action(
    'search-filter/settings/init',
    function() {

        if (
            ! class_exists(
                '\Search_Filter\Queries\Settings'
            )
        ) {
            return;
        }


        $setting =
            \Search_Filter\Queries\Settings
                ::get_setting(
                    'queryIntegration'
                );


        if ( ! $setting ) {
            return;
        }


        $setting->add_option(
            [
                'label' =>
                    'TFSC Combined Vacancy Archive',

                'value' =>
                    TFSC_SEARCH_FILTER_INTEGRATION,
            ]
        );
    },
    10
);


/**
 * ============================================================
 * 10. SEARCH & FILTER LIVE-SEARCH SELECTORS
 * ============================================================
 *
 * Elementor Loop Grid krijgt:
 *
 * Advanced → CSS ID:
 *
 * tfsc-vacancy-results
 *
 * Daardoor weet Search & Filter exact welk gedeelte van
 * de pagina bij live filtering vervangen moet worden.
 */

add_filter(
    'search-filter/queries/query/get_attributes',
    function(
        $attributes,
        $query
    ) {

        if (
            ! isset(
                $attributes[
                    'queryIntegration'
                ]
            )
        ) {
            return $attributes;
        }


        if (
            $attributes[
                'queryIntegration'
            ]
            !==
            TFSC_SEARCH_FILTER_INTEGRATION
        ) {
            return $attributes;
        }


        /**
         * Volledige Elementor Loop Grid widget.
         */
        $attributes[
            'queryContainer'
        ] =
            '#tfsc-vacancy-results';


        /**
         * Elementor Loop Grid posts.
         */
        $attributes[
            'queryPostsContainer'
        ] =
            '#tfsc-vacancy-results '
            .
            '.elementor-loop-container';


        /**
         * Elementor pagination.
         *
         * S&F behandelt dit als child van queryContainer.
         */
        $attributes[
            'queryPaginationSelector'
        ] =
            'a.page-numbers';


        return $attributes;
    },
    10,
    2
);


/**
 * ============================================================
 * 11. WORDPRESS MAIN QUERY
 * ============================================================
 *
 * DIT IS DE ENIGE VACATURE RESULTATENQUERY.
 *
 * We maken dus geen tweede Elementor / S&F WP_Query meer.
 *
 * Belangrijk:
 * priority 1 zodat Search & Filter daarna deze query
 * verder kan filteren.
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin()
            ||
            ! $query->is_main_query()
            ||
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $combo_tax_query =
            tfsc_build_combo_tax_query();


        if (
            ! $combo_tax_query
        ) {
            return;
        }


        /**
         * Vacatures.
         */
        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        /**
         * Vaste voorwaarden uit onze SEO/archive URL.
         */
        $query->set(
            'tax_query',
            $combo_tax_query
        );


        /**
         * Search & Filter Pro v3:
         *
         * koppel Query #1 aan DEZE bestaande
         * WordPress main query.
         */
        $query->set(
            'search_filter_query_id',
            TFSC_SEARCH_FILTER_QUERY_ID
        );


        /**
         * Nodig voor correcte pagination.
         */
        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


/**
 * ============================================================
 * 12. ARCHIVE STATUS
 * ============================================================
 */

add_action(
    'wp',
    function() {

        if (
            ! tfsc_is_combo_archive()
            ||
            ! tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->is_home =
            false;

        $wp_query->is_front_page =
            false;

        $wp_query->is_page =
            false;

        $wp_query->is_single =
            false;

        $wp_query->is_singular =
            false;

        $wp_query->is_search =
            false;

        $wp_query->is_404 =
            false;


        /**
         * Wel een archive.
         */
        $wp_query->is_archive =
            true;
    }
);


/**
 * ============================================================
 * 13. ONGELDIGE COMBO URL → 404
 * ============================================================
 */

add_action(
    'template_redirect',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        if (
            tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->set_404();

        status_header(
            404
        );

        nocache_headers();
    }
);


/**
 * ============================================================
 * 14. ELEMENTOR ARCHIVE CONDITION
 * ============================================================
 */

add_action(
    'elementor/theme/register_conditions',
    function(
        $conditions_manager
    ) {

        if (
            ! class_exists(
                '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base'
            )
        ) {
            return;
        }


        if (
            ! class_exists(
                'TFSC_Combined_Vacancy_Archive_Condition'
            )
        ) {

            class
            TFSC_Combined_Vacancy_Archive_Condition

            extends
            \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {


                public static function get_type() {

                    return
                        'archive';
                }


                public static function get_priority() {

                    return
                        40;
                }


                public function get_name() {

                    return
                        'tfsc_combined_vacancy_archive';
                }


                public function get_label() {

                    return
                        'Combined Vacancy Archives';
                }


                public function check(
                    $args
                ) {

                    return (

                        tfsc_is_combo_archive()

                        &&

                        false
                        !==
                        tfsc_get_combo_archive()
                    );
                }
            }
        }


        $archive_condition =
            $conditions_manager
                ->get_condition(
                    'archive'
                );


        if (
            $archive_condition
        ) {

            $archive_condition
                ->register_sub_condition(

                    new
                    TFSC_Combined_Vacancy_Archive_Condition()
                );
        }
    }
);


/**
 * ============================================================
 * 15. HEADING
 * ============================================================
 *
 * [combo_heading]
 */

add_shortcode(
    'combo_heading',
    function() {

        $combo =
            tfsc_get_combo_archive();


        if ( ! $combo ) {
            return '';
        }


        $function_parts =
            [];

        $other_parts =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                $item[
                    'taxonomy'
                ]
                ===
                'functienaam'
            ) {

                $function_parts[] =
                    $item[
                        'term'
                    ]
                    ->name;

            } else {

                $other_parts[] =
                    $item[
                        'term'
                    ]
                    ->name;
            }
        }


        return esc_html(
            implode(
                ' - ',
                array_merge(
                    $function_parts,
                    $other_parts
                )
            )
        );
    }
);


/**
 * ============================================================
 * 16. SPECIFIEKE TERM
 * ============================================================
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',
                ],
                $atts
            );


        $wanted_taxonomy =
            sanitize_key(
                $atts[
                    'taxonomy'
                ]
            );


        if (
            ! $wanted_taxonomy
        ) {
            return '';
        }


        $combo =
            tfsc_get_combo_archive();


        if ( ! $combo ) {
            return '';
        }


        foreach (
            $combo
            as $item
        ) {

            if (
                $item[
                    'taxonomy'
                ]
                ===
                $wanted_taxonomy
            ) {

                return esc_html(
                    $item[
                        'term'
                    ]
                    ->name
                );
            }
        }


        return '';
    }
);


/**
 * ============================================================
 * 17. RANK MATH SEO TITLE
 * ============================================================
 */

add_filter(
    'rank_math/frontend/title',
    function( $title ) {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return $title;
        }


        $combo =
            tfsc_get_combo_archive();


        if ( ! $combo ) {
            return $title;
        }


        $functienaam =
            '';

        $other_terms =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                $item[
                    'taxonomy'
                ]
                ===
                'functienaam'
            ) {

                $functienaam =
                    $item[
                        'term'
                    ]
                    ->name;

            } else {

                $other_terms[] =
                    $item[
                        'term'
                    ]
                    ->name;
            }
        }


        if (
            $functienaam
        ) {

            return implode(
                ' - ',
                array_merge(
                    [
                        $functienaam
                        .
                        ' vacatures'
                    ],
                    $other_terms
                )
            );
        }


        if (
            ! empty(
                $other_terms
            )
        ) {

            $first =
                array_shift(
                    $other_terms
                );


            return implode(
                ' - ',
                array_merge(
                    [
                        $first
                        .
                        ' vacatures'
                    ],
                    $other_terms
                )
            );
        }


        return $title;
    }
);


/**
 * ============================================================
 * 18. RANK MATH META DESCRIPTION
 * ============================================================
 */

add_filter(
    'rank_math/frontend/description',
    function(
        $description
    ) {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return $description;
        }


        $combo =
            tfsc_get_combo_archive();


        if ( ! $combo ) {
            return $description;
        }


        $functienaam  = '';
        $kennisgebied = '';
        $locatie      = '';
        $branche      = '';


        foreach (
            $combo
            as $item
        ) {

            $name =
                $item[
                    'term'
                ]
                ->name;


            switch (
                $item[
                    'taxonomy'
                ]
            ) {

                case
                    'functienaam':

                    $functienaam =
                        $name;

                    break;


                case
                    'kennisgebied':

                    $kennisgebied =
                        $name;

                    break;


                case
                    'locatie':

                    $locatie =
                        $name;

                    break;


                case
                    'branche':

                    $branche =
                        $name;

                    break;
            }
        }


        $parts =
            [];


        if (
            $functienaam
        ) {

            $parts[] =
                $functienaam
                .
                ' vacatures';

        } else {

            $parts[] =
                'Vacatures';
        }


        if (
            $kennisgebied
        ) {

            $parts[] =
                'in '
                .
                $kennisgebied;
        }


        if (
            $branche
        ) {

            $parts[] =
                'binnen '
                .
                $branche;
        }


        if (
            $locatie
        ) {

            $parts[] =
                'in '
                .
                $locatie;
        }


        return
            implode(
                ' ',
                $parts
            )
            .
            '. Bekijk actuele vacatures en solliciteer direct.';
    }
);

/**
 * ============================================================
 * TFSC - DYNAMISCHE / GECOMBINEERDE VACATURE ARCHIEVEN
 * + SEARCH & FILTER PRO V3
 * ============================================================
 *
 * Ondersteunt automatisch alle publieke taxonomies
 * die gekoppeld zijn aan het CPT "vacature".
 *
 *
 * Voorbeelden:
 *
 * /vacatures/functienaam/field-service-engineer/
 *
 * /vacatures/functienaam/field-service-engineer/
 * locatie/noord-brabant/
 *
 * /vacatures/functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/tilburg/
 *
 *
 * ELEMENTOR
 * ------------------------------------------------------------
 *
 * Archive Condition:
 * Combined Vacancy Archives
 *
 * Loop Grid:
 * Source = Current Query
 *
 * GEEN custom Elementor Query ID.
 *
 *
 * SEARCH & FILTER
 * ------------------------------------------------------------
 *
 * Query:
 * Vacatures
 *
 * Query ID:
 * 1
 *
 * Location:
 * Archive
 *
 * Post Type:
 * Vacature
 *
 * Include Taxonomy Archives:
 * All Taxonomies
 *
 * Indexer:
 * AAN
 *
 *
 * BELANGRIJK VOOR SEARCH & FILTER FIELDS
 * ------------------------------------------------------------
 *
 * URL Name moet gelijk zijn aan de taxonomy slug.
 *
 * Voorbeelden:
 *
 * taxonomy functienaam
 * URL Name: functienaam
 *
 * taxonomy kennisgebied
 * URL Name: kennisgebied
 *
 * taxonomy locatie
 * URL Name: locatie
 *
 * Nieuwe taxonomies hoeven NIET in deze PHP toegevoegd
 * te worden.
 *
 *
 * SHORTCODES
 * ------------------------------------------------------------
 *
 * [combo_heading]
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

define(
    'TFSC_COMBO_BASE',
    'vacatures'
);

define(
    'TFSC_VACANCY_POST_TYPE',
    'vacature'
);

define(
    'TFSC_SEARCH_FILTER_QUERY_ID',
    1
);


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';

        $vars[] = 'combo_tax_1';
        $vars[] = 'combo_path_1';

        $vars[] = 'combo_tax_2';
        $vars[] = 'combo_path_2';

        $vars[] = 'combo_tax_3';
        $vars[] = 'combo_path_3';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if ( ! $tax_object ) {
        return false;
    }


    /**
     * Alleen publiek bevraagbare taxonomies.
     */
    if (
        ! $tax_object->publicly_queryable
    ) {
        return false;
    }


    /**
     * Taxonomy moet gekoppeld zijn
     * aan het Vacature CPT.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. TOEGESTANE TAXONOMIES
 * ============================================================
 *
 * Wordt automatisch uit WordPress gehaald.
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed = [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * 4. SEARCH & FILTER URL NAME
 * ============================================================
 *
 * Volledig automatisch:
 *
 * taxonomy slug
 * =
 * Search & Filter URL Name
 *
 *
 * functienaam  -> functienaam
 * kennisgebied -> kennisgebied
 * locatie      -> locatie
 * branche      -> branche
 * sector       -> sector
 *
 * enzovoort.
 */

function tfsc_get_search_filter_url_name(
    $taxonomy
) {

    if (
        ! tfsc_combo_taxonomy_allowed(
            $taxonomy
        )
    ) {
        return false;
    }


    return sanitize_key(
        $taxonomy
    );
}


/**
 * ============================================================
 * 5. REWRITE RULES
 * ============================================================
 *
 * Ondersteunt:
 *
 * 1 taxonomy
 * 2 taxonomies
 * 3 taxonomies
 *
 * De laatste taxonomy mag een hiërarchisch pad hebben.
 *
 * Bijvoorbeeld:
 *
 * locatie/noord-brabant/tilburg/
 */

add_action(
    'init',
    function() {

        $taxonomies =
            tfsc_get_allowed_combo_taxonomies();


        if (
            empty(
                $taxonomies
            )
        ) {
            return;
        }


        $escaped =
            array_map(
                function( $taxonomy ) {

                    return preg_quote(
                        $taxonomy,
                        '/'
                    );
                },
                $taxonomies
            );


        $tax_regex =
            '(?:'
            .
            implode(
                '|',
                $escaped
            )
            .
            ')';


        /**
         * ----------------------------------------------------
         * 3 TAXONOMIES
         * ----------------------------------------------------
         */

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )

            . '/('
            . $tax_regex
            . ')/([^/]+)'

            . '/('
            . $tax_regex
            . ')/([^/]+)'

            . '/('
            . $tax_regex
            . ')/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'

            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]'

            . '&combo_tax_2=$matches[3]'
            . '&combo_path_2=$matches[4]'

            . '&combo_tax_3=$matches[5]'
            . '&combo_path_3=$matches[6]',

            'top'
        );


        /**
         * ----------------------------------------------------
         * 2 TAXONOMIES
         * ----------------------------------------------------
         */

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )

            . '/('
            . $tax_regex
            . ')/([^/]+)'

            . '/('
            . $tax_regex
            . ')/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'

            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]'

            . '&combo_tax_2=$matches[3]'
            . '&combo_path_2=$matches[4]',

            'top'
        );


        /**
         * ----------------------------------------------------
         * 1 TAXONOMY
         * ----------------------------------------------------
         */

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )

            . '/('
            . $tax_regex
            . ')/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'

            . '&combo_tax_1=$matches[1]'
            . '&combo_path_1=$matches[2]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * 6. IS COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (bool)
        get_query_var(
            'tfsc_combo_archive'
        );
}


/**
 * ============================================================
 * 7. TERMPAD VALIDEREN
 * ============================================================
 *
 * Voorbeelden:
 *
 * tilburg
 *
 * noord-brabant/tilburg
 *
 * nederland/noord-brabant/tilburg
 *
 *
 * Iedere volgende term moet werkelijk
 * child zijn van de vorige term.
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $path
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if ( ! $tax_object ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    explode(
                        '/',
                        trim(
                            $path,
                            '/'
                        )
                    )
                )
            )
        );


    if (
        empty(
            $segments
        )
    ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     * maximaal één segment.
     */
    if (
        ! $tax_object->hierarchical
        &&
        count( $segments ) > 1
    ) {
        return false;
    }


    $resolved_terms = [];

    $parent_id = 0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term
            ||
            is_wp_error(
                $term
            )
        ) {
            return false;
        }


        /**
         * Vanaf niveau 2 moet de term echt
         * een child van de vorige term zijn.
         */
        if (
            $index > 0
            &&
            (int) $term->parent
            !==
            (int) $parent_id
        ) {
            return false;
        }


        $resolved_terms[] =
            $term;


        $parent_id =
            $term->term_id;
    }


    return [

        /**
         * Volledige hiërarchie.
         */
        'path' =>
            $resolved_terms,

        /**
         * Diepste term wordt daadwerkelijk gefilterd.
         */
        'term' =>
            end(
                $resolved_terms
            ),
    ];
}


/**
 * ============================================================
 * 8. COMBINATIE UITLEZEN
 * ============================================================
 */

function tfsc_get_combo_archive() {

    static $cache_set = false;
    static $cache     = false;


    if (
        $cache_set
    ) {
        return $cache;
    }


    $cache_set = true;


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    $raw_items = [];


    for (
        $i = 1;
        $i <= 3;
        $i++
    ) {

        $taxonomy =
            get_query_var(
                'combo_tax_'
                .
                $i
            );


        $path =
            get_query_var(
                'combo_path_'
                .
                $i
            );


        if (
            $taxonomy
            &&
            $path
        ) {

            $raw_items[] = [

                'taxonomy' =>
                    $taxonomy,

                'path' =>
                    $path,
            ];
        }
    }


    /**
     * Minimaal één taxonomy.
     */
    if (
        empty(
            $raw_items
        )
    ) {
        return false;
    }


    $items = [];

    $used_taxonomies = [];


    foreach (
        $raw_items
        as $raw_item
    ) {

        $taxonomy =
            sanitize_key(
                $raw_item[
                    'taxonomy'
                ]
            );


        $path =
            trim(
                (string)
                $raw_item[
                    'path'
                ],
                '/'
            );


        if (
            ! $taxonomy
            ||
            ! $path
        ) {
            return false;
        }


        /**
         * Dezelfde taxonomy niet twee keer
         * in dezelfde combo-URL.
         */
        if (
            in_array(
                $taxonomy,
                $used_taxonomies,
                true
            )
        ) {
            return false;
        }


        /**
         * Alleen taxonomies van Vacature.
         */
        if (
            ! tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return false;
        }


        /**
         * Term / hiërarchie valideren.
         */
        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $path
            );


        if (
            ! $resolved
        ) {
            return false;
        }


        $items[] = [

            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved[
                    'term'
                ],

            'path' =>
                $resolved[
                    'path'
                ],
        ];


        $used_taxonomies[] =
            $taxonomy;
    }


    $cache =
        $items;


    return $cache;
}


/**
 * ============================================================
 * 9. SEARCH & FILTER ACTIVE VALUES UIT COMBO URL
 * ============================================================
 *
 * Native taxonomy archive:
 *
 * /functienaam/field-service-engineer/
 *
 * Search & Filter kan daar zelf via
 * "Inherit from current location" de actieve term vinden.
 *
 *
 * Virtueel combo archive:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/tilburg/
 *
 * is GEEN native taxonomy archive.
 *
 *
 * Daarom maken we intern van:
 *
 * functienaam/field-service-engineer/
 *
 * effectief:
 *
 * functienaam=field-service-engineer
 *
 *
 * zonder de zichtbare browser-URL te veranderen.
 *
 *
 * BELANGRIJK:
 *
 * De Search & Filter URL Name moet gelijk zijn
 * aan de taxonomy slug.
 */

add_action(
    'parse_request',
    function( $wp ) {

        if (
            empty(
                $wp->query_vars[
                    'tfsc_combo_archive'
                ]
            )
        ) {
            return;
        }


        for (
            $i = 1;
            $i <= 3;
            $i++
        ) {

            /**
             * Taxonomy uit rewrite.
             */
            $taxonomy =
                isset(
                    $wp->query_vars[
                        'combo_tax_'
                        .
                        $i
                    ]
                )
                    ?
                sanitize_key(
                    $wp->query_vars[
                        'combo_tax_'
                        .
                        $i
                    ]
                )
                    :
                '';


            /**
             * Termpad uit rewrite.
             */
            $path =
                isset(
                    $wp->query_vars[
                        'combo_path_'
                        .
                        $i
                    ]
                )
                    ?
                trim(
                    (string)
                    $wp->query_vars[
                        'combo_path_'
                        .
                        $i
                    ],
                    '/'
                )
                    :
                '';


            if (
                ! $taxonomy
                ||
                ! $path
            ) {
                continue;
            }


            /**
             * URL Name automatisch bepalen.
             *
             * functienaam -> functienaam
             * locatie -> locatie
             * sector -> sector
             * enz.
             */
            $parameter =
                tfsc_get_search_filter_url_name(
                    $taxonomy
                );


            if (
                ! $parameter
            ) {
                continue;
            }


            /**
             * Voor:
             *
             * locatie/noord-brabant/tilburg
             *
             * moet Search & Filter de diepste
             * term als actieve waarde krijgen:
             *
             * tilburg
             */
            $segments =
                array_values(
                    array_filter(
                        explode(
                            '/',
                            trim(
                                $path,
                                '/'
                            )
                        )
                    )
                );


            if (
                empty(
                    $segments
                )
            ) {
                continue;
            }


            $term_slug =
                sanitize_title(
                    end(
                        $segments
                    )
                );


            if (
                ! $term_slug
            ) {
                continue;
            }


            /**
             * Als de bezoeker via Search & Filter
             * daadwerkelijk een parameter heeft gekozen,
             * heeft die waarde voorrang.
             */
            if (
                isset(
                    $_GET[
                        $parameter
                    ]
                )
            ) {
                continue;
            }


            /**
             * Search & Filter actieve waarde aanbieden.
             */
            $_GET[
                $parameter
            ] =
                $term_slug;


            $_REQUEST[
                $parameter
            ] =
                $term_slug;
        }
    },
    1
);


/**
 * ============================================================
 * 10. TAX QUERY BOUWEN
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! $combo
    ) {
        return false;
    }


    $tax_query = [

        'relation' =>
            'AND',
    ];


    foreach (
        $combo
        as $item
    ) {

        $tax_object =
            get_taxonomy(
                $item[
                    'taxonomy'
                ]
            );


        $tax_query[] = [

            'taxonomy' =>
                $item[
                    'taxonomy'
                ],

            'field' =>
                'term_id',

            'terms' => [

                (int)
                $item[
                    'term'
                ]
                ->term_id,
            ],

            'operator' =>
                'IN',

            /**
             * Hiërarchische taxonomy:
             *
             * bij Noord-Brabant bijvoorbeeld ook
             * Tilburg, Eindhoven enz. meenemen.
             */
            'include_children' =>
                (
                    $tax_object
                    &&
                    $tax_object
                        ->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/**
 * ============================================================
 * 11. WORDPRESS MAIN QUERY
 * ============================================================
 *
 * Elementor:
 *
 * Loop Grid → Source = Current Query
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin()
            ||
            ! $query->is_main_query()
            ||
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $tax_query =
            tfsc_build_combo_tax_query();


        if (
            ! $tax_query
        ) {
            return;
        }


        /**
         * Alleen vacatures.
         */
        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        /**
         * Taxonomies uit SEO-URL.
         */
        $query->set(
            'tax_query',
            $tax_query
        );


        /**
         * Search & Filter Query #1
         * koppelen aan deze WP main query.
         */
        $query->set(
            'search_filter_query_id',
            TFSC_SEARCH_FILTER_QUERY_ID
        );


        /**
         * Nodig voor correcte aantallen/pagination.
         */
        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


/**
 * ============================================================
 * 12. ARCHIVE STATUS
 * ============================================================
 */

add_action(
    'wp',
    function() {

        if (
            ! tfsc_is_combo_archive()
            ||
            ! tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->is_home =
            false;

        $wp_query->is_front_page =
            false;

        $wp_query->is_page =
            false;

        $wp_query->is_single =
            false;

        $wp_query->is_singular =
            false;

        $wp_query->is_search =
            false;

        $wp_query->is_404 =
            false;


        /**
         * Dit is een archive.
         */
        $wp_query->is_archive =
            true;
    }
);


/**
 * ============================================================
 * 13. ONGELDIGE COMBINATIE → 404
 * ============================================================
 */

add_action(
    'template_redirect',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        if (
            tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->set_404();


        status_header(
            404
        );


        nocache_headers();
    }
);


/**
 * ============================================================
 * 14. ELEMENTOR ARCHIVE CONDITION
 * ============================================================
 *
 * Geeft in Elementor Theme Builder:
 *
 * Combined Vacancy Archives
 */

add_action(
    'elementor/theme/register_conditions',
    function(
        $conditions_manager
    ) {

        if (
            ! class_exists(
                '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base'
            )
        ) {
            return;
        }


        if (
            ! class_exists(
                'TFSC_Combined_Vacancy_Archive_Condition'
            )
        ) {

            class
            TFSC_Combined_Vacancy_Archive_Condition

            extends
            \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {


                public static function get_type() {

                    return
                        'archive';
                }


                public static function get_priority() {

                    return
                        40;
                }


                public function get_name() {

                    return
                        'tfsc_combined_vacancy_archive';
                }


                public function get_label() {

                    return
                        'Combined Vacancy Archives';
                }


                public function check(
                    $args
                ) {

                    return (

                        tfsc_is_combo_archive()

                        &&

                        false
                        !==
                        tfsc_get_combo_archive()
                    );
                }
            }
        }


        $archive_condition =
            $conditions_manager
                ->get_condition(
                    'archive'
                );


        if (
            $archive_condition
        ) {

            $archive_condition
                ->register_sub_condition(

                    new
                    TFSC_Combined_Vacancy_Archive_Condition()
                );
        }
    }
);


/**
 * ============================================================
 * 15. HEADING
 * ============================================================
 *
 * [combo_heading]
 *
 * Voorbeelden:
 *
 * Field Service Engineer
 *
 * Field Service Engineer - Noord-Brabant
 *
 * Field Service Engineer - Elektrotechniek - Tilburg
 */

add_shortcode(
    'combo_heading',
    function() {

        $combo =
            tfsc_get_combo_archive();


        if (
            ! $combo
        ) {
            return '';
        }


        $function_parts = [];

        $other_parts = [];


        foreach (
            $combo
            as $item
        ) {

            /**
             * Functienaam altijd vooraan.
             */
            if (
                $item[
                    'taxonomy'
                ]
                ===
                'functienaam'
            ) {

                $function_parts[] =
                    $item[
                        'term'
                    ]
                    ->name;

            } else {

                $other_parts[] =
                    $item[
                        'term'
                    ]
                    ->name;
            }
        }


        $parts =
            array_merge(
                $function_parts,
                $other_parts
            );


        return esc_html(
            implode(
                ' - ',
                $parts
            )
        );
    }
);


/**
 * ============================================================
 * 16. SPECIFIEKE TERM
 * ============================================================
 *
 * Werkt automatisch met iedere taxonomy.
 *
 *
 * Voorbeelden:
 *
 * [combo_term taxonomy="functienaam"]
 *
 * [combo_term taxonomy="kennisgebied"]
 *
 * [combo_term taxonomy="locatie"]
 *
 * [combo_term taxonomy="branche"]
 *
 * [combo_term taxonomy="sector"]
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',
                ],
                $atts
            );


        $wanted_taxonomy =
            sanitize_key(
                $atts[
                    'taxonomy'
                ]
            );


        if (
            ! $wanted_taxonomy
        ) {
            return '';
        }


        $combo =
            tfsc_get_combo_archive();


        if (
            ! $combo
        ) {
            return '';
        }


        foreach (
            $combo
            as $item
        ) {

            if (
                $item[
                    'taxonomy'
                ]
                ===
                $wanted_taxonomy
            ) {

                return esc_html(
                    $item[
                        'term'
                    ]
                    ->name
                );
            }
        }


        return '';
    }
);

/**
 * ============================================================
 * TFSC - SEARCH & FILTER COMPLETE DEBUG
 * ============================================================
 *
 * TIJDELIJK.
 *
 * Alleen zichtbaar voor admins.
 *
 * Werkt met de huidige generieke combo architectuur:
 *
 * tfsc_combo_archive
 * tfsc_combo_path
 *
