 */

add_action(
    'wp_footer',
    function() {

        if (
            ! current_user_can(
                'manage_options'
            )
        ) {
            return;
        }


        /**
         * ====================================================
         * PHP / WORDPRESS DATA
         * ====================================================
         */

        global $wp_query;


        $combo_output =
            [];


        if (
            function_exists(
                'tfsc_get_combo_archive'
            )
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
            ) {

                foreach (
                    $combo
                    as $item
                ) {

                    $path =
                        [];


                    if (
                        isset(
                            $item['path']
                        )
                        &&
                        is_array(
                            $item['path']
                        )
                    ) {

                        foreach (
                            $item['path']
