                        ) {

                            $path[] = [

                                'id' =>
                                    $term->term_id
                                    ?? null,

                                'slug' =>
                                    $term->slug
                                    ?? null,

                                'name' =>
                                    $term->name
                                    ?? null,

                                'parent' =>
                                    $term->parent
                                    ?? null,
                            ];
                        }
                    }


                    $combo_output[] = [

                        'taxonomy' =>
                            $item['taxonomy']
                            ?? null,

                        'term_id' =>
                            isset(
                                $item['term']->term_id
                            )
                                ?
                            $item['term']->term_id
                                :
                            null,

                        'term_slug' =>
                            isset(
                                $item['term']->slug
                            )
                                ?
                            $item['term']->slug
                                :
                            null,

                        'term_name' =>
                            isset(
                                $item['term']->name
                            )
                                ?
                            $item['term']->name
                                :
                            null,

                        'path' =>
                            $path,
                    ];
                }
            }
        }


        $queried_object =
            get_queried_object();


        if (
            is_object(
                $queried_object
            )
        ) {

            $queried_object_output = [

                'class' =>
                    get_class(
                        $queried_object
                    ),

                'term_id' =>
                    $queried_object->term_id
                    ?? null,

                'taxonomy' =>
                    $queried_object->taxonomy
                    ?? null,

                'slug' =>
                    $queried_object->slug
                    ?? null,

                'name' =>
                    $queried_object->name
                    ?? null,

                'ID' =>
                    $queried_object->ID
                    ?? null,

                'post_type' =>
                    $queried_object->post_type
                    ?? null,
            ];

        } else {

            $queried_object_output =
                $queried_object;
        }


        $php_debug = [

            'url' =>
                home_url(
                    wp_unslash(
                        $_SERVER[
                            'REQUEST_URI'
                        ]
                        ?? '/'
                    )
                ),

            'combo' =>
                $combo_output,

            'GET' =>
                $_GET,

            'REQUEST' =>
                $_REQUEST,

            /**
             * Huidige generieke combo vars.
             */
            'query_vars' => [

                'tfsc_combo_archive' =>
                    get_query_var(
                        'tfsc_combo_archive'
                    ),

                'tfsc_combo_path' =>
                    get_query_var(
                        'tfsc_combo_path'
                    ),
            ],

            'wordpress_conditions' => [

                'is_archive' =>
                    is_archive(),

                'is_tax' =>
                    is_tax(),

                'is_post_type_archive' =>
                    is_post_type_archive(),

                'is_singular' =>
                    is_singular(),

                'is_page' =>
                    is_page(),

                'is_single' =>
                    is_single(),

                'is_search' =>
                    is_search(),

                'is_404' =>
                    is_404(),

                'is_main_query' =>
                    is_main_query(),
            ],

            'queried_object' =>
                $queried_object_output,

            'main_query' => [

                'post_type' =>
                    $wp_query
                        ->query_vars[
                            'post_type'
                        ]
                    ?? null,

                'post_status' =>
                    $wp_query
                        ->query_vars[
                            'post_status'
                        ]
                    ?? null,

                'tax_query' =>
                    $wp_query
                        ->query_vars[
                            'tax_query'
                        ]
                    ?? null,

                'search_filter_query_id' =>
                    $wp_query
                        ->query_vars[
                            'search_filter_query_id'
                        ]
                    ?? null,

                'posts_per_page' =>
                    $wp_query
                        ->query_vars[
                            'posts_per_page'
                        ]
                    ?? null,

                'paged' =>
                    $wp_query
                        ->query_vars[
                            'paged'
                        ]
                    ?? null,

                'found_posts' =>
                    $wp_query
                        ->found_posts
                    ?? null,

                'max_num_pages' =>
                    $wp_query
                        ->max_num_pages
                    ?? null,
            ],
        ];

        ?>


        <style>

            #tfsc-sf-debug {

                position: relative;
                z-index: 999999;

                margin: 30px;
                padding: 20px;

                background: #111;
                color: #eee;

