            </h3>

            <pre id="tfsc-debug-php"><?php

                echo esc_html(
                    wp_json_encode(
                        $php_debug,
                        JSON_PRETTY_PRINT
                        |
                        JSON_UNESCAPED_SLASHES
                        |
                        JSON_UNESCAPED_UNICODE
                    )
                );

            ?></pre>


            <h3>
                2. Search & Filter global data
            </h3>

            <pre id="tfsc-debug-global">
Waiting...
            </pre>


            <h3>
                3. Search & Filter Query #1
            </h3>

            <pre id="tfsc-debug-query">
Waiting...
            </pre>


            <h3>
                4. Search & Filter Fields
            </h3>

            <pre id="tfsc-debug-fields">
Waiting...
            </pre>


            <h3>
                5. Filter DOM inputs
            </h3>

            <pre id="tfsc-debug-dom">
Waiting...
            </pre>


            <h3>
                6. Browser URL
            </h3>

            <pre id="tfsc-debug-url">
Waiting...
            </pre>


            <h3>
                7. LIVE Search & Filter events
            </h3>

            <pre id="tfsc-live-sf-debug">
Waiting for events...
            </pre>

        </div>


        <script>

        (function () {

            const QUERY_ID =
                1;


            let liveEvents =
                [];


            let attachedQuery =
                null;


            /**
             * =================================================
             * SAFE OBJECT SERIALIZER
             * =================================================
             */

            function safeValue(
                value,
                depth = 0
            ) {

                if (
                    depth > 5
                ) {
                    return '[max depth]';
                }


                if (
                    value === null
                    ||
                    value === undefined
                ) {
                    return value;
                }


                if (
                    typeof value === 'string'
                    ||
                    typeof value === 'number'
                    ||
                    typeof value === 'boolean'
                ) {
                    return value;
                }


                if (
                    typeof value === 'function'
                ) {
                    return '[function]';
                }


                if (
                    Array.isArray(
                        value
                    )
                ) {

                    return value.map(
                        function( item ) {

                            return safeValue(
                                item,
                                depth + 1
                            );
                        }
                    );
                }


                if (
                    value instanceof HTMLElement
                ) {

                    return {

                        tag:
                            value.tagName,

                        id:
                            value.id,

                        class:
                            value.className
                    };
                }


                if (
                    value instanceof Map
                ) {

                    return Object.fromEntries(
                        Array.from(
                            value.entries()
                        )
                        .map(
                            function( entry ) {

                                return [

                                    entry[0],

                                    safeValue(
                                        entry[1],
                                        depth + 1
                                    )
                                ];
                            }
                        )
                    );
                }


                if (
                    typeof value === 'object'
                ) {

                    const result =
                        {};


                    Object.keys(
                        value
                    )
                    .forEach(
                        function( key ) {

                            try {

                                result[
                                    key
                                ] =
                                    safeValue(
                                        value[
                                            key
                                        ],
                                        depth + 1
                                    );

                            } catch (
                                error
                            ) {

                                result[
                                    key
                                ] =
                                    '[error reading property]';
                            }
                        }
                    );


                    return result;
                }


                return String(
                    value
                );
            }


            function stringify(
                value
            ) {

                try {

                    return JSON.stringify(
                        value,
                        null,
                        2
                    );

                } catch (
                    error
                ) {

                    return String(
                        error
                    );
                }
            }


            /**
             * =================================================
             * QUERY OPHALEN
             * =================================================
             */

            function getQuery() {

                const queries =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.queries;


                if (
                    ! queries
                    ||
                    typeof queries.get
                    !== 'function'
                ) {
                    return null;
                }


                try {

                    return queries.get(
                        QUERY_ID
                    );

                } catch (
                    error
                ) {

                    return null;
                }
            }


            /**
             * =================================================
             * FIELDS NORMALISEREN
             * =================================================
             */

            function normalizeFields(
                fields
            ) {

                if (
                    ! fields
                ) {
                    return [];
                }


                if (
                    fields instanceof Map
                ) {

                    return Array.from(
                        fields.values()
                    );
                }


                if (
                    Array.isArray(
                        fields
                    )
                ) {

                    return fields;
                }


                if (
                    typeof fields
                    === 'object'
                ) {

                    return Object.values(
                        fields
                    );
                }


                return [];
            }


            /**
             * =================================================
             * FIELD DETAILS
             * =================================================
             */

            function collectField(
                field
            ) {

                const result =
                    {};


                if (
                    ! field
                ) {
                    return result;
                }


                const methods = [

                    'getId',
                    'getName',
                    'getUrlName',
                    'getValues',
                    'getUrlValues',
                    'getUrl',
                    'getState',
                    'getAttributes',
                    'getConnectedData',
                    'getQueryData',
                    'getStoreKey',
                    'getUid'
                ];


                methods.forEach(
                    function( method ) {

                        if (
                            typeof field[
                                method
                            ]
                            === 'function'
                        ) {

                            try {

                                result[
                                    method
                                ] =
                                    safeValue(
                                        field[
                                            method
                                        ]()
                                    );

                            } catch (
                                error
                            ) {

                                result[
                                    method
                                ] =
                                    '[ERROR] '
                                    +
                                    error.message;
                            }

                        } else {

                            result[
                                method
                            ] =
                                '[not available]';
                        }
                    }
                );


                return result;
            }


            /**
             * =================================================
             * GLOBAL DATA
             * =================================================
             */

            function collectGlobalData() {

                return {

                    searchAndFilterExists:
                        !!window
                            .searchAndFilter,

                    searchAndFilterDataExists:
                        !!window
                            .searchAndFilterData,

                    searchAndFilterData:
                        window
                            .searchAndFilterData
                            ?
                        safeValue(
                            window
                                .searchAndFilterData
                        )
                            :
                        null
                };
            }


            /**
             * =================================================
             * QUERY DATA
             * =================================================
             */

            function collectQueryData() {

                const query =
                    getQuery();


                if (
                    ! query
                ) {

                    return {

                        queryFound:
                            false
                    };
                }


                const result = {

                    queryFound:
                        true,

                    objectKeys:
                        Object.keys(
                            query
                        ),

                    methods:
                        {}
                };


                const methods = [

                    'getId',
                    'getUid',
                    'getStoreKey',
                    'getName',
                    'getUrl',
                    'getValues',
                    'getActiveUrlArg',
                    'getAttributes',
                    'getActions',
                    'getFields',
                    'getQueryContainer',
                    'isActive'
                ];


                methods.forEach(
                    function( method ) {

                        if (
                            typeof query[
                                method
                            ]
                            === 'function'
                        ) {

                            try {

                                result
                                    .methods[
                                        method
                                    ] =
                                        safeValue(
                                            query[
                                                method
                                            ]()
                                        );

                            } catch (
                                error
                            ) {

                                result
                                    .methods[
                                        method
                                    ] =
                                        '[ERROR] '
                                        +
                                        error.message;
                            }

                        } else {

                            result
                                .methods[
                                    method
                                ] =
                                    '[not available]';
                        }
                    }
                );


                return result;
            }


            /**
             * =================================================
             * ALL FIELDS
             * =================================================
             */

            function collectFields() {

                const fieldsApi =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.fields;


                if (
                    ! fieldsApi
                    ||
                    typeof fieldsApi.getAll
                    !== 'function'
                ) {

                    return {

                        apiExists:
                            false,

                        fields:
                            []
                    };
                }


                let fields =
                    [];


                try {

                    fields =
                        normalizeFields(
                            fieldsApi.getAll()
                        );

                } catch (
                    error
                ) {

                    return {

                        apiExists:
                            true,

                        error:
                            error.message,

                        fields:
                            []
                    };
                }


                return {

                    apiExists:
                        true,

                    apiKeys:
                        Object.keys(
                            fieldsApi
                        ),

                    fields:
                        fields.map(
                            function(
                                field,
                                index
                            ) {

                                return {

                                    index:
                                        index,

                                    objectKeys:
                                        Object.keys(
                                            field
                                            ||
                                            {}
                                        ),

                                    state:
                                        collectField(
                                            field
                                        )
                                };
                            }
                        )
                };
            }


            /**
             * =================================================
             * DOM INPUTS
             * =================================================
             */

            function collectDomInputs() {

                const output =
                    [];


                document
                    .querySelectorAll(
                        '.search-filter-field input,'
                        +
                        '.search-filter-field select,'
                        +
                        '.search-filter-field textarea'
                    )
                    .forEach(
                        function(
                            element
                        ) {

                            const item = {

                                tag:
                                    element.tagName,

                                type:
                                    element.type
                                    ||
                                    null,

                                name:
                                    element.name
                                    ||
                                    null,

                                id:
                                    element.id
                                    ||
                                    null,

                                value:
                                    element.value,

                                checked:
                                    (
                                        'checked'
                                        in
                                        element
                                    )
                                        ?
                                    element.checked
                                        :
                                    null,

                                disabled:
                                    element.disabled,

                                class:
                                    element.className
                            };


                            if (
                                element.tagName
                                ===
                                'SELECT'
                            ) {

                                item
                                    .selectedOptions =
                                        Array.from(
                                            element
                                                .selectedOptions
                                        )
                                        .map(
                                            function(
                                                option
                                            ) {

                                                return {

                                                    value:
                                                        option.value,

                                                    text:
                                                        option.text,

                                                    selected:
                                                        option.selected
                                                };
                                            }
                                        );
                            }


                            output.push(
                                item
                            );
                        }
                    );


                return output;
            }


            /**
             * =================================================
             * CURRENT BROWSER URL
             * =================================================
             */

            function collectUrl() {

                return {

                    href:
                        window
                            .location
                            .href,

                    origin:
                        window
                            .location
                            .origin,

                    pathname:
                        window
                            .location
                            .pathname,

                    search:
                        window
                            .location
                            .search,

                    hash:
                        window
                            .location
                            .hash,

                    searchParams:
                        Object.fromEntries(
                            new URLSearchParams(
                                window
                                    .location
                                    .search
                            )
                        )
                };
            }


            /**
             * =================================================
             * PANEL REFRESH
             * =================================================
             */

            function updateDebug() {

                const globalElement =
                    document.getElementById(
                        'tfsc-debug-global'
                    );


                const queryElement =
                    document.getElementById(
                        'tfsc-debug-query'
                    );


                const fieldsElement =
                    document.getElementById(
                        'tfsc-debug-fields'
                    );


                const domElement =
                    document.getElementById(
                        'tfsc-debug-dom'
                    );


                const urlElement =
                    document.getElementById(
                        'tfsc-debug-url'
                    );


                if (
                    globalElement
                ) {

                    globalElement
                        .textContent =
                            stringify(
                                collectGlobalData()
                            );
                }


                if (
                    queryElement
                ) {

                    queryElement
                        .textContent =
                            stringify(
                                collectQueryData()
                            );
                }


                if (
                    fieldsElement
                ) {

                    fieldsElement
                        .textContent =
                            stringify(
                                collectFields()
                            );
                }


                if (
                    domElement
                ) {

                    domElement
                        .textContent =
                            stringify(
                                collectDomInputs()
                            );
                }


                if (
                    urlElement
                ) {

                    urlElement
                        .textContent =
                            stringify(
                                collectUrl()
                            );
                }
            }


            /**
             * =================================================
             * LIVE EVENT SNAPSHOT
             * =================================================
             */

            function createLiveSnapshot(
                eventName,
                args
            ) {

                const query =
                    getQuery();


                let queryFields =
                    [];


                if (
                    query
                    &&
                    typeof query.getFields
                    === 'function'
                ) {

                    try {

                        queryFields =
                            normalizeFields(
                                query.getFields()
                            );

                    } catch (
                        error
                    ) {

                        queryFields =
                            [];
                    }
                }


                return {

                    time:
                        new Date()
                            .toISOString(),

                    event:
                        eventName,

                    browserUrl:
                        window
                            .location
                            .href,

                    eventArguments:
                        safeValue(
                            args
                        ),

                    query: {

                        url:
                            query
                            &&
                            typeof query.getUrl
                            === 'function'
                                ?
                            query.getUrl()
                                :
                            null,

                        values:
                            query
                            &&
                            typeof query.getValues
                            === 'function'
                                ?
                            safeValue(
                                query.getValues()
                            )
                                :
                            null,

                        activeUrlArg:
                            query
                            &&
                            typeof query.getActiveUrlArg
                            === 'function'
                                ?
                            safeValue(
                                query.getActiveUrlArg()
                            )
                                :
                            null,

                        attributes:
                            query
                            &&
                            typeof query.getAttributes
                            === 'function'
                                ?
                            safeValue(
                                query.getAttributes()
                            )
                                :
                            null
                    },

                    fields:
                        queryFields.map(
                            function(
                                field
                            ) {

                                return collectField(
                                    field
                                );
                            }
                        ),

                    domInputs:
                        collectDomInputs()
                };
            }


            function renderLiveEvents() {

                const element =
                    document.getElementById(
                        'tfsc-live-sf-debug'
                    );


                if (
                    ! element
                ) {
                    return;
                }


                element.textContent =
                    stringify(
                        liveEvents
                    );
            }


            function addLiveEvent(
                eventName,
                args
            ) {

                liveEvents.push(
                    createLiveSnapshot(
                        eventName,
                        args
                    )
                );


                /**
                 * Niet onbeperkt laten groeien.
                 */
                if (
                    liveEvents.length > 20
                ) {

                    liveEvents =
                        liveEvents.slice(
                            -20
                        );
                }


                renderLiveEvents();


                /**
                 * Ook de normale debug vernieuwen.
                 */
                setTimeout(
                    updateDebug,
                    25
                );
            }


            /**
             * =================================================
             * QUERY EVENTS ATTACHEN
             * =================================================
             */

            function attachQueryEvents() {

                const query =
                    getQuery();


                if (
                    ! query
                    ||
                    typeof query.on
                    !== 'function'
                ) {
                    return false;
                }


                /**
                 * Nieuwe query instance?
                 */
                if (
                    attachedQuery
                    ===
                    query
                ) {
                    return true;
                }


                attachedQuery =
                    query;


                const events = [

                    'get-results/start',
                    'get-results/finish',
                    'update',
                    'change',
                    'submit',
                    'reset'
                ];


                events.forEach(
                    function(
                        eventName
                    ) {

                        try {

                            query.on(
                                eventName,
                                function() {

                                    addLiveEvent(
                                        eventName,
                                        Array.from(
                                            arguments
                                        )
                                    );
                                }
                            );

                        } catch (
                            error
                        ) {

                            console.log(
                                'TFSC debug event attach failed:',
                                eventName,
                                error
                            );
                        }
                    }
                );


                addLiveEvent(
                    'debug-attached',
                    []
                );


                return true;
            }


            /**
             * =================================================
             * SEARCH & FILTER GLOBAL EVENTS
             * =================================================
             */

            document.addEventListener(
                'search-filter/mount',
                function(
                    event
                ) {

                    addLiveEvent(
                        'DOM search-filter/mount',
                        [
                            safeValue(
                                event.detail
                            )
                        ]
                    );


                    setTimeout(
                        attachQueryEvents,
                        0
                    );


                    setTimeout(
                        updateDebug,
                        50
                    );
                }
            );


            /**
             * =================================================
             * URL / BROWSER HISTORY DEBUG
             * =================================================
             *
             * Belangrijk voor ons huidige probleem.
             */

            window.addEventListener(
                'popstate',
                function(
                    event
                ) {

                    addLiveEvent(
                        'browser popstate',
                        [
                            safeValue(
                                event.state
                            )
                        ]
                    );


                    setTimeout(
                        updateDebug,
                        20
                    );
                }
            );


            /**
             * pushState / replaceState onderscheppen
             * voor debugging.
             */

            const originalPushState =
                history.pushState;


            history.pushState =
                function() {

                    const result =
                        originalPushState
                            .apply(
                                this,
                                arguments
                            );


                    addLiveEvent(
                        'history.pushState',
                        Array.from(
                            arguments
                        )
                    );


                    return result;
                };


            const originalReplaceState =
                history.replaceState;


            history.replaceState =
                function() {

                    const result =
                        originalReplaceState
                            .apply(
                                this,
                                arguments
                            );


                    addLiveEvent(
                        'history.replaceState',
                        Array.from(
                            arguments
                        )
                    );


                    return result;
                };


            /**
             * =================================================
             * INITIALISATIE
             * =================================================
             */

            function startDebug() {

                updateDebug();


                attachQueryEvents();


                /**
                 * S&F kan iets later mounten.
                 */
                setTimeout(
                    function() {

                        attachQueryEvents();
                        updateDebug();

                    },
                    250
                );


                setTimeout(
                    function() {

                        attachQueryEvents();
                        updateDebug();

                    },
                    750
                );


                setTimeout(
                    function() {

                        attachQueryEvents();
                        updateDebug();

                    },
                    1500
                );
            }


            if (
                document.readyState
                === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    startDebug
                );

            } else {

                startDebug();
            }


            /**
             * =================================================
             * BUTTONS
             * =================================================
             */

            document.addEventListener(
                'click',
                function(
                    event
                ) {

                    if (
                        event.target.id
                        ===
                        'tfsc-debug-refresh'
                    ) {

                        updateDebug();

                        attachQueryEvents();

                        return;
                    }


                    if (
                        event.target.id
                        !==
                        'tfsc-debug-copy'
                    ) {
                        return;
                    }


                    const panel =
                        document.getElementById(
                            'tfsc-sf-debug'
                        );


                    if (
                        ! panel
                    ) {
                        return;
                    }


                    navigator.clipboard
                        .writeText(
                            panel.innerText
                        )
                        .then(
                            function() {

                                event.target
                                    .textContent =
                                    'Copied';
                            }
                        );
                }
            );

        })();

        </script>

        <?php
    },
    999
);

/**
 * ============================================================
 * TFSC - VOLLEDIG DYNAMISCHE VACATURE ARCHIEVEN
 * + SEARCH & FILTER PRO V3
 * ============================================================
 *
 * ONBEPERKT AANTAL TAXONOMIES.
 *
 *
 * Voorbeelden:
 *
 * /vacatures/functienaam/field-service-engineer/
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/tilburg/
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * branche/machinebouw/
 * sector/industrie/
 * locatie/noord-brabant/tilburg/
 *
 *
 * ------------------------------------------------------------
 * ELEMENTOR
 * ------------------------------------------------------------
 *
 * Archive Condition:
 * Combined Vacancy Archives
 *
 * Loop Grid:
 * Source = Current Query
 *
 * Geen Elementor Custom Query ID.
 *
 *
 * ------------------------------------------------------------
 * SEARCH & FILTER
 * ------------------------------------------------------------
 *
 * Query:
 * Vacatures
 *
 * Query ID:
 * 1
 *
 * Location:
 * Archive
 *
 * Archive Type:
 * Post Type
 *
 * Post Type:
 * Vacature
 *
 * Include Taxonomy Archives:
 * All Taxonomies
 *
 * Indexer:
 * Aan
 *
 *
 * ------------------------------------------------------------
 * SHORTCODES
 * ------------------------------------------------------------
 *
 * [combo_heading]
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

define(
    'TFSC_COMBO_BASE',
    'vacatures'
);

define(
    'TFSC_VACANCY_POST_TYPE',
    'vacature'
);

define(
    'TFSC_SEARCH_FILTER_QUERY_ID',
    1
);


/**
 * ============================================================
 * 1. QUERY VAR
 * ============================================================
 *
 * We gebruiken nog maar één query-var:
 *
 * tfsc_combo_path
 *
 * Bijvoorbeeld:
 *
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/tilburg
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed(
    $taxonomy
) {

    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    /**
     * Alleen publiek bevraagbare taxonomies.
     */
    if (
        ! $tax_object->publicly_queryable
    ) {
        return false;
    }


    /**
     * Alleen taxonomies gekoppeld aan vacature.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. ALLE TOEGESTANE TAXONOMIES
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed =
        [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * 4. ÉÉN GENERIEKE REWRITE RULE
 * ============================================================
 *
 * Alles na:
 *
 * /vacatures/
 *
 * wordt opgeslagen in:
 *
 * tfsc_combo_path
 *
 *
 * Hierdoor bestaat geen limiet meer op het aantal
 * taxonomies.
 */

add_action(
    'init',
    function() {

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )
            .
            '/(.+?)/?$',

            'index.php'
            .
            '?tfsc_combo_archive=1'
            .
            '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * 5. IS COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (
        (bool)
        get_query_var(
            'tfsc_combo_archive'
        )
    );
}


/**
 * ============================================================
 * 6. HIËRARCHISCH TERMPAD OPLOSSEN
 * ============================================================
 *
 * Voorbeelden:
 *
 * tilburg
 *
 * noord-brabant/tilburg
 *
 * nederland/noord-brabant/tilburg
 *
 *
 * Iedere volgende term moet werkelijk child zijn
 * van de vorige.
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    if (
        ! is_array(
            $segments
        )
        ||
        empty(
            $segments
        )
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        empty(
            $segments
        )
    ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     * exact één termsegment.
     */
    if (
        ! $tax_object->hierarchical
        &&
        count(
            $segments
        ) !== 1
    ) {
        return false;
    }


    $resolved_terms =
        [];


    $parent_id =
        0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term
            ||
            is_wp_error(
                $term
            )
        ) {
            return false;
        }


        /**
         * Vanaf niveau 2 moet de huidige term
         * rechtstreeks child zijn van de vorige.
         */
        if (
            $index > 0
            &&
            (int) $term->parent
            !==
            (int) $parent_id
        ) {
            return false;
        }


        $resolved_terms[] =
            $term;


        $parent_id =
            (int)
            $term->term_id;
    }


    return [

        'path' =>
            $resolved_terms,

        /**
         * Diepste term.
         */
        'term' =>
            end(
                $resolved_terms
            ),
    ];
}


/**
 * ============================================================
 * 7. VOLLEDIGE COMBO-URL PARSEN
 * ============================================================
 *
 * Voorbeeld:
 *
 * functienaam
 * field-service-engineer
 * kennisgebied
 * elektrotechniek
 * locatie
 * noord-brabant
 * tilburg
 *
 *
 * Omdat we alle geldige taxonomy-slugs kennen,
 * kunnen we automatisch bepalen waar een nieuwe
 * taxonomy begint.
 */

function tfsc_get_combo_archive() {

    static $cache_set =
        false;


    static $cache =
        false;


    if (
        $cache_set
    ) {
        return $cache;
    }


    $cache_set =
        true;


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if (
        ! $raw_path
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string)
                        $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    if (
        count(
            $segments
        ) < 2
    ) {
        return false;
    }


    $allowed_taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if (
        empty(
            $allowed_taxonomies
        )
    ) {
        return false;
    }


    $items =
        [];


    $used_taxonomies =
        [];


    $segment_count =
        count(
            $segments
        );


    $index =
        0;


    while (
        $index
        <
        $segment_count
    ) {

        /**
         * Ieder blok moet beginnen met
         * een geldige taxonomy slug.
         */
        $taxonomy =
            sanitize_key(
                $segments[
                    $index
                ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed_taxonomies,
                true
            )
        ) {
            return false;
        }


        /**
         * Taxonomy niet tweemaal in dezelfde URL.
         */
        if (
            in_array(
                $taxonomy,
                $used_taxonomies,
                true
            )
        ) {
            return false;
        }


        $index++;


        /**
         * Nu alle termsegmenten verzamelen
         * totdat de volgende bekende taxonomy begint.
         */
        $term_segments =
            [];


        while (
            $index
            <
            $segment_count
        ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[
                        $index
                    ]
                );


            /**
             * Nieuwe taxonomy gevonden.
             */
            if (
                in_array(
                    $possible_taxonomy,
                    $allowed_taxonomies,
                    true
                )
            ) {
                break;
            }


            $term_segments[] =
                $segments[
                    $index
                ];


            $index++;
        }


        /**
         * Taxonomy zonder term is ongeldig.
         */
        if (
            empty(
                $term_segments
            )
        ) {
            return false;
        }


        /**
         * Termpad valideren.
         */
        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if (
            ! $resolved
        ) {
            return false;
        }


        $items[] = [

            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved[
                    'term'
                ],

            'path' =>
                $resolved[
                    'path'
                ],
        ];


        $used_taxonomies[] =
            $taxonomy;
    }


    if (
        empty(
            $items
        )
    ) {
        return false;
    }


    $cache =
        $items;


    return $cache;
}


/**
 * ============================================================
 * 8. WORDPRESS TAX_QUERY BOUWEN
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! $combo
    ) {
        return false;
    }


    $tax_query = [

        'relation' =>
            'AND',
    ];


    foreach (
        $combo
        as $item
    ) {

        $tax_object =
            get_taxonomy(
                $item[
                    'taxonomy'
                ]
            );


        $tax_query[] = [

            'taxonomy' =>
                $item[
                    'taxonomy'
                ],

            'field' =>
                'term_id',

            'terms' => [

                (int)
                $item[
                    'term'
                ]
                ->term_id,
            ],

            'operator' =>
                'IN',

            /**
             * Bij hiërarchische taxonomies:
             *
             * Provincie Noord-Brabant neemt bijvoorbeeld
             * ook Tilburg en Eindhoven mee.
             */
            'include_children' =>
                (
                    $tax_object
                    &&
                    $tax_object
                        ->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/**
 * ============================================================
 * 9. WORDPRESS MAIN QUERY
 * ============================================================
 *
 * Elementor:
 *
 * Loop Grid → Source = Current Query
 *
 *
 * Search & Filter Query #1 wordt gekoppeld aan
 * dezelfde WP main query.
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin()
            ||
            ! $query->is_main_query()
            ||
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $tax_query =
            tfsc_build_combo_tax_query();


        if (
            ! $tax_query
        ) {
            return;
        }


        /**
         * Alleen vacatures.
         */
        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        /**
         * Alle termen uit de virtuele URL.
         */
        $query->set(
            'tax_query',
            $tax_query
        );


        /**
         * Search & Filter Query koppelen.
         */
        $query->set(
            'search_filter_query_id',
            TFSC_SEARCH_FILTER_QUERY_ID
        );


        /**
         * Nodig voor correcte pagination en counts.
         */
        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


/**
 * ============================================================
 * 10. ARCHIVE STATUS
 * ============================================================
 */

add_action(
    'wp',
    function() {

        if (
            ! tfsc_is_combo_archive()
            ||
            ! tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->is_home =
            false;


        $wp_query->is_front_page =
            false;


        $wp_query->is_page =
            false;


        $wp_query->is_single =
            false;


        $wp_query->is_singular =
            false;


        $wp_query->is_search =
            false;


        $wp_query->is_404 =
            false;


        /**
         * Wel archive.
         */
        $wp_query->is_archive =
            true;
    }
);


/**
 * ============================================================
 * 11. ONGELDIGE COMBO URL → 404
 * ============================================================
 */

add_action(
    'template_redirect',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        if (
            tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->set_404();


        status_header(
            404
        );


        nocache_headers();
    }
);


/**
 * ============================================================
 * 12. SEARCH & FILTER FRONTEND SYNC
 * ============================================================
 *
 * Search & Filter ziet onze virtuele pagina als:
 *
 * is_archive = true
 * is_tax = false
 *
 *
 * Daardoor kan "Inherit archive value" niet automatisch
 * bepalen welke taxonomy-termen uit onze custom URL actief zijn.
 *
 *
 * Uit de debug weten we dat ieder frontend field beschikt over:
 *
 * getAttributes()
 * getValues()
 * setValues()
 *
 *
 * We koppelen daarom automatisch:
 *
 * dataTaxonomy
 *
 * aan de taxonomy in onze combo URL.
 *
 *
 * Geen taxonomy-lijst nodig.
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $combo =
            tfsc_get_combo_archive();


        if (
            ! is_array(
                $combo
            )
            ||
            empty(
                $combo
            )
        ) {
            return;
        }


        /**
         * Automatisch:
         *
         * {
         *   "functienaam": "field-service-engineer",
         *   "kennisgebied": "elektrotechniek",
         *   "branche": "machinebouw",
         *   "locatie": "tilburg"
         * }
         */
        $active_values =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                empty(
                    $item[
                        'taxonomy'
                    ]
                )
                ||
                empty(
                    $item[
                        'term'
                    ]
                    ->slug
                )
            ) {
                continue;
            }


            $active_values[
                $item[
                    'taxonomy'
                ]
            ] =
                $item[
                    'term'
                ]
                ->slug;
        }


        if (
            empty(
                $active_values
            )
        ) {
            return;
        }

        ?>

        <script>
        (function () {

            const TFSC_COMBO_VALUES =
                <?php
                echo wp_json_encode(
                    $active_values
                );
                ?>;


            let tfscApplying =
                false;


            let tfscInitialSyncDone =
                false;


            /**
             * Search & Filter frontend fields ophalen.
             */
            function tfscGetSearchFilterFields() {

                const fieldsApi =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.fields;


                if (
                    ! fieldsApi
                    ||
                    typeof fieldsApi.getAll
                    !== 'function'
                ) {
                    return [];
                }


                let fields =
                    fieldsApi.getAll();


                /**
                 * Map → Array
                 */
                if (
                    fields instanceof Map
                ) {

                    fields =
                        Array.from(
                            fields.values()
                        );
                }


                /**
                 * Object → Array
                 */
                else if (
                    fields
                    &&
                    ! Array.isArray(
                        fields
                    )
                    &&
                    typeof fields
                    === 'object'
                ) {

                    fields =
                        Object.values(
                            fields
                        );
                }


                return Array.isArray(
                    fields
                )
                    ?
                fields
                    :
                [];
            }


            /**
             * Alle combo-termen eenmaal synchroniseren
             * naar de S&F field-state.
             */
            function tfscSyncComboValues() {

                if (
                    tfscApplying
                    ||
                    tfscInitialSyncDone
                ) {
                    return;
                }


                const fields =
                    tfscGetSearchFilterFields();


                if (
                    ! fields.length
                ) {
                    return;
                }


                tfscApplying =
                    true;


                let matchedFields =
                    0;


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getAttributes
                                !== 'function'
                            ||
                            typeof field.getValues
                                !== 'function'
                            ||
                            typeof field.setValues
                                !== 'function'
                        ) {
                            return;
                        }


                        const attributes =
                            field.getAttributes();


                        /**
                         * Alleen taxonomy fields.
                         */
                        if (
                            ! attributes
                            ||
                            attributes.dataType
                                !== 'taxonomy'
                        ) {
                            return;
                        }


                        const taxonomy =
                            attributes.dataTaxonomy;


                        if (
                            ! taxonomy
                            ||
                            ! Object.prototype
                                .hasOwnProperty
                                .call(
                                    TFSC_COMBO_VALUES,
                                    taxonomy
                                )
                        ) {
                            return;
                        }


                        const wantedValue =
                            TFSC_COMBO_VALUES[
                                taxonomy
                            ];


                        let currentValues =
                            field.getValues();


                        if (
                            ! Array.isArray(
                                currentValues
                            )
                        ) {

                            currentValues =
                                [];
                        }


                        matchedFields++;


                        /**
                         * Al correct actief.
                         */
                        if (
                            currentValues.includes(
                                wantedValue
                            )
                        ) {
                            return;
                        }


                        /**
                         * Zoek & Filter frontend API.
                         */
                        field.setValues(
                            [
                                wantedValue
                            ]
                        );
                    }
                );


                tfscApplying =
                    false;


                /**
                 * Alleen klaar verklaren als er daadwerkelijk
                 * S&F fields gevonden zijn die overeenkomen
                 * met onze combo-taxonomies.
                 */
                if (
                    matchedFields > 0
                ) {

                    tfscInitialSyncDone =
                        true;
                }
            }


            /**
             * ------------------------------------------------
             * S&F mount
             * ------------------------------------------------
             */

            document.addEventListener(
                'search-filter/mount',
                function () {

                    setTimeout(
                        tfscSyncComboValues,
                        0
                    );


                    setTimeout(
                        tfscSyncComboValues,
                        100
                    );
                }
            );


            /**
             * ------------------------------------------------
             * Fallback wanneer S&F al gemount is
             * ------------------------------------------------
             */

            function tfscStartComboSync() {

                setTimeout(
                    tfscSyncComboValues,
                    50
                );


                setTimeout(
                    tfscSyncComboValues,
                    250
                );


                setTimeout(
                    tfscSyncComboValues,
                    750
                );


                setTimeout(
                    tfscSyncComboValues,
                    1500
                );
            }


            if (
                document.readyState
                === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartComboSync
                );

            } else {

                tfscStartComboSync();
            }

        })();
        </script>

        <?php
    },
    100
);


