    'vacatures'
);

define(
    'TFSC_VACANCY_POST_TYPE',
    'vacature'
);

define(
    'TFSC_SEARCH_FILTER_QUERY_ID',
    1
);


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 *
 * Alles na:
 *
 * /vacatures/
 *
 * wordt opgeslagen in:
 *
 * tfsc_combo_path
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed(
    $taxonomy
) {

    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    /**
     * Alleen publieke / bevraagbare taxonomies.
     */
    if (
        ! $tax_object->publicly_queryable
    ) {
        return false;
    }


    /**
     * Alleen taxonomies die daadwerkelijk
     * gekoppeld zijn aan CPT vacature.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. ALLE TOEGESTANE TAXONOMIES
 * ============================================================
 *
 * Automatisch ophalen.
 *
 * Nieuwe taxonomy aan vacature toevoegen =
 * automatisch beschikbaar.
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed =
        [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * 4. GENERIEKE REWRITE
 * ============================================================
 *
 * Eén regel voor onbeperkt aantal taxonomies.
 *
 *
 * Bijvoorbeeld:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/tilburg/
 *
 *
 * wordt intern:
 *
 * tfsc_combo_path =
 *
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/tilburg
 */

add_action(
    'init',
    function() {

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )
            .
            '/(.+?)/?$',

            'index.php'
            .
            '?tfsc_combo_archive=1'
            .
            '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * 5. IS DIT EEN COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (
        (bool)
        get_query_var(
            'tfsc_combo_archive'
        )
    );
}


/**
 * ============================================================
 * 6. TERMPAD VALIDEREN
 * ============================================================
 *
 * Ondersteunt bijvoorbeeld:
 *
 * tilburg
 *
 * noord-brabant/tilburg
 *
 * nederland/noord-brabant/tilburg
 *
 *
 * Bij hiërarchische taxonomies controleren we
 * daadwerkelijk de parent-child structuur.
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    if (
        ! is_array(
            $segments
        )
        ||
        empty(
            $segments
        )
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        empty(
            $segments
        )
    ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     *
     * exact één termsegment toegestaan.
     */
    if (
        ! $tax_object->hierarchical
        &&
        count(
            $segments
        ) !== 1
    ) {
        return false;
    }


    $resolved_terms =
        [];


    $parent_id =
        0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term
            ||
            is_wp_error(
                $term
            )
        ) {
            return false;
        }


        /**
         * Vanaf het tweede segment moet
         * de term direct child zijn van
         * de voorgaande term.
         */
        if (
            $index > 0
            &&
            (int) $term->parent
            !==
            (int) $parent_id
        ) {
            return false;
        }


        $resolved_terms[] =
            $term;


        $parent_id =
            (int)
            $term->term_id;
    }


    return [

        /**
         * Volledige hiërarchie.
         */
        'path' =>
            $resolved_terms,

        /**
         * De diepste term is de term
         * waarop daadwerkelijk gefilterd wordt.
         */
        'term' =>
            end(
                $resolved_terms
            ),
    ];
}


/**
 * ============================================================
 * 7. VOLLEDIGE COMBO-URL PARSEN
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * functienaam
 * field-service-engineer
 * kennisgebied
 * elektrotechniek
 * locatie
 * noord-brabant
 * tilburg
 *
 *
 * Omdat alle taxonomy-slugs bekend zijn,
 * herkennen we automatisch waar een nieuwe
 * taxonomy begint.
 *
 *
 * Geen maximum aantal taxonomies.
 */

function tfsc_get_combo_archive() {

    static $cache_set =
        false;


    static $cache =
        false;


    if (
        $cache_set
    ) {
        return $cache;
    }


    $cache_set =
        true;


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if (
        ! $raw_path
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string)
                        $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    /**
     * Minimaal:
     *
     * taxonomy/term
     */
    if (
        count(
            $segments
        ) < 2
    ) {
        return false;
    }


    $allowed_taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if (
        empty(
            $allowed_taxonomies
        )
    ) {
        return false;
    }


    $items =
        [];


    $used_taxonomies =
        [];


    $segment_count =
        count(
            $segments
        );


    $index =
        0;


    while (
        $index
        <
        $segment_count
    ) {

        /**
         * Elk blok moet beginnen
         * met een geldige taxonomy slug.
         */
        $taxonomy =
            sanitize_key(
                $segments[
                    $index
                ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed_taxonomies,
                true
            )
        ) {
            return false;
        }


        /**
         * Dezelfde taxonomy mag niet
         * tweemaal voorkomen.
         */
        if (
            in_array(
                $taxonomy,
                $used_taxonomies,
                true
            )
        ) {
            return false;
        }


        $index++;


        /**
         * Termsegmenten verzamelen totdat
         * de volgende taxonomy begint.
         */
        $term_segments =
            [];


        while (
            $index
            <
            $segment_count
        ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[
                        $index
                    ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed_taxonomies,
                    true
                )
            ) {
                break;
            }


            $term_segments[] =
                $segments[
                    $index
                ];


            $index++;
        }


        /**
         * Een taxonomy zonder term
         * is ongeldig.
         */
        if (
            empty(
                $term_segments
            )
        ) {
            return false;
        }


        /**
         * Term en eventuele hiërarchie
         * daadwerkelijk controleren.
         */
        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if (
            ! $resolved
        ) {
            return false;
        }


        $items[] = [

            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved[
                    'term'
                ],

            'path' =>
                $resolved[
                    'path'
                ],
        ];


        $used_taxonomies[] =
            $taxonomy;
    }


    if (
        empty(
            $items
        )
    ) {
        return false;
    }


    $cache =
        $items;


    return $cache;
}


/**
 * ============================================================
 * 8. WORDPRESS TAX_QUERY
 * ============================================================
 *
 * Alle taxonomies worden met AND gecombineerd.
 */

function tfsc_build_combo_tax_query() {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! $combo
    ) {
        return false;
    }


    $tax_query = [

        'relation' =>
            'AND',
    ];


    foreach (
        $combo
        as $item
    ) {

        $tax_object =
            get_taxonomy(
                $item[
                    'taxonomy'
                ]
            );


        $tax_query[] = [

            'taxonomy' =>
                $item[
                    'taxonomy'
                ],

            'field' =>
                'term_id',

            'terms' => [

                (int)
                $item[
                    'term'
                ]
                ->term_id,
            ],

            'operator' =>
                'IN',

            /**
             * Bij een hiërarchische taxonomy
             * nemen we children mee.
             *
             * Noord-Brabant:
             *
             * → Tilburg
             * → Eindhoven
             * → Breda
             * enz.
             */
            'include_children' =>
                (
                    $tax_object
                    &&
                    $tax_object
                        ->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/**
 * ============================================================
 * 9. COMBO ARCHIVE MAIN QUERY
 * ============================================================
 *
 * BELANGRIJK:
 *
 * Dit is GEEN Search & Filter results query.
 *
 * De combo archive is een SEO-landingspagina.
 *
 *
 * De vacatures worden hier rechtstreeks via
 * WordPress tax_query opgehaald.
 *
 *
 * Elementor:
 *
 * Loop Grid
 * Source = Current Query
 *
 *
 * We zetten hier dus BEWUST NIET:
 *
 * search_filter_query_id
 *
 *
 * Daardoor behandelt Search & Filter deze pagina
 * niet als zijn AJAX-resultatenpagina.
 *
 * Een nieuwe filteractie gaat via de Results Link
 * naar:
 *
 * /vacatures/
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin()
            ||
            ! $query->is_main_query()
            ||
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $tax_query =
            tfsc_build_combo_tax_query();


        if (
            ! $tax_query
        ) {
            return;
        }


        /**
         * Alleen vacatures.
         */
        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        /**
         * Filtervoorwaarden uit de combo URL.
         */
        $query->set(
            'tax_query',
            $tax_query
        );


        /**
         * Correcte pagination/counts.
         */
        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


/**
 * ============================================================
 * 10. ARCHIVE STATUS
 * ============================================================
 */

add_action(
    'wp',
    function() {

        if (
            ! tfsc_is_combo_archive()
            ||
            ! tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->is_home =
            false;


        $wp_query->is_front_page =
            false;


        $wp_query->is_page =
            false;


        $wp_query->is_single =
            false;


        $wp_query->is_singular =
            false;


        $wp_query->is_search =
            false;


        $wp_query->is_404 =
            false;


        /**
         * Elementor moet hem als archive zien.
         */
        $wp_query->is_archive =
            true;
    }
);


/**
 * ============================================================
 * 11. ONGELDIGE COMBO URL → 404
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * /vacatures/functienaam/bestaat-niet/
 *
 * of:
 *
 * /vacatures/onbekende-taxonomy/test/
 */

add_action(
    'template_redirect',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        if (
            tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->set_404();


        status_header(
            404
        );


        nocache_headers();
    }
);


/**
 * ============================================================
 * 12. SEARCH & FILTER FRONTEND FIELD SYNC
 * ============================================================
 *
 * De combo archive is GEEN native taxonomy archive.
 *
 * WordPress / S&F ziet:
 *
 * is_archive = true
 * is_tax     = false
 *
 *
 * Daardoor kan Search & Filter niet automatisch
 * weten welke waarden uit onze mooie URL actief zijn.
 *
 *
 * Daarom zetten we alleen de VISUELE / FRONTEND
 * field-state.
 *
 *
 * Uit debug weten we dat Search & Filter beschikt over:
 *
 * field.getAttributes()
 * field.getValues()
 * field.setValues()
 *
 *
 * We gebruiken:
 *
 * attributes.dataTaxonomy
 *
 * om automatisch het juiste field te vinden.
 *
 *
 * BELANGRIJK:
 *
 * We maken de combo archive hiermee NIET tot een
 * Search & Filter results query.
 *
 *
 * Als de gebruiker daarna een filter wijzigt,
 * gebruikt Search & Filter zijn gewone Results Link:
 *
 * /vacatures/
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $combo =
            tfsc_get_combo_archive();


        if (
            ! is_array(
                $combo
            )
            ||
            empty(
                $combo
            )
        ) {
            return;
        }


        /**
         * Automatisch bijvoorbeeld:
         *
         * {
         *   "functienaam": "field-service-engineer",
         *   "kennisgebied": "elektrotechniek",
         *   "locatie": "tilburg"
         * }
         */
        $active_values =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                empty(
                    $item[
                        'taxonomy'
                    ]
                )
                ||
                empty(
                    $item[
                        'term'
                    ]
                    ->slug
                )
            ) {
                continue;
            }


            $active_values[
                $item[
                    'taxonomy'
                ]
            ] =
                $item[
                    'term'
                ]
                ->slug;
        }


        if (
            empty(
                $active_values
            )
        ) {
            return;
        }

        ?>

        <script>
        (function () {

            const TFSC_COMBO_VALUES =
                <?php
                echo wp_json_encode(
                    $active_values
                );
                ?>;


            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            let tfscApplying =
                false;


            let tfscInitialSyncDone =
                false;


            /**
             * =================================================
             * S&F FIELDS OPHALEN
             * =================================================
             */

            function tfscGetSearchFilterFields() {

                const fieldsApi =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.fields;


                if (
                    ! fieldsApi
                    ||
                    typeof fieldsApi.getAll
                    !== 'function'
                ) {
                    return [];
                }


                let fields =
                    fieldsApi.getAll();


                /**
                 * Map → Array.
                 */
                if (
                    fields instanceof Map
                ) {

                    fields =
                        Array.from(
                            fields.values()
                        );
                }


                /**
                 * Object → Array.
                 */
                else if (
                    fields
                    &&
                    ! Array.isArray(
                        fields
                    )
                    &&
                    typeof fields
                    === 'object'
                ) {

                    fields =
                        Object.values(
                            fields
                        );
                }


                return Array.isArray(
                    fields
                )
                    ?
                fields
                    :
                [];
            }


            /**
             * =================================================
             * COMBO VALUES → S&F FIELD STATE
             * =================================================
             */

            function tfscSyncComboValues() {

                if (
                    tfscApplying
                    ||
                    tfscInitialSyncDone
                ) {
                    return;
                }


                const fields =
                    tfscGetSearchFilterFields();


                if (
                    ! fields.length
                ) {
                    return;
                }


                tfscApplying =
                    true;


                let matchedFields =
                    0;


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getAttributes
                                !== 'function'
                            ||
                            typeof field.getValues
                                !== 'function'
                            ||
                            typeof field.setValues
                                !== 'function'
                        ) {
                            return;
                        }


                        const attributes =
                            field.getAttributes();


                        if (
                            ! attributes
                        ) {
                            return;
                        }


                        /**
                         * Alleen fields van S&F Query #1.
                         *
                         * Hierdoor beïnvloeden we geen
                         * eventuele andere Search & Filter
                         * queries op de site.
                         */
                        if (
                            String(
                                attributes.queryId
                            )
                            !==
                            String(
                                TFSC_QUERY_ID
                            )
                        ) {
                            return;
                        }


                        /**
                         * Alleen taxonomy-fields.
                         */
                        if (
                            attributes.dataType
                            !==
                            'taxonomy'
                        ) {
                            return;
                        }


                        const taxonomy =
                            attributes.dataTaxonomy;


                        if (
                            ! taxonomy
                            ||
                            ! Object.prototype
                                .hasOwnProperty
                                .call(
                                    TFSC_COMBO_VALUES,
                                    taxonomy
                                )
                        ) {
                            return;
                        }


                        const wantedValue =
                            TFSC_COMBO_VALUES[
                                taxonomy
                            ];


                        let currentValues =
                            field.getValues();


                        if (
                            ! Array.isArray(
                                currentValues
                            )
                        ) {

                            currentValues =
                                [];
                        }


                        matchedFields++;


                        /**
                         * Staat al correct actief.
                         */
                        if (
                            currentValues.includes(
                                wantedValue
                            )
                        ) {
                            return;
                        }


                        /**
                         * De Search & Filter frontend API
                         * gebruiken om het field actief
                         * te zetten.
                         */
                        field.setValues(
                            [
                                wantedValue
                            ]
                        );
                    }
                );


                tfscApplying =
                    false;


                /**
                 * Als de relevante fields gevonden zijn,
                 * niet later opnieuw de oorspronkelijke
                 * combo-waarden over gebruikerskeuzes zetten.
                 */
                if (
                    matchedFields > 0
                ) {

                    tfscInitialSyncDone =
                        true;
                }
            }


            /**
             * =================================================
             * S&F MOUNT
             * =================================================
             */

            document.addEventListener(
                'search-filter/mount',
                function () {

                    setTimeout(
                        tfscSyncComboValues,
                        0
                    );


                    setTimeout(
                        tfscSyncComboValues,
                        100
                    );
                }
            );


            /**
             * =================================================
             * FALLBACK
             * =================================================
             *
             * Voor het geval Search & Filter al gemount
             * is voordat onze footer-code draait.
             */

            function tfscStartComboSync() {

                setTimeout(
                    tfscSyncComboValues,
                    50
                );


                setTimeout(
                    tfscSyncComboValues,
                    250
                );


                setTimeout(
                    tfscSyncComboValues,
                    750
                );


                setTimeout(
                    tfscSyncComboValues,
                    1500
                );
            }


            if (
                document.readyState
                === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartComboSync
                );

            } else {

                tfscStartComboSync();
            }

        })();
        </script>

        <?php
    },
    100
);


