 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed(
    $taxonomy
) {

    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    /**
     * Alleen publiek bevraagbare taxonomies.
     */
    if (
        ! $tax_object->publicly_queryable
    ) {
        return false;
    }


    /**
     * Alleen taxonomies gekoppeld aan vacature.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. ALLE TOEGESTANE TAXONOMIES
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed =
        [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * 4. GENERIEKE REWRITE
 * ============================================================
 *
 * Alles achter:
 *
 * /vacatures/
 *
 * wordt opgeslagen in:
 *
 * tfsc_combo_path
 */

add_action(
    'init',
    function() {

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )
            .
            '/(.+?)/?$',

            'index.php'
            .
            '?tfsc_combo_archive=1'
            .
            '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * 5. IS COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (
        (bool)
        get_query_var(
            'tfsc_combo_archive'
        )
    );
}


/**
 * ============================================================
 * 6. TERMPAD VALIDEREN
 * ============================================================
 *
 * Ondersteunt:
 *
 * tilburg
 *
 * noord-brabant/tilburg
 *
 * nederland/noord-brabant/tilburg
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    if (
        ! is_array(
            $segments
        )
        ||
        empty(
            $segments
        )
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        empty(
            $segments
        )
    ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     *
     * exact één termsegment.
     */
    if (
        ! $tax_object->hierarchical
        &&
        count(
            $segments
        ) !== 1
    ) {
        return false;
    }


    $resolved_terms =
        [];


    $parent_id =
        0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term
            ||
            is_wp_error(
                $term
            )
        ) {
            return false;
        }


        /**
         * Vanaf niveau 2 moet de huidige term
         * rechtstreeks child zijn van de vorige.
         */
        if (
            $index > 0
            &&
            (int) $term->parent
            !==
            (int) $parent_id
        ) {
            return false;
        }


        $resolved_terms[] =
            $term;


        $parent_id =
            (int)
            $term->term_id;
    }


    return [

        'path' =>
            $resolved_terms,

        /**
         * Diepste term.
         */
        'term' =>
            end(
                $resolved_terms
            ),
    ];
}


/**
 * ============================================================
 * 7. VOLLEDIGE COMBO-URL PARSEN
 * ============================================================
 */

function tfsc_get_combo_archive() {

    static $cache_set =
        false;


    static $cache =
        false;


    if (
        $cache_set
    ) {
        return $cache;
    }


    $cache_set =
        true;


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if (
        ! $raw_path
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string)
                        $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    /**
     * Minimaal:
     *
     * taxonomy/term
     */
    if (
        count(
            $segments
        ) < 2
    ) {
        return false;
    }


    $allowed_taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if (
        empty(
            $allowed_taxonomies
        )
    ) {
        return false;
    }


    $items =
        [];


    $used_taxonomies =
        [];


    $segment_count =
        count(
            $segments
        );


    $index =
        0;


    while (
        $index
        <
        $segment_count
    ) {

        /**
         * Ieder blok begint met
         * een taxonomy slug.
         */
        $taxonomy =
            sanitize_key(
                $segments[
                    $index
                ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed_taxonomies,
                true
            )
        ) {
            return false;
        }


        /**
         * Taxonomy mag niet tweemaal
         * voorkomen.
         */
        if (
            in_array(
                $taxonomy,
                $used_taxonomies,
                true
            )
        ) {
            return false;
        }


        $index++;


        /**
         * Termsegmenten verzamelen totdat
         * de volgende taxonomy begint.
         */
        $term_segments =
            [];


        while (
            $index
            <
            $segment_count
        ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[
                        $index
                    ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed_taxonomies,
                    true
                )
            ) {
                break;
            }


            $term_segments[] =
                $segments[
                    $index
                ];


            $index++;
        }


        /**
         * Taxonomy zonder term is ongeldig.
         */
        if (
            empty(
                $term_segments
            )
        ) {
            return false;
        }


        /**
         * Termpad valideren.
         */
        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if (
            ! $resolved
        ) {
            return false;
        }


        $items[] = [

            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved[
                    'term'
                ],

            'path' =>
                $resolved[
                    'path'
                ],
        ];


        $used_taxonomies[] =
            $taxonomy;
    }


    if (
        empty(
            $items
        )
    ) {
        return false;
    }


    $cache =
        $items;


    return $cache;
}


/**
 * ============================================================
 * 8. WORDPRESS TAX_QUERY BOUWEN
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! $combo
    ) {
        return false;
    }


    $tax_query = [

        'relation' =>
            'AND',
    ];


    foreach (
        $combo
        as $item
    ) {

        $tax_object =
            get_taxonomy(
                $item[
                    'taxonomy'
                ]
            );


        $tax_query[] = [

            'taxonomy' =>
                $item[
                    'taxonomy'
                ],

            'field' =>
                'term_id',

            'terms' => [

                (int)
                $item[
                    'term'
                ]
                ->term_id,
            ],

            'operator' =>
                'IN',

            /**
             * Bij hiërarchische taxonomies:
             *
             * provincie neemt onderliggende
             * steden automatisch mee.
             */
            'include_children' =>
                (
                    $tax_object
                    &&
                    $tax_object
                        ->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/**
 * ============================================================
 * 9. COMBO ARCHIVE MAIN QUERY
 * ============================================================
 *
 * BELANGRIJK:
 *
 * Dit is GEEN S&F results query.
 *
 * Search & Filter wordt hier dus NIET via:
 *
 * search_filter_query_id
 *
 * aan de WordPress main query gekoppeld.
 *
 *
 * Elementor Loop Grid:
 *
 * Source = Current Query
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin()
            ||
            ! $query->is_main_query()
            ||
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $tax_query =
            tfsc_build_combo_tax_query();


        if (
            ! $tax_query
        ) {
            return;
        }


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        $query->set(
            'tax_query',
            $tax_query
        );


        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


/**
 * ============================================================
 * 10. ARCHIVE STATUS
 * ============================================================
 */

add_action(
    'wp',
    function() {

        if (
            ! tfsc_is_combo_archive()
            ||
            ! tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->is_home =
            false;


        $wp_query->is_front_page =
            false;


        $wp_query->is_page =
            false;


        $wp_query->is_single =
            false;


        $wp_query->is_singular =
            false;


        $wp_query->is_search =
            false;


        $wp_query->is_404 =
            false;


        /**
         * Elementor moet deze pagina
         * als archive herkennen.
         */
        $wp_query->is_archive =
            true;
    }
);


/**
 * ============================================================
 * 11. ONGELDIGE COMBO URL → 404
