);


/**
 * ============================================================
 * 12. SEARCH & FILTER COMBO FIELD SYNC
 * ============================================================
 *
 * Onze combo archive is:
 *
 * is_archive = true
 * is_tax     = false
 *
 *
 * Daardoor kan S&F de termen uit de mooie URL
 * niet automatisch inheriten.
 *
 *
 * We synchroniseren daarom:
 *
 * combo taxonomy
 *
 *      ↓
 *
 * S&F field dataTaxonomy
 *
 *
 * Bijvoorbeeld:
 *
 * functienaam → field-service-engineer
 * kennisgebied → elektrotechniek
 * locatie → tilburg
 *
 *
 * Deze code doet GEEN query-submit.
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $combo =
            tfsc_get_combo_archive();


        if (
            ! is_array(
                $combo
            )
            ||
            empty(
                $combo
            )
        ) {
            return;
        }


        $active_values =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                empty(
                    $item[
                        'taxonomy'
                    ]
                )
                ||
                empty(
                    $item[
                        'term'
                    ]
                    ->slug
                )
            ) {
                continue;
            }


            $active_values[
                $item[
                    'taxonomy'
                ]
            ] =
                $item[
                    'term'
                ]
                ->slug;
        }


        if (
            empty(
                $active_values
            )
        ) {
            return;
        }

        ?>

        <script>

        (function () {

            const TFSC_COMBO_VALUES =
                <?php
                echo wp_json_encode(
                    $active_values
                );
                ?>;


            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            let tfscApplying =
                false;


            let tfscInitialSyncDone =
                false;


            /**
             * Deze globale vlag gebruiken we ook
             * voor de redirectcode hieronder.
             *
             * Redirect mag pas reageren nadat
             * de oorspronkelijke combo-values
             * in S&F staan.
             */
            window.TFSC_SF_COMBO_READY =
                false;


            /**
             * ------------------------------------------------
             * FIELDS OPHALEN
             * ------------------------------------------------
             */

            function tfscGetSearchFilterFields() {

                const fieldsApi =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.fields;


                if (
                    ! fieldsApi
                    ||
                    typeof fieldsApi.getAll
                    !== 'function'
                ) {
                    return [];
                }


                let fields =
                    fieldsApi.getAll();


                if (
                    fields instanceof Map
                ) {

                    fields =
                        Array.from(
                            fields.values()
                        );
                }


                else if (
                    fields
                    &&
                    ! Array.isArray(
                        fields
                    )
                    &&
                    typeof fields
                    === 'object'
                ) {

                    fields =
                        Object.values(
                            fields
                        );
                }


                return Array.isArray(
                    fields
                )
                    ?
                fields
                    :
                [];
            }


            /**
             * ------------------------------------------------
             * COMBO → S&F FIELD VALUES
             * ------------------------------------------------
             */

            function tfscSyncComboValues() {

                if (
                    tfscApplying
                    ||
                    tfscInitialSyncDone
                ) {
                    return;
                }


                const fields =
                    tfscGetSearchFilterFields();


                if (
                    ! fields.length
                ) {
                    return;
                }


                tfscApplying =
                    true;


                let matchedFields =
                    0;


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getAttributes
                                !== 'function'
                            ||
                            typeof field.getValues
                                !== 'function'
                            ||
                            typeof field.setValues
                                !== 'function'
                        ) {
                            return;
                        }


                        const attributes =
                            field.getAttributes();


                        if (
                            ! attributes
                        ) {
                            return;
                        }


                        /**
                         * Alleen Query #1.
                         */
                        if (
                            String(
                                attributes.queryId
                            )
                            !==
                            String(
                                TFSC_QUERY_ID
                            )
                        ) {
                            return;
                        }


                        /**
                         * Alleen taxonomy fields.
                         */
                        if (
                            attributes.dataType
                            !==
                            'taxonomy'
                        ) {
                            return;
                        }


                        const taxonomy =
                            attributes.dataTaxonomy;


                        if (
                            ! taxonomy
                            ||
                            ! Object.prototype
                                .hasOwnProperty
                                .call(
                                    TFSC_COMBO_VALUES,
                                    taxonomy
                                )
                        ) {
                            return;
                        }


                        const wantedValue =
                            TFSC_COMBO_VALUES[
                                taxonomy
                            ];


                        let currentValues =
                            field.getValues();


                        if (
                            ! Array.isArray(
                                currentValues
                            )
                        ) {

                            currentValues =
                                [];
                        }


                        matchedFields++;


                        /**
                         * Staat al correct.
                         */
                        if (
                            currentValues.includes(
                                wantedValue
                            )
                        ) {
                            return;
                        }


                        field.setValues(
                            [
                                wantedValue
                            ]
                        );
                    }
                );


                tfscApplying =
                    false;


                if (
                    matchedFields > 0
                ) {

                    tfscInitialSyncDone =
                        true;


                    /**
                     * Vanaf nu mag een echte
                     * gebruikersfilteractie worden
                     * onderschept.
                     */
                    setTimeout(
                        function() {

                            window
                                .TFSC_SF_COMBO_READY =
                                    true;
                        },
                        100
                    );
                }
            }


            /**
             * ------------------------------------------------
             * S&F MOUNT
             * ------------------------------------------------
             */

            document.addEventListener(
                'search-filter/mount',
                function() {

                    setTimeout(
                        tfscSyncComboValues,
                        0
                    );


                    setTimeout(
                        tfscSyncComboValues,
                        100
                    );
                }
            );


            /**
             * ------------------------------------------------
             * FALLBACK
             * ------------------------------------------------
             */

            function tfscStartComboSync() {

                setTimeout(
                    tfscSyncComboValues,
                    50
                );


                setTimeout(
                    tfscSyncComboValues,
                    250
                );


                setTimeout(
                    tfscSyncComboValues,
                    750
                );


                setTimeout(
                    tfscSyncComboValues,
                    1500
                );
            }


            if (
                document.readyState
                === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartComboSync
                );

            } else {

                tfscStartComboSync();
            }

        })();

        </script>

        <?php
    },
    90
);


/**
 * ============================================================
 * 13. SEO LANDING → EERSTE FILTER = HARD PAGE LOAD
 * ============================================================
 *
 * Dit is het belangrijke nieuwe onderdeel.
 *
 *
 * Alleen actief op:
 *
 * 1. virtuele combo archives
 * 2. native taxonomy archives van vacature
 *
 *
 * NIET actief op:
 *
 * /vacatures/
 *
 *
 * Daardoor:
 *
 * LANDING PAGE
 *      ↓
 * eerste wijziging
 *      ↓
 * volledige navigatie naar /vacatures/?...
 *
 *
 * Daarna:
 *
 * /vacatures/?...
 *      ↓
 * verdere filtering
 *      ↓
 * AJAX / Live Search
 *
 *
 * Uit onze debug weten we dat op:
 *
 * get-results/start
 *
 * S&F reeds de NIEUWE field values bevat.
 */

add_action(
    'wp_footer',
    function() {

        $is_tfsc_landing =
            false;


        $is_combo =
            (
                function_exists(
                    'tfsc_is_combo_archive'
                )
                &&
                tfsc_is_combo_archive()
            );


        /**
         * Virtuele combo archive.
         */
        if (
            $is_combo
        ) {

            $is_tfsc_landing =
                true;
        }


        /**
         * Native taxonomy archive.
         *
         * Alleen als die taxonomy gekoppeld
         * is aan vacature.
         */
        elseif (
            is_tax()
        ) {

            $queried_object =
                get_queried_object();


            if (
                $queried_object
                instanceof
                WP_Term
            ) {

                if (
                    tfsc_combo_taxonomy_allowed(
                        $queried_object
                            ->taxonomy
                    )
                ) {

                    $is_tfsc_landing =
                        true;
                }
            }
        }


        /**
         * Op /vacatures/ en overige pagina's:
         *
         * NIETS DOEN.
         *
         * Daar blijft S&F volledig AJAX.
         */
        if (
            ! $is_tfsc_landing
        ) {
            return;
        }

        ?>

        <script>

        (function () {

            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            const TFSC_IS_COMBO =
                <?php
                echo $is_combo
                    ?
                'true'
                    :
                'false';
                ?>;


            let tfscRedirectAttached =
                false;


            let tfscRedirectStarted =
                false;


            /**
             * ------------------------------------------------
             * FIELDS NORMALISEREN
             * ------------------------------------------------
             */

            function tfscNormalizeFields(
                fields
            ) {

                if (
                    ! fields
                ) {
                    return [];
                }


                if (
                    fields instanceof Map
                ) {

                    return Array.from(
                        fields.values()
                    );
                }


                if (
                    Array.isArray(
                        fields
                    )
                ) {

                    return fields;
                }


                if (
                    typeof fields
                    === 'object'
                ) {

                    return Object.values(
                        fields
                    );
                }


                return [];
            }


            /**
             * ------------------------------------------------
             * RESULTATEN-URL BOUWEN
             * ------------------------------------------------
             *
             * Gebruikt rechtstreeks de S&F API:
             *
             * query.getUrl()
             * query.getFields()
             * field.getUrlName()
             * field.getUrlValues()
             * query.getActiveUrlArg()
             */

            function tfscBuildResultsUrl(
                query
            ) {

                if (
                    ! query
                    ||
                    typeof query.getUrl
                        !== 'function'
                    ||
                    typeof query.getFields
                        !== 'function'
                ) {
                    return null;
                }


                const baseUrl =
                    query.getUrl();


                if (
                    ! baseUrl
                ) {
                    return null;
                }


                const fields =
                    tfscNormalizeFields(
                        query.getFields()
                    );


                /**
                 * Bij jou:
                 *
                 * _
                 *
                 * zodat bijvoorbeeld:
                 *
                 * kennisgebied
                 *
                 * wordt:
                 *
                 * _kennisgebied
                 */
                const prefix =
                    window
                        .searchAndFilterData
                        ?.urlPrefix
                    ||
                    '_';


                const parts =
                    [];


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getUrlName
                                !== 'function'
                            ||
                            typeof field.getUrlValues
                                !== 'function'
                        ) {
                            return;
                        }


                        const urlName =
                            field.getUrlName();


                        let values =
                            field.getUrlValues();


                        if (
                            ! urlName
                        ) {
                            return;
                        }


                        /**
                         * Eén enkele waarde eventueel
                         * naar array converteren.
                         */
                        if (
                            values !== null
                            &&
                            values !== undefined
                            &&
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [
                                    values
                                ];
                        }


                        if (
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [];
                        }


                        /**
                         * Lege waarden verwijderen.
                         */
                        values =
                            values.filter(
                                function(
                                    value
                                ) {

                                    return (
                                        value
                                        !== null
                                        &&
                                        value
                                        !== undefined
                                        &&
                                        String(
                                            value
                                        )
                                        !== ''
                                    );
                                }
                            );


                        if (
                            ! values.length
                        ) {
                            return;
                        }


                        /**
                         * Iedere waarde afzonderlijk encoden.
                         *
                         * De komma tussen meerdere waarden
                         * blijft bewust een komma.
                         *
                         * Bijvoorbeeld:
                         *
                         * elektrotechniek,koeltechniek
                         */
                        const encodedValues =
                            values
                                .map(
                                    function(
                                        value
                                    ) {

                                        return encodeURIComponent(
                                            String(
                                                value
                                            )
                                        );
                                    }
                                )
                                .join(
                                    ','
                                );


                        const parameterName =
                            prefix
                            +
                            urlName;


                        parts.push(
                            encodeURIComponent(
                                parameterName
                            )
                            +
                            '='
                            +
                            encodedValues
                        );
                    }
                );


                /**
                 * Search & Filter Query identifier.
                 *
                 * Bij Query #1:
                 *
                 * ~1
                 */
                if (
                    typeof query.getActiveUrlArg
                    === 'function'
                ) {

                    const activeArg =
                        query.getActiveUrlArg();


                    if (
                        activeArg
                    ) {

                        parts.push(
                            encodeURIComponent(
                                activeArg
                            )
                        );
                    }
                }


                /**
                 * Basis URL schoonmaken.
                 */
                const cleanBase =
                    String(
                        baseUrl
                    )
                    .split(
                        '#'
                    )[0]
                    .split(
                        '?'
                    )[0];


                if (
                    ! parts.length
                ) {

                    return cleanBase;
                }


                return (
                    cleanBase
                    +
                    '?'
                    +
                    parts.join(
                        '&'
                    )
                );
            }


            /**
             * ------------------------------------------------
             * REDIRECT AAN QUERY KOPPELEN
             * ------------------------------------------------
             */

            function tfscAttachLandingRedirect() {

                if (
                    tfscRedirectAttached
                ) {
                    return true;
                }


                const queries =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.queries;


                if (
                    ! queries
                    ||
                    typeof queries.get
                        !== 'function'
                ) {
                    return false;
                }


                const query =
                    queries.get(
                        TFSC_QUERY_ID
                    );


                if (
                    ! query
                    ||
                    typeof query.on
                        !== 'function'
                ) {
                    return false;
                }


                tfscRedirectAttached =
                    true;


                query.on(
                    'get-results/start',
                    function() {

                        if (
                            tfscRedirectStarted
                        ) {
                            return;
                        }


                        /**
                         * Combo page:
                         *
                         * eerst wachten tot onze oorspronkelijke
                         * URL-values netjes in S&F zijn gezet.
                         *
                         *
                         * Native taxonomy archive:
                         *
                         * S&F verzorgt inheritance zelf,
                         * dus daar is deze vlag niet nodig.
                         */
                        if (
                            TFSC_IS_COMBO
                            &&
                            window
                                .TFSC_SF_COMBO_READY
                                !==
                                true
                        ) {
                            return;
                        }


                        const targetUrl =
                            tfscBuildResultsUrl(
                                query
                            );


                        if (
                            ! targetUrl
                        ) {
                            return;
                        }


                        tfscRedirectStarted =
                            true;


                        /**
                         * BELANGRIJK:
                         *
                         * Echte browser-navigation.
                         *
                         * Hierdoor doet WordPress opnieuw
                         * een volledige request.
                         *
                         * Elementor krijgt daardoor:
                         *
                         * is_post_type_archive = true
                         *
                         * en laadt de echte /vacatures/
                         * archive-template.
                         */
                        window.location.href =
                            targetUrl;
                    }
                );


                return true;
            }


            /**
             * ------------------------------------------------
             * S&F MOUNT
             * ------------------------------------------------
             */

            document.addEventListener(
                'search-filter/mount',
                function() {

                    /**
                     * Kleine delay zodat S&F eerst volledig
                     * kan initialiseren.
                     */
                    setTimeout(
                        tfscAttachLandingRedirect,
                        150
                    );


                    setTimeout(
                        tfscAttachLandingRedirect,
                        400
                    );
                }
            );


            /**
             * ------------------------------------------------
             * FALLBACK
             * ------------------------------------------------
             */

            function tfscStartLandingRedirect() {

                setTimeout(
                    tfscAttachLandingRedirect,
                    250
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    750
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    1500
                );
            }


            if (
                document.readyState
                === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartLandingRedirect
                );

            } else {

                tfscStartLandingRedirect();
            }

        })();

        </script>

        <?php
    },
    100
);


/**
 * ============================================================
 * 14. ELEMENTOR ARCHIVE CONDITION
