 *
 * Theme Builder:
 *
 * Combined Vacancy Archives
 */

add_action(
    'elementor/theme/register_conditions',
    function(
        $conditions_manager
    ) {

        if (
            ! class_exists(
                '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base'
            )
        ) {
            return;
        }


        if (
            ! class_exists(
                'TFSC_Combined_Vacancy_Archive_Condition'
            )
        ) {

            class
            TFSC_Combined_Vacancy_Archive_Condition

            extends
            \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {


                public static function get_type() {

                    return
                        'archive';
                }


                public static function get_priority() {

                    return
                        40;
                }


                public function get_name() {

                    return
                        'tfsc_combined_vacancy_archive';
                }


                public function get_label() {

                    return
                        'Combined Vacancy Archives';
                }


                public function check(
                    $args
                ) {

                    return (

                        tfsc_is_combo_archive()

                        &&

                        false
                        !==
                        tfsc_get_combo_archive()
                    );
                }
            }
        }


        $archive_condition =
            $conditions_manager
                ->get_condition(
                    'archive'
                );


        if (
            $archive_condition
        ) {

            $archive_condition
                ->register_sub_condition(

                    new
                    TFSC_Combined_Vacancy_Archive_Condition()
                );
        }
    }
);


/**
