add_shortcode(
    'combo_heading',
    function() {

        $combo =
            tfsc_get_combo_archive();


        if (
            ! $combo
        ) {
            return '';
        }


        $function_parts =
            [];


        $other_parts =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                $item[
                    'taxonomy'
                ]
                ===
                'functienaam'
            ) {

                $function_parts[] =
                    $item[
                        'term'
                    ]
                    ->name;

            } else {

                $other_parts[] =
                    $item[
