 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',
                ],
                $atts
            );


        $wanted_taxonomy =
            sanitize_key(
                $atts[
                    'taxonomy'
                ]
            );


        if (
            ! $wanted_taxonomy
        ) {
            return '';
        }


        $combo =
            tfsc_get_combo_archive();


        if (
