 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * branche/machinebouw/
 * sector/industrie/
 * locatie/noord-brabant/tilburg/
 *
 *
 * ============================================================
 * SEARCH & FILTER
 * ============================================================
 *
 * /vacatures/
 *
 * is de ENIGE echte interactieve Search & Filter
 * resultatenpagina.
 *
 *
 * FLOW:
 *
 * SEO landing page
 *      ↓
 * gebruiker wijzigt filter
 *      ↓
 * S&F get-results/start
 *      ↓
 * HARD PAGE LOAD naar:
 *
 * /vacatures/?_...
 *
 *      ↓
 *
 * vanaf /vacatures/
 * werkt Live Search verder gewoon via AJAX.
 *
 *
 * ============================================================
 * BROWSER BACK / BFCACHE
 * ============================================================
 *
 * Als gebruiker vanaf /vacatures/ teruggaat naar een
 * SEO-landingspagina, kan de browser de oude DOM herstellen
 * vanuit de Back/Forward Cache.
 *
 * Daardoor kunnen Elementor en S&F in een half gewijzigde
 * frontend-state terugkomen.
 *
 * Als de browser zo'n landing uit BFCache herstelt:
 *
 * → één echte reload
 *
 * Daardoor krijgt WordPress/Elementor opnieuw de correcte
 * server-side archive context.
 *
 *
 * ============================================================
 * SEARCH & FILTER QUERY
 * ============================================================
 *
 * Query:
 * Vacatures
 *
 * Query ID:
 * 1
 *
 * Location:
 * Archive
 *
 * Archive Type:
 * Post Type
 *
 * Post Type:
 * vacature
 *
 * Include Taxonomy Archives:
 * NONE / UIT
 *
 * Results Link:
 * /vacatures/
 *
 * Live Search:
 * YES / AAN
 *
 * Update URL:
 * YES / AAN
 *
 * Indexer:
 * AAN
 *
 *
 * ============================================================
 * ELEMENTOR
 * ============================================================
 *
 * Combo archive template condition:
 *
 * Combined Vacancy Archives
 *
 *
 * Loop Grid op combo archive:
 *
 * Source = Current Query
 *
 * GEEN custom Elementor Query ID.
 *
 *
 * ============================================================
 * SHORTCODES
 * ============================================================
 *
 * [combo_heading]
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

define(
    'TFSC_COMBO_BASE',
    'vacatures'
);

define(
    'TFSC_VACANCY_POST_TYPE',
    'vacature'
);

define(
    'TFSC_SEARCH_FILTER_QUERY_ID',
    1
);


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed(
    $taxonomy
) {

    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    /**
     * Alleen publiek bevraagbare taxonomies.
     */
    if (
        ! $tax_object->publicly_queryable
    ) {
        return false;
    }


    /**
     * Alleen taxonomies gekoppeld aan vacature.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. ALLE TOEGESTANE TAXONOMIES
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed =
        [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * 4. GENERIEKE REWRITE
 * ============================================================
 *
 * Alles achter:
 *
 * /vacatures/
 *
 * wordt opgeslagen in:
 *
 * tfsc_combo_path
 */

add_action(
    'init',
    function() {

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )
            .
            '/(.+?)/?$',

            'index.php'
            .
            '?tfsc_combo_archive=1'
            .
            '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * 5. IS COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (
        (bool)
        get_query_var(
            'tfsc_combo_archive'
        )
    );
}


/**
 * ============================================================
 * 6. IS TFSC SEO-LANDINGSPAGINA?
 * ============================================================
 *
 * TRUE voor:
 *
 * - geldige virtuele combo archive
 * - native taxonomy archive van een taxonomy
 *   die gekoppeld is aan vacature
 *
 *
 * FALSE voor:
 *
 * - /vacatures/
 * - overige archives/pagina's
 */

function tfsc_is_vacancy_seo_landing() {

    /**
     * Virtuele combo archive.
     */
    if (
        tfsc_is_combo_archive()
        &&
        false
        !==
        tfsc_get_combo_archive()
    ) {
        return true;
    }


    /**
     * Native taxonomy archive.
     */
    if (
        is_tax()
    ) {

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            tfsc_combo_taxonomy_allowed(
                $queried_object->taxonomy
            )
        ) {

            return true;
        }
    }


    return false;
}


/**
 * ============================================================
 * 7. TERMPAD VALIDEREN
 * ============================================================
 *
 * Ondersteunt:
 *
 * tilburg
 *
 * noord-brabant/tilburg
 *
 * nederland/noord-brabant/tilburg
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    if (
        ! is_array(
            $segments
        )
        ||
        empty(
            $segments
        )
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        empty(
            $segments
        )
    ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     *
     * exact één termsegment.
     */
    if (
        ! $tax_object->hierarchical
        &&
        count(
            $segments
        ) !== 1
    ) {
        return false;
    }


    $resolved_terms =
        [];


    $parent_id =
        0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term
            ||
            is_wp_error(
                $term
            )
        ) {
            return false;
        }


        /**
         * Vanaf niveau 2 moet de huidige term
         * rechtstreeks child zijn van de vorige.
         */
        if (
            $index > 0
            &&
            (int) $term->parent
            !==
            (int) $parent_id
        ) {
            return false;
        }


        $resolved_terms[] =
            $term;


        $parent_id =
            (int)
            $term->term_id;
    }


    return [

        'path' =>
            $resolved_terms,

        /**
         * Diepste term.
         */
        'term' =>
            end(
                $resolved_terms
            ),
    ];
}


/**
 * ============================================================
 * 8. VOLLEDIGE COMBO-URL PARSEN
 * ============================================================
 */

function tfsc_get_combo_archive() {

    static $cache_set =
        false;


    static $cache =
        false;


    if (
        $cache_set
    ) {
        return $cache;
    }


    $cache_set =
        true;


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if (
        ! $raw_path
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string)
                        $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    /**
     * Minimaal:
     *
     * taxonomy/term
     */
    if (
        count(
            $segments
        ) < 2
    ) {
        return false;
    }


    $allowed_taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if (
        empty(
            $allowed_taxonomies
        )
    ) {
        return false;
    }


    $items =
        [];


    $used_taxonomies =
        [];


    $segment_count =
        count(
            $segments
        );


    $index =
        0;


    while (
        $index
        <
        $segment_count
    ) {

        /**
         * Ieder blok begint met
         * een taxonomy slug.
         */
        $taxonomy =
            sanitize_key(
                $segments[
                    $index
                ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed_taxonomies,
                true
            )
        ) {
            return false;
        }


        /**
         * Taxonomy mag niet tweemaal
         * voorkomen.
         */
        if (
            in_array(
                $taxonomy,
                $used_taxonomies,
                true
            )
        ) {
            return false;
        }


        $index++;


        /**
         * Termsegmenten verzamelen totdat
         * de volgende taxonomy begint.
         */
        $term_segments =
            [];


        while (
            $index
            <
            $segment_count
        ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[
                        $index
                    ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed_taxonomies,
                    true
                )
            ) {
                break;
            }


            $term_segments[] =
                $segments[
                    $index
                ];


            $index++;
        }


        /**
         * Taxonomy zonder term is ongeldig.
         */
        if (
            empty(
                $term_segments
            )
        ) {
            return false;
        }


        /**
         * Termpad valideren.
         */
        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if (
            ! $resolved
        ) {
            return false;
        }


        $items[] = [

            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved[
                    'term'
                ],

            'path' =>
                $resolved[
                    'path'
                ],
        ];


        $used_taxonomies[] =
            $taxonomy;
    }


    if (
        empty(
            $items
        )
    ) {
        return false;
    }


    $cache =
        $items;


    return $cache;
}


/**
 * ============================================================
 * 9. WORDPRESS TAX_QUERY BOUWEN
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! $combo
    ) {
        return false;
    }


    $tax_query = [

        'relation' =>
            'AND',
    ];


    foreach (
        $combo
        as $item
    ) {

        $tax_object =
            get_taxonomy(
                $item[
                    'taxonomy'
                ]
            );


        $tax_query[] = [

            'taxonomy' =>
                $item[
                    'taxonomy'
                ],

            'field' =>
                'term_id',

            'terms' => [

                (int)
                $item[
                    'term'
                ]
                ->term_id,
            ],

            'operator' =>
                'IN',

            /**
             * Bij hiërarchische taxonomies:
             *
             * provincie neemt onderliggende
             * steden automatisch mee.
             */
            'include_children' =>
                (
                    $tax_object
                    &&
                    $tax_object
                        ->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/**
 * ============================================================
 * 10. COMBO ARCHIVE MAIN QUERY
 * ============================================================
 *
 * BELANGRIJK:
 *
 * Dit is GEEN S&F results query.
 *
 * Search & Filter wordt hier dus NIET via:
 *
 * search_filter_query_id
 *
 * aan de WordPress main query gekoppeld.
 *
 *
 * Elementor Loop Grid:
 *
 * Source = Current Query
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin()
            ||
            ! $query->is_main_query()
            ||
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $tax_query =
            tfsc_build_combo_tax_query();


        if (
            ! $tax_query
        ) {
            return;
        }


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        $query->set(
            'tax_query',
            $tax_query
        );


        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


/**
 * ============================================================
 * 11. ARCHIVE STATUS
 * ============================================================
 */

add_action(
    'wp',
    function() {

        if (
            ! tfsc_is_combo_archive()
            ||
            ! tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->is_home =
            false;


        $wp_query->is_front_page =
            false;


        $wp_query->is_page =
            false;


        $wp_query->is_single =
            false;


        $wp_query->is_singular =
            false;


        $wp_query->is_search =
            false;


        $wp_query->is_404 =
            false;


        /**
         * Elementor moet deze pagina
         * als archive herkennen.
         */
        $wp_query->is_archive =
            true;
    }
);


/**
 * ============================================================
 * 12. ONGELDIGE COMBO URL → 404
 * ============================================================
 */

add_action(
    'template_redirect',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        if (
            tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->set_404();


        status_header(
            404
        );


        nocache_headers();
    }
);


/**
 * ============================================================
 * 13. SEARCH & FILTER COMBO FIELD SYNC
 * ============================================================
 *
 * Onze combo archive is:
 *
 * is_archive = true
 * is_tax     = false
 *
 *
 * Daardoor kan S&F de termen uit de mooie URL
 * niet automatisch inheriten.
 *
 *
 * We synchroniseren daarom:
 *
 * combo taxonomy
 *
 *      ↓
 *
 * S&F field dataTaxonomy
 *
 *
 * Bijvoorbeeld:
 *
 * functienaam → field-service-engineer
 * kennisgebied → elektrotechniek
 * locatie → tilburg
 *
 *
 * Deze code doet GEEN query-submit.
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $combo =
            tfsc_get_combo_archive();


        if (
            ! is_array(
                $combo
            )
            ||
            empty(
                $combo
            )
        ) {
            return;
        }


        $active_values =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                empty(
                    $item[
                        'taxonomy'
                    ]
                )
                ||
                empty(
                    $item[
                        'term'
                    ]
                    ->slug
                )
            ) {
                continue;
            }


            $active_values[
                $item[
                    'taxonomy'
                ]
            ] =
                $item[
                    'term'
                ]
                ->slug;
        }


        if (
            empty(
                $active_values
            )
        ) {
            return;
        }

        ?>

        <script>

        (function () {

            const TFSC_COMBO_VALUES =
                <?php
                echo wp_json_encode(
                    $active_values
                );
                ?>;


            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            let tfscApplying =
                false;


            let tfscInitialSyncDone =
                false;


            /**
             * De redirectcode gebruikt deze vlag.
             *
             * Pas nadat de oorspronkelijke combo-values
             * in S&F staan mag een gebruikersactie
             * worden onderschept.
             */
            window.TFSC_SF_COMBO_READY =
                false;


            /**
             * ------------------------------------------------
             * FIELDS OPHALEN
             * ------------------------------------------------
             */

            function tfscGetSearchFilterFields() {

                const fieldsApi =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.fields;


                if (
                    ! fieldsApi
                    ||
                    typeof fieldsApi.getAll
                    !== 'function'
                ) {
                    return [];
                }


                let fields =
                    fieldsApi.getAll();


                if (
                    fields instanceof Map
                ) {

                    fields =
                        Array.from(
                            fields.values()
                        );
                }


                else if (
                    fields
                    &&
                    ! Array.isArray(
                        fields
                    )
                    &&
                    typeof fields
                    === 'object'
                ) {

                    fields =
                        Object.values(
                            fields
                        );
                }


                return Array.isArray(
                    fields
                )
                    ?
                fields
                    :
                [];
            }


            /**
             * ------------------------------------------------
             * COMBO → S&F FIELD VALUES
             * ------------------------------------------------
             */

            function tfscSyncComboValues() {

                if (
                    tfscApplying
                    ||
                    tfscInitialSyncDone
                ) {
                    return;
                }


                const fields =
                    tfscGetSearchFilterFields();


                if (
                    ! fields.length
                ) {
                    return;
                }


                tfscApplying =
                    true;


                let matchedFields =
                    0;


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getAttributes
                                !== 'function'
                            ||
                            typeof field.getValues
                                !== 'function'
                            ||
                            typeof field.setValues
                                !== 'function'
                        ) {
                            return;
                        }


                        const attributes =
                            field.getAttributes();


                        if (
                            ! attributes
                        ) {
                            return;
                        }


                        /**
                         * Alleen Query #1.
                         */
                        if (
                            String(
                                attributes.queryId
                            )
                            !==
                            String(
                                TFSC_QUERY_ID
                            )
                        ) {
                            return;
                        }


                        /**
                         * Alleen taxonomy fields.
                         */
                        if (
                            attributes.dataType
                            !==
                            'taxonomy'
                        ) {
                            return;
                        }


                        const taxonomy =
                            attributes.dataTaxonomy;


                        if (
                            ! taxonomy
                            ||
                            ! Object.prototype
                                .hasOwnProperty
                                .call(
                                    TFSC_COMBO_VALUES,
                                    taxonomy
                                )
                        ) {
                            return;
                        }


                        const wantedValue =
                            TFSC_COMBO_VALUES[
                                taxonomy
                            ];


                        let currentValues =
                            field.getValues();


                        if (
                            ! Array.isArray(
                                currentValues
                            )
                        ) {

                            currentValues =
                                [];
                        }


                        matchedFields++;


                        /**
                         * Staat al correct.
                         */
                        if (
                            currentValues.includes(
                                wantedValue
                            )
                        ) {
                            return;
                        }


                        field.setValues(
                            [
                                wantedValue
                            ]
                        );
                    }
                );


                tfscApplying =
                    false;


                if (
                    matchedFields > 0
                ) {

                    tfscInitialSyncDone =
                        true;


                    /**
                     * Kleine buffer nadat alle field states
                     * zijn aangepast.
                     */
                    setTimeout(
                        function() {

                            window
                                .TFSC_SF_COMBO_READY =
                                    true;
                        },
                        100
                    );
                }
            }


            /**
             * ------------------------------------------------
             * S&F MOUNT
             * ------------------------------------------------
             */

            document.addEventListener(
                'search-filter/mount',
                function() {

                    setTimeout(
                        tfscSyncComboValues,
                        0
                    );


                    setTimeout(
                        tfscSyncComboValues,
                        100
                    );
                }
            );


            /**
             * ------------------------------------------------
             * FALLBACK
             * ------------------------------------------------
             */

            function tfscStartComboSync() {

                setTimeout(
                    tfscSyncComboValues,
                    50
                );


                setTimeout(
                    tfscSyncComboValues,
                    250
                );


                setTimeout(
                    tfscSyncComboValues,
                    750
                );


                setTimeout(
                    tfscSyncComboValues,
                    1500
                );
            }


            if (
                document.readyState
                === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartComboSync
                );

            } else {

                tfscStartComboSync();
            }

        })();

        </script>

        <?php
    },
    90
);


/**
 * ============================================================
 * 14. SEO LANDING → EERSTE FILTER = HARD PAGE LOAD
 * ============================================================
 *
 * Alleen actief op:
 *
 * - virtuele combo archives
 * - native vacature taxonomy archives
 *
 *
 * NIET actief op:
 *
 * /vacatures/
 *
 *
 * Daardoor:
 *
 * LANDING PAGE
 *      ↓
 * eerste filterwijziging
 *      ↓
 * echte page load naar /vacatures/?...
 *
 *
 * Daarna:
 *
 * /vacatures/?...
 *      ↓
 * verdere filters
 *      ↓
 * AJAX / Live Search
 *
 *
 * Uit debug bevestigd:
 *
 * op get-results/start heeft S&F reeds
 * de NIEUWE filterwaarden.
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_vacancy_seo_landing()
        ) {
            return;
        }


        $is_combo =
            tfsc_is_combo_archive();

        ?>

        <script>

        (function () {

            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            const TFSC_IS_COMBO =
                <?php
                echo $is_combo
                    ?
                'true'
                    :
                'false';
                ?>;


            let tfscRedirectAttached =
                false;


            let tfscRedirectStarted =
                false;


            /**
             * ------------------------------------------------
             * FIELDS NORMALISEREN
             * ------------------------------------------------
             */

            function tfscNormalizeFields(
                fields
            ) {

                if (
                    ! fields
                ) {
                    return [];
                }


                if (
                    fields instanceof Map
                ) {

                    return Array.from(
                        fields.values()
                    );
                }


                if (
                    Array.isArray(
                        fields
                    )
                ) {

                    return fields;
                }


                if (
                    typeof fields
                    === 'object'
                ) {

                    return Object.values(
                        fields
                    );
                }


                return [];
            }


            /**
             * ------------------------------------------------
             * RESULTATEN-URL BOUWEN
             * ------------------------------------------------
             */

            function tfscBuildResultsUrl(
                query
            ) {

                if (
                    ! query
                    ||
                    typeof query.getUrl
                        !== 'function'
                    ||
                    typeof query.getFields
                        !== 'function'
                ) {
                    return null;
                }


                const baseUrl =
                    query.getUrl();


                if (
                    ! baseUrl
                ) {
                    return null;
                }


                const fields =
                    tfscNormalizeFields(
                        query.getFields()
                    );


                const prefix =
                    window
                        .searchAndFilterData
                        ?.urlPrefix
                    ||
                    '_';


                const parts =
                    [];


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getUrlName
                                !== 'function'
                            ||
                            typeof field.getUrlValues
                                !== 'function'
                        ) {
                            return;
                        }


                        const urlName =
                            field.getUrlName();


                        let values =
                            field.getUrlValues();


                        if (
                            ! urlName
                        ) {
                            return;
                        }


                        if (
                            values !== null
                            &&
                            values !== undefined
                            &&
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [
                                    values
                                ];
                        }


                        if (
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [];
                        }


                        values =
                            values.filter(
                                function(
                                    value
                                ) {

                                    return (
                                        value
                                        !== null
                                        &&
                                        value
                                        !== undefined
                                        &&
                                        String(
                                            value
                                        )
                                        !== ''
                                    );
                                }
                            );


                        if (
                            ! values.length
                        ) {
                            return;
                        }


                        /**
                         * Waarden afzonderlijk URL-encoden.
                         *
                         * De komma tussen meerdere waarden
                         * blijft bewust staan.
                         */
                        const encodedValues =
                            values
                                .map(
                                    function(
                                        value
                                    ) {

                                        return encodeURIComponent(
                                            String(
                                                value
                                            )
                                        );
                                    }
                                )
                                .join(
                                    ','
                                );


                        const parameterName =
                            prefix
                            +
                            urlName;


                        parts.push(
                            encodeURIComponent(
                                parameterName
                            )
                            +
                            '='
                            +
                            encodedValues
                        );
                    }
                );


                /**
                 * Bij Query #1:
                 *
                 * ~1
                 */
                if (
                    typeof query.getActiveUrlArg
                    === 'function'
                ) {

                    const activeArg =
                        query.getActiveUrlArg();


                    if (
                        activeArg
                    ) {

                        parts.push(
                            encodeURIComponent(
                                activeArg
                            )
                        );
                    }
                }


                /**
                 * Querystring/hash van base URL verwijderen.
                 */
                const cleanBase =
                    String(
                        baseUrl
                    )
                    .split(
                        '#'
                    )[0]
                    .split(
                        '?'
                    )[0];


                if (
                    ! parts.length
                ) {

                    return cleanBase;
                }


                return (
                    cleanBase
                    +
                    '?'
                    +
                    parts.join(
                        '&'
                    )
                );
            }


            /**
             * ------------------------------------------------
             * REDIRECT AAN S&F QUERY KOPPELEN
             * ------------------------------------------------
             */

            function tfscAttachLandingRedirect() {

                if (
                    tfscRedirectAttached
                ) {
                    return true;
                }


                const queries =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.queries;


                if (
                    ! queries
                    ||
                    typeof queries.get
                        !== 'function'
                ) {
                    return false;
                }


                const query =
                    queries.get(
                        TFSC_QUERY_ID
                    );


                if (
                    ! query
                    ||
                    typeof query.on
                        !== 'function'
                ) {
                    return false;
                }


                tfscRedirectAttached =
                    true;


                query.on(
                    'get-results/start',
                    function() {

                        if (
                            tfscRedirectStarted
                        ) {
                            return;
                        }


                        /**
                         * Op combo-pagina eerst wachten totdat
                         * de waarden uit de mooie URL in de
                         * S&F-fields zijn gezet.
                         */
                        if (
                            TFSC_IS_COMBO
                            &&
                            window
                                .TFSC_SF_COMBO_READY
                                !==
                                true
                        ) {
                            return;
                        }


                        const targetUrl =
                            tfscBuildResultsUrl(
                                query
                            );


                        if (
                            ! targetUrl
                        ) {
                            return;
                        }


                        tfscRedirectStarted =
                            true;


                        /**
                         * ECHTE NAVIGATIE.
                         *
                         * Dus geen AJAX-template-overgang.
                         */
                        window.location.href =
                            targetUrl;
                    }
                );


                return true;
            }


            /**
             * ------------------------------------------------
             * S&F MOUNT
             * ------------------------------------------------
             */

            document.addEventListener(
                'search-filter/mount',
                function() {

                    setTimeout(
                        tfscAttachLandingRedirect,
                        150
                    );


                    setTimeout(
                        tfscAttachLandingRedirect,
                        400
                    );
                }
            );


            /**
             * ------------------------------------------------
             * FALLBACK
             * ------------------------------------------------
             */

            function tfscStartLandingRedirect() {

                setTimeout(
                    tfscAttachLandingRedirect,
                    250
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    750
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    1500
                );
            }


            if (
                document.readyState
                === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartLandingRedirect
                );

            } else {

                tfscStartLandingRedirect();
            }

        })();

        </script>

        <?php
    },
    100
);


/**
 * ============================================================
 * 15. BFCache / BROWSER BACK FIX
 * ============================================================
 *
 * PROBLEEM:
 *
 * combo landing
 *      ↓
 * filter
 *      ↓
 * /vacatures/
 *      ↓
 * browser Back
 *
 *
 * Browsers kunnen dan de vorige pagina direct
 * uit de Back/Forward Cache herstellen.
 *
 * Daarmee wordt NIET opnieuw WordPress geladen.
 *
 * De browser herstelt de oude DOM + oude JS state,
 * inclusief de toestand waarin S&F/Elementor zich
 * vlak vóór de redirect bevonden.
 *
 *
 * OPLOSSING:
 *
 * Als een TFSC SEO-landingspagina met pageshow
 * vanuit BFCache terugkomt:
 *
 * → één echte reload.
 *
 *
 * Op een normale page load:
 *
 * event.persisted = false
 *
 * en gebeurt er dus niets.
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_vacancy_seo_landing()
        ) {
            return;
        }

        ?>

        <script>

        (function () {

            window.addEventListener(
                'pageshow',
                function( event ) {

                    /**
                     * TRUE betekent:
                     *
                     * deze pagina is niet opnieuw geladen,
                     * maar uit de browser BFCache gehaald.
                     */
                    if (
                        event.persisted
                    ) {

                        window.location.reload();
                    }
                }
            );

        })();

        </script>

        <?php
    },
    110
);


