/**
 * ============================================================
 * 13. SEARCH & FILTER COMBO FIELD SYNC
 * ============================================================
 *
 * Onze combo archive is:
 *
 * is_archive = true
 * is_tax     = false
 *
 *
 * Daardoor kan S&F de termen uit de mooie URL
 * niet automatisch inheriten.
 *
 *
 * We synchroniseren daarom:
 *
 * combo taxonomy
 *
 *      ↓
 *
 * S&F field dataTaxonomy
 *
 *
 * Bijvoorbeeld:
 *
 * functienaam → field-service-engineer
 * kennisgebied → elektrotechniek
 * locatie → tilburg
 *
 *
 * Deze code doet GEEN query-submit.
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $combo =
            tfsc_get_combo_archive();


        if (
            ! is_array(
                $combo
            )
            ||
            empty(
                $combo
            )
        ) {
            return;
        }


        $active_values =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                empty(
                    $item[
                        'taxonomy'
                    ]
                )
                ||
                empty(
                    $item[
                        'term'
                    ]
                    ->slug
                )
            ) {
                continue;
            }


            $active_values[
                $item[
                    'taxonomy'
                ]
            ] =
                $item[
                    'term'
                ]
                ->slug;
        }


        if (
            empty(
                $active_values
            )
        ) {
            return;
        }

        ?>

        <script>

        (function () {

            const TFSC_COMBO_VALUES =
                <?php
                echo wp_json_encode(
                    $active_values
                );
                ?>;


            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            let tfscApplying =
                false;


            let tfscInitialSyncDone =
                false;


            /**
             * De redirectcode gebruikt deze vlag.
             *
             * Pas nadat de oorspronkelijke combo-values
             * in S&F staan mag een gebruikersactie
             * worden onderschept.
             */
            window.TFSC_SF_COMBO_READY =
                false;


            /**
             * ------------------------------------------------
             * FIELDS OPHALEN
             * ------------------------------------------------
             */

            function tfscGetSearchFilterFields() {

                const fieldsApi =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.fields;


                if (
                    ! fieldsApi
                    ||
                    typeof fieldsApi.getAll
                    !== 'function'
                ) {
                    return [];
                }


                let fields =
                    fieldsApi.getAll();


                if (
                    fields instanceof Map
                ) {

                    fields =
                        Array.from(
                            fields.values()
                        );
                }


                else if (
                    fields
                    &&
                    ! Array.isArray(
                        fields
                    )
                    &&
                    typeof fields
                    === 'object'
                ) {

                    fields =
                        Object.values(
                            fields
                        );
                }


                return Array.isArray(
                    fields
                )
                    ?
                fields
                    :
                [];
            }


            /**
             * ------------------------------------------------
             * COMBO → S&F FIELD VALUES
             * ------------------------------------------------
             */

            function tfscSyncComboValues() {

                if (
                    tfscApplying
                    ||
                    tfscInitialSyncDone
                ) {
                    return;
                }


                const fields =
                    tfscGetSearchFilterFields();


                if (
                    ! fields.length
                ) {
                    return;
                }


                tfscApplying =
                    true;


                let matchedFields =
                    0;


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getAttributes
                                !== 'function'
                            ||
                            typeof field.getValues
                                !== 'function'
                            ||
                            typeof field.setValues
                                !== 'function'
                        ) {
                            return;
                        }


                        const attributes =
                            field.getAttributes();


                        if (
                            ! attributes
                        ) {
                            return;
                        }


                        /**
                         * Alleen Query #1.
                         */
                        if (
                            String(
                                attributes.queryId
                            )
                            !==
                            String(
                                TFSC_QUERY_ID
                            )
                        ) {
                            return;
                        }


                        /**
                         * Alleen taxonomy fields.
                         */
                        if (
                            attributes.dataType
                            !==
                            'taxonomy'
                        ) {
                            return;
                        }


                        const taxonomy =
                            attributes.dataTaxonomy;


                        if (
                            ! taxonomy
                            ||
                            ! Object.prototype
                                .hasOwnProperty
                                .call(
                                    TFSC_COMBO_VALUES,
                                    taxonomy
                                )
                        ) {
                            return;
                        }


                        const wantedValue =
                            TFSC_COMBO_VALUES[
                                taxonomy
                            ];


                        let currentValues =
                            field.getValues();


                        if (
                            ! Array.isArray(
                                currentValues
                            )
                        ) {

                            currentValues =
                                [];
                        }


                        matchedFields++;


                        /**
                         * Staat al correct.
                         */
                        if (
                            currentValues.includes(
                                wantedValue
                            )
                        ) {
                            return;
                        }


                        field.setValues(
                            [
                                wantedValue
                            ]
                        );
                    }
                );


                tfscApplying =
                    false;


                if (
                    matchedFields > 0
                ) {

                    tfscInitialSyncDone =
                        true;


                    /**
                     * Kleine buffer nadat alle field states
                     * zijn aangepast.
                     */
                    setTimeout(
                        function() {

                            window
                                .TFSC_SF_COMBO_READY =
                                    true;
                        },
                        100
                    );
                }
            }


            /**
             * ------------------------------------------------
             * S&F MOUNT
             * ------------------------------------------------
             */

            document.addEventListener(
                'search-filter/mount',
                function() {

                    setTimeout(
                        tfscSyncComboValues,
                        0
                    );


                    setTimeout(
                        tfscSyncComboValues,
                        100
                    );
                }
            );


            /**
             * ------------------------------------------------
             * FALLBACK
             * ------------------------------------------------
             */

            function tfscStartComboSync() {

                setTimeout(
                    tfscSyncComboValues,
                    50
                );


                setTimeout(
                    tfscSyncComboValues,
                    250
                );


                setTimeout(
                    tfscSyncComboValues,
                    750
                );


                setTimeout(
                    tfscSyncComboValues,
                    1500
                );
            }


            if (
                document.readyState
                === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartComboSync
                );

            } else {

                tfscStartComboSync();
            }

        })();

        </script>

        <?php
    },
    90
);


/**
 * ============================================================
 * 14. SEO LANDING → EERSTE FILTER = HARD PAGE LOAD
 * ============================================================
 *
 * Alleen actief op:
 *
 * - virtuele combo archives
 * - native vacature taxonomy archives
 *
 *
 * NIET actief op:
 *
 * /vacatures/
 *
 *
 * Daardoor:
 *
 * LANDING PAGE
 *      ↓
 * eerste filterwijziging
 *      ↓
 * echte page load naar /vacatures/?...
 *
 *
 * Daarna:
 *
 * /vacatures/?...
 *      ↓
 * verdere filters
 *      ↓
 * AJAX / Live Search
 *
 *
 * Uit debug bevestigd:
 *
 * op get-results/start heeft S&F reeds
 * de NIEUWE filterwaarden.
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_vacancy_seo_landing()
        ) {
            return;
        }


        $is_combo =
            tfsc_is_combo_archive();

        ?>

        <script>

        (function () {

            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            const TFSC_IS_COMBO =
                <?php
                echo $is_combo
                    ?
                'true'
                    :
                'false';
                ?>;


            let tfscRedirectAttached =
                false;


            let tfscRedirectStarted =
                false;


            /**
             * ------------------------------------------------
             * FIELDS NORMALISEREN
             * ------------------------------------------------
             */

            function tfscNormalizeFields(
                fields
            ) {

                if (
                    ! fields
                ) {
                    return [];
                }


                if (
                    fields instanceof Map
                ) {

                    return Array.from(
                        fields.values()
                    );
                }


                if (
                    Array.isArray(
                        fields
                    )
                ) {

                    return fields;
                }


                if (
                    typeof fields
                    === 'object'
                ) {

                    return Object.values(
                        fields
                    );
                }


                return [];
            }


            /**
             * ------------------------------------------------
             * RESULTATEN-URL BOUWEN
             * ------------------------------------------------
             */

            function tfscBuildResultsUrl(
                query
            ) {

                if (
                    ! query
                    ||
                    typeof query.getUrl
                        !== 'function'
                    ||
                    typeof query.getFields
                        !== 'function'
                ) {
                    return null;
                }


                const baseUrl =
                    query.getUrl();


                if (
                    ! baseUrl
                ) {
                    return null;
                }


                const fields =
                    tfscNormalizeFields(
                        query.getFields()
                    );


                const prefix =
                    window
                        .searchAndFilterData
                        ?.urlPrefix
                    ||
                    '_';


                const parts =
                    [];


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getUrlName
                                !== 'function'
                            ||
                            typeof field.getUrlValues
                                !== 'function'
                        ) {
                            return;
                        }


                        const urlName =
                            field.getUrlName();


                        let values =
                            field.getUrlValues();


                        if (
                            ! urlName
                        ) {
                            return;
                        }


                        if (
                            values !== null
                            &&
                            values !== undefined
                            &&
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [
                                    values
                                ];
                        }


                        if (
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [];
                        }


                        values =
                            values.filter(
                                function(
                                    value
                                ) {

                                    return (
                                        value
                                        !== null
                                        &&
                                        value
                                        !== undefined
                                        &&
                                        String(
                                            value
                                        )
                                        !== ''
                                    );
                                }
                            );


                        if (
                            ! values.length
                        ) {
                            return;
                        }


                        /**
                         * Waarden afzonderlijk URL-encoden.
                         *
                         * De komma tussen meerdere waarden
                         * blijft bewust staan.
                         */
                        const encodedValues =
                            values
                                .map(
                                    function(
                                        value
                                    ) {

                                        return encodeURIComponent(
                                            String(
                                                value
                                            )
                                        );
                                    }
                                )
                                .join(
                                    ','
                                );


                        const parameterName =
                            prefix
                            +
                            urlName;


                        parts.push(
                            encodeURIComponent(
                                parameterName
                            )
                            +
                            '='
                            +
                            encodedValues
                        );
                    }
                );


                /**
                 * Bij Query #1:
                 *
                 * ~1
                 */
                if (
                    typeof query.getActiveUrlArg
                    === 'function'
                ) {

                    const activeArg =
                        query.getActiveUrlArg();


                    if (
                        activeArg
                    ) {

                        parts.push(
                            encodeURIComponent(
                                activeArg
                            )
                        );
                    }
                }


                /**
                 * Querystring/hash van base URL verwijderen.
                 */
                const cleanBase =
                    String(
                        baseUrl
                    )
                    .split(
                        '#'
                    )[0]
                    .split(
                        '?'
                    )[0];


                if (
                    ! parts.length
                ) {

                    return cleanBase;
                }


                return (
                    cleanBase
                    +
                    '?'
                    +
                    parts.join(
                        '&'
                    )
                );
            }


            /**
             * ------------------------------------------------
             * REDIRECT AAN S&F QUERY KOPPELEN
             * ------------------------------------------------
             */

            function tfscAttachLandingRedirect() {

                if (
                    tfscRedirectAttached
                ) {
                    return true;
                }


                const queries =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.queries;


                if (
                    ! queries
                    ||
                    typeof queries.get
                        !== 'function'
                ) {
                    return false;
                }


                const query =
                    queries.get(
                        TFSC_QUERY_ID
                    );


                if (
                    ! query
                    ||
                    typeof query.on
                        !== 'function'
                ) {
                    return false;
                }


                tfscRedirectAttached =
                    true;


                query.on(
                    'get-results/start',
                    function() {

                        if (
                            tfscRedirectStarted
                        ) {
                            return;
                        }


                        /**
                         * Op combo-pagina eerst wachten totdat
                         * de waarden uit de mooie URL in de
                         * S&F-fields zijn gezet.
                         */
                        if (
                            TFSC_IS_COMBO
                            &&
                            window
                                .TFSC_SF_COMBO_READY
                                !==
                                true
                        ) {
                            return;
                        }


                        const targetUrl =
                            tfscBuildResultsUrl(
                                query
                            );


                        if (
                            ! targetUrl
                        ) {
                            return;
                        }


                        tfscRedirectStarted =
                            true;


                        /**
                         * ECHTE NAVIGATIE.
                         *
                         * Dus geen AJAX-template-overgang.
                         */
                        window.location.href =
                            targetUrl;
                    }
                );


                return true;
            }


            /**
             * ------------------------------------------------
             * S&F MOUNT
             * ------------------------------------------------
             */

            document.addEventListener(
                'search-filter/mount',
                function() {

                    setTimeout(
                        tfscAttachLandingRedirect,
                        150
                    );


                    setTimeout(
                        tfscAttachLandingRedirect,
                        400
                    );
                }
            );


            /**
             * ------------------------------------------------
             * FALLBACK
             * ------------------------------------------------
             */

            function tfscStartLandingRedirect() {

                setTimeout(
                    tfscAttachLandingRedirect,
                    250
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    750
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    1500
                );
            }


            if (
                document.readyState
                === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartLandingRedirect
                );

            } else {

                tfscStartLandingRedirect();
            }

        })();

        </script>

        <?php
    },
    100
);


/**
 * ============================================================
 * 15. BFCache / BROWSER BACK FIX
 * ============================================================
 *
 * PROBLEEM:
 *
 * combo landing
 *      ↓
 * filter
 *      ↓
 * /vacatures/
 *      ↓
 * browser Back
 *
 *
 * Browsers kunnen dan de vorige pagina direct
 * uit de Back/Forward Cache herstellen.
 *
 * Daarmee wordt NIET opnieuw WordPress geladen.
 *
 * De browser herstelt de oude DOM + oude JS state,
 * inclusief de toestand waarin S&F/Elementor zich
 * vlak vóór de redirect bevonden.
 *
 *
 * OPLOSSING:
 *
 * Als een TFSC SEO-landingspagina met pageshow
 * vanuit BFCache terugkomt:
 *
 * → één echte reload.
 *
 *
 * Op een normale page load:
 *
 * event.persisted = false
 *
 * en gebeurt er dus niets.
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_vacancy_seo_landing()
        ) {
            return;
        }

        ?>

        <script>

        (function () {

            window.addEventListener(
                'pageshow',
                function( event ) {

                    /**
                     * TRUE betekent:
                     *
                     * deze pagina is niet opnieuw geladen,
                     * maar uit de browser BFCache gehaald.
                     */
                    if (
                        event.persisted
                    ) {

                        window.location.reload();
                    }
                }
            );

        })();

        </script>

        <?php
    },
    110
);


