/**
 * ============================================================
 * 17. ARCHIVE / COMBO HEADING
 * ============================================================
 *
 * [combo_heading]
 *
 * Werkt op:
 *
 * - virtuele combo archives
 * - native taxonomy archives
 * - vacature post type archive /vacatures/
 *
 *
 * Voorbeelden:
 *
 * /functienaam/service-engineer/
 * → Service Engineer
 *
 * /kennisgebied/elektrotechniek/
 * → Elektrotechniek
 *
 * /locatie/tilburg/
 * → Tilburg
 *
 * /vacatures/
 * → Vacatures
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/tilburg/
 *
 * → Field Service Engineer - Elektrotechniek - Tilburg
 */

add_shortcode(
    'combo_heading',
    function() {

        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                $function_parts =
                    [];


                $other_parts =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {
                        continue;
                    }


                    if (
                        isset(
                            $item['taxonomy']
                        )
                        &&
                        $item['taxonomy']
                        ===
                        'functienaam'
                    ) {

                        $function_parts[] =
                            $item['term']->name;

                    } else {

                        $other_parts[] =
                            $item['term']->name;
                    }
                }


                $parts =
                    array_merge(
                        $function_parts,
                        $other_parts
                    );


                if (
                    ! empty(
                        $parts
                    )
                ) {

                    return esc_html(
                        implode(
                            ' - ',
                            $parts
                        )
                    );
                }
            }
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
        ) {

            $taxonomy =
                $queried_object->taxonomy;


            if (
                $taxonomy
                &&
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $taxonomy
                )
            ) {

                return esc_html(
                    $queried_object->name
                );
            }
        }


        /**
         * ----------------------------------------------------
         * 3. VACATURE POST TYPE ARCHIVE
         * ----------------------------------------------------
         *
         * /vacatures/
         *
         * → Vacatures
         */

        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {

            return esc_html(
                'Vacatures'
            );
        }


        return '';
    }
);

/**
 * ============================================================
 * 18. SPECIFIEKE ARCHIVE / COMBO TERM
 * ============================================================
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 * [combo_term taxonomy="branche"]
 * [combo_term taxonomy="sector"]
 *
 *
 * Werkt op:
 *
 * - virtuele combo archives
 * - native taxonomy archives
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',
                ],
                $atts,
                'combo_term'
            );


        $wanted_taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );


        if (
            ! $wanted_taxonomy
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        $item['taxonomy']
                        !==
                        $wanted_taxonomy
                    ) {
                        continue;
                    }


                    if (
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {
                        continue;
                    }


                    return esc_html(
                        $item['term']->name
                    );
                }
            }


            return '';
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            $queried_object->taxonomy
            ===
            $wanted_taxonomy
        ) {

            if (
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $queried_object->taxonomy
                )
            ) {

                return esc_html(
                    $queried_object->name
                );
            }
        }


        return '';
    }
);

/**
 * ============================================================
 * COMBO + TAXONOMY DESCRIPTIONS
 * ============================================================
 *
 * Shortcode:
 *
 * [combo_descriptions]
 *
 *
 * WERKT OP:
 *
 * /functienaam/field-service-engineer/
 *
 * /kennisgebied/elektrotechniek/
 *
 * /locatie/tilburg/
 *
 * /vacatures/functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/tilburg/
 *
 *
 * OUTPUT:
 *
 * Alle relevante term descriptions achter elkaar.
 *
 * Lege descriptions worden overgeslagen.
 * Shortcodes binnen descriptions worden uitgevoerd.
 * ============================================================
 */

add_shortcode(
    'combo_descriptions',
    function() {

        $descriptions = [];


        /*
         * ====================================================
         * 1. COMBO ARCHIVE
         * ====================================================
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
            ) {

                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {
                        continue;
                    }


                    $term =
                        $item['term'];


                    $description =
                        term_description(
                            $term->term_id,
                            $term->taxonomy
                        );


                    $description =
                        trim(
                            $description
                        );


                    if (
                        $description === ''
                    ) {
                        continue;
                    }


                    $descriptions[] =
                        do_shortcode(
                            $description
                        );
                }
            }


            return implode(
                "\n\n",
                $descriptions
            );
        }


        /*
         * ====================================================
         * 2. NORMAAL TAXONOMY ARCHIVE
         * ====================================================
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
        ) {

            /*
             * Alleen taxonomies die geldig zijn
             * voor onze vacature-architectuur.
             */
            if (
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                ! tfsc_combo_taxonomy_allowed(
                    $queried_object->taxonomy
                )
            ) {
                return '';
            }


            $description =
                term_description(
                    $queried_object->term_id,
                    $queried_object->taxonomy
                );


            $description =
                trim(
                    $description
                );


            if (
                $description === ''
            ) {
                return '';
            }


            return do_shortcode(
                $description
            );
        }


        /*
         * ====================================================
         * 3. GEEN GELDIG ARCHIVE
         * ====================================================
         */

        return '';
    }
);

/**
 * ============================================================
 * TFSC - RELATED ARCHIVES
 * ============================================================
 *
 * Vereist:
 * De actieve snippet:
 *
 * "Make Automatic Archives & combo with Vacature plus Taxonomies"
 *
 * Deze snippet gebruikt onder andere:
 *
 * - TFSC_COMBO_BASE
 * - TFSC_VACANCY_POST_TYPE
 * - tfsc_is_combo_archive()
 * - tfsc_get_combo_archive()
 * - tfsc_combo_taxonomy_allowed()
 * - tfsc_get_allowed_combo_taxonomies()
 *
 *
 * ============================================================
 * GEBRUIK
 * ============================================================
 *
 * Voorbeeld:
 *
 * [related_archives
 *     taxonomy="kennisgebied"
 *     title="Kennisgebieden"
 *     limit="8"
 * ]
 *
 *
 * Andere voorbeelden:
 *
 * [related_archives taxonomy="functieinhoud" title="Functie-inhoud"]
 *
 * [related_archives taxonomy="branche" title="Branches" limit="10"]
 *
 * [related_archives taxonomy="locatie" title="Locaties" limit="12"]
 *
 *
 * ============================================================
 * OPTIES
 * ============================================================
 *
 * taxonomy
 * Verplicht.
 *
 * Voorbeeld:
 * taxonomy="kennisgebied"
 *
 *
 * title
 * Titel boven het blok.
 *
 * Laat leeg om geen titel vanuit de shortcode te tonen:
 *
 * title=""
 *
 *
 * limit
 * Maximaal aantal links.
 *
 * 0 = onbeperkt.
 *
 * Standaard:
 * 10
 *
 *
 * orderby
 *
 * name
 * = alfabetisch
 *
 * count
 * = meeste vacatures eerst
 *
 * Standaard:
 * name
 *
 *
 * order
 *
 * ASC
 * DESC
 *
 * Standaard:
 * ASC
 *
 *
 * show_count
 *
 * yes
 * no
 *
 * Voorbeeld:
 *
 * show_count="yes"
 *
 * Resultaat:
 *
 * Elektrotechniek (4)
 *
 *
 * ============================================================
 * VOORBEELD WERKING
 * ============================================================
 *
 * Huidige pagina:
 *
 * Commissioning Engineer
 *
 * Shortcode:
 *
 * [related_archives taxonomy="kennisgebied"]
 *
 * Mogelijk resultaat:
 *
 * Elektrotechniek
 * Mechanica
 * Mechatronica
 *
 *
 * De links gaan dan bijvoorbeeld naar:
 *
 * /vacatures/
 * functienaam/commissioning-engineer/
 * kennisgebied/elektrotechniek/
 *
 *
 * Alleen combinaties waar daadwerkelijk gepubliceerde
 * vacatures onder vallen worden weergegeven.
 *
 *
 * ============================================================
 * ELEMENTOR
 * ============================================================
 *
 * Plaats de shortcode in een Elementor Shortcode-widget.
 *
 * Voor twee kolommen zoals:
 *
 * Kennisgebieden       Functie-inhoud
 *
 * maak je in Elementor twee containers naast elkaar en
 * plaats je in iedere container een eigen shortcode.
 *
 *
 * HTML classes voor styling:
 *
 * .tfsc-related-archives
 * .tfsc-related-title
 * .tfsc-related-list
 * .tfsc-related-item
 * .tfsc-related-link
 * .tfsc-related-name
 * .tfsc-related-count
 * .tfsc-related-arrow
 *
 * ============================================================
 */


/**
 * ============================================================
 * 1. HUIDIGE ARCHIVE CONTEXT OPHALEN
 * ============================================================
 *
 * Geeft de actieve taxonomy/term combinaties terug.
 *
 * Werkt voor:
 *
 * - virtuele combo archives
 * - native taxonomy archives
 * - /vacatures/
 */
function tfsc_related_get_current_items() {

    $items = [];


    /**
     * --------------------------------------------------------
     * COMBO ARCHIVE
     * --------------------------------------------------------
     */
    if (
        function_exists( 'tfsc_is_combo_archive' )
        &&
        tfsc_is_combo_archive()
        &&
        function_exists( 'tfsc_get_combo_archive' )
    ) {

        $combo =
            tfsc_get_combo_archive();


        if (
            is_array( $combo )
            &&
            ! empty( $combo )
        ) {

            foreach ( $combo as $item ) {

                if (
                    empty( $item['taxonomy'] )
                    ||
                    empty( $item['term'] )
                    ||
                    ! ( $item['term'] instanceof WP_Term )
                ) {
                    continue;
                }


                $items[] = [
                    'taxonomy' =>
                        $item['taxonomy'],

                    'term' =>
                        $item['term'],
                ];
            }
        }


        return $items;
    }


    /**
     * --------------------------------------------------------
     * NATIVE TAXONOMY ARCHIVE
     * --------------------------------------------------------
     */
    if ( is_tax() ) {

        $term =
            get_queried_object();


        if (
            $term instanceof WP_Term
            &&
            function_exists(
                'tfsc_combo_taxonomy_allowed'
            )
            &&
            tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {

            $items[] = [
                'taxonomy' =>
                    $term->taxonomy,

                'term' =>
                    $term,
            ];
        }
    }


    return $items;
}


/**
 * ============================================================
 * 2. CANONIEKE VOLGORDE TAXONOMIES
 * ============================================================
 *
 * Zorgt ervoor dat dezelfde combinatie altijd in dezelfde
 * taxonomy-volgorde wordt opgebouwd.
 *
 * functienaam komt altijd eerst.
 */
function tfsc_related_get_taxonomy_order() {

    if (
        ! function_exists(
            'tfsc_get_allowed_combo_taxonomies'
        )
    ) {
        return [];
    }


    $taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if (
        ! is_array( $taxonomies )
    ) {
        return [];
    }


    /**
     * functienaam altijd vooraan.
     */
    $taxonomies =
        array_values(
            array_diff(
                $taxonomies,
                [ 'functienaam' ]
            )
        );


    array_unshift(
        $taxonomies,
        'functienaam'
    );


    return array_values(
        array_unique(
            $taxonomies
        )
    );
}


/**
 * ============================================================
 * 3. ITEMS SORTEREN OP TAXONOMY-VOLGORDE
 * ============================================================
 */
function tfsc_related_sort_items(
    $items
) {

    $order =
        tfsc_related_get_taxonomy_order();


    usort(
        $items,
        function(
            $a,
            $b
        ) use (
            $order
        ) {

            $a_position =
                array_search(
                    $a['taxonomy'],
                    $order,
                    true
                );


            $b_position =
                array_search(
                    $b['taxonomy'],
                    $order,
                    true
                );


            if (
                false === $a_position
            ) {
                $a_position = 9999;
            }


            if (
                false === $b_position
            ) {
                $b_position = 9999;
            }


            return
                $a_position
                <=>
                $b_position;
        }
    );


    return $items;
}


/**
 * ============================================================
 * 4. VOLLEDIG TERMPAD MAKEN
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * Tilburg
 *
 * binnen:
 *
 * Nederland
 *   Noord-Brabant
 *     Tilburg
 *
 * wordt:
 *
 * nederland/noord-brabant/tilburg
 */
function tfsc_related_get_term_path(
    $term
) {

    if (
        ! (
            $term instanceof WP_Term
        )
    ) {
        return '';
    }


    $taxonomy_object =
        get_taxonomy(
            $term->taxonomy
        );


    if (
        ! $taxonomy_object
        ||
        ! $taxonomy_object->hierarchical
    ) {

        return
            $term->slug;
    }


    $ancestor_ids =
        get_ancestors(
            $term->term_id,
            $term->taxonomy,
            'taxonomy'
        );


    $ancestor_ids =
        array_reverse(
            $ancestor_ids
        );


    $slugs = [];


    foreach (
        $ancestor_ids
        as $ancestor_id
    ) {

        $ancestor =
            get_term(
                $ancestor_id,
                $term->taxonomy
            );


        if (
            $ancestor
            &&
            ! is_wp_error(
                $ancestor
            )
        ) {

            $slugs[] =
                $ancestor->slug;
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        $slugs
    );
}


/**
 * ============================================================
 * 5. ARCHIVE URL BOUWEN
 * ============================================================
 *
 * Eén taxonomy:
 *
 * gebruikt native WordPress term URL.
 *
 *
 * Meerdere taxonomies:
 *
 * gebruikt TFSC combo URL.
 */
function tfsc_related_build_archive_url(
    $items
) {

    if (
        empty( $items )
    ) {
        return '';
    }


    $items =
        tfsc_related_sort_items(
            $items
        );


    /**
     * --------------------------------------------------------
     * ÉÉN ITEM → NATIVE TAXONOMY URL
     * --------------------------------------------------------
     */
    if (
        count( $items ) === 1
    ) {

        $url =
            get_term_link(
                $items[0]['term']
            );


        if (
            is_wp_error( $url )
        ) {
            return '';
        }


        return $url;
    }


    /**
     * --------------------------------------------------------
     * MEERDERE ITEMS → COMBO URL
     * --------------------------------------------------------
     */
    if (
        ! defined(
            'TFSC_COMBO_BASE'
        )
    ) {
        return '';
    }


    $segments = [];


    foreach (
        $items
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['term']
            )
            ||
            ! (
                $item['term']
                instanceof
                WP_Term
            )
        ) {
            continue;
        }


        $term_path =
            tfsc_related_get_term_path(
                $item['term']
            );


        if (
            ! $term_path
        ) {
            continue;
        }


        $segments[] =
            sanitize_key(
                $item['taxonomy']
            );


        foreach (
            explode(
                '/',
                $term_path
            )
            as $slug
        ) {

            $segments[] =
                sanitize_title(
                    $slug
                );
        }
    }


    if (
        empty( $segments )
    ) {
        return '';
    }


    return
        home_url(
            '/'
            .
            trim(
                TFSC_COMBO_BASE,
                '/'
            )
            .
            '/'
            .
            implode(
                '/',
                $segments
            )
            .
            '/'
        );
}


/**
 * ============================================================
 * 6. TAX_QUERY VOOR BESTAANDE CONTEXT
 * ============================================================
 *
 * De taxonomy waarvoor related links worden gezocht wordt
 * uit de huidige context verwijderd.
 *
 * Daardoor kan dezelfde shortcode ook worden gebruikt om
 * alternatieven te tonen.
 *
 * Bijvoorbeeld:
 *
 * huidige pagina:
 *
 * Commissioning Engineer + Elektrotechniek
 *
 * taxonomy="kennisgebied"
 *
 * Dan kunnen ook:
 *
 * Mechanica
 * Mechatronica
 *
 * worden aangeboden.
 */
function tfsc_related_build_base_tax_query(
    $current_items,
    $target_taxonomy
) {

    $tax_query = [
        'relation' => 'AND',
    ];


    foreach (
        $current_items
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['term']
            )
            ||
            ! (
                $item['term']
                instanceof
                WP_Term
            )
        ) {
            continue;
        }


        /**
         * Target taxonomy verwijderen.
         *
         * Die wordt later vervangen door de kandidaat-term.
         */
        if (
            $item['taxonomy']
            ===
            $target_taxonomy
        ) {
            continue;
        }


        $taxonomy_object =
            get_taxonomy(
                $item['taxonomy']
            );


        $tax_query[] = [

            'taxonomy' =>
                $item['taxonomy'],

            'field' =>
                'term_id',

            'terms' => [
                (int)
                $item['term']->term_id,
            ],

            'operator' =>
                'IN',

            'include_children' =>
                (
                    $taxonomy_object
                    &&
                    $taxonomy_object
                        ->hierarchical
                ),
        ];
    }


    /**
     * Alleen relation aanwezig?
     *
     * Dan is er feitelijk geen tax_query nodig.
     */
    if (
        count( $tax_query ) === 1
    ) {
        return [];
    }


    return $tax_query;
}


/**
 * ============================================================
 * 7. VACATURE-AANTALLEN PER RELATED TERM BEREKENEN
 * ============================================================
 *
 * We halen eerst alle vacatures binnen de bestaande context
 * op en tellen daarna welke termen van de target taxonomy
 * daarin voorkomen.
 *
 * Voor hiërarchische taxonomies telt een vacature onder een
 * child-term ook mee voor de parent.
 */
function tfsc_related_get_term_counts(
    $taxonomy,
    $current_items
) {

    if (
        ! defined(
            'TFSC_VACANCY_POST_TYPE'
        )
    ) {
        return [];
    }


    $base_tax_query =
        tfsc_related_build_base_tax_query(
            $current_items,
            $taxonomy
        );


    $query_args = [

        'post_type' =>
            TFSC_VACANCY_POST_TYPE,

        'post_status' =>
            'publish',

        'posts_per_page' =>
            -1,

        'fields' =>
            'ids',

        'no_found_rows' =>
            true,

        'ignore_sticky_posts' =>
            true,
    ];


    if (
        ! empty(
            $base_tax_query
        )
    ) {

        $query_args['tax_query'] =
            $base_tax_query;
    }


    $post_ids =
        get_posts(
            $query_args
        );


    if (
        empty( $post_ids )
    ) {
        return [];
    }


    $relationships =
        wp_get_object_terms(
            $post_ids,
            $taxonomy
        );


    if (
        is_wp_error(
            $relationships
        )
        ||
        empty(
            $relationships
        )
    ) {
        return [];
    }


    $taxonomy_object =
        get_taxonomy(
            $taxonomy
        );


    $counts = [];


    /**
     * Per vacature bijhouden welke termen al geteld zijn.
     *
     * Hiermee voorkomen we dubbeltellingen wanneer een vacature
     * meerdere child-termen onder dezelfde parent heeft.
     */
    $seen_per_post = [];


    foreach (
        $relationships
        as $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            continue;
        }


        /**
         * wp_get_object_terms() levert bij meerdere objecten
         * normaal gesproken object_id mee.
         */
        $object_id =
            isset(
                $term->object_id
            )
                ?
            (int)
            $term->object_id
                :
            0;


        if (
            ! $object_id
        ) {
            continue;
        }


        $term_ids = [
            (int)
            $term->term_id,
        ];


        /**
         * Parents ook meetellen.
         */
        if (
            $taxonomy_object
            &&
            $taxonomy_object
                ->hierarchical
        ) {

            $ancestors =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            foreach (
                $ancestors
                as $ancestor_id
            ) {

                $term_ids[] =
                    (int)
                    $ancestor_id;
            }
        }


        $term_ids =
            array_unique(
                $term_ids
            );


        foreach (
            $term_ids
            as $term_id
        ) {

            if (
                isset(
                    $seen_per_post[
                        $object_id
                    ][
                        $term_id
                    ]
                )
            ) {
                continue;
            }


            $seen_per_post[
                $object_id
            ][
                $term_id
            ] =
                true;


            if (
                ! isset(
                    $counts[
                        $term_id
                    ]
                )
            ) {

                $counts[
                    $term_id
                ] =
                    0;
            }


            $counts[
                $term_id
            ]++;
        }
    }


    return $counts;
}


/**
 * ============================================================
 * 8. SHORTCODE
 * ============================================================
 *
 * [related_archives taxonomy="kennisgebied"]
 */
add_shortcode(
    'related_archives',
    function(
        $atts
    ) {

        $atts =
            shortcode_atts(
                [

                    'taxonomy' =>
                        '',

                    'title' =>
                        '',

                    'limit' =>
                        10,

                    'orderby' =>
                        'name',

                    'order' =>
                        'ASC',

                    'show_count' =>
                        'no',

                ],
                $atts,
                'related_archives'
            );


        /**
         * ----------------------------------------------------
         * TAXONOMY
         * ----------------------------------------------------
         */
        $taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );


        if (
            ! $taxonomy
            ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        if (
            function_exists(
                'tfsc_combo_taxonomy_allowed'
            )
            &&
            ! tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * INSTELLINGEN
         * ----------------------------------------------------
         */
        $limit =
            max(
                0,
                (int)
                $atts['limit']
            );


        $orderby =
            strtolower(
                sanitize_key(
                    $atts['orderby']
                )
            );


        if (
            ! in_array(
                $orderby,
                [
                    'name',
                    'count',
                ],
                true
            )
        ) {

            $orderby =
                'name';
        }


        $order =
            strtoupper(
                sanitize_key(
                    $atts['order']
                )
            );


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {

            $order =
                'ASC';
        }


        $show_count =
            strtolower(
                (string)
                $atts['show_count']
            )
            ===
            'yes';


        /**
         * ----------------------------------------------------
         * HUIDIGE CONTEXT
         * ----------------------------------------------------
         */
        $current_items =
            tfsc_related_get_current_items();


        /**
         * Huidige term van target taxonomy onthouden.
         */
        $current_target_term_id =
            0;


        foreach (
            $current_items
            as $item
        ) {

            if (
                $item['taxonomy']
                ===
                $taxonomy
            ) {

                $current_target_term_id =
                    (int)
                    $item['term']->term_id;

                break;
            }
        }


        /**
         * ----------------------------------------------------
         * TERM COUNTS
         * ----------------------------------------------------
         */
        $counts =
            tfsc_related_get_term_counts(
                $taxonomy,
                $current_items
            );


        if (
            empty(
                $counts
            )
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * TERM OBJECTEN OPHALEN
         * ----------------------------------------------------
         */
        $term_ids =
            array_keys(
                $counts
            );


        $terms =
            get_terms(
                [
                    'taxonomy' =>
                        $taxonomy,

                    'include' =>
                        $term_ids,

                    'hide_empty' =>
                        false,
                ]
            );


        if (
            is_wp_error(
                $terms
            )
            ||
            empty(
                $terms
            )
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * HUIDIGE TERM VERWIJDEREN
         * ----------------------------------------------------
         */
        $terms =
            array_values(
                array_filter(
                    $terms,
                    function(
                        $term
                    ) use (
                        $current_target_term_id
                    ) {

                        return (
                            ! $current_target_term_id
                            ||
                            (int)
                            $term->term_id
                            !==
                            $current_target_term_id
                        );
                    }
                )
            );


        if (
            empty(
                $terms
            )
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * SORTEREN
         * ----------------------------------------------------
         */
        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $counts,
                $orderby,
                $order
            ) {

                if (
                    $orderby
                    ===
                    'count'
                ) {

                    $a_value =
                        isset(
                            $counts[
                                $a->term_id
                            ]
                        )
                            ?
                        (int)
                        $counts[
                            $a->term_id
                        ]
                            :
                        0;


                    $b_value =
                        isset(
                            $counts[
                                $b->term_id
                            ]
                        )
                            ?
                        (int)
                        $counts[
                            $b->term_id
                        ]
                            :
                        0;


                    $comparison =
                        $a_value
                        <=>
                        $b_value;

                } else {

                    $comparison =
                        strcasecmp(
                            $a->name,
                            $b->name
                        );
                }


                if (
                    $order
                    ===
                    'DESC'
                ) {

                    $comparison *= -1;
                }


                return $comparison;
            }
        );


        /**
         * ----------------------------------------------------
         * LIMIT
         * ----------------------------------------------------
         */
        if (
            $limit > 0
        ) {

            $terms =
                array_slice(
                    $terms,
                    0,
                    $limit
                );
        }


        /**
         * ----------------------------------------------------
         * HTML OPBOUWEN
         * ----------------------------------------------------
         */
        $html =
            '<div class="tfsc-related-archives">';


        if (
            trim(
                $atts['title']
            )
            !== ''
        ) {

            $html .=
                '<h3 class="tfsc-related-title">'
                .
                esc_html(
                    $atts['title']
                )
                .
                '</h3>';
        }


        $html .=
            '<div class="tfsc-related-list">';


        foreach (
            $terms
            as $term
        ) {

            /**
             * Bestaande context kopiëren,
             * maar target taxonomy verwijderen.
             */
            $new_items = [];


            foreach (
                $current_items
                as $item
            ) {

                if (
                    $item['taxonomy']
                    ===
                    $taxonomy
                ) {
                    continue;
                }


                $new_items[] =
                    $item;
            }


            /**
             * Nieuwe related term toevoegen.
             */
            $new_items[] = [

                'taxonomy' =>
                    $taxonomy,

                'term' =>
                    $term,
            ];


            $url =
                tfsc_related_build_archive_url(
                    $new_items
                );


            if (
                ! $url
            ) {
                continue;
            }


            $count =
                isset(
                    $counts[
                        $term->term_id
                    ]
                )
                    ?
                (int)
                $counts[
                    $term->term_id
                ]
                    :
                0;


            /**
             * Geen vacatures = nooit tonen.
             */
            if (
                $count < 1
            ) {
                continue;
            }


            $html .=
                '<div class="tfsc-related-item">';


            $html .=
                '<a class="tfsc-related-link" href="'
                .
                esc_url(
                    $url
                )
                .
                '">';


            $html .=
                '<span class="tfsc-related-name">'
                .
                esc_html(
                    $term->name
                )
                .
                '</span>';


            if (
                $show_count
            ) {

                $html .=
                    '<span class="tfsc-related-count">'
                    .
                    esc_html(
                        $count
                    )
                    .
                    '</span>';
            }


            $html .=
                '<span class="tfsc-related-arrow" aria-hidden="true">'
                .
                '&#8250;'
                .
                '</span>';


            $html .=
                '</a>';


            $html .=
                '</div>';
        }


        $html .=
            '</div>';


        $html .=
            '</div>';


        return $html;
    }
);

/**
 * ============================================================
 * COMBO + TAXONOMY DESCRIPTIONS
 * ============================================================
 *
 * Shortcode:
 *
 * [combo_descriptions]
 *
 *
 * WERKT OP:
 *
 * /functienaam/field-service-engineer/
 *
 * /kennisgebied/elektrotechniek/
 *
 * /locatie/tilburg/
 *
 * /vacatures/functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/tilburg/
 *
 *
 * OUTPUT:
 *
 * Alle relevante term descriptions achter elkaar.
 *
 * Lege descriptions worden overgeslagen.
 * Shortcodes binnen descriptions worden uitgevoerd.
 * ============================================================
 */

add_shortcode(
    'combo_descriptions',
    function() {

        $descriptions = [];


        /*
         * ====================================================
         * 1. COMBO ARCHIVE
         * ====================================================
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
            ) {

                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {
                        continue;
                    }


                    $term =
                        $item['term'];


                    $description =
                        term_description(
                            $term->term_id,
                            $term->taxonomy
                        );


                    $description =
                        trim(
                            $description
                        );


                    if (
                        $description === ''
                    ) {
                        continue;
                    }


                    $descriptions[] =
                        do_shortcode(
                            $description
                        );
                }
            }


            return implode(
                "\n\n",
                $descriptions
            );
        }


        /*
         * ====================================================
         * 2. NORMAAL TAXONOMY ARCHIVE
         * ====================================================
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
        ) {

            /*
             * Alleen taxonomies die geldig zijn
             * voor onze vacature-architectuur.
             */
            if (
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                ! tfsc_combo_taxonomy_allowed(
                    $queried_object->taxonomy
                )
            ) {
                return '';
            }


            $description =
                term_description(
                    $queried_object->term_id,
                    $queried_object->taxonomy
                );


            $description =
                trim(
                    $description
                );


            if (
                $description === ''
            ) {
                return '';
            }


            return do_shortcode(
                $description
            );
        }


        /*
         * ====================================================
         * 3. GEEN GELDIG ARCHIVE
         * ====================================================
         */

        return '';
    }
);

