/**
 * ============================================================
 * 17. ARCHIVE / COMBO HEADING
 * ============================================================
 *
 * [combo_heading]
 *
 *
 * COMBO MET FUNCTIENAAM:
 *
 * Field Service Engineer vacatures
 * | Elektrotechniek
 * | Noord-Brabant
 * | 5 dagen internationaal
 * | Europa
 * | Machinebouw
 *
 *
 * COMBO ZONDER FUNCTIENAAM:
 *
 * Vacatures
 * | Elektrotechniek
 * | Noord-Brabant
 * | Machinebouw
 *
 *
 * NATIVE TAXONOMY:
 *
 * /functienaam/field-service-engineer/
 * → Field Service Engineer vacatures
 *
 * /kennisgebied/elektrotechniek/
 * → Elektrotechniek vacatures
 *
 * /locatie/noord-brabant/
 * → Noord-Brabant vacatures
 *
 *
 * POST TYPE ARCHIVE:
 *
 * /vacatures/
 * → Vacatures
 *
 *
 * NIEUWE TAXONOMIES:
 *
 * Worden automatisch meegenomen.
 * Er hoeft daarvoor niets aan deze shortcode
 * aangepast te worden.
 */

add_shortcode(
    'combo_heading',
    function() {

        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                $function_name =
                    '';


                $other_parts =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {
                        continue;
                    }


                    $taxonomy =
                        $item['taxonomy'];


                    $term_name =
                        trim(
                            $item['term']->name
                        );


                    if (
                        $term_name === ''
                    ) {
                        continue;
                    }


                    /**
                     * Functienaam altijd vooraan.
                     */
                    if (
                        $taxonomy
                        ===
                        'functienaam'
                    ) {

                        $function_name =
                            $term_name;


                        continue;
                    }


                    /**
                     * Alle overige taxonomies
                     * automatisch meenemen.
                     *
                     * Volgorde =
                     * volgorde waarin ze in
                     * de combo URL staan.
                     */
                    $other_parts[] =
                        $term_name;
                }


                $parts =
                    [];


                /**
                 * Met functienaam:
                 *
                 * Field Service Engineer vacatures
                 */
                if (
                    $function_name !== ''
                ) {

                    $parts[] =
                        $function_name
                        .
                        ' vacatures';

                } else {

                    /**
                     * Geen functienaam aanwezig:
                     *
                     * Vacatures | ...
                     */
                    $parts[] =
                        'Vacatures';
                }


                /**
                 * Overige actieve taxonomies.
                 */
                foreach (
                    $other_parts
                    as $part
                ) {

                    $parts[] =
                        $part;
                }


                return esc_html(
                    implode(
                        '  • ',
                        $parts
                    )
                );
            }
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
        ) {

            $taxonomy =
                $queried_object->taxonomy;


            if (
                $taxonomy
                &&
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $taxonomy
                )
            ) {

                $term_name =
                    trim(
                        $queried_object->name
                    );


                if (
                    $term_name === ''
                ) {
                    return '';
                }


                return esc_html(
                    $term_name
                    .
                    ' vacatures'
                );
            }
        }


        /**
         * ----------------------------------------------------
         * 3. VACATURE POST TYPE ARCHIVE
         * ----------------------------------------------------
         *
         * /vacatures/
         *
         * → Vacatures
         */

        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {

            return esc_html(
                'Vacatures'
            );
        }


        return '';
    }
);

/**
 * ============================================================
 * 18. SPECIFIEKE ARCHIVE / COMBO TERM
 * ============================================================
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 * [combo_term taxonomy="branche"]
 * [combo_term taxonomy="sector"]
 *
 *
 * Werkt op:
 *
 * - virtuele combo archives
 * - native taxonomy archives
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',
                ],
                $atts,
                'combo_term'
            );


        $wanted_taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );


        if (
            ! $wanted_taxonomy
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        $item['taxonomy']
                        !==
                        $wanted_taxonomy
                    ) {
                        continue;
                    }


                    if (
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {
                        continue;
                    }


                    return esc_html(
                        $item['term']->name
                    );
                }
            }


            return '';
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            $queried_object->taxonomy
            ===
            $wanted_taxonomy
        ) {

            if (
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $queried_object->taxonomy
                )
            ) {

                return esc_html(
                    $queried_object->name
                );
            }
        }


        return '';
    }
);

/**
 * ============================================================
 * TFSC - VOLLEDIG DYNAMISCHE VACATURE ARCHIEVEN
 * + SEARCH & FILTER PRO V3
 * ============================================================
 *
 * ONBEPERKT AANTAL TAXONOMIES.
 * ONBEPERKT AANTAL TERMEN PER TAXONOMY.
 *
 *
 * ============================================================
 * ARCHITECTUUR
 * ============================================================
 *
 * NATIVE TAXONOMY:
 *
 * /functienaam/service-engineer/
 *
 *
 * VIRTUELE COMBO:
 *
 * /vacatures/functienaam/field-service-engineer/
 *
 *
 * MEERDERE TAXONOMIES:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/noord-brabant/
 *
 *
 * MEERDERE TERMEN BINNEN DEZELFDE TAXONOMY:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * kennisgebied/mechanisch/
 * locatie/noord-brabant/
 * locatie/zuid-holland/
 *
 *
 * HIËRARCHISCHE TAXONOMY BLIJFT WERKEN:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * locatie/noord-brabant/tilburg/
 * locatie/zuid-holland/rotterdam/
 *
 *
 * ============================================================
 * TAXONOMY MATCHING
 * ============================================================
 *
 * Verschillende taxonomies:
 *
 * AND
 *
 *
 * Meerdere termen binnen één taxonomy:
 *
 * standaard OR
 *
 *
 * Uitzondering:
 *
 * kennisgebied = AND
 *
 * omdat Search & Filter daar ook
 * multipleMatchMethod = all gebruikt.
 *
 *
 * ============================================================
 * SEARCH & FILTER
 * ============================================================
 *
 * /vacatures/
 *
 * is de ENIGE echte interactieve Search & Filter
 * resultatenpagina.
 *
 *
 * FLOW:
 *
 * SEO landing page
 *      ↓
 * gebruiker wijzigt filter
 *      ↓
 * S&F get-results/start
 *      ↓
 * HARD PAGE LOAD naar:
 *
 * /vacatures/?_...
 *
 *      ↓
 *
 * vanaf /vacatures/
 * werkt Live Search verder via AJAX.
 *
 *
 * ============================================================
 * SHORTCODES
 * ============================================================
 *
 * [combo_heading]
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 *
 * Bij meerdere waarden:
 *
 * [combo_term taxonomy="kennisgebied"]
 *
 * →
 *
 * Elektrotechniek • Mechanisch
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

define(
    'TFSC_COMBO_BASE',
    'vacatures'
);

define(
    'TFSC_VACANCY_POST_TYPE',
    'vacature'
);

define(
    'TFSC_SEARCH_FILTER_QUERY_ID',
    1
);


/**
 * ============================================================
 * TAXONOMY MATCH METHOD
 * ============================================================
 *
 * Standaard:
 *
 * OR
 *
 * Dus bijvoorbeeld:
 *
 * locatie Noord-Brabant
 * OF
 * locatie Zuid-Holland
 *
 *
 * Taxonomies die ALLE geselecteerde termen
 * moeten bevatten kunnen hieronder op AND.
 *
 * Momenteel:
 *
 * kennisgebied = AND
 */

function tfsc_get_combo_taxonomy_match_method(
    $taxonomy
) {

    $methods = [

        'kennisgebied' =>
            'AND',
    ];


    if (
        isset(
            $methods[
                $taxonomy
            ]
        )
    ) {

        return
            $methods[
                $taxonomy
            ];
    }


    return 'OR';
}


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed(
    $taxonomy
) {

    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    /**
     * Alleen publiek bevraagbare taxonomies.
     */
    if (
        ! $tax_object
            ->publicly_queryable
    ) {
        return false;
    }


    /**
     * Alleen taxonomies gekoppeld aan vacature.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. ALLE TOEGESTANE TAXONOMIES
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed =
        [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * 4. GENERIEKE REWRITE
 * ============================================================
 */

add_action(
    'init',
    function() {

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )
            .
            '/(.+?)/?$',

            'index.php'
            .
            '?tfsc_combo_archive=1'
            .
            '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * 5. IS COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (
        (bool)
        get_query_var(
            'tfsc_combo_archive'
        )
    );
}


/**
 * ============================================================
 * 6. IS TFSC SEO-LANDINGSPAGINA?
 * ============================================================
 */

function tfsc_is_vacancy_seo_landing() {

    /**
     * Virtuele combo.
     */
    if (
        tfsc_is_combo_archive()
        &&
        false
        !==
        tfsc_get_combo_archive()
    ) {

        return true;
    }


    /**
     * Native taxonomy.
     */
    if (
        is_tax()
    ) {

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            tfsc_combo_taxonomy_allowed(
                $queried_object->taxonomy
            )
        ) {

            return true;
        }
    }


    return false;
}


/**
 * ============================================================
 * 7. TERMPAD VALIDEREN
 * ============================================================
 *
 * Ondersteunt:
 *
 * tilburg
 *
 * noord-brabant/tilburg
 *
 * nederland/noord-brabant/tilburg
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    if (
        ! is_array(
            $segments
        )
        ||
        empty(
            $segments
        )
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        empty(
            $segments
        )
    ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     *
     * exact één termsegment.
     */
    if (
        ! $tax_object->hierarchical
        &&
        count(
            $segments
        )
        !==
        1
    ) {

        return false;
    }


    $resolved_terms =
        [];


    $parent_id =
        0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term
            ||
            is_wp_error(
                $term
            )
        ) {

            return false;
        }


        /**
         * Vanaf niveau 2 moet term
         * rechtstreeks child zijn
         * van vorige term.
         */
        if (
            $index > 0
            &&
            (int)
            $term->parent
            !==
            (int)
            $parent_id
        ) {

            return false;
        }


        $resolved_terms[] =
            $term;


        $parent_id =
            (int)
            $term->term_id;
    }


    return [

        'path' =>
            $resolved_terms,

        /**
         * Diepste term.
         */
        'term' =>
            end(
                $resolved_terms
            ),
    ];
}


/**
 * ============================================================
 * 8. VOLLEDIGE COMBO-URL PARSEN
 * ============================================================
 *
 * BELANGRIJK:
 *
 * Dezelfde taxonomy mag nu meerdere keren
 * voorkomen.
 *
 *
 * Bijvoorbeeld:
 *
 * kennisgebied/elektrotechniek/
 * kennisgebied/mechanisch/
 *
 *
 * of:
 *
 * locatie/noord-brabant/tilburg/
 * locatie/zuid-holland/rotterdam/
 */

function tfsc_get_combo_archive() {

    static $cache_set =
        false;


    static $cache =
        false;


    if (
        $cache_set
    ) {

        return $cache;
    }


    $cache_set =
        true;


    if (
        ! tfsc_is_combo_archive()
    ) {

        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if (
        ! $raw_path
    ) {

        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string)
                        $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    /**
     * Minimaal:
     *
     * taxonomy/term
     */
    if (
        count(
            $segments
        )
        <
        2
    ) {

        return false;
    }


    $allowed_taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if (
        empty(
            $allowed_taxonomies
        )
    ) {

        return false;
    }


    $items =
        [];


    $segment_count =
        count(
            $segments
        );


    $index =
        0;


    while (
        $index
        <
        $segment_count
    ) {

        /**
         * Ieder blok begint met taxonomy.
         */
        $taxonomy =
            sanitize_key(
                $segments[
                    $index
                ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed_taxonomies,
                true
            )
        ) {

            return false;
        }


        $index++;


        /**
         * Termsegmenten verzamelen totdat
         * volgende taxonomy begint.
         */
        $term_segments =
            [];


        while (
            $index
            <
            $segment_count
        ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[
                        $index
                    ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed_taxonomies,
                    true
                )
            ) {

                break;
            }


            $term_segments[] =
                $segments[
                    $index
                ];


            $index++;
        }


        /**
         * Taxonomy zonder term is ongeldig.
         */
        if (
            empty(
                $term_segments
            )
        ) {

            return false;
        }


        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if (
            ! $resolved
        ) {

            return false;
        }


        /**
         * IEDER taxonomy/term blok blijft
         * een afzonderlijk item.
         *
         * Daardoor blijven bestaande
         * descriptions/shortcodes compatibel.
         */
        $items[] = [

            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved[
                    'term'
                ],

            'path' =>
                $resolved[
                    'path'
                ],
        ];
    }


    if (
        empty(
            $items
        )
    ) {

        return false;
    }


    $cache =
        $items;


    return $cache;
}


/**
 * ============================================================
 * 9. WORDPRESS TAX_QUERY BOUWEN
 * ============================================================
 *
 * Verschillende taxonomies:
 *
 * AND
 *
 *
 * Binnen dezelfde taxonomy:
 *
 * standaard OR
 *
 *
 * kennisgebied:
 *
 * AND
 */

function tfsc_build_combo_tax_query() {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! $combo
    ) {

        return false;
    }


    /**
     * Eerst alle geselecteerde termen
     * groeperen per taxonomy.
     */
    $grouped =
        [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['term']
            )
            ||
            ! (
                $item['term']
                instanceof
                WP_Term
            )
        ) {

            continue;
        }


        $taxonomy =
            $item['taxonomy'];


        if (
            ! isset(
                $grouped[
                    $taxonomy
                ]
            )
        ) {

            $grouped[
                $taxonomy
            ] =
                [];
        }


        $term_id =
            (int)
            $item['term']
                ->term_id;


        if (
            ! in_array(
                $term_id,
                $grouped[
                    $taxonomy
                ],
                true
            )
        ) {

            $grouped[
                $taxonomy
            ][] =
                $term_id;
        }
    }


    if (
        empty(
            $grouped
        )
    ) {

        return false;
    }


    $tax_query = [

        'relation' =>
            'AND',
    ];


    foreach (
        $grouped
        as $taxonomy => $term_ids
    ) {

        if (
            empty(
                $term_ids
            )
        ) {

            continue;
        }


        $tax_object =
            get_taxonomy(
                $taxonomy
            );


        $match_method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        /**
         * AND:
         *
         * vacature moet ALLE termen hebben.
         *
         * Bijvoorbeeld:
         *
         * Elektrotechniek
         * EN
         * Mechanisch
         */
        if (
            $match_method
            ===
            'AND'
            &&
            count(
                $term_ids
            )
            >
            1
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    $term_ids,

                'operator' =>
                    'AND',

                /**
                 * AND + child-expansie kan bij
                 * hiërarchische taxonomies
                 * ongewenste logica veroorzaken.
                 */
                'include_children' =>
                    false,
            ];


            continue;
        }


        /**
         * OR:
         *
         * vacature mag één van de termen hebben.
         *
         * Bijvoorbeeld:
         *
         * Noord-Brabant
         * OF
         * Zuid-Holland
         */
        $tax_query[] = [

            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            'operator' =>
                'IN',

            /**
             * Provincie neemt steden mee.
             */
            'include_children' =>
                (
                    $tax_object
                    &&
                    $tax_object
                        ->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/**
 * ============================================================
 * 10. COMBO ARCHIVE MAIN QUERY
 * ============================================================
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin()
            ||
            ! $query->is_main_query()
            ||
            ! tfsc_is_combo_archive()
        ) {

            return;
        }


        $tax_query =
            tfsc_build_combo_tax_query();


        if (
            ! $tax_query
        ) {

            return;
        }


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        $query->set(
            'tax_query',
            $tax_query
        );


        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


