/**
 * ============================================================
 * 17. ARCHIVE / COMBO HEADING
 * ============================================================
 *
 * [combo_heading]
 *
 *
 * ÉÉN FUNCTIENAAM:
 *
 * Field Service Engineer vacatures
 * • Elektrotechniek
 * • Mechanisch
 * • Noord-Brabant
 *
 *
 * MEERDERE FUNCTIENAMEN:
 *
 * Vacatures
 * • Field Service Engineer
 * • Commissioning Engineer
 * • Elektrotechniek
 *
 *
 * GEEN FUNCTIENAAM:
 *
 * Vacatures
 * • Elektrotechniek
 * • Noord-Brabant
 */

add_shortcode(
    'combo_heading',
    function() {

        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                $function_names =
                    [];


                $other_parts =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {

                        continue;
                    }


                    $taxonomy =
                        $item['taxonomy'];


                    $term_name =
                        trim(
                            $item['term']->name
                        );


                    if (
                        $term_name === ''
                    ) {

                        continue;
                    }


                    if (
                        $taxonomy
                        ===
                        'functienaam'
                    ) {

                        if (
                            ! in_array(
                                $term_name,
                                $function_names,
                                true
                            )
                        ) {

                            $function_names[] =
                                $term_name;
                        }


                        continue;
                    }


                    if (
                        ! in_array(
                            $term_name,
                            $other_parts,
                            true
                        )
                    ) {

                        $other_parts[] =
                            $term_name;
                    }
                }


                $parts =
                    [];


                /**
                 * Eén functienaam:
                 *
                 * Field Service Engineer vacatures
                 */
                if (
                    count(
                        $function_names
                    )
                    ===
                    1
                ) {

                    $parts[] =
                        $function_names[0]
                        .
                        ' vacatures';
                }


                /**
                 * Meerdere functienamen:
                 *
                 * Vacatures
                 * • Field Service Engineer
                 * • Commissioning Engineer
                 */
                elseif (
                    count(
                        $function_names
                    )
                    >
                    1
                ) {

                    $parts[] =
                        'Vacatures';


                    foreach (
                        $function_names
                        as $function_name
                    ) {

                        $parts[] =
                            $function_name;
                    }
                }


                /**
                 * Geen functienaam.
                 */
                else {

                    $parts[] =
                        'Vacatures';
                }


                foreach (
                    $other_parts
                    as $part
                ) {

                    $parts[] =
                        $part;
                }


                return esc_html(
                    implode(
                        ' • ',
                        $parts
                    )
                );
            }
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
        ) {

            $taxonomy =
                $queried_object
                    ->taxonomy;


            if (
                $taxonomy
                &&
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $taxonomy
                )
            ) {

                $term_name =
                    trim(
                        $queried_object
                            ->name
                    );


                if (
                    $term_name
                    ===
                    ''
                ) {

                    return '';
                }


                return esc_html(
                    $term_name
                    .
                    ' vacatures'
                );
            }
        }


        /**
         * ----------------------------------------------------
         * 3. VACATURE POST TYPE ARCHIVE
         * ----------------------------------------------------
         */

        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {

            return esc_html(
                'Vacatures'
            );
        }


        return '';
    }
);


/**
 * ============================================================
 * 18. SPECIFIEKE ARCHIVE / COMBO TERM
 * ============================================================
 *
 * [combo_term taxonomy="kennisgebied"]
 *
 * Eén waarde:
 *
 * Elektrotechniek
 *
 *
 * Meerdere waarden:
 *
 * Elektrotechniek • Mechanisch
 *
 *
 * Andere separator:
 *
 * [combo_term
 * taxonomy="kennisgebied"
 * separator=", "]
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',

                    'separator' =>
                        ' • ',
                ],
                $atts,
                'combo_term'
            );


        $wanted_taxonomy =
            sanitize_key(
                $atts[
                    'taxonomy'
                ]
            );


        if (
            ! $wanted_taxonomy
        ) {

            return '';
        }


        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                $names =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        $item['taxonomy']
                        !==
                        $wanted_taxonomy
                    ) {

                        continue;
                    }


                    if (
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {

                        continue;
                    }


                    $name =
                        trim(
                            $item['term']->name
                        );


                    if (
                        $name === ''
                    ) {

                        continue;
                    }


                    if (
                        ! in_array(
                            $name,
                            $names,
                            true
                        )
                    ) {

                        $names[] =
                            $name;
                    }
                }


                if (
                    empty(
                        $names
                    )
                ) {

                    return '';
                }


                return esc_html(
                    implode(
                        (string)
                        $atts[
                            'separator'
                        ],
                        $names
                    )
                );
            }


            return '';
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            $queried_object
                ->taxonomy
            ===
            $wanted_taxonomy
        ) {

            if (
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $queried_object
                        ->taxonomy
                )
            ) {

                return esc_html(
                    $queried_object
                        ->name
                );
            }
        }


        return '';
    }
);

/**
 * ============================================================
 * TFSC - VOLLEDIG DYNAMISCHE VACATURE ARCHIEVEN
 * + SEARCH & FILTER PRO V3
 * ============================================================
 *
 * ONBEPERKT AANTAL TAXONOMIES.
 * ONBEPERKT AANTAL TERMEN PER TAXONOMY.
 *
 *
 * ============================================================
 * ARCHITECTUUR
 * ============================================================
 *
 * NATIVE TAXONOMY:
 *
 * /functienaam/service-engineer/
 *
 *
 * VIRTUELE COMBO:
 *
 * /vacatures/functienaam/field-service-engineer/
 *
 *
 * MEERDERE TAXONOMIES:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/noord-brabant/
 *
 *
 * MEERDERE TERMEN BINNEN DEZELFDE TAXONOMY:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * kennisgebied/mechanisch/
 * locatie/noord-brabant/
 * locatie/zuid-holland/
 *
 *
 * HIËRARCHISCHE TAXONOMY BLIJFT WERKEN:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * locatie/noord-brabant/tilburg/
 * locatie/zuid-holland/rotterdam/
 *
 *
 * ============================================================
 * TAXONOMY MATCHING
 * ============================================================
 *
 * Verschillende taxonomies:
 *
 * AND
 *
 *
 * Meerdere termen binnen één taxonomy:
 *
 * standaard OR
 *
 *
 * Uitzondering:
 *
 * kennisgebied = AND
 *
 * omdat Search & Filter daar ook
 * multipleMatchMethod = all gebruikt.
 *
 *
 * ============================================================
 * SEARCH & FILTER
 * ============================================================
 *
 * /vacatures/
 *
 * is de ENIGE echte interactieve Search & Filter
 * resultatenpagina.
 *
 *
 * FLOW:
 *
 * SEO landing page
 *      ↓
 * gebruiker wijzigt filter
 *      ↓
 * S&F get-results/start
 *      ↓
 * HARD PAGE LOAD naar:
 *
 * /vacatures/?_...
 *
 *      ↓
 *
 * vanaf /vacatures/
 * werkt Live Search verder via AJAX.
 *
 *
 * ============================================================
 * SHORTCODES
 * ============================================================
 *
 * [combo_heading]
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 *
 * Bij meerdere waarden:
 *
 * [combo_term taxonomy="kennisgebied"]
 *
 * →
 *
 * Elektrotechniek • Mechanisch
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

define(
    'TFSC_COMBO_BASE',
    'vacatures'
);

define(
    'TFSC_VACANCY_POST_TYPE',
    'vacature'
);

define(
    'TFSC_SEARCH_FILTER_QUERY_ID',
    1
);


/**
 * ============================================================
 * TAXONOMY MATCH METHOD
 * ============================================================
 *
 * Standaard:
 *
 * OR
 *
 * Dus bijvoorbeeld:
 *
 * locatie Noord-Brabant
 * OF
 * locatie Zuid-Holland
 *
 *
 * Taxonomies die ALLE geselecteerde termen
 * moeten bevatten kunnen hieronder op AND.
 *
 * Momenteel:
 *
 * kennisgebied = AND
 */

function tfsc_get_combo_taxonomy_match_method(
    $taxonomy
) {

    $methods = [

        'kennisgebied' =>
            'AND',
    ];


    if (
        isset(
            $methods[
                $taxonomy
            ]
        )
    ) {

        return
            $methods[
                $taxonomy
            ];
    }


    return 'OR';
}


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed(
    $taxonomy
) {

    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    /**
     * Alleen publiek bevraagbare taxonomies.
     */
    if (
        ! $tax_object
            ->publicly_queryable
    ) {
        return false;
    }


    /**
     * Alleen taxonomies gekoppeld aan vacature.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. ALLE TOEGESTANE TAXONOMIES
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed =
        [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


