/**
 * ============================================================
 * 6. IS TFSC SEO-LANDINGSPAGINA?
 * ============================================================
 */

function tfsc_is_vacancy_seo_landing() {

    /**
     * Virtuele combo.
     */
    if (
        tfsc_is_combo_archive()
        &&
        false
        !==
        tfsc_get_combo_archive()
    ) {

        return true;
    }


    /**
     * Native taxonomy.
     */
    if (
        is_tax()
    ) {

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            tfsc_combo_taxonomy_allowed(
                $queried_object->taxonomy
            )
        ) {

            return true;
        }
    }


    return false;
}


/**
 * ============================================================
 * 7. TERMPAD VALIDEREN
 * ============================================================
 *
 * Ondersteunt:
 *
 * tilburg
 *
 * noord-brabant/tilburg
 *
 * nederland/noord-brabant/tilburg
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {
        return false;
    }


    if (
        ! is_array(
            $segments
        )
        ||
        empty(
            $segments
        )
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        empty(
            $segments
        )
    ) {
        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     *
     * exact één termsegment.
     */
    if (
        ! $tax_object->hierarchical
        &&
        count(
            $segments
        )
        !==
        1
    ) {

        return false;
    }


    $resolved_terms =
        [];


    $parent_id =
        0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term
            ||
            is_wp_error(
                $term
            )
        ) {

            return false;
        }


        /**
         * Vanaf niveau 2 moet term
         * rechtstreeks child zijn
         * van vorige term.
         */
        if (
            $index > 0
            &&
            (int)
            $term->parent
            !==
            (int)
            $parent_id
        ) {

            return false;
        }


        $resolved_terms[] =
            $term;


        $parent_id =
            (int)
            $term->term_id;
    }


    return [

        'path' =>
            $resolved_terms,

        /**
         * Diepste term.
         */
        'term' =>
            end(
                $resolved_terms
            ),
    ];
}


/**
 * ============================================================
 * 8. VOLLEDIGE COMBO-URL PARSEN
 * ============================================================
 *
 * BELANGRIJK:
 *
 * Dezelfde taxonomy mag nu meerdere keren
 * voorkomen.
 *
 *
 * Bijvoorbeeld:
 *
 * kennisgebied/elektrotechniek/
 * kennisgebied/mechanisch/
 *
 *
 * of:
 *
 * locatie/noord-brabant/tilburg/
 * locatie/zuid-holland/rotterdam/
 */

function tfsc_get_combo_archive() {

    static $cache_set =
        false;


    static $cache =
        false;


    if (
        $cache_set
    ) {

        return $cache;
    }


    $cache_set =
        true;


    if (
        ! tfsc_is_combo_archive()
    ) {

        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if (
        ! $raw_path
    ) {

        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string)
                        $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    /**
     * Minimaal:
     *
     * taxonomy/term
     */
    if (
        count(
            $segments
        )
        <
        2
    ) {

        return false;
    }


    $allowed_taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if (
        empty(
            $allowed_taxonomies
        )
    ) {

        return false;
    }


    $items =
        [];


    $segment_count =
        count(
            $segments
        );


    $index =
        0;


    while (
        $index
        <
        $segment_count
    ) {

        /**
         * Ieder blok begint met taxonomy.
         */
        $taxonomy =
            sanitize_key(
                $segments[
                    $index
                ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed_taxonomies,
                true
            )
        ) {

            return false;
        }


        $index++;


        /**
         * Termsegmenten verzamelen totdat
         * volgende taxonomy begint.
         */
        $term_segments =
            [];


        while (
            $index
            <
            $segment_count
        ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[
                        $index
                    ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed_taxonomies,
                    true
                )
            ) {

                break;
            }


            $term_segments[] =
                $segments[
                    $index
                ];


            $index++;
        }


        /**
         * Taxonomy zonder term is ongeldig.
         */
        if (
            empty(
                $term_segments
            )
        ) {

            return false;
        }


        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if (
            ! $resolved
        ) {

            return false;
        }


        /**
         * IEDER taxonomy/term blok blijft
         * een afzonderlijk item.
         *
         * Daardoor blijven bestaande
         * descriptions/shortcodes compatibel.
         */
        $items[] = [

            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved[
                    'term'
                ],

            'path' =>
                $resolved[
                    'path'
                ],
        ];
    }


    if (
        empty(
            $items
        )
    ) {

        return false;
    }


    $cache =
        $items;


    return $cache;
}


/**
 * ============================================================
 * 9. WORDPRESS TAX_QUERY BOUWEN
 * ============================================================
 *
 * Verschillende taxonomies:
 *
 * AND
 *
 *
 * Binnen dezelfde taxonomy:
 *
 * standaard OR
 *
 *
 * kennisgebied:
 *
 * AND
 */

function tfsc_build_combo_tax_query() {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! $combo
    ) {

        return false;
    }


    /**
     * Eerst alle geselecteerde termen
     * groeperen per taxonomy.
     */
    $grouped =
        [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['term']
            )
            ||
            ! (
                $item['term']
                instanceof
                WP_Term
            )
        ) {

            continue;
        }


        $taxonomy =
            $item['taxonomy'];


        if (
            ! isset(
                $grouped[
                    $taxonomy
                ]
            )
        ) {

            $grouped[
                $taxonomy
            ] =
                [];
        }


        $term_id =
            (int)
            $item['term']
                ->term_id;


        if (
            ! in_array(
                $term_id,
                $grouped[
                    $taxonomy
                ],
                true
            )
        ) {

            $grouped[
                $taxonomy
            ][] =
                $term_id;
        }
    }


    if (
        empty(
            $grouped
        )
    ) {

        return false;
    }


    $tax_query = [

        'relation' =>
            'AND',
    ];


    foreach (
        $grouped
        as $taxonomy => $term_ids
    ) {

        if (
            empty(
                $term_ids
            )
        ) {

            continue;
        }


        $tax_object =
            get_taxonomy(
                $taxonomy
            );


        $match_method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        /**
         * AND:
         *
         * vacature moet ALLE termen hebben.
         *
         * Bijvoorbeeld:
         *
         * Elektrotechniek
         * EN
         * Mechanisch
         */
        if (
            $match_method
            ===
            'AND'
            &&
            count(
                $term_ids
            )
            >
            1
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    $term_ids,

                'operator' =>
                    'AND',

                /**
                 * AND + child-expansie kan bij
                 * hiërarchische taxonomies
                 * ongewenste logica veroorzaken.
                 */
                'include_children' =>
                    false,
            ];


            continue;
        }


        /**
         * OR:
         *
         * vacature mag één van de termen hebben.
         *
         * Bijvoorbeeld:
         *
         * Noord-Brabant
         * OF
         * Zuid-Holland
         */
        $tax_query[] = [

            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            'operator' =>
                'IN',

            /**
             * Provincie neemt steden mee.
             */
            'include_children' =>
                (
                    $tax_object
                    &&
                    $tax_object
                        ->hierarchical
                ),
        ];
    }


    return $tax_query;
}


