 * ]
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {

            return;
        }


        $combo =
            tfsc_get_combo_archive();


        if (
            ! is_array(
                $combo
            )
            ||
            empty(
                $combo
            )
        ) {

            return;
        }


        $active_values =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                empty(
                    $item['taxonomy']
                )
                ||
                empty(
                    $item['term']
                )
                ||
                ! (
                    $item['term']
                    instanceof
                    WP_Term
                )
                ||
                empty(
                    $item['term']->slug
                )
            ) {

                continue;
            }


            $taxonomy =
                $item['taxonomy'];


            $slug =
                $item['term']->slug;


            if (
                ! isset(
                    $active_values[
                        $taxonomy
                    ]
                )
            ) {

                $active_values[
                    $taxonomy
                ] =
                    [];
            }


            if (
                ! in_array(
                    $slug,
                    $active_values[
                        $taxonomy
                    ],
                    true
                )
            ) {

                $active_values[
                    $taxonomy
                ][] =
                    $slug;
            }
        }


        if (
            empty(
                $active_values
            )
        ) {

            return;
        }

        ?>

        <script>

        (function () {

            const TFSC_COMBO_VALUES =
                <?php
                echo wp_json_encode(
                    $active_values
                );
                ?>;


            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            let tfscApplying =
                false;


            let tfscInitialSyncDone =
                false;


            window.TFSC_SF_COMBO_READY =
                false;


            /**
             * ------------------------------------------------
             * FIELDS OPHALEN
             * ------------------------------------------------
             */

            function tfscGetSearchFilterFields() {

                const fieldsApi =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.fields;


                if (
                    ! fieldsApi
                    ||
                    typeof fieldsApi.getAll
                    !== 'function'
                ) {

                    return [];
                }


                let fields =
                    fieldsApi.getAll();


                if (
                    fields instanceof Map
                ) {

                    fields =
                        Array.from(
                            fields.values()
                        );
                }


                else if (
                    fields
                    &&
                    ! Array.isArray(
                        fields
                    )
                    &&
                    typeof fields
                    === 'object'
                ) {

                    fields =
                        Object.values(
                            fields
                        );
                }


                return Array.isArray(
                    fields
                )
                    ?
                fields
                    :
                [];
            }


            /**
             * ------------------------------------------------
             * ARRAY GELIJKHEID
             * ------------------------------------------------
             */

            function tfscSameValues(
                currentValues,
                wantedValues
            ) {

                const current =
                    Array.isArray(
                        currentValues
                    )
                        ?
                    currentValues
                        .map(
                            String
                        )
                        .sort()
                        :
                    [];


                const wanted =
                    Array.isArray(
                        wantedValues
                    )
                        ?
                    wantedValues
                        .map(
                            String
                        )
                        .sort()
                        :
                    [];


                if (
                    current.length
                    !==
                    wanted.length
                ) {

                    return false;
                }


                return current.every(
                    function(
                        value,
                        index
                    ) {

                        return (
                            value
                            ===
                            wanted[
                                index
                            ]
                        );
                    }
                );
            }


            /**
             * ------------------------------------------------
             * COMBO → S&F FIELD VALUES
             * ------------------------------------------------
             */

            function tfscSyncComboValues() {

                if (
                    tfscApplying
                    ||
                    tfscInitialSyncDone
                ) {

                    return;
                }


                const fields =
                    tfscGetSearchFilterFields();


                if (
                    ! fields.length
                ) {

                    return;
                }


                tfscApplying =
                    true;


                let matchedFields =
                    0;


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getAttributes
                                !== 'function'
                            ||
                            typeof field.getValues
                                !== 'function'
                            ||
                            typeof field.setValues
                                !== 'function'
                        ) {

                            return;
                        }


                        const attributes =
                            field.getAttributes();


                        if (
                            ! attributes
                        ) {

                            return;
                        }


                        if (
                            String(
                                attributes.queryId
                            )
                            !==
                            String(
                                TFSC_QUERY_ID
                            )
                        ) {

                            return;
                        }


                        if (
                            attributes.dataType
                            !==
                            'taxonomy'
                        ) {

                            return;
                        }


                        const taxonomy =
                            attributes.dataTaxonomy;


                        if (
                            ! taxonomy
                            ||
                            ! Object.prototype
                                .hasOwnProperty
                                .call(
                                    TFSC_COMBO_VALUES,
                                    taxonomy
                                )
                        ) {

                            return;
                        }


                        const wantedValues =
                            TFSC_COMBO_VALUES[
                                taxonomy
                            ];


                        let currentValues =
                            field.getValues();


                        if (
                            ! Array.isArray(
                                currentValues
                            )
                        ) {

                            currentValues =
                                [];
                        }


                        matchedFields++;


                        if (
                            tfscSameValues(
                                currentValues,
                                wantedValues
                            )
                        ) {

                            return;
                        }


                        field.setValues(
                            wantedValues
                        );
                    }
                );


                tfscApplying =
                    false;


                if (
                    matchedFields > 0
                ) {

                    tfscInitialSyncDone =
                        true;


                    setTimeout(
                        function() {

                            window
                                .TFSC_SF_COMBO_READY =
                                    true;
                        },
                        100
                    );
                }
            }


            document.addEventListener(
                'search-filter/mount',
                function() {

                    setTimeout(
                        tfscSyncComboValues,
                        0
                    );


                    setTimeout(
                        tfscSyncComboValues,
                        100
                    );
                }
            );


            function tfscStartComboSync() {

                setTimeout(
                    tfscSyncComboValues,
                    50
                );


                setTimeout(
                    tfscSyncComboValues,
                    250
                );


                setTimeout(
                    tfscSyncComboValues,
                    750
                );


                setTimeout(
                    tfscSyncComboValues,
                    1500
                );
            }


            if (
                document.readyState
                ===
                'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartComboSync
                );

            } else {

                tfscStartComboSync();
            }

        })();

        </script>

        <?php
    },
    90
);


/**
 * ============================================================
 * 14. SEO LANDING → EERSTE FILTER = HARD PAGE LOAD
 * ============================================================
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_vacancy_seo_landing()
        ) {

            return;
        }


        $is_combo =
            tfsc_is_combo_archive();

        ?>

        <script>

        (function () {

            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            const TFSC_IS_COMBO =
                <?php
                echo $is_combo
                    ?
                'true'
                    :
                'false';
                ?>;


            let tfscRedirectAttached =
                false;


            let tfscRedirectStarted =
                false;


            function tfscNormalizeFields(
                fields
            ) {

                if (
                    ! fields
                ) {

                    return [];
                }


                if (
                    fields instanceof Map
                ) {

                    return Array.from(
                        fields.values()
                    );
                }


                if (
                    Array.isArray(
                        fields
                    )
                ) {

                    return fields;
                }


                if (
                    typeof fields
                    === 'object'
                ) {

                    return Object.values(
                        fields
                    );
                }


                return [];
            }


            function tfscBuildResultsUrl(
                query
            ) {

                if (
                    ! query
                    ||
                    typeof query.getUrl
                        !== 'function'
                    ||
                    typeof query.getFields
                        !== 'function'
                ) {

                    return null;
                }


                const baseUrl =
                    query.getUrl();


                if (
                    ! baseUrl
                ) {

                    return null;
                }


                const fields =
                    tfscNormalizeFields(
                        query.getFields()
                    );


                const prefix =
                    window
                        .searchAndFilterData
                        ?.urlPrefix
                    ||
                    '_';


                const parts =
                    [];


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getUrlName
                                !== 'function'
                            ||
                            typeof field.getUrlValues
                                !== 'function'
                        ) {

                            return;
                        }


                        const urlName =
                            field.getUrlName();


                        let values =
                            field.getUrlValues();


                        if (
                            ! urlName
                        ) {

                            return;
                        }


                        if (
                            values !== null
                            &&
                            values !== undefined
                            &&
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [
                                    values
                                ];
                        }


                        if (
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [];
                        }


                        values =
                            values.filter(
                                function(
                                    value
                                ) {

                                    return (
                                        value
                                        !== null
                                        &&
                                        value
                                        !== undefined
                                        &&
                                        String(
                                            value
                                        )
                                        !== ''
                                    );
                                }
                            );


                        if (
                            ! values.length
                        ) {

                            return;
                        }


                        const encodedValues =
                            values
                                .map(
                                    function(
                                        value
                                    ) {

                                        return encodeURIComponent(
                                            String(
                                                value
                                            )
                                        );
                                    }
                                )
                                .join(
                                    ','
                                );


                        const parameterName =
                            prefix
                            +
                            urlName;


                        parts.push(
                            encodeURIComponent(
                                parameterName
                            )
                            +
                            '='
                            +
                            encodedValues
                        );
                    }
                );


                if (
                    typeof query.getActiveUrlArg
                    === 'function'
                ) {

                    const activeArg =
                        query
                            .getActiveUrlArg();


                    if (
                        activeArg
                    ) {

                        parts.push(
                            encodeURIComponent(
                                activeArg
                            )
                        );
                    }
                }


                const cleanBase =
                    String(
                        baseUrl
                    )
                    .split(
                        '#'
                    )[0]
                    .split(
                        '?'
                    )[0];


                if (
                    ! parts.length
                ) {

                    return cleanBase;
                }


                return (
                    cleanBase
                    +
                    '?'
                    +
                    parts.join(
                        '&'
                    )
                );
            }


            function tfscAttachLandingRedirect() {

                if (
                    tfscRedirectAttached
                ) {

                    return true;
                }


                const queries =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.queries;


                if (
                    ! queries
                    ||
                    typeof queries.get
                        !== 'function'
                ) {

                    return false;
                }


                const query =
                    queries.get(
                        TFSC_QUERY_ID
                    );


                if (
                    ! query
                    ||
                    typeof query.on
                        !== 'function'
                ) {

                    return false;
                }


                tfscRedirectAttached =
                    true;


                query.on(
                    'get-results/start',
                    function() {

                        if (
                            tfscRedirectStarted
                        ) {

                            return;
                        }


                        if (
                            TFSC_IS_COMBO
                            &&
                            window
                                .TFSC_SF_COMBO_READY
                                !==
                                true
                        ) {

                            return;
                        }


                        const targetUrl =
                            tfscBuildResultsUrl(
                                query
                            );


                        if (
                            ! targetUrl
                        ) {

                            return;
                        }


                        tfscRedirectStarted =
                            true;


                        window.location.href =
                            targetUrl;
                    }
                );


                return true;
            }


            document.addEventListener(
                'search-filter/mount',
                function() {

                    setTimeout(
                        tfscAttachLandingRedirect,
                        150
                    );


                    setTimeout(
                        tfscAttachLandingRedirect,
                        400
                    );
                }
            );


            function tfscStartLandingRedirect() {

                setTimeout(
                    tfscAttachLandingRedirect,
                    250
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    750
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    1500
                );
            }


            if (
                document.readyState
                ===
                'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartLandingRedirect
                );

            } else {

                tfscStartLandingRedirect();
            }

        })();

        </script>

        <?php
    },
    100
);


