/**
 * ============================================================
 * 17. ARCHIVE / COMBO HEADING
 * ============================================================
 *
 * [combo_heading]
 *
 *
 * COMBO ARCHIEVEN:
 *
 * Worden altijd automatisch opgebouwd uit
 * de geselecteerde taxonomies en termen.
 *
 *
 * NATIVE TAXONOMY ARCHIEVEN:
 *
 * Kijken eerst naar het term meta-veld:
 *
 * pods_archive_title
 *
 * Als dit veld is ingevuld, wordt die waarde gebruikt.
 * Als het veld leeg is, wordt teruggevallen op:
 *
 * Termnaam vacatures
 *
 *
 * OUTPUT VOORBEELD COMBO:
 *
 * Field Service Engineer vacatures
 * Elektrotechniek, Mechanisch
 * Provincie Noord-Brabant, Provincie Zuid-Holland
 *
 *
 * LOGICA:
 *
 * - alles blijft binnen één Elementor H1
 * - iedere taxonomy krijgt één eigen regel
 * - meerdere termen binnen dezelfde taxonomy
 *   worden gescheiden met een komma
 * - functienaam staat altijd bovenaan
 * - HTML-regels worden ook met whitespace/newline
 *   van elkaar gescheiden
 */

add_shortcode(
    'combo_heading',
    function() {

        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         *
         * Combo-archieven gebruiken altijd de automatisch
         * opgebouwde heading.
         *
         * Het veld pods_archive_title wordt hier dus
         * bewust niet gebruikt.
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                /**
                 * Termen groeperen per taxonomy.
                 */
                $grouped =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {

                        continue;
                    }


                    $taxonomy =
                        $item[
                            'taxonomy'
                        ];


                    $term_name =
                        trim(
                            $item[
                                'term'
                            ]->name
                        );


                    if (
                        $term_name === ''
                    ) {

                        continue;
                    }


                    if (
                        ! isset(
                            $grouped[
                                $taxonomy
                            ]
                        )
                    ) {

                        $grouped[
                            $taxonomy
                        ] =
                            [];
                    }


                    /**
                     * Dubbele termen voorkomen.
                     */
                    if (
                        ! in_array(
                            $term_name,
                            $grouped[
                                $taxonomy
                            ],
                            true
                        )
                    ) {

                        $grouped[
                            $taxonomy
                        ][] =
                            $term_name;
                    }
                }


                if (
                    empty(
                        $grouped
                    )
                ) {

                    return '';
                }


                /**
                 * Hier komen de afzonderlijke regels.
                 */
                $rows =
                    [];


                /**
                 * ------------------------------------------------
                 * FUNCTIENAAM ALTIJD EERST
                 * ------------------------------------------------
                 */

                if (
                    ! empty(
                        $grouped[
                            'functienaam'
                        ]
                    )
                ) {

                    $function_names =
                        $grouped[
                            'functienaam'
                        ];


                    /**
                     * Eén functienaam:
                     *
                     * Field Service Engineer vacatures
                     */
                    if (
                        count(
                            $function_names
                        )
                        ===
                        1
                    ) {

                        $rows[] =
                            $function_names[0]
                            .
                            ' vacatures';
                    }


                    /**
                     * Meerdere functienamen:
                     *
                     * Vacatures
                     * Field Service Engineer, Commissioning Engineer
                     */
                    else {

                        $rows[] =
                            'Vacatures';


                        $rows[] =
                            implode(
                                ', ',
                                $function_names
                            );
                    }


                    unset(
                        $grouped[
                            'functienaam'
                        ]
                    );

                } else {

                    /**
                     * Geen functienaam actief.
                     */
                    $rows[] =
                        'Vacatures';
                }


                /**
                 * ------------------------------------------------
                 * OVERIGE TAXONOMIES
                 * ------------------------------------------------
                 *
                 * Iedere taxonomy krijgt één regel.
                 *
                 * Meerdere termen:
                 *
                 * Elektrotechniek, Mechanisch
                 *
                 * Provincie Noord-Brabant,
                 * Provincie Zuid-Holland
                 */

                foreach (
                    $grouped
                    as $taxonomy => $term_names
                ) {

                    if (
                        empty(
                            $term_names
                        )
                    ) {

                        continue;
                    }


                    $rows[] =
                        implode(
                            ', ',
                            $term_names
                        );
                }


                if (
                    empty(
                        $rows
                    )
                ) {

                    return '';
                }


                /**
                 * ------------------------------------------------
                 * HTML OUTPUT
                 * ------------------------------------------------
                 *
                 * Elementor maakt zelf de H1.
                 *
                 * De shortcode levert alleen de inhoud:
                 *
                 * <span class="tfsc-heading">
                 *     <span>...</span>
                 *     <span>...</span>
                 * </span>
                 */

                $html =
                    '<span class="tfsc-heading">'
                    .
                    "\n";


                foreach (
                    $rows
                    as $index => $row
                ) {

                    $class =
                        (
                            $index === 0
                        )
                        ?
                        'tfsc-heading__main'
                        :
                        'tfsc-heading__row';


                    $html .=
                        '<span class="'
                        .
                        esc_attr(
                            $class
                        )
                        .
                        '">'
                        .
                        esc_html(
                            $row
                        )
                        .
                        '</span>'
                        .
                        "\n";
                }


                $html .=
                    '</span>';


                return $html;
            }
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         *
         * Op een werkelijk taxonomy-archief wordt eerst
         * gekeken naar het Pods-termveld:
         *
         * pods_archive_title
         *
         * Is dat veld ingevuld, dan wordt die waarde gebruikt.
         *
         * Is het veld leeg, dan blijft de standaardtitel:
         *
         * Termnaam vacatures
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
        ) {

            $taxonomy =
                $queried_object
                    ->taxonomy;


            if (
                $taxonomy
                &&
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $taxonomy
                )
            ) {

                /**
                 * Pods-taxonomyvelden worden normaal gesproken
                 * opgeslagen als WordPress term metadata.
                 */
                $alternative_title =
                    get_term_meta(
                        $queried_object
                            ->term_id,
                        'pods_archive_title',
                        true
                    );


                /**
                 * Alleen een bruikbare tekstwaarde accepteren.
                 */
                if (
                    is_string(
                        $alternative_title
                    )
                ) {

                    $alternative_title =
                        trim(
                            wp_strip_all_tags(
                                $alternative_title
                            )
                        );

                } else {

                    $alternative_title =
                        '';
                }


                /**
                 * Alternatieve archieftitel heeft voorrang.
                 */
                if (
                    $alternative_title !== ''
                ) {

                    $archive_title =
                        $alternative_title;

                } else {

                    /**
                     * Fallback wanneer het Pods-veld leeg is.
                     */
                    $term_name =
                        trim(
                            $queried_object
                                ->name
                        );


                    if (
                        $term_name === ''
                    ) {

                        return '';
                    }


                    $archive_title =
                        $term_name
                        .
                        ' vacatures';
                }


                return

                    '<span class="tfsc-heading">'
                    .
                    "\n"
                    .
                    '<span class="tfsc-heading__main">'
                    .
                    esc_html(
                        $archive_title
                    )
                    .
                    '</span>'
                    .
                    "\n"
                    .
                    '</span>';
            }
        }


        /**
         * ----------------------------------------------------
         * 3. VACATURE POST TYPE ARCHIVE
         * ----------------------------------------------------
         */

        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {

            return

                '<span class="tfsc-heading">'
                .
                "\n"
                .
                '<span class="tfsc-heading__main">'
                .
                esc_html(
                    'Vacatures'
                )
                .
                '</span>'
                .
                "\n"
                .
                '</span>';
        }


        return '';
    }
);
/**
 * ============================================================
 * 18. SPECIFIEKE ARCHIVE / COMBO TERM
 * ============================================================
 *
 * [combo_term taxonomy="kennisgebied"]
 *
 * Eén waarde:
 *
 * Elektrotechniek
 *
 *
 * Meerdere waarden:
 *
 * Elektrotechniek • Mechanisch
 *
 *
 * Andere separator:
 *
 * [combo_term
 * taxonomy="kennisgebied"
 * separator=", "]
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',

                    'separator' =>
                        ' • ',
                ],
                $atts,
                'combo_term'
            );


        $wanted_taxonomy =
            sanitize_key(
                $atts[
                    'taxonomy'
                ]
            );


        if (
            ! $wanted_taxonomy
        ) {

            return '';
        }


        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                $names =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        $item['taxonomy']
                        !==
                        $wanted_taxonomy
                    ) {

                        continue;
                    }


                    if (
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {

                        continue;
                    }


                    $name =
                        trim(
                            $item['term']->name
                        );


                    if (
                        $name === ''
                    ) {

                        continue;
                    }


                    if (
                        ! in_array(
                            $name,
                            $names,
                            true
                        )
                    ) {

                        $names[] =
                            $name;
                    }
                }


                if (
                    empty(
                        $names
                    )
                ) {

                    return '';
                }


                return esc_html(
                    implode(
                        (string)
                        $atts[
                            'separator'
                        ],
                        $names
                    )
                );
            }


            return '';
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            $queried_object
                ->taxonomy
            ===
            $wanted_taxonomy
        ) {

            if (
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $queried_object
                        ->taxonomy
                )
            ) {

                return esc_html(
                    $queried_object
                        ->name
                );
            }
        }


        return '';
    }
);

/**
 * ============================================================
 * TFSC - VOLLEDIG DYNAMISCHE VACATURE ARCHIEVEN
 * + SEARCH & FILTER PRO V3
 * + ALLEEN OPEN VACATURES
 * ============================================================
 *
 * ONBEPERKT AANTAL TAXONOMIES.
 * ONBEPERKT AANTAL TERMEN PER TAXONOMY.
 *
 *
 * ============================================================
 * VACATURESTATUS
 * ============================================================
 *
 * Alleen vacatures met:
 *
 * Taxonomy:
 * vac_status
 *
 * Term:
 * open
 *
 * worden weergegeven.
 *
 *
 * Daardoor worden vacatures met bijvoorbeeld:
 *
 * - Gesloten Oud
 * - Ingevuld
 *
 * automatisch uitgesloten.
 *
 *
 * De taxonomy "vac_status" is intern en wordt NIET
 * beschikbaar gemaakt als publieke combo-taxonomy.
 *
 *
 * ============================================================
 * ARCHITECTUUR
 * ============================================================
 *
 * NATIVE TAXONOMY:
 *
 * /functienaam/service-engineer/
 *
 *
 * VIRTUELE COMBO:
 *
 * /vacatures/functienaam/field-service-engineer/
 *
 *
 * MEERDERE TAXONOMIES:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/noord-brabant/
 *
 *
 * MEERDERE TERMEN BINNEN DEZELFDE TAXONOMY:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * kennisgebied/mechanisch/
 * locatie/noord-brabant/
 * locatie/zuid-holland/
 *
 *
 * HIËRARCHISCHE TAXONOMY:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * locatie/noord-brabant/tilburg/
 * locatie/zuid-holland/rotterdam/
 *
 *
 * ============================================================
 * TAXONOMY MATCHING
 * ============================================================
 *
 * Verschillende taxonomies:
 *
 * AND
 *
 *
 * Meerdere termen binnen één taxonomy:
 *
 * standaard OR
 *
 *
 * Uitzondering:
 *
 * kennisgebied = AND
 *
 *
 * ============================================================
 * SEARCH & FILTER
 * ============================================================
 *
 * /vacatures/
 *
 * is de interactieve Search & Filter resultatenpagina.
 *
 *
 * SEO landing page
 *      ↓
 * gebruiker wijzigt filter
 *      ↓
 * S&F get-results/start
 *      ↓
 * HARD PAGE LOAD naar:
 *
 * /vacatures/?_...
 *
 *      ↓
 *
 * vanaf /vacatures/
 * werkt Live Search verder via AJAX.
 *
 *
 * ============================================================
 * SHORTCODES
 * ============================================================
 *
 * [combo_heading]
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 *
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

define(
    'TFSC_COMBO_BASE',
    'vacatures'
);

define(
    'TFSC_VACANCY_POST_TYPE',
    'vacature'
);

define(
    'TFSC_SEARCH_FILTER_QUERY_ID',
    1
);


/**
 * Vacaturestatus taxonomy.
 */
define(
    'TFSC_STATUS_TAXONOMY',
    'vac_status'
);


/**
 * Alleen deze status wordt als actief beschouwd.
 */
define(
    'TFSC_OPEN_STATUS_SLUG',
    'open'
);


/**
 * ============================================================
 * TAXONOMY MATCH METHOD
 * ============================================================
 *
 * Standaard:
 *
 * OR
 *
 * Bijvoorbeeld locaties:
 *
 * Noord-Brabant
 * OF
 * Zuid-Holland
 *
 *
 * kennisgebied:
 *
 * AND
 *
 * Bijvoorbeeld:
 *
 * Elektrotechniek
 * EN
 * Mechanisch
 */

function tfsc_get_combo_taxonomy_match_method(
    $taxonomy
) {

    $methods = [

        'kennisgebied' =>
            'AND',
    ];


    if (
        isset(
            $methods[
                $taxonomy
            ]
        )
    ) {

        return
            $methods[
                $taxonomy
            ];
    }


    return 'OR';
}


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed(
    $taxonomy
) {

    /**
     * --------------------------------------------------------
     * VACATURESTATUS IS INTERN
     * --------------------------------------------------------
     *
     * vac_status mag niet als normale SEO-taxonomy
     * in combo-URL's terechtkomen.
     */

    if (
        $taxonomy
        ===
        TFSC_STATUS_TAXONOMY
    ) {

        return false;
    }


    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {

        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {

        return false;
    }


    /**
     * Alleen publiek bevraagbare taxonomies.
     */
    if (
        ! $tax_object
            ->publicly_queryable
    ) {

        return false;
    }


    /**
     * Alleen taxonomies gekoppeld aan vacature.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {

        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. ALLE TOEGESTANE COMBO TAXONOMIES
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed =
        [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


