/**
 * ============================================================
 * 17. ARCHIVE / COMBO HEADING
 * ============================================================
 *
 * [combo_heading]
 *
 *
 * COMBO:
 *
 * Automatisch opgebouwd uit de geselecteerde termen.
 *
 *
 * NATIVE TAXONOMY:
 *
 * Eerst:
 *
 * pods_archive_title
 *
 * indien gevuld.
 *
 * Anders:
 *
 * Termnaam vacatures
 */

add_shortcode(
    'combo_heading',
    function() {

        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                $grouped =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {

                        continue;
                    }


                    $taxonomy =
                        $item[
                            'taxonomy'
                        ];


                    $term_name =
                        trim(
                            $item[
                                'term'
                            ]->name
                        );


                    if (
                        $term_name === ''
                    ) {

                        continue;
                    }


                    if (
                        ! isset(
                            $grouped[
                                $taxonomy
                            ]
                        )
                    ) {

                        $grouped[
                            $taxonomy
                        ] =
                            [];
                    }


                    if (
                        ! in_array(
                            $term_name,
                            $grouped[
                                $taxonomy
                            ],
                            true
                        )
                    ) {

                        $grouped[
                            $taxonomy
                        ][] =
                            $term_name;
                    }
                }


                if (
                    empty(
                        $grouped
                    )
                ) {

                    return '';
                }


                $rows =
                    [];


                /**
                 * Functienaam eerst.
                 */
                if (
                    ! empty(
                        $grouped[
                            'functienaam'
                        ]
                    )
                ) {

                    $function_names =
                        $grouped[
                            'functienaam'
                        ];


                    if (
                        count(
                            $function_names
                        )
                        ===
                        1
                    ) {

                        $rows[] =
                            $function_names[0]
                            .
                            ' vacatures';

                    } else {

                        $rows[] =
                            'Vacatures';


                        $rows[] =
                            implode(
                                ', ',
                                $function_names
                            );
                    }


                    unset(
                        $grouped[
                            'functienaam'
                        ]
                    );

                } else {

                    $rows[] =
                        'Vacatures';
                }


                /**
                 * Overige taxonomies.
                 */
                foreach (
                    $grouped
                    as $taxonomy => $term_names
                ) {

                    if (
                        empty(
                            $term_names
                        )
                    ) {

                        continue;
                    }


                    $rows[] =
                        implode(
                            ', ',
                            $term_names
                        );
                }


                if (
                    empty(
                        $rows
                    )
                ) {

                    return '';
                }


                /**
                 * HTML.
                 */
                $html =
                    '<span class="tfsc-heading">'
                    .
                    "\n";


                foreach (
                    $rows
                    as $index => $row
                ) {

                    $class =
                        (
                            $index === 0
                        )
                        ?
                        'tfsc-heading__main'
                        :
                        'tfsc-heading__row';


                    $html .=
                        '<span class="'
                        .
                        esc_attr(
                            $class
                        )
                        .
                        '">'
                        .
                        esc_html(
                            $row
                        )
                        .
                        '</span>'
                        .
                        "\n";
                }


                $html .=
                    '</span>';


                return $html;
            }
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
        ) {

            $taxonomy =
                $queried_object
                    ->taxonomy;


            if (
                $taxonomy
                &&
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $taxonomy
                )
            ) {

                /**
                 * Pods alternatieve archive title.
                 */
                $alternative_title =
                    get_term_meta(
                        $queried_object
                            ->term_id,
                        'pods_archive_title',
                        true
                    );


                if (
                    is_string(
                        $alternative_title
                    )
                ) {

                    $alternative_title =
                        trim(
                            wp_strip_all_tags(
                                $alternative_title
                            )
                        );

                } else {

                    $alternative_title =
                        '';
                }


                if (
                    $alternative_title !== ''
                ) {

                    $archive_title =
                        $alternative_title;

                } else {

                    $term_name =
                        trim(
                            $queried_object
                                ->name
                        );


                    if (
                        $term_name === ''
                    ) {

                        return '';
                    }


                    $archive_title =
                        $term_name
                        .
                        ' vacatures';
                }


                return

                    '<span class="tfsc-heading">'
                    .
                    "\n"
                    .
                    '<span class="tfsc-heading__main">'
                    .
                    esc_html(
                        $archive_title
                    )
                    .
                    '</span>'
                    .
                    "\n"
                    .
                    '</span>';
            }
        }


        /**
         * ----------------------------------------------------
         * 3. VACATURE POST TYPE ARCHIVE
         * ----------------------------------------------------
         */

        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {

            return

                '<span class="tfsc-heading">'
                .
                "\n"
                .
                '<span class="tfsc-heading__main">'
                .
                esc_html(
                    'Vacatures'
                )
                .
                '</span>'
                .
                "\n"
                .
                '</span>';
        }


        return '';
    }
);


/**
 * ============================================================
 * 18. SPECIFIEKE ARCHIVE / COMBO TERM
 * ============================================================
 *
 * [combo_term taxonomy="kennisgebied"]
 *
 *
 * Eén waarde:
 *
 * Elektrotechniek
 *
 *
 * Meerdere waarden:
 *
 * Elektrotechniek • Mechanisch
 *
 *
 * Andere separator:
 *
 * [combo_term
 * taxonomy="kennisgebied"
 * separator=", "]
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',

                    'separator' =>
                        ' • ',
                ],
                $atts,
                'combo_term'
            );


        $wanted_taxonomy =
            sanitize_key(
                $atts[
                    'taxonomy'
                ]
            );


        if (
            ! $wanted_taxonomy
        ) {

            return '';
        }


        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                $names =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        $item['taxonomy']
                        !==
                        $wanted_taxonomy
                    ) {

                        continue;
                    }


                    if (
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {

                        continue;
                    }


                    $name =
                        trim(
                            $item['term']->name
                        );


                    if (
                        $name === ''
                    ) {

                        continue;
                    }


                    if (
                        ! in_array(
                            $name,
                            $names,
                            true
                        )
                    ) {

                        $names[] =
                            $name;
                    }
                }


                if (
                    empty(
                        $names
                    )
                ) {

                    return '';
                }


                return esc_html(
                    implode(
                        (string)
                        $atts[
                            'separator'
                        ],
                        $names
                    )
                );
            }


            return '';
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            $queried_object
                ->taxonomy
            ===
            $wanted_taxonomy
        ) {

            if (
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $queried_object
                        ->taxonomy
                )
            ) {

                return esc_html(
                    $queried_object
                        ->name
                );
            }
        }


        return '';
    }
);

add_action(
    'wp_footer',
    function() {
        ?>

<script>
(function () {

    /**
     * ========================================================
     * CONFIG
     * ========================================================
     *
     * Aantal taxonomy-opties dat standaard zichtbaar blijft.
     */
    const TFSC_VISIBLE_TERMS = 6;


    /**
     * ========================================================
     * ÉÉN FILTER VERWERKEN
     * ========================================================
     */
    function tfscSetupMoreFilter(container) {

        if (!container) {
            return;
        }


        /**
         * Zoek checkbox/radio items.
         *
         * Search & Filter kan per field iets andere markup
         * genereren, daarom zoeken we meerdere gangbare vormen.
         */
        let items = Array.from(
            container.querySelectorAll(
                'li'
            )
        );


        /**
         * Alleen LI's behouden waarin daadwerkelijk
         * een checkbox of radio button staat.
         */
        items = items.filter(function (item) {

            return item.querySelector(
                'input[type="checkbox"], input[type="radio"]'
            );

        });


        /**
         * Niet genoeg opties?
         *
         * Dan is "Meer tonen" niet nodig.
         */
        if (
            items.length <= TFSC_VISIBLE_TERMS
        ) {

            const oldToggle =
                container.querySelector(
                    '.tfsc-filter-more-toggle'
                );

            if (oldToggle) {
                oldToggle.remove();
            }

            items.forEach(function (item) {
                item.classList.remove(
                    'tfsc-hidden-term'
                );
            });

            return;
        }


        /**
         * ----------------------------------------------------
         * SELECTIES ALTIJD ZICHTBAAR HOUDEN
         * ----------------------------------------------------
         *
         * Een aangevinkte optie mag nooit verborgen worden,
         * ook wanneer deze buiten de eerste 6 valt.
         */

        let visibleCount = 0;


        items.forEach(function (item) {

            item.classList.remove(
                'tfsc-hidden-term'
            );


            const input =
                item.querySelector(
                    'input[type="checkbox"], input[type="radio"]'
                );


            const selected =
                input && input.checked;


            if (
                visibleCount < TFSC_VISIBLE_TERMS
                ||
                selected
            ) {

                visibleCount++;

                return;
            }


            item.classList.add(
                'tfsc-hidden-term'
            );

        });


        /**
         * ----------------------------------------------------
         * BESTAANDE BUTTON HERGEBRUIKEN
         * ----------------------------------------------------
         */

        let toggle =
            container.querySelector(
                ':scope > .tfsc-filter-more-toggle'
            );


        if (!toggle) {

            toggle =
                document.createElement(
                    'button'
                );


            toggle.type =
                'button';


            toggle.className =
                'tfsc-filter-more-toggle';


            container.appendChild(
                toggle
            );

        }


        /**
         * ----------------------------------------------------
         * BUTTONTEKST
         * ----------------------------------------------------
         */

        function tfscUpdateToggleText() {

            const expanded =
                container.classList.contains(
                    'tfsc-filter-expanded'
                );


            toggle.textContent =
                expanded
                    ? 'Minder tonen'
                    : 'Meer tonen';

        }


        tfscUpdateToggleText();


        /**
         * Geen dubbele click handlers.
         */
        if (
            toggle.dataset.tfscBound
            ===
            '1'
        ) {

            return;
        }


        toggle.dataset.tfscBound =
            '1';


        toggle.addEventListener(
            'click',
            function () {

                container.classList.toggle(
                    'tfsc-filter-expanded'
                );


                tfscUpdateToggleText();

            }
        );

    }


    /**
     * ========================================================
     * ALLE FILTERS VERWERKEN
     * ========================================================
     */

    function tfscSetupAllMoreFilters() {

        const containers =
            document.querySelectorAll(
                '.tfsc-filter-more'
            );


        containers.forEach(
            tfscSetupMoreFilter
        );

    }


    /**
     * ========================================================
     * EERSTE PAGE LOAD
     * ========================================================
     */

    if (
        document.readyState === 'loading'
    ) {

        document.addEventListener(
            'DOMContentLoaded',
            tfscSetupAllMoreFilters
        );

    } else {

        tfscSetupAllMoreFilters();

    }


    /**
     * ========================================================
     * SEARCH & FILTER MOUNT
     * ========================================================
     */

    document.addEventListener(
        'search-filter/mount',
        function () {

            setTimeout(
                tfscSetupAllMoreFilters,
                50
            );

        }
    );


    /**
     * ========================================================
     * AJAX / DOM UPDATES
     * ========================================================
     *
     * Search & Filter kan de field-markup opnieuw genereren.
     * Daarom controleren we wijzigingen in de DOM.
     */

    let tfscMutationTimer = null;


    const observer =
        new MutationObserver(
            function () {

                clearTimeout(
                    tfscMutationTimer
                );


                tfscMutationTimer =
                    setTimeout(
                        tfscSetupAllMoreFilters,
                        100
                    );

            }
        );


    observer.observe(
        document.body,
        {
            childList: true,
            subtree: true
        }
    );

})();
</script>

   <?php
    },
    120
);

/**
 * ============================================================
 * TFSC - RANK MATH BREADCRUMBS VOOR COMBO ARCHIEVEN
 * ============================================================
 *
 * Vereist de bestaande TFSC combo archive snippet.
 *
 *
 * VOORBEELD:
 *
 * URL:
 * /vacatures/functienaam/field-service-engineer/
 *
 * Breadcrumb:
 *
 * Home > Vacatures > Field Service Engineer
 *
 *
 * URL:
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 *
 * Breadcrumb:
 *
 * Home > Vacatures > Field Service Engineer > Elektrotechniek
 *
 *
 * URL:
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/noord-brabant/
 *
 * Breadcrumb:
 *
 * Home > Vacatures > Field Service Engineer
 *      > Elektrotechniek
 *      > Noord-Brabant
 *
 *
 * De technische taxonomy-namen zoals:
 *
 * functienaam
 * kennisgebied
 * locatie
 *
 * worden NIET getoond.
 */


add_filter(
    'rank_math/frontend/breadcrumb/items',
    function( $crumbs, $class ) {

        /**
         * Alleen uitvoeren wanneer onze
         * combo-archive functies bestaan.
         */
        if (
            ! function_exists(
                'tfsc_is_combo_archive'
            )
            ||
            ! function_exists(
                'tfsc_get_combo_archive'
            )
        ) {

            return $crumbs;
        }


        /**
         * Alleen virtuele combo-archieven.
         */
        if (
            ! tfsc_is_combo_archive()
        ) {

            return $crumbs;
        }


        $combo =
            tfsc_get_combo_archive();


        if (
            ! is_array(
                $combo
            )
            ||
            empty(
                $combo
            )
        ) {

            return $crumbs;
        }


        /**
         * ----------------------------------------------------
         * NIEUWE BREADCRUMBS OPBOUWEN
         * ----------------------------------------------------
         */

        $new_crumbs =
            [];


        /**
         * ----------------------------------------------------
         * 1. HOME
         * ----------------------------------------------------
         */

        $new_crumbs[] = [

    'Home',

    home_url(
        '/'
    ),
];


        /**
         * ----------------------------------------------------
         * 2. VACATURES
         * ----------------------------------------------------
         */

        $vacatures_url =
            home_url(
                '/'
                .
                trim(
                    TFSC_COMBO_BASE,
                    '/'
                )
                .
                '/'
            );


        $new_crumbs[] = [

            'Vacatures',

            $vacatures_url,
        ];


        /**
         * ----------------------------------------------------
         * 3. COMBO TERMEN
         * ----------------------------------------------------
         *
         * We bouwen voor iedere stap een geldige
         * tussen-URL op.
         *
         * Daardoor worden breadcrumbs ook echt
         * bruikbare interne links.
         */

        $path_parts =
            [];


        $combo_count =
            count(
                $combo
            );


        foreach (
            $combo
            as $index => $item
        ) {

            if (
                empty(
                    $item['taxonomy']
                )
                ||
                empty(
                    $item['term']
                )
                ||
                ! (
                    $item['term']
                    instanceof
                    WP_Term
                )
            ) {

                continue;
            }


            $taxonomy =
                sanitize_key(
                    $item[
                        'taxonomy'
                    ]
                );


            $term =
                $item[
                    'term'
                ];


            /**
             * Taxonomy toevoegen aan URL.
             */
            $path_parts[] =
                $taxonomy;


            /**
             * ------------------------------------------------
             * HIËRARCHISCH TERMPAD
             * ------------------------------------------------
             *
             * Bijvoorbeeld:
             *
             * locatie/noord-brabant/tilburg/
             *
             * In plaats van alleen:
             *
             * locatie/tilburg/
             */

            if (
                ! empty(
                    $item['path']
                )
                &&
                is_array(
                    $item['path']
                )
            ) {

                foreach (
                    $item['path']
                    as $path_term
                ) {

                    if (
                        $path_term
                        instanceof
                        WP_Term
                    ) {

                        $path_parts[] =
                            $path_term
                                ->slug;
                    }
                }

            } else {

                $path_parts[] =
                    $term->slug;
            }


            /**
             * URL tot en met deze breadcrumb.
             */
            $breadcrumb_url =
                home_url(
                    '/'
                    .
                    trim(
                        TFSC_COMBO_BASE,
                        '/'
                    )
                    .
                    '/'
                    .
                    implode(
                        '/',
                        array_map(
                            'rawurlencode',
                            $path_parts
                        )
                    )
                    .
                    '/'
                );


            /**
             * Laatste breadcrumb is de huidige pagina.
             *
             * Rank Math verwacht daarvoor normaal
             * geen URL.
             */
            $is_last =
                (
                    $index
                    ===
                    $combo_count - 1
                );


            if (
                $is_last
            ) {

                $new_crumbs[] = [

                    $term->name,

                    '',
                ];

            } else {

                $new_crumbs[] = [

                    $term->name,

                    $breadcrumb_url,
                ];
            }
        }


        return $new_crumbs;

    },
    20,
    2
);

/**
 * ============================================================
 * TFSC - DYNAMISCHE ARCHIVE DESCRIPTION ACCORDION
 * ============================================================
 *
 * Shortcode:
 *
 * [tfsc_archive_accordion]
 *
 *
 * Werkt op:
 *
 * - native taxonomy archives
 * - virtuele TFSC combo archives
 *
 *
 * Per aanwezige term-description wordt automatisch
 * één accordion-item opgebouwd.
 *
 *
 * TITELLOGICA:
 *
 * 1. Pods term field:
 *    pods_archive_title
 *
 * 2. Als leeg:
 *    taxonomy singular label
 *
 * 3. Als ook dat ontbreekt:
 *    termnaam
 *
 *
 * CONTENT:
 *
 * WordPress taxonomy term description
 */


/**
 * ============================================================
 * 1. ACCORDION ITEM DATA VAN ÉÉN TERM
 * ============================================================
 */

function tfsc_get_archive_accordion_item(
    $term
) {

    if (
        ! (
            $term
            instanceof
            WP_Term
        )
    ) {
        return false;
    }


    /**
     * --------------------------------------------------------
     * DESCRIPTION
     * --------------------------------------------------------
     */

    $description =
        term_description(
            $term->term_id,
            $term->taxonomy
        );


    $description =
        trim(
            (string)
            $description
        );


    /**
     * Geen description:
     * geen accordion-item.
     */
    if (
        $description === ''
    ) {
        return false;
    }


    /**
     * --------------------------------------------------------
     * CUSTOM PODS ARCHIVE TITLE
     * --------------------------------------------------------
     */

    $title =
        get_term_meta(
            $term->term_id,
            'pods_archive_title',
            true
        );


    if (
        is_string(
            $title
        )
    ) {

        $title =
            trim(
                wp_strip_all_tags(
                    $title
                )
            );

    } else {

        $title =
            '';
    }


    /**
     * --------------------------------------------------------
     * FALLBACK:
     * TAXONOMY SINGULAR LABEL
     * --------------------------------------------------------
     */

    if (
        $title === ''
    ) {

        $taxonomy_object =
            get_taxonomy(
                $term->taxonomy
            );


        if (
            $taxonomy_object
            &&
            ! empty(
                $taxonomy_object
                    ->labels
                    ->singular_name
            )
        ) {

            $title =
                trim(
                    $taxonomy_object
                        ->labels
                        ->singular_name
                );
        }
    }


    /**
     * --------------------------------------------------------
     * LAATSTE FALLBACK:
     * TERMNAAM
     * --------------------------------------------------------
     */

    if (
        $title === ''
    ) {

        $title =
            trim(
                $term->name
            );
    }


    if (
        $title === ''
    ) {
        return false;
    }


    return [

        'title' =>
            $title,

        'description' =>
            $description,

        'term_id' =>
            (int)
            $term->term_id,

        'taxonomy' =>
            $term->taxonomy,
    ];
}


/**
 * ============================================================
 * 2. ALLE RELEVANTE ACCORDION ITEMS OPHALEN
 * ============================================================
 */

function tfsc_get_archive_accordion_items() {

    $items =
        [];


    $seen =
        [];


    /**
     * --------------------------------------------------------
     * A. VIRTUEEL COMBO ARCHIVE
     * --------------------------------------------------------
     */

    if (
        function_exists(
            'tfsc_is_combo_archive'
        )
        &&
        function_exists(
            'tfsc_get_combo_archive'
        )
        &&
        tfsc_is_combo_archive()
    ) {

        $combo =
            tfsc_get_combo_archive();


        if (
            is_array(
                $combo
            )
            &&
            ! empty(
                $combo
            )
        ) {

            foreach (
                $combo
                as $combo_item
            ) {

                if (
                    empty(
                        $combo_item['term']
                    )
                    ||
                    ! (
                        $combo_item['term']
                        instanceof
                        WP_Term
                    )
                ) {

                    continue;
                }


                $term =
                    $combo_item['term'];


                /**
                 * Dubbele term voorkomen.
                 */
                $unique_key =
                    $term->taxonomy
                    .
                    ':'
                    .
                    $term->term_id;


                if (
                    isset(
                        $seen[
                            $unique_key
                        ]
                    )
                ) {
                    continue;
                }


                $accordion_item =
                    tfsc_get_archive_accordion_item(
                        $term
                    );


                if (
                    ! $accordion_item
                ) {
                    continue;
                }


                $seen[
                    $unique_key
                ] =
                    true;


                $items[] =
                    $accordion_item;
            }
        }


        return $items;
    }


    /**
     * --------------------------------------------------------
     * B. NATIVE TAXONOMY ARCHIVE
     * --------------------------------------------------------
     */

    $queried_object =
        get_queried_object();


    if (
        $queried_object
        instanceof
        WP_Term
    ) {

        /**
         * Als je main snippet aanwezig is,
         * alleen toegestane vacature-taxonomies gebruiken.
         */
        if (
            function_exists(
                'tfsc_combo_taxonomy_allowed'
            )
            &&
            ! tfsc_combo_taxonomy_allowed(
                $queried_object
                    ->taxonomy
            )
        ) {

            return [];
        }


        $accordion_item =
            tfsc_get_archive_accordion_item(
                $queried_object
            );


        if (
            $accordion_item
        ) {

            $items[] =
                $accordion_item;
        }
    }


    return $items;
}


