 * ============================================================
 */

function tfsc_get_archive_accordion_items() {

    $items =
        [];


    /**
     * Hiermee voorkomen we dubbele termen.
     */
    $seen =
        [];


    /**
     * --------------------------------------------------------
     * A. VIRTUEEL COMBO ARCHIVE
     * --------------------------------------------------------
     */

    if (
        function_exists(
            'tfsc_is_combo_archive'
        )
        &&
        function_exists(
            'tfsc_get_combo_archive'
        )
        &&
        tfsc_is_combo_archive()
    ) {

        $combo =
            tfsc_get_combo_archive();


        if (
            is_array(
                $combo
            )
            &&
            ! empty(
                $combo
            )
        ) {

            foreach (
                $combo
                as $combo_item
            ) {

                if (
                    empty(
                        $combo_item['term']
                    )
                    ||
                    ! (
                        $combo_item['term']
                        instanceof
                        WP_Term
                    )
                ) {

                    continue;
                }


                $term =
                    $combo_item['term'];


                /**
                 * Unieke combinatie van taxonomy + term ID.
                 *
                 * Dezelfde term kan hierdoor niet twee keer
                 * in de accordion terechtkomen.
                 */
                $unique_key =
                    $term->taxonomy
                    .
                    ':'
                    .
                    $term->term_id;


                if (
                    isset(
                        $seen[
                            $unique_key
                        ]
                    )
                ) {

                    continue;
                }


                $accordion_item =
                    tfsc_get_archive_accordion_item(
                        $term
                    );


                /**
                 * Geen description:
                 * geen accordion-item.
                 */
                if (
                    ! $accordion_item
                ) {

                    continue;
                }


                $seen[
                    $unique_key
                ] =
                    true;


                $items[] =
                    $accordion_item;
            }
        }


        return $items;
    }


    /**
     * --------------------------------------------------------
     * B. NATIVE TAXONOMY ARCHIVE
     * --------------------------------------------------------
     */

    $queried_object =
        get_queried_object();


    if (
        $queried_object
        instanceof
        WP_Term
    ) {

        /**
         * Als de TFSC main combo snippet aanwezig is,
         * alleen taxonomies gebruiken die aan Vacature
         * gekoppeld en publiek bevraagbaar zijn.
         */

        if (
            function_exists(
                'tfsc_combo_taxonomy_allowed'
            )
            &&
            ! tfsc_combo_taxonomy_allowed(
                $queried_object
                    ->taxonomy
            )
        ) {

            return [];
        }


        $accordion_item =
            tfsc_get_archive_accordion_item(
                $queried_object
            );


        if (
            $accordion_item
        ) {

            $items[] =
                $accordion_item;
        }
    }


    return $items;
}


