                            }

                        }
                    );
            }
        );
        </script>

        <?php
    }
);

/**
 * ============================================================
 * TFSC - VOLLEDIG DYNAMISCHE VACATURE ARCHIEVEN
 * + SEARCH & FILTER PRO V3
 * + ALLEEN OPEN VACATURES
 * ============================================================
 *
 * ONBEPERKT AANTAL TAXONOMIES.
 * ONBEPERKT AANTAL TERMEN PER TAXONOMY.
 *
 *
 * ============================================================
 * VACATURESTATUS
 * ============================================================
 *
 * Alleen vacatures met:
 *
 * Taxonomy:
 * vac_status
 *
 * Term:
 * open
 *
 * worden weergegeven.
 *
 *
 * Daardoor worden vacatures met bijvoorbeeld:
 *
 * - Gesloten Oud
 * - Ingevuld
 *
 * automatisch uitgesloten.
 *
 *
 * De taxonomy "vac_status" is intern en wordt NIET
 * beschikbaar gemaakt als publieke combo-taxonomy.
 *
 *
 * ============================================================
 * ARCHITECTUUR
 * ============================================================
 *
 * NATIVE TAXONOMY:
 *
 * /functienaam/service-engineer/
 *
 *
 * VIRTUELE COMBO:
 *
 * /vacatures/functienaam/field-service-engineer/
 *
 *
 * MEERDERE TAXONOMIES:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * locatie/noord-brabant/
 *
 *
 * MEERDERE TERMEN BINNEN DEZELFDE TAXONOMY:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 * kennisgebied/mechanisch/
 * locatie/noord-brabant/
 * locatie/zuid-holland/
 *
 *
 * HIËRARCHISCHE TAXONOMY:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * locatie/noord-brabant/tilburg/
 * locatie/zuid-holland/rotterdam/
 *
 *
 * ============================================================
 * TAXONOMY MATCHING
 * ============================================================
 *
 * Verschillende taxonomies:
 *
 * AND
 *
 *
 * Meerdere termen binnen één taxonomy:
 *
 * standaard OR
 *
 *
 * Uitzondering:
 *
 * kennisgebied = AND
 *
 *
 * ============================================================
 * SEARCH & FILTER
 * ============================================================
 *
 * /vacatures/
 *
 * is de interactieve Search & Filter resultatenpagina.
 *
 *
 * SEO landing page
 *      ↓
 * gebruiker wijzigt filter
 *      ↓
 * S&F get-results/start
 *      ↓
 * HARD PAGE LOAD naar:
 *
 * /vacatures/?_...
 *
 *      ↓
 *
 * vanaf /vacatures/
 * werkt Live Search verder via AJAX.
 *
 *
 * ============================================================
 * SHORTCODES
 * ============================================================
 *
 * [combo_heading]
 *
 * [combo_term taxonomy="functienaam"]
 * [combo_term taxonomy="kennisgebied"]
 * [combo_term taxonomy="locatie"]
 *
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

define(
    'TFSC_COMBO_BASE',
    'vacatures'
);

define(
    'TFSC_VACANCY_POST_TYPE',
    'vacature'
);

define(
    'TFSC_SEARCH_FILTER_QUERY_ID',
    1
);


/**
 * Vacaturestatus taxonomy.
 */
define(
    'TFSC_STATUS_TAXONOMY',
    'vac_status'
);


/**
 * Alleen deze status wordt als actief beschouwd.
 */
define(
    'TFSC_OPEN_STATUS_SLUG',
    'open'
);


/**
 * ============================================================
 * TAXONOMY MATCH METHOD
 * ============================================================
 *
 * Standaard:
 *
 * OR
 *
 * Bijvoorbeeld locaties:
 *
 * Noord-Brabant
 * OF
 * Zuid-Holland
 *
 *
 * kennisgebied:
 *
 * AND
 *
 * Bijvoorbeeld:
 *
 * Elektrotechniek
 * EN
 * Mechanisch
 */

function tfsc_get_combo_taxonomy_match_method(
    $taxonomy
) {

    $methods = [

        'kennisgebied' =>
            'AND',
    ];


    if (
        isset(
            $methods[
                $taxonomy
            ]
        )
    ) {

        return
            $methods[
                $taxonomy
            ];
    }


    return 'OR';
}


/**
 * ============================================================
 * 1. QUERY VARS
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. TAXONOMY MAG MEE DOEN?
 * ============================================================
 */

function tfsc_combo_taxonomy_allowed(
    $taxonomy
) {

    /**
     * --------------------------------------------------------
     * VACATURESTATUS IS INTERN
     * --------------------------------------------------------
     *
     * vac_status mag niet als normale SEO-taxonomy
     * in combo-URL's terechtkomen.
     */

    if (
        $taxonomy
        ===
        TFSC_STATUS_TAXONOMY
    ) {

        return false;
    }


    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {

        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {

        return false;
    }


    /**
     * Alleen publiek bevraagbare taxonomies.
     */
    if (
        ! $tax_object
            ->publicly_queryable
    ) {

        return false;
    }


    /**
     * Alleen taxonomies gekoppeld aan vacature.
     */
    if (
        ! in_array(
            TFSC_VACANCY_POST_TYPE,
            $tax_object->object_type,
            true
        )
    ) {

        return false;
    }


    return true;
}


/**
 * ============================================================
 * 3. ALLE TOEGESTANE COMBO TAXONOMIES
 * ============================================================
 */

function tfsc_get_allowed_combo_taxonomies() {

    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    $allowed =
        [];


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * 4. GENERIEKE REWRITE
 * ============================================================
 */

add_action(
    'init',
    function() {

        add_rewrite_rule(

            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )
            .
            '/(.+?)/?$',

            'index.php'
            .
            '?tfsc_combo_archive=1'
            .
            '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * 5. IS COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_is_combo_archive() {

    return (
        (bool)
        get_query_var(
            'tfsc_combo_archive'
        )
    );
}


/**
 * ============================================================
 * 6. IS TFSC SEO-LANDINGSPAGINA?
 * ============================================================
 */

function tfsc_is_vacancy_seo_landing() {

    /**
     * Virtuele combo.
     */
    if (
        tfsc_is_combo_archive()
        &&
        false
        !==
        tfsc_get_combo_archive()
    ) {

        return true;
    }


    /**
     * Native taxonomy.
     */
    if (
        is_tax()
    ) {

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            tfsc_combo_taxonomy_allowed(
                $queried_object->taxonomy
            )
        ) {

            return true;
        }
    }


    return false;
}


/**
 * ============================================================
 * 7. TERMPAD VALIDEREN
 * ============================================================
 *
 * Ondersteunt:
 *
 * tilburg
 *
 * noord-brabant/tilburg
 *
 * nederland/noord-brabant/tilburg
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
    ) {

        return false;
    }


    if (
        ! is_array(
            $segments
        )
        ||
        empty(
            $segments
        )
    ) {

        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        empty(
            $segments
        )
    ) {

        return false;
    }


    /**
     * Niet-hiërarchische taxonomy:
     *
     * exact één termsegment.
     */
    if (
        ! $tax_object->hierarchical
        &&
        count(
            $segments
        )
        !==
        1
    ) {

        return false;
    }


    $resolved_terms =
        [];


    $parent_id =
        0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term
            ||
            is_wp_error(
                $term
            )
        ) {

            return false;
        }


        /**
         * Vanaf niveau 2 moet de term rechtstreeks
         * child zijn van de voorgaande term.
         */
        if (
            $index > 0
            &&
            (int)
            $term->parent
            !==
            (int)
            $parent_id
        ) {

            return false;
        }


        $resolved_terms[] =
            $term;


        $parent_id =
            (int)
            $term->term_id;
    }


    return [

        'path' =>
            $resolved_terms,

        /**
         * Diepste term.
         */
        'term' =>
            end(
                $resolved_terms
            ),
    ];
}


/**
 * ============================================================
 * 8. VOLLEDIGE COMBO-URL PARSEN
 * ============================================================
 *
 * Dezelfde taxonomy mag meerdere keren voorkomen.
 *
 * Bijvoorbeeld:
 *
 * kennisgebied/elektrotechniek/
 * kennisgebied/mechanisch/
 *
 * of:
 *
 * locatie/noord-brabant/tilburg/
 * locatie/zuid-holland/rotterdam/
 */

function tfsc_get_combo_archive() {

    static $cache_set =
        false;


    static $cache =
        false;


    if (
        $cache_set
    ) {

        return $cache;
    }


    $cache_set =
        true;


    if (
        ! tfsc_is_combo_archive()
    ) {

        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if (
        ! $raw_path
    ) {

        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string)
                        $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    /**
     * Minimaal:
     *
     * taxonomy/term
     */
    if (
        count(
            $segments
        )
        <
        2
    ) {

        return false;
    }


    $allowed_taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if (
        empty(
            $allowed_taxonomies
        )
    ) {

        return false;
    }


    $items =
        [];


    $segment_count =
        count(
            $segments
        );


    $index =
        0;


    while (
        $index
        <
        $segment_count
    ) {

        /**
         * Ieder blok begint met taxonomy.
         */
        $taxonomy =
            sanitize_key(
                $segments[
                    $index
                ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed_taxonomies,
                true
            )
        ) {

            return false;
        }


        $index++;


        /**
         * Termsegmenten verzamelen totdat
         * de volgende taxonomy begint.
         */
        $term_segments =
            [];


        while (
            $index
            <
            $segment_count
        ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[
                        $index
                    ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed_taxonomies,
                    true
                )
            ) {

                break;
            }


            $term_segments[] =
                $segments[
                    $index
                ];


            $index++;
        }


        /**
         * Taxonomy zonder term is ongeldig.
         */
        if (
            empty(
                $term_segments
            )
        ) {

            return false;
        }


        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if (
            ! $resolved
        ) {

            return false;
        }


        /**
         * Ieder taxonomy/term-blok blijft
         * een afzonderlijk item.
         */
        $items[] = [

            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved[
                    'term'
                ],

            'path' =>
                $resolved[
                    'path'
                ],
        ];
    }


    if (
        empty(
            $items
        )
    ) {

        return false;
    }


    $cache =
        $items;


    return $cache;
}


/**
 * ============================================================
 * 9. WORDPRESS TAX_QUERY BOUWEN
 * ============================================================
 *
 * Verschillende taxonomies:
 *
 * AND
 *
 *
 * Binnen dezelfde taxonomy:
 *
 * standaard OR
 *
 *
 * kennisgebied:
 *
 * AND
 *
 *
 * EN ALTIJD:
 *
 * vac_status = open
 */

function tfsc_build_combo_tax_query() {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! $combo
    ) {

        return false;
    }


    /**
     * Eerst geselecteerde termen groeperen
     * per taxonomy.
     */
    $grouped =
        [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['term']
            )
            ||
            ! (
                $item['term']
                instanceof
                WP_Term
            )
        ) {

            continue;
        }


        $taxonomy =
            $item['taxonomy'];


        if (
            ! isset(
                $grouped[
                    $taxonomy
                ]
            )
        ) {

            $grouped[
                $taxonomy
            ] =
                [];
        }


        $term_id =
            (int)
            $item['term']
                ->term_id;


        if (
            ! in_array(
                $term_id,
                $grouped[
                    $taxonomy
                ],
                true
            )
        ) {

            $grouped[
                $taxonomy
            ][] =
                $term_id;
        }
    }


    if (
        empty(
            $grouped
        )
    ) {

        return false;
    }


    /**
     * ========================================================
     * BASIS:
     *
     * ALLEEN OPEN VACATURES
     * ========================================================
     */

    $tax_query = [

        'relation' =>
            'AND',

        [
            'taxonomy' =>
                TFSC_STATUS_TAXONOMY,

            'field' =>
                'slug',

            'terms' => [
                TFSC_OPEN_STATUS_SLUG,
            ],

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ],
    ];


    /**
     * ========================================================
     * OVERIGE COMBO TAXONOMIES
     * ========================================================
     */

    foreach (
        $grouped
        as $taxonomy => $term_ids
    ) {

        if (
            empty(
                $term_ids
            )
        ) {

            continue;
        }


        $tax_object =
            get_taxonomy(
                $taxonomy
            );


        $match_method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        /**
         * ----------------------------------------------------
         * AND
         * ----------------------------------------------------
         *
         * Vacature moet ALLE termen hebben.
         *
         * Bijvoorbeeld:
         *
         * Elektrotechniek
         * EN
         * Mechanisch
         */

        if (
            $match_method
            ===
            'AND'
            &&
            count(
                $term_ids
            )
            >
            1
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    $term_ids,

                'operator' =>
                    'AND',

                'include_children' =>
                    false,
            ];


            continue;
        }


        /**
         * ----------------------------------------------------
         * OR / IN
         * ----------------------------------------------------
         *
         * Vacature mag één van de termen hebben.
         *
         * Bijvoorbeeld:
         *
         * Noord-Brabant
         * OF
         * Zuid-Holland
         */

        $tax_query[] = [

            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            'operator' =>
                'IN',

            /**
             * Provincie neemt steden mee.
             */
            'include_children' =>
                (
                    $tax_object
                    &&
                    $tax_object
                        ->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/**
 * ============================================================
 * 10. ARCHIVE MAIN QUERY
 * ============================================================
 *
 * FILTERT:
 *
 * 1. virtuele combo-archieven
 * 2. native vacature-taxonomy-archieven
 *
 *
 * ALTIJD:
 *
 * vac_status = open
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin()
            ||
            ! $query->is_main_query()
        ) {

            return;
        }


        /**
         * ====================================================
         * A. VIRTUELE COMBO ARCHIVE
         * ====================================================
         */

        if (
            tfsc_is_combo_archive()
        ) {

            $tax_query =
                tfsc_build_combo_tax_query();


            if (
                ! $tax_query
            ) {

                return;
            }


            $query->set(
                'post_type',
                TFSC_VACANCY_POST_TYPE
            );


            $query->set(
                'post_status',
                'publish'
            );


            $query->set(
                'tax_query',
                $tax_query
            );


            $query->set(
                'no_found_rows',
                false
            );


            return;
        }


        /**
         * ====================================================
         * B. NATIVE VACATURE TAXONOMY ARCHIVE
         * ====================================================
         *
         * Bijvoorbeeld:
         *
         * /functienaam/service-engineer/
         *
         * Ook hier uitsluitend:
         *
         * vac_status = open
         */

        if (
            $query->is_tax()
        ) {

            $queried_object =
                $query->get_queried_object();


            if (
                ! (
                    $queried_object
                    instanceof
                    WP_Term
                )
            ) {

                return;
            }


            /**
             * Alleen publieke TFSC vacature-taxonomies.
             *
             * vac_status zelf valt hier automatisch buiten.
             */
            if (
                ! tfsc_combo_taxonomy_allowed(
                    $queried_object
                        ->taxonomy
                )
            ) {

                return;
            }


            $existing_tax_query =
                $query->get(
                    'tax_query'
                );


            if (
                ! is_array(
                    $existing_tax_query
                )
            ) {

                $existing_tax_query =
                    [];
            }


            /**
             * Status Open toevoegen.
             */
            $existing_tax_query[] = [

                'taxonomy' =>
                    TFSC_STATUS_TAXONOMY,

                'field' =>
                    'slug',

                'terms' => [
                    TFSC_OPEN_STATUS_SLUG,
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];


            $existing_tax_query[
                'relation'
            ] =
                'AND';


            $query->set(
                'post_type',
                TFSC_VACANCY_POST_TYPE
            );


            $query->set(
                'post_status',
                'publish'
            );


            $query->set(
                'tax_query',
                $existing_tax_query
            );
        }
    },
    1
);


/**
 * ============================================================
 * 11. ARCHIVE STATUS
 * ============================================================
 */

add_action(
    'wp',
    function() {

        if (
            ! tfsc_is_combo_archive()
            ||
            ! tfsc_get_combo_archive()
        ) {

            return;
        }


        global $wp_query;


        $wp_query->is_home =
            false;


        $wp_query->is_front_page =
            false;


        $wp_query->is_page =
            false;


        $wp_query->is_single =
            false;


        $wp_query->is_singular =
            false;


        $wp_query->is_search =
            false;


        $wp_query->is_404 =
            false;


        /**
         * Elementor moet dit herkennen
         * als archive.
         */
        $wp_query->is_archive =
            true;
    }
);


/**
 * ============================================================
 * 12. ONGELDIGE COMBO URL → 404
 * ============================================================
 */

add_action(
    'template_redirect',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {

            return;
        }


        if (
            tfsc_get_combo_archive()
        ) {

            return;
        }


        global $wp_query;


        $wp_query->set_404();


        status_header(
            404
        );


        nocache_headers();
    }
);


/**
 * ============================================================
 * 13. SEARCH & FILTER COMBO FIELD SYNC
 * + CURRENT SELECTION INITIAL SYNC
 * ============================================================
 *
 * Ondersteunt meerdere waarden:
 *
 * kennisgebied:
 *
 * [
 *   "elektrotechniek",
 *   "mechanisch"
 * ]
 *
 *
 * locatie:
 *
 * [
 *   "noord-brabant",
 *   "zuid-holland"
 * ]
 *
 *
 * BELANGRIJK:
 *
 * De combo-URL zet bij page load de actieve waarden
 * programmatisch in Search & Filter.
 *
 * Daarna wordt éénmalig een change-event gestuurd naar
 * de bijbehorende frontend inputs.
 *
 * Hierdoor kan Search & Filter ook onderdelen zoals
 * Current Selection direct opnieuw opbouwen.
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_combo_archive()
        ) {

            return;
        }


        $combo =
            tfsc_get_combo_archive();


        if (
            ! is_array(
                $combo
            )
            ||
            empty(
                $combo
            )
        ) {

            return;
        }


        $active_values =
            [];


        foreach (
            $combo
            as $item
        ) {

            if (
                empty(
                    $item['taxonomy']
                )
                ||
                empty(
                    $item['term']
                )
                ||
                ! (
                    $item['term']
                    instanceof
                    WP_Term
                )
                ||
                empty(
                    $item['term']->slug
                )
            ) {

                continue;
            }


            $taxonomy =
                $item['taxonomy'];


            $slug =
                $item['term']->slug;


            if (
                ! isset(
                    $active_values[
                        $taxonomy
                    ]
                )
            ) {

                $active_values[
                    $taxonomy
                ] =
                    [];
            }


            if (
                ! in_array(
                    $slug,
                    $active_values[
                        $taxonomy
                    ],
                    true
                )
            ) {

                $active_values[
                    $taxonomy
                ][] =
                    $slug;
            }
        }


        if (
            empty(
                $active_values
            )
        ) {

            return;
        }

        ?>

        <script>

        (function () {

            /**
             * =================================================
             * CONFIG
             * =================================================
             */

            const TFSC_COMBO_VALUES =
                <?php
                echo wp_json_encode(
                    $active_values
                );
                ?>;


            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            /**
             * Voorkomt dubbele synchronisatie.
             */
            let tfscApplying =
                false;


            let tfscInitialSyncDone =
                false;


            let tfscInitialChangeTriggered =
                false;


            /**
             * Wordt door onderdeel 14 gebruikt.
             */
            window.TFSC_SF_COMBO_READY =
                false;


            /**
             * =================================================
             * FIELDS OPHALEN
             * =================================================
             */

            function tfscGetSearchFilterFields() {

                const fieldsApi =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.fields;


                if (
                    ! fieldsApi
                    ||
                    typeof fieldsApi.getAll
                    !== 'function'
                ) {

                    return [];
                }


                let fields =
                    fieldsApi.getAll();


                if (
                    fields instanceof Map
                ) {

                    fields =
                        Array.from(
                            fields.values()
                        );
                }


                else if (
                    fields
                    &&
                    ! Array.isArray(
                        fields
                    )
                    &&
                    typeof fields
                    === 'object'
                ) {

                    fields =
                        Object.values(
                            fields
                        );
                }


                return Array.isArray(
                    fields
                )
                    ?
                fields
                    :
                [];
            }


            /**
             * =================================================
             * ARRAY GELIJKHEID
             * =================================================
             */

            function tfscSameValues(
                currentValues,
                wantedValues
            ) {

                const current =
                    Array.isArray(
                        currentValues
                    )
                        ?
                    currentValues
                        .map(
                            String
                        )
                        .sort()
                        :
                    [];


                const wanted =
                    Array.isArray(
                        wantedValues
                    )
                        ?
                    wantedValues
                        .map(
                            String
                        )
                        .sort()
                        :
                    [];


                if (
                    current.length
                    !==
                    wanted.length
                ) {

                    return false;
                }


                return current.every(
                    function(
                        value,
                        index
                    ) {

                        return (
                            value
                            ===
                            wanted[
                                index
                            ]
                        );
                    }
                );
            }


            /**
             * =================================================
             * SEARCH & FILTER FRONTEND INPUTS OPZOEKEN
             * =================================================
             *
             * We zoeken alleen inputs waarvan de value
             * overeenkomt met een actieve combo-term.
             *
             * Zo hoeven we niet afhankelijk te zijn van
             * interne S&F veld-ID's.
             */

            function tfscGetComboInputElements() {

                const elements =
                    [];


                Object.keys(
                    TFSC_COMBO_VALUES
                )
                .forEach(
                    function (taxonomy) {

                        const wantedValues =
                            TFSC_COMBO_VALUES[
                                taxonomy
                            ];


                        if (
                            ! Array.isArray(
                                wantedValues
                            )
                        ) {

                            return;
                        }


                        wantedValues.forEach(
                            function (wantedValue) {

                                /**
                                 * Search & Filter checkbox markup:
                                 *
                                 * .search-filter-input-checkbox
                                 * [data-option-value="slug"]
                                 */
                                const wrappers =
                                    document
                                        .querySelectorAll(
                                            '.search-filter-input-checkbox[data-option-value]'
                                        );


                                wrappers.forEach(
                                    function (wrapper) {

                                        if (
                                            String(
                                                wrapper
                                                    .dataset
                                                    .optionValue
                                            )
                                            !==
                                            String(
                                                wantedValue
                                            )
                                        ) {

                                            return;
                                        }


                                        const input =
                                            wrapper.querySelector(
                                                'input[type="checkbox"], input[type="radio"]'
                                            );


                                        if (
                                            input
                                            &&
                                            ! elements.includes(
                                                input
                                            )
                                        ) {

                                            elements.push(
                                                input
                                            );
                                        }
                                    }
                                );


                                /**
                                 * Selectvelden.
                                 */
                                const selects =
                                    document.querySelectorAll(
                                        'select'
                                    );


                                selects.forEach(
                                    function (select) {

                                        const hasWantedOption =
                                            Array.from(
                                                select.options
                                            )
                                            .some(
                                                function (
                                                    option
                                                ) {

                                                    return (
                                                        String(
                                                            option.value
                                                        )
                                                        ===
                                                        String(
                                                            wantedValue
                                                        )
                                                    );
                                                }
                                            );


                                        if (
                                            hasWantedOption
                                            &&
                                            ! elements.includes(
                                                select
                                            )
                                        ) {

                                            elements.push(
                                                select
                                            );
                                        }
                                    }
                                );

                            }
                        );
                    }
                );


                return elements;
            }


            /**
             * =================================================
             * CURRENT SELECTION / FRONTEND STATE TRIGGER
             * =================================================
             *
             * setValues() zet de S&F field state.
             *
             * Daarna sturen we éénmalig een echte change-event
             * naar de gekoppelde frontend controls.
             *
             * Search & Filter kan hierdoor zijn afhankelijke
             * controls, waaronder Current Selection, bijwerken.
             */

            function tfscTriggerInitialFieldChange() {

                if (
                    tfscInitialChangeTriggered
                ) {

                    return;
                }


                const elements =
                    tfscGetComboInputElements();


                if (
                    ! elements.length
                ) {

                    return;
                }


                tfscInitialChangeTriggered =
                    true;


                elements.forEach(
                    function (element) {

                        element.dispatchEvent(
                            new Event(
                                'change',
                                {
                                    bubbles: true
                                }
                            )
                        );

                    }
                );
            }


            /**
             * =================================================
             * COMBO → SEARCH & FILTER FIELD VALUES
             * =================================================
             */

            function tfscSyncComboValues() {

                if (
                    tfscApplying
                    ||
                    tfscInitialSyncDone
                ) {

                    return;
                }


                const fields =
                    tfscGetSearchFilterFields();


                if (
                    ! fields.length
                ) {

                    return;
                }


                tfscApplying =
                    true;


                let matchedFields =
                    0;


                fields.forEach(
                    function (field) {

                        if (
                            ! field
                            ||
                            typeof field.getAttributes
                                !== 'function'
                            ||
                            typeof field.getValues
                                !== 'function'
                            ||
                            typeof field.setValues
                                !== 'function'
                        ) {

                            return;
                        }


                        const attributes =
                            field.getAttributes();


                        if (
                            ! attributes
                        ) {

                            return;
                        }


                        /**
                         * Alleen Search & Filter Query #1.
                         */
                        if (
                            String(
                                attributes.queryId
                            )
                            !==
                            String(
                                TFSC_QUERY_ID
                            )
                        ) {

                            return;
                        }


                        /**
                         * Alleen taxonomy fields.
                         */
                        if (
                            attributes.dataType
                            !==
                            'taxonomy'
                        ) {

                            return;
                        }


                        const taxonomy =
                            attributes.dataTaxonomy;


                        if (
                            ! taxonomy
                            ||
                            ! Object.prototype
                                .hasOwnProperty
                                .call(
                                    TFSC_COMBO_VALUES,
                                    taxonomy
                                )
                        ) {

                            return;
                        }


                        const wantedValues =
                            TFSC_COMBO_VALUES[
                                taxonomy
                            ];


                        let currentValues =
                            field.getValues();


                        if (
                            ! Array.isArray(
                                currentValues
                            )
                        ) {

                            currentValues =
                                [];
                        }


                        matchedFields++;


                        /**
                         * Waarden al correct?
                         */
                        if (
                            tfscSameValues(
                                currentValues,
                                wantedValues
                            )
                        ) {

                            return;
                        }


                        /**
                         * Combo-values programmatisch
                         * in het S&F veld zetten.
                         */
                        field.setValues(
                            wantedValues
                        );
                    }
                );


                tfscApplying =
                    false;


                /**
                 * =================================================
                 * SYNC KLAAR
                 * =================================================
                 */

                if (
                    matchedFields > 0
                ) {

                    tfscInitialSyncDone =
                        true;


                    /**
                     * Eerst Search & Filter gelegenheid geven
                     * om zijn DOM te synchroniseren.
                     */
                    setTimeout(
                        function () {

                            tfscTriggerInitialFieldChange();

                        },
                        100
                    );


                    /**
                     * Tweede poging voor trager gerenderde
                     * Elementor / S&F controls.
                     */
                    setTimeout(
                        function () {

                            tfscTriggerInitialFieldChange();

                        },
                        250
                    );


                    /**
                     * Pas daarna de combo landing als klaar
                     * markeren.
                     */
                    setTimeout(
                        function () {

                            window
                                .TFSC_SF_COMBO_READY =
                                    true;

                        },
                        350
                    );
                }
            }


            /**
             * =================================================
             * SEARCH & FILTER MOUNT
             * =================================================
             */

            document.addEventListener(
                'search-filter/mount',
                function () {

                    setTimeout(
                        tfscSyncComboValues,
                        0
                    );


                    setTimeout(
                        tfscSyncComboValues,
                        100
                    );
                }
            );


            /**
             * =================================================
             * FALLBACK START
             * =================================================
             */

            function tfscStartComboSync() {

                setTimeout(
                    tfscSyncComboValues,
                    50
                );


                setTimeout(
                    tfscSyncComboValues,
                    250
                );


                setTimeout(
                    tfscSyncComboValues,
                    750
                );


                setTimeout(
                    tfscSyncComboValues,
                    1500
                );
            }


            if (
                document.readyState
                ===
                'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartComboSync
                );

            } else {

                tfscStartComboSync();
            }


        })();

        </script>

        <?php
    },
    90
);

/**
 * ============================================================
 * 14. SEO LANDING → EERSTE ECHTE FILTERACTIE = HARD PAGE LOAD
 * ============================================================
 *
 * BELANGRIJK:
 *
 * Alleen een ECHTE gebruikersactie mag een redirect veroorzaken.
 *
 * Programmatische wijzigingen, zoals de initiële combo-sync
 * uit onderdeel 13, mogen NOOIT redirecten.
 *
 *
 * FLOW:
 *
 * Combo SEO landing
 *      ↓
 * JS synchroniseert filters
 *      ↓
 * GEEN redirect
 *
 *
 * Gebruiker wijzigt filter
 *      ↓
 * echte browser interaction (isTrusted)
 *      ↓
 * S&F get-results/start
 *      ↓
 * HARD PAGE LOAD naar /vacatures/?...
 */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_vacancy_seo_landing()
        ) {

            return;
        }


        $is_combo =
            tfsc_is_combo_archive();

        ?>

        <script>

        (function () {

            /**
             * =================================================
             * CONFIG
             * =================================================
             */

            const TFSC_QUERY_ID =
                <?php
                echo (int)
                    TFSC_SEARCH_FILTER_QUERY_ID;
                ?>;


            const TFSC_IS_COMBO =
                <?php
                echo $is_combo
                    ?
                'true'
                    :
                'false';
                ?>;


            /**
             * =================================================
             * STATE
             * =================================================
             */

            let tfscRedirectAttached =
                false;


            let tfscRedirectStarted =
                false;


            /**
             * Wordt alleen TRUE wanneer een bezoeker
             * daadwerkelijk een filter bedient.
             *
             * Programmatische dispatchEvent() calls hebben:
             *
             * event.isTrusted === false
             *
             * en worden dus genegeerd.
             */
            let tfscRealUserInteraction =
                false;


            /**
             * =================================================
             * ECHTE GEBRUIKERSACTIE DETECTEREN
             * =================================================
             */

            function tfscRegisterRealUserInteraction(
                event
            ) {

                if (
                    ! event
                    ||
                    event.isTrusted !== true
                ) {

                    return;
                }


                const target =
                    event.target;


                if (
                    ! target
                    ||
                    typeof target.closest
                        !== 'function'
                ) {

                    return;
                }


                /**
                 * Alleen interacties binnen Search & Filter.
                 *
                 * De selectors zijn bewust breed genoeg voor
                 * verschillende S&F V3 field types.
                 */
                const searchFilterElement =
                    target.closest(
                        [
                            '.search-filter-field',
                            '[class*="search-filter-"]'
                        ].join(',')
                    );


                if (
                    ! searchFilterElement
                ) {

                    return;
                }


                tfscRealUserInteraction =
                    true;
            }


            /**
             * Change:
             *
             * checkbox
             * radio
             * select
             */
            document.addEventListener(
                'change',
                tfscRegisterRealUserInteraction,
                true
            );


            /**
             * Input:
             *
             * zoekvelden
             * tekstvelden
             * nummers
             * etc.
             */
            document.addEventListener(
                'input',
                tfscRegisterRealUserInteraction,
                true
            );


            /**
             * Klikken op speciale controls.
             */
            document.addEventListener(
                'click',
                tfscRegisterRealUserInteraction,
                true
            );


            /**
             * =================================================
             * FIELDS NORMALISEREN
             * =================================================
             */

            function tfscNormalizeFields(
                fields
            ) {

                if (
                    ! fields
                ) {

                    return [];
                }


                if (
                    fields instanceof Map
                ) {

                    return Array.from(
                        fields.values()
                    );
                }


                if (
                    Array.isArray(
                        fields
                    )
                ) {

                    return fields;
                }


                if (
                    typeof fields
                    === 'object'
                ) {

                    return Object.values(
                        fields
                    );
                }


                return [];
            }


            /**
             * =================================================
             * RESULTATEN-URL BOUWEN
             * =================================================
             */

            function tfscBuildResultsUrl(
                query
            ) {

                if (
                    ! query
                    ||
                    typeof query.getUrl
                        !== 'function'
                    ||
                    typeof query.getFields
                        !== 'function'
                ) {

                    return null;
                }


                const baseUrl =
                    query.getUrl();


                if (
                    ! baseUrl
                ) {

                    return null;
                }


                const fields =
                    tfscNormalizeFields(
                        query.getFields()
                    );


                const prefix =
                    window
                        .searchAndFilterData
                        ?.urlPrefix
                    ||
                    '_';


                const parts =
                    [];


                fields.forEach(
                    function( field ) {

                        if (
                            ! field
                            ||
                            typeof field.getUrlName
                                !== 'function'
                            ||
                            typeof field.getUrlValues
                                !== 'function'
                        ) {

                            return;
                        }


                        const urlName =
                            field.getUrlName();


                        let values =
                            field.getUrlValues();


                        if (
                            ! urlName
                        ) {

                            return;
                        }


                        if (
                            values !== null
                            &&
                            values !== undefined
                            &&
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values = [
                                values
                            ];
                        }


                        if (
                            ! Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [];
                        }


                        values =
                            values.filter(
                                function(
                                    value
                                ) {

                                    return (
                                        value
                                        !== null
                                        &&
                                        value
                                        !== undefined
                                        &&
                                        String(
                                            value
                                        )
                                        !== ''
                                    );
                                }
                            );


                        if (
                            ! values.length
                        ) {

                            return;
                        }


                        const encodedValues =
                            values
                                .map(
                                    function(
                                        value
                                    ) {

                                        return encodeURIComponent(
                                            String(
                                                value
                                            )
                                        );
                                    }
                                )
                                .join(
                                    ','
                                );


                        const parameterName =
                            prefix
                            +
                            urlName;


                        parts.push(
                            encodeURIComponent(
                                parameterName
                            )
                            +
                            '='
                            +
                            encodedValues
                        );
                    }
                );


                /**
                 * Search & Filter active URL arg.
                 */
                if (
                    typeof query.getActiveUrlArg
                    === 'function'
                ) {

                    const activeArg =
                        query
                            .getActiveUrlArg();


                    if (
                        activeArg
                    ) {

                        parts.push(
                            encodeURIComponent(
                                activeArg
                            )
                        );
                    }
                }


                /**
                 * Querystring verwijderen van base URL.
                 */
                const cleanBase =
                    String(
                        baseUrl
                    )
                    .split(
                        '#'
                    )[0]
                    .split(
                        '?'
                    )[0];


                if (
                    ! parts.length
                ) {

                    return cleanBase;
                }


                return (
                    cleanBase
                    +
                    '?'
                    +
                    parts.join(
                        '&'
                    )
                );
            }


            /**
             * =================================================
             * REDIRECT KOPPELEN
             * =================================================
             */

            function tfscAttachLandingRedirect() {

                if (
                    tfscRedirectAttached
                ) {

                    return true;
                }


                const queries =
                    window
                        .searchAndFilter
                        ?.frontend
                        ?.queries;


                if (
                    ! queries
                    ||
                    typeof queries.get
                        !== 'function'
                ) {

                    return false;
                }


                const query =
                    queries.get(
                        TFSC_QUERY_ID
                    );


                if (
                    ! query
                    ||
                    typeof query.on
                        !== 'function'
                ) {

                    return false;
                }


                tfscRedirectAttached =
                    true;


                /**
                 * ---------------------------------------------
                 * SEARCH & FILTER START RESULTATEN
                 * ---------------------------------------------
                 */

                query.on(
                    'get-results/start',
                    function() {

                        /**
                         * Redirect al begonnen?
                         */
                        if (
                            tfscRedirectStarted
                        ) {

                            return;
                        }


                        /**
                         * =================================================
                         * CRUCIALE BEVEILIGING
                         * =================================================
                         *
                         * Geen echte gebruikersactie?
                         *
                         * DAN NOOIT REDIRECTEN.
                         *
                         * Hierdoor mag onderdeel 13 rustig:
                         *
                         * field.setValues()
                         *
                         * en:
                         *
                         * dispatchEvent(new Event('change'))
                         *
                         * uitvoeren.
                         */
                        if (
                            tfscRealUserInteraction
                            !==
                            true
                        ) {

                            return;
                        }


                        /**
                         * Extra beveiliging voor combo-sync.
                         */
                        if (
                            TFSC_IS_COMBO
                            &&
                            window
                                .TFSC_SF_COMBO_READY
                                !==
                                true
                        ) {

                            return;
                        }


                        const targetUrl =
                            tfscBuildResultsUrl(
                                query
                            );


                        if (
                            ! targetUrl
                        ) {

                            return;
                        }


                        tfscRedirectStarted =
                            true;


                        window.location.href =
                            targetUrl;
                    }
                );


                return true;
            }


            /**
             * =================================================
             * SEARCH & FILTER MOUNT
             * =================================================
             */

            document.addEventListener(
                'search-filter/mount',
                function() {

                    setTimeout(
                        tfscAttachLandingRedirect,
                        150
                    );


                    setTimeout(
                        tfscAttachLandingRedirect,
                        400
                    );
                }
            );


            /**
             * =================================================
             * FALLBACK INITIALISATIE
             * =================================================
             */

            function tfscStartLandingRedirect() {

                setTimeout(
                    tfscAttachLandingRedirect,
                    250
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    750
                );


                setTimeout(
                    tfscAttachLandingRedirect,
                    1500
                );
            }


            if (
                document.readyState
                ===
                'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscStartLandingRedirect
                );

            } else {

                tfscStartLandingRedirect();
            }


        })();

        </script>

        <?php
    },
    100
);

