/**
 * ============================================================
 * 17. ARCHIVE / COMBO HEADING
 * ============================================================
 *
 * [combo_heading]
 *
 *
 * COMBO:
 *
 * Automatisch opgebouwd uit de geselecteerde termen.
 *
 *
 * NATIVE TAXONOMY:
 *
 * Eerst:
 *
 * pods_archive_title
 *
 * indien gevuld.
 *
 * Anders:
 *
 * Termnaam vacatures
 */

add_shortcode(
    'combo_heading',
    function() {

        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                $grouped =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {

                        continue;
                    }


                    $taxonomy =
                        $item[
                            'taxonomy'
                        ];


                    $term_name =
                        trim(
                            $item[
                                'term'
                            ]->name
                        );


                    if (
                        $term_name === ''
                    ) {

                        continue;
                    }


                    if (
                        ! isset(
                            $grouped[
                                $taxonomy
                            ]
                        )
                    ) {

                        $grouped[
                            $taxonomy
                        ] =
                            [];
                    }


                    if (
                        ! in_array(
                            $term_name,
                            $grouped[
                                $taxonomy
                            ],
                            true
                        )
                    ) {

                        $grouped[
                            $taxonomy
                        ][] =
                            $term_name;
                    }
                }


                if (
                    empty(
                        $grouped
                    )
                ) {

                    return '';
                }


                $rows =
                    [];


                /**
                 * Functienaam eerst.
                 */
                if (
                    ! empty(
                        $grouped[
                            'functienaam'
                        ]
                    )
                ) {

                    $function_names =
                        $grouped[
                            'functienaam'
                        ];


                    if (
                        count(
                            $function_names
                        )
                        ===
                        1
                    ) {

                        $rows[] =
                            $function_names[0]
                            .
                            ' vacatures';

                    } else {

                        $rows[] =
                            'Vacatures';


                        $rows[] =
                            implode(
                                ', ',
                                $function_names
                            );
                    }


                    unset(
                        $grouped[
                            'functienaam'
                        ]
                    );

                } else {

                    $rows[] =
                        'Vacatures';
                }


                /**
                 * Overige taxonomies.
                 */
                foreach (
                    $grouped
                    as $taxonomy => $term_names
                ) {

                    if (
                        empty(
                            $term_names
                        )
                    ) {

                        continue;
                    }


                    $rows[] =
                        implode(
                            ', ',
                            $term_names
                        );
                }


                if (
                    empty(
                        $rows
                    )
                ) {

                    return '';
                }


                /**
                 * HTML.
                 */
                $html =
                    '<span class="tfsc-heading">'
                    .
                    "\n";


                foreach (
                    $rows
                    as $index => $row
                ) {

                    $class =
                        (
                            $index === 0
                        )
                        ?
                        'tfsc-heading__main'
                        :
                        'tfsc-heading__row';


                    $html .=
                        '<span class="'
                        .
                        esc_attr(
                            $class
                        )
                        .
                        '">'
                        .
                        esc_html(
                            $row
                        )
                        .
                        '</span>'
                        .
                        "\n";
                }


                $html .=
                    '</span>';


                return $html;
            }
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
        ) {

            $taxonomy =
                $queried_object
                    ->taxonomy;


            if (
                $taxonomy
                &&
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $taxonomy
                )
            ) {

                /**
                 * Pods alternatieve archive title.
                 */
                $alternative_title =
                    get_term_meta(
                        $queried_object
                            ->term_id,
                        'pods_archive_title',
                        true
                    );


                if (
                    is_string(
                        $alternative_title
                    )
                ) {

                    $alternative_title =
                        trim(
                            wp_strip_all_tags(
                                $alternative_title
                            )
                        );

                } else {

                    $alternative_title =
                        '';
                }


                if (
                    $alternative_title !== ''
                ) {

                    $archive_title =
                        $alternative_title;

                } else {

                    $term_name =
                        trim(
                            $queried_object
                                ->name
                        );


                    if (
                        $term_name === ''
                    ) {

                        return '';
                    }


                    $archive_title =
                        $term_name
                        .
                        ' vacatures';
                }


                return

                    '<span class="tfsc-heading">'
                    .
                    "\n"
                    .
                    '<span class="tfsc-heading__main">'
                    .
                    esc_html(
                        $archive_title
                    )
                    .
                    '</span>'
                    .
                    "\n"
                    .
                    '</span>';
            }
        }


        /**
         * ----------------------------------------------------
         * 3. VACATURE POST TYPE ARCHIVE
         * ----------------------------------------------------
         */

        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {

            return

                '<span class="tfsc-heading">'
                .
                "\n"
                .
                '<span class="tfsc-heading__main">'
                .
                esc_html(
                    'Vacatures'
                )
                .
                '</span>'
                .
                "\n"
                .
                '</span>';
        }


        return '';
    }
);


/**
 * ============================================================
 * 18. SPECIFIEKE ARCHIVE / COMBO TERM
 * ============================================================
 *
 * [combo_term taxonomy="kennisgebied"]
 *
 *
 * Eén waarde:
 *
 * Elektrotechniek
 *
 *
 * Meerdere waarden:
 *
 * Elektrotechniek • Mechanisch
 *
 *
 * Andere separator:
 *
 * [combo_term
 * taxonomy="kennisgebied"
 * separator=", "]
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',

                    'separator' =>
                        ' • ',
                ],
                $atts,
                'combo_term'
            );


        $wanted_taxonomy =
            sanitize_key(
                $atts[
                    'taxonomy'
                ]
            );


        if (
            ! $wanted_taxonomy
        ) {

            return '';
        }


        /**
         * ----------------------------------------------------
         * 1. COMBO ARCHIVE
         * ----------------------------------------------------
         */

        if (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        ) {

            $combo =
                tfsc_get_combo_archive();


            if (
                is_array(
                    $combo
                )
                &&
                ! empty(
                    $combo
                )
            ) {

                $names =
                    [];


                foreach (
                    $combo
                    as $item
                ) {

                    if (
                        empty(
                            $item['taxonomy']
                        )
                        ||
                        $item['taxonomy']
                        !==
                        $wanted_taxonomy
                    ) {

                        continue;
                    }


                    if (
                        empty(
                            $item['term']
                        )
                        ||
                        ! (
                            $item['term']
                            instanceof
                            WP_Term
                        )
                    ) {

                        continue;
                    }


                    $name =
                        trim(
                            $item['term']->name
                        );


                    if (
                        $name === ''
                    ) {

                        continue;
                    }


                    if (
                        ! in_array(
                            $name,
                            $names,
                            true
                        )
                    ) {

                        $names[] =
                            $name;
                    }
                }


                if (
                    empty(
                        $names
                    )
                ) {

                    return '';
                }


                return esc_html(
                    implode(
                        (string)
                        $atts[
                            'separator'
                        ],
                        $names
                    )
                );
            }


            return '';
        }


        /**
         * ----------------------------------------------------
         * 2. NATIVE TAXONOMY ARCHIVE
         * ----------------------------------------------------
         */

        $queried_object =
            get_queried_object();


        if (
            $queried_object
            instanceof
            WP_Term
            &&
            $queried_object
                ->taxonomy
            ===
            $wanted_taxonomy
        ) {

            if (
                function_exists(
                    'tfsc_combo_taxonomy_allowed'
                )
                &&
                tfsc_combo_taxonomy_allowed(
                    $queried_object
                        ->taxonomy
                )
            ) {

                return esc_html(
                    $queried_object
                        ->name
                );
            }
        }


        return '';
    }
);

/**
 * ============================================================
 * TFSC - TAXONOMY ARCHIEVEN IN WORDPRESS LINKZOEKER
 * ============================================================
 *
 * Voegt de native taxonomy-term archieven van het post type
 * "vacature" toe aan de normale WordPress interne linkzoeker.
 *
 *
 * Voorbeeld:
 *
 * Zoeken naar:
 * Field Service Engineer
 *
 * Geeft onder andere:
 *
 * Field Service Engineer — Functienaam
 *
 * Linkt naar het native taxonomy-archief:
 *
 * /functienaam/field-service-engineer/
 *
 *
 * De virtuele /vacatures/... combo-archieven worden
 * bewust NIET toegevoegd.
 */


add_filter(
    'wp_link_query',
    function( $results, $query ) {

        /**
         * Zoekterm ophalen.
         */
        $search =
            isset(
                $query['s']
            )
                ?
            trim(
                (string)
                $query['s']
            )
                :
            '';


        /**
         * Alleen taxonomy-termen toevoegen
         * wanneer daadwerkelijk wordt gezocht.
         */
        if (
            $search === ''
        ) {
            return $results;
        }


        /**
         * ----------------------------------------------------
         * TOEGESTANE TAXONOMIES
         * ----------------------------------------------------
         *
         * Als de TFSC main snippet beschikbaar is,
         * gebruiken we exact dezelfde toegestane taxonomies.
         */

        if (
            function_exists(
                'tfsc_get_allowed_combo_taxonomies'
            )
        ) {

            $taxonomies =
                tfsc_get_allowed_combo_taxonomies();

        } else {

            /**
             * Fallback:
             * alle taxonomies van vacature.
             */
            $taxonomies =
                get_object_taxonomies(
                    'vacature',
                    'names'
                );
        }


        if (
            empty(
                $taxonomies
            )
        ) {
            return $results;
        }


        /**
         * ----------------------------------------------------
         * TERMEN ZOEKEN
         * ----------------------------------------------------
         */

        $terms =
            get_terms(
                [
                    'taxonomy' =>
                        $taxonomies,

                    'hide_empty' =>
                        false,

                    'search' =>
                        $search,

                    'number' =>
                        30,
                ]
            );


        if (
            is_wp_error(
                $terms
            )
            ||
            empty(
                $terms
            )
        ) {

            return $results;
        }


        /**
         * ----------------------------------------------------
         * RESULTATEN TOEVOEGEN
         * ----------------------------------------------------
         */

        foreach (
            $terms
            as $term
        ) {

            if (
                ! (
                    $term
                    instanceof
                    WP_Term
                )
            ) {
                continue;
            }


            $term_link =
                get_term_link(
                    $term
                );


            if (
                is_wp_error(
                    $term_link
                )
            ) {
                continue;
            }


            $taxonomy =
                get_taxonomy(
                    $term->taxonomy
                );


            $taxonomy_label =
                (
                    $taxonomy
                    &&
                    ! empty(
                        $taxonomy
                            ->labels
                            ->singular_name
                    )
                )
                    ?
                $taxonomy
                    ->labels
                    ->singular_name
                    :
                $term->taxonomy;


            $results[] = [

                'ID' =>
                    'term-'
                    .
                    $term->taxonomy
                    .
                    '-'
                    .
                    $term->term_id,

                'title' =>
                    $term->name,

                'permalink' =>
                    $term_link,

                'info' =>
                    $taxonomy_label,
            ];
        }


        return $results;
    },
    20,
    2
);

/**
 * ============================================================
 * TFSC - DYNAMISCHE ARCHIVE DESCRIPTION ACCORDION
 * ============================================================
 *
 * Shortcode:
 *
 * [tfsc_archive_accordion]
 *
 *
 * Werkt op:
 *
 * - native taxonomy archives
 * - virtuele TFSC combo archives
 *
 *
 * Per aanwezige term-description wordt automatisch
 * één accordion-item opgebouwd.
 *
 *
 * TITELLOGICA:
 *
 * 1. Pods term field:
 *    pods_archive_title
 *
 * 2. Als leeg:
 *    actieve termnaam
 *
 *
 * Voorbeelden:
 *
 * Field Service Engineer
 * Elektrotechniek
 * Mechanisch
 * Noord-Brabant
 * Zuid-Holland
 *
 *
 * CONTENT:
 *
 * WordPress taxonomy term description
 */


/**
 * ============================================================
 * 1. ACCORDION ITEM DATA VAN ÉÉN TERM
 * ============================================================
 */

function tfsc_get_archive_accordion_item(
    $term
) {

    if (
        ! (
            $term
            instanceof
            WP_Term
        )
    ) {
        return false;
    }


    /**
     * --------------------------------------------------------
     * DESCRIPTION
     * --------------------------------------------------------
     */

    $description =
        term_description(
            $term->term_id,
            $term->taxonomy
        );


    $description =
        trim(
            (string)
            $description
        );


    /**
     * Geen description:
     * geen accordion-item.
     */
    if (
        $description === ''
    ) {
        return false;
    }


    /**
     * --------------------------------------------------------
     * CUSTOM PODS ARCHIVE TITLE
     * --------------------------------------------------------
     *
     * Pods field:
     *
     * pods_archive_title
     */

    $title =
        get_term_meta(
            $term->term_id,
            'pods_archive_title',
            true
        );


    if (
        is_string(
            $title
        )
    ) {

        $title =
            trim(
                wp_strip_all_tags(
                    $title
                )
            );

    } else {

        $title =
            '';
    }


    /**
     * --------------------------------------------------------
     * FALLBACK:
     * ACTIEVE TERMNAAM
     * --------------------------------------------------------
     *
     * Als pods_archive_title niet is ingevuld,
     * gebruiken we de werkelijke actieve term.
     *
     * Bijvoorbeeld:
     *
     * Field Service Engineer
     * Elektrotechniek
     * Mechanisch
     * Noord-Brabant
     */

    if (
        $title === ''
    ) {

        $title =
            trim(
                $term->name
            );
    }


    /**
     * Ook geen termnaam beschikbaar:
     * item niet tonen.
     */
    if (
        $title === ''
    ) {
        return false;
    }


    return [

        'title' =>
            $title,

        'description' =>
            $description,

        'term_id' =>
            (int)
            $term->term_id,

        'taxonomy' =>
            $term->taxonomy,
    ];
}


/**
 * ============================================================
 * 2. ALLE RELEVANTE ACCORDION ITEMS OPHALEN
 * ============================================================
 *
 * Werkt volledig zelfstandig voor:
 *
 * A. virtuele TFSC combo archives
 * B. native vacature taxonomy archives
 *
 * Native archives zijn NIET afhankelijk van
 * tfsc_combo_taxonomy_allowed().
 */

function tfsc_get_archive_accordion_items() {

    $items =
        [];


    /**
     * Hiermee voorkomen we dubbele termen.
     */
    $seen =
        [];


    /**
     * ========================================================
     * A. VIRTUEEL COMBO ARCHIVE
     * ========================================================
     */

    if (
        function_exists(
            'tfsc_is_combo_archive'
        )
        &&
        function_exists(
            'tfsc_get_combo_archive'
        )
        &&
        tfsc_is_combo_archive()
    ) {

        $combo =
            tfsc_get_combo_archive();


        if (
            is_array(
                $combo
            )
            &&
            ! empty(
                $combo
            )
        ) {

            foreach (
                $combo
                as $combo_item
            ) {

                if (
                    empty(
                        $combo_item['term']
                    )
                    ||
                    ! (
                        $combo_item['term']
                        instanceof
                        WP_Term
                    )
                ) {

                    continue;
                }


                $term =
                    $combo_item['term'];


                /**
                 * Unieke taxonomy + term combinatie.
                 */
                $unique_key =
                    $term->taxonomy
                    .
                    ':'
                    .
                    $term->term_id;


                if (
                    isset(
                        $seen[
                            $unique_key
                        ]
                    )
                ) {

                    continue;
                }


                $accordion_item =
                    tfsc_get_archive_accordion_item(
                        $term
                    );


                if (
                    ! $accordion_item
                ) {

                    continue;
                }


                $seen[
                    $unique_key
                ] =
                    true;


                $items[] =
                    $accordion_item;
            }
        }


        return $items;
    }


    /**
     * ========================================================
     * B. NATIVE TAXONOMY ARCHIVE
     * ========================================================
     *
     * Bijvoorbeeld:
     *
     * /functienaam/field-service-engineer/
     * /kennisgebied/elektrotechniek/
     * /bedrijfssector/machinebouw/
     * /locatie/noord-brabant/
     *
     * Deze controle staat bewust LOS van de combo-URL logica.
     */

    if (
        ! is_tax()
    ) {

        return [];
    }


    $queried_object =
        get_queried_object();


    if (
        ! (
            $queried_object
            instanceof
            WP_Term
        )
    ) {

        return [];
    }


    $taxonomy =
        $queried_object
            ->taxonomy;


    /**
     * Taxonomy moet bestaan.
     */
    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {

        return [];
    }


    /**
     * Interne vacaturestatus nooit als
     * inhoudelijk archive tonen.
     */
    if (
        defined(
            'TFSC_STATUS_TAXONOMY'
        )
        &&
        $taxonomy
        ===
        TFSC_STATUS_TAXONOMY
    ) {

        return [];
    }


    /**
     * Taxonomy-object ophalen.
     */
    $taxonomy_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $taxonomy_object
    ) {

        return [];
    }


    /**
     * Alleen taxonomies die daadwerkelijk
     * gekoppeld zijn aan post type vacature.
     */
    $vacancy_post_type =
        defined(
            'TFSC_VACANCY_POST_TYPE'
        )
            ?
        TFSC_VACANCY_POST_TYPE
            :
        'vacature';


    if (
        ! in_array(
            $vacancy_post_type,
            $taxonomy_object
                ->object_type,
            true
        )
    ) {

        return [];
    }


    /**
     * Accordion-item maken.
     */
    $accordion_item =
        tfsc_get_archive_accordion_item(
            $queried_object
        );


    if (
        $accordion_item
    ) {

        $items[] =
            $accordion_item;
    }


    return $items;
}

/**
 * ============================================================
 * 3. SHORTCODE
 * ============================================================
 *
 * Gebruik in Elementor:
 *
 * [tfsc_archive_accordion]
 */

add_shortcode(
    'tfsc_archive_accordion',
    function() {

        $items =
            tfsc_get_archive_accordion_items();


        /**
         * Geen descriptions aanwezig:
         * helemaal niets renderen.
         */
        if (
            empty(
                $items
            )
        ) {

            return '';
        }


        /**
         * Uniek instance nummer.
         *
         * Hierdoor kan de shortcode eventueel
         * meerdere keren op dezelfde pagina staan.
         */
        static $instance =
            0;


        $instance++;


        $accordion_id =
            'tfsc-archive-accordion-'
            .
            $instance;


        ob_start();

        ?>

        <div
            id="<?php echo esc_attr( $accordion_id ); ?>"
            class="tfsc-archive-accordion"
        >

            <?php

            foreach (
                $items
                as $index => $item
            ) :

                $item_id =
                    $accordion_id
                    .
                    '-item-'
                    .
                    $index;


                $button_id =
                    $item_id
                    .
                    '-button';


                $content_id =
                    $item_id
                    .
                    '-content';

                ?>

                <div
                    class="tfsc-archive-accordion__item"
                    data-taxonomy="<?php echo esc_attr( $item['taxonomy'] ); ?>"
                    data-term-id="<?php echo esc_attr( $item['term_id'] ); ?>"
                >

                    <!--
                    ==================================================
                    ACCORDION TITLE
                    ==================================================
                    -->

                    <button
                        type="button"
                        id="<?php echo esc_attr( $button_id ); ?>"
                        class="tfsc-archive-accordion__title"
                        aria-expanded="false"
                        aria-controls="<?php echo esc_attr( $content_id ); ?>"
                    >

                        <span
                            class="tfsc-archive-accordion__title-text"
                        >
                            <?php

                            echo esc_html(
                                $item['title']
                            );

                            ?>
                        </span>


                        <span
                            class="tfsc-archive-accordion__chevron"
                            aria-hidden="true"
                        ></span>

                    </button>


                    <!--
                    ==================================================
                    ACCORDION CONTENT
                    ==================================================
                    -->

                    <div
                        id="<?php echo esc_attr( $content_id ); ?>"
                        class="tfsc-archive-accordion__content"
                        role="region"
                        aria-labelledby="<?php echo esc_attr( $button_id ); ?>"
                        hidden
                    >

                        <div
                            class="tfsc-archive-accordion__content-inner"
                        >

                            <?php

                            /**
                             * Taxonomy description.
                             *
                             * Veilige WordPress HTML blijft toegestaan:
                             *
                             * p
                             * strong
                             * em
                             * links
                             * lists
                             * etc.
                             */

                            echo wp_kses_post(
                                $item[
                                    'description'
                                ]
                            );

                            ?>

                        </div>

                    </div>

                </div>

                <?php

            endforeach;

            ?>

        </div>


        <script>
        (function () {

            /**
             * ========================================================
             * TFSC ARCHIVE ACCORDION
             * ========================================================
             */

            const accordion =
                document.getElementById(
                    <?php
                    echo wp_json_encode(
                        $accordion_id
                    );
                    ?>
                );


            if (!accordion) {
                return;
            }


            /**
             * Klik op een accordiontitel.
             */
            accordion.addEventListener(
                'click',
                function (event) {

                    const button =
                        event.target.closest(
                            '.tfsc-archive-accordion__title'
                        );


                    if (
                        ! button
                        ||
                        ! accordion.contains(
                            button
                        )
                    ) {

                        return;
                    }


                    const item =
                        button.closest(
                            '.tfsc-archive-accordion__item'
                        );


                    if (!item) {
                        return;
                    }


                    const content =
                        item.querySelector(
                            '.tfsc-archive-accordion__content'
                        );


                    if (!content) {
                        return;
                    }


                    const isOpen =
                        button.getAttribute(
                            'aria-expanded'
                        )
                        ===
                        'true';


                    /**
                     * ARIA status.
                     */
                    button.setAttribute(
                        'aria-expanded',
                        isOpen
                            ?
                            'false'
                            :
                            'true'
                    );


                    /**
                     * CSS class.
                     */
                    item.classList.toggle(
                        'tfsc-archive-accordion__item--open',
                        !isOpen
                    );


                    /**
                     * Content tonen/verbergen.
                     */
                    content.hidden =
                        isOpen;
                }
            );

        })();
        </script>

        <?php

        return ob_get_clean();
    }
);

/**
 * ============================================================
 * TFSC - ARCHIVE INFO CONTAINER ZICHTBAARHEID
 * ============================================================
 *
 * Elementor container class:
 *
 * tfsc-archive-info
 *
 *
 * LOGICA:
 *
 * Accordion aanwezig:
 * → container tonen
 *
 * Geen accordion aanwezig:
 * → container verbergen
 *
 *
 * Wordt opnieuw gecontroleerd wanneer Elementor /
 * Search & Filter later content in de DOM plaatst.
 */

add_action(
    'wp_footer',
    function() {
        ?>

        <script>
        (function () {

            /**
             * =================================================
             * CONTAINERS CONTROLEREN
             * =================================================
             */

            function tfscRefreshArchiveInfo() {

                document
                    .querySelectorAll(
                        '.tfsc-archive-info'
                    )
                    .forEach(
                        function (container) {

                            const accordion =
                                container.querySelector(
                                    '.tfsc-archive-accordion'
                                );


                            /**
                             * Accordion aanwezig:
                             * empty-class VERWIJDEREN.
                             *
                             * Accordion niet aanwezig:
                             * empty-class TOEVOEGEN.
                             */
                            container.classList.toggle(
                                'tfsc-archive-info-empty',
                                !accordion
                            );

                        }
                    );
            }


            /**
             * =================================================
             * EERSTE LOAD
             * =================================================
             */

            if (
                document.readyState
                ===
                'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    tfscRefreshArchiveInfo
                );

            } else {

                tfscRefreshArchiveInfo();
            }


            /**
             * Nogmaals controleren nadat Elementor
             * zijn frontend heeft opgebouwd.
             */
            setTimeout(
                tfscRefreshArchiveInfo,
                100
            );


            setTimeout(
                tfscRefreshArchiveInfo,
                500
            );


            setTimeout(
                tfscRefreshArchiveInfo,
                1000
            );


            /**
             * =================================================
             * SEARCH & FILTER
             * =================================================
             *
             * Als Search & Filter onderdelen opnieuw mount.
             */

            document.addEventListener(
                'search-filter/mount',
                function () {

                    setTimeout(
                        tfscRefreshArchiveInfo,
                        50
                    );


                    setTimeout(
                        tfscRefreshArchiveInfo,
                        250
                    );

                }
            );


            /**
             * =================================================
             * DOM UPDATES
             * =================================================
             *
             * Elementor / S&F kan later onderdelen toevoegen
             * of vervangen.
             *
             * Daarom controleren we opnieuw bij DOM-wijzigingen.
             */

            let tfscArchiveInfoTimer =
                null;


            const observer =
                new MutationObserver(
                    function () {

                        clearTimeout(
                            tfscArchiveInfoTimer
                        );


                        tfscArchiveInfoTimer =
                            setTimeout(
                                tfscRefreshArchiveInfo,
                                50
                            );

                    }
                );


            observer.observe(
                document.body,
                {
                    childList: true,
                    subtree: true
                }
            );

        })();
        </script>

        <?php
    },
    120
);

/**
 * ============================================================
 * TFSC - DYNAMISCHE ARCHIVE DESCRIPTION ACCORDION
 * ============================================================
 *
 * Shortcode:
 *
 * [tfsc_archive_accordion]
 *
 *
 * Werkt op:
 *
 * - native taxonomy archives
 * - virtuele TFSC combo archives
 *
 *
 * Per aanwezige term-description wordt automatisch
 * één accordion-item opgebouwd.
 *
 *
 * TITELLOGICA:
 *
 * 1. Pods term field:
 *    pods_archive_title
 *
 * 2. Als leeg:
 *    actieve termnaam
 *
 *
 * CONTENT:
 *
 * WordPress taxonomy term description
 */


/**
 * ============================================================
 * 1. ACCORDION ITEM DATA VAN ÉÉN TERM
 * ============================================================
 */

function tfsc_get_archive_accordion_item(
    $term
) {

    if (
        ! (
            $term
            instanceof
            WP_Term
        )
    ) {
        return false;
    }


    /**
     * --------------------------------------------------------
     * DESCRIPTION
     * --------------------------------------------------------
     */

    $description =
        term_description(
            $term->term_id,
            $term->taxonomy
        );


    $description =
        trim(
            (string)
            $description
        );


    /**
     * Geen description:
     * geen accordion-item.
     */
    if (
        $description === ''
    ) {
        return false;
    }


    /**
     * --------------------------------------------------------
     * CUSTOM PODS ARCHIVE TITLE
     * --------------------------------------------------------
     *
     * Pods field:
     *
     * pods_archive_title
     */

    $title =
        get_term_meta(
            $term->term_id,
            'pods_archive_title',
            true
        );


    if (
        is_string(
            $title
        )
    ) {

        $title =
            trim(
                wp_strip_all_tags(
                    $title
                )
            );

    } else {

        $title =
            '';
    }


    /**
     * --------------------------------------------------------
     * FALLBACK:
     * ACTIEVE TERMNAAM
     * --------------------------------------------------------
     */

    if (
        $title === ''
    ) {

        $title =
            trim(
                $term->name
            );
    }


    /**
     * Ook geen termnaam:
     * item niet tonen.
     */
    if (
        $title === ''
    ) {
        return false;
    }


    return [

        'title' =>
            $title,

        'description' =>
            $description,

        'term_id' =>
            (int)
            $term->term_id,

        'taxonomy' =>
            $term->taxonomy,
    ];
}


/**
 * ============================================================
 * 2. ALLE RELEVANTE ACCORDION ITEMS OPHALEN
 * ============================================================
 *
 * A. virtuele TFSC combo archives
 * B. native vacature taxonomy archives
 */

function tfsc_get_archive_accordion_items() {

    $items =
        [];


    /**
     * Dubbele termen voorkomen.
     */
    $seen =
        [];


    /**
     * ========================================================
     * A. VIRTUEEL COMBO ARCHIVE
     * ========================================================
     */

    if (
        function_exists(
            'tfsc_is_combo_archive'
        )
        &&
        function_exists(
            'tfsc_get_combo_archive'
        )
        &&
        tfsc_is_combo_archive()
    ) {

        $combo =
            tfsc_get_combo_archive();


        if (
            is_array(
                $combo
            )
            &&
            ! empty(
                $combo
            )
        ) {

            foreach (
                $combo
                as $combo_item
            ) {

                if (
                    empty(
                        $combo_item['term']
                    )
                    ||
                    ! (
                        $combo_item['term']
                        instanceof
                        WP_Term
                    )
                ) {

                    continue;
                }


                $term =
                    $combo_item['term'];


                /**
                 * Unieke taxonomy + term combinatie.
                 */
                $unique_key =
                    $term->taxonomy
                    .
                    ':'
                    .
                    $term->term_id;


                if (
                    isset(
                        $seen[
                            $unique_key
                        ]
                    )
                ) {

                    continue;
                }


                $accordion_item =
                    tfsc_get_archive_accordion_item(
                        $term
                    );


                if (
                    ! $accordion_item
                ) {

                    continue;
                }


                $seen[
                    $unique_key
                ] =
                    true;


                $items[] =
                    $accordion_item;
            }
        }


        return $items;
    }


    /**
     * ========================================================
     * B. NATIVE TAXONOMY ARCHIVE
     * ========================================================
     */

    if (
        ! is_tax()
    ) {

        return [];
    }


    $queried_object =
        get_queried_object();


    if (
        ! (
            $queried_object
            instanceof
            WP_Term
        )
    ) {

        return [];
    }


    $taxonomy =
        $queried_object
            ->taxonomy;


    /**
     * Taxonomy moet bestaan.
     */
    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {

        return [];
    }


    /**
     * Interne vacaturestatus uitsluiten.
     */
    $status_taxonomy =
        defined(
            'TFSC_STATUS_TAXONOMY'
        )
            ?
        TFSC_STATUS_TAXONOMY
            :
        'vac_status';


    if (
        $taxonomy
        ===
        $status_taxonomy
    ) {

        return [];
    }


    /**
     * Taxonomy-object ophalen.
     */
    $taxonomy_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $taxonomy_object
    ) {

        return [];
    }


    /**
     * Alleen taxonomies die aan vacature gekoppeld zijn.
     */
    $vacancy_post_type =
        defined(
            'TFSC_VACANCY_POST_TYPE'
        )
            ?
        TFSC_VACANCY_POST_TYPE
            :
        'vacature';


    if (
        ! in_array(
            $vacancy_post_type,
            (array)
            $taxonomy_object
                ->object_type,
            true
        )
    ) {

        return [];
    }


    /**
     * Native archive heeft één actieve term.
     */
    $accordion_item =
        tfsc_get_archive_accordion_item(
            $queried_object
        );


    if (
        $accordion_item
    ) {

        $items[] =
            $accordion_item;
    }


    return $items;
}


/**
 * ============================================================
 * 3. SHORTCODE
 * ============================================================
 *
 * Gebruik:
 *
 * [tfsc_archive_accordion]
 */

add_shortcode(
    'tfsc_archive_accordion',
    function() {

        $items =
            tfsc_get_archive_accordion_items();


        /**
         * Geen descriptions:
         * shortcode rendert niets.
         */
        if (
            empty(
                $items
            )
        ) {

            return '';
        }


        /**
         * Uniek instance nummer.
         */
        static $instance =
            0;


        $instance++;


        $accordion_id =
            'tfsc-archive-accordion-'
            .
            $instance;


        ob_start();

        ?>

        <div
            id="<?php echo esc_attr( $accordion_id ); ?>"
            class="tfsc-archive-accordion"
        >

            <?php

            foreach (
                $items
                as $index => $item
            ) :

                $item_id =
                    $accordion_id
                    .
                    '-item-'
                    .
                    $index;


                $button_id =
                    $item_id
                    .
                    '-button';


                $content_id =
                    $item_id
                    .
                    '-content';

                ?>

                <div
                    class="tfsc-archive-accordion__item"
                    data-taxonomy="<?php echo esc_attr( $item['taxonomy'] ); ?>"
                    data-term-id="<?php echo esc_attr( $item['term_id'] ); ?>"
                >

                    <button
                        type="button"
                        id="<?php echo esc_attr( $button_id ); ?>"
                        class="tfsc-archive-accordion__title"
                        aria-expanded="false"
                        aria-controls="<?php echo esc_attr( $content_id ); ?>"
                    >

                        <span
                            class="tfsc-archive-accordion__title-text"
                        >
                            <?php

                            echo esc_html(
                                $item['title']
                            );

                            ?>
                        </span>


                        <span
                            class="tfsc-archive-accordion__chevron"
                            aria-hidden="true"
                        ></span>

                    </button>


                    <div
                        id="<?php echo esc_attr( $content_id ); ?>"
                        class="tfsc-archive-accordion__content"
                        role="region"
                        aria-labelledby="<?php echo esc_attr( $button_id ); ?>"
                        hidden
                    >

                        <div
                            class="tfsc-archive-accordion__content-inner"
                        >

                            <?php

                            echo wp_kses_post(
                                $item[
                                    'description'
                                ]
                            );

                            ?>

                        </div>

                    </div>

                </div>

                <?php

            endforeach;

            ?>

        </div>


        <script>
        (function () {

            const accordion =
                document.getElementById(
                    <?php
                    echo wp_json_encode(
                        $accordion_id
                    );
                    ?>
                );


            if (!accordion) {
                return;
            }


            accordion.addEventListener(
                'click',
                function (event) {

                    const button =
                        event.target.closest(
                            '.tfsc-archive-accordion__title'
                        );


                    if (
                        ! button
                        ||
                        ! accordion.contains(
                            button
                        )
                    ) {

                        return;
                    }


                    const item =
                        button.closest(
                            '.tfsc-archive-accordion__item'
                        );


                    if (!item) {

                        return;
                    }


                    const content =
                        item.querySelector(
                            '.tfsc-archive-accordion__content'
                        );


                    if (!content) {

                        return;
                    }


                    const isOpen =
                        button.getAttribute(
                            'aria-expanded'
                        )
                        ===
                        'true';


                    /**
                     * ARIA-status.
                     */
                    button.setAttribute(
                        'aria-expanded',
                        isOpen
                            ? 'false'
                            : 'true'
                    );


                    /**
                     * Open-class.
                     */
                    item.classList.toggle(
                        'tfsc-archive-accordion__item--open',
                        !isOpen
                    );


                    /**
                     * Content tonen/verbergen.
                     */
                    content.hidden =
                        isOpen;
                }
            );

        })();
        </script>

        <?php

        return ob_get_clean();
    }
);


