/**
 * TFSC - Archive title without prefix + optional term override [v2.0]
 *
 * Source snippet ID: 39
 * Scope: global
 *
 * Taxonomy term archives may provide a custom visible archive heading in
 * term meta field `pods_archive_title`. When the field is empty or missing,
 * the normal term name remains the fallback.
 *
 * This filter controls Elementors dynamic Archive Title tag. It does not
 * change the term name, slug, URL, breadcrumb or Rank Math SEO title.
 */

add_filter( 'elementor/utils/get_the_archive_title', function( $title ) {

    if ( is_category() ) {
        return single_cat_title( '', false );
    }

    if ( is_tag() ) {
        return single_tag_title( '', false );
    }

    if ( is_tax() ) {

        $term = get_queried_object();

        if ( $term instanceof WP_Term ) {

            $override = get_term_meta(
                $term->term_id,
                'pods_archive_title',
                true
            );

            $override = is_string( $override )
                ? trim( wp_strip_all_tags( $override ) )
                : '';

            if ( '' !== $override ) {
                return $override;
            }
        }

        return single_term_title( '', false );
    }

    if ( is_post_type_archive() ) {
        return post_type_archive_title( '', false );
    }

    return $title;
});

/**
 * TFSC - Rank Math breadcrumbs voor echte taxonomy-archieven
 *
 * DOEL
 * ----
 * WordPress/Pods kan een taxonomy een custom rewrite slug geven, bijvoorbeeld:
 *
 *   beroepen
 *   beroepengids/functie-inhoud
 *
 * De URL wordt dan bijvoorbeeld:
 *
 *   /beroepen/commissioning-engineer/
 *
 * of:
 *
 *   /beroepengids/functie-inhoud/inbedrijfstellen/
 *
 * Rank Math ziet de onderdelen van de rewrite slug niet automatisch als
 * afzonderlijke breadcrumb-niveaus.
 *
 * Deze snippet maakt daar automatisch van:
 *
 *   Home > Beroepen > Commissioning Engineer
 *
 * of:
 *
 *   Home > Beroepengids > Functie-inhoud > Inbedrijfstellen
 *
 *
 * BELANGRIJK
 * ----------
 * De snippet werkt ALLEEN op het echte/native WordPress taxonomy-archief.
 *
 * Hiervoor wordt de huidige URL vergeleken met get_term_link().
 * Virtuele/combo-archieven met een andere URL, zoals:
 *
 *   /vacatures/functienaam/commissioning-engineer/
 *
 * worden daardoor niet aangepast.
 *
 *
 * EXTRA
 * -----
 * - Werkt automatisch voor alle taxonomies.
 * - Geen taxonomy-namen handmatig toevoegen.
 * - Werkt met één of meerdere niveaus in de rewrite slug.
 * - Werkt ook met parent/child terms.
 * - Pagination (/page/2/) wordt ondersteund.
 */


add_filter( 'rank_math/frontend/breadcrumb/items', function( $crumbs, $class ) {

    /*
     * Alleen uitvoeren wanneer WordPress de huidige pagina
     * daadwerkelijk als taxonomy-archief herkent.
     */
    if ( ! is_tax() ) {
        return $crumbs;
    }


    /*
     * Huidige term ophalen.
     */
    $term = get_queried_object();

    if (
        ! $term ||
        is_wp_error( $term ) ||
        empty( $term->taxonomy )
    ) {
        return $crumbs;
    }


    /*
     * De echte WordPress-URL van deze term ophalen.
     */
    $term_url = get_term_link( $term );

    if ( is_wp_error( $term_url ) ) {
        return $crumbs;
    }


    /*
     * Controleren of we echt op het originele taxonomy-archief staan.
     *
     * Hierdoor worden bijvoorbeeld TFSC combo-archive URL's niet geraakt,
     * ook wanneer daarin dezelfde taxonomy/term wordt gebruikt.
     */
    $native_path = wp_parse_url( $term_url, PHP_URL_PATH );

    $current_path = wp_parse_url(
        $_SERVER['REQUEST_URI'],
        PHP_URL_PATH
    );

    /*
     * Eventuele pagination verwijderen uit de huidige URL,
     * bijvoorbeeld /page/2/.
     */
    $current_path = preg_replace(
        '#/page/[0-9]+/?$#',
        '/',
        $current_path
    );

    $native_path  = untrailingslashit( $native_path );
    $current_path = untrailingslashit( $current_path );

    if ( $native_path !== $current_path ) {
        return $crumbs;
    }


    /*
     * Taxonomy-configuratie ophalen.
     */
    $taxonomy = get_taxonomy( $term->taxonomy );

    if (
        ! $taxonomy ||
        empty( $taxonomy->rewrite['slug'] )
    ) {
        return $crumbs;
    }


    /*
     * Custom rewrite slug ophalen.
     *
     * Voorbeelden:
     *
     * beroepen
     *
     * beroepengids/functie-inhoud
     */
    $rewrite_slug = trim(
        $taxonomy->rewrite['slug'],
        '/'
    );

    if ( $rewrite_slug === '' ) {
        return $crumbs;
    }


    /*
     * Rewrite slug opdelen in afzonderlijke breadcrumb-niveaus.
     *
     * beroepengids/functie-inhoud
     *
     * wordt:
     *
     * beroepengids
     * functie-inhoud
     */
    $segments = array_values(
        array_filter(
            explode( '/', $rewrite_slug )
        )
    );


    /*
     * Nieuwe breadcrumb opbouwen.
     */
    $new_crumbs = [];


    /*
     * Bestaande Home breadcrumb van Rank Math behouden.
     */
    if ( ! empty( $crumbs[0] ) ) {
        $new_crumbs[] = $crumbs[0];
    }


    /*
     * Rewrite slug toevoegen aan de breadcrumb.
     */
    $path = '';

    foreach ( $segments as $segment ) {

        $path .= '/' . $segment;

        /*
         * Van bijvoorbeeld:
         *
         * functie-inhoud
         *
         * maken we:
         *
         * Functie-inhoud
         */
        $label = ucfirst(
            str_replace(
                '_',
                ' ',
                $segment
            )
        );

        $new_crumbs[] = [
            $label,
            home_url( $path . '/' ),
        ];
    }


    /*
     * Als de taxonomy hiërarchisch is:
     * eventuele parent terms toevoegen.
     */
    if ( is_taxonomy_hierarchical( $term->taxonomy ) ) {

        $ancestors = array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        );

        foreach ( $ancestors as $ancestor_id ) {

            $ancestor = get_term(
                $ancestor_id,
                $term->taxonomy
            );

            if (
                ! $ancestor ||
                is_wp_error( $ancestor )
            ) {
                continue;
            }

            $ancestor_url = get_term_link( $ancestor );

            if ( is_wp_error( $ancestor_url ) ) {
                continue;
            }

            $new_crumbs[] = [
                $ancestor->name,
                $ancestor_url,
            ];
        }
    }


    /*
     * Huidige term als laatste breadcrumb.
     * Geen URL nodig omdat dit de huidige pagina is.
     */
    $new_crumbs[] = [
        $term->name,
        '',
    ];


    return $new_crumbs;

}, 10, 2 );

/**
 * TFSC - Taxonomy Base Archives + Elementor Theme Builder Condition
 *
 * DOEL
 * ============================================================
 * WordPress kent standaard:
 *
 *   /beroepengids/functie-inhoud/term/
 *
 * als archive van één specifieke taxonomy term.
 *
 * Maar WordPress kent standaard NIET:
 *
 *   /beroepengids/functie-inhoud/
 *
 * als overzichtsarchive van de taxonomy zelf.
 *
 * Deze snippet voegt dat ontbrekende niveau toe.
 *
 *
 * VOORBEELD
 * ============================================================
 * In Pods staat bij een taxonomy:
 *
 *   Custom Rewrite Slug:
 *   beroepengids/functie-inhoud
 *
 * Dan ontstaat automatisch:
 *
 *   /beroepengids/functie-inhoud/
 *
 * als TFSC Taxonomy Base Archive.
 *
 * De bestaande term-URL blijft gewoon:
 *
 *   /beroepengids/functie-inhoud/inbedrijfstellen/
 *
 *
 * REWRITE SLUG IS LEIDEND
 * ============================================================
 * De snippet leest automatisch de rewrite slug van WordPress/Pods.
 *
 * Dus:
 *
 *   beroepen
 *
 * geeft:
 *
 *   /beroepen/
 *
 * En:
 *
 *   beroepengids/functie-inhoud
 *
 * geeft:
 *
 *   /beroepengids/functie-inhoud/
 *
 * Je hoeft taxonomy-namen of URL's dus niet handmatig in deze
 * snippet te onderhouden.
 *
 *
 * ELEMENTOR THEME BUILDER
 * ============================================================
 * Deze snippet voegt bij Elementor Pro een nieuwe Archive
 * Display Condition toe:
 *
 *   Archives
 *   → TFSC Taxonomy Base Archives
 *
 * Daardoor kun je één Elementor Archive Template koppelen aan
 * al deze nieuwe taxonomy-overzichten.
 *
 *
 * QUERY VAR
 * ============================================================
 * Op zo'n archive bevat:
 *
 *   get_query_var( 'tfsc_taxonomy_archive' )
 *
 * automatisch de interne taxonomy name.
 *
 * Die gebruiken we later ook voor de TFSC Term Loop Grid.
 *
 *
 * BESTAANDE ARCHIEVEN
 * ============================================================
 * Deze snippet verandert NIET:
 *
 * - normale taxonomy term archives;
 * - CPT archives;
 * - Posts / Pages;
 * - TFSC combo archives;
 * - bestaande combo-archive breadcrumbs.
 *
 * De rewrite matcht alleen exact de taxonomy rewrite-basis.
 *
 *
 * URL-CONFLICTEN
 * ============================================================
 * Eén URL kan niet tegelijk twee verschillende archives zijn.
 *
 * Als bijvoorbeeld /beroepen/ al een CPT archive is en een
 * taxonomy óók rewrite slug "beroepen" krijgt, is er een conflict.
 *
 * Gebruik daarom voor taxonomies unieke rewrite bases wanneer nodig.
 *
 *
 * NA ACTIVEREN
 * ============================================================
 * Ga EENMALIG naar:
 *
 *   WordPress → Instellingen → Permalinks
 *
 * en klik:
 *
 *   Wijzigingen opslaan
 *
 * Dit is nodig om WordPress de nieuwe rewrite rules direct te
 * laten opslaan.
 */


/* ============================================================
 * 1. TFSC QUERY VAR REGISTREREN
 * ============================================================
 */

add_filter( 'query_vars', function( $vars ) {

    $vars[] = 'tfsc_taxonomy_archive';

    return $vars;

} );


/* ============================================================
 * 2. TAXONOMY BASE REWRITE RULES REGISTREREN
 * ============================================================
 */

add_action( 'init', function() {

    $taxonomies = get_taxonomies(
        [
            'public' => true,
        ],
        'objects'
    );

    foreach ( $taxonomies as $taxonomy ) {

        /*
         * Alleen taxonomies gebruiken die een rewrite hebben.
         */
        if (
            empty( $taxonomy->rewrite ) ||
            empty( $taxonomy->rewrite['slug'] )
        ) {
            continue;
        }

        $rewrite_slug = trim(
            $taxonomy->rewrite['slug'],
            '/'
        );

        if ( $rewrite_slug === '' ) {
            continue;
        }

        /*
         * Exact de taxonomy-basis matchen.
         *
         * beroepengids/functie-inhoud
         *
         * matcht dus:
         *
         * /beroepengids/functie-inhoud/
         *
         * maar NIET:
         *
         * /beroepengids/functie-inhoud/term/
         */
        $regex =
            '^' .
            preg_quote( $rewrite_slug, '#' ) .
            '/?$';

        add_rewrite_rule(
            $regex,
            'index.php?tfsc_taxonomy_archive=' .
                urlencode( $taxonomy->name ),
            'top'
        );
    }

}, 99 );


/* ============================================================
 * 3. VIRTUELE TAXONOMY-PAGINA ALS ARCHIVE MARKEREN
 * ============================================================
 */

add_action( 'parse_query', function( $query ) {

    $taxonomy_name = $query->get(
        'tfsc_taxonomy_archive'
    );

    if ( ! $taxonomy_name ) {
        return;
    }

    $taxonomy = get_taxonomy(
        $taxonomy_name
    );

    if (
        ! $taxonomy ||
        empty( $taxonomy->public )
    ) {
        return;
    }

    /*
     * Alle conflicterende WordPress-conditionals uitschakelen.
     */
    $query->is_home          = false;
    $query->is_front_page    = false;
    $query->is_singular      = false;
    $query->is_page          = false;
    $query->is_single        = false;
    $query->is_search        = false;
    $query->is_404           = false;

    /*
     * Dit is voor WordPress/Elementor een archive.
     */
    $query->is_archive = true;

}, 20 );


/* ============================================================
 * 4. 404-AFHANDELING VOORKOMEN
 * ============================================================
 *
 * Omdat dit een virtuele archive-URL is en geen echte post/page
 * bestaat, voorkomen we dat WordPress hem later alsnog als 404
 * behandelt.
 */

add_filter( 'pre_handle_404', function( $preempt, $wp_query ) {

    if (
        $wp_query->get( 'tfsc_taxonomy_archive' )
    ) {

        $taxonomy_name = $wp_query->get(
            'tfsc_taxonomy_archive'
        );

        $taxonomy = get_taxonomy(
            $taxonomy_name
        );

        if (
            $taxonomy &&
            ! empty( $taxonomy->public )
        ) {

            $wp_query->is_404    = false;
            $wp_query->is_archive = true;

            status_header( 200 );

            return true;
        }
    }

    return $preempt;

}, 10, 2 );


/* ============================================================
 * 5. GEEN NORMALE POSTS OPHALEN VOOR DE MAIN QUERY
 * ============================================================
 *
 * De taxonomy-base archive is bedoeld om taxonomy terms te tonen.
 * De toekomstige TFSC Term Loop Grid haalt die terms zelf op.
 */

add_action( 'pre_get_posts', function( $query ) {

    if (
        is_admin() ||
        ! $query->is_main_query()
    ) {
        return;
    }

    if (
        ! $query->get(
            'tfsc_taxonomy_archive'
        )
    ) {
        return;
    }

    /*
     * Laat de normale post-query geen echte content renderen.
     */
    $query->set(
        'post__in',
        [ 0 ]
    );

}, 20 );


/* ============================================================
 * 6. HELPERFUNCTIE: ACTIEVE TAXONOMY OPHALEN
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_get_current_taxonomy_archive'
    )
) {

    function tfsc_get_current_taxonomy_archive() {

        $taxonomy_name = get_query_var(
            'tfsc_taxonomy_archive'
        );

        if ( ! $taxonomy_name ) {
            return false;
        }

        $taxonomy = get_taxonomy(
            $taxonomy_name
        );

        return $taxonomy ?: false;
    }
}


/* ============================================================
 * 7. HELPERFUNCTIE: CONTROLEREN OF DIT EEN TFSC
 *    TAXONOMY BASE ARCHIVE IS
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_is_taxonomy_base_archive'
    )
) {

    function tfsc_is_taxonomy_base_archive() {

        return (
            (bool) get_query_var(
                'tfsc_taxonomy_archive'
            )
        );
    }
}


/* ============================================================
 * 8. ARCHIVE TITLE
 * ============================================================
 *
 * Voorbeeld:
 *
 * interne taxonomy:
 * functie_inhoud_beroep
 *
 * label:
 * Functie-inhoud
 *
 * archive title:
 * Functie-inhoud
 */

add_filter( 'get_the_archive_title', function( $title ) {

    $taxonomy = tfsc_get_current_taxonomy_archive();

    if ( ! $taxonomy ) {
        return $title;
    }

    if (
        ! empty(
            $taxonomy->labels->name
        )
    ) {
        return $taxonomy->labels->name;
    }

    return $title;

} );


/*
 * Elementor gebruikt voor zijn Archive Title Dynamic Tag
 * een eigen filter.
 */

add_filter(
    'elementor/utils/get_the_archive_title',
    function( $title ) {

        $taxonomy =
            tfsc_get_current_taxonomy_archive();

        if ( ! $taxonomy ) {
            return $title;
        }

        if (
            ! empty(
                $taxonomy->labels->name
            )
        ) {
            return $taxonomy->labels->name;
        }

        return $title;
    }
);


/* ============================================================
 * 9. BODY CLASSES
 * ============================================================
 *
 * Geeft bijvoorbeeld:
 *
 * tfsc-taxonomy-base-archive
 *
 * tfsc-taxonomy-base-archive--functie_inhoud_beroep
 */

add_filter( 'body_class', function( $classes ) {

    $taxonomy_name = get_query_var(
        'tfsc_taxonomy_archive'
    );

    if ( ! $taxonomy_name ) {
        return $classes;
    }

    $classes[] =
        'tfsc-taxonomy-base-archive';

    $classes[] =
        'tfsc-taxonomy-base-archive--' .
        sanitize_html_class(
            $taxonomy_name
        );

    return $classes;

} );


/* ============================================================
 * 10. ELEMENTOR PRO THEME BUILDER CONDITION
 * ============================================================
 *
 * Elementor Pro ondersteunt custom Theme Conditions.
 *
 * Deze condition verschijnt onder Archives als:
 *
 *   TFSC Taxonomy Base Archives
 *
 * Een Archive Template met deze condition wordt alleen toegepast
 * wanneer onze query var aanwezig is.
 */

add_action(
    'elementor/theme/register_conditions',
    function( $conditions_manager ) {

        /*
         * Elementor Pro moet actief zijn.
         */
        if (
            ! class_exists(
                '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base'
            )
        ) {
            return;
        }

        /*
         * Class maar één keer declareren.
         */
        if (
            ! class_exists(
                'TFSC_Elementor_Taxonomy_Base_Archive_Condition'
            )
        ) {

            class TFSC_Elementor_Taxonomy_Base_Archive_Condition
                extends
                \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                /*
                 * Deze condition hoort bij Archives.
                 */
                public static function get_type(): string {
                    return 'archive';
                }


                /*
                 * Positie binnen Elementor conditions.
                 */
                public static function get_priority(): int {
                    return 90;
                }


                /*
                 * Interne unieke naam.
                 */
                public function get_name(): string {
                    return 'tfsc_taxonomy_base_archive';
                }


                /*
                 * Naam die in Elementor wordt weergegeven.
                 */
                public function get_label(): string {
                    return 'TFSC Taxonomy Base Archives';
                }


                /*
                 * Elementor controleert hiermee of een template
                 * op de huidige pagina toegepast moet worden.
                 */
                public function check( $args ): bool {

                    return function_exists(
                        'tfsc_is_taxonomy_base_archive'
                    )
                        &&
                        tfsc_is_taxonomy_base_archive();
                }
            }
        }


        /*
         * Condition daadwerkelijk onder "Archives" registreren.
         */
        $archive_condition =
            $conditions_manager->get_condition(
                'archive'
            );

        if ( $archive_condition ) {

            $archive_condition->register_sub_condition(
                new TFSC_Elementor_Taxonomy_Base_Archive_Condition()
            );
        }
    },
    100
);

/**
 * TFSC - Connecties tonen in Pods Admin > Edit Pods
 *
 * DOEL
 * ============================================================
 * In:
 *
 *   Pods Admin > Edit Pods
 *
 * toont Pods standaard kolommen zoals:
 *
 *   Label | Name | Type | Storage Type | Groups | Fields
 *
 * Maar bij een Custom Taxonomy zie je daar niet direct aan welk
 * post type / CPT die taxonomy gekoppeld is.
 *
 * Deze snippet voegt daarom een extra kolom toe:
 *
 *   Connecties
 *
 * Voorbeelden:
 *
 *   Functie-Inhoud - Beroep
 *   → Beroepen
 *
 *   Functie-Inhoud - Vacature
 *   → Vacatures
 *
 * Als een taxonomy aan meerdere post types gekoppeld is:
 *
 *   Beroepen, Vacatures
 *
 *
 * HOE HET WERKT
 * ============================================================
 * WordPress bewaart bij iedere geregistreerde taxonomy de
 * gekoppelde post types in:
 *
 *   $taxonomy->object_type
 *
 * De PHP-code leest deze informatie rechtstreeks uit WordPress.
 *
 * Pods gebruikt voor "Edit Pods" geen normale WordPress
 * WP_List_Table-kolommen. Daarom voegen we de extra kolom alleen
 * visueel toe aan precies dit adminscherm.
 *
 *
 * BELANGRIJK
 * ============================================================
 * - Verandert GEEN Pods-instellingen.
 * - Verandert GEEN taxonomy-connecties.
 * - Verandert GEEN CPT's.
 * - Alleen zichtbaar in wp-admin.
 * - Werkt automatisch met alle geregistreerde taxonomies.
 * - Nieuwe of gewijzigde Pods-connecties worden automatisch
 *   weergegeven nadat de pagina opnieuw geladen wordt.
 * - Custom Post Type labels worden gebruikt in plaats van alleen
 *   technische namen.
 *
 *
 * CODE SNIPPETS
 * ============================================================
 * Deze snippet mag ingesteld worden op:
 *
 *   Only run in administration area
 */


add_action( 'admin_footer', function() {

    /*
     * Alleen uitvoeren op:
     *
     * Pods Admin > Edit Pods
     *
     * URL is normaal:
     * /wp-admin/admin.php?page=pods
     */
    if (
        ! isset( $_GET['page'] ) ||
        'pods' !== sanitize_key( $_GET['page'] )
    ) {
        return;
    }

    /*
     * Niet uitvoeren wanneer één individuele Pod wordt bewerkt.
     */
    if (
        isset( $_GET['action'] ) &&
        ! in_array(
            sanitize_key( $_GET['action'] ),
            [ '', 'manage' ],
            true
        )
    ) {
        return;
    }


    /*
     * Alle geregistreerde taxonomies ophalen.
     */
    $taxonomies = get_taxonomies(
        [],
        'objects'
    );

    $connections = [];


    foreach ( $taxonomies as $taxonomy ) {

        if (
            empty( $taxonomy->name ) ||
            empty( $taxonomy->object_type )
        ) {
            continue;
        }

        $labels = [];


        /*
         * Ieder gekoppeld post type omzetten naar
         * een leesbaar WordPress-label.
         */
        foreach ( $taxonomy->object_type as $post_type_name ) {

            $post_type = get_post_type_object(
                $post_type_name
            );

            if (
                $post_type &&
                ! empty( $post_type->labels->name )
            ) {
                $labels[] = $post_type->labels->name;
            } else {
                $labels[] = $post_type_name;
            }
        }


        $connections[ $taxonomy->name ] =
            array_values(
                array_unique( $labels )
            );
    }

    ?>

    <script>
    document.addEventListener('DOMContentLoaded', function () {

        const connections =
            <?php echo wp_json_encode( $connections ); ?>;


        function addTfscConnectionsColumn() {

            /*
             * Pods-overzichtstabel zoeken.
             */
            const tables = document.querySelectorAll(
                '.wrap table'
            );

            let table = null;


            tables.forEach(function(candidate) {

                const headers =
                    Array.from(
                        candidate.querySelectorAll('thead th')
                    ).map(function(th) {
                        return th.textContent.trim();
                    });


                /*
                 * Controleren of dit daadwerkelijk de
                 * Edit Pods tabel is.
                 */
                if (
                    headers.includes('Label') &&
                    headers.includes('Name') &&
                    headers.includes('Type') &&
                    headers.includes('Storage Type')
                ) {
                    table = candidate;
                }
            });


            if (!table) {
                return;
            }


            /*
             * Voorkomen dat de kolom meerdere keren wordt
             * toegevoegd.
             */
            if (
                table.querySelector(
                    '.tfsc-pods-connections-column'
                )
            ) {
                return;
            }


            const headerRow =
                table.querySelector('thead tr');

            if (!headerRow) {
                return;
            }


            /*
             * Bepalen in welke kolom "Name" staat.
             */
            const headerCells =
                Array.from(
                    headerRow.querySelectorAll('th')
                );

            const nameIndex =
                headerCells.findIndex(function(th) {
                    return th.textContent.trim() === 'Name';
                });


            if (nameIndex === -1) {
                return;
            }


            /*
             * Nieuwe header toevoegen.
             */
            const newHeader =
                document.createElement('th');

            newHeader.textContent = 'Connecties';
            newHeader.className =
                'tfsc-pods-connections-column';

            headerRow.appendChild(newHeader);


            /*
             * Iedere Pods-rij verwerken.
             */
            const rows =
                table.querySelectorAll('tbody tr');


            rows.forEach(function(row) {

                const cells =
                    row.querySelectorAll('td');

                if (!cells.length) {
                    return;
                }


                const nameCell =
                    cells[nameIndex];

                if (!nameCell) {
                    return;
                }


                /*
                 * Technische Pods-name uit de Name-kolom.
                 */
                const podName =
                    nameCell.textContent.trim();


                const newCell =
                    document.createElement('td');

                newCell.className =
                    'tfsc-pods-connections-column';


                /*
                 * Alleen taxonomies hebben in onze PHP-map
                 * een taxonomy → post type connectie.
                 */
                if (
                    Object.prototype.hasOwnProperty.call(
                        connections,
                        podName
                    ) &&
                    connections[podName].length
                ) {

                    newCell.textContent =
                        connections[podName].join(', ');

                } else {

                    newCell.textContent = '—';
                }


                row.appendChild(newCell);
            });
        }


        addTfscConnectionsColumn();

    });
    </script>

    <?php
} );

/**
 * TFSC - Terms tonen van het huidige Taxonomy Base Archive
 *
 * Gebruik in Elementor:
 *
 *   [tfsc_taxonomy_terms]
 *
 * De shortcode kijkt automatisch welke taxonomy actief is via:
 *
 *   get_query_var( 'tfsc_taxonomy_archive' )
 *
 * en toont vervolgens alle terms van die taxonomy.
 *
 * Werkt dus generiek voor:
 *
 *   /beroepengids/functie-inhoud/
 *   /beroepengids/kennisgebied/
 *   /beroepengids/functienaam/
 *
 * zonder dat je per taxonomy iets hoeft aan te passen.
 */

add_shortcode( 'tfsc_taxonomy_terms', function() {

    $taxonomy_name = get_query_var( 'tfsc_taxonomy_archive' );

    if ( ! $taxonomy_name ) {
        return '';
    }

    $taxonomy = get_taxonomy( $taxonomy_name );

    if ( ! $taxonomy ) {
        return '';
    }

    $terms = get_terms( [
        'taxonomy'   => $taxonomy_name,
        'hide_empty' => false,
        'orderby'    => 'name',
        'order'      => 'ASC',
    ] );

    if ( is_wp_error( $terms ) || empty( $terms ) ) {
        return '';
    }

    $output = '<div class="tfsc-taxonomy-terms">';

    foreach ( $terms as $term ) {

        $term_link = get_term_link( $term );

        if ( is_wp_error( $term_link ) ) {
            continue;
        }

        $output .= sprintf(
            '<a class="tfsc-taxonomy-term" href="%s">%s</a>',
            esc_url( $term_link ),
            esc_html( $term->name )
        );
    }

    $output .= '</div>';

    return $output;

} );

/**
 * TFSC - Elementor Taxonomy Loop filters
 *
 * ============================================================
 * BESCHIKBARE QUERY ID'S
 * ============================================================
 *
 * 1. TAXONOMY DIE IN DE ELEMENTOR LOOP IS GESELECTEERD
 * ------------------------------------------------------------
 *
 * taxonomy_level_0
 * taxonomy_level_1
 * taxonomy_level_2
 * enz.
 *
 * Voorbeeld:
 *
 * In Elementor selecteer je taxonomy "Locatie"
 * Query ID:
 *
 * taxonomy_level_1
 *
 * Dan toont Elementor alleen level 1 van Locatie.
 *
 *
 * 2. GERELATEERDE LOCATIES VANUIT HUIDIG BEROEP
 * ------------------------------------------------------------
 *
 * related_locaties_level_0
 * related_locaties_level_1
 * related_locaties_level_2
 *
 * Werking:
 *
 * huidig beroep
 *      ↓
 * functienaam
 *      ↓
 * vacatures met dezelfde functienaam
 *      ↓
 * locaties van die vacatures
 *      ↓
 * filter op gewenst level
 *
 * Deze bestaande functionaliteit blijft ongewijzigd.
 *
 *
 * 3. TAXONOMY VAN HET HUIDIGE TFSC TAXONOMY BASE ARCHIVE
 * ------------------------------------------------------------
 *
 * current_taxonomy
 *
 * Toont ALLE terms van de taxonomy van het huidige
 * TFSC Taxonomy Base Archive.
 *
 * Bijvoorbeeld:
 *
 * /beroepengids/functie-inhoud/
 *
 * Als dit archive hoort bij:
 *
 * beroep_functie-inhoud
 *
 * dan worden automatisch de terms van:
 *
 * beroep_functie-inhoud
 *
 * gebruikt.
 *
 *
 * Met level:
 *
 * current_taxonomy_level_0
 * current_taxonomy_level_1
 * current_taxonomy_level_2
 *
 *
 * Voorbeeld:
 *
 * current_taxonomy_level_0
 *
 * toont alleen top-level terms van de taxonomy die bij het
 * huidige taxonomy-base archive hoort.
 *
 *
 * ============================================================
 * LEVELS
 * ============================================================
 *
 * level_0 = term zonder parent
 * level_1 = child van level 0
 * level_2 = child van level 1
 * enz.
 *
 *
 * ============================================================
 * BELANGRIJK BIJ CURRENT TAXONOMY
 * ============================================================
 *
 * De TFSC Taxonomy Base Archive snippet zet:
 *
 * tfsc_taxonomy_archive
 *
 * op de interne WordPress/Pods taxonomy name.
 *
 * Deze loop-filter leest die waarde automatisch uit.
 *
 * Je hoeft dus bij current_taxonomy NIET zelf de taxonomy-name
 * in de Query ID te zetten.
 */


add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        if ( empty( $settings['term_taxonomy_id'] ) ) {
            return $args;
        }

        $query_id = sanitize_key(
            $settings['term_taxonomy_id']
        );


        /*
         * =========================================================
         * 1. NORMALE TAXONOMY LEVEL FILTER
         * =========================================================
         *
         * Query ID:
         *
         * taxonomy_level_0
         * taxonomy_level_1
         * taxonomy_level_2
         */

        if (
            preg_match(
                '/^taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {

            $wanted_level = (int) $matches[1];

            if ( empty( $args['taxonomy'] ) ) {
                return $args;
            }

            $taxonomy = is_array( $args['taxonomy'] )
                ? reset( $args['taxonomy'] )
                : $args['taxonomy'];

            if ( ! taxonomy_exists( $taxonomy ) ) {
                return $args;
            }

            unset( $args['term_taxonomy_id'] );

            $all_terms = get_terms( [
                'taxonomy'   => $taxonomy,
                'hide_empty' => false,
            ] );

            if (
                is_wp_error( $all_terms ) ||
                empty( $all_terms )
            ) {
                $args['include'] = [ 0 ];
                return $args;
            }

            $include = [];

            foreach ( $all_terms as $term ) {

                $level = count(
                    get_ancestors(
                        $term->term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );

                if ( $level === $wanted_level ) {
                    $include[] = $term->term_id;
                }
            }

            $args['include'] = ! empty( $include )
                ? $include
                : [ 0 ];

            return $args;
        }


        /*
         * =========================================================
         * 2. GERELATEERDE LOCATIES VOOR HUIDIG BEROEP
         * =========================================================
         *
         * Query ID:
         *
         * related_locaties_level_0
         * related_locaties_level_1
         * related_locaties_level_2
         */

        if (
            preg_match(
                '/^related_locaties_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {

            $wanted_level = (int) $matches[1];

            $current_post_id = get_queried_object_id();

            if ( ! $current_post_id ) {
                return $args;
            }


            /*
             * Functienaam van huidige Beroep ophalen.
             */

            $functie_terms = wp_get_post_terms(
                $current_post_id,
                'functienaam',
                [
                    'fields' => 'ids',
                ]
            );

            if (
                is_wp_error( $functie_terms ) ||
                empty( $functie_terms )
            ) {
                $args['include'] = [ 0 ];
                return $args;
            }


            /*
             * Automatisch bepalen welke post types zowel
             * functienaam als locatie gebruiken.
             */

            $functie_taxonomy =
                get_taxonomy( 'functienaam' );

            $locatie_taxonomy =
                get_taxonomy( 'locatie' );

            if (
                ! $functie_taxonomy ||
                ! $locatie_taxonomy
            ) {
                return $args;
            }

            $vacature_post_types = array_values(
                array_intersect(
                    $functie_taxonomy->object_type,
                    $locatie_taxonomy->object_type
                )
            );

            if ( empty( $vacature_post_types ) ) {
                $args['include'] = [ 0 ];
                return $args;
            }


            /*
             * Alle vacatures met dezelfde functienaam ophalen.
             */

            $vacature_ids = get_posts( [
                'post_type'      => $vacature_post_types,
                'post_status'    => 'publish',
                'posts_per_page' => -1,
                'fields'         => 'ids',

                'tax_query' => [
                    [
                        'taxonomy' => 'functienaam',
                        'field'    => 'term_id',
                        'terms'    => $functie_terms,
                    ],
                ],
            ] );


            if ( empty( $vacature_ids ) ) {
                $args['include'] = [ 0 ];
                return $args;
            }


            /*
             * Locaties verzamelen van gevonden vacatures.
             */

            $location_ids = [];

            foreach ( $vacature_ids as $vacature_id ) {

                $locations = wp_get_post_terms(
                    $vacature_id,
                    'locatie',
                    [
                        'fields' => 'ids',
                    ]
                );

                if ( ! is_wp_error( $locations ) ) {
                    $location_ids = array_merge(
                        $location_ids,
                        $locations
                    );
                }
            }

            $location_ids = array_unique(
                array_map(
                    'intval',
                    $location_ids
                )
            );


            if ( empty( $location_ids ) ) {
                $args['include'] = [ 0 ];
                return $args;
            }


            /*
             * Alleen gewenste locatie-level behouden.
             */

            $include = [];

            foreach ( $location_ids as $location_id ) {

                $level = count(
                    get_ancestors(
                        $location_id,
                        'locatie',
                        'taxonomy'
                    )
                );

                if ( $level === $wanted_level ) {
                    $include[] = $location_id;
                }
            }


            unset( $args['term_taxonomy_id'] );


            /*
             * Elementor moet locatie-termen renderen.
             */

            $args['taxonomy'] = 'locatie';

            $args['include'] = ! empty( $include )
                ? array_unique( $include )
                : [ 0 ];

            $args['hide_empty'] = false;
            $args['orderby']    = 'name';
            $args['order']      = 'ASC';

            return $args;
        }


        /*
         * =========================================================
         * 3. HUIDIGE TFSC TAXONOMY BASE ARCHIVE
         * =========================================================
         *
         * Query ID:
         *
         * current_taxonomy
         *
         * OF:
         *
         * current_taxonomy_level_0
         * current_taxonomy_level_1
         * current_taxonomy_level_2
         */


        /*
         * Eerst controleren of één van onze current_taxonomy
         * Query ID's gebruikt wordt.
         */

        if (
            'current_taxonomy' === $query_id ||
            preg_match(
                '/^current_taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {

            /*
             * Taxonomy ophalen uit ons TFSC Taxonomy Base Archive.
             */

            $taxonomy = get_query_var(
                'tfsc_taxonomy_archive'
            );


            /*
             * Extra fallback naar de main WP_Query.
             *
             * Dit maakt de werking iets robuuster wanneer Elementor
             * de query in een andere context uitvoert.
             */

            if (
                ! $taxonomy &&
                isset( $GLOBALS['wp_query'] )
            ) {
                $taxonomy =
                    $GLOBALS['wp_query']->get(
                        'tfsc_taxonomy_archive'
                    );
            }


            /*
             * Geen geldige archive-taxonomy gevonden:
             * bewust geen resultaten tonen.
             */

            if (
                ! $taxonomy ||
                ! taxonomy_exists( $taxonomy )
            ) {
                $args['include'] = [ 0 ];
                return $args;
            }


            /*
             * Elementor Query ID verwijderen.
             */

            unset( $args['term_taxonomy_id'] );


            /*
             * BELANGRIJK:
             *
             * De taxonomy die in Elementor bij Source staat
             * geselecteerd wordt hier overschreven.
             *
             * De archive-context is dus leidend.
             */

            $args['taxonomy'] = $taxonomy;

            $args['hide_empty'] = false;
            $args['orderby']    = 'name';
            $args['order']      = 'ASC';


            /*
             * -----------------------------------------------------
             * 3A. ALLE LEVELS
             * -----------------------------------------------------
             *
             * current_taxonomy
             */

            if ( 'current_taxonomy' === $query_id ) {

                return $args;
            }


            /*
             * -----------------------------------------------------
             * 3B. SPECIFIEK LEVEL
             * -----------------------------------------------------
             *
             * current_taxonomy_level_X
             */

            $wanted_level = (int) $matches[1];


            $all_terms = get_terms( [
                'taxonomy'   => $taxonomy,
                'hide_empty' => false,
            ] );


            if (
                is_wp_error( $all_terms ) ||
                empty( $all_terms )
            ) {
                $args['include'] = [ 0 ];
                return $args;
            }


            $include = [];


            foreach ( $all_terms as $term ) {

                $level = count(
                    get_ancestors(
                        $term->term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );


                if ( $level === $wanted_level ) {
                    $include[] = $term->term_id;
                }
            }


            $args['include'] = ! empty( $include )
                ? array_unique( $include )
                : [ 0 ];


            return $args;
        }


        /*
         * Geen TFSC Query ID:
         * Elementor standaardquery ongemoeid laten.
         */

        return $args;

    },
    20,
    3
);

/**
 * TFSC - Elementor Taxonomy Loop filters
 *
 * ============================================================
 * 1. NORMALE TAXONOMY LOOPS
 * ============================================================
 *
 * Hiervoor is GEEN custom Query ID meer nodig.
 *
 * Gebruik gewoon Elementor:
 *
 * - Template type: Post Taxonomy
 * - Source: gewenste taxonomy
 * - Filter By: Show All
 * - Filter by depth: indien gewenst inschakelen
 * - Query ID: leeg
 *
 *
 * ============================================================
 * 2. HUIDIGE TFSC TAXONOMY BASE ARCHIVE
 * ============================================================
 *
 * Query ID:
 *
 * current_taxonomy
 *
 * current_taxonomy_level_0
 * current_taxonomy_level_1
 * current_taxonomy_level_2
 * enz.
 *
 * Werking:
 *
 * De taxonomy wordt automatisch bepaald via:
 *
 * get_query_var( 'tfsc_taxonomy_archive' )
 *
 * De Source die in Elementor geselecteerd staat wordt hierbij
 * bewust overschreven.
 *
 *
 * Voorbeelden:
 *
 * current_taxonomy
 * = alle terms
 *
 * current_taxonomy_level_0
 * = alleen top-level terms
 *
 * current_taxonomy_level_1
 * = alleen terms met 1 ancestor
 *
 *
 * ============================================================
 * 3. GERELATEERDE LOCATIES VOOR HUIDIG BEROEP
 * ============================================================
 *
 * Query ID:
 *
 * related_locaties_level_0
 * related_locaties_level_1
 * related_locaties_level_2
 *
 * Werking:
 *
 * huidig beroep
 *      ↓
 * functienaam
 *      ↓
 * vacatures met dezelfde functienaam
 *      ↓
 * locaties van die vacatures
 *      ↓
 * alleen gewenst hiërarchisch level
 *
 *
 * ============================================================
 * LEVELS
 * ============================================================
 *
 * level_0 = geen parent
 * level_1 = 1 ancestor
 * level_2 = 2 ancestors
 * enz.
 */


add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        /*
         * Zonder Query ID niets aanpassen.
         *
         * Daardoor blijven normale Elementor Taxonomy Loops
         * volledig door Elementor zelf geregeld.
         */
        if ( empty( $settings['term_taxonomy_id'] ) ) {
            return $args;
        }


        $query_id = sanitize_key(
            $settings['term_taxonomy_id']
        );


        /*
         * =====================================================
         * HELPER: TERMS OP HIËRARCHISCH LEVEL
         * =====================================================
         */

        $get_terms_at_level = function(
            $taxonomy,
            $wanted_level,
            $allowed_term_ids = null
        ) {

            if (
                empty( $taxonomy ) ||
                ! taxonomy_exists( $taxonomy )
            ) {
                return [];
            }


            $term_args = [
                'taxonomy'   => $taxonomy,
                'hide_empty' => false,
            ];


            /*
             * Optioneel alleen binnen een bestaande verzameling
             * term IDs zoeken.
             *
             * Dit gebruiken we bij related_locaties.
             */
            if ( is_array( $allowed_term_ids ) ) {

                $allowed_term_ids = array_values(
                    array_unique(
                        array_map(
                            'intval',
                            $allowed_term_ids
                        )
                    )
                );


                if ( empty( $allowed_term_ids ) ) {
                    return [];
                }


                $term_args['include'] =
                    $allowed_term_ids;
            }


            $terms = get_terms(
                $term_args
            );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                return [];
            }


            $include = [];


            foreach ( $terms as $term ) {

                $level = count(
                    get_ancestors(
                        $term->term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );


                if ( $level === $wanted_level ) {
                    $include[] =
                        (int) $term->term_id;
                }
            }


            return array_values(
                array_unique(
                    $include
                )
            );
        };


        /*
         * =====================================================
         * 1. CURRENT TAXONOMY BASE ARCHIVE
         * =====================================================
         *
         * Query ID:
         *
         * current_taxonomy
         *
         * current_taxonomy_level_0
         * current_taxonomy_level_1
         * current_taxonomy_level_2
         */

        if (
            'current_taxonomy' === $query_id ||
            preg_match(
                '/^current_taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {

            /*
             * Actieve taxonomy ophalen uit onze
             * TFSC Taxonomy Base Archive functionaliteit.
             */
            $taxonomy =
                get_query_var(
                    'tfsc_taxonomy_archive'
                );


            /*
             * Extra fallback via de hoofdquery.
             */
            if (
                empty( $taxonomy ) &&
                isset( $GLOBALS['wp_query'] )
            ) {

                $taxonomy =
                    $GLOBALS['wp_query']->get(
                        'tfsc_taxonomy_archive'
                    );
            }


            /*
             * Geen geldige taxonomy:
             * geen resultaten tonen.
             */
            if (
                empty( $taxonomy ) ||
                ! taxonomy_exists( $taxonomy )
            ) {

                unset(
                    $args['term_taxonomy_id']
                );

                $args['include'] = [ 0 ];

                return $args;
            }


            /*
             * Elementor gebruikt term_taxonomy_id intern ook
             * voor de Query ID.
             *
             * Verwijderen voordat WP_Term_Query wordt uitgevoerd.
             */
            unset(
                $args['term_taxonomy_id']
            );


            /*
             * De huidige archive-taxonomy is leidend.
             *
             * Hiermee wordt de Elementor Source overschreven.
             */
            $args['taxonomy'] =
                $taxonomy;

            $args['hide_empty'] =
                false;


            /*
             * -------------------------------------------------
             * ALLE TERMS
             * -------------------------------------------------
             *
             * Query ID:
             *
             * current_taxonomy
             */

            if (
                'current_taxonomy' ===
                $query_id
            ) {

                return $args;
            }


            /*
             * -------------------------------------------------
             * SPECIFIEK LEVEL
             * -------------------------------------------------
             */

            $wanted_level =
                (int) $matches[1];


            $include =
                $get_terms_at_level(
                    $taxonomy,
                    $wanted_level
                );


            $args['include'] =
                ! empty( $include )
                    ? $include
                    : [ 0 ];


            return $args;
        }


        /*
         * =====================================================
         * 2. GERELATEERDE LOCATIES VOOR HUIDIG BEROEP
         * =====================================================
         *
         * Query ID:
         *
         * related_locaties_level_0
         * related_locaties_level_1
         * related_locaties_level_2
         */

        if (
            preg_match(
                '/^related_locaties_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {

            $wanted_level =
                (int) $matches[1];


            /*
             * Huidige Beroep/post.
             */
            $current_post_id =
                get_queried_object_id();


            if ( ! $current_post_id ) {
                return $args;
            }


            /*
             * -------------------------------------------------
             * FUNCTIENAAM VAN HUIDIG BEROEP
             * -------------------------------------------------
             */

            $functie_terms =
                wp_get_post_terms(
                    $current_post_id,
                    'functienaam',
                    [
                        'fields' => 'ids',
                    ]
                );


            if (
                is_wp_error( $functie_terms ) ||
                empty( $functie_terms )
            ) {

                unset(
                    $args['term_taxonomy_id']
                );

                $args['include'] = [ 0 ];

                return $args;
            }


            /*
             * -------------------------------------------------
             * POST TYPES AUTOMATISCH BEPALEN
             * -------------------------------------------------
             *
             * Zoek post types die zowel:
             *
             * functienaam
             *
             * als:
             *
             * locatie
             *
             * gebruiken.
             *
             * Daardoor hoeft de vacature-CPT niet hardcoded
             * te worden.
             */

            $functie_taxonomy =
                get_taxonomy(
                    'functienaam'
                );

            $locatie_taxonomy =
                get_taxonomy(
                    'locatie'
                );


            if (
                ! $functie_taxonomy ||
                ! $locatie_taxonomy
            ) {
                return $args;
            }


            $vacature_post_types =
                array_values(
                    array_intersect(
                        $functie_taxonomy->object_type,
                        $locatie_taxonomy->object_type
                    )
                );


            if (
                empty(
                    $vacature_post_types
                )
            ) {

                unset(
                    $args['term_taxonomy_id']
                );

                $args['include'] = [ 0 ];

                return $args;
            }


            /*
             * -------------------------------------------------
             * VACATURES MET DEZELFDE FUNCTIENAAM
             * -------------------------------------------------
             */

            $vacature_ids =
                get_posts( [

                    'post_type' =>
                        $vacature_post_types,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'tax_query' => [
                        [
                            'taxonomy' =>
                                'functienaam',

                            'field' =>
                                'term_id',

                            'terms' =>
                                $functie_terms,
                        ],
                    ],
                ] );


            if ( empty( $vacature_ids ) ) {

                unset(
                    $args['term_taxonomy_id']
                );

                $args['include'] = [ 0 ];

                return $args;
            }


            /*
             * -------------------------------------------------
             * LOCATIES VAN GEVONDEN VACATURES
             * -------------------------------------------------
             */

            $location_ids = [];


            foreach (
                $vacature_ids
                as $vacature_id
            ) {

                $locations =
                    wp_get_post_terms(
                        $vacature_id,
                        'locatie',
                        [
                            'fields' => 'ids',
                        ]
                    );


                if (
                    ! is_wp_error(
                        $locations
                    )
                ) {

                    $location_ids =
                        array_merge(
                            $location_ids,
                            $locations
                        );
                }
            }


            $location_ids =
                array_values(
                    array_unique(
                        array_map(
                            'intval',
                            $location_ids
                        )
                    )
                );


            if ( empty( $location_ids ) ) {

                unset(
                    $args['term_taxonomy_id']
                );

                $args['include'] = [ 0 ];

                return $args;
            }


            /*
             * -------------------------------------------------
             * ALLEEN GEWENST LOCATIELEVEL
             * -------------------------------------------------
             */

            $include =
                $get_terms_at_level(
                    'locatie',
                    $wanted_level,
                    $location_ids
                );


            /*
             * Query ID uit WP_Term_Query verwijderen.
             */
            unset(
                $args['term_taxonomy_id']
            );


            /*
             * Deze query moet altijd locaties renderen.
             */
            $args['taxonomy'] =
                'locatie';


            $args['include'] =
                ! empty( $include )
                    ? $include
                    : [ 0 ];


            $args['hide_empty'] =
                false;

            $args['orderby'] =
                'name';

            $args['order'] =
                'ASC';


            return $args;
        }


        /*
         * =====================================================
         * ANDERE QUERY ID
         * =====================================================
         *
         * Niet van ons?
         *
         * Elementor ongemoeid laten.
         */

        return $args;

    },
    20,
    3
);

/**
 * TFSC - Elementor Taxonomy Loop debug
 *
 * Tijdelijk gebruiken.
 *
 * Geeft in de HTML-bron weer:
 * - Query ID
 * - Elementor settings
 * - uiteindelijke taxonomy args
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        if ( empty( $settings['term_taxonomy_id'] ) ) {
            return $args;
        }

        $query_id = sanitize_key(
            $settings['term_taxonomy_id']
        );

        if (
            ! str_starts_with( $query_id, 'taxonomy_' ) &&
            ! str_starts_with( $query_id, 'current_taxonomy' ) &&
            ! str_starts_with( $query_id, 'related_locaties' )
        ) {
            return $args;
        }

        echo "\n<!-- TFSC TAXONOMY DEBUG\n";

        echo "QUERY ID:\n";
        echo esc_html( $query_id ) . "\n\n";

        echo "SETTINGS:\n";
        echo esc_html(
            print_r( $settings, true )
        );

        echo "\nARGS:\n";
        echo esc_html(
            print_r( $args, true )
        );

        echo "\nEND TFSC DEBUG -->\n";

        return $args;

    },
    1,
    3
);

/**
 * TFSC - Elementor Taxonomy Loop vanuit Pods relationshipvelden
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Deze snippet koppelt een Elementor Post Taxonomy Loop
 * automatisch aan een Pods relationshipveld.
 *
 *
 * ============================================================
 * NAAMCONVENTIE
 * ============================================================
 *
 * Taxonomy:
 *
 *   {taxonomy_name}
 *
 * Pods relationshipveld:
 *
 *   relationship_{taxonomy_name}
 *
 * Elementor Query ID:
 *
 *   relationship_{taxonomy_name}
 *
 *
 * Voorbeeld:
 *
 * Taxonomy:
 *
 *   functienaam
 *
 * Pods relationshipveld:
 *
 *   relationship_functienaam
 *
 * Elementor Query ID:
 *
 *   relationship_functienaam
 *
 *
 * Andere voorbeelden:
 *
 *   relationship_kennisgebied
 *   relationship_opleiding
 *   relationship_locatie
 *
 *
 * ============================================================
 * WERKING
 * ============================================================
 *
 * Huidige post
 *      ↓
 * Pods object van huidige post
 *      ↓
 * relationship_{taxonomy}
 *      ↓
 * gekoppelde term IDs
 *      ↓
 * Elementor Taxonomy Loop toont alleen die terms
 *
 *
 * ============================================================
 * BELANGRIJK
 * ============================================================
 *
 * Deze snippet reageert ALLEEN op Query ID's die beginnen met:
 *
 *   relationship_
 *
 * Daardoor blijft hij gescheiden van andere TFSC-query's zoals:
 *
 *   current_taxonomy
 *   current_taxonomy_level_0
 *
 *   related_locaties_level_0
 *   related_locaties_level_1
 *
 * Normale Elementor taxonomy-loops zonder relationship_ Query ID
 * worden volledig ongemoeid gelaten.
 */


add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        /*
         * Elementor plaatst de Query ID van een Taxonomy Loop
         * momenteel in term_taxonomy_id.
         *
         * Eerst proberen we hem uit $settings te lezen.
         * Als fallback gebruiken we $args.
         */
        $query_id = '';

        if ( ! empty( $settings['term_taxonomy_id'] ) ) {

            $query_id =
                $settings['term_taxonomy_id'];

        } elseif (
            isset( $args['term_taxonomy_id'] ) &&
            is_string( $args['term_taxonomy_id'] )
        ) {

            $query_id =
                $args['term_taxonomy_id'];
        }


        if ( ! is_string( $query_id ) ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $query_id
            );


        $prefix =
            'relationship_';


        /*
         * Alleen relationship-query's verwerken.
         *
         * Alle andere Elementor Taxonomy Loops blijven
         * volledig ongemoeid.
         */
        if (
            strpos(
                $query_id,
                $prefix
            ) !== 0
        ) {
            return $args;
        }


        /*
         * -----------------------------------------------------
         * TAXONOMY AFLEIDEN UIT QUERY ID
         * -----------------------------------------------------
         *
         * relationship_functienaam
         *
         * wordt:
         *
         * functienaam
         */

        $taxonomy =
            substr(
                $query_id,
                strlen( $prefix )
            );


        if (
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {

            unset(
                $args['term_taxonomy_id']
            );

            $args['include'] = [ 0 ];

            return $args;
        }


        /*
         * Pods moet beschikbaar zijn.
         */
        if ( ! function_exists( 'pods' ) ) {

            unset(
                $args['term_taxonomy_id']
            );

            $args['include'] = [ 0 ];

            return $args;
        }


        /*
         * -----------------------------------------------------
         * QUERY ID VERWIJDEREN UIT WP_TERM_QUERY
         * -----------------------------------------------------
         *
         * Elementor gebruikt term_taxonomy_id ook om de Query ID
         * door te geven.
         *
         * WordPress verwacht daar normaal numerieke taxonomy IDs.
         *
         * Daarom moet de tekstuele Query ID verwijderd worden.
         */

        unset(
            $args['term_taxonomy_id']
        );


        /*
         * -----------------------------------------------------
         * HUIDIGE POST BEPALEN
         * -----------------------------------------------------
         */

        $post_id =
            get_queried_object_id();


        /*
         * Elementor preview fallback.
         */
        if (
            ! $post_id ||
            'revision' === get_post_type( $post_id )
        ) {

            $post_id =
                get_the_ID();
        }


        $post_type =
            $post_id
                ? get_post_type( $post_id )
                : false;


        if (
            ! $post_id ||
            ! $post_type
        ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /*
         * -----------------------------------------------------
         * PODS OBJECT OPHALEN
         * -----------------------------------------------------
         */

        $pod =
            pods(
                $post_type,
                $post_id
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /*
         * -----------------------------------------------------
         * RELATIONSHIPVELD OPHALEN
         * -----------------------------------------------------
         *
         * De Pods-veldnaam is exact gelijk aan de Query ID.
         *
         * Bijvoorbeeld:
         *
         * relationship_functienaam
         */

        $relations =
            $pod->field(
                $query_id
            );


        if ( empty( $relations ) ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /*
         * -----------------------------------------------------
         * PODS RETURN STRUCTUUR NORMALISEREN
         * -----------------------------------------------------
         *
         * Bij één gekoppelde term kan Pods één associatieve
         * array teruggeven in plaats van een lijst.
         */

        if (
            is_array( $relations ) &&
            (
                isset( $relations['term_id'] ) ||
                isset( $relations['id'] ) ||
                isset( $relations['ID'] )
            )
        ) {

            $relations = [
                $relations,
            ];
        }


        /*
         * -----------------------------------------------------
         * TERM IDs VERZAMELEN
         * -----------------------------------------------------
         */

        $term_ids = [];


        foreach (
            (array) $relations
            as $relation
        ) {

            $term_id = 0;


            /*
             * Pods kan afhankelijk van veld/configuratie
             * verschillende structuren teruggeven.
             */
            if ( is_numeric( $relation ) ) {

                $term_id =
                    (int) $relation;

            } elseif ( is_array( $relation ) ) {

                $term_id =
                    (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

            } elseif ( is_object( $relation ) ) {

                $term_id =
                    (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
            }


            if ( ! $term_id ) {
                continue;
            }


            /*
             * Alleen terms uit de taxonomy accepteren die uit
             * de Query ID is afgeleid.
             *
             * Daarmee voorkomen we dat een term ID uit een
             * andere taxonomy per ongeluk wordt gebruikt.
             */

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if ( $term instanceof WP_Term ) {

                $term_ids[] =
                    $term_id;
            }
        }


        /*
         * Dubbele en lege IDs verwijderen.
         */

        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        /*
         * -----------------------------------------------------
         * ELEMENTOR TERM QUERY INSTELLEN
         * -----------------------------------------------------
         */

        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            ! empty( $term_ids )
                ? $term_ids
                : [ 0 ];


        $args['hide_empty'] =
            false;


        /*
         * Volgorde van Pods relationshipveld behouden.
         */
        $args['orderby'] =
            'include';


        return $args;

    },
    20,
    3
);

/**
 * TFSC - Rank Math breadcrumbs voor taxonomy base archives
 * en native taxonomy term archives
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * De breadcrumb wordt automatisch opgebouwd vanuit de rewrite
 * slug van de taxonomy.
 *
 * Voorbeeld rewrite slug:
 *
 *   beroepengids/opleidingen
 *
 * Geeft op het taxonomy-base archive:
 *
 *   Home > Beroepengids > Opleidingen
 *
 * En op een term archive:
 *
 *   Home > Beroepengids > Opleidingen > Elektrotechniek
 *
 *
 * ============================================================
 * BRON VAN WAARHEID
 * ============================================================
 *
 * De rewrite slug van Pods / WordPress:
 *
 *   $taxonomy->rewrite['slug']
 *
 * Er worden dus GEEN taxonomy-namen, labels of URL-structuren
 * hardcoded in deze snippet.
 *
 * Verander je later de rewrite slug in Pods, dan verandert de
 * breadcrumb automatisch mee.
 *
 *
 * ============================================================
 * ONDERSTEUNT
 * ============================================================
 *
 * 1. TFSC taxonomy-base archives
 *
 *    /beroepengids/opleidingen/
 *
 * 2. Native taxonomy term archives
 *
 *    /beroepengids/opleidingen/elektrotechniek/
 *
 * 3. Hiërarchische parent/child terms
 *
 * 4. Pagination
 *
 * 5. Meerdere niveaus in de rewrite slug
 *
 *
 * ============================================================
 * BELANGRIJK
 * ============================================================
 *
 * Virtuele/combo archives zoals:
 *
 *   /vacatures/functienaam/commissioning-engineer/
 *
 * worden niet aangepast wanneer dat niet de native term URL is.
 */


add_filter(
    'rank_math/frontend/breadcrumb/items',
    function( $crumbs, $class ) {


        /*
         * =====================================================
         * HELPER: REWRITE SLUG → BREADCRUMBS
         * =====================================================
         *
         * Bouwt breadcrumb-items op basis van bijvoorbeeld:
         *
         * beroepengids/opleidingen
         *
         * →
         *
         * Beroepengids
         * Opleidingen
         */

        $build_rewrite_crumbs = function(
            $crumbs,
            $taxonomy,
            $last_item_is_current = false
        ) {

            if (
                ! $taxonomy ||
                empty( $taxonomy->rewrite['slug'] )
            ) {
                return $crumbs;
            }


            $rewrite_slug = trim(
                $taxonomy->rewrite['slug'],
                '/'
            );


            if ( '' === $rewrite_slug ) {
                return $crumbs;
            }


            $segments = array_values(
                array_filter(
                    explode(
                        '/',
                        $rewrite_slug
                    )
                )
            );


            if ( empty( $segments ) ) {
                return $crumbs;
            }


            $new_crumbs = [];


            /*
             * Home breadcrumb van Rank Math behouden.
             */
            if ( ! empty( $crumbs[0] ) ) {
                $new_crumbs[] = $crumbs[0];
            }


            $path       = '';
            $last_index = count( $segments ) - 1;


            foreach ( $segments as $index => $segment ) {

                $path .= '/' . $segment;


                /*
                 * Slug leesbaar maken.
                 *
                 * functie-inhoud
                 *
                 * →
                 *
                 * Functie inhoud
                 */
                $label = ucfirst(
                    str_replace(
                        [ '-', '_' ],
                        ' ',
                        $segment
                    )
                );


                /*
                 * Voor het laatste rewrite-segment gebruiken we
                 * het officiële taxonomy-label.
                 *
                 * Daardoor blijft bijvoorbeeld:
                 *
                 * opleidingen
                 *
                 * netjes:
                 *
                 * Opleidingen
                 */
                if (
                    $index === $last_index &&
                    ! empty( $taxonomy->labels->name )
                ) {
                    $label = $taxonomy->labels->name;
                }


                /*
                 * Op een taxonomy-base archive is het laatste
                 * rewrite-segment de huidige pagina.
                 */
                if (
                    $last_item_is_current &&
                    $index === $last_index
                ) {

                    $new_crumbs[] = [
                        $label,
                        '',
                    ];

                } else {

                    $new_crumbs[] = [
                        $label,
                        home_url(
                            $path . '/'
                        ),
                    ];
                }
            }


            return $new_crumbs;
        };



        /*
         * =====================================================
         * 1. TFSC TAXONOMY BASE ARCHIVE
         * =====================================================
         *
         * Voorbeeld:
         *
         * /beroepengids/opleidingen/
         */

        $base_taxonomy_name = get_query_var(
            'tfsc_taxonomy_archive'
        );


        if (
            ! empty( $base_taxonomy_name ) &&
            taxonomy_exists( $base_taxonomy_name )
        ) {

            $taxonomy = get_taxonomy(
                $base_taxonomy_name
            );


            if ( ! $taxonomy ) {
                return $crumbs;
            }


            return $build_rewrite_crumbs(
                $crumbs,
                $taxonomy,
                true
            );
        }



        /*
         * =====================================================
         * 2. NATIVE TAXONOMY TERM ARCHIVE
         * =====================================================
         */

        if ( ! is_tax() ) {
            return $crumbs;
        }


        $term = get_queried_object();


        if (
            ! $term ||
            is_wp_error( $term ) ||
            empty( $term->taxonomy )
        ) {
            return $crumbs;
        }


        /*
         * Native URL van de term ophalen.
         */
        $term_url = get_term_link(
            $term
        );


        if ( is_wp_error( $term_url ) ) {
            return $crumbs;
        }


        /*
         * =====================================================
         * CONTROLEREN OF WE OP DE ECHTE TERM URL ZITTEN
         * =====================================================
         *
         * Hierdoor worden virtuele/combo archives met een
         * andere URL ongemoeid gelaten.
         */

        $native_path = wp_parse_url(
            $term_url,
            PHP_URL_PATH
        );


        $current_path = wp_parse_url(
            $_SERVER['REQUEST_URI'],
            PHP_URL_PATH
        );


        /*
         * Pagination verwijderen.
         *
         * Bijvoorbeeld:
         *
         * /page/2/
         */
        $current_path = preg_replace(
            '#/page/[0-9]+/?$#',
            '/',
            $current_path
        );


        $native_path = untrailingslashit(
            $native_path
        );


        $current_path = untrailingslashit(
            $current_path
        );


        /*
         * Niet de native term URL?
         *
         * Dan niets aanpassen.
         */
        if ( $native_path !== $current_path ) {
            return $crumbs;
        }


        /*
         * Taxonomy-configuratie ophalen.
         */
        $taxonomy = get_taxonomy(
            $term->taxonomy
        );


        if ( ! $taxonomy ) {
            return $crumbs;
        }


        /*
         * Rewrite breadcrumbs opbouwen.
         *
         * Bijvoorbeeld:
         *
         * Home
         * > Beroepengids
         * > Opleidingen
         */
        $new_crumbs = $build_rewrite_crumbs(
            $crumbs,
            $taxonomy,
            false
        );


        /*
         * =====================================================
         * 3. PARENT TERMS
         * =====================================================
         *
         * Alleen relevant voor hiërarchische taxonomies.
         */

        if (
            is_taxonomy_hierarchical(
                $term->taxonomy
            )
        ) {

            $ancestors = array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            );


            foreach ( $ancestors as $ancestor_id ) {

                $ancestor = get_term(
                    $ancestor_id,
                    $term->taxonomy
                );


                if (
                    ! $ancestor ||
                    is_wp_error( $ancestor )
                ) {
                    continue;
                }


                $ancestor_url = get_term_link(
                    $ancestor
                );


                if ( is_wp_error( $ancestor_url ) ) {
                    continue;
                }


                $new_crumbs[] = [
                    $ancestor->name,
                    $ancestor_url,
                ];
            }
        }


        /*
         * =====================================================
         * 4. HUIDIGE TERM
         * =====================================================
         */

        $new_crumbs[] = [
            $term->name,
            '',
        ];


        return $new_crumbs;

    },
    10,
    2
);

/**
 * Deze snippet is voor de archives van beroepen, om de query die informatie bevat te tonen (beroepen posts of current taxonomies), zodat we 1 archive template kunnen gebruiken voor allen. 
 * 
 * TFSC - Archive context classes
 *
 * Voor één generiek archive-template met:
 *
 * .tfsc_query_beroepen
 * .tfsc_query_taxonomies_current
 * 
 */

add_filter( 'body_class', function( $classes ) {

    // CPT archive Beroepen.
    if ( is_post_type_archive( 'beroepengids' ) ) {
        $classes[] = 'tfsc-archive-beroepen';
    }

    // TFSC taxonomy-base archive.
    if ( get_query_var( 'tfsc_taxonomy_archive' ) ) {
        $classes[] = 'tfsc-archive-taxonomy';
    }

    return $classes;
});

/**
 * TFSC - Rank Math breadcrumbs voor:
 *
 * 1. Taxonomy base archives
 * 2. Native taxonomy term archives
 * 3. CPT archives
 * 4. CPT singular items
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Breadcrumbs automatisch opbouwen vanuit de echte WordPress /
 * Pods rewrite- en archive-structuur.
 *
 *
 * VOORBEELDEN
 * ============================================================
 *
 * Taxonomy base:
 *
 * /beroepengids/opleidingen/
 *
 * Home > Beroepengids > Opleidingen
 *
 *
 * Taxonomy term:
 *
 * /beroepengids/opleidingen/elektrotechniek/
 *
 * Home > Beroepengids > Opleidingen > Elektrotechniek
 *
 *
 * CPT archive:
 *
 * /beroepengids/beroepen/
 *
 * Home > Beroepengids > Beroepen
 *
 *
 * CPT singular:
 *
 * /beroepengids/beroep/service-monteur/
 *
 * Home > Beroepengids > Beroepen > Service Monteur
 *
 *
 * ============================================================
 * BELANGRIJK
 * ============================================================
 *
 * Voor CPT singulars gebruiken we:
 *
 * get_post_type_archive_link()
 *
 * als daadwerkelijke archive-link.
 *
 * Daardoor kan bijvoorbeeld:
 *
 * singular rewrite:
 *
 *   beroepengids/beroep
 *
 * verschillen van:
 *
 * archive:
 *
 *   beroepengids/beroepen
 *
 *
 * Dat is precies jouw huidige Beroep-configuratie.
 *
 *
 * Voor taxonomies gebruiken we:
 *
 *   $taxonomy->rewrite['slug']
 *
 *
 * Virtuele/combo archives worden alleen aangepast wanneer ze
 * daadwerkelijk door onze TFSC taxonomy-base archive functionaliteit
 * worden herkend.
 */


add_filter(
    'rank_math/frontend/breadcrumb/items',
    function( $crumbs, $class ) {


        /*
         * =====================================================
         * HELPER 1
         * Pad opdelen en als breadcrumbs toevoegen
         * =====================================================
         *
         * Bijvoorbeeld:
         *
         * beroepengids/opleidingen
         *
         * wordt:
         *
         * Beroepengids
         * Opleidingen
         */

        $add_path_crumbs = function(
            $crumbs,
            $path,
            $last_label = '',
            $last_is_current = false
        ) {

            $path = trim(
                (string) $path,
                '/'
            );

            if ( '' === $path ) {
                return $crumbs;
            }


            $segments = array_values(
                array_filter(
                    explode(
                        '/',
                        $path
                    )
                )
            );


            if ( empty( $segments ) ) {
                return $crumbs;
            }


            $new_crumbs = [];


            /*
             * Home van Rank Math behouden.
             */
            if ( ! empty( $crumbs[0] ) ) {
                $new_crumbs[] = $crumbs[0];
            }


            $current_path = '';
            $last_index   = count( $segments ) - 1;


            foreach ( $segments as $index => $segment ) {

                $current_path .= '/' . $segment;


                /*
                 * Slug leesbaar maken.
                 */
                $label = ucfirst(
                    str_replace(
                        [ '-', '_' ],
                        ' ',
                        $segment
                    )
                );


                /*
                 * Voor laatste onderdeel eventueel een
                 * officieel label gebruiken.
                 */
                if (
                    $index === $last_index &&
                    '' !== $last_label
                ) {
                    $label = $last_label;
                }


                /*
                 * Laatste onderdeel kan huidige pagina zijn.
                 */
                if (
                    $last_is_current &&
                    $index === $last_index
                ) {

                    $new_crumbs[] = [
                        $label,
                        '',
                    ];

                } else {

                    $new_crumbs[] = [
                        $label,
                        home_url(
                            $current_path . '/'
                        ),
                    ];
                }
            }


            return $new_crumbs;
        };



        /*
         * =====================================================
         * HELPER 2
         * Archive URL omzetten naar relatief pad
         * =====================================================
         */

        $get_relative_path = function( $url ) {

            if ( empty( $url ) ) {
                return '';
            }


            $path = wp_parse_url(
                $url,
                PHP_URL_PATH
            );


            if ( empty( $path ) ) {
                return '';
            }


            return trim(
                $path,
                '/'
            );
        };



        /*
         * =====================================================
         * 1. TFSC TAXONOMY BASE ARCHIVE
         * =====================================================
         *
         * Voorbeeld:
         *
         * /beroepengids/opleidingen/
         */

        $base_taxonomy_name = get_query_var(
            'tfsc_taxonomy_archive'
        );


        if (
            ! empty( $base_taxonomy_name ) &&
            taxonomy_exists( $base_taxonomy_name )
        ) {

            $taxonomy = get_taxonomy(
                $base_taxonomy_name
            );


            if (
                ! $taxonomy ||
                empty( $taxonomy->rewrite['slug'] )
            ) {
                return $crumbs;
            }


            return $add_path_crumbs(
                $crumbs,
                $taxonomy->rewrite['slug'],
                ! empty( $taxonomy->labels->name )
                    ? $taxonomy->labels->name
                    : '',
                true
            );
        }



        /*
         * =====================================================
         * 2. NATIVE TAXONOMY TERM ARCHIVE
         * =====================================================
         */

        if ( is_tax() ) {

            $term = get_queried_object();


            if (
                ! $term ||
                is_wp_error( $term ) ||
                empty( $term->taxonomy )
            ) {
                return $crumbs;
            }


            $term_url = get_term_link(
                $term
            );


            if ( is_wp_error( $term_url ) ) {
                return $crumbs;
            }


            /*
             * Controleren of dit echt de native term URL is.
             *
             * Hiermee voorkomen we dat virtuele/combo URLs
             * worden aangepast.
             */

            $native_path = wp_parse_url(
                $term_url,
                PHP_URL_PATH
            );


            $current_path = wp_parse_url(
                $_SERVER['REQUEST_URI'],
                PHP_URL_PATH
            );


            /*
             * Pagination verwijderen.
             */
            $current_path = preg_replace(
                '#/page/[0-9]+/?$#',
                '/',
                $current_path
            );


            $native_path = untrailingslashit(
                $native_path
            );


            $current_path = untrailingslashit(
                $current_path
            );


            if ( $native_path !== $current_path ) {
                return $crumbs;
            }


            $taxonomy = get_taxonomy(
                $term->taxonomy
            );


            if (
                ! $taxonomy ||
                empty( $taxonomy->rewrite['slug'] )
            ) {
                return $crumbs;
            }


            /*
             * Eerst rewrite pad toevoegen.
             */
            $new_crumbs = $add_path_crumbs(
                $crumbs,
                $taxonomy->rewrite['slug'],
                ! empty( $taxonomy->labels->name )
                    ? $taxonomy->labels->name
                    : '',
                false
            );


            /*
             * Parent terms toevoegen.
             */
            if (
                is_taxonomy_hierarchical(
                    $term->taxonomy
                )
            ) {

                $ancestors = array_reverse(
                    get_ancestors(
                        $term->term_id,
                        $term->taxonomy,
                        'taxonomy'
                    )
                );


                foreach ( $ancestors as $ancestor_id ) {

                    $ancestor = get_term(
                        $ancestor_id,
                        $term->taxonomy
                    );


                    if (
                        ! $ancestor ||
                        is_wp_error( $ancestor )
                    ) {
                        continue;
                    }


                    $ancestor_url = get_term_link(
                        $ancestor
                    );


                    if ( is_wp_error( $ancestor_url ) ) {
                        continue;
                    }


                    $new_crumbs[] = [
                        $ancestor->name,
                        $ancestor_url,
                    ];
                }
            }


            /*
             * Huidige term.
             */
            $new_crumbs[] = [
                $term->name,
                '',
            ];


            return $new_crumbs;
        }



        /*
         * =====================================================
         * 3. CPT ARCHIVE
         * =====================================================
         *
         * Voorbeeld:
         *
         * /beroepengids/beroepen/
         */

        if ( is_post_type_archive() ) {

            $post_type = get_query_var(
                'post_type'
            );


            /*
             * Soms geeft WP een array terug.
             */
            if ( is_array( $post_type ) ) {
                $post_type = reset(
                    $post_type
                );
            }


            if ( empty( $post_type ) ) {
                return $crumbs;
            }


            $post_type_object = get_post_type_object(
                $post_type
            );


            if ( ! $post_type_object ) {
                return $crumbs;
            }


            $archive_url = get_post_type_archive_link(
                $post_type
            );


            if ( ! $archive_url ) {
                return $crumbs;
            }


            $archive_path = $get_relative_path(
                $archive_url
            );


            if ( '' === $archive_path ) {
                return $crumbs;
            }


            $archive_label =
                ! empty(
                    $post_type_object->labels->name
                )
                    ? $post_type_object->labels->name
                    : '';


            return $add_path_crumbs(
                $crumbs,
                $archive_path,
                $archive_label,
                true
            );
        }



        /*
         * =====================================================
         * 4. CPT SINGULAR
         * =====================================================
         *
         * Voorbeeld:
         *
         * /beroepengids/beroep/service-monteur/
         *
         * Breadcrumb:
         *
         * Home
         * > Beroepengids
         * > Beroepen
         * > Service Monteur
         */

        if ( is_singular() ) {

            $post_id = get_queried_object_id();


            if ( ! $post_id ) {
                return $crumbs;
            }


            $post_type = get_post_type(
                $post_id
            );


            if (
                empty( $post_type ) ||
                'post' === $post_type ||
                'page' === $post_type ||
                'attachment' === $post_type
            ) {
                return $crumbs;
            }


            $post_type_object = get_post_type_object(
                $post_type
            );


            if (
                ! $post_type_object ||
                empty( $post_type_object->has_archive )
            ) {
                return $crumbs;
            }


            /*
             * Echte archive-link ophalen.
             *
             * Dus bijvoorbeeld:
             *
             * /beroepengids/beroepen/
             *
             * en NIET:
             *
             * /beroepengids/beroep/
             */
            $archive_url = get_post_type_archive_link(
                $post_type
            );


            if ( ! $archive_url ) {
                return $crumbs;
            }


            $archive_path = $get_relative_path(
                $archive_url
            );


            if ( '' === $archive_path ) {
                return $crumbs;
            }


            $archive_label =
                ! empty(
                    $post_type_object->labels->name
                )
                    ? $post_type_object->labels->name
                    : '';


            /*
             * Archive-pad opbouwen.
             */
            $new_crumbs = $add_path_crumbs(
                $crumbs,
                $archive_path,
                $archive_label,
                false
            );


            /*
             * =================================================
             * EVENTUELE CPT PARENT POSTS
             * =================================================
             *
             * Alleen wanneer CPT hiërarchisch is.
             */

            if ( is_post_type_hierarchical( $post_type ) ) {

                $ancestors = array_reverse(
                    get_post_ancestors(
                        $post_id
                    )
                );


                foreach ( $ancestors as $ancestor_id ) {

                    $new_crumbs[] = [
                        get_the_title(
                            $ancestor_id
                        ),
                        get_permalink(
                            $ancestor_id
                        ),
                    ];
                }
            }


            /*
             * Huidige CPT post.
             */
            $new_crumbs[] = [
                get_the_title(
                    $post_id
                ),
                '',
            ];


            return $new_crumbs;
        }



        /*
         * Geen TFSC situatie:
         * Rank Math standaard breadcrumb behouden.
         */
        return $crumbs;

    },
    10,
    2
);

/**
 * TFSC - Dynamisch Pods taxonomy-veld van actieve term
 *
 * Gebruik in Elementor:
 *
 * [tfsc_taxonomy_field field="introduction"]
 *
 * Werking:
 * - bepaalt automatisch welke taxonomy-term actief is;
 * - bepaalt automatisch bij welke taxonomy die term hoort;
 * - haalt vervolgens het opgegeven Pods-veld op;
 * - werkt daardoor met één Elementor-template voor meerdere taxonomies.
 *
 * Voorwaarden:
 * - het veld moet op de betreffende taxonomies dezelfde interne naam hebben;
 * - voorbeeld veldnaam: introduction
 *
 * Voorbeelden:
 *
 * [tfsc_taxonomy_field field="introduction"]
 * [tfsc_taxonomy_field field="archive_intro"]
 * [tfsc_taxonomy_field field="extra_description"]
 *
 * Als er geen actieve taxonomy-term is of het veld leeg is,
 * wordt niets weergegeven.
 */

add_shortcode( 'tfsc_taxonomy_field', function( $atts ) {

    /*
     * Shortcode-attributen.
     */
    $atts = shortcode_atts(
        [
            'field' => '',
        ],
        $atts,
        'tfsc_taxonomy_field'
    );


    /*
     * Interne Pods veldnaam.
     */
    $field = sanitize_key(
        $atts['field']
    );


    if ( empty( $field ) ) {
        return '';
    }


    /*
     * Alleen uitvoeren op echte taxonomy term archives.
     */
    if ( ! is_tax() ) {
        return '';
    }


    /*
     * Actieve term ophalen.
     */
    $term = get_queried_object();


    if (
        ! $term instanceof WP_Term ||
        empty( $term->taxonomy )
    ) {
        return '';
    }


    /*
     * Pods moet beschikbaar zijn.
     */
    if ( ! function_exists( 'pods' ) ) {
        return '';
    }


    /*
     * Automatisch het juiste Pods taxonomy-object openen.
     *
     * Bijvoorbeeld:
     *
     * actieve taxonomy:
     * beroep_kennisgebied
     *
     * actieve term:
     * Mechatronica
     *
     * Dan wordt automatisch die term binnen
     * beroep_kennisgebied geopend.
     */
    $pod = pods(
        $term->taxonomy,
        $term->term_id
    );


    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        return '';
    }


    /*
     * Veldwaarde ophalen.
     */
    $value = $pod->field(
        $field
    );


    if (
        null === $value ||
        '' === $value
    ) {
        return '';
    }


    /*
     * Arrays/objecten niet rechtstreeks renderen.
     *
     * Deze shortcode is bedoeld voor tekstvelden,
     * WYSIWYG, paragraph text enz.
     */
    if (
        is_array( $value ) ||
        is_object( $value )
    ) {
        return '';
    }


    /*
     * WYSIWYG / HTML netjes renderen.
     */
    return wp_kses_post(
        do_shortcode(
            (string) $value
        )
    );

} );

/**
 * TFSC - Elementor Pods Relationship Queries + Debug
 *
 * Ondersteunt:
 * - CPT/post als bron
 * - taxonomy-term als bron
 * - Posts Loop als resultaat
 * - Taxonomy Loop als resultaat
 *
 * Naamconventie:
 *
 * Doel-taxonomy:
 *   {taxonomy_name}
 *
 * Pods relationshipveld:
 *   relationship_{taxonomy_name}
 *
 * Elementor Query ID:
 *   relationship_{taxonomy_name}
 *
 *
 * DEBUG:
 * Zet TFSC_RELATIONSHIP_DEBUG op true om informatie
 * naar de PHP error log te schrijven.
 */

define( 'TFSC_RELATIONSHIP_DEBUG', true );


/**
 * ============================================================
 * DEBUG HELPER
 * ============================================================
 */
function tfsc_relationship_debug( $label, $data = null ) {

    if (
        ! defined( 'TFSC_RELATIONSHIP_DEBUG' ) ||
        ! TFSC_RELATIONSHIP_DEBUG
    ) {
        return;
    }

    $message = '[TFSC RELATIONSHIP] ' . $label;

    if ( null !== $data ) {

        if (
            is_array( $data ) ||
            is_object( $data )
        ) {
            $message .= ' | ' . print_r( $data, true );
        } else {
            $message .= ' | ' . (string) $data;
        }
    }

    error_log( $message );
}


/**
 * ============================================================
 * HELPER
 * PODS OBJECT VAN HUIDIGE CONTEXT
 * ============================================================
 *
 * Ondersteunt:
 *
 * - taxonomy term
 * - post / CPT
 */
function tfsc_relationship_get_source_pod() {

    if ( ! function_exists( 'pods' ) ) {

        tfsc_relationship_debug(
            'Pods functie bestaat niet'
        );

        return false;
    }


    $object = get_queried_object();


    tfsc_relationship_debug(
        'Queried object',
        $object
    );


    /**
     * --------------------------------------------------------
     * TAXONOMY TERM
     * --------------------------------------------------------
     */
    if (
        $object instanceof WP_Term &&
        ! empty( $object->taxonomy ) &&
        ! empty( $object->term_id )
    ) {

        tfsc_relationship_debug(
            'Context = taxonomy term',
            [
                'taxonomy' => $object->taxonomy,
                'term_id'  => $object->term_id,
                'name'     => $object->name,
                'slug'     => $object->slug,
            ]
        );


        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );


        if (
            $pod &&
            $pod->exists()
        ) {

            tfsc_relationship_debug(
                'Pods taxonomy-object gevonden',
                [
                    'taxonomy' => $object->taxonomy,
                    'term_id'  => $object->term_id,
                ]
            );

            return $pod;
        }


        tfsc_relationship_debug(
            'Pods taxonomy-object NIET gevonden'
        );
    }


    /**
     * --------------------------------------------------------
     * POST / CPT
     * --------------------------------------------------------
     */
    if (
        $object instanceof WP_Post &&
        ! empty( $object->ID )
    ) {

        $post_id   = (int) $object->ID;
        $post_type = get_post_type( $post_id );


        tfsc_relationship_debug(
            'Context = post/CPT',
            [
                'post_id'   => $post_id,
                'post_type' => $post_type,
            ]
        );


        if ( $post_type ) {

            $pod = pods(
                $post_type,
                $post_id
            );


            if (
                $pod &&
                $pod->exists()
            ) {

                tfsc_relationship_debug(
                    'Pods post-object gevonden'
                );

                return $pod;
            }
        }
    }


    /**
     * --------------------------------------------------------
     * ELEMENTOR PREVIEW FALLBACK
     * --------------------------------------------------------
     */
    $post_id = (int) get_the_ID();


    tfsc_relationship_debug(
        'Elementor/get_the_ID fallback',
        $post_id
    );


    if ( $post_id ) {

        $post_type = get_post_type(
            $post_id
        );


        if ( $post_type ) {

            $pod = pods(
                $post_type,
                $post_id
            );


            if (
                $pod &&
                $pod->exists()
            ) {

                tfsc_relationship_debug(
                    'Fallback Pods post-object gevonden',
                    [
                        'post_id'   => $post_id,
                        'post_type' => $post_type,
                    ]
                );

                return $pod;
            }
        }
    }


    tfsc_relationship_debug(
        'GEEN bruikbaar Pods bronobject gevonden'
    );


    return false;
}


/**
 * ============================================================
 * HELPER
 * GEKOPPELDE TERM IDs OPHALEN
 * ============================================================
 */
function tfsc_relationship_get_term_ids(
    $relationship_field,
    $target_taxonomy
) {

    tfsc_relationship_debug(
        'Relationship uitlezen',
        [
            'field'           => $relationship_field,
            'target_taxonomy' => $target_taxonomy,
        ]
    );


    if (
        empty( $relationship_field ) ||
        empty( $target_taxonomy ) ||
        ! taxonomy_exists( $target_taxonomy )
    ) {

        tfsc_relationship_debug(
            'Ongeldige relationship of taxonomy'
        );

        return [];
    }


    $pod = tfsc_relationship_get_source_pod();


    if (
        ! $pod ||
        ! $pod->exists()
    ) {

        tfsc_relationship_debug(
            'Geen Pods object beschikbaar'
        );

        return [];
    }


    /**
     * --------------------------------------------------------
     * NORMALE PODS RETURN
     * --------------------------------------------------------
     */
    $relations = $pod->field(
        $relationship_field
    );


    tfsc_relationship_debug(
        'Ruwe Pods relationship return',
        $relations
    );


    /**
     * --------------------------------------------------------
     * PODS TRAVERSAL TEST
     * --------------------------------------------------------
     *
     * Hiermee zien we óók wat:
     *
     * relationship_x.term_id
     *
     * oplevert.
     */
    $traversed_term_ids = $pod->field(
        $relationship_field . '.term_id'
    );


    tfsc_relationship_debug(
        'Pods traversal .term_id return',
        $traversed_term_ids
    );


    /**
     * Eerst proberen via traversal.
     *
     * Dit is voor taxonomy relationships meestal
     * de betrouwbaarste bron.
     */
    $term_ids = [];


    if ( ! empty( $traversed_term_ids ) ) {

        foreach (
            (array) $traversed_term_ids
            as $term_id
        ) {

            if ( is_numeric( $term_id ) ) {

                $term_ids[] =
                    (int) $term_id;
            }
        }
    }


    /**
     * --------------------------------------------------------
     * FALLBACK: RUWE RELATIONSHIP RETURN
     * --------------------------------------------------------
     */
    if (
        empty( $term_ids ) &&
        ! empty( $relations )
    ) {

        /**
         * Eén associatieve relatie normaliseren.
         */
        if (
            is_array( $relations ) &&
            (
                isset( $relations['term_id'] ) ||
                isset( $relations['id'] ) ||
                isset( $relations['ID'] )
            )
        ) {

            $relations = [
                $relations
            ];
        }


        foreach (
            (array) $relations
            as $relation
        ) {

            $term_id = 0;


            if ( is_numeric( $relation ) ) {

                $term_id =
                    (int) $relation;

            } elseif ( is_array( $relation ) ) {

                $term_id = (int) (
                    $relation['term_id']
                    ?? $relation['id']
                    ?? $relation['ID']
                    ?? 0
                );

            } elseif ( is_object( $relation ) ) {

                $term_id = (int) (
                    $relation->term_id
                    ?? $relation->id
                    ?? $relation->ID
                    ?? 0
                );
            }


            if ( $term_id ) {

                $term_ids[] =
                    $term_id;
            }
        }
    }


    /**
     * IDs opschonen.
     */
    $term_ids = array_values(
        array_unique(
            array_filter(
                array_map(
                    'intval',
                    $term_ids
                )
            )
        )
    );


    tfsc_relationship_debug(
        'Gevonden IDs vóór taxonomy controle',
        $term_ids
    );


    /**
     * --------------------------------------------------------
     * ALLEEN TERMS UIT JUISTE TAXONOMY ACCEPTEREN
     * --------------------------------------------------------
     */
    $valid_term_ids = [];


    foreach (
        $term_ids
        as $term_id
    ) {

        $term = get_term(
            $term_id,
            $target_taxonomy
        );


        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {

            $valid_term_ids[] =
                $term_id;


            tfsc_relationship_debug(
                'Geldige gekoppelde term',
                [
                    'term_id'  => $term_id,
                    'taxonomy' => $target_taxonomy,
                    'name'     => $term->name,
                    'slug'     => $term->slug,
                ]
            );

        } else {

            tfsc_relationship_debug(
                'ID is GEEN term in doel-taxonomy',
                [
                    'term_id'  => $term_id,
                    'taxonomy' => $target_taxonomy,
                ]
            );
        }
    }


    tfsc_relationship_debug(
        'Definitieve term IDs',
        $valid_term_ids
    );


    return $valid_term_ids;
}


/**
 * ============================================================
 * POSTS LOOP
 * ============================================================
 *
 * Registreert automatisch:
 *
 * relationship_functienaam
 * relationship_functie-inhoud
 * relationship_kennisgebied
 * enz.
 *
 * voor alle bestaande WordPress taxonomies.
 */
add_action(
    'init',
    function() {

        $taxonomies = get_taxonomies(
            [],
            'names'
        );


        foreach (
            $taxonomies
            as $taxonomy
        ) {

            $query_id =
                'relationship_' . $taxonomy;


            add_action(
                'elementor/query/' . $query_id,
                function( $query ) use (
                    $taxonomy,
                    $query_id
                ) {

                    tfsc_relationship_debug(
                        'ELEMENTOR POSTS QUERY HOOK GERAAKT',
                        [
                            'query_id' => $query_id,
                            'taxonomy' => $taxonomy,
                        ]
                    );


                    tfsc_relationship_debug(
                        'Elementor query vóór aanpassing',
                        $query->query_vars
                    );


                    $term_ids =
                        tfsc_relationship_get_term_ids(
                            $query_id,
                            $taxonomy
                        );


                    /**
                     * Geen gekoppelde terms:
                     * absoluut geen posts tonen.
                     */
                    if ( empty( $term_ids ) ) {

                        tfsc_relationship_debug(
                            'Geen gekoppelde terms: post__in = [0]'
                        );


                        $query->set(
                            'post__in',
                            [ 0 ]
                        );


                        return;
                    }


                    /**
                     * Bestaande Elementor tax_query bewaren.
                     */
                    $tax_query =
                        $query->get(
                            'tax_query'
                        );


                    if (
                        ! is_array( $tax_query )
                    ) {
                        $tax_query = [];
                    }


                    /**
                     * Onze relatie-filter toevoegen.
                     */
                    $tax_query[] = [

                        'taxonomy' =>
                            $taxonomy,

                        'field' =>
                            'term_id',

                        'terms' =>
                            $term_ids,

                        'operator' =>
                            'IN',

                        'include_children' =>
                            true,

                    ];


                    if (
                        count( $tax_query ) > 1 &&
                        empty( $tax_query['relation'] )
                    ) {

                        $tax_query['relation'] =
                            'AND';
                    }


                    $query->set(
                        'tax_query',
                        $tax_query
                    );


                    tfsc_relationship_debug(
                        'Toegevoegde tax_query',
                        $tax_query
                    );


                    tfsc_relationship_debug(
                        'Elementor query NA aanpassing',
                        $query->query_vars
                    );

                },
                20,
                1
            );
        }


        tfsc_relationship_debug(
            'Relationship Posts hooks geregistreerd',
            array_values( $taxonomies )
        );

    },
    99
);


/**
 * ============================================================
 * TAXONOMY LOOP
 * ============================================================
 *
 * Bestaande functionaliteit behouden:
 *
 * Elementor Taxonomy Loop met:
 *
 * relationship_functienaam
 *
 * toont rechtstreeks de gekoppelde term(s).
 */
add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id = '';


        if (
            isset( $settings['term_taxonomy_id'] ) &&
            is_string(
                $settings['term_taxonomy_id']
            )
        ) {

            $query_id =
                $settings['term_taxonomy_id'];

        } elseif (
            isset( $args['term_taxonomy_id'] ) &&
            is_string(
                $args['term_taxonomy_id']
            )
        ) {

            $query_id =
                $args['term_taxonomy_id'];
        }


        if ( empty( $query_id ) ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $query_id
            );


        $prefix =
            'relationship_';


        if (
            strpos(
                $query_id,
                $prefix
            ) !== 0
        ) {
            return $args;
        }


        tfsc_relationship_debug(
            'ELEMENTOR TAXONOMY LOOP HOOK GERAAKT',
            $query_id
        );


        $target_taxonomy =
            substr(
                $query_id,
                strlen( $prefix )
            );


        unset(
            $args['term_taxonomy_id']
        );


        if (
            empty( $target_taxonomy ) ||
            ! taxonomy_exists(
                $target_taxonomy
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $term_ids =
            tfsc_relationship_get_term_ids(
                $query_id,
                $target_taxonomy
            );


        $args['taxonomy'] =
            $target_taxonomy;


        $args['include'] =
            ! empty( $term_ids )
                ? $term_ids
                : [ 0 ];


        $args['hide_empty'] =
            false;


        $args['orderby'] =
            'include';


        tfsc_relationship_debug(
            'Taxonomy Loop definitieve args',
            $args
        );


        return $args;

    },
    20,
    3
);

