/**
 * TFSC - Generieke Elementor Pods Relationship Queries
 *
 * ============================================================
 * NAAMCONVENTIE
 * ============================================================
 *
 * Doel-taxonomy:
 *     {taxonomy_name}
 *
 * Pods relationshipveld:
 *     relationship_{taxonomy_name}
 *
 * Elementor Query ID:
 *     relationship_{taxonomy_name}
 *
 *
 * Voorbeelden:
 *
 * relationship_functienaam
 * relationship_functie-inhoud
 * relationship_kennisgebied
 * relationship_locatie
 *
 *
 * ============================================================
 * BRONCONTEXT
 * ============================================================
 *
 * Werkt vanuit:
 *
 * - huidige post / CPT
 * - huidige taxonomy-term
 *
 *
 * ============================================================
 * RESULTAAT
 * ============================================================
 *
 * A. Elementor Posts Loop
 *
 * relationship_functienaam
 *
 * →
 *
 * gekoppelde functienaam-term(s)
 *
 * →
 *
 * toon alleen posts uit de bestaande Elementor Source
 * die die functienaam-term(s) hebben.
 *
 *
 * B. Elementor Taxonomy Loop
 *
 * relationship_functienaam
 *
 * →
 *
 * toon rechtstreeks de gekoppelde functienaam-term(s).
 */


/**
 * ============================================================
 * HELPER 1
 * Huidige Pods bronobject ophalen
 * ============================================================
 */
if ( ! function_exists( 'tfsc_rel_get_source_pod' ) ) {

    function tfsc_rel_get_source_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }

        $object = get_queried_object();


        /**
         * TAXONOMY TERM
         */
        if (
            $object instanceof WP_Term &&
            ! empty( $object->taxonomy ) &&
            ! empty( $object->term_id )
        ) {

            $pod = pods(
                $object->taxonomy,
                (int) $object->term_id
            );

            if (
                $pod &&
                $pod->exists()
            ) {
                return $pod;
            }
        }


        /**
         * POST / CPT
         */
        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID )
        ) {

            $post_type = get_post_type(
                $object->ID
            );

            if ( $post_type ) {

                $pod = pods(
                    $post_type,
                    (int) $object->ID
                );

                if (
                    $pod &&
                    $pod->exists()
                ) {
                    return $pod;
                }
            }
        }


        /**
         * Elementor preview fallback.
         */
        $post_id = (int) get_the_ID();

        if ( $post_id ) {

            $post_type = get_post_type(
                $post_id
            );

            if ( $post_type ) {

                $pod = pods(
                    $post_type,
                    $post_id
                );

                if (
                    $pod &&
                    $pod->exists()
                ) {
                    return $pod;
                }
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * HELPER 2
 * Relationship-term IDs ophalen
 * ============================================================
 *
 * Voorbeeld:
 *
 * Query ID:
 *     relationship_functienaam
 *
 * →
 *
 * doel-taxonomy:
 *     functienaam
 *
 * →
 *
 * Pods veld:
 *     relationship_functienaam
 */
if ( ! function_exists( 'tfsc_rel_get_term_ids' ) ) {

    function tfsc_rel_get_term_ids(
        $relationship_field,
        $target_taxonomy
    ) {

        if (
            empty( $relationship_field ) ||
            empty( $target_taxonomy ) ||
            ! taxonomy_exists( $target_taxonomy )
        ) {
            return [];
        }


        $pod = tfsc_rel_get_source_pod();

        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return [];
        }


        /**
         * Eerst Pods traversal proberen.
         *
         * Bijvoorbeeld:
         *
         * relationship_functienaam.term_id
         */
        $traversed_ids = $pod->field(
            $relationship_field . '.term_id'
        );

        $term_ids = [];


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {
                    $term_ids[] = (int) $term_id;
                }
            }
        }


        /**
         * Fallback naar normale relationship return.
         */
        if ( empty( $term_ids ) ) {

            $relations = $pod->field(
                $relationship_field
            );


            if ( empty( $relations ) ) {
                return [];
            }


            /**
             * Eén associatieve relationship normaliseren.
             */
            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {
                $relations = [ $relations ];
            }


            if ( is_numeric( $relations ) ) {
                $relations = [ $relations ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id = (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {
                    $term_ids[] = $term_id;
                }
            }
        }


        /**
         * Opschonen.
         */
        $term_ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );


        /**
         * Alleen terms uit de bedoelde taxonomy accepteren.
         */
        $valid_term_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term = get_term(
                $term_id,
                $target_taxonomy
            );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {
                $valid_term_ids[] = $term_id;
            }
        }


        return $valid_term_ids;
    }
}


/**
 * ============================================================
 * POSTS LOOP
 * ============================================================
 *
 * Automatisch query hooks registreren voor alle taxonomies.
 *
 * Voorbeeld:
 *
 * Elementor:
 *
 * Source:
 *     Vacatures
 *
 * Query ID:
 *     relationship_functienaam
 *
 * Resultaat:
 *
 * Source blijft Vacatures,
 * maar alleen vacatures met de gekoppelde functienaam-term(s).
 */
add_action(
    'init',
    function() {

        $taxonomies = get_taxonomies(
            [],
            'names'
        );


        foreach (
            $taxonomies
            as $taxonomy
        ) {

            $query_id =
                'relationship_' . $taxonomy;


            add_action(
                'elementor/query/' . $query_id,
                function( $query ) use (
                    $query_id,
                    $taxonomy
                ) {

                    $term_ids =
                        tfsc_rel_get_term_ids(
                            $query_id,
                            $taxonomy
                        );


                    /**
                     * Geen relatie:
                     * geen posts tonen.
                     */
                    if ( empty( $term_ids ) ) {

                        $query->set(
                            'post__in',
                            [ 0 ]
                        );

                        return;
                    }


                    /**
                     * Bestaande Elementor tax_query behouden.
                     */
                    $tax_query =
                        $query->get(
                            'tax_query'
                        );


                    if ( ! is_array( $tax_query ) ) {
                        $tax_query = [];
                    }


                    /**
                     * Relationship-filter toevoegen.
                     */
                    $tax_query[] = [
                        'taxonomy'         => $taxonomy,
                        'field'            => 'term_id',
                        'terms'            => $term_ids,
                        'operator'         => 'IN',
                        'include_children' => true,
                    ];


                    /**
                     * Als Elementor al andere taxonomyfilters had,
                     * moeten alle voorwaarden gelden.
                     */
                    if (
                        count( $tax_query ) > 1 &&
                        empty( $tax_query['relation'] )
                    ) {
                        $tax_query['relation'] = 'AND';
                    }


                    $query->set(
                        'tax_query',
                        $tax_query
                    );

                },
                20,
                1
            );
        }
    },
    99
);


/**
 * ============================================================
 * TAXONOMY LOOP
 * ============================================================
 *
 * Voorbeeld:
 *
 * Query ID:
 *     relationship_functienaam
 *
 * →
 *
 * toont rechtstreeks de gekoppelde functienaam-term(s).
 */
add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id = '';


        if (
            isset( $settings['term_taxonomy_id'] ) &&
            is_string( $settings['term_taxonomy_id'] )
        ) {

            $query_id =
                $settings['term_taxonomy_id'];

        } elseif (
            isset( $args['term_taxonomy_id'] ) &&
            is_string( $args['term_taxonomy_id'] )
        ) {

            $query_id =
                $args['term_taxonomy_id'];
        }


        if ( empty( $query_id ) ) {
            return $args;
        }


        $query_id = sanitize_key(
            $query_id
        );


        $prefix =
            'relationship_';


        /**
         * Alleen onze relationship-querys verwerken.
         */
        if (
            strpos(
                $query_id,
                $prefix
            ) !== 0
        ) {
            return $args;
        }


        /**
         * relationship_functienaam
         *
         * →
         *
         * functienaam
         */
        $target_taxonomy = substr(
            $query_id,
            strlen( $prefix )
        );


        /**
         * Elementor's tekstuele Query ID verwijderen uit
         * de uiteindelijke term-query.
         */
        unset(
            $args['term_taxonomy_id']
        );


        if (
            empty( $target_taxonomy ) ||
            ! taxonomy_exists(
                $target_taxonomy
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $term_ids =
            tfsc_rel_get_term_ids(
                $query_id,
                $target_taxonomy
            );


        $args['taxonomy'] =
            $target_taxonomy;


        $args['include'] =
            ! empty( $term_ids )
                ? $term_ids
                : [ 0 ];


        $args['hide_empty'] =
            false;


        $args['orderby'] =
            'include';


        return $args;

    },
    20,
    3
);

/**
 * TFSC - Elementor Derived Taxonomy Relationships
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Toont taxonomy-terms vanuit een huidige CPT/post OF
 * taxonomy-term, met:
 *
 * 1. handmatige override via:
 *      relationship_{target_taxonomy}
 *
 * 2. automatische fallback via:
 *      relationship_{bridge_taxonomy}
 *
 *
 * ============================================================
 * QUERY ID
 * ============================================================
 *
 * derived_{target}_via_{bridge}
 *
 * OF met hierarchy level:
 *
 * derived_{target}_via_{bridge}_level_{X}
 *
 *
 * Voorbeelden:
 *
 * derived_locatie_via_functienaam
 *
 * derived_locatie_via_functienaam_level_0
 * derived_locatie_via_functienaam_level_1
 * derived_locatie_via_functienaam_level_2
 *
 * derived_bedrijfssector_via_functienaam
 *
 *
 * ============================================================
 * VOORBEELD
 * ============================================================
 *
 * Huidig Beroep:
 * Field Service Engineer
 *
 * relationship_locatie ingevuld?
 *
 * JA:
 * → gebruik handmatig geselecteerde locaties.
 *
 * NEE:
 * → lees relationship_functienaam
 * → bijvoorbeeld Field Service Engineer
 * → zoek posts met die functienaam
 * → verzamel hun locatie terms
 * → toon die locaties.
 *
 *
 * ============================================================
 * LEVELS
 * ============================================================
 *
 * level_0 = top-level
 * level_1 = child van level 0
 * level_2 = child van level 1
 */


