/**
 * ============================================================
 * ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        /*
         * --------------------------------------------------------
         * 1. QUERY ID OPHALEN
         * --------------------------------------------------------
         */

        $query_id = '';


        if (
            ! empty( $settings['term_taxonomy_id'] ) &&
            is_string( $settings['term_taxonomy_id'] )
        ) {

            $query_id =
                $settings['term_taxonomy_id'];

        } elseif (
            ! empty( $args['term_taxonomy_id'] ) &&
            is_string( $args['term_taxonomy_id'] )
        ) {

            $query_id =
                $args['term_taxonomy_id'];
        }


        if ( empty( $query_id ) ) {
            return $args;
        }


        $query_id = sanitize_key(
            $query_id
        );


        /*
         * --------------------------------------------------------
         * 2. QUERY ID ONTLEDEN
         * --------------------------------------------------------
         *
         * derived_locatie_via_functienaam
         *
         * OF:
         *
         * derived_locatie_via_functienaam_level_1
         */

        if (
            ! preg_match(
                '/^derived_(.+)_via_(.+?)(?:_level_([0-9]+))?$/',
                $query_id,
                $matches
            )
        ) {
            return $args;
        }


        $target_taxonomy =
            sanitize_key( $matches[1] );


        $bridge_taxonomy =
            sanitize_key( $matches[2] );


        $wanted_level =
            isset( $matches[3] ) &&
            '' !== $matches[3]
                ? (int) $matches[3]
                : null;


        /*
         * Taxonomies controleren.
         */
        if (
            ! taxonomy_exists( $target_taxonomy ) ||
            ! taxonomy_exists( $bridge_taxonomy )
        ) {

            unset( $args['term_taxonomy_id'] );

            $args['include'] = [ 0 ];

            return $args;
        }


        /*
         * Tekstuele Elementor Query ID verwijderen.
         */
        unset(
            $args['term_taxonomy_id']
        );


        /*
         * --------------------------------------------------------
         * 3. HUIDIG PODS-OBJECT
         * --------------------------------------------------------
         */

        $pod =
            tfsc_derived_get_source_pod();


        if ( ! $pod ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * 4. HANDMATIGE OVERRIDE
         * ========================================================
         *
         * Target:
         *
         * locatie
         *
         * →
         *
         * relationship_locatie
         */

        $target_relationship_field =
            'relationship_' . $target_taxonomy;


        $target_term_ids =
            tfsc_derived_get_relationship_term_ids(
                $pod,
                $target_relationship_field,
                $target_taxonomy
            );


        /*
         * ========================================================
         * 5. FALLBACK
         * ========================================================
         *
         * Alleen wanneer relationship_{target} leeg is.
         */

        if ( empty( $target_term_ids ) ) {


            /*
             * ----------------------------------------------------
             * 5A. BRIDGE RELATIONSHIP OPHALEN
             * ----------------------------------------------------
             *
             * functienaam
             *
             * →
             *
             * relationship_functienaam
             */

            $bridge_relationship_field =
                'relationship_' . $bridge_taxonomy;


            $bridge_term_ids =
                tfsc_derived_get_relationship_term_ids(
                    $pod,
                    $bridge_relationship_field,
                    $bridge_taxonomy
                );


            if ( empty( $bridge_term_ids ) ) {

                $args['include'] = [ 0 ];

                return $args;
            }


            /*
             * ----------------------------------------------------
             * 5B. POST TYPES VINDEN DIE BEIDE TAXONOMIES GEBRUIKEN
             * ----------------------------------------------------
             *
             * Bijvoorbeeld:
             *
             * functienaam + locatie
             *
             * →
             *
             * vacature
             */

            $bridge_tax_object =
                get_taxonomy(
                    $bridge_taxonomy
                );


            $target_tax_object =
                get_taxonomy(
                    $target_taxonomy
                );


            if (
                ! $bridge_tax_object ||
                ! $target_tax_object
            ) {

                $args['include'] = [ 0 ];

                return $args;
            }


            $shared_post_types =
                array_values(
                    array_intersect(
                        (array) $bridge_tax_object->object_type,
                        (array) $target_tax_object->object_type
                    )
                );


            if ( empty( $shared_post_types ) ) {

                $args['include'] = [ 0 ];

                return $args;
            }


            /*
             * ----------------------------------------------------
             * 5C. POSTS MET BRIDGE TERMS ZOEKEN
             * ----------------------------------------------------
             */

            $post_ids = get_posts(
                [
                    'post_type' =>
                        $shared_post_types,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        [
                            [
                                'taxonomy' =>
                                    $bridge_taxonomy,

                                'field' =>
                                    'term_id',

                                'terms' =>
                                    $bridge_term_ids,

                                'operator' =>
                                    'IN',
                            ],
                        ],
                ]
            );


            if ( empty( $post_ids ) ) {

                $args['include'] = [ 0 ];

                return $args;
            }


            /*
             * ----------------------------------------------------
             * 5D. TARGET TERMS VAN DIE POSTS VERZAMELEN
             * ----------------------------------------------------
             */

            $derived_ids = [];


            foreach (
                $post_ids
                as $post_id
            ) {

                $ids = wp_get_post_terms(
                    $post_id,
                    $target_taxonomy,
                    [
                        'fields' => 'ids',
                    ]
                );


                if (
                    ! is_wp_error( $ids ) &&
                    ! empty( $ids )
                ) {

                    $derived_ids = array_merge(
                        $derived_ids,
                        $ids
                    );
                }
            }


            $target_term_ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $derived_ids
                            )
                        )
                    )
                );
        }


        /*
         * Geen handmatige of afgeleide waarden.
         */
        if ( empty( $target_term_ids ) ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * 6. OPTIONEEL HIERARCHY LEVEL FILTER
         * ========================================================
         */

        if ( null !== $wanted_level ) {

            $level_ids = [];


            foreach (
                $target_term_ids
                as $term_id
            ) {

                $level = count(
                    get_ancestors(
                        $term_id,
                        $target_taxonomy,
                        'taxonomy'
                    )
                );


                if (
                    $level === $wanted_level
                ) {

                    $level_ids[] =
                        $term_id;
                }
            }


            $target_term_ids =
                array_values(
                    array_unique(
                        $level_ids
                    )
                );
        }


        /*
         * ========================================================
         * 7. ELEMENTOR TERM QUERY
         * ========================================================
         */

        $args['taxonomy'] =
            $target_taxonomy;


        $args['include'] =
            ! empty( $target_term_ids )
                ? $target_term_ids
                : [ 0 ];


        $args['hide_empty'] =
            false;


        $args['orderby'] =
            'name';


        $args['order'] =
            'ASC';


        return $args;

    },
    30,
    3
);

/**
 * TFSC - Elementor - Generieke Pods Relationship Queries
 *
 * Werkt voor:
 *
 * 1. CPT/post als bron
 * 2. Taxonomy-term als bron
 *
 * En voor:
 *
 * A. Elementor Posts Loop
 *    → toont posts die gekoppelde taxonomy-term(s) hebben
 *
 * B. Elementor Taxonomy Loop
 *    → toont de gekoppelde taxonomy-term(s) zelf
 *
 *
 * ============================================================
 * NAAMCONVENTIE
 * ============================================================
 *
 * Taxonomy:
 *     {taxonomy_name}
 *
 * Pods relationshipveld:
 *     relationship_{taxonomy_name}
 *
 * Elementor Query ID:
 *     relationship_{taxonomy_name}
 *
 *
 * Voorbeelden:
 *
 * taxonomy:
 *     functienaam
 *
 * Pods:
 *     relationship_functienaam
 *
 * Elementor:
 *     relationship_functienaam
 *
 *
 * taxonomy:
 *     functie-inhoud
 *
 * Pods:
 *     relationship_functie-inhoud
 *
 * Elementor:
 *     relationship_functie-inhoud
 */


/**
 * ============================================================
 * HELPER 1
 * PODS-OBJECT VAN HUIDIGE CONTEXT
 * ============================================================
 */

if ( ! function_exists( 'tfsc_relationship_v2_source_pod' ) ) {

    function tfsc_relationship_v2_source_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }

        $object = get_queried_object();


        /*
         * --------------------------------------------------------
         * TAXONOMY-TERM ALS BRON
         * --------------------------------------------------------
         */
        if (
            $object instanceof WP_Term &&
            ! empty( $object->taxonomy ) &&
            ! empty( $object->term_id )
        ) {

            $pod = pods(
                $object->taxonomy,
                (int) $object->term_id
            );

            if (
                $pod &&
                $pod->exists()
            ) {
                return $pod;
            }
        }


        /*
         * --------------------------------------------------------
         * CPT / POST ALS BRON
         * --------------------------------------------------------
         */
        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID )
        ) {

            $post_type = get_post_type(
                $object->ID
            );

            if ( $post_type ) {

                $pod = pods(
                    $post_type,
                    (int) $object->ID
                );

                if (
                    $pod &&
                    $pod->exists()
                ) {
                    return $pod;
                }
            }
        }


        /*
         * --------------------------------------------------------
         * ELEMENTOR PREVIEW FALLBACK
         * --------------------------------------------------------
         */
        $post_id = (int) get_the_ID();

        if ( $post_id ) {

            $post_type = get_post_type(
                $post_id
            );

            if ( $post_type ) {

                $pod = pods(
                    $post_type,
                    $post_id
                );

                if (
                    $pod &&
                    $pod->exists()
                ) {
                    return $pod;
                }
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * HELPER 2
 * GEKOPPELDE TAXONOMY TERM IDs OPHALEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_relationship_v2_term_ids' ) ) {

    function tfsc_relationship_v2_term_ids(
        $relationship_field,
        $target_taxonomy
    ) {

        if (
            empty( $relationship_field ) ||
            empty( $target_taxonomy ) ||
            ! taxonomy_exists( $target_taxonomy )
        ) {
            return [];
        }


        $pod =
            tfsc_relationship_v2_source_pod();


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * --------------------------------------------------------
         * EERST PODS TRAVERSAL
         * --------------------------------------------------------
         *
         * Bijvoorbeeld:
         *
         * relationship_functie-inhoud.term_id
         */

        $traversed_ids = $pod->field(
            $relationship_field . '.term_id'
        );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {
                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /*
         * --------------------------------------------------------
         * FALLBACK NAAR NORMALE RELATIONSHIP RETURN
         * --------------------------------------------------------
         */

        if ( empty( $term_ids ) ) {

            $relations = $pod->field(
                $relationship_field
            );


            if ( empty( $relations ) ) {
                return [];
            }


            /*
             * Eén associatieve relationship normaliseren.
             */
            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {
                $relations = [ $relations ];
            }


            /*
             * Eén los numeriek ID normaliseren.
             */
            if ( is_numeric( $relations ) ) {
                $relations = [ $relations ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {
                    $term_ids[] =
                        $term_id;
                }
            }
        }


        /*
         * IDs opschonen.
         */
        $term_ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );


        /*
         * Alleen IDs accepteren die daadwerkelijk
         * tot de bedoelde taxonomy behoren.
         */
        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term = get_term(
                $term_id,
                $target_taxonomy
            );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {
                $valid_ids[] =
                    $term_id;
            }
        }


        return $valid_ids;
    }
}


/**
 * ============================================================
 * POSTS LOOP
 * ============================================================
 *
 * BELANGRIJK:
 *
 * We registreren deze hooks pas op wp_loaded.
 *
 * Dan zijn ook de door Pods geregistreerde custom
 * taxonomies beschikbaar.
 *
 *
 * Voorbeeld Elementor:
 *
 * Source:
 *     Vacatures
 *
 * Query ID:
 *     relationship_functie-inhoud
 *
 *
 * Huidige CPT:
 *
 * relationship_functie-inhoud
 *     ↓
 * gekoppelde functie-inhoud term
 *     ↓
 * alleen vacatures met die term
 */

add_action(
    'wp_loaded',
    function() {

        $taxonomies = get_taxonomies(
            [],
            'names'
        );


        foreach (
            $taxonomies
            as $taxonomy
        ) {

            $query_id =
                'relationship_' . $taxonomy;


            add_action(
                'elementor/query/' . $query_id,
                function( $query ) use (
                    $taxonomy,
                    $query_id
                ) {

                    /*
                     * Relationship-term(s) van huidige
                     * CPT of taxonomy-term ophalen.
                     */
                    $term_ids =
                        tfsc_relationship_v2_term_ids(
                            $query_id,
                            $taxonomy
                        );


                    /*
                     * Geen relationship ingevuld:
                     * geen posts tonen.
                     *
                     * Hiermee voorkomen we dat Elementor
                     * ineens alle posts toont.
                     */
                    if ( empty( $term_ids ) ) {

                        $query->set(
                            'post__in',
                            [ 0 ]
                        );

                        return;
                    }


                    /*
                     * Eventuele bestaande Elementor
                     * tax_query behouden.
                     */
                    $tax_query =
                        $query->get(
                            'tax_query'
                        );


                    if ( ! is_array( $tax_query ) ) {
                        $tax_query = [];
                    }


                    /*
                     * Relationship-filter toevoegen.
                     */
                    $tax_query[] = [
                        'taxonomy' =>
                            $taxonomy,

                        'field' =>
                            'term_id',

                        'terms' =>
                            $term_ids,

                        'operator' =>
                            'IN',

                        'include_children' =>
                            true,
                    ];


                    /*
                     * Als Elementor al andere taxonomyfilters
                     * gebruikt, moeten beide voorwaarden gelden.
                     */
                    if (
                        count( $tax_query ) > 1 &&
                        empty( $tax_query['relation'] )
                    ) {
                        $tax_query['relation'] =
                            'AND';
                    }


                    /*
                     * Alleen taxonomyfilter aanpassen.
                     *
                     * Source/post_type blijft volledig
                     * door Elementor bepaald.
                     */
                    $query->set(
                        'tax_query',
                        $tax_query
                    );

                },
                20,
                1
            );
        }

    },
    20
);


/**
 * ============================================================
 * TAXONOMY LOOP
 * ============================================================
 *
 * Deze bestaande functionaliteit blijft behouden.
 *
 * Voorbeeld:
 *
 * Query ID:
 *     relationship_functie-inhoud
 *
 * →
 *
 * toont rechtstreeks de gekoppelde
 * functie-inhoud term(s).
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id = '';


        /*
         * Elementor Taxonomy Loop Query ID.
         */
        if (
            isset( $settings['term_taxonomy_id'] ) &&
            is_string(
                $settings['term_taxonomy_id']
            )
        ) {

            $query_id =
                $settings['term_taxonomy_id'];

        } elseif (
            isset( $args['term_taxonomy_id'] ) &&
            is_string(
                $args['term_taxonomy_id']
            )
        ) {

            $query_id =
                $args['term_taxonomy_id'];
        }


        if ( empty( $query_id ) ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $query_id
            );


        $prefix =
            'relationship_';


        /*
         * Alleen onze relationship Query ID's.
         */
        if (
            strpos(
                $query_id,
                $prefix
            ) !== 0
        ) {
            return $args;
        }


        /*
         * relationship_functie-inhoud
         *
         * →
         *
         * functie-inhoud
         */
        $target_taxonomy =
            substr(
                $query_id,
                strlen( $prefix )
            );


        /*
         * Tekstuele Elementor Query ID verwijderen.
         */
        unset(
            $args['term_taxonomy_id']
        );


        if (
            empty( $target_taxonomy ) ||
            ! taxonomy_exists(
                $target_taxonomy
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Relationship-term IDs ophalen.
         */
        $term_ids =
            tfsc_relationship_v2_term_ids(
                $query_id,
                $target_taxonomy
            );


        /*
         * Elementor Taxonomy Loop instellen.
         */
        $args['taxonomy'] =
            $target_taxonomy;


        $args['include'] =
            ! empty( $term_ids )
                ? $term_ids
                : [ 0 ];


        $args['hide_empty'] =
            false;


        $args['orderby'] =
            'include';


        return $args;

    },
    20,
    3
);

/**
 * TFSC - Elementor Posts filteren via Pods relationships
 *
 * ============================================================
 * QUERY ID
 * ============================================================
 *
 * Elementor Posts / Loop Grid:
 *
 * relationship_posts
 *
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Deze query haalt posts op vanuit Pods relationshipvelden.
 *
 * Werkt op:
 *
 * - CPT / post
 * - taxonomy term archives
 *
 *
 * ============================================================
 * BELANGRIJKE LOGICA
 * ============================================================
 *
 * CPT / POST CONTEXT
 * ------------------------------------------------------------
 *
 * Op een gewone post/CPT worden alle bruikbare Pods fields met:
 *
 * relationship_
 *
 * gelezen.
 *
 * Bijvoorbeeld:
 *
 * relationship_functienaam
 * relationship_functie-inhoud
 *
 *
 * Verschillende fields worden gecombineerd met:
 *
 * AND
 *
 *
 * Meerdere terms binnen één field:
 *
 * IN / OR
 *
 *
 * ============================================================
 * TAXONOMY TERM CONTEXT
 * ============================================================
 *
 * Op een taxonomy term wordt NIET meer automatisch naar alle
 * relationship_* fields gekeken.
 *
 * Alleen het relationshipveld dat bij de huidige taxonomy hoort
 * wordt gebruikt.
 *
 *
 * Voorbeeld:
 *
 * huidige taxonomy:
 *
 * beroep_functie-inhoud
 *
 * →
 *
 * relationship_functie-inhoud
 *
 *
 * huidige taxonomy:
 *
 * beroep_functienaam
 *
 * →
 *
 * relationship_functienaam
 *
 *
 * Hierdoor kan deze query veilig naast de TFSC
 * archive_relationship_* taxonomy query draaien.
 *
 *
 * ============================================================
 * TAXONOMY PREFIX
 * ============================================================
 *
 * De volgende prefixes worden automatisch verwijderd bij het
 * zoeken naar het relationshipveld:
 *
 * beroep_
 * beroep-
 * beroepengids_
 * beroepengids-
 *
 *
 * Dus bijvoorbeeld:
 *
 * beroep_functie-inhoud
 *
 * wordt:
 *
 * functie-inhoud
 *
 * en gebruikt:
 *
 * relationship_functie-inhoud
 *
 *
 * ============================================================
 * LEGE RELATIONSHIPS
 * ============================================================
 *
 * Als geen bruikbare relationship gevonden wordt:
 *
 * → geen posts tonen
 */


/**
 * ============================================================
 * 1. CONTEXT BEPALEN
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_relationship_posts_v2_get_context'
    )
) {

    function tfsc_relationship_posts_v2_get_context() {

        $object =
            get_queried_object();


        /**
         * TAXONOMY TERM
         */
        if (
            $object instanceof WP_Term &&
            ! empty( $object->taxonomy ) &&
            ! empty( $object->term_id )
        ) {

            return [
                'type'     => 'term',
                'taxonomy' => $object->taxonomy,
                'term_id'  => (int) $object->term_id,
            ];
        }


        /**
         * NORMALE POST / CPT
         */
        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID ) &&
            'elementor_library'
            !==
            get_post_type(
                $object->ID
            )
        ) {

            return [
                'type'    => 'post',
                'post_id' => (int) $object->ID,
            ];
        }


        /**
         * ELEMENTOR THEME BUILDER PREVIEW
         */
        if (
            function_exists(
                'tfsc_derived_rel_v2_get_context_post_id'
            )
        ) {

            $post_id =
                (int)
                tfsc_derived_rel_v2_get_context_post_id();


            if (
                $post_id &&
                'elementor_library'
                !==
                get_post_type(
                    $post_id
                )
            ) {

                return [
                    'type'    => 'post',
                    'post_id' => $post_id,
                ];
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * 2. PODS OBJECT UIT CONTEXT
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_relationship_posts_v2_get_pod'
    )
) {

    function tfsc_relationship_posts_v2_get_pod(
        $context
    ) {

        if (
            ! function_exists( 'pods' ) ||
            ! is_array( $context ) ||
            empty( $context['type'] )
        ) {
            return false;
        }


        /**
         * TAXONOMY TERM
         */
        if (
            'term' === $context['type']
        ) {

            if (
                empty( $context['taxonomy'] ) ||
                empty( $context['term_id'] )
            ) {
                return false;
            }


            $pod =
                pods(
                    $context['taxonomy'],
                    (int) $context['term_id']
                );


            if (
                $pod &&
                $pod->exists()
            ) {
                return $pod;
            }


            return false;
        }


        /**
         * POST / CPT
         */
        if (
            'post' === $context['type']
        ) {

            if (
                empty( $context['post_id'] )
            ) {
                return false;
            }


            $post_id =
                (int) $context['post_id'];


            $post_type =
                get_post_type(
                    $post_id
                );


            if ( ! $post_type ) {
                return false;
            }


            $pod =
                pods(
                    $post_type,
                    $post_id
                );


            if (
                $pod &&
                $pod->exists()
            ) {
                return $pod;
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * 3. TARGET TAXONOMY UIT HUIDIGE ARCHIVE TAXONOMY AFLEIDEN
 * ============================================================
 *
 * Voorbeelden:
 *
 * beroep_functie-inhoud
 * →
 * functie-inhoud
 *
 * beroep_functienaam
 * →
 * functienaam
 *
 * beroepengids_kennisgebied
 * →
 * kennisgebied
 */

if (
    ! function_exists(
        'tfsc_relationship_posts_v2_archive_target_taxonomy'
    )
) {

    function tfsc_relationship_posts_v2_archive_target_taxonomy(
        $source_taxonomy
    ) {

        $source_taxonomy =
            sanitize_key(
                $source_taxonomy
            );


        if ( ! $source_taxonomy ) {
            return '';
        }


        /**
         * Eerst exact dezelfde taxonomy proberen.
         *
         * Handig wanneer beroep-side en vacature-side toevallig
         * dezelfde interne taxonomy name gebruiken.
         */
        if (
            taxonomy_exists(
                $source_taxonomy
            )
        ) {

            $exact_field =
                'relationship_'
                .
                $source_taxonomy;


            /*
             * Hier nog niet valideren of field bestaat.
             * Dat gebeurt later tegen de actieve Pod.
             */
        }


        /**
         * Mogelijke beroepengids prefixes verwijderen.
         */
        $prefixes = [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ];


        foreach (
            $prefixes
            as $prefix
        ) {

            if (
                0 === strpos(
                    $source_taxonomy,
                    $prefix
                )
            ) {

                $candidate =
                    substr(
                        $source_taxonomy,
                        strlen(
                            $prefix
                        )
                    );


                $candidate =
                    sanitize_key(
                        $candidate
                    );


                if (
                    $candidate &&
                    taxonomy_exists(
                        $candidate
                    )
                ) {

                    return $candidate;
                }
            }
        }


        /**
         * Als de source taxonomy zelf ook de target taxonomy is.
         */
        if (
            taxonomy_exists(
                $source_taxonomy
            )
        ) {
            return $source_taxonomy;
        }


        return '';
    }
}


/**
 * ============================================================
 * 4. RELATIONSHIP TERM IDS OPHALEN
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_relationship_posts_v2_get_term_ids'
    )
) {

    function tfsc_relationship_posts_v2_get_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            ! $field_name ||
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return [];
        }


        $term_ids =
            [];


        /**
         * PODS TRAVERSAL
         */
        $traversed =
            $pod->field(
                $field_name
                .
                '.term_id'
            );


        if (
            ! empty(
                $traversed
            )
        ) {

            foreach (
                (array) $traversed
                as $term_id
            ) {

                if (
                    is_numeric(
                        $term_id
                    )
                ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /**
         * NORMALE RELATIONSHIP FALLBACK
         */
        if (
            empty(
                $term_ids
            )
        ) {

            $relations =
                $pod->field(
                    $field_name
                );


            if (
                empty(
                    $relations
                )
            ) {
                return [];
            }


            /**
             * Eén associatieve relatie.
             */
            if (
                is_array( $relations ) &&
                (
                    isset(
                        $relations['term_id']
                    ) ||
                    isset(
                        $relations['id']
                    ) ||
                    isset(
                        $relations['ID']
                    )
                )
            ) {

                $relations = [
                    $relations,
                ];
            }


            /**
             * Eén numeriek ID.
             */
            if (
                is_numeric(
                    $relations
                )
            ) {

                $relations = [
                    $relations,
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id =
                    0;


                if (
                    is_numeric(
                        $relation
                    )
                ) {

                    $term_id =
                        (int) $relation;

                } elseif (
                    is_array(
                        $relation
                    )
                ) {

                    $term_id =
                        (int) (
                            $relation['term_id']
                            ??
                            $relation['id']
                            ??
                            $relation['ID']
                            ??
                            0
                        );

                } elseif (
                    is_object(
                        $relation
                    )
                ) {

                    $term_id =
                        (int) (
                            $relation->term_id
                            ??
                            $relation->id
                            ??
                            $relation->ID
                            ??
                            0
                        );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        /**
         * OPSCHONEN
         */
        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        if (
            empty(
                $term_ids
            )
        ) {
            return [];
        }


        /**
         * CONTROLEREN OF IDS BIJ TARGET TAXONOMY HOREN
         */
        $valid_ids =
            [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error(
                    $term
                )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        return
            array_values(
                array_unique(
                    $valid_ids
                )
            );
    }
}


/**
 * ============================================================
 * 5. CONTROLEREN OF TAXONOMY BIJ ELEMENTOR SOURCE HOORT
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_relationship_posts_v2_taxonomy_matches_source'
    )
) {

    function tfsc_relationship_posts_v2_taxonomy_matches_source(
        $taxonomy,
        $query_post_types
    ) {

        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        $taxonomy_object =
            get_taxonomy(
                $taxonomy
            );


        if ( ! $taxonomy_object ) {
            return false;
        }


        foreach (
            (array) $query_post_types
            as $query_post_type
        ) {

            if (
                in_array(
                    $query_post_type,
                    (array)
                    $taxonomy_object
                        ->object_type,
                    true
                )
            ) {
                return true;
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * 6. ELEMENTOR QUERY
 * ============================================================
 */

add_action(
    'elementor/query/relationship_posts',
    function( $query ) {

        /**
         * ====================================================
         * BASISCONTROLES
         * ====================================================
         */

        if (
            ! function_exists(
                'pods'
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        $context =
            tfsc_relationship_posts_v2_get_context();


        if ( ! $context ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        $pod =
            tfsc_relationship_posts_v2_get_pod(
                $context
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /**
         * ====================================================
         * ELEMENTOR SOURCE
         * ====================================================
         */

        $query_post_types =
            $query->get(
                'post_type'
            );


        if (
            empty(
                $query_post_types
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        $query_post_types =
            array_values(
                array_filter(
                    (array)
                    $query_post_types
                )
            );


        /**
         * ====================================================
         * PODS FIELDS
         * ====================================================
         */

        $fields =
            $pod->fields();


        if (
            empty( $fields ) ||
            ! is_array(
                $fields
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        $relationship_tax_queries =
            [];


        /**
         * ====================================================
         * TAXONOMY TERM CONTEXT
         * ====================================================
         *
         * BELANGRIJK:
         *
         * Hier gebruiken we slechts ÉÉN relationshipveld.
         *
         * Dus NIET meer alle relationship_* fields.
         */

        if (
            'term' ===
            $context['type']
        ) {

            $source_taxonomy =
                $context['taxonomy'];


            $target_taxonomy =
                tfsc_relationship_posts_v2_archive_target_taxonomy(
                    $source_taxonomy
                );


            if (
                ! $target_taxonomy
            ) {

                $query->set(
                    'post__in',
                    [ 0 ]
                );

                return;
            }


            $field_name =
                'relationship_'
                .
                $target_taxonomy;


            /**
             * Field moet daadwerkelijk op deze taxonomy Pod bestaan.
             */
            if (
                ! array_key_exists(
                    $field_name,
                    $fields
                )
            ) {

                $query->set(
                    'post__in',
                    [ 0 ]
                );

                return;
            }


            /**
             * Target taxonomy moet bij Elementor Source horen.
             */
            if (
                ! tfsc_relationship_posts_v2_taxonomy_matches_source(
                    $target_taxonomy,
                    $query_post_types
                )
            ) {

                $query->set(
                    'post__in',
                    [ 0 ]
                );

                return;
            }


            $term_ids =
                tfsc_relationship_posts_v2_get_term_ids(
                    $pod,
                    $field_name,
                    $target_taxonomy
                );


            if (
                empty(
                    $term_ids
                )
            ) {

                $query->set(
                    'post__in',
                    [ 0 ]
                );

                return;
            }


            $relationship_tax_queries[] =
                [
                    'taxonomy' =>
                        $target_taxonomy,

                    'field' =>
                        'term_id',

                    'terms' =>
                        $term_ids,

                    'operator' =>
                        'IN',

                    'include_children' =>
                        true,
                ];
        }


        /**
         * ====================================================
         * POST / CPT CONTEXT
         * ====================================================
         *
         * Hier blijven alle relationship_* fields bruikbaar.
         */

        elseif (
            'post' ===
            $context['type']
        ) {

            foreach (
                $fields
                as $field_name =>
                    $field_definition
            ) {

                if (
                    ! is_string(
                        $field_name
                    ) ||
                    '' === $field_name ||
                    0 !== strpos(
                        $field_name,
                        'relationship_'
                    )
                ) {
                    continue;
                }


                $taxonomy =
                    substr(
                        $field_name,
                        strlen(
                            'relationship_'
                        )
                    );


                $taxonomy =
                    sanitize_key(
                        $taxonomy
                    );


                if (
                    ! $taxonomy ||
                    ! taxonomy_exists(
                        $taxonomy
                    )
                ) {
                    continue;
                }


                if (
                    ! tfsc_relationship_posts_v2_taxonomy_matches_source(
                        $taxonomy,
                        $query_post_types
                    )
                ) {
                    continue;
                }


                $term_ids =
                    tfsc_relationship_posts_v2_get_term_ids(
                        $pod,
                        $field_name,
                        $taxonomy
                    );


                if (
                    empty(
                        $term_ids
                    )
                ) {
                    continue;
                }


                $relationship_tax_queries[] =
                    [
                        'taxonomy' =>
                            $taxonomy,

                        'field' =>
                            'term_id',

                        'terms' =>
                            $term_ids,

                        'operator' =>
                            'IN',

                        'include_children' =>
                            true,
                    ];
            }
        }


        /**
         * ====================================================
         * GEEN BRUIKBARE RELATIONSHIPS
         * ====================================================
         */

        if (
            empty(
                $relationship_tax_queries
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /**
         * ====================================================
         * RELATIONSHIP GROUP
         * ====================================================
         */

        $relationship_group =
            [
                'relation' =>
                    'AND',
            ];


        foreach (
            $relationship_tax_queries
            as $relationship_tax_query
        ) {

            $relationship_group[] =
                $relationship_tax_query;
        }


        /**
         * ====================================================
         * BESTAANDE ELEMENTOR TAX QUERY BEWAREN
         * ====================================================
         */

        $existing_tax_query =
            $query->get(
                'tax_query'
            );


        if (
            ! is_array(
                $existing_tax_query
            )
        ) {

            $existing_tax_query =
                [];
        }


        /**
         * ====================================================
         * FINALE TAX QUERY
         * ====================================================
         */

        if (
            ! empty(
                $existing_tax_query
            )
        ) {

            $final_tax_query =
                [
                    'relation' =>
                        'AND',

                    $existing_tax_query,

                    $relationship_group,
                ];

        } else {

            $final_tax_query =
                $relationship_group;
        }


        $query->set(
            'tax_query',
            $final_tax_query
        );
    },
    20,
    1
);

/**
 * TFSC - Elementor - Smart Pods Relationship Queries
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Generieke koppeling tussen:
 *
 * - actieve CPT/post
 * - actieve taxonomy-term
 * - Pods relationshipvelden
 * - Elementor Posts Loops
 * - Elementor Taxonomy Loops
 *
 *
 * ============================================================
 * NAAMCONVENTIE
 * ============================================================
 *
 * Taxonomy:
 *
 *   functienaam
 *
 * Pods relationshipveld:
 *
 *   relationship_functienaam
 *
 * Elementor Query ID:
 *
 *   relationship_functienaam
 *
 *
 * ============================================================
 * POSTS LOOP
 * ============================================================
 *
 * Bron:
 * - CPT/post
 * - taxonomy-term
 *
 * Elementor:
 *
 *   Source: Vacatures
 *
 * OPTIE A — expliciete keuze:
 *
 *   Query ID:
 *   relationship_functienaam
 *
 * Dan gebruikt de query alleen:
 *
 *   relationship_functienaam
 *
 *
 * OPTIE B — automatische keuze:
 *
 * Laat de Query ID leeg of gebruik:
 *
 *   relationship_auto
 *
 * Dan:
 *
 * - 0 bruikbare relationshipvelden → geen posts
 * - 1 bruikbaar relationshipveld   → automatisch gebruiken
 * - >1 bruikbare velden            → geen posts, omdat keuze ambigu is
 *
 *
 * ============================================================
 * TAXONOMY LOOP
 * ============================================================
 *
 * Query ID:
 *
 *   relationship_functienaam
 *
 * →
 *
 * toont rechtstreeks de gekoppelde functienaam-term(s).
 */


/**
 * ============================================================
 * HELPER 1
 * Actieve Pods broncontext ophalen
 * ============================================================
 */

if ( ! function_exists( 'tfsc_smart_rel_get_source_pod' ) ) {

    function tfsc_smart_rel_get_source_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }

        $object = get_queried_object();


        /*
         * TAXONOMY TERM
         */
        if (
            $object instanceof WP_Term &&
            ! empty( $object->taxonomy ) &&
            ! empty( $object->term_id )
        ) {

            $pod = pods(
                $object->taxonomy,
                (int) $object->term_id
            );

            if (
                $pod &&
                $pod->exists()
            ) {
                return $pod;
            }
        }


        /*
         * CPT / POST
         */
        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID )
        ) {

            $post_type = get_post_type(
                $object->ID
            );

            if ( $post_type ) {

                $pod = pods(
                    $post_type,
                    (int) $object->ID
                );

                if (
                    $pod &&
                    $pod->exists()
                ) {
                    return $pod;
                }
            }
        }


        /*
         * Elementor preview fallback.
         */
        $post_id = (int) get_the_ID();

        if ( $post_id ) {

            $post_type = get_post_type(
                $post_id
            );

            if ( $post_type ) {

                $pod = pods(
                    $post_type,
                    $post_id
                );

                if (
                    $pod &&
                    $pod->exists()
                ) {
                    return $pod;
                }
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * HELPER 2
 * Term IDs uit één relationshipveld halen
 * ============================================================
 */

if ( ! function_exists( 'tfsc_smart_rel_get_term_ids' ) ) {

    function tfsc_smart_rel_get_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $field_name ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * Eerst Pods traversal proberen.
         *
         * relationship_functienaam.term_id
         */
        $traversed = $pod->field(
            $field_name . '.term_id'
        );


        if ( ! empty( $traversed ) ) {

            foreach (
                (array) $traversed
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {
                    $term_ids[] = (int) $term_id;
                }
            }
        }


        /*
         * Fallback naar normale relationship return.
         */
        if ( empty( $term_ids ) ) {

            $relations = $pod->field(
                $field_name
            );


            if ( empty( $relations ) ) {
                return [];
            }


            /*
             * Eén associatieve relationship normaliseren.
             */
            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {
                $relations = [ $relations ];
            }


            /*
             * Eén numeriek ID normaliseren.
             */
            if ( is_numeric( $relations ) ) {
                $relations = [ $relations ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {
                    $term_ids[] = $term_id;
                }
            }
        }


        /*
         * IDs opschonen.
         */
        $term_ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );


        /*
         * Alleen terms accepteren die echt
         * bij de bedoelde taxonomy horen.
         */
        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term = get_term(
                $term_id,
                $taxonomy
            );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {
                $valid_ids[] = $term_id;
            }
        }


        return $valid_ids;
    }
}


/**
 * ============================================================
 * HELPER 3
 * Alle bruikbare relationshipvelden vinden
 * ============================================================
 *
 * Alleen relationshipvelden waarvan:
 *
 * - taxonomy bestaat;
 * - taxonomy bij het Elementor post type hoort;
 * - veld daadwerkelijk een waarde bevat.
 */

if ( ! function_exists( 'tfsc_smart_rel_get_usable_fields' ) ) {

    function tfsc_smart_rel_get_usable_fields(
        $pod,
        $query_post_types
    ) {

        if ( ! $pod ) {
            return [];
        }


        $fields = $pod->fields();

        if (
            empty( $fields ) ||
            ! is_array( $fields )
        ) {
            return [];
        }


        $usable = [];


        foreach (
            $fields
            as $field_name => $field_definition
        ) {

            if (
                ! is_string( $field_name ) ||
                0 !== strpos(
                    $field_name,
                    'relationship_'
                )
            ) {
                continue;
            }


            /*
             * relationship_functienaam
             *
             * →
             *
             * functienaam
             */
            $taxonomy = substr(
                $field_name,
                strlen( 'relationship_' )
            );


            if (
                empty( $taxonomy ) ||
                ! taxonomy_exists( $taxonomy )
            ) {
                continue;
            }


            /*
             * Taxonomy moet bij de Elementor Source horen.
             */
            $taxonomy_object =
                get_taxonomy(
                    $taxonomy
                );


            if ( ! $taxonomy_object ) {
                continue;
            }


            $belongs_to_query = false;


            foreach (
                (array) $query_post_types
                as $query_post_type
            ) {

                if (
                    in_array(
                        $query_post_type,
                        (array) $taxonomy_object->object_type,
                        true
                    )
                ) {
                    $belongs_to_query = true;
                    break;
                }
            }


            if ( ! $belongs_to_query ) {
                continue;
            }


            /*
             * Veld moet daadwerkelijk gekoppelde terms hebben.
             */
            $term_ids =
                tfsc_smart_rel_get_term_ids(
                    $pod,
                    $field_name,
                    $taxonomy
                );


            if ( empty( $term_ids ) ) {
                continue;
            }


            $usable[ $field_name ] = [
                'taxonomy' => $taxonomy,
                'term_ids' => $term_ids,
            ];
        }


        return $usable;
    }
}


/**
 * ============================================================
 * POSTS LOOP
 * ============================================================
 *
 * Twee modi:
 *
 * 1. relationship_auto
 *    → automatisch als exact 1 bruikbaar relationshipveld bestaat
 *
 * 2. relationship_{taxonomy}
 *    → expliciet dat relationshipveld gebruiken
 */


/**
 * ------------------------------------------------------------
 * AUTOMATISCHE MODUS
 * ------------------------------------------------------------
 */

add_action(
    'elementor/query/relationship_auto',
    function( $query ) {

        $pod =
            tfsc_smart_rel_get_source_pod();


        if ( ! $pod ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        $post_types =
            (array) $query->get(
                'post_type'
            );


        if ( empty( $post_types ) ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        $usable =
            tfsc_smart_rel_get_usable_fields(
                $pod,
                $post_types
            );


        /*
         * Alleen automatisch gebruiken als
         * er exact 1 bruikbaar relationshipveld is.
         */
        if ( 1 !== count( $usable ) ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        $relationship =
            reset( $usable );


        $tax_query =
            $query->get(
                'tax_query'
            );


        if ( ! is_array( $tax_query ) ) {
            $tax_query = [];
        }


        $tax_query[] = [
            'taxonomy' =>
                $relationship['taxonomy'],

            'field' =>
                'term_id',

            'terms' =>
                $relationship['term_ids'],

            'operator' =>
                'IN',

            'include_children' =>
                true,
        ];


        $query->set(
            'tax_query',
            $tax_query
        );

    },
    20,
    1
);


/**
 * ------------------------------------------------------------
 * EXPLICIETE MODUS
 * ------------------------------------------------------------
 *
 * Voor alle bestaande taxonomies registreren we:
 *
 * relationship_functienaam
 * relationship_functie-inhoud
 * relationship_locatie
 * enz.
 */

add_action(
    'wp_loaded',
    function() {

        $taxonomies = get_taxonomies(
            [],
            'names'
        );


        foreach (
            $taxonomies
            as $taxonomy
        ) {

            $query_id =
                'relationship_' . $taxonomy;


            add_action(
                'elementor/query/' . $query_id,
                function( $query ) use (
                    $query_id,
                    $taxonomy
                ) {

                    $pod =
                        tfsc_smart_rel_get_source_pod();


                    if ( ! $pod ) {

                        $query->set(
                            'post__in',
                            [ 0 ]
                        );

                        return;
                    }


                    /*
                     * Controleren of taxonomy bij Elementor Source hoort.
                     */
                    $post_types =
                        (array) $query->get(
                            'post_type'
                        );


                    if ( empty( $post_types ) ) {

                        $query->set(
                            'post__in',
                            [ 0 ]
                        );

                        return;
                    }


                    $taxonomy_object =
                        get_taxonomy(
                            $taxonomy
                        );


                    if ( ! $taxonomy_object ) {

                        $query->set(
                            'post__in',
                            [ 0 ]
                        );

                        return;
                    }


                    $belongs_to_query =
                        false;


                    foreach (
                        $post_types
                        as $post_type
                    ) {

                        if (
                            in_array(
                                $post_type,
                                (array) $taxonomy_object->object_type,
                                true
                            )
                        ) {

                            $belongs_to_query =
                                true;

                            break;
                        }
                    }


                    if ( ! $belongs_to_query ) {

                        $query->set(
                            'post__in',
                            [ 0 ]
                        );

                        return;
                    }


                    /*
                     * Exact gelijknamig Pods veld uitlezen.
                     */
                    $term_ids =
                        tfsc_smart_rel_get_term_ids(
                            $pod,
                            $query_id,
                            $taxonomy
                        );


                    if ( empty( $term_ids ) ) {

                        $query->set(
                            'post__in',
                            [ 0 ]
                        );

                        return;
                    }


                    /*
                     * Bestaande Elementor tax_query behouden.
                     */
                    $tax_query =
                        $query->get(
                            'tax_query'
                        );


                    if ( ! is_array( $tax_query ) ) {
                        $tax_query = [];
                    }


                    $tax_query[] = [
                        'taxonomy' =>
                            $taxonomy,

                        'field' =>
                            'term_id',

                        'terms' =>
                            $term_ids,

                        'operator' =>
                            'IN',

                        'include_children' =>
                            true,
                    ];


                    $query->set(
                        'tax_query',
                        $tax_query
                    );

                },
                20,
                1
            );
        }

    },
    20
);


/**
 * ============================================================
 * TAXONOMY LOOP
 * ============================================================
 *
 * relationship_{taxonomy}
 *
 * toont rechtstreeks de gekoppelde taxonomy terms.
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id = '';


        if (
            isset( $settings['term_taxonomy_id'] ) &&
            is_string(
                $settings['term_taxonomy_id']
            )
        ) {

            $query_id =
                $settings['term_taxonomy_id'];

        } elseif (
            isset( $args['term_taxonomy_id'] ) &&
            is_string(
                $args['term_taxonomy_id']
            )
        ) {

            $query_id =
                $args['term_taxonomy_id'];
        }


        if ( empty( $query_id ) ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $query_id
            );


        if (
            0 !== strpos(
                $query_id,
                'relationship_'
            ) ||
            'relationship_auto' === $query_id
        ) {
            return $args;
        }


        $taxonomy = substr(
            $query_id,
            strlen( 'relationship_' )
        );


        if (
            empty( $taxonomy ) ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return $args;
        }


        $pod =
            tfsc_smart_rel_get_source_pod();


        if ( ! $pod ) {

            unset(
                $args['term_taxonomy_id']
            );

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $term_ids =
            tfsc_smart_rel_get_term_ids(
                $pod,
                $query_id,
                $taxonomy
            );


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            ! empty( $term_ids )
                ? $term_ids
                : [ 0 ];


        $args['hide_empty'] =
            false;


        $args['orderby'] =
            'include';


        return $args;

    },
    20,
    3
);

/**
 * TFSC - Elementor - Pods Relationship Taxonomy Query
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Toont in een Elementor Taxonomy Loop de taxonomy-terms
 * die via een Pods relationshipveld gekoppeld zijn aan
 * de huidige context.
 *
 * De bron mag zijn:
 *
 * - CPT / post
 * - taxonomy-term archive
 *
 *
 * ============================================================
 * NAAMCONVENTIE
 * ============================================================
 *
 * Taxonomy:
 *
 *     {taxonomy_name}
 *
 * Pods relationshipveld:
 *
 *     relationship_{taxonomy_name}
 *
 * Elementor Query ID:
 *
 *     relationship_{taxonomy_name}
 *
 *
 * VOORBEELD
 * ============================================================
 *
 * Taxonomy:
 *
 *     locatie
 *
 * Pods veld:
 *
 *     relationship_locatie
 *
 * Elementor Taxonomy Loop Query ID:
 *
 *     relationship_locatie
 *
 *
 * Ander voorbeeld:
 *
 *     relationship_functienaam
 *     relationship_functie-inhoud
 *     relationship_kennisgebied
 *
 *
 * ============================================================
 * WERKING
 * ============================================================
 *
 * huidige CPT/post OF taxonomy-term
 *      ↓
 * open bijbehorend Pods-object
 *      ↓
 * lees relationship_{taxonomy}
 *      ↓
 * verzamel gekoppelde term IDs
 *      ↓
 * Elementor toont alleen die taxonomy-terms
 */


add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        /*
         * ========================================================
         * 1. QUERY ID OPHALEN
         * ========================================================
         */

        $query_id = '';


        if (
            isset( $settings['term_taxonomy_id'] ) &&
            is_string( $settings['term_taxonomy_id'] )
        ) {

            $query_id =
                $settings['term_taxonomy_id'];

        } elseif (
            isset( $args['term_taxonomy_id'] ) &&
            is_string( $args['term_taxonomy_id'] )
        ) {

            $query_id =
                $args['term_taxonomy_id'];
        }


        if ( empty( $query_id ) ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $query_id
            );


        /*
         * Alleen relationship_ Query ID's verwerken.
         */
        if (
            0 !== strpos(
                $query_id,
                'relationship_'
            )
        ) {
            return $args;
        }


        /*
         * ========================================================
         * 2. TAXONOMY AFLEIDEN
         * ========================================================
         *
         * relationship_locatie
         *
         * →
         *
         * locatie
         */

        $taxonomy = substr(
            $query_id,
            strlen( 'relationship_' )
        );


        if (
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy ) ||
            ! function_exists( 'pods' )
        ) {

            unset(
                $args['term_taxonomy_id']
            );

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Elementor Query ID verwijderen uit de daadwerkelijke
         * WordPress term query.
         */
        unset(
            $args['term_taxonomy_id']
        );


        /*
         * ========================================================
         * 3. HUIDIGE BRONCONTEXT
         * ========================================================
         */

        $object =
            get_queried_object();

        $pod =
            false;


        /*
         * --------------------------------------------------------
         * TAXONOMY TERM
         * --------------------------------------------------------
         */

        if (
            $object instanceof WP_Term &&
            ! empty( $object->taxonomy ) &&
            ! empty( $object->term_id )
        ) {

            $pod = pods(
                $object->taxonomy,
                (int) $object->term_id
            );
        }


        /*
         * --------------------------------------------------------
         * CPT / POST
         * --------------------------------------------------------
         */

        elseif (
            $object instanceof WP_Post &&
            ! empty( $object->ID )
        ) {

            $post_type =
                get_post_type(
                    $object->ID
                );


            if ( $post_type ) {

                $pod = pods(
                    $post_type,
                    (int) $object->ID
                );
            }
        }


        /*
         * --------------------------------------------------------
         * ELEMENTOR PREVIEW FALLBACK
         * --------------------------------------------------------
         */

        if (
            ! $pod ||
            ! $pod->exists()
        ) {

            $post_id =
                (int) get_the_ID();


            if ( $post_id ) {

                $post_type =
                    get_post_type(
                        $post_id
                    );


                if ( $post_type ) {

                    $pod = pods(
                        $post_type,
                        $post_id
                    );
                }
            }
        }


        if (
            ! $pod ||
            ! $pod->exists()
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * 4. RELATIONSHIP UITLEZEN
         * ========================================================
         */

        $term_ids = [];


        /*
         * Eerst via Pods traversal proberen.
         *
         * relationship_locatie.term_id
         */

        $traversed_ids =
            $pod->field(
                $query_id . '.term_id'
            );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /*
         * ========================================================
         * 5. FALLBACK NAAR NORMALE PODS RETURN
         * ========================================================
         */

        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    $query_id
                );


            if ( empty( $relations ) ) {

                $args['include'] =
                    [ 0 ];

                return $args;
            }


            /*
             * Eén associatieve relationship normaliseren.
             */
            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {

                $relations = [
                    $relations
                ];
            }


            if ( is_numeric( $relations ) ) {

                $relations = [
                    $relations
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        /*
         * ========================================================
         * 6. TERM IDs OPSCHONEN EN CONTROLEREN
         * ========================================================
         */

        $term_ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );


        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term = get_term(
                $term_id,
                $taxonomy
            );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        /*
         * ========================================================
         * 7. ELEMENTOR TAXONOMY LOOP
         * ========================================================
         */

        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            ! empty( $valid_ids )
                ? $valid_ids
                : [ 0 ];


        $args['hide_empty'] =
            false;


        /*
         * Volgorde van Pods relationship behouden.
         */
        $args['orderby'] =
            'include';


        return $args;

    },
    20,
    3
);

/**
 * TFSC - Elementor - Taxonomy Archive Relationship Posts
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Filtert een Elementor Posts / Loop Grid op basis van
 * Pods relationshipvelden van de ACTIEVE TAXONOMY-TERM.
 *
 * Deze snippet is uitsluitend bedoeld voor taxonomy archives.
 *
 *
 * ============================================================
 * QUERY ID
 * ============================================================
 *
 * Elementor Posts / Loop Grid:
 *
 *     relationship_posts
 *
 *
 * ============================================================
 * VOORBEELD
 * ============================================================
 *
 * Actief taxonomy archive:
 *
 *     beroep_functie-inhoud
 *     → Inbedrijfstellen
 *
 * Pods veld op deze taxonomy-term:
 *
 *     relationship_functie-inhoud
 *
 * gekoppeld aan:
 *
 *     functie-inhoud
 *     → Inbedrijfstellen
 *
 * Elementor:
 *
 *     Source: Vacatures
 *     Query ID: relationship_posts
 *
 * Resultaat:
 *
 *     alleen vacatures met
 *     functie-inhoud = Inbedrijfstellen
 *
 *
 * ============================================================
 * MEERDERE RELATIONSHIPVELDEN
 * ============================================================
 *
 * Als meerdere bruikbare relationshipvelden op dezelfde
 * taxonomy-term gevuld zijn, worden deze met AND gecombineerd.
 *
 * Meerdere terms binnen één relationshipveld gebruiken IN.
 */


add_action(
    'elementor/query/relationship_posts',
    function( $query ) {

        /*
         * ========================================================
         * 1. PODS BESCHIKBAAR?
         * ========================================================
         */

        if ( ! function_exists( 'pods' ) ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /*
         * ========================================================
         * 2. ALLEEN ACTIEVE TAXONOMY-TERM GEBRUIKEN
         * ========================================================
         */

        $object = get_queried_object();


        if (
            ! ( $object instanceof WP_Term ) ||
            empty( $object->taxonomy ) ||
            empty( $object->term_id )
        ) {

            /*
             * Dit is bewust GEEN CPT-query.
             *
             * CPT-functionaliteit bouwen we apart.
             */
            return;
        }


        /*
         * ========================================================
         * 3. PODS-OBJECT VAN ACTIEVE TAXONOMY-TERM
         * ========================================================
         */

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /*
         * ========================================================
         * 4. POST TYPE VAN ELEMENTOR SOURCE
         * ========================================================
         *
         * Elementor blijft bepalen wat voor posts worden gezocht.
         *
         * Bijvoorbeeld:
         *
         *     Source: Vacatures
         */

        $query_post_types = $query->get(
            'post_type'
        );


        if ( empty( $query_post_types ) ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        $query_post_types =
            (array) $query_post_types;


        /*
         * ========================================================
         * 5. ALLE PODS-VELDEN OPHALEN
         * ========================================================
         */

        $fields = $pod->fields();


        if (
            empty( $fields ) ||
            ! is_array( $fields )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /*
         * ========================================================
         * 6. BRUIKBARE RELATIONSHIPVELDEN ZOEKEN
         * ========================================================
         */

        $relationship_tax_queries = [];


        foreach (
            $fields
            as $field_name => $field_definition
        ) {

            /*
             * Alleen velden:
             *
             * relationship_*
             */
            if (
                ! is_string( $field_name ) ||
                0 !== strpos(
                    $field_name,
                    'relationship_'
                )
            ) {
                continue;
            }


            /*
             * ----------------------------------------------------
             * DOEL-TAXONOMY AFLEIDEN
             * ----------------------------------------------------
             *
             * relationship_functie-inhoud
             *
             * →
             *
             * functie-inhoud
             */

            $taxonomy = substr(
                $field_name,
                strlen( 'relationship_' )
            );


            if (
                empty( $taxonomy ) ||
                ! taxonomy_exists( $taxonomy )
            ) {
                continue;
            }


            /*
             * ====================================================
             * 7. CONTROLEREN OF TAXONOMY BIJ ELEMENTOR SOURCE HOORT
             * ====================================================
             */

            $taxonomy_object =
                get_taxonomy(
                    $taxonomy
                );


            if ( ! $taxonomy_object ) {
                continue;
            }


            $usable_for_query = false;


            foreach (
                $query_post_types
                as $query_post_type
            ) {

                if (
                    in_array(
                        $query_post_type,
                        (array) $taxonomy_object->object_type,
                        true
                    )
                ) {

                    $usable_for_query = true;

                    break;
                }
            }


            if ( ! $usable_for_query ) {
                continue;
            }


            /*
             * ====================================================
             * 8. GEKOPPELDE TERM IDs OPHALEN
             * ====================================================
             */

            $term_ids = [];


            /*
             * Eerst Pods traversal.
             */
            $traversed_ids =
                $pod->field(
                    $field_name . '.term_id'
                );


            if ( ! empty( $traversed_ids ) ) {

                foreach (
                    (array) $traversed_ids
                    as $term_id
                ) {

                    if ( is_numeric( $term_id ) ) {

                        $term_ids[] =
                            (int) $term_id;
                    }
                }
            }


            /*
             * ----------------------------------------------------
             * FALLBACK: NORMALE PODS RELATIONSHIP RETURN
             * ----------------------------------------------------
             */

            if ( empty( $term_ids ) ) {

                $relations =
                    $pod->field(
                        $field_name
                    );


                if ( empty( $relations ) ) {
                    continue;
                }


                /*
                 * Eén associatieve relatie normaliseren.
                 */
                if (
                    is_array( $relations ) &&
                    (
                        isset( $relations['term_id'] ) ||
                        isset( $relations['id'] ) ||
                        isset( $relations['ID'] )
                    )
                ) {

                    $relations = [
                        $relations
                    ];
                }


                /*
                 * Eén numeriek ID normaliseren.
                 */
                if ( is_numeric( $relations ) ) {

                    $relations = [
                        $relations
                    ];
                }


                foreach (
                    (array) $relations
                    as $relation
                ) {

                    $term_id = 0;


                    if ( is_numeric( $relation ) ) {

                        $term_id =
                            (int) $relation;

                    } elseif ( is_array( $relation ) ) {

                        $term_id = (int) (
                            $relation['term_id']
                            ?? $relation['id']
                            ?? $relation['ID']
                            ?? 0
                        );

                    } elseif ( is_object( $relation ) ) {

                        $term_id = (int) (
                            $relation->term_id
                            ?? $relation->id
                            ?? $relation->ID
                            ?? 0
                        );
                    }


                    if ( $term_id ) {

                        $term_ids[] =
                            $term_id;
                    }
                }
            }


            /*
             * ====================================================
             * 9. IDS OPSCHONEN
             * ====================================================
             */

            $term_ids = array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


            /*
             * Alleen IDs accepteren die bij de juiste
             * taxonomy horen.
             */
            $valid_term_ids = [];


            foreach (
                $term_ids
                as $term_id
            ) {

                $term = get_term(
                    $term_id,
                    $taxonomy
                );


                if (
                    $term instanceof WP_Term &&
                    ! is_wp_error( $term )
                ) {

                    $valid_term_ids[] =
                        $term_id;
                }
            }


            if ( empty( $valid_term_ids ) ) {
                continue;
            }


            /*
             * ====================================================
             * 10. TAX QUERY VOOR DEZE RELATIONSHIP
             * ====================================================
             */

            $relationship_tax_queries[] = [

                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    $valid_term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    true,
            ];
        }


        /*
         * ========================================================
         * 11. GEEN BRUIKBARE RELATIONSHIPS
         * ========================================================
         */

        if (
            empty(
                $relationship_tax_queries
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /*
         * ========================================================
         * 12. BESTAANDE ELEMENTOR TAX_QUERY BEWAREN
         * ========================================================
         */

        $existing_tax_query =
            $query->get(
                'tax_query'
            );


        if (
            ! is_array(
                $existing_tax_query
            )
        ) {

            $existing_tax_query =
                [];
        }


        /*
         * ========================================================
         * 13. RELATIONSHIPS MET AND COMBINEREN
         * ========================================================
         */

        $relationship_group = [
            'relation' => 'AND',
        ];


        foreach (
            $relationship_tax_queries
            as $relationship_tax_query
        ) {

            $relationship_group[] =
                $relationship_tax_query;
        }


        /*
         * Bestaande Elementor filtering behouden.
         */
        if ( ! empty( $existing_tax_query ) ) {

            $final_tax_query = [
                'relation' => 'AND',
                $existing_tax_query,
                $relationship_group,
            ];

        } else {

            $final_tax_query =
                $relationship_group;
        }


        /*
         * ========================================================
         * 14. QUERY TOEPASSEN
         * ========================================================
         */

        $query->set(
            'tax_query',
            $final_tax_query
        );

    },
    20,
    1
);

/**
 * TFSC - Elementor Taxonomy Loop filters
 *
 * Query ID's:
 *
 * taxonomy_level_X
 *
 * current_taxonomy
 * current_taxonomy_level_X
 */


/**
 * Term IDs van exact taxonomy-level ophalen.
 */
function tfsc_taxonomy_level_term_ids(
    $taxonomy,
    $level,
    $hide_empty = true
) {

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return [];
    }

    $terms = get_terms( [
        'taxonomy'   => $taxonomy,
        'hide_empty' => (bool) $hide_empty,
    ] );

    if (
        is_wp_error( $terms ) ||
        ! $terms
    ) {
        return [];
    }

    $ids = [];

    foreach ( $terms as $term ) {

        if (
            count(
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                )
            ) === (int) $level
        ) {
            $ids[] = (int) $term->term_id;
        }
    }

    return $ids;
}


/**
 * Bepaal de relevante taxonomy voor iedere context.
 *
 * Volgorde:
 * 1. Virtueel TFSC taxonomy-basearchief.
 * 2. Normaal WordPress taxonomy-, categorie- of tagarchief.
 * 3. Taxonomy die Elementor zelf aan de loop meegeeft.
 */
function tfsc_current_loop_taxonomy( $args ) {

    $taxonomy = get_query_var(
        'tfsc_taxonomy_archive'
    );

    if (
        ! $taxonomy &&
        isset( $GLOBALS['wp_query'] )
    ) {
        $taxonomy =
            $GLOBALS['wp_query']->get(
                'tfsc_taxonomy_archive'
            );
    }

    if ( ! $taxonomy ) {
        $queried_object = get_queried_object();

        if ( $queried_object instanceof WP_Term ) {
            $taxonomy = $queried_object->taxonomy;
        }
    }

    if ( ! $taxonomy ) {
        $taxonomy = $args['taxonomy'] ?? '';

        if ( is_array( $taxonomy ) ) {
            $taxonomy = reset( $taxonomy );
        }
    }

    return taxonomy_exists( $taxonomy )
        ? $taxonomy
        : '';
}


/**
 * Elementor Taxonomy Loop.
 */
add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        $query_id = sanitize_key(
            $settings['term_taxonomy_id']
            ?? ''
        );

        if ( ! $query_id ) {
            return $args;
        }


        /**
         * ====================================================
         * taxonomy_level_X
         * ====================================================
         */

        if (
            preg_match(
                '/^taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {

            $taxonomy =
                $args['taxonomy']
                ?? '';

            if ( is_array( $taxonomy ) ) {
                $taxonomy = reset( $taxonomy );
            }

            if ( ! taxonomy_exists( $taxonomy ) ) {
                return $args;
            }

            unset(
                $args['term_taxonomy_id']
            );

            $ids =
                tfsc_taxonomy_level_term_ids(
                    $taxonomy,
                    (int) $matches[1],
                    ! empty( $args['hide_empty'] )
                );

            $args['include'] =
                $ids ?: [ 0 ];

            return $args;
        }


        /**
         * ====================================================
         * current_taxonomy
         * current_taxonomy_level_X
         * ====================================================
         */

        $is_current =
            'current_taxonomy' === $query_id;

        $has_level =
            preg_match(
                '/^current_taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            );

        if (
            ! $is_current &&
            ! $has_level
        ) {
            return $args;
        }


        $taxonomy =
            tfsc_current_loop_taxonomy( $args );

        if ( ! $taxonomy ) {
            $args['include'] = [ 0 ];
            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );

        $args['taxonomy']   = $taxonomy;
        // Respecteer de Elementor-instelling ‘Hide Empty’.
        $args['hide_empty'] = ! empty( $args['hide_empty'] );
        $args['orderby']    = 'name';
        $args['order']      = 'ASC';


        /**
         * current_taxonomy = alle terms.
         */
        if ( $is_current ) {
            return $args;
        }


        /**
         * current_taxonomy_level_X.
         */
        $ids =
            tfsc_taxonomy_level_term_ids(
                $taxonomy,
                (int) $matches[1],
                ! empty( $args['hide_empty'] )
            );

        $args['include'] =
            $ids ?: [ 0 ];

        return $args;
    },
    20,
    3
);

/**
 * TFSC - Elementor - CPT Relationship Taxonomy Query
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Toont in een Elementor Taxonomy Loop automatisch de terms
 * die relevant zijn voor de huidige CPT-post.
 *
 *
 * ============================================================
 * QUERY ID
 * ============================================================
 *
 *     relationship_{taxonomy}
 *
 *
 * Voorbeeld:
 *
 *     relationship_locatie
 *
 *
 * ============================================================
 * VOORBEELD
 * ============================================================
 *
 * Huidige CPT:
 *
 *     Beroep → Field Service Engineer
 *
 * Pods velden op Beroep:
 *
 *     relationship_functienaam
 *         → Field Service Engineer
 *
 *     relationship_locatie
 *         → veld bestaat
 *
 *
 * Elementor Taxonomy Loop:
 *
 *     Source:
 *         locatie
 *
 *     Query ID:
 *         relationship_locatie
 *
 *
 * De code doet:
 *
 * huidige Beroep
 *      ↓
 * controleer of relationship_locatie bestaat
 *      ↓
 * lees relationship_functienaam
 *      ↓
 * verkrijg functienaam-term(s)
 *      ↓
 * zoek posttypes die zowel:
 *
 *     functienaam
 *     locatie
 *
 * gebruiken
 *      ↓
 * zoek gepubliceerde posts met die functienaam
 *      ↓
 * verzamel hun locatie-terms
 *      ↓
 * voeg ook ancestors toe
 *      ↓
 * geef die terms terug aan Elementor
 *
 *
 * ============================================================
 * DEPTH
 * ============================================================
 *
 * Deze snippet filtert NIET op hierarchy level.
 *
 * Dat gebeurt volledig via Elementor:
 *
 *     Filter by Depth
 *     Depth
 *
 *
 * ============================================================
 * BELANGRIJK
 * ============================================================
 *
 * relationship_locatie hoeft voor deze functionaliteit niet
 * handmatig gevuld te zijn.
 *
 * Het veld moet alleen op de huidige Pod BESTAAN.
 *
 * De daadwerkelijke locaties worden afgeleid via:
 *
 *     relationship_functienaam
 *
 *
 * ============================================================
 * CONFLICTEN
 * ============================================================
 *
 * Deze snippet:
 *
 * - gebruikt alleen elementor/loop_taxonomy/args
 * - reageert alleen op relationship_* Query ID's
 * - doet niets met relationship_posts
 * - doet niets met taxonomy_level_*
 * - doet niets met current_taxonomy*
 *
 * Priority 30 wordt gebruikt zodat de bestaande TFSC
 * Taxonomy Loop filters op priority 20 eerst kunnen draaien.
 */


/**
 * ============================================================
 * HELPER
 * Pods relationship → geldige taxonomy term IDs
 * ============================================================
 *
 * Unieke functienaam zodat deze niet botst met andere
 * TFSC relationship snippets.
 */

if ( ! function_exists( 'tfsc_cpt_rel_tax_get_term_ids' ) ) {

    function tfsc_cpt_rel_tax_get_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $field_name ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * --------------------------------------------------------
         * 1. PODS TRAVERSAL
         * --------------------------------------------------------
         *
         * Bijvoorbeeld:
         *
         * relationship_functienaam.term_id
         */

        $traversed_ids =
            $pod->field(
                $field_name . '.term_id'
            );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /*
         * --------------------------------------------------------
         * 2. FALLBACK NORMALE PODS RETURN
         * --------------------------------------------------------
         */

        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    $field_name
                );


            if ( empty( $relations ) ) {
                return [];
            }


            /*
             * Eén associatieve relatie normaliseren.
             */
            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {

                $relations = [
                    $relations
                ];
            }


            /*
             * Eén numeriek ID normaliseren.
             */
            if ( is_numeric( $relations ) ) {

                $relations = [
                    $relations
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        /*
         * IDs uniek en integer maken.
         */

        $term_ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );


        /*
         * Alleen IDs accepteren die daadwerkelijk
         * tot deze taxonomy behoren.
         */

        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $valid_ids
            )
        );
    }
}


/**
 * ============================================================
 * ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        /*
         * ========================================================
         * 1. QUERY ID OPHALEN
         * ========================================================
         */

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $settings['term_taxonomy_id']
            );


        /*
         * Alleen Query ID's verwerken die beginnen met:
         *
         * relationship_
         */

        if (
            0 !== strpos(
                $query_id,
                'relationship_'
            )
        ) {
            return $args;
        }


        /*
         * ========================================================
         * 2. ALLEEN CPT / POST CONTEXT
         * ========================================================
         *
         * Taxonomy archives worden bewust NIET door deze snippet
         * behandeld.
         *
         * Daarvoor blijft relationship_posts apart bestaan.
         */

        $current_object =
            get_queried_object();


        if (
            ! (
                $current_object
                instanceof WP_Post
            ) ||
            empty(
                $current_object->ID
            )
        ) {
            return $args;
        }


        $current_post_id =
            (int) $current_object->ID;


        $current_post_type =
            get_post_type(
                $current_post_id
            );


        if ( ! $current_post_type ) {
            return $args;
        }


        /*
         * ========================================================
         * 3. PODS BESCHIKBAAR?
         * ========================================================
         */

        if (
            ! function_exists(
                'pods'
            )
        ) {
            return $args;
        }


        $pod =
            pods(
                $current_post_type,
                $current_post_id
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return $args;
        }


        /*
         * ========================================================
         * 4. TARGET RELATIONSHIP BEPALEN
         * ========================================================
         *
         * Query ID:
         *
         * relationship_locatie
         *
         * betekent:
         *
         * Pods veld:
         *
         * relationship_locatie
         *
         * target taxonomy:
         *
         * locatie
         */

        $target_field =
            $query_id;


        $target_taxonomy =
            substr(
                $query_id,
                strlen(
                    'relationship_'
                )
            );


        if (
            empty(
                $target_taxonomy
            ) ||
            ! taxonomy_exists(
                $target_taxonomy
            )
        ) {
            return $args;
        }


        /*
         * ========================================================
         * 5. CONTROLEREN OF TARGET RELATIONSHIP FIELD BESTAAT
         * ========================================================
         *
         * Het veld hoeft NIET gevuld te zijn.
         *
         * Het bestaan van het veld geeft aan dat deze afgeleide
         * relationship voor deze CPT bedoeld is.
         */

        $pod_fields =
            $pod->fields();


        if (
            ! is_array(
                $pod_fields
            ) ||
            ! array_key_exists(
                $target_field,
                $pod_fields
            )
        ) {

            /*
             * Geen gelijknamig relationshipveld op deze Pod:
             * Elementor standaardquery ongemoeid laten.
             */

            return $args;
        }


        /*
         * ========================================================
         * 6. CONTROLEREN OF ELEMENTOR SOURCE KLOPT
         * ========================================================
         *
         * Bijvoorbeeld:
         *
         * Query ID:
         *     relationship_locatie
         *
         * Elementor Source:
         *     locatie
         *
         * Deze moeten bij elkaar horen.
         */

        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ? reset(
                    $args['taxonomy']
                )
                : $args['taxonomy'];


        if (
            $elementor_taxonomy !==
            $target_taxonomy
        ) {

            /*
             * Bewust niets doen bij een verkeerde Source.
             */

            return $args;
        }


        /*
         * ========================================================
         * 7. BRIDGE RELATIONSHIP
         * ========================================================
         *
         * Voor deze functionaliteit gebruiken we:
         *
         * relationship_functienaam
         *
         * →
         *
         * taxonomy:
         *
         * functienaam
         */

        $bridge_field =
            'relationship_functienaam';


        $bridge_taxonomy =
            'functienaam';


        /*
         * Bridge field moet op de Pod bestaan.
         */

        if (
            ! array_key_exists(
                $bridge_field,
                $pod_fields
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * 8. GESELECTEERDE FUNCTIENAAM OPHALEN
         * ========================================================
         */

        $bridge_term_ids =
            tfsc_cpt_rel_tax_get_term_ids(
                $pod,
                $bridge_field,
                $bridge_taxonomy
            );


        if (
            empty(
                $bridge_term_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * 9. GEDEELDE POST TYPES ZOEKEN
         * ========================================================
         *
         * We hardcoden "vacature" bewust NIET.
         *
         * Er wordt automatisch gezocht naar posttypes die zowel:
         *
         * - functienaam
         * - target taxonomy
         *
         * gebruiken.
         */

        $bridge_taxonomy_object =
            get_taxonomy(
                $bridge_taxonomy
            );


        $target_taxonomy_object =
            get_taxonomy(
                $target_taxonomy
            );


        if (
            ! $bridge_taxonomy_object ||
            ! $target_taxonomy_object
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $shared_post_types =
            array_values(
                array_intersect(
                    (array)
                    $bridge_taxonomy_object
                        ->object_type,

                    (array)
                    $target_taxonomy_object
                        ->object_type
                )
            );


        /*
         * Huidige bron-CPT uitsluiten.
         *
         * We zoeken immers de gekoppelde content,
         * bijvoorbeeld Vacatures, niet opnieuw Beroepen.
         */

        $shared_post_types =
            array_values(
                array_diff(
                    $shared_post_types,
                    [
                        $current_post_type,
                    ]
                )
            );


        if (
            empty(
                $shared_post_types
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * 10. POSTS MET DE GESELECTEERDE FUNCTIENAAM ZOEKEN
         * ========================================================
         */

        $related_post_ids =
            get_posts(
                [
                    'post_type' =>
                        $shared_post_types,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        [
                            [
                                'taxonomy' =>
                                    $bridge_taxonomy,

                                'field' =>
                                    'term_id',

                                'terms' =>
                                    $bridge_term_ids,

                                'operator' =>
                                    'IN',
                            ],
                        ],
                ]
            );


        if (
            empty(
                $related_post_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * 11. TARGET TERMS VERZAMELEN
         * ========================================================
         *
         * Bijvoorbeeld:
         *
         * vacatures met Field Service Engineer
         *
         * →
         *
         * alle locatie-terms van die vacatures
         */

        $target_term_ids =
            [];


        foreach (
            $related_post_ids
            as $related_post_id
        ) {

            $post_term_ids =
                wp_get_post_terms(
                    $related_post_id,
                    $target_taxonomy,
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error(
                    $post_term_ids
                ) ||
                empty(
                    $post_term_ids
                )
            ) {
                continue;
            }


            foreach (
                $post_term_ids
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                /*
                 * Direct gekoppelde term toevoegen.
                 */

                $target_term_ids[] =
                    $term_id;


                /*
                 * =================================================
                 * OOK ANCESTORS TOEVOEGEN
                 * =================================================
                 *
                 * Dit is belangrijk voor Elementor Filter by Depth.
                 *
                 * Voorbeeld:
                 *
                 * Eindhoven
                 *      ↓
                 * Noord-Brabant
                 *      ↓
                 * Nederland
                 *
                 * Als alleen Eindhoven aan de vacature hangt,
                 * voegen we ook Noord-Brabant en Nederland toe.
                 *
                 * Daardoor kan Elementor daarna zelf met Depth
                 * bepalen welk niveau weergegeven wordt.
                 */

                if (
                    is_taxonomy_hierarchical(
                        $target_taxonomy
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            $target_taxonomy,
                            'taxonomy'
                        );


                    if (
                        ! empty(
                            $ancestors
                        )
                    ) {

                        $target_term_ids =
                            array_merge(
                                $target_term_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        /*
         * ========================================================
         * 12. IDS OPSCHONEN
         * ========================================================
         */

        $target_term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $target_term_ids
                        )
                    )
                )
            );


        if (
            empty(
                $target_term_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * 13. ELEMENTOR TAXONOMY QUERY FILTEREN
         * ========================================================
         *
         * LET OP:
         *
         * Geen hierarchy-level filtering hier.
         *
         * Elementor Filter by Depth blijft daarvoor verantwoordelijk.
         */

        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $target_taxonomy;


        $args['include'] =
            $target_term_ids;


        $args['hide_empty'] =
            false;


        /*
         * We overschrijven bewust NIET:
         *
         * - parent
         * - child_of
         * - depth instellingen
         *
         * zodat Elementor zijn eigen Filter by Depth
         * kan blijven toepassen.
         */


        return $args;

    },
    30,
    3
);

/**
 * TFSC - Filtercontext via taxonomy archive URL
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Maakt echte filter-resultaat URLs mogelijk zoals:
 *
 * /locaties/nederland/friesland/heerenveen/
 *     ?functienaam=field-service-engineer
 *
 *
 * Hierdoor is:
 *
 * - Locatie = bepaald door het taxonomy archive
 * - Functienaam = bepaald door de URL parameter
 *
 * De WordPress query wordt vervolgens daadwerkelijk gefilterd
 * op die functienaam.
 *
 *
 * ============================================================
 * GEBRUIK
 * ============================================================
 *
 * Op een Beroep:
 *
 * relationship_functienaam
 *     → Field Service Engineer
 *
 * Een locatie-link kan vervolgens worden:
 *
 * /locaties/.../heerenveen/
 *     ?functienaam=field-service-engineer
 *
 *
 * ============================================================
 * SHORTCODE
 * ============================================================
 *
 * Gebruik voor een URL naar de huidige taxonomy-term:
 *
 * [tfsc_filter_term_url]
 *
 * Deze shortcode:
 *
 * 1. pakt de huidige term in de taxonomy-loop;
 * 2. maakt de normale term archive URL;
 * 3. kijkt naar de huidige Beroep-post;
 * 4. leest relationship_functienaam;
 * 5. voegt ?functienaam=slug toe.
 *
 *
 * ============================================================
 * CONFLICTEN
 * ============================================================
 *
 * Deze snippet gebruikt NIET:
 *
 * - elementor/loop_taxonomy/args
 * - elementor/query/relationship_posts
 * - taxonomy_level_*
 * - current_taxonomy*
 * - relationship_locatie
 *
 * De bestaande snippets blijven dus ongemoeid.
 */


/**
 * ============================================================
 * 1. QUERY VAR REGISTREREN
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'functienaam';

        return $vars;
    }
);


/**
 * ============================================================
 * 2. HELPER
 * FUNCTIENAAM UIT relationship_functienaam OPHALEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_filter_context_functienaam_slugs' ) ) {

    function tfsc_filter_context_functienaam_slugs( $post_id ) {

        if (
            ! $post_id ||
            ! function_exists( 'pods' ) ||
            ! taxonomy_exists( 'functienaam' )
        ) {
            return [];
        }


        $post_type =
            get_post_type( $post_id );


        if ( ! $post_type ) {
            return [];
        }


        $pod =
            pods(
                $post_type,
                (int) $post_id
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return [];
        }


        /*
         * relationship_functienaam moet daadwerkelijk
         * op deze Pod bestaan.
         */

        $fields =
            $pod->fields();


        if (
            ! is_array( $fields ) ||
            ! array_key_exists(
                'relationship_functienaam',
                $fields
            )
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * Eerst Pods traversal.
         */

        $traversed =
            $pod->field(
                'relationship_functienaam.term_id'
            );


        if ( ! empty( $traversed ) ) {

            foreach (
                (array) $traversed
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {
                    $term_ids[] = (int) $term_id;
                }
            }
        }


        /*
         * Fallback normale relationship return.
         */

        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    'relationship_functienaam'
                );


            if ( empty( $relations ) ) {
                return [];
            }


            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {
                $relations = [ $relations ];
            }


            if ( is_numeric( $relations ) ) {
                $relations = [ $relations ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {
                    $term_ids[] = $term_id;
                }
            }
        }


        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        /*
         * IDs naar slugs omzetten.
         */

        $slugs = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    'functienaam'
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {
                $slugs[] =
                    $term->slug;
            }
        }


        return array_values(
            array_unique(
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 3. SHORTCODE VOOR TAXONOMY LOOP LINK
 * ============================================================
 *
 * [tfsc_filter_term_url]
 *
 * Gebruik deze als URL voor het klikbare taxonomy-loop item.
 */

add_shortcode(
    'tfsc_filter_term_url',
    function() {

        /*
         * --------------------------------------------------------
         * ACTUELE TERM IN DE ELEMENTOR TAXONOMY LOOP
         * --------------------------------------------------------
         */

        $term =
            get_queried_object();


        /*
         * In een Elementor taxonomy-loop kan get_queried_object()
         * nog steeds het bovenliggende Beroep zijn.
         *
         * Daarom eerst get_term() proberen op basis van
         * de huidige loop-object context.
         */

        $current_id =
            get_the_ID();


        if (
            ! (
                $term instanceof WP_Term
            )
        ) {

            /*
             * Elementor kan tijdens taxonomy loops de huidige
             * term als globale object-context zetten.
             */

            global $wp_query;

            if (
                isset( $wp_query->queried_object ) &&
                $wp_query->queried_object instanceof WP_Term
            ) {
                $term =
                    $wp_query->queried_object;
            }
        }


        /*
         * Als Elementor de term rechtstreeks als current object
         * beschikbaar heeft, gebruiken.
         */

        if (
            function_exists( 'get_queried_object' )
        ) {

            $possible_term =
                get_queried_object();

            if (
                $possible_term instanceof WP_Term
            ) {
                $term =
                    $possible_term;
            }
        }


        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $url =
            get_term_link(
                $term
            );


        if (
            is_wp_error( $url )
        ) {
            return '';
        }


        /*
         * --------------------------------------------------------
         * BRONPOST / BEROEP BEPALEN
         * --------------------------------------------------------
         *
         * Op een Beroep-template is de main queried object
         * normaal de huidige Beroep-post.
         */

        $source_post_id = 0;

        $queried_object =
            get_queried_object();


        if (
            $queried_object instanceof WP_Post
        ) {

            $source_post_id =
                (int) $queried_object->ID;

        } elseif (
            is_singular()
        ) {

            $source_post_id =
                (int) get_queried_object_id();
        }


        /*
         * Geen Beroep/context gevonden:
         * normale taxonomy URL gebruiken.
         */

        if ( ! $source_post_id ) {
            return esc_url( $url );
        }


        /*
         * Functienaamrelationship ophalen.
         */

        $functie_slugs =
            tfsc_filter_context_functienaam_slugs(
                $source_post_id
            );


        if ( empty( $functie_slugs ) ) {
            return esc_url( $url );
        }


        /*
         * Meerdere functienamen ondersteunen.
         *
         * Standaard:
         *
         * ?functienaam=field-service-engineer
         *
         * Bij meerdere:
         *
         * ?functienaam=term-a,term-b
         */

        $url =
            add_query_arg(
                'functienaam',
                implode(
                    ',',
                    $functie_slugs
                ),
                $url
            );


        return esc_url( $url );
    }
);


/**
 * ============================================================
 * 4. FUNCTIENAAM PARAMETER ECHT OP DE POST QUERY TOEPASSEN
 * ============================================================
 *
 * Voorbeeld:
 *
 * /locaties/.../heerenveen/
 * ?functienaam=field-service-engineer
 *
 * wordt:
 *
 * locatie = Heerenveen
 * AND
 * functienaam = Field Service Engineer
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        /*
         * Alleen frontend main query.
         */

        if (
            is_admin() ||
            ! $query->is_main_query()
        ) {
            return;
        }


        /*
         * Alleen wanneer functienaam expliciet
         * in de URL staat.
         */

        if (
            ! isset(
                $_GET['functienaam']
            )
        ) {
            return;
        }


        $raw =
            sanitize_text_field(
                wp_unslash(
                    $_GET['functienaam']
                )
            );


        if ( '' === $raw ) {
            return;
        }


        $slugs =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'sanitize_title',
                            explode(
                                ',',
                                $raw
                            )
                        )
                    )
                )
            );


        if ( empty( $slugs ) ) {
            return;
        }


        /*
         * Alleen bestaande functienaam-terms behouden.
         */

        $valid_slugs = [];


        foreach (
            $slugs
            as $slug
        ) {

            $term =
                get_term_by(
                    'slug',
                    $slug,
                    'functienaam'
                );


            if (
                $term instanceof WP_Term
            ) {
                $valid_slugs[] =
                    $term->slug;
            }
        }


        if ( empty( $valid_slugs ) ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /*
         * Bestaande tax_query bewaren.
         */

        $tax_query =
            $query->get(
                'tax_query'
            );


        if (
            ! is_array(
                $tax_query
            )
        ) {
            $tax_query = [];
        }


        $tax_query[] = [
            'taxonomy' =>
                'functienaam',

            'field' =>
                'slug',

            'terms' =>
                $valid_slugs,

            'operator' =>
                'IN',
        ];


        $query->set(
            'tax_query',
            $tax_query
        );

    },
    20
);


/**
 * ============================================================
 * 5. FILTERWIDGET VISUEEL SYNCHRONISEREN
 * ============================================================
 *
 * Als de URL bevat:
 *
 * ?functienaam=field-service-engineer
 *
 * proberen we een bestaand functienaam checkbox/radio/select
 * met die waarde ook als actief weer te geven.
 *
 * Dit verandert NIET de query; dat gebeurt hierboven al via PHP.
 */

add_action(
    'wp_footer',
    function() {

        if (
            is_admin() ||
            empty(
                $_GET['functienaam']
            )
        ) {
            return;
        }


        $raw =
            sanitize_text_field(
                wp_unslash(
                    $_GET['functienaam']
                )
            );


        $slugs =
            array_values(
                array_filter(
                    array_map(
                        'sanitize_title',
                        explode(
                            ',',
                            $raw
                        )
                    )
                )
            );


        if ( empty( $slugs ) ) {
            return;
        }

        ?>
        <script>
        document.addEventListener('DOMContentLoaded', function () {

            const tfscFunctionSlugs =
                <?php echo wp_json_encode( $slugs ); ?>;

            if (!Array.isArray(tfscFunctionSlugs)) {
                return;
            }


            function tfscSyncFunctionFilter() {

                tfscFunctionSlugs.forEach(function (slug) {

                    /*
                     * Checkbox / radio met directe slugwaarde.
                     */
                    document.querySelectorAll(
                        'input[type="checkbox"], input[type="radio"]'
                    ).forEach(function (input) {

                        if (
                            String(input.value) === String(slug)
                        ) {
                            input.checked = true;

                            input.setAttribute(
                                'checked',
                                'checked'
                            );

                            input.dispatchEvent(
                                new Event(
                                    'change',
                                    {
                                        bubbles: true
                                    }
                                )
                            );
                        }
                    });


                    /*
                     * Select opties.
                     */
                    document.querySelectorAll(
                        'select option'
                    ).forEach(function (option) {

                        if (
                            String(option.value) === String(slug)
                        ) {
                            option.selected = true;
                        }
                    });

                });
            }


            /*
             * Meteen uitvoeren.
             */
            tfscSyncFunctionFilter();


            /*
             * Elementor/filterwidgets kunnen na pageload
             * opnieuw worden gerenderd.
             *
             * Daarom kort observeren op DOM wijzigingen.
             */
            const observer =
                new MutationObserver(function () {
                    tfscSyncFunctionFilter();
                });


            observer.observe(
                document.body,
                {
                    childList: true,
                    subtree: true
                }
            );


            setTimeout(function () {
                observer.disconnect();
            }, 5000);

        });
        </script>
        <?php

    },
    100
);

/**
 * TFSC - Beroep → Relationship Locaties → Combo Archives
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een Beroep:
 *
 *     relationship_functienaam
 *         → Field Service Engineer
 *
 *     relationship_locatie
 *         → veld bestaat
 *
 * Elementor Taxonomy Loop:
 *
 *     Source: locatie
 *     Query ID: relationship_locatie
 *
 *
 * De snippet:
 *
 * 1. controleert of relationship_locatie bestaat op de CPT;
 * 2. leest relationship_functienaam;
 * 3. zoekt OPEN vacatures met die functienaam;
 * 4. verzamelt de locaties van die vacatures;
 * 5. voegt bij hiërarchische locaties ook ancestors toe;
 * 6. geeft alleen die locaties terug aan Elementor;
 * 7. laat Elementor zelf Filter by Depth toepassen;
 * 8. verandert locatie-links op deze Beroep-pagina naar
 *    TFSC combo archive URLs.
 *
 *
 * ============================================================
 * VOORBEELD LINK
 * ============================================================
 *
 * Beroep:
 *
 *     Field Service Engineer
 *
 * Locatie:
 *
 *     Heerenveen
 *
 * Wordt bijvoorbeeld:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * locatie/nederland/friesland/heerenveen/
 *
 *
 * ============================================================
 * VACATURESTATUS
 * ============================================================
 *
 * Alleen:
 *
 *     vac_status = open
 *
 * worden gebruikt.
 *
 * Indien de constants van het bestaande combo-script bestaan,
 * worden die automatisch gebruikt:
 *
 *     TFSC_VACANCY_POST_TYPE
 *     TFSC_STATUS_TAXONOMY
 *     TFSC_OPEN_STATUS_SLUG
 *     TFSC_COMBO_BASE
 *
 *
 * ============================================================
 * CONFLICTEN
 * ============================================================
 *
 * Deze snippet gebruikt:
 *
 *     elementor/loop_taxonomy/args
 *
 * maar reageert ALLEEN op:
 *
 *     relationship_locatie
 *
 * Hij doet dus niets met:
 *
 *     relationship_posts
 *     taxonomy_level_*
 *     current_taxonomy*
 *
 * De term_link filter werkt bovendien alleen:
 *
 * - op een singuliere CPT/post;
 * - als relationship_locatie op die Pod bestaat;
 * - voor taxonomy locatie;
 * - wanneer relationship_functienaam gevuld is.
 */


/**
 * ============================================================
 * 1. CONFIG HELPERS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_vacancy_post_type' ) ) {

    function tfsc_rel_location_v2_vacancy_post_type() {

        return defined( 'TFSC_VACANCY_POST_TYPE' )
            ? TFSC_VACANCY_POST_TYPE
            : 'vacature';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v2_status_taxonomy' ) ) {

    function tfsc_rel_location_v2_status_taxonomy() {

        return defined( 'TFSC_STATUS_TAXONOMY' )
            ? TFSC_STATUS_TAXONOMY
            : 'vac_status';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v2_open_status' ) ) {

    function tfsc_rel_location_v2_open_status() {

        return defined( 'TFSC_OPEN_STATUS_SLUG' )
            ? TFSC_OPEN_STATUS_SLUG
            : 'open';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v2_combo_base' ) ) {

    function tfsc_rel_location_v2_combo_base() {

        return defined( 'TFSC_COMBO_BASE' )
            ? TFSC_COMBO_BASE
            : 'vacatures';
    }
}


/**
 * ============================================================
 * 2. HUIDIGE CPT POD OPHALEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_current_pod' ) ) {

    function tfsc_rel_location_v2_get_current_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }


        $object = get_queried_object();


        /*
         * Alleen CPT/post context.
         *
         * Taxonomy archives worden bewust niet door
         * deze snippet behandeld.
         */
        if (
            ! ( $object instanceof WP_Post ) ||
            empty( $object->ID )
        ) {
            return false;
        }


        $post_type =
            get_post_type(
                $object->ID
            );


        if ( ! $post_type ) {
            return false;
        }


        $pod =
            pods(
                $post_type,
                (int) $object->ID
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return false;
        }


        return $pod;
    }
}


/**
 * ============================================================
 * 3. RELATIONSHIP TERM IDs UITLEZEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_relationship_term_ids' ) ) {

    function tfsc_rel_location_v2_get_relationship_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $field_name ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * Eerst Pods traversal.
         */
        $traversed_ids =
            $pod->field(
                $field_name . '.term_id'
            );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /*
         * Fallback naar normale Pods relationship return.
         */
        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    $field_name
                );


            if ( empty( $relations ) ) {
                return [];
            }


            /*
             * Eén associatieve relationship normaliseren.
             */
            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {

                $relations = [
                    $relations
                ];
            }


            /*
             * Eén numeriek ID normaliseren.
             */
            if ( is_numeric( $relations ) ) {

                $relations = [
                    $relations
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        /*
         * Opschonen.
         */
        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        /*
         * Alleen terms van de juiste taxonomy.
         */
        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $valid_ids
            )
        );
    }
}


/**
 * ============================================================
 * 4. CONTROLEREN OF RELATIONSHIP_LOCATIE BESTAAT
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_has_location_field' ) ) {

    function tfsc_rel_location_v2_has_location_field(
        $pod
    ) {

        if ( ! $pod ) {
            return false;
        }


        $fields =
            $pod->fields();


        return (
            is_array( $fields )
            &&
            array_key_exists(
                'relationship_locatie',
                $fields
            )
        );
    }
}


/**
 * ============================================================
 * 5. ACTIEVE FUNCTIENAAM IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_function_ids' ) ) {

    function tfsc_rel_location_v2_get_function_ids(
        $pod
    ) {

        return
            tfsc_rel_location_v2_get_relationship_term_ids(
                $pod,
                'relationship_functienaam',
                'functienaam'
            );
    }
}


/**
 * ============================================================
 * 6. OPEN VACATURES VAN FUNCTIENAAM
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_vacancy_ids' ) ) {

    function tfsc_rel_location_v2_get_vacancy_ids(
        $function_term_ids
    ) {

        if (
            empty( $function_term_ids ) ||
            ! taxonomy_exists( 'functienaam' )
        ) {
            return [];
        }


        $vacancy_post_type =
            tfsc_rel_location_v2_vacancy_post_type();


        if (
            ! post_type_exists(
                $vacancy_post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' => 'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],
        ];


        /*
         * Alleen OPEN vacatures.
         */
        $status_taxonomy =
            tfsc_rel_location_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $vacancy_ids =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $vacancy_ids ) ) {
            return [];
        }


        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $vacancy_ids
                )
            )
        );
    }
}


/**
 * ============================================================
 * 7. LOCATIES VAN OPEN VACATURES VERZAMELEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_location_ids' ) ) {

    function tfsc_rel_location_v2_get_location_ids(
        $vacancy_ids
    ) {

        if (
            empty( $vacancy_ids ) ||
            ! taxonomy_exists( 'locatie' )
        ) {
            return [];
        }


        $location_ids = [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    'locatie',
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                /*
                 * Direct gekoppelde locatie.
                 */
                $location_ids[] =
                    $term_id;


                /*
                 * Ook ancestors toevoegen.
                 *
                 * Bijvoorbeeld:
                 *
                 * Heerenveen
                 * → Friesland
                 * → Nederland
                 *
                 * Hierdoor kan Elementor zijn eigen
                 * Filter by Depth gebruiken.
                 */
                if (
                    is_taxonomy_hierarchical(
                        'locatie'
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            'locatie',
                            'taxonomy'
                        );


                    if ( ! empty( $ancestors ) ) {

                        $location_ids =
                            array_merge(
                                $location_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $location_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Query ID:
 *
 *     relationship_locatie
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        /*
         * Query ID.
         */
        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $settings['term_taxonomy_id']
            );


        /*
         * Alleen onze specifieke query.
         */
        if (
            'relationship_locatie'
            !==
            $query_id
        ) {
            return $args;
        }


        /*
         * Alleen Source: locatie.
         */
        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        if (
            'locatie'
            !==
            $elementor_taxonomy
        ) {
            return $args;
        }


        /*
         * Huidige Beroep/CPT Pod.
         */
        $pod =
            tfsc_rel_location_v2_get_current_pod();


        if ( ! $pod ) {
            return $args;
        }


        /*
         * relationship_locatie moet bestaan.
         *
         * Het veld hoeft NIET gevuld te zijn.
         */
        if (
            ! tfsc_rel_location_v2_has_location_field(
                $pod
            )
        ) {
            return $args;
        }


        /*
         * relationship_functienaam uitlezen.
         */
        $function_term_ids =
            tfsc_rel_location_v2_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_term_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Alleen OPEN vacatures met deze functienaam.
         */
        $vacancy_ids =
            tfsc_rel_location_v2_get_vacancy_ids(
                $function_term_ids
            );


        if (
            empty(
                $vacancy_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Locaties van deze vacatures.
         */
        $location_ids =
            tfsc_rel_location_v2_get_location_ids(
                $vacancy_ids
            );


        if (
            empty(
                $location_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Elementor Query ID verwijderen.
         */
        unset(
            $args['term_taxonomy_id']
        );


        /*
         * Alleen relevante locaties.
         */
        $args['taxonomy'] =
            'locatie';


        $args['include'] =
            $location_ids;


        /*
         * Geen eigen level/depth filtering.
         *
         * Elementor blijft verantwoordelijk voor:
         *
         * Filter by Depth
         * Depth
         */
        $args['hide_empty'] =
            false;


        return $args;

    },
    30,
    3
);


/**
 * ============================================================
 * 9. VOLLEDIG TAXONOMY TERMPAD MAKEN
 * ============================================================
 *
 * Heerenveen:
 *
 * nederland/friesland/heerenveen
 */

if ( ! function_exists( 'tfsc_rel_location_v2_term_path' ) ) {

    function tfsc_rel_location_v2_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs = [];


        /*
         * Ancestors geeft:
         *
         * directe parent → root
         *
         * Voor URL willen we:
         *
         * root → parent → huidige term
         */
        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if (
                ! empty(
                    $ancestor_ids
                )
            ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor
                        instanceof WP_Term
                        &&
                        ! is_wp_error(
                            $ancestor
                        )
                        &&
                        ! empty(
                            $ancestor->slug
                        )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 10. COMBO URL VOOR LOCATIE BOUWEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_build_combo_url' ) ) {

    function tfsc_rel_location_v2_build_combo_url(
        $location_term
    ) {

        if (
            ! (
                $location_term
                instanceof WP_Term
            ) ||
            'locatie'
            !==
            $location_term->taxonomy
        ) {
            return false;
        }


        $pod =
            tfsc_rel_location_v2_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_rel_location_v2_has_location_field(
                $pod
            )
        ) {
            return false;
        }


        /*
         * Functienaam uit Beroep.
         */
        $function_ids =
            tfsc_rel_location_v2_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_ids
            )
        ) {
            return false;
        }


        /*
         * Voor deze link gebruiken we de geselecteerde
         * functienaam relationship.
         *
         * Als er meerdere functienamen geselecteerd zijn,
         * worden ze als afzonderlijke functienaam-blokken
         * aan de combo URL toegevoegd.
         */
        $function_terms = [];


        foreach (
            $function_ids
            as $function_id
        ) {

            $function_term =
                get_term(
                    $function_id,
                    'functienaam'
                );


            if (
                $function_term
                instanceof WP_Term
                &&
                ! is_wp_error(
                    $function_term
                )
            ) {

                $function_terms[] =
                    $function_term;
            }
        }


        if (
            empty(
                $function_terms
            )
        ) {
            return false;
        }


        /*
         * --------------------------------------------------------
         * EXTRA VEILIGHEID:
         *
         * Deze specifieke combinatie moet daadwerkelijk
         * minimaal één OPEN vacature opleveren.
         * --------------------------------------------------------
         */

        $vacancy_post_type =
            tfsc_rel_location_v2_vacancy_post_type();


        $status_taxonomy =
            tfsc_rel_location_v2_status_taxonomy();


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],

            [
                'taxonomy' =>
                    'locatie',

                'field' =>
                    'term_id',

                'terms' => [
                    (int)
                    $location_term->term_id,
                ],

                'operator' =>
                    'IN',

                /*
                 * Provincie/land mag onderliggende
                 * plaatsen meenemen.
                 */
                'include_children' =>
                    is_taxonomy_hierarchical(
                        'locatie'
                    ),
            ],
        ];


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        /*
         * Geen resultaat:
         * geen combo URL maken.
         */
        if (
            empty(
                $has_result
            )
        ) {
            return false;
        }


        /*
         * --------------------------------------------------------
         * URL OPBOUW
         * --------------------------------------------------------
         */

        $parts = [
            tfsc_rel_location_v2_combo_base(),
        ];


        /*
         * Functienaam-blokken.
         */
        foreach (
            $function_terms
            as $function_term
        ) {

            $function_path =
                tfsc_rel_location_v2_term_path(
                    $function_term
                );


            if (
                '' === $function_path
            ) {
                continue;
            }


            $parts[] =
                'functienaam';

            $parts[] =
                $function_path;
        }


        /*
         * Locatieblok.
         */
        $location_path =
            tfsc_rel_location_v2_term_path(
                $location_term
            );


        if (
            '' === $location_path
        ) {
            return false;
        }


        $parts[] =
            'locatie';

        $parts[] =
            $location_path;


        /*
         * Basis-URL.
         */
        $url =
            home_url(
                '/'
                .
                implode(
                    '/',
                    array_map(
                        function( $part ) {

                            return trim(
                                $part,
                                '/'
                            );
                        },
                        $parts
                    )
                )
                .
                '/'
            );


        return $url;
    }
}


/**
 * ============================================================
 * 11. LOCATIE TERM LINKS OP BEROEP → COMBO URL
 * ============================================================
 *
 * Elementor gebruikt voor taxonomy-term links uiteindelijk
 * WordPress get_term_link().
 *
 * Deze filter grijpt daarom alleen locatie-links aan wanneer:
 *
 * - we op een CPT/post zitten;
 * - die Pod relationship_locatie heeft;
 * - relationship_functienaam is ingevuld;
 * - de combinatie minimaal één open vacature heeft.
 *
 * Alle andere term-links blijven volledig ongemoeid.
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        /*
         * Alleen locatie.
         */
        if (
            'locatie'
            !==
            $taxonomy
        ) {
            return $termlink;
        }


        /*
         * Alleen frontend.
         */
        if ( is_admin() ) {
            return $termlink;
        }


        /*
         * Alleen huidige singular CPT/post.
         */
        $object =
            get_queried_object();


        if (
            ! (
                $object
                instanceof WP_Post
            )
        ) {
            return $termlink;
        }


        /*
         * Combo URL proberen.
         */
        $combo_url =
            tfsc_rel_location_v2_build_combo_url(
                $term
            );


        /*
         * Geen geldige combinatie:
         * normale taxonomy-link behouden.
         */
        if (
            ! $combo_url
        ) {
            return $termlink;
        }


        return $combo_url;

    },
    30,
    3
);

/**
 * TFSC - Beroep → Relationship Locaties → Combo Archives
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een Beroep:
 *
 *     relationship_functienaam
 *         → Field Service Engineer
 *
 *     relationship_locatie
 *         → veld bestaat
 *
 * Elementor Taxonomy Loop:
 *
 *     Source: locatie
 *     Query ID: relationship_locatie
 *
 *
 * De snippet:
 *
 * 1. controleert of relationship_locatie bestaat op de CPT;
 * 2. leest relationship_functienaam;
 * 3. zoekt OPEN vacatures met die functienaam;
 * 4. verzamelt de locaties van die vacatures;
 * 5. voegt bij hiërarchische locaties ook ancestors toe;
 * 6. sorteert locaties hiërarchisch + alfabetisch;
 * 7. geeft alleen die locaties terug aan Elementor;
 * 8. laat Elementor zelf Filter by Depth toepassen;
 * 9. verandert locatie-links naar TFSC combo archive URLs.
 */


/**
 * ============================================================
 * 1. CONFIG HELPERS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_vacancy_post_type' ) ) {

    function tfsc_rel_location_v2_vacancy_post_type() {

        return defined( 'TFSC_VACANCY_POST_TYPE' )
            ? TFSC_VACANCY_POST_TYPE
            : 'vacature';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v2_status_taxonomy' ) ) {

    function tfsc_rel_location_v2_status_taxonomy() {

        return defined( 'TFSC_STATUS_TAXONOMY' )
            ? TFSC_STATUS_TAXONOMY
            : 'vac_status';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v2_open_status' ) ) {

    function tfsc_rel_location_v2_open_status() {

        return defined( 'TFSC_OPEN_STATUS_SLUG' )
            ? TFSC_OPEN_STATUS_SLUG
            : 'open';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v2_combo_base' ) ) {

    function tfsc_rel_location_v2_combo_base() {

        return defined( 'TFSC_COMBO_BASE' )
            ? TFSC_COMBO_BASE
            : 'vacatures';
    }
}


/**
 * ============================================================
 * 2. HUIDIGE CPT POD OPHALEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_current_pod' ) ) {

    function tfsc_rel_location_v2_get_current_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }


        $object = get_queried_object();


        if (
            ! ( $object instanceof WP_Post ) ||
            empty( $object->ID )
        ) {
            return false;
        }


        $post_type =
            get_post_type(
                $object->ID
            );


        if ( ! $post_type ) {
            return false;
        }


        $pod =
            pods(
                $post_type,
                (int) $object->ID
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return false;
        }


        return $pod;
    }
}


/**
 * ============================================================
 * 3. RELATIONSHIP TERM IDs UITLEZEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_relationship_term_ids' ) ) {

    function tfsc_rel_location_v2_get_relationship_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $field_name ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        $traversed_ids =
            $pod->field(
                $field_name . '.term_id'
            );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    $field_name
                );


            if ( empty( $relations ) ) {
                return [];
            }


            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {

                $relations = [
                    $relations
                ];
            }


            if ( is_numeric( $relations ) ) {

                $relations = [
                    $relations
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $valid_ids
            )
        );
    }
}


/**
 * ============================================================
 * 4. CONTROLEREN OF RELATIONSHIP_LOCATIE BESTAAT
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_has_location_field' ) ) {

    function tfsc_rel_location_v2_has_location_field(
        $pod
    ) {

        if ( ! $pod ) {
            return false;
        }


        $fields =
            $pod->fields();


        return (
            is_array( $fields )
            &&
            array_key_exists(
                'relationship_locatie',
                $fields
            )
        );
    }
}


/**
 * ============================================================
 * 5. ACTIEVE FUNCTIENAAM IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_function_ids' ) ) {

    function tfsc_rel_location_v2_get_function_ids(
        $pod
    ) {

        return
            tfsc_rel_location_v2_get_relationship_term_ids(
                $pod,
                'relationship_functienaam',
                'functienaam'
            );
    }
}


/**
 * ============================================================
 * 6. OPEN VACATURES VAN FUNCTIENAAM
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_vacancy_ids' ) ) {

    function tfsc_rel_location_v2_get_vacancy_ids(
        $function_term_ids
    ) {

        if (
            empty( $function_term_ids ) ||
            ! taxonomy_exists( 'functienaam' )
        ) {
            return [];
        }


        $vacancy_post_type =
            tfsc_rel_location_v2_vacancy_post_type();


        if (
            ! post_type_exists(
                $vacancy_post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' => 'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],
        ];


        $status_taxonomy =
            tfsc_rel_location_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $vacancy_ids =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $vacancy_ids ) ) {
            return [];
        }


        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $vacancy_ids
                )
            )
        );
    }
}


/**
 * ============================================================
 * 7. LOCATIES VAN OPEN VACATURES VERZAMELEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_get_location_ids' ) ) {

    function tfsc_rel_location_v2_get_location_ids(
        $vacancy_ids
    ) {

        if (
            empty( $vacancy_ids ) ||
            ! taxonomy_exists( 'locatie' )
        ) {
            return [];
        }


        $location_ids = [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    'locatie',
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                $location_ids[] =
                    $term_id;


                if (
                    is_taxonomy_hierarchical(
                        'locatie'
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            'locatie',
                            'taxonomy'
                        );


                    if ( ! empty( $ancestors ) ) {

                        $location_ids =
                            array_merge(
                                $location_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $location_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. LOCATIES HIËRARCHISCH + ALFABETISCH SORTEREN
 * ============================================================
 *
 * Voorbeeld:
 *
 * Nederland
 *   Friesland
 *     Heerenveen
 *     Leeuwarden
 *   Noord-Brabant
 *     Breda
 *     Eindhoven
 *   Zuid-Holland
 *     Rotterdam
 */

if ( ! function_exists( 'tfsc_rel_location_v2_sort_location_ids' ) ) {

    function tfsc_rel_location_v2_sort_location_ids(
        $term_ids
    ) {

        if ( empty( $term_ids ) ) {
            return [];
        }


        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        $terms = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    'locatie'
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $terms[
                    $term_id
                ] = $term;
            }
        }


        if ( empty( $terms ) ) {
            return [];
        }


        $children_by_parent = [];


        foreach (
            $terms
            as $term
        ) {

            $parent_id =
                (int) $term->parent;


            if (
                ! isset(
                    $children_by_parent[
                        $parent_id
                    ]
                )
            ) {

                $children_by_parent[
                    $parent_id
                ] = [];
            }


            $children_by_parent[
                $parent_id
            ][] = $term;
        }


        /*
         * Iedere groep children alfabetisch.
         */
        foreach (
            $children_by_parent
            as &$children
        ) {

            usort(
                $children,
                function( $a, $b ) {

                    return strnatcasecmp(
                        $a->name,
                        $b->name
                    );
                }
            );
        }

        unset( $children );


        $sorted_ids = [];


        /*
         * Recursief:
         *
         * parent
         * → children alfabetisch
         * → grandchildren alfabetisch
         */
        $walk =
            function( $parent_id ) use (
                &$walk,
                &$sorted_ids,
                &$children_by_parent
            ) {

                if (
                    empty(
                        $children_by_parent[
                            $parent_id
                        ]
                    )
                ) {
                    return;
                }


                foreach (
                    $children_by_parent[
                        $parent_id
                    ]
                    as $term
                ) {

                    $sorted_ids[] =
                        (int) $term->term_id;


                    $walk(
                        (int) $term->term_id
                    );
                }
            };


        /*
         * Start bij level 0.
         */
        $walk( 0 );


        /*
         * Veiligheidsfallback voor terms waarvan
         * de parent onverwacht niet in de selectie zit.
         */
        $remaining = [];


        foreach (
            $terms
            as $term_id => $term
        ) {

            if (
                ! in_array(
                    (int) $term_id,
                    $sorted_ids,
                    true
                )
            ) {

                $remaining[] =
                    $term;
            }
        }


        /*
         * Ook fallbackterms alfabetisch sorteren.
         */
        usort(
            $remaining,
            function( $a, $b ) {

                return strnatcasecmp(
                    $a->name,
                    $b->name
                );
            }
        );


        foreach (
            $remaining
            as $term
        ) {

            $sorted_ids[] =
                (int) $term->term_id;
        }


        return array_values(
            array_unique(
                $sorted_ids
            )
        );
    }
}


/**
 * ============================================================
 * 9. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Query ID:
 *
 *     relationship_locatie
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $settings['term_taxonomy_id']
            );


        if (
            'relationship_locatie'
            !==
            $query_id
        ) {
            return $args;
        }


        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        if (
            'locatie'
            !==
            $elementor_taxonomy
        ) {
            return $args;
        }


        $pod =
            tfsc_rel_location_v2_get_current_pod();


        if ( ! $pod ) {
            return $args;
        }


        if (
            ! tfsc_rel_location_v2_has_location_field(
                $pod
            )
        ) {
            return $args;
        }


        $function_term_ids =
            tfsc_rel_location_v2_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_term_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $vacancy_ids =
            tfsc_rel_location_v2_get_vacancy_ids(
                $function_term_ids
            );


        if (
            empty(
                $vacancy_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $location_ids =
            tfsc_rel_location_v2_get_location_ids(
                $vacancy_ids
            );


        if (
            empty(
                $location_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * NIEUW:
         * HIËRARCHISCH + ALFABETISCH SORTEREN
         * ========================================================
         */

        $location_ids =
            tfsc_rel_location_v2_sort_location_ids(
                $location_ids
            );


        if (
            empty(
                $location_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            'locatie';


        $args['include'] =
            $location_ids;


        /*
         * Zeer belangrijk:
         *
         * WordPress/Elementor moet exact de volgorde
         * van onze include-array behouden.
         */
        $args['orderby'] =
            'include';


        $args['hide_empty'] =
            false;


        /*
         * Geen eigen depth filtering.
         *
         * Elementor Filter by Depth blijft leidend.
         */

        return $args;

    },
    30,
    3
);


/**
 * ============================================================
 * 10. VOLLEDIG TAXONOMY TERMPAD MAKEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_term_path' ) ) {

    function tfsc_rel_location_v2_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs = [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if (
                ! empty(
                    $ancestor_ids
                )
            ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor
                        instanceof WP_Term
                        &&
                        ! is_wp_error(
                            $ancestor
                        )
                        &&
                        ! empty(
                            $ancestor->slug
                        )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 11. COMBO URL VOOR LOCATIE BOUWEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v2_build_combo_url' ) ) {

    function tfsc_rel_location_v2_build_combo_url(
        $location_term
    ) {

        if (
            ! (
                $location_term
                instanceof WP_Term
            ) ||
            'locatie'
            !==
            $location_term->taxonomy
        ) {
            return false;
        }


        $pod =
            tfsc_rel_location_v2_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_rel_location_v2_has_location_field(
                $pod
            )
        ) {
            return false;
        }


        $function_ids =
            tfsc_rel_location_v2_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_ids
            )
        ) {
            return false;
        }


        $function_terms = [];


        foreach (
            $function_ids
            as $function_id
        ) {

            $function_term =
                get_term(
                    $function_id,
                    'functienaam'
                );


            if (
                $function_term
                instanceof WP_Term
                &&
                ! is_wp_error(
                    $function_term
                )
            ) {

                $function_terms[] =
                    $function_term;
            }
        }


        if (
            empty(
                $function_terms
            )
        ) {
            return false;
        }


        /*
         * Controleren of deze specifieke combo
         * minimaal één OPEN vacature oplevert.
         */

        $vacancy_post_type =
            tfsc_rel_location_v2_vacancy_post_type();


        $status_taxonomy =
            tfsc_rel_location_v2_status_taxonomy();


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],

            [
                'taxonomy' =>
                    'locatie',

                'field' =>
                    'term_id',

                'terms' => [
                    (int)
                    $location_term->term_id,
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    is_taxonomy_hierarchical(
                        'locatie'
                    ),
            ],
        ];


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if (
            empty(
                $has_result
            )
        ) {
            return false;
        }


        $parts = [
            tfsc_rel_location_v2_combo_base(),
        ];


        foreach (
            $function_terms
            as $function_term
        ) {

            $function_path =
                tfsc_rel_location_v2_term_path(
                    $function_term
                );


            if (
                '' === $function_path
            ) {
                continue;
            }


            $parts[] =
                'functienaam';

            $parts[] =
                $function_path;
        }


        $location_path =
            tfsc_rel_location_v2_term_path(
                $location_term
            );


        if (
            '' ===
            $location_path
        ) {
            return false;
        }


        $parts[] =
            'locatie';

        $parts[] =
            $location_path;


        return home_url(
            '/'
            .
            implode(
                '/',
                array_map(
                    function( $part ) {

                        return trim(
                            $part,
                            '/'
                        );
                    },
                    $parts
                )
            )
            .
            '/'
        );
    }
}


/**
 * ============================================================
 * 12. LOCATIE TERM LINKS OP CPT → COMBO URL
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            'locatie'
            !==
            $taxonomy
        ) {
            return $termlink;
        }


        if ( is_admin() ) {
            return $termlink;
        }


        $object =
            get_queried_object();


        if (
            ! (
                $object
                instanceof WP_Post
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_rel_location_v2_build_combo_url(
                $term
            );


        if (
            ! $combo_url
        ) {
            return $termlink;
        }


        return $combo_url;

    },
    30,
    3
);

/**
 * TFSC - Beroep → Relationship Locaties → Combo Archives
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een CPT/post:
 *
 *     relationship_functienaam
 *         → bijvoorbeeld Field Service Engineer
 *
 *     relationship_locatie
 *         → veld bestaat
 *
 * Elementor Taxonomy Loop:
 *
 *     Source: locatie
 *     Query ID: relationship_locatie
 *
 *
 * De snippet:
 *
 * 1. controleert of relationship_locatie bestaat op de CPT;
 * 2. leest relationship_functienaam;
 * 3. zoekt OPEN vacatures met die functienaam;
 * 4. verzamelt de locaties van die vacatures;
 * 5. voegt bij hiërarchische locaties ook ancestors toe;
 * 6. geeft alleen die locaties terug aan Elementor;
 * 7. laat Elementor zelf Depth én sortering bepalen;
 * 8. verandert locatie-links naar TFSC combo archive URLs.
 *
 *
 * ============================================================
 * ELEMENTOR
 * ============================================================
 *
 * Source:
 *
 *     locatie
 *
 * Query ID:
 *
 *     relationship_locatie
 *
 * Sortering stel je gewoon in de widget zelf in.
 *
 * Bijvoorbeeld:
 *
 *     Order By: Name
 *     Order: ASC
 *
 */


/**
 * ============================================================
 * 1. CONFIG HELPERS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v3_vacancy_post_type' ) ) {

    function tfsc_rel_location_v3_vacancy_post_type() {

        return defined( 'TFSC_VACANCY_POST_TYPE' )
            ? TFSC_VACANCY_POST_TYPE
            : 'vacature';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v3_status_taxonomy' ) ) {

    function tfsc_rel_location_v3_status_taxonomy() {

        return defined( 'TFSC_STATUS_TAXONOMY' )
            ? TFSC_STATUS_TAXONOMY
            : 'vac_status';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v3_open_status' ) ) {

    function tfsc_rel_location_v3_open_status() {

        return defined( 'TFSC_OPEN_STATUS_SLUG' )
            ? TFSC_OPEN_STATUS_SLUG
            : 'open';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v3_combo_base' ) ) {

    function tfsc_rel_location_v3_combo_base() {

        return defined( 'TFSC_COMBO_BASE' )
            ? TFSC_COMBO_BASE
            : 'vacatures';
    }
}


/**
 * ============================================================
 * 2. HUIDIGE CPT POD OPHALEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v3_get_current_pod' ) ) {

    function tfsc_rel_location_v3_get_current_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }


        $object = get_queried_object();


        if (
            ! ( $object instanceof WP_Post ) ||
            empty( $object->ID )
        ) {
            return false;
        }


        $post_type =
            get_post_type(
                $object->ID
            );


        if ( ! $post_type ) {
            return false;
        }


        $pod =
            pods(
                $post_type,
                (int) $object->ID
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return false;
        }


        return $pod;
    }
}


/**
 * ============================================================
 * 3. RELATIONSHIP TERM IDs UITLEZEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v3_get_relationship_term_ids' ) ) {

    function tfsc_rel_location_v3_get_relationship_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $field_name ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * Eerst Pods traversal.
         */
        $traversed_ids =
            $pod->field(
                $field_name . '.term_id'
            );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /*
         * Fallback normale Pods relationship return.
         */
        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    $field_name
                );


            if ( empty( $relations ) ) {
                return [];
            }


            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {

                $relations = [
                    $relations
                ];
            }


            if ( is_numeric( $relations ) ) {

                $relations = [
                    $relations
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        /*
         * IDs opschonen.
         */
        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        /*
         * Alleen terms accepteren van de juiste taxonomy.
         */
        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $valid_ids
            )
        );
    }
}


/**
 * ============================================================
 * 4. CONTROLEREN OF RELATIONSHIP_LOCATIE BESTAAT
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v3_has_location_field' ) ) {

    function tfsc_rel_location_v3_has_location_field(
        $pod
    ) {

        if ( ! $pod ) {
            return false;
        }


        $fields =
            $pod->fields();


        return (
            is_array( $fields )
            &&
            array_key_exists(
                'relationship_locatie',
                $fields
            )
        );
    }
}


/**
 * ============================================================
 * 5. ACTIEVE FUNCTIENAAM IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v3_get_function_ids' ) ) {

    function tfsc_rel_location_v3_get_function_ids(
        $pod
    ) {

        return
            tfsc_rel_location_v3_get_relationship_term_ids(
                $pod,
                'relationship_functienaam',
                'functienaam'
            );
    }
}


/**
 * ============================================================
 * 6. OPEN VACATURES VAN FUNCTIENAAM
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v3_get_vacancy_ids' ) ) {

    function tfsc_rel_location_v3_get_vacancy_ids(
        $function_term_ids
    ) {

        if (
            empty( $function_term_ids ) ||
            ! taxonomy_exists( 'functienaam' )
        ) {
            return [];
        }


        $vacancy_post_type =
            tfsc_rel_location_v3_vacancy_post_type();


        if (
            ! post_type_exists(
                $vacancy_post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' => 'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],
        ];


        /*
         * Alleen OPEN vacatures.
         */
        $status_taxonomy =
            tfsc_rel_location_v3_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v3_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $vacancy_ids =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $vacancy_ids ) ) {
            return [];
        }


        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $vacancy_ids
                )
            )
        );
    }
}


/**
 * ============================================================
 * 7. LOCATIES VAN OPEN VACATURES VERZAMELEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v3_get_location_ids' ) ) {

    function tfsc_rel_location_v3_get_location_ids(
        $vacancy_ids
    ) {

        if (
            empty( $vacancy_ids ) ||
            ! taxonomy_exists( 'locatie' )
        ) {
            return [];
        }


        $location_ids = [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    'locatie',
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                /*
                 * Direct gekoppelde locatie.
                 */
                $location_ids[] =
                    $term_id;


                /*
                 * Ancestors toevoegen.
                 *
                 * Hierdoor kan Elementor zelf
                 * Filter by Depth gebruiken.
                 */
                if (
                    is_taxonomy_hierarchical(
                        'locatie'
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            'locatie',
                            'taxonomy'
                        );


                    if ( ! empty( $ancestors ) ) {

                        $location_ids =
                            array_merge(
                                $location_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $location_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Query ID:
 *
 *     relationship_locatie
 *
 * BELANGRIJK:
 *
 * Deze snippet bepaalt alleen WELKE locaties worden getoond.
 *
 * Elementor bepaalt:
 *
 * - Depth
 * - Order By
 * - Order
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $settings['term_taxonomy_id']
            );


        if (
            'relationship_locatie'
            !==
            $query_id
        ) {
            return $args;
        }


        /*
         * Alleen Source: locatie.
         */
        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        if (
            'locatie'
            !==
            $elementor_taxonomy
        ) {
            return $args;
        }


        /*
         * Huidige CPT Pod.
         */
        $pod =
            tfsc_rel_location_v3_get_current_pod();


        if ( ! $pod ) {
            return $args;
        }


        /*
         * relationship_locatie moet bestaan.
         */
        if (
            ! tfsc_rel_location_v3_has_location_field(
                $pod
            )
        ) {
            return $args;
        }


        /*
         * Functienaam uitlezen.
         */
        $function_term_ids =
            tfsc_rel_location_v3_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_term_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Alleen open vacatures van deze functienaam.
         */
        $vacancy_ids =
            tfsc_rel_location_v3_get_vacancy_ids(
                $function_term_ids
            );


        if (
            empty(
                $vacancy_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Relevante locaties verzamelen.
         */
        $location_ids =
            tfsc_rel_location_v3_get_location_ids(
                $vacancy_ids
            );


        if (
            empty(
                $location_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Elementor Query ID verwijderen.
         */
        unset(
            $args['term_taxonomy_id']
        );


        /*
         * Alleen de relevante locaties toestaan.
         */
        $args['taxonomy'] =
            'locatie';


        $args['include'] =
            $location_ids;


        $args['hide_empty'] =
            false;


        /*
         * BELANGRIJK:
         *
         * We zetten hier bewust GEEN:
         *
         * $args['orderby']
         * $args['order']
         *
         * Daardoor blijven de instellingen van de
         * Elementor Taxonomy widget zelf leidend.
         */


        return $args;

    },
    30,
    3
);


/**
 * ============================================================
 * 9. VOLLEDIG TAXONOMY TERMPAD MAKEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v3_term_path' ) ) {

    function tfsc_rel_location_v3_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs = [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if (
                ! empty(
                    $ancestor_ids
                )
            ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor
                        instanceof WP_Term
                        &&
                        ! is_wp_error(
                            $ancestor
                        )
                        &&
                        ! empty(
                            $ancestor->slug
                        )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 10. COMBO URL VOOR LOCATIE BOUWEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v3_build_combo_url' ) ) {

    function tfsc_rel_location_v3_build_combo_url(
        $location_term
    ) {

        if (
            ! (
                $location_term
                instanceof WP_Term
            ) ||
            'locatie'
            !==
            $location_term->taxonomy
        ) {
            return false;
        }


        $pod =
            tfsc_rel_location_v3_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_rel_location_v3_has_location_field(
                $pod
            )
        ) {
            return false;
        }


        $function_ids =
            tfsc_rel_location_v3_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_ids
            )
        ) {
            return false;
        }


        $function_terms = [];


        foreach (
            $function_ids
            as $function_id
        ) {

            $function_term =
                get_term(
                    $function_id,
                    'functienaam'
                );


            if (
                $function_term
                instanceof WP_Term
                &&
                ! is_wp_error(
                    $function_term
                )
            ) {

                $function_terms[] =
                    $function_term;
            }
        }


        if (
            empty(
                $function_terms
            )
        ) {
            return false;
        }


        /*
         * Controleren of deze combinatie
         * minimaal één open vacature oplevert.
         */

        $vacancy_post_type =
            tfsc_rel_location_v3_vacancy_post_type();


        $status_taxonomy =
            tfsc_rel_location_v3_status_taxonomy();


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],

            [
                'taxonomy' =>
                    'locatie',

                'field' =>
                    'term_id',

                'terms' => [
                    (int)
                    $location_term->term_id,
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    is_taxonomy_hierarchical(
                        'locatie'
                    ),
            ],
        ];


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v3_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if (
            empty(
                $has_result
            )
        ) {
            return false;
        }


        /*
         * Combo URL bouwen.
         */

        $parts = [
            tfsc_rel_location_v3_combo_base(),
        ];


        foreach (
            $function_terms
            as $function_term
        ) {

            $function_path =
                tfsc_rel_location_v3_term_path(
                    $function_term
                );


            if (
                '' === $function_path
            ) {
                continue;
            }


            $parts[] =
                'functienaam';

            $parts[] =
                $function_path;
        }


        $location_path =
            tfsc_rel_location_v3_term_path(
                $location_term
            );


        if (
            '' ===
            $location_path
        ) {
            return false;
        }


        $parts[] =
            'locatie';

        $parts[] =
            $location_path;


        return home_url(
            '/'
            .
            implode(
                '/',
                array_map(
                    function( $part ) {

                        return trim(
                            $part,
                            '/'
                        );
                    },
                    $parts
                )
            )
            .
            '/'
        );
    }
}


/**
 * ============================================================
 * 11. LOCATIE TERM LINKS OP CPT → COMBO URL
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            'locatie'
            !==
            $taxonomy
        ) {
            return $termlink;
        }


        if ( is_admin() ) {
            return $termlink;
        }


        $object =
            get_queried_object();


        if (
            ! (
                $object
                instanceof WP_Post
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_rel_location_v3_build_combo_url(
                $term
            );


        if (
            ! $combo_url
        ) {
            return $termlink;
        }


        return $combo_url;

    },
    30,
    3
);

/**
 * TFSC - Relationship Locaties per Exact Level → Combo Archives
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een CPT/post:
 *
 *     relationship_functienaam
 *         → bijvoorbeeld Field Service Engineer
 *
 *     relationship_locatie
 *         → veld bestaat
 *
 * Elementor Taxonomy Loop:
 *
 *     Source: locatie
 *
 *     Query ID:
 *
 *         relationship_locatie_level_0
 *         relationship_locatie_level_1
 *         relationship_locatie_level_2
 *
 *
 * ============================================================
 * LEVELS
 * ============================================================
 *
 * level_0
 *     alleen top-level terms
 *
 * level_1
 *     alleen children van level 0
 *
 * level_2
 *     alleen children van level 1
 *
 * enz.
 *
 * Het level wordt exact afgedwongen.
 *
 * Elementor Filter by Depth moet daarom UIT staan.
 *
 *
 * ============================================================
 * SORTERING
 * ============================================================
 *
 * Binnen het gekozen level worden de terms alfabetisch
 * op naam gesorteerd.
 *
 *
 * ============================================================
 * RESULTATEN
 * ============================================================
 *
 * Alleen locaties die voorkomen bij:
 *
 *     gepubliceerde vacatures
 *     AND
 *     relationship_functienaam
 *     AND
 *     vac_status = open
 *
 * worden getoond.
 *
 *
 * ============================================================
 * COMBO LINKS
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * locatie/noord-brabant/
 *
 * De link wordt alleen gemaakt wanneer die combinatie
 * minimaal één open vacature oplevert.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

