/**
 * ============================================================
 * 6. OPEN VACATURE IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v4_get_vacancy_ids' ) ) {

    function tfsc_rel_location_v4_get_vacancy_ids(
        $function_term_ids
    ) {

        if (
            empty( $function_term_ids ) ||
            ! taxonomy_exists( 'functienaam' )
        ) {
            return [];
        }


        $vacancy_post_type =
            tfsc_rel_location_v4_vacancy_post_type();


        if (
            ! post_type_exists(
                $vacancy_post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],
        ];


        $status_taxonomy =
            tfsc_rel_location_v4_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v4_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $vacancy_ids =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $vacancy_ids ) ) {
            return [];
        }


        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $vacancy_ids
                )
            )
        );
    }
}


/**
 * ============================================================
 * 7. LOCATIES VAN VACATURES + ANCESTORS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v4_get_location_ids' ) ) {

    function tfsc_rel_location_v4_get_location_ids(
        $vacancy_ids
    ) {

        if (
            empty( $vacancy_ids ) ||
            ! taxonomy_exists( 'locatie' )
        ) {
            return [];
        }


        $location_ids = [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    'locatie',
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                /*
                 * Direct gekoppelde locatie.
                 */
                $location_ids[] =
                    $term_id;


                /*
                 * Ancestors toevoegen zodat ook provincies,
                 * landen enz. beschikbaar zijn.
                 */
                if (
                    is_taxonomy_hierarchical(
                        'locatie'
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            'locatie',
                            'taxonomy'
                        );


                    if ( ! empty( $ancestors ) ) {

                        $location_ids =
                            array_merge(
                                $location_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $location_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. ALLEEN EXACT GEWENST LEVEL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v4_filter_level' ) ) {

    function tfsc_rel_location_v4_filter_level(
        $term_ids,
        $wanted_level
    ) {

        if ( empty( $term_ids ) ) {
            return [];
        }


        $filtered = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $level =
                count(
                    get_ancestors(
                        $term_id,
                        'locatie',
                        'taxonomy'
                    )
                );


            if (
                $level ===
                (int) $wanted_level
            ) {

                $filtered[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $filtered
            )
        );
    }
}


/**
 * ============================================================
 * 9. ALFABETISCH SORTEREN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v4_sort_alphabetically' ) ) {

    function tfsc_rel_location_v4_sort_alphabetically(
        $term_ids
    ) {

        if ( empty( $term_ids ) ) {
            return [];
        }


        $terms = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    (int) $term_id,
                    'locatie'
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $terms[] =
                    $term;
            }
        }


        if ( empty( $terms ) ) {
            return [];
        }


        /*
         * Alfabetisch op zichtbare naam.
         */
        usort(
            $terms,
            function( $a, $b ) {

                return strnatcasecmp(
                    remove_accents(
                        $a->name
                    ),
                    remove_accents(
                        $b->name
                    )
                );
            }
        );


        return array_values(
            array_map(
                function( $term ) {

                    return
                        (int) $term->term_id;
                },
                $terms
            )
        );
    }
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Query IDs:
 *
 * relationship_locatie_level_0
 * relationship_locatie_level_1
 * relationship_locatie_level_2
 * enz.
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $settings['term_taxonomy_id']
            );


        /*
         * Exact Query ID patroon.
         */
        if (
            ! preg_match(
                '/^relationship_locatie_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {
            return $args;
        }


        $wanted_level =
            (int) $matches[1];


        /*
         * Alleen Source: locatie.
         */
        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        if (
            'locatie'
            !==
            $elementor_taxonomy
        ) {
            return $args;
        }


        /*
         * Huidige Pod.
         */
        $pod =
            tfsc_rel_location_v4_get_current_pod();


        if ( ! $pod ) {
            return $args;
        }


        /*
         * relationship_locatie moet bestaan.
         */
        if (
            ! tfsc_rel_location_v4_has_location_field(
                $pod
            )
        ) {
            return $args;
        }


        /*
         * Functienaam.
         */
        $function_term_ids =
            tfsc_rel_location_v4_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_term_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Open vacatures.
         */
        $vacancy_ids =
            tfsc_rel_location_v4_get_vacancy_ids(
                $function_term_ids
            );


        if (
            empty(
                $vacancy_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Alle relevante locaties.
         */
        $location_ids =
            tfsc_rel_location_v4_get_location_ids(
                $vacancy_ids
            );


        if (
            empty(
                $location_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * EXACT LEVEL
         * ========================================================
         */

        $location_ids =
            tfsc_rel_location_v4_filter_level(
                $location_ids,
                $wanted_level
            );


        if (
            empty(
                $location_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * ========================================================
         * ALFABETISCH
         * ========================================================
         */

        $location_ids =
            tfsc_rel_location_v4_sort_alphabetically(
                $location_ids
            );


        if (
            empty(
                $location_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Elementor Query ID uit WP term query halen.
         */
        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            'locatie';


        $args['include'] =
            $location_ids;


        /*
         * Exact onze alfabetische include-volgorde gebruiken.
         */
        $args['orderby'] =
            'include';


        $args['order'] =
            'ASC';


        $args['hide_empty'] =
            false;


        /*
         * Geen Elementor Depth nodig.
         * Het exacte level is hierboven al bepaald.
         */


        return $args;

    },
    30,
    3
);


/**
 * ============================================================
 * 11. VOLLEDIG TERMPAD
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v4_term_path' ) ) {

    function tfsc_rel_location_v4_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs = [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if (
                ! empty(
                    $ancestor_ids
                )
            ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor
                        instanceof WP_Term
                        &&
                        ! is_wp_error(
                            $ancestor
                        )
                        &&
                        ! empty(
                            $ancestor->slug
                        )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 12. COMBO URL BOUWEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v4_build_combo_url' ) ) {

    function tfsc_rel_location_v4_build_combo_url(
        $location_term
    ) {

        if (
            ! (
                $location_term
                instanceof WP_Term
            ) ||
            'locatie'
            !==
            $location_term->taxonomy
        ) {
            return false;
        }


        $pod =
            tfsc_rel_location_v4_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_rel_location_v4_has_location_field(
                $pod
            )
        ) {
            return false;
        }


        $function_ids =
            tfsc_rel_location_v4_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_ids
            )
        ) {
            return false;
        }


        $function_terms = [];


        foreach (
            $function_ids
            as $function_id
        ) {

            $function_term =
                get_term(
                    $function_id,
                    'functienaam'
                );


            if (
                $function_term instanceof WP_Term &&
                ! is_wp_error( $function_term )
            ) {

                $function_terms[] =
                    $function_term;
            }
        }


        if (
            empty(
                $function_terms
            )
        ) {
            return false;
        }


        /*
         * Controleren of exacte combo minimaal
         * één OPEN vacature oplevert.
         */

        $vacancy_post_type =
            tfsc_rel_location_v4_vacancy_post_type();


        $status_taxonomy =
            tfsc_rel_location_v4_status_taxonomy();


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],

            [
                'taxonomy' =>
                    'locatie',

                'field' =>
                    'term_id',

                'terms' => [
                    (int)
                    $location_term->term_id,
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    is_taxonomy_hierarchical(
                        'locatie'
                    ),
            ],
        ];


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v4_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        /*
         * Geen open vacatures = geen combo-link.
         */
        if (
            empty(
                $has_result
            )
        ) {
            return false;
        }


        $parts = [
            tfsc_rel_location_v4_combo_base(),
        ];


        /*
         * Functienaam.
         */
        foreach (
            $function_terms
            as $function_term
        ) {

            $function_path =
                tfsc_rel_location_v4_term_path(
                    $function_term
                );


            if (
                '' ===
                $function_path
            ) {
                continue;
            }


            $parts[] =
                'functienaam';

            $parts[] =
                $function_path;
        }


        /*
         * Locatie.
         */
        $location_path =
            tfsc_rel_location_v4_term_path(
                $location_term
            );


        if (
            '' ===
            $location_path
        ) {
            return false;
        }


        $parts[] =
            'locatie';

        $parts[] =
            $location_path;


        return home_url(
            '/'
            .
            implode(
                '/',
                array_map(
                    function( $part ) {

                        return trim(
                            $part,
                            '/'
                        );
                    },
                    $parts
                )
            )
            .
            '/'
        );
    }
}


/**
 * ============================================================
 * 13. LOCATIE LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            'locatie'
            !==
            $taxonomy
        ) {
            return $termlink;
        }


        if ( is_admin() ) {
            return $termlink;
        }


        $object =
            get_queried_object();


        if (
            ! (
                $object
                instanceof WP_Post
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_rel_location_v4_build_combo_url(
                $term
            );


        if (
            ! $combo_url
        ) {
            return $termlink;
        }


        return $combo_url;

    },
    30,
    3
);

/**
 * TFSC - Relationship Locaties per Exact Level → Combo Archives
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een CPT/post:
 *
 *     relationship_functienaam
 *         → bijvoorbeeld Field Service Engineer
 *
 *     relationship_locatie
 *         → veld bestaat
 *
 * Elementor Taxonomy Loop:
 *
 *     Source: locatie
 *
 *     Query ID:
 *
 *         relationship_locatie_level_0
 *         relationship_locatie_level_1
 *         relationship_locatie_level_2
 *
 *
 * ============================================================
 * LEVELS
 * ============================================================
 *
 * level_0
 *     alleen top-level terms
 *
 * level_1
 *     alleen children van level 0
 *
 * level_2
 *     alleen children van level 1
 *
 * enz.
 *
 * Het level wordt exact afgedwongen.
 *
 * Elementor Filter by Depth moet daarom UIT staan.
 *
 *
 * ============================================================
 * SORTERING
 * ============================================================
 *
 * De uiteindelijke taxonomy-query wordt door WordPress zelf
 * alfabetisch op termnaam gesorteerd:
 *
 *     orderby = name
 *     order   = ASC
 *
 *
 * ============================================================
 * RESULTATEN
 * ============================================================
 *
 * Alleen locaties die voorkomen bij:
 *
 *     gepubliceerde vacatures
 *     AND
 *     relationship_functienaam
 *     AND
 *     vac_status = open
 *
 * worden getoond.
 *
 *
 * ============================================================
 * COMBO LINKS
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * locatie/noord-brabant/
 *
 * De link wordt alleen gemaakt wanneer die combinatie
 * minimaal één open vacature oplevert.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_vacancy_post_type' ) ) {

    function tfsc_rel_location_v5_vacancy_post_type() {

        return defined( 'TFSC_VACANCY_POST_TYPE' )
            ? TFSC_VACANCY_POST_TYPE
            : 'vacature';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v5_status_taxonomy' ) ) {

    function tfsc_rel_location_v5_status_taxonomy() {

        return defined( 'TFSC_STATUS_TAXONOMY' )
            ? TFSC_STATUS_TAXONOMY
            : 'vac_status';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v5_open_status' ) ) {

    function tfsc_rel_location_v5_open_status() {

        return defined( 'TFSC_OPEN_STATUS_SLUG' )
            ? TFSC_OPEN_STATUS_SLUG
            : 'open';
    }
}


if ( ! function_exists( 'tfsc_rel_location_v5_combo_base' ) ) {

    function tfsc_rel_location_v5_combo_base() {

        return defined( 'TFSC_COMBO_BASE' )
            ? TFSC_COMBO_BASE
            : 'vacatures';
    }
}


/**
 * ============================================================
 * 2. HUIDIGE CPT POD
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_get_current_pod' ) ) {

    function tfsc_rel_location_v5_get_current_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }


        $object =
            get_queried_object();


        if (
            ! ( $object instanceof WP_Post ) ||
            empty( $object->ID )
        ) {
            return false;
        }


        $post_type =
            get_post_type(
                $object->ID
            );


        if ( ! $post_type ) {
            return false;
        }


        $pod =
            pods(
                $post_type,
                (int) $object->ID
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return false;
        }


        return $pod;
    }
}


/**
 * ============================================================
 * 3. PODS RELATIONSHIP → TERM IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_get_relationship_term_ids' ) ) {

    function tfsc_rel_location_v5_get_relationship_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $field_name ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * Eerst Pods traversal.
         */
        $traversed_ids =
            $pod->field(
                $field_name . '.term_id'
            );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /*
         * Fallback normale relationship return.
         */
        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    $field_name
                );


            if ( empty( $relations ) ) {
                return [];
            }


            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {

                $relations = [
                    $relations
                ];
            }


            if ( is_numeric( $relations ) ) {

                $relations = [
                    $relations
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $valid_ids
            )
        );
    }
}


/**
 * ============================================================
 * 4. RELATIONSHIP_LOCATIE FIELD BESTAAT?
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_has_location_field' ) ) {

    function tfsc_rel_location_v5_has_location_field(
        $pod
    ) {

        if ( ! $pod ) {
            return false;
        }


        $fields =
            $pod->fields();


        return (
            is_array( $fields )
            &&
            array_key_exists(
                'relationship_locatie',
                $fields
            )
        );
    }
}


/**
 * ============================================================
 * 5. FUNCTIENAAM IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_get_function_ids' ) ) {

    function tfsc_rel_location_v5_get_function_ids(
        $pod
    ) {

        return
            tfsc_rel_location_v5_get_relationship_term_ids(
                $pod,
                'relationship_functienaam',
                'functienaam'
            );
    }
}


/**
 * ============================================================
 * 6. OPEN VACATURE IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_get_vacancy_ids' ) ) {

    function tfsc_rel_location_v5_get_vacancy_ids(
        $function_term_ids
    ) {

        if (
            empty( $function_term_ids ) ||
            ! taxonomy_exists( 'functienaam' )
        ) {
            return [];
        }


        $vacancy_post_type =
            tfsc_rel_location_v5_vacancy_post_type();


        if (
            ! post_type_exists(
                $vacancy_post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],
        ];


        $status_taxonomy =
            tfsc_rel_location_v5_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v5_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $vacancy_ids =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $vacancy_ids ) ) {
            return [];
        }


        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $vacancy_ids
                )
            )
        );
    }
}


/**
 * ============================================================
 * 7. LOCATIES VAN VACATURES + ANCESTORS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_get_location_ids' ) ) {

    function tfsc_rel_location_v5_get_location_ids(
        $vacancy_ids
    ) {

        if (
            empty( $vacancy_ids ) ||
            ! taxonomy_exists( 'locatie' )
        ) {
            return [];
        }


        $location_ids = [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    'locatie',
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                /*
                 * Direct gekoppelde locatie.
                 */
                $location_ids[] =
                    $term_id;


                /*
                 * Ancestors toevoegen zodat hogere levels
                 * ook beschikbaar zijn.
                 */
                if (
                    is_taxonomy_hierarchical(
                        'locatie'
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            'locatie',
                            'taxonomy'
                        );


                    if ( ! empty( $ancestors ) ) {

                        $location_ids =
                            array_merge(
                                $location_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $location_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. EXACT LEVEL FILTER
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_filter_level' ) ) {

    function tfsc_rel_location_v5_filter_level(
        $term_ids,
        $wanted_level
    ) {

        if ( empty( $term_ids ) ) {
            return [];
        }


        $filtered = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $level =
                count(
                    get_ancestors(
                        $term_id,
                        'locatie',
                        'taxonomy'
                    )
                );


            if (
                $level ===
                (int) $wanted_level
            ) {

                $filtered[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $filtered
            )
        );
    }
}


/**
 * ============================================================
 * 9. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Query IDs:
 *
 * relationship_locatie_level_0
 * relationship_locatie_level_1
 * relationship_locatie_level_2
 * enz.
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            sanitize_key(
                $settings['term_taxonomy_id']
            );


        if (
            ! preg_match(
                '/^relationship_locatie_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {
            return $args;
        }


        $wanted_level =
            (int) $matches[1];


        /*
         * Alleen Source: locatie.
         */
        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        if (
            'locatie'
            !==
            $elementor_taxonomy
        ) {
            return $args;
        }


        /*
         * Huidige Pod.
         */
        $pod =
            tfsc_rel_location_v5_get_current_pod();


        if ( ! $pod ) {
            return $args;
        }


        /*
         * relationship_locatie moet bestaan.
         */
        if (
            ! tfsc_rel_location_v5_has_location_field(
                $pod
            )
        ) {
            return $args;
        }


        /*
         * Functienaam.
         */
        $function_term_ids =
            tfsc_rel_location_v5_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_term_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Alleen open vacatures.
         */
        $vacancy_ids =
            tfsc_rel_location_v5_get_vacancy_ids(
                $function_term_ids
            );


        if (
            empty(
                $vacancy_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Relevante locaties.
         */
        $location_ids =
            tfsc_rel_location_v5_get_location_ids(
                $vacancy_ids
            );


        if (
            empty(
                $location_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Exact gewenste level.
         */
        $location_ids =
            tfsc_rel_location_v5_filter_level(
                $location_ids,
                $wanted_level
            );


        if (
            empty(
                $location_ids
            )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Elementor Query ID uit WP term query halen.
         */
        unset(
            $args['term_taxonomy_id']
        );


        /*
         * Alleen geselecteerde locaties.
         */
        $args['taxonomy'] =
            'locatie';


        $args['include'] =
            $location_ids;


        /*
         * ========================================================
         * ALFABETISCHE SORTERING
         * ========================================================
         *
         * WordPress zelf sorteert de uiteindelijke termselectie
         * alfabetisch op naam.
         */

        $args['orderby'] =
            'name';


        $args['order'] =
            'ASC';


        $args['hide_empty'] =
            false;


        return $args;

    },
    30,
    3
);


/**
 * ============================================================
 * 10. VOLLEDIG TERMPAD
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_term_path' ) ) {

    function tfsc_rel_location_v5_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs = [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if (
                ! empty(
                    $ancestor_ids
                )
            ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor
                        instanceof WP_Term
                        &&
                        ! is_wp_error(
                            $ancestor
                        )
                        &&
                        ! empty(
                            $ancestor->slug
                        )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 11. COMBO URL BOUWEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_rel_location_v5_build_combo_url' ) ) {

    function tfsc_rel_location_v5_build_combo_url(
        $location_term
    ) {

        if (
            ! (
                $location_term
                instanceof WP_Term
            ) ||
            'locatie'
            !==
            $location_term->taxonomy
        ) {
            return false;
        }


        $pod =
            tfsc_rel_location_v5_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_rel_location_v5_has_location_field(
                $pod
            )
        ) {
            return false;
        }


        $function_ids =
            tfsc_rel_location_v5_get_function_ids(
                $pod
            );


        if (
            empty(
                $function_ids
            )
        ) {
            return false;
        }


        $function_terms = [];


        foreach (
            $function_ids
            as $function_id
        ) {

            $function_term =
                get_term(
                    $function_id,
                    'functienaam'
                );


            if (
                $function_term instanceof WP_Term &&
                ! is_wp_error( $function_term )
            ) {

                $function_terms[] =
                    $function_term;
            }
        }


        if (
            empty(
                $function_terms
            )
        ) {
            return false;
        }


        /*
         * Exacte combo moet minimaal één OPEN vacature hebben.
         */

        $vacancy_post_type =
            tfsc_rel_location_v5_vacancy_post_type();


        $status_taxonomy =
            tfsc_rel_location_v5_status_taxonomy();


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],

            [
                'taxonomy' =>
                    'locatie',

                'field' =>
                    'term_id',

                'terms' => [
                    (int)
                    $location_term->term_id,
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    is_taxonomy_hierarchical(
                        'locatie'
                    ),
            ],
        ];


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_rel_location_v5_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if (
            empty(
                $has_result
            )
        ) {
            return false;
        }


        /*
         * Combo URL bouwen.
         */

        $parts = [
            tfsc_rel_location_v5_combo_base(),
        ];


        foreach (
            $function_terms
            as $function_term
        ) {

            $function_path =
                tfsc_rel_location_v5_term_path(
                    $function_term
                );


            if (
                '' ===
                $function_path
            ) {
                continue;
            }


            $parts[] =
                'functienaam';

            $parts[] =
                $function_path;
        }


        $location_path =
            tfsc_rel_location_v5_term_path(
                $location_term
            );


        if (
            '' ===
            $location_path
        ) {
            return false;
        }


        $parts[] =
            'locatie';

        $parts[] =
            $location_path;


        return home_url(
            '/'
            .
            implode(
                '/',
                array_map(
                    function( $part ) {

                        return trim(
                            $part,
                            '/'
                        );
                    },
                    $parts
                )
            )
            .
            '/'
        );
    }
}


/**
