 * 12. LOCATIE LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            'locatie'
            !==
            $taxonomy
        ) {
            return $termlink;
        }


        if ( is_admin() ) {
            return $termlink;
        }


        $object =
            get_queried_object();


        if (
            ! (
                $object
                instanceof WP_Post
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_rel_location_v5_build_combo_url(
                $term
            );


        if (
            ! $combo_url
        ) {
            return $termlink;
        }


        return $combo_url;

    },
    30,
    3
);

/**
 * TFSC - DEBUG Relationship Locatie Selectie
 *
 * Toont onderaan de frontendpagina hoe de selectie voor
 * relationship_locatie_level_X wordt opgebouwd.
 *
 * Deze snippet wijzigt GEEN queries.
 */

add_action(
    'wp_footer',
    function() {

        if ( is_admin() ) {
            return;
        }

        if (
            ! function_exists( 'pods' ) ||
            ! function_exists( 'tfsc_rel_location_v5_get_current_pod' ) ||
            ! function_exists( 'tfsc_rel_location_v5_get_function_ids' ) ||
            ! function_exists( 'tfsc_rel_location_v5_get_vacancy_ids' ) ||
            ! function_exists( 'tfsc_rel_location_v5_get_location_ids' ) ||
            ! function_exists( 'tfsc_rel_location_v5_filter_level' )
        ) {
            return;
        }


        $object = get_queried_object();

        if (
            ! ( $object instanceof WP_Post ) ||
            empty( $object->ID )
        ) {
            return;
        }


        $pod =
            tfsc_rel_location_v5_get_current_pod();


        if ( ! $pod ) {
            return;
        }


        $fields =
            $pod->fields();


        $has_relationship_locatie =
            (
                is_array( $fields )
                &&
                array_key_exists(
                    'relationship_locatie',
                    $fields
                )
            );


        $function_ids =
            tfsc_rel_location_v5_get_function_ids(
                $pod
            );


        $function_terms = [];


        foreach (
            $function_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    'functienaam'
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $function_terms[] = [
                    'id'   => $term->term_id,
                    'name' => $term->name,
                    'slug' => $term->slug,
                ];
            }
        }


        $vacancy_ids =
            tfsc_rel_location_v5_get_vacancy_ids(
                $function_ids
            );


        $all_location_ids =
            tfsc_rel_location_v5_get_location_ids(
                $vacancy_ids
            );


        /*
         * Alle locaties uitschrijven met naam + level.
         */

        $all_locations = [];


        foreach (
            $all_location_ids
            as $location_id
        ) {

            $term =
                get_term(
                    $location_id,
                    'locatie'
                );


            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                is_wp_error( $term )
            ) {
                continue;
            }


            $level =
                count(
                    get_ancestors(
                        $term->term_id,
                        'locatie',
                        'taxonomy'
                    )
                );


            $all_locations[] = [
                'id'     => $term->term_id,
                'name'   => $term->name,
                'slug'   => $term->slug,
                'level'  => $level,
                'parent' => (int) $term->parent,
            ];
        }


        /*
         * Debug van de relevante levels 0 t/m 4.
         */

        $levels = [];


        for ( $level = 0; $level <= 4; $level++ ) {

            $ids =
                tfsc_rel_location_v5_filter_level(
                    $all_location_ids,
                    $level
                );


            $terms = [];


            foreach (
                $ids
                as $term_id
            ) {

                $term =
                    get_term(
                        $term_id,
                        'locatie'
                    );


                if (
                    $term instanceof WP_Term &&
                    ! is_wp_error( $term )
                ) {

                    $terms[] = [
                        'id'   => $term->term_id,
                        'name' => $term->name,
                        'slug' => $term->slug,
                    ];
                }
            }


            /*
             * Exact zoals name ASC zou sorteren.
             */

            usort(
                $terms,
                function( $a, $b ) {

                    return strnatcasecmp(
                        remove_accents(
                            $a['name']
                        ),
                        remove_accents(
                            $b['name']
                        )
                    );
                }
            );


            $levels[
                'level_' . $level
            ] = $terms;
        }


        ?>
        <div
            style="
                margin:40px 20px;
                padding:20px;
                border:2px solid #000;
                background:#fff;
                color:#000;
                font-family:monospace;
                font-size:13px;
                line-height:1.5;
                overflow:auto;
                position:relative;
                z-index:999999;
            "
        >

            <h3>
                TFSC DEBUG — relationship_locatie
            </h3>

            <p>
                <strong>Huidige post ID:</strong>
                <?php echo esc_html( $object->ID ); ?>
            </p>

            <p>
                <strong>Post type:</strong>
                <?php echo esc_html(
                    get_post_type(
                        $object->ID
                    )
                ); ?>
            </p>

            <p>
                <strong>relationship_locatie field bestaat:</strong>
                <?php echo $has_relationship_locatie
                    ? 'JA'
                    : 'NEE'; ?>
            </p>


            <h4>
                relationship_functienaam
            </h4>

            <pre><?php
            echo esc_html(
                print_r(
                    $function_terms,
                    true
                )
            );
            ?></pre>


            <h4>
                Gevonden OPEN vacature IDs
            </h4>

            <pre><?php
            echo esc_html(
                print_r(
                    $vacancy_ids,
                    true
                )
            );
            ?></pre>


            <h4>
                Alle gevonden locaties + level
            </h4>

            <pre><?php
            echo esc_html(
                print_r(
                    $all_locations,
                    true
                )
            );
            ?></pre>


            <h4>
                Selectie per exact level, alfabetisch
            </h4>

            <pre><?php
            echo esc_html(
                print_r(
                    $levels,
                    true
                )
            );
            ?></pre>

        </div>
        <?php

    },
    9999
);

