/**
 * TFSC - DEBUG uiteindelijke locatie term resultaten
 *
 * Toont onderaan de pagina de daadwerkelijke volgorde
 * waarin WordPress de locatie-terms uit get_terms() teruggeeft.
 *
 * Wijzigt niets.
 */

if ( ! function_exists( 'tfsc_debug_final_location_terms_store' ) ) {

    function tfsc_debug_final_location_terms_store(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if ( is_admin() ) {
            return $terms;
        }


        /*
         * Alleen taxonomy locatie.
         */
        $taxonomies =
            (array) $taxonomies;


        if (
            ! in_array(
                'locatie',
                $taxonomies,
                true
            )
        ) {
            return $terms;
        }


        /*
         * Alleen onze gefilterde query.
         *
         * De relationship-query bevat een include-array.
         */
        if (
            empty( $args['include'] ) ||
            ! is_array( $args['include'] )
        ) {
            return $terms;
        }


        /*
         * Alleen interessant als de query op naam sorteert.
         */
        if (
            empty( $args['orderby'] ) ||
            'name' !== $args['orderby']
        ) {
            return $terms;
        }


        if (
            ! isset(
                $GLOBALS['tfsc_debug_final_location_terms']
            )
        ) {

            $GLOBALS['tfsc_debug_final_location_terms'] =
                [];
        }


        $result = [];


        foreach (
            (array) $terms
            as $index => $term
        ) {

            if (
                ! (
                    $term instanceof WP_Term
                )
            ) {
                continue;
            }


            $result[] = [

                'positie' =>
                    $index + 1,

                'id' =>
                    (int) $term->term_id,

                'naam' =>
                    $term->name,

                'parent' =>
                    (int) $term->parent,
            ];
        }


        $GLOBALS[
            'tfsc_debug_final_location_terms'
        ][] = [

            'orderby' =>
                $args['orderby'] ?? null,

            'order' =>
                $args['order'] ?? null,

            'include' =>
                $args['include'] ?? [],

            'resultaat' =>
                $result,
        ];


        return $terms;

    }
}


add_filter(
    'get_terms',
    'tfsc_debug_final_location_terms_store',
    999,
    4
);


