            ? TFSC_COMBO_BASE
            : 'vacatures';
    }
}


/**
 * ============================================================
 * 2. HUIDIGE POD
 * ============================================================
 *
 * Werkt op normale frontend en probeert ook Elementor
 * preview/editor context te herkennen.
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_current_pod' ) ) {

    function tfsc_derived_rel_v2_get_current_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }


        $post_id = 0;


        /*
         * 1. Normale queried object.
         */
        $object =
            get_queried_object();


        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID )
        ) {

            /*
             * Een Elementor template zelf willen we niet
             * als contentbron gebruiken.
             */
            if (
                'elementor_library'
                !==
                get_post_type( $object->ID )
            ) {

                $post_id =
                    (int) $object->ID;
            }
        }


        /*
         * 2. WordPress preview_id.
         */
        if (
            ! $post_id &&
            isset( $_GET['preview_id'] )
        ) {

            $preview_id =
                absint(
                    wp_unslash(
                        $_GET['preview_id']
                    )
                );


            if (
                $preview_id &&
                'elementor_library'
                !==
                get_post_type( $preview_id )
            ) {

                $post_id =
                    $preview_id;
            }
        }


        /*
         * 3. Elementor preview parameter.
         *
         * Alleen gebruiken wanneer dit geen Elementor template is.
         */
        if (
            ! $post_id &&
            isset( $_GET['elementor-preview'] )
        ) {

            $preview_id =
                absint(
                    wp_unslash(
                        $_GET['elementor-preview']
                    )
                );


            if (
                $preview_id &&
                'elementor_library'
                !==
                get_post_type( $preview_id )
            ) {

                $post_id =
                    $preview_id;
            }
        }


        /*
         * 4. Global post fallback.
         */
        if ( ! $post_id ) {

            global $post;


            if (
                $post instanceof WP_Post &&
                ! empty( $post->ID ) &&
                'elementor_library'
                !==
                get_post_type( $post->ID )
            ) {

                $post_id =
                    (int) $post->ID;
            }
        }


        if ( ! $post_id ) {
            return false;
        }


        $post_type =
            get_post_type(
                $post_id
            );


        if ( ! $post_type ) {
            return false;
        }


        $pod =
            pods(
                $post_type,
                $post_id
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return false;
        }


        return $pod;
    }
}


/**
 * ============================================================
 * 3. RELATIONSHIP TERM IDS UITLEZEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_relationship_term_ids' ) ) {

    function tfsc_derived_rel_v2_get_relationship_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $field_name ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * Pods traversal.
         */
        $traversed_ids =
            $pod->field(
                $field_name . '.term_id'
            );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /*
         * Fallback normale relationship return.
         */
        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    $field_name
                );


            if ( empty( $relations ) ) {
                return [];
            }


            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {

                $relations = [
                    $relations
                ];
            }


            if ( is_numeric( $relations ) ) {

                $relations = [
                    $relations
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $valid_ids
            )
        );
    }
}


/**
 * ============================================================
 * 4. RELATIONSHIP FIELD BESTAAT?
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_has_relationship_field' ) ) {

    function tfsc_derived_rel_v2_has_relationship_field(
        $pod,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $taxonomy )
        ) {
            return false;
        }


        $fields =
            $pod->fields();


        if ( ! is_array( $fields ) ) {
            return false;
        }


        $field_name =
            'relationship_' . $taxonomy;


        return array_key_exists(
            $field_name,
            $fields
        );
    }
}


/**
 * ============================================================
 * 5. FUNCTIENAAM IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_function_ids' ) ) {

    function tfsc_derived_rel_v2_get_function_ids(
        $pod
    ) {

        return
            tfsc_derived_rel_v2_get_relationship_term_ids(
                $pod,
                'relationship_functienaam',
                'functienaam'
            );
    }
}


/**
 * ============================================================
 * 6. OPEN VACATURE IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_vacancy_ids' ) ) {

    function tfsc_derived_rel_v2_get_vacancy_ids(
        $function_term_ids
    ) {

        if (
            empty( $function_term_ids ) ||
            ! taxonomy_exists( 'functienaam' )
        ) {
            return [];
        }


        $vacancy_post_type =
            tfsc_derived_rel_v2_vacancy_post_type();


        if (
            ! post_type_exists(
                $vacancy_post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],
        ];


        $status_taxonomy =
            tfsc_derived_rel_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_derived_rel_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $vacancy_ids =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $vacancy_ids ) ) {
            return [];
        }


        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $vacancy_ids
                )
            )
        );
    }
}


/**
 * ============================================================
 * 7. TARGET TAXONOMY TERMS UIT VACATURES
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_target_term_ids' ) ) {

    function tfsc_derived_rel_v2_get_target_term_ids(
        $vacancy_ids,
        $taxonomy
    ) {

        if (
            empty( $vacancy_ids ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    $taxonomy,
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                $term_ids[] =
                    $term_id;


                if (
                    is_taxonomy_hierarchical(
                        $taxonomy
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        );


                    if ( ! empty( $ancestors ) ) {

                        $term_ids =
                            array_merge(
                                $term_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_filter_level' ) ) {

    function tfsc_derived_rel_v2_filter_level(
        $term_ids,
        $taxonomy,
        $wanted_level
    ) {

        if (
            empty( $term_ids ) ||
            empty( $taxonomy )
        ) {
            return [];
        }


        /*
         * Niet-hiërarchisch:
         * alles = level 0.
         */
        if (
            ! is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            return (
                0 ===
                (int) $wanted_level
            )
                ?
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
                :
            [];
        }


        $filtered = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $level =
                count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );


            if (
                $level ===
                (int) $wanted_level
            ) {

                $filtered[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $filtered
            )
        );
    }
}


/**
 * ============================================================
 * 9. QUERY ID PARSEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_parse_query_id' ) ) {

    function tfsc_derived_rel_v2_parse_query_id(
        $query_id
    ) {

        $query_id =
            (string) $query_id;


        if (
            ! preg_match(
                '/^relationship_(.+)_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {
            return false;
        }


        $taxonomy =
            sanitize_key(
                $matches[1]
            );


        $level =
            (int) $matches[2];


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        return [
            'taxonomy' =>
                $taxonomy,

            'level' =>
                $level,
        ];
    }
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            (string)
            $settings['term_taxonomy_id'];


        $parsed =
            tfsc_derived_rel_v2_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        $taxonomy =
            $parsed['taxonomy'];


        $wanted_level =
            $parsed['level'];


        /*
         * Status taxonomy nooit.
         */
        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /*
         * Elementor Source.
         */
        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        $elementor_taxonomy =
            sanitize_key(
                $elementor_taxonomy
            );


        if (
            $elementor_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if ( ! $pod ) {
            return $args;
        }


        if (
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $args;
        }


        $function_ids =
            tfsc_derived_rel_v2_get_function_ids(
                $pod
            );


        if ( empty( $function_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $vacancy_ids =
            tfsc_derived_rel_v2_get_vacancy_ids(
                $function_ids
            );


        if ( empty( $vacancy_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $target_term_ids =
            tfsc_derived_rel_v2_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $target_term_ids =
            tfsc_derived_rel_v2_filter_level(
                $target_term_ids,
                $taxonomy,
                $wanted_level
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            $target_term_ids;


        $args['hide_empty'] =
            false;


        $args['hierarchical'] =
            false;


        /*
         * Markering voor sorteerfix.
         */
        $args['tfsc_derived_relationship_query'] =
            1;


        $args['tfsc_derived_relationship_taxonomy'] =
            $taxonomy;


        return $args;

    },
    30,
    3
);


/**
 * ============================================================
 * 11. UITEINDELIJKE SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if ( is_admin() ) {
            return $terms;
        }


        if (
            empty( $terms ) ||
            ! is_array( $terms )
        ) {
            return $terms;
        }


        if (
            empty(
                $args['tfsc_derived_relationship_query']
            )
        ) {
            return $terms;
        }


        $taxonomy =
            isset(
                $args['tfsc_derived_relationship_taxonomy']
            )
                ?
            sanitize_key(
                $args['tfsc_derived_relationship_taxonomy']
            )
                :
            '';


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return $terms;
        }


        foreach (
            $terms
            as $term
        ) {

            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                $taxonomy !==
                $term->taxonomy
            ) {
                return $terms;
            }
        }


        $orderby =
            isset(
                $args['orderby']
            )
                ?
            strtolower(
                (string) $args['orderby']
            )
                :
            'name';


        if (
            'name'
            !==
            $orderby
        ) {
            return $terms;
        }


        $order =
            isset(
                $args['order']
            )
                ?
            strtoupper(
                (string) $args['order']
            )
                :
            'ASC';


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {
            $order =
                'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                $name_a =
                    remove_accents(
                        wp_strip_all_tags(
                            $a->name
                        )
                    );


                $name_b =
                    remove_accents(
                        wp_strip_all_tags(
                            $b->name
                        )
                    );


                $comparison =
                    strnatcasecmp(
                        $name_a,
                        $name_b
                    );


                if (
                    'DESC'
                    ===
                    $order
                ) {

                    $comparison *=
                        -1;
                }


                return $comparison;
            }
        );


        return $terms;

    },
    9999,
    4
);


/**
 * ============================================================
 * 12. HIËRARCHISCH TERMPAD
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_term_path' ) ) {

    function tfsc_derived_rel_v2_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs = [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if ( ! empty( $ancestor_ids ) ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error( $ancestor ) &&
                        ! empty( $ancestor->slug )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 13. COMBO URL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_build_combo_url' ) ) {

    function tfsc_derived_rel_v2_build_combo_url(
        $target_term
    ) {

        if (
            ! (
                $target_term instanceof WP_Term
            )
        ) {
            return false;
        }


        $taxonomy =
            $target_term->taxonomy;


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return false;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return false;
        }


        $function_ids =
            tfsc_derived_rel_v2_get_function_ids(
                $pod
            );


        if ( empty( $function_ids ) ) {
            return false;
        }


        $function_terms = [];


        foreach (
            $function_ids
            as $function_id
        ) {

            $function_term =
                get_term(
                    $function_id,
                    'functienaam'
                );


            if (
                $function_term instanceof WP_Term &&
                ! is_wp_error(
                    $function_term
                )
            ) {

                $function_terms[] =
                    $function_term;
            }
        }


        if ( empty( $function_terms ) ) {
            return false;
        }


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],

            [
                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' => [
                    (int)
                    $target_term->term_id,
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    is_taxonomy_hierarchical(
                        $taxonomy
                    ),
            ],
        ];


        $status_taxonomy =
            tfsc_derived_rel_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_derived_rel_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        tfsc_derived_rel_v2_vacancy_post_type(),

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $has_result ) ) {
            return false;
        }


        $parts = [
            tfsc_derived_rel_v2_combo_base(),
        ];


        foreach (
            $function_terms
            as $function_term
        ) {

            $function_path =
                tfsc_derived_rel_v2_term_path(
                    $function_term
                );


            if (
                '' ===
                $function_path
            ) {
                continue;
            }


            $parts[] =
                'functienaam';

            $parts[] =
                $function_path;
        }


        $target_path =
            tfsc_derived_rel_v2_term_path(
                $target_term
            );


        if (
            '' ===
            $target_path
        ) {
            return false;
        }


        $parts[] =
            $taxonomy;

        $parts[] =
            $target_path;


        return home_url(
            '/'
            .
            implode(
                '/',
                array_map(
                    function( $part ) {

                        return trim(
                            $part,
                            '/'
                        );
                    },
                    $parts
                )
            )
            .
            '/'
        );
    }
}


/**
 * ============================================================
 * 14. TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if ( is_admin() ) {
            return $termlink;
        }


        if (
            ! (
                $term instanceof WP_Term
            ) ||
            empty(
                $taxonomy
            )
        ) {
            return $termlink;
        }


        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $termlink;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_derived_rel_v2_build_combo_url(
                $term
            );


        if ( ! $combo_url ) {
            return $termlink;
        }


        return $combo_url;

    },
    30,
    3
);

/**
 * TFSC - Query Show More
 *
 * Gebruik op een Elementor Taxonomy Loop widget:
 *
 * CSS class:
 *     tfsc_query_show-more
 *
 * Custom Attribute:
 *     data_visible-items|8
 *
 * Als data_visible-items ontbreekt, wordt standaard 8 gebruikt.
 */

add_action(
    'wp_footer',
    function() {

        if ( is_admin() ) {
            return;
        }

        ?>
        <script>
        document.addEventListener('DOMContentLoaded', function () {

            const widgets = document.querySelectorAll(
                '.tfsc_query_show-more'
            );

            if (!widgets.length) {
                return;
            }

            widgets.forEach(function (widget) {

                /*
                 * Dubbele initialisatie voorkomen.
                 */
                if (
                    widget.dataset.tfscShowMoreInitialized === '1'
                ) {
                    return;
                }

                const visibleItems = parseInt(
                    widget.getAttribute('data_visible-items'),
                    10
                ) || 8;


                /*
                 * Elementor widget container.
                 */
                const widgetContainer =
                    widget.querySelector(
                        ':scope > .elementor-widget-container'
                    );

                if (!widgetContainer) {
                    return;
                }


                /*
                 * Elementor Loop container.
                 */
                const loopContainer =
                    widgetContainer.querySelector(
                        '.elementor-loop-container'
                    );

                if (!loopContainer) {
                    return;
                }


                /*
                 * Alleen de daadwerkelijke loop-items.
                 */
                const items = Array.from(
                    loopContainer.querySelectorAll(
                        ':scope > .e-loop-item'
                    )
                );


                /*
                 * Niet genoeg items voor show-more.
                 */
                if (
                    !items.length ||
                    items.length <= visibleItems
                ) {
                    return;
                }


                widget.dataset.tfscShowMoreInitialized = '1';


                /*
                 * Items na de limiet verbergen.
                 */
                items.forEach(function (item, index) {

                    if (index >= visibleItems) {

                        item.style.display = 'none';

                        item.setAttribute(
                            'data-tfsc-hidden',
                            '1'
                        );
                    }
                });


                /*
                 * Button wrapper.
                 */
                const buttonWrapper =
                    document.createElement('div');

                buttonWrapper.className =
                    'tfsc-query-show-more__wrapper';


                /*
                 * Button.
                 */
                const button =
                    document.createElement('button');

                button.type =
                    'button';

                button.className =
                    'tfsc-query-show-more__button';

                button.textContent =
                    'Meer tonen';

                button.setAttribute(
                    'aria-expanded',
                    'false'
                );


                buttonWrapper.appendChild(
                    button
                );


                /*
                 * BELANGRIJK:
                 *
                 * Button BINNEN de Elementor widget-container
                 * plaatsen, direct na de loop-container.
                 */
                loopContainer.insertAdjacentElement(
                    'afterend',
                    buttonWrapper
                );


                let expanded = false;


                button.addEventListener(
                    'click',
                    function () {

                        expanded =
                            !expanded;


                        items.forEach(
                            function (item, index) {

                                if (
                                    index <
                                    visibleItems
                                ) {
                                    return;
                                }


                                item.style.display =
                                    expanded
                                        ? ''
                                        : 'none';
                            }
                        );


                        button.textContent =
                            expanded
                                ? 'Minder tonen'
                                : 'Meer tonen';


                        button.setAttribute(
                            'aria-expanded',
                            expanded
                                ? 'true'
                                : 'false'
                        );
                    }
                );

            });

        });
        </script>


        <style>
        .tfsc_query_show-more
        .tfsc-query-show-more__wrapper {
            width: 100%;
            margin-top: 20px;
        }

        .tfsc_query_show-more
        .tfsc-query-show-more__button {
            cursor: pointer;
        }
        </style>
        <?php

    },
    100
);

/**
 * TFSC - Query Show More
 *
 * CSS class:
 *     tfsc_query_show-more
 *
 * Custom Attribute:
 *     data_visible-items|8
 *
 * Werkt op normale frontend én bij dynamische
 * Elementor editor/preview rendering.
 */

add_action(
    'wp_footer',
    function() {

        if ( is_admin() ) {
            return;
        }

        ?>
        <script>
        (function () {

            function tfscInitShowMore(scope) {

                const root =
                    scope || document;


                let widgets = [];


                /*
                 * Scope zelf kan de widget zijn.
                 */
                if (
                    root.classList &&
                    root.classList.contains(
                        'tfsc_query_show-more'
                    )
                ) {

                    widgets.push(
                        root
                    );
                }


                /*
                 * Widgets binnen scope zoeken.
                 */
                if (
                    root.querySelectorAll
                ) {

                    widgets = widgets.concat(
                        Array.from(
                            root.querySelectorAll(
                                '.tfsc_query_show-more'
                            )
                        )
                    );
                }


                if (!widgets.length) {
                    return;
                }


                widgets.forEach(function (widget) {

                    /*
                     * Bestaande knop opruimen als Elementor
                     * de inhoud opnieuw heeft gerenderd.
                     */
                    const oldWrapper =
                        widget.querySelector(
                            '.tfsc-query-show-more__wrapper'
                        );


                    if (oldWrapper) {

                        oldWrapper.remove();
                    }


                    const visibleItems =
                        parseInt(
                            widget.getAttribute(
                                'data_visible-items'
                            ),
                            10
                        ) || 8;


                    const widgetContainer =
                        widget.querySelector(
                            ':scope > .elementor-widget-container'
                        );


                    if (!widgetContainer) {
                        return;
                    }


                    const loopContainer =
                        widgetContainer.querySelector(
                            '.elementor-loop-container'
                        );


                    if (!loopContainer) {
                        return;
                    }


                    const items =
                        Array.from(
                            loopContainer.querySelectorAll(
                                ':scope > .e-loop-item'
                            )
                        );


                    if (!items.length) {
                        return;
                    }


                    /*
                     * Eerst eventuele eerdere inline display
                     * terugzetten.
                     */
                    items.forEach(function (item) {

                        item.style.display = '';

                        item.removeAttribute(
                            'data-tfsc-hidden'
                        );
                    });


                    /*
                     * Geen knop nodig.
                     */
                    if (
                        items.length <=
                        visibleItems
                    ) {
                        return;
                    }


                    /*
                     * Extra items verbergen.
                     */
                    items.forEach(
                        function (item, index) {

                            if (
                                index >=
                                visibleItems
                            ) {

                                item.style.display =
                                    'none';

                                item.setAttribute(
                                    'data-tfsc-hidden',
                                    '1'
                                );
                            }
                        }
                    );


                    const buttonWrapper =
                        document.createElement(
                            'div'
                        );


                    buttonWrapper.className =
                        'tfsc-query-show-more__wrapper';


                    const button =
                        document.createElement(
                            'button'
                        );


                    button.type =
                        'button';


                    button.className =
                        'tfsc-query-show-more__button';


                    button.textContent =
                        'Meer tonen';


                    button.setAttribute(
                        'aria-expanded',
                        'false'
                    );


                    buttonWrapper.appendChild(
                        button
                    );


                    loopContainer.insertAdjacentElement(
                        'afterend',
                        buttonWrapper
                    );


                    let expanded =
                        false;


                    button.addEventListener(
                        'click',
                        function () {

                            expanded =
                                !expanded;


                            items.forEach(
                                function (
                                    item,
                                    index
                                ) {

                                    if (
                                        index <
                                        visibleItems
                                    ) {
                                        return;
                                    }


                                    item.style.display =
                                        expanded
                                            ? ''
                                            : 'none';
                                }
                            );


                            button.textContent =
                                expanded
                                    ? 'Minder tonen'
                                    : 'Meer tonen';


                            button.setAttribute(
                                'aria-expanded',
                                expanded
                                    ? 'true'
                                    : 'false'
                            );
                        }
                    );
                });
            }


            /*
             * Normale frontend.
             */
            document.addEventListener(
                'DOMContentLoaded',
                function () {

                    tfscInitShowMore(
                        document
                    );
                }
            );


            /*
             * Elementor frontend / editor.
             */
            window.addEventListener(
                'elementor/frontend/init',
                function () {

                    if (
                        typeof elementorFrontend ===
                        'undefined'
                    ) {
                        return;
                    }


                    elementorFrontend.hooks.addAction(
                        'frontend/element_ready/global',
                        function (scope) {

                            /*
                             * Elementor geeft vaak een
                             * jQuery-object mee.
                             */
                            let element =
                                scope;


                            if (
                                scope &&
                                scope[0]
                            ) {

                                element =
                                    scope[0];
                            }


                            if (!element) {
                                return;
                            }


                            tfscInitShowMore(
                                element
                            );
                        }
                    );
                }
            );


            /*
             * Extra fallback voor Elementor die DOM-elementen
             * later vervangt.
             */
            const observer =
                new MutationObserver(
                    function (mutations) {

                        mutations.forEach(
                            function (mutation) {

                                mutation.addedNodes.forEach(
                                    function (node) {

                                        if (
                                            node.nodeType !==
                                            1
                                        ) {
                                            return;
                                        }


                                        tfscInitShowMore(
                                            node
                                        );
                                    }
                                );
                            }
                        );
                    }
                );


            observer.observe(
                document.documentElement,
                {
                    childList: true,
                    subtree: true
                }
            );

        })();
        </script>


        <style>
        .tfsc_query_show-more
        .tfsc-query-show-more__wrapper {
            width: 100%;
            margin-top: 20px;
        }

        .tfsc_query_show-more
        .tfsc-query-show-more__button {
            cursor: pointer;
        }
        </style>
        <?php

    },
    100
);

/**
 * TFSC - DEBUG Elementor Template Settings
 *
 * Laat zien welke Elementor document/template settings
 * beschikbaar zijn tijdens het bewerken van een Theme Builder template.
 */

add_action(
    'wp_footer',
    function() {

        if ( is_admin() ) {
            return;
        }

        if (
            ! did_action( 'elementor/loaded' ) ||
            ! class_exists( '\Elementor\Plugin' )
        ) {
            return;
        }


        $object =
            get_queried_object();


        if (
            ! ( $object instanceof WP_Post ) ||
            'elementor_library'
            !== get_post_type( $object->ID )
        ) {
            return;
        }


        $template_id =
            (int) $object->ID;


        $data = [
            'template_id' =>
                $template_id,

            'template_title' =>
                get_the_title(
                    $template_id
                ),
        ];


        try {

            $document =
                \Elementor\Plugin::$instance
                    ->documents
                    ->get(
                        $template_id
                    );


            if ( $document ) {

                /*
                 * Alle document settings.
                 */
                if (
                    method_exists(
                        $document,
                        'get_settings'
                    )
                ) {

                    $data[
                        'document_settings'
                    ] =
                        $document->get_settings();
                }


                /*
                 * Probeer veel voorkomende preview keys
                 * ook afzonderlijk.
                 */
                $possible_keys = [
                    'preview_type',
                    'preview_id',
                    'preview_post_id',
                    'preview_post',
                    'preview_dynamic_content',
                    'preview_dynamic_content_type',
                    'preview_dynamic_content_id',
                ];


                $data[
                    'possible_preview_settings'
                ] = [];


                foreach (
                    $possible_keys
                    as $key
                ) {

                    if (
                        method_exists(
                            $document,
                            'get_settings'
                        )
                    ) {

                        $value =
                            $document->get_settings(
                                $key
                            );


                        if (
                            null !== $value &&
                            '' !== $value
                        ) {

                            $data[
                                'possible_preview_settings'
                            ][ $key ] =
                                $value;
                        }
                    }
                }
            }

        } catch ( Throwable $e ) {

            $data[
                'error'
            ] =
                $e->getMessage();
        }


        /*
         * Ook relevante post meta bekijken.
         *
         * Dit is alleen debug-output.
         */
        $meta =
            get_post_meta(
                $template_id
            );


        $relevant_meta = [];


        foreach (
            $meta
            as $key => $value
        ) {

            if (
                false !== stripos(
                    $key,
                    'preview'
                ) ||
                false !== stripos(
                    $key,
                    'elementor'
                )
            ) {

                $relevant_meta[
                    $key
                ] =
                    $value;
            }
        }


        $data[
            'relevant_meta'
        ] =
            $relevant_meta;


        ?>
        <div
            style="
                margin:40px 20px;
                padding:20px;
                border:2px solid #000;
                background:#fff;
                color:#000;
                font-family:monospace;
                font-size:13px;
                line-height:1.5;
                overflow:auto;
                position:relative;
                z-index:999999;
            "
        >

            <h3>
                TFSC DEBUG — Elementor Template Settings
            </h3>

            <pre><?php
            echo esc_html(
                print_r(
                    $data,
                    true
                )
            );
            ?></pre>

        </div>
        <?php

    },
    9999
);

/**
 * TFSC - Generic Derived Relationship Taxonomy Terms
 *
 * Query ID:
 *
 * relationship_{taxonomy}_level_{nummer}
 *
 * Voorbeelden:
 *
 * relationship_locatie_level_1
 * relationship_functie-inhoud_level_0
 * relationship_bedrijfssector_level_0
 *
 * Elementor Filter by Depth: UIT
 */


/**
 * ============================================================
 * 1. CONFIG
