/**
 * ============================================================
 * 2. HUIDIGE CONTENT POST + POD
 * ============================================================
 *
 * Frontend:
 *     gebruikt de normale queried post.
 *
 * Elementor Theme Builder editor:
 *     queried object = elementor_library template.
 *
 *     In dat geval lezen we uit de Elementor template:
 *
 *         preview_type
 *         preview_id
 *
 *     Bijvoorbeeld:
 *
 *         preview_type = single/beroep
 *         preview_id   = 23402
 *
 *     Vervolgens gebruiken we beroep 23402 als echte
 *     content-context voor Pods en de relationship queries.
 */


/**
 * Echte content post-ID bepalen.
 */
if ( ! function_exists( 'tfsc_derived_rel_v2_get_context_post_id' ) ) {

    function tfsc_derived_rel_v2_get_context_post_id() {

        $object =
            get_queried_object();


        /**
         * ========================================================
         * 1. NORMALE FRONTEND
         * ========================================================
         */

        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID ) &&
            'elementor_library'
            !==
            get_post_type( $object->ID )
        ) {

            return (int) $object->ID;
        }


        /**
         * ========================================================
         * 2. ELEMENTOR THEME BUILDER TEMPLATE
         * ========================================================
         */

        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID ) &&
            'elementor_library'
            ===
            get_post_type( $object->ID )
        ) {

            $template_id =
                (int) $object->ID;


            /*
             * Eerst via Elementor document API.
             */
            if (
                did_action( 'elementor/loaded' ) &&
                class_exists( '\Elementor\Plugin' )
            ) {

                try {

                    $documents =
                        \Elementor\Plugin::$instance
                            ->documents;


                    if ( $documents ) {

                        $document =
                            $documents->get(
                                $template_id
                            );


                        if (
                            $document &&
                            method_exists(
                                $document,
                                'get_settings'
                            )
                        ) {

                            $preview_id =
                                absint(
                                    $document->get_settings(
                                        'preview_id'
                                    )
                                );


                            if (
                                $preview_id &&
                                'elementor_library'
                                !==
                                get_post_type(
                                    $preview_id
                                )
                            ) {

                                return $preview_id;
                            }
                        }
                    }

                } catch ( Throwable $e ) {

                    /*
                     * Niets doen.
                     *
                     * Hieronder volgt nog een directe
                     * post-meta fallback.
                     */
                }
            }


            /**
             * ====================================================
             * FALLBACK: _elementor_page_settings
             * ====================================================
             *
             * Uit jouw debug weten we dat preview_id hier
             * eveneens wordt opgeslagen.
             */

            $page_settings =
                get_post_meta(
                    $template_id,
                    '_elementor_page_settings',
                    true
                );


            if (
                is_array(
                    $page_settings
                ) &&
                ! empty(
                    $page_settings['preview_id']
                )
            ) {

                $preview_id =
                    absint(
                        $page_settings['preview_id']
                    );


                if (
                    $preview_id &&
                    'elementor_library'
                    !==
                    get_post_type(
                        $preview_id
                    )
                ) {

                    return $preview_id;
                }
            }
        }


        /**
         * ========================================================
         * 3. WORDPRESS PREVIEW FALLBACK
         * ========================================================
         */

        if (
            isset(
                $_GET['preview_id']
            )
        ) {

            $preview_id =
                absint(
                    wp_unslash(
                        $_GET['preview_id']
                    )
                );


            if (
                $preview_id &&
                'elementor_library'
                !==
                get_post_type(
                    $preview_id
                )
            ) {

                return $preview_id;
            }
        }


        /**
         * ========================================================
         * 4. GLOBAL $post FALLBACK
         * ========================================================
         */

        global $post;


        if (
            $post instanceof WP_Post &&
            ! empty( $post->ID ) &&
            'elementor_library'
            !==
            get_post_type( $post->ID )
        ) {

            return (int) $post->ID;
        }


        return 0;
    }
}


/**
 * Pods-object van de echte content-context ophalen.
 */
if ( ! function_exists( 'tfsc_derived_rel_v2_get_current_pod' ) ) {

    function tfsc_derived_rel_v2_get_current_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }


        $post_id =
            tfsc_derived_rel_v2_get_context_post_id();


        if ( ! $post_id ) {
            return false;
        }


        $post_type =
            get_post_type(
                $post_id
            );


        if ( ! $post_type ) {
            return false;
        }


        $pod =
            pods(
                $post_type,
                $post_id
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return false;
        }


        return $pod;
    }
}

/**
 * ============================================================
 * 3. RELATIONSHIP TERM IDS UITLEZEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_relationship_term_ids' ) ) {

    function tfsc_derived_rel_v2_get_relationship_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $field_name ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * Pods traversal.
         */
        $traversed_ids =
            $pod->field(
                $field_name . '.term_id'
            );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /*
         * Fallback normale relationship return.
         */
        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    $field_name
                );


            if ( empty( $relations ) ) {
                return [];
            }


            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {

                $relations = [
                    $relations
                ];
            }


            if ( is_numeric( $relations ) ) {

                $relations = [
                    $relations
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $valid_ids
            )
        );
    }
}


