/**
 * ============================================================
 * 7. TARGET TAXONOMY TERMS UIT VACATURES
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_target_term_ids' ) ) {

    function tfsc_derived_rel_v2_get_target_term_ids(
        $vacancy_ids,
        $taxonomy
    ) {

        if (
            empty( $vacancy_ids ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    $taxonomy,
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                $term_ids[] =
                    $term_id;


                if (
                    is_taxonomy_hierarchical(
                        $taxonomy
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        );


                    if ( ! empty( $ancestors ) ) {

                        $term_ids =
                            array_merge(
                                $term_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_filter_level' ) ) {

    function tfsc_derived_rel_v2_filter_level(
        $term_ids,
        $taxonomy,
        $wanted_level
    ) {

        if (
            empty( $term_ids ) ||
            empty( $taxonomy )
        ) {
            return [];
        }


        /*
         * Niet-hiërarchisch:
         * alles = level 0.
         */
        if (
            ! is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            return (
                0 ===
                (int) $wanted_level
            )
                ?
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
                :
            [];
        }


        $filtered = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $level =
                count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );


            if (
                $level ===
                (int) $wanted_level
            ) {

                $filtered[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $filtered
            )
        );
    }
}


/**
 * ============================================================
 * 9. QUERY ID PARSEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_parse_query_id' ) ) {

    function tfsc_derived_rel_v2_parse_query_id(
        $query_id
    ) {

        $query_id =
            (string) $query_id;


        if (
            ! preg_match(
                '/^relationship_(.+)_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {
            return false;
        }


        $taxonomy =
            sanitize_key(
                $matches[1]
            );


        $level =
            (int) $matches[2];


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        return [
            'taxonomy' =>
                $taxonomy,

            'level' =>
                $level,
        ];
    }
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            (string)
            $settings['term_taxonomy_id'];


        $parsed =
            tfsc_derived_rel_v2_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        $taxonomy =
            $parsed['taxonomy'];


        $wanted_level =
            $parsed['level'];


        /*
         * Status taxonomy nooit.
         */
        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /*
         * Elementor Source.
         */
        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        $elementor_taxonomy =
            sanitize_key(
                $elementor_taxonomy
            );


        if (
            $elementor_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if ( ! $pod ) {
            return $args;
        }


        if (
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $args;
        }


        $function_ids =
            tfsc_derived_rel_v2_get_function_ids(
                $pod
            );


        if ( empty( $function_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $vacancy_ids =
            tfsc_derived_rel_v2_get_vacancy_ids(
                $function_ids
            );


        if ( empty( $vacancy_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $target_term_ids =
            tfsc_derived_rel_v2_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $target_term_ids =
            tfsc_derived_rel_v2_filter_level(
                $target_term_ids,
                $taxonomy,
                $wanted_level
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            $target_term_ids;


        $args['hide_empty'] =
            false;


        $args['hierarchical'] =
            false;


        /*
         * Markering voor sorteerfix.
         */
        $args['tfsc_derived_relationship_query'] =
            1;


        $args['tfsc_derived_relationship_taxonomy'] =
            $taxonomy;


        return $args;

    },
    30,
    3
);


/**
 * ============================================================
 * 11. UITEINDELIJKE SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if ( is_admin() ) {
            return $terms;
        }


        if (
            empty( $terms ) ||
            ! is_array( $terms )
        ) {
            return $terms;
        }


        if (
            empty(
                $args['tfsc_derived_relationship_query']
            )
        ) {
            return $terms;
        }


        $taxonomy =
            isset(
                $args['tfsc_derived_relationship_taxonomy']
            )
                ?
            sanitize_key(
                $args['tfsc_derived_relationship_taxonomy']
            )
                :
            '';


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return $terms;
        }


        foreach (
            $terms
            as $term
        ) {

            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                $taxonomy !==
                $term->taxonomy
            ) {
                return $terms;
            }
        }


        $orderby =
            isset(
                $args['orderby']
            )
                ?
            strtolower(
                (string) $args['orderby']
            )
                :
            'name';


        if (
            'name'
            !==
            $orderby
        ) {
            return $terms;
        }


        $order =
            isset(
                $args['order']
            )
                ?
            strtoupper(
                (string) $args['order']
            )
                :
            'ASC';


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {
            $order =
                'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                $name_a =
                    remove_accents(
                        wp_strip_all_tags(
                            $a->name
                        )
                    );


                $name_b =
                    remove_accents(
                        wp_strip_all_tags(
                            $b->name
                        )
                    );


                $comparison =
                    strnatcasecmp(
                        $name_a,
                        $name_b
                    );


                if (
                    'DESC'
                    ===
                    $order
                ) {

                    $comparison *=
                        -1;
                }


                return $comparison;
            }
        );


        return $terms;

    },
    9999,
    4
);


/**
 * ============================================================
 * 12. HIËRARCHISCH TERMPAD
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_term_path' ) ) {

    function tfsc_derived_rel_v2_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs = [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if ( ! empty( $ancestor_ids ) ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error( $ancestor ) &&
                        ! empty( $ancestor->slug )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 13. COMBO URL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_build_combo_url' ) ) {

    function tfsc_derived_rel_v2_build_combo_url(
        $target_term
    ) {

        if (
            ! (
                $target_term instanceof WP_Term
            )
        ) {
            return false;
        }


        $taxonomy =
            $target_term->taxonomy;


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return false;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return false;
        }


        $function_ids =
            tfsc_derived_rel_v2_get_function_ids(
                $pod
            );


        if ( empty( $function_ids ) ) {
            return false;
        }


        $function_terms = [];


        foreach (
            $function_ids
            as $function_id
        ) {

            $function_term =
                get_term(
                    $function_id,
                    'functienaam'
                );


            if (
                $function_term instanceof WP_Term &&
                ! is_wp_error(
                    $function_term
                )
            ) {

                $function_terms[] =
                    $function_term;
            }
        }


        if ( empty( $function_terms ) ) {
            return false;
        }


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],

            [
                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' => [
                    (int)
                    $target_term->term_id,
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    is_taxonomy_hierarchical(
                        $taxonomy
                    ),
            ],
        ];


        $status_taxonomy =
            tfsc_derived_rel_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_derived_rel_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        tfsc_derived_rel_v2_vacancy_post_type(),

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $has_result ) ) {
            return false;
        }


        $parts = [
            tfsc_derived_rel_v2_combo_base(),
        ];


        foreach (
            $function_terms
            as $function_term
        ) {

            $function_path =
                tfsc_derived_rel_v2_term_path(
                    $function_term
                );


            if (
                '' ===
                $function_path
            ) {
                continue;
            }


            $parts[] =
                'functienaam';

            $parts[] =
                $function_path;
        }


        $target_path =
            tfsc_derived_rel_v2_term_path(
                $target_term
            );


        if (
            '' ===
            $target_path
        ) {
            return false;
        }


        $parts[] =
            $taxonomy;

        $parts[] =
            $target_path;


        return home_url(
            '/'
            .
            implode(
                '/',
                array_map(
                    function( $part ) {

                        return trim(
                            $part,
                            '/'
                        );
                    },
                    $parts
                )
            )
            .
            '/'
        );
    }
}


/**
 * ============================================================
 * 14. TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if ( is_admin() ) {
            return $termlink;
        }


        if (
            ! (
                $term instanceof WP_Term
            ) ||
            empty(
                $taxonomy
            )
        ) {
            return $termlink;
        }


        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $termlink;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_derived_rel_v2_build_combo_url(
                $term
            );


        if ( ! $combo_url ) {
            return $termlink;
        }


        return $combo_url;

    },
    30,
    3
);

/**
 * TFSC - Query Show More
 *
 * Gebruik op een Elementor Taxonomy Loop widget:
 *
 * CSS class:
 *     tfsc_query_show-more
 *
 * Custom Attribute:
 *     data_visible-items|8
 *
 * Werkt op frontend en bij dynamische Elementor rendering.
 */

add_action(
    'wp_footer',
    function() {

        if ( is_admin() ) {
            return;
        }

        ?>
        <script>
        (function () {

            function tfscInitShowMore(scope) {

                const root =
                    scope || document;

                let widgets = [];


                /*
                 * Scope zelf kan de widget zijn.
                 */
                if (
                    root.classList &&
                    root.classList.contains(
                        'tfsc_query_show-more'
                    )
                ) {

                    widgets.push(
                        root
                    );
                }


                /*
                 * Widgets binnen scope zoeken.
                 */
                if (
                    root.querySelectorAll
                ) {

                    widgets = widgets.concat(
                        Array.from(
                            root.querySelectorAll(
                                '.tfsc_query_show-more'
                            )
                        )
                    );
                }


                if (!widgets.length) {
                    return;
                }


                widgets.forEach(function (widget) {

                    /*
                     * Bestaande knop opruimen als Elementor
                     * de widget opnieuw heeft gerenderd.
                     */
                    const oldWrapper =
                        widget.querySelector(
                            '.tfsc-query-show-more__wrapper'
                        );


                    if (oldWrapper) {
                        oldWrapper.remove();
                    }


                    const visibleItems =
                        parseInt(
                            widget.getAttribute(
                                'data_visible-items'
                            ),
                            10
                        ) || 8;


                    const widgetContainer =
                        widget.querySelector(
                            ':scope > .elementor-widget-container'
                        );


                    if (!widgetContainer) {
                        return;
                    }


                    const loopContainer =
                        widgetContainer.querySelector(
                            '.elementor-loop-container'
                        );


                    if (!loopContainer) {
                        return;
                    }


                    const items =
                        Array.from(
                            loopContainer.querySelectorAll(
                                ':scope > .e-loop-item'
                            )
                        );


                    if (!items.length) {
                        return;
                    }


                    /*
                     * Oude inline display terugzetten.
                     */
                    items.forEach(function (item) {

                        item.style.display = '';

                        item.removeAttribute(
                            'data-tfsc-hidden'
                        );
                    });


                    /*
                     * Geen knop nodig.
                     */
                    if (
                        items.length <=
                        visibleItems
                    ) {
                        return;
                    }


                    /*
                     * Extra items verbergen.
                     */
                    items.forEach(
                        function (item, index) {

                            if (
                                index >=
                                visibleItems
                            ) {

                                item.style.display =
                                    'none';

                                item.setAttribute(
                                    'data-tfsc-hidden',
                                    '1'
                                );
                            }
                        }
                    );


                    /*
                     * Wrapper.
                     */
                    const buttonWrapper =
                        document.createElement(
                            'div'
                        );


                    buttonWrapper.className =
                        'tfsc-query-show-more__wrapper';


                    /*
                     * Button.
                     */
                    const button =
                        document.createElement(
                            'button'
                        );


                    button.type =
                        'button';


                    button.className =
                        'tfsc-query-show-more__button';


                    button.innerHTML =
                        '<span class="tfsc-query-show-more__label">Meer opties tonen</span>' +
                        '<span class="tfsc-query-show-more__icon" aria-hidden="true"></span>';


                    button.setAttribute(
                        'aria-expanded',
                        'false'
                    );


                    buttonWrapper.appendChild(
                        button
                    );


                    /*
                     * Binnen Elementor widget-container,
                     * direct na de loop.
                     */
                    loopContainer.insertAdjacentElement(
                        'afterend',
                        buttonWrapper
                    );


                    let expanded =
                        false;


                    button.addEventListener(
                        'click',
                        function () {

                            expanded =
                                !expanded;


                            items.forEach(
                                function (
                                    item,
                                    index
                                ) {

                                    if (
                                        index <
                                        visibleItems
                                    ) {
                                        return;
                                    }


                                    item.style.display =
                                        expanded
                                            ? ''
                                            : 'none';
                                }
                            );


                            const label =
                                button.querySelector(
                                    '.tfsc-query-show-more__label'
                                );


                            if (label) {

                                label.textContent =
                                    expanded
                                        ? 'Minder opties tonen'
                                        : 'Meer opties tonen';
                            }


                            button.classList.toggle(
                                'tfsc-query-show-more__button--expanded',
                                expanded
                            );


                            button.setAttribute(
                                'aria-expanded',
                                expanded
                                    ? 'true'
                                    : 'false'
                            );
                        }
                    );
                });
            }


            /*
             * Normale frontend.
             */
            document.addEventListener(
                'DOMContentLoaded',
                function () {

                    tfscInitShowMore(
                        document
                    );
                }
            );


            /*
             * Elementor frontend / editor rendering.
             */
            window.addEventListener(
                'elementor/frontend/init',
                function () {

                    if (
                        typeof elementorFrontend ===
                        'undefined'
                    ) {
                        return;
                    }


                    elementorFrontend.hooks.addAction(
                        'frontend/element_ready/global',
                        function (scope) {

                            let element =
                                scope;


                            if (
                                scope &&
                                scope[0]
                            ) {

                                element =
                                    scope[0];
                            }


                            if (!element) {
                                return;
                            }


                            tfscInitShowMore(
                                element
                            );
                        }
                    );
                }
            );


            /*
             * Fallback voor dynamisch opnieuw
             * gerenderde Elementor onderdelen.
             */
            const observer =
                new MutationObserver(
                    function (mutations) {

                        mutations.forEach(
                            function (mutation) {

                                mutation.addedNodes.forEach(
                                    function (node) {

                                        if (
                                            node.nodeType !==
                                            1
                                        ) {
                                            return;
                                        }


                                        tfscInitShowMore(
                                            node
                                        );
                                    }
                                );
                            }
                        );
                    }
                );


            observer.observe(
                document.documentElement,
                {
                    childList: true,
                    subtree: true
                }
            );

        })();
        </script>


        <style>
        .tfsc_query_show-more
        .tfsc-query-show-more__wrapper {
            width: 100%
        }


        .tfsc_query_show-more
        .tfsc-query-show-more__button {
            display: inline-flex;
            align-items: center;
            gap: 8px;

            cursor: pointer;
        }


        /*
         * Pijl.
         */
        .tfsc_query_show-more
        .tfsc-query-show-more__icon {
            display: inline-block;

            width: 8px;
            height: 8px;

            border-right: 2px solid currentColor;
            border-bottom: 2px solid currentColor;

            transform:
                rotate(45deg)
                translateY(-2px);

            transition:
                transform 0.2s ease;
        }


        /*
         * Uitgeklapt = pijl omhoog.
         */
        .tfsc_query_show-more
        .tfsc-query-show-more__button--expanded
        .tfsc-query-show-more__icon {

            transform:
                rotate(225deg)
                translateY(-2px);
        }
        </style>
        <?php

    },
    100
);

/**
 * TFSC - Vacature Button URL
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Deze shortcode bepaalt de URL van een vacaturebutton op basis
 * van één vast Pods relationship field:
 *
 *     relationship_vacature_button_url
 *
 * Dat field mag verwijzen naar een taxonomy-term naar keuze.
 *
 *
 * ============================================================
 * SHORTCODE
 * ============================================================
 *
 * Gebruik:
 *
 *     [vacature_button_url]
 *
 *
 * ============================================================
 * WERKING OP CPT / POST
 * ============================================================
 *
 * Op een singular post of CPT:
 *
 *     huidige post
 *         ↓
 *     Pods object
 *         ↓
 *     relationship_vacature_button_url
 *         ↓
 *     gekoppelde taxonomy-term
 *         ↓
 *     get_term_link()
 *         ↓
 *     URL
 *
 *
 * Voorbeeld:
 *
 * Beroep "Field Service Engineer"
 *
 * relationship_vacature_button_url
 *     → functienaam: Field Service Engineer
 *
 * De shortcode geeft dan de URL van die functienaam-term terug.
 *
 *
 * ============================================================
 * WERKING OP TAXONOMY ARCHIVE
 * ============================================================
 *
 * Op een taxonomy archive:
 *
 *     huidige WP_Term
 *         ↓
 *     Pods taxonomy-term object
 *         ↓
 *     relationship_vacature_button_url
 *         ↓
 *     gekoppelde taxonomy-term
 *         ↓
 *     get_term_link()
 *         ↓
 *     URL
 *
 *
 * Daardoor hoeft de shortcode niet te weten op welke taxonomy
 * hij wordt gebruikt.
 *
 *
 * ============================================================
 * ELEMENTOR PREVIEW
 * ============================================================
 *
 * Als de helper uit:
 *
 *     TFSC - Generic Derived Relationship Taxonomy Terms
 *
 * beschikbaar is:
 *
 *     tfsc_derived_rel_v2_get_context_post_id()
 *
 * dan wordt bij een Elementor Theme Builder preview automatisch
 * de ingestelde Preview Dynamic Content post gebruikt.
 *
 *
 * ============================================================
 * BELANGRIJK
 * ============================================================
 *
 * Het relationship field is bedoeld als ENKELE selectie.
 *
 * Als er toch meerdere gekoppelde objecten terugkomen,
 * gebruikt deze shortcode de eerste geldige taxonomy-term.
 *
 * De uiteindelijke URL wordt opgehaald met get_term_link().
 * Daardoor blijven bestaande TFSC term_link filters actief.
 */


add_shortcode(
    'vacature_button_url',
    function() {

        if ( ! function_exists( 'pods' ) ) {
            return '';
        }


        $field_name =
            'relationship_vacature_button_url';


        $pod = false;


        /**
         * ========================================================
         * 1. TAXONOMY ARCHIVE
         * ========================================================
         */

        $object =
            get_queried_object();


        if (
            $object instanceof WP_Term &&
            ! empty( $object->term_id ) &&
            ! empty( $object->taxonomy )
        ) {

            /*
             * Pods taxonomy object openen.
             */
            $pod =
                pods(
                    $object->taxonomy,
                    (int) $object->term_id
                );
        }


        /**
         * ========================================================
         * 2. SINGULAR POST / CPT
         * ========================================================
         */

        if ( ! $pod ) {

            $post_id = 0;


            /*
             * Gebruik onze Elementor-aware context helper
             * als die beschikbaar is.
             */
            if (
                function_exists(
                    'tfsc_derived_rel_v2_get_context_post_id'
                )
            ) {

                $post_id =
                    tfsc_derived_rel_v2_get_context_post_id();

            } elseif (
                $object instanceof WP_Post
            ) {

                $post_id =
                    (int) $object->ID;

            } else {

                $post_id =
                    get_queried_object_id();
            }


            if ( $post_id ) {

                $post_type =
                    get_post_type(
                        $post_id
                    );


                if ( $post_type ) {

                    $pod =
                        pods(
                            $post_type,
                            $post_id
                        );
                }
            }
        }


        /**
         * ========================================================
         * 3. POD CONTROLEREN
         * ========================================================
         */

        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return '';
        }


        /**
         * ========================================================
         * 4. RELATIONSHIP UITLEZEN
         * ========================================================
         */

        $relations =
            $pod->field(
                $field_name
            );


        if ( empty( $relations ) ) {
            return '';
        }


        /*
         * Eén numerieke waarde.
         */
        if (
            is_numeric(
                $relations
            )
        ) {

            $relations = [
                $relations
            ];
        }


        /*
         * Eén associatieve relationship array.
         */
        if (
            is_array( $relations ) &&
            (
                isset( $relations['term_id'] ) ||
                isset( $relations['id'] ) ||
                isset( $relations['ID'] )
            )
        ) {

            $relations = [
                $relations
            ];
        }


        /**
         * ========================================================
         * 5. EERSTE GELDIGE TAXONOMY TERM VINDEN
         * ========================================================
         */

        $term = false;


        foreach (
            (array) $relations
            as $relation
        ) {

            $term_id =
                0;


            $taxonomy =
                '';


            /*
             * Relationship als object.
             */
            if (
                is_object(
                    $relation
                )
            ) {

                $term_id =
                    (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );


                if (
                    ! empty(
                        $relation->taxonomy
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation->taxonomy
                        );
                }


            /*
             * Relationship als array.
             */
            } elseif (
                is_array(
                    $relation
                )
            ) {

                $term_id =
                    (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );


                if (
                    ! empty(
                        $relation['taxonomy']
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation['taxonomy']
                        );
                }


            /*
             * Alleen een numerieke ID.
             *
             * Zonder taxonomy kunnen we hier niet veilig bepalen
             * bij welke taxonomy het ID hoort.
             */
            } elseif (
                is_numeric(
                    $relation
                )
            ) {

                continue;
            }


            if ( ! $term_id ) {
                continue;
            }


            if (
                ! $taxonomy ||
                ! taxonomy_exists(
                    $taxonomy
                )
            ) {
                continue;
            }


            $candidate =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $candidate instanceof WP_Term &&
                ! is_wp_error(
                    $candidate
                )
            ) {

                $term =
                    $candidate;

                break;
            }
        }


        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        /**
         * ========================================================
         * 6. TERM URL
         * ========================================================
         */

        $url =
            get_term_link(
                $term
            );


        if (
            is_wp_error(
                $url
            )
        ) {
            return '';
        }


        return esc_url(
            $url
        );
    }
);

