/**
 * ============================================================
 * 6. OPEN VACATURE IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_vacancy_ids' ) ) {

    function tfsc_derived_rel_v2_get_vacancy_ids(
        $function_term_ids
    ) {

        if (
            empty( $function_term_ids ) ||
            ! taxonomy_exists( 'functienaam' )
        ) {
            return [];
        }


        $vacancy_post_type =
            tfsc_derived_rel_v2_vacancy_post_type();


        if (
            ! post_type_exists(
                $vacancy_post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],
        ];


        $status_taxonomy =
            tfsc_derived_rel_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_derived_rel_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $vacancy_ids =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $vacancy_ids ) ) {
            return [];
        }


        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $vacancy_ids
                )
            )
        );
    }
}


/**
 * ============================================================
 * 7. TARGET TAXONOMY TERMS UIT VACATURES
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_target_term_ids' ) ) {

    function tfsc_derived_rel_v2_get_target_term_ids(
        $vacancy_ids,
        $taxonomy
    ) {

        if (
            empty( $vacancy_ids ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    $taxonomy,
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                $term_ids[] =
                    $term_id;


                if (
                    is_taxonomy_hierarchical(
                        $taxonomy
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        );


                    if ( ! empty( $ancestors ) ) {

                        $term_ids =
                            array_merge(
                                $term_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_filter_level' ) ) {

    function tfsc_derived_rel_v2_filter_level(
        $term_ids,
        $taxonomy,
        $wanted_level
    ) {

        if (
            empty( $term_ids ) ||
            empty( $taxonomy )
        ) {
            return [];
        }


        /*
         * Niet-hiërarchisch:
         * alles = level 0.
         */
        if (
            ! is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            return (
                0 ===
                (int) $wanted_level
            )
                ?
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
                :
            [];
        }


        $filtered = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $level =
                count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );


            if (
                $level ===
                (int) $wanted_level
            ) {

                $filtered[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $filtered
            )
        );
    }
}


/**
 * ============================================================
 * 9. QUERY ID PARSEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_parse_query_id' ) ) {

    function tfsc_derived_rel_v2_parse_query_id(
        $query_id
    ) {

        $query_id =
            (string) $query_id;


        if (
            ! preg_match(
                '/^relationship_(.+)_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {
            return false;
        }


        $taxonomy =
            sanitize_key(
                $matches[1]
            );


        $level =
            (int) $matches[2];


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        return [
            'taxonomy' =>
                $taxonomy,

            'level' =>
                $level,
        ];
    }
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            (string)
            $settings['term_taxonomy_id'];


        $parsed =
            tfsc_derived_rel_v2_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        $taxonomy =
            $parsed['taxonomy'];


        $wanted_level =
            $parsed['level'];


        /*
         * Status taxonomy nooit.
         */
        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /*
         * Elementor Source.
         */
        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        $elementor_taxonomy =
            sanitize_key(
                $elementor_taxonomy
            );


        if (
            $elementor_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if ( ! $pod ) {
            return $args;
        }


        if (
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $args;
        }


        $function_ids =
            tfsc_derived_rel_v2_get_function_ids(
                $pod
            );


        if ( empty( $function_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $vacancy_ids =
            tfsc_derived_rel_v2_get_vacancy_ids(
                $function_ids
            );


        if ( empty( $vacancy_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $target_term_ids =
            tfsc_derived_rel_v2_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $target_term_ids =
            tfsc_derived_rel_v2_filter_level(
                $target_term_ids,
                $taxonomy,
                $wanted_level
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            $target_term_ids;


        $args['hide_empty'] =
            false;


        $args['hierarchical'] =
            false;


        /*
         * Markering voor sorteerfix.
         */
        $args['tfsc_derived_relationship_query'] =
            1;


        $args['tfsc_derived_relationship_taxonomy'] =
            $taxonomy;


        return $args;

    },
    30,
    3
);


/**
 * ============================================================
 * 11. UITEINDELIJKE SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if ( is_admin() ) {
            return $terms;
        }


        if (
            empty( $terms ) ||
            ! is_array( $terms )
        ) {
            return $terms;
        }


        if (
            empty(
                $args['tfsc_derived_relationship_query']
            )
        ) {
            return $terms;
        }


        $taxonomy =
            isset(
                $args['tfsc_derived_relationship_taxonomy']
            )
                ?
            sanitize_key(
                $args['tfsc_derived_relationship_taxonomy']
            )
                :
            '';


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return $terms;
        }


        foreach (
            $terms
            as $term
        ) {

            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                $taxonomy !==
                $term->taxonomy
            ) {
                return $terms;
            }
        }


        $orderby =
            isset(
                $args['orderby']
            )
                ?
            strtolower(
                (string) $args['orderby']
            )
                :
            'name';


        if (
            'name'
            !==
            $orderby
        ) {
            return $terms;
        }


        $order =
            isset(
                $args['order']
            )
                ?
            strtoupper(
                (string) $args['order']
            )
                :
            'ASC';


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {
            $order =
                'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                $name_a =
                    remove_accents(
                        wp_strip_all_tags(
                            $a->name
                        )
                    );


                $name_b =
                    remove_accents(
                        wp_strip_all_tags(
                            $b->name
                        )
                    );


                $comparison =
                    strnatcasecmp(
                        $name_a,
                        $name_b
                    );


                if (
                    'DESC'
                    ===
                    $order
                ) {

                    $comparison *=
                        -1;
                }


                return $comparison;
            }
        );


        return $terms;

    },
    9999,
    4
);


/**
 * ============================================================
 * 12. HIËRARCHISCH TERMPAD
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_term_path' ) ) {

    function tfsc_derived_rel_v2_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs = [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if ( ! empty( $ancestor_ids ) ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error( $ancestor ) &&
                        ! empty( $ancestor->slug )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 13. COMBO URL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_build_combo_url' ) ) {

    function tfsc_derived_rel_v2_build_combo_url(
        $target_term
    ) {

        if (
            ! (
                $target_term instanceof WP_Term
            )
        ) {
            return false;
        }


        $taxonomy =
            $target_term->taxonomy;


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return false;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return false;
        }


        $function_ids =
            tfsc_derived_rel_v2_get_function_ids(
                $pod
            );


        if ( empty( $function_ids ) ) {
            return false;
        }


        $function_terms = [];


        foreach (
            $function_ids
            as $function_id
        ) {

            $function_term =
                get_term(
                    $function_id,
                    'functienaam'
                );


            if (
                $function_term instanceof WP_Term &&
                ! is_wp_error(
                    $function_term
                )
            ) {

                $function_terms[] =
                    $function_term;
            }
        }


        if ( empty( $function_terms ) ) {
            return false;
        }


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],

            [
                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' => [
                    (int)
                    $target_term->term_id,
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    is_taxonomy_hierarchical(
                        $taxonomy
                    ),
            ],
        ];


        $status_taxonomy =
            tfsc_derived_rel_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_derived_rel_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        tfsc_derived_rel_v2_vacancy_post_type(),

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $has_result ) ) {
            return false;
        }


        $parts = [
            tfsc_derived_rel_v2_combo_base(),
        ];


        foreach (
            $function_terms
            as $function_term
        ) {

            $function_path =
                tfsc_derived_rel_v2_term_path(
                    $function_term
                );


            if (
                '' ===
                $function_path
            ) {
                continue;
            }


            $parts[] =
                'functienaam';

            $parts[] =
                $function_path;
        }


        $target_path =
            tfsc_derived_rel_v2_term_path(
                $target_term
            );


        if (
            '' ===
            $target_path
        ) {
            return false;
        }


        $parts[] =
            $taxonomy;

        $parts[] =
            $target_path;


        return home_url(
            '/'
            .
            implode(
                '/',
                array_map(
                    function( $part ) {

                        return trim(
                            $part,
                            '/'
                        );
                    },
                    $parts
                )
            )
            .
            '/'
        );
    }
}


/**
 * ============================================================
 * 14. TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        /*
         * ========================================================
         * BYPASS VOOR NATIVE TERM LINK
         * ========================================================
         *
         * Sommige TFSC-functionaliteit wil bewust de originele
         * taxonomy URL gebruiken en NIET de combo archive URL.
         *
         * Bijvoorbeeld:
         *
         *     [vacature_button_url]
         *
         * Die shortcode kan tijdelijk deze globale vlag zetten:
         *
         *     $GLOBALS['tfsc_force_native_term_link'] = true;
         *
         * Zolang die vlag actief is, laten we WordPress' originele
         * get_term_link() resultaat volledig ongemoeid.
         */
        if (
            ! empty(
                $GLOBALS['tfsc_force_native_term_link']
            )
        ) {
            return $termlink;
        }


        if ( is_admin() ) {
            return $termlink;
        }


        if (
            ! (
                $term instanceof WP_Term
            ) ||
            empty(
                $taxonomy
            )
        ) {
            return $termlink;
        }


        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $termlink;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_derived_rel_v2_build_combo_url(
                $term
            );


        if ( ! $combo_url ) {
            return $termlink;
        }


        return $combo_url;

    },
    30,
    3
);

/**
 * TFSC - Vacature Button URL
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Deze shortcode geeft de URL terug van de taxonomy-term
 * die gekoppeld is via het vaste Pods relationship field:
 *
 *     relationship_vacature_button_url
 *
 *
 * ============================================================
 * SHORTCODE
 * ============================================================
 *
 * Gebruik:
 *
 *     [vacature_button_url]
 *
 *
 * ============================================================
 * WERKING
 * ============================================================
 *
 * De shortcode werkt zowel op:
 *
 * - singular posts / CPT's;
 * - taxonomy archives;
 * - Elementor Theme Builder previews.
 *
 *
 * Hij kijkt uitsluitend naar:
 *
 *     relationship_vacature_button_url
 *
 * Dat relationship field bepaalt dus volledig waar de
 * vacaturebutton naartoe linkt.
 *
 *
 * Voorbeeld:
 *
 * relationship_vacature_button_url
 *     → functie-inhoud
 *     → Inbedrijfstellen
 *
 * Dan geeft de shortcode de normale taxonomy URL van
 * "Inbedrijfstellen" terug.
 *
 *
 * ============================================================
 * GEEN COMBO URL
 * ============================================================
 *
 * Normaal worden sommige term-links door:
 *
 *     TFSC - Generic Derived Relationship Taxonomy Terms
 *
 * automatisch omgezet naar een combo URL.
 *
 * Bijvoorbeeld:
 *
 *     /vacatures/
 *     functienaam/field-service-engineer/
 *     functie-inhoud/inbedrijfstellen/
 *
 * Voor deze shortcode willen we dat NIET.
 *
 * Daarom wordt tijdens get_term_link() tijdelijk deze vlag gezet:
 *
 *     tfsc_force_native_term_link
 *
 * De term_link filter laat de URL dan ongemoeid.
 *
 * Daardoor krijgt deze shortcode bijvoorbeeld:
 *
 *     /functie-inhoud/inbedrijfstellen/
 *
 * of de native URL-structuur die WordPress voor die taxonomy
 * gebruikt.
 *
 *
 * ============================================================
 * ELEMENTOR PREVIEW
 * ============================================================
 *
 * Als deze helper beschikbaar is:
 *
 *     tfsc_derived_rel_v2_get_context_post_id()
 *
 * gebruikt de shortcode in Elementor Theme Builder automatisch
 * de ingestelde Preview Dynamic Content post.
 *
 *
 * ============================================================
 * PODS
 * ============================================================
 *
 * Het field:
 *
 *     relationship_vacature_button_url
 *
 * is bij voorkeur een single-select relationship naar een
 * taxonomy-term.
 *
 * Als er toch meerdere relaties aanwezig zijn, wordt de eerste
 * geldige taxonomy-term gebruikt.
 */


add_shortcode(
    'vacature_button_url',
    function() {

        if ( ! function_exists( 'pods' ) ) {
            return '';
        }


        $field_name =
            'relationship_vacature_button_url';


        $pod =
            false;


        $object =
            get_queried_object();


        /**
         * ========================================================
         * 1. TAXONOMY ARCHIVE
         * ========================================================
         */

        if (
            $object instanceof WP_Term &&
            ! empty( $object->term_id ) &&
            ! empty( $object->taxonomy )
        ) {

            $pod =
                pods(
                    $object->taxonomy,
                    (int) $object->term_id
                );
        }


        /**
         * ========================================================
         * 2. POST / CPT
         * ========================================================
         */

        if ( ! $pod ) {

            $post_id =
                0;


            /*
             * Elementor-aware context helper gebruiken
             * wanneer beschikbaar.
             */
            if (
                function_exists(
                    'tfsc_derived_rel_v2_get_context_post_id'
                )
            ) {

                $post_id =
                    tfsc_derived_rel_v2_get_context_post_id();

            } elseif (
                $object instanceof WP_Post
            ) {

                $post_id =
                    (int) $object->ID;

            } else {

                $post_id =
                    get_queried_object_id();
            }


            if ( $post_id ) {

                $post_type =
                    get_post_type(
                        $post_id
                    );


                if ( $post_type ) {

                    $pod =
                        pods(
                            $post_type,
                            $post_id
                        );
                }
            }
        }


        /**
         * ========================================================
         * 3. POD CONTROLEREN
         * ========================================================
         */

        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return '';
        }


        /**
         * ========================================================
         * 4. RELATIONSHIP UITLEZEN
         * ========================================================
         */

        $relations =
            $pod->field(
                $field_name
            );


        if ( empty( $relations ) ) {
            return '';
        }


        /*
         * Eén numerieke relationship value.
         */
        if (
            is_numeric(
                $relations
            )
        ) {

            $relations = [
                $relations
            ];
        }


        /*
         * Eén associatieve relationship array.
         */
        if (
            is_array( $relations ) &&
            (
                isset( $relations['term_id'] ) ||
                isset( $relations['id'] ) ||
                isset( $relations['ID'] )
            )
        ) {

            $relations = [
                $relations
            ];
        }


        /**
         * ========================================================
         * 5. EERSTE GELDIGE TAXONOMY TERM VINDEN
         * ========================================================
         */

        $term =
            false;


        foreach (
            (array) $relations
            as $relation
        ) {

            $term_id =
                0;


            $taxonomy =
                '';


            /*
             * Pods relationship als object.
             */
            if (
                is_object(
                    $relation
                )
            ) {

                $term_id =
                    (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );


                if (
                    ! empty(
                        $relation->taxonomy
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation->taxonomy
                        );
                }


            /*
             * Pods relationship als array.
             */
            } elseif (
                is_array(
                    $relation
                )
            ) {

                $term_id =
                    (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );


                if (
                    ! empty(
                        $relation['taxonomy']
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation['taxonomy']
                        );
                }
            }


            /*
             * We hebben zowel term-ID als taxonomy nodig.
             */
            if (
                ! $term_id ||
                ! $taxonomy ||
                ! taxonomy_exists(
                    $taxonomy
                )
            ) {
                continue;
            }


            $candidate =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $candidate instanceof WP_Term &&
                ! is_wp_error(
                    $candidate
                )
            ) {

                $term =
                    $candidate;

                break;
            }
        }


        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        /**
         * ========================================================
         * 6. NATIVE TERM URL
         * ========================================================
         *
         * Tijdelijk de TFSC combo term_link conversie
         * uitschakelen.
         */

        $GLOBALS[
            'tfsc_force_native_term_link'
        ] = true;


        $url =
            get_term_link(
                $term
            );


        /*
         * Bypass onmiddellijk weer uitschakelen.
         */
        unset(
            $GLOBALS[
                'tfsc_force_native_term_link'
            ]
        );


        /**
         * ========================================================
         * 7. URL TERUGGEVEN
         * ========================================================
         */

        if (
            is_wp_error(
                $url
            )
        ) {
            return '';
        }


        return esc_url(
            $url
        );
    }
);

/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Deze snippet is de taxonomy-archive variant van:
 *
 *     CPT → Relationship Taxonomies Pods  → link to Combo Archives
 *
 * De bestaande CPT-versie blijft volledig ongemoeid.
 *
 *
 * ============================================================
 * BRONCONTEXT
 * ============================================================
 *
 * Op een taxonomy archive gebruikt deze snippet de huidige
 * taxonomy-term als bron.
 *
 * Voorbeeld:
 *
 *     huidige taxonomy:
 *         functie-inhoud
 *
 *     huidige term:
 *         Inbedrijfstellen
 *
 * Dan zoekt de snippet automatisch op die term naar het
 * Pods relationship field:
 *
 *     relationship_functie-inhoud
 *
 *
 * ============================================================
 * SOURCE RELATIONSHIP
 * ============================================================
 *
 * Het field:
 *
 *     relationship_{huidige-taxonomy}
 *
 * bepaalt welke vacature-taxonomy term(s) als basis voor
 * de vacaturequery worden gebruikt.
 *
 * Voorbeeld:
 *
 *     archive taxonomy:
 *         functie-inhoud
 *
 *     field:
 *         relationship_functie-inhoud
 *
 *     gekoppeld aan:
 *         vacature taxonomy functie-inhoud
 *         term Inbedrijfstellen
 *
 *
 * ============================================================
 * ELEMENTOR QUERY ID
 * ============================================================
 *
 * Gebruik:
 *
 *     archive_relationship_{doel-taxonomy}_level_{nummer}
 *
 * Voorbeelden:
 *
 *     archive_relationship_locatie_level_0
 *     archive_relationship_locatie_level_1
 *     archive_relationship_locatie_level_2
 *
 *     archive_relationship_bedrijfssector_level_0
 *
 *     archive_relationship_kennisgebied_level_0
 *
 *     archive_relationship_functie-inhoud_level_0
 *
 *
 * ============================================================
 * ELEMENTOR
 * ============================================================
 *
 * Elementor Source moet overeenkomen met de doel-taxonomy
 * uit de Query ID.
 *
 * Voorbeeld:
 *
 *     Source:
 *         locatie
 *
 *     Query ID:
 *         archive_relationship_locatie_level_2
 *
 *
 * Elementor:
 *
 *     Filter by Depth = UIT
 *
 * Order By en Order blijven door Elementor bepaald.
 *
 *
 * ============================================================
 * OPEN VACATURES
 * ============================================================
 *
 * Alleen gepubliceerde vacatures worden gebruikt.
 *
 * Wanneer de status taxonomy bestaat:
 *
 *     vac_status
 *
 * worden alleen vacatures meegenomen met:
 *
 *     open
 *
 *
 * ============================================================
 * TERM LINKS
 * ============================================================
 *
 * De termen uit deze derived taxonomy loops krijgen automatisch
 * een TFSC combo archive URL.
 *
 * Voorbeeld:
 *
 * bron:
 *
 *     functie-inhoud → inbedrijfstellen
 *
 * doel:
 *
 *     locatie → noord-brabant
 *
 * resultaat:
 *
 *     /vacatures/
 *     functie-inhoud/inbedrijfstellen/
 *     locatie/noord-brabant/
 *
 *
 * ============================================================
 * SORTERING
 * ============================================================
 *
 * Net als bij de CPT-versie wordt de uiteindelijke get_terms()
 * array opnieuw op naam gesorteerd.
 *
 * Dit voorkomt dat WordPress hiërarchische terms alsnog
 * per parent groepeert.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

if ( ! function_exists( 'tfsc_taxrel_v1_vacancy_post_type' ) ) {

    function tfsc_taxrel_v1_vacancy_post_type() {

        return defined( 'TFSC_VACANCY_POST_TYPE' )
            ? TFSC_VACANCY_POST_TYPE
            : 'vacature';
    }
}


if ( ! function_exists( 'tfsc_taxrel_v1_status_taxonomy' ) ) {

    function tfsc_taxrel_v1_status_taxonomy() {

        return defined( 'TFSC_STATUS_TAXONOMY' )
            ? TFSC_STATUS_TAXONOMY
            : 'vac_status';
    }
}


if ( ! function_exists( 'tfsc_taxrel_v1_open_status' ) ) {

    function tfsc_taxrel_v1_open_status() {

        return defined( 'TFSC_OPEN_STATUS_SLUG' )
            ? TFSC_OPEN_STATUS_SLUG
            : 'open';
    }
}


if ( ! function_exists( 'tfsc_taxrel_v1_combo_base' ) ) {

    function tfsc_taxrel_v1_combo_base() {

        return defined( 'TFSC_COMBO_BASE' )
            ? TFSC_COMBO_BASE
            : 'vacatures';
    }
}


/**
 * ============================================================
 * 2. HUIDIGE TAXONOMY TERM
 * ============================================================
 */

if ( ! function_exists( 'tfsc_taxrel_v1_get_current_term' ) ) {

    function tfsc_taxrel_v1_get_current_term() {

        $object =
            get_queried_object();


        if (
            ! (
                $object instanceof WP_Term
            )
        ) {
            return false;
        }


        if (
            empty( $object->term_id ) ||
            empty( $object->taxonomy ) ||
            ! taxonomy_exists(
                $object->taxonomy
            )
        ) {
            return false;
        }


        return $object;
    }
}


/**
 * ============================================================
 * 3. PODS OBJECT VAN HUIDIGE TAXONOMY TERM
 * ============================================================
 */

if ( ! function_exists( 'tfsc_taxrel_v1_get_current_pod' ) ) {

    function tfsc_taxrel_v1_get_current_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }


        $term =
            tfsc_taxrel_v1_get_current_term();


        if ( ! $term ) {
            return false;
        }


        $pod =
            pods(
                $term->taxonomy,
                (int) $term->term_id
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return false;
        }


        return $pod;
    }
}


/**
 * ============================================================
 * 4. SOURCE RELATIONSHIP FIELD
 * ============================================================
 *
 * Automatisch:
 *
 *     relationship_{huidige-taxonomy}
 */

if ( ! function_exists( 'tfsc_taxrel_v1_source_field_name' ) ) {

    function tfsc_taxrel_v1_source_field_name() {

        $term =
            tfsc_taxrel_v1_get_current_term();


        if ( ! $term ) {
            return '';
        }


        return
            'relationship_'
            .
            $term->taxonomy;
    }
}


/**
 * ============================================================
 * 5. SOURCE RELATIONSHIPS UITLEZEN
 * ============================================================
 *
 * Resultaat:
 *
 * [
 *     'functie-inhoud' => [ 12, 15 ],
 *     'locatie'        => [ 44 ],
 * ]
 *
 * Meestal bevat een field slechts één taxonomy.
 */

if ( ! function_exists( 'tfsc_taxrel_v1_get_source_relationships' ) ) {

    function tfsc_taxrel_v1_get_source_relationships() {

        $pod =
            tfsc_taxrel_v1_get_current_pod();


        $current_term =
            tfsc_taxrel_v1_get_current_term();


        if (
            ! $pod ||
            ! $current_term
        ) {
            return [];
        }


        $field_name =
            tfsc_taxrel_v1_source_field_name();


        if ( ! $field_name ) {
            return [];
        }


        /*
         * Controleren of field daadwerkelijk bestaat.
         */
        $fields =
            $pod->fields();


        if (
            ! is_array( $fields ) ||
            ! array_key_exists(
                $field_name,
                $fields
            )
        ) {
            return [];
        }


        $relations =
            $pod->field(
                $field_name
            );


        if ( empty( $relations ) ) {
            return [];
        }


        /*
         * Eén item normaliseren naar array.
         */
        if ( is_numeric( $relations ) ) {

            $relations = [
                $relations
            ];
        }


        if (
            is_array( $relations ) &&
            (
                isset( $relations['term_id'] ) ||
                isset( $relations['id'] ) ||
                isset( $relations['ID'] )
            )
        ) {

            $relations = [
                $relations
            ];
        }


        $groups = [];


        foreach (
            (array) $relations
            as $relation
        ) {

            $term_id =
                0;


            $taxonomy =
                '';


            /*
             * Object return.
             */
            if ( is_object( $relation ) ) {

                $term_id =
                    (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );


                if (
                    ! empty(
                        $relation->taxonomy
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation->taxonomy
                        );
                }


            /*
             * Array return.
             */
            } elseif ( is_array( $relation ) ) {

                $term_id =
                    (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );


                if (
                    ! empty(
                        $relation['taxonomy']
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation['taxonomy']
                        );
                }


            /*
             * Alleen ID.
             *
             * Als Pods geen taxonomy meestuurt,
             * gebruiken we de huidige taxonomy als fallback.
             */
            } elseif ( is_numeric( $relation ) ) {

                $term_id =
                    (int) $relation;


                $taxonomy =
                    $current_term->taxonomy;
            }


            if ( ! $term_id ) {
                continue;
            }


            /*
             * Extra fallback:
             *
             * relatie bevat wel ID maar geen taxonomy.
             */
            if ( ! $taxonomy ) {

                $taxonomy =
                    $current_term->taxonomy;
            }


            if (
                ! taxonomy_exists(
                    $taxonomy
                )
            ) {
                continue;
            }


            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                is_wp_error(
                    $term
                )
            ) {
                continue;
            }


            if (
                ! isset(
                    $groups[ $taxonomy ]
                )
            ) {

                $groups[ $taxonomy ] =
                    [];
            }


            $groups[ $taxonomy ][] =
                (int) $term_id;
        }


        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $groups[ $taxonomy ] =
                array_values(
                    array_unique(
                        array_map(
                            'intval',
                            $ids
                        )
                    )
                );
        }


        return array_filter(
            $groups
        );
    }
}


/**
 * ============================================================
 * 6. OPEN VACATURES OP BASIS VAN SOURCE RELATIONSHIP
 * ============================================================
 */

if ( ! function_exists( 'tfsc_taxrel_v1_get_vacancy_ids' ) ) {

    function tfsc_taxrel_v1_get_vacancy_ids(
        $source_groups
    ) {

        if ( empty( $source_groups ) ) {
            return [];
        }


        $post_type =
            tfsc_taxrel_v1_vacancy_post_type();


        if (
            ! post_type_exists(
                $post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' =>
                'AND',
        ];


        foreach (
            $source_groups
            as $taxonomy => $term_ids
        ) {

            if (
                ! taxonomy_exists(
                    $taxonomy
                ) ||
                empty(
                    $term_ids
                )
            ) {
                continue;
            }


            $tax_query[] = [

                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    array_map(
                        'intval',
                        $term_ids
                    ),

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        /*
         * Geen geldige source clauses.
         */
        if (
            count( $tax_query )
            <=
            1
        ) {
            return [];
        }


        $status_taxonomy =
            tfsc_taxrel_v1_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_taxrel_v1_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $ids =
            get_posts(
                [
                    'post_type' =>
                        $post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $ids ) ) {
            return [];
        }


        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );
    }
}


/**
 * ============================================================
 * 7. TARGET TERMS UIT VACATURES
 * ============================================================
 */

if ( ! function_exists( 'tfsc_taxrel_v1_get_target_term_ids' ) ) {

    function tfsc_taxrel_v1_get_target_term_ids(
        $vacancy_ids,
        $taxonomy
    ) {

        if (
            empty( $vacancy_ids ) ||
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return [];
        }


        $term_ids =
            [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    $taxonomy,
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                $term_ids[] =
                    $term_id;


                /*
                 * Ancestors meenemen.
                 */
                if (
                    is_taxonomy_hierarchical(
                        $taxonomy
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        );


                    if (
                        ! empty(
                            $ancestors
                        )
                    ) {

                        $term_ids =
                            array_merge(
                                $term_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_taxrel_v1_filter_level' ) ) {

    function tfsc_taxrel_v1_filter_level(
        $term_ids,
        $taxonomy,
        $wanted_level
    ) {

        if (
            empty( $term_ids ) ||
            ! $taxonomy
        ) {
            return [];
        }


        /*
         * Niet-hiërarchisch = level 0.
         */
        if (
            ! is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            return (
                0 ===
                (int) $wanted_level
            )
                ?
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
                :
            [];
        }


        $filtered =
            [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $level =
                count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );


            if (
                $level ===
                (int) $wanted_level
            ) {

                $filtered[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $filtered
            )
        );
    }
}


/**
 * ============================================================
 * 9. QUERY ID PARSEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_taxrel_v1_parse_query_id' ) ) {

    function tfsc_taxrel_v1_parse_query_id(
        $query_id
    ) {

        $query_id =
            (string) $query_id;


        if (
            ! preg_match(
                '/^archive_relationship_(.+)_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {
            return false;
        }


        $taxonomy =
            sanitize_key(
                $matches[1]
            );


        $level =
            (int) $matches[2];


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        return [
            'taxonomy' =>
                $taxonomy,

            'level' =>
                $level,
        ];
    }
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP QUERY
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            (string)
            $settings['term_taxonomy_id'];


        $parsed =
            tfsc_taxrel_v1_parse_query_id(
                $query_id
            );


        /*
         * Geen archive_relationship query:
         * deze snippet doet niets.
         */
        if ( ! $parsed ) {
            return $args;
        }


        /*
         * Alleen taxonomy archive context.
         */
        $current_term =
            tfsc_taxrel_v1_get_current_term();


        if ( ! $current_term ) {
            return $args;
        }


        $taxonomy =
            $parsed['taxonomy'];


        $wanted_level =
            $parsed['level'];


        /*
         * Status taxonomy nooit als target.
         */
        if (
            tfsc_taxrel_v1_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /*
         * Elementor Source.
         */
        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        $elementor_taxonomy =
            sanitize_key(
                $elementor_taxonomy
            );


        /*
         * Source moet overeenkomen met target taxonomy.
         */
        if (
            $elementor_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        /*
         * Source relationships van huidige archive term.
         */
        $source_groups =
            tfsc_taxrel_v1_get_source_relationships();


        if ( empty( $source_groups ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Open vacatures.
         */
        $vacancy_ids =
            tfsc_taxrel_v1_get_vacancy_ids(
                $source_groups
            );


        if ( empty( $vacancy_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Target terms.
         */
        $target_term_ids =
            tfsc_taxrel_v1_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Exact hierarchy level.
         */
        $target_term_ids =
            tfsc_taxrel_v1_filter_level(
                $target_term_ids,
                $taxonomy,
                $wanted_level
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /*
         * Custom Elementor Query ID verwijderen.
         */
        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            $target_term_ids;


        $args['hide_empty'] =
            false;


        /*
         * Exact level is al bepaald.
         */
        $args['hierarchical'] =
            false;


        /*
         * Marker voor uiteindelijke sortering.
         */
        $args['tfsc_taxrel_v1_query'] =
            1;


        $args['tfsc_taxrel_v1_taxonomy'] =
            $taxonomy;


        /*
         * Alleen target taxonomies die daadwerkelijk door
         * deze query gebruikt worden mogen straks door onze
         * term_link filter naar combo URLs worden omgezet.
         */
        if (
            ! isset(
                $GLOBALS[
                    'tfsc_taxrel_v1_active_targets'
                ]
            ) ||
            ! is_array(
                $GLOBALS[
                    'tfsc_taxrel_v1_active_targets'
                ]
            )
        ) {

            $GLOBALS[
                'tfsc_taxrel_v1_active_targets'
            ] = [];
        }


        $GLOBALS[
            'tfsc_taxrel_v1_active_targets'
        ][ $taxonomy ] =
            true;


        return $args;

    },
    40,
    3
);


/**
 * ============================================================
 * 11. UITEINDELIJKE SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if ( is_admin() ) {
            return $terms;
        }


        if (
            empty( $terms ) ||
            ! is_array( $terms )
        ) {
            return $terms;
        }


        if (
            empty(
                $args['tfsc_taxrel_v1_query']
            )
        ) {
            return $terms;
        }


        $taxonomy =
            isset(
                $args['tfsc_taxrel_v1_taxonomy']
            )
                ?
            sanitize_key(
                $args['tfsc_taxrel_v1_taxonomy']
            )
                :
            '';


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return $terms;
        }


        foreach (
            $terms
            as $term
        ) {

            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                $term->taxonomy
                !==
                $taxonomy
            ) {
                return $terms;
            }
        }


        $orderby =
            isset(
                $args['orderby']
            )
                ?
            strtolower(
                (string)
                $args['orderby']
            )
                :
            'name';


        /*
         * Alleen Name corrigeren.
         */
        if (
            'name'
            !==
            $orderby
        ) {
            return $terms;
        }


        $order =
            isset(
                $args['order']
            )
                ?
            strtoupper(
                (string)
                $args['order']
            )
                :
            'ASC';


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {

            $order =
                'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                $name_a =
                    remove_accents(
                        wp_strip_all_tags(
                            $a->name
                        )
                    );


                $name_b =
                    remove_accents(
                        wp_strip_all_tags(
                            $b->name
                        )
                    );


                $comparison =
                    strnatcasecmp(
                        $name_a,
                        $name_b
                    );


                if (
                    'DESC'
                    ===
                    $order
                ) {

                    $comparison *=
                        -1;
                }


                return $comparison;
            }
        );


        return $terms;

    },
    9999,
    4
);


/**
 * ============================================================
 * 12. TERMPAD
 * ============================================================
 */

if ( ! function_exists( 'tfsc_taxrel_v1_term_path' ) ) {

    function tfsc_taxrel_v1_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        $slugs =
            [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if (
                ! empty(
                    $ancestor_ids
                )
            ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error( $ancestor ) &&
                        ! empty( $ancestor->slug )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 13. COMBO URL BOUWEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_taxrel_v1_build_combo_url' ) ) {

    function tfsc_taxrel_v1_build_combo_url(
        $target_term
    ) {

        if (
            ! (
                $target_term instanceof WP_Term
            )
        ) {
            return false;
        }


        $source_groups =
            tfsc_taxrel_v1_get_source_relationships();


        if ( empty( $source_groups ) ) {
            return false;
        }


        /*
         * Eerst controleren of combinatie minimaal één
         * open vacature oplevert.
         */
        $tax_query = [
            'relation' =>
                'AND',
        ];


        foreach (
            $source_groups
            as $taxonomy => $term_ids
        ) {

            if (
                ! taxonomy_exists(
                    $taxonomy
                ) ||
                empty( $term_ids )
            ) {
                continue;
            }


            $tax_query[] = [

                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    $term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $tax_query[] = [

            'taxonomy' =>
                $target_term->taxonomy,

            'field' =>
                'term_id',

            'terms' => [
                (int)
                $target_term->term_id,
            ],

            'operator' =>
                'IN',

            'include_children' =>
                is_taxonomy_hierarchical(
                    $target_term->taxonomy
                ),
        ];


        $status_taxonomy =
            tfsc_taxrel_v1_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_taxrel_v1_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        tfsc_taxrel_v1_vacancy_post_type(),

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $has_result ) ) {
            return false;
        }


        /**
         * ========================================================
         * URL ONDERDELEN
         * ========================================================
         */

        $parts = [
            tfsc_taxrel_v1_combo_base(),
        ];


        /*
         * Source relationship terms.
         */
        foreach (
            $source_groups
            as $taxonomy => $term_ids
        ) {

            foreach (
                $term_ids
                as $term_id
            ) {

                /*
                 * Exact dezelfde target term niet dubbel
                 * aan URL toevoegen.
                 */
                if (
                    $taxonomy
                    ===
                    $target_term->taxonomy
                    &&
                    (int) $term_id
                    ===
                    (int) $target_term->term_id
                ) {
                    continue;
                }


                $source_term =
                    get_term(
                        $term_id,
                        $taxonomy
                    );


                if (
                    ! (
                        $source_term instanceof WP_Term
                    ) ||
                    is_wp_error(
                        $source_term
                    )
                ) {
                    continue;
                }


                $path =
                    tfsc_taxrel_v1_term_path(
                        $source_term
                    );


                if ( ! $path ) {
                    continue;
                }


                $parts[] =
                    $taxonomy;


                $parts[] =
                    $path;
            }
        }


        /*
         * Target.
         */
        $target_path =
            tfsc_taxrel_v1_term_path(
                $target_term
            );


        if ( ! $target_path ) {
            return false;
        }


        $parts[] =
            $target_term->taxonomy;


        $parts[] =
            $target_path;


        return home_url(
            '/'
            .
            implode(
                '/',
                array_map(
                    function( $part ) {

                        return trim(
                            $part,
                            '/'
                        );
                    },
                    $parts
                )
            )
            .
            '/'
        );
    }
}


/**
 * ============================================================
 * 14. TERM LINKS VAN DEZE DERIVED LOOPS
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        /*
         * Native term-link bypass respecteren.
         *
         * Dit wordt o.a. gebruikt door:
         *
         *     [vacature_button_url]
         */
        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            )
        ) {
            return $termlink;
        }


        if ( is_admin() ) {
            return $termlink;
        }


        if (
            ! (
                $term instanceof WP_Term
            ) ||
            ! $taxonomy
        ) {
            return $termlink;
        }


        /*
         * Alleen taxonomy archive context.
         */
        if (
            ! tfsc_taxrel_v1_get_current_term()
        ) {
            return $termlink;
        }


        /*
         * Alleen taxonomies die daadwerkelijk door een
         * archive_relationship query op deze pagina zijn
         * geactiveerd.
         */
        $active_targets =
            isset(
                $GLOBALS[
                    'tfsc_taxrel_v1_active_targets'
                ]
            ) &&
            is_array(
                $GLOBALS[
                    'tfsc_taxrel_v1_active_targets'
                ]
            )
                ?
            $GLOBALS[
                'tfsc_taxrel_v1_active_targets'
            ]
                :
            [];


        if (
            empty(
                $active_targets[
                    $taxonomy
                ]
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_taxrel_v1_build_combo_url(
                $term
            );


        if ( ! $combo_url ) {
            return $termlink;
        }


        return $combo_url;

    },
    40,
    3
);

