/**
 * ============================================================
 * 2. HUIDIGE CONTENT POST + POD
 * ============================================================
 *
 * Frontend:
 *     gebruikt de normale queried post.
 *
 * Elementor Theme Builder editor:
 *     queried object = elementor_library template.
 *
 *     In dat geval lezen we uit de Elementor template:
 *
 *         preview_type
 *         preview_id
 *
 *     Bijvoorbeeld:
 *
 *         preview_type = single/beroep
 *         preview_id   = 23402
 *
 *     Vervolgens gebruiken we beroep 23402 als echte
 *     content-context voor Pods en de relationship queries.
 */


/**
 * Echte content post-ID bepalen.
 */
if ( ! function_exists( 'tfsc_derived_rel_v2_get_context_post_id' ) ) {

    function tfsc_derived_rel_v2_get_context_post_id() {

        $object =
            get_queried_object();


        /**
         * ========================================================
         * 1. NORMALE FRONTEND
         * ========================================================
         */

        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID ) &&
            'elementor_library'
            !==
            get_post_type( $object->ID )
        ) {

            return (int) $object->ID;
        }


        /**
         * ========================================================
         * 2. ELEMENTOR THEME BUILDER TEMPLATE
         * ========================================================
         */

        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID ) &&
            'elementor_library'
            ===
            get_post_type( $object->ID )
        ) {

            $template_id =
                (int) $object->ID;


            /*
             * Eerst via Elementor document API.
             */
            if (
                did_action( 'elementor/loaded' ) &&
                class_exists( '\Elementor\Plugin' )
            ) {

                try {

                    $documents =
                        \Elementor\Plugin::$instance
                            ->documents;


                    if ( $documents ) {

                        $document =
                            $documents->get(
                                $template_id
                            );


                        if (
                            $document &&
                            method_exists(
                                $document,
                                'get_settings'
                            )
                        ) {

                            $preview_id =
                                absint(
                                    $document->get_settings(
                                        'preview_id'
                                    )
                                );


                            if (
                                $preview_id &&
                                'elementor_library'
                                !==
                                get_post_type(
                                    $preview_id
                                )
                            ) {

                                return $preview_id;
                            }
                        }
                    }

                } catch ( Throwable $e ) {

                    /*
                     * Niets doen.
                     *
                     * Hieronder volgt nog een directe
                     * post-meta fallback.
                     */
                }
            }


            /**
             * ====================================================
             * FALLBACK: _elementor_page_settings
             * ====================================================
             *
             * Uit jouw debug weten we dat preview_id hier
             * eveneens wordt opgeslagen.
             */

            $page_settings =
                get_post_meta(
                    $template_id,
                    '_elementor_page_settings',
                    true
                );


            if (
                is_array(
                    $page_settings
                ) &&
                ! empty(
                    $page_settings['preview_id']
                )
            ) {

                $preview_id =
                    absint(
                        $page_settings['preview_id']
                    );


                if (
                    $preview_id &&
                    'elementor_library'
                    !==
                    get_post_type(
                        $preview_id
                    )
                ) {

                    return $preview_id;
                }
            }
        }


        /**
         * ========================================================
         * 3. WORDPRESS PREVIEW FALLBACK
         * ========================================================
         */

        if (
            isset(
                $_GET['preview_id']
            )
        ) {

            $preview_id =
                absint(
                    wp_unslash(
                        $_GET['preview_id']
                    )
                );


            if (
                $preview_id &&
                'elementor_library'
                !==
                get_post_type(
                    $preview_id
                )
            ) {

                return $preview_id;
            }
        }


        /**
         * ========================================================
         * 4. GLOBAL $post FALLBACK
         * ========================================================
         */

        global $post;


        if (
            $post instanceof WP_Post &&
            ! empty( $post->ID ) &&
            'elementor_library'
            !==
            get_post_type( $post->ID )
        ) {

            return (int) $post->ID;
        }


        return 0;
    }
}


/**
 * Pods-object van de echte content-context ophalen.
 */
if ( ! function_exists( 'tfsc_derived_rel_v2_get_current_pod' ) ) {

    function tfsc_derived_rel_v2_get_current_pod() {

        if ( ! function_exists( 'pods' ) ) {
            return false;
        }


        $post_id =
            tfsc_derived_rel_v2_get_context_post_id();


        if ( ! $post_id ) {
            return false;
        }


        $post_type =
            get_post_type(
                $post_id
            );


        if ( ! $post_type ) {
            return false;
        }


        $pod =
            pods(
                $post_type,
                $post_id
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return false;
        }


        return $pod;
    }
}

/**
 * ============================================================
 * 3. RELATIONSHIP TERM IDS UITLEZEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_relationship_term_ids' ) ) {

    function tfsc_derived_rel_v2_get_relationship_term_ids(
        $pod,
        $field_name,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $field_name ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        /*
         * Pods traversal.
         */
        $traversed_ids =
            $pod->field(
                $field_name . '.term_id'
            );


        if ( ! empty( $traversed_ids ) ) {

            foreach (
                (array) $traversed_ids
                as $term_id
            ) {

                if ( is_numeric( $term_id ) ) {

                    $term_ids[] =
                        (int) $term_id;
                }
            }
        }


        /*
         * Fallback normale relationship return.
         */
        if ( empty( $term_ids ) ) {

            $relations =
                $pod->field(
                    $field_name
                );


            if ( empty( $relations ) ) {
                return [];
            }


            if (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            ) {

                $relations = [
                    $relations
                ];
            }


            if ( is_numeric( $relations ) ) {

                $relations = [
                    $relations
                ];
            }


            foreach (
                (array) $relations
                as $relation
            ) {

                $term_id = 0;


                if ( is_numeric( $relation ) ) {

                    $term_id =
                        (int) $relation;

                } elseif ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['id']
                        ?? $relation['ID']
                        ?? 0
                    );

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->id
                        ?? $relation->ID
                        ?? 0
                    );
                }


                if ( $term_id ) {

                    $term_ids[] =
                        $term_id;
                }
            }
        }


        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        $valid_ids = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $valid_ids[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $valid_ids
            )
        );
    }
}


/**
 * ============================================================
 * 4. RELATIONSHIP FIELD BESTAAT?
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_has_relationship_field' ) ) {

    function tfsc_derived_rel_v2_has_relationship_field(
        $pod,
        $taxonomy
    ) {

        if (
            ! $pod ||
            empty( $taxonomy )
        ) {
            return false;
        }


        $fields =
            $pod->fields();


        if ( ! is_array( $fields ) ) {
            return false;
        }


        $field_name =
            'relationship_' . $taxonomy;


        return array_key_exists(
            $field_name,
            $fields
        );
    }
}


/**
 * ============================================================
 * 5. FUNCTIENAAM IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_function_ids' ) ) {

    function tfsc_derived_rel_v2_get_function_ids(
        $pod
    ) {

        return
            tfsc_derived_rel_v2_get_relationship_term_ids(
                $pod,
                'relationship_functienaam',
                'functienaam'
            );
    }
}


/**
 * ============================================================
 * 6. OPEN VACATURE IDS
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_vacancy_ids' ) ) {

    function tfsc_derived_rel_v2_get_vacancy_ids(
        $function_term_ids
    ) {

        if (
            empty( $function_term_ids ) ||
            ! taxonomy_exists( 'functienaam' )
        ) {
            return [];
        }


        $vacancy_post_type =
            tfsc_derived_rel_v2_vacancy_post_type();


        if (
            ! post_type_exists(
                $vacancy_post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],
        ];


        $status_taxonomy =
            tfsc_derived_rel_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_derived_rel_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $vacancy_ids =
            get_posts(
                [
                    'post_type' =>
                        $vacancy_post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $vacancy_ids ) ) {
            return [];
        }


        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $vacancy_ids
                )
            )
        );
    }
}


/**
 * ============================================================
 * 7. TARGET TAXONOMY TERMS UIT VACATURES
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_get_target_term_ids' ) ) {

    function tfsc_derived_rel_v2_get_target_term_ids(
        $vacancy_ids,
        $taxonomy
    ) {

        if (
            empty( $vacancy_ids ) ||
            empty( $taxonomy ) ||
            ! taxonomy_exists( $taxonomy )
        ) {
            return [];
        }


        $term_ids = [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    $taxonomy,
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error( $terms ) ||
                empty( $terms )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                $term_ids[] =
                    $term_id;


                if (
                    is_taxonomy_hierarchical(
                        $taxonomy
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        );


                    if ( ! empty( $ancestors ) ) {

                        $term_ids =
                            array_merge(
                                $term_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );
    }
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_filter_level' ) ) {

    function tfsc_derived_rel_v2_filter_level(
        $term_ids,
        $taxonomy,
        $wanted_level
    ) {

        if (
            empty( $term_ids ) ||
            empty( $taxonomy )
        ) {
            return [];
        }


        /*
         * Niet-hiërarchisch:
         * alles = level 0.
         */
        if (
            ! is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            return (
                0 ===
                (int) $wanted_level
            )
                ?
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
                :
            [];
        }


        $filtered = [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $level =
                count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );


            if (
                $level ===
                (int) $wanted_level
            ) {

                $filtered[] =
                    $term_id;
            }
        }


        return array_values(
            array_unique(
                $filtered
            )
        );
    }
}


/**
 * ============================================================
 * 9. QUERY ID PARSEN
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_parse_query_id' ) ) {

    function tfsc_derived_rel_v2_parse_query_id(
        $query_id
    ) {

        $query_id =
            (string) $query_id;


        if (
            ! preg_match(
                '/^relationship_(.+)_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {
            return false;
        }


        $taxonomy =
            sanitize_key(
                $matches[1]
            );


        $level =
            (int) $matches[2];


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        return [
            'taxonomy' =>
                $taxonomy,

            'level' =>
                $level,
        ];
    }
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings['term_taxonomy_id']
            )
        ) {
            return $args;
        }


        $query_id =
            (string)
            $settings['term_taxonomy_id'];


        $parsed =
            tfsc_derived_rel_v2_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        $taxonomy =
            $parsed['taxonomy'];


        $wanted_level =
            $parsed['level'];


        /*
         * Status taxonomy nooit.
         */
        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /*
         * Elementor Source.
         */
        if (
            empty(
                $args['taxonomy']
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args['taxonomy']
            )
                ?
            reset(
                $args['taxonomy']
            )
                :
            $args['taxonomy'];


        $elementor_taxonomy =
            sanitize_key(
                $elementor_taxonomy
            );


        if (
            $elementor_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if ( ! $pod ) {
            return $args;
        }


        if (
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $args;
        }


        $function_ids =
            tfsc_derived_rel_v2_get_function_ids(
                $pod
            );


        if ( empty( $function_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $vacancy_ids =
            tfsc_derived_rel_v2_get_vacancy_ids(
                $function_ids
            );


        if ( empty( $vacancy_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $target_term_ids =
            tfsc_derived_rel_v2_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $target_term_ids =
            tfsc_derived_rel_v2_filter_level(
                $target_term_ids,
                $taxonomy,
                $wanted_level
            );


        if ( empty( $target_term_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            $target_term_ids;


        $args['hide_empty'] =
            false;


        $args['hierarchical'] =
            false;


        /*
         * Markering voor sorteerfix.
         */
        $args['tfsc_derived_relationship_query'] =
            1;


        $args['tfsc_derived_relationship_taxonomy'] =
            $taxonomy;


        return $args;

    },
    30,
    3
);


/**
 * ============================================================
 * 11. UITEINDELIJKE SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if ( is_admin() ) {
            return $terms;
        }


        if (
            empty( $terms ) ||
            ! is_array( $terms )
        ) {
            return $terms;
        }


        if (
            empty(
                $args['tfsc_derived_relationship_query']
            )
        ) {
            return $terms;
        }


        $taxonomy =
            isset(
                $args['tfsc_derived_relationship_taxonomy']
            )
                ?
            sanitize_key(
                $args['tfsc_derived_relationship_taxonomy']
            )
                :
            '';


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return $terms;
        }


        foreach (
            $terms
            as $term
        ) {

            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                $taxonomy !==
                $term->taxonomy
            ) {
                return $terms;
            }
        }


        $orderby =
            isset(
                $args['orderby']
            )
                ?
            strtolower(
                (string) $args['orderby']
            )
                :
            'name';


        if (
            'name'
            !==
            $orderby
        ) {
            return $terms;
        }


        $order =
            isset(
                $args['order']
            )
                ?
            strtoupper(
                (string) $args['order']
            )
                :
            'ASC';


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {
            $order =
                'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                $name_a =
                    remove_accents(
                        wp_strip_all_tags(
                            $a->name
                        )
                    );


                $name_b =
                    remove_accents(
                        wp_strip_all_tags(
                            $b->name
                        )
                    );


                $comparison =
                    strnatcasecmp(
                        $name_a,
                        $name_b
                    );


                if (
                    'DESC'
                    ===
                    $order
                ) {

                    $comparison *=
                        -1;
                }


                return $comparison;
            }
        );


        return $terms;

    },
    9999,
    4
);


/**
 * ============================================================
 * 12. HIËRARCHISCH TERMPAD
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_term_path' ) ) {

    function tfsc_derived_rel_v2_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs = [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if ( ! empty( $ancestor_ids ) ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error( $ancestor ) &&
                        ! empty( $ancestor->slug )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return implode(
            '/',
            array_map(
                'rawurlencode',
                $slugs
            )
        );
    }
}


/**
 * ============================================================
 * 13. COMBO URL
 * ============================================================
 */

if ( ! function_exists( 'tfsc_derived_rel_v2_build_combo_url' ) ) {

    function tfsc_derived_rel_v2_build_combo_url(
        $target_term
    ) {

        if (
            ! (
                $target_term instanceof WP_Term
            )
        ) {
            return false;
        }


        $taxonomy =
            $target_term->taxonomy;


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return false;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if (
            ! $pod ||
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return false;
        }


        $function_ids =
            tfsc_derived_rel_v2_get_function_ids(
                $pod
            );


        if ( empty( $function_ids ) ) {
            return false;
        }


        $function_terms = [];


        foreach (
            $function_ids
            as $function_id
        ) {

            $function_term =
                get_term(
                    $function_id,
                    'functienaam'
                );


            if (
                $function_term instanceof WP_Term &&
                ! is_wp_error(
                    $function_term
                )
            ) {

                $function_terms[] =
                    $function_term;
            }
        }


        if ( empty( $function_terms ) ) {
            return false;
        }


        $tax_query = [
            'relation' =>
                'AND',

            [
                'taxonomy' =>
                    'functienaam',

                'field' =>
                    'term_id',

                'terms' =>
                    $function_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ],

            [
                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' => [
                    (int)
                    $target_term->term_id,
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    is_taxonomy_hierarchical(
                        $taxonomy
                    ),
            ],
        ];


        $status_taxonomy =
            tfsc_derived_rel_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [

                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_derived_rel_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        tfsc_derived_rel_v2_vacancy_post_type(),

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if ( empty( $has_result ) ) {
            return false;
        }


        $parts = [
            tfsc_derived_rel_v2_combo_base(),
        ];


        foreach (
            $function_terms
            as $function_term
        ) {

            $function_path =
                tfsc_derived_rel_v2_term_path(
                    $function_term
                );


            if (
                '' ===
                $function_path
            ) {
                continue;
            }


            $parts[] =
                'functienaam';

            $parts[] =
                $function_path;
        }


        $target_path =
            tfsc_derived_rel_v2_term_path(
                $target_term
            );


        if (
            '' ===
            $target_path
        ) {
            return false;
        }


        $parts[] =
            $taxonomy;

        $parts[] =
            $target_path;


        return home_url(
            '/'
            .
            implode(
                '/',
                array_map(
                    function( $part ) {

                        return trim(
                            $part,
                            '/'
                        );
                    },
                    $parts
                )
            )
            .
            '/'
        );
    }
}


/**
 * ============================================================
 * 14. TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        /*
         * Native link bypass respecteren.
         *
         * Wordt o.a. gebruikt door:
         *
         * [vacature_button_url]
         */
        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            )
        ) {
            return $termlink;
        }


        if ( is_admin() ) {
            return $termlink;
        }


        if (
            ! (
                $term instanceof WP_Term
            ) ||
            empty(
                $taxonomy
            )
        ) {
            return $termlink;
        }


        /**
         * ========================================================
         * ALLEEN CPT / POST CONTEXT
         * ========================================================
         *
         * Heel belangrijk:
         *
         * Deze snippet is de CPT-versie.
         *
         * Op een taxonomy archive is get_queried_object()
         * een WP_Term. In dat geval mag deze term_link filter
         * absoluut niets veranderen.
         */

        $current_object =
            get_queried_object();


        if (
            $current_object instanceof WP_Term
        ) {
            return $termlink;
        }


        /**
         * Normale frontend:
         *
         * alleen verder als het queried object een WP_Post is.
         *
         * Elementor Theme Builder gebruikt een
         * elementor_library WP_Post; dat laten we bewust toe,
         * omdat get_current_pod() daar via preview_id de echte
         * preview-post kan vinden.
         */
        if (
            ! (
                $current_object instanceof WP_Post
            )
        ) {
            return $termlink;
        }


        /*
         * Status taxonomy nooit.
         */
        if (
            tfsc_derived_rel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $termlink;
        }


        $pod =
            tfsc_derived_rel_v2_get_current_pod();


        if ( ! $pod ) {
            return $termlink;
        }


        /*
         * Alleen converteren wanneer de huidige CPT daadwerkelijk
         * een relationship field voor deze target taxonomy heeft.
         */
        if (
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_derived_rel_v2_build_combo_url(
                $term
            );


        if ( ! $combo_url ) {
            return $termlink;
        }


        return $combo_url;

    },
    30,
    3
);

/**
 * TFSC - Taxonomy Base Archives + Elementor Theme Builder Condition
 *
 * DOEL
 * ============================================================
 * WordPress kent standaard:
 *
 *   /beroepengids/functie-inhoud/term/
 *
 * als archive van één specifieke taxonomy term.
 *
 * Maar WordPress kent standaard NIET:
 *
 *   /beroepengids/functie-inhoud/
 *
 * als overzichtsarchive van de taxonomy zelf.
 *
 * Deze snippet voegt dat ontbrekende niveau toe.
 *
 *
 * VOORBEELD
 * ============================================================
 * In Pods staat bij een taxonomy:
 *
 *   Custom Rewrite Slug:
 *   beroepengids/functie-inhoud
 *
 * Dan ontstaat automatisch:
 *
 *   /beroepengids/functie-inhoud/
 *
 * als TFSC Taxonomy Base Archive.
 *
 * De bestaande term-URL blijft gewoon:
 *
 *   /beroepengids/functie-inhoud/inbedrijfstellen/
 *
 *
 * REWRITE SLUG IS LEIDEND
 * ============================================================
 * De snippet leest automatisch de rewrite slug van WordPress/Pods.
 *
 * Dus:
 *
 *   beroepen
 *
 * geeft:
 *
 *   /beroepen/
 *
 * En:
 *
 *   beroepengids/functie-inhoud
 *
 * geeft:
 *
 *   /beroepengids/functie-inhoud/
 *
 * Je hoeft taxonomy-namen of URL's dus niet handmatig in deze
 * snippet te onderhouden.
 *
 *
 * ELEMENTOR THEME BUILDER
 * ============================================================
 * Deze snippet voegt bij Elementor Pro een nieuwe Archive
 * Display Condition toe:
 *
 *   Archives
 *   → TFSC Taxonomy Base Archives
 *
 * Daardoor kun je één Elementor Archive Template koppelen aan
 * al deze nieuwe taxonomy-overzichten.
 *
 *
 * QUERY VAR
 * ============================================================
 * Op zo'n archive bevat:
 *
 *   get_query_var( 'tfsc_taxonomy_archive' )
 *
 * automatisch de interne taxonomy name.
 *
 * Die gebruiken we later ook voor de TFSC Term Loop Grid.
 *
 *
 * BESTAANDE ARCHIEVEN
 * ============================================================
 * Deze snippet verandert NIET:
 *
 * - normale taxonomy term archives;
 * - CPT archives;
 * - Posts / Pages;
 * - TFSC combo archives;
 * - bestaande combo-archive breadcrumbs.
 *
 * De rewrite matcht alleen exact de taxonomy rewrite-basis.
 *
 *
 * URL-CONFLICTEN
 * ============================================================
 * Eén URL kan niet tegelijk twee verschillende archives zijn.
 *
 * Als bijvoorbeeld /beroepen/ al een CPT archive is en een
 * taxonomy óók rewrite slug "beroepen" krijgt, is er een conflict.
 *
 * Gebruik daarom voor taxonomies unieke rewrite bases wanneer nodig.
 *
 *
 * NA ACTIVEREN
 * ============================================================
 * Ga EENMALIG naar:
 *
 *   WordPress → Instellingen → Permalinks
 *
 * en klik:
 *
 *   Wijzigingen opslaan
 *
 * Dit is nodig om WordPress de nieuwe rewrite rules direct te
 * laten opslaan.
 */


/* ============================================================
 * 1. TFSC QUERY VAR REGISTREREN
 * ============================================================
 */

add_filter( 'query_vars', function( $vars ) {

    $vars[] = 'tfsc_taxonomy_archive';

    return $vars;

} );


/* ============================================================
 * 2. TAXONOMY BASE REWRITE RULES REGISTREREN
 * ============================================================
 */

add_action( 'init', function() {

    $taxonomies = get_taxonomies(
        [
            'public' => true,
        ],
        'objects'
    );

    foreach ( $taxonomies as $taxonomy ) {

        /*
         * Alleen taxonomies gebruiken die een rewrite hebben.
         */
        if (
            empty( $taxonomy->rewrite ) ||
            empty( $taxonomy->rewrite['slug'] )
        ) {
            continue;
        }

        $rewrite_slug = trim(
            $taxonomy->rewrite['slug'],
            '/'
        );

        if ( $rewrite_slug === '' ) {
            continue;
        }

        /*
         * Exact de taxonomy-basis matchen.
         *
         * beroepengids/functie-inhoud
         *
         * matcht dus:
         *
         * /beroepengids/functie-inhoud/
         *
         * maar NIET:
         *
         * /beroepengids/functie-inhoud/term/
         */
        $regex =
            '^' .
            preg_quote( $rewrite_slug, '#' ) .
            '/?$';

        add_rewrite_rule(
            $regex,
            'index.php?tfsc_taxonomy_archive=' .
                urlencode( $taxonomy->name ),
            'top'
        );
    }

}, 99 );


/* ============================================================
 * 3. VIRTUELE TAXONOMY-PAGINA ALS ARCHIVE MARKEREN
 * ============================================================
 */

add_action( 'parse_query', function( $query ) {

    $taxonomy_name = $query->get(
        'tfsc_taxonomy_archive'
    );

    if ( ! $taxonomy_name ) {
        return;
    }

    $taxonomy = get_taxonomy(
        $taxonomy_name
    );

    if (
        ! $taxonomy ||
        empty( $taxonomy->public )
    ) {
        return;
    }

    /*
     * Alle conflicterende WordPress-conditionals uitschakelen.
     */
    $query->is_home          = false;
    $query->is_front_page    = false;
    $query->is_singular      = false;
    $query->is_page          = false;
    $query->is_single        = false;
    $query->is_search        = false;
    $query->is_404           = false;

    /*
     * Dit is voor WordPress/Elementor een archive.
     */
    $query->is_archive = true;

}, 20 );


/* ============================================================
 * 4. 404-AFHANDELING VOORKOMEN
 * ============================================================
 *
 * Omdat dit een virtuele archive-URL is en geen echte post/page
 * bestaat, voorkomen we dat WordPress hem later alsnog als 404
 * behandelt.
 */

add_filter( 'pre_handle_404', function( $preempt, $wp_query ) {

    if (
        $wp_query->get( 'tfsc_taxonomy_archive' )
    ) {

        $taxonomy_name = $wp_query->get(
            'tfsc_taxonomy_archive'
        );

        $taxonomy = get_taxonomy(
            $taxonomy_name
        );

        if (
            $taxonomy &&
            ! empty( $taxonomy->public )
        ) {

            $wp_query->is_404    = false;
            $wp_query->is_archive = true;

            status_header( 200 );

            return true;
        }
    }

    return $preempt;

}, 10, 2 );


/* ============================================================
 * 5. GEEN NORMALE POSTS OPHALEN VOOR DE MAIN QUERY
 * ============================================================
 *
 * De taxonomy-base archive is bedoeld om taxonomy terms te tonen.
 * De toekomstige TFSC Term Loop Grid haalt die terms zelf op.
 */

add_action( 'pre_get_posts', function( $query ) {

    if (
        is_admin() ||
        ! $query->is_main_query()
    ) {
        return;
    }

    if (
        ! $query->get(
            'tfsc_taxonomy_archive'
        )
    ) {
        return;
    }

    /*
     * Laat de normale post-query geen echte content renderen.
     */
    $query->set(
        'post__in',
        [ 0 ]
    );

}, 20 );


/* ============================================================
 * 6. HELPERFUNCTIE: ACTIEVE TAXONOMY OPHALEN
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_get_current_taxonomy_archive'
    )
) {

    function tfsc_get_current_taxonomy_archive() {

        $taxonomy_name = get_query_var(
            'tfsc_taxonomy_archive'
        );

        if ( ! $taxonomy_name ) {
            return false;
        }

        $taxonomy = get_taxonomy(
            $taxonomy_name
        );

        return $taxonomy ?: false;
    }
}


/* ============================================================
 * 7. HELPERFUNCTIE: CONTROLEREN OF DIT EEN TFSC
 *    TAXONOMY BASE ARCHIVE IS
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_is_taxonomy_base_archive'
    )
) {

    function tfsc_is_taxonomy_base_archive() {

        return (
            (bool) get_query_var(
                'tfsc_taxonomy_archive'
            )
        );
    }
}


/* ============================================================
 * 8. ARCHIVE TITLE
 * ============================================================
 *
 * Voorbeeld:
 *
 * interne taxonomy:
 * functie_inhoud_beroep
 *
 * label:
 * Functie-inhoud
 *
 * archive title:
 * Functie-inhoud
 */

add_filter( 'get_the_archive_title', function( $title ) {

    $taxonomy = tfsc_get_current_taxonomy_archive();

    if ( ! $taxonomy ) {
        return $title;
    }

    if (
        ! empty(
            $taxonomy->labels->name
        )
    ) {
        return $taxonomy->labels->name;
    }

    return $title;

} );


/*
 * Elementor gebruikt voor zijn Archive Title Dynamic Tag
 * een eigen filter.
 */

add_filter(
