/* ============================================================
 * 9. BODY CLASSES
 * ============================================================
 *
 * Geeft bijvoorbeeld:
 *
 * tfsc-taxonomy-base-archive
 *
 * tfsc-taxonomy-base-archive--functie_inhoud_beroep
 */

add_filter( 'body_class', function( $classes ) {

