        );

    return $classes;

} );


/**
 * ============================================================
 * 10. ELEMENTOR PRO THEME BUILDER CONDITIONS
 * ============================================================
 *
 * Deze code registreert TWEE aparte archive conditions:
 *
 * 1. TFSC Beroepengids Taxonomy Base Archives
 *
 *    Bijvoorbeeld:
 *
 *    /beroepengids/functienamen/
 *    /beroepengids/functie-inhoud/
 *    /beroepengids/kennisgebied/
 *
 *
 * 2. TFSC Beroepengids Taxonomy Term Archives
 *
 *    Bijvoorbeeld:
 *
 *    /beroepengids/functienamen/field-service-engineer/
 *    /beroepengids/functie-inhoud/inbedrijfstellen/
 *    /beroepengids/kennisgebied/elektrotechniek/
 *
 *
 * Alleen publieke taxonomies waarvan de rewrite slug begint met:
 *
 *    beroepengids/
 *
 * worden meegenomen.
 */


/**
 * ============================================================
 * HELPER:
 * HOORT TAXONOMY BIJ BEROEPENGIDS?
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_is_beroepengids_taxonomy'
    )
) {

    function tfsc_is_beroepengids_taxonomy(
        $taxonomy_name
    ) {

        if ( ! $taxonomy_name ) {
            return false;
        }


        $taxonomy =
            get_taxonomy(
                $taxonomy_name
            );


        if (
            ! $taxonomy ||
            empty(
                $taxonomy->public
            )
        ) {
            return false;
        }


        if (
            empty(
                $taxonomy->rewrite
            ) ||
            empty(
                $taxonomy->rewrite['slug']
            )
        ) {
            return false;
        }


        $rewrite_slug =
            trim(
                $taxonomy->rewrite['slug'],
                '/'
            );


        if ( '' === $rewrite_slug ) {
            return false;
        }


        return (
            0 === strpos(
                $rewrite_slug,
                'beroepengids/'
            )
        );
    }
}


/**
 * ============================================================
 * HELPER:
 * IS DIT EEN BEROEPENGIDS TAXONOMY BASE ARCHIVE?
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * /beroepengids/functienamen/
 */

if (
    ! function_exists(
        'tfsc_is_beroepengids_taxonomy_base_archive'
    )
) {

    function tfsc_is_beroepengids_taxonomy_base_archive() {

        $taxonomy_name =
            get_query_var(
                'tfsc_taxonomy_archive'
            );


        if ( ! $taxonomy_name ) {
            return false;
        }


        return
            tfsc_is_beroepengids_taxonomy(
                $taxonomy_name
            );
    }
}


/**
 * ============================================================
 * HELPER:
 * IS DIT EEN BEROEPENGIDS TAXONOMY TERM ARCHIVE?
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * /beroepengids/functienamen/field-service-engineer/
 */

if (
    ! function_exists(
        'tfsc_is_beroepengids_taxonomy_term_archive'
    )
) {

    function tfsc_is_beroepengids_taxonomy_term_archive() {

        $object =
            get_queried_object();


        if (
            ! (
                $object instanceof WP_Term
            )
        ) {
            return false;
        }


        if (
            empty(
                $object->taxonomy
            )
        ) {
            return false;
        }


        return
            tfsc_is_beroepengids_taxonomy(
                $object->taxonomy
            );
    }
}


/**
 * ============================================================
 * ELEMENTOR CONDITIONS REGISTREREN
 * ============================================================
 */

add_action(
    'elementor/theme/register_conditions',
    function( $conditions_manager ) {

        if (
            ! class_exists(
                '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base'
            )
        ) {
            return;
        }


        /**
         * ====================================================
         * CONDITION 1:
         * TAXONOMY BASE ARCHIVES
         * ====================================================
         */

        if (
            ! class_exists(
                'TFSC_Elementor_Beroepengids_Taxonomy_Base_Archive_Condition'
            )
        ) {

            class TFSC_Elementor_Beroepengids_Taxonomy_Base_Archive_Condition
                extends
                \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type(): string {
                    return 'archive';
                }


                public static function get_priority(): int {
                    return 90;
                }


                public function get_name(): string {
                    return 'tfsc_beroepengids_taxonomy_base_archive';
                }


                public function get_label(): string {
                    return 'TFSC Beroepengids Taxonomy Base Archives';
                }


                public function check( $args ): bool {

                    return
                        function_exists(
                            'tfsc_is_beroepengids_taxonomy_base_archive'
                        )
                        &&
                        tfsc_is_beroepengids_taxonomy_base_archive();
                }
            }
        }


        /**
         * ====================================================
         * CONDITION 2:
         * TAXONOMY TERM ARCHIVES
         * ====================================================
         */

        if (
            ! class_exists(
                'TFSC_Elementor_Beroepengids_Taxonomy_Term_Archive_Condition'
            )
        ) {

            class TFSC_Elementor_Beroepengids_Taxonomy_Term_Archive_Condition
                extends
                \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type(): string {
                    return 'archive';
                }


                public static function get_priority(): int {
                    return 91;
                }


                public function get_name(): string {
                    return 'tfsc_beroepengids_taxonomy_term_archive';
                }


                public function get_label(): string {
                    return 'TFSC Beroepengids Taxonomy Term Archives';
                }


                public function check( $args ): bool {

                    return
                        function_exists(
                            'tfsc_is_beroepengids_taxonomy_term_archive'
                        )
                        &&
                        tfsc_is_beroepengids_taxonomy_term_archive();
                }
            }
        }


        /**
         * ====================================================
         * ONDER ARCHIVES REGISTREREN
         * ====================================================
         */

        $archive_condition =
            $conditions_manager->get_condition(
                'archive'
            );


        if ( ! $archive_condition ) {
            return;
        }


        $archive_condition->register_sub_condition(
            new TFSC_Elementor_Beroepengids_Taxonomy_Base_Archive_Condition()
        );


        $archive_condition->register_sub_condition(
            new TFSC_Elementor_Beroepengids_Taxonomy_Term_Archive_Condition()
        );
    },
    100
);

/**
 * TFSC - Generic Pods Field Shortcode
 *
 * Gebruik:
 *
 * [pods_field field="veldnaam"]
 *
 * Optioneel:
 *
 * [pods_field field="veldnaam" before="Tekst ervoor " after=" tekst erna"]
 *
 * Werkt op:
 *
 * - normale posts / CPT's
 * - Elementor Theme Builder preview
 * - taxonomy term archives
 *
 * Output is plain text.
 */

add_shortcode(
    'pods_field',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'field'  => '',
                    'before' => '',
                    'after'  => '',
                ],
                $atts,
                'pods_field'
            );


        $field_name =
            sanitize_key(
                $atts['field']
            );


        if ( ! $field_name ) {
            return '';
        }


        if ( ! function_exists( 'pods' ) ) {
            return '';
        }


        $pod = false;


        /**
         * ====================================================
         * 1. TAXONOMY TERM
         * ====================================================
         */

        $object =
            get_queried_object();


        if (
            $object instanceof WP_Term
        ) {

            $pod =
                pods(
                    $object->taxonomy,
                    $object->term_id
                );
        }


        /**
         * ====================================================
         * 2. POST / CPT
         * ====================================================
         */

        if ( ! $pod ) {

            $post_id = 0;


            /*
             * Elementor-aware helper gebruiken
             * als die al beschikbaar is.
             */
            if (
                function_exists(
                    'tfsc_derived_rel_v2_get_context_post_id'
                )
            ) {

                $post_id =
                    tfsc_derived_rel_v2_get_context_post_id();
            }


            /*
             * Normale fallback.
             */
            if (
                ! $post_id &&
                $object instanceof WP_Post
            ) {

                $post_id =
                    (int) $object->ID;
            }


            /*
             * Laatste fallback.
             */
            if ( ! $post_id ) {

                $post_id =
                    get_the_ID();
            }


            if ( $post_id ) {

                $post_type =
                    get_post_type(
                        $post_id
                    );


                if ( $post_type ) {

                    $pod =
                        pods(
                            $post_type,
                            $post_id
                        );
                }
            }
        }


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return '';
        }


        /**
         * ====================================================
         * FIELD OPHALEN
         * ====================================================
         */

        $value =
            $pod->field(
                $field_name
            );


        if (
            null === $value ||
            false === $value ||
            '' === $value
        ) {
            return '';
        }


        /**
         * ====================================================
         * ALLEEN EENVOUDIGE TEKSTWAARDEN
         * ====================================================
         */

        if (
            is_array( $value ) ||
            is_object( $value )
        ) {
            return '';
        }


        $value =
            wp_strip_all_tags(
                (string) $value
            );


        if ( '' === $value ) {
            return '';
        }


        return
            (string) $atts['before']
            .
            $value
            .
            (string) $atts['after'];
    }
);

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ?? '';

        if (
            strpos(
                (string) $query_id,
                'archive_relationship_'
            ) !== 0
        ) {
            return $args;
        }


        $object =
            get_queried_object();


        $entry = [

            'time' =>
                microtime( true ),

            'is_admin' =>
                is_admin(),

            'doing_ajax' =>
                wp_doing_ajax(),

            'request_uri' =>
                $_SERVER['REQUEST_URI']
                ?? '',

            'queried_type' =>
                is_object( $object )
                    ? get_class( $object )
                    : gettype( $object ),

            'queried_taxonomy' =>
                (
                    $object instanceof WP_Term
                )
                    ?
                $object->taxonomy
                    :
                '',

            'queried_term_id' =>
                (
                    $object instanceof WP_Term
                )
                    ?
                $object->term_id
                    :
                '',

            'query_id' =>
                $query_id,

            'taxonomy' =>
                $args['taxonomy']
                ?? null,

            'include' =>
                $args['include']
                ?? null,

            'term_taxonomy_id' =>
                $args['term_taxonomy_id']
                ?? null,

            'marker' =>
                $args['tfsc_taxrel_v1_query']
                ?? null,
        ];


        $log =
            get_option(
                'tfsc_taxonomy_loop_output_log',
                []
            );


        if (
            ! is_array( $log )
        ) {
            $log = [];
        }


        $log[] =
            $entry;


        /*
         * Alleen laatste 30 bewaren.
         */
        $log =
            array_slice(
                $log,
                -30
            );


        update_option(
            'tfsc_taxonomy_loop_output_log',
            $log,
            false
        );


        return $args;

    },
    999,
    3
);


