/**
 * TFSC - Elementor Posts filteren via Pods taxonomy relationships
 *
 * ============================================================
 * QUERY ID
 * ============================================================
 *
 * Elementor Posts / Loop Grid:
 *
 * relationship_posts
 *
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Deze snippet gebruikt de Pods relationshipvelden van de
 * huidige post/CPT of taxonomy-term om de Elementor Posts Query
 * te filteren.
 *
 * Elementor Source blijft altijd leidend.
 *
 * Bijvoorbeeld:
 *
 * Source:
 * vacature
 *
 * Query ID:
 * relationship_posts
 *
 *
 * ============================================================
 * BELANGRIJKE WIJZIGING
 * ============================================================
 *
 * Deze versie leidt de taxonomy NIET meer af uit de naam
 * van het Pods field.
 *
 * Oude gedachte:
 *
 * relationship_functie-inhoud
 *
 * →
 *
 * taxonomy functie-inhoud
 *
 *
 * Nieuwe gedachte:
 *
 * De daadwerkelijke Pods relationship wordt uitgelezen.
 *
 * Bijvoorbeeld RAW:
 *
 * [
 *     'term_id'  => 220,
 *     'name'     => 'Inbedrijfstellen',
 *     'taxonomy' => 'functie-inhoud',
 * ]
 *
 * De snippet gebruikt dus:
 *
 * taxonomy = functie-inhoud
 * term_id  = 220
 *
 *
 * ============================================================
 * WAAROM?
 * ============================================================
 *
 * Hierdoor is relationship_posts niet meer afhankelijk van:
 *
 * - Pods traversal via .term_id
 * - de taxonomynaam in de field name
 * - dezelfde naming-logica als archive_relationship_*
 *
 * De archive_relationship_* snippets mogen dezelfde Pods
 * relationships gewoon blijven gebruiken.
 *
 *
 * ============================================================
 * PODS FIELDS
 * ============================================================
 *
 * De snippet kijkt alleen naar fields die beginnen met:
 *
 * relationship_
 *
 * Bijvoorbeeld:
 *
 * relationship_functienaam
 * relationship_functie-inhoud
 * relationship_kennisgebied
 * relationship_locatie
 * relationship_bedrijfssector
 *
 *
 * Het volgende speciale field wordt genegeerd:
 *
 * relationship_vacature_button_url
 *
 * Dat field wordt alleen gebruikt voor de vacaturebutton en
 * mag de Posts Query niet beïnvloeden.
 *
 *
 * ============================================================
 * CONTEXT
 * ============================================================
 *
 * Werkt op:
 *
 * - normale post
 * - CPT
 * - taxonomy term archive
 * - Elementor Theme Builder preview voor posts/CPT's
 *
 *
 * ============================================================
 * LOGICA
 * ============================================================
 *
 * Verschillende relationshipvelden:
 *
 * AND
 *
 *
 * Meerdere geselecteerde terms binnen dezelfde taxonomy:
 *
 * OR / IN
 *
 *
 * Bijvoorbeeld:
 *
 * relationship_functienaam
 * → Field Service Engineer
 *
 * relationship_functie-inhoud
 * → Service
 * → Inbedrijfstellen
 *
 *
 * wordt:
 *
 * functienaam = Field Service Engineer
 *
 * AND
 *
 * functie-inhoud IN (Service, Inbedrijfstellen)
 *
 *
 * ============================================================
 * ELEMENTOR SOURCE
 * ============================================================
 *
 * Een relationship wordt alleen gebruikt wanneer de taxonomy
 * daadwerkelijk gekoppeld is aan het post type dat Elementor
 * als Source gebruikt.
 *
 * Dus:
 *
 * Elementor Source = vacature
 *
 * relatie naar taxonomy functie-inhoud
 *
 * →
 *
 * alleen gebruiken wanneer functie-inhoud gekoppeld is aan
 * post type vacature.
 *
 *
 * ============================================================
 * LEGE RELATIONSHIPS
 * ============================================================
 *
 * Lege relationshipvelden worden genegeerd.
 *
 * Als uiteindelijk geen bruikbare relationshipfilters bestaan,
 * worden bewust geen posts getoond.
 */


/**
 * ============================================================
 * 1. HUIDIGE CONTEXT BEPALEN
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_relposts_v3_get_context'
    )
) {

    function tfsc_relposts_v3_get_context() {

        $object =
            get_queried_object();


        /**
         * ====================================================
         * TAXONOMY TERM
         * ====================================================
         */

        if (
            $object instanceof WP_Term &&
            ! empty( $object->taxonomy ) &&
            ! empty( $object->term_id )
        ) {

            return [
                'type' =>
                    'term',

                'taxonomy' =>
                    $object->taxonomy,

                'term_id' =>
                    (int) $object->term_id,
            ];
        }


        /**
         * ====================================================
         * NORMALE POST / CPT
         * ====================================================
         */

        if (
            $object instanceof WP_Post &&
            ! empty( $object->ID ) &&
            'elementor_library'
            !==
            get_post_type(
                $object->ID
            )
        ) {

            return [
                'type' =>
                    'post',

                'post_id' =>
                    (int) $object->ID,
            ];
        }


        /**
         * ====================================================
         * ELEMENTOR THEME BUILDER PREVIEW
         * ====================================================
         */

        if (
            function_exists(
                'tfsc_derived_rel_v2_get_context_post_id'
            )
        ) {

            $post_id =
                (int)
                tfsc_derived_rel_v2_get_context_post_id();


            if (
                $post_id &&
                'elementor_library'
                !==
                get_post_type(
                    $post_id
                )
            ) {

                return [
                    'type' =>
                        'post',

                    'post_id' =>
                        $post_id,
                ];
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * 2. PODS OBJECT UIT CONTEXT
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_relposts_v3_get_pod'
    )
) {

    function tfsc_relposts_v3_get_pod(
        $context
    ) {

        if (
            ! function_exists( 'pods' ) ||
            ! is_array( $context ) ||
            empty( $context['type'] )
        ) {
            return false;
        }


        /**
         * ====================================================
         * TAXONOMY TERM
         * ====================================================
         */

        if (
            'term' === $context['type']
        ) {

            if (
                empty( $context['taxonomy'] ) ||
                empty( $context['term_id'] )
            ) {
                return false;
            }


            $pod =
                pods(
                    $context['taxonomy'],
                    (int) $context['term_id']
                );


            if (
                $pod &&
                $pod->exists()
            ) {
                return $pod;
            }


            return false;
        }


        /**
         * ====================================================
         * POST / CPT
         * ====================================================
         */

        if (
            'post' === $context['type']
        ) {

            if (
                empty( $context['post_id'] )
            ) {
                return false;
            }


            $post_id =
                (int) $context['post_id'];


            $post_type =
                get_post_type(
                    $post_id
                );


            if ( ! $post_type ) {
                return false;
            }


            $pod =
                pods(
                    $post_type,
                    $post_id
                );


            if (
                $pod &&
                $pod->exists()
            ) {
                return $pod;
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * 3. ÉÉN RAW PODS RELATIONSHIP NORMALISEREN
 * ============================================================
 *
 * Resultaat:
 *
 * [
 *     [
 *         'taxonomy' => 'functie-inhoud',
 *         'term_id'  => 220,
 *     ],
 *     ...
 * ]
 */

if (
    ! function_exists(
        'tfsc_relposts_v3_normalize_relationship'
    )
) {

    function tfsc_relposts_v3_normalize_relationship(
        $value
    ) {

        if (
            empty( $value )
        ) {
            return [];
        }


        /**
         * Eén associatieve relationship-array.
         */
        if (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['taxonomy'] )
            )
        ) {

            $value = [
                $value,
            ];
        }


        /**
         * Eén relationship-object.
         */
        if (
            is_object( $value )
        ) {

            $value = [
                $value,
            ];
        }


        if (
            ! is_array(
                $value
            )
        ) {
            return [];
        }


        $relationships =
            [];


        foreach (
            $value
            as $relation
        ) {

            $taxonomy =
                '';


            $term_id =
                0;


            /**
             * =================================================
             * ARRAY
             * =================================================
             */

            if (
                is_array(
                    $relation
                )
            ) {

                if (
                    ! empty(
                        $relation['taxonomy']
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation['taxonomy']
                        );
                }


                $term_id =
                    (int) (
                        $relation['term_id']
                        ??
                        $relation['pod_item_id']
                        ??
                        $relation['id']
                        ??
                        $relation['ID']
                        ??
                        0
                    );
            }


            /**
             * =================================================
             * OBJECT
             * =================================================
             */

            elseif (
                is_object(
                    $relation
                )
            ) {

                if (
                    ! empty(
                        $relation->taxonomy
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation->taxonomy
                        );
                }


                $term_id =
                    (int) (
                        $relation->term_id
                        ??
                        $relation->pod_item_id
                        ??
                        $relation->id
                        ??
                        $relation->ID
                        ??
                        0
                    );
            }


            /**
             * We accepteren alleen echte taxonomy relationships.
             */
            if (
                ! $taxonomy ||
                ! $term_id ||
                ! taxonomy_exists(
                    $taxonomy
                )
            ) {
                continue;
            }


            /**
             * Controleer of term daadwerkelijk bestaat
             * binnen de opgegeven taxonomy.
             */
            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                is_wp_error(
                    $term
                )
            ) {
                continue;
            }


            $relationships[] =
                [
                    'taxonomy' =>
                        $taxonomy,

                    'term_id' =>
                        (int) $term_id,
                ];
        }


        return $relationships;
    }
}


/**
 * ============================================================
 * 4. CONTROLEREN OF TAXONOMY BIJ ELEMENTOR SOURCE HOORT
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_relposts_v3_taxonomy_matches_source'
    )
) {

    function tfsc_relposts_v3_taxonomy_matches_source(
        $taxonomy,
        $query_post_types
    ) {

        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        $taxonomy_object =
            get_taxonomy(
                $taxonomy
            );


        if ( ! $taxonomy_object ) {
            return false;
        }


        foreach (
            (array) $query_post_types
            as $query_post_type
        ) {

            if (
                in_array(
                    $query_post_type,
                    (array)
                    $taxonomy_object->object_type,
                    true
                )
            ) {
                return true;
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * 5. ELEMENTOR QUERY
 * ============================================================
 */

add_action(
    'elementor/query/relationship_posts',
    function( $query ) {

        /**
         * ====================================================
         * PODS BESCHIKBAAR?
         * ====================================================
         */

        if (
            ! function_exists(
                'pods'
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /**
         * ====================================================
         * CONTEXT
         * ====================================================
         */

        $context =
            tfsc_relposts_v3_get_context();


        if ( ! $context ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /**
         * ====================================================
         * POD
         * ====================================================
         */

        $pod =
            tfsc_relposts_v3_get_pod(
                $context
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /**
         * ====================================================
         * ELEMENTOR SOURCE
         * ====================================================
         */

        $query_post_types =
            $query->get(
                'post_type'
            );


        if (
            empty(
                $query_post_types
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        $query_post_types =
            array_values(
                array_filter(
                    (array)
                    $query_post_types
                )
            );


        if (
            empty(
                $query_post_types
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /**
         * ====================================================
         * PODS FIELDS
         * ====================================================
         */

        $fields =
            $pod->fields();


        if (
            empty( $fields ) ||
            ! is_array(
                $fields
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /**
         * ====================================================
         * RELATIONSHIPS GROEPEREN PER TARGET TAXONOMY
         * ====================================================
         *
         * Bijvoorbeeld:
         *
         * [
         *     'functienaam' => [ 100 ],
         *     'functie-inhoud' => [ 220, 221 ],
         * ]
         */

        $taxonomy_term_ids =
            [];


        foreach (
            $fields
            as $field_name =>
                $field_definition
        ) {

            /**
             * Alleen fields met:
             *
             * relationship_
             */
            if (
                ! is_string(
                    $field_name
                ) ||
                '' === $field_name ||
                0 !== strpos(
                    $field_name,
                    'relationship_'
                )
            ) {
                continue;
            }


            /**
             * =================================================
             * SPECIAL FIELD UITSLUITEN
             * =================================================
             *
             * Dit veld bepaalt alleen de vacaturebutton URL.
             */

            if (
                'relationship_vacature_button_url'
                ===
                $field_name
            ) {
                continue;
            }


            /**
             * =================================================
             * RAW PODS VALUE
             * =================================================
             *
             * BELANGRIJK:
             *
             * GEEN:
             *
             * $pod->field( $field_name . '.term_id' )
             *
             * meer gebruiken.
             */

            $raw_value =
                $pod->field(
                    $field_name
                );


            if (
                empty(
                    $raw_value
                )
            ) {
                continue;
            }


            $relationships =
                tfsc_relposts_v3_normalize_relationship(
                    $raw_value
                );


            if (
                empty(
                    $relationships
                )
            ) {
                continue;
            }


            foreach (
                $relationships
                as $relationship
            ) {

                $taxonomy =
                    $relationship['taxonomy'];


                $term_id =
                    (int)
                    $relationship['term_id'];


                /**
                 * Alleen taxonomies gebruiken die daadwerkelijk
                 * gekoppeld zijn aan Elementor Source.
                 */
                if (
                    ! tfsc_relposts_v3_taxonomy_matches_source(
                        $taxonomy,
                        $query_post_types
                    )
                ) {
                    continue;
                }


                if (
                    ! isset(
                        $taxonomy_term_ids[
                            $taxonomy
                        ]
                    )
                ) {

                    $taxonomy_term_ids[
                        $taxonomy
                    ] =
                        [];
                }


                $taxonomy_term_ids[
                    $taxonomy
                ][] =
                    $term_id;
            }
        }


        /**
         * ====================================================
         * IDS PER TAXONOMY OPSCHONEN
         * ====================================================
         */

        foreach (
            $taxonomy_term_ids
            as $taxonomy =>
                $term_ids
        ) {

            $taxonomy_term_ids[
                $taxonomy
            ] =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $term_ids
                            )
                        )
                    )
                );


            if (
                empty(
                    $taxonomy_term_ids[
                        $taxonomy
                    ]
                )
            ) {

                unset(
                    $taxonomy_term_ids[
                        $taxonomy
                    ]
                );
            }
        }


        /**
         * ====================================================
         * GEEN BRUIKBARE RELATIONSHIPS
         * ====================================================
         */

        if (
            empty(
                $taxonomy_term_ids
            )
        ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }


        /**
         * ====================================================
         * TAX QUERY BOUWEN
         * ====================================================
         *
         * Verschillende taxonomies:
         *
         * AND
         *
         * Meerdere terms binnen taxonomy:
         *
         * IN
         */

        $relationship_group =
            [
                'relation' =>
                    'AND',
            ];


        foreach (
            $taxonomy_term_ids
            as $taxonomy =>
                $term_ids
        ) {

            $relationship_group[] =
                [
                    'taxonomy' =>
                        $taxonomy,

                    'field' =>
                        'term_id',

                    'terms' =>
                        $term_ids,

                    'operator' =>
                        'IN',

                    'include_children' =>
                        true,
                ];
        }


        /**
         * ====================================================
         * BESTAANDE ELEMENTOR TAX QUERY BEWAREN
         * ====================================================
         */

        $existing_tax_query =
            $query->get(
                'tax_query'
            );


        if (
            ! is_array(
                $existing_tax_query
            )
        ) {

            $existing_tax_query =
                [];
        }


        /**
         * ====================================================
         * BESTAAND + RELATIONSHIPS COMBINEREN
         * ====================================================
         */

        if (
            ! empty(
                $existing_tax_query
            )
        ) {

            $final_tax_query =
                [
                    'relation' =>
                        'AND',

                    $existing_tax_query,

                    $relationship_group,
                ];

        } else {

            $final_tax_query =
                $relationship_group;
        }


        /**
         * ====================================================
         * ELEMENTOR QUERY AANPASSEN
         * ====================================================
         */

        $query->set(
            'tax_query',
            $final_tax_query
        );
    },
    20,
    1
);

/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 2
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Deze snippet toont op een Beroepengids taxonomy-term
 * automatisch taxonomy-termen die voorkomen bij de relevante
 * OPEN vacatures.
 *
 *
 * VOORBEELD
 * ------------------------------------------------------------
 *
 * Huidige Beroepengids taxonomy:
 *
 * beroep_functie-inhoud
 *
 * Huidige term:
 *
 * Inbedrijfstellen
 *
 * Pods relationship field:
 *
 * relationship_functie-inhoud
 *
 * Geselecteerde vacature-term:
 *
 * functie-inhoud
 * → Inbedrijfstellen
 *
 *
 * De snippet zoekt vervolgens:
 *
 * open vacatures
 * met:
 *
 * functie-inhoud = Inbedrijfstellen
 *
 * en kan daaruit bijvoorbeeld tonen:
 *
 * - locaties
 * - kennisgebieden
 * - bedrijfssectoren
 * - functienamen
 * - andere target taxonomies
 *
 *
 * ============================================================
 * BELANGRIJKE WIJZIGING T.O.V. V1
 * ============================================================
 *
 * V1 verwachtte:
 *
 * huidige taxonomy:
 *
 * beroep_functie-inhoud
 *
 * →
 *
 * relationship_beroep_functie-inhoud
 *
 * Dat is niet hoe de Pods-velden zijn opgebouwd.
 *
 *
 * V2 begrijpt automatisch:
 *
 * beroep_functie-inhoud
 *
 * →
 *
 * relationship_functie-inhoud
 *
 *
 * De volgende prefixes kunnen automatisch worden verwijderd:
 *
 * beroep_
 * beroep-
 * beroepengids_
 * beroepengids-
 *
 *
 * ============================================================
 * RAW PODS RELATIONSHIP IS LEIDEND
 * ============================================================
 *
 * Voorbeeld Pods-return:
 *
 * [
 *     'term_id'  => 220,
 *     'name'     => 'Inbedrijfstellen',
 *     'taxonomy' => 'functie-inhoud',
 * ]
 *
 * V2 gebruikt dan rechtstreeks:
 *
 * taxonomy = functie-inhoud
 * term_id  = 220
 *
 * Dit is betrouwbaarder dan de taxonomy uitsluitend uit een
 * veldnaam proberen af te leiden.
 *
 *
 * ============================================================
 * ELEMENTOR QUERY ID
 * ============================================================
 *
 * archive_relationship_{target-taxonomy}_level_{nummer}
 *
 *
 * Voorbeelden:
 *
 * archive_relationship_locatie_level_0
 * archive_relationship_locatie_level_1
 * archive_relationship_locatie_level_2
 *
 * archive_relationship_kennisgebied_level_0
 *
 * archive_relationship_bedrijfssector_level_0
 *
 * archive_relationship_functie-inhoud_level_0
 *
 * archive_relationship_functienaam_level_0
 *
 *
 * ============================================================
 * ELEMENTOR INSTELLINGEN
 * ============================================================
 *
 * Elementor Taxonomy Loop:
 *
 * Source:
 *
 * moet exact overeenkomen met de target taxonomy uit
 * de Query ID.
 *
 *
 * Voorbeeld:
 *
 * Source:
 * locatie
 *
 * Query ID:
 * archive_relationship_locatie_level_1
 *
 *
 * Filter by Depth:
 * UIT
 *
 *
 * Order By / Order:
 * gewoon in Elementor instellen.
 *
 *
 * ============================================================
 * LEVELS
 * ============================================================
 *
 * Bij een hiërarchische taxonomy zoals:
 *
 * Nederland
 * └── Noord-Brabant
 *     └── Eindhoven
 *
 * is:
 *
 * level 0 = Nederland
 * level 1 = Noord-Brabant
 * level 2 = Eindhoven
 *
 *
 * ============================================================
 * VACATURES
 * ============================================================
 *
 * Alleen:
 *
 * post_status = publish
 *
 * en wanneer vac_status bestaat:
 *
 * vac_status = open
 *
 * worden gebruikt.
 *
 *
 * ============================================================
 * COMBO LINKS
 * ============================================================
 *
 * De termen uit deze derived loops krijgen een TFSC combo URL.
 *
 * Bijvoorbeeld:
 *
 * bron:
 *
 * functie-inhoud/inbedrijfstellen
 *
 * target:
 *
 * locatie/noord-brabant
 *
 * →
 *
 * /vacatures/
 * functie-inhoud/inbedrijfstellen/
 * locatie/noord-brabant/
 *
 *
 * ============================================================
 * AND / OR
 * ============================================================
 *
 * Verschillende source taxonomies:
 *
 * AND
 *
 * Meerdere terms binnen dezelfde source taxonomy:
 *
 * IN / OR
 *
 *
 * ============================================================
 * SPECIALE RELATIONSHIP FIELDS
 * ============================================================
 *
 * relationship_vacature_button_url
 *
 * wordt nooit als source relationship gebruikt.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

if (
