/**
 * ============================================================
 * 2. HUIDIGE TAXONOMY TERM
 * ============================================================
 *
 * Werkt op:
 *
 * - normale taxonomy term frontend
 * - Elementor Theme Builder taxonomy archive preview
 *
 * In Elementor is het queried object vaak het
 * elementor_library template.
 *
 * Daarom proberen we daar de ingestelde preview_id / preview
 * context uit Elementor te halen.
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_get_current_term'
    )
) {

    function tfsc_taxrel_v2_get_current_term() {

        $object =
            get_queried_object();


        /**
         * ====================================================
         * 1. NORMALE FRONTEND
         * ====================================================
         */

        if (
            $object instanceof WP_Term &&
            ! empty(
                $object->term_id
            ) &&
            ! empty(
                $object->taxonomy
            ) &&
            taxonomy_exists(
                $object->taxonomy
            )
        ) {

            return $object;
        }


        /**
         * ====================================================
         * 2. ELEMENTOR THEME BUILDER PREVIEW
         * ====================================================
         *
         * In de editor is queried_object meestal:
         *
         * WP_Post
         * post_type = elementor_library
         */

        if (
            $object instanceof WP_Post &&
            ! empty(
                $object->ID
            ) &&
            'elementor_library'
            ===
            get_post_type(
                $object->ID
            )
        ) {

            $template_id =
                (int) $object->ID;


            /**
             * =================================================
             * 2A. ELEMENTOR DOCUMENT API
             * =================================================
             */

            if (
                did_action(
                    'elementor/loaded'
                ) &&
                class_exists(
                    '\Elementor\Plugin'
                )
            ) {

                try {

                    $documents =
                        \Elementor\Plugin::$instance
                            ->documents;


                    if ( $documents ) {

                        $document =
                            $documents->get(
                                $template_id
                            );


                        if (
                            $document &&
                            method_exists(
                                $document,
                                'get_settings'
                            )
                        ) {

                            /**
                             * Elementor gebruikt preview_id
                             * regelmatig ook voor taxonomy terms.
                             */
                            $preview_id =
                                absint(
                                    $document->get_settings(
                                        'preview_id'
                                    )
                                );


                            $preview_type =
                                (string)
                                $document->get_settings(
                                    'preview_type'
                                );


                            if (
                                $preview_id &&
                                $preview_type
                            ) {

                                /**
                                 * Preview type kan bijvoorbeeld
                                 * iets bevatten als:
                                 *
                                 * taxonomy/beroep_functie-inhoud
                                 *
                                 * of een vergelijkbare
                                 * taxonomy-context.
                                 */

                                $taxonomy =
                                    '';


                                if (
                                    0 === strpos(
                                        $preview_type,
                                        'taxonomy/'
                                    )
                                ) {

                                    $taxonomy =
                                        substr(
                                            $preview_type,
                                            strlen(
                                                'taxonomy/'
                                            )
                                        );

                                } elseif (
                                    0 === strpos(
                                        $preview_type,
                                        'archive/'
                                    )
                                ) {

                                    $candidate =
                                        substr(
                                            $preview_type,
                                            strlen(
                                                'archive/'
                                            )
                                        );


                                    if (
                                        taxonomy_exists(
                                            $candidate
                                        )
                                    ) {

                                        $taxonomy =
                                            $candidate;
                                    }
                                }


                                $taxonomy =
                                    sanitize_key(
                                        $taxonomy
                                    );


                                if (
                                    $taxonomy &&
                                    taxonomy_exists(
                                        $taxonomy
                                    )
                                ) {

                                    $term =
                                        get_term(
                                            $preview_id,
                                            $taxonomy
                                        );


                                    if (
                                        $term instanceof WP_Term &&
                                        ! is_wp_error(
                                            $term
                                        )
                                    ) {

                                        return $term;
                                    }
                                }
                            }
                        }
                    }

                } catch ( Throwable $e ) {

                    /*
                     * Geen fout tonen.
                     * Hieronder volgen fallbacks.
                     */
                }
            }


            /**
             * =================================================
             * 2B. _ELEMENTOR_PAGE_SETTINGS FALLBACK
             * =================================================
             */

            $page_settings =
                get_post_meta(
                    $template_id,
                    '_elementor_page_settings',
                    true
                );


            if (
                is_array(
                    $page_settings
                )
            ) {

                $preview_id =
                    ! empty(
                        $page_settings[
                            'preview_id'
                        ]
                    )
                        ?
                    absint(
                        $page_settings[
                            'preview_id'
                        ]
                    )
                        :
                    0;


                $preview_type =
                    ! empty(
                        $page_settings[
                            'preview_type'
                        ]
                    )
                        ?
                    (string)
                    $page_settings[
                        'preview_type'
                    ]
                        :
                    '';


                if (
                    $preview_id &&
                    $preview_type
                ) {

                    $taxonomy =
                        '';


                    if (
                        0 === strpos(
                            $preview_type,
                            'taxonomy/'
                        )
                    ) {

                        $taxonomy =
                            substr(
                                $preview_type,
                                strlen(
                                    'taxonomy/'
                                )
                            );

                    } elseif (
                        0 === strpos(
                            $preview_type,
                            'archive/'
                        )
                    ) {

                        $candidate =
                            substr(
                                $preview_type,
                                strlen(
                                    'archive/'
                                )
                            );


                        if (
                            taxonomy_exists(
                                $candidate
                            )
                        ) {

                            $taxonomy =
                                $candidate;
                        }
                    }


                    $taxonomy =
                        sanitize_key(
                            $taxonomy
                        );


                    if (
                        $taxonomy &&
                        taxonomy_exists(
                            $taxonomy
                        )
                    ) {

                        $term =
                            get_term(
                                $preview_id,
                                $taxonomy
                            );


                        if (
                            $term instanceof WP_Term &&
                            ! is_wp_error(
                                $term
                            )
                        ) {

                            return $term;
                        }
                    }
                }
            }
        }


        /**
         * ====================================================
         * 3. URL PREVIEW FALLBACK
         * ====================================================
         */

        if (
            isset(
                $_GET['preview_id']
            )
        ) {

            $preview_id =
                absint(
                    wp_unslash(
                        $_GET['preview_id']
                    )
                );


            if ( $preview_id ) {

                /**
                 * We kennen hier niet automatisch de taxonomy.
                 * Daarom alleen gebruiken wanneer Elementor
                 * ergens ook een taxonomy meegeeft.
                 */

                $taxonomy_candidates = [
                    'taxonomy',
                    'preview_taxonomy',
                ];


                foreach (
                    $taxonomy_candidates
                    as $parameter
                ) {

                    if (
                        empty(
                            $_GET[
                                $parameter
                            ]
                        )
                    ) {
                        continue;
                    }


                    $taxonomy =
                        sanitize_key(
                            wp_unslash(
                                $_GET[
                                    $parameter
                                ]
                            )
                        );


                    if (
                        ! taxonomy_exists(
                            $taxonomy
                        )
                    ) {
                        continue;
                    }


                    $term =
                        get_term(
                            $preview_id,
                            $taxonomy
                        );


                    if (
                        $term instanceof WP_Term &&
                        ! is_wp_error(
                            $term
                        )
                    ) {

                        return $term;
                    }
                }
            }
        }


        return false;
    }
}


/**
 * ============================================================
 * 3. PODS OBJECT VAN HUIDIGE TERM
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_get_current_pod'
    )
) {

    function tfsc_taxrel_v2_get_current_pod() {

        if (
            ! function_exists(
                'pods'
            )
        ) {
            return false;
        }


        $term =
            tfsc_taxrel_v2_get_current_term();


        if ( ! $term ) {
            return false;
        }


        $pod =
            pods(
                $term->taxonomy,
                (int) $term->term_id
            );


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return false;
        }


        return $pod;
    }
}


/**
 * ============================================================
 * 4. SOURCE TAXONOMY NAAM NORMALISEREN
 * ============================================================
 *
 * Voorbeeld:
 *
 * beroep_functie-inhoud
 *
 * →
 *
 * functie-inhoud
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_normalize_source_taxonomy'
    )
) {

    function tfsc_taxrel_v2_normalize_source_taxonomy(
        $taxonomy
    ) {

        $taxonomy =
            sanitize_key(
                $taxonomy
            );


        if ( ! $taxonomy ) {
            return '';
        }


        $prefixes = [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ];


        foreach (
            $prefixes
            as $prefix
        ) {

            if (
                0 === strpos(
                    $taxonomy,
                    $prefix
                )
            ) {

                $candidate =
                    substr(
                        $taxonomy,
                        strlen(
                            $prefix
                        )
                    );


                $candidate =
                    sanitize_key(
                        $candidate
                    );


                if ( $candidate ) {
                    return $candidate;
                }
            }
        }


        return $taxonomy;
    }
}


/**
 * ============================================================
 * 5. SOURCE RELATIONSHIP FIELD BEPALEN
 * ============================================================
 *
 * Eerst proberen:
 *
 * relationship_{huidige taxonomy}
 *
 *
 * Daarna:
 *
 * relationship_{genormaliseerde taxonomy}
 *
 *
 * Voorbeeld:
 *
 * beroep_functie-inhoud
 *
 * probeert:
 *
 * relationship_beroep_functie-inhoud
 *
 * en daarna:
 *
 * relationship_functie-inhoud
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_source_field_name'
    )
) {

    function tfsc_taxrel_v2_source_field_name() {

        $term =
            tfsc_taxrel_v2_get_current_term();


        $pod =
            tfsc_taxrel_v2_get_current_pod();


        if (
            ! $term ||
            ! $pod
        ) {
            return '';
        }


        $fields =
            $pod->fields();


        if (
            ! is_array(
                $fields
            )
        ) {
            return '';
        }


        $candidates =
            [];


        /**
         * Exacte taxonomy name.
         */
        $candidates[] =
            'relationship_'
            .
            $term->taxonomy;


        /**
         * Genormaliseerde taxonomy name.
         */
        $normalized =
            tfsc_taxrel_v2_normalize_source_taxonomy(
                $term->taxonomy
            );


        if ( $normalized ) {

            $candidates[] =
                'relationship_'
                .
                $normalized;
        }


        $candidates =
            array_values(
                array_unique(
                    $candidates
                )
            );


        foreach (
            $candidates
            as $field_name
        ) {

            /**
             * Speciale button relationship nooit.
             */
            if (
                'relationship_vacature_button_url'
                ===
                $field_name
            ) {
                continue;
            }


            if (
                array_key_exists(
                    $field_name,
                    $fields
                )
            ) {

                return $field_name;
            }
        }


        return '';
    }
}


/**
 * ============================================================
 * 6. TAXONOMY FALLBACK UIT FIELD NAME
 * ============================================================
 *
 * relationship_functie-inhoud
 *
 * →
 *
 * functie-inhoud
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_taxonomy_from_field_name'
    )
) {

    function tfsc_taxrel_v2_taxonomy_from_field_name(
        $field_name
    ) {

        if (
            ! is_string(
                $field_name
            ) ||
            0 !== strpos(
                $field_name,
                'relationship_'
            )
        ) {
            return '';
        }


        $taxonomy =
            substr(
                $field_name,
                strlen(
                    'relationship_'
                )
            );


        $taxonomy =
            sanitize_key(
                $taxonomy
            );


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        return $taxonomy;
    }
}


/**
 * ============================================================
 * 7. SOURCE RELATIONSHIPS UITLEZEN
 * ============================================================
 *
 * Resultaat:
 *
 * [
 *     'functie-inhoud' => [ 220 ],
 * ]
 *
 *
 * RAW Pods relationship taxonomy is leidend.
 *
 * Alleen als Pods geen taxonomy meestuurt, gebruiken we
 * de taxonomy die uit het relationship field kan worden
 * afgeleid.
 *
 * We gebruiken NOOIT meer de huidige Beroepengids-taxonomy
 * als fallback.
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_get_source_relationships'
    )
) {

    function tfsc_taxrel_v2_get_source_relationships() {

        $pod =
            tfsc_taxrel_v2_get_current_pod();


        if ( ! $pod ) {
            return [];
        }


        $field_name =
            tfsc_taxrel_v2_source_field_name();


        if ( ! $field_name ) {
            return [];
        }


        if (
            'relationship_vacature_button_url'
            ===
            $field_name
        ) {
            return [];
        }


        $relations =
            $pod->field(
                $field_name
            );


        if (
            empty(
                $relations
            )
        ) {
            return [];
        }


        /**
         * Taxonomy fallback uit field name.
         */
        $field_taxonomy =
            tfsc_taxrel_v2_taxonomy_from_field_name(
                $field_name
            );


        /**
         * Eén numerieke relation normaliseren.
         */
        if (
            is_numeric(
                $relations
            )
        ) {

            $relations = [
                $relations,
            ];
        }


        /**
         * Eén associatieve relationship-array normaliseren.
         */
        if (
            is_array(
                $relations
            ) &&
            (
                isset(
                    $relations['term_id']
                ) ||
                isset(
                    $relations['pod_item_id']
                ) ||
                isset(
                    $relations['id']
                ) ||
                isset(
                    $relations['ID']
                )
            )
        ) {

            $relations = [
                $relations,
            ];
        }


        /**
         * Eén object normaliseren.
         */
        if (
            is_object(
                $relations
            )
        ) {

            $relations = [
                $relations,
            ];
        }


        $groups =
            [];


        foreach (
            (array) $relations
            as $relation
        ) {

            $term_id =
                0;


            $taxonomy =
                '';


            /**
             * =================================================
             * ARRAY
             * =================================================
             */

            if (
                is_array(
                    $relation
                )
            ) {

                $term_id =
                    (int) (
                        $relation['term_id']
                        ??
                        $relation['pod_item_id']
                        ??
                        $relation['id']
                        ??
                        $relation['ID']
                        ??
                        0
                    );


                if (
                    ! empty(
                        $relation['taxonomy']
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation['taxonomy']
                        );
                }
            }


            /**
             * =================================================
             * OBJECT
             * =================================================
             */

            elseif (
                is_object(
                    $relation
                )
            ) {

                $term_id =
                    (int) (
                        $relation->term_id
                        ??
                        $relation->pod_item_id
                        ??
                        $relation->id
                        ??
                        $relation->ID
                        ??
                        0
                    );


                if (
                    ! empty(
                        $relation->taxonomy
                    )
                ) {

                    $taxonomy =
                        sanitize_key(
                            $relation->taxonomy
                        );
                }
            }


            /**
             * =================================================
             * NUMERIEK ID
             * =================================================
             *
             * In dit geval weten we de taxonomy niet uit
             * de relationship return.
             *
             * Gebruik daarom uitsluitend de veilige taxonomy
             * uit de field name.
             */

            elseif (
                is_numeric(
                    $relation
                )
            ) {

                $term_id =
                    (int) $relation;


                $taxonomy =
                    $field_taxonomy;
            }


            if ( ! $term_id ) {
                continue;
            }


            /**
             * RAW relationship bevat geen taxonomy.
             *
             * Veilige fallback:
             *
             * relationship_functie-inhoud
             *
             * →
             *
             * functie-inhoud
             */
            if (
                ! $taxonomy
            ) {

                $taxonomy =
                    $field_taxonomy;
            }


            /**
             * Geen geldige taxonomy kunnen bepalen.
             */
            if (
                ! $taxonomy ||
                ! taxonomy_exists(
                    $taxonomy
                )
            ) {
                continue;
            }


            /**
             * Term moet daadwerkelijk binnen deze taxonomy
             * bestaan.
             */
            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                is_wp_error(
                    $term
                )
            ) {
                continue;
            }


            if (
                ! isset(
                    $groups[
                        $taxonomy
                    ]
                )
            ) {

                $groups[
                    $taxonomy
                ] =
                    [];
            }


            $groups[
                $taxonomy
            ][] =
                (int) $term_id;
        }


        /**
         * IDs opschonen.
         */
        foreach (
            $groups
            as $taxonomy =>
                $ids
        ) {

            $groups[
                $taxonomy
            ] =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $ids
                            )
                        )
                    )
                );
        }


        return
            array_filter(
                $groups
            );
    }
}


/**
 * ============================================================
 * 8. OPEN VACATURE IDS
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_get_vacancy_ids'
    )
) {

    function tfsc_taxrel_v2_get_vacancy_ids(
        $source_groups
    ) {

        if (
            empty(
                $source_groups
            )
        ) {
            return [];
        }


        $post_type =
            tfsc_taxrel_v2_vacancy_post_type();


        if (
            ! post_type_exists(
                $post_type
            )
        ) {
            return [];
        }


        $tax_query = [
            'relation' =>
                'AND',
        ];


        foreach (
            $source_groups
            as $taxonomy =>
                $term_ids
        ) {

            if (
                ! taxonomy_exists(
                    $taxonomy
                ) ||
                empty(
                    $term_ids
                )
            ) {
                continue;
            }


            $tax_query[] = [
                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    array_values(
                        array_unique(
                            array_map(
                                'intval',
                                $term_ids
                            )
                        )
                    ),

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        /**
         * Minimaal één echte source clause vereist.
         */
        if (
            count(
                $tax_query
            )
            <=
            1
        ) {
            return [];
        }


        /**
         * OPEN status.
         */
        $status_taxonomy =
            tfsc_taxrel_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [
                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_taxrel_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $ids =
            get_posts(
                [
                    'post_type' =>
                        $post_type,

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        -1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if (
            empty(
                $ids
            )
        ) {
            return [];
        }


        return
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }
}


/**
 * ============================================================
 * 9. TARGET TERM IDS UIT VACATURES
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_get_target_term_ids'
    )
) {

    function tfsc_taxrel_v2_get_target_term_ids(
        $vacancy_ids,
        $taxonomy
    ) {

        if (
            empty(
                $vacancy_ids
            ) ||
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return [];
        }


        $term_ids =
            [];


        foreach (
            $vacancy_ids
            as $vacancy_id
        ) {

            $terms =
                wp_get_post_terms(
                    $vacancy_id,
                    $taxonomy,
                    [
                        'fields' =>
                            'ids',
                    ]
                );


            if (
                is_wp_error(
                    $terms
                ) ||
                empty(
                    $terms
                )
            ) {
                continue;
            }


            foreach (
                $terms
                as $term_id
            ) {

                $term_id =
                    (int) $term_id;


                if ( ! $term_id ) {
                    continue;
                }


                $term_ids[] =
                    $term_id;


                /**
                 * Bij hiërarchische taxonomies ook ancestors
                 * meenemen zodat level 0 / 1 / 2 allemaal
                 * afgeleid kunnen worden.
                 */
                if (
                    is_taxonomy_hierarchical(
                        $taxonomy
                    )
                ) {

                    $ancestors =
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        );


                    if (
                        ! empty(
                            $ancestors
                        )
                    ) {

                        $term_ids =
                            array_merge(
                                $term_ids,
                                $ancestors
                            );
                    }
                }
            }
        }


        return
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );
    }
}


/**
 * ============================================================
 * 10. EXACT HIERARCHY LEVEL
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_filter_level'
    )
) {

    function tfsc_taxrel_v2_filter_level(
        $term_ids,
        $taxonomy,
        $wanted_level
    ) {

        if (
            empty(
                $term_ids
            ) ||
            ! $taxonomy
        ) {
            return [];
        }


        /**
         * Niet-hiërarchisch:
         *
         * alles is level 0.
         */
        if (
            ! is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            return (
                0 ===
                (int) $wanted_level
            )
                ?
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
                :
            [];
        }


        $filtered =
            [];


        foreach (
            $term_ids
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $level =
                count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );


            if (
                $level ===
                (int) $wanted_level
            ) {

                $filtered[] =
                    $term_id;
            }
        }


        return
            array_values(
                array_unique(
                    $filtered
                )
            );
    }
}


/**
 * ============================================================
 * 11. QUERY ID PARSEN
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_parse_query_id'
    )
) {

    function tfsc_taxrel_v2_parse_query_id(
        $query_id
    ) {

        $query_id =
            (string) $query_id;


        if (
            ! preg_match(
                '/^archive_relationship_(.+)_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {
            return false;
        }


        $taxonomy =
            sanitize_key(
                $matches[1]
            );


        $level =
            (int) $matches[2];


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return false;
        }


        return [
            'taxonomy' =>
                $taxonomy,

            'level' =>
                $level,
        ];
    }
}


/**
 * ============================================================
 * 12. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        if (
            empty(
                $settings[
                    'term_taxonomy_id'
                ]
            )
        ) {
            return $args;
        }


        $query_id =
            (string)
            $settings[
                'term_taxonomy_id'
            ];


        $parsed =
            tfsc_taxrel_v2_parse_query_id(
                $query_id
            );


        /**
         * Geen archive_relationship Query ID:
         *
         * niets doen.
         */
        if ( ! $parsed ) {
            return $args;
        }


        /**
         * Alleen echte taxonomy term context.
         */
        if (
            ! tfsc_taxrel_v2_get_current_term()
        ) {
            return $args;
        }


        $taxonomy =
            $parsed[
                'taxonomy'
            ];


        $wanted_level =
            $parsed[
                'level'
            ];


        /**
         * Status taxonomy nooit tonen.
         */
        if (
            tfsc_taxrel_v2_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /**
         * Elementor Source moet aanwezig zijn.
         */
        if (
            empty(
                $args[
                    'taxonomy'
                ]
            )
        ) {
            return $args;
        }


        $elementor_taxonomy =
            is_array(
                $args[
                    'taxonomy'
                ]
            )
                ?
            reset(
                $args[
                    'taxonomy'
                ]
            )
                :
            $args[
                'taxonomy'
            ];


        $elementor_taxonomy =
            sanitize_key(
                $elementor_taxonomy
            );


        /**
         * Elementor Source moet overeenkomen met
         * target taxonomy uit Query ID.
         */
        if (
            $elementor_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        /**
         * ====================================================
         * SOURCE RELATIONSHIP
         * ====================================================
         */

        $source_groups =
            tfsc_taxrel_v2_get_source_relationships();


        if (
            empty(
                $source_groups
            )
        ) {

            $args[
                'include'
            ] = [
                0,
            ];

            return $args;
        }


        /**
         * ====================================================
         * OPEN VACATURES
         * ====================================================
         */

        $vacancy_ids =
            tfsc_taxrel_v2_get_vacancy_ids(
                $source_groups
            );


        if (
            empty(
                $vacancy_ids
            )
        ) {

            $args[
                'include'
            ] = [
                0,
            ];

            return $args;
        }


        /**
         * ====================================================
         * TARGET TERMS
         * ====================================================
         */

        $target_term_ids =
            tfsc_taxrel_v2_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );


        if (
            empty(
                $target_term_ids
            )
        ) {

            $args[
                'include'
            ] = [
                0,
            ];

            return $args;
        }


        /**
         * ====================================================
         * EXACT LEVEL
         * ====================================================
         */

        $target_term_ids =
            tfsc_taxrel_v2_filter_level(
                $target_term_ids,
                $taxonomy,
                $wanted_level
            );


        if (
            empty(
                $target_term_ids
            )
        ) {

            $args[
                'include'
            ] = [
                0,
            ];

            return $args;
        }


        /**
         * Custom Elementor Query ID verwijderen.
         */
        unset(
            $args[
                'term_taxonomy_id'
            ]
        );


        $args[
            'taxonomy'
        ] =
            $taxonomy;


        $args[
            'include'
        ] =
            $target_term_ids;


        $args[
            'hide_empty'
        ] =
            false;


        /**
         * Exact level is al door ons bepaald.
         */
        $args[
            'hierarchical'
        ] =
            false;


        /**
         * Marker voor sorteerfix.
         */
        $args[
            'tfsc_taxrel_v2_query'
        ] =
            1;


        $args[
            'tfsc_taxrel_v2_taxonomy'
        ] =
            $taxonomy;


        /**
         * Target markeren voor combo term links.
         */
        if (
            ! isset(
                $GLOBALS[
                    'tfsc_taxrel_v2_active_targets'
                ]
            ) ||
            ! is_array(
                $GLOBALS[
                    'tfsc_taxrel_v2_active_targets'
                ]
            )
        ) {

            $GLOBALS[
                'tfsc_taxrel_v2_active_targets'
            ] =
                [];
        }


        $GLOBALS[
            'tfsc_taxrel_v2_active_targets'
        ][
            $taxonomy
        ] =
            true;


        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * 13. UITEINDELIJKE SORTERING
 * ============================================================
 *
 * WordPress groepeert hiërarchische terms soms alsnog
 * per parent.
 *
 * Daarom sorteren we de uiteindelijke WP_Term array opnieuw
 * wanneer Elementor Order By = Name gebruikt.
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            is_admin()
        ) {
            return $terms;
        }


        if (
            empty(
                $terms
            ) ||
            ! is_array(
                $terms
            )
        ) {
            return $terms;
        }


        if (
            empty(
                $args[
                    'tfsc_taxrel_v2_query'
                ]
            )
        ) {
            return $terms;
        }


        $taxonomy =
            isset(
                $args[
                    'tfsc_taxrel_v2_taxonomy'
                ]
            )
                ?
            sanitize_key(
                $args[
                    'tfsc_taxrel_v2_taxonomy'
                ]
            )
                :
            '';


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return $terms;
        }


        /**
         * Alleen sorteren als werkelijk alle teruggegeven
         * terms bij onze taxonomy horen.
         */
        foreach (
            $terms
            as $term
        ) {

            if (
                ! (
                    $term instanceof WP_Term
                ) ||
                $term->taxonomy
                !==
                $taxonomy
            ) {
                return $terms;
            }
        }


        $orderby =
            isset(
                $args[
                    'orderby'
                ]
            )
                ?
            strtolower(
                (string)
                $args[
                    'orderby'
                ]
            )
                :
            'name';


        /**
         * Alleen Elementor Name-order corrigeren.
         */
        if (
            'name'
            !==
            $orderby
        ) {
            return $terms;
        }


        $order =
            isset(
                $args[
                    'order'
                ]
            )
                ?
            strtoupper(
                (string)
                $args[
                    'order'
                ]
            )
                :
            'ASC';


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {

            $order =
                'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                $name_a =
                    remove_accents(
                        wp_strip_all_tags(
                            $a->name
                        )
                    );


                $name_b =
                    remove_accents(
                        wp_strip_all_tags(
                            $b->name
                        )
                    );


                $comparison =
                    strnatcasecmp(
                        $name_a,
                        $name_b
                    );


                if (
                    'DESC'
                    ===
                    $order
                ) {

                    $comparison *=
                        -1;
                }


                return $comparison;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 14. HIËRARCHISCH TERMPAD
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_term_path'
    )
) {

    function tfsc_taxrel_v2_term_path(
        $term
    ) {

        if (
            ! (
                $term instanceof WP_Term
            )
        ) {
            return '';
        }


        $taxonomy =
            $term->taxonomy;


        if (
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return '';
        }


        $slugs =
            [];


        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            $ancestor_ids =
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                );


            if (
                ! empty(
                    $ancestor_ids
                )
            ) {

                $ancestor_ids =
                    array_reverse(
                        $ancestor_ids
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error(
                            $ancestor
                        ) &&
                        ! empty(
                            $ancestor->slug
                        )
                    ) {

                        $slugs[] =
                            $ancestor->slug;
                    }
                }
            }
        }


        $slugs[] =
            $term->slug;


        return
            implode(
                '/',
                array_map(
                    'rawurlencode',
                    $slugs
                )
            );
    }
}


/**
 * ============================================================
 * 15. COMBO URL BOUWEN
 * ============================================================
 */

if (
    ! function_exists(
        'tfsc_taxrel_v2_build_combo_url'
    )
) {

    function tfsc_taxrel_v2_build_combo_url(
        $target_term
    ) {

        if (
            ! (
                $target_term instanceof WP_Term
            )
        ) {
            return false;
        }


        /**
         * Source relationship opnieuw uit huidige taxonomy term.
         */
        $source_groups =
            tfsc_taxrel_v2_get_source_relationships();


        if (
            empty(
                $source_groups
            )
        ) {
            return false;
        }


        /**
         * ====================================================
         * CONTROLEREN OF COMBINATIE OPEN VACATURE OPLEVERT
         * ====================================================
         */

        $tax_query = [
            'relation' =>
                'AND',
        ];


        foreach (
            $source_groups
            as $taxonomy =>
                $term_ids
        ) {

            if (
                ! taxonomy_exists(
                    $taxonomy
                ) ||
                empty(
                    $term_ids
                )
            ) {
                continue;
            }


            $tax_query[] = [
                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    $term_ids,

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        /**
         * Target toevoegen.
         */
        $tax_query[] = [
            'taxonomy' =>
                $target_term->taxonomy,

            'field' =>
                'term_id',

            'terms' => [
                (int)
                $target_term->term_id,
            ],

            'operator' =>
                'IN',

            'include_children' =>
                is_taxonomy_hierarchical(
                    $target_term->taxonomy
                ),
        ];


        /**
         * OPEN status.
         */
        $status_taxonomy =
            tfsc_taxrel_v2_status_taxonomy();


        if (
            taxonomy_exists(
                $status_taxonomy
            )
        ) {

            $tax_query[] = [
                'taxonomy' =>
                    $status_taxonomy,

                'field' =>
                    'slug',

                'terms' => [
                    tfsc_taxrel_v2_open_status(),
                ],

                'operator' =>
                    'IN',

                'include_children' =>
                    false,
            ];
        }


        $has_result =
            get_posts(
                [
                    'post_type' =>
                        tfsc_taxrel_v2_vacancy_post_type(),

                    'post_status' =>
                        'publish',

                    'posts_per_page' =>
                        1,

                    'fields' =>
                        'ids',

                    'no_found_rows' =>
                        true,

                    'suppress_filters' =>
                        false,

                    'tax_query' =>
                        $tax_query,
                ]
            );


        if (
            empty(
                $has_result
            )
        ) {
            return false;
        }


        /**
         * ====================================================
         * COMBO URL ONDERDELEN
         * ====================================================
         */

        $parts = [
            tfsc_taxrel_v2_combo_base(),
        ];


        /**
         * Source relationship terms.
         */
        foreach (
            $source_groups
            as $taxonomy =>
                $term_ids
        ) {

            foreach (
                $term_ids
                as $term_id
            ) {

                /**
                 * Exact dezelfde term als target niet dubbel
                 * in URL opnemen.
                 */
                if (
                    $taxonomy
                    ===
                    $target_term->taxonomy
                    &&
                    (int) $term_id
                    ===
                    (int) $target_term->term_id
                ) {
                    continue;
                }


                $source_term =
                    get_term(
                        $term_id,
                        $taxonomy
                    );


                if (
                    ! (
                        $source_term instanceof WP_Term
                    ) ||
                    is_wp_error(
                        $source_term
                    )
                ) {
                    continue;
                }


                $path =
                    tfsc_taxrel_v2_term_path(
                        $source_term
                    );


                if ( ! $path ) {
                    continue;
                }


                $parts[] =
                    $taxonomy;


                $parts[] =
                    $path;
            }
        }


        /**
         * Target term.
         */
        $target_path =
            tfsc_taxrel_v2_term_path(
                $target_term
            );


        if ( ! $target_path ) {
            return false;
        }


        $parts[] =
            $target_term->taxonomy;


        $parts[] =
            $target_path;


        return
            home_url(
                '/'
                .
                implode(
                    '/',
                    array_map(
                        function(
                            $part
                        ) {

                            return
                                trim(
                                    $part,
                                    '/'
                                );
                        },
                        $parts
                    )
                )
                .
                '/'
            );
    }
}


/**
 * ============================================================
 * 16. TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        /**
         * Native link bypass respecteren.
         *
         * Wordt bijvoorbeeld gebruikt door:
         *
         * [vacature_button_url]
         */
        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            )
        ) {
            return $termlink;
        }


        if (
            is_admin()
        ) {
            return $termlink;
        }


        if (
            ! (
                $term instanceof WP_Term
            ) ||
            ! $taxonomy
        ) {
            return $termlink;
        }


        /**
         * Alleen op echte taxonomy-term archives.
         */
        if (
            ! tfsc_taxrel_v2_get_current_term()
        ) {
            return $termlink;
        }


        /**
         * Alleen target taxonomies die daadwerkelijk door
         * een archive_relationship query op deze pagina
         * zijn geactiveerd.
         */
        $active_targets =
            isset(
                $GLOBALS[
                    'tfsc_taxrel_v2_active_targets'
                ]
            ) &&
            is_array(
                $GLOBALS[
                    'tfsc_taxrel_v2_active_targets'
                ]
            )
                ?
            $GLOBALS[
                'tfsc_taxrel_v2_active_targets'
            ]
                :
            [];


        if (
            empty(
                $active_targets[
                    $taxonomy
                ]
            )
        ) {
            return $termlink;
        }


        $combo_url =
            tfsc_taxrel_v2_build_combo_url(
                $term
            );


        if (
            ! $combo_url
        ) {
            return $termlink;
        }


        return $combo_url;
    },
    40,
    3
);


/**
 * ============================================================
 * 17. ELEMENTOR EDITOR PREVIEW FALLBACK
 * ============================================================
 *
 * Elementor gebruikt in de editor niet altijd:
 *
 * elementor/loop_taxonomy/args
 *
 * Daardoor kan de live query goed werken terwijl de
 * Taxonomy Loop in de Elementor editor leeg blijft.
 *
 * Deze fallback grijpt alleen in tijdens Elementor
 * editor/preview en gebruikt de bestaande V2-functies.
 *
 * BELANGRIJK:
 *
 * De recursion guard voorkomt dat interne get_terms()
 * calls deze fallback opnieuw starten.
 */

add_filter(
    'get_terms_args',
    function(
        $args,
        $taxonomies
    ) {

        /**
         * ====================================================
         * RECURSION GUARD
         * ====================================================
         */

        static $running =
            false;


        if ( $running ) {
            return $args;
        }


        /**
         * ====================================================
         * ALLEEN ELEMENTOR EDITOR / PREVIEW
         * ====================================================
         */

        $is_elementor =
            false;


        if (
            class_exists(
                '\Elementor\Plugin'
            )
        ) {

            try {

                if (
                    isset(
                        \Elementor\Plugin::$instance->editor
                    ) &&
                    \Elementor\Plugin::$instance->editor &&
                    method_exists(
                        \Elementor\Plugin::$instance->editor,
                        'is_edit_mode'
                    ) &&
                    \Elementor\Plugin::$instance->editor
                        ->is_edit_mode()
                ) {

                    $is_elementor =
                        true;
                }


                if (
                    isset(
                        \Elementor\Plugin::$instance->preview
                    ) &&
                    \Elementor\Plugin::$instance->preview &&
                    method_exists(
                        \Elementor\Plugin::$instance->preview,
                        'is_preview_mode'
                    ) &&
                    \Elementor\Plugin::$instance->preview
                        ->is_preview_mode()
                ) {

                    $is_elementor =
                        true;
                }

            } catch ( Throwable $e ) {

                return $args;
            }
        }


        if ( ! $is_elementor ) {
            return $args;
        }


        /**
         * ====================================================
         * HUIDIGE TAXONOMY TERM
         * ====================================================
         */

        $current_term =
            tfsc_taxrel_v2_get_current_term();


        if (
            ! (
                $current_term instanceof WP_Term
            )
        ) {
            return $args;
        }


        /**
         * ====================================================
         * ÉÉN TARGET TAXONOMY
         * ====================================================
         */

        $taxonomies =
            array_values(
                array_filter(
                    (array) $taxonomies
                )
            );


        if (
            1 !==
            count(
                $taxonomies
            )
        ) {
            return $args;
        }


        $taxonomy =
            sanitize_key(
                $taxonomies[0]
            );


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return $args;
        }


        /**
         * ====================================================
         * ALLEEN VACATURE TAXONOMIES
         * ====================================================
         */

        $vacancy_post_type =
            tfsc_taxrel_v2_vacancy_post_type();


        $vacancy_taxonomies =
            get_object_taxonomies(
                $vacancy_post_type,
                'names'
            );


        if (
            ! in_array(
                $taxonomy,
                $vacancy_taxonomies,
                true
            )
        ) {
            return $args;
        }


        /**
         * ====================================================
         * VANAF HIER WORDEN FUNCTIES AANGEROEPEN DIE ZELF
         * GET_TERMS() KUNNEN GEBRUIKEN.
         *
         * DAAROM GUARD AAN.
         * ====================================================
         */

        $running =
            true;


        try {

            /**
             * Source relationship.
             */
            $source_groups =
                tfsc_taxrel_v2_get_source_relationships();


            if (
                empty(
                    $source_groups
                )
            ) {

                $args['include'] =
                    [ 0 ];

                return $args;
            }


            /**
             * Open vacatures.
             */
            $vacancy_ids =
                tfsc_taxrel_v2_get_vacancy_ids(
                    $source_groups
                );


            if (
                empty(
                    $vacancy_ids
                )
            ) {

                $args['include'] =
                    [ 0 ];

                return $args;
            }


            /**
             * Target terms uit deze vacatures.
             */
            $target_ids =
                tfsc_taxrel_v2_get_target_term_ids(
                    $vacancy_ids,
                    $taxonomy
                );


            if (
                empty(
                    $target_ids
                )
            ) {

                $args['include'] =
                    [ 0 ];

                return $args;
            }


            /**
             * Alleen relevante terms tonen.
             */
            $args['include'] =
                $target_ids;


            $args['hide_empty'] =
                false;


            return $args;

        } finally {

            /**
             * Guard altijd weer vrijgeven.
             */
            $running =
                false;
        }
    },
    40,
    2
);

/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 3
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een Beroepengids taxonomy-term:
 *
 * huidige term
 * → Pods relationship_{vacature-taxonomy}
 * → relevante OPEN vacatures
 * → target taxonomy terms uit die vacatures
 * → Elementor Taxonomy Loop
 *
 *
 * Voorbeeld:
 *
 * huidige taxonomy:
 * beroep_functie-inhoud
 *
 * huidige term:
 * Inbedrijfstellen
 *
 * relationship field:
 * relationship_functie-inhoud
 *
 * relationship:
 * functie-inhoud → Inbedrijfstellen
 *
 *
 * Elementor Query ID:
 *
 * archive_relationship_{taxonomy}_level_{nummer}
 *
 * Bijvoorbeeld:
 *
 * archive_relationship_locatie_level_2
 * archive_relationship_kennisgebied_level_0
 * archive_relationship_bedrijfssector_level_0
 *
 *
 * Elementor Source moet overeenkomen met de taxonomy
 * uit de Query ID.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_taxrel_v3_vacancy_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_taxrel_v3_status_taxonomy() {

    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}


function tfsc_taxrel_v3_open_status() {

    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


function tfsc_taxrel_v3_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. HUIDIGE TAXONOMY TERM
 * ============================================================
 *
 * Werkt live én in Elementor zolang Elementor een WP_Term
 * als queried object gebruikt.
 */

function tfsc_taxrel_v3_current_term() {

    $object = get_queried_object();


    /**
     * Normale taxonomy archive / preview.
     */
    if (
        $object instanceof WP_Term &&
        ! empty( $object->term_id ) &&
        ! empty( $object->taxonomy ) &&
        taxonomy_exists( $object->taxonomy )
    ) {
        return $object;
    }


    /**
     * Elementor editor:
     * queried object kan het Theme Builder template zijn.
     */
    if (
        is_admin() &&
        $object instanceof WP_Post
    ) {

        $settings =
            get_post_meta(
                $object->ID,
                '_elementor_page_settings',
                true
            );


        if (
            is_array( $settings ) &&
            ! empty( $settings['preview_id'] )
        ) {

            $preview_term =
                get_term(
                    (int) $settings['preview_id']
                );


            if (
                $preview_term instanceof WP_Term &&
                ! is_wp_error( $preview_term ) &&
                ! empty( $preview_term->taxonomy ) &&
                taxonomy_exists( $preview_term->taxonomy )
            ) {
                return $preview_term;
            }
        }
    }


    return false;
}


/**
 * ============================================================
 * 3. PODS OBJECT
 * ============================================================
 */

function tfsc_taxrel_v3_current_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $term = tfsc_taxrel_v3_current_term();

    if ( ! $term ) {
        return false;
    }

    $pod = pods(
        $term->taxonomy,
        (int) $term->term_id
    );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        return false;
    }

    return $pod;
}


/**
 * ============================================================
 * 4. SOURCE TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functie-inhoud
 * → functie-inhoud
 *
 * beroepengids_kennisgebied
 * → kennisgebied
 */

function tfsc_taxrel_v3_normalize_source_taxonomy( $taxonomy ) {

    $taxonomy = sanitize_key( $taxonomy );

    foreach (
        [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ]
        as $prefix
    ) {

        if ( 0 === strpos( $taxonomy, $prefix ) ) {

            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen( $prefix )
                )
            );
        }
    }

    return $taxonomy;
}


/**
 * ============================================================
 * 5. SOURCE RELATIONSHIP FIELD
 * ============================================================
 *
 * beroep_functie-inhoud
 * → relationship_functie-inhoud
 */

function tfsc_taxrel_v3_source_field() {

    $term = tfsc_taxrel_v3_current_term();
    $pod  = tfsc_taxrel_v3_current_pod();

    if (
        ! $term ||
        ! $pod
    ) {
        return '';
    }

    $fields = $pod->fields();

    if ( ! is_array( $fields ) ) {
        return '';
    }

    $normalized =
        tfsc_taxrel_v3_normalize_source_taxonomy(
            $term->taxonomy
        );

    $candidates = [
        'relationship_' . $term->taxonomy,
        'relationship_' . $normalized,
    ];

    foreach (
        array_unique( $candidates )
        as $field
    ) {

        if (
            'relationship_vacature_button_url' === $field
        ) {
            continue;
        }

        if (
            array_key_exists(
                $field,
                $fields
            )
        ) {
            return $field;
        }
    }

    return '';
}


/**
 * ============================================================
 * 6. SOURCE RELATIONSHIPS
 * ============================================================
 *
 * Resultaat:
 *
 * [
 *     'functie-inhoud' => [220]
 * ]
 */

function tfsc_taxrel_v3_source_relationships() {

    $pod = tfsc_taxrel_v3_current_pod();

    if ( ! $pod ) {
        return [];
    }

    $field =
        tfsc_taxrel_v3_source_field();

    if ( ! $field ) {
        return [];
    }

    $value =
        $pod->field( $field );

    if ( empty( $value ) ) {
        return [];
    }


    /**
     * Fallback taxonomy uit field name.
     */
    $field_taxonomy =
        sanitize_key(
            substr(
                $field,
                strlen( 'relationship_' )
            )
        );


    /**
     * Eén relationship normaliseren.
     */
    if (
        is_numeric( $value ) ||
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }


    $groups = [];


    foreach (
        (array) $value
        as $relation
    ) {

        $term_id  = 0;
        $taxonomy = '';


        if ( is_array( $relation ) ) {

            $term_id =
                (int) (
                    $relation['term_id']
                    ??
                    $relation['pod_item_id']
                    ??
                    $relation['id']
                    ??
                    $relation['ID']
                    ??
                    0
                );

            $taxonomy =
                ! empty( $relation['taxonomy'] )
                    ? sanitize_key( $relation['taxonomy'] )
                    : '';

        } elseif ( is_object( $relation ) ) {

            $term_id =
                (int) (
                    $relation->term_id
                    ??
                    $relation->pod_item_id
                    ??
                    $relation->id
                    ??
                    $relation->ID
                    ??
                    0
                );

            $taxonomy =
                ! empty( $relation->taxonomy )
                    ? sanitize_key( $relation->taxonomy )
                    : '';

        } elseif ( is_numeric( $relation ) ) {

            $term_id =
                (int) $relation;
        }


        if ( ! $taxonomy ) {
            $taxonomy = $field_taxonomy;
        }


        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }


        $term =
            get_term(
                $term_id,
                $taxonomy
            );


        if (
            ! ( $term instanceof WP_Term ) ||
            is_wp_error( $term )
        ) {
            continue;
        }


        $groups[ $taxonomy ][] =
            $term_id;
    }


    foreach (
        $groups
        as $taxonomy => $ids
    ) {

        $groups[ $taxonomy ] =
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }


    return array_filter( $groups );
}


/**
 * ============================================================
 * 7. OPEN VACATURES
 * ============================================================
 */

function tfsc_taxrel_v3_vacancy_ids( $source_groups ) {

    if ( empty( $source_groups ) ) {
        return [];
    }


    $tax_query = [
        'relation' => 'AND',
    ];


    foreach (
        $source_groups
        as $taxonomy => $ids
    ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            empty( $ids )
        ) {
            continue;
        }

        $tax_query[] = [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => $ids,
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }


    if ( count( $tax_query ) <= 1 ) {
        return [];
    }


    $status_taxonomy =
        tfsc_taxrel_v3_status_taxonomy();


    if (
        taxonomy_exists(
            $status_taxonomy
        )
    ) {

        $tax_query[] = [
            'taxonomy' =>
                $status_taxonomy,

            'field' =>
                'slug',

            'terms' => [
                tfsc_taxrel_v3_open_status(),
            ],

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    $ids =
        get_posts(
            [
                'post_type' =>
                    tfsc_taxrel_v3_vacancy_post_type(),

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    -1,

                'fields' =>
                    'ids',

                'no_found_rows' =>
                    true,

                'tax_query' =>
                    $tax_query,
            ]
        );


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 8. TARGET TERMS UIT VACATURES
 * ============================================================
 */

function tfsc_taxrel_v3_target_terms(
    $vacancy_ids,
    $taxonomy
) {

    if (
        empty( $vacancy_ids ) ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }


    $ids = [];


    foreach (
        $vacancy_ids
        as $vacancy_id
    ) {

        $terms =
            wp_get_post_terms(
                $vacancy_id,
                $taxonomy,
                [
                    'fields' => 'ids',
                ]
            );


        if (
            is_wp_error( $terms ) ||
            empty( $terms )
        ) {
            continue;
        }


        foreach (
            $terms
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $ids[] =
                $term_id;


            if (
                is_taxonomy_hierarchical(
                    $taxonomy
                )
            ) {

                $ids =
                    array_merge(
                        $ids,
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    );
            }
        }
    }


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 9. EXACT LEVEL
 * ============================================================
 */

function tfsc_taxrel_v3_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( empty( $ids ) ) {
        return [];
    }


    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return 0 === (int) $level
            ? $ids
            : [];
    }


    $result = [];


    foreach (
        $ids
        as $term_id
    ) {

        $depth =
            count(
                get_ancestors(
                    $term_id,
                    $taxonomy,
                    'taxonomy'
                )
            );


        if (
            $depth ===
            (int) $level
        ) {

            $result[] =
                (int) $term_id;
        }
    }


    return array_values(
        array_unique(
            $result
        )
    );
}


/**
 * ============================================================
 * 10. QUERY ID
 * ============================================================
 */

function tfsc_taxrel_v3_parse_query_id( $query_id ) {

    if (
        ! preg_match(
            '/^archive_relationship_(.+)_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }


    $taxonomy =
        sanitize_key(
            $matches[1]
        );


    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    return [
        'taxonomy' =>
            $taxonomy,

        'level' =>
            (int) $matches[2],
    ];
}


/**
 * ============================================================
 * 11. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

		$query_id = '';

if (
    ! empty(
        $settings['term_taxonomy_id']
    )
) {

    $query_id =
        (string)
        $settings['term_taxonomy_id'];

} elseif (
    ! empty(
        $settings['post_taxonomy_term_taxonomy_id']
    )
) {

    $query_id =
        (string)
        $settings['post_taxonomy_term_taxonomy_id'];
}




        $parsed =
            tfsc_taxrel_v3_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        if (
            ! tfsc_taxrel_v3_current_term()
        ) {
            return $args;
        }


        $taxonomy =
            $parsed['taxonomy'];


        $level =
            $parsed['level'];


        if (
            tfsc_taxrel_v3_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /**
         * Elementor Source moet overeenkomen.
         */
        $source_taxonomy =
    isset( $args['taxonomy'] )
        ? $args['taxonomy']
        : '';

if (
    empty( $source_taxonomy ) &&
    ! empty(
        $settings['post_taxonomy_query_post_type']
    )
) {

    $source_taxonomy =
        $settings['post_taxonomy_query_post_type'];
}


        if (
            is_array(
                $source_taxonomy
            )
        ) {

            $source_taxonomy =
                reset(
                    $source_taxonomy
                );
        }


        $source_taxonomy =
            sanitize_key(
                $source_taxonomy
            );


        if (
            $source_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        $source_groups =
            tfsc_taxrel_v3_source_relationships();


        $vacancy_ids =
            tfsc_taxrel_v3_vacancy_ids(
                $source_groups
            );


        $target_ids =
            tfsc_taxrel_v3_target_terms(
                $vacancy_ids,
                $taxonomy
            );


        $target_ids =
            tfsc_taxrel_v3_filter_level(
                $target_ids,
                $taxonomy,
                $level
            );


        if ( empty( $target_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            $target_ids;


        $args['hide_empty'] =
            false;


        $args['hierarchical'] =
            false;


        /**
         * Marker voor sortering.
         */
        $args['tfsc_taxrel_v3'] =
            1;


        $args['tfsc_taxrel_v3_taxonomy'] =
            $taxonomy;


        /**
         * Marker voor term links.
         */
        $GLOBALS[
            'tfsc_taxrel_v3_active_targets'
        ][ $taxonomy ] =
            true;


        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * 12. SORTERING OP NAAM
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty(
                $args['tfsc_taxrel_v3']
            ) ||
            empty( $terms ) ||
            ! is_array( $terms )
        ) {
            return $terms;
        }


        if (
            isset( $args['orderby'] ) &&
            'name'
            !==
            strtolower(
                (string) $args['orderby']
            )
        ) {
            return $terms;
        }


        $order =
            isset( $args['order'] )
                ? strtoupper( $args['order'] )
                : 'ASC';


        usort(
            $terms,
            function( $a, $b ) use ( $order ) {

                if (
                    ! ( $a instanceof WP_Term ) ||
                    ! ( $b instanceof WP_Term )
                ) {
                    return 0;
                }


                $comparison =
                    strnatcasecmp(
                        remove_accents(
                            $a->name
                        ),
                        remove_accents(
                            $b->name
                        )
                    );


                return 'DESC' === $order
                    ? -$comparison
                    : $comparison;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 13. TERM PATH
 * ============================================================
 */

function tfsc_taxrel_v3_term_path( $term ) {

    if (
        ! ( $term instanceof WP_Term )
    ) {
        return '';
    }


    $slugs = [];


    if (
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
    ) {

        $ancestors =
            array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            );


        foreach (
            $ancestors
            as $ancestor_id
        ) {

            $ancestor =
                get_term(
                    $ancestor_id,
                    $term->taxonomy
                );


            if (
                $ancestor instanceof WP_Term &&
                ! is_wp_error( $ancestor )
            ) {

                $slugs[] =
                    $ancestor->slug;
            }
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 14. COMBO URL
 * ============================================================
 */

function tfsc_taxrel_v3_combo_url(
    $target_term
) {

    if (
        ! ( $target_term instanceof WP_Term )
    ) {
        return false;
    }


    $source_groups =
        tfsc_taxrel_v3_source_relationships();


    if ( empty( $source_groups ) ) {
        return false;
    }


    $parts = [
        tfsc_taxrel_v3_combo_base(),
    ];


    foreach (
        $source_groups
        as $taxonomy => $ids
    ) {

        foreach (
            $ids
            as $term_id
        ) {

            if (
                $taxonomy ===
                $target_term->taxonomy
                &&
                (int) $term_id ===
                (int) $target_term->term_id
            ) {
                continue;
            }


            $source_term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! ( $source_term instanceof WP_Term ) ||
                is_wp_error( $source_term )
            ) {
                continue;
            }


            $parts[] =
                $taxonomy;


            $parts[] =
                tfsc_taxrel_v3_term_path(
                    $source_term
                );
        }
    }


    $parts[] =
        $target_term->taxonomy;


    $parts[] =
        tfsc_taxrel_v3_term_path(
            $target_term
        );


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                function( $part ) {

                    return trim(
                        $part,
                        '/'
                    );
                },
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 15. TERM LINKS → COMBO URL
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            )
        ) {
            return $termlink;
        }


        if (
            is_admin() ||
            ! ( $term instanceof WP_Term ) ||
            ! tfsc_taxrel_v3_current_term()
        ) {
            return $termlink;
        }


        $active =
            isset(
                $GLOBALS[
                    'tfsc_taxrel_v3_active_targets'
                ][ $taxonomy ]
            )
                ?
            $GLOBALS[
                'tfsc_taxrel_v3_active_targets'
            ][ $taxonomy ]
                :
            false;


        if ( ! $active ) {
            return $termlink;
        }


        $url =
            tfsc_taxrel_v3_combo_url(
                $term
            );


        return $url
            ? $url
            : $termlink;
    },
    40,
    3
);

/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 3.2
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een Beroepengids taxonomy-term:
 *
 * huidige term
 * → Pods relationship_{vacature-taxonomy}
 * → relevante OPEN vacatures
 * → target taxonomy terms uit die vacatures
 * → Elementor Taxonomy Loop
 *
 *
 * Voorbeeld:
 *
 * huidige taxonomy:
 * beroep_functie-inhoud
 *
 * huidige term:
 * Inbedrijfstellen
 *
 * relationship field:
 * relationship_functie-inhoud
 *
 * relationship:
 * functie-inhoud → Inbedrijfstellen
 *
 *
 * Elementor Query ID:
 *
 * archive_relationship_{taxonomy}_level_{nummer}
 *
 * Bijvoorbeeld:
 *
 * archive_relationship_locatie_level_2
 * archive_relationship_kennisgebied_level_0
 * archive_relationship_bedrijfssector_level_0
 * archive_relationship_functie-inhoud_level_0
 *
 *
 * Elementor Source moet overeenkomen met de taxonomy
 * uit de Query ID.
 *
 *
 * ============================================================
 * ELEMENTOR EDITOR
 * ============================================================
 *
 * Elementor gebruikt in de editor bij de Taxonomy Loop skin
 * andere setting-namen dan tijdens de normale frontend render.
 *
 * Frontend / normale query:
 *
 * term_taxonomy_id
 * taxonomy
 *
 * Elementor editor / render_widget:
 *
 * post_taxonomy_term_taxonomy_id
 * post_taxonomy_query_post_type
 *
 * V3.2 ondersteunt beide.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_taxrel_v32_vacancy_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_taxrel_v32_status_taxonomy() {

    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}


function tfsc_taxrel_v32_open_status() {

    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


function tfsc_taxrel_v32_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. HUIDIGE TAXONOMY TERM
 * ============================================================
 */

function tfsc_taxrel_v32_current_term() {

    $term =
        get_queried_object();


    if (
        ! ( $term instanceof WP_Term ) ||
        empty( $term->term_id ) ||
        empty( $term->taxonomy ) ||
        ! taxonomy_exists( $term->taxonomy )
    ) {
        return false;
    }


    return $term;
}


/**
 * ============================================================
 * 3. PODS OBJECT
 * ============================================================
 */

function tfsc_taxrel_v32_current_pod() {

    if (
        ! function_exists( 'pods' )
    ) {
        return false;
    }


    $term =
        tfsc_taxrel_v32_current_term();


    if ( ! $term ) {
        return false;
    }


    $pod =
        pods(
            $term->taxonomy,
            (int) $term->term_id
        );


    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        return false;
    }


    return $pod;
}


/**
 * ============================================================
 * 4. SOURCE TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functie-inhoud
 * → functie-inhoud
 *
 * beroepengids_kennisgebied
 * → kennisgebied
 */

function tfsc_taxrel_v32_normalize_source_taxonomy(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );


    foreach (
        [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ]
        as $prefix
    ) {

        if (
            0 ===
            strpos(
                $taxonomy,
                $prefix
            )
        ) {

            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen(
                        $prefix
                    )
                )
            );
        }
    }


    return $taxonomy;
}


/**
 * ============================================================
 * 5. SOURCE RELATIONSHIP FIELD
 * ============================================================
 *
 * beroep_functie-inhoud
 * → relationship_functie-inhoud
 */

function tfsc_taxrel_v32_source_field() {

    $term =
        tfsc_taxrel_v32_current_term();


    $pod =
        tfsc_taxrel_v32_current_pod();


    if (
        ! $term ||
        ! $pod
    ) {
        return '';
    }


    $fields =
        $pod->fields();


    if (
        ! is_array(
            $fields
        )
    ) {
        return '';
    }


    $normalized =
        tfsc_taxrel_v32_normalize_source_taxonomy(
            $term->taxonomy
        );


    $candidates = [
        'relationship_' . $term->taxonomy,
        'relationship_' . $normalized,
    ];


    foreach (
        array_unique(
            $candidates
        )
        as $field
    ) {

        if (
            'relationship_vacature_button_url'
            ===
            $field
        ) {
            continue;
        }


        if (
            array_key_exists(
                $field,
                $fields
            )
        ) {
            return $field;
        }
    }


    return '';
}


/**
 * ============================================================
 * 6. SOURCE RELATIONSHIPS
 * ============================================================
 *
 * Resultaat:
 *
 * [
 *     'functie-inhoud' => [ 220 ]
 * ]
 */

function tfsc_taxrel_v32_source_relationships() {

    $pod =
        tfsc_taxrel_v32_current_pod();


    if ( ! $pod ) {
        return [];
    }


    $field =
        tfsc_taxrel_v32_source_field();


    if ( ! $field ) {
        return [];
    }


    $value =
        $pod->field(
            $field
        );


    if (
        empty(
            $value
        )
    ) {
        return [];
    }


    /**
     * Fallback taxonomy uit field name.
     */
    $field_taxonomy =
        sanitize_key(
            substr(
                $field,
                strlen(
                    'relationship_'
                )
            )
        );


    /**
     * Eén relationship normaliseren.
     */
    if (
        is_numeric(
            $value
        ) ||
        is_object(
            $value
        ) ||
        (
            is_array(
                $value
            ) &&
            (
                isset(
                    $value['term_id']
                ) ||
                isset(
                    $value['pod_item_id']
                ) ||
                isset(
                    $value['id']
                ) ||
                isset(
                    $value['ID']
                )
            )
        )
    ) {

        $value = [
            $value,
        ];
    }


    $groups =
        [];


    foreach (
        (array) $value
        as $relation
    ) {

        $term_id =
            0;


        $taxonomy =
            '';


        /**
         * ARRAY
         */
        if (
            is_array(
                $relation
            )
        ) {

            $term_id =
                (int) (
                    $relation['term_id']
                    ??
                    $relation['pod_item_id']
                    ??
                    $relation['id']
                    ??
                    $relation['ID']
                    ??
                    0
                );


            if (
                ! empty(
                    $relation['taxonomy']
                )
            ) {

                $taxonomy =
                    sanitize_key(
                        $relation['taxonomy']
                    );
            }
        }


        /**
         * OBJECT
         */
        elseif (
            is_object(
                $relation
            )
        ) {

            $term_id =
                (int) (
                    $relation->term_id
                    ??
                    $relation->pod_item_id
                    ??
                    $relation->id
                    ??
                    $relation->ID
                    ??
                    0
                );


            if (
                ! empty(
                    $relation->taxonomy
                )
            ) {

                $taxonomy =
                    sanitize_key(
                        $relation->taxonomy
                    );
            }
        }


        /**
         * NUMERIEK ID
         */
        elseif (
            is_numeric(
                $relation
            )
        ) {

            $term_id =
                (int) $relation;
        }


        /**
         * Geen taxonomy in RAW return:
         *
         * relationship_functie-inhoud
         * → functie-inhoud
         */
        if (
            ! $taxonomy
        ) {

            $taxonomy =
                $field_taxonomy;
        }


        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            continue;
        }


        $term =
            get_term(
                $term_id,
                $taxonomy
            );


        if (
            ! ( $term instanceof WP_Term ) ||
            is_wp_error(
                $term
            )
        ) {
            continue;
        }


        if (
            ! isset(
                $groups[
                    $taxonomy
                ]
            )
        ) {

            $groups[
                $taxonomy
            ] =
                [];
        }


        $groups[
            $taxonomy
        ][] =
            $term_id;
    }


    foreach (
        $groups
        as $taxonomy =>
            $ids
    ) {

        $groups[
            $taxonomy
        ] =
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }


    return array_filter(
        $groups
    );
}


/**
 * ============================================================
 * 7. OPEN VACATURES
 * ============================================================
 */

function tfsc_taxrel_v32_vacancy_ids(
    $source_groups
) {

    if (
        empty(
            $source_groups
        )
    ) {
        return [];
    }


    $tax_query = [
        'relation' =>
            'AND',
    ];


    foreach (
        $source_groups
        as $taxonomy =>
            $ids
    ) {

        if (
            ! taxonomy_exists(
                $taxonomy
            ) ||
            empty(
                $ids
            )
        ) {
            continue;
        }


        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $ids,

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    if (
        count(
            $tax_query
        )
        <=
        1
    ) {
        return [];
    }


    $status_taxonomy =
        tfsc_taxrel_v32_status_taxonomy();


    if (
        taxonomy_exists(
            $status_taxonomy
        )
    ) {

        $tax_query[] = [
            'taxonomy' =>
                $status_taxonomy,

            'field' =>
                'slug',

            'terms' => [
                tfsc_taxrel_v32_open_status(),
            ],

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    $ids =
        get_posts(
            [
                'post_type' =>
                    tfsc_taxrel_v32_vacancy_post_type(),

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    -1,

                'fields' =>
                    'ids',

                'no_found_rows' =>
                    true,

                'tax_query' =>
                    $tax_query,
            ]
        );


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 8. TARGET TERMS UIT VACATURES
 * ============================================================
 */

function tfsc_taxrel_v32_target_terms(
    $vacancy_ids,
    $taxonomy
) {

    if (
        empty(
            $vacancy_ids
        ) ||
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return [];
    }


    $ids =
        [];


    foreach (
        $vacancy_ids
        as $vacancy_id
    ) {

        $terms =
            wp_get_post_terms(
                $vacancy_id,
                $taxonomy,
                [
                    'fields' =>
                        'ids',
                ]
            );


        if (
            is_wp_error(
                $terms
            ) ||
            empty(
                $terms
            )
        ) {
            continue;
        }


        foreach (
            $terms
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if (
                ! $term_id
            ) {
                continue;
            }


            $ids[] =
                $term_id;


            /**
             * Ancestors meenemen zodat level filtering
             * ook parent-levels kan teruggeven.
             */
            if (
                is_taxonomy_hierarchical(
                    $taxonomy
                )
            ) {

                $ids =
                    array_merge(
                        $ids,
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    );
            }
        }
    }


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 9. EXACT HIERARCHY LEVEL
 * ============================================================
 */

function tfsc_taxrel_v32_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if (
        empty(
            $ids
        )
    ) {
        return [];
    }


    /**
     * Niet-hiërarchisch = level 0.
     */
    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return
            0 ===
            (int) $level
                ?
            $ids
                :
            [];
    }


    $result =
        [];


    foreach (
        $ids
        as $term_id
    ) {

        $depth =
            count(
                get_ancestors(
                    $term_id,
                    $taxonomy,
                    'taxonomy'
                )
            );


        if (
            $depth ===
            (int) $level
        ) {

            $result[] =
                (int) $term_id;
        }
    }


    return array_values(
        array_unique(
            $result
        )
    );
}


/**
 * ============================================================
 * 10. QUERY ID PARSEN
 * ============================================================
 */

function tfsc_taxrel_v32_parse_query_id(
    $query_id
) {

    if (
        ! preg_match(
            '/^archive_relationship_(.+)_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }


    $taxonomy =
        sanitize_key(
            $matches[1]
        );


    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    return [
        'taxonomy' =>
            $taxonomy,

        'level' =>
            (int) $matches[2],
    ];
}


/**
 * ============================================================
 * 11. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Ondersteunt:
 *
 * FRONTEND:
 *
 * settings['term_taxonomy_id']
 * args['taxonomy']
 *
 *
 * ELEMENTOR EDITOR / render_widget:
 *
 * settings['post_taxonomy_term_taxonomy_id']
 * settings['post_taxonomy_query_post_type']
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        /**
         * ====================================================
         * QUERY ID
         * ====================================================
         */

        $query_id =
            '';


        /**
         * Normale Elementor/frontend setting.
         */
        if (
            ! empty(
                $settings[
                    'term_taxonomy_id'
                ]
            )
        ) {

            $query_id =
                (string)
                $settings[
                    'term_taxonomy_id'
                ];
        }


        /**
         * Elementor Taxonomy skin in editor/render_widget.
         */
        elseif (
            ! empty(
                $settings[
                    'post_taxonomy_term_taxonomy_id'
                ]
            )
        ) {

            $query_id =
                (string)
                $settings[
                    'post_taxonomy_term_taxonomy_id'
                ];
        }


        $parsed =
            tfsc_taxrel_v32_parse_query_id(
                $query_id
            );


        if (
            ! $parsed
        ) {
            return $args;
        }


        /**
         * Huidige Beroepengids taxonomy term.
         */
        if (
            ! tfsc_taxrel_v32_current_term()
        ) {
            return $args;
        }


        $taxonomy =
            $parsed[
                'taxonomy'
            ];


        $level =
            $parsed[
                'level'
            ];


        /**
         * Status taxonomy nooit target.
         */
        if (
            tfsc_taxrel_v32_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /**
         * ====================================================
         * ELEMENTOR SOURCE TAXONOMY
         * ====================================================
         */

        $source_taxonomy =
            '';


        /**
         * Normale frontend query args.
         */
        if (
            ! empty(
                $args[
                    'taxonomy'
                ]
            )
        ) {

            $source_taxonomy =
                $args[
                    'taxonomy'
                ];
        }


        /**
         * Elementor editor/render_widget fallback.
         */
        elseif (
            ! empty(
                $settings[
                    'post_taxonomy_query_post_type'
                ]
            )
        ) {

            $source_taxonomy =
                $settings[
                    'post_taxonomy_query_post_type'
                ];
        }


        if (
            is_array(
                $source_taxonomy
            )
        ) {

            $source_taxonomy =
                reset(
                    $source_taxonomy
                );
        }


        $source_taxonomy =
            sanitize_key(
                $source_taxonomy
            );


        /**
         * Elementor Source moet overeenkomen met
         * taxonomy uit Query ID.
         */
        if (
            $source_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        /**
         * ====================================================
         * SOURCE RELATIONSHIP
         * ====================================================
         */

        $source_groups =
            tfsc_taxrel_v32_source_relationships();


        if (
            empty(
                $source_groups
            )
        ) {

            $args[
                'include'
            ] = [
                0,
            ];

            return $args;
        }


        /**
         * ====================================================
         * OPEN VACATURES
         * ====================================================
         */

        $vacancy_ids =
            tfsc_taxrel_v32_vacancy_ids(
                $source_groups
            );


        if (
            empty(
                $vacancy_ids
            )
        ) {

            $args[
                'include'
            ] = [
                0,
            ];

            return $args;
        }


        /**
         * ====================================================
         * TARGET TERMS
         * ====================================================
         */

        $target_ids =
            tfsc_taxrel_v32_target_terms(
                $vacancy_ids,
                $taxonomy
            );


        $target_ids =
            tfsc_taxrel_v32_filter_level(
                $target_ids,
                $taxonomy,
                $level
            );


        if (
            empty(
                $target_ids
            )
        ) {

            $args[
                'include'
            ] = [
                0,
            ];

            return $args;
        }


        /**
         * Custom Query ID verwijderen voordat WP_Term_Query
         * wordt uitgevoerd.
         */
        unset(
            $args[
                'term_taxonomy_id'
            ]
        );


        /**
         * Werkelijke taxonomy query.
         */
        $args[
            'taxonomy'
        ] =
            $taxonomy;


        $args[
            'include'
        ] =
            $target_ids;


        $args[
            'hide_empty'
        ] =
            false;


        /**
         * Exact level is al door ons bepaald.
         */
        $args[
            'hierarchical'
        ] =
            false;


        /**
         * Marker voor sortering.
         */
        $args[
            'tfsc_taxrel_v32'
        ] =
            1;


        $args[
            'tfsc_taxrel_v32_taxonomy'
        ] =
            $taxonomy;


        /**
         * Marker voor combo term links.
         */
        if (
            ! isset(
                $GLOBALS[
                    'tfsc_taxrel_v32_active_targets'
                ]
            ) ||
            ! is_array(
                $GLOBALS[
                    'tfsc_taxrel_v32_active_targets'
                ]
            )
        ) {

            $GLOBALS[
                'tfsc_taxrel_v32_active_targets'
            ] =
                [];
        }


        $GLOBALS[
            'tfsc_taxrel_v32_active_targets'
        ][
            $taxonomy
        ] =
            true;


        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * 12. UITEINDELIJKE SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty(
                $args[
                    'tfsc_taxrel_v32'
                ]
            ) ||
            empty(
                $terms
            ) ||
            ! is_array(
                $terms
            )
        ) {
            return $terms;
        }


        /**
         * Alleen Name-order corrigeren.
         */
        if (
            isset(
                $args[
                    'orderby'
                ]
            ) &&
            'name'
            !==
            strtolower(
                (string)
                $args[
                    'orderby'
                ]
            )
        ) {
            return $terms;
        }


        $order =
            isset(
                $args[
                    'order'
                ]
            )
                ?
            strtoupper(
                (string)
                $args[
                    'order'
                ]
            )
                :
            'ASC';


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {

            $order =
                'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                if (
                    ! ( $a instanceof WP_Term ) ||
                    ! ( $b instanceof WP_Term )
                ) {
                    return 0;
                }


                $comparison =
                    strnatcasecmp(
                        remove_accents(
                            wp_strip_all_tags(
                                $a->name
                            )
                        ),
                        remove_accents(
                            wp_strip_all_tags(
                                $b->name
                            )
                        )
                    );


                return
                    'DESC'
                    ===
                    $order
                        ?
                    -$comparison
                        :
                    $comparison;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 13. HIËRARCHISCH TERMPAD
 * ============================================================
 */

function tfsc_taxrel_v32_term_path(
    $term
) {

    if (
        ! (
            $term instanceof WP_Term
        )
    ) {
        return '';
    }


    $slugs =
        [];


    if (
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
    ) {

        $ancestors =
            array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            );


        foreach (
            $ancestors
            as $ancestor_id
        ) {

            $ancestor =
                get_term(
                    $ancestor_id,
                    $term->taxonomy
                );


            if (
                $ancestor instanceof WP_Term &&
                ! is_wp_error(
                    $ancestor
                ) &&
                ! empty(
                    $ancestor->slug
                )
            ) {

                $slugs[] =
                    $ancestor->slug;
            }
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 14. COMBO URL
 * ============================================================
 */

function tfsc_taxrel_v32_combo_url(
    $target_term
) {

    if (
        ! (
            $target_term instanceof WP_Term
        )
    ) {
        return false;
    }


    $source_groups =
        tfsc_taxrel_v32_source_relationships();


    if (
        empty(
            $source_groups
        )
    ) {
        return false;
    }


    $parts = [
        tfsc_taxrel_v32_combo_base(),
    ];


    /**
     * Source relationship terms.
     */
    foreach (
        $source_groups
        as $taxonomy =>
            $ids
    ) {

        foreach (
            $ids
            as $term_id
        ) {

            /**
             * Exact dezelfde term niet dubbel toevoegen.
             */
            if (
                $taxonomy
                ===
                $target_term->taxonomy
                &&
                (int) $term_id
                ===
                (int) $target_term->term_id
            ) {
                continue;
            }


            $source_term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! (
                    $source_term instanceof WP_Term
                ) ||
                is_wp_error(
                    $source_term
                )
            ) {
                continue;
            }


            $path =
                tfsc_taxrel_v32_term_path(
                    $source_term
                );


            if (
                ! $path
            ) {
                continue;
            }


            $parts[] =
                $taxonomy;


            $parts[] =
                $path;
        }
    }


    /**
     * Target.
     */
    $target_path =
        tfsc_taxrel_v32_term_path(
            $target_term
        );


    if (
        ! $target_path
    ) {
        return false;
    }


    $parts[] =
        $target_term->taxonomy;


    $parts[] =
        $target_path;


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                function(
                    $part
                ) {

                    return trim(
                        $part,
                        '/'
                    );
                },
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 15. TERM LINKS → COMBO URL
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        /**
         * Native term-link bypass respecteren.
         */
        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            )
        ) {
            return $termlink;
        }


        if (
            is_admin() ||
            ! (
                $term instanceof WP_Term
            ) ||
            ! tfsc_taxrel_v32_current_term()
        ) {
            return $termlink;
        }


        $active =
            ! empty(
                $GLOBALS[
                    'tfsc_taxrel_v32_active_targets'
                ][
                    $taxonomy
                ]
            );


        if (
            ! $active
        ) {
            return $termlink;
        }


        $url =
            tfsc_taxrel_v32_combo_url(
                $term
            );


        return
            $url
                ?
            $url
                :
            $termlink;
    },
    40,
    3
);

/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 3
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een Beroepengids taxonomy-term:
 *
 * huidige term
 * → Pods relationship_{vacature-taxonomy}
 * → relevante OPEN vacatures
 * → target taxonomy terms uit die vacatures
 * → Elementor Taxonomy Loop
 *
 *
 * Voorbeeld:
 *
 * huidige taxonomy:
 * beroep_functie-inhoud
 *
 * huidige term:
 * Inbedrijfstellen
 *
 * relationship field:
 * relationship_functie-inhoud
 *
 * relationship:
 * functie-inhoud → Inbedrijfstellen
 *
 *
 * Elementor Query ID:
 *
 * archive_relationship_{taxonomy}_level_{nummer}
 *
 * Bijvoorbeeld:
 *
 * archive_relationship_locatie_level_2
 * archive_relationship_kennisgebied_level_0
 * archive_relationship_bedrijfssector_level_0
 *
 *
 * Elementor Source moet overeenkomen met de taxonomy
 * uit de Query ID.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_taxrel_v3_vacancy_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_taxrel_v3_status_taxonomy() {

    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}


function tfsc_taxrel_v3_open_status() {

    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


function tfsc_taxrel_v3_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}

/**
 * ============================================================
 * 2. HUIDIGE TAXONOMY TERM
 * ============================================================
 */

function tfsc_taxrel_v3_current_term() {

    $object = get_queried_object();


    /**
     * Normale taxonomy archive / Elementor preview.
     */
    if (
        $object instanceof WP_Term &&
        ! empty( $object->term_id ) &&
        ! empty( $object->taxonomy ) &&
        taxonomy_exists( $object->taxonomy )
    ) {
        return $object;
    }


    /**
     * Elementor editor eerste render.
     *
     * Daar is het queried object het Theme Builder template
     * in plaats van de preview taxonomy-term.
     */
    if (
        is_admin() &&
        $object instanceof WP_Post
    ) {

        $settings =
            get_post_meta(
                $object->ID,
                '_elementor_page_settings',
                true
            );


        if (
            is_array( $settings ) &&
            ! empty( $settings['preview_id'] )
        ) {

            $preview_term =
                get_term(
                    (int) $settings['preview_id']
                );


            if (
                $preview_term instanceof WP_Term &&
                ! is_wp_error( $preview_term ) &&
                taxonomy_exists(
                    $preview_term->taxonomy
                )
            ) {
                return $preview_term;
            }
        }
    }


    return false;
}



/**
 * ============================================================
 * 3. PODS OBJECT
 * ============================================================
 */

function tfsc_taxrel_v3_current_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $term = tfsc_taxrel_v3_current_term();

    if ( ! $term ) {
        return false;
    }

    $pod = pods(
        $term->taxonomy,
        (int) $term->term_id
    );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        return false;
    }

    return $pod;
}


/**
 * ============================================================
 * 4. SOURCE TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functie-inhoud
 * → functie-inhoud
 *
 * beroepengids_kennisgebied
 * → kennisgebied
 */

function tfsc_taxrel_v3_normalize_source_taxonomy( $taxonomy ) {

    $taxonomy = sanitize_key( $taxonomy );

    foreach (
        [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ]
        as $prefix
    ) {

        if ( 0 === strpos( $taxonomy, $prefix ) ) {

            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen( $prefix )
                )
            );
        }
    }

    return $taxonomy;
}


/**
 * ============================================================
 * 5. SOURCE RELATIONSHIP FIELD
 * ============================================================
 *
 * beroep_functie-inhoud
 * → relationship_functie-inhoud
 */

function tfsc_taxrel_v3_source_field() {

    $term = tfsc_taxrel_v3_current_term();
    $pod  = tfsc_taxrel_v3_current_pod();

    if (
        ! $term ||
        ! $pod
    ) {
        return '';
    }

    $fields = $pod->fields();

    if ( ! is_array( $fields ) ) {
        return '';
    }

    $normalized =
        tfsc_taxrel_v3_normalize_source_taxonomy(
            $term->taxonomy
        );

    $candidates = [
        'relationship_' . $term->taxonomy,
        'relationship_' . $normalized,
    ];

    foreach (
        array_unique( $candidates )
        as $field
    ) {

        if (
            'relationship_vacature_button_url' === $field
        ) {
            continue;
        }

        if (
            array_key_exists(
                $field,
                $fields
            )
        ) {
            return $field;
        }
    }

    return '';
}


/**
 * ============================================================
 * 6. SOURCE RELATIONSHIPS
 * ============================================================
 *
 * Resultaat:
 *
 * [
 *     'functie-inhoud' => [220]
 * ]
 */

function tfsc_taxrel_v3_source_relationships() {

    $pod = tfsc_taxrel_v3_current_pod();

    if ( ! $pod ) {
        return [];
    }

    $field =
        tfsc_taxrel_v3_source_field();

    if ( ! $field ) {
        return [];
    }

    $value =
        $pod->field( $field );

    if ( empty( $value ) ) {
        return [];
    }


    /**
     * Fallback taxonomy uit field name.
     */
    $field_taxonomy =
        sanitize_key(
            substr(
                $field,
                strlen( 'relationship_' )
            )
        );


    /**
     * Eén relationship normaliseren.
     */
    if (
        is_numeric( $value ) ||
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }


    $groups = [];


    foreach (
        (array) $value
        as $relation
    ) {

        $term_id  = 0;
        $taxonomy = '';


        if ( is_array( $relation ) ) {

            $term_id =
                (int) (
                    $relation['term_id']
                    ??
                    $relation['pod_item_id']
                    ??
                    $relation['id']
                    ??
                    $relation['ID']
                    ??
                    0
                );

            $taxonomy =
                ! empty( $relation['taxonomy'] )
                    ? sanitize_key( $relation['taxonomy'] )
                    : '';

        } elseif ( is_object( $relation ) ) {

            $term_id =
                (int) (
                    $relation->term_id
                    ??
                    $relation->pod_item_id
                    ??
                    $relation->id
                    ??
                    $relation->ID
                    ??
                    0
                );

            $taxonomy =
                ! empty( $relation->taxonomy )
                    ? sanitize_key( $relation->taxonomy )
                    : '';

        } elseif ( is_numeric( $relation ) ) {

            $term_id =
                (int) $relation;
        }


        if ( ! $taxonomy ) {
            $taxonomy = $field_taxonomy;
        }


        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }


        $term =
            get_term(
                $term_id,
                $taxonomy
            );


        if (
            ! ( $term instanceof WP_Term ) ||
            is_wp_error( $term )
        ) {
            continue;
        }


        $groups[ $taxonomy ][] =
            $term_id;
    }


    foreach (
        $groups
        as $taxonomy => $ids
    ) {

        $groups[ $taxonomy ] =
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }


    return array_filter( $groups );
}


/**
 * ============================================================
 * 7. OPEN VACATURES
 * ============================================================
 */

function tfsc_taxrel_v3_vacancy_ids( $source_groups ) {

    if ( empty( $source_groups ) ) {
        return [];
    }


    $tax_query = [
        'relation' => 'AND',
    ];


    foreach (
        $source_groups
        as $taxonomy => $ids
    ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            empty( $ids )
        ) {
            continue;
        }

        $tax_query[] = [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => $ids,
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }


    if ( count( $tax_query ) <= 1 ) {
        return [];
    }


    $status_taxonomy =
        tfsc_taxrel_v3_status_taxonomy();


    if (
        taxonomy_exists(
            $status_taxonomy
        )
    ) {

        $tax_query[] = [
            'taxonomy' =>
                $status_taxonomy,

            'field' =>
                'slug',

            'terms' => [
                tfsc_taxrel_v3_open_status(),
            ],

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    $ids =
        get_posts(
            [
                'post_type' =>
                    tfsc_taxrel_v3_vacancy_post_type(),

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    -1,

                'fields' =>
                    'ids',

                'no_found_rows' =>
                    true,

                'tax_query' =>
                    $tax_query,
            ]
        );


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 8. TARGET TERMS UIT VACATURES
 * ============================================================
 */

function tfsc_taxrel_v3_target_terms(
    $vacancy_ids,
    $taxonomy
) {

    if (
        empty( $vacancy_ids ) ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }


    $ids = [];


    foreach (
        $vacancy_ids
        as $vacancy_id
    ) {

        $terms =
            wp_get_post_terms(
                $vacancy_id,
                $taxonomy,
                [
                    'fields' => 'ids',
                ]
            );


        if (
            is_wp_error( $terms ) ||
            empty( $terms )
        ) {
            continue;
        }


        foreach (
            $terms
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $ids[] =
                $term_id;


            if (
                is_taxonomy_hierarchical(
                    $taxonomy
                )
            ) {

                $ids =
                    array_merge(
                        $ids,
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    );
            }
        }
    }


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 9. EXACT LEVEL
 * ============================================================
 */

function tfsc_taxrel_v3_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( empty( $ids ) ) {
        return [];
    }


    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return 0 === (int) $level
            ? $ids
            : [];
    }


    $result = [];


    foreach (
        $ids
        as $term_id
    ) {

        $depth =
            count(
                get_ancestors(
                    $term_id,
                    $taxonomy,
                    'taxonomy'
                )
            );


        if (
            $depth ===
            (int) $level
        ) {

            $result[] =
                (int) $term_id;
        }
    }


    return array_values(
        array_unique(
            $result
        )
    );
}


/**
 * ============================================================
 * 10. QUERY ID
 * ============================================================
 */

function tfsc_taxrel_v3_parse_query_id( $query_id ) {

    if (
        ! preg_match(
            '/^archive_relationship_(.+)_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }


    $taxonomy =
        sanitize_key(
            $matches[1]
        );


    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    return [
        'taxonomy' =>
            $taxonomy,

        'level' =>
            (int) $matches[2],
    ];
}


/**
 * ============================================================
 * 11. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

		$query_id = '';

if (
    ! empty(
        $settings['term_taxonomy_id']
    )
) {

    $query_id =
        (string)
        $settings['term_taxonomy_id'];

} elseif (
    ! empty(
        $settings['post_taxonomy_term_taxonomy_id']
    )
) {

    $query_id =
        (string)
        $settings['post_taxonomy_term_taxonomy_id'];
}




        $parsed =
            tfsc_taxrel_v3_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        if (
            ! tfsc_taxrel_v3_current_term()
        ) {
            return $args;
        }


        $taxonomy =
            $parsed['taxonomy'];


        $level =
            $parsed['level'];


        if (
            tfsc_taxrel_v3_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /**
         * Elementor Source moet overeenkomen.
         */
        $source_taxonomy =
    isset( $args['taxonomy'] )
        ? $args['taxonomy']
        : '';

if (
    empty( $source_taxonomy ) &&
    ! empty(
        $settings['post_taxonomy_query_post_type']
    )
) {

    $source_taxonomy =
        $settings['post_taxonomy_query_post_type'];
}


        if (
            is_array(
                $source_taxonomy
            )
        ) {

            $source_taxonomy =
                reset(
                    $source_taxonomy
                );
        }


        $source_taxonomy =
            sanitize_key(
                $source_taxonomy
            );


        if (
            $source_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        $source_groups =
            tfsc_taxrel_v3_source_relationships();


        $vacancy_ids =
            tfsc_taxrel_v3_vacancy_ids(
                $source_groups
            );


        $target_ids =
            tfsc_taxrel_v3_target_terms(
                $vacancy_ids,
                $taxonomy
            );


        $target_ids =
            tfsc_taxrel_v3_filter_level(
                $target_ids,
                $taxonomy,
                $level
            );


        if ( empty( $target_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            $target_ids;


        $args['hide_empty'] =
            false;


        $args['hierarchical'] =
            false;


        /**
         * Marker voor sortering.
         */
        $args['tfsc_taxrel_v3'] =
            1;


        $args['tfsc_taxrel_v3_taxonomy'] =
            $taxonomy;


        /**
         * Marker voor term links.
         */
        $GLOBALS[
            'tfsc_taxrel_v3_active_targets'
        ][ $taxonomy ] =
            true;


        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * 12. SORTERING OP NAAM
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty(
                $args['tfsc_taxrel_v3']
            ) ||
            empty( $terms ) ||
            ! is_array( $terms )
        ) {
            return $terms;
        }


        if (
            isset( $args['orderby'] ) &&
            'name'
            !==
            strtolower(
                (string) $args['orderby']
            )
        ) {
            return $terms;
        }


        $order =
            isset( $args['order'] )
                ? strtoupper( $args['order'] )
                : 'ASC';


        usort(
            $terms,
            function( $a, $b ) use ( $order ) {

                if (
                    ! ( $a instanceof WP_Term ) ||
                    ! ( $b instanceof WP_Term )
                ) {
                    return 0;
                }


                $comparison =
                    strnatcasecmp(
                        remove_accents(
                            $a->name
                        ),
                        remove_accents(
                            $b->name
                        )
                    );


                return 'DESC' === $order
                    ? -$comparison
                    : $comparison;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 13. TERM PATH
 * ============================================================
 */

function tfsc_taxrel_v3_term_path( $term ) {

    if (
        ! ( $term instanceof WP_Term )
    ) {
        return '';
    }


    $slugs = [];


    if (
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
    ) {

        $ancestors =
            array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            );


        foreach (
            $ancestors
            as $ancestor_id
        ) {

            $ancestor =
                get_term(
                    $ancestor_id,
                    $term->taxonomy
                );


            if (
                $ancestor instanceof WP_Term &&
                ! is_wp_error( $ancestor )
            ) {

                $slugs[] =
                    $ancestor->slug;
            }
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 14. COMBO URL
 * ============================================================
 */

function tfsc_taxrel_v3_combo_url(
    $target_term
) {

    if (
        ! ( $target_term instanceof WP_Term )
    ) {
        return false;
    }


    $source_groups =
        tfsc_taxrel_v3_source_relationships();


    if ( empty( $source_groups ) ) {
        return false;
    }


    $parts = [
        tfsc_taxrel_v3_combo_base(),
    ];


    foreach (
        $source_groups
        as $taxonomy => $ids
    ) {

        foreach (
            $ids
            as $term_id
        ) {

            if (
                $taxonomy ===
                $target_term->taxonomy
                &&
                (int) $term_id ===
                (int) $target_term->term_id
            ) {
                continue;
            }


            $source_term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! ( $source_term instanceof WP_Term ) ||
                is_wp_error( $source_term )
            ) {
                continue;
            }


            $parts[] =
                $taxonomy;


            $parts[] =
                tfsc_taxrel_v3_term_path(
                    $source_term
                );
        }
    }


    $parts[] =
        $target_term->taxonomy;


    $parts[] =
        tfsc_taxrel_v3_term_path(
            $target_term
        );


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                function( $part ) {

                    return trim(
                        $part,
                        '/'
                    );
                },
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 15. TERM LINKS → COMBO URL
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            )
        ) {
            return $termlink;
        }


        if (
            is_admin() ||
            ! ( $term instanceof WP_Term ) ||
            ! tfsc_taxrel_v3_current_term()
        ) {
            return $termlink;
        }


        $active =
            isset(
                $GLOBALS[
                    'tfsc_taxrel_v3_active_targets'
                ][ $taxonomy ]
            )
                ?
            $GLOBALS[
                'tfsc_taxrel_v3_active_targets'
            ][ $taxonomy ]
                :
            false;


        if ( ! $active ) {
            return $termlink;
        }


        $url =
            tfsc_taxrel_v3_combo_url(
                $term
            );


        return $url
            ? $url
            : $termlink;
    },
    40,
    3
);

add_shortcode(
    'tfsc_taxonomy_hook_debug',
    function() {

        global $wp_filter;

        $hook = 'elementor/loop_taxonomy/args';

        if (
            empty( $wp_filter[ $hook ] )
        ) {
            return '<pre>Geen callbacks gevonden.</pre>';
        }

        $callbacks =
            $wp_filter[ $hook ]->callbacks
            ?? [];

        $output = [];

        foreach (
            $callbacks
            as $priority => $items
        ) {

            foreach (
                $items
                as $item
            ) {

                $function =
                    $item['function']
                    ?? null;

                $name = '';

                if (
                    is_string( $function )
                ) {

                    $name =
                        $function;

                } elseif (
                    is_array( $function ) &&
                    count( $function ) === 2
                ) {

                    $left =
                        is_object( $function[0] )
                            ? get_class( $function[0] )
                            : (string) $function[0];

                    $name =
                        $left
                        .
                        '::'
                        .
                        $function[1];

                } elseif (
                    $function instanceof Closure
                ) {

                    try {

                        $reflection =
                            new ReflectionFunction(
                                $function
                            );

                        $name =
                            'Closure @ '
                            .
                            $reflection->getFileName()
                            .
                            ':'
                            .
                            $reflection->getStartLine();

                    } catch ( Throwable $e ) {

                        $name =
                            'Closure';
                    }

                } else {

                    $name =
                        'Onbekende callback';
                }

                $output[] = [
                    'priority' =>
                        $priority,

                    'callback' =>
                        $name,

                    'accepted_args' =>
                        $item['accepted_args']
                        ?? null,
                ];
            }
        }


        return
            '<pre style="white-space:pre-wrap;">'
            .
            esc_html(
                print_r(
                    $output,
                    true
                )
            )
            .
            '</pre>';
    }
);

