/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 3
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een Beroepengids taxonomy-term:
 *
 * huidige term
 * → Pods relationship_{vacature-taxonomy}
 * → relevante OPEN vacatures
 * → target taxonomy terms uit die vacatures
 * → Elementor Taxonomy Loop
 *
 *
 * Voorbeeld:
 *
 * huidige taxonomy:
 * beroep_functie-inhoud
 *
 * huidige term:
 * Inbedrijfstellen
 *
 * relationship field:
 * relationship_functie-inhoud
 *
 * relationship:
 * functie-inhoud → Inbedrijfstellen
 *
 *
 * Elementor Query ID:
 *
 * archive_relationship_{taxonomy}_level_{nummer}
 *
 * Bijvoorbeeld:
 *
 * archive_relationship_locatie_level_2
 * archive_relationship_kennisgebied_level_0
 * archive_relationship_bedrijfssector_level_0
 *
 *
 * Elementor Source moet overeenkomen met de taxonomy
 * uit de Query ID.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_taxrel_v3_vacancy_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_taxrel_v3_status_taxonomy() {

    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}


function tfsc_taxrel_v3_open_status() {

    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


function tfsc_taxrel_v3_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. HUIDIGE TAXONOMY TERM
 * ============================================================
 *
 * Werkt live én in Elementor zolang Elementor een WP_Term
 * als queried object gebruikt.
 */

function tfsc_taxrel_v3_current_term() {

    $object = get_queried_object();

    /**
     * Normale taxonomy archive / Elementor preview iframe.
     */
    if (
        $object instanceof WP_Term &&
        ! empty( $object->term_id ) &&
        ! empty( $object->taxonomy ) &&
        taxonomy_exists( $object->taxonomy )
    ) {

        /**
         * Elementor editor rendert daarna ook nog vanuit
         * wp-admin, waar het queried object het template is.
         *
         * Daarom bewaren we de huidige preview-term kort.
         */
        if (
            is_user_logged_in()
        ) {

            set_transient(
                'tfsc_taxrel_v3_preview_'
                . get_current_user_id(),
                [
                    'term_id'  => (int) $object->term_id,
                    'taxonomy' => $object->taxonomy,
                ],
                5 * MINUTE_IN_SECONDS
            );
        }

        return $object;
    }


    /**
     * Elementor editor eerste admin-render.
     */
    if (
        is_admin() &&
        $object instanceof WP_Post &&
        is_user_logged_in()
    ) {

        $preview =
            get_transient(
                'tfsc_taxrel_v3_preview_'
                . get_current_user_id()
            );


        if (
            is_array( $preview ) &&
            ! empty( $preview['term_id'] ) &&
            ! empty( $preview['taxonomy'] ) &&
            taxonomy_exists( $preview['taxonomy'] )
        ) {

            /**
             * Controleren of Elementor momenteel daadwerkelijk
             * een archive van deze taxonomy previewt.
             */
            $settings =
                get_post_meta(
                    $object->ID,
                    '_elementor_page_settings',
                    true
                );

            $preview_type =
                is_array( $settings )
                && ! empty( $settings['preview_type'] )
                    ? $settings['preview_type']
                    : '';

            if (
                $preview_type ===
                'taxonomy/' . $preview['taxonomy']
            ) {

                $term =
                    get_term(
                        (int) $preview['term_id'],
                        $preview['taxonomy']
                    );

                if (
                    $term instanceof WP_Term &&
                    ! is_wp_error( $term )
                ) {
                    return $term;
                }
            }
        }
    }


    return false;
}


/**
 * ============================================================
 * 3. PODS OBJECT
 * ============================================================
 */

function tfsc_taxrel_v3_current_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $term = tfsc_taxrel_v3_current_term();

    if ( ! $term ) {
        return false;
    }

    $pod = pods(
        $term->taxonomy,
        (int) $term->term_id
    );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        return false;
    }

    return $pod;
}


/**
 * ============================================================
 * 4. SOURCE TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functie-inhoud
 * → functie-inhoud
 *
 * beroepengids_kennisgebied
 * → kennisgebied
 */

function tfsc_taxrel_v3_normalize_source_taxonomy( $taxonomy ) {

    $taxonomy = sanitize_key( $taxonomy );

    foreach (
        [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ]
        as $prefix
    ) {

        if ( 0 === strpos( $taxonomy, $prefix ) ) {

            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen( $prefix )
                )
            );
        }
    }

    return $taxonomy;
}


/**
 * ============================================================
 * 5. SOURCE RELATIONSHIP FIELD
 * ============================================================
 *
 * beroep_functie-inhoud
 * → relationship_functie-inhoud
 */

function tfsc_taxrel_v3_source_field() {

    $term = tfsc_taxrel_v3_current_term();
    $pod  = tfsc_taxrel_v3_current_pod();

    if (
        ! $term ||
        ! $pod
    ) {
        return '';
    }

    $fields = $pod->fields();

    if ( ! is_array( $fields ) ) {
        return '';
    }

    $normalized =
        tfsc_taxrel_v3_normalize_source_taxonomy(
            $term->taxonomy
        );

    $candidates = [
        'relationship_' . $term->taxonomy,
        'relationship_' . $normalized,
    ];

    foreach (
        array_unique( $candidates )
        as $field
    ) {

        if (
            'relationship_vacature_button_url' === $field
        ) {
            continue;
        }

        if (
            array_key_exists(
                $field,
                $fields
            )
        ) {
            return $field;
        }
    }

    return '';
}


/**
 * ============================================================
 * 6. SOURCE RELATIONSHIPS
 * ============================================================
 *
 * Resultaat:
 *
 * [
 *     'functie-inhoud' => [220]
 * ]
 */

function tfsc_taxrel_v3_source_relationships() {

    $pod = tfsc_taxrel_v3_current_pod();

    if ( ! $pod ) {
        return [];
    }

    $field =
        tfsc_taxrel_v3_source_field();

    if ( ! $field ) {
        return [];
    }

    $value =
        $pod->field( $field );

    if ( empty( $value ) ) {
        return [];
    }


    /**
     * Fallback taxonomy uit field name.
     */
    $field_taxonomy =
        sanitize_key(
            substr(
                $field,
                strlen( 'relationship_' )
            )
        );


    /**
     * Eén relationship normaliseren.
     */
    if (
        is_numeric( $value ) ||
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }


    $groups = [];


    foreach (
        (array) $value
        as $relation
    ) {

        $term_id  = 0;
        $taxonomy = '';


        if ( is_array( $relation ) ) {

            $term_id =
                (int) (
                    $relation['term_id']
                    ??
                    $relation['pod_item_id']
                    ??
                    $relation['id']
                    ??
                    $relation['ID']
                    ??
                    0
                );

            $taxonomy =
                ! empty( $relation['taxonomy'] )
                    ? sanitize_key( $relation['taxonomy'] )
                    : '';

        } elseif ( is_object( $relation ) ) {

            $term_id =
                (int) (
                    $relation->term_id
                    ??
                    $relation->pod_item_id
                    ??
                    $relation->id
                    ??
                    $relation->ID
                    ??
                    0
                );

            $taxonomy =
                ! empty( $relation->taxonomy )
                    ? sanitize_key( $relation->taxonomy )
                    : '';

        } elseif ( is_numeric( $relation ) ) {

            $term_id =
                (int) $relation;
        }


        if ( ! $taxonomy ) {
            $taxonomy = $field_taxonomy;
        }


        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }


        $term =
            get_term(
                $term_id,
                $taxonomy
            );


        if (
            ! ( $term instanceof WP_Term ) ||
            is_wp_error( $term )
        ) {
            continue;
        }


        $groups[ $taxonomy ][] =
            $term_id;
    }


    foreach (
        $groups
        as $taxonomy => $ids
    ) {

        $groups[ $taxonomy ] =
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }


    return array_filter( $groups );
}


/**
 * ============================================================
 * 7. OPEN VACATURES
 * ============================================================
 */

function tfsc_taxrel_v3_vacancy_ids( $source_groups ) {

    if ( empty( $source_groups ) ) {
        return [];
    }


    $tax_query = [
        'relation' => 'AND',
    ];


    foreach (
        $source_groups
        as $taxonomy => $ids
    ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            empty( $ids )
        ) {
            continue;
        }

        $tax_query[] = [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => $ids,
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }


    if ( count( $tax_query ) <= 1 ) {
        return [];
    }


    $status_taxonomy =
        tfsc_taxrel_v3_status_taxonomy();


    if (
        taxonomy_exists(
            $status_taxonomy
        )
    ) {

        $tax_query[] = [
            'taxonomy' =>
                $status_taxonomy,

            'field' =>
                'slug',

            'terms' => [
                tfsc_taxrel_v3_open_status(),
            ],

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    $ids =
        get_posts(
            [
                'post_type' =>
                    tfsc_taxrel_v3_vacancy_post_type(),

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    -1,

                'fields' =>
                    'ids',

                'no_found_rows' =>
                    true,

                'tax_query' =>
                    $tax_query,
            ]
        );


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 8. TARGET TERMS UIT VACATURES
 * ============================================================
 */

function tfsc_taxrel_v3_target_terms(
    $vacancy_ids,
    $taxonomy
) {

    if (
        empty( $vacancy_ids ) ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }


    $ids = [];


    foreach (
        $vacancy_ids
        as $vacancy_id
    ) {

        $terms =
            wp_get_post_terms(
                $vacancy_id,
                $taxonomy,
                [
                    'fields' => 'ids',
                ]
            );


        if (
            is_wp_error( $terms ) ||
            empty( $terms )
        ) {
            continue;
        }


        foreach (
            $terms
            as $term_id
        ) {

            $term_id =
                (int) $term_id;


            if ( ! $term_id ) {
                continue;
            }


            $ids[] =
                $term_id;


            if (
                is_taxonomy_hierarchical(
                    $taxonomy
                )
            ) {

                $ids =
                    array_merge(
                        $ids,
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    );
            }
        }
    }


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 9. EXACT LEVEL
 * ============================================================
 */

function tfsc_taxrel_v3_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( empty( $ids ) ) {
        return [];
    }


    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return 0 === (int) $level
            ? $ids
            : [];
    }


    $result = [];


    foreach (
        $ids
        as $term_id
    ) {

        $depth =
            count(
                get_ancestors(
                    $term_id,
                    $taxonomy,
                    'taxonomy'
                )
            );


        if (
            $depth ===
            (int) $level
        ) {

            $result[] =
                (int) $term_id;
        }
    }


    return array_values(
        array_unique(
            $result
        )
    );
}


/**
 * ============================================================
 * 10. QUERY ID
 * ============================================================
 */

function tfsc_taxrel_v3_parse_query_id( $query_id ) {

    if (
        ! preg_match(
            '/^archive_relationship_(.+)_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }


    $taxonomy =
        sanitize_key(
            $matches[1]
        );


    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }


    return [
        'taxonomy' =>
            $taxonomy,

        'level' =>
            (int) $matches[2],
    ];
}


/**
 * ============================================================
 * 11. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

		$query_id = '';

if (
    ! empty(
        $settings['term_taxonomy_id']
    )
) {

    $query_id =
        (string)
        $settings['term_taxonomy_id'];

} elseif (
    ! empty(
        $settings['post_taxonomy_term_taxonomy_id']
    )
) {

    $query_id =
        (string)
        $settings['post_taxonomy_term_taxonomy_id'];
}




        $parsed =
            tfsc_taxrel_v3_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        if (
            ! tfsc_taxrel_v3_current_term()
        ) {
            return $args;
        }


        $taxonomy =
            $parsed['taxonomy'];


        $level =
            $parsed['level'];


        if (
            tfsc_taxrel_v3_status_taxonomy()
            ===
            $taxonomy
        ) {
            return $args;
        }


        /**
         * Elementor Source moet overeenkomen.
         */
        $source_taxonomy =
    isset( $args['taxonomy'] )
        ? $args['taxonomy']
        : '';

if (
    empty( $source_taxonomy ) &&
    ! empty(
        $settings['post_taxonomy_query_post_type']
    )
) {

    $source_taxonomy =
        $settings['post_taxonomy_query_post_type'];
}


        if (
            is_array(
                $source_taxonomy
            )
        ) {

            $source_taxonomy =
                reset(
                    $source_taxonomy
                );
        }


        $source_taxonomy =
            sanitize_key(
                $source_taxonomy
            );


        if (
            $source_taxonomy
            !==
            $taxonomy
        ) {
            return $args;
        }


        $source_groups =
            tfsc_taxrel_v3_source_relationships();


        $vacancy_ids =
            tfsc_taxrel_v3_vacancy_ids(
                $source_groups
            );


        $target_ids =
            tfsc_taxrel_v3_target_terms(
                $vacancy_ids,
                $taxonomy
            );


        $target_ids =
            tfsc_taxrel_v3_filter_level(
                $target_ids,
                $taxonomy,
                $level
            );


        if ( empty( $target_ids ) ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;


        $args['include'] =
            $target_ids;


        $args['hide_empty'] =
            false;


        $args['hierarchical'] =
            false;


        /**
         * Marker voor sortering.
         */
        $args['tfsc_taxrel_v3'] =
            1;


        $args['tfsc_taxrel_v3_taxonomy'] =
            $taxonomy;


        /**
         * Marker voor term links.
         */
        $GLOBALS[
            'tfsc_taxrel_v3_active_targets'
        ][ $taxonomy ] =
            true;


        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * 12. SORTERING OP NAAM
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty(
                $args['tfsc_taxrel_v3']
            ) ||
            empty( $terms ) ||
            ! is_array( $terms )
        ) {
            return $terms;
        }


        if (
            isset( $args['orderby'] ) &&
            'name'
            !==
            strtolower(
                (string) $args['orderby']
            )
        ) {
            return $terms;
        }


        $order =
            isset( $args['order'] )
                ? strtoupper( $args['order'] )
                : 'ASC';


        usort(
            $terms,
            function( $a, $b ) use ( $order ) {

                if (
                    ! ( $a instanceof WP_Term ) ||
                    ! ( $b instanceof WP_Term )
                ) {
                    return 0;
                }


                $comparison =
                    strnatcasecmp(
                        remove_accents(
                            $a->name
                        ),
                        remove_accents(
                            $b->name
                        )
                    );


                return 'DESC' === $order
                    ? -$comparison
                    : $comparison;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 13. TERM PATH
 * ============================================================
 */

function tfsc_taxrel_v3_term_path( $term ) {

    if (
        ! ( $term instanceof WP_Term )
    ) {
        return '';
    }


    $slugs = [];


    if (
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
    ) {

        $ancestors =
            array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            );


        foreach (
            $ancestors
            as $ancestor_id
        ) {

            $ancestor =
                get_term(
                    $ancestor_id,
                    $term->taxonomy
                );


            if (
                $ancestor instanceof WP_Term &&
                ! is_wp_error( $ancestor )
            ) {

                $slugs[] =
                    $ancestor->slug;
            }
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 14. COMBO URL
 * ============================================================
 */

function tfsc_taxrel_v3_combo_url(
    $target_term
) {

    if (
        ! ( $target_term instanceof WP_Term )
    ) {
        return false;
    }


    $source_groups =
        tfsc_taxrel_v3_source_relationships();


    if ( empty( $source_groups ) ) {
        return false;
    }


    $parts = [
        tfsc_taxrel_v3_combo_base(),
    ];


    foreach (
        $source_groups
        as $taxonomy => $ids
    ) {

        foreach (
            $ids
            as $term_id
        ) {

            if (
                $taxonomy ===
                $target_term->taxonomy
                &&
                (int) $term_id ===
                (int) $target_term->term_id
            ) {
                continue;
            }


            $source_term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! ( $source_term instanceof WP_Term ) ||
                is_wp_error( $source_term )
            ) {
                continue;
            }


            $parts[] =
                $taxonomy;


            $parts[] =
                tfsc_taxrel_v3_term_path(
                    $source_term
                );
        }
    }


    $parts[] =
        $target_term->taxonomy;


    $parts[] =
        tfsc_taxrel_v3_term_path(
            $target_term
        );


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                function( $part ) {

                    return trim(
                        $part,
                        '/'
                    );
                },
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 15. TERM LINKS → COMBO URL
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            )
        ) {
            return $termlink;
        }


        if (
            is_admin() ||
            ! ( $term instanceof WP_Term ) ||
            ! tfsc_taxrel_v3_current_term()
        ) {
            return $termlink;
        }


        $active =
            isset(
                $GLOBALS[
                    'tfsc_taxrel_v3_active_targets'
                ][ $taxonomy ]
            )
                ?
            $GLOBALS[
                'tfsc_taxrel_v3_active_targets'
            ][ $taxonomy ]
                :
            false;


        if ( ! $active ) {
            return $termlink;
        }


        $url =
            tfsc_taxrel_v3_combo_url(
                $term
            );


        return $url
            ? $url
            : $termlink;
    },
    40,
    3
);

/**
 * TFSC - Generic Derived Relationship Taxonomy Terms
 *
 * Query ID:
 * relationship_{taxonomy}_level_{nummer}
 *
 * Voorbeelden:
 * relationship_locatie_level_1
 * relationship_functie-inhoud_level_0
 * relationship_bedrijfssector_level_0
 *
 * Elementor Filter by Depth: UIT
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

function tfsc_derived_rel_v2_vacancy_post_type() {
    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}

function tfsc_derived_rel_v2_status_taxonomy() {
    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}

function tfsc_derived_rel_v2_open_status() {
    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}

function tfsc_derived_rel_v2_combo_base() {
    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * CONTEXT + PODS
 * ============================================================
 */

function tfsc_derived_rel_v2_get_context_post_id() {

    static $resolved = null;

    if ( null !== $resolved ) {
        return $resolved;
    }

    $resolved = 0;
    $object   = get_queried_object();

    /**
     * Normale frontend.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' !== get_post_type( $object->ID )
    ) {
        return $resolved = (int) $object->ID;
    }

    /**
     * Elementor Theme Builder.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' === get_post_type( $object->ID )
    ) {

        $template_id = (int) $object->ID;

        if (
            did_action( 'elementor/loaded' ) &&
            class_exists( '\Elementor\Plugin' )
        ) {
            try {
                $document =
                    \Elementor\Plugin::$instance
                        ->documents
                        ->get( $template_id );

                if ( $document ) {
                    $preview_id = absint(
                        $document->get_settings( 'preview_id' )
                    );

                    if (
                        $preview_id &&
                        'elementor_library' !== get_post_type( $preview_id )
                    ) {
                        return $resolved = $preview_id;
                    }
                }
            } catch ( Throwable $e ) {
                // Meta fallback hieronder.
            }
        }

        $settings = get_post_meta(
            $template_id,
            '_elementor_page_settings',
            true
        );

        if (
            is_array( $settings ) &&
            ! empty( $settings['preview_id'] )
        ) {
            $preview_id = absint( $settings['preview_id'] );

            if (
                $preview_id &&
                'elementor_library' !== get_post_type( $preview_id )
            ) {
                return $resolved = $preview_id;
            }
        }
    }

    /**
     * WordPress/Elementor preview fallback.
     */
    if ( ! empty( $_GET['preview_id'] ) ) {

        $preview_id = absint(
            wp_unslash( $_GET['preview_id'] )
        );

        if (
            $preview_id &&
            'elementor_library' !== get_post_type( $preview_id )
        ) {
            return $resolved = $preview_id;
        }
    }

    /**
     * Laatste fallback.
     */
    global $post;

    if (
        $post instanceof WP_Post &&
        'elementor_library' !== get_post_type( $post->ID )
    ) {
        return $resolved = (int) $post->ID;
    }

    return 0;
}


function tfsc_derived_rel_v2_get_current_pod() {

    static $pod = null;
    static $resolved = false;

    if ( $resolved ) {
        return $pod;
    }

    $resolved = true;

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $post_id = tfsc_derived_rel_v2_get_context_post_id();

    if ( ! $post_id ) {
        return false;
    }

    $post_type = get_post_type( $post_id );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods( $post_type, $post_id );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        $pod = false;
    }

    return $pod;
}


/**
 * ============================================================
 * RELATIONSHIPS
 * ============================================================
 */

function tfsc_derived_rel_v2_has_relationship_field(
    $pod,
    $taxonomy
) {

    if ( ! $pod || ! $taxonomy ) {
        return false;
    }

    $fields = $pod->fields();

    return
        is_array( $fields ) &&
        array_key_exists(
            'relationship_' . $taxonomy,
            $fields
        );
}


function tfsc_derived_rel_v2_get_relationship_term_ids(
    $pod,
    $field_name,
    $taxonomy
) {

    static $cache = [];

    if (
        ! $pod ||
        ! $field_name ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }

    $post_id = tfsc_derived_rel_v2_get_context_post_id();
    $key     = $post_id . '|' . $field_name . '|' . $taxonomy;

    if ( isset( $cache[ $key ] ) ) {
        return $cache[ $key ];
    }

    $ids = [];

    /**
     * Eerst Pods traversal.
     */
    $traversed =
        $pod->field(
            $field_name . '.term_id'
        );

    foreach ( (array) $traversed as $id ) {
        if ( is_numeric( $id ) ) {
            $ids[] = (int) $id;
        }
    }

    /**
     * RAW relationship fallback.
     */
    if ( ! $ids ) {

        $relations =
            $pod->field( $field_name );

        if (
            is_numeric( $relations ) ||
            is_object( $relations ) ||
            (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['pod_item_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            )
        ) {
            $relations = [ $relations ];
        }

        foreach ( (array) $relations as $relation ) {

            if ( is_numeric( $relation ) ) {
                $ids[] = (int) $relation;
                continue;
            }

            if ( is_array( $relation ) ) {
                $id = $relation['term_id']
                    ?? $relation['pod_item_id']
                    ?? $relation['id']
                    ?? $relation['ID']
                    ?? 0;
            } elseif ( is_object( $relation ) ) {
                $id = $relation->term_id
                    ?? $relation->pod_item_id
                    ?? $relation->id
                    ?? $relation->ID
                    ?? 0;
            } else {
                $id = 0;
            }

            if ( $id ) {
                $ids[] = (int) $id;
            }
        }
    }

    $ids = array_values(
        array_unique(
            array_filter(
                array_map( 'intval', $ids )
            )
        )
    );

    /**
     * Alleen geldige IDs uit de juiste taxonomy.
     */
    $valid = [];

    foreach ( $ids as $id ) {

        $term = get_term( $id, $taxonomy );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            $valid[] = $id;
        }
    }

    return $cache[ $key ] = $valid;
}


function tfsc_derived_rel_v2_get_function_ids( $pod ) {

    return tfsc_derived_rel_v2_get_relationship_term_ids(
        $pod,
        'relationship_functienaam',
        'functienaam'
    );
}


/**
 * ============================================================
 * VACATURES + TARGET TERMS
 * ============================================================
 */

function tfsc_derived_rel_v2_get_vacancy_ids(
    $function_ids
) {

    static $cache = [];

    $function_ids = array_values(
        array_unique(
            array_map( 'intval', (array) $function_ids )
        )
    );

    sort( $function_ids );

    $key = implode( ',', $function_ids );

    if ( isset( $cache[ $key ] ) ) {
        return $cache[ $key ];
    }

    if (
        ! $function_ids ||
        ! taxonomy_exists( 'functienaam' )
    ) {
        return [];
    }

    $post_type =
        tfsc_derived_rel_v2_vacancy_post_type();

    if ( ! post_type_exists( $post_type ) ) {
        return [];
    }

    $tax_query = [
        'relation' => 'AND',
        [
            'taxonomy'         => 'functienaam',
            'field'            => 'term_id',
            'terms'            => $function_ids,
            'operator'         => 'IN',
            'include_children' => false,
        ],
    ];

    $status_taxonomy =
        tfsc_derived_rel_v2_status_taxonomy();

    if ( taxonomy_exists( $status_taxonomy ) ) {
        $tax_query[] = [
            'taxonomy'         => $status_taxonomy,
            'field'            => 'slug',
            'terms'            => [
                tfsc_derived_rel_v2_open_status(),
            ],
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    $ids = get_posts( [
        'post_type'        => $post_type,
        'post_status'      => 'publish',
        'posts_per_page'   => -1,
        'fields'           => 'ids',
        'no_found_rows'    => true,
        'suppress_filters' => false,
        'tax_query'        => $tax_query,
    ] );

    return $cache[ $key ] =
        array_values(
            array_unique(
                array_map( 'intval', $ids )
            )
        );
}


function tfsc_derived_rel_v2_get_target_term_ids(
    $vacancy_ids,
    $taxonomy
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }

    /**
     * Eén term-query voor alle vacatures in plaats van
     * wp_get_post_terms() per vacature.
     */
    $ids = wp_get_object_terms(
        array_map( 'intval', $vacancy_ids ),
        $taxonomy,
        [
            'fields' => 'ids',
        ]
    );

    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }

    $ids = array_map( 'intval', $ids );

    if ( is_taxonomy_hierarchical( $taxonomy ) ) {

        foreach ( $ids as $id ) {
            $ids = array_merge(
                $ids,
                get_ancestors(
                    $id,
                    $taxonomy,
                    'taxonomy'
                )
            );
        }
    }

    return array_values(
        array_unique(
            array_filter(
                array_map( 'intval', $ids )
            )
        )
    );
}


function tfsc_derived_rel_v2_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( ! $ids ) {
        return [];
    }

    if ( ! is_taxonomy_hierarchical( $taxonomy ) ) {
        return 0 === (int) $level
            ? array_values( array_unique( $ids ) )
            : [];
    }

    return array_values(
        array_filter(
            array_unique( array_map( 'intval', $ids ) ),
            function( $id ) use ( $taxonomy, $level ) {
                return count(
                    get_ancestors(
                        $id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === (int) $level;
            }
        )
    );
}


/**
 * ============================================================
 * QUERY ID
 * ============================================================
 */

function tfsc_derived_rel_v2_parse_query_id(
    $query_id
) {

    if (
        ! preg_match(
            '/^relationship_(.+)_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }

    $taxonomy = sanitize_key( $matches[1] );

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return false;
    }

    return [
        'taxonomy' => $taxonomy,
        'level'    => (int) $matches[2],
    ];
}


/**
 * ============================================================
 * ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        $query_id =
            $settings['term_taxonomy_id']
            ?? '';

        $parsed =
            tfsc_derived_rel_v2_parse_query_id(
                $query_id
            );

        if ( ! $parsed ) {
            return $args;
        }

        $taxonomy = $parsed['taxonomy'];
        $level    = $parsed['level'];

        if (
            $taxonomy ===
            tfsc_derived_rel_v2_status_taxonomy()
        ) {
            return $args;
        }

        $source = $args['taxonomy'] ?? '';

        if ( is_array( $source ) ) {
            $source = reset( $source );
        }

        if (
            sanitize_key( $source )
            !==
            $taxonomy
        ) {
            return $args;
        }

        $pod =
            tfsc_derived_rel_v2_get_current_pod();

        if (
            ! $pod ||
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $args;
        }

        $function_ids =
            tfsc_derived_rel_v2_get_function_ids(
                $pod
            );

        $vacancy_ids =
            tfsc_derived_rel_v2_get_vacancy_ids(
                $function_ids
            );

        $target_ids =
            tfsc_derived_rel_v2_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );

        $target_ids =
            tfsc_derived_rel_v2_filter_level(
                $target_ids,
                $taxonomy,
                $level
            );

        if ( ! $target_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        unset( $args['term_taxonomy_id'] );

        $args['taxonomy']     = $taxonomy;
        $args['include']      = $target_ids;
        $args['hide_empty']   = false;
        $args['hierarchical'] = false;

        $args['tfsc_derived_relationship_query'] =
            1;

        $args['tfsc_derived_relationship_taxonomy'] =
            $taxonomy;

        return $args;
    },
    30,
    3
);


/**
 * ============================================================
 * SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function( $terms, $taxonomies, $args, $term_query ) {

        if (
            is_admin() ||
            empty( $args['tfsc_derived_relationship_query'] ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }

        if (
            isset( $args['orderby'] ) &&
            'name' !== strtolower( (string) $args['orderby'] )
        ) {
            return $terms;
        }

        $order =
            strtoupper(
                (string) (
                    $args['order']
                    ?? 'ASC'
                )
            );

        if (
            ! in_array(
                $order,
                [ 'ASC', 'DESC' ],
                true
            )
        ) {
            $order = 'ASC';
        }

        usort(
            $terms,
            function( $a, $b ) use ( $order ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }

                $compare = strnatcasecmp(
                    remove_accents(
                        wp_strip_all_tags( $a->name )
                    ),
                    remove_accents(
                        wp_strip_all_tags( $b->name )
                    )
                );

                return 'DESC' === $order
                    ? -$compare
                    : $compare;
            }
        );

        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * TERMPAD
 * ============================================================
 */

function tfsc_derived_rel_v2_term_path( $term ) {

    if (
        ! $term instanceof WP_Term ||
        ! taxonomy_exists( $term->taxonomy )
    ) {
        return '';
    }

    $ids = is_taxonomy_hierarchical( $term->taxonomy )
        ? array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        )
        : [];

    $slugs = [];

    foreach ( $ids as $id ) {

        $ancestor =
            get_term(
                $id,
                $term->taxonomy
            );

        if (
            $ancestor instanceof WP_Term &&
            ! is_wp_error( $ancestor )
        ) {
            $slugs[] = $ancestor->slug;
        }
    }

    $slugs[] = $term->slug;

    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * COMBO URL
 * ============================================================
 */

function tfsc_derived_rel_v2_build_combo_url(
    $target_term
) {

    if ( ! $target_term instanceof WP_Term ) {
        return false;
    }

    $taxonomy = $target_term->taxonomy;

    if (
        ! taxonomy_exists( $taxonomy ) ||
        $taxonomy === tfsc_derived_rel_v2_status_taxonomy()
    ) {
        return false;
    }

    $pod =
        tfsc_derived_rel_v2_get_current_pod();

    if (
        ! $pod ||
        ! tfsc_derived_rel_v2_has_relationship_field(
            $pod,
            $taxonomy
        )
    ) {
        return false;
    }

    $function_ids =
        tfsc_derived_rel_v2_get_function_ids(
            $pod
        );

    if ( ! $function_ids ) {
        return false;
    }

    /**
     * Alleen link maken als deze combinatie
     * daadwerkelijk een open vacature heeft.
     */
    $tax_query = [
        'relation' => 'AND',
        [
            'taxonomy'         => 'functienaam',
            'field'            => 'term_id',
            'terms'            => $function_ids,
            'operator'         => 'IN',
            'include_children' => false,
        ],
        [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => [
                (int) $target_term->term_id,
            ],
            'operator'         => 'IN',
            'include_children' =>
                is_taxonomy_hierarchical( $taxonomy ),
        ],
    ];

    $status_taxonomy =
        tfsc_derived_rel_v2_status_taxonomy();

    if ( taxonomy_exists( $status_taxonomy ) ) {
        $tax_query[] = [
            'taxonomy'         => $status_taxonomy,
            'field'            => 'slug',
            'terms'            => [
                tfsc_derived_rel_v2_open_status(),
            ],
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    $exists = get_posts( [
        'post_type'      =>
            tfsc_derived_rel_v2_vacancy_post_type(),
        'post_status'    => 'publish',
        'posts_per_page' => 1,
        'fields'         => 'ids',
        'no_found_rows'  => true,
        'tax_query'      => $tax_query,
    ] );

    if ( ! $exists ) {
        return false;
    }

    $parts = [
        tfsc_derived_rel_v2_combo_base(),
    ];

    foreach ( $function_ids as $id ) {

        $term =
            get_term(
                $id,
                'functienaam'
            );

        if (
            ! $term instanceof WP_Term ||
            is_wp_error( $term )
        ) {
            continue;
        }

        $path =
            tfsc_derived_rel_v2_term_path(
                $term
            );

        if ( $path ) {
            $parts[] = 'functienaam';
            $parts[] = $path;
        }
    }

    $target_path =
        tfsc_derived_rel_v2_term_path(
            $target_term
        );

    if ( ! $target_path ) {
        return false;
    }

    $parts[] = $taxonomy;
    $parts[] = $target_path;

    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                fn( $part ) => trim( $part, '/' ),
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function( $termlink, $term, $taxonomy ) {

        if (
            ! empty(
                $GLOBALS['tfsc_force_native_term_link']
            ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! $taxonomy
        ) {
            return $termlink;
        }

        /**
         * Deze snippet is alleen voor CPT/post-context.
         */
        $object =
            get_queried_object();

        if (
            ! $object instanceof WP_Post
        ) {
            return $termlink;
        }

        if (
            $taxonomy ===
            tfsc_derived_rel_v2_status_taxonomy()
        ) {
            return $termlink;
        }

        $pod =
            tfsc_derived_rel_v2_get_current_pod();

        if (
            ! $pod ||
            ! tfsc_derived_rel_v2_has_relationship_field(
                $pod,
                $taxonomy
            )
        ) {
            return $termlink;
        }

        $url =
            tfsc_derived_rel_v2_build_combo_url(
                $term
            );

        return $url ?: $termlink;
    },
    30,
    3
);

/**
 * TFSC - Volledig dynamische vacature-archieven
 *
 * - Virtuele combo archives onder /vacatures/...
 * - Onbeperkt aantal taxonomies/terms
 * - Verschillende taxonomies = AND
 * - Meerdere terms binnen taxonomy = OR
 * - kennisgebied = AND
 * - Alleen vac_status=open
 * - Search & Filter Pro v3 sync
 * - Elementor archive condition
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_BASE' ) ) {
    define( 'TFSC_COMBO_BASE', 'vacatures' );
}

if ( ! defined( 'TFSC_VACANCY_POST_TYPE' ) ) {
    define( 'TFSC_VACANCY_POST_TYPE', 'vacature' );
}

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}

if ( ! defined( 'TFSC_STATUS_TAXONOMY' ) ) {
    define( 'TFSC_STATUS_TAXONOMY', 'vac_status' );
}

if ( ! defined( 'TFSC_OPEN_STATUS_SLUG' ) ) {
    define( 'TFSC_OPEN_STATUS_SLUG', 'open' );
}


/**
 * ============================================================
 * HELPERS
 * ============================================================
 */

function tfsc_get_combo_taxonomy_match_method( $taxonomy ) {

    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


function tfsc_combo_status_clause() {

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    if (
        ! $taxonomy ||
        TFSC_STATUS_TAXONOMY === $taxonomy ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return false;
    }

    $object = get_taxonomy( $taxonomy );

    return (
        $object &&
        $object->publicly_queryable &&
        in_array(
            TFSC_VACANCY_POST_TYPE,
            (array) $object->object_type,
            true
        )
    );
}


function tfsc_get_allowed_combo_taxonomies() {

    static $allowed = null;

    if ( null !== $allowed ) {
        return $allowed;
    }

    $allowed = [];

    foreach (
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        )
        as $taxonomy => $object
    ) {
        if ( tfsc_combo_taxonomy_allowed( $taxonomy ) ) {
            $allowed[] = $taxonomy;
        }
    }

    return $allowed;
}


function tfsc_is_combo_archive() {

    return (bool) get_query_var(
        'tfsc_combo_archive'
    );
}


function tfsc_is_vacancy_seo_landing() {

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term = get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


/**
 * ============================================================
 * QUERY VARS + REWRITE
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';
        $vars[] = 'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        add_rewrite_rule(
            '^'
            . preg_quote( TFSC_COMBO_BASE, '/' )
            . '/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * TERMPAD OPLOSSEN
 * ============================================================
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy( $taxonomy );

    if (
        ! $tax_object ||
        ! is_array( $segments ) ||
        ! $segments
    ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            array_map(
                'sanitize_title',
                $segments
            )
        )
    );

    if (
        ! $segments ||
        (
            ! $tax_object->hierarchical &&
            1 !== count( $segments )
        )
    ) {
        return false;
    }

    $terms     = [];
    $parent_id = 0;

    foreach ( $segments as $index => $slug ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );

        if (
            ! $term ||
            is_wp_error( $term )
        ) {
            return false;
        }

        if (
            $index > 0 &&
            (int) $term->parent !== $parent_id
        ) {
            return false;
        }

        $terms[]  = $term;
        $parent_id = (int) $term->term_id;
    }

    return [
        'path' => $terms,
        'term' => end( $terms ),
    ];
}


/**
 * ============================================================
 * COMBO URL PARSEN
 * ============================================================
 */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;

    if ( $resolved ) {
        return $cache;
    }

    $resolved = true;

    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }

    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );

    if ( ! $raw_path ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            explode(
                '/',
                trim(
                    (string) $raw_path,
                    '/'
                )
            ),
            'strlen'
        )
    );

    if ( count( $segments ) < 2 ) {
        return false;
    }

    $allowed =
        tfsc_get_allowed_combo_taxonomies();

    if ( ! $allowed ) {
        return false;
    }

    $items = [];
    $count = count( $segments );
    $i     = 0;

    while ( $i < $count ) {

        $taxonomy =
            sanitize_key(
                $segments[ $i ]
            );

        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }

        $i++;
        $term_segments = [];

        while ( $i < $count ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[ $i ]
                );

            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }

            $term_segments[] =
                $segments[ $i ];

            $i++;
        }

        if ( ! $term_segments ) {
            return false;
        }

        $resolved_path =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );

        if ( ! $resolved_path ) {
            return false;
        }

        $items[] = [
            'taxonomy' => $taxonomy,
            'term'     => $resolved_path['term'],
            'path'     => $resolved_path['path'],
        ];
    }

    return $cache = (
        $items
            ? $items
            : false
    );
}


/**
 * ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================
 */

function tfsc_group_combo_terms(
    $property = 'term_id'
) {

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    $grouped = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $taxonomy =
            $item['taxonomy'];

        if ( 'name' === $property ) {

            $value =
                trim(
                    $item['term']->name
                );

        } elseif ( 'slug' === $property ) {

            $value =
                $item['term']->slug;

        } else {

            $value =
                (int) $item['term']->term_id;
        }

        if (
            '' === $value ||
            0 === $value
        ) {
            continue;
        }

        if (
            ! isset(
                $grouped[ $taxonomy ]
            )
        ) {
            $grouped[ $taxonomy ] = [];
        }

        if (
            ! in_array(
                $value,
                $grouped[ $taxonomy ],
                true
            )
        ) {
            $grouped[ $taxonomy ][] =
                $value;
        }
    }

    return $grouped;
}


/**
 * ============================================================
 * TAX QUERY
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $grouped =
        tfsc_group_combo_terms(
            'term_id'
        );

    if ( ! $grouped ) {
        return false;
    }

    $tax_query = [
        'relation' => 'AND',
        tfsc_combo_status_clause(),
    ];

    foreach (
        $grouped
        as $taxonomy => $term_ids
    ) {

        if ( ! $term_ids ) {
            continue;
        }

        $object =
            get_taxonomy(
                $taxonomy
            );

        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );

        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method &&
                    $object &&
                    $object->hierarchical
                ),
        ];
    }

    return $tax_query;
}


/**
 * ============================================================
 * MAIN QUERY
 * ============================================================
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin() ||
            ! $query->is_main_query()
        ) {
            return;
        }

        /**
         * Virtuele combo archive.
         */
        if ( tfsc_is_combo_archive() ) {

            $tax_query =
                tfsc_build_combo_tax_query();

            if ( ! $tax_query ) {
                return;
            }

            $query->set(
                'post_type',
                TFSC_VACANCY_POST_TYPE
            );

            $query->set(
                'post_status',
                'publish'
            );

            $query->set(
                'tax_query',
                $tax_query
            );

            $query->set(
                'no_found_rows',
                false
            );

            return;
        }

        /**
         * Native vacature taxonomy archive.
         */
        if ( ! $query->is_tax() ) {
            return;
        }

        $term =
            $query->get_queried_object();

        if (
            ! $term instanceof WP_Term ||
            ! tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {
            return;
        }

        $tax_query =
            $query->get(
                'tax_query'
            );

        if ( ! is_array( $tax_query ) ) {
            $tax_query = [];
        }

        $tax_query[] =
            tfsc_combo_status_clause();

        $tax_query['relation'] =
            'AND';

        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );

        $query->set(
            'post_status',
            'publish'
        );

        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
);


