/**
 * ============================================================
 * HEADING HTML
 * ============================================================
 */

function tfsc_combo_heading_html( $rows ) {

    $rows = array_values(
        array_filter(
            (array) $rows,
            'strlen'
        )
    );

    if ( ! $rows ) {
        return '';
    }

    $html =
        '<span class="tfsc-heading">';

    foreach (
        $rows
        as $index => $row
    ) {

        $html .=
            '<span class="'
            .
            (
                0 === $index
                    ? 'tfsc-heading__main'
                    : 'tfsc-heading__row'
            )
            .
            '">'
            .
            esc_html( $row )
            .
            '</span>';
    }

    $html .=
        '</span>';

    return $html;
}


/**
 * ============================================================
 * [combo_heading]
 * ============================================================
 */

add_shortcode(
    'combo_heading',
    function() {

        /**
         * Combo archive.
         */
        if ( tfsc_is_combo_archive() ) {

            $grouped =
                tfsc_group_combo_terms(
                    'name'
                );

            if ( ! $grouped ) {
                return '';
            }

            $rows = [];

            if (
                ! empty(
                    $grouped['functienaam']
                )
            ) {

                $functions =
                    $grouped['functienaam'];

                if ( 1 === count( $functions ) ) {

                    $rows[] =
                        $functions[0]
                        .
                        ' vacatures';

                } else {

                    $rows[] =
                        'Vacatures';

                    $rows[] =
                        implode(
                            ', ',
                            $functions
                        );
                }

                unset(
                    $grouped['functienaam']
                );

            } else {

                $rows[] =
                    'Vacatures';
            }

            foreach (
                $grouped
                as $names
            ) {
                if ( $names ) {
                    $rows[] =
                        implode(
                            ', ',
                            $names
                        );
                }
            }

            return tfsc_combo_heading_html(
                $rows
            );
        }

        /**
         * Native taxonomy archive.
         */
        $term =
            get_queried_object();

        if (
            $term instanceof WP_Term &&
            tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {

            $title =
                get_term_meta(
                    $term->term_id,
                    'pods_archive_title',
                    true
                );

            $title =
                is_string( $title )
                    ? trim(
                        wp_strip_all_tags(
                            $title
                        )
                    )
                    : '';

            if ( '' === $title ) {

                $name =
                    trim(
                        $term->name
                    );

                if ( '' === $name ) {
                    return '';
                }

                $title =
                    $name
                    .
                    ' vacatures';
            }

            return tfsc_combo_heading_html(
                [ $title ]
            );
        }

        /**
         * Vacature post type archive.
         */
        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {
            return tfsc_combo_heading_html(
                [ 'Vacatures' ]
            );
        }

        return '';
    }
);


/**
 * ============================================================
 * [combo_term taxonomy="..."]
 * ============================================================
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' => '',
                    'separator' => ' • ',
                ],
                $atts,
                'combo_term'
            );

        $taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );

        if ( ! $taxonomy ) {
            return '';
        }

        /**
         * Combo archive.
         */
        if ( tfsc_is_combo_archive() ) {

            $grouped =
                tfsc_group_combo_terms(
                    'name'
                );

            if (
                empty(
                    $grouped[ $taxonomy ]
                )
            ) {
                return '';
            }

            return esc_html(
                implode(
                    (string) $atts['separator'],
                    $grouped[ $taxonomy ]
                )
            );
        }

        /**
         * Native taxonomy archive.
         */
        $term =
            get_queried_object();

        if (
            $term instanceof WP_Term &&
            $term->taxonomy === $taxonomy &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return esc_html(
                $term->name
            );
        }

        return '';
    }
);

/**
 * TFSC - Rank Math breadcrumbs voor combo-archieven
 *
 * Voorbeeld:
 * Home > Vacatures > Field Service Engineer > Elektrotechniek
 */

add_filter(
    'rank_math/frontend/breadcrumb/items',
    function( $crumbs, $class ) {

        if (
            ! function_exists( 'tfsc_is_combo_archive' ) ||
            ! function_exists( 'tfsc_get_combo_archive' ) ||
            ! tfsc_is_combo_archive()
        ) {
            return $crumbs;
        }

        $combo = tfsc_get_combo_archive();

        if ( ! is_array( $combo ) || ! $combo ) {
            return $crumbs;
        }

        $base = trim( TFSC_COMBO_BASE, '/' );

        $new_crumbs = [
            [
                'Home',
                home_url( '/' ),
            ],
            [
                'Vacatures',
                home_url( '/' . $base . '/' ),
            ],
        ];

        $path_parts = [];
        $last_index = count( $combo ) - 1;

        foreach ( $combo as $index => $item ) {

            if (
                empty( $item['taxonomy'] ) ||
                empty( $item['term'] ) ||
                ! $item['term'] instanceof WP_Term
            ) {
                continue;
            }

            $term = $item['term'];

            $path_parts[] =
                sanitize_key(
                    $item['taxonomy']
                );

            if (
                ! empty( $item['path'] ) &&
                is_array( $item['path'] )
            ) {

                foreach ( $item['path'] as $path_term ) {

                    if ( $path_term instanceof WP_Term ) {
                        $path_parts[] = $path_term->slug;
                    }
                }

            } else {

                $path_parts[] = $term->slug;
            }

            $url =
                home_url(
                    '/'
                    . $base
                    . '/'
                    . implode(
                        '/',
                        array_map(
                            'rawurlencode',
                            $path_parts
                        )
                    )
                    . '/'
                );

            $new_crumbs[] = [
                $term->name,
                $index === $last_index
                    ? ''
                    : $url,
            ];
        }

        return $new_crumbs;
    },
    20,
    2
);

/**
 * TFSC - Alle taxonomy termen in WordPress linkzoeker
 *
 * Alle publieke native taxonomy-term archieven.
 * Geen virtuele combo-URL's.
 */

add_filter(
    'wp_link_query',
    function( $results, $query ) {

        $search = trim(
            (string) ( $query['s'] ?? '' )
        );

        if ( '' === $search ) {
            return $results;
        }

        $taxonomies = array_keys(
            get_taxonomies(
                [
                    'public'             => true,
                    'publicly_queryable' => true,
                ],
                'objects'
            )
        );

        $taxonomies = array_values(
            array_diff(
                $taxonomies,
                [ 'post_format' ]
            )
        );

        if ( ! $taxonomies ) {
            return $results;
        }

        $terms = get_terms( [
            'taxonomy'   => $taxonomies,
            'hide_empty' => false,
            'search'     => $search,
            'number'     => 50,
        ] );

        if (
            is_wp_error( $terms ) ||
            ! $terms
        ) {
            return $results;
        }

        foreach ( $terms as $term ) {

            if ( ! $term instanceof WP_Term ) {
                continue;
            }

            $GLOBALS['tfsc_force_native_term_link'] = true;
            $url = get_term_link( $term );
            unset( $GLOBALS['tfsc_force_native_term_link'] );

            if ( is_wp_error( $url ) ) {
                continue;
            }

            $taxonomy =
                get_taxonomy(
                    $term->taxonomy
                );

            $results[] = [
                'ID' =>
                    'term-'
                    . $term->taxonomy
                    . '-'
                    . $term->term_id,

                'title' =>
                    $term->name,

                'permalink' =>
                    $url,

                'info' =>
                    $taxonomy->labels->singular_name
                    ?? $term->taxonomy,
            ];
        }

        return $results;
    },
    20,
    2
);

/**
 * TFSC - Dynamische Archive Description Accordion
 *
 * Shortcode:
 * [tfsc_archive_accordion]
 *
 * Titel:
 * pods_archive_title → termnaam
 *
 * Content:
 * term description
 */


/**
 * Eén accordion-item maken.
 */
function tfsc_get_archive_accordion_item( $term ) {

    if ( ! $term instanceof WP_Term ) {
        return false;
    }

    $description = trim(
        (string) term_description(
            $term->term_id,
            $term->taxonomy
        )
    );

    if ( '' === $description ) {
        return false;
    }

    $title = get_term_meta(
        $term->term_id,
        'pods_archive_title',
        true
    );

    $title = is_string( $title )
        ? trim( wp_strip_all_tags( $title ) )
        : '';

    if ( '' === $title ) {
        $title = trim( $term->name );
    }

    if ( '' === $title ) {
        return false;
    }

    return [
        'title'       => $title,
        'description' => $description,
        'term_id'     => (int) $term->term_id,
        'taxonomy'    => $term->taxonomy,
    ];
}


/**
 * Actieve archive-terms bepalen.
 */
function tfsc_get_archive_accordion_terms() {

    /**
     * Virtueel combo archive.
     */
    if (
        function_exists( 'tfsc_is_combo_archive' ) &&
        function_exists( 'tfsc_get_combo_archive' ) &&
        tfsc_is_combo_archive()
    ) {

        $combo = tfsc_get_combo_archive();

        if ( ! is_array( $combo ) ) {
            return [];
        }

        $terms = [];
        $seen  = [];

        foreach ( $combo as $item ) {

            $term = $item['term'] ?? null;

            if ( ! $term instanceof WP_Term ) {
                continue;
            }

            $key =
                $term->taxonomy
                . ':'
                . $term->term_id;

            if ( isset( $seen[ $key ] ) ) {
                continue;
            }

            $seen[ $key ] = true;
            $terms[] = $term;
        }

        return $terms;
    }

    /**
     * Native taxonomy archive.
     */
    if ( ! is_tax() ) {
        return [];
    }

    $term = get_queried_object();

    if ( ! $term instanceof WP_Term ) {
        return [];
    }

    $status_taxonomy =
        defined( 'TFSC_STATUS_TAXONOMY' )
            ? TFSC_STATUS_TAXONOMY
            : 'vac_status';

    if ( $term->taxonomy === $status_taxonomy ) {
        return [];
    }

    /**
     * Hoofd-combosnippet gebruiken indien beschikbaar.
     */
    if (
        function_exists( 'tfsc_combo_taxonomy_allowed' )
    ) {
        return tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
            ? [ $term ]
            : [];
    }

    /**
     * Fallback: taxonomy moet aan vacature hangen.
     */
    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );

    $post_type =
        defined( 'TFSC_VACANCY_POST_TYPE' )
            ? TFSC_VACANCY_POST_TYPE
            : 'vacature';

    if (
        ! $taxonomy ||
        ! in_array(
            $post_type,
            (array) $taxonomy->object_type,
            true
        )
    ) {
        return [];
    }

    return [ $term ];
}


/**
 * Accordion-items ophalen.
 */
function tfsc_get_archive_accordion_items() {

    $items = [];

    foreach (
        tfsc_get_archive_accordion_terms()
        as $term
    ) {

        $item =
            tfsc_get_archive_accordion_item(
                $term
            );

        if ( $item ) {
            $items[] = $item;
        }
    }

    return $items;
}


/**
 * Shortcode.
 */
add_shortcode(
    'tfsc_archive_accordion',
    function() {

        $items =
            tfsc_get_archive_accordion_items();

        if ( ! $items ) {
            return '';
        }

        static $instance = 0;
        $instance++;

        $accordion_id =
            'tfsc-archive-accordion-'
            . $instance;

        ob_start();
        ?>

        <div
            id="<?php echo esc_attr( $accordion_id ); ?>"
            class="tfsc-archive-accordion"
        >

            <?php foreach ( $items as $index => $item ) :

                $item_id =
                    $accordion_id
                    . '-item-'
                    . $index;

                $button_id =
                    $item_id . '-button';

                $content_id =
                    $item_id . '-content';
            ?>

                <div
                    class="tfsc-archive-accordion__item"
                    data-taxonomy="<?php echo esc_attr( $item['taxonomy'] ); ?>"
                    data-term-id="<?php echo esc_attr( $item['term_id'] ); ?>"
                >

                    <button
                        type="button"
                        id="<?php echo esc_attr( $button_id ); ?>"
                        class="tfsc-archive-accordion__title"
                        aria-expanded="false"
                        aria-controls="<?php echo esc_attr( $content_id ); ?>"
                    >
                        <span class="tfsc-archive-accordion__title-text">
                            <?php echo esc_html( $item['title'] ); ?>
                        </span>

                        <span
                            class="tfsc-archive-accordion__chevron"
                            aria-hidden="true"
                        ></span>
                    </button>

                    <div
                        id="<?php echo esc_attr( $content_id ); ?>"
                        class="tfsc-archive-accordion__content"
                        role="region"
                        aria-labelledby="<?php echo esc_attr( $button_id ); ?>"
                        hidden
                    >
                        <div class="tfsc-archive-accordion__content-inner">
                            <?php
                            echo wp_kses_post(
                                $item['description']
                            );
                            ?>
                        </div>
                    </div>

                </div>

            <?php endforeach; ?>

        </div>

        <script>
        (function () {

            const accordion =
                document.getElementById(
                    <?php echo wp_json_encode( $accordion_id ); ?>
                );

            if (!accordion) {
                return;
            }

            accordion.addEventListener(
                'click',
                function (event) {

                    const button =
                        event.target.closest(
                            '.tfsc-archive-accordion__title'
                        );

                    if (
                        !button ||
                        !accordion.contains(button)
                    ) {
                        return;
                    }

                    const item =
                        button.closest(
                            '.tfsc-archive-accordion__item'
                        );

                    const content =
                        item?.querySelector(
                            '.tfsc-archive-accordion__content'
                        );

                    if (!content) {
                        return;
                    }

                    const open =
                        button.getAttribute(
                            'aria-expanded'
                        ) === 'true';

                    button.setAttribute(
                        'aria-expanded',
                        String(!open)
                    );

                    item.classList.toggle(
                        'tfsc-archive-accordion__item--open',
                        !open
                    );

                    content.hidden = open;
                }
            );

        })();
        </script>

        <?php
        return ob_get_clean();
    }
);


