/**
 * TFSC - Rank Math breadcrumbs voor:
 * - taxonomy base archives
 * - native taxonomy term archives
 * - CPT archives
 * - CPT singulars
 */

add_filter(
    'rank_math/frontend/breadcrumb/items',
    function( $crumbs, $class ) {

        /**
         * Home breadcrumb behouden en een pad opbouwen.
         */
        $build_path = function(
            $path,
            $last_label = '',
            $last_current = false
        ) use ( $crumbs ) {

            $segments = array_values(
                array_filter(
                    explode(
                        '/',
                        trim( (string) $path, '/' )
                    )
                )
            );

            if ( ! $segments ) {
                return $crumbs;
            }

            $result = [];

            if ( ! empty( $crumbs[0] ) ) {
                $result[] = $crumbs[0];
            }

            $current = '';
            $last    = count( $segments ) - 1;

            foreach ( $segments as $index => $segment ) {

                $current .= '/' . $segment;

                $label = (
                    $index === $last &&
                    '' !== $last_label
                )
                    ? $last_label
                    : ucfirst(
                        str_replace(
                            [ '-', '_' ],
                            ' ',
                            $segment
                        )
                    );

                $result[] = [
                    $label,
                    (
                        $last_current &&
                        $index === $last
                    )
                        ? ''
                        : home_url( $current . '/' ),
                ];
            }

            return $result;
        };


        /**
         * URL → relatief pad.
         */
        $relative_path = function( $url ) {

            $path = $url
                ? wp_parse_url(
                    $url,
                    PHP_URL_PATH
                )
                : '';

            return $path
                ? trim( $path, '/' )
                : '';
        };


        /**
         * ====================================================
         * 1. TAXONOMY BASE ARCHIVE
         * ====================================================
         */

        $base_taxonomy =
            get_query_var(
                'tfsc_taxonomy_archive'
            );

        if (
            $base_taxonomy &&
            taxonomy_exists( $base_taxonomy )
        ) {

            $taxonomy =
                get_taxonomy(
                    $base_taxonomy
                );

            if (
                ! $taxonomy ||
                empty( $taxonomy->rewrite['slug'] )
            ) {
                return $crumbs;
            }

            return $build_path(
                $taxonomy->rewrite['slug'],
                $taxonomy->labels->name ?? '',
                true
            );
        }


        /**
         * ====================================================
         * 2. NATIVE TAXONOMY TERM ARCHIVE
         * ====================================================
         *
         * Native taxonomy URL:
         * /locatie/nederland/noord-brabant/eindhoven/
         *
         * Breadcrumb:
         * Home
         * > Vacatures
         * > Locaties
         * > Nederland
         * > Noord-Brabant
         * > Eindhoven
         *
         * Alle breadcrumb-links wijzen naar de combo-structuur:
         * /vacatures/{taxonomy}/...
         */

        if ( is_tax() ) {

            $term =
                get_queried_object();

            if (
                ! $term instanceof WP_Term
            ) {
                return $crumbs;
            }

            /**
             * Alleen echte native term URL behandelen.
             * Combo/virtuele URLs blijven ongemoeid.
             */
            $term_url =
                get_term_link(
                    $term
                );

            if ( is_wp_error( $term_url ) ) {
                return $crumbs;
            }

            $native_path =
                untrailingslashit(
                    wp_parse_url(
                        $term_url,
                        PHP_URL_PATH
                    )
                );

            $current_path =
                wp_parse_url(
                    $_SERVER['REQUEST_URI'] ?? '',
                    PHP_URL_PATH
                );

            $current_path =
                preg_replace(
                    '#/page/[0-9]+/?$#',
                    '/',
                    $current_path
                );

            $current_path =
                untrailingslashit(
                    $current_path
                );

            if (
                $native_path !==
                $current_path
            ) {
                return $crumbs;
            }

            $taxonomy =
                get_taxonomy(
                    $term->taxonomy
                );

            if ( ! $taxonomy ) {
                return $crumbs;
            }

            /**
             * Combo base.
             *
             * Bijvoorbeeld:
             * /vacatures/locatie/
             */
            $combo_base =
                defined( 'TFSC_COMBO_BASE' )
                    ? trim(
                        TFSC_COMBO_BASE,
                        '/'
                    )
                    : 'vacatures';

            $taxonomy_slug =
                ! empty( $taxonomy->rewrite['slug'] )
                    ? trim(
                        $taxonomy->rewrite['slug'],
                        '/'
                    )
                    : $term->taxonomy;

            $result = [];

            /**
             * Home.
             */
            if ( ! empty( $crumbs[0] ) ) {
                $result[] = $crumbs[0];
            }

            /**
             * Vacatures.
             */
            $result[] = [
                'Vacatures',
                home_url(
                    '/' . $combo_base . '/'
                ),
            ];

            /**
             * Taxonomy base.
             *
             * Locaties
             * → /vacatures/locatie/
             */
            $result[] = [
                $taxonomy->labels->name
                    ?? ucfirst(
                        str_replace(
                            [ '-', '_' ],
                            ' ',
                            $taxonomy_slug
                        )
                    ),

                home_url(
                    '/'
                    . $combo_base
                    . '/'
                    . $taxonomy_slug
                    . '/'
                ),
            ];

            /**
             * Pad binnen de taxonomy opbouwen.
             */
            $term_path = [];

            if (
                is_taxonomy_hierarchical(
                    $term->taxonomy
                )
            ) {

                foreach (
                    array_reverse(
                        get_ancestors(
                            $term->term_id,
                            $term->taxonomy,
                            'taxonomy'
                        )
                    )
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $term->taxonomy
                        );

                    if (
                        ! $ancestor instanceof WP_Term ||
                        is_wp_error( $ancestor )
                    ) {
                        continue;
                    }

                    $term_path[] =
                        $ancestor->slug;

                    $result[] = [
                        $ancestor->name,

                        home_url(
                            '/'
                            . $combo_base
                            . '/'
                            . $taxonomy_slug
                            . '/'
                            . implode(
                                '/',
                                $term_path
                            )
                            . '/'
                        ),
                    ];
                }
            }

            /**
             * Huidige term.
             *
             * Geen link omdat dit de huidige native pagina is.
             */
            $result[] = [
                $term->name,
                '',
            ];

            return $result;
        }


        /**
         * ====================================================
         * 3. CPT ARCHIVE
         * ====================================================
         */

        if ( is_post_type_archive() ) {

            $post_type =
                get_query_var(
                    'post_type'
                );

            if ( is_array( $post_type ) ) {
                $post_type =
                    reset( $post_type );
            }

            if ( ! $post_type ) {
                return $crumbs;
            }

            $object =
                get_post_type_object(
                    $post_type
                );

            $archive_url =
                get_post_type_archive_link(
                    $post_type
                );

            $archive_path =
                $relative_path(
                    $archive_url
                );

            if (
                ! $object ||
                ! $archive_path
            ) {
                return $crumbs;
            }

            return $build_path(
                $archive_path,
                $object->labels->name ?? '',
                true
            );
        }


        /**
         * ====================================================
         * 4. CPT SINGULAR
         * ====================================================
         */

        if ( is_singular() ) {

            $post_id =
                get_queried_object_id();

            if ( ! $post_id ) {
                return $crumbs;
            }

            $post_type =
                get_post_type(
                    $post_id
                );

            if (
                ! $post_type ||
                in_array(
                    $post_type,
                    [
                        'post',
                        'page',
                        'attachment',
                    ],
                    true
                )
            ) {
                return $crumbs;
            }

            $object =
                get_post_type_object(
                    $post_type
                );

            if (
                ! $object ||
                empty( $object->has_archive )
            ) {
                return $crumbs;
            }

            $archive_path =
                $relative_path(
                    get_post_type_archive_link(
                        $post_type
                    )
                );

            if ( ! $archive_path ) {
                return $crumbs;
            }

            $result =
                $build_path(
                    $archive_path,
                    $object->labels->name ?? ''
                );

            if (
                is_post_type_hierarchical(
                    $post_type
                )
            ) {

                foreach (
                    array_reverse(
                        get_post_ancestors(
                            $post_id
                        )
                    )
                    as $ancestor_id
                ) {

                    $result[] = [
                        get_the_title(
                            $ancestor_id
                        ),
                        get_permalink(
                            $ancestor_id
                        ),
                    ];
                }
            }

            $result[] = [
                get_the_title(
                    $post_id
                ),
                '',
            ];

            return $result;
        }


        return $crumbs;
    },
    10,
    2
);

/**
 * TFSC - Elementor Taxonomy Loop filters
 *
 * Query ID's:
 *
 * taxonomy_level_X
 *
 * current_taxonomy
 * current_taxonomy_level_X
 */


/**
 * Term IDs van exact taxonomy-level ophalen.
 */
function tfsc_taxonomy_level_term_ids(
    $taxonomy,
    $level
) {

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return [];
    }

    $terms = get_terms( [
        'taxonomy'   => $taxonomy,
        'hide_empty' => false,
    ] );

    if (
        is_wp_error( $terms ) ||
        ! $terms
    ) {
        return [];
    }

    $ids = [];

    foreach ( $terms as $term ) {

        if (
            count(
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                )
            ) === (int) $level
        ) {
            $ids[] = (int) $term->term_id;
        }
    }

    return $ids;
}


/**
 * Elementor Taxonomy Loop.
 */
add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        $query_id = sanitize_key(
            $settings['term_taxonomy_id']
            ?? ''
        );

        if ( ! $query_id ) {
            return $args;
        }


        /**
         * ====================================================
         * taxonomy_level_X
         * ====================================================
         */

        if (
            preg_match(
                '/^taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {

            $taxonomy =
                $args['taxonomy']
                ?? '';

            if ( is_array( $taxonomy ) ) {
                $taxonomy = reset( $taxonomy );
            }

            if ( ! taxonomy_exists( $taxonomy ) ) {
                return $args;
            }

            unset(
                $args['term_taxonomy_id']
            );

            $ids =
                tfsc_taxonomy_level_term_ids(
                    $taxonomy,
                    (int) $matches[1]
                );

            $args['include'] =
                $ids ?: [ 0 ];

            return $args;
        }


        /**
         * ====================================================
         * current_taxonomy
         * current_taxonomy_level_X
         * ====================================================
         */

        $is_current =
            'current_taxonomy' === $query_id;

        $has_level =
            preg_match(
                '/^current_taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            );

        if (
            ! $is_current &&
            ! $has_level
        ) {
            return $args;
        }


        $taxonomy =
            get_query_var(
                'tfsc_taxonomy_archive'
            );

        if (
            ! $taxonomy &&
            isset( $GLOBALS['wp_query'] )
        ) {
            $taxonomy =
                $GLOBALS['wp_query']->get(
                    'tfsc_taxonomy_archive'
                );
        }

        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            $args['include'] = [ 0 ];
            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );

        $args['taxonomy']   = $taxonomy;
        $args['hide_empty'] = false;
        $args['orderby']    = 'name';
        $args['order']      = 'ASC';


        /**
         * current_taxonomy = alle terms.
         */
        if ( $is_current ) {
            return $args;
        }


        /**
         * current_taxonomy_level_X.
         */
        $ids =
            tfsc_taxonomy_level_term_ids(
                $taxonomy,
                (int) $matches[1]
            );

        $args['include'] =
            $ids ?: [ 0 ];

        return $args;
    },
    20,
    3
);

/**
 * TFSC - Query Show More
 *
 * Elementor widget class:
 * tfsc_query_show-more
 *
 * Custom attribute:
 * data_visible-items|8
 */

add_action(
    'wp_footer',
    function() {

        if ( is_admin() ) {
            return;
        }

        ?>
        <script>
        (function () {

            function init(scope) {

                const root = scope || document;

                const widgets = [];

                if (
                    root.classList?.contains(
                        'tfsc_query_show-more'
                    )
                ) {
                    widgets.push(root);
                }

                if (root.querySelectorAll) {
                    widgets.push(
                        ...root.querySelectorAll(
                            '.tfsc_query_show-more'
                        )
                    );
                }

                widgets.forEach(
                    function (widget) {

                        widget
                            .querySelector(
                                '.tfsc-query-show-more__wrapper'
                            )
                            ?.remove();

                        const visible =
                            parseInt(
                                widget.getAttribute(
                                    'data_visible-items'
                                ),
                                10
                            ) || 8;

                        const loop =
                            widget.querySelector(
                                ':scope > .elementor-widget-container .elementor-loop-container'
                            );

                        if (!loop) {
                            return;
                        }

                        const items =
                            Array.from(
                                loop.querySelectorAll(
                                    ':scope > .e-loop-item'
                                )
                            );

                        if (!items.length) {
                            return;
                        }

                        items.forEach(
                            item => item.style.display = ''
                        );

                        if (
                            items.length <= visible
                        ) {
                            return;
                        }

                        items.slice(visible).forEach(
                            item => item.style.display = 'none'
                        );

                        const wrapper =
                            document.createElement('div');

                        wrapper.className =
                            'tfsc-query-show-more__wrapper';

                        wrapper.innerHTML = `
                            <button
                                type="button"
                                class="tfsc-query-show-more__button"
                                aria-expanded="false"
                            >
                                <span class="tfsc-query-show-more__label">
                                    Meer tonen
                                </span>
                                <span
                                    class="tfsc-query-show-more__icon"
                                    aria-hidden="true"
                                ></span>
                            </button>
                        `;

                        loop.insertAdjacentElement(
                            'afterend',
                            wrapper
                        );

                        const button =
                            wrapper.querySelector('button');

                        const label =
                            wrapper.querySelector(
                                '.tfsc-query-show-more__label'
                            );

                        button.addEventListener(
                            'click',
                            function () {

                                const expanded =
                                    button.getAttribute(
                                        'aria-expanded'
                                    ) === 'true';

                                items.slice(visible).forEach(
                                    item =>
                                        item.style.display =
                                            expanded
                                                ? 'none'
                                                : ''
                                );

                                button.setAttribute(
                                    'aria-expanded',
                                    String(!expanded)
                                );

                                button.classList.toggle(
                                    'tfsc-query-show-more__button--expanded',
                                    !expanded
                                );

                                label.textContent =
                                    expanded
                                        ? 'Meer tonen'
                                        : 'Minder tonen';
                            }
                        );
                    }
                );
            }


            document.addEventListener(
                'DOMContentLoaded',
                () => init(document)
            );


            window.addEventListener(
                'elementor/frontend/init',
                function () {

                    if (
                        typeof elementorFrontend ===
                        'undefined'
                    ) {
                        return;
                    }

                    elementorFrontend.hooks.addAction(
                        'frontend/element_ready/global',
                        function (scope) {

                            init(
                                scope?.[0] || scope
                            );
                        }
                    );
                }
            );


            new MutationObserver(
                mutations => {

                    mutations.forEach(
                        mutation => {

                            mutation.addedNodes.forEach(
                                node => {

                                    if (node.nodeType === 1) {
                                        init(node);
                                    }
                                }
                            );
                        }
                    );
                }
            ).observe(
                document.documentElement,
                {
                    childList: true,
                    subtree: true,
                }
            );

        })();
        </script>

        <style>
        .tfsc_query_show-more .tfsc-query-show-more__wrapper {
            width: 100%;
        }

        .tfsc_query_show-more .tfsc-query-show-more__button {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            cursor: pointer;
        }

        .tfsc_query_show-more .tfsc-query-show-more__icon {
            display: inline-block;
            width: 8px;
            height: 8px;
            border-right: 2px solid currentColor;
            border-bottom: 2px solid currentColor;
            transform: rotate(45deg) translateY(-2px);
            transition: transform 0.2s ease;
        }

        .tfsc_query_show-more
        .tfsc-query-show-more__button--expanded
        .tfsc-query-show-more__icon {
            transform: rotate(225deg) translateY(-2px);
        }
        </style>
        <?php
    },
    100
);

/**
 * TFSC - Vacature Button URL
 *
 * Shortcode:
 * [vacature_button_url]
 *
 * Gebruikt Pods field:
 * relationship_vacature_button_url
 *
 * Geeft altijd de native taxonomy-term URL terug,
 * dus geen TFSC combo URL.
 */

add_shortcode(
    'vacature_button_url',
    function() {

        if ( ! function_exists( 'pods' ) ) {
            return '';
        }

        $object = get_queried_object();
        $pod    = false;

        /**
         * Taxonomy archive.
         */
        if ( $object instanceof WP_Term ) {

            $pod = pods(
                $object->taxonomy,
                (int) $object->term_id
            );
        }

        /**
         * Post / CPT / Elementor preview.
         */
        if ( ! $pod ) {

            if (
                function_exists(
                    'tfsc_derived_rel_v2_get_context_post_id'
                )
            ) {
                $post_id =
                    tfsc_derived_rel_v2_get_context_post_id();

            } elseif ( $object instanceof WP_Post ) {

                $post_id =
                    (int) $object->ID;

            } else {

                $post_id =
                    get_queried_object_id();
            }

            if ( ! empty( $post_id ) ) {

                $post_type =
                    get_post_type(
                        $post_id
                    );

                if ( $post_type ) {
                    $pod =
                        pods(
                            $post_type,
                            $post_id
                        );
                }
            }
        }

        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return '';
        }

        $relations =
            $pod->field(
                'relationship_vacature_button_url'
            );

        if ( empty( $relations ) ) {
            return '';
        }

        /**
         * Eén relatie normaliseren naar array.
         */
        if (
            is_numeric( $relations ) ||
            is_object( $relations ) ||
            (
                is_array( $relations ) &&
                (
                    isset( $relations['term_id'] ) ||
                    isset( $relations['pod_item_id'] ) ||
                    isset( $relations['id'] ) ||
                    isset( $relations['ID'] )
                )
            )
        ) {
            $relations = [ $relations ];
        }

        $term = false;

        foreach ( (array) $relations as $relation ) {

            if ( is_array( $relation ) ) {

                $term_id = (int) (
                    $relation['term_id']
                    ?? $relation['pod_item_id']
                    ?? $relation['id']
                    ?? $relation['ID']
                    ?? 0
                );

                $taxonomy =
                    ! empty( $relation['taxonomy'] )
                        ? sanitize_key(
                            $relation['taxonomy']
                        )
                        : '';

            } elseif ( is_object( $relation ) ) {

                $term_id = (int) (
                    $relation->term_id
                    ?? $relation->pod_item_id
                    ?? $relation->id
                    ?? $relation->ID
                    ?? 0
                );

                $taxonomy =
                    ! empty( $relation->taxonomy )
                        ? sanitize_key(
                            $relation->taxonomy
                        )
                        : '';

            } else {

                continue;
            }

            if (
                ! $term_id ||
                ! $taxonomy ||
                ! taxonomy_exists( $taxonomy )
            ) {
                continue;
            }

            $candidate =
                get_term(
                    $term_id,
                    $taxonomy
                );

            if (
                $candidate instanceof WP_Term &&
                ! is_wp_error( $candidate )
            ) {
                $term = $candidate;
                break;
            }
        }

        if ( ! $term instanceof WP_Term ) {
            return '';
        }

        /**
         * Native term-link forceren.
         */
        $GLOBALS['tfsc_force_native_term_link'] = true;

        $url =
            get_term_link(
                $term
            );

        unset(
            $GLOBALS['tfsc_force_native_term_link']
        );

        return is_wp_error( $url )
            ? ''
            : esc_url( $url );
    }
);

/**
 * TFSC - Dynamische tekst shortcodes
 *
 * [post_title]
 * [archive_title]
 * [tfsc_pods field="..."]
 *
 * Output is platte tekst.
 */


/**
 * ============================================================
 * CONTEXT HELPERS
 * ============================================================
 */

function tfsc_text_context_post_id() {

    if (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v2_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }

    $object =
        get_queried_object();

    if ( $object instanceof WP_Post ) {
        return (int) $object->ID;
    }

    return (int) get_the_ID();
}


function tfsc_text_context_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object =
        get_queried_object();

    /**
     * Taxonomy term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /**
     * Post / CPT / Elementor preview.
     */
    $post_id =
        tfsc_text_context_post_id();

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * [post_title]
 * ============================================================
 */

add_shortcode(
    'post_title',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'before' => '',
                'after'  => '',
            ],
            $atts,
            'post_title'
        );

        $post_id =
            tfsc_text_context_post_id();

        if ( ! $post_id ) {
            return '';
        }

        $title =
            wp_strip_all_tags(
                get_the_title(
                    $post_id
                )
            );

        return '' === $title
            ? ''
            : (string) $atts['before']
                . $title
                . (string) $atts['after'];
    }
);


/**
 * ============================================================
 * [archive_title]
 * ============================================================
 */

add_shortcode(
    'archive_title',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'mode'            => 'current',
                'separator'       => ' › ',
                'label_separator' => ': ',
                'before'          => '',
                'after'           => '',
            ],
            $atts,
            'archive_title'
        );

        $term =
            get_queried_object();

        if (
            ! $term instanceof WP_Term ||
            ! taxonomy_exists(
                $term->taxonomy
            )
        ) {
            return '';
        }

        $taxonomy =
            $term->taxonomy;

        $current =
            wp_strip_all_tags(
                $term->name
            );

        $parents = [];

        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            foreach (
                array_reverse(
                    get_ancestors(
                        $term->term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                )
                as $ancestor_id
            ) {

                $ancestor =
                    get_term(
                        $ancestor_id,
                        $taxonomy
                    );

                if (
                    $ancestor instanceof WP_Term &&
                    ! is_wp_error( $ancestor )
                ) {
                    $parents[] =
                        wp_strip_all_tags(
                            $ancestor->name
                        );
                }
            }
        }

        $taxonomy_object =
            get_taxonomy(
                $taxonomy
            );

        $label =
            $taxonomy_object
            && ! empty(
                $taxonomy_object
                    ->labels
                    ->singular_name
            )
                ? wp_strip_all_tags(
                    $taxonomy_object
                        ->labels
                        ->singular_name
                )
                : '';

        $full =
            implode(
                (string) $atts['separator'],
                array_merge(
                    $parents,
                    [ $current ]
                )
            );

        switch (
            sanitize_key(
                $atts['mode']
            )
        ) {

            case 'parents':

                $output =
                    implode(
                        (string) $atts['separator'],
                        $parents
                    );

                break;

            case 'full':

                $output =
                    $full;

                break;

            case 'label_current':

                $output =
                    $label
                        ? $label
                            . (string) $atts['label_separator']
                            . $current
                        : $current;

                break;

            case 'label_full':

                $output =
                    $label
                        ? $label
                            . (string) $atts['label_separator']
                            . $full
                        : $full;

                break;

            default:

                $output =
                    $current;
        }

        if ( '' === $output ) {
            return '';
        }

        return
            (string) $atts['before']
            . $output
            . (string) $atts['after'];
    }
);


/**
 * ============================================================
 * [tfsc_pods]
 * ============================================================
 */

add_shortcode(
    'tfsc_pods',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'field'     => '',
                'before'    => '',
                'after'     => '',
                'separator' => ', ',
            ],
            $atts,
            'tfsc_pods'
        );

        $field =
            sanitize_key(
                $atts['field']
            );

        if ( ! $field ) {
            return '';
        }

        $pod =
            tfsc_text_context_pod();

        if ( ! $pod ) {
            return '';
        }

        $value =
            $pod->field(
                $field
            );

        if (
            null === $value ||
            false === $value ||
            '' === $value
        ) {
            return '';
        }

        /**
         * Normaal tekstveld.
         */
        if (
            ! is_array( $value ) &&
            ! is_object( $value )
        ) {

            $output =
                wp_strip_all_tags(
                    (string) $value
                );

        } else {

            /**
             * Eén relationship normaliseren.
             */
            if (
                is_object( $value ) ||
                (
                    is_array( $value ) &&
                    (
                        isset( $value['name'] ) ||
                        isset( $value['post_title'] ) ||
                        isset( $value['title'] )
                    )
                )
            ) {
                $value = [ $value ];
            }

            $names = [];

            foreach (
                (array) $value
                as $relation
            ) {

                if ( is_array( $relation ) ) {

                    $name =
                        $relation['name']
                        ?? $relation['post_title']
                        ?? $relation['title']
                        ?? '';

                } elseif ( is_object( $relation ) ) {

                    $name =
                        $relation->name
                        ?? $relation->post_title
                        ?? $relation->title
                        ?? '';

                } else {

                    $name = '';
                }

                $name =
                    wp_strip_all_tags(
                        (string) $name
                    );

                if ( '' !== $name ) {
                    $names[] = $name;
                }
            }

            $output =
                implode(
                    (string) $atts['separator'],
                    array_values(
                        array_unique(
                            $names
                        )
                    )
                );
        }

        if ( '' === $output ) {
            return '';
        }

        return
            (string) $atts['before']
            . $output
            . (string) $atts['after'];
    }
);

/**
 * TFSC - Taxonomy Base Archives + Elementor Theme Builder Conditions
 *
 * Voegt taxonomy-base archives toe, zoals:
 * /beroepengids/functie-inhoud/
 *
 * Query var:
 * tfsc_taxonomy_archive
 */


/**
 * ============================================================
 * QUERY VAR + REWRITE
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_taxonomy_archive';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        $taxonomies = get_taxonomies(
            [ 'public' => true ],
            'objects'
        );

        foreach ( $taxonomies as $taxonomy ) {

            $slug = $taxonomy->rewrite['slug'] ?? '';

            if ( ! $slug ) {
                continue;
            }

            $slug = trim( $slug, '/' );

            if ( '' === $slug ) {
                continue;
            }

            add_rewrite_rule(
                '^' . preg_quote( $slug, '#' ) . '/?$',
                'index.php?tfsc_taxonomy_archive='
                . urlencode( $taxonomy->name ),
                'top'
            );
        }
    },
    99
);


/**
 * ============================================================
 * HELPERS
 * ============================================================
 */

function tfsc_get_current_taxonomy_archive() {

    $name =
        get_query_var(
            'tfsc_taxonomy_archive'
        );

    if ( ! $name ) {
        return false;
    }

    $taxonomy =
        get_taxonomy(
            $name
        );

    return (
        $taxonomy &&
        ! empty( $taxonomy->public )
    )
        ? $taxonomy
        : false;
}


function tfsc_is_taxonomy_base_archive() {

    return (bool)
        tfsc_get_current_taxonomy_archive();
}


function tfsc_is_beroepengids_taxonomy(
    $taxonomy_name
) {

    $taxonomy =
        get_taxonomy(
            $taxonomy_name
        );

    if (
        ! $taxonomy ||
        empty( $taxonomy->public )
    ) {
        return false;
    }

    $slug =
        trim(
            (string) (
                $taxonomy->rewrite['slug']
                ?? ''
            ),
            '/'
        );

    return (
        $slug &&
        0 === strpos(
            $slug,
            'beroepengids/'
        )
    );
}


function tfsc_is_beroepengids_taxonomy_base_archive() {

    $taxonomy =
        tfsc_get_current_taxonomy_archive();

    return (
        $taxonomy &&
        tfsc_is_beroepengids_taxonomy(
            $taxonomy->name
        )
    );
}


function tfsc_is_beroepengids_taxonomy_term_archive() {

    $term =
        get_queried_object();

    return (
        $term instanceof WP_Term &&
        tfsc_is_beroepengids_taxonomy(
            $term->taxonomy
        )
    );
}


