 */

add_action(
    'elementor/theme/register_conditions',
    function( $conditions_manager ) {

        $base_class =
            '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base';

        if ( ! class_exists( $base_class ) ) {
            return;
        }


        if (
            ! class_exists(
                'TFSC_Beroepengids_Taxonomy_Base_Condition'
            )
        ) {

            class TFSC_Beroepengids_Taxonomy_Base_Condition
                extends \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type(): string {
                    return 'archive';
                }

                public static function get_priority(): int {
                    return 90;
                }

                public function get_name(): string {
                    return 'tfsc_beroepengids_taxonomy_base_archive';
                }

                public function get_label(): string {
                    return 'TFSC Beroepengids Taxonomy Base Archives';
                }

                public function check( $args ): bool {
                    return tfsc_is_beroepengids_taxonomy_base_archive();
                }
            }
        }


        if (
            ! class_exists(
                'TFSC_Beroepengids_Taxonomy_Term_Condition'
            )
        ) {

            class TFSC_Beroepengids_Taxonomy_Term_Condition
                extends \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type(): string {
                    return 'archive';
                }

                public static function get_priority(): int {
                    return 91;
                }

                public function get_name(): string {
                    return 'tfsc_beroepengids_taxonomy_term_archive';
                }

                public function get_label(): string {
                    return 'TFSC Beroepengids Taxonomy Term Archives';
                }

                public function check( $args ): bool {
                    return tfsc_is_beroepengids_taxonomy_term_archive();
                }
            }
        }


        $archive =
            $conditions_manager
                ->get_condition(
                    'archive'
                );

        if ( ! $archive ) {
            return;
        }

        $archive->register_sub_condition(
            new TFSC_Beroepengids_Taxonomy_Base_Condition()
        );

        $archive->register_sub_condition(
            new TFSC_Beroepengids_Taxonomy_Term_Condition()
        );
    },
    100
);

/**
 * TFSC - Elementor Posts filteren via Pods taxonomy relationships
 *
 * Query ID:
 * relationship_posts
 *
 * Doel:
 * Filtert een Elementor Posts/Loop Grid automatisch op basis van de
 * Pods relationshipvelden van de huidige post, CPT of taxonomy-term.
 *
 * Belangrijk:
 * - RAW Pods relationshipdata is leidend.
 * - Verschillende taxonomies = AND.
 * - Meerdere terms binnen dezelfde taxonomy = IN / OR.
 * - Elementor Source blijft leidend.
 * - relationship_vacature_button_url wordt bewust genegeerd.
 * - Werkt ook in Elementor Theme Builder preview voor posts/CPT's.
 */


/**
 * ============================================================
 * CONTEXT + POD
 * ============================================================
 *
 * Bepaalt het Pods-object van de huidige context:
 *
 * - taxonomy archive → Pod van de huidige term;
 * - post / CPT → Pod van de huidige post;
 * - Elementor Theme Builder → gebruikt indien beschikbaar
 *   tfsc_derived_rel_v2_get_context_post_id() om de echte
 *   preview-post te vinden.
 */

function tfsc_relposts_v3_get_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();

    /*
     * Taxonomy term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /*
     * Post / CPT / Elementor preview.
     */
    $post_id = 0;

    if (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v2_get_context_post_id();
    }

    if (
        ! $post_id &&
        $object instanceof WP_Post &&
        'elementor_library'
        !==
        get_post_type( $object->ID )
    ) {
        $post_id =
            (int) $object->ID;
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * RAW RELATIONSHIP NORMALISEREN
 * ============================================================
 *
 * Pods kan relationshipdata als array of object teruggeven.
 * Deze functie maakt daar steeds dit formaat van:
 *
 * [
 *     [
 *         'taxonomy' => 'functie-inhoud',
 *         'term_id'  => 220,
 *     ],
 * ]
 *
 * De taxonomy wordt dus NIET afgeleid uit de fieldnaam.
 * De daadwerkelijke RAW relationshipdata bepaalt welke taxonomy
 * en term gebruikt worden.
 */

function tfsc_relposts_v3_normalize_relationship(
    $value
) {

    if ( empty( $value ) ) {
        return [];
    }

    /*
     * Eén relationship normaliseren naar een lijst.
     */
    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['taxonomy'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    if ( ! is_array( $value ) ) {
        return [];
    }

    $result = [];

    foreach ( $value as $relation ) {

        if ( is_array( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

        } elseif ( is_object( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

        } else {

            continue;
        }

        /*
         * Alleen echte, bestaande taxonomy-terms accepteren.
         */
        if (
            ! $taxonomy ||
            ! $term_id ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            $result[] = [
                'taxonomy' => $taxonomy,
                'term_id'  => $term_id,
            ];
        }
    }

    return $result;
}


/**
 * ============================================================
 * TAXONOMY HOORT BIJ ELEMENTOR SOURCE?
 * ============================================================
 *
 * Een relationship wordt alleen gebruikt als de betreffende
 * taxonomy gekoppeld is aan het post type dat Elementor als
 * Source gebruikt.
 *
 * Voorbeeld:
 *
 * Elementor Source = vacature
 * relationship → functie-inhoud
 *
 * Dan wordt die relationship alleen gebruikt wanneer
 * functie-inhoud daadwerkelijk aan vacature gekoppeld is.
 */

function tfsc_relposts_v3_taxonomy_matches_source(
    $taxonomy,
    $post_types
) {

    $object =
        get_taxonomy(
            $taxonomy
        );

    if ( ! $object ) {
        return false;
    }

    return (bool) array_intersect(
        (array) $post_types,
        (array) $object->object_type
    );
}


/**
 * ============================================================
 * ELEMENTOR QUERY
 * ============================================================
 *
 * Query ID in Elementor:
 *
 * relationship_posts
 *
 * Werking:
 *
 * relationship_functienaam
 * → Field Service Engineer
 *
 * relationship_functie-inhoud
 * → Service
 * → Inbedrijfstellen
 *
 * wordt:
 *
 * functienaam = Field Service Engineer
 *
 * AND
 *
 * functie-inhoud IN (Service, Inbedrijfstellen)
 *
 * Bestaande Elementor tax_query blijft behouden en wordt met
 * deze relationship-query gecombineerd via AND.
 */

add_action(
    'elementor/query/relationship_posts',
    function( $query ) {

        $pod =
            tfsc_relposts_v3_get_pod();

        if ( ! $pod ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Elementor Source.
         */
        $post_types =
            array_values(
                array_filter(
                    (array) $query->get( 'post_type' )
                )
            );

        if ( ! $post_types ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        $fields =
            $pod->fields();

        if ( ! is_array( $fields ) || ! $fields ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Relationship terms groeperen per taxonomy.
         *
         * Bijvoorbeeld:
         *
         * [
         *     'functienaam'    => [100],
         *     'functie-inhoud' => [220, 221],
         * ]
         */
        $groups = [];

        foreach ( $fields as $field_name => $definition ) {

            /*
             * Alleen relationship_* fields.
             *
             * relationship_vacature_button_url wordt uitgesloten,
             * omdat dat field alleen de vacaturebutton bepaalt.
             */
            if (
                ! is_string( $field_name ) ||
                0 !== strpos(
                    $field_name,
                    'relationship_'
                ) ||
                'relationship_vacature_button_url'
                ===
                $field_name
            ) {
                continue;
            }

            /*
             * RAW Pods relationship uitlezen.
             *
             * Bewust geen traversal zoals:
             * $pod->field( $field_name . '.term_id' )
             */
            $relationships =
                tfsc_relposts_v3_normalize_relationship(
                    $pod->field(
                        $field_name
                    )
                );

            foreach (
                $relationships
                as $relationship
            ) {

                $taxonomy =
                    $relationship['taxonomy'];

                /*
                 * Alleen gebruiken als taxonomy bij de
                 * Elementor Source hoort.
                 */
                if (
                    ! tfsc_relposts_v3_taxonomy_matches_source(
                        $taxonomy,
                        $post_types
                    )
                ) {
                    continue;
                }

                $groups[ $taxonomy ][] =
                    (int) $relationship['term_id'];
            }
        }

        /*
         * Dubbele en ongeldige IDs verwijderen.
         */
        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $ids
                            )
                        )
                    )
                );

            if ( $ids ) {
                $groups[ $taxonomy ] = $ids;
            } else {
                unset( $groups[ $taxonomy ] );
            }
        }

        /*
         * Geen bruikbare relationships:
         * bewust geen posts tonen.
         */
        if ( ! $groups ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Verschillende taxonomies = AND.
         * Meerdere terms binnen taxonomy = IN.
         */
        $relationship_query = [
            'relation' => 'AND',
        ];

        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $relationship_query[] = [
                'taxonomy'         => $taxonomy,
                'field'            => 'term_id',
                'terms'            => $ids,
                'operator'         => 'IN',
                'include_children' => true,
            ];
        }

        /*
         * Bestaande Elementor tax_query bewaren.
         */
        $existing =
            $query->get(
                'tax_query'
            );

        $query->set(
            'tax_query',
            is_array( $existing ) &&
            $existing
                ? [
                    'relation' => 'AND',
                    $existing,
                    $relationship_query,
                ]
                : $relationship_query
        );
    },
    20,
    1
);

/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 3
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een Beroepengids taxonomy-term:
 *
 * huidige term
 * → Pods relationship_{vacature-taxonomy}
 * → relevante OPEN vacatures
 * → target taxonomy terms uit die vacatures
 * → Elementor Taxonomy Loop
 *
 * Voorbeeld:
 *
 * beroep_functie-inhoud → Inbedrijfstellen
 *
 * relationship_functie-inhoud
 * → functie-inhoud → Inbedrijfstellen
 *
 * Elementor Query ID:
 *
 * archive_relationship_{taxonomy}_level_{nummer}
 *
 * Voorbeelden:
 *
 * archive_relationship_locatie_level_2
 * archive_relationship_kennisgebied_level_0
 * archive_relationship_bedrijfssector_level_0
 *
 * Elementor Source moet overeenkomen met de taxonomy
 * uit de Query ID.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_taxrel_v3_vacancy_post_type() {
    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}

function tfsc_taxrel_v3_status_taxonomy() {
    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}

function tfsc_taxrel_v3_open_status() {
    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}

function tfsc_taxrel_v3_combo_base() {
    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. HUIDIGE TAXONOMY TERM
 * ============================================================
 *
 * Belangrijk voor Elementor:
 *
 * De preview-iframe heeft eerst een echte WP_Term-context.
 * Elementor rendert daarna in wp-admin opnieuw met het
 * Theme Builder template als WP_Post.
 *
 * Daarom wordt de preview-term kort opgeslagen in een transient
 * en in de admin-render opnieuw opgehaald.
 *
 * Deze editorfix is bewust behouden.
 */

function tfsc_taxrel_v3_current_term() {

    static $cached = null;

    if ( null !== $cached ) {
        return $cached;
    }

    $object = get_queried_object();

    /**
     * Normale taxonomy archive / Elementor preview iframe.
     */
    if (
        $object instanceof WP_Term &&
        ! empty( $object->term_id ) &&
        ! empty( $object->taxonomy ) &&
        taxonomy_exists( $object->taxonomy )
    ) {

        if ( is_user_logged_in() ) {
            set_transient(
                'tfsc_taxrel_v3_preview_' . get_current_user_id(),
                [
                    'term_id'  => (int) $object->term_id,
                    'taxonomy' => $object->taxonomy,
                ],
                5 * MINUTE_IN_SECONDS
            );
        }

        return $cached = $object;
    }

    /**
     * Elementor admin-render.
     */
    if (
        is_admin() &&
        $object instanceof WP_Post &&
        is_user_logged_in()
    ) {

        $preview = get_transient(
            'tfsc_taxrel_v3_preview_' . get_current_user_id()
        );

        if (
            is_array( $preview ) &&
            ! empty( $preview['term_id'] ) &&
            ! empty( $preview['taxonomy'] ) &&
            taxonomy_exists( $preview['taxonomy'] )
        ) {

            $settings = get_post_meta(
                $object->ID,
                '_elementor_page_settings',
                true
            );

            $preview_type =
                is_array( $settings )
                    ? ( $settings['preview_type'] ?? '' )
                    : '';

            if (
                $preview_type ===
                'taxonomy/' . $preview['taxonomy']
            ) {

                $term = get_term(
                    (int) $preview['term_id'],
                    $preview['taxonomy']
                );

                if (
                    $term instanceof WP_Term &&
                    ! is_wp_error( $term )
                ) {
                    return $cached = $term;
                }
            }
        }
    }

    return $cached = false;
}


/**
 * ============================================================
 * 3. PODS OBJECT
 * ============================================================
 */

function tfsc_taxrel_v3_current_pod() {

    static $resolved = false;
    static $pod = false;

    if ( $resolved ) {
        return $pod;
    }

    $resolved = true;

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $term = tfsc_taxrel_v3_current_term();

    if ( ! $term ) {
        return false;
    }

    $pod = pods(
        $term->taxonomy,
        (int) $term->term_id
    );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        $pod = false;
    }

    return $pod;
}


/**
 * ============================================================
 * 4. SOURCE TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functie-inhoud
 * → functie-inhoud
 *
 * beroepengids_kennisgebied
 * → kennisgebied
 */

function tfsc_taxrel_v3_normalize_source_taxonomy( $taxonomy ) {

    $taxonomy = sanitize_key( $taxonomy );

    foreach (
        [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ]
        as $prefix
    ) {
        if ( 0 === strpos( $taxonomy, $prefix ) ) {
            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen( $prefix )
                )
            );
        }
    }

    return $taxonomy;
}


/**
 * ============================================================
 * 5. SOURCE RELATIONSHIP FIELD
 * ============================================================
 *
 * beroep_functie-inhoud
 * → relationship_functie-inhoud
 *
 * relationship_vacature_button_url wordt bewust uitgesloten.
 */

function tfsc_taxrel_v3_source_field() {

    static $resolved = false;
    static $field = '';

    if ( $resolved ) {
        return $field;
    }

    $resolved = true;

    $term = tfsc_taxrel_v3_current_term();
    $pod  = tfsc_taxrel_v3_current_pod();

    if (
        ! $term ||
        ! $pod
    ) {
        return '';
    }

    $fields = $pod->fields();

    if ( ! is_array( $fields ) ) {
        return '';
    }

    $normalized =
        tfsc_taxrel_v3_normalize_source_taxonomy(
            $term->taxonomy
        );

    foreach (
        array_unique(
            [
                'relationship_' . $term->taxonomy,
                'relationship_' . $normalized,
            ]
        )
        as $candidate
    ) {

        if (
            'relationship_vacature_button_url'
            ===
            $candidate
        ) {
            continue;
        }

        if (
            array_key_exists(
                $candidate,
                $fields
            )
        ) {
            return $field = $candidate;
        }
    }

    return '';
}


/**
 * ============================================================
 * 6. SOURCE RELATIONSHIPS
 * ============================================================
 *
 * Resultaat bijvoorbeeld:
 *
 * [
 *     'functie-inhoud' => [220]
 * ]
 *
 * RAW Pods relationshipdata blijft leidend.
 * Taxonomy uit RAW data heeft voorrang.
 * Alleen als die ontbreekt wordt de fieldnaam als fallback gebruikt.
 */

function tfsc_taxrel_v3_source_relationships() {

    static $cache = null;

    if ( null !== $cache ) {
        return $cache;
    }

    $cache = [];

    $pod =
        tfsc_taxrel_v3_current_pod();

    $field =
        tfsc_taxrel_v3_source_field();

    if (
        ! $pod ||
        ! $field
    ) {
        return [];
    }

    $value =
        $pod->field(
            $field
        );

    if ( empty( $value ) ) {
        return [];
    }

    $field_taxonomy =
        sanitize_key(
            substr(
                $field,
                strlen( 'relationship_' )
            )
        );

    /**
     * Eén relationship normaliseren naar een lijst.
     */
    if (
        is_numeric( $value ) ||
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    foreach (
        (array) $value
        as $relation
    ) {

        $term_id  = 0;
        $taxonomy = '';

        if ( is_array( $relation ) ) {

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

        } elseif ( is_object( $relation ) ) {

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

        } elseif ( is_numeric( $relation ) ) {

            $term_id =
                (int) $relation;
        }

        if ( ! $taxonomy ) {
            $taxonomy = $field_taxonomy;
        }

        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            ! $term instanceof WP_Term ||
            is_wp_error( $term )
        ) {
            continue;
        }

        $cache[ $taxonomy ][] =
            $term_id;
    }

    foreach (
        $cache
        as $taxonomy => $ids
    ) {
        $cache[ $taxonomy ] =
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }

    return array_filter( $cache );
}


/**
 * ============================================================
 * 7. OPEN VACATURES
 * ============================================================
 *
 * Zoekt alleen gepubliceerde vacatures die voldoen aan de
 * source relationships én vac_status=open.
 */

function tfsc_taxrel_v3_vacancy_ids( $source_groups ) {

    static $cache = [];

    if ( empty( $source_groups ) ) {
        return [];
    }

    $cache_key =
        md5(
            serialize(
                $source_groups
            )
        );

    if ( isset( $cache[ $cache_key ] ) ) {
        return $cache[ $cache_key ];
    }

    $tax_query = [
        'relation' => 'AND',
    ];

    foreach (
        $source_groups
        as $taxonomy => $ids
    ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $ids
        ) {
            continue;
        }

        $tax_query[] = [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => $ids,
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    if ( count( $tax_query ) <= 1 ) {
        return [];
    }

    $status_taxonomy =
        tfsc_taxrel_v3_status_taxonomy();

    if ( taxonomy_exists( $status_taxonomy ) ) {
        $tax_query[] = [
            'taxonomy'         => $status_taxonomy,
            'field'            => 'slug',
            'terms'            => [
                tfsc_taxrel_v3_open_status(),
            ],
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    $ids = get_posts( [
        'post_type'      =>
            tfsc_taxrel_v3_vacancy_post_type(),

        'post_status'    =>
            'publish',

        'posts_per_page' =>
            -1,

        'fields'         =>
            'ids',

        'no_found_rows'  =>
            true,

        'tax_query'      =>
            $tax_query,
    ] );

    return $cache[ $cache_key ] =
        array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );
}


/**
 * ============================================================
 * 8. TARGET TERMS UIT VACATURES
 * ============================================================
 *
 * Haalt de target taxonomy terms uit alle relevante vacatures.
 * Bij hiërarchische taxonomies worden ook ancestors toegevoegd.
 */

function tfsc_taxrel_v3_target_terms(
    $vacancy_ids,
    $taxonomy
) {

    if (
        empty( $vacancy_ids ) ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }

    /**
     * Eén query voor alle vacatures.
     */
    $ids = wp_get_object_terms(
        array_map(
            'intval',
            $vacancy_ids
        ),
        $taxonomy,
        [
            'fields' => 'ids',
        ]
    );

    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }

    $ids =
        array_map(
            'intval',
            $ids
        );

    if (
        is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {
        foreach ( $ids as $term_id ) {
            $ids = array_merge(
                $ids,
                get_ancestors(
                    $term_id,
                    $taxonomy,
                    'taxonomy'
                )
            );
        }
    }

    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 9. EXACT LEVEL
 * ============================================================
 *
 * level 0 = top-level
 * level 1 = child van level 0
 * level 2 = child van level 1
 */

function tfsc_taxrel_v3_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( empty( $ids ) ) {
        return [];
    }

    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {
        return 0 === (int) $level
            ? array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            )
            : [];
    }

    return array_values(
        array_filter(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            ),
            function( $term_id ) use (
                $taxonomy,
                $level
            ) {
                return count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === (int) $level;
            }
        )
    );
}


/**
 * ============================================================
 * 10. QUERY ID
 * ============================================================
 *
 * archive_relationship_{taxonomy}_level_{nummer}
 */

function tfsc_taxrel_v3_parse_query_id( $query_id ) {

    if (
        ! preg_match(
            '/^archive_relationship_(.+)_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }

    $taxonomy =
        sanitize_key(
            $matches[1]
        );

    if (
        ! taxonomy_exists(
            $taxonomy
        )
    ) {
        return false;
    }

    return [
        'taxonomy' => $taxonomy,
        'level'    => (int) $matches[2],
    ];
}


/**
 * ============================================================
 * 11. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Elementor Source moet overeenkomen met de taxonomy uit
 * de Query ID.
 *
 * Priority 40 blijft bewust behouden.
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings['post_taxonomy_term_taxonomy_id']
            ??
            '';

        $parsed =
            tfsc_taxrel_v3_parse_query_id(
                $query_id
            );

        if (
            ! $parsed ||
            ! tfsc_taxrel_v3_current_term()
        ) {
            return $args;
        }

        $taxonomy =
            $parsed['taxonomy'];

        if (
            $taxonomy ===
            tfsc_taxrel_v3_status_taxonomy()
        ) {
            return $args;
        }

        /**
         * Elementor Source controleren.
         */
        $source_taxonomy =
            $args['taxonomy']
            ??
            $settings['post_taxonomy_query_post_type']
            ??
            '';

        if ( is_array( $source_taxonomy ) ) {
            $source_taxonomy =
                reset(
                    $source_taxonomy
                );
        }

        if (
            sanitize_key( $source_taxonomy )
            !==
            $taxonomy
        ) {
            return $args;
        }

        $source_groups =
            tfsc_taxrel_v3_source_relationships();

        $vacancy_ids =
            tfsc_taxrel_v3_vacancy_ids(
                $source_groups
            );

        $target_ids =
            tfsc_taxrel_v3_target_terms(
                $vacancy_ids,
                $taxonomy
            );

        $target_ids =
            tfsc_taxrel_v3_filter_level(
                $target_ids,
                $taxonomy,
                $parsed['level']
            );

        if ( ! $target_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        unset(
            $args['term_taxonomy_id']
        );

        $args['taxonomy']     = $taxonomy;
        $args['include']      = $target_ids;
        $args['hide_empty']   = false;
        $args['hierarchical'] = false;

        /**
         * Marker voor sorteerfix.
         */
        $args['tfsc_taxrel_v3'] =
            1;

        /**
         * Marker voor term-link omzetting.
         */
        $GLOBALS[
            'tfsc_taxrel_v3_active_targets'
        ][ $taxonomy ] =
            true;

        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * 12. SORTERING OP NAAM
 * ============================================================
 *
 * WordPress groepeert hiërarchische terms normaal per parent.
 * Daarom wordt de uiteindelijke termlijst hier na afloop
 * opnieuw alfabetisch gesorteerd.
 *
 * Priority 9999 blijft bewust behouden.
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty( $args['tfsc_taxrel_v3'] ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }

        if (
            isset( $args['orderby'] ) &&
            'name' !== strtolower(
                (string) $args['orderby']
            )
        ) {
            return $terms;
        }

        $order =
            strtoupper(
                (string) (
                    $args['order']
                    ?? 'ASC'
                )
            );

        usort(
            $terms,
            function( $a, $b ) use ( $order ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }

                $compare =
                    strnatcasecmp(
                        remove_accents(
                            $a->name
                        ),
                        remove_accents(
                            $b->name
                        )
                    );

                return 'DESC' === $order
                    ? -$compare
                    : $compare;
            }
        );

        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 13. TERM PATH
 * ============================================================
 *
 * Voor hiërarchische taxonomies:
 *
 * noord-brabant/tilburg
 *
 * in plaats van alleen:
 *
 * tilburg
 */

function tfsc_taxrel_v3_term_path( $term ) {

    if ( ! $term instanceof WP_Term ) {
        return '';
    }

    $slugs = [];

    if (
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
    ) {

        foreach (
            array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            )
            as $ancestor_id
        ) {

            $ancestor =
                get_term(
                    $ancestor_id,
                    $term->taxonomy
                );

            if (
                $ancestor instanceof WP_Term &&
                ! is_wp_error( $ancestor )
            ) {
                $slugs[] =
                    $ancestor->slug;
            }
        }
    }

    $slugs[] =
        $term->slug;

    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 14. COMBO URL
 * ============================================================
 *
 * Bouwt:
 *
 * /vacatures/{source-taxonomy}/{source-term}/{target-taxonomy}/{target-term}/
 */

function tfsc_taxrel_v3_combo_url(
    $target_term
) {

    if ( ! $target_term instanceof WP_Term ) {
        return false;
    }

    $source_groups =
        tfsc_taxrel_v3_source_relationships();

    if ( ! $source_groups ) {
        return false;
    }

    $parts = [
        tfsc_taxrel_v3_combo_base(),
    ];

    foreach (
        $source_groups
        as $taxonomy => $ids
    ) {

        foreach ( $ids as $term_id ) {

            if (
                $taxonomy ===
                $target_term->taxonomy &&
                (int) $term_id ===
                (int) $target_term->term_id
            ) {
                continue;
            }

            $source_term =
                get_term(
                    $term_id,
                    $taxonomy
                );

            if (
                ! $source_term instanceof WP_Term ||
                is_wp_error( $source_term )
            ) {
                continue;
            }

            $parts[] =
                $taxonomy;

            $parts[] =
                tfsc_taxrel_v3_term_path(
                    $source_term
                );
        }
    }

    $parts[] =
        $target_term->taxonomy;

    $parts[] =
        tfsc_taxrel_v3_term_path(
            $target_term
        );

    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                fn( $part ) =>
                    trim(
                        $part,
                        '/'
                    ),
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 15. TERM LINKS → COMBO URL
 * ============================================================
 *
 * Alleen terms die door deze derived relationship query zijn
 * geactiveerd krijgen een combo-link.
 *
 * tfsc_force_native_term_link blijft gerespecteerd zodat
 * bijvoorbeeld [vacature_button_url] altijd de native
 * taxonomy-term URL kan ophalen.
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! tfsc_taxrel_v3_current_term()
        ) {
            return $termlink;
        }

        if (
            empty(
                $GLOBALS[
                    'tfsc_taxrel_v3_active_targets'
                ][ $taxonomy ]
            )
        ) {
            return $termlink;
        }

        $url =
            tfsc_taxrel_v3_combo_url(
                $term
            );

        return $url
            ?: $termlink;
    },
    40,
    3
);

/**
 * TFSC - Post Terms Buttons
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Toont de taxonomy terms die aan de huidige post / CPT
 * gekoppeld zijn als klikbare buttons.
 *
 * Werkt ook in Elementor Theme Builder previews wanneer
 * tfsc_derived_rel_v2_get_context_post_id() beschikbaar is.
 *
 *
 * ============================================================
 * SHORTCODE
 * ============================================================
 *
 * Alle publieke taxonomies met gekoppelde terms:
 *
 * [tfsc_post_terms]
 *
 * Eén taxonomy:
 *
 * [tfsc_post_terms taxonomy="kennisgebied"]
 *
 * Meerdere taxonomies:
 *
 * [tfsc_post_terms taxonomy="functienaam,kennisgebied,locatie"]
 *
 *
 * ============================================================
 * LINKS
 * ============================================================
 *
 * Iedere term linkt naar zijn normale native taxonomy URL.
 *
 * De TFSC combo-link omzetting wordt bewust tijdelijk
 * uitgeschakeld via:
 *
 * tfsc_force_native_term_link
 *
 *
 * ============================================================
 * OUTPUT
 * ============================================================
 *
 * .tfsc-post-terms
 * .tfsc-post-terms__item
 * .tfsc-post-terms__item--{taxonomy}
 */
/**
 * ============================================================
 * CSS
 * ============================================================
 *
 * Voeg onderstaande CSS toe in Elementor Custom CSS,
 * Site Settings of je eigen stylesheet:
 *
 *
 * .tfsc-post-terms {
 *     display: flex;
 *     flex-wrap: wrap;
 *     gap: 8px;
 * }
 *
 * .tfsc-post-terms__item {
 *     display: inline-flex;
 *     align-items: center;
 *     padding: 8px 14px;
 *     border: 1px solid currentColor;
 *     border-radius: 999px;
 *     text-decoration: none;
 * }
 *
 *
 * ============================================================
 * TAXONOMY-SPECIFIEKE STYLING
 * ============================================================
 *
 * Iedere button krijgt ook een class met de taxonomy name.
 *
 * Bijvoorbeeld:
 *
 * .tfsc-post-terms__item--kennisgebied
 * .tfsc-post-terms__item--functienaam
 * .tfsc-post-terms__item--locatie
 *
 * Daardoor kun je taxonomies afzonderlijk stylen.
 *
 * Voorbeeld:
 *
 * .tfsc-post-terms__item--kennisgebied {
 *     font-weight: 600;
 * }
 *
 *
 * ============================================================
 * HOVER
 * ============================================================
 *
 * Eventueel:
 *
 * .tfsc-post-terms__item:hover {
 *     text-decoration: none;
 * }
 */

add_shortcode(
    'tfsc_post_terms',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'taxonomy' => '',
            ],
            $atts,
            'tfsc_post_terms'
        );


        /**
         * ====================================================
         * HUIDIGE POST / ELEMENTOR PREVIEW
         * ====================================================
         */

        $post_id =
            function_exists(
                'tfsc_derived_rel_v2_get_context_post_id'
            )
                ? (int) tfsc_derived_rel_v2_get_context_post_id()
                : 0;

        if ( ! $post_id ) {

            $object =
                get_queried_object();

            $post_id =
                $object instanceof WP_Post
                    ? (int) $object->ID
                    : (int) get_the_ID();
        }

        if ( ! $post_id ) {
            return '';
        }

        $post_type =
            get_post_type(
                $post_id
            );

        if ( ! $post_type ) {
            return '';
        }


        /**
         * ====================================================
         * TAXONOMIES BEPALEN
         * ====================================================
         *
         * Zonder taxonomy="" worden automatisch alle publieke
         * taxonomies van het huidige post type gebruikt.
         */

        $taxonomies =
            $atts['taxonomy']
                ? array_filter(
                    array_map(
                        'sanitize_key',
                        preg_split(
                            '/\s*,\s*/',
                            $atts['taxonomy']
                        )
                    )
                )
                : get_object_taxonomies(
                    $post_type,
                    'names'
                );

        $taxonomies =
            array_filter(
                $taxonomies,
                function( $taxonomy ) use ( $post_type ) {

                    $object =
                        get_taxonomy(
                            $taxonomy
                        );

                    return (
                        $object &&
                        ! empty( $object->public ) &&
                        in_array(
                            $post_type,
                            (array) $object->object_type,
                            true
                        )
                    );
                }
            );

        if ( ! $taxonomies ) {
            return '';
        }


        /**
         * ====================================================
         * TERMS + BUTTONS
         * ====================================================
         *
         * Alleen terms die daadwerkelijk aan de huidige
         * post gekoppeld zijn worden weergegeven.
         */

        $buttons = [];

        foreach ( $taxonomies as $taxonomy ) {

            $terms =
                wp_get_post_terms(
                    $post_id,
                    $taxonomy
                );

            if (
                is_wp_error( $terms ) ||
                ! $terms
            ) {
                continue;
            }

            foreach ( $terms as $term ) {

                if ( ! $term instanceof WP_Term ) {
                    continue;
                }

                /**
                 * Native term URL forceren.
                 * Hierdoor maken andere TFSC term_link filters
                 * hier geen vacature-combo URL van.
                 */
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ] = true;

                $url =
                    get_term_link(
                        $term
                    );

                unset(
                    $GLOBALS[
                        'tfsc_force_native_term_link'
                    ]
                );

                if ( is_wp_error( $url ) ) {
                    continue;
                }

                $buttons[] =
                    sprintf(
                        '<a class="tfsc-post-terms__item tfsc-post-terms__item--%1$s" href="%2$s">%3$s</a>',
                        esc_attr(
                            sanitize_html_class(
                                $taxonomy
                            )
                        ),
                        esc_url( $url ),
                        esc_html( $term->name )
                    );
            }
        }

        if ( ! $buttons ) {
            return '';
        }

        return
            '<div class="tfsc-post-terms">'
            . implode( '', $buttons )
            . '</div>';
    }
);

/**
 * TFSC - Elementor Posts filteren via Pods taxonomy relationships
 *
 * Query ID:
 * relationship_posts
 *
 * Doel:
 * Filtert een Elementor Posts/Loop Grid automatisch op basis van de
 * Pods relationshipvelden van de huidige post, CPT of taxonomy-term.
 *
 * Belangrijk:
 * - RAW Pods relationshipdata is leidend.
 * - Verschillende taxonomies = AND.
 * - Meerdere terms binnen dezelfde taxonomy = IN / OR.
 * - Elementor Source blijft leidend.
 * - relationship_vacature_button_url wordt bewust genegeerd.
 * - Werkt ook in Elementor Theme Builder preview voor posts/CPT's.
 */


/**
 * ============================================================
 * CONTEXT + POD
 * ============================================================
 *
 * Bepaalt het Pods-object van de huidige context:
 *
 * - taxonomy archive → Pod van de huidige term;
 * - post / CPT → Pod van de huidige post;
 * - Elementor Theme Builder → gebruikt indien beschikbaar
 *   tfsc_derived_rel_v2_get_context_post_id() om de echte
 *   preview-post te vinden.
 */

function tfsc_relposts_v3_get_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();

    /*
     * Taxonomy term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /*
     * Post / CPT / Elementor preview.
     */
    $post_id = 0;

    if (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v2_get_context_post_id();
    }

    if (
        ! $post_id &&
        $object instanceof WP_Post &&
        'elementor_library'
        !==
        get_post_type( $object->ID )
    ) {
        $post_id =
            (int) $object->ID;
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * RAW RELATIONSHIP NORMALISEREN
 * ============================================================
 *
 * Pods kan relationshipdata als array of object teruggeven.
 * Deze functie maakt daar steeds dit formaat van:
 *
 * [
 *     [
 *         'taxonomy' => 'functie-inhoud',
 *         'term_id'  => 220,
 *     ],
 * ]
 *
 * De taxonomy wordt dus NIET afgeleid uit de fieldnaam.
 * De daadwerkelijke RAW relationshipdata bepaalt welke taxonomy
 * en term gebruikt worden.
 */

function tfsc_relposts_v3_normalize_relationship(
    $value
) {

    if ( empty( $value ) ) {
        return [];
    }

    /*
     * Eén relationship normaliseren naar een lijst.
     */
    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['taxonomy'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    if ( ! is_array( $value ) ) {
        return [];
    }

    $result = [];

    foreach ( $value as $relation ) {

        if ( is_array( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

        } elseif ( is_object( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

        } else {

            continue;
        }

        /*
         * Alleen echte, bestaande taxonomy-terms accepteren.
         */
        if (
            ! $taxonomy ||
            ! $term_id ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            $result[] = [
                'taxonomy' => $taxonomy,
                'term_id'  => $term_id,
            ];
        }
    }

    return $result;
}


/**
 * ============================================================
 * TAXONOMY HOORT BIJ ELEMENTOR SOURCE?
 * ============================================================
 *
 * Een relationship wordt alleen gebruikt als de betreffende
 * taxonomy gekoppeld is aan het post type dat Elementor als
 * Source gebruikt.
 *
 * Voorbeeld:
 *
 * Elementor Source = vacature
 * relationship → functie-inhoud
 *
 * Dan wordt die relationship alleen gebruikt wanneer
 * functie-inhoud daadwerkelijk aan vacature gekoppeld is.
 */

function tfsc_relposts_v3_taxonomy_matches_source(
    $taxonomy,
    $post_types
) {

    $object =
        get_taxonomy(
            $taxonomy
        );

    if ( ! $object ) {
        return false;
    }

    return (bool) array_intersect(
        (array) $post_types,
        (array) $object->object_type
    );
}


/**
 * ============================================================
 * ELEMENTOR QUERY
 * ============================================================
 *
 * Query ID in Elementor:
 *
 * relationship_posts
 *
 * Werking:
 *
 * relationship_functienaam
 * → Field Service Engineer
 *
 * relationship_functie-inhoud
 * → Service
 * → Inbedrijfstellen
 *
 * wordt:
 *
 * functienaam = Field Service Engineer
 *
 * AND
 *
 * functie-inhoud IN (Service, Inbedrijfstellen)
 *
 * Bestaande Elementor tax_query blijft behouden en wordt met
 * deze relationship-query gecombineerd via AND.
 */

add_action(
    'elementor/query/relationship_posts',
    function( $query ) {

        $pod =
            tfsc_relposts_v3_get_pod();

        if ( ! $pod ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Elementor Source.
         */
        $post_types =
            array_values(
                array_filter(
                    (array) $query->get( 'post_type' )
                )
            );

        if ( ! $post_types ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        $fields =
            $pod->fields();

        if ( ! is_array( $fields ) || ! $fields ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Relationship terms groeperen per taxonomy.
         *
         * Bijvoorbeeld:
         *
         * [
         *     'functienaam'    => [100],
         *     'functie-inhoud' => [220, 221],
         * ]
         */
        $groups = [];

        foreach ( $fields as $field_name => $definition ) {

            /*
             * Alleen relationship_* fields.
             *
             * relationship_vacature_button_url wordt uitgesloten,
             * omdat dat field alleen de vacaturebutton bepaalt.
             */
            if (
                ! is_string( $field_name ) ||
                0 !== strpos(
                    $field_name,
                    'relationship_'
                ) ||
                'relationship_vacature_button_url'
                ===
                $field_name
            ) {
                continue;
            }

            /*
             * RAW Pods relationship uitlezen.
             *
             * Bewust geen traversal zoals:
             * $pod->field( $field_name . '.term_id' )
             */
            $relationships =
                tfsc_relposts_v3_normalize_relationship(
                    $pod->field(
                        $field_name
                    )
                );

            foreach (
                $relationships
                as $relationship
            ) {

                $taxonomy =
                    $relationship['taxonomy'];

                /*
                 * Alleen gebruiken als taxonomy bij de
                 * Elementor Source hoort.
                 */
                if (
                    ! tfsc_relposts_v3_taxonomy_matches_source(
                        $taxonomy,
                        $post_types
                    )
                ) {
                    continue;
                }

                $groups[ $taxonomy ][] =
                    (int) $relationship['term_id'];
            }
        }

        /*
         * Dubbele en ongeldige IDs verwijderen.
         */
        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $ids
                            )
                        )
                    )
                );

            if ( $ids ) {
                $groups[ $taxonomy ] = $ids;
            } else {
                unset( $groups[ $taxonomy ] );
            }
        }

        /*
         * Geen bruikbare relationships:
         * bewust geen posts tonen.
         */
        if ( ! $groups ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Verschillende taxonomies = AND.
         * Meerdere terms binnen taxonomy = IN.
         */
        $relationship_query = [
            'relation' => 'AND',
        ];

        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $relationship_query[] = [
                'taxonomy'         => $taxonomy,
                'field'            => 'term_id',
                'terms'            => $ids,
                'operator'         => 'IN',
                'include_children' => true,
            ];
        }

        /*
         * Bestaande Elementor tax_query bewaren.
         */
        $query->set(
    'tax_query',
    $relationship_query
);
    },
    20,
    1
);

/**
 * TFSC - Dynamische tekst shortcodes
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Deze snippet bevat drie generieke tekst-shortcodes:
 *
 * [post_title]
 * [archive_title]
 * [tfsc_pods field="..."]
 *
 * Alle output is platte tekst.
 *
 *
 * ============================================================
 * CASE
 * ============================================================
 *
 * Alle drie de shortcodes ondersteunen:
 *
 * case="normal"
 * → originele schrijfwijze behouden
 *
 * case="lower"
 * → alles lowercase
 *
 * case="sentence"
 * → alles lowercase, alleen eerste letter hoofdletter
 *
 *
 * Voorbeelden:
 *
 * [post_title case="sentence"]
 *
 * [archive_title case="lower"]
 *
 * [tfsc_pods
 *     field="relationship_functienaam"
 *     case="sentence"]
 *
 *
 * Zonder case-attribuut verandert er niets:
 *
 * [post_title]
 *
 * [archive_title]
 *
 * [tfsc_pods field="relationship_functienaam"]
 *
 * gebruikt automatisch:
 *
 * case="normal"
 *
 *
 * ============================================================
 * BELANGRIJK
 * ============================================================
 *
 * Alleen de dynamische waarde wordt door case aangepast.
 *
 * before="" en after="" blijven exact zoals ingevoerd.
 *
 * Voorbeeld:
 *
 * [tfsc_pods
 *     field="relationship_functienaam"
 *     before="Lees meer over "
 *     case="lower"]
 *
 * Resultaat:
 *
 * Lees meer over field service engineer
 *
 *
 * ============================================================
 * [post_title]
 * ============================================================
 *
 * Titel van huidige post / CPT.
 *
 * Werkt ook in Elementor Theme Builder previews wanneer
 * tfsc_derived_rel_v2_get_context_post_id() beschikbaar is.
 *
 * Voorbeelden:
 *
 * [post_title]
 *
 * [post_title
 *     before="Bekijk "
 *     after=" vacatures"]
 *
 * [post_title case="sentence"]
 *
 *
 * ============================================================
 * [archive_title]
 * ============================================================
 *
 * Titel van huidige taxonomy-term.
 *
 * Modes:
 *
 * current
 * → huidige term
 *
 * parents
 * → alleen parent terms
 *
 * full
 * → parents + huidige term
 *
 * label_current
 * → taxonomy label + huidige term
 *
 * label_full
 * → taxonomy label + volledige termstructuur
 *
 * Voorbeelden:
 *
 * [archive_title]
 *
 * [archive_title mode="full"]
 *
 * [archive_title
 *     mode="full"
 *     separator=" › "
 *     case="sentence"]
 *
 *
 * ============================================================
 * [tfsc_pods]
 * ============================================================
 *
 * Generieke shortcode voor Pods custom fields.
 *
 * Werkt op:
 *
 * - huidige post / CPT
 * - Elementor Theme Builder preview
 * - huidige taxonomy-term
 *
 * Voorbeelden:
 *
 * [tfsc_pods field="ondertitel"]
 *
 * [tfsc_pods field="relationship_functienaam"]
 *
 * [tfsc_pods
 *     field="relationship_functienaam"
 *     separator=" • "]
 *
 * [tfsc_pods
 *     field="relationship_functienaam"
 *     case="lower"]
 *
 * [tfsc_pods
 *     field="relationship_functienaam"
 *     case="sentence"]
 */


/**
 * ============================================================
 * CONTEXT HELPERS
 * ============================================================
 */

function tfsc_text_context_post_id() {

    if (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v2_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }

    $object =
        get_queried_object();

    if ( $object instanceof WP_Post ) {
        return (int) $object->ID;
    }

    return (int) get_the_ID();
}


function tfsc_text_context_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object =
        get_queried_object();

    /**
     * Taxonomy term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /**
     * Post / CPT / Elementor preview.
     */
    $post_id =
        tfsc_text_context_post_id();

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * TEXT CASE HELPER
 * ============================================================
 *
 * normal
 * → originele schrijfwijze
 *
 * lower
 * → alles lowercase
 *
 * sentence
 * → alles lowercase, eerste letter hoofdletter
 */

function tfsc_text_case(
    $text,
    $case = 'normal'
) {

    $text =
        (string) $text;

    if ( '' === $text ) {
        return '';
    }

    switch (
        sanitize_key(
            $case
        )
    ) {

        case 'lower':

            return mb_strtolower(
                $text,
                'UTF-8'
            );


        case 'sentence':

            $text =
                mb_strtolower(
                    $text,
                    'UTF-8'
                );

            return
                mb_strtoupper(
                    mb_substr(
                        $text,
                        0,
                        1,
                        'UTF-8'
                    ),
                    'UTF-8'
                )
                .
                mb_substr(
                    $text,
                    1,
                    null,
                    'UTF-8'
                );


        case 'normal':
        default:

            return $text;
    }
}


/**
 * ============================================================
 * [post_title]
 * ============================================================
 */

add_shortcode(
    'post_title',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'before' => '',
                'after'  => '',
                'case'   => 'normal',
            ],
            $atts,
            'post_title'
        );

        $post_id =
            tfsc_text_context_post_id();

        if ( ! $post_id ) {
            return '';
        }

        $title =
            wp_strip_all_tags(
                get_the_title(
                    $post_id
                )
            );

        if ( '' === $title ) {
            return '';
        }

        $title =
            tfsc_text_case(
                $title,
                $atts['case']
            );

        return
            (string) $atts['before']
            . $title
            . (string) $atts['after'];
    }
);


/**
 * ============================================================
 * [archive_title]
 * ============================================================
 */

add_shortcode(
    'archive_title',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'mode'            => 'current',
                'separator'       => ' › ',
                'label_separator' => ': ',
                'before'          => '',
                'after'           => '',
                'case'            => 'normal',
            ],
            $atts,
            'archive_title'
        );

        $term =
            get_queried_object();

        if (
            ! $term instanceof WP_Term ||
            ! taxonomy_exists(
                $term->taxonomy
            )
        ) {
            return '';
        }

        $taxonomy =
            $term->taxonomy;

        $current =
            wp_strip_all_tags(
                $term->name
            );

        $parents = [];

        if (
            is_taxonomy_hierarchical(
                $taxonomy
            )
        ) {

            foreach (
                array_reverse(
                    get_ancestors(
                        $term->term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                )
                as $ancestor_id
            ) {

                $ancestor =
                    get_term(
                        $ancestor_id,
                        $taxonomy
                    );

                if (
                    $ancestor instanceof WP_Term &&
                    ! is_wp_error( $ancestor )
                ) {
                    $parents[] =
                        wp_strip_all_tags(
                            $ancestor->name
                        );
                }
            }
        }

        $taxonomy_object =
            get_taxonomy(
                $taxonomy
            );

        $label =
            $taxonomy_object
            && ! empty(
                $taxonomy_object
                    ->labels
                    ->singular_name
            )
                ? wp_strip_all_tags(
                    $taxonomy_object
                        ->labels
                        ->singular_name
                )
                : '';

        $full =
            implode(
                (string) $atts['separator'],
                array_merge(
                    $parents,
                    [ $current ]
                )
            );

        switch (
            sanitize_key(
                $atts['mode']
            )
        ) {

            case 'parents':

                $output =
                    implode(
                        (string) $atts['separator'],
                        $parents
                    );

                break;

            case 'full':

                $output =
                    $full;

                break;

            case 'label_current':

                $output =
                    $label
                        ? $label
                            . (string) $atts['label_separator']
                            . $current
                        : $current;

                break;

            case 'label_full':

                $output =
                    $label
                        ? $label
                            . (string) $atts['label_separator']
                            . $full
                        : $full;

                break;

            default:

                $output =
                    $current;
        }

        if ( '' === $output ) {
            return '';
        }

        $output =
            tfsc_text_case(
                $output,
                $atts['case']
            );

        return
            (string) $atts['before']
            . $output
            . (string) $atts['after'];
    }
);


/**
 * ============================================================
 * [tfsc_pods]
 * ============================================================
 */

add_shortcode(
    'tfsc_pods',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'field'     => '',
                'before'    => '',
                'after'     => '',
                'separator' => ', ',
                'case'      => 'normal',
            ],
            $atts,
            'tfsc_pods'
        );

        $field =
            sanitize_key(
                $atts['field']
            );

        if ( ! $field ) {
            return '';
        }

        $pod =
            tfsc_text_context_pod();

        if ( ! $pod ) {
            return '';
        }

        $value =
            $pod->field(
                $field
            );

        if (
            null === $value ||
            false === $value ||
            '' === $value
        ) {
            return '';
        }

        /**
         * Normaal tekstveld.
         */
        if (
            ! is_array( $value ) &&
            ! is_object( $value )
        ) {

            $output =
                wp_strip_all_tags(
                    (string) $value
                );

        } else {

            /**
             * Eén relationship normaliseren.
             */
            if (
                is_object( $value ) ||
                (
                    is_array( $value ) &&
                    (
                        isset( $value['name'] ) ||
                        isset( $value['post_title'] ) ||
                        isset( $value['title'] )
                    )
                )
            ) {
                $value = [ $value ];
            }

            $names = [];

            foreach (
                (array) $value
                as $relation
            ) {

                if ( is_array( $relation ) ) {

                    $name =
                        $relation['name']
                        ?? $relation['post_title']
                        ?? $relation['title']
                        ?? '';

                } elseif ( is_object( $relation ) ) {

                    $name =
                        $relation->name
                        ?? $relation->post_title
                        ?? $relation->title
                        ?? '';

                } else {

                    $name = '';
                }

                $name =
                    wp_strip_all_tags(
                        (string) $name
                    );

                if ( '' !== $name ) {
                    $names[] = $name;
                }
            }

            $output =
                implode(
                    (string) $atts['separator'],
                    array_values(
                        array_unique(
                            $names
                        )
                    )
                );
        }

        if ( '' === $output ) {
            return '';
        }

        $output =
            tfsc_text_case(
                $output,
                $atts['case']
            );

        return
            (string) $atts['before']
            . $output
            . (string) $atts['after'];
    }
);

/**
 * TFSC - Taxonomy Base Archives + Elementor Theme Builder Conditions
 *
 * ============================================================
 * MANUAL
 * ============================================================
 *
 * Deze snippet voegt een extra archive-niveau toe voor
 * geselecteerde taxonomies.
 *
 * WordPress kent standaard bijvoorbeeld:
 *
 * /beroepengids/functie-inhoud/inbedrijfstellen/
 *
 * maar niet automatisch:
 *
 * /beroepengids/functie-inhoud/
 *
 * Deze snippet maakt dat taxonomy-base archive mogelijk.
 *
 *
 * ============================================================
 * ALLOWLIST
 * ============================================================
 *
 * Alleen taxonomies die hieronder staan krijgen een
 * TFSC taxonomy-base archive.
 *
 * Gebruik de INTERNE taxonomy name, dus niet het label
 * en niet de rewrite slug.
 *
 * Voorbeeld:
 *
 * 'beroep_functienaam'
 *
 * Taxonomy toevoegen:
 * → naam toevoegen aan de array
 *
 * Taxonomy uitschakelen:
 * → naam uit de array verwijderen
 *
 * Na een wijziging in deze lijst of in rewrite slugs:
 *
 * WordPress
 * → Instellingen
 * → Permalinks
 * → Wijzigingen opslaan
 *
 *
 * ============================================================
 * URL
 * ============================================================
 *
 * De URL wordt automatisch bepaald door de rewrite slug
 * van de taxonomy.
 *
 * Bijvoorbeeld:
 *
 * interne taxonomy:
 * beroep_functie_inhoud
 *
 * rewrite slug:
 * beroepengids/functie-inhoud
 *
 * archive:
 * /beroepengids/functie-inhoud/
 *
 *
 * ============================================================
 * QUERY VAR
 * ============================================================
 *
 * Op een TFSC taxonomy-base archive bevat:
 *
 * get_query_var( 'tfsc_taxonomy_archive' )
 *
 * de interne taxonomy name.
 *
 *
 * ============================================================
 * ELEMENTOR
 * ============================================================
 *
 * Er worden twee Theme Builder conditions geregistreerd:
 *
 * TFSC Beroepengids Taxonomy Base Archives
 *
 * → /beroepengids/functie-inhoud/
 *
 * TFSC Beroepengids Taxonomy Term Archives
 *
 * → /beroepengids/functie-inhoud/inbedrijfstellen/
 *
 * Voor de Beroepengids conditions moet de rewrite slug
 * beginnen met:
 *
 * beroepengids/
 *
 *
 * ============================================================
 * BESTAANDE URLS
 * ============================================================
 *
 * Deze snippet verandert niet:
 *
 * - normale taxonomy term archives
 * - CPT archives
 * - singular posts / CPT's
 * - TFSC combo archives
 *
 * De rewrite matcht uitsluitend exact de taxonomy-basis.
 */


/**
 * ============================================================
 * ALLOWLIST
 * ============================================================
 *
 * Alleen deze taxonomies krijgen een taxonomy-base archive.
 *
 * VERVANG onderstaande voorbeelden door je echte interne
 * taxonomy names.
 */

function tfsc_taxonomy_base_archive_allowed(
    $taxonomy_name
) {

    $allowed = [
		'beroep_bedrijfssector',
        'beroep_functienaam',
        'beroep_functie-inhoud',
        'beroep_kennisgebied',
        'beroep_locatie',
		'beroep_opleidingsniveau',
		'beroep_studierichting',
		'beroep_werkgebied',
    ];

    return in_array(
        $taxonomy_name,
        $allowed,
        true
    );
}


/**
 * ============================================================
 * QUERY VAR
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_taxonomy_archive';

        return $vars;
    }
);


/**
 * ============================================================
 * TAXONOMY BASE REWRITE RULES
 * ============================================================
 *
 * De rewrite slug van WordPress / Pods blijft leidend.
 */

add_action(
    'init',
    function() {

        $taxonomies =
            get_taxonomies(
                [
                    'public' => true,
                ],
                'objects'
            );

        foreach (
            $taxonomies
            as $taxonomy
        ) {

            /**
             * Alleen taxonomies uit de allowlist.
             */
            if (
                ! tfsc_taxonomy_base_archive_allowed(
                    $taxonomy->name
                )
            ) {
                continue;
            }

            $slug =
                trim(
                    (string) (
                        $taxonomy->rewrite['slug']
                        ?? ''
                    ),
                    '/'
                );

            if ( '' === $slug ) {
                continue;
            }

            /**
             * Match alleen exact de taxonomy-basis.
             *
             * Wel:
             * /beroepengids/functie-inhoud/
             *
             * Niet:
             * /beroepengids/functie-inhoud/inbedrijfstellen/
             */
            add_rewrite_rule(
                '^'
                . preg_quote(
                    $slug,
                    '#'
                )
                . '/?$',
                'index.php?tfsc_taxonomy_archive='
                . urlencode(
                    $taxonomy->name
                ),
                'top'
            );
        }
    },
    99
);


/**
 * ============================================================
 * HELPERS
 * ============================================================
 */

/**
 * Geeft het taxonomy-object van het huidige
 * TFSC taxonomy-base archive terug.
 */

function tfsc_get_current_taxonomy_archive() {

    $name =
        get_query_var(
            'tfsc_taxonomy_archive'
        );

    if (
        ! $name ||
        ! tfsc_taxonomy_base_archive_allowed(
            $name
        )
    ) {
        return false;
    }

    $taxonomy =
        get_taxonomy(
            $name
        );

    return (
        $taxonomy &&
        ! empty( $taxonomy->public )
    )
        ? $taxonomy
        : false;
}


/**
 * Controleert of de huidige pagina een geldig
 * TFSC taxonomy-base archive is.
 */

function tfsc_is_taxonomy_base_archive() {

    return (bool)
        tfsc_get_current_taxonomy_archive();
}


/**
 * Controleert of een taxonomy bij Beroepengids hoort.
 *
 * Voor Elementor Theme Builder conditions gebruiken we
 * hiervoor de rewrite prefix:
 *
 * beroepengids/
 */

function tfsc_is_beroepengids_taxonomy(
    $taxonomy_name
) {

    $taxonomy =
        get_taxonomy(
            $taxonomy_name
        );

    if (
        ! $taxonomy ||
        empty( $taxonomy->public )
    ) {
        return false;
    }

    $slug =
        trim(
            (string) (
                $taxonomy->rewrite['slug']
                ?? ''
            ),
            '/'
        );

    return (
        $slug &&
        0 === strpos(
            $slug,
            'beroepengids/'
        )
    );
}


/**
 * Beroepengids taxonomy-base archive.
 */

function tfsc_is_beroepengids_taxonomy_base_archive() {

    $taxonomy =
        tfsc_get_current_taxonomy_archive();

    return (
        $taxonomy &&
        tfsc_is_beroepengids_taxonomy(
            $taxonomy->name
        )
    );
}


/**
 * Normaal Beroepengids taxonomy term archive.
 */

function tfsc_is_beroepengids_taxonomy_term_archive() {

    $term =
        get_queried_object();

    return (
        $term instanceof WP_Term &&
        tfsc_is_beroepengids_taxonomy(
            $term->taxonomy
        )
    );
}


/**
 * ============================================================
 * ARCHIVE QUERY STATUS
 * ============================================================
 *
 * Een taxonomy-base URL heeft geen echte WordPress post/page.
 * Daarom markeren we hem handmatig als archive.
 */

add_action(
    'parse_query',
    function( $query ) {

        $name =
            $query->get(
                'tfsc_taxonomy_archive'
            );

        if (
            ! $name ||
            ! tfsc_taxonomy_base_archive_allowed(
                $name
            )
        ) {
            return;
        }

        $taxonomy =
            get_taxonomy(
                $name
            );

        if (
            ! $taxonomy ||
            empty( $taxonomy->public )
        ) {
            return;
        }

        $query->is_home       = false;
        $query->is_front_page = false;
        $query->is_singular   = false;
        $query->is_page       = false;
        $query->is_single     = false;
        $query->is_search     = false;
        $query->is_404        = false;
        $query->is_archive    = true;
    },
    20
);


/**
 * ============================================================
 * 404 VOORKOMEN
 * ============================================================
 */

add_filter(
    'pre_handle_404',
    function(
        $preempt,
        $wp_query
    ) {

        $name =
            $wp_query->get(
                'tfsc_taxonomy_archive'
            );

        if (
            ! $name ||
            ! tfsc_taxonomy_base_archive_allowed(
                $name
            )
        ) {
            return $preempt;
        }

        $taxonomy =
            get_taxonomy(
                $name
            );

        if (
            ! $taxonomy ||
            empty( $taxonomy->public )
        ) {
            return $preempt;
        }

        $wp_query->is_404     = false;
        $wp_query->is_archive = true;

        status_header( 200 );

        return true;
    },
    10,
    2
);


/**
 * ============================================================
 * GEEN NORMALE POSTS OPHALEN
 * ============================================================
 *
 * Het taxonomy-base archive is bedoeld om taxonomy terms
 * te tonen. Elementor / TFSC term loops halen die zelf op.
 */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin() ||
            ! $query->is_main_query()
        ) {
            return;
        }

        $name =
            $query->get(
                'tfsc_taxonomy_archive'
            );

        if (
            ! $name ||
            ! tfsc_taxonomy_base_archive_allowed(
                $name
            )
        ) {
            return;
        }

        $query->set(
            'post__in',
            [ 0 ]
        );
    },
    20
);


/**
 * ============================================================
 * ARCHIVE TITLE
 * ============================================================
 *
 * Gebruikt het plural taxonomy label.
 */

function tfsc_taxonomy_base_archive_title(
    $title
) {

    $taxonomy =
        tfsc_get_current_taxonomy_archive();

    return (
        $taxonomy &&
        ! empty(
            $taxonomy->labels->name
        )
    )
        ? $taxonomy->labels->name
        : $title;
}


add_filter(
    'get_the_archive_title',
    'tfsc_taxonomy_base_archive_title'
);

add_filter(
    'elementor/utils/get_the_archive_title',
    'tfsc_taxonomy_base_archive_title'
);


/**
 * ============================================================
 * BODY CLASSES
 * ============================================================
 *
 * Voorbeeld:
 *
 * tfsc-taxonomy-base-archive
 *
 * tfsc-taxonomy-base-archive--beroep_functienaam
 */

add_filter(
    'body_class',
    function( $classes ) {

        $taxonomy =
            tfsc_get_current_taxonomy_archive();

        if ( ! $taxonomy ) {
            return $classes;
        }

        $classes[] =
            'tfsc-taxonomy-base-archive';

        $classes[] =
            'tfsc-taxonomy-base-archive--'
            . sanitize_html_class(
                $taxonomy->name
            );

        return $classes;
    }
);


/**
 * ============================================================
 * ELEMENTOR THEME BUILDER CONDITIONS
 * ============================================================
 *
 * Registreert:
 *
 * 1. TFSC Beroepengids Taxonomy Base Archives
 * 2. TFSC Beroepengids Taxonomy Term Archives
 */

add_action(
    'elementor/theme/register_conditions',
    function( $conditions_manager ) {

        if (
            ! class_exists(
                '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base'
            )
        ) {
            return;
        }


        /**
         * Taxonomy Base Archives.
         */
        if (
            ! class_exists(
                'TFSC_Beroepengids_Taxonomy_Base_Condition'
            )
        ) {

            class TFSC_Beroepengids_Taxonomy_Base_Condition
                extends
                \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type(): string {
                    return 'archive';
                }

                public static function get_priority(): int {
                    return 90;
                }

                public function get_name(): string {
