/**
 * TFSC - Generic Current Taxonomy Term Fields
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Generieke laag voor custom fields op taxonomy terms.
 *
 * Werkt onafhankelijk van de taxonomy:
 *
 * beroep_functienaam
 * beroep_kennisgebied
 * beroep_opleiding
 * beroep_werkgebied
 * enz.
 *
 * Zolang dezelfde veldnaam op de betreffende taxonomy bestaat,
 * kan hetzelfde Elementor-template / shortcode gebruikt worden.
 *
 *
 * ============================================================
 * SHORTCODE
 * ============================================================
 *
 * Tekstveld:
 *
 * [tfsc_term_field field="intro_taxonomy"]
 *
 * Image/file URL:
 *
 * [tfsc_term_field field="archive_featured_image" output="url"]
 *
 *
 * ============================================================
 * ELEMENTOR DYNAMIC TAGS
 * ============================================================
 *
 * 1. TFSC Current Term Field
 *
 * Voor tekstvelden, headings, descriptions enz.
 *
 * Voorbeeld:
 *
 * Heading
 * → Dynamic
 * → TFSC Current Term Field
 * → Term field: archive_intro
 *
 *
 * 2. TFSC Current Term Image
 *
 * Voor image widgets en backgrounds.
 *
 * Voorbeeld:
 *
 * Container
 * → Background
 * → Image
 * → Dynamic
 * → TFSC Current Term Image
 * → Term field: archive_featured_image
 *
 *
 * ============================================================
 * BELANGRIJK
 * ============================================================
 *
 * Je selecteert alleen de veldnaam.
 *
 * Je selecteert GEEN taxonomy en GEEN specifieke term.
 *
 * De huidige taxonomy-term wordt automatisch uit de context
 * gehaald.
 */


/**
 * ============================================================
 * 1. CURRENT TERM
 * ============================================================
 */
function tfsc_current_term() {

    $object = get_queried_object();

    return $object instanceof WP_Term
        ? $object
        : null;
}


/**
 * ============================================================
 * 2. CURRENT TERM FIELD
 * ============================================================
 *
 * Leest een Pods field van de huidige taxonomy-term.
 *
 * Fallback naar normale WordPress term-meta.
 */
function tfsc_current_term_field( $field ) {

    $term = tfsc_current_term();

    if ( ! $term || ! $field ) {
        return null;
    }

    $field = sanitize_key( $field );

    if ( function_exists( 'pods' ) ) {

        $pod = pods(
            $term->taxonomy,
            $term->term_id
        );

        if ( $pod && $pod->exists() ) {
            return $pod->field( $field );
        }
    }

    return get_term_meta(
        $term->term_id,
        $field,
        true
    );
}


/**
 * ============================================================
 * 3. IMAGE ATTACHMENT ID
 * ============================================================
 *
 * Zet verschillende mogelijke Pods image/file return values
 * om naar één WordPress attachment ID.
 */
function tfsc_current_term_image_id( $field ) {

    $value = tfsc_current_term_field( $field );

    if ( empty( $value ) ) {
        return 0;
    }

    if ( is_numeric( $value ) ) {
        return (int) $value;
    }

    if ( is_array( $value ) ) {

        return (int) (
            $value['ID']
            ?? $value['id']
            ?? $value['pod_item_id']
            ?? 0
        );
    }

    if ( is_object( $value ) ) {

        return (int) (
            $value->ID
            ?? $value->id
            ?? $value->pod_item_id
            ?? 0
        );
    }

    return 0;
}


/**
 * ============================================================
 * 4. SHORTCODE
 * ============================================================
 *
 * Tekst:
 *
 * [tfsc_term_field field="archive_intro"]
 *
 * Image URL:
 *
 * [tfsc_term_field
 *     field="archive_featured_image"
 *     output="url"
 * ]
 */
add_shortcode(
    'tfsc_term_field',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'field'  => '',
                'output' => 'text',
                'size'   => 'full',
            ],
            $atts,
            'tfsc_term_field'
        );

        $field = sanitize_key( $atts['field'] );

        if ( ! $field ) {
            return '';
        }

        if ( $atts['output'] === 'url' ) {

            $id = tfsc_current_term_image_id( $field );

            if ( ! $id ) {
                return '';
            }

            $url = wp_get_attachment_image_url(
                $id,
                sanitize_key( $atts['size'] )
            );

            return $url
                ? esc_url( $url )
                : '';
        }

        $value = tfsc_current_term_field( $field );

        if (
            is_array( $value ) ||
            is_object( $value )
        ) {
            return '';
        }

        return wp_kses_post(
            (string) $value
        );
    }
);


