                ?? $first['pod_item_id']
                ?? 0
            );
        }

        if ( is_object( $first ) ) {
            return (int) (
                $first->ID
                ?? $first->id
                ?? $first->pod_item_id
                ?? 0
            );
        }
    }

    if ( is_object( $value ) ) {

        return (int) (
            $value->ID
            ?? $value->id
            ?? $value->pod_item_id
            ?? 0
        );
    }

    return 0;
}


/**
 * ============================================================
 * 4. GENERIEKE SHORTCODE
 * ============================================================
 *
 * Tekst:
 *
 * [tfsc_term_field field="intro_taxonomy"]
 *
 * Afbeelding URL:
 *
 * [tfsc_term_field
 *     field="archive_featured_image"
 *     output="url"
 * ]
 */
add_shortcode(
    'tfsc_term_field',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'field'  => '',
                'output' => 'text',
                'size'   => 'full',
            ],
            $atts,
            'tfsc_term_field'
        );

        $field = sanitize_key( $atts['field'] );

        if ( ! $field ) {
            return '';
        }

        if ( $atts['output'] === 'url' ) {

            $id = tfsc_current_term_image_id( $field );

            if ( ! $id ) {
                return '';
            }

            $url = wp_get_attachment_image_url(
                $id,
                sanitize_key( $atts['size'] )
            );

            return $url
                ? esc_url( $url )
                : '';
        }

        $value = tfsc_current_term_field( $field );

        if (
            is_array( $value )
            || is_object( $value )
        ) {
            return '';
        }

        return wp_kses_post(
            (string) $value
        );
    }
);


