/**
 * TFSC - Relationship Debug
 *
 * Tijdelijke debug-shortcode:
 *
 * [tfsc_relationship_debug]
 *
 * Toont:
 * - huidige WordPress context
 * - gebruikte CPT / taxonomy / ID
 * - Pods object
 * - alle velden die beginnen met relationship_
 * - gewone Pods field() waarde
 * - RAW Pods waarde
 * - Pods field-definitie
 *
 * Gebruik:
 *
 * 1. Zet shortcode op de betreffende CPT-template.
 * 2. Maak screenshot / kopieer output.
 * 3. Verander daarna de relationship selecties.
 * 4. Herlaad en stuur de tweede output.
 *
 * Daarna kunnen we exact zien hoe Pods de selectie aanlevert.
 */

add_shortcode(
    'tfsc_relationship_debug',
    function() {

        if ( ! current_user_can( 'manage_options' ) ) {
            return '';
        }

        if ( ! function_exists( 'pods' ) ) {
            return '<pre>Pods niet beschikbaar.</pre>';
        }

        $object  = get_queried_object();
        $post_id = 0;
        $pod     = false;
        $context = [];


        /**
         * ----------------------------------------------------
         * WORDPRESS CONTEXT
         * ----------------------------------------------------
         */
        if ( $object instanceof WP_Term ) {

            $context = [
                'type'      => 'taxonomy-term',
                'taxonomy'  => $object->taxonomy,
                'term_id'   => $object->term_id,
                'term_name' => $object->name,
            ];

            $pod = pods(
                $object->taxonomy,
                $object->term_id
            );

        } else {

            if (
                function_exists(
                    'tfsc_derived_rel_v2_get_context_post_id'
                )
            ) {
                $post_id = (int)
                    tfsc_derived_rel_v2_get_context_post_id();
            }

            if (
                ! $post_id &&
                $object instanceof WP_Post &&
                $object->post_type !== 'elementor_library'
            ) {
                $post_id = (int) $object->ID;
            }

            if ( ! $post_id ) {
                $post_id = (int) get_queried_object_id();
            }

            $post_type = $post_id
                ? get_post_type( $post_id )
                : '';

            $context = [
                'type'          => 'post/cpt',
                'post_id'       => $post_id,
                'post_type'     => $post_type,
                'queried_class' => is_object( $object )
                    ? get_class( $object )
                    : gettype( $object ),
            ];

            if ( $post_id && $post_type ) {
                $pod = pods(
                    $post_type,
                    $post_id
                );
            }
        }


        $debug = [
            'context' => $context,
            'pod'     => [
                'exists' => (
                    $pod &&
                    method_exists( $pod, 'exists' ) &&
                    $pod->exists()
                ),
            ],
            'relationships' => [],
        ];


        if (
            ! $pod ||
            ! method_exists( $pod, 'exists' ) ||
            ! $pod->exists()
        ) {
            return '<pre>' .
                esc_html(
                    print_r( $debug, true )
                ) .
                '</pre>';
        }


        /**
         * ----------------------------------------------------
         * ALLE relationship_ VELDEN
         * ----------------------------------------------------
         */
        $fields = $pod->fields();

        if ( is_array( $fields ) ) {

            foreach ( $fields as $key => $field ) {

                $field_name = is_string( $key )
                    ? $key
                    : (
                        is_array( $field )
                            ? ( $field['name'] ?? '' )
                            : ''
                    );

                if (
                    ! $field_name ||
                    strpos(
                        $field_name,
                        'relationship_'
                    ) !== 0
                ) {
                    continue;
                }


                $normal = $pod->field(
                    $field_name
                );

                $raw = method_exists( $pod, 'raw' )
                    ? $pod->raw( $field_name )
                    : 'raw() niet beschikbaar';


                $definition =
                    $pod->fields(
                        $field_name
                    );


                $debug['relationships'][ $field_name ] = [
                    'field()'    => $normal,
                    'raw()'      => $raw,
                    'definition' => $definition,
                ];
            }
        }


        return '<pre style="
            white-space:pre-wrap;
            overflow:auto;
            padding:20px;
            background:#f5f5f5;
            border:1px solid #ccc;
            font-size:12px;
            line-height:1.5;
        ">' .
            esc_html(
                print_r( $debug, true )
            ) .
            '</pre>';
    }
);

/**
 * TFSC - Vacature Button Decision Debug
 *
 * Tijdelijke shortcode:
 *
 * [tfsc_button_debug]
 *
 * Toont exact:
 *
 * - welk CPT / object gebruikt wordt
 * - welke relationship_ velden worden doorlopen
 * - welke gevuld/leeg zijn
 * - welke taxonomy + term_id gevonden worden
 * - welke relationship uiteindelijk wordt gekozen
 * - welke native URL daaruit komt
 *
 * Alleen zichtbaar voor administrators.
 */

add_shortcode(
    'tfsc_button_debug',
    function() {

        if ( ! current_user_can( 'manage_options' ) ) {
            return '';
        }

        if ( ! function_exists( 'pods' ) ) {
            return '<pre>Pods niet beschikbaar.</pre>';
        }

        $object  = get_queried_object();
        $post_id = 0;
        $pod     = false;

        $debug = [
            'context'  => [],
            'fields'   => [],
            'selected' => null,
            'url'      => '',
        ];


        /**
         * ====================================================
         * 1. CONTEXT
         * ====================================================
         */
        if ( $object instanceof WP_Term ) {

            $debug['context'] = [
                'type'     => 'term',
                'taxonomy' => $object->taxonomy,
                'term_id'  => $object->term_id,
                'name'     => $object->name,
            ];

            $pod = pods(
                $object->taxonomy,
                $object->term_id
            );

        } else {

            if (
                function_exists(
                    'tfsc_derived_rel_v2_get_context_post_id'
                )
            ) {
                $post_id = (int)
                    tfsc_derived_rel_v2_get_context_post_id();
            }

            if (
                ! $post_id &&
                $object instanceof WP_Post &&
                $object->post_type !== 'elementor_library'
            ) {
                $post_id = (int) $object->ID;
            }

            if ( ! $post_id ) {
                $post_id = (int) get_queried_object_id();
            }

            $post_type = $post_id
                ? get_post_type( $post_id )
                : '';

            $debug['context'] = [
                'type'      => 'post/cpt',
                'post_id'   => $post_id,
                'post_type' => $post_type,
            ];

            if ( $post_id && $post_type ) {
                $pod = pods(
                    $post_type,
                    $post_id
                );
            }
        }


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            $debug['error'] = 'Geen geldige Pod gevonden.';

            return '<pre>' .
                esc_html(
                    print_r( $debug, true )
                ) .
                '</pre>';
        }


        /**
         * ====================================================
         * 2. VOLGORDE VAN VELDEN
         * ====================================================
         *
         * relationship_vacature_button_url altijd eerst.
         */
        $field_names = [
            'relationship_vacature_button_url',
        ];

        $fields = $pod->fields();

        if ( is_array( $fields ) ) {

            foreach ( $fields as $key => $field ) {

                $field_name = '';

                if ( is_string( $key ) ) {

                    $field_name = $key;

                } elseif (
                    is_object( $field ) &&
                    isset( $field->args['name'] )
                ) {

                    $field_name =
                        $field->args['name'];

                } elseif (
                    is_array( $field ) &&
                    ! empty( $field['name'] )
                ) {

                    $field_name =
                        $field['name'];
                }

                $field_name =
                    sanitize_key( $field_name );

                if (
                    ! $field_name ||
                    strpos(
                        $field_name,
                        'relationship_'
                    ) !== 0 ||
                    $field_name ===
                        'relationship_vacature_button_url'
                ) {
                    continue;
                }

                $field_names[] = $field_name;
            }
        }


        /**
         * ====================================================
         * 3. IEDER VELD DAADWERKELIJK TESTEN
         * ====================================================
         */
        foreach ( array_unique( $field_names ) as $field_name ) {

            $raw = method_exists( $pod, 'raw' )
                ? $pod->raw( $field_name )
                : $pod->field( $field_name );

            $entry = [
                'filled'   => ! empty( $raw ),
                'term_id'  => 0,
                'taxonomy' => '',
                'name'     => '',
                'valid'    => false,
            ];


            if ( empty( $raw ) ) {

                $debug['fields'][ $field_name ] = $entry;
                continue;
            }


            /**
             * Eén relatie naar lijst normaliseren.
             */
            if (
                is_object( $raw ) ||
                (
                    is_array( $raw ) &&
                    (
                        isset( $raw['term_id'] ) ||
                        isset( $raw['pod_item_id'] ) ||
                        isset( $raw['ID'] ) ||
                        isset( $raw['id'] )
                    )
                )
            ) {
                $raw = [ $raw ];
            }


            foreach ( (array) $raw as $relation ) {

                $term_id  = 0;
                $taxonomy = '';

                if ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['pod_item_id']
                        ?? $relation['ID']
                        ?? $relation['id']
                        ?? 0
                    );

                    $taxonomy =
                        ! empty( $relation['taxonomy'] )
                            ? sanitize_key(
                                $relation['taxonomy']
                            )
                            : '';

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->pod_item_id
                        ?? $relation->ID
                        ?? $relation->id
                        ?? 0
                    );

                    $taxonomy =
                        ! empty( $relation->taxonomy )
                            ? sanitize_key(
                                $relation->taxonomy
                            )
                            : '';
                }


                $entry['term_id']  = $term_id;
                $entry['taxonomy'] = $taxonomy;


                if (
                    ! $term_id ||
                    ! $taxonomy ||
                    ! taxonomy_exists( $taxonomy )
                ) {
                    continue;
                }


                $term = get_term(
                    $term_id,
                    $taxonomy
                );


                if (
                    ! $term instanceof WP_Term ||
                    is_wp_error( $term )
                ) {
                    continue;
                }


                $entry['name']  = $term->name;
                $entry['valid'] = true;

                $debug['fields'][ $field_name ] = $entry;


                /**
                 * Eerste geldige relationship wint.
                 */
                if ( empty( $debug['selected'] ) ) {

                    $GLOBALS[
                        'tfsc_force_native_term_link'
                    ] = true;

                    $url = get_term_link( $term );

                    unset(
                        $GLOBALS[
                            'tfsc_force_native_term_link'
                        ]
                    );


                    $debug['selected'] = [
                        'field'    => $field_name,
                        'term_id'  => $term->term_id,
                        'taxonomy' => $term->taxonomy,
                        'name'     => $term->name,
                    ];

                    $debug['url'] =
                        is_wp_error( $url )
                            ? 'WP_Error: ' .
                                $url->get_error_message()
                            : $url;
                }


                break;
            }


            if (
                ! isset(
                    $debug['fields'][ $field_name ]
                )
            ) {
                $debug['fields'][ $field_name ] = $entry;
            }


            /**
             * Als een geldige relatie gevonden is,
             * hoeft de rest voor de button niet meer.
             */
            if ( ! empty( $debug['selected'] ) ) {
                break;
            }
        }


        return '<pre style="
            white-space:pre-wrap;
            overflow:auto;
            padding:20px;
            background:#f5f5f5;
            border:1px solid #ccc;
            font-size:12px;
            line-height:1.5;
        ">' .
            esc_html(
                print_r( $debug, true )
            ) .
            '</pre>';
    }
);

/**
 * TFSC - Vacature Button URL + Text
 *
 * Shortcodes:
 *
 * [vacature_button_url]
 * [vacature_button_text]
 *
 * ============================================================
 * WERKING
 * ============================================================
 *
 * 1. relationship_vacature_button_url heeft altijd voorrang.
 *
 * 2. Is die leeg?
 *    Dan wordt de eerste andere gevulde relationship_ taxonomy
 *    gebruikt.
 *
 * 3. URL en tekst gebruiken ALTIJD dezelfde gevonden term.
 *
 * Voorbeeld:
 *
 * relationship_vacature_button_url = leeg
 * relationship_functie-inhoud      = Inbedrijfstellen
 *
 * Resultaat:
 *
 * [vacature_button_text]
 * → Inbedrijfstellen
 *
 * [vacature_button_url]
 * → native URL van Inbedrijfstellen
 */


/**
 * ============================================================
 * 1. HUIDIGE POD CONTEXT
 * ============================================================
 */
function tfsc_vacature_button_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    /**
     * Elementor Taxonomy Loop / term-context.
     */
    if ( function_exists( 'tfsc_current_term' ) ) {

        $term = tfsc_current_term();

        if ( $term instanceof WP_Term ) {

            $pod = pods(
                $term->taxonomy,
                $term->term_id
            );

            if ( $pod && $pod->exists() ) {
                return $pod;
            }
        }
    }

    $object = get_queried_object();

    /**
     * Normale taxonomy-term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            $object->term_id
        );

        if ( $pod && $pod->exists() ) {
            return $pod;
        }
    }

    /**
     * CPT / post / Elementor Theme Builder preview.
     */
    $post_id = 0;

    if (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id = (int)
            tfsc_derived_rel_v2_get_context_post_id();
    }

    if (
        ! $post_id &&
        $object instanceof WP_Post &&
        $object->post_type !== 'elementor_library'
    ) {
        $post_id = (int) $object->ID;
    }

    if ( ! $post_id ) {
        $post_id = (int) get_queried_object_id();
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type = get_post_type( $post_id );

    if (
        ! $post_type ||
        $post_type === 'elementor_library'
    ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * 2. RELATIONSHIP FIELD → WP_TERM
 * ============================================================
 */
function tfsc_vacature_button_term_from_field(
    $pod,
    $field_name
) {

    $raw = method_exists( $pod, 'raw' )
        ? $pod->raw( $field_name )
        : $pod->field( $field_name );

    if ( empty( $raw ) ) {
        return false;
    }

    /**
     * Eén relatie normaliseren naar lijst.
     */
    if (
        is_object( $raw ) ||
        (
            is_array( $raw ) &&
            (
                isset( $raw['term_id'] ) ||
                isset( $raw['pod_item_id'] ) ||
                isset( $raw['ID'] ) ||
                isset( $raw['id'] )
            )
        )
    ) {
        $raw = [ $raw ];
    }

    foreach ( (array) $raw as $relation ) {

        $term_id  = 0;
        $taxonomy = '';

        if ( is_array( $relation ) ) {

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['ID']
                ?? $relation['id']
                ?? 0
            );

            $taxonomy = ! empty( $relation['taxonomy'] )
                ? sanitize_key( $relation['taxonomy'] )
                : '';

        } elseif ( is_object( $relation ) ) {

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->ID
                ?? $relation->id
                ?? 0
            );

            $taxonomy = ! empty( $relation->taxonomy )
                ? sanitize_key( $relation->taxonomy )
                : '';
        }

        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term = get_term(
            $term_id,
            $taxonomy
        );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            return $term;
        }
    }

    return false;
}


/**
 * ============================================================
 * 3. BUTTON TERM BEPALEN
 * ============================================================
 */
function tfsc_vacature_button_term() {

    $pod = tfsc_vacature_button_pod();

    if ( ! $pod ) {
        return false;
    }

    /**
     * Eerst expliciete button-selectie.
     */
    $term = tfsc_vacature_button_term_from_field(
        $pod,
        'relationship_vacature_button_url'
    );

    if ( $term ) {
        return $term;
    }

    /**
     * Daarna eerste andere gevulde relationship_.
     */
    $fields = $pod->fields();

    if ( ! is_array( $fields ) ) {
        return false;
    }

    foreach ( $fields as $field_name => $field ) {

        if (
            ! is_string( $field_name ) ||
            strpos(
                $field_name,
                'relationship_'
            ) !== 0 ||
            $field_name ===
                'relationship_vacature_button_url'
        ) {
            continue;
        }

        $term = tfsc_vacature_button_term_from_field(
            $pod,
            $field_name
        );

        if ( $term ) {
            return $term;
        }
    }

    return false;
}


/**
 * ============================================================
 * 4. BUTTON URL
 * ============================================================
 *
 * [vacature_button_url]
 */
add_shortcode(
    'vacature_button_url',
    function() {

        $term = tfsc_vacature_button_term();

        if ( ! $term ) {
            return '';
        }

        $GLOBALS[
            'tfsc_force_native_term_link'
        ] = true;

        $url = get_term_link( $term );

        unset(
            $GLOBALS[
                'tfsc_force_native_term_link'
            ]
        );

        return is_wp_error( $url )
            ? ''
            : esc_url( $url );
    }
);


