/**
 * ============================================================
 * HUIDIGE POD CONTEXT
 * ============================================================
 *
 * Prioriteit:
 *
 * 1. CPT / post
 * 2. Normale taxonomy-term
 * 3. Elementor Taxonomy Loop
 *
 * Dit voorkomt dat een Elementor loop_term de context van
 * een normale CPT-pagina overschrijft.
 */
function tfsc_vacature_button_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();


    /**
     * ========================================================
     * 1. CPT / POST HEEFT VOORRANG
     * ========================================================
     */
    if (
        $object instanceof WP_Post &&
        $object->post_type !== 'elementor_library'
    ) {

        $post_id = (int) $object->ID;

        /**
         * Elementor Theme Builder preview eventueel gebruiken.
         */
        if (
            function_exists(
                'tfsc_derived_rel_v2_get_context_post_id'
            )
        ) {

            $context_id = (int)
                tfsc_derived_rel_v2_get_context_post_id();

            if ( $context_id ) {
                $post_id = $context_id;
            }
        }

        $post_type = get_post_type( $post_id );

        if ( ! $post_type ) {
            return false;
        }

        $pod = pods(
            $post_type,
            $post_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }


    /**
     * ========================================================
     * 2. NORMALE TAXONOMY TERM
     * ========================================================
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }


    /**
     * ========================================================
     * 3. ELEMENTOR TAXONOMY LOOP
     * ========================================================
     */
    if ( function_exists( 'tfsc_current_term' ) ) {

        $term = tfsc_current_term();

        if ( $term instanceof WP_Term ) {

            $pod = pods(
                $term->taxonomy,
                $term->term_id
            );

            return (
                $pod &&
                $pod->exists()
            )
                ? $pod
                : false;
        }
    }


    /**
     * Laatste post fallback.
     */
    $post_id = (int) get_queried_object_id();

    if ( ! $post_id ) {
        return false;
    }

    $post_type = get_post_type( $post_id );

    if (
        ! $post_type ||
        $post_type === 'elementor_library'
    ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}

/**
 * TFSC - Vacature Button URL 2
 *
 * Tijdelijke test-shortcode:
 *
 * [vacature_button_url_2]
 *
 * Gebruikt dezelfde werkende selectie-logica als de debug:
 *
 * 1. relationship_vacature_button_url
 * 2. indien leeg: eerste andere gevulde relationship_
 * 3. native taxonomy-term URL
 */

add_shortcode(
    'vacature_button_url_2',
    function() {

        if ( ! function_exists( 'pods' ) ) {
            return '';
        }

        $object  = get_queried_object();
        $post_id = 0;
        $pod     = false;


        /**
         * Taxonomy-term.
         */
        if ( $object instanceof WP_Term ) {

            $pod = pods(
                $object->taxonomy,
                $object->term_id
            );

        } else {

            /**
             * CPT / post / Elementor preview.
             */
            if (
                function_exists(
                    'tfsc_derived_rel_v2_get_context_post_id'
                )
            ) {
                $post_id = (int)
                    tfsc_derived_rel_v2_get_context_post_id();
            }

            if (
                ! $post_id &&
                $object instanceof WP_Post &&
                $object->post_type !== 'elementor_library'
            ) {
                $post_id = (int) $object->ID;
            }

            if ( ! $post_id ) {
                $post_id = (int) get_queried_object_id();
            }

            if ( $post_id ) {

                $post_type = get_post_type( $post_id );

                if ( $post_type ) {
                    $pod = pods(
                        $post_type,
                        $post_id
                    );
                }
            }
        }


        if (
            ! $pod ||
            ! $pod->exists()
        ) {
            return '';
        }


        /**
         * Relationship field uitlezen.
         */
        $get_term = function( $field_name ) use ( $pod ) {

            $raw = method_exists( $pod, 'raw' )
                ? $pod->raw( $field_name )
                : $pod->field( $field_name );

            if ( empty( $raw ) ) {
                return false;
            }

            if (
                is_object( $raw ) ||
                (
                    is_array( $raw ) &&
                    (
                        isset( $raw['term_id'] ) ||
                        isset( $raw['pod_item_id'] ) ||
                        isset( $raw['ID'] ) ||
                        isset( $raw['id'] )
                    )
                )
            ) {
                $raw = [ $raw ];
            }

            foreach ( (array) $raw as $relation ) {

                if ( is_array( $relation ) ) {

                    $term_id = (int) (
                        $relation['term_id']
                        ?? $relation['pod_item_id']
                        ?? $relation['ID']
                        ?? $relation['id']
                        ?? 0
                    );

                    $taxonomy = ! empty( $relation['taxonomy'] )
                        ? sanitize_key( $relation['taxonomy'] )
                        : '';

                } elseif ( is_object( $relation ) ) {

                    $term_id = (int) (
                        $relation->term_id
                        ?? $relation->pod_item_id
                        ?? $relation->ID
                        ?? $relation->id
                        ?? 0
                    );

                    $taxonomy = ! empty( $relation->taxonomy )
                        ? sanitize_key( $relation->taxonomy )
                        : '';

                } else {
                    continue;
                }

                if (
                    ! $term_id ||
                    ! $taxonomy ||
                    ! taxonomy_exists( $taxonomy )
                ) {
                    continue;
                }

                $term = get_term(
                    $term_id,
                    $taxonomy
                );

                if (
                    $term instanceof WP_Term &&
                    ! is_wp_error( $term )
                ) {
                    return $term;
                }
            }

            return false;
        };


        /**
         * 1. Expliciete button-relatie.
         */
        $term = $get_term(
            'relationship_vacature_button_url'
        );


        /**
         * 2. Fallback naar eerste andere gevulde relationship_.
         */
        if ( ! $term ) {

            $fields = $pod->fields();

            if ( is_array( $fields ) ) {

                foreach ( $fields as $field_name => $field ) {

                    if (
                        ! is_string( $field_name ) ||
                        strpos(
                            $field_name,
                            'relationship_'
                        ) !== 0 ||
                        $field_name ===
                            'relationship_vacature_button_url'
                    ) {
                        continue;
                    }

                    $term = $get_term( $field_name );

                    if ( $term ) {
                        break;
                    }
                }
            }
        }


        if ( ! $term instanceof WP_Term ) {
            return '';
        }


        /**
         * Native URL forceren.
         */
        $GLOBALS['tfsc_force_native_term_link'] = true;

        $url = get_term_link( $term );

        unset(
            $GLOBALS['tfsc_force_native_term_link']
        );


        return is_wp_error( $url )
            ? ''
            : esc_url( $url );
    }
);

/**
 * TFSC - Generic Derived Relationship Taxonomy Terms
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Toont in een Elementor Taxonomy Loop de taxonomy-terms die
 * voorkomen binnen OPEN vacatures die overeenkomen met alle
 * actieve Pods relationship_ velden van de huidige CPT/post.
 *
 *
 * ============================================================
 * ELEMENTOR
 * ============================================================
 *
 * Elementor Source bepaalt de taxonomy.
 *
 * Voorbeeld:
 *
 * Source:
 * locatie
 *
 * Query ID:
 * relationship_level_1
 *
 *
 * Of:
 *
 * Source:
 * kennisgebied
 *
 * Query ID:
 * relationship_level_0
 *
 *
 * De taxonomy hoeft dus NIET meer in de Query ID te staan.
 *
 *
 * ============================================================
 * RELATIONSHIP LOGICA
 * ============================================================
 *
 * Stel op de huidige CPT staat:
 *
 * relationship_functienaam
 * → Field Service Engineer
 *
 * relationship_functie-inhoud
 * → Inbedrijfstellen
 *
 * relationship_kennisgebied
 * → Elektrotechniek
 *
 * Dan zoeken we OPEN vacatures met:
 *
 * functienaam = Field Service Engineer
 * AND
 * functie-inhoud = Inbedrijfstellen
 * AND
 * kennisgebied = Elektrotechniek
 *
 * Elementor Source bepaalt vervolgens welke taxonomy-terms
 * uit die vacatures worden teruggegeven.
 *
 *
 * ============================================================
 * MEERDERE SELECTIES
 * ============================================================
 *
 * Verschillende taxonomies:
 * AND
 *
 * Meerdere terms binnen dezelfde taxonomy:
 * IN / OR
 *
 *
 * ============================================================
 * UITGESLOTEN FIELD
 * ============================================================
 *
 * relationship_vacature_button_url
 *
 * wordt nooit gebruikt om vacatures te filteren.
 *
 *
 * ============================================================
 * LEVEL
 * ============================================================
 *
 * relationship_level_0
 * → alleen top-level terms
 *
 * relationship_level_1
 * → exact één ancestor
 *
 * relationship_level_2
 * → exact twee ancestors
 *
 * Elementor Filter by Depth kan UIT blijven.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_derived_rel_v3_vacancy_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_derived_rel_v3_status_taxonomy() {

    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}


function tfsc_derived_rel_v3_open_status() {

    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


function tfsc_derived_rel_v3_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. CPT / POST CONTEXT
 * ============================================================
 *
 * Deze werkende contextmethode uit de bestaande snippet blijft
 * behouden.
 *
 * Werkt met:
 *
 * - normale CPT/post frontend
 * - Elementor Theme Builder preview
 * - preview_id fallback
 */

function tfsc_derived_rel_v3_get_context_post_id() {

    static $resolved = null;

    if ( null !== $resolved ) {
        return $resolved;
    }

    $resolved = 0;
    $object   = get_queried_object();


    /**
     * Normale frontend.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' !== get_post_type( $object->ID )
    ) {
        return $resolved = (int) $object->ID;
    }


    /**
     * Elementor Theme Builder.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' === get_post_type( $object->ID )
    ) {

        $template_id = (int) $object->ID;

        if (
            did_action( 'elementor/loaded' ) &&
            class_exists( '\Elementor\Plugin' )
        ) {
            try {

                $document =
                    \Elementor\Plugin::$instance
                        ->documents
                        ->get( $template_id );

                if ( $document ) {

                    $preview_id = absint(
                        $document->get_settings(
                            'preview_id'
                        )
                    );

                    if (
                        $preview_id &&
                        'elementor_library' !==
                        get_post_type( $preview_id )
                    ) {
                        return $resolved = $preview_id;
                    }
                }

            } catch ( Throwable $e ) {
                // Meta fallback hieronder.
            }
        }


        $settings = get_post_meta(
            $template_id,
            '_elementor_page_settings',
            true
        );

        if (
            is_array( $settings ) &&
            ! empty( $settings['preview_id'] )
        ) {

            $preview_id =
                absint(
                    $settings['preview_id']
                );

            if (
                $preview_id &&
                'elementor_library' !==
                get_post_type( $preview_id )
            ) {
                return $resolved = $preview_id;
            }
        }
    }


    /**
     * WordPress / Elementor preview fallback.
     */
    if ( ! empty( $_GET['preview_id'] ) ) {

        $preview_id = absint(
            wp_unslash(
                $_GET['preview_id']
            )
        );

        if (
            $preview_id &&
            'elementor_library' !==
            get_post_type( $preview_id )
        ) {
            return $resolved = $preview_id;
        }
    }


    /**
     * Laatste fallback.
     */
    global $post;

    if (
        $post instanceof WP_Post &&
        'elementor_library' !==
        get_post_type( $post->ID )
    ) {
        return $resolved = (int) $post->ID;
    }


    return 0;
}


/**
 * ============================================================
 * 3. HUIDIGE POD
 * ============================================================
 */

function tfsc_derived_rel_v3_get_current_pod() {

    static $resolved = false;
    static $pod      = false;

    if ( $resolved ) {
        return $pod;
    }

    $resolved = true;

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $post_id =
        tfsc_derived_rel_v3_get_context_post_id();

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        $pod = false;
    }

    return $pod;
}


/**
 * ============================================================
 * 4. RAW RELATIONSHIP NORMALISEREN
 * ============================================================
 *
 * Gebruikt dezelfde bewezen aanpak als de andere werkende
 * TFSC relationship snippets:
 *
 * RAW/Pods relationshipdata bepaalt:
 *
 * - taxonomy
 * - term_id
 *
 * Resultaat:
 *
 * [
 *     [
 *         'taxonomy' => 'functie-inhoud',
 *         'term_id'  => 220,
 *     ]
 * ]
 */

function tfsc_derived_rel_v3_normalize_relationship(
    $value
) {

    if ( empty( $value ) ) {
        return [];
    }


    /**
     * Eén relationship normaliseren naar lijst.
     */
    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }


    if ( ! is_array( $value ) ) {
        return [];
    }


    $result = [];


    foreach ( $value as $relation ) {

        $taxonomy = '';
        $term_id  = 0;


        if ( is_array( $relation ) ) {

            $taxonomy = sanitize_key(
                $relation['taxonomy']
                ?? ''
            );

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

        } elseif ( is_object( $relation ) ) {

            $taxonomy = sanitize_key(
                $relation->taxonomy
                ?? ''
            );

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

        } else {

            continue;
        }


        if (
            ! $taxonomy ||
            ! $term_id ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }


        $term = get_term(
            $term_id,
            $taxonomy
        );


        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {

            $result[] = [
                'taxonomy' => $taxonomy,
                'term_id'  => $term_id,
            ];
        }
    }


    return $result;
}


/**
 * ============================================================
 * 5. ALLE ACTIEVE RELATIONSHIPS
 * ============================================================
 *
 * Leest ALLE gevulde relationship_ velden van de huidige Pod.
 *
 * relationship_vacature_button_url wordt uitgesloten.
 *
 * Resultaat bijvoorbeeld:
 *
 * [
 *     'functienaam' => [226],
 *
 *     'functie-inhoud' => [220],
 *
 *     'kennisgebied' => [310],
 * ]
 */

function tfsc_derived_rel_v3_relationship_groups() {

    static $cache = null;

    if ( null !== $cache ) {
        return $cache;
    }

    $cache = [];

    $pod =
        tfsc_derived_rel_v3_get_current_pod();

    if ( ! $pod ) {
        return [];
    }


    $fields =
        $pod->fields();

    if (
        ! is_array( $fields ) ||
        ! $fields
    ) {
        return [];
    }


    foreach (
        $fields
        as $field_name => $definition
    ) {

        if (
            ! is_string( $field_name ) ||
            0 !== strpos(
                $field_name,
                'relationship_'
            ) ||
            'relationship_vacature_button_url'
            ===
            $field_name
        ) {
            continue;
        }


        /**
         * Bewust de normale Pods relationshipwaarde gebruiken.
         *
         * Op deze site bevat deze RAW relationshipstructuur
         * betrouwbaar taxonomy + term_id.
         */
        $value =
            $pod->field(
                $field_name
            );


        $relationships =
            tfsc_derived_rel_v3_normalize_relationship(
                $value
            );


        foreach (
            $relationships
            as $relationship
        ) {

            $cache[
                $relationship['taxonomy']
            ][] =
                (int)
                $relationship['term_id'];
        }
    }


    /**
     * Dubbelen verwijderen.
     */
    foreach (
        $cache
        as $taxonomy => $ids
    ) {

        $ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            )
        );


        if ( $ids ) {

            $cache[ $taxonomy ] =
                $ids;

        } else {

            unset(
                $cache[ $taxonomy ]
            );
        }
    }


    return $cache;
}


/**
 * ============================================================
 * 6. OPEN VACATURES OP BASIS VAN ALLE RELATIONSHIPS
 * ============================================================
 *
 * Verschillende taxonomies = AND.
 *
 * Meerdere terms binnen dezelfde taxonomy = IN / OR.
 */

function tfsc_derived_rel_v3_get_vacancy_ids(
    $relationship_groups
) {

    static $cache = [];

    if ( empty( $relationship_groups ) ) {
        return [];
    }


    /**
     * Stabiele cache-key.
     */
    ksort(
        $relationship_groups
    );

    foreach (
        $relationship_groups
        as &$ids
    ) {

        $ids = array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );

        sort( $ids );
    }

    unset( $ids );


    $key = md5(
        serialize(
            $relationship_groups
        )
    );


    if ( isset( $cache[ $key ] ) ) {
        return $cache[ $key ];
    }


    $post_type =
        tfsc_derived_rel_v3_vacancy_post_type();


    if ( ! post_type_exists( $post_type ) ) {
        return [];
    }


    $tax_query = [
        'relation' => 'AND',
    ];


    foreach (
        $relationship_groups
        as $taxonomy => $term_ids
    ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $term_ids
        ) {
            continue;
        }


        $tax_query[] = [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => $term_ids,
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }


    /**
     * Geen bruikbare relationship-query.
     */
    if ( count( $tax_query ) <= 1 ) {
        return [];
    }


    /**
     * Alleen OPEN vacatures.
     */
    $status_taxonomy =
        tfsc_derived_rel_v3_status_taxonomy();


    if ( taxonomy_exists( $status_taxonomy ) ) {

        $tax_query[] = [
            'taxonomy'         =>
                $status_taxonomy,

            'field'            =>
                'slug',

            'terms'            => [
                tfsc_derived_rel_v3_open_status(),
            ],

            'operator'         =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    $ids = get_posts( [
        'post_type'        =>
            $post_type,

        'post_status'      =>
            'publish',

        'posts_per_page'   =>
            -1,

        'fields'           =>
            'ids',

        'no_found_rows'    =>
            true,

        'suppress_filters' =>
            false,

        'tax_query'        =>
            $tax_query,
    ] );


    return $cache[ $key ] =
        array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );
}


/**
 * ============================================================
 * 7. TARGET TERMS UIT VACATURES
 * ============================================================
 *
 * Elementor Source bepaalt welke taxonomy hier wordt gebruikt.
 *
 * Bij hiërarchische taxonomies worden ancestors meegenomen,
 * waarna later exact op level wordt gefilterd.
 */

function tfsc_derived_rel_v3_get_target_term_ids(
    $vacancy_ids,
    $taxonomy
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }


    $ids = wp_get_object_terms(
        array_map(
            'intval',
            $vacancy_ids
        ),
        $taxonomy,
        [
            'fields' => 'ids',
        ]
    );


    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }


    $ids =
        array_map(
            'intval',
            $ids
        );


    if (
        is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        foreach ( $ids as $id ) {

            $ids = array_merge(
                $ids,
                get_ancestors(
                    $id,
                    $taxonomy,
                    'taxonomy'
                )
            );
        }
    }


    return array_values(
        array_unique(
            array_filter(
                array_map(
                    'intval',
                    $ids
                )
            )
        )
    );
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 *
 * level 0 = top-level
 * level 1 = exact één ancestor
 * level 2 = exact twee ancestors
 */

function tfsc_derived_rel_v3_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( ! $ids ) {
        return [];
    }


    /**
     * Niet-hiërarchische taxonomy heeft alleen level 0.
     */
    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return 0 === (int) $level
            ? array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            )
            : [];
    }


    return array_values(
        array_filter(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            ),
            function( $id ) use (
                $taxonomy,
                $level
            ) {

                return count(
                    get_ancestors(
                        $id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === (int) $level;
            }
        )
    );
}


/**
 * ============================================================
 * 9. QUERY ID
 * ============================================================
 *
 * relationship_level_0
 * relationship_level_1
 * relationship_level_2
 */

function tfsc_derived_rel_v3_parse_query_id(
    $query_id
) {

    if (
        ! preg_match(
            '/^relationship_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }


    return [
        'level' =>
            (int) $matches[1],
    ];
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Elementor Source bepaalt de taxonomy.
 *
 * Priority 30 blijft behouden.
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings[
                'post_taxonomy_term_taxonomy_id'
            ]
            ??
            '';


        $parsed =
            tfsc_derived_rel_v3_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        /**
         * Elementor Source = target taxonomy.
         */
        $taxonomy =
            $args['taxonomy']
            ??
            $settings[
                'post_taxonomy_query_post_type'
            ]
            ??
            '';


        if ( is_array( $taxonomy ) ) {
            $taxonomy =
                reset(
                    $taxonomy
                );
        }


        $taxonomy =
            sanitize_key(
                $taxonomy
            );


        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy ) ||
            $taxonomy ===
            tfsc_derived_rel_v3_status_taxonomy()
        ) {
            return $args;
        }


        /**
         * Alle actieve relationship selections.
         */
        $relationship_groups =
            tfsc_derived_rel_v3_relationship_groups();


        if ( ! $relationship_groups ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /**
         * Alleen vacatures die voldoen aan de volledige
         * relationship-combinatie.
         */
        $vacancy_ids =
            tfsc_derived_rel_v3_get_vacancy_ids(
                $relationship_groups
            );


        if ( ! $vacancy_ids ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /**
         * Terms van Elementor Source uit deze vacatures.
         */
        $target_ids =
            tfsc_derived_rel_v3_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );


        /**
         * Exact level.
         */
        $target_ids =
            tfsc_derived_rel_v3_filter_level(
                $target_ids,
                $taxonomy,
                $parsed['level']
            );


        if ( ! $target_ids ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        /**
         * Alleen de relevante terms beperken.
         *
         * Overige Elementor widgetinstellingen blijven zoveel
         * mogelijk ongemoeid.
         */
        $args['taxonomy']   =
            $taxonomy;

        $args['include']    =
            $target_ids;

        $args['hide_empty'] =
            false;

        $args['hierarchical'] =
            false;


        /**
         * Marker voor sorteerfix.
         */
        $args[
            'tfsc_derived_relationship_query'
        ] = 1;


        /**
         * Marker voor combo term-links.
         */
        $GLOBALS[
            'tfsc_derived_rel_v3_active_targets'
        ][ $taxonomy ] =
            true;


        return $args;
    },
    30,
    3
);


/**
 * ============================================================
 * 11. SORTERING
 * ============================================================
 *
 * WordPress groepeert hiërarchische terms anders per parent.
 *
 * Daarom wordt de uiteindelijke lijst na afloop alfabetisch
 * gesorteerd wanneer Elementor op naam sorteert.
 *
 * Priority 9999 blijft behouden.
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            is_admin() ||
            empty(
                $args[
                    'tfsc_derived_relationship_query'
                ]
            ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }


        if (
            isset( $args['orderby'] ) &&
            'name' !== strtolower(
                (string) $args['orderby']
            )
        ) {
            return $terms;
        }


        $order =
            strtoupper(
                (string) (
                    $args['order']
                    ?? 'ASC'
                )
            );


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {
            $order = 'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }


                $compare =
                    strnatcasecmp(
                        remove_accents(
                            wp_strip_all_tags(
                                $a->name
                            )
                        ),
                        remove_accents(
                            wp_strip_all_tags(
                                $b->name
                            )
                        )
                    );


                return 'DESC' === $order
                    ? -$compare
                    : $compare;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 12. TERMPAD
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * noord-brabant/tilburg
 */

function tfsc_derived_rel_v3_term_path(
    $term
) {

    if (
        ! $term instanceof WP_Term ||
        ! taxonomy_exists(
            $term->taxonomy
        )
    ) {
        return '';
    }


    $ids =
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
            ? array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            )
            : [];


    $slugs = [];


    foreach ( $ids as $id ) {

        $ancestor =
            get_term(
                $id,
                $term->taxonomy
            );


        if (
            $ancestor instanceof WP_Term &&
            ! is_wp_error( $ancestor )
        ) {
            $slugs[] =
                $ancestor->slug;
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 13. COMBO URL
 * ============================================================
 *
 * Bouwt een comboarchief uit:
 *
 * ALLE actieve relationship selections
 *
 * +
 *
 * de aangeklikte target term.
 *
 *
 * Voorbeeld:
 *
 * functienaam
 * → Field Service Engineer
 *
 * functie-inhoud
 * → Inbedrijfstellen
 *
 * kennisgebied
 * → Elektrotechniek
 *
 * aangeklikte locatie
 * → Noord-Brabant
 *
 * wordt:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * functie-inhoud/inbedrijfstellen/
 * kennisgebied/elektrotechniek/
 * locatie/noord-brabant/
 */

function tfsc_derived_rel_v3_build_combo_url(
    $target_term
) {

    if (
        ! $target_term instanceof WP_Term
    ) {
        return false;
    }


    $groups =
        tfsc_derived_rel_v3_relationship_groups();


    if ( ! $groups ) {
        return false;
    }


    $parts = [
        tfsc_derived_rel_v3_combo_base(),
    ];


    /**
     * Alle actieve relationships toevoegen.
     */
    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        foreach (
            $term_ids
            as $term_id
        ) {

            /**
             * Exact dezelfde target-term niet dubbel toevoegen.
             */
            if (
                $taxonomy ===
                $target_term->taxonomy &&
                (int) $term_id ===
                (int) $target_term->term_id
            ) {
                continue;
            }


            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }


            $path =
                tfsc_derived_rel_v3_term_path(
                    $term
                );


            if ( ! $path ) {
                continue;
            }


            $parts[] =
                $taxonomy;

            $parts[] =
                $path;
        }
    }


    /**
     * Aangeklikte target term toevoegen.
     */
    $target_path =
        tfsc_derived_rel_v3_term_path(
            $target_term
        );


    if ( ! $target_path ) {
        return false;
    }


    $parts[] =
        $target_term->taxonomy;

    $parts[] =
        $target_path;


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                fn( $part ) =>
                    trim(
                        $part,
                        '/'
                    ),
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 14. TERM LINKS → COMBO ARCHIVES
 * ============================================================
 *
 * Alleen terms die door deze relationship loop geactiveerd zijn
 * krijgen een combo-link.
 *
 * tfsc_force_native_term_link blijft gerespecteerd.
 *
 * Priority 30 blijft behouden.
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! $taxonomy
        ) {
            return $termlink;
        }


        /**
         * Alleen CPT/post-context.
         */
        $object =
            get_queried_object();


        if (
            ! $object instanceof WP_Post
        ) {
            return $termlink;
        }


        if (
            $taxonomy ===
            tfsc_derived_rel_v3_status_taxonomy()
        ) {
            return $termlink;
        }


        /**
         * Alleen taxonomies die daadwerkelijk door deze
         * Elementor relationship-loop geactiveerd zijn.
         */
        if (
            empty(
                $GLOBALS[
                    'tfsc_derived_rel_v3_active_targets'
                ][ $taxonomy ]
            )
        ) {
            return $termlink;
        }


        $url =
            tfsc_derived_rel_v3_build_combo_url(
                $term
            );


        return $url
            ?: $termlink;
    },
    30,
    3
);

/**
 * TFSC - Vacature Button URL + Text via Relationship Groups
 *
 * Shortcodes:
 *
 * [vacature_button_url]
 * [vacature_button_text]
 *
 * ============================================================
 * WERKING
 * ============================================================
 *
 * 1. relationship_vacature_button_url gevuld?
 *
 *    → gebruik de native taxonomy-term URL
 *    → buttontekst = naam van die term
 *
 * 2. relationship_vacature_button_url leeg?
 *
 *    → gebruik ALLE actieve relationship_ velden
 *      uit:
 *
 *      tfsc_derived_rel_v3_relationship_groups()
 *
 *    → bouw daarmee één TFSC combo archive URL
 *
 *    → buttontekst = "Bekijk vacatures"
 *
 *
 * ============================================================
 * VOORBEELD
 * ============================================================
 *
 * relationship_functienaam
 * → Field Service Engineer
 *
 * relationship_functie-inhoud
 * → Inbedrijfstellen
 *
 * relationship_kennisgebied
 * → Elektrotechniek
 *
 * Zonder expliciete button-selectie:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * functie-inhoud/inbedrijfstellen/
 * kennisgebied/elektrotechniek/
 *
 *
 * ============================================================
 * AFHANKELIJKHEID
 * ============================================================
 *
 * Deze snippet gebruikt de werkende functies uit:
 *
 * TFSC - Generic Derived Relationship Taxonomy Terms V3
 *
 * met name:
 *
 * tfsc_derived_rel_v3_relationship_groups()
 * tfsc_derived_rel_v3_term_path()
 * tfsc_derived_rel_v3_combo_base()
 */


/**
 * ============================================================
 * 1. HUIDIGE POD
 * ============================================================
 */
function tfsc_vacature_button_v3_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();


    /**
     * Taxonomy-term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }


    /**
     * CPT / post / Elementor preview.
     *
     * Gebruik dezelfde contextresolver als de relationship
     * taxonomy-loop indien beschikbaar.
     */
    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {
        $post_id = (int)
            tfsc_derived_rel_v3_get_context_post_id();

    } elseif (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id = (int)
            tfsc_derived_rel_v2_get_context_post_id();

    } elseif (
        $object instanceof WP_Post
    ) {
        $post_id = (int) $object->ID;

    } else {
        $post_id = (int) get_queried_object_id();
    }


    if ( ! $post_id ) {
        return false;
    }


    $post_type =
        get_post_type(
            $post_id
        );


    if (
        ! $post_type ||
        'elementor_library' === $post_type
    ) {
        return false;
    }


    $pod = pods(
        $post_type,
        $post_id
    );


    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * 2. EXPLICIETE BUTTON TERM
 * ============================================================
 *
 * relationship_vacature_button_url
 */
function tfsc_vacature_button_v3_explicit_term() {

    $pod =
        tfsc_vacature_button_v3_pod();

    if ( ! $pod ) {
        return false;
    }


    $value =
        $pod->field(
            'relationship_vacature_button_url'
        );


    if ( empty( $value ) ) {
        return false;
    }


    /**
     * Eén relatie normaliseren naar lijst.
     */
    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }


    foreach ( (array) $value as $relation ) {

        $term_id  = 0;
        $taxonomy = '';


        if ( is_array( $relation ) ) {

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

        } elseif ( is_object( $relation ) ) {

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );
        }


        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }


        $term = get_term(
            $term_id,
            $taxonomy
        );


        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            return $term;
        }
    }


    return false;
}


/**
 * ============================================================
 * 3. COMBO URL UIT ALLE ACTIEVE RELATIONSHIPS
 * ============================================================
 */
function tfsc_vacature_button_v3_combo_url() {

    if (
        ! function_exists(
            'tfsc_derived_rel_v3_relationship_groups'
        ) ||
        ! function_exists(
            'tfsc_derived_rel_v3_term_path'
        ) ||
        ! function_exists(
            'tfsc_derived_rel_v3_combo_base'
        )
    ) {
        return '';
    }


    $groups =
        tfsc_derived_rel_v3_relationship_groups();


    if ( ! $groups ) {
        return '';
    }


    $parts = [
        tfsc_derived_rel_v3_combo_base(),
    ];


    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        foreach (
            $term_ids
            as $term_id
        ) {

            $term = get_term(
                $term_id,
                $taxonomy
            );


            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }


            $path =
                tfsc_derived_rel_v3_term_path(
                    $term
                );


            if ( ! $path ) {
                continue;
            }


            $parts[] =
                $taxonomy;

            $parts[] =
                $path;
        }
    }


    if ( count( $parts ) <= 1 ) {
        return '';
    }


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                fn( $part ) =>
                    trim(
                        $part,
                        '/'
                    ),
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 4. BUTTON URL
 * ============================================================
 *
 * [vacature_button_url]
 */
add_shortcode(
    'vacature_button_url',
    function() {

        /**
         * Expliciete selectie heeft altijd voorrang.
         */
        $term =
            tfsc_vacature_button_v3_explicit_term();


        if ( $term ) {

            $GLOBALS[
                'tfsc_force_native_term_link'
            ] = true;

            $url =
                get_term_link(
                    $term
                );

            unset(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            );


            return is_wp_error( $url )
                ? ''
                : esc_url( $url );
        }


        /**
         * Geen expliciete selectie:
         * combo van alle actieve relationships.
         */
        $url =
            tfsc_vacature_button_v3_combo_url();


        return $url
            ? esc_url( $url )
            : '';
    }
);


/**
 * ============================================================
 * 5. BUTTON TEXT
 * ============================================================
 *
 * [vacature_button_text]
 *
 * Expliciete button-term:
 * → naam van de term
 *
 * Combo fallback:
 * → Bekijk vacatures
 */
add_shortcode(
    'vacature_button_text',
    function() {

        $term =
            tfsc_vacature_button_v3_explicit_term();


        if ( $term ) {
            return esc_html(
                $term->name
            );
        }


        $groups =
            function_exists(
                'tfsc_derived_rel_v3_relationship_groups'
            )
                ? tfsc_derived_rel_v3_relationship_groups()
                : [];


        return $groups
            ? 'Bekijk vacatures'
            : '';
    }
);

/**
 * TFSC - Volledig dynamische vacature-archieven
 *
 * - Virtuele combo archives onder /vacatures/...
 * - Onbeperkt aantal taxonomies/terms
 * - Verschillende taxonomies = AND
 * - Meerdere terms binnen taxonomy = OR
 * - kennisgebied = AND
 * - Alleen vac_status=open
 * - Search & Filter Pro v3 sync
 * - Elementor archive condition
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_BASE' ) ) {
    define( 'TFSC_COMBO_BASE', 'vacatures' );
}

if ( ! defined( 'TFSC_VACANCY_POST_TYPE' ) ) {
    define( 'TFSC_VACANCY_POST_TYPE', 'vacature' );
}

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}

if ( ! defined( 'TFSC_STATUS_TAXONOMY' ) ) {
    define( 'TFSC_STATUS_TAXONOMY', 'vac_status' );
}

if ( ! defined( 'TFSC_OPEN_STATUS_SLUG' ) ) {
    define( 'TFSC_OPEN_STATUS_SLUG', 'open' );
}


/**
 * ============================================================
 * HELPERS
 * ============================================================
 */

function tfsc_get_combo_taxonomy_match_method( $taxonomy ) {

    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


function tfsc_combo_status_clause() {

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    if (
        ! $taxonomy ||
        TFSC_STATUS_TAXONOMY === $taxonomy ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return false;
    }

    $object = get_taxonomy( $taxonomy );

    return (
        $object &&
        $object->publicly_queryable &&
        in_array(
            TFSC_VACANCY_POST_TYPE,
            (array) $object->object_type,
            true
        )
    );
}


function tfsc_get_allowed_combo_taxonomies() {

    static $allowed = null;

    if ( null !== $allowed ) {
        return $allowed;
    }

    $allowed = [];

    foreach (
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        )
        as $taxonomy => $object
    ) {
        if ( tfsc_combo_taxonomy_allowed( $taxonomy ) ) {
            $allowed[] = $taxonomy;
        }
    }

    return $allowed;
}


function tfsc_is_combo_archive() {

    return (bool) get_query_var(
        'tfsc_combo_archive'
    );
}


function tfsc_is_vacancy_seo_landing() {

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term = get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


/**
 * ============================================================
 * QUERY VARS + REWRITE
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';
        $vars[] = 'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        add_rewrite_rule(
            '^'
            . preg_quote( TFSC_COMBO_BASE, '/' )
            . '/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * TERMPAD OPLOSSEN
 * ============================================================
 */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy( $taxonomy );

    if (
        ! $tax_object ||
        ! is_array( $segments ) ||
        ! $segments
    ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            array_map(
                'sanitize_title',
                $segments
            )
        )
    );

    if (
        ! $segments ||
        (
            ! $tax_object->hierarchical &&
            1 !== count( $segments )
        )
    ) {
        return false;
    }

    $terms     = [];
    $parent_id = 0;

    foreach ( $segments as $index => $slug ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );

        if (
            ! $term ||
            is_wp_error( $term )
        ) {
            return false;
        }

        if (
            $index > 0 &&
            (int) $term->parent !== $parent_id
        ) {
            return false;
        }

        $terms[]  = $term;
        $parent_id = (int) $term->term_id;
    }

    return [
        'path' => $terms,
        'term' => end( $terms ),
    ];
}


/**
 * ============================================================
 * COMBO URL PARSEN
 * ============================================================
 */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;

    if ( $resolved ) {
        return $cache;
    }

    $resolved = true;

    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }

    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );

    if ( ! $raw_path ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            explode(
                '/',
                trim(
                    (string) $raw_path,
                    '/'
                )
            ),
            'strlen'
        )
    );

    if ( count( $segments ) < 2 ) {
        return false;
    }

    $allowed =
        tfsc_get_allowed_combo_taxonomies();

    if ( ! $allowed ) {
        return false;
    }

    $items = [];
    $count = count( $segments );
    $i     = 0;

    while ( $i < $count ) {

        $taxonomy =
            sanitize_key(
                $segments[ $i ]
            );

        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }

        $i++;
        $term_segments = [];

        while ( $i < $count ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[ $i ]
                );

            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }

            $term_segments[] =
                $segments[ $i ];

            $i++;
        }

        if ( ! $term_segments ) {
            return false;
        }

        $resolved_path =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );

        if ( ! $resolved_path ) {
            return false;
        }

        $items[] = [
            'taxonomy' => $taxonomy,
            'term'     => $resolved_path['term'],
            'path'     => $resolved_path['path'],
        ];
    }

    return $cache = (
        $items
            ? $items
            : false
    );
}


/**
 * ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================
 */

function tfsc_group_combo_terms(
    $property = 'term_id'
) {

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    $grouped = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $taxonomy =
            $item['taxonomy'];

        if ( 'name' === $property ) {

            $value =
                trim(
                    $item['term']->name
                );

        } elseif ( 'slug' === $property ) {

            $value =
                $item['term']->slug;

        } else {

            $value =
                (int) $item['term']->term_id;
        }

        if (
            '' === $value ||
            0 === $value
        ) {
            continue;
        }

        if (
            ! isset(
                $grouped[ $taxonomy ]
            )
        ) {
            $grouped[ $taxonomy ] = [];
        }

        if (
            ! in_array(
                $value,
                $grouped[ $taxonomy ],
                true
            )
        ) {
            $grouped[ $taxonomy ][] =
                $value;
        }
    }

    return $grouped;
}


/**
 * ============================================================
 * TAX QUERY
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $grouped =
        tfsc_group_combo_terms(
            'term_id'
        );

    if ( ! $grouped ) {
        return false;
    }

    $tax_query = [
        'relation' => 'AND',
        tfsc_combo_status_clause(),
    ];

    foreach (
        $grouped
        as $taxonomy => $term_ids
    ) {

        if ( ! $term_ids ) {
            continue;
        }

        $object =
            get_taxonomy(
                $taxonomy
            );

        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );

        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method &&
                    $object &&
                    $object->hierarchical
                ),
        ];
    }

    return $tax_query;
}


