add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin() ||
            ! $query->is_main_query()
        ) {
            return;
        }

        /**
         * Virtuele combo archive.
         */
        if ( tfsc_is_combo_archive() ) {

            $tax_query =
                tfsc_build_combo_tax_query();

            if ( ! $tax_query ) {
                return;
            }

            $query->set(
                'post_type',
                TFSC_VACANCY_POST_TYPE
            );

            $query->set(
                'post_status',
                'publish'
            );

            $query->set(
                'tax_query',
                $tax_query
            );

            $query->set(
                'no_found_rows',
                false
            );

            return;
        }

        /**
         * Native vacature taxonomy archive.
         */
        if ( ! $query->is_tax() ) {
            return;
        }

        $term =
            $query->get_queried_object();

        if (
            ! $term instanceof WP_Term ||
            ! tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {
            return;
        }

        $tax_query =
            $query->get(
                'tax_query'
            );

        if ( ! is_array( $tax_query ) ) {
            $tax_query = [];
        }

        $tax_query[] =
            tfsc_combo_status_clause();

        $tax_query['relation'] =
            'AND';

        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );

        $query->set(
            'post_status',
            'publish'
        );

        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
);


