/**
 * TFSC - Taxonomy Base Archive Settings Fields
 *
 * Leest generieke velden uit:
 *
 * pods_archief_instellingen
 *
 * Veldnaam:
 *
 * archive_{context}_{taxonomy}_{field}
 *
 * Voorbeeld:
 *
 * huidige taxonomy:
 * beroep_functienaam
 *
 * wordt genormaliseerd naar:
 * functienaam
 *
 * en geeft:
 * archive_beroep_functienaam_description
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_archive_settings_pod_name() {
    return 'pods_archief_instellingen';
}


/**
 * ============================================================
 * 2. TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functienaam
 * → functienaam
 *
 * beroep_kennisgebied
 * → kennisgebied
 */

function tfsc_archive_settings_normalize_taxonomy(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );

    foreach (
        [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ]
        as $prefix
    ) {

        if (
            0 === strpos(
                $taxonomy,
                $prefix
            )
        ) {
            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen( $prefix )
                )
            );
        }
    }

    return $taxonomy;
}


/**
 * ============================================================
 * 3. HUIDIGE TAXONOMY BASE
 * ============================================================
 */

function tfsc_archive_settings_taxonomy() {

    if (
        ! function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {
        return '';
    }

    $taxonomy =
        tfsc_get_current_taxonomy_archive();

    if (
        is_object( $taxonomy ) &&
        ! empty( $taxonomy->name )
    ) {
        $taxonomy =
            $taxonomy->name;
    }

    $taxonomy =
        tfsc_archive_settings_normalize_taxonomy(
            $taxonomy
        );

    return $taxonomy;
}


/**
 * ============================================================
 * 4. VELDNAAM OPBOUWEN
 * ============================================================
 *
 * archive_{context}_{taxonomy}_{field}
 */

function tfsc_archive_settings_field_name(
    $context,
    $field
) {

    $taxonomy =
        tfsc_archive_settings_taxonomy();

    $context =
        sanitize_key(
            $context
        );

    $field =
        sanitize_key(
            $field
        );

    if (
        ! $taxonomy ||
        ! $context ||
        ! $field
    ) {
        return '';
    }

    return sanitize_key(
        'archive_'
        . $context
        . '_'
        . $taxonomy
        . '_'
        . $field
    );
}


/**
 * ============================================================
 * 5. PODS SETTINGS VALUE
 * ============================================================
 */

function tfsc_archive_settings_value(
    $context,
    $field
) {

    if ( ! function_exists( 'pods' ) ) {
        return '';
    }

    $field_name =
        tfsc_archive_settings_field_name(
            $context,
            $field
        );

    if ( ! $field_name ) {
        return '';
    }

    $pod =
        pods(
            tfsc_archive_settings_pod_name()
        );

    if ( ! $pod ) {
        return '';
    }

    $value =
        $pod->field(
            $field_name
        );

    return (
        null === $value ||
        false === $value
    )
        ? ''
        : $value;
}


/**
 * ============================================================
 * 6. SHORTCODE
 * ============================================================
 *
 * [tfsc_archive_field
 *     context="beroep"
 *     field="description"]
 */

add_shortcode(
    'tfsc_archive_field',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'context' => 'beroep',
                'field'   => '',
            ],
            $atts,
            'tfsc_archive_field'
        );

        $value =
            tfsc_archive_settings_value(
                $atts['context'],
                $atts['field']
            );

        if (
            is_array( $value ) ||
            is_object( $value )
        ) {
            return '';
        }

        return wp_kses_post(
            (string) $value
        );
    }
);


/**
 * ============================================================
 * 7. ELEMENTOR DYNAMIC TAG
 * ============================================================
 */

add_action(
    'elementor/dynamic_tags/register',
    function( $dynamic_tags ) {

        if (
            ! class_exists(
                '\Elementor\Core\DynamicTags\Tag'
            )
        ) {
            return;
        }

        class TFSC_Archive_Settings_Field_Tag
            extends \Elementor\Core\DynamicTags\Tag {

            public function get_name() {
                return 'tfsc-archive-settings-field';
            }

            public function get_title() {
                return 'TFSC Archive Settings Field';
            }

            public function get_group() {
                return 'site';
            }

            public function get_categories() {
                return [
                    \Elementor\Modules\DynamicTags\Module::TEXT_CATEGORY,
                ];
            }

            protected function register_controls() {

                $this->add_control(
                    'context',
                    [
                        'label'   => 'Context',
                        'type'    =>
                            \Elementor\Controls_Manager::TEXT,
                        'default' => 'beroep',
                    ]
                );

                $this->add_control(
                    'field',
                    [
                        'label' =>
                            'Field',

                        'type' =>
                            \Elementor\Controls_Manager::TEXT,

                        'placeholder' =>
                            'description',
                    ]
                );
            }

            public function render() {

                $value =
                    tfsc_archive_settings_value(
                        $this->get_settings(
                            'context'
                        ),
                        $this->get_settings(
                            'field'
                        )
                    );

                if (
                    is_array( $value ) ||
                    is_object( $value )
                ) {
                    return;
                }

                echo wp_kses_post(
                    (string) $value
                );
            }
        }

        $dynamic_tags->register(
            new TFSC_Archive_Settings_Field_Tag()
        );
    }
);

