/**
 * TFSC - Dynamische tekst shortcodes
 *
 * Shortcodes:
 *
 * [post_title]
 * [archive_title]
 * [tfsc_pods field="..."]
 *
 * ============================================================
 * CASE
 * ============================================================
 *
 * case="normal"
 * case="lower"
 * case="sentence"
 *
 *
 * ============================================================
 * [archive_title] MODES
 * ============================================================
 *
 * Term archives:
 *
 * current
 * parents
 * full
 * label_current
 * label_full
 *
 * Taxonomy base archives:
 *
 * taxonomy
 * taxonomy_plural
 */


/**
 * ============================================================
 * 1. CONTEXT POST ID
 * ============================================================
 */

function tfsc_text_context_post_id() {

    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v3_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }

    if (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v2_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }

    $object =
        get_queried_object();

    if ( $object instanceof WP_Post ) {
        return (int) $object->ID;
    }

    return (int) get_the_ID();
}


/**
 * ============================================================
 * 2. CONTEXT POD
 * ============================================================
 */

function tfsc_text_context_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object =
        get_queried_object();

    /**
     * Taxonomy term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /**
     * Post / CPT / Elementor preview.
     */
    $post_id =
        tfsc_text_context_post_id();

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * 3. TAXONOMY BASE OBJECT
 * ============================================================
 */

function tfsc_text_taxonomy_archive_object() {

    if (
        ! function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {
        return false;
    }

    $taxonomy =
        tfsc_get_current_taxonomy_archive();

    if ( $taxonomy instanceof WP_Taxonomy ) {
        return $taxonomy;
    }

    if ( is_string( $taxonomy ) ) {

        $taxonomy =
            get_taxonomy(
                sanitize_key( $taxonomy )
            );

        return $taxonomy instanceof WP_Taxonomy
            ? $taxonomy
            : false;
    }

    return false;
}


/**
 * ============================================================
 * 4. TEXT CASE
 * ============================================================
 */

function tfsc_text_case(
    $text,
    $case = 'normal'
) {

    $text =
        (string) $text;

    if ( '' === $text ) {
        return '';
    }

    switch (
        sanitize_key(
            $case
        )
    ) {

        case 'lower':

            return mb_strtolower(
                $text,
                'UTF-8'
            );


        case 'sentence':

            $text =
                mb_strtolower(
                    $text,
                    'UTF-8'
                );

            return
                mb_strtoupper(
                    mb_substr(
                        $text,
                        0,
                        1,
                        'UTF-8'
                    ),
                    'UTF-8'
                )
                .
                mb_substr(
                    $text,
                    1,
                    null,
                    'UTF-8'
                );


        default:

            return $text;
    }
}


/**
 * ============================================================
 * 5. [post_title]
 * ============================================================
 */

add_shortcode(
    'post_title',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'before' => '',
                'after'  => '',
                'case'   => 'normal',
            ],
            $atts,
            'post_title'
        );

        $post_id =
            tfsc_text_context_post_id();

        if ( ! $post_id ) {
            return '';
        }

        $title =
            wp_strip_all_tags(
                get_the_title(
                    $post_id
                )
            );

        if ( '' === $title ) {
            return '';
        }

        $title =
            tfsc_text_case(
                $title,
                $atts['case']
            );

        return
            (string) $atts['before']
            . $title
            . (string) $atts['after'];
    }
);


/**
 * ============================================================
 * 6. [archive_title]
 * ============================================================
 */

add_shortcode(
    'archive_title',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'mode'            => 'current',
                'separator'       => ' › ',
                'label_separator' => ': ',
                'before'          => '',
                'after'           => '',
                'case'            => 'normal',
            ],
            $atts,
            'archive_title'
        );

        $mode =
            sanitize_key(
                $atts['mode']
            );

        $object =
            get_queried_object();

        /**
         * ====================================================
         * TAXONOMY TERM ARCHIVE
         * ====================================================
         */
        if (
            $object instanceof WP_Term &&
            taxonomy_exists(
                $object->taxonomy
            )
        ) {

            $taxonomy =
                $object->taxonomy;

            $current =
                wp_strip_all_tags(
                    $object->name
                );

            $parents = [];

            if (
                is_taxonomy_hierarchical(
                    $taxonomy
                )
            ) {

                foreach (
                    array_reverse(
                        get_ancestors(
                            $object->term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    )
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );

                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error( $ancestor )
                    ) {
                        $parents[] =
                            wp_strip_all_tags(
                                $ancestor->name
                            );
                    }
                }
            }

            $taxonomy_object =
                get_taxonomy(
                    $taxonomy
                );

            $label =
                $taxonomy_object
                && ! empty(
                    $taxonomy_object
                        ->labels
                        ->singular_name
                )
                    ? wp_strip_all_tags(
                        $taxonomy_object
                            ->labels
                            ->singular_name
                    )
                    : '';

            $full =
                implode(
                    (string) $atts['separator'],
                    array_merge(
                        $parents,
                        [ $current ]
                    )
                );

            switch ( $mode ) {

                case 'parents':

                    $output =
                        implode(
                            (string) $atts['separator'],
                            $parents
                        );

                    break;

                case 'full':

                    $output =
                        $full;

                    break;

                case 'label_current':

                    $output =
                        $label
                            ? $label
                                . (string) $atts['label_separator']
                                . $current
                            : $current;

                    break;

                case 'label_full':

                    $output =
                        $label
                            ? $label
                                . (string) $atts['label_separator']
                                . $full
                            : $full;

                    break;

                default:

                    $output =
                        $current;
            }

        /**
         * ====================================================
         * TAXONOMY BASE ARCHIVE
         * ====================================================
         */
        } else {

            $taxonomy_object =
                tfsc_text_taxonomy_archive_object();

            if ( ! $taxonomy_object ) {
                return '';
            }

            switch ( $mode ) {

                case 'taxonomy_plural':

                    $output =
                        $taxonomy_object
                            ->labels
                            ->name
                        ?? $taxonomy_object->label
                        ?? '';

                    break;

                case 'taxonomy':
                default:

                    $output =
                        $taxonomy_object
                            ->labels
                            ->singular_name
                        ?? $taxonomy_object->label
                        ?? '';
            }

            $output =
                wp_strip_all_tags(
                    (string) $output
                );
        }

        if ( '' === $output ) {
            return '';
        }

        $output =
            tfsc_text_case(
                $output,
                $atts['case']
            );

        return
            (string) $atts['before']
            . $output
            . (string) $atts['after'];
    }
);


/**
 * ============================================================
 * 7. [tfsc_pods]
 * ============================================================
 */

add_shortcode(
    'tfsc_pods',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'field'     => '',
                'before'    => '',
                'after'     => '',
                'separator' => ', ',
                'case'      => 'normal',
            ],
            $atts,
            'tfsc_pods'
        );

        $field =
            sanitize_key(
                $atts['field']
            );

        if ( ! $field ) {
            return '';
        }

        $pod =
            tfsc_text_context_pod();

        if ( ! $pod ) {
            return '';
        }

        $value =
            $pod->field(
                $field
            );

        if (
            null === $value ||
            false === $value ||
            '' === $value
        ) {
            return '';
        }

        /**
         * Normaal tekstveld.
         */
        if (
            ! is_array( $value ) &&
            ! is_object( $value )
        ) {

            $output =
                wp_strip_all_tags(
                    (string) $value
                );

        } else {

            /**
             * Eén relationship normaliseren.
             */
            if (
                is_object( $value ) ||
                (
                    is_array( $value ) &&
                    (
                        isset( $value['name'] ) ||
                        isset( $value['post_title'] ) ||
                        isset( $value['title'] )
                    )
                )
            ) {
                $value = [ $value ];
            }

            $names = [];

            foreach (
                (array) $value
                as $relation
            ) {

                if ( is_array( $relation ) ) {

                    $name =
                        $relation['name']
                        ?? $relation['post_title']
                        ?? $relation['title']
                        ?? '';

                } elseif ( is_object( $relation ) ) {

                    $name =
                        $relation->name
                        ?? $relation->post_title
                        ?? $relation->title
                        ?? '';

                } else {

                    $name = '';
                }

                $name =
                    wp_strip_all_tags(
                        (string) $name
                    );

                if ( '' !== $name ) {
                    $names[] = $name;
                }
            }

            $output =
                implode(
                    (string) $atts['separator'],
                    array_values(
                        array_unique(
                            $names
                        )
                    )
                );
        }

        if ( '' === $output ) {
            return '';
        }

        $output =
            tfsc_text_case(
                $output,
                $atts['case']
            );

        return
            (string) $atts['before']
            . $output
            . (string) $atts['after'];
    }
);

/**
 * TFSC - Base Archive → Vacancy Terms via Relationship Field
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Taxonomy base archive
 * → archive settings relationship field
 * → Pods fielddefinitie bepaalt target vacature-taxonomy
 * → optionele geselecteerde terms beperken de lijst
 * → alleen terms tonen die OPEN vacatures hebben
 *
 *
 * VELDNAAM
 * ============================================================
 *
 * archive_{context}_{taxonomy}_relationship
 *
 * Voorbeeld:
 *
 * huidig archive:
 * beroep_functienaam
 *
 * settings field:
 * archive_beroep_functienaam_relationship
 *
 * relationship field wijst in Pods naar taxonomy:
 * functienaam
 *
 *
 * QUERY IDS
 * ============================================================
 *
 * base_vacancy_terms_level_0
 * base_vacancy_terms_level_1
 * base_vacancy_terms_level_2
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_basevac_v3_vacancy_post_type() {
    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}

function tfsc_basevac_v3_status_taxonomy() {
    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}

function tfsc_basevac_v3_open_status() {
    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}

function tfsc_basevac_v3_settings_pod() {
    return 'pods_archief_instellingen';
}


/**
 * ============================================================
 * 2. HUIDIGE BASE TAXONOMY
 * ============================================================
 */

function tfsc_basevac_v3_base_taxonomy() {

    if (
        ! function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {
        return '';
    }

    $taxonomy =
        tfsc_get_current_taxonomy_archive();

    if ( $taxonomy instanceof WP_Taxonomy ) {
        $taxonomy = $taxonomy->name;
    }

    return sanitize_key(
        (string) $taxonomy
    );
}


/**
 * ============================================================
 * 3. TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functienaam
 * → functienaam
 */

function tfsc_basevac_v3_normalize_taxonomy(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );

    foreach (
        [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ]
        as $prefix
    ) {

        if (
            0 === strpos(
                $taxonomy,
                $prefix
            )
        ) {
            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen( $prefix )
                )
            );
        }
    }

    return $taxonomy;
}


/**
 * ============================================================
 * 4. RELATIONSHIP FIELD NAME
 * ============================================================
 *
 * archive_beroep_functienaam_relationship
 */

function tfsc_basevac_v3_relationship_field_name(
    $context = 'beroep'
) {

    $taxonomy =
        tfsc_basevac_v3_normalize_taxonomy(
            tfsc_basevac_v3_base_taxonomy()
        );

    if ( ! $taxonomy ) {
        return '';
    }

    return sanitize_key(
        'archive_'
        . sanitize_key( $context )
        . '_'
        . $taxonomy
        . '_relationship'
    );
}


/**
 * ============================================================
 * 5. SETTINGS POD
 * ============================================================
 */

function tfsc_basevac_v3_settings_object() {

    static $pod = null;

    if ( null !== $pod ) {
        return $pod;
    }

    if ( ! function_exists( 'pods' ) ) {
        return $pod = false;
    }

    $pod =
        pods(
            tfsc_basevac_v3_settings_pod()
        );

    return $pod ?: false;
}


/**
 * ============================================================
 * 6. TARGET TAXONOMY UIT PODS FIELDDEFINITIE
 * ============================================================
 *
 * De inhoud van het relationshipveld is NIET leidend.
 *
 * De Pods fielddefinitie bepaalt naar welke taxonomy
 * het relationshipveld verwijst.
 */

function tfsc_basevac_v3_target_taxonomy(
    $context = 'beroep'
) {

    static $cache = [];

    $field_name =
        tfsc_basevac_v3_relationship_field_name(
            $context
        );

    if ( ! $field_name ) {
        return '';
    }

    if ( isset( $cache[ $field_name ] ) ) {
        return $cache[ $field_name ];
    }

    $pod =
        tfsc_basevac_v3_settings_object();

    if ( ! $pod ) {
        return $cache[ $field_name ] = '';
    }

    $fields =
        $pod->fields();

    if (
        ! is_array( $fields ) ||
        empty( $fields[ $field_name ] )
    ) {
        return $cache[ $field_name ] = '';
    }

    $field =
        $fields[ $field_name ];

    /**
     * Pods relationship fields bevatten doorgaans:
     *
     * pick_object = taxonomy
     * pick_val    = functienaam
     */
    $pick_object =
        sanitize_key(
            $field['pick_object']
            ?? ''
        );

    $pick_val =
        sanitize_key(
            $field['pick_val']
            ?? ''
        );

    if (
        'taxonomy' === $pick_object &&
        $pick_val &&
        taxonomy_exists( $pick_val )
    ) {
        return $cache[ $field_name ] =
            $pick_val;
    }

    /**
     * Extra fallback voor afwijkende Pods arrays.
     */
    foreach (
        [
            'taxonomy',
            'pick_val',
            'object',
            'name',
        ]
        as $key
    ) {

        $candidate =
            sanitize_key(
                $field[ $key ]
                ?? ''
            );

        if (
            $candidate &&
            taxonomy_exists( $candidate )
        ) {
            return $cache[ $field_name ] =
                $candidate;
        }
    }

    return $cache[ $field_name ] = '';
}


/**
 * ============================================================
 * 7. GESELECTEERDE RELATIONSHIP TERMS
 * ============================================================
 *
 * Relationship leeg:
 * → geen beperking
 *
 * Relationship gevuld:
 * → alleen geselecteerde terms meenemen
 */

function tfsc_basevac_v3_selected_term_ids(
    $taxonomy,
    $context = 'beroep'
) {

    $pod =
        tfsc_basevac_v3_settings_object();

    $field_name =
        tfsc_basevac_v3_relationship_field_name(
            $context
        );

    if (
        ! $pod ||
        ! $field_name ||
        ! $taxonomy
    ) {
        return [];
    }

    $value =
        $pod->field(
            $field_name
        );

    if ( empty( $value ) ) {
        return [];
    }

    if (
        is_numeric( $value ) ||
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    $ids = [];

    foreach (
        (array) $value
        as $relation
    ) {

        $term_id = 0;
        $rel_taxonomy = '';

        if ( is_array( $relation ) ) {

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

            $rel_taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

        } elseif ( is_object( $relation ) ) {

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

            $rel_taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

        } elseif ( is_numeric( $relation ) ) {

            $term_id =
                (int) $relation;
        }

        if (
            $rel_taxonomy &&
            $rel_taxonomy !== $taxonomy
        ) {
            continue;
        }

        if ( ! $term_id ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            $ids[] =
                $term_id;
        }
    }

    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 8. OPEN VACATURE IDS
 * ============================================================
 */

function tfsc_basevac_v3_open_vacancy_ids() {

    static $ids = null;

    if ( null !== $ids ) {
        return $ids;
    }

    $tax_query = [];

    $status_taxonomy =
        tfsc_basevac_v3_status_taxonomy();

    if (
        taxonomy_exists(
            $status_taxonomy
        )
    ) {
        $tax_query[] = [
            'taxonomy'         => $status_taxonomy,
            'field'            => 'slug',
            'terms'            => [
                tfsc_basevac_v3_open_status(),
            ],
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    $ids = get_posts( [
        'post_type'      =>
            tfsc_basevac_v3_vacancy_post_type(),

        'post_status'    =>
            'publish',

        'posts_per_page' =>
            -1,

        'fields'         =>
            'ids',

        'no_found_rows'  =>
            true,

        'tax_query'      =>
            $tax_query,
    ] );

    return $ids =
        array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );
}


/**
 * ============================================================
 * 9. TERMS UIT OPEN VACATURES
 * ============================================================
 */

function tfsc_basevac_v3_available_term_ids(
    $taxonomy
) {

    $vacancy_ids =
        tfsc_basevac_v3_open_vacancy_ids();

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }

    $ids =
        wp_get_object_terms(
            $vacancy_ids,
            $taxonomy,
            [
                'fields' => 'ids',
            ]
        );

    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }

    $ids =
        array_map(
            'intval',
            $ids
        );

    /**
     * Ancestors meenemen zodat levels correct werken.
     */
    if (
        is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        foreach (
            $ids
            as $term_id
        ) {

            $ids =
                array_merge(
                    $ids,
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );
        }
    }

    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 10. OPTIONELE SETTINGS SELECTIE TOEPASSEN
 * ============================================================
 */

function tfsc_basevac_v3_term_ids(
    $taxonomy,
    $context = 'beroep'
) {

    $available =
        tfsc_basevac_v3_available_term_ids(
            $taxonomy
        );

    if ( ! $available ) {
        return [];
    }

    $selected =
        tfsc_basevac_v3_selected_term_ids(
            $taxonomy,
            $context
        );

    /**
     * Niets geselecteerd:
     * alle beschikbare terms tonen.
     */
    if ( ! $selected ) {
        return $available;
    }

    /**
     * Wel geselecteerd:
     * alleen geselecteerde terms die ook vacatures hebben.
     */
    return array_values(
        array_intersect(
            $available,
            $selected
        )
    );
}


/**
 * ============================================================
 * 11. EXACT LEVEL
 * ============================================================
 */

function tfsc_basevac_v3_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( ! $ids ) {
        return [];
    }

    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {
        return 0 === (int) $level
            ? $ids
            : [];
    }

    return array_values(
        array_filter(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            ),
            function( $term_id ) use (
                $taxonomy,
                $level
            ) {

                return count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === (int) $level;
            }
        )
    );
}


/**
 * ============================================================
 * 12. QUERY ID
 * ============================================================
 */

function tfsc_basevac_v3_parse_query_id(
    $query_id
) {

    if (
        ! preg_match(
            '/^base_vacancy_terms_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }

    return (int) $matches[1];
}


/**
 * ============================================================
 * 13. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Elementor Source wordt volledig door deze snippet bepaald.
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings['post_taxonomy_term_taxonomy_id']
            ??
            '';

        $level =
            tfsc_basevac_v3_parse_query_id(
                $query_id
            );

        if ( false === $level ) {
            return $args;
        }

        $taxonomy =
            tfsc_basevac_v3_target_taxonomy(
                'beroep'
            );

        if (
            ! $taxonomy ||
            $taxonomy ===
            tfsc_basevac_v3_status_taxonomy()
        ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $term_ids =
            tfsc_basevac_v3_term_ids(
                $taxonomy,
                'beroep'
            );

        $term_ids =
            tfsc_basevac_v3_filter_level(
                $term_ids,
                $taxonomy,
                $level
            );

        if ( ! $term_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        unset(
            $args['term_taxonomy_id']
        );

        $args['taxonomy']     = $taxonomy;
        $args['include']      = $term_ids;
        $args['hide_empty']   = false;
        $args['hierarchical'] = false;

        /**
         * Marker voor alfabetische sortering.
         */
        $args['tfsc_basevac_v3'] =
            1;

        return $args;
    },
    35,
    3
);


/**
 * ============================================================
 * 14. ALFABETISCHE SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty(
                $args['tfsc_basevac_v3']
            ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }

        usort(
            $terms,
            function( $a, $b ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }

                return strnatcasecmp(
                    remove_accents(
                        $a->name
                    ),
                    remove_accents(
                        $b->name
                    )
                );
            }
        );

        return $terms;
    },
    9999,
    4
);

/**
 * TFSC - Query Show More
 *
 * Elementor widget class:
 * tfsc_query_show-more
 *
 * Custom attribute:
 * data_visible-items|8
 *
 * Werking:
 * - start met data_visible-items
 * - "Meer tonen" toont telkens 20 extra items
 * - als alles zichtbaar is wordt knop "Minder tonen"
 * - "Minder tonen" reset naar originele hoeveelheid
 *   en scrollt terug naar bovenkant van de widget
 */

add_action(
    'wp_footer',
    function() {

        if ( is_admin() ) {
            return;
        }

        ?>
        <script>
        (function () {

            const STEP = 20;

            function init(scope) {

                const root = scope || document;
                const widgets = [];

                if (
                    root.classList?.contains(
                        'tfsc_query_show-more'
                    )
                ) {
                    widgets.push(root);
                }

                if (root.querySelectorAll) {
                    widgets.push(
                        ...root.querySelectorAll(
                            '.tfsc_query_show-more'
                        )
                    );
                }

                widgets.forEach(
                    function (widget) {

                        widget
                            .querySelector(
                                '.tfsc-query-show-more__wrapper'
                            )
                            ?.remove();

                        const initial =
                            parseInt(
                                widget.getAttribute(
                                    'data_visible-items'
                                ),
                                10
                            ) || 8;

                        const loop =
                            widget.querySelector(
                                ':scope > .elementor-widget-container .elementor-loop-container'
                            );

                        if (!loop) {
                            return;
                        }

                        const items =
                            Array.from(
                                loop.querySelectorAll(
                                    ':scope > .e-loop-item'
                                )
                            );

                        if (!items.length) {
                            return;
                        }

                        let visibleCount =
                            Math.min(
                                initial,
                                items.length
                            );

                        function renderItems() {

                            items.forEach(
                                (item, index) => {
                                    item.style.display =
                                        index < visibleCount
                                            ? ''
                                            : 'none';
                                }
                            );
                        }

                        renderItems();

                        if (
                            items.length <= initial
                        ) {
                            return;
                        }

                        const wrapper =
                            document.createElement('div');

                        wrapper.className =
                            'tfsc-query-show-more__wrapper';

                        wrapper.innerHTML = `
                            <button
                                type="button"
                                class="tfsc-query-show-more__button"
                                aria-expanded="false"
                            >
                                <span class="tfsc-query-show-more__label">
                                    Meer
                                </span>

                                <span
                                    class="tfsc-query-show-more__icon"
                                    aria-hidden="true"
                                ></span>
                            </button>
                        `;

                        loop.insertAdjacentElement(
                            'afterend',
                            wrapper
                        );

                        const button =
                            wrapper.querySelector('button');

                        const label =
                            wrapper.querySelector(
                                '.tfsc-query-show-more__label'
                            );

                        button.addEventListener(
                            'click',
                            function () {

                                const allVisible =
                                    visibleCount >=
                                    items.length;

                                /**
                                 * Minder tonen:
                                 * terug naar startaantal.
                                 */
                                if (allVisible) {

                                    visibleCount =
                                        Math.min(
                                            initial,
                                            items.length
                                        );

                                    renderItems();

                                    button.setAttribute(
                                        'aria-expanded',
                                        'false'
                                    );

                                    button.classList.remove(
                                        'tfsc-query-show-more__button--expanded'
                                    );

                                    label.textContent =
                                        'Meer';

                                    widget.scrollIntoView({
                                        behavior: 'smooth',
                                        block: 'start',
                                    });

                                    return;
                                }

                                /**
                                 * Meer tonen:
                                 * telkens 20 extra.
                                 */
                                visibleCount =
                                    Math.min(
                                        visibleCount + STEP,
                                        items.length
                                    );

                                renderItems();

                                const nowAllVisible =
                                    visibleCount >=
                                    items.length;

                                button.setAttribute(
                                    'aria-expanded',
                                    String(nowAllVisible)
                                );

                                button.classList.toggle(
                                    'tfsc-query-show-more__button--expanded',
                                    nowAllVisible
                                );

                                label.textContent =
                                    nowAllVisible
                                        ? 'Minder'
                                        : 'Meer';
                            }
                        );
                    }
                );
            }


            document.addEventListener(
                'DOMContentLoaded',
                () => init(document)
            );


            window.addEventListener(
                'elementor/frontend/init',
                function () {

                    if (
                        typeof elementorFrontend ===
                        'undefined'
                    ) {
                        return;
                    }

                    elementorFrontend.hooks.addAction(
                        'frontend/element_ready/global',
                        function (scope) {

                            init(
                                scope?.[0] || scope
                            );
                        }
                    );
                }
            );


            new MutationObserver(
                mutations => {

                    mutations.forEach(
                        mutation => {

                            mutation.addedNodes.forEach(
                                node => {

                                    if (
                                        node.nodeType === 1
                                    ) {
                                        init(node);
                                    }
                                }
                            );
                        }
                    );
                }
            ).observe(
                document.documentElement,
                {
                    childList: true,
                    subtree: true,
                }
            );

        })();
        </script>

        <style>
        .tfsc_query_show-more .tfsc-query-show-more__wrapper {
            width: 100%;
        }

        .tfsc_query_show-more .tfsc-query-show-more__button {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            cursor: pointer;
        }

        .tfsc_query_show-more .tfsc-query-show-more__icon {
            display: inline-block;
            width: 8px;
            height: 8px;
            border-right: 2px solid currentColor;
            border-bottom: 2px solid currentColor;
            transform: rotate(45deg) translateY(-2px);
            transition: transform 0.2s ease;
        }

        .tfsc_query_show-more
        .tfsc-query-show-more__button--expanded
        .tfsc-query-show-more__icon {
            transform: rotate(225deg) translateY(-2px);
        }
        </style>
        <?php
    },
    100
);

/**
 * TFSC - Archive Settings Fields
 *
 * Leest generieke velden uit:
 *
 * pods_archief_instellingen
 *
 * ============================================================
 * TAXONOMY BASE ARCHIVE
 * ============================================================
 *
 * archive_{context}_{taxonomy}_{field}
 *
 * Voorbeeld:
 *
 * beroep_functienaam
 * + context beroep
 * + field description
 *
 * → archive_beroep_functienaam_description
 *
 *
 * ============================================================
 * CPT ARCHIVE
 * ============================================================
 *
 * archive_cpt_{context}_{field}
 *
 * Voorbeeld:
 *
 * CPT archive beroepengids
 * + context beroep
 * + field description
 *
 * → archive_cpt_beroep_description
 *
 *
 * ELEMENTOR
 * ============================================================
 *
 * Dynamic Tag:
 * TFSC Archive Settings Field
 *
 * Context:
 * beroep
 *
 * Field:
 * description
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_archive_settings_pod_name() {
    return 'pods_archief_instellingen';
}


/**
 * ============================================================
 * 2. TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functienaam
 * → functienaam
 */

function tfsc_archive_settings_normalize_taxonomy(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );

    foreach (
        [
            'beroep_',
            'beroep-',
            'beroepengids_',
            'beroepengids-',
        ]
        as $prefix
    ) {

        if (
            0 === strpos(
                $taxonomy,
                $prefix
            )
        ) {
            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen( $prefix )
                )
            );
        }
    }

    return $taxonomy;
}


/**
 * ============================================================
 * 3. HUIDIGE TAXONOMY BASE
 * ============================================================
 */

function tfsc_archive_settings_taxonomy() {

    if (
        ! function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {
        return '';
    }

    $taxonomy =
        tfsc_get_current_taxonomy_archive();

    if (
        is_object( $taxonomy ) &&
        ! empty( $taxonomy->name )
    ) {
        $taxonomy =
            $taxonomy->name;
    }

    if ( ! $taxonomy ) {
        return '';
    }

    return tfsc_archive_settings_normalize_taxonomy(
        $taxonomy
    );
}


/**
 * ============================================================
 * 4. CPT ARCHIVE CONTEXT
 * ============================================================
 *
 * Geeft alleen true terug op een echt post type archive.
 */

function tfsc_archive_settings_is_cpt_archive() {

    return is_post_type_archive();
}


/**
 * ============================================================
 * 5. VELDNAAM OPBOUWEN
 * ============================================================
 *
 * Taxonomy base:
 * archive_{context}_{taxonomy}_{field}
 *
 * CPT archive:
 * archive_cpt_{context}_{field}
 */

function tfsc_archive_settings_field_name(
    $context,
    $field
) {

    $context =
        sanitize_key(
            $context
        );

    $field =
        sanitize_key(
            $field
        );

    if (
        ! $context ||
        ! $field
    ) {
        return '';
    }

    /**
     * Taxonomy base archive heeft voorrang.
     */
    $taxonomy =
        tfsc_archive_settings_taxonomy();

    if ( $taxonomy ) {

        return sanitize_key(
            'archive_'
            . $context
            . '_'
            . $taxonomy
            . '_'
            . $field
        );
    }

    /**
     * CPT archive.
     */
    if (
        tfsc_archive_settings_is_cpt_archive()
    ) {

        return sanitize_key(
            'archive_cpt_'
            . $context
            . '_'
            . $field
        );
    }

    return '';
}


/**
 * ============================================================
 * 6. PODS SETTINGS VALUE
 * ============================================================
 */

function tfsc_archive_settings_value(
    $context,
    $field
) {

    if ( ! function_exists( 'pods' ) ) {
        return '';
    }

    $field_name =
        tfsc_archive_settings_field_name(
            $context,
            $field
        );

    if ( ! $field_name ) {
        return '';
    }

    $pod =
        pods(
            tfsc_archive_settings_pod_name()
        );

    if ( ! $pod ) {
        return '';
    }

    $value =
        $pod->field(
            $field_name
        );

    return (
        null === $value ||
        false === $value
    )
        ? ''
        : $value;
}


/**
 * ============================================================
 * 7. SHORTCODE
 * ============================================================
 *
 * [tfsc_archive_field
 *     context="beroep"
 *     field="description"]
 */

add_shortcode(
    'tfsc_archive_field',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'context' => 'beroep',
                'field'   => '',
            ],
