(function () {

    const loopSelector = '.tfsc-ajax-loop';

    document.addEventListener('click', function (event) {

        const paginationLink = event.target.closest(
            loopSelector + ' .elementor-pagination a'
        );

        if (!paginationLink) {
            return;
        }

        const loop = paginationLink.closest(loopSelector);

        if (!loop) {
            return;
        }

        const widgetId = loop.getAttribute('data-id');

        if (!widgetId) {
            return;
        }

        const observer = new MutationObserver(function () {

            clearTimeout(observer.tfscTimer);

            observer.tfscTimer = setTimeout(function () {

                observer.disconnect();

                const refreshedLoop = document.querySelector(
                    loopSelector + '[data-id="' + widgetId + '"]'
                );

                if (!refreshedLoop) {
                    return;
                }

                const offset = 20;

                const top =
                    refreshedLoop.getBoundingClientRect().top +
                    window.scrollY -
                    offset;

                window.scrollTo({
                    top: top,
                    behavior: 'smooth'
                });

            }, 150);
        });

        observer.observe(loop, {
            childList: true,
            subtree: true
        });
    });

})();

/**
 * TFSC - Combo Archive SEO
 *
 * Vereist:
 * - TFSC combo archive snippet
 * - Rank Math SEO
 *
 * Regelt ALLEEN virtuele combo archives:
 * - SEO title
 * - Meta description
 * - Canonical
 * - Robots
 *
 * Taxonomy-agnostisch:
 * nieuwe toegestane taxonomies worden automatisch meegenomen.
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {
    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}


/**
 * ============================================================
 * GELDIG COMBO SEO ARCHIVE?
 * ============================================================
 */

function tfsc_combo_seo_is_active() {

    if (
        ! function_exists( 'tfsc_is_combo_archive' ) ||
        ! function_exists( 'tfsc_get_combo_archive' )
    ) {
        return false;
    }

    return (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    );
}


/**
 * ============================================================
 * COMBO TERM NAMEN IN URL-VOLGORDE
 * ============================================================
 */

function tfsc_combo_seo_get_items() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return [];
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    $items = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $name =
            trim(
                wp_strip_all_tags(
                    $item['term']->name
                )
            );

        if ( '' === $name ) {
            continue;
        }

        $items[] = [
            'taxonomy' =>
                $item['taxonomy'],

            'term_id' =>
                (int) $item['term']->term_id,

            'slug' =>
                $item['term']->slug,

            'name' =>
                $name,
        ];
    }

    return $items;
}


/**
 * ============================================================
 * SEO TITLE OPBOUWEN
 * ============================================================
 *
 * Voorbeelden:
 *
 * Field Service Engineer vacatures
 *
 * Field Service Engineer vacatures Elektrotechniek
 *
 * Field Service Engineer vacatures Elektrotechniek Noord-Brabant
 *
 * Zonder functienaam:
 *
 * Vacatures Elektrotechniek Noord-Brabant
 *
 * Alleen functienaam wordt speciaal behandeld.
 * Alle andere taxonomies worden automatisch meegenomen.
 */

function tfsc_combo_seo_build_title() {

    $items =
        tfsc_combo_seo_get_items();

    if ( ! $items ) {
        return '';
    }

    $function_names = [];
    $other_names    = [];

    foreach ( $items as $item ) {

        /**
         * Functienaam krijgt speciale plaatsing.
         */
        if (
            'functienaam'
            === $item['taxonomy']
        ) {

            if (
                ! in_array(
                    $item['name'],
                    $function_names,
                    true
                )
            ) {
                $function_names[] =
                    $item['name'];
            }

            continue;
        }

        /**
         * Alle overige taxonomies generiek.
         */
        if (
            ! in_array(
                $item['name'],
                $other_names,
                true
            )
        ) {
            $other_names[] =
                $item['name'];
        }
    }


    /**
     * Functienaam aanwezig.
     */
    if ( $function_names ) {

        if (
            1 === count(
                $function_names
            )
        ) {

            $title =
                $function_names[0]
                .
                ' vacatures';

        } else {

            $title =
                implode(
                    ' ',
                    $function_names
                )
                .
                ' vacatures';
        }

        if ( $other_names ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $other_names
                );
        }

        return trim(
            $title
        );
    }


    /**
     * Geen functienaam.
     */
    if ( ! $other_names ) {
        return '';
    }

    return trim(
        'Vacatures '
        .
        implode(
            ' ',
            $other_names
        )
    );
}


/**
 * ============================================================
 * META DESCRIPTION
 * ============================================================
 *
 * Voorbeeld:
 *
 * Field Service Engineer vacatures Elektrotechniek
 * Noord-Brabant bij The Field Service Company.
 */

function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();

    if ( '' === $title ) {
        return '';
    }

    return sprintf(
        '%s bij %s.',
        $title,
        TFSC_COMBO_SEO_BRAND
    );
}


/**
 * ============================================================
 * CANONICAL URL
 * ============================================================
 *
 * Canonical wordt opgebouwd vanuit de daadwerkelijk
 * geresolvde combo.
 *
 * Querystrings zoals Search & Filter parameters
 * komen daardoor nooit in de canonical terecht.
 */

function tfsc_combo_seo_build_canonical() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return '';
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return '';
    }

    $segments = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['path'] ) ||
            ! is_array( $item['path'] )
        ) {
            continue;
        }

        /**
         * Taxonomy.
         */
        $segments[] =
            sanitize_key(
                $item['taxonomy']
            );

        /**
         * Volledige term path.
         *
         * Hierdoor blijven ook hiërarchische
         * taxonomy paths correct.
         */
        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term
                instanceof WP_Term
            ) {
                continue;
            }

            $segments[] =
                $term->slug;
        }
    }

    if ( ! $segments ) {
        return '';
    }

    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );

    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


