/**
 * ============================================================
 * GELDIG COMBO SEO ARCHIVE?
 * ============================================================
 */

function tfsc_combo_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }

    if (
        ! function_exists( 'tfsc_is_combo_archive' ) ||
        ! function_exists( 'tfsc_get_combo_archive' )
    ) {
        return false;
    }

    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }

    return false !== tfsc_get_combo_archive();
}


/**
 * ============================================================
 * COMBO ITEMS
 * ============================================================
 *
 * Volgorde = bestaande combo-volgorde.
 * Nieuwe taxonomies worden automatisch meegenomen.
 */

function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];

    if ( $resolved ) {
        return $items;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return [];
    }

    $combo = tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $name =
            trim(
                wp_strip_all_tags(
                    $item['term']->name
                )
            );

        if ( '' === $name ) {
            continue;
        }

        $items[] = [
            'taxonomy' =>
                (string) $item['taxonomy'],

            'term_id' =>
                (int) $item['term']->term_id,

            'slug' =>
                (string) $item['term']->slug,

            'name' =>
                $name,
        ];
    }

    return $items;
}


/**
 * ============================================================
 * INDEXERINGSREGEL
 * ============================================================
 *
 * Centrale functie voor SEO én later de sitemap.
 *
 * Voorlopig:
 * iedere geldige combo mag indexeren.
 *
 * Later kunnen hier regels komen voor bijvoorbeeld:
 * - aantal taxonomies
 * - aantal resultaten
 * - specifieke combinaties
 * - handmatige uitzonderingen
 */

function tfsc_combo_should_index( $combo = null ) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return false;
        }

        $combo = tfsc_get_combo_archive();
    }

    if (
        ! is_array( $combo ) ||
        ! $combo
    ) {
        return false;
    }

    return true;
}


