/**
 * TFSC - Combo Vacancy Sitemap
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - TFSC - Combo Archive SEO
 * - Rank Math SEO
 *
 * Maakt:
 * /combo-vacatures-sitemap.xml
 *
 * Wordt automatisch toegevoegd aan:
 * /sitemap_index.xml
 *
 * FASE 1:
 * - taxonomy-agnostisch
 * - alleen geldige toegestane vacature-taxonomies
 * - alleen open + gepubliceerde vacatures
 * - alleen combo's die daadwerkelijk bij minimaal 1 vacature voorkomen
 * - exact 2 verschillende taxonomies per combo
 *
 * Performance:
 * - combinaties worden NIET op normale paginaweergaven berekend
 * - lijst wordt in een transient gecachet
 * - Rank Math sitemap caching blijft gewoon actief
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

/**
 * Minimum aantal verschillende taxonomies
 * in een sitemap-combinatie.
 */
if ( ! defined( 'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS' ) ) {
    define(
        'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS',
        2
    );
}


/**
 * Maximum aantal verschillende taxonomies
 * in een sitemap-combinatie.
 *
 * Fase 1 = 2.
 *
 * Later bijvoorbeeld naar 3 voor:
 *
 * functienaam
 * + kennisgebied
 * + locatie
 */
if ( ! defined( 'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS' ) ) {
    define(
        'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS',
        2
    );
}


/**
 * Eigen cache voor de gegenereerde URL-lijst.
 *
 * Rank Math heeft daarnaast zelf ook sitemap caching.
 */
if ( ! defined( 'TFSC_COMBO_SITEMAP_CACHE_KEY' ) ) {
    define(
        'TFSC_COMBO_SITEMAP_CACHE_KEY',
        'tfsc_combo_sitemap_links_v1'
    );
}


/**
 * Fallback levensduur van onze eigen cache.
 *
 * De cache wordt normaal al verwijderd wanneer
 * vacatures of relevante terms wijzigen.
 */
if ( ! defined( 'TFSC_COMBO_SITEMAP_CACHE_TTL' ) ) {
    define(
        'TFSC_COMBO_SITEMAP_CACHE_TTL',
        DAY_IN_SECONDS
    );
}


/**
 * ============================================================
 * BESCHIKBAARHEID CONTROLEREN
 * ============================================================
 */

function tfsc_combo_sitemap_is_available() {

    return (
        function_exists(
            'tfsc_get_allowed_combo_taxonomies'
        )
        &&
        function_exists(
            'tfsc_get_combo_taxonomy_match_method'
        )
        &&
        function_exists(
            'tfsc_combo_should_index'
        )
        &&
        defined(
            'TFSC_VACANCY_POST_TYPE'
        )
        &&
        defined(
            'TFSC_STATUS_TAXONOMY'
        )
        &&
        defined(
            'TFSC_OPEN_STATUS_SLUG'
        )
        &&
        defined(
            'TFSC_COMBO_BASE'
        )
    );
}


/**
 * ============================================================
 * TERM PATH OPBOUWEN
 * ============================================================
 *
 * Zet bijvoorbeeld:
 *
 * Noord-Brabant
 *
 * of bij een hiërarchische taxonomy:
 *
 * Nederland / Noord-Brabant
 *
 * om naar de volledige term-path die jouw bestaande
 * combo parser ook begrijpt.
 */

function tfsc_combo_sitemap_get_term_path(
    WP_Term $term
) {

    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );

    if ( ! $taxonomy ) {
        return [];
    }

    /**
     * Niet-hiërarchische taxonomy:
     * alleen de term zelf.
     */
    if ( ! $taxonomy->hierarchical ) {

        return [
            $term,
        ];
    }

    $path = [];

    $ancestor_ids =
        array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        );

    foreach ( $ancestor_ids as $ancestor_id ) {

        $ancestor =
            get_term(
                $ancestor_id,
                $term->taxonomy
            );

        if (
            $ancestor instanceof WP_Term &&
            ! is_wp_error( $ancestor )
        ) {
            $path[] = $ancestor;
        }
    }

    $path[] = $term;

    return $path;
}


/**
 * ============================================================
 * TERM NORMALISEREN NAAR COMBO ITEM
 * ============================================================
 *
 * Zelfde basisstructuur als tfsc_get_combo_archive().
 *
 * Daardoor kan tfsc_combo_should_index()
 * later dezelfde combo's beoordelen.
 */

function tfsc_combo_sitemap_make_item(
    WP_Term $term
) {

    return [
        'taxonomy' =>
            $term->taxonomy,

        'term' =>
            $term,

        'path' =>
            tfsc_combo_sitemap_get_term_path(
                $term
            ),
    ];
}


/**
 * ============================================================
 * URL VAN COMBO OPBOUWEN
 * ============================================================
 */

function tfsc_combo_sitemap_build_url(
    array $combo
) {

    if ( ! $combo ) {
        return '';
    }

    $segments = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['path'] ) ||
            ! is_array( $item['path'] )
        ) {
            return '';
        }

        $segments[] =
            sanitize_key(
                $item['taxonomy']
            );

        foreach ( $item['path'] as $term ) {

            if ( ! $term instanceof WP_Term ) {
                return '';
            }

            $segments[] =
                $term->slug;
        }
    }

    if ( ! $segments ) {
        return '';
    }

    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );

    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


/**
 * ============================================================
 * TERMSET VOOR ÉÉN VACATURE
 * ============================================================
 *
 * Geeft bijvoorbeeld:
 *
 * [
 *     'functienaam' => [
 *         WP_Term Field Service Engineer
 *     ],
 *
 *     'kennisgebied' => [
 *         WP_Term Elektrotechniek,
 *         WP_Term Mechanisch
 *     ],
 *
 *     'locatie' => [
 *         WP_Term Noord-Brabant
 *     ]
 * ]
 *
 * Voor hiërarchische OR-taxonomies worden ook ancestors
 * toegevoegd, omdat jouw vacaturequery children mag meenemen.
 */

function tfsc_combo_sitemap_get_post_dimensions(
    $post_id,
    array $taxonomies
) {

    $dimensions = [];

    foreach ( $taxonomies as $taxonomy ) {

        $terms =
            get_the_terms(
                $post_id,
                $taxonomy
            );

        if (
            ! is_array( $terms ) ||
            ! $terms
        ) {
            continue;
        }

        $taxonomy_object =
            get_taxonomy(
                $taxonomy
            );

        $match_method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );

        $collected = [];

        foreach ( $terms as $term ) {

            if ( ! $term instanceof WP_Term ) {
                continue;
            }

            $collected[
                $term->term_id
            ] = $term;


            /**
             * Bij OR-taxonomies met hiërarchie mag een
             * parent-archive een vacature vinden die alleen
             * aan een child gekoppeld is.
             *
             * Daarom voegen we ook de ancestors toe.
             *
             * Bij AND-taxonomies doen we dat bewust niet,
             * omdat jouw bestaande query daar
             * include_children = false gebruikt.
             */
            if (
                $taxonomy_object &&
                $taxonomy_object->hierarchical &&
                'AND' !== $match_method
            ) {

                $ancestor_ids =
                    get_ancestors(
                        $term->term_id,
                        $taxonomy,
                        'taxonomy'
                    );

                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );

                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error( $ancestor )
                    ) {
                        $collected[
                            $ancestor->term_id
                        ] = $ancestor;
                    }
                }
            }
        }

        if ( $collected ) {

            $dimensions[
                $taxonomy
            ] =
                array_values(
                    $collected
                );
        }
    }

    return $dimensions;
}


/**
 * ============================================================
 * TAXONOMY SUBSETS
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * functienaam
 * kennisgebied
 * locatie
 *
 * met size 2:
 *
 * functienaam + kennisgebied
 * functienaam + locatie
 * kennisgebied + locatie
 */

function tfsc_combo_sitemap_dimension_sets(
    array $dimensions,
    $size
) {

    $dimensions =
        array_values(
            $dimensions
        );

    $size =
        (int) $size;

    if (
        $size < 1 ||
        count( $dimensions ) < $size
    ) {
        return [];
    }

    if ( 1 === $size ) {

        return array_map(
            static function( $dimension ) {

                return [
                    $dimension,
                ];
            },
            $dimensions
        );
    }

    $result = [];

    $first =
        array_shift(
            $dimensions
        );

    /**
     * Sets mét eerste dimension.
     */
    foreach (
        tfsc_combo_sitemap_dimension_sets(
            $dimensions,
            $size - 1
        )
        as $subset
    ) {

        array_unshift(
            $subset,
            $first
        );

        $result[] =
            $subset;
    }

    /**
     * Sets zonder eerste dimension.
     */
    foreach (
        tfsc_combo_sitemap_dimension_sets(
            $dimensions,
            $size
        )
        as $subset
    ) {

        $result[] =
            $subset;
    }

    return $result;
}


/**
 * ============================================================
 * CARTESIAN PRODUCT VAN TERMS
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * functienaam:
 * - Field Service Engineer
 *
 * kennisgebied:
 * - Elektro
 * - Mechanisch
 *
 * wordt:
 *
 * FSE + Elektro
 * FSE + Mechanisch
 */

function tfsc_combo_sitemap_term_products(
    array $taxonomy_set,
    array $dimensions
) {

    $products = [
        [],
    ];

    foreach (
        $taxonomy_set
        as $taxonomy
    ) {

        if (
            empty(
                $dimensions[
                    $taxonomy
                ]
            )
        ) {
            return [];
        }

        $next = [];

        foreach (
            $products
            as $product
        ) {

            foreach (
                $dimensions[
                    $taxonomy
                ]
                as $term
            ) {

                if (
                    ! $term
                    instanceof WP_Term
                ) {
                    continue;
                }

                $new_product =
                    $product;

                $new_product[] =
                    tfsc_combo_sitemap_make_item(
                        $term
                    );

                $next[] =
                    $new_product;
            }
        }

        $products = $next;
    }

    return $products;
}


/**
 * ============================================================
 * ALLE INDEXWAARDIGE COMBO URLS GENEREREN
 * ============================================================
 *
 * DIT IS HET ZWARE DEEL.
 *
 * Wordt alleen aangeroepen wanneer Rank Math onze sitemap
 * nodig heeft, en daarna gecachet.
 */

function tfsc_combo_sitemap_generate_links() {

    if (
        ! tfsc_combo_sitemap_is_available()
    ) {
        return [];
    }


    /**
     * Eerst onze eigen cache proberen.
     */
    $cached =
        get_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY
        );

    if ( is_array( $cached ) ) {
        return $cached;
    }


    $taxonomies =
        tfsc_get_allowed_combo_taxonomies();

    if ( ! $taxonomies ) {
        return [];
    }


    /**
     * Alleen open + gepubliceerde vacatures.
     */
    $post_ids =
        get_posts(
            [
                'post_type' =>
                    TFSC_VACANCY_POST_TYPE,

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    -1,

                'fields' =>
                    'ids',

                'no_found_rows' =>
                    true,

                'orderby' =>
                    'ID',

                'order' =>
                    'ASC',

                'tax_query' => [
                    [
                        'taxonomy' =>
                            TFSC_STATUS_TAXONOMY,

                        'field' =>
                            'slug',

                        'terms' => [
                            TFSC_OPEN_STATUS_SLUG,
                        ],

                        'operator' =>
                            'IN',

                        'include_children' =>
                            false,
                    ],
                ],
            ]
        );


    if ( ! $post_ids ) {

        set_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            [],
            TFSC_COMBO_SITEMAP_CACHE_TTL
        );

        return [];
    }


    /**
     * URL als key gebruiken.
     *
     * Daardoor worden combo's die bij meerdere vacatures
     * voorkomen automatisch maar één keer opgenomen.
     */
    $links = [];


    foreach ( $post_ids as $post_id ) {

        $dimensions =
            tfsc_combo_sitemap_get_post_dimensions(
                $post_id,
                $taxonomies
            );

        if ( ! $dimensions ) {
            continue;
        }


        $taxonomy_names =
            array_keys(
                $dimensions
            );


        $min =
            max(
                2,
                (int)
                TFSC_COMBO_SITEMAP_MIN_DIMENSIONS
            );

        $max =
            min(
                count(
                    $taxonomy_names
                ),
                max(
                    $min,
                    (int)
                    TFSC_COMBO_SITEMAP_MAX_DIMENSIONS
                )
            );


        if ( $max < $min ) {
            continue;
        }


        for (
            $size = $min;
            $size <= $max;
            $size++
        ) {

            $dimension_sets =
                tfsc_combo_sitemap_dimension_sets(
                    $taxonomy_names,
                    $size
                );


            foreach (
                $dimension_sets
                as $taxonomy_set
            ) {

                $products =
                    tfsc_combo_sitemap_term_products(
                        $taxonomy_set,
                        $dimensions
                    );


                foreach (
                    $products
                    as $combo
                ) {

                    /**
                     * Dezelfde centrale indexregel als SEO.
                     */
                    if (
                        ! tfsc_combo_should_index(
                            $combo
                        )
                    ) {
                        continue;
                    }


                    $url =
                        tfsc_combo_sitemap_build_url(
                            $combo
                        );

                    if ( '' === $url ) {
                        continue;
                    }


                    $links[
                        $url
                    ] = [
                        'loc' =>
                            $url,
                    ];
                }
            }
        }
    }


    /**
     * Stabiele sitemap-volgorde.
     */
    ksort(
        $links,
        SORT_STRING
    );


    $links =
        array_values(
            $links
        );


    set_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY,
        $links,
        TFSC_COMBO_SITEMAP_CACHE_TTL
    );


    return $links;
}


/**
 * ============================================================
 * CACHE VERWIJDEREN
 * ============================================================
 */

function tfsc_combo_sitemap_flush_cache() {

    delete_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY
    );


    /**
     * Rank Math's eigen cache voor onze provider.
     */
    if (
        class_exists(
            '\RankMath\Sitemap\Cache'
        )
    ) {

        \RankMath\Sitemap\Cache::invalidate_storage(
            'combo-vacatures'
        );
    }
}


