/**
 * ============================================================
 * RANK MATH CUSTOM SITEMAP PROVIDER
 * ============================================================
 *
 * De provider wordt door Rank Math aangeroepen wanneer
 * de sitemap(index) wordt gegenereerd.
 *
 * Op normale pagina's wordt tfsc_combo_sitemap_generate_links()
 * hierdoor niet uitgevoerd.
 */

add_filter(
    'rank_math/sitemap/providers',
    function( $providers ) {


        if (
            ! interface_exists(
                '\RankMath\Sitemap\Providers\Provider'
            )
        ) {
            return $providers;
        }


        if (
            ! class_exists(
                'TFSC_Combo_Vacancy_Sitemap_Provider',
                false
            )
        ) {

            class TFSC_Combo_Vacancy_Sitemap_Provider
                implements
                \RankMath\Sitemap\Providers\Provider {


                /**
                 * ==============================================
                 * TYPE
                 * ==============================================
                 */

                public function handles_type(
                    $type
                ) {

                    return (
                        'combo-vacatures'
                        === $type
                    );
                }


                /**
                 * ==============================================
                 * SITEMAP INDEX
                 * ==============================================
                 */

                public function get_index_links(
                    $max_entries
                ) {

                    $links =
                        tfsc_combo_sitemap_generate_links();


                    $total =
                        count(
                            $links
                        );


                    if ( 0 === $total ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int) $max_entries
                        );


                    $pages =
                        max(
                            1,
                            (int) ceil(
                                $total
                                /
                                $max_entries
                            )
                        );


                    $index = [];


                    for (
                        $page = 1;
                        $page <= $pages;
                        $page++
                    ) {

                        $suffix =
                            $pages > 1
                                ? $page
                                : '';


                        $index[] = [
                            'loc' =>
                                \RankMath\Sitemap\Router::get_base_url(
                                    'combo-vacatures-sitemap'
                                    .
                                    $suffix
                                    .
                                    '.xml'
                                ),

                            'lastmod' =>
                                '',
                        ];
                    }


                    return $index;
                }


                /**
                 * ==============================================
                 * SITEMAP URLS
                 * ==============================================
                 */

                public function get_sitemap_links(
                    $type,
                    $max_entries,
                    $current_page
                ) {

                    if (
                        'combo-vacatures'
                        !== $type
                    ) {
                        return [];
                    }


                    $links =
                        tfsc_combo_sitemap_generate_links();


                    if ( ! $links ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int) $max_entries
                        );


                    $page =
                        max(
                            1,
                            (int) $current_page
                        );


                    $offset =
                        (
                            $page - 1
                        )
                        *
                        $max_entries;


                    return array_slice(
                        $links,
                        $offset,
                        $max_entries
                    );
                }
            }
        }


        $providers[
            'combo-vacatures'
        ] =
            new TFSC_Combo_Vacancy_Sitemap_Provider();


        return $providers;
    }
);

/**
 * TFSC - Combo Archive SEO
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * Regelt ALLEEN geldige virtuele combo archives:
 * - SEO title
 * - Meta description
 * - Canonical
 * - Robots
 * - Centrale indexeringslogica voor SEO + sitemap
 *
 * INDEXERINGSSTRATEGIE:
 *
 * Met functienaam:
 * → index, follow
 *
 * Zonder functienaam:
 * → noindex, follow
 *
 * De combo sitemap gebruikt dezelfde functie
 * tfsc_combo_should_index(), waardoor noindex-combo's
 * automatisch buiten de sitemap blijven.
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {
    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}


/**
 * ============================================================
 * GELDIG COMBO SEO ARCHIVE?
 * ============================================================
 */

function tfsc_combo_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }

    if (
        ! function_exists( 'tfsc_is_combo_archive' ) ||
        ! function_exists( 'tfsc_get_combo_archive' )
    ) {
        return false;
    }

    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }

    return false !== tfsc_get_combo_archive();
}


/**
 * ============================================================
 * COMBO ITEMS
 * ============================================================
 *
 * Volgorde = bestaande combo-volgorde.
 *
 * Nieuwe taxonomies worden automatisch meegenomen.
 */

function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];

    if ( $resolved ) {
        return $items;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return [];
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $name =
            trim(
                wp_strip_all_tags(
                    $item['term']->name
                )
            );

        if ( '' === $name ) {
            continue;
        }

        $items[] = [
            'taxonomy' =>
                (string) $item['taxonomy'],

            'term_id' =>
                (int) $item['term']->term_id,

            'slug' =>
                (string) $item['term']->slug,

            'name' =>
                $name,
        ];
    }

    return $items;
}


/**
 * ============================================================
 * HELPER: HEEFT COMBO EEN FUNCTIENAAM?
 * ============================================================
 */

function tfsc_combo_has_function_name(
    $combo = null
) {

    /**
     * Actuele frontend combo.
     */
    if ( null === $combo ) {

        $items =
            tfsc_combo_seo_get_items();

        foreach ( $items as $item ) {

            if (
                'functienaam'
                === $item['taxonomy']
            ) {
                return true;
            }
        }

        return false;
    }


    /**
     * Combo-object vanuit bijvoorbeeld sitemapgenerator.
     */
    if ( ! is_array( $combo ) ) {
        return false;
    }

    foreach ( $combo as $item ) {

        if (
            ! empty( $item['taxonomy'] ) &&
            'functienaam' === $item['taxonomy']
        ) {
            return true;
        }
    }

    return false;
}


/**
 * ============================================================
 * CENTRALE INDEXERINGSREGEL
 * ============================================================
 *
 * Deze functie is DE centrale waarheid voor:
 *
 * - Rank Math robots
 * - Combo sitemap
 *
 * Daardoor kan een noindex combo nooit per ongeluk
 * toch in de combo sitemap terechtkomen.
 *
 *
 * HUIDIGE STRATEGIE:
 *
 * functienaam aanwezig
 * → index
 *
 * functienaam ontbreekt
 * → noindex
 *
 *
 * Later kunnen we hier gecontroleerd uitzonderingen aan
 * toevoegen voor bijvoorbeeld sterke:
 *
 * Field Service vacatures Elektrotechniek
 *
 * zonder de sitemapcode te hoeven wijzigen.
 */

function tfsc_combo_should_index(
    $combo = null
) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return false;
        }

        $combo =
            tfsc_get_combo_archive();
    }

    if (
        ! is_array( $combo ) ||
        ! $combo
    ) {
        return false;
    }


    /**
     * Voorlopig alleen combo's met functienaam.
     */
    if (
        ! tfsc_combo_has_function_name(
            $combo
        )
    ) {
        return false;
    }


    /**
     * Extensibility hook.
     *
     * Hiermee kunnen we later extra regels toevoegen
     * zonder deze kernfunctie opnieuw op te bouwen.
     */
    return (bool) apply_filters(
        'tfsc/combo/should_index',
        true,
        $combo
    );
}


/**
 * ============================================================
 * SEO TITLE
 * ============================================================
 *
 * Met functienaam:
 *
 * Field Service Engineer vacatures
 *
 * Field Service Engineer vacatures Elektrotechniek
 *
 * Commissioning Engineer vacatures Noord-Brabant
 *
 *
 * Zonder functienaam:
 *
 * Field Service vacatures Elektrotechniek
 *
 * Field Service vacatures Noord-Brabant
 *
 * Deze pagina's krijgen voorlopig noindex,
 * maar houden wel een logische title voor gebruikers.
 */

function tfsc_combo_seo_build_title() {

    $items =
        tfsc_combo_seo_get_items();

    if ( ! $items ) {
        return '';
    }

    $function_names = [];
    $other_names    = [];

    foreach ( $items as $item ) {

        if (
            'functienaam'
            === $item['taxonomy']
        ) {

            if (
                ! in_array(
                    $item['name'],
                    $function_names,
                    true
                )
            ) {
                $function_names[] =
                    $item['name'];
            }

            continue;
        }


        if (
            ! in_array(
                $item['name'],
                $other_names,
                true
            )
        ) {
            $other_names[] =
                $item['name'];
        }
    }


    /**
     * Functienaam aanwezig.
     */
    if ( $function_names ) {

        $title =
            implode(
                ' ',
                $function_names
            )
            .
            ' vacatures';

        if ( $other_names ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $other_names
                );
        }

        return trim(
            $title
        );
    }


    /**
     * Geen functienaam.
     *
     * Bewust "Field Service vacatures"
     * in plaats van alleen "Vacatures".
     */
    if ( ! $other_names ) {
        return '';
    }

    return trim(
        'Field Service vacatures '
        .
        implode(
            ' ',
            $other_names
        )
    );
}


/**
 * ============================================================
 * META DESCRIPTION
 * ============================================================
 */

function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();

    if ( '' === $title ) {
        return '';
    }

    return sprintf(
        '%s bij %s.',
        $title,
        TFSC_COMBO_SEO_BRAND
    );
}


/**
 * ============================================================
 * CANONICAL
 * ============================================================
 *
 * Canonical wordt opgebouwd vanuit de geresolvde combo.
 *
 * Querystrings worden niet meegenomen.
 */

function tfsc_combo_seo_build_canonical() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return '';
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return '';
    }

    $segments = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['path'] ) ||
            ! is_array( $item['path'] )
        ) {
            continue;
        }

        $segments[] =
            sanitize_key(
                $item['taxonomy']
            );

        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term
                instanceof WP_Term
            ) {
                continue;
            }

            $segments[] =
                $term->slug;
        }
    }

    if ( ! $segments ) {
        return '';
    }

    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );

    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


/**
 * ============================================================
 * CENTRAAL SEO OBJECT
 * ============================================================
 *
 * Wordt maximaal één keer per request opgebouwd.
 */

function tfsc_get_combo_seo() {

    static $resolved = false;
    static $seo      = false;

    if ( $resolved ) {
