if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {
    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}


if ( ! defined( 'TFSC_COMBO_SEO_MIN_RESULTS_WITH_FUNCTION' ) ) {
    define(
        'TFSC_COMBO_SEO_MIN_RESULTS_WITH_FUNCTION',
        1
    );
}


if ( ! defined( 'TFSC_COMBO_SEO_MIN_RESULTS_WITHOUT_FUNCTION' ) ) {
    define(
        'TFSC_COMBO_SEO_MIN_RESULTS_WITHOUT_FUNCTION',
        3
    );
}


