 * ============================================================
 * CENTRAAL SEO OBJECT
 * ============================================================
 */

function tfsc_get_combo_seo() {

    static $resolved = false;
    static $seo      = false;


    if ( $resolved ) {
        return $seo;
    }


    $resolved = true;


    if ( ! tfsc_combo_seo_is_active() ) {
        return false;
    }


    $title =
        tfsc_combo_seo_build_title();


    if ( '' === $title ) {
        return false;
    }


    $index_status =
        tfsc_combo_get_index_status();


    $seo = [
        'title' =>
            $title,

        'description' =>
            tfsc_combo_seo_build_description(),

        'canonical' =>
            tfsc_combo_seo_build_canonical(),

        'index' =>
            ! empty(
                $index_status['index']
            ),

        'index_reason' =>
            $index_status['reason'],

        'results' =>
            $index_status['results'],

        'taxonomies' =>
            $index_status['taxonomies'],
    ];


    return $seo;
}


