/**
 * ============================================================
 * TAXONOMIES IN COMBO TELLEN
 * ============================================================
 *
 * Twee terms binnen dezelfde taxonomy tellen dus als
 * één taxonomy.
 *
 * Bijvoorbeeld:
 *
 * functienaam = Field Service Engineer
 * kennisgebied = Elektrotechniek
 * kennisgebied = Mechanisch
 * locatie = Noord-Brabant
 *
 * = 3 verschillende taxonomies.
 */

function tfsc_combo_count_taxonomies(
    $combo = null
) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return 0;
        }

        $combo =
            tfsc_get_combo_archive();
    }

    if ( ! is_array( $combo ) ) {
        return 0;
    }

    $taxonomies = [];

    foreach ( $combo as $item ) {

        if ( empty( $item['taxonomy'] ) ) {
            continue;
        }

        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );

        if ( '' === $taxonomy ) {
            continue;
        }

        $taxonomies[
            $taxonomy
        ] = true;
    }

    return count(
        $taxonomies
    );
}


/**
 * ============================================================
 * HEEFT COMBO FUNCTIENAAM?
 * ============================================================
 */

function tfsc_combo_has_function_name(
    $combo = null
) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return false;
        }

        $combo =
            tfsc_get_combo_archive();
    }

    if ( ! is_array( $combo ) ) {
        return false;
    }

    foreach ( $combo as $item ) {

        if (
            ! empty( $item['taxonomy'] ) &&
            'functienaam'
            === $item['taxonomy']
        ) {
            return true;
        }
    }

    return false;
}


/**
 * ============================================================
 * RESULTAAT-AANTAL HUIDIGE COMBO
 * ============================================================
 *
 * De hoofdquery heeft de vacaturequery al uitgevoerd.
 * We voeren op de frontend dus GEEN tweede WP_Query uit.
 */

function tfsc_combo_get_current_result_count() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return 0;
    }

    global $wp_query;

    if ( ! $wp_query instanceof WP_Query ) {
        return 0;
    }

    return max(
        0,
        (int) $wp_query->found_posts
    );
}


/**
 * ============================================================
 * INDEXSTATUS
 * ============================================================
 *
 * Retourneert niet alleen true/false, maar ook WAAROM.
 *
 * Handig voor debugging en later voor sitemapbeheer.
 */

function tfsc_combo_get_index_status(
    $combo = null,
    $result_count = null
) {

    /**
     * Huidige frontend combo.
     */
    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {

            return [
                'index'        => false,
                'reason'       => 'not_combo',
                'results'      => 0,
                'taxonomies'   => 0,
                'has_function' => false,
            ];
        }

        $combo =
            tfsc_get_combo_archive();


        /**
         * Alleen voor de huidige frontendpagina kunnen we
         * het aantal resultaten gratis uit de hoofdquery halen.
         */
        if ( null === $result_count ) {

            $result_count =
                tfsc_combo_get_current_result_count();
        }
    }


    if (
        ! is_array( $combo ) ||
        ! $combo
    ) {

        return [
            'index'        => false,
            'reason'       => 'invalid_combo',
            'results'      => 0,
            'taxonomies'   => 0,
            'has_function' => false,
        ];
    }


    $taxonomy_count =
        tfsc_combo_count_taxonomies(
            $combo
        );


    $has_function =
        tfsc_combo_has_function_name(
            $combo
        );


    /**
     * Te diepe combinatie.
     */
    if (
        $taxonomy_count
        >
        TFSC_COMBO_SEO_MAX_TAXONOMIES
    ) {

        return [
            'index'        => false,
            'reason'       => 'too_many_taxonomies',
            'results'      => null === $result_count
                ? null
                : (int) $result_count,
            'taxonomies'   => $taxonomy_count,
            'has_function' => $has_function,
        ];
    }


    /**
     * Als een externe toepassing, zoals de sitemapgenerator,
     * geen resultaat-aantal meegeeft, gaan we conservatief om
     * met de beslissing.
     *
     * Met functienaam:
     * toegestaan.
     *
     * Zonder functienaam:
     * resultaat-aantal is vereist voordat we hem indexeren.
     */
    if ( null === $result_count ) {

        if ( $has_function ) {

            return [
                'index'        => true,
                'reason'       => 'function_combo',
                'results'      => null,
                'taxonomies'   => $taxonomy_count,
                'has_function' => true,
            ];
        }


        return [
            'index'        => false,
            'reason'       => 'result_count_required',
            'results'      => null,
            'taxonomies'   => $taxonomy_count,
            'has_function' => false,
        ];
    }


    $result_count =
        max(
            0,
            (int) $result_count
        );


    /**
     * Met functienaam.
     */
    if ( $has_function ) {

        if (
            $result_count
            <
            TFSC_COMBO_SEO_MIN_RESULTS_WITH_FUNCTION
        ) {

            return [
                'index'        => false,
                'reason'       => 'too_few_results',
                'results'      => $result_count,
                'taxonomies'   => $taxonomy_count,
                'has_function' => true,
            ];
        }


        return [
            'index'        => true,
            'reason'       => 'function_combo',
            'results'      => $result_count,
            'taxonomies'   => $taxonomy_count,
            'has_function' => true,
        ];
    }


    /**
     * Zonder functienaam:
     * minimaal 3 vacatures.
     */
    if (
        $result_count
        <
        TFSC_COMBO_SEO_MIN_RESULTS_WITHOUT_FUNCTION
    ) {

        return [
            'index'        => false,
            'reason'       => 'too_few_results',
            'results'      => $result_count,
            'taxonomies'   => $taxonomy_count,
            'has_function' => false,
        ];
    }


    return [
        'index'        => true,
        'reason'       => 'field_service_combo',
        'results'      => $result_count,
        'taxonomies'   => $taxonomy_count,
        'has_function' => false,
    ];
}


/**
 * ============================================================
 * CENTRALE TRUE/FALSE FUNCTIE
 * ============================================================
 *
 * Deze blijft bewust bestaan omdat de sitemap snippet
 * deze functie al gebruikt.
 *
 * Optioneel kan de sitemap later het daadwerkelijke
 * resultaat-aantal als tweede argument meegeven.
 */

function tfsc_combo_should_index(
    $combo = null,
    $result_count = null
) {

    $status =
        tfsc_combo_get_index_status(
            $combo,
            $result_count
        );

    return ! empty(
        $status['index']
    );
}


/**
 * ============================================================
 * SEO TITLE
 * ============================================================
 *
 * Met functienaam:
 *
 * Field Service Engineer vacatures Elektrotechniek
 *
 *
 * Zonder functienaam:
 *
 * Field Service vacatures Elektrotechniek Noord-Brabant
 */

function tfsc_combo_seo_build_title() {

    $items =
        tfsc_combo_seo_get_items();

    if ( ! $items ) {
        return '';
    }

    $function_names = [];
    $other_names    = [];

    foreach ( $items as $item ) {

        if (
            'functienaam'
            === $item['taxonomy']
        ) {

            if (
                ! in_array(
                    $item['name'],
                    $function_names,
                    true
                )
            ) {

                $function_names[] =
                    $item['name'];
            }

            continue;
        }


        if (
            ! in_array(
                $item['name'],
                $other_names,
                true
            )
        ) {

            $other_names[] =
                $item['name'];
        }
    }


    /**
     * Functienaam aanwezig.
     */
    if ( $function_names ) {

        $title =
            implode(
                ' ',
                $function_names
            )
            .
            ' vacatures';


        if ( $other_names ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $other_names
                );
        }


        return trim(
            $title
        );
    }


    /**
     * Geen functienaam.
     */
    if ( ! $other_names ) {
        return '';
    }


    return trim(
        'Field Service vacatures '
        .
        implode(
            ' ',
            $other_names
        )
    );
}


/**
 * ============================================================
 * META DESCRIPTION
 * ============================================================
 */

function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();

    if ( '' === $title ) {
        return '';
    }


    return sprintf(
        '%s bij %s.',
        $title,
        TFSC_COMBO_SEO_BRAND
    );
}


/**
 * ============================================================
 * CANONICAL
 * ============================================================
 */

function tfsc_combo_seo_build_canonical() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return '';
    }


    $combo =
        tfsc_get_combo_archive();


    if ( ! is_array( $combo ) ) {
        return '';
    }


    $segments = [];


    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['path'] ) ||
            ! is_array( $item['path'] )
        ) {
            continue;
        }


        $segments[] =
            sanitize_key(
                $item['taxonomy']
            );


        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term
                instanceof WP_Term
            ) {
                continue;
            }


            $segments[] =
                $term->slug;
        }
    }


    if ( ! $segments ) {
        return '';
    }


    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


/**
 * ============================================================
 * CENTRAAL SEO OBJECT
 * ============================================================
 */

function tfsc_get_combo_seo() {

    static $resolved = false;
    static $seo      = false;


    if ( $resolved ) {
        return $seo;
    }


    $resolved = true;


    if ( ! tfsc_combo_seo_is_active() ) {
        return false;
    }


    $title =
        tfsc_combo_seo_build_title();


    if ( '' === $title ) {
        return false;
    }


    $index_status =
        tfsc_combo_get_index_status();


    $seo = [
        'title' =>
            $title,

        'description' =>
            tfsc_combo_seo_build_description(),

        'canonical' =>
            tfsc_combo_seo_build_canonical(),

        'index' =>
            ! empty(
                $index_status['index']
            ),

        'index_reason' =>
            $index_status['reason'],

        'results' =>
            $index_status['results'],

        'taxonomies' =>
            $index_status['taxonomies'],
    ];


    return $seo;
}


