 */

function tfsc_combo_rankmath_title(
    $title
) {

    $seo =
        tfsc_get_combo_seo();


    if (
        ! is_array( $seo ) ||
        empty( $seo['title'] )
    ) {
        return $title;
    }


    return $seo['title'];
}


function tfsc_combo_rankmath_description(
    $description
) {

    $seo =
        tfsc_get_combo_seo();


    if (
        ! is_array( $seo ) ||
        empty( $seo['description'] )
    ) {
        return $description;
    }


    return $seo['description'];
}


function tfsc_combo_rankmath_canonical(
    $canonical
) {

    $seo =
        tfsc_get_combo_seo();


    if (
        ! is_array( $seo ) ||
        empty( $seo['canonical'] )
    ) {
        return $canonical;
    }


    return $seo['canonical'];
}


function tfsc_combo_rankmath_robots(
    $robots
) {

    $seo =
        tfsc_get_combo_seo();


    if ( ! is_array( $seo ) ) {
        return $robots;
    }


    if ( ! is_array( $robots ) ) {
        $robots = [];
    }


    if ( ! empty( $seo['index'] ) ) {

        $robots['index'] =
            'index';

        $robots['follow'] =
            'follow';

    } else {

        $robots['index'] =
            'noindex';

        $robots['follow'] =
            'follow';
    }


    return $robots;
}


