/**
 * TFSC - Combo Archive SEO
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * Regelt ALLEEN virtuele combo archives:
 * - SEO title
 * - Meta description
 * - Canonical
 * - Robots
 * - Centrale indexeringslogica voor SEO + sitemap
 *
 *
 * INDEXERINGSREGELS
 * ============================================================
 *
 * Functienaam aanwezig
 * + maximaal 3 verschillende taxonomies
 * + minimaal 1 resultaat op de frontend
 * → index, follow
 *
 * Geen functienaam
 * → noindex, follow
 *
 * Meer dan 3 verschillende taxonomies
 * → noindex, follow
 *
 *
 * De sitemap gebruikt dezelfde centrale functie:
 *
 * tfsc_combo_should_index()
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {
    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}

if ( ! defined( 'TFSC_COMBO_SEO_MAX_TAXONOMIES' ) ) {
    define(
        'TFSC_COMBO_SEO_MAX_TAXONOMIES',
        3
    );
}


/**
 * ============================================================
 * GELDIG COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_combo_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }

    if (
        ! function_exists( 'tfsc_is_combo_archive' ) ||
        ! function_exists( 'tfsc_get_combo_archive' )
    ) {
        return false;
    }

    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }

    return false !== tfsc_get_combo_archive();
}


/**
 * ============================================================
 * COMBO ITEMS
 * ============================================================
 */

function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];

    if ( $resolved ) {
        return $items;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return [];
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $name =
            trim(
                wp_strip_all_tags(
                    $item['term']->name
                )
            );

        if ( '' === $name ) {
            continue;
        }

        $items[] = [
            'taxonomy' =>
                (string) $item['taxonomy'],

            'term_id' =>
                (int) $item['term']->term_id,

            'slug' =>
                (string) $item['term']->slug,

            'name' =>
                $name,
        ];
    }

    return $items;
}


/**
 * ============================================================
 * AANTAL VERSCHILLENDE TAXONOMIES
 * ============================================================
 *
 * Meerdere terms binnen dezelfde taxonomy
 * tellen als één taxonomy.
 */

function tfsc_combo_count_taxonomies(
    $combo = null
) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return 0;
        }

        $combo =
            tfsc_get_combo_archive();
    }

    if ( ! is_array( $combo ) ) {
        return 0;
    }

    $taxonomies = [];

    foreach ( $combo as $item ) {

        if ( empty( $item['taxonomy'] ) ) {
            continue;
        }

        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );

        if ( '' === $taxonomy ) {
            continue;
        }

        $taxonomies[
            $taxonomy
        ] = true;
    }

    return count(
        $taxonomies
    );
}


/**
 * ============================================================
 * HEEFT COMBO EEN FUNCTIENAAM?
 * ============================================================
 */

function tfsc_combo_has_function_name(
    $combo = null
) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return false;
        }

        $combo =
            tfsc_get_combo_archive();
    }

    if ( ! is_array( $combo ) ) {
        return false;
    }

    foreach ( $combo as $item ) {

        if (
            ! empty( $item['taxonomy'] ) &&
            'functienaam' === $item['taxonomy']
        ) {
            return true;
        }
    }

    return false;
}


/**
 * ============================================================
 * RESULTAAT-AANTAL HUIDIGE FRONTEND COMBO
 * ============================================================
 *
 * Geen extra query.
 *
 * We gebruiken het resultaat van de bestaande
 * WordPress hoofdquery.
 */

function tfsc_combo_get_current_result_count() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return 0;
    }

    global $wp_query;

    if ( ! $wp_query instanceof WP_Query ) {
        return 0;
    }

    return max(
        0,
        (int) $wp_query->found_posts
    );
}


/**
 * ============================================================
 * CENTRALE INDEXERINGSSTATUS
 * ============================================================
 *
 * Wordt gebruikt door:
 *
 * - Rank Math robots
 * - tfsc_combo_should_index()
 * - sitemap
 *
 *
 * BELANGRIJK:
 *
 * Wanneer $combo wordt meegegeven door de sitemap,
 * weten we dat de sitemapgenerator die combo vanuit
 * minimaal één bestaande open vacature heeft opgebouwd.
 *
 * Daarom hoeft de sitemap hier geen extra databasequery
 * voor het resultaat-aantal te doen.
 */

function tfsc_combo_get_index_status(
    $combo = null
) {

    $is_frontend_combo =
        null === $combo;


    /**
     * Huidige frontend combo.
     */
    if ( $is_frontend_combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {

            return [
                'index'      => false,
                'reason'     => 'not_combo',
                'results'    => 0,
                'taxonomies' => 0,
            ];
        }

        $combo =
            tfsc_get_combo_archive();
    }


    if (
        ! is_array( $combo ) ||
        ! $combo
    ) {

        return [
            'index'      => false,
            'reason'     => 'invalid_combo',
            'results'    => 0,
            'taxonomies' => 0,
        ];
    }


    $taxonomy_count =
        tfsc_combo_count_taxonomies(
            $combo
        );


    /**
     * Meer dan maximaal toegestane taxonomies.
     */
    if (
        $taxonomy_count
        >
        TFSC_COMBO_SEO_MAX_TAXONOMIES
    ) {

        return [
            'index'      => false,
            'reason'     => 'too_many_taxonomies',
            'results'    => null,
            'taxonomies' => $taxonomy_count,
        ];
    }


    /**
     * Functienaam is verplicht voor indexatie.
     */
    if (
        ! tfsc_combo_has_function_name(
            $combo
        )
    ) {

        return [
            'index'      => false,
            'reason'     => 'no_function_name',
            'results'    => null,
            'taxonomies' => $taxonomy_count,
        ];
    }


    /**
     * Op de daadwerkelijke frontendpagina controleren
     * we ook of er minimaal één resultaat is.
     */
    if ( $is_frontend_combo ) {

        $result_count =
            tfsc_combo_get_current_result_count();


        if ( $result_count < 1 ) {

            return [
                'index'      => false,
                'reason'     => 'no_results',
                'results'    => $result_count,
                'taxonomies' => $taxonomy_count,
            ];
        }


        return [
            'index'      => true,
            'reason'     => 'valid_function_combo',
            'results'    => $result_count,
            'taxonomies' => $taxonomy_count,
        ];
    }


    /**
     * Sitemap:
     *
     * De sitemapgenerator genereert alleen combo's
     * vanuit bestaande open vacatures.
     *
     * Daardoor weten we hier dat minimaal één resultaat
     * bestaat zonder opnieuw een query uit te voeren.
     */
    return [
        'index'      => true,
        'reason'     => 'valid_sitemap_function_combo',
        'results'    => null,
        'taxonomies' => $taxonomy_count,
    ];
}


/**
 * ============================================================
 * CENTRALE TRUE/FALSE INDEXERINGSFUNCTIE
 * ============================================================
 *
 * De sitemap snippet gebruikt deze functie.
 */

function tfsc_combo_should_index(
    $combo = null
) {

    $status =
        tfsc_combo_get_index_status(
            $combo
        );

    return ! empty(
        $status['index']
    );
}


/**
 * ============================================================
 * SEO TITLE
 * ============================================================
 *
 * Met functienaam:
 *
 * Field Service Engineer vacatures Elektrotechniek
 *
 * Commissioning Engineer vacatures Noord-Brabant
 *
 *
 * Zonder functienaam:
 *
 * Field Service vacatures Elektrotechniek Noord-Brabant
 *
 * Deze laatste krijgen voorlopig wel een nette title,
 * maar noindex.
 */

function tfsc_combo_seo_build_title() {

    $items =
        tfsc_combo_seo_get_items();

    if ( ! $items ) {
        return '';
    }

    $function_names = [];
    $other_names    = [];

    foreach ( $items as $item ) {

        if (
            'functienaam'
            === $item['taxonomy']
        ) {

            if (
                ! in_array(
                    $item['name'],
                    $function_names,
                    true
                )
            ) {

                $function_names[] =
                    $item['name'];
            }

            continue;
        }


        if (
            ! in_array(
                $item['name'],
                $other_names,
                true
            )
        ) {

            $other_names[] =
                $item['name'];
        }
    }


    /**
     * Functienaam aanwezig.
     */
    if ( $function_names ) {

        $title =
            implode(
                ' ',
                $function_names
            )
            .
            ' vacatures';


        if ( $other_names ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $other_names
                );
        }


        return trim(
            $title
        );
    }


    /**
     * Geen functienaam.
     */
    if ( ! $other_names ) {
        return '';
    }


    return trim(
        'Field Service vacatures '
        .
        implode(
            ' ',
            $other_names
        )
    );
}


/**
 * ============================================================
 * META DESCRIPTION
 * ============================================================
 */

function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();

    if ( '' === $title ) {
        return '';
    }

    return sprintf(
        '%s bij %s.',
        $title,
        TFSC_COMBO_SEO_BRAND
    );
}


/**
 * ============================================================
 * CANONICAL
 * ============================================================
 */

function tfsc_combo_seo_build_canonical() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return '';
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return '';
    }

    $segments = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['path'] ) ||
            ! is_array( $item['path'] )
        ) {
            continue;
        }

        $segments[] =
            sanitize_key(
                $item['taxonomy']
            );

        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term
                instanceof WP_Term
            ) {
                continue;
            }

            $segments[] =
                $term->slug;
        }
    }

    if ( ! $segments ) {
        return '';
    }

    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );

    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


/**
 * ============================================================
 * CENTRAAL SEO OBJECT
 * ============================================================
 */

function tfsc_get_combo_seo() {

    static $resolved = false;
    static $seo      = false;

    if ( $resolved ) {
        return $seo;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return false;
    }

    $title =
        tfsc_combo_seo_build_title();

    if ( '' === $title ) {
        return false;
    }

    $index_status =
        tfsc_combo_get_index_status();

    $seo = [
        'title' =>
            $title,

        'description' =>
            tfsc_combo_seo_build_description(),

        'canonical' =>
            tfsc_combo_seo_build_canonical(),

        'index' =>
            ! empty(
                $index_status['index']
            ),

        'index_reason' =>
            $index_status['reason'],

        'results' =>
            $index_status['results'],

        'taxonomies' =>
            $index_status['taxonomies'],
    ];

    return $seo;
}


/**
 * ============================================================
 * RANK MATH CALLBACKS
