}


function tfsc_combo_rankmath_canonical(
    $canonical
) {

    $seo =
        tfsc_get_combo_seo();

    if (
        ! is_array( $seo ) ||
        empty( $seo['canonical'] )
    ) {
        return $canonical;
    }

    return $seo['canonical'];
}


function tfsc_combo_rankmath_robots(
    $robots
) {

    $seo =
        tfsc_get_combo_seo();

    if ( ! is_array( $seo ) ) {
        return $robots;
