/**
 * TFSC - Combo Vacancy Sitemap
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - TFSC - Combo Archive SEO
 * - Rank Math SEO
 *
 * Maakt:
 * /combo-vacatures-sitemap.xml
 *
 * Wordt automatisch toegevoegd aan:
 * /sitemap_index.xml
 *
 *
 * HUIDIGE STRATEGIE
 * ============================================================
 *
 * - Alleen gepubliceerde + open vacatures
 * - Alleen werkelijk bestaande termcombinaties
 * - Exact 2 verschillende taxonomies per combo
 * - tfsc_combo_should_index() bepaalt of de combo
 *   daadwerkelijk in de sitemap mag
 * - functienaam wordt altijd als eerste taxonomy
 *   in de URL geplaatst
 * - overige taxonomies blijven volledig dynamisch
 *
 *
 * Voorbeeld:
 *
 * NIET:
 * /vacatures/bedrijfssector/energie/
 * functienaam/field-service-engineer/
 *
 * WEL:
 * /vacatures/functienaam/field-service-engineer/
 * bedrijfssector/energie/
 *
 *
 * Performance:
 * - combinaties worden alleen berekend wanneer nodig
 * - URL-lijst wordt gecachet
 * - cache wordt automatisch verwijderd bij relevante wijzigingen
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if (
    ! defined(
        'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS',
        2
    );
}


if (
    ! defined(
        'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS',
        2
    );
}


/**
 * Nieuwe cache key.
 *
 * Hierdoor gebruiken we sowieso niet de oude sitemapcache
 * waarin de verkeerde URL-volgorde stond.
 */
if (
    ! defined(
        'TFSC_COMBO_SITEMAP_CACHE_KEY'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_CACHE_KEY',
        'tfsc_combo_sitemap_links_v3'
    );
}


if (
    ! defined(
        'TFSC_COMBO_SITEMAP_CACHE_TTL'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_CACHE_TTL',
        DAY_IN_SECONDS
    );
}


/**
 * ============================================================
 * BESCHIKBAARHEID
 * ============================================================
 */

function tfsc_combo_sitemap_is_available() {

    return (
        function_exists(
            'tfsc_get_allowed_combo_taxonomies'
        )
        &&
        function_exists(
            'tfsc_get_combo_taxonomy_match_method'
        )
        &&
        function_exists(
            'tfsc_combo_should_index'
        )
        &&
        defined(
            'TFSC_VACANCY_POST_TYPE'
        )
        &&
        defined(
            'TFSC_STATUS_TAXONOMY'
        )
        &&
        defined(
            'TFSC_OPEN_STATUS_SLUG'
        )
        &&
        defined(
            'TFSC_COMBO_BASE'
        )
    );
}


/**
 * ============================================================
 * TAXONOMY VOLGORDE
 * ============================================================
 *
 * functienaam altijd vooraan.
 *
 * Alle overige taxonomies behouden hun bestaande volgorde.
 *
 * Nieuwe taxonomies hoeven dus nergens toegevoegd te worden.
 */

function tfsc_combo_sitemap_order_taxonomies(
    array $taxonomies
) {

    $function = [];
    $others   = [];

    foreach ( $taxonomies as $taxonomy ) {

        if ( 'functienaam' === $taxonomy ) {
            $function[] = $taxonomy;
        } else {
            $others[] = $taxonomy;
        }
    }

    return array_merge(
        $function,
        $others
    );
}


/**
 * ============================================================
 * COMBO VOLGORDE
 * ============================================================
 *
 * Zelfde principe voor reeds opgebouwde combo-items.
 */

function tfsc_combo_sitemap_order_combo(
    array $combo
) {

    $function = [];
    $others   = [];

    foreach ( $combo as $item ) {

        if (
            isset( $item['taxonomy'] ) &&
            'functienaam'
            === $item['taxonomy']
        ) {
            $function[] = $item;
        } else {
            $others[] = $item;
        }
    }

    return array_merge(
        $function,
        $others
    );
}


/**
 * ============================================================
 * VOLLEDIG TERM-PAD
 * ============================================================
 *
 * Nodig voor hiërarchische taxonomies.
 *
 * Bijvoorbeeld:
 *
 * ouder / kind
 */

function tfsc_combo_sitemap_get_term_path(
    WP_Term $term
) {

    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );

    if ( ! $taxonomy ) {
        return [];
    }


    /**
     * Niet-hiërarchische taxonomy.
     */
    if (
        ! $taxonomy->hierarchical
    ) {
        return [
            $term,
        ];
    }


    $path = [];


    $ancestor_ids =
        array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        );


    foreach (
        $ancestor_ids
        as $ancestor_id
    ) {

        $ancestor =
            get_term(
                $ancestor_id,
                $term->taxonomy
            );


        if (
            $ancestor instanceof WP_Term &&
            ! is_wp_error( $ancestor )
        ) {
            $path[] = $ancestor;
        }
    }


    $path[] = $term;


    return $path;
}


/**
 * ============================================================
 * TERM → COMBO ITEM
 * ============================================================
 *
 * Zelfde datastructuur als de bestaande combo resolver:
 *
 * [
 *     'taxonomy' => ...,
 *     'term'     => WP_Term,
 *     'path'     => [...]
 * ]
 */

function tfsc_combo_sitemap_make_item(
    WP_Term $term
) {

    return [
        'taxonomy' =>
            $term->taxonomy,

        'term' =>
            $term,

        'path' =>
            tfsc_combo_sitemap_get_term_path(
                $term
            ),
    ];
}


/**
 * ============================================================
 * COMBO URL
 * ============================================================
 *
 * Bouwt exact dezelfde structuur die jouw bestaande
 * combo-parser verwacht:
 *
 * /vacatures/
 * taxonomy/term/
 * taxonomy/term/
 *
 * functienaam wordt vooraf altijd vooraan geplaatst.
 */

function tfsc_combo_sitemap_build_url(
    array $combo
) {

    if ( ! $combo ) {
        return '';
    }


    $combo =
        tfsc_combo_sitemap_order_combo(
            $combo
        );


    $segments = [];


    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['path'] ) ||
            ! is_array( $item['path'] )
        ) {
            return '';
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            function_exists(
                'tfsc_combo_taxonomy_allowed'
            )
            &&
            ! tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return '';
        }


        $segments[] =
            $taxonomy;


        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term instanceof WP_Term ||
                $term->taxonomy !== $taxonomy
            ) {
                return '';
            }


            $segments[] =
                $term->slug;
        }
    }


    if ( ! $segments ) {
        return '';
    }


    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


/**
 * ============================================================
 * TAXONOMY TERMS VAN ÉÉN VACATURE
 * ============================================================
 */

function tfsc_combo_sitemap_get_post_dimensions(
    $post_id,
    array $taxonomies
) {

    $dimensions = [];


    foreach (
        $taxonomies
        as $taxonomy
    ) {

        $terms =
            get_the_terms(
                $post_id,
                $taxonomy
            );


        if (
            ! is_array( $terms ) ||
            ! $terms
        ) {
            continue;
        }


        $taxonomy_object =
            get_taxonomy(
                $taxonomy
            );


        $match_method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        $collected = [];


        foreach (
            $terms
            as $term
        ) {

            if (
                ! $term instanceof WP_Term
            ) {
                continue;
            }


            $collected[
                $term->term_id
            ] = $term;


            /**
             * Jouw bestaande combo-query gebruikt bij
             * hiërarchische OR-taxonomies:
             *
             * include_children = true
             *
             * Daarom mogen ook ancestor terms een geldige
             * landingspagina vormen voor deze vacature.
             *
             * kennisgebied gebruikt AND en krijgt daarom
             * bewust geen ancestors toegevoegd.
             */
            if (
                $taxonomy_object &&
                $taxonomy_object->hierarchical &&
                'AND' !== $match_method
            ) {

                $ancestor_ids =
                    get_ancestors(
                        $term->term_id,
                        $taxonomy,
                        'taxonomy'
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error(
                            $ancestor
                        )
                    ) {

                        $collected[
                            $ancestor->term_id
                        ] = $ancestor;
                    }
                }
            }
        }


        if ( $collected ) {

            $dimensions[
                $taxonomy
            ] =
                array_values(
                    $collected
                );
        }
    }


    return $dimensions;
}


/**
 * ============================================================
 * COMBINATIES VAN TAXONOMIES
 * ============================================================
 *
 * Voor:
 *
 * functienaam
 * kennisgebied
 * locatie
 *
 * en size = 2:
 *
 * functienaam + kennisgebied
 * functienaam + locatie
 * kennisgebied + locatie
 */

function tfsc_combo_sitemap_dimension_sets(
    array $dimensions,
    $size
) {

    $dimensions =
        array_values(
            $dimensions
        );


    $size =
        (int) $size;


    if (
        $size < 1 ||
        count( $dimensions ) < $size
    ) {
        return [];
    }


    if ( 1 === $size ) {

        return array_map(
            static function(
                $dimension
            ) {

                return [
                    $dimension,
                ];
            },
            $dimensions
        );
    }


    $result = [];


    $first =
        array_shift(
            $dimensions
        );


    /**
     * Combinaties mét eerste taxonomy.
     */
    foreach (
        tfsc_combo_sitemap_dimension_sets(
            $dimensions,
            $size - 1
        )
        as $subset
    ) {

        array_unshift(
            $subset,
            $first
        );


        $result[] =
            $subset;
    }


    /**
     * Combinaties zonder eerste taxonomy.
     */
    foreach (
        tfsc_combo_sitemap_dimension_sets(
            $dimensions,
            $size
        )
        as $subset
    ) {

        $result[] =
            $subset;
    }


    return $result;
}


/**
 * ============================================================
 * TERM PRODUCTEN
 * ============================================================
 *
 * Bijvoorbeeld:
 *
 * functienaam:
 * Field Service Engineer
 *
 * kennisgebied:
 * Elektrotechniek
 * Mechanisch
 *
 * levert:
 *
 * FSE + Elektrotechniek
 * FSE + Mechanisch
 */

function tfsc_combo_sitemap_term_products(
    array $taxonomy_set,
    array $dimensions
) {

    /**
     * Zorg ook hier dat functienaam vooraan staat.
     */
    $taxonomy_set =
        tfsc_combo_sitemap_order_taxonomies(
            $taxonomy_set
        );


    $products = [
        [],
    ];


    foreach (
        $taxonomy_set
        as $taxonomy
    ) {

        if (
            empty(
                $dimensions[
                    $taxonomy
                ]
            )
        ) {
            return [];
        }


        $next = [];


        foreach (
            $products
            as $product
        ) {

            foreach (
                $dimensions[
                    $taxonomy
                ]
                as $term
            ) {

                if (
                    ! $term instanceof WP_Term
                ) {
                    continue;
                }


                $new_product =
                    $product;


                $new_product[] =
                    tfsc_combo_sitemap_make_item(
                        $term
                    );


                $next[] =
                    $new_product;
            }
        }


        $products =
            $next;
    }


    return $products;
}


/**
 * ============================================================
 * SITEMAP LINKS GENEREREN
 * ============================================================
 *
 * Dit is het zwaardere gedeelte.
 *
 * Wordt daarom gecachet.
 */

function tfsc_combo_sitemap_generate_links() {

    if (
        ! tfsc_combo_sitemap_is_available()
    ) {
        return [];
    }


    /**
     * Cache.
     */
    $cached =
        get_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY
        );


    if (
        is_array( $cached )
    ) {
        return $cached;
    }


    /**
     * Dynamisch alle toegestane vacature-taxonomies.
     */
    $taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if ( ! $taxonomies ) {
        return [];
    }


    /**
     * functienaam intern eerst verwerken.
     */
    $taxonomies =
        tfsc_combo_sitemap_order_taxonomies(
            $taxonomies
        );


    /**
     * Alleen gepubliceerde vacatures met status open.
     */
    $post_ids =
        get_posts(
            [
                'post_type' =>
                    TFSC_VACANCY_POST_TYPE,

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    -1,

                'fields' =>
                    'ids',

                'no_found_rows' =>
                    true,

                'orderby' =>
                    'ID',

                'order' =>
                    'ASC',

                'tax_query' => [
                    [
                        'taxonomy' =>
                            TFSC_STATUS_TAXONOMY,

                        'field' =>
                            'slug',

                        'terms' => [
                            TFSC_OPEN_STATUS_SLUG,
                        ],

                        'operator' =>
                            'IN',

                        'include_children' =>
                            false,
                    ],
                ],
            ]
        );


    if ( ! $post_ids ) {

        set_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            [],
            TFSC_COMBO_SITEMAP_CACHE_TTL
        );


        return [];
    }


    /**
     * URL als array-key.
     *
     * Een combo die via meerdere vacatures ontstaat,
     * komt daardoor maar één keer in de sitemap.
     */
    $links = [];


    foreach (
        $post_ids
        as $post_id
    ) {

        $dimensions =
            tfsc_combo_sitemap_get_post_dimensions(
                $post_id,
                $taxonomies
            );


        if ( ! $dimensions ) {
            continue;
        }


        /**
         * Ook dimensions expliciet in dezelfde
         * taxonomy-volgorde zetten.
         */
        $ordered_dimensions = [];


        foreach (
            $taxonomies
            as $taxonomy
        ) {

            if (
                isset(
                    $dimensions[
                        $taxonomy
                    ]
                )
            ) {

                $ordered_dimensions[
                    $taxonomy
                ] =
                    $dimensions[
                        $taxonomy
                    ];
            }
        }


        $dimensions =
            $ordered_dimensions;


        $taxonomy_names =
            array_keys(
                $dimensions
            );


        $min =
            max(
                2,
                (int)
                TFSC_COMBO_SITEMAP_MIN_DIMENSIONS
            );


        $max =
            min(
                count(
                    $taxonomy_names
                ),
                max(
                    $min,
                    (int)
                    TFSC_COMBO_SITEMAP_MAX_DIMENSIONS
                )
            );


        if ( $max < $min ) {
            continue;
        }


        for (
            $size = $min;
            $size <= $max;
            $size++
        ) {

            $dimension_sets =
                tfsc_combo_sitemap_dimension_sets(
                    $taxonomy_names,
                    $size
                );


            foreach (
                $dimension_sets
                as $taxonomy_set
            ) {

                /**
                 * Consistente taxonomy-volgorde.
                 */
                $taxonomy_set =
                    tfsc_combo_sitemap_order_taxonomies(
                        $taxonomy_set
                    );


                $products =
                    tfsc_combo_sitemap_term_products(
                        $taxonomy_set,
                        $dimensions
                    );


                foreach (
                    $products
                    as $combo
                ) {

                    /**
                     * Definitieve combo-volgorde.
                     */
                    $combo =
                        tfsc_combo_sitemap_order_combo(
                            $combo
                        );


                    /**
                     * SEO-laag bepaalt centraal of deze
                     * combo geïndexeerd mag worden.
                     */
                    if (
                        ! tfsc_combo_should_index(
                            $combo
                        )
                    ) {
                        continue;
                    }


                    $url =
                        tfsc_combo_sitemap_build_url(
                            $combo
                        );


                    if ( '' === $url ) {
                        continue;
                    }


                    $links[
                        $url
                    ] = [
                        'loc' =>
                            $url,
                    ];
                }
            }
        }
    }


    /**
     * Stabiele alfabetische output.
     */
    ksort(
        $links,
        SORT_STRING
    );


    $links =
        array_values(
            $links
        );


    /**
     * Opslaan.
     */
    set_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY,
        $links,
        TFSC_COMBO_SITEMAP_CACHE_TTL
    );


    return $links;
}


/**
 * ============================================================
 * CACHE LEGEN
 * ============================================================
 */

function tfsc_combo_sitemap_flush_cache() {

    /**
     * Huidige versie.
     */
    delete_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY
    );


    /**
     * Oude versies meteen opruimen.
     */
    delete_transient(
        'tfsc_combo_sitemap_links_v1'
    );

    delete_transient(
        'tfsc_combo_sitemap_links_v2'
    );


    /**
     * Rank Math sitemapcache invalidaten.
     */
    if (
        class_exists(
            '\RankMath\Sitemap\Cache'
        )
        &&
        method_exists(
            '\RankMath\Sitemap\Cache',
            'invalidate_storage'
        )
    ) {

        \RankMath\Sitemap\Cache::invalidate_storage(
            'combo-vacatures'
        );
    }
}


