/**
 * ============================================================
 * RANK MATH CUSTOM SITEMAP PROVIDER
 * ============================================================
 */

add_filter(
    'rank_math/sitemap/providers',

    function( $providers ) {

        if (
            ! interface_exists(
                '\RankMath\Sitemap\Providers\Provider'
            )
        ) {
            return $providers;
        }


        if (
            ! class_exists(
                'TFSC_Combo_Vacancy_Sitemap_Provider',
                false
            )
        ) {

            class TFSC_Combo_Vacancy_Sitemap_Provider
                implements
                \RankMath\Sitemap\Providers\Provider {


                /**
                 * ============================================
                 * TYPE
                 * ============================================
                 */

                public function handles_type(
                    $type
                ) {

                    return (
                        'combo-vacatures'
                        === $type
                    );
                }


                /**
                 * ============================================
                 * SITEMAP INDEX
                 * ============================================
                 */

                public function get_index_links(
                    $max_entries
                ) {

                    $links =
                        tfsc_combo_sitemap_generate_links();


                    $total =
                        count(
                            $links
                        );


                    if ( 0 === $total ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int) $max_entries
                        );


                    $pages =
                        max(
                            1,
                            (int) ceil(
                                $total
                                /
                                $max_entries
                            )
                        );


                    $index = [];


                    for (
                        $page = 1;
                        $page <= $pages;
                        $page++
                    ) {

                        $suffix =
                            $pages > 1
                                ? $page
                                : '';


                        $index[] = [
                            'loc' =>
                                \RankMath\Sitemap\Router::get_base_url(
                                    'combo-vacatures-sitemap'
                                    .
                                    $suffix
                                    .
                                    '.xml'
                                ),

                            'lastmod' =>
                                '',
                        ];
                    }


                    return $index;
                }


                /**
                 * ============================================
                 * SITEMAP URLS
                 * ============================================
                 */

                public function get_sitemap_links(
                    $type,
                    $max_entries,
                    $current_page
                ) {

                    if (
                        'combo-vacatures'
                        !== $type
                    ) {
                        return [];
                    }


                    $links =
                        tfsc_combo_sitemap_generate_links();


                    if ( ! $links ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int) $max_entries
                        );


                    $page =
                        max(
                            1,
                            (int) $current_page
                        );


                    $offset =
                        (
                            $page - 1
                        )
                        *
                        $max_entries;


                    return array_slice(
                        $links,
                        $offset,
                        $max_entries
                    );
                }
            }
        }


        $providers[
            'combo-vacatures'
        ] =
            new TFSC_Combo_Vacancy_Sitemap_Provider();


        return $providers;
    }
);

/**
 * TFSC - Native Archive Canonical Test
 *
 * Doel:
 * Native vacature-taxonomy archives canonicaliseren
 * naar de equivalente TFSC combo-archive URL.
 *
 * Voorbeeld:
 *
 * /locatie/nederland/zuid-holland/leiden/
 *
 * wordt canonical naar:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * locatie/nederland/zuid-holland/leiden/
 *
 *
 * BELANGRIJK:
 *
 * - Geen redirects
 * - Geen noindex
 * - Native archive blijft gewoon bereikbaar
 * - Alleen de Rank Math canonical wordt gewijzigd
 * - Alleen vacature-taxonomies
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY' ) ) {
    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY',
        'functienaam'
    );
}


if ( ! defined( 'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG' ) ) {
    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG',
        'field-service-engineer'
    );
}


/**
 * ============================================================
 * IS DIT EEN GELDIG NATIVE VACATURE-ARCHIVE?
 * ============================================================
 */

function tfsc_native_canonical_is_target() {

    if ( is_admin() ) {
        return false;
    }


    /**
     * Alleen echte taxonomy archives.
     *
     * Dus NIET onze virtuele combo archives.
     */
    if (
        ! is_tax() ||
        (
            function_exists( 'tfsc_is_combo_archive' ) &&
            tfsc_is_combo_archive()
        )
    ) {
        return false;
    }


    $term =
        get_queried_object();


    if (
        ! $term instanceof WP_Term
    ) {
        return false;
    }


    /**
     * Alleen taxonomies die volgens de bestaande
     * combo-engine aan vacatures gekoppeld en toegestaan zijn.
     */
    if (
        ! function_exists(
            'tfsc_combo_taxonomy_allowed'
        ) ||
        ! tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * VOLLEDIG TERM-PAD OPHALEN
 * ============================================================
 *
 * Bijvoorbeeld voor Leiden:
 *
 * Nederland
 * → Zuid-Holland
 * → Leiden
 *
 * Wordt:
 *
 * [
 *   nederland,
 *   zuid-holland,
 *   leiden
 * ]
 */

function tfsc_native_canonical_get_term_path(
    WP_Term $term
) {

    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );


    if ( ! $taxonomy ) {
        return [];
    }


    /**
     * Niet-hiërarchische taxonomy.
     */
    if (
        ! $taxonomy->hierarchical
    ) {
        return [
            $term,
        ];
    }


    $path = [];


    $ancestor_ids =
        array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        );


    foreach (
        $ancestor_ids
        as $ancestor_id
    ) {

        $ancestor =
            get_term(
                $ancestor_id,
                $term->taxonomy
            );


        if (
            $ancestor instanceof WP_Term &&
            ! is_wp_error( $ancestor )
        ) {
            $path[] =
                $ancestor;
        }
    }


    $path[] =
        $term;


    return $path;
}


/**
 * ============================================================
 * EQUIVALENTE COMBO CANONICAL BOUWEN
 * ============================================================
 */

function tfsc_native_canonical_build_url() {

    if (
        ! tfsc_native_canonical_is_target()
    ) {
        return '';
    }


    if (
        ! defined( 'TFSC_COMBO_BASE' )
    ) {
        return '';
    }


    $native_term =
        get_queried_object();


    if (
        ! $native_term instanceof WP_Term
    ) {
        return '';
    }


    /**
     * Field Service Engineer term ophalen.
     */
    $function_term =
        get_term_by(
            'slug',
            TFSC_NATIVE_CANONICAL_FUNCTION_SLUG,
            TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY
        );


    if (
        ! $function_term instanceof WP_Term ||
        is_wp_error( $function_term )
    ) {
        return '';
    }


    /**
     * Volledig native taxonomy-pad.
     */
    $native_path =
        tfsc_native_canonical_get_term_path(
            $native_term
        );


    if ( ! $native_path ) {
        return '';
    }


    /**
     * URL-segmenten.
     *
     * functienaam altijd eerst.
     */
    $segments = [
        TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY,
        $function_term->slug,
        $native_term->taxonomy,
    ];


    foreach (
        $native_path
        as $path_term
    ) {

        if (
            ! $path_term instanceof WP_Term
        ) {
            return '';
        }


        $segments[] =
            $path_term->slug;
    }


    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    $url =
        trailingslashit(
            home_url(
                '/' . $path
            )
        );


    /**
     * ========================================================
     * PAGINATION
     * ========================================================
     *
     * Native /page/3/ moet canonical worden naar
     * combo /page/3/, NIET naar combo pagina 1.
     */

    $paged =
        max(
            1,
            (int) get_query_var( 'paged' )
        );


    if ( $paged > 1 ) {

        $url =
            trailingslashit(
                $url
                .
                'page/'
                .
                $paged
            );
    }


    return $url;
}


/**
 * ============================================================
 * RANK MATH CANONICAL
 * ============================================================
 */

add_filter(
    'rank_math/frontend/canonical',
    function( $canonical ) {

        if (
            ! tfsc_native_canonical_is_target()
        ) {
            return $canonical;
        }


        $combo_canonical =
            tfsc_native_canonical_build_url();


        if ( '' === $combo_canonical ) {
            return $canonical;
        }


        return $combo_canonical;
    },
    99
);

/**
 * TFSC - Combo Archive SEO + Native Archive Canonicals
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * Regelt:
 *
 * COMBO ARCHIVES
 * - SEO title
 * - Meta description
 * - Canonical
 * - Robots
 * - Centrale indexeringslogica voor SEO + sitemap
 *
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * - blijven gewoon bereikbaar
 * - blijven index, follow
 * - canonical naar equivalente combo archive
 *
 *
 * INDEXERINGSREGELS COMBO ARCHIVES
 * ============================================================
 *
 * Functienaam aanwezig
 * + maximaal 3 verschillende taxonomies
 * + minimaal 1 resultaat op frontend
 * → index, follow
 *
 * Geen functienaam
 * → noindex, follow
 *
 * Meer dan 3 verschillende taxonomies
 * → noindex, follow
 *
 *
 * De sitemap gebruikt:
 *
 * tfsc_combo_should_index()
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {
    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}


if ( ! defined( 'TFSC_COMBO_SEO_MAX_TAXONOMIES' ) ) {
    define(
        'TFSC_COMBO_SEO_MAX_TAXONOMIES',
        3
    );
}


/**
 * Standaard functieterm waarmee native archives
 * canonicaliseren naar de equivalente combo.
 */
if ( ! defined( 'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY' ) ) {
    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY',
        'functienaam'
    );
}


if ( ! defined( 'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG' ) ) {
    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG',
        'field-service-engineer'
    );
}


/**
 * ============================================================
 * GELDIG COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_combo_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }

    if (
        ! function_exists( 'tfsc_is_combo_archive' ) ||
        ! function_exists( 'tfsc_get_combo_archive' )
    ) {
        return false;
    }

    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }

    return false !== tfsc_get_combo_archive();
}


/**
 * ============================================================
 * COMBO ITEMS
 * ============================================================
 */

function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];

    if ( $resolved ) {
        return $items;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return [];
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $name =
            trim(
                wp_strip_all_tags(
                    $item['term']->name
                )
            );

        if ( '' === $name ) {
            continue;
        }

        $items[] = [
            'taxonomy' =>
                (string) $item['taxonomy'],

            'term_id' =>
                (int) $item['term']->term_id,

            'slug' =>
                (string) $item['term']->slug,

            'name' =>
                $name,
        ];
    }

    return $items;
}


/**
 * ============================================================
 * AANTAL VERSCHILLENDE TAXONOMIES
 * ============================================================
 */

function tfsc_combo_count_taxonomies(
    $combo = null
) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return 0;
        }

        $combo =
            tfsc_get_combo_archive();
    }

    if ( ! is_array( $combo ) ) {
        return 0;
    }

    $taxonomies = [];

    foreach ( $combo as $item ) {

        if ( empty( $item['taxonomy'] ) ) {
            continue;
        }

        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );

        if ( '' === $taxonomy ) {
            continue;
        }

        $taxonomies[
            $taxonomy
        ] = true;
    }

    return count(
        $taxonomies
    );
}


/**
 * ============================================================
 * HEEFT COMBO EEN FUNCTIENAAM?
 * ============================================================
 */

function tfsc_combo_has_function_name(
    $combo = null
) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return false;
        }

        $combo =
            tfsc_get_combo_archive();
    }

    if ( ! is_array( $combo ) ) {
        return false;
    }

    foreach ( $combo as $item ) {

        if (
            ! empty( $item['taxonomy'] ) &&
            'functienaam' === $item['taxonomy']
        ) {
            return true;
        }
    }

    return false;
}


/**
 * ============================================================
 * RESULTAAT-AANTAL HUIDIGE FRONTEND COMBO
 * ============================================================
 */

function tfsc_combo_get_current_result_count() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return 0;
    }

    global $wp_query;

    if ( ! $wp_query instanceof WP_Query ) {
        return 0;
    }

    return max(
        0,
        (int) $wp_query->found_posts
    );
}


/**
 * ============================================================
 * CENTRALE INDEXERINGSSTATUS
 * ============================================================
 */

function tfsc_combo_get_index_status(
    $combo = null
) {

    $is_frontend_combo =
        null === $combo;


    if ( $is_frontend_combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {

            return [
                'index'      => false,
                'reason'     => 'not_combo',
                'results'    => 0,
                'taxonomies' => 0,
            ];
        }

        $combo =
            tfsc_get_combo_archive();
    }


    if (
        ! is_array( $combo ) ||
        ! $combo
    ) {

        return [
            'index'      => false,
            'reason'     => 'invalid_combo',
            'results'    => 0,
            'taxonomies' => 0,
        ];
    }


    $taxonomy_count =
        tfsc_combo_count_taxonomies(
            $combo
        );


    if (
        $taxonomy_count
        >
        TFSC_COMBO_SEO_MAX_TAXONOMIES
    ) {

        return [
            'index'      => false,
            'reason'     => 'too_many_taxonomies',
            'results'    => null,
            'taxonomies' => $taxonomy_count,
        ];
    }


    if (
        ! tfsc_combo_has_function_name(
            $combo
        )
    ) {

        return [
            'index'      => false,
            'reason'     => 'no_function_name',
            'results'    => null,
            'taxonomies' => $taxonomy_count,
        ];
    }


    if ( $is_frontend_combo ) {

        $result_count =
            tfsc_combo_get_current_result_count();


        if ( $result_count < 1 ) {

            return [
                'index'      => false,
                'reason'     => 'no_results',
                'results'    => $result_count,
                'taxonomies' => $taxonomy_count,
            ];
        }


        return [
            'index'      => true,
            'reason'     => 'valid_function_combo',
            'results'    => $result_count,
            'taxonomies' => $taxonomy_count,
        ];
    }


    /**
     * Sitemap-combo's worden alleen opgebouwd
     * vanuit bestaande open vacatures.
     */
    return [
        'index'      => true,
        'reason'     => 'valid_sitemap_function_combo',
        'results'    => null,
        'taxonomies' => $taxonomy_count,
    ];
}


/**
 * ============================================================
 * CENTRALE TRUE/FALSE INDEXERINGSFUNCTIE
 * ============================================================
 */

function tfsc_combo_should_index(
    $combo = null
) {

    $status =
        tfsc_combo_get_index_status(
            $combo
        );

    return ! empty(
        $status['index']
    );
}


/**
 * ============================================================
 * SEO TITLE COMBO ARCHIVES
 * ============================================================
 */

function tfsc_combo_seo_build_title() {

    $items =
        tfsc_combo_seo_get_items();

    if ( ! $items ) {
        return '';
    }

    $function_names = [];
    $other_names    = [];

    foreach ( $items as $item ) {

        if (
            'functienaam'
            === $item['taxonomy']
        ) {

            if (
                ! in_array(
                    $item['name'],
                    $function_names,
                    true
                )
            ) {
                $function_names[] =
                    $item['name'];
            }

            continue;
        }


        if (
            ! in_array(
                $item['name'],
                $other_names,
                true
            )
        ) {
            $other_names[] =
                $item['name'];
        }
    }


    if ( $function_names ) {

        $title =
            implode(
                ' ',
                $function_names
            )
            .
            ' vacatures';


        if ( $other_names ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $other_names
                );
        }


        return trim(
            $title
        );
    }


    /**
     * Zonder functienaam:
     * nette title voor bezoeker,
     * maar momenteel noindex.
     */
    if ( ! $other_names ) {
        return '';
    }


    return trim(
        'Field Service vacatures '
        .
        implode(
            ' ',
            $other_names
        )
    );
}


/**
 * ============================================================
 * META DESCRIPTION COMBO ARCHIVES
 * ============================================================
 */

function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();

    if ( '' === $title ) {
        return '';
    }

    return sprintf(
        '%s bij %s.',
        $title,
        TFSC_COMBO_SEO_BRAND
    );
}


/**
 * ============================================================
 * CANONICAL COMBO ARCHIVES
 * ============================================================
 */

function tfsc_combo_seo_build_canonical() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return '';
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return '';
    }

    $segments = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['path'] ) ||
            ! is_array( $item['path'] )
        ) {
            continue;
        }

        $segments[] =
            sanitize_key(
                $item['taxonomy']
            );

        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term
                instanceof WP_Term
            ) {
                continue;
            }

            $segments[] =
                $term->slug;
        }
    }

    if ( ! $segments ) {
        return '';
    }

    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );

    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


/**
