/**
 * ============================================================
 * NATIVE VACATURE TAXONOMY ARCHIVE?
 * ============================================================
 */

function tfsc_native_canonical_is_target() {

    if ( is_admin() ) {
        return false;
    }


    /**
     * Alleen echte taxonomy archives.
     */
    if (
        ! is_tax() ||
        (
            function_exists(
                'tfsc_is_combo_archive'
            )
            &&
            tfsc_is_combo_archive()
        )
    ) {
        return false;
    }


    $term =
        get_queried_object();


    if (
        ! $term instanceof WP_Term
    ) {
        return false;
    }


    /**
     * Alleen taxonomies die aan vacature hangen
     * en volgens de combo-engine toegestaan zijn.
     */
    if (
        ! function_exists(
            'tfsc_combo_taxonomy_allowed'
        )
        ||
        ! tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    ) {
        return false;
    }


    return true;
}


/**
 * ============================================================
 * VOLLEDIG NATIVE TERM-PAD
 * ============================================================
 */

function tfsc_native_canonical_get_term_path(
    WP_Term $term
) {

    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );


    if ( ! $taxonomy ) {
        return [];
    }


    if (
        ! $taxonomy->hierarchical
    ) {
        return [
            $term,
        ];
    }


    $path = [];


    $ancestor_ids =
        array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        );


    foreach (
        $ancestor_ids
        as $ancestor_id
    ) {

        $ancestor =
            get_term(
                $ancestor_id,
                $term->taxonomy
            );


        if (
            $ancestor instanceof WP_Term &&
            ! is_wp_error(
                $ancestor
            )
        ) {
            $path[] =
                $ancestor;
        }
    }


    $path[] =
        $term;


    return $path;
}


/**
 * ============================================================
 * NATIVE ARCHIVE → COMBO CANONICAL
 * ============================================================
 */

function tfsc_native_canonical_build_url() {

    if (
        ! tfsc_native_canonical_is_target()
    ) {
        return '';
    }


    if (
        ! defined(
            'TFSC_COMBO_BASE'
        )
    ) {
        return '';
    }


    $native_term =
        get_queried_object();


    if (
        ! $native_term
        instanceof WP_Term
    ) {
        return '';
    }


    /**
     * Field Service Engineer functieterm.
     */
    $function_term =
        get_term_by(
            'slug',
            TFSC_NATIVE_CANONICAL_FUNCTION_SLUG,
            TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY
        );


    if (
        ! $function_term
        instanceof WP_Term
        ||
        is_wp_error(
            $function_term
        )
    ) {
        return '';
    }


    $native_path =
        tfsc_native_canonical_get_term_path(
            $native_term
        );


    if ( ! $native_path ) {
        return '';
    }


    /**
     * functienaam altijd vooraan.
     */
    $segments = [
        TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY,
        $function_term->slug,
        $native_term->taxonomy,
    ];


    foreach (
        $native_path
        as $path_term
    ) {

        if (
            ! $path_term
            instanceof WP_Term
        ) {
            return '';
        }


        $segments[] =
            $path_term->slug;
    }


    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    $url =
        trailingslashit(
            home_url(
                '/' . $path
            )
        );


    /**
     * Pagination behouden.
     *
     * Native /page/3/
     * → combo /page/3/
     */
    $paged =
        max(
            1,
            (int)
            get_query_var(
                'paged'
            )
        );


    if ( $paged > 1 ) {

        $url =
            trailingslashit(
                $url
                .
                'page/'
                .
                $paged
            );
    }


    return $url;
}


