function tfsc_combo_rankmath_robots(
    $robots
) {

    $seo =
        tfsc_get_combo_seo();

    if (
        ! is_array( $seo )
    ) {
        return $robots;
    }

    if (
        ! is_array( $robots )
    ) {
        $robots = [];
    }


    if (
        ! empty(
            $seo['index']
        )
    ) {

        $robots['index'] =
            'index';

        $robots['follow'] =
            'follow';

    } else {

        $robots['index'] =
            'noindex';

        $robots['follow'] =
            'follow';
    }

    return $robots;
}


/**
 * ============================================================
 * RANK MATH CALLBACK - NATIVE CANONICAL
 * ============================================================
 */

function tfsc_native_rankmath_canonical(
    $canonical
) {

    if (
        ! tfsc_native_canonical_is_target()
    ) {
        return $canonical;
    }


    $combo_canonical =
        tfsc_native_canonical_build_url();


    if (
        '' === $combo_canonical
    ) {
        return $canonical;
    }


    return $combo_canonical;
}


