function tfsc_native_canonical_build_url() {

    if (
        ! tfsc_native_canonical_is_target()
    ) {
        return '';
    }

    if (
        ! defined(
            'TFSC_COMBO_BASE'
        )
    ) {
        return '';
    }

    $native_term =
        get_queried_object();

    if (
        ! $native_term
        instanceof WP_Term
    ) {
        return '';
    }

    $function_term =
        get_term_by(
            'slug',
            TFSC_NATIVE_CANONICAL_FUNCTION_SLUG,
            TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY
        );

    if (
        ! $function_term
        instanceof WP_Term
        ||
        is_wp_error(
            $function_term
        )
    ) {
        return '';
    }

    $native_path =
        tfsc_native_canonical_get_term_path(
            $native_term
        );

    if ( ! $native_path ) {
        return '';
    }

    $segments = [
        TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY,
        $function_term->slug,
        $native_term->taxonomy,
    ];

    foreach (
        $native_path
        as $path_term
    ) {

        if (
            ! $path_term
            instanceof WP_Term
        ) {
            return '';
        }

        $segments[] =
            $path_term->slug;
    }

    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );

    $url =
        trailingslashit(
            home_url(
                '/' . $path
            )
        );

    $paged =
        max(
            1,
            (int)
            get_query_var(
                'paged'
            )
        );

    if ( $paged > 1 ) {

        $url =
            trailingslashit(
                $url
                .
                'page/'
                .
                $paged
            );
    }

    return $url;
}


/**
 * ============================================================
 * SEARCH & FILTER URL HERKENNEN
 * ============================================================
 *
 * Alleen op het gewone vacature-archief.
 *
 * Combo archives worden bewust uitgesloten.
 *
 * We beschouwen queryparameters die met "_" beginnen
 * als Search & Filter parameters.
 *
 * Voorbeelden:
 *
 * /vacatures/?_locatie=noord-brabant
 * /vacatures/?_kennisgebied=elektrotechniek
 */

function tfsc_vacancy_filter_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }

    /**
     * Nooit op combo archives.
     */
    if (
        function_exists(
            'tfsc_is_combo_archive'
        )
        &&
        tfsc_is_combo_archive()
    ) {
        return false;
    }

    /**
     * Alleen het echte vacature post type archive.
     */
    if (
        ! is_post_type_archive(
            TFSC_VACANCY_POST_TYPE
        )
    ) {
        return false;
    }

    if ( empty( $_GET ) ) {
        return false;
    }

    foreach (
        array_keys( $_GET )
        as $key
    ) {

        $key =
            (string) $key;

        /**
         * Search & Filter gebruikt bij jou
         * underscore-prefixed URL arguments.
         */
        if (
            '' !== $key &&
            '_' === $key[0]
        ) {
            return true;
        }
    }

    return false;
}


/**
 * ============================================================
 * SCHONE VACATURE CANONICAL
 * ============================================================
 */

function tfsc_vacancy_filter_clean_canonical() {

    if (
        ! defined(
            'TFSC_VACANCY_POST_TYPE'
        )
    ) {
        return '';
    }

    $url =
        get_post_type_archive_link(
            TFSC_VACANCY_POST_TYPE
        );

    if ( ! $url ) {
        return '';
    }

    return trailingslashit(
        $url
    );
}


/**
 * ============================================================
 * RANK MATH CALLBACKS - COMBO
 * ============================================================
 */

function tfsc_combo_rankmath_title(
    $title
) {

    $seo =
        tfsc_get_combo_seo();

    if (
        ! is_array( $seo ) ||
        empty( $seo['title'] )
    ) {
        return $title;
    }

    return $seo['title'];
}


function tfsc_combo_rankmath_description(
    $description
) {

    $seo =
        tfsc_get_combo_seo();

    if (
        ! is_array( $seo ) ||
        empty(
            $seo['description']
        )
    ) {
        return $description;
    }

    return $seo['description'];
}


function tfsc_combo_rankmath_canonical(
    $canonical
) {

    $seo =
        tfsc_get_combo_seo();

    if (
        ! is_array( $seo ) ||
        empty(
            $seo['canonical']
        )
    ) {
        return $canonical;
    }

    return $seo['canonical'];
}


function tfsc_combo_rankmath_robots(
    $robots
) {

    $seo =
        tfsc_get_combo_seo();

    if (
        ! is_array( $seo )
    ) {
        return $robots;
    }

    if (
        ! is_array( $robots )
    ) {
        $robots = [];
    }

    if (
        ! empty(
            $seo['index']
        )
    ) {

        $robots['index'] =
            'index';

        $robots['follow'] =
            'follow';

    } else {

        $robots['index'] =
            'noindex';

        $robots['follow'] =
            'follow';
    }

    return $robots;
}


/**
 * ============================================================
 * RANK MATH CALLBACK - NATIVE CANONICAL
 * ============================================================
 */

function tfsc_native_rankmath_canonical(
    $canonical
) {

    if (
        ! tfsc_native_canonical_is_target()
    ) {
        return $canonical;
    }

    $combo_canonical =
        tfsc_native_canonical_build_url();

    if (
        '' === $combo_canonical
    ) {
        return $canonical;
    }

    return $combo_canonical;
}


/**
 * ============================================================
 * RANK MATH CALLBACKS - FILTER URLS
 * ============================================================
 */

function tfsc_vacancy_filter_rankmath_robots(
    $robots
) {

    if (
        ! tfsc_vacancy_filter_seo_is_active()
    ) {
        return $robots;
    }

    if (
        ! is_array( $robots )
    ) {
        $robots = [];
    }

    $robots['index'] =
        'noindex';

    $robots['follow'] =
        'follow';

    return $robots;
}


function tfsc_vacancy_filter_rankmath_canonical(
    $canonical
) {

    if (
        ! tfsc_vacancy_filter_seo_is_active()
    ) {
        return $canonical;
    }

    $clean =
        tfsc_vacancy_filter_clean_canonical();

    if ( '' === $clean ) {
        return $canonical;
    }

    return $clean;
}


/**
 * ============================================================
 * RANK MATH FILTERS
 * ============================================================
 *
 * Alleen de filters registreren die voor de huidige
 * request nodig zijn.
 */

add_action(
    'wp',
    function() {

        /**
         * ====================================================
         * COMBO ARCHIVE
         * ====================================================
         */

        if (
            tfsc_combo_seo_is_active()
        ) {

            add_filter(
                'rank_math/frontend/title',
                'tfsc_combo_rankmath_title',
                99
            );

            add_filter(
                'rank_math/frontend/description',
                'tfsc_combo_rankmath_description',
                99
            );

            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_combo_rankmath_canonical',
                99
            );

            add_filter(
                'rank_math/frontend/robots',
                'tfsc_combo_rankmath_robots',
                99
            );

            return;
        }


        /**
         * ====================================================
         * SEARCH & FILTER RESULTAAT-URL
         * ====================================================
         */

        if (
            tfsc_vacancy_filter_seo_is_active()
        ) {

            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_vacancy_filter_rankmath_canonical',
                99
            );

            add_filter(
                'rank_math/frontend/robots',
                'tfsc_vacancy_filter_rankmath_robots',
                99
            );

            return;
        }


        /**
         * ====================================================
         * NATIVE VACATURE TAXONOMY ARCHIVE
         * ====================================================
         */

        if (
            tfsc_native_canonical_is_target()
        ) {

            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_native_rankmath_canonical',
                99
            );
        }
    },
    20
);

/**
 * TFSC - Combo Vacancy Sitemap
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - TFSC - Combo Archive SEO
 * - Rank Math SEO
 *
 * Maakt:
 * /combo-vacatures-sitemap.xml
 *
 * Wordt automatisch toegevoegd aan:
 * /sitemap_index.xml
 *
 *
 * HUIDIGE STRATEGIE
 * ============================================================
 *
 * - Alleen gepubliceerde + open vacatures
 * - Alleen werkelijk bestaande termcombinaties
 * - Exact 2 verschillende taxonomies per combo
 * - tfsc_combo_should_index() bepaalt of de combo
 *   daadwerkelijk in de sitemap mag
 * - functienaam wordt altijd als eerste taxonomy
 *   in de URL geplaatst
 * - overige taxonomies blijven volledig dynamisch
 * - iedere combo-URL krijgt een betrouwbare lastmod
 * - sitemap-index krijgt per sitemapdeel de nieuwste lastmod
 *
 *
 * Performance:
 * - combinaties worden alleen berekend wanneer nodig
 * - URL-lijst wordt gecachet
 * - cache wordt automatisch verwijderd bij relevante wijzigingen
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if (
    ! defined(
        'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS',
        2
    );
}


if (
    ! defined(
        'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS',
        2
    );
}


/**
 * Nieuwe cache key vanwege toevoeging lastmod.
 */
if (
    ! defined(
        'TFSC_COMBO_SITEMAP_CACHE_KEY'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_CACHE_KEY',
        'tfsc_combo_sitemap_links_v4'
    );
}


if (
    ! defined(
        'TFSC_COMBO_SITEMAP_CACHE_TTL'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_CACHE_TTL',
        DAY_IN_SECONDS
    );
}


/**
 * ============================================================
 * BESCHIKBAARHEID
 * ============================================================
 */

function tfsc_combo_sitemap_is_available() {

    return (
        function_exists(
            'tfsc_get_allowed_combo_taxonomies'
        )
        &&
        function_exists(
            'tfsc_get_combo_taxonomy_match_method'
        )
        &&
        function_exists(
            'tfsc_combo_should_index'
        )
        &&
        defined(
            'TFSC_VACANCY_POST_TYPE'
        )
        &&
        defined(
            'TFSC_STATUS_TAXONOMY'
        )
        &&
        defined(
            'TFSC_OPEN_STATUS_SLUG'
        )
        &&
        defined(
            'TFSC_COMBO_BASE'
        )
    );
}


/**
 * ============================================================
 * TAXONOMY VOLGORDE
 * ============================================================
 */

function tfsc_combo_sitemap_order_taxonomies(
    array $taxonomies
) {

    $function = [];
    $others   = [];

    foreach ( $taxonomies as $taxonomy ) {

        if ( 'functienaam' === $taxonomy ) {
            $function[] = $taxonomy;
        } else {
            $others[] = $taxonomy;
        }
    }

    return array_merge(
        $function,
        $others
    );
}


/**
 * ============================================================
 * COMBO VOLGORDE
 * ============================================================
 */

function tfsc_combo_sitemap_order_combo(
    array $combo
) {

    $function = [];
    $others   = [];

    foreach ( $combo as $item ) {

        if (
            isset( $item['taxonomy'] ) &&
            'functienaam'
            === $item['taxonomy']
        ) {
            $function[] = $item;
        } else {
            $others[] = $item;
        }
    }

    return array_merge(
        $function,
        $others
    );
}


/**
 * ============================================================
 * VOLLEDIG TERM-PAD
 * ============================================================
 */

function tfsc_combo_sitemap_get_term_path(
    WP_Term $term
) {

    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );

    if ( ! $taxonomy ) {
        return [];
    }


    if (
        ! $taxonomy->hierarchical
    ) {
        return [
            $term,
        ];
    }


    $path = [];


    $ancestor_ids =
        array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        );


    foreach (
        $ancestor_ids
        as $ancestor_id
    ) {

        $ancestor =
            get_term(
                $ancestor_id,
                $term->taxonomy
            );


        if (
            $ancestor instanceof WP_Term &&
            ! is_wp_error( $ancestor )
        ) {
            $path[] = $ancestor;
        }
    }


    $path[] = $term;


    return $path;
}


/**
 * ============================================================
 * TERM → COMBO ITEM
 * ============================================================
 */

function tfsc_combo_sitemap_make_item(
    WP_Term $term
) {

    return [
        'taxonomy' =>
            $term->taxonomy,

        'term' =>
            $term,

        'path' =>
            tfsc_combo_sitemap_get_term_path(
                $term
            ),
    ];
}


/**
 * ============================================================
 * COMBO URL
 * ============================================================
 */

function tfsc_combo_sitemap_build_url(
    array $combo
) {

    if ( ! $combo ) {
        return '';
    }


    $combo =
        tfsc_combo_sitemap_order_combo(
            $combo
        );


    $segments = [];


    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['path'] ) ||
            ! is_array( $item['path'] )
        ) {
            return '';
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            function_exists(
                'tfsc_combo_taxonomy_allowed'
            )
            &&
            ! tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return '';
        }


        $segments[] =
            $taxonomy;


        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term instanceof WP_Term ||
                $term->taxonomy !== $taxonomy
            ) {
                return '';
            }


            $segments[] =
                $term->slug;
        }
    }


    if ( ! $segments ) {
        return '';
    }


    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


/**
 * ============================================================
 * POST LASTMOD
 * ============================================================
 *
 * Rank Math / XML sitemap gebruikt W3C-datetime.
 *
 * We nemen post_modified_gmt van de vacature.
 */

function tfsc_combo_sitemap_get_post_lastmod(
    $post_id
) {

    $modified_gmt =
        get_post_field(
            'post_modified_gmt',
            $post_id
        );


    if (
        ! $modified_gmt ||
        '0000-00-00 00:00:00'
        === $modified_gmt
    ) {
        return '';
    }


    $timestamp =
        strtotime(
            $modified_gmt . ' GMT'
        );


    if ( ! $timestamp ) {
        return '';
    }


    return gmdate(
        'c',
        $timestamp
    );
}


/**
 * ============================================================
 * NIEUWSTE LASTMOD
 * ============================================================
 */

function tfsc_combo_sitemap_newest_lastmod(
    $current,
    $candidate
) {

    if ( ! $candidate ) {
        return $current;
    }


    if ( ! $current ) {
        return $candidate;
    }


    $current_time =
        strtotime(
            $current
        );


    $candidate_time =
        strtotime(
            $candidate
        );


    if (
        ! $candidate_time
    ) {
        return $current;
    }


    if (
        ! $current_time ||
        $candidate_time > $current_time
    ) {
        return $candidate;
    }


    return $current;
}


/**
 * ============================================================
 * TAXONOMY TERMS VAN ÉÉN VACATURE
 * ============================================================
 */

function tfsc_combo_sitemap_get_post_dimensions(
    $post_id,
    array $taxonomies
) {

    $dimensions = [];


    foreach (
        $taxonomies
        as $taxonomy
    ) {

        $terms =
            get_the_terms(
                $post_id,
                $taxonomy
            );


        if (
            ! is_array( $terms ) ||
            ! $terms
        ) {
            continue;
        }


        $taxonomy_object =
            get_taxonomy(
                $taxonomy
            );


        $match_method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        $collected = [];


        foreach (
            $terms
            as $term
        ) {

            if (
                ! $term instanceof WP_Term
            ) {
                continue;
            }


            $collected[
                $term->term_id
            ] = $term;


            if (
                $taxonomy_object &&
                $taxonomy_object->hierarchical &&
                'AND' !== $match_method
            ) {

                $ancestor_ids =
                    get_ancestors(
                        $term->term_id,
                        $taxonomy,
                        'taxonomy'
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error(
                            $ancestor
                        )
                    ) {

                        $collected[
                            $ancestor->term_id
                        ] = $ancestor;
                    }
                }
            }
        }


        if ( $collected ) {

            $dimensions[
                $taxonomy
            ] =
                array_values(
                    $collected
                );
        }
    }


    return $dimensions;
}


/**
 * ============================================================
 * COMBINATIES VAN TAXONOMIES
 * ============================================================
 */

function tfsc_combo_sitemap_dimension_sets(
    array $dimensions,
    $size
) {

    $dimensions =
        array_values(
            $dimensions
        );


    $size =
        (int) $size;


    if (
        $size < 1 ||
        count( $dimensions ) < $size
    ) {
        return [];
    }


    if ( 1 === $size ) {

        return array_map(
            static function(
                $dimension
            ) {

                return [
                    $dimension,
                ];
            },
            $dimensions
        );
    }


    $result = [];


    $first =
        array_shift(
            $dimensions
        );


    foreach (
        tfsc_combo_sitemap_dimension_sets(
            $dimensions,
            $size - 1
        )
        as $subset
    ) {

        array_unshift(
            $subset,
            $first
        );


        $result[] =
            $subset;
    }


    foreach (
        tfsc_combo_sitemap_dimension_sets(
            $dimensions,
            $size
        )
        as $subset
    ) {

        $result[] =
            $subset;
    }


    return $result;
}


/**
 * ============================================================
 * TERM PRODUCTEN
 * ============================================================
 */

function tfsc_combo_sitemap_term_products(
    array $taxonomy_set,
    array $dimensions
) {

    $taxonomy_set =
        tfsc_combo_sitemap_order_taxonomies(
            $taxonomy_set
        );


    $products = [
        [],
    ];


    foreach (
        $taxonomy_set
        as $taxonomy
    ) {

        if (
            empty(
                $dimensions[
                    $taxonomy
                ]
            )
        ) {
            return [];
        }


        $next = [];


        foreach (
            $products
            as $product
        ) {

            foreach (
                $dimensions[
                    $taxonomy
                ]
                as $term
            ) {

                if (
                    ! $term instanceof WP_Term
                ) {
                    continue;
                }


                $new_product =
                    $product;


                $new_product[] =
                    tfsc_combo_sitemap_make_item(
                        $term
                    );


                $next[] =
                    $new_product;
            }
        }


        $products =
            $next;
    }


    return $products;
}


/**
 * ============================================================
 * SITEMAP LINKS GENEREREN
 * ============================================================
 */

function tfsc_combo_sitemap_generate_links() {

    if (
        ! tfsc_combo_sitemap_is_available()
    ) {
        return [];
    }


    $cached =
        get_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY
        );


    if (
        is_array( $cached )
    ) {
        return $cached;
    }


    $taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if ( ! $taxonomies ) {
        return [];
    }


    $taxonomies =
        tfsc_combo_sitemap_order_taxonomies(
            $taxonomies
        );


    /**
     * Alleen gepubliceerde + open vacatures.
     *
     * We halen volledige WP_Post objecten op,
     * zodat modified-datum direct beschikbaar is.
     */
    $posts =
        get_posts(
            [
                'post_type' =>
                    TFSC_VACANCY_POST_TYPE,

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    -1,

                'no_found_rows' =>
                    true,

                'orderby' =>
                    'ID',

                'order' =>
                    'ASC',

                'tax_query' => [
                    [
                        'taxonomy' =>
                            TFSC_STATUS_TAXONOMY,

                        'field' =>
                            'slug',

                        'terms' => [
                            TFSC_OPEN_STATUS_SLUG,
                        ],

                        'operator' =>
                            'IN',

                        'include_children' =>
                            false,
                    ],
                ],
            ]
        );


    if ( ! $posts ) {

        set_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            [],
            TFSC_COMBO_SITEMAP_CACHE_TTL
        );


        return [];
    }


    $links = [];


    foreach (
        $posts
        as $post
    ) {

        if (
            ! $post instanceof WP_Post
        ) {
            continue;
        }


        $post_id =
            (int) $post->ID;


        $post_lastmod =
            tfsc_combo_sitemap_get_post_lastmod(
                $post_id
            );


        $dimensions =
            tfsc_combo_sitemap_get_post_dimensions(
                $post_id,
                $taxonomies
            );


        if ( ! $dimensions ) {
            continue;
        }


        $ordered_dimensions = [];


        foreach (
            $taxonomies
            as $taxonomy
        ) {

            if (
                isset(
                    $dimensions[
                        $taxonomy
                    ]
                )
            ) {

                $ordered_dimensions[
                    $taxonomy
                ] =
                    $dimensions[
                        $taxonomy
                    ];
            }
        }


        $dimensions =
            $ordered_dimensions;


        $taxonomy_names =
            array_keys(
                $dimensions
            );


        $min =
            max(
                2,
                (int)
                TFSC_COMBO_SITEMAP_MIN_DIMENSIONS
            );


        $max =
            min(
                count(
                    $taxonomy_names
                ),
                max(
                    $min,
                    (int)
                    TFSC_COMBO_SITEMAP_MAX_DIMENSIONS
                )
            );


        if ( $max < $min ) {
            continue;
        }


        for (
            $size = $min;
            $size <= $max;
            $size++
        ) {

            $dimension_sets =
                tfsc_combo_sitemap_dimension_sets(
                    $taxonomy_names,
                    $size
                );


            foreach (
                $dimension_sets
                as $taxonomy_set
            ) {

                $taxonomy_set =
                    tfsc_combo_sitemap_order_taxonomies(
                        $taxonomy_set
                    );


                $products =
                    tfsc_combo_sitemap_term_products(
                        $taxonomy_set,
                        $dimensions
                    );


                foreach (
                    $products
                    as $combo
                ) {

                    $combo =
                        tfsc_combo_sitemap_order_combo(
                            $combo
                        );


                    if (
                        ! tfsc_combo_should_index(
                            $combo
                        )
                    ) {
                        continue;
                    }


                    $url =
                        tfsc_combo_sitemap_build_url(
                            $combo
                        );


                    if ( '' === $url ) {
                        continue;
                    }


                    /**
                     * Nieuwe combo.
                     */
                    if (
                        ! isset(
                            $links[
                                $url
                            ]
                        )
                    ) {

                        $links[
                            $url
                        ] = [
                            'loc' =>
                                $url,

                            'lastmod' =>
                                $post_lastmod,
                        ];

                        continue;
                    }


                    /**
                     * Bestaande combo:
                     *
                     * meerdere vacatures kunnen dezelfde
                     * combinatie ondersteunen.
                     *
                     * Bewaar dan de nieuwste wijzigingsdatum.
                     */
                    $links[
                        $url
                    ][
                        'lastmod'
                    ] =
                        tfsc_combo_sitemap_newest_lastmod(
                            isset(
                                $links[
                                    $url
                                ][
                                    'lastmod'
                                ]
                            )
                                ?
                                $links[
                                    $url
                                ][
                                    'lastmod'
                                ]
                                :
                                '',

                            $post_lastmod
                        );
                }
            }
        }
    }


    ksort(
        $links,
        SORT_STRING
    );


    $links =
        array_values(
            $links
        );


    set_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY,
        $links,
        TFSC_COMBO_SITEMAP_CACHE_TTL
    );


    return $links;
}


/**
 * ============================================================
 * CACHE LEGEN
 * ============================================================
 */

function tfsc_combo_sitemap_flush_cache() {

    delete_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY
    );


    delete_transient(
        'tfsc_combo_sitemap_links_v1'
    );

    delete_transient(
        'tfsc_combo_sitemap_links_v2'
    );

    delete_transient(
        'tfsc_combo_sitemap_links_v3'
    );


    if (
        class_exists(
            '\RankMath\Sitemap\Cache'
        )
        &&
        method_exists(
            '\RankMath\Sitemap\Cache',
            'invalidate_storage'
        )
    ) {

        \RankMath\Sitemap\Cache::invalidate_storage(
            'combo-vacatures'
        );
    }
}


