         */

        if (
            tfsc_native_canonical_is_target()
        ) {

            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_native_rankmath_canonical',
                99
            );
        }
    },
    20
);

/**
 * TFSC - Combo Archive URLs
 *
 * Centrale URL-builder voor alle TFSC vacature-combo-archives.
 *
 * Doel:
 * - één plek voor alle uitgaande combo-URL's;
 * - functienaam altijd als eerste taxonomy;
 * - ondersteuning voor hiërarchische taxonomies;
 * - ondersteuning voor pagination;
 * - ondersteuning voor native term → combo URL;
 * - later hergebruiken door:
 *      - SEO canonicals
 *      - sitemap
 *      - Elementor Post Terms
 *      - interne links
 *
 * Deze snippet:
 * - doet GEEN rewrites;
 * - verandert GEEN queries;
 * - verandert GEEN canonicals;
 * - verandert GEEN Elementor-links;
 * - genereert alleen URL's wanneer een andere snippet
 *   expliciet een van deze functies aanroept.
 */


/**
 * ============================================================
 * FALLBACK CONFIG
 * ============================================================
 *
 * Normaal worden deze constants al door andere TFSC-snippets
 * gedefinieerd.
 *
 * De fallbacks voorkomen afhankelijkheid van snippet-load-order.
 */

if ( ! defined( 'TFSC_COMBO_BASE' ) ) {
    define(
        'TFSC_COMBO_BASE',
        'vacatures'
    );
}

if ( ! defined( 'TFSC_VACANCY_POST_TYPE' ) ) {
    define(
        'TFSC_VACANCY_POST_TYPE',
        'vacature'
    );
}

if ( ! defined( 'TFSC_STATUS_TAXONOMY' ) ) {
    define(
        'TFSC_STATUS_TAXONOMY',
        'vac_status'
    );
}

if ( ! defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) ) {
    define(
        'TFSC_COMBO_FUNCTION_TAXONOMY',
        'functienaam'
    );
}

if ( ! defined( 'TFSC_COMBO_DEFAULT_FUNCTION_SLUG' ) ) {
    define(
        'TFSC_COMBO_DEFAULT_FUNCTION_SLUG',
        'field-service-engineer'
    );
}


/**
 * ============================================================
 * TAXONOMY TOEGESTAAN VOOR COMBO?
 * ============================================================
 *
 * Gebruikt bij voorkeur de centrale functie uit:
 *
 * TFSC - Volledig dynamische vacature-archieven
 *
 * Er zit alleen een veilige fallback in voor situaties waarin
 * die snippet nog niet geladen is.
 */

function tfsc_combo_url_taxonomy_allowed(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );

    if ( '' === $taxonomy ) {
        return false;
    }

    if (
        TFSC_STATUS_TAXONOMY
        === $taxonomy
    ) {
        return false;
    }


    /**
     * Centrale bestaande combo-logica gebruiken.
     */
    if (
        function_exists(
            'tfsc_combo_taxonomy_allowed'
        )
    ) {
        return (bool)
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            );
    }


    /**
     * Fallback.
     */
    $taxonomy_object =
        get_taxonomy(
            $taxonomy
        );

    if ( ! $taxonomy_object ) {
        return false;
    }

    if (
        empty(
            $taxonomy_object->publicly_queryable
        )
        &&
        empty(
            $taxonomy_object->public
        )
    ) {
        return false;
    }


    $post_types =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE
        );


    return in_array(
        $taxonomy,
        $post_types,
        true
    );
}


/**
 * ============================================================
 * VOLLEDIG PAD VAN EEN TERM
 * ============================================================
 *
 * Niet-hiërarchisch:
 *
 * elektrotechniek
 *
 * →
 *
 * [
 *     elektrotechniek
 * ]
 *
 *
 * Hiërarchisch:
 *
 * Leiden
 *
 * →
 *
 * [
 *     Nederland,
 *     Zuid-Holland,
 *     Leiden
 * ]
 */

function tfsc_combo_url_get_term_path(
    WP_Term $term
) {

    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );

    if ( ! $taxonomy ) {
        return [];
    }


    if (
        ! tfsc_combo_url_taxonomy_allowed(
            $term->taxonomy
        )
    ) {
        return [];
    }


    /**
     * Niet-hiërarchische taxonomy.
     */
    if (
        ! $taxonomy->hierarchical
    ) {
        return [
            $term,
        ];
    }


    $path = [];


    $ancestor_ids =
        array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        );


    foreach (
        $ancestor_ids
        as $ancestor_id
    ) {

        $ancestor =
            get_term(
                $ancestor_id,
                $term->taxonomy
            );


        if (
            $ancestor instanceof WP_Term
            &&
            ! is_wp_error(
                $ancestor
            )
        ) {
            $path[] =
                $ancestor;
        }
    }


    $path[] =
        $term;


    return $path;
}


/**
 * ============================================================
 * STANDAARD FUNCTIENAAM
 * ============================================================
 *
 * Wordt gebruikt wanneer we bijvoorbeeld een native archive
 * van Elektrotechniek naar een combo archive sturen:
 *
 * /kennisgebied/elektrotechniek/
 *
 * →
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 */

function tfsc_combo_url_get_default_function_term() {

    $term =
        get_term_by(
            'slug',
            TFSC_COMBO_DEFAULT_FUNCTION_SLUG,
            TFSC_COMBO_FUNCTION_TAXONOMY
        );


    if (
        ! $term instanceof WP_Term
        ||
        is_wp_error(
            $term
        )
    ) {
        return false;
    }


    return $term;
}


/**
 * ============================================================
 * COMBO-ITEM MAKEN VAN EEN TERM
 * ============================================================
 *
 * Maakt dezelfde datastructuur die de centrale URL-builder
 * gebruikt.
 */

function tfsc_combo_url_create_item(
    WP_Term $term
) {

    if (
        ! tfsc_combo_url_taxonomy_allowed(
            $term->taxonomy
        )
    ) {
        return false;
    }


    $path =
        tfsc_combo_url_get_term_path(
            $term
        );


    if ( ! $path ) {
        return false;
    }


    return [
        'taxonomy' =>
            $term->taxonomy,

        'term' =>
            $term,

        'path' =>
            $path,
    ];
}


/**
 * ============================================================
 * COMBO VOLGORDE NORMALISEREN
 * ============================================================
 *
 * Belangrijk:
 *
 * functienaam komt ALTIJD eerst.
 *
 * De volgorde van alle overige taxonomies blijft behouden.
 *
 * Hierdoor gebruiken:
 *
 * - sitemap
 * - canonical
 * - Elementor-links
 * - interne links
 *
 * allemaal dezelfde hoofdstructuur.
 */

function tfsc_combo_url_normalize_combo(
    array $combo
) {

    $function_items = [];
    $other_items    = [];


    foreach (
        $combo
        as $item
    ) {

        if (
            ! is_array(
                $item
            )
            ||
            empty(
                $item['taxonomy']
            )
        ) {
            continue;
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            '' === $taxonomy
            ||
            ! tfsc_combo_url_taxonomy_allowed(
                $taxonomy
            )
        ) {
            continue;
        }


        $item['taxonomy'] =
            $taxonomy;


        if (
            TFSC_COMBO_FUNCTION_TAXONOMY
            === $taxonomy
        ) {

            $function_items[] =
                $item;

        } else {

            $other_items[] =
                $item;
        }
    }


    return array_merge(
        $function_items,
        $other_items
    );
}


/**
 * ============================================================
 * CENTRALE COMBO URL-BUILDER
 * ============================================================
 *
 * Dit wordt uiteindelijk de ENIGE functie die een volledige
 * combo-archive URL daadwerkelijk samenstelt.
 *
 *
 * Verwachte structuur:
 *
 * [
 *     [
 *         'taxonomy' => 'functienaam',
 *         'term'     => WP_Term,
 *         'path'     => [ WP_Term ],
 *     ],
 *     [
 *         'taxonomy' => 'locatie',
 *         'term'     => WP_Term,
 *         'path'     => [
 *             Nederland,
 *             Zuid-Holland,
 *             Leiden
 *         ],
 *     ],
 * ]
 */

function tfsc_build_combo_url(
    array $combo,
    $paged = 1
) {

    $combo =
        tfsc_combo_url_normalize_combo(
            $combo
        );


    if ( ! $combo ) {
        return '';
    }


    $segments = [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['path']
            )
            ||
            ! is_array(
                $item['path']
            )
        ) {
            return '';
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            '' === $taxonomy
            ||
            ! tfsc_combo_url_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return '';
        }


        $segments[] =
            $taxonomy;


        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term instanceof WP_Term
                ||
                $term->taxonomy
                    !==
                    $taxonomy
            ) {
                return '';
            }


            $slug =
                trim(
                    (string)
                    $term->slug
                );


            if ( '' === $slug ) {
                return '';
            }


            $segments[] =
                $slug;
        }
    }


    if ( ! $segments ) {
        return '';
    }


    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    $url =
        trailingslashit(
            home_url(
                '/' . $path
            )
        );


    /**
     * Pagination.
     */
    $paged =
        max(
            1,
            (int) $paged
        );


    if ( $paged > 1 ) {

        $url =
            trailingslashit(
                $url
                .
                'page/'
                .
                $paged
        );
    }


    return $url;
}


/**
 * ============================================================
 * TERM → COMBO URL
 * ============================================================
 *
 * Centrale helper voor één taxonomy-term.
 *
 *
 * FUNCTIENAAM:
 *
 * Commissioning Engineer
 *
 * →
 *
 * /vacatures/functienaam/commissioning-engineer/
 *
 *
 * ANDERE TAXONOMY:
 *
 * Elektrotechniek
 *
 * →
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * kennisgebied/elektrotechniek/
 *
 *
 * Optioneel kan een andere functienaam worden meegegeven.
 * Dat gaan we later gebruiken bij vacature Post Terms.
 */

function tfsc_build_combo_url_for_term(
    WP_Term $term,
    $function_term = null,
    $paged = 1
) {

    if (
        ! tfsc_combo_url_taxonomy_allowed(
            $term->taxonomy
        )
    ) {
        return '';
    }


    /**
     * ========================================================
     * DE TERM IS ZELF EEN FUNCTIENAAM
     * ========================================================
     *
     * Dan gebruiken we alleen deze functienaam.
     *
     * Dus:
     *
     * Commissioning Engineer
     *
     * NIET:
     *
     * Field Service Engineer + Commissioning Engineer
     */

    if (
        TFSC_COMBO_FUNCTION_TAXONOMY
        === $term->taxonomy
    ) {

        $item =
            tfsc_combo_url_create_item(
                $term
            );


        if ( ! $item ) {
            return '';
        }


        return tfsc_build_combo_url(
            [
                $item,
            ],
            $paged
        );
    }


    /**
     * ========================================================
     * ANDERE TAXONOMY
     * ========================================================
     *
     * Geen functienaam meegegeven?
     *
     * Dan gebruiken we de standaard:
     *
     * Field Service Engineer.
     */

    if (
        ! $function_term
        instanceof WP_Term
    ) {

        $function_term =
            tfsc_combo_url_get_default_function_term();
    }


    if (
        ! $function_term
        instanceof WP_Term
        ||
        TFSC_COMBO_FUNCTION_TAXONOMY
            !==
            $function_term->taxonomy
    ) {
        return '';
    }


    $function_item =
        tfsc_combo_url_create_item(
            $function_term
        );


    $term_item =
        tfsc_combo_url_create_item(
            $term
        );


    if (
        ! $function_item
        ||
        ! $term_item
    ) {
        return '';
    }


    return tfsc_build_combo_url(
        [
            $function_item,
            $term_item,
        ],
        $paged
    );
}

/**
 * TFSC - Combo Archive SEO + Native Archive Canonicals + Filter SEO
 *
 * Vereist:
 * - TFSC - Combo Archive URLs
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * Regelt:
 *
 * COMBO ARCHIVES
 * - SEO title
 * - Meta description
 * - Canonical via centrale URL-builder
 * - Robots
 * - Centrale indexeringslogica voor SEO + sitemap
 *
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * - blijven bereikbaar
 * - robots blijven door Rank Math / WordPress bepaald
 * - canonical via centrale URL-builder
 *
 * SEARCH & FILTER URLS OP /vacatures/
 * - noindex, follow
 * - canonical naar schone /vacatures/
 */


/**
 * ============================================================
 * SEO CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {
    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}

if ( ! defined( 'TFSC_COMBO_SEO_MAX_TAXONOMIES' ) ) {
    define(
        'TFSC_COMBO_SEO_MAX_TAXONOMIES',
        3
    );
}


/**
 * ============================================================
 * GELDIG COMBO ARCHIVE?
 * ============================================================
 */

function tfsc_combo_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }

    if (
        ! function_exists( 'tfsc_is_combo_archive' ) ||
        ! function_exists( 'tfsc_get_combo_archive' ) ||
        ! function_exists( 'tfsc_build_combo_url' )
    ) {
        return false;
    }

    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }

    return false !== tfsc_get_combo_archive();
}


/**
 * ============================================================
 * COMBO ITEMS
 * ============================================================
 *
 * Alleen voor title/description.
 *
 * Dezelfde normalisatie als de centrale URL-builder wordt
 * gebruikt zodat functienaam vooraan staat.
 */

function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];

    if ( $resolved ) {
        return $items;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return [];
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    if (
        function_exists(
            'tfsc_urlcore_normalize_combo'
        )
    ) {
        $combo =
            tfsc_urlcore_normalize_combo(
                $combo
            );
    }

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $name =
            trim(
                wp_strip_all_tags(
                    $item['term']->name
                )
            );

        if ( '' === $name ) {
            continue;
        }

        $items[] = [
            'taxonomy' =>
                (string) $item['taxonomy'],

            'term_id' =>
                (int) $item['term']->term_id,

            'slug' =>
                (string) $item['term']->slug,

            'name' =>
                $name,
        ];
    }

    return $items;
}


/**
 * ============================================================
 * AANTAL VERSCHILLENDE TAXONOMIES
 * ============================================================
 */

function tfsc_combo_count_taxonomies(
    $combo = null
) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return 0;
        }

        $combo =
            tfsc_get_combo_archive();
    }

    if ( ! is_array( $combo ) ) {
        return 0;
    }

    $taxonomies = [];

    foreach ( $combo as $item ) {

        if ( empty( $item['taxonomy'] ) ) {
            continue;
        }

        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );

        if ( '' === $taxonomy ) {
            continue;
        }

        $taxonomies[
            $taxonomy
        ] = true;
    }

    return count(
        $taxonomies
    );
}


/**
 * ============================================================
 * HEEFT COMBO EEN FUNCTIENAAM?
 * ============================================================
 */

function tfsc_combo_has_function_name(
    $combo = null
) {

    if ( null === $combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return false;
        }

        $combo =
            tfsc_get_combo_archive();
    }

    if ( ! is_array( $combo ) ) {
        return false;
    }

    $function_taxonomy =
        defined(
            'TFSC_COMBO_FUNCTION_TAXONOMY'
        )
            ? TFSC_COMBO_FUNCTION_TAXONOMY
            : 'functienaam';

    foreach ( $combo as $item ) {

        if (
            ! empty( $item['taxonomy'] ) &&
            $function_taxonomy === $item['taxonomy']
        ) {
            return true;
        }
    }

    return false;
}


/**
 * ============================================================
 * RESULTAAT-AANTAL HUIDIGE FRONTEND COMBO
 * ============================================================
 */

function tfsc_combo_get_current_result_count() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return 0;
    }

    global $wp_query;

    if ( ! $wp_query instanceof WP_Query ) {
        return 0;
    }

    return max(
        0,
        (int) $wp_query->found_posts
    );
}


/**
 * ============================================================
 * CENTRALE INDEXERINGSSTATUS
 * ============================================================
 *
 * Regels:
 *
 * - functienaam verplicht
 * - maximaal 3 verschillende taxonomies
 * - frontend moet minimaal 1 resultaat hebben
 *
 * Sitemap-combo's worden vanuit bestaande open vacatures
 * opgebouwd en krijgen daarom geen extra result-query.
 */

function tfsc_combo_get_index_status(
    $combo = null
) {

    $is_frontend_combo =
        null === $combo;


    if ( $is_frontend_combo ) {

        if ( ! tfsc_combo_seo_is_active() ) {

            return [
                'index'      => false,
                'reason'     => 'not_combo',
                'results'    => 0,
                'taxonomies' => 0,
            ];
        }

        $combo =
            tfsc_get_combo_archive();
    }


    if (
        ! is_array( $combo ) ||
        ! $combo
    ) {

        return [
            'index'      => false,
            'reason'     => 'invalid_combo',
            'results'    => 0,
            'taxonomies' => 0,
        ];
    }


    $taxonomy_count =
        tfsc_combo_count_taxonomies(
            $combo
        );


    if (
        $taxonomy_count >
        TFSC_COMBO_SEO_MAX_TAXONOMIES
    ) {

        return [
            'index'      => false,
            'reason'     => 'too_many_taxonomies',
            'results'    => null,
            'taxonomies' => $taxonomy_count,
        ];
    }


    if (
        ! tfsc_combo_has_function_name(
            $combo
        )
    ) {

        return [
            'index'      => false,
            'reason'     => 'no_function_name',
            'results'    => null,
            'taxonomies' => $taxonomy_count,
        ];
    }


    if ( $is_frontend_combo ) {

        $result_count =
            tfsc_combo_get_current_result_count();


        if ( $result_count < 1 ) {

            return [
                'index'      => false,
                'reason'     => 'no_results',
                'results'    => $result_count,
                'taxonomies' => $taxonomy_count,
            ];
        }


        return [
            'index'      => true,
            'reason'     => 'valid_function_combo',
            'results'    => $result_count,
            'taxonomies' => $taxonomy_count,
        ];
    }


    return [
        'index'      => true,
        'reason'     => 'valid_sitemap_function_combo',
        'results'    => null,
        'taxonomies' => $taxonomy_count,
    ];
}


/**
 * ============================================================
 * CENTRALE TRUE/FALSE INDEXERINGSFUNCTIE
 * ============================================================
 *
 * Wordt ook door de sitemap gebruikt.
 */

function tfsc_combo_should_index(
    $combo = null
) {

    $status =
        tfsc_combo_get_index_status(
            $combo
        );

    return ! empty(
        $status['index']
    );
}


/**
 * ============================================================
 * SEO TITLE COMBO ARCHIVES
 * ============================================================
 */

function tfsc_combo_seo_build_title() {

    $items =
        tfsc_combo_seo_get_items();

    if ( ! $items ) {
        return '';
    }

    $function_taxonomy =
        defined(
            'TFSC_COMBO_FUNCTION_TAXONOMY'
        )
            ? TFSC_COMBO_FUNCTION_TAXONOMY
            : 'functienaam';

    $function_names = [];
    $other_names    = [];


    foreach ( $items as $item ) {

        if (
            $function_taxonomy
            ===
            $item['taxonomy']
        ) {

            if (
                ! in_array(
                    $item['name'],
                    $function_names,
                    true
                )
            ) {
                $function_names[] =
                    $item['name'];
            }

            continue;
        }


        if (
            ! in_array(
                $item['name'],
                $other_names,
                true
            )
        ) {
            $other_names[] =
                $item['name'];
        }
    }


    if ( $function_names ) {

        $title =
            implode(
                ' ',
                $function_names
            )
            .
            ' vacatures';


        if ( $other_names ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $other_names
                );
        }


        return trim(
            $title
        );
    }


    if ( ! $other_names ) {
        return '';
    }


    return trim(
        'Field Service vacatures '
        .
        implode(
            ' ',
            $other_names
        )
    );
}


/**
 * ============================================================
 * META DESCRIPTION COMBO ARCHIVES
 * ============================================================
 */

function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();

    if ( '' === $title ) {
        return '';
    }

    return sprintf(
        '%s bij %s.',
        $title,
        TFSC_COMBO_SEO_BRAND
    );
}


/**
 * ============================================================
 * CANONICAL COMBO ARCHIVES
 * ============================================================
 *
 * SEO bouwt zelf GEEN combo URL meer.
 *
 * Alles loopt via:
 *
 * tfsc_build_combo_url()
 */

function tfsc_combo_seo_build_canonical() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return '';
    }

    if (
        ! function_exists(
            'tfsc_build_combo_url'
        )
    ) {
        return '';
    }

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return '';
    }

    $paged =
        max(
            1,
            (int)
            get_query_var(
                'paged'
            )
        );

    return tfsc_build_combo_url(
        $combo,
        $paged
    );
}


/**
 * ============================================================
 * CENTRAAL SEO OBJECT COMBO ARCHIVES
 * ============================================================
 */

function tfsc_get_combo_seo() {

    static $resolved = false;
    static $seo      = false;

    if ( $resolved ) {
        return $seo;
    }

    $resolved = true;


    if ( ! tfsc_combo_seo_is_active() ) {
        return false;
    }


    $title =
        tfsc_combo_seo_build_title();

    if ( '' === $title ) {
        return false;
    }


    $index_status =
        tfsc_combo_get_index_status();


    $seo = [
        'title' =>
            $title,

        'description' =>
            tfsc_combo_seo_build_description(),

        'canonical' =>
            tfsc_combo_seo_build_canonical(),

        'index' =>
            ! empty(
                $index_status['index']
            ),

        'index_reason' =>
            $index_status['reason'],

        'results' =>
            $index_status['results'],

        'taxonomies' =>
            $index_status['taxonomies'],
    ];


    return $seo;
}


/**
 * ============================================================
 * NATIVE VACATURE TAXONOMY ARCHIVE?
 * ============================================================
 */

function tfsc_native_canonical_is_target() {

    if ( is_admin() ) {
        return false;
    }

    if ( ! is_tax() ) {
        return false;
    }

    if (
        function_exists(
            'tfsc_is_combo_archive'
        )
        &&
        tfsc_is_combo_archive()
    ) {
        return false;
    }

    $term =
        get_queried_object();

    if (
        ! $term instanceof WP_Term
    ) {
        return false;
    }


    /**
     * Centrale URL-core is leidend.
     */
    if (
        function_exists(
            'tfsc_urlcore_taxonomy_allowed'
        )
    ) {
        return tfsc_urlcore_taxonomy_allowed(
            $term->taxonomy
        );
    }


    /**
     * Compatibiliteitsfallback.
     */
    if (
        function_exists(
            'tfsc_combo_taxonomy_allowed'
        )
    ) {
        return tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        );
    }


    return false;
}


/**
 * ============================================================
 * NATIVE ARCHIVE → COMBO CANONICAL
 * ============================================================
 *
 * Geen eigen term-pad of URL-logica meer.
 *
 * Voorbeelden:
 *
 * /functienaam/field-service-engineer/
 *
 * →
 *
 * /vacatures/functienaam/field-service-engineer/
 *
 *
 * /functie-inhoud/inbedrijfstellen/
 *
 * →
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * functie-inhoud/inbedrijfstellen/
 */

function tfsc_native_canonical_build_url() {

    if (
        ! tfsc_native_canonical_is_target()
    ) {
        return '';
    }

    if (
        ! function_exists(
            'tfsc_build_combo_url_for_term'
        )
    ) {
        return '';
    }

    $native_term =
        get_queried_object();

    if (
        ! $native_term instanceof WP_Term
    ) {
        return '';
    }

    $paged =
        max(
            1,
            (int)
            get_query_var(
                'paged'
            )
        );

    return tfsc_build_combo_url_for_term(
        $native_term,
        null,
        $paged
    );
}


/**
 * ============================================================
 * SEARCH & FILTER URL HERKENNEN
 * ============================================================
 *
 * Alleen op het echte vacature post type archive.
 *
 * Queryparameters die met "_" beginnen worden beschouwd
 * als Search & Filter parameters.
 */

function tfsc_vacancy_filter_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }


    if (
        function_exists(
            'tfsc_is_combo_archive'
        )
        &&
        tfsc_is_combo_archive()
    ) {
        return false;
    }


    if (
        ! defined(
            'TFSC_VACANCY_POST_TYPE'
        )
    ) {
        return false;
    }


    if (
        ! is_post_type_archive(
            TFSC_VACANCY_POST_TYPE
        )
    ) {
        return false;
    }


    if ( empty( $_GET ) ) {
        return false;
    }


    foreach (
        array_keys( $_GET )
        as $key
    ) {

        $key =
            (string) $key;


        if (
            '' !== $key
            &&
            '_' === $key[0]
        ) {
            return true;
        }
    }


    return false;
}


/**
 * ============================================================
 * SCHONE VACATURE CANONICAL
 * ============================================================
 */

function tfsc_vacancy_filter_clean_canonical() {

    if (
        ! defined(
            'TFSC_VACANCY_POST_TYPE'
        )
    ) {
        return '';
    }


    $url =
        get_post_type_archive_link(
            TFSC_VACANCY_POST_TYPE
        );


    if ( ! $url ) {
        return '';
    }


    return trailingslashit(
        $url
    );
}


/**
 * ============================================================
 * RANK MATH CALLBACKS - COMBO
 * ============================================================
 */

function tfsc_combo_rankmath_title(
    $title
) {

    $seo =
        tfsc_get_combo_seo();


    if (
        ! is_array( $seo ) ||
        empty( $seo['title'] )
    ) {
