/**
 * TFSC - Combo Archive URLs
 *
 * Centrale data- en URL-supplier voor vacature combo archives.
 *
 * MIGRATIEVEILIG:
 * - kan naast de huidige Vac Combo Archives Base Code draaien;
 * - declareert GEEN bestaande Base Code functies opnieuw;
 * - verandert zelf GEEN rewrites;
 * - verandert zelf GEEN queries;
 * - verandert zelf GEEN canonicals;
 *
 * Uiteindelijk worden Base Code, SEO, Sitemap en interne links
 * allemaal consumers van deze centrale supplier.
 */


/**
 * ============================================================
 * CENTRALE CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_BASE' ) ) {
    define(
        'TFSC_COMBO_BASE',
        'vacatures'
    );
}

if ( ! defined( 'TFSC_VACANCY_POST_TYPE' ) ) {
    define(
        'TFSC_VACANCY_POST_TYPE',
        'vacature'
    );
}

if ( ! defined( 'TFSC_STATUS_TAXONOMY' ) ) {
    define(
        'TFSC_STATUS_TAXONOMY',
        'vac_status'
    );
}

if ( ! defined( 'TFSC_OPEN_STATUS_SLUG' ) ) {
    define(
        'TFSC_OPEN_STATUS_SLUG',
        'open'
    );
}

if ( ! defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) ) {
    define(
        'TFSC_COMBO_FUNCTION_TAXONOMY',
        'functienaam'
    );
}

if ( ! defined( 'TFSC_COMBO_DEFAULT_FUNCTION_SLUG' ) ) {
    define(
        'TFSC_COMBO_DEFAULT_FUNCTION_SLUG',
        'field-service-engineer'
    );
}


/**
 * ============================================================
 * CENTRALE TAXONOMY VALIDATIE
 * ============================================================
 *
 * LET OP:
 * bewust een nieuwe interne functienaam.
 *
 * Daardoor botst deze tijdens de migratie niet met:
 *
 * tfsc_combo_taxonomy_allowed()
 *
 * uit de huidige Base Code.
 */

function tfsc_urlcore_taxonomy_allowed(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );

    if (
        '' === $taxonomy
        ||
        TFSC_STATUS_TAXONOMY === $taxonomy
        ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return false;
    }


    $object =
        get_taxonomy(
            $taxonomy
        );


    if ( ! $object ) {
        return false;
    }


    return (
        ! empty(
            $object->publicly_queryable
        )
        &&
        in_array(
            TFSC_VACANCY_POST_TYPE,
            (array) $object->object_type,
            true
        )
    );
}


/**
 * ============================================================
 * ALLE TOEGESTANE COMBO TAXONOMIES
 * ============================================================
 */

function tfsc_urlcore_get_allowed_taxonomies() {

    static $allowed = null;


    if ( null !== $allowed ) {
        return $allowed;
    }


    $allowed = [];


    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_urlcore_taxonomy_allowed(
                $taxonomy
            )
        ) {
            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * INKOMEND TERM-PAD OPLOSSEN
 * ============================================================
 *
 * Deze functie wordt later door de Base Code gebruikt.
 *
 * Voorbeeld:
 *
 * locatie
 * nederland
 * zuid-holland
 * leiden
 *
 * →
 *
 * [
 *     'path' => [ Nederland, Zuid-Holland, Leiden ],
 *     'term' => Leiden
 * ]
 */

function tfsc_urlcore_resolve_term_path(
    $taxonomy,
    $segments
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );


    if (
        ! tfsc_urlcore_taxonomy_allowed(
            $taxonomy
        )
    ) {
        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
        ||
        ! is_array( $segments )
        ||
        ! $segments
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if ( ! $segments ) {
        return false;
    }


    if (
        ! $tax_object->hierarchical
        &&
        1 !== count( $segments )
    ) {
        return false;
    }


    $terms     = [];
    $parent_id = 0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term instanceof WP_Term
            ||
            is_wp_error( $term )
        ) {
            return false;
        }


        if (
            $index > 0
            &&
            (int) $term->parent
                !==
                $parent_id
        ) {
            return false;
        }


        $terms[] =
            $term;


        $parent_id =
            (int) $term->term_id;
    }


    return [
        'path' =>
            $terms,

        'term' =>
            end( $terms ),
    ];
}


/**
 * ============================================================
 * UITGAAND VOLLEDIG TERM-PAD
 * ============================================================
 *
 * Leiden:
 *
 * Nederland
 * → Zuid-Holland
 * → Leiden
 */

function tfsc_urlcore_get_term_path(
    WP_Term $term
) {

    if (
        ! tfsc_urlcore_taxonomy_allowed(
            $term->taxonomy
        )
    ) {
        return [];
    }


    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );


    if ( ! $taxonomy ) {
        return [];
    }


    if (
        ! $taxonomy->hierarchical
    ) {
        return [
            $term,
        ];
    }


    $path = [];


    $ancestor_ids =
        array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        );


    foreach (
        $ancestor_ids
        as $ancestor_id
    ) {

        $ancestor =
            get_term(
                $ancestor_id,
                $term->taxonomy
            );


        if (
            ! $ancestor instanceof WP_Term
            ||
            is_wp_error( $ancestor )
        ) {
            return [];
        }


        $path[] =
            $ancestor;
    }


    $path[] =
        $term;


    return $path;
}


/**
 * ============================================================
 * TERM → COMBO ITEM
 * ============================================================
 *
 * Maakt dezelfde datastructuur als de huidige combo-parser:
 *
 * [
 *     'taxonomy' => 'locatie',
 *     'term'     => WP_Term Leiden,
 *     'path'     => [
 *         WP_Term Nederland,
 *         WP_Term Zuid-Holland,
 *         WP_Term Leiden
 *     ]
 * ]
 */

function tfsc_urlcore_create_item(
    WP_Term $term
) {

    $path =
        tfsc_urlcore_get_term_path(
            $term
        );


    if ( ! $path ) {
        return false;
    }


    return [
        'taxonomy' =>
            $term->taxonomy,

        'term' =>
            $term,

        'path' =>
            $path,
    ];
}


/**
 * ============================================================
 * STANDAARD FUNCTIENAAM
 * ============================================================
 */

function tfsc_urlcore_get_default_function_term() {

    $term =
        get_term_by(
            'slug',
            TFSC_COMBO_DEFAULT_FUNCTION_SLUG,
            TFSC_COMBO_FUNCTION_TAXONOMY
        );


    if (
        ! $term instanceof WP_Term
        ||
        is_wp_error( $term )
    ) {
        return false;
    }


    return $term;
}


/**
 * ============================================================
 * COMBO NORMALISEREN
 * ============================================================
 *
 * functienaam komt altijd eerst.
 *
 * Andere taxonomies behouden hun bestaande onderlinge
 * volgorde.
 */

function tfsc_urlcore_normalize_combo(
    array $combo
) {

    $function_items = [];
    $other_items    = [];


    foreach (
        $combo
        as $item
    ) {

        if (
            ! is_array( $item )
            ||
            empty( $item['taxonomy'] )
        ) {
            return [];
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            '' === $taxonomy
            ||
            ! tfsc_urlcore_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return [];
        }


        $item['taxonomy'] =
            $taxonomy;


        if (
            TFSC_COMBO_FUNCTION_TAXONOMY
            ===
            $taxonomy
        ) {

            $function_items[] =
                $item;

        } else {

            $other_items[] =
                $item;
        }
    }


    return array_merge(
        $function_items,
        $other_items
    );
}


/**
 * ============================================================
 * CENTRALE COMBO URL-BUILDER
 * ============================================================
 *
 * Dit is de publieke functie die andere snippets straks
 * gebruiken.
 *
 * Alle daadwerkelijke combo-URL-opbouw hoort uiteindelijk
 * via deze functie te lopen.
 */

function tfsc_build_combo_url(
    array $combo,
    $paged = 1
) {

    $combo =
        tfsc_urlcore_normalize_combo(
            $combo
        );


    if ( ! $combo ) {
        return '';
    }


    $segments = [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty( $item['taxonomy'] )
            ||
            empty( $item['path'] )
            ||
            ! is_array( $item['path'] )
        ) {
            return '';
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            ! tfsc_urlcore_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return '';
        }


        $segments[] =
            $taxonomy;


        foreach (
            $item['path']
            as $path_term
        ) {

            if (
                ! $path_term instanceof WP_Term
                ||
                $path_term->taxonomy
                    !==
                    $taxonomy
            ) {
                return '';
            }


            $slug =
                trim(
                    (string)
                    $path_term->slug
                );


            if ( '' === $slug ) {
                return '';
            }


            $segments[] =
                $slug;
        }
    }


    if ( ! $segments ) {
        return '';
    }


    $path =
        trim(
            TFSC_COMBO_BASE,
            '/'
        )
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    $url =
        trailingslashit(
            home_url(
                '/' . $path
            )
        );


    $paged =
        max(
            1,
            (int) $paged
        );


    if ( $paged > 1 ) {

        $url =
            trailingslashit(
                $url
                .
                'page/'
                .
                $paged
            );
    }


    return $url;
}


/**
 * ============================================================
 * TERM → COMBO URL
 * ============================================================
 *
 * FUNCTIENAAM
 *
 * Commissioning Engineer:
 *
 * /vacatures/functienaam/commissioning-engineer/
 *
 *
 * ANDERE TAXONOMY ZONDER EXPLICIETE FUNCTIENAAM
 *
 * Inbedrijfstellen:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * functie-inhoud/inbedrijfstellen/
 *
 *
 * ANDERE TAXONOMY MET EXPLICIETE FUNCTIENAAM
 *
 * Commissioning Engineer + Inbedrijfstellen:
 *
 * /vacatures/
 * functienaam/commissioning-engineer/
 * functie-inhoud/inbedrijfstellen/
 */

function tfsc_build_combo_url_for_term(
    WP_Term $term,
    $function_term = null,
    $paged = 1
) {

    if (
        ! tfsc_urlcore_taxonomy_allowed(
            $term->taxonomy
        )
    ) {
        return '';
    }


    /**
     * Term is zelf functienaam.
     */
    if (
        TFSC_COMBO_FUNCTION_TAXONOMY
        ===
        $term->taxonomy
    ) {

        $item =
            tfsc_urlcore_create_item(
                $term
            );


        if ( ! $item ) {
            return '';
        }


        return tfsc_build_combo_url(
            [
                $item,
            ],
            $paged
        );
    }


    /**
     * Geen functienaam meegegeven:
     * standaard Field Service Engineer.
     */
    if (
        ! $function_term instanceof WP_Term
    ) {

        $function_term =
            tfsc_urlcore_get_default_function_term();
    }


    if (
        ! $function_term instanceof WP_Term
        ||
        TFSC_COMBO_FUNCTION_TAXONOMY
            !==
            $function_term->taxonomy
    ) {
        return '';
    }


    $function_item =
        tfsc_urlcore_create_item(
            $function_term
        );


    $term_item =
        tfsc_urlcore_create_item(
            $term
        );


    if (
        ! $function_item
        ||
        ! $term_item
    ) {
        return '';
    }


    return tfsc_build_combo_url(
        [
            $function_item,
            $term_item,
        ],
        $paged
    );
}

/**
 * TFSC - Volledig dynamische vacature-archieven
 *
 * Vereist:
 * - TFSC - Combo Archive URLs
 *
 * - Virtuele combo archives onder /vacatures/...
 * - Onbeperkt aantal taxonomies/terms
 * - Verschillende taxonomies = AND
 * - Meerdere terms binnen taxonomy = OR
 * - kennisgebied = AND
 * - Alleen vac_status=open
 * - Search & Filter Pro v3 sync
 * - Elementor archive conditions
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 *
 * Centrale combo-config, taxonomy-validatie en term-padlogica
 * komen uit:
 *
 * TFSC - Combo Archive URLs
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define(
        'TFSC_SEARCH_FILTER_QUERY_ID',
        1
    );
}


/**
 * ============================================================
 * COMPATIBILITEITSLAAG NAAR URL CORE
 * ============================================================
 *
 * Deze publieke functies blijven bewust bestaan omdat andere
 * bestaande TFSC-snippets ze al gebruiken.
 *
 * De daadwerkelijke logica komt nu uit:
 *
 * TFSC - Combo Archive URLs
 */


/**
 * Taxonomy geldig voor combo archives?
 */
function tfsc_combo_taxonomy_allowed(
    $taxonomy
) {

    if (
        ! function_exists(
            'tfsc_urlcore_taxonomy_allowed'
        )
    ) {
        return false;
    }

    return tfsc_urlcore_taxonomy_allowed(
        $taxonomy
    );
}


/**
 * Alle toegestane vacature-combo-taxonomies.
 */
function tfsc_get_allowed_combo_taxonomies() {

    if (
        ! function_exists(
            'tfsc_urlcore_get_allowed_taxonomies'
        )
    ) {
        return [];
    }

    return tfsc_urlcore_get_allowed_taxonomies();
}


/**
 * Inkomend hiërarchisch term-pad oplossen.
 */
function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    if (
        ! function_exists(
            'tfsc_urlcore_resolve_term_path'
        )
    ) {
        return false;
    }

    return tfsc_urlcore_resolve_term_path(
        $taxonomy,
        $segments
    );
}


/**
 * ============================================================
 * HELPERS
 * ============================================================
 */

function tfsc_get_combo_taxonomy_match_method(
    $taxonomy
) {

    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


function tfsc_combo_status_clause() {

    return [
        'taxonomy' =>
            TFSC_STATUS_TAXONOMY,

        'field' =>
            'slug',

        'terms' =>
            [
                TFSC_OPEN_STATUS_SLUG,
            ],

        'operator' =>
            'IN',

        'include_children' =>
            false,
    ];
}


function tfsc_is_combo_archive() {

    return (bool)
        get_query_var(
            'tfsc_combo_archive'
        );
}


function tfsc_is_vacancy_seo_landing() {

    if (
        tfsc_is_combo_archive()
        &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term =
        get_queried_object();

    return (
        is_tax()
        &&
        $term instanceof WP_Term
        &&
        tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


/**
 * ============================================================
 * QUERY VARS + REWRITE
 * ============================================================
 */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        if (
            ! defined(
                'TFSC_COMBO_BASE'
            )
        ) {
            return;
        }

        /**
         * Gepagineerde combo archive.
         *
         * Moet vóór de algemene regel staan zodat /page/2/
         * niet als onderdeel van tfsc_combo_path wordt gezien.
         */
        add_rewrite_rule(
            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )
            .
            '/(.+?)/page/([0-9]+)/?$',

            'index.php'
            .
            '?tfsc_combo_archive=1'
            .
            '&tfsc_combo_path=$matches[1]'
            .
            '&paged=$matches[2]',

            'top'
        );


        /**
         * Normale combo archive.
         */
        add_rewrite_rule(
            '^'
            .
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            )
            .
            '/(.+?)/?$',

            'index.php'
            .
            '?tfsc_combo_archive=1'
            .
            '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/**
 * ============================================================
 * COMBO URL PARSEN
 * ============================================================
 */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;

    if ( $resolved ) {
        return $cache;
    }

    $resolved =
        true;

    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }

    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );

    if (
        ! $raw_path
    ) {
        return false;
    }

    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string)
                        $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );

    if (
        count( $segments ) < 2
    ) {
        return false;
    }

    $allowed =
        tfsc_get_allowed_combo_taxonomies();

    if (
        ! $allowed
    ) {
        return false;
    }

    $items = [];
    $count =
        count( $segments );
    $i =
        0;

    while (
        $i < $count
    ) {

        $taxonomy =
            sanitize_key(
                $segments[ $i ]
            );

        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }

        $i++;

        $term_segments =
            [];

        while (
            $i < $count
        ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[ $i ]
                );

            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }

            $term_segments[] =
                $segments[ $i ];

            $i++;
        }

        if (
            ! $term_segments
        ) {
            return false;
        }

        $resolved_path =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );

        if (
            ! $resolved_path
        ) {
            return false;
        }

        $items[] = [
            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved_path['term'],

            'path' =>
                $resolved_path['path'],
        ];
    }

    return $cache = (
        $items
            ? $items
            : false
    );
}


/**
 * ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================
 */

function tfsc_group_combo_terms(
    $property = 'term_id'
) {

    $combo =
        tfsc_get_combo_archive();

    if (
        ! is_array(
            $combo
        )
    ) {
        return [];
    }

    $grouped =
        [];

    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['term']
            )
            ||
            ! $item['term']
                instanceof WP_Term
        ) {
            continue;
        }

        $taxonomy =
            $item['taxonomy'];

        if (
            'name'
            ===
            $property
        ) {

            $value =
                trim(
                    $item['term']->name
                );

        } elseif (
            'slug'
            ===
            $property
        ) {

            $value =
                $item['term']->slug;

        } else {

            $value =
                (int)
                $item['term']->term_id;
        }

        if (
            '' === $value
            ||
            0 === $value
        ) {
            continue;
        }

        if (
            ! isset(
                $grouped[
                    $taxonomy
                ]
            )
        ) {
            $grouped[
                $taxonomy
            ] = [];
        }

        if (
            ! in_array(
                $value,
                $grouped[
                    $taxonomy
                ],
                true
            )
        ) {
            $grouped[
                $taxonomy
            ][] =
                $value;
        }
    }

    return $grouped;
}


/**
 * ============================================================
 * TAX QUERY
 * ============================================================
 */

function tfsc_build_combo_tax_query() {

    $grouped =
        tfsc_group_combo_terms(
            'term_id'
        );

    if (
        ! $grouped
    ) {
        return false;
    }

    $tax_query = [
        'relation' =>
            'AND',

        tfsc_combo_status_clause(),
    ];

    foreach (
        $grouped
        as $taxonomy => $term_ids
    ) {

        if (
            ! $term_ids
        ) {
            continue;
        }

        $object =
            get_taxonomy(
                $taxonomy
            );

        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );

        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            'operator' =>
                (
                    'AND' === $method
                    &&
                    count(
                        $term_ids
                    ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method
                    &&
                    $object
                    &&
                    $object->hierarchical
                ),
        ];
    }

    return $tax_query;
}


