/**
 * ============================================================
 * HEADING HTML
 * ============================================================
 */

function tfsc_combo_heading_html(
    $rows
) {

    $rows =
        array_values(
            array_filter(
                (array) $rows,
                'strlen'
            )
        );

    if (
        ! $rows
    ) {
        return '';
    }

    $html =
        '<span class="tfsc-heading">';

    foreach (
        $rows
        as $index => $row
    ) {

        $html .=
            '<span class="'
            .
            (
                0 === $index
                    ? 'tfsc-heading__main'
                    : 'tfsc-heading__row'
            )
            .
            '">'
            .
            esc_html(
                $row
            )
            .
            '</span>';
    }

    $html .=
        '</span>';

    return $html;
}


/**
 * ============================================================
 * [combo_heading]
 * ============================================================
 */

add_shortcode(
    'combo_heading',
    function() {

        /**
         * Combo archive.
         */
        if (
            tfsc_is_combo_archive()
        ) {

            $grouped =
                tfsc_group_combo_terms(
                    'name'
                );

            if (
                ! $grouped
            ) {
                return '';
            }

            $rows =
                [];

            if (
                ! empty(
                    $grouped[
                        TFSC_COMBO_FUNCTION_TAXONOMY
                    ]
                )
            ) {

                $functions =
                    $grouped[
                        TFSC_COMBO_FUNCTION_TAXONOMY
                    ];

                if (
                    1 === count(
                        $functions
                    )
                ) {

                    $rows[] =
                        $functions[0]
                        .
                        ' vacatures';

                } else {

                    $rows[] =
                        'Vacatures';

                    $rows[] =
                        implode(
                            ', ',
                            $functions
                        );
                }

                unset(
                    $grouped[
                        TFSC_COMBO_FUNCTION_TAXONOMY
                    ]
                );

            } else {

                $rows[] =
                    'Vacatures';
            }

            foreach (
                $grouped
                as $names
            ) {

                if (
                    $names
                ) {
                    $rows[] =
                        implode(
                            ', ',
                            $names
                        );
                }
            }

            return tfsc_combo_heading_html(
                $rows
            );
        }


        /**
         * Native taxonomy archive.
         */
        $term =
            get_queried_object();

        if (
            $term instanceof WP_Term
            &&
            tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {

            $title =
                get_term_meta(
                    $term->term_id,
                    'pods_archive_title',
                    true
                );

            $title =
                is_string(
                    $title
                )
                    ? trim(
                        wp_strip_all_tags(
                            $title
                        )
                    )
                    : '';

            if (
                '' === $title
            ) {

                $name =
                    trim(
                        $term->name
                    );

                if (
                    '' === $name
                ) {
                    return '';
                }

                $title =
                    $name
                    .
                    ' vacatures';
            }

            return tfsc_combo_heading_html(
                [
                    $title,
                ]
            );
        }


        /**
         * Vacature post type archive.
         */
        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {

            return tfsc_combo_heading_html(
                [
                    'Vacatures',
                ]
            );
        }

        return '';
    }
);


/**
 * ============================================================
 * [combo_term taxonomy="..."]
 * ============================================================
 */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',

                    'separator' =>
                        ' • ',
                ],
                $atts,
                'combo_term'
            );

        $taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );

        if (
            ! $taxonomy
        ) {
            return '';
        }


        /**
         * Combo archive.
         */
        if (
            tfsc_is_combo_archive()
        ) {

            $grouped =
                tfsc_group_combo_terms(
                    'name'
                );

            if (
                empty(
                    $grouped[
                        $taxonomy
                    ]
                )
            ) {
                return '';
            }

            return esc_html(
                implode(
                    (string)
                    $atts['separator'],
                    $grouped[
                        $taxonomy
                    ]
                )
            );
        }


        /**
         * Native taxonomy archive.
         */
        $term =
            get_queried_object();

        if (
            $term instanceof WP_Term
            &&
            $term->taxonomy
                ===
                $taxonomy
            &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            return esc_html(
                $term->name
            );
        }

        return '';
    }
);

/**
 * TFSC - Combo Vacancy Sitemap
 *
 * Vereist:
 * - TFSC - Combo Archive URLs
 * - TFSC - Volledig dynamische vacature-archieven
 * - TFSC - Combo Archive SEO
 * - Rank Math SEO
 *
 * Maakt:
 * /combo-vacatures-sitemap.xml
 *
 * Wordt automatisch toegevoegd aan:
 * /sitemap_index.xml
 *
 *
 * HUIDIGE STRATEGIE
 * ============================================================
 *
 * - Alleen gepubliceerde + open vacatures
 * - Alleen werkelijk bestaande termcombinaties
 * - Exact 2 verschillende taxonomies per combo
 * - tfsc_combo_should_index() bepaalt of de combo
 *   daadwerkelijk in de sitemap mag
 * - URL-opbouw loopt uitsluitend via TFSC - Combo Archive URLs
 * - iedere combo-URL krijgt een betrouwbare lastmod
 * - sitemap-index krijgt per sitemapdeel de nieuwste lastmod
 *
 *
 * Performance:
 * - combinaties worden alleen berekend wanneer nodig
 * - URL-lijst wordt gecachet
 * - cache wordt automatisch verwijderd bij relevante wijzigingen
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if (
    ! defined(
        'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS',
        2
    );
}


if (
    ! defined(
        'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS',
        2
    );
}


/**
 * Nieuwe cache key omdat URL-opbouw nu centraal loopt.
 */
if (
    ! defined(
        'TFSC_COMBO_SITEMAP_CACHE_KEY'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_CACHE_KEY',
        'tfsc_combo_sitemap_links_v5'
    );
}


if (
    ! defined(
        'TFSC_COMBO_SITEMAP_CACHE_TTL'
    )
) {
    define(
        'TFSC_COMBO_SITEMAP_CACHE_TTL',
        DAY_IN_SECONDS
    );
}


/**
 * ============================================================
 * BESCHIKBAARHEID
 * ============================================================
 */

function tfsc_combo_sitemap_is_available() {

    return (
        function_exists(
            'tfsc_get_allowed_combo_taxonomies'
        )
        &&
        function_exists(
            'tfsc_get_combo_taxonomy_match_method'
        )
        &&
        function_exists(
            'tfsc_combo_should_index'
        )
        &&
        function_exists(
            'tfsc_urlcore_create_item'
        )
        &&
        function_exists(
            'tfsc_build_combo_url'
        )
        &&
        defined(
            'TFSC_VACANCY_POST_TYPE'
        )
        &&
        defined(
            'TFSC_STATUS_TAXONOMY'
        )
        &&
        defined(
            'TFSC_OPEN_STATUS_SLUG'
        )
    );
}


/**
 * ============================================================
 * TAXONOMY VOLGORDE VOOR GENERATIE
 * ============================================================
 *
 * Dit bepaalt alleen de volgorde waarin combinaties worden
 * gegenereerd.
 *
 * De uiteindelijke URL-volgorde wordt alsnog centraal bepaald
 * door tfsc_build_combo_url().
 */

function tfsc_combo_sitemap_order_taxonomies(
    array $taxonomies
) {

    $function = [];
    $others   = [];

    $function_taxonomy =
        defined(
            'TFSC_COMBO_FUNCTION_TAXONOMY'
        )
            ? TFSC_COMBO_FUNCTION_TAXONOMY
            : 'functienaam';


    foreach (
        $taxonomies
        as $taxonomy
    ) {

        if (
            $function_taxonomy
            ===
            $taxonomy
        ) {

            $function[] =
                $taxonomy;

        } else {

            $others[] =
                $taxonomy;
        }
    }


    return array_merge(
        $function,
        $others
    );
}


/**
 * ============================================================
 * POST LASTMOD
 * ============================================================
 */

function tfsc_combo_sitemap_get_post_lastmod(
    $post_id
) {

    $modified_gmt =
        get_post_field(
            'post_modified_gmt',
            $post_id
        );


    if (
        ! $modified_gmt
        ||
        '0000-00-00 00:00:00'
        ===
        $modified_gmt
    ) {
        return '';
    }


    $timestamp =
        strtotime(
            $modified_gmt
            .
            ' GMT'
        );


    if (
        ! $timestamp
    ) {
        return '';
    }


    return gmdate(
        'c',
        $timestamp
    );
}


/**
 * ============================================================
 * NIEUWSTE LASTMOD
 * ============================================================
 */

function tfsc_combo_sitemap_newest_lastmod(
    $current,
    $candidate
) {

    if (
        ! $candidate
    ) {
        return $current;
    }


    if (
        ! $current
    ) {
        return $candidate;
    }


    $current_time =
        strtotime(
            $current
        );


    $candidate_time =
        strtotime(
            $candidate
        );


    if (
        ! $candidate_time
    ) {
        return $current;
    }


    if (
        ! $current_time
        ||
        $candidate_time
            >
            $current_time
    ) {
        return $candidate;
    }


    return $current;
}


/**
 * ============================================================
 * TAXONOMY TERMS VAN ÉÉN VACATURE
 * ============================================================
 */

function tfsc_combo_sitemap_get_post_dimensions(
    $post_id,
    array $taxonomies
) {

    $dimensions =
        [];


    foreach (
        $taxonomies
        as $taxonomy
    ) {

        $terms =
            get_the_terms(
                $post_id,
                $taxonomy
            );


        if (
            ! is_array( $terms )
            ||
            ! $terms
        ) {
            continue;
        }


        $taxonomy_object =
            get_taxonomy(
                $taxonomy
            );


        $match_method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        $collected =
            [];


        foreach (
            $terms
            as $term
        ) {

            if (
                ! $term
                instanceof WP_Term
            ) {
                continue;
            }


            $collected[
                $term->term_id
            ] =
                $term;


            /**
             * Bij OR-taxonomies tellen ancestors ook mee.
             *
             * Bij kennisgebied (AND) juist niet.
             */
            if (
                $taxonomy_object
                &&
                $taxonomy_object->hierarchical
                &&
                'AND'
                    !==
                    $match_method
            ) {

                $ancestor_ids =
                    get_ancestors(
                        $term->term_id,
                        $taxonomy,
                        'taxonomy'
                    );


                foreach (
                    $ancestor_ids
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor
                        instanceof WP_Term
                        &&
                        ! is_wp_error(
                            $ancestor
                        )
                    ) {

                        $collected[
                            $ancestor->term_id
                        ] =
                            $ancestor;
                    }
                }
            }
        }


        if (
            $collected
        ) {

            $dimensions[
                $taxonomy
            ] =
                array_values(
                    $collected
                );
        }
    }


    return $dimensions;
}


/**
 * ============================================================
 * COMBINATIES VAN TAXONOMIES
 * ============================================================
 */

function tfsc_combo_sitemap_dimension_sets(
    array $dimensions,
    $size
) {

    $dimensions =
        array_values(
            $dimensions
        );


    $size =
        (int) $size;


    if (
        $size < 1
        ||
        count(
            $dimensions
        ) < $size
    ) {
        return [];
    }


    if (
        1 === $size
    ) {

        return array_map(
            static function(
                $dimension
            ) {

                return [
                    $dimension,
                ];
            },
            $dimensions
        );
    }


    $result =
        [];


    $first =
        array_shift(
            $dimensions
        );


    foreach (
        tfsc_combo_sitemap_dimension_sets(
            $dimensions,
            $size - 1
        )
        as $subset
    ) {

        array_unshift(
            $subset,
            $first
        );


        $result[] =
            $subset;
    }


    foreach (
        tfsc_combo_sitemap_dimension_sets(
            $dimensions,
            $size
        )
        as $subset
    ) {

        $result[] =
            $subset;
    }


    return $result;
}


/**
 * ============================================================
 * TERM PRODUCTEN
 * ============================================================
 *
 * Maakt alleen combo-arrays.
 *
 * Het uiteindelijke term-pad en de URL worden door de
 * centrale URL Core afgehandeld.
 */

function tfsc_combo_sitemap_term_products(
    array $taxonomy_set,
    array $dimensions
) {

    $taxonomy_set =
        tfsc_combo_sitemap_order_taxonomies(
            $taxonomy_set
        );


    $products = [
        [],
    ];


    foreach (
        $taxonomy_set
        as $taxonomy
    ) {

        if (
            empty(
                $dimensions[
                    $taxonomy
                ]
            )
        ) {
            return [];
        }


        $next =
            [];


        foreach (
            $products
            as $product
        ) {

            foreach (
                $dimensions[
                    $taxonomy
                ]
                as $term
            ) {

                if (
                    ! $term
                    instanceof WP_Term
                ) {
                    continue;
                }


                /**
                 * Centrale supplier maakt het combo-item,
                 * inclusief correct hiërarchisch term-pad.
                 */
                $item =
                    tfsc_urlcore_create_item(
                        $term
                    );


                if (
                    ! $item
                ) {
                    continue;
                }


                $new_product =
                    $product;


                $new_product[] =
                    $item;


                $next[] =
                    $new_product;
            }
        }


        $products =
            $next;


        if (
            ! $products
        ) {
            return [];
        }
    }


    return $products;
}


/**
 * ============================================================
 * SITEMAP LINKS GENEREREN
 * ============================================================
 */

function tfsc_combo_sitemap_generate_links() {

    if (
        ! tfsc_combo_sitemap_is_available()
    ) {
        return [];
    }


    $cached =
        get_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY
        );


    if (
        is_array(
            $cached
        )
    ) {
        return $cached;
    }


    $taxonomies =
        tfsc_get_allowed_combo_taxonomies();


    if (
        ! $taxonomies
    ) {
        return [];
    }


    $taxonomies =
        tfsc_combo_sitemap_order_taxonomies(
            $taxonomies
        );


    $posts =
        get_posts(
            [
                'post_type' =>
                    TFSC_VACANCY_POST_TYPE,

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    -1,

                'no_found_rows' =>
                    true,

                'orderby' =>
                    'ID',

                'order' =>
                    'ASC',

                'tax_query' => [
                    [
                        'taxonomy' =>
                            TFSC_STATUS_TAXONOMY,

                        'field' =>
                            'slug',

                        'terms' => [
                            TFSC_OPEN_STATUS_SLUG,
                        ],

                        'operator' =>
                            'IN',

                        'include_children' =>
                            false,
                    ],
                ],
            ]
        );


    if (
        ! $posts
    ) {

        set_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            [],
            TFSC_COMBO_SITEMAP_CACHE_TTL
        );


        return [];
    }


    $links =
        [];


    foreach (
        $posts
        as $post
    ) {

        if (
            ! $post
            instanceof WP_Post
        ) {
            continue;
        }


        $post_id =
            (int)
            $post->ID;


        $post_lastmod =
            tfsc_combo_sitemap_get_post_lastmod(
                $post_id
            );


        $dimensions =
            tfsc_combo_sitemap_get_post_dimensions(
                $post_id,
                $taxonomies
            );


        if (
            ! $dimensions
        ) {
            continue;
        }


        /**
         * Zelfde taxonomy-volgorde behouden als de centrale
         * vacancy-taxonomy lijst.
         */
        $ordered_dimensions =
            [];


        foreach (
            $taxonomies
            as $taxonomy
        ) {

            if (
                isset(
                    $dimensions[
                        $taxonomy
                    ]
                )
            ) {

                $ordered_dimensions[
                    $taxonomy
                ] =
                    $dimensions[
                        $taxonomy
                    ];
            }
        }


        $dimensions =
            $ordered_dimensions;


        $taxonomy_names =
            array_keys(
                $dimensions
            );


        $min =
            max(
                2,
                (int)
                TFSC_COMBO_SITEMAP_MIN_DIMENSIONS
            );


        $max =
            min(
                count(
                    $taxonomy_names
                ),
                max(
                    $min,
                    (int)
                    TFSC_COMBO_SITEMAP_MAX_DIMENSIONS
                )
            );


        if (
            $max < $min
        ) {
            continue;
        }


        for (
            $size = $min;
            $size <= $max;
            $size++
        ) {

            $dimension_sets =
                tfsc_combo_sitemap_dimension_sets(
                    $taxonomy_names,
                    $size
                );


            foreach (
                $dimension_sets
                as $taxonomy_set
            ) {

                $products =
                    tfsc_combo_sitemap_term_products(
                        $taxonomy_set,
                        $dimensions
                    );


                foreach (
                    $products
                    as $combo
                ) {

                    /**
                     * SEO blijft bepalen of deze combo
                     * indexeerbaar genoeg is voor de sitemap.
                     */
                    if (
                        ! tfsc_combo_should_index(
                            $combo
                        )
                    ) {
                        continue;
                    }


                    /**
                     * DE ENIGE URL-BUILDER.
                     */
                    $url =
                        tfsc_build_combo_url(
                            $combo
                        );


                    if (
                        '' === $url
                    ) {
                        continue;
                    }


                    if (
                        ! isset(
                            $links[
                                $url
                            ]
                        )
                    ) {

                        $links[
                            $url
                        ] = [
                            'loc' =>
                                $url,

                            'lastmod' =>
                                $post_lastmod,
                        ];

                        continue;
                    }


                    $links[
                        $url
                    ][
                        'lastmod'
                    ] =
                        tfsc_combo_sitemap_newest_lastmod(
                            isset(
                                $links[
                                    $url
                                ][
                                    'lastmod'
                                ]
                            )
                                ?
                                $links[
                                    $url
                                ][
                                    'lastmod'
                                ]
                                :
                                '',

                            $post_lastmod
                        );
                }
            }
        }
    }


    ksort(
        $links,
        SORT_STRING
    );


    $links =
        array_values(
            $links
        );


    set_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY,
        $links,
        TFSC_COMBO_SITEMAP_CACHE_TTL
    );


    return $links;
}


/**
 * ============================================================
 * CACHE LEGEN
 * ============================================================
 */

function tfsc_combo_sitemap_flush_cache() {

    /**
     * Huidige cache.
     */
    delete_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY
    );


    /**
     * Oude caches opruimen.
     */
    delete_transient(
        'tfsc_combo_sitemap_links_v1'
    );

    delete_transient(
        'tfsc_combo_sitemap_links_v2'
    );

    delete_transient(
        'tfsc_combo_sitemap_links_v3'
    );

    delete_transient(
        'tfsc_combo_sitemap_links_v4'
    );


    if (
        class_exists(
            '\RankMath\Sitemap\Cache'
        )
        &&
        method_exists(
            '\RankMath\Sitemap\Cache',
            'invalidate_storage'
        )
    ) {

        \RankMath\Sitemap\Cache::invalidate_storage(
            'combo-vacatures'
        );
    }
}


