function tfsc_combo_sitemap_term_changed(
    $term_id,
    $tt_id = 0,
    $taxonomy = ''
) {

    if (
        ! $taxonomy
    ) {
        return;
    }


    if (
        TFSC_STATUS_TAXONOMY
        !==
        $taxonomy
        &&
        ! tfsc_urlcore_taxonomy_allowed(
            $taxonomy
        )
    ) {
        return;
    }


    tfsc_combo_sitemap_flush_cache();
}


