/**
 * ============================================================
 * RANK MATH CUSTOM SITEMAP PROVIDER
 * ============================================================
 */

add_filter(
    'rank_math/sitemap/providers',

    function( $providers ) {

        if (
            ! interface_exists(
                '\RankMath\Sitemap\Providers\Provider'
            )
        ) {
            return $providers;
        }


        if (
            ! class_exists(
                'TFSC_Combo_Vacancy_Sitemap_Provider',
                false
            )
        ) {

            class TFSC_Combo_Vacancy_Sitemap_Provider
                implements
                \RankMath\Sitemap\Providers\Provider {


                public function handles_type(
                    $type
                ) {

                    return (
                        'combo-vacatures'
                        ===
                        $type
                    );
                }


                public function get_index_links(
                    $max_entries
                ) {

                    $links =
                        tfsc_combo_sitemap_generate_links();


                    $total =
                        count(
                            $links
                        );


                    if (
                        0 === $total
                    ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int)
                            $max_entries
                        );


                    $pages =
                        max(
                            1,
                            (int)
                            ceil(
                                $total
                                /
                                $max_entries
                            )
                        );


                    $index =
                        [];


                    for (
                        $page = 1;
                        $page <= $pages;
                        $page++
                    ) {

                        $suffix =
                            $pages > 1
                                ? $page
                                : '';


                        $offset =
                            (
                                $page - 1
                            )
                            *
                            $max_entries;


                        $page_links =
                            array_slice(
                                $links,
                                $offset,
                                $max_entries
                            );


                        $page_lastmod =
                            '';


                        foreach (
                            $page_links
                            as $page_link
                        ) {

                            if (
                                empty(
                                    $page_link[
                                        'lastmod'
                                    ]
                                )
                            ) {
                                continue;
                            }


                            $page_lastmod =
                                tfsc_combo_sitemap_newest_lastmod(
                                    $page_lastmod,
                                    $page_link[
                                        'lastmod'
                                    ]
                                );
                        }


                        $index[] = [
                            'loc' =>
                                \RankMath\Sitemap\Router::get_base_url(
                                    'combo-vacatures-sitemap'
                                    .
                                    $suffix
                                    .
                                    '.xml'
                                ),

                            'lastmod' =>
                                $page_lastmod,
                        ];
                    }


                    return $index;
                }


                public function get_sitemap_links(
                    $type,
                    $max_entries,
                    $current_page
                ) {

                    if (
                        'combo-vacatures'
                        !==
                        $type
                    ) {
                        return [];
                    }


                    $links =
                        tfsc_combo_sitemap_generate_links();


                    if (
                        ! $links
                    ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int)
                            $max_entries
                        );


                    $page =
                        max(
                            1,
                            (int)
                            $current_page
                        );


                    $offset =
                        (
                            $page - 1
                        )
                        *
                        $max_entries;


                    return array_slice(
                        $links,
                        $offset,
                        $max_entries
                    );
                }
            }
        }


        $providers[
            'combo-vacatures'
        ] =
            new TFSC_Combo_Vacancy_Sitemap_Provider();


        return $providers;
    }
);

/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 5
 *
 * Op een taxonomy-term:
 * relationship_* velden
 * → relevante OPEN vacatures
 * → terms uit Elementor Source taxonomy
 * → Elementor Taxonomy Loop
 * → centrale combo-URL
 *
 * Verschillende taxonomies = AND
 * Meerdere terms binnen dezelfde taxonomy = OR / IN
 *
 * Query IDs:
 * archive_relationship_level_0
 * archive_relationship_level_1
 * archive_relationship_level_2
 *
 * Vereist voor combo-links:
 * TFSC - Combo Archive URLs
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

function tfsc_taxrel_v5_vacancy_post_type() {
    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}

function tfsc_taxrel_v5_status_taxonomy() {
    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}

function tfsc_taxrel_v5_open_status() {
    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


/**
 * ============================================================
 * HUIDIGE TAXONOMY TERM
 * ============================================================
 *
 * Inclusief Elementor Theme Builder preview-fix.
 */

function tfsc_taxrel_v5_current_term() {

    static $resolved = false;
    static $term = false;

    if ( $resolved ) {
        return $term;
    }

    $resolved = true;
    $object = get_queried_object();

    /*
     * Normale taxonomy archive / Elementor preview iframe.
     */
    if (
        $object instanceof WP_Term &&
        $object->term_id &&
        $object->taxonomy &&
        taxonomy_exists( $object->taxonomy )
    ) {

        if ( is_user_logged_in() ) {
            set_transient(
                'tfsc_taxrel_v5_preview_' . get_current_user_id(),
                [
                    'term_id'  => (int) $object->term_id,
                    'taxonomy' => $object->taxonomy,
                ],
                5 * MINUTE_IN_SECONDS
            );
        }

        return $term = $object;
    }

    /*
     * Elementor admin-render.
     */
    if (
        ! is_admin() ||
        ! is_user_logged_in() ||
        ! $object instanceof WP_Post
    ) {
        return false;
    }

    $preview = get_transient(
        'tfsc_taxrel_v5_preview_' . get_current_user_id()
    );

    if (
        ! is_array( $preview ) ||
        empty( $preview['term_id'] ) ||
        empty( $preview['taxonomy'] ) ||
        ! taxonomy_exists( $preview['taxonomy'] )
    ) {
        return false;
    }

    $settings = get_post_meta(
        $object->ID,
        '_elementor_page_settings',
        true
    );

    if (
        ! is_array( $settings ) ||
        ( $settings['preview_type'] ?? '' ) !==
            'taxonomy/' . $preview['taxonomy']
    ) {
        return false;
    }

    $candidate = get_term(
        (int) $preview['term_id'],
        $preview['taxonomy']
    );

    if (
        $candidate instanceof WP_Term &&
        ! is_wp_error( $candidate )
    ) {
        $term = $candidate;
    }

    return $term;
}


/**
 * ============================================================
 * POD VAN HUIDIGE TERM
 * ============================================================
 */

function tfsc_taxrel_v5_current_pod() {

    static $resolved = false;
    static $pod = false;

    if ( $resolved ) {
        return $pod;
    }

    $resolved = true;

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $term = tfsc_taxrel_v5_current_term();

    if ( ! $term ) {
        return false;
    }

    $candidate = pods(
        $term->taxonomy,
        (int) $term->term_id
    );

    if (
        $candidate &&
        $candidate->exists()
    ) {
        $pod = $candidate;
    }

    return $pod;
}


/**
 * ============================================================
 * ÉÉN RELATIONSHIP ITEM UITLEZEN
 * ============================================================
 */

function tfsc_taxrel_v5_relationship_item(
    $relation,
    $fallback_taxonomy = ''
) {

    $term_id  = 0;
    $taxonomy = '';

    if ( is_array( $relation ) ) {

        $term_id = (int) (
            $relation['term_id']
            ?? $relation['pod_item_id']
            ?? $relation['id']
            ?? $relation['ID']
            ?? 0
        );

        $taxonomy = sanitize_key(
            $relation['taxonomy'] ?? ''
        );

    } elseif ( is_object( $relation ) ) {

        $term_id = (int) (
            $relation->term_id
            ?? $relation->pod_item_id
            ?? $relation->id
            ?? $relation->ID
            ?? 0
        );

        $taxonomy = sanitize_key(
            $relation->taxonomy ?? ''
        );

    } elseif ( is_numeric( $relation ) ) {

        $term_id = (int) $relation;
    }

    if ( ! $taxonomy ) {
        $taxonomy = sanitize_key( $fallback_taxonomy );
    }

    if (
        ! $term_id ||
        ! $taxonomy ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return false;
    }

    $term = get_term(
        $term_id,
        $taxonomy
    );

    if (
        ! $term instanceof WP_Term ||
        is_wp_error( $term )
    ) {
        return false;
    }

    return [
        'taxonomy' => $taxonomy,
        'term_id'  => $term_id,
    ];
}


/**
 * ============================================================
 * ALLE ACTIEVE RELATIONSHIPS OP HUIDIGE TERM
 * ============================================================
 */

function tfsc_taxrel_v5_relationship_groups() {

    static $resolved = false;
    static $groups = [];

    if ( $resolved ) {
        return $groups;
    }

    $resolved = true;

    $pod = tfsc_taxrel_v5_current_pod();

    if ( ! $pod ) {
        return [];
    }

    $fields = $pod->fields();

    if ( ! is_array( $fields ) ) {
        return [];
    }

    foreach ( $fields as $field_name => $field_data ) {

        if (
            ! is_string( $field_name ) ||
            strpos( $field_name, 'relationship_' ) !== 0 ||
            $field_name === 'relationship_vacature_button_url'
        ) {
            continue;
        }

        $value = $pod->field( $field_name );

        if ( empty( $value ) ) {
            continue;
        }

        /*
         * Eén Pods-resultaat naar een lijst normaliseren.
         */
        if (
            is_numeric( $value ) ||
            is_object( $value ) ||
            (
                is_array( $value ) &&
                (
                    isset( $value['term_id'] ) ||
                    isset( $value['pod_item_id'] ) ||
                    isset( $value['id'] ) ||
                    isset( $value['ID'] )
                )
            )
        ) {
            $value = [ $value ];
        }

        $fallback_taxonomy = substr(
            $field_name,
            strlen( 'relationship_' )
        );

        foreach ( (array) $value as $relation ) {

            $item = tfsc_taxrel_v5_relationship_item(
                $relation,
                $fallback_taxonomy
            );

            if ( ! $item ) {
                continue;
            }

            /*
             * Term ID als array-key voorkomt duplicaten direct.
             */
            $groups[ $item['taxonomy'] ][ $item['term_id'] ] =
                $item['term_id'];
        }
    }

    foreach ( $groups as $taxonomy => $ids ) {
        $groups[ $taxonomy ] = array_values( $ids );
    }

    return $groups;
}


/**
 * ============================================================
 * OPEN VACATURES BIJ DE RELATIONSHIPS
 * ============================================================
 */

function tfsc_taxrel_v5_vacancy_ids(
    array $groups
) {

    static $cache = [];

    if ( ! $groups ) {
        return [];
    }

    $cache_key = md5( serialize( $groups ) );

    if ( isset( $cache[ $cache_key ] ) ) {
        return $cache[ $cache_key ];
    }

    $tax_query = [
        'relation' => 'AND',
    ];

    /*
     * Verschillende taxonomies = AND.
     * Terms binnen dezelfde taxonomy = IN / OR.
     */
    foreach ( $groups as $taxonomy => $ids ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $ids
        ) {
            continue;
        }

        $tax_query[] = [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => $ids,
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    if ( count( $tax_query ) === 1 ) {
        return [];
    }

    $status_taxonomy =
        tfsc_taxrel_v5_status_taxonomy();

    if ( taxonomy_exists( $status_taxonomy ) ) {
        $tax_query[] = [
            'taxonomy'         => $status_taxonomy,
            'field'            => 'slug',
            'terms'            => [
                tfsc_taxrel_v5_open_status(),
            ],
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    $ids = get_posts( [
        'post_type'      => tfsc_taxrel_v5_vacancy_post_type(),
        'post_status'    => 'publish',
        'posts_per_page' => -1,
        'fields'         => 'ids',
        'no_found_rows'  => true,
        'tax_query'      => $tax_query,
    ] );

    return $cache[ $cache_key ] =
        array_values(
            array_unique(
                array_map( 'intval', $ids )
            )
        );
}


/**
 * ============================================================
 * TARGET TERMS UIT VACATURES
 * ============================================================
 */

function tfsc_taxrel_v5_target_terms(
    array $vacancy_ids,
    $taxonomy
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }

    $ids = wp_get_object_terms(
        $vacancy_ids,
        $taxonomy,
        [
            'fields' => 'ids',
        ]
    );

    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }

    /*
     * ID als key voorkomt duplicaten zonder aparte
     * array_unique-rondes.
     */
    $result = [];

    foreach ( $ids as $term_id ) {

        $term_id = (int) $term_id;

        if ( ! $term_id ) {
            continue;
        }

        $result[ $term_id ] = $term_id;

        if ( is_taxonomy_hierarchical( $taxonomy ) ) {

            foreach (
                get_ancestors(
                    $term_id,
                    $taxonomy,
                    'taxonomy'
                )
                as $ancestor_id
            ) {
                $result[ (int) $ancestor_id ] =
                    (int) $ancestor_id;
            }
        }
    }

    return array_values( $result );
}


/**
 * ============================================================
 * EXACT TAXONOMY LEVEL
 * ============================================================
 *
 * level 0 = top-level
 * level 1 = één ancestor
 * level 2 = twee ancestors
 */

function tfsc_taxrel_v5_filter_level(
    array $ids,
    $taxonomy,
    $level
) {

    $level = (int) $level;

    if ( ! $ids ) {
        return [];
    }

    if ( ! is_taxonomy_hierarchical( $taxonomy ) ) {
        return $level === 0
            ? $ids
            : [];
    }

    return array_values(
        array_filter(
            $ids,
            static function( $term_id ) use (
                $taxonomy,
                $level
            ) {
                return count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === $level;
            }
        )
    );
}


/**
 * ============================================================
 * QUERY ID → LEVEL
 * ============================================================
 */

function tfsc_taxrel_v5_query_level(
    $query_id
) {

    return preg_match(
        '/^archive_relationship_level_([0-9]+)$/',
        (string) $query_id,
        $matches
    )
        ? (int) $matches[1]
        : false;
}


/**
 * ============================================================
 * ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings['post_taxonomy_term_taxonomy_id']
            ??
            '';

        $level =
            tfsc_taxrel_v5_query_level(
                $query_id
            );

        if (
            $level === false ||
            ! tfsc_taxrel_v5_current_term()
        ) {
            return $args;
        }

        /*
         * Elementor Source bepaalt target taxonomy.
         */
        $taxonomy =
            $args['taxonomy']
            ??
            $settings['post_taxonomy_query_post_type']
            ??
            '';

        if ( is_array( $taxonomy ) ) {
            $taxonomy = reset( $taxonomy );
        }

        $taxonomy = sanitize_key( $taxonomy );

        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy ) ||
            $taxonomy === tfsc_taxrel_v5_status_taxonomy()
        ) {
            return $args;
        }

        $groups =
            tfsc_taxrel_v5_relationship_groups();

        $vacancy_ids =
            tfsc_taxrel_v5_vacancy_ids(
                $groups
            );

        $target_ids =
            tfsc_taxrel_v5_filter_level(
                tfsc_taxrel_v5_target_terms(
                    $vacancy_ids,
                    $taxonomy
                ),
                $taxonomy,
                $level
            );

        if ( ! $target_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        unset(
            $args['term_taxonomy_id']
        );

        $args['taxonomy']     = $taxonomy;
        $args['include']      = $target_ids;
        $args['hide_empty']   = false;
        $args['hierarchical'] = false;

        /*
         * Marker voor eigen sortering.
         */
        $args['tfsc_taxrel_v5'] = true;

        /*
         * Alleen deze target taxonomy krijgt combo-links.
         */
        $GLOBALS['tfsc_taxrel_v5_active_targets'][ $taxonomy ] =
            true;

        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * SORTERING OP NAAM
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty( $args['tfsc_taxrel_v5'] ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }

        if (
            isset( $args['orderby'] ) &&
            strtolower( (string) $args['orderby'] ) !== 'name'
        ) {
            return $terms;
        }

        $descending =
            strtoupper( (string) ( $args['order'] ?? 'ASC' ) )
            === 'DESC';

        usort(
            $terms,
            static function( $a, $b ) use ( $descending ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }

                $result = strnatcasecmp(
                    remove_accents( $a->name ),
                    remove_accents( $b->name )
                );

                return $descending
                    ? -$result
                    : $result;
            }
        );

        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * RELATIONSHIPS + TARGET TERM → CENTRALE COMBO URL
 * ============================================================
 */

function tfsc_taxrel_v5_combo_url(
    $target_term = null
) {

    if (
        ! function_exists( 'tfsc_urlcore_create_item' ) ||
        ! function_exists( 'tfsc_build_combo_url' )
    ) {
        return false;
    }

    $groups =
        tfsc_taxrel_v5_relationship_groups();

    if ( ! $groups ) {
        return false;
    }

    $combo = [];

    foreach ( $groups as $taxonomy => $ids ) {

        foreach ( $ids as $term_id ) {

            /*
             * Target term niet dubbel toevoegen.
             */
            if (
                $target_term instanceof WP_Term &&
                $target_term->taxonomy === $taxonomy &&
                (int) $target_term->term_id === (int) $term_id
            ) {
                continue;
            }

            $term = get_term(
                $term_id,
                $taxonomy
            );

            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }

            $item =
                tfsc_urlcore_create_item(
                    $term
                );

            if ( $item ) {
                $combo[] = $item;
            }
        }
    }

    if ( $target_term instanceof WP_Term ) {

        $item =
            tfsc_urlcore_create_item(
                $target_term
            );

        if ( $item ) {
            $combo[] = $item;
        }
    }

    return $combo
        ? tfsc_build_combo_url( $combo )
        : false;
}


/**
 * ============================================================
 * ELEMENTOR TERM LINKS → COMBO URL
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        /*
         * Expliciete native-link bypass behouden.
         */
        if (
            ! empty( $GLOBALS['tfsc_force_native_term_link'] ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! tfsc_taxrel_v5_current_term()
        ) {
            return $termlink;
        }

        /*
         * Alleen target-taxonomies die door onze Elementor
         * taxonomy-loop zijn geactiveerd.
         */
        if (
            empty(
                $GLOBALS[
                    'tfsc_taxrel_v5_active_targets'
                ][
                    $taxonomy
                ]
            )
        ) {
            return $termlink;
        }

        $url =
            tfsc_taxrel_v5_combo_url(
                $term
            );

        return $url
            ?: $termlink;
    },
    40,
    3
);

/**
 * TFSC - Generic Derived Relationship Taxonomy Terms
 * Version 4
 *
 * Huidige CPT/post
 * → relationship_* velden
 * → overeenkomende OPEN vacatures
 * → terms uit Elementor Source taxonomy
 * → Elementor Taxonomy Loop
 * → centrale combo-URL
 *
 * Verschillende taxonomies = AND
 * Meerdere terms binnen taxonomy = OR / IN
 *
 * Query IDs:
 * relationship_level_0
 * relationship_level_1
 * relationship_level_2
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

function tfsc_derived_rel_v4_vacancy_post_type() {
    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}

function tfsc_derived_rel_v4_status_taxonomy() {
    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}

function tfsc_derived_rel_v4_open_status() {
    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


/**
 * ============================================================
 * CPT / POST CONTEXT
 * ============================================================
 *
 * Werkt met:
 * - normale frontend;
 * - Elementor Theme Builder preview;
 * - preview_id;
 * - globale $post fallback.
 */

function tfsc_derived_rel_v4_get_context_post_id() {

    static $resolved = null;

    if ( null !== $resolved ) {
        return $resolved;
    }

    $resolved = 0;
    $object   = get_queried_object();

    /*
     * Normale frontend.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' !== get_post_type( $object->ID )
    ) {
        return $resolved = (int) $object->ID;
    }

    /*
     * Elementor Theme Builder.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' === get_post_type( $object->ID )
    ) {
        $template_id = (int) $object->ID;

        if (
            did_action( 'elementor/loaded' ) &&
            class_exists( '\Elementor\Plugin' )
        ) {
            try {
                $document = \Elementor\Plugin::$instance
                    ->documents
                    ->get( $template_id );

                if ( $document ) {
                    $preview_id = absint(
                        $document->get_settings( 'preview_id' )
                    );

                    if (
                        $preview_id &&
                        'elementor_library' !== get_post_type( $preview_id )
                    ) {
                        return $resolved = $preview_id;
                    }
                }
            } catch ( Throwable $e ) {
                // Meta fallback hieronder.
            }
        }

        $settings = get_post_meta(
            $template_id,
            '_elementor_page_settings',
            true
        );

        $preview_id = is_array( $settings )
            ? absint( $settings['preview_id'] ?? 0 )
            : 0;

        if (
            $preview_id &&
            'elementor_library' !== get_post_type( $preview_id )
        ) {
            return $resolved = $preview_id;
        }
    }

    /*
     * WordPress / Elementor preview fallback.
     */
    if ( ! empty( $_GET['preview_id'] ) ) {
        $preview_id = absint(
            wp_unslash( $_GET['preview_id'] )
        );

        if (
            $preview_id &&
            'elementor_library' !== get_post_type( $preview_id )
        ) {
            return $resolved = $preview_id;
        }
    }

    /*
     * Laatste fallback.
     */
    global $post;

    if (
        $post instanceof WP_Post &&
        'elementor_library' !== get_post_type( $post->ID )
    ) {
        return $resolved = (int) $post->ID;
    }

    return 0;
}


/**
 * ============================================================
 * POD VAN HUIDIGE CPT / POST
 * ============================================================
 */

function tfsc_derived_rel_v4_get_current_pod() {

    static $resolved = false;
    static $pod      = false;

    if ( $resolved ) {
        return $pod;
    }

    $resolved = true;

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $post_id = tfsc_derived_rel_v4_get_context_post_id();

    if ( ! $post_id ) {
        return false;
    }

    $post_type = get_post_type( $post_id );

    if ( ! $post_type ) {
        return false;
    }

    $candidate = pods(
        $post_type,
        $post_id
    );

    if (
        $candidate &&
        $candidate->exists()
    ) {
        $pod = $candidate;
    }

    return $pod;
}


/**
 * ============================================================
 * ÉÉN RELATIONSHIP ITEM NORMALISEREN
 * ============================================================
 */

function tfsc_derived_rel_v4_relationship_item(
    $relation
) {

    $taxonomy = '';
    $term_id  = 0;

    if ( is_array( $relation ) ) {
        $taxonomy = sanitize_key(
            $relation['taxonomy'] ?? ''
        );

        $term_id = (int) (
            $relation['term_id']
            ?? $relation['pod_item_id']
            ?? $relation['id']
            ?? $relation['ID']
            ?? 0
        );

    } elseif ( is_object( $relation ) ) {
        $taxonomy = sanitize_key(
            $relation->taxonomy ?? ''
        );

        $term_id = (int) (
            $relation->term_id
            ?? $relation->pod_item_id
            ?? $relation->id
            ?? $relation->ID
            ?? 0
        );

    } else {
        return false;
    }

    if (
        ! $taxonomy ||
        ! $term_id ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return false;
    }

    $term = get_term(
        $term_id,
        $taxonomy
    );

    if (
        ! $term instanceof WP_Term ||
        is_wp_error( $term )
    ) {
        return false;
    }

    return [
        'taxonomy' => $taxonomy,
        'term_id'  => $term_id,
    ];
}


/**
 * ============================================================
 * ALLE ACTIEVE RELATIONSHIPS
 * ============================================================
 *
 * Resultaat bijvoorbeeld:
 *
 * [
 *     'functienaam'    => [226],
 *     'functie-inhoud' => [220],
 *     'kennisgebied'    => [310],
 * ]
 */

function tfsc_derived_rel_v4_relationship_groups() {

    static $resolved = false;
    static $groups   = [];

    if ( $resolved ) {
        return $groups;
    }

    $resolved = true;

    $pod = tfsc_derived_rel_v4_get_current_pod();

    if ( ! $pod ) {
        return [];
    }

    $fields = $pod->fields();

    if (
        ! is_array( $fields ) ||
        ! $fields
    ) {
        return [];
    }

    foreach ( $fields as $field_name => $definition ) {

        if (
            ! is_string( $field_name ) ||
            0 !== strpos( $field_name, 'relationship_' ) ||
            'relationship_vacature_button_url' === $field_name
        ) {
            continue;
        }

        $value = $pod->field( $field_name );

        if ( empty( $value ) ) {
            continue;
        }

        /*
         * Eén Pods relationship naar lijst normaliseren.
         */
        if (
            is_object( $value ) ||
            (
                is_array( $value ) &&
                (
                    isset( $value['term_id'] ) ||
                    isset( $value['pod_item_id'] ) ||
                    isset( $value['id'] ) ||
                    isset( $value['ID'] )
                )
            )
        ) {
            $value = [ $value ];
        }

        if ( ! is_array( $value ) ) {
            continue;
        }

        foreach ( $value as $relation ) {

            $item = tfsc_derived_rel_v4_relationship_item(
                $relation
            );

            if ( ! $item ) {
                continue;
            }

            /*
             * ID als key voorkomt duplicaten direct.
             */
            $groups[
                $item['taxonomy']
            ][
                $item['term_id']
            ] = $item['term_id'];
        }
    }

    foreach ( $groups as $taxonomy => $ids ) {
        $groups[ $taxonomy ] = array_values( $ids );
    }

    return $groups;
}


/**
 * ============================================================
 * OPEN VACATURES OP BASIS VAN RELATIONSHIPS
 * ============================================================
 */

function tfsc_derived_rel_v4_get_vacancy_ids(
    array $groups
) {

    static $cache = [];

    if ( ! $groups ) {
        return [];
    }

    /*
     * Stabiele cache-key.
     */
    ksort( $groups );

    foreach ( $groups as &$ids ) {
        sort( $ids, SORT_NUMERIC );
    }
    unset( $ids );

    $key = md5( serialize( $groups ) );

    if ( isset( $cache[ $key ] ) ) {
        return $cache[ $key ];
    }

    $post_type =
        tfsc_derived_rel_v4_vacancy_post_type();

    if ( ! post_type_exists( $post_type ) ) {
        return [];
    }

    $tax_query = [
        'relation' => 'AND',
    ];

    /*
     * Verschillende taxonomies = AND.
     * Meerdere terms binnen taxonomy = IN / OR.
     */
    foreach ( $groups as $taxonomy => $term_ids ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $term_ids
        ) {
            continue;
        }

        $tax_query[] = [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => $term_ids,
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    if ( count( $tax_query ) === 1 ) {
        return [];
    }

    /*
     * Alleen OPEN vacatures.
     */
    $status_taxonomy =
        tfsc_derived_rel_v4_status_taxonomy();

    if ( taxonomy_exists( $status_taxonomy ) ) {
        $tax_query[] = [
            'taxonomy'         => $status_taxonomy,
            'field'            => 'slug',
            'terms'            => [
                tfsc_derived_rel_v4_open_status(),
            ],
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    $ids = get_posts( [
        'post_type'        => $post_type,
        'post_status'      => 'publish',
        'posts_per_page'   => -1,
        'fields'           => 'ids',
        'no_found_rows'    => true,
        'suppress_filters' => false,
        'tax_query'        => $tax_query,
    ] );

    return $cache[ $key ] =
        array_values(
            array_unique(
                array_map( 'intval', $ids )
            )
        );
}


/**
 * ============================================================
 * TARGET TERMS UIT VACATURES
 * ============================================================
 */

function tfsc_derived_rel_v4_get_target_term_ids(
    array $vacancy_ids,
    $taxonomy
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }

    $ids = wp_get_object_terms(
        $vacancy_ids,
        $taxonomy,
        [
            'fields' => 'ids',
        ]
    );

    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }

    $result       = [];
    $hierarchical = is_taxonomy_hierarchical( $taxonomy );

    foreach ( $ids as $term_id ) {

        $term_id = (int) $term_id;

        if ( ! $term_id ) {
            continue;
        }

        $result[ $term_id ] = $term_id;

        if ( ! $hierarchical ) {
            continue;
        }

        foreach (
            get_ancestors(
                $term_id,
                $taxonomy,
                'taxonomy'
            )
            as $ancestor_id
        ) {
            $ancestor_id = (int) $ancestor_id;
            $result[ $ancestor_id ] = $ancestor_id;
        }
    }

    return array_values( $result );
}


/**
 * ============================================================
 * EXACT LEVEL
 * ============================================================
 */

function tfsc_derived_rel_v4_filter_level(
    array $ids,
    $taxonomy,
    $level
) {

    if ( ! $ids ) {
        return [];
    }

    $level = (int) $level;

    /*
     * Niet-hiërarchisch heeft alleen level 0.
     */
    if ( ! is_taxonomy_hierarchical( $taxonomy ) ) {
        return 0 === $level
            ? $ids
            : [];
    }

    return array_values(
        array_filter(
            $ids,
            static function( $term_id ) use (
                $taxonomy,
                $level
            ) {
                return count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === $level;
            }
        )
    );
}


/**
 * ============================================================
 * QUERY ID → LEVEL
 * ============================================================
 */

function tfsc_derived_rel_v4_query_level(
    $query_id
) {

    return preg_match(
        '/^relationship_level_([0-9]+)$/',
        (string) $query_id,
        $matches
    )
        ? (int) $matches[1]
        : false;
}


/**
 * ============================================================
 * ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Elementor Source bepaalt de taxonomy.
 * Priority 30 behouden.
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings['post_taxonomy_term_taxonomy_id']
            ??
            '';

        $level =
            tfsc_derived_rel_v4_query_level(
                $query_id
            );

        if ( false === $level ) {
            return $args;
        }

        $taxonomy =
            $args['taxonomy']
            ??
            $settings['post_taxonomy_query_post_type']
            ??
            '';

        if ( is_array( $taxonomy ) ) {
            $taxonomy = reset( $taxonomy );
        }

        $taxonomy = sanitize_key( $taxonomy );

        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy ) ||
            $taxonomy === tfsc_derived_rel_v4_status_taxonomy()
        ) {
            return $args;
        }

        $groups =
            tfsc_derived_rel_v4_relationship_groups();

        if ( ! $groups ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $vacancy_ids =
            tfsc_derived_rel_v4_get_vacancy_ids(
                $groups
            );

        if ( ! $vacancy_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $target_ids =
            tfsc_derived_rel_v4_filter_level(
                tfsc_derived_rel_v4_get_target_term_ids(
                    $vacancy_ids,
                    $taxonomy
                ),
                $taxonomy,
                $level
            );

        if ( ! $target_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        unset(
            $args['term_taxonomy_id']
        );

        $args['taxonomy']     = $taxonomy;
        $args['include']      = $target_ids;
        $args['hide_empty']   = false;
        $args['hierarchical'] = false;

        /*
         * Marker voor sortering.
         */
        $args['tfsc_derived_rel_v4'] = true;

        /*
         * Alleen deze taxonomy krijgt combo-links.
         */
        $GLOBALS[
            'tfsc_derived_rel_v4_active_targets'
        ][
            $taxonomy
        ] = true;

        return $args;
    },
    30,
    3
);


/**
 * ============================================================
 * SORTERING OP NAAM
 * ============================================================
 *
 * Priority 9999 behouden.
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            is_admin() ||
            empty( $args['tfsc_derived_rel_v4'] ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }

        if (
            isset( $args['orderby'] ) &&
            'name' !== strtolower(
                (string) $args['orderby']
            )
        ) {
            return $terms;
        }

        $descending =
            'DESC' === strtoupper(
                (string) ( $args['order'] ?? 'ASC' )
            );

        usort(
            $terms,
            static function( $a, $b ) use ( $descending ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }

                $compare = strnatcasecmp(
                    remove_accents(
                        wp_strip_all_tags( $a->name )
                    ),
                    remove_accents(
                        wp_strip_all_tags( $b->name )
                    )
                );

                return $descending
                    ? -$compare
                    : $compare;
            }
        );

        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * RELATIONSHIPS + TARGET → CENTRALE COMBO URL
 * ============================================================
 *
 * Deze snippet bouwt zelf geen URL-structuur meer.
 */

function tfsc_derived_rel_v4_build_combo_url(
    $target_term
) {

    if (
        ! $target_term instanceof WP_Term ||
        ! function_exists( 'tfsc_urlcore_create_item' ) ||
        ! function_exists( 'tfsc_build_combo_url' )
    ) {
        return false;
    }

    $groups =
        tfsc_derived_rel_v4_relationship_groups();

    if ( ! $groups ) {
        return false;
    }

    $combo = [];

    /*
     * Alle actieve relationships.
     */
    foreach ( $groups as $taxonomy => $term_ids ) {

        foreach ( $term_ids as $term_id ) {

            /*
             * Target-term niet dubbel opnemen.
             */
            if (
                $taxonomy === $target_term->taxonomy &&
                (int) $term_id === (int) $target_term->term_id
            ) {
                continue;
            }

            $term = get_term(
                $term_id,
                $taxonomy
            );

            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }

            $item =
                tfsc_urlcore_create_item(
                    $term
                );

            if ( $item ) {
                $combo[] = $item;
            }
        }
    }

    /*
     * Aangeklikte target-term.
     */
    $target_item =
        tfsc_urlcore_create_item(
            $target_term
        );

    if ( ! $target_item ) {
        return false;
    }

    $combo[] = $target_item;

    return tfsc_build_combo_url(
        $combo
    );
}


/**
 * ============================================================
 * TERM LINKS → COMBO ARCHIVES
 * ============================================================
 *
 * Priority 30 behouden.
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty( $GLOBALS['tfsc_force_native_term_link'] ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! $taxonomy
        ) {
            return $termlink;
        }

        /*
         * Alleen CPT/post-context.
         */
        $object = get_queried_object();

        if ( ! $object instanceof WP_Post ) {
            return $termlink;
        }

        if (
            $taxonomy ===
            tfsc_derived_rel_v4_status_taxonomy()
        ) {
            return $termlink;
        }

        /*
         * Alleen door deze Elementor-loop geactiveerde
         * target-taxonomies.
         */
        if (
            empty(
                $GLOBALS[
                    'tfsc_derived_rel_v4_active_targets'
                ][
                    $taxonomy
                ]
            )
        ) {
            return $termlink;
        }

        $url =
            tfsc_derived_rel_v4_build_combo_url(
                $term
            );

        return $url
            ?: $termlink;
    },
    30,
    3
);

/**
 * TFSC - Generic Derived Relationship Taxonomy Terms
 * Version 5 - Compact
 *
 * Vereist:
 * - Pods
 * - Elementor Pro
 * - TFSC - Combo Archive URLs
 *
 * Huidige CPT/post
 * → alle relationship_* velden
 * → overeenkomende OPEN vacatures
 * → terms uit Elementor Source taxonomy
 * → level-filter
 * → combo-links via centrale URL builder
 *
 * Query IDs:
 * relationship_level_0
 * relationship_level_1
 * relationship_level_2
 *
 * Verschillende taxonomies = AND
 * Meerdere terms binnen taxonomy = OR / IN
 */


/**
 * ============================================================
 * CONTEXT POST
 * ============================================================
 *
 * Normale frontend + Elementor Theme Builder preview.
 */

function tfsc_derived_rel_v5_context_post_id() {

    static $id = null;

    if ( null !== $id ) {
        return $id;
    }

    $id     = 0;
    $object = get_queried_object();

    /* Normale post/CPT. */
    if (
        $object instanceof WP_Post &&
        'elementor_library' !== get_post_type( $object->ID )
    ) {
        return $id = (int) $object->ID;
    }

    /* Elementor Theme Builder template. */
    if (
        $object instanceof WP_Post &&
        'elementor_library' === get_post_type( $object->ID )
    ) {
        $template_id = (int) $object->ID;

        if (
            did_action( 'elementor/loaded' ) &&
            class_exists( '\Elementor\Plugin' )
        ) {
            try {
                $document = \Elementor\Plugin::$instance
                    ->documents
                    ->get( $template_id );

                if ( $document ) {
                    $preview_id = absint(
                        $document->get_settings( 'preview_id' )
                    );

                    if (
                        $preview_id &&
                        'elementor_library' !== get_post_type( $preview_id )
                    ) {
                        return $id = $preview_id;
                    }
                }
            } catch ( Throwable $e ) {}
        }

        $settings = get_post_meta(
            $template_id,
            '_elementor_page_settings',
            true
        );

        $preview_id = is_array( $settings )
            ? absint( $settings['preview_id'] ?? 0 )
            : 0;

        if (
            $preview_id &&
            'elementor_library' !== get_post_type( $preview_id )
        ) {
            return $id = $preview_id;
        }
    }

    /* preview_id fallback. */
    if ( ! empty( $_GET['preview_id'] ) ) {
        $preview_id = absint(
            wp_unslash( $_GET['preview_id'] )
        );

        if (
            $preview_id &&
            'elementor_library' !== get_post_type( $preview_id )
        ) {
            return $id = $preview_id;
        }
    }

    /* Laatste fallback. */
    global $post;

    if (
        $post instanceof WP_Post &&
        'elementor_library' !== get_post_type( $post->ID )
    ) {
        return $id = (int) $post->ID;
    }

    return 0;
}


/**
 * ============================================================
 * RELATIONSHIPS VAN HUIDIGE CPT
 * ============================================================
 *
 * Resultaat:
 *
 * [
 *     'functienaam'    => [226],
 *     'functie-inhoud' => [220],
 *     'kennisgebied'    => [310],
 * ]
 */

function tfsc_derived_rel_v5_relationship_groups() {

    static $resolved = false;
    static $groups   = [];

    if ( $resolved ) {
        return $groups;
    }

    $resolved = true;

    if ( ! function_exists( 'pods' ) ) {
        return [];
    }

    $post_id = tfsc_derived_rel_v5_context_post_id();

    if ( ! $post_id ) {
        return [];
    }

    $pod = pods(
        get_post_type( $post_id ),
        $post_id
    );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        return [];
    }

    $fields = $pod->fields();

    if ( ! is_array( $fields ) ) {
        return [];
    }

    foreach ( $fields as $field_name => $definition ) {

        if (
            ! is_string( $field_name ) ||
            strpos( $field_name, 'relationship_' ) !== 0 ||
            'relationship_vacature_button_url' === $field_name
        ) {
            continue;
        }

        $value = $pod->field( $field_name );

        if ( empty( $value ) ) {
            continue;
        }

        /*
         * Enkel relationship-object naar lijst.
         */
        if (
            is_object( $value ) ||
            (
                is_array( $value ) &&
                (
                    isset( $value['term_id'] ) ||
                    isset( $value['pod_item_id'] ) ||
                    isset( $value['id'] ) ||
                    isset( $value['ID'] )
                )
            )
        ) {
            $value = [ $value ];
        }

        if ( ! is_array( $value ) ) {
            continue;
        }

        foreach ( $value as $relation ) {

            if ( is_array( $relation ) ) {
                $taxonomy = sanitize_key(
                    $relation['taxonomy'] ?? ''
                );

                $term_id = (int) (
                    $relation['term_id']
                    ?? $relation['pod_item_id']
                    ?? $relation['id']
                    ?? $relation['ID']
                    ?? 0
                );

            } elseif ( is_object( $relation ) ) {
                $taxonomy = sanitize_key(
                    $relation->taxonomy ?? ''
                );

                $term_id = (int) (
                    $relation->term_id
                    ?? $relation->pod_item_id
                    ?? $relation->id
                    ?? $relation->ID
                    ?? 0
                );

            } else {
                continue;
            }

            if (
                ! $taxonomy ||
                ! $term_id ||
                ! taxonomy_exists( $taxonomy )
            ) {
                continue;
            }

            $term = get_term(
                $term_id,
                $taxonomy
            );

            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }

            /* ID als key = direct uniek. */
            $groups[ $taxonomy ][ $term_id ] = $term_id;
        }
    }

    foreach ( $groups as $taxonomy => $ids ) {
        $groups[ $taxonomy ] = array_values( $ids );
    }

    return $groups;
}


/**
 * ============================================================
 * OPEN VACATURES
 * ============================================================
 */

function tfsc_derived_rel_v5_vacancy_ids(
    array $groups
) {

    static $cache = [];

    if ( ! $groups ) {
        return [];
    }

    /* Stabiele cache-key. */
    ksort( $groups );

    foreach ( $groups as &$ids ) {
        sort( $ids, SORT_NUMERIC );
    }
    unset( $ids );

    $key = md5( serialize( $groups ) );

    if ( isset( $cache[ $key ] ) ) {
        return $cache[ $key ];
    }

    $tax_query = [
        'relation' => 'AND',
    ];

    foreach ( $groups as $taxonomy => $term_ids ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $term_ids
        ) {
            continue;
        }

        $tax_query[] = [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => $term_ids,
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    if ( count( $tax_query ) === 1 ) {
        return [];
    }

    if ( taxonomy_exists( TFSC_STATUS_TAXONOMY ) ) {
        $tax_query[] = [
            'taxonomy'         => TFSC_STATUS_TAXONOMY,
            'field'            => 'slug',
            'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    $ids = get_posts( [
        'post_type'        => TFSC_VACANCY_POST_TYPE,
        'post_status'      => 'publish',
        'posts_per_page'   => -1,
        'fields'           => 'ids',
        'no_found_rows'    => true,
        'suppress_filters' => false,
        'tax_query'        => $tax_query,
    ] );

    return $cache[ $key ] = array_map(
        'intval',
        $ids
    );
}


/**
 * ============================================================
 * TARGET TERMS + LEVEL
 * ============================================================
 */

function tfsc_derived_rel_v5_target_terms(
    array $vacancy_ids,
    $taxonomy,
    $level
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }

    $ids = wp_get_object_terms(
        $vacancy_ids,
        $taxonomy,
        [ 'fields' => 'ids' ]
    );

    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }

    $level        = (int) $level;
    $hierarchical = is_taxonomy_hierarchical( $taxonomy );
    $all          = [];

    /*
     * Directe terms + ancestors verzamelen.
     */
    foreach ( $ids as $term_id ) {

        $term_id = (int) $term_id;

        if ( ! $term_id ) {
            continue;
        }

        $all[ $term_id ] = $term_id;

        if ( $hierarchical ) {
            foreach (
                get_ancestors(
                    $term_id,
                    $taxonomy,
                    'taxonomy'
                )
                as $ancestor_id
            ) {
                $all[ (int) $ancestor_id ] =
                    (int) $ancestor_id;
            }
        }
    }

    /*
     * Niet-hiërarchisch bestaat alleen level 0.
     */
    if ( ! $hierarchical ) {
        return 0 === $level
            ? array_values( $all )
            : [];
    }

    return array_values(
        array_filter(
            $all,
            static function( $term_id ) use (
                $taxonomy,
                $level
            ) {
                return count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === $level;
            }
        )
    );
}


/**
 * ============================================================
 * ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings['post_taxonomy_term_taxonomy_id']
            ??
            '';

        if (
            ! preg_match(
                '/^relationship_level_([0-9]+)$/',
                (string) $query_id,
                $match
            )
        ) {
            return $args;
        }

        /*
         * Elementor Source bepaalt target taxonomy.
         */
        $taxonomy =
            $args['taxonomy']
            ??
            $settings['post_taxonomy_query_post_type']
            ??
            '';

        if ( is_array( $taxonomy ) ) {
            $taxonomy = reset( $taxonomy );
        }

        $taxonomy = sanitize_key( $taxonomy );

        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy ) ||
            TFSC_STATUS_TAXONOMY === $taxonomy
        ) {
            return $args;
        }

        $groups = tfsc_derived_rel_v5_relationship_groups();

        if ( ! $groups ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $vacancy_ids =
            tfsc_derived_rel_v5_vacancy_ids(
                $groups
            );

        if ( ! $vacancy_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $target_ids =
            tfsc_derived_rel_v5_target_terms(
                $vacancy_ids,
                $taxonomy,
                (int) $match[1]
            );

        if ( ! $target_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        unset( $args['term_taxonomy_id'] );

        $args['taxonomy']     = $taxonomy;
        $args['include']      = $target_ids;
        $args['hide_empty']   = false;
        $args['hierarchical'] = false;

        /* Sortering + combo-link marker. */
        $args['tfsc_derived_rel_v5'] = true;

        $GLOBALS[
            'tfsc_derived_rel_v5_active_targets'
        ][ $taxonomy ] = true;

        return $args;
    },
    30,
    3
);


/**
 * ============================================================
 * ALFABETISCHE SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            is_admin() ||
            empty( $args['tfsc_derived_rel_v5'] ) ||
            ! is_array( $terms ) ||
            ! $terms ||
            (
                isset( $args['orderby'] ) &&
                'name' !== strtolower(
                    (string) $args['orderby']
                )
            )
        ) {
            return $terms;
        }

        $descending =
            'DESC' === strtoupper(
                (string) ( $args['order'] ?? 'ASC' )
            );

        usort(
            $terms,
            static function( $a, $b ) use ( $descending ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }

                $compare = strnatcasecmp(
                    remove_accents(
                        wp_strip_all_tags( $a->name )
                    ),
                    remove_accents(
                        wp_strip_all_tags( $b->name )
                    )
                );

                return $descending
                    ? -$compare
                    : $compare;
            }
        );

        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * CENTRALE COMBO URL
 * ============================================================
 */

function tfsc_derived_rel_v5_combo_url(
    WP_Term $target
) {

    if (
        ! function_exists( 'tfsc_urlcore_create_item' ) ||
        ! function_exists( 'tfsc_build_combo_url' )
    ) {
        return false;
    }

    $groups = tfsc_derived_rel_v5_relationship_groups();

    if ( ! $groups ) {
        return false;
    }

    $combo = [];

    foreach ( $groups as $taxonomy => $term_ids ) {

        foreach ( $term_ids as $term_id ) {

            /*
             * Target niet dubbel opnemen.
             */
            if (
                $taxonomy === $target->taxonomy &&
                (int) $term_id === (int) $target->term_id
            ) {
                continue;
            }

            $term = get_term(
                $term_id,
                $taxonomy
            );

            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }

            $item = tfsc_urlcore_create_item( $term );

            if ( $item ) {
                $combo[] = $item;
            }
        }
    }

    $target_item =
        tfsc_urlcore_create_item(
            $target
        );

    if ( ! $target_item ) {
        return false;
    }

    $combo[] = $target_item;

    return tfsc_build_combo_url( $combo );
}


/**
 * ============================================================
 * TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty( $GLOBALS['tfsc_force_native_term_link'] ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! tfsc_derived_rel_v5_context_post_id() ||
            TFSC_STATUS_TAXONOMY === $taxonomy ||
            empty(
                $GLOBALS[
                    'tfsc_derived_rel_v5_active_targets'
                ][
                    $taxonomy
                ]
            )
        ) {
            return $termlink;
        }

        $url =
            tfsc_derived_rel_v5_combo_url(
                $term
            );

        return $url ?: $termlink;
    },
    30,
    3
);

/**
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 6 - Compact
 *
 * Huidige taxonomy-term
 * → relationship_* velden
 * → overeenkomende OPEN vacatures
 * → terms uit Elementor Source taxonomy
 * → level-filter
 * → combo-links via centrale URL builder
 *
 * Query IDs:
 * archive_relationship_level_0
 * archive_relationship_level_1
 * archive_relationship_level_2
 *
 * Verschillende taxonomies = AND
 * Meerdere terms binnen taxonomy = OR / IN
 */


/**
 * ============================================================
 * HUIDIGE TAXONOMY TERM
 * ============================================================
 *
 * Inclusief Elementor Theme Builder preview-fix.
 */

function tfsc_taxrel_v6_current_term() {

    static $resolved = false;
    static $term = false;

    if ( $resolved ) {
        return $term;
    }

    $resolved = true;
    $object = get_queried_object();

    /* Normale taxonomy archive / preview iframe. */
    if (
        $object instanceof WP_Term &&
        $object->term_id &&
        $object->taxonomy &&
        taxonomy_exists( $object->taxonomy )
    ) {
        if ( is_user_logged_in() ) {
            set_transient(
                'tfsc_taxrel_v6_preview_' . get_current_user_id(),
                [
                    'term_id'  => (int) $object->term_id,
                    'taxonomy' => $object->taxonomy,
                ],
                5 * MINUTE_IN_SECONDS
            );
        }

        return $term = $object;
    }

    /* Elementor admin-render. */
    if (
        ! is_admin() ||
        ! is_user_logged_in() ||
        ! $object instanceof WP_Post
    ) {
        return false;
    }

    $preview = get_transient(
        'tfsc_taxrel_v6_preview_' . get_current_user_id()
    );

    if (
        ! is_array( $preview ) ||
        empty( $preview['term_id'] ) ||
        empty( $preview['taxonomy'] ) ||
        ! taxonomy_exists( $preview['taxonomy'] )
    ) {
        return false;
    }

    $settings = get_post_meta(
        $object->ID,
        '_elementor_page_settings',
        true
    );

    if (
        ! is_array( $settings ) ||
        ( $settings['preview_type'] ?? '' ) !==
            'taxonomy/' . $preview['taxonomy']
    ) {
        return false;
    }

    $candidate = get_term(
        (int) $preview['term_id'],
        $preview['taxonomy']
    );

    if (
        $candidate instanceof WP_Term &&
        ! is_wp_error( $candidate )
    ) {
        $term = $candidate;
    }

    return $term;
}


/**
 * ============================================================
 * RELATIONSHIPS VAN HUIDIGE TERM
 * ============================================================
 *
 * Resultaat:
 *
 * [
 *     'functienaam'    => [226],
 *     'functie-inhoud' => [220],
 *     'kennisgebied'    => [310],
 * ]
 */

function tfsc_taxrel_v6_relationship_groups() {

    static $resolved = false;
    static $groups = [];

    if ( $resolved ) {
        return $groups;
    }

    $resolved = true;

    if ( ! function_exists( 'pods' ) ) {
        return [];
    }

    $current = tfsc_taxrel_v6_current_term();

    if ( ! $current ) {
        return [];
    }

    $pod = pods(
        $current->taxonomy,
        (int) $current->term_id
    );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        return [];
    }

    $fields = $pod->fields();

    if ( ! is_array( $fields ) ) {
        return [];
    }

    foreach ( $fields as $field_name => $definition ) {

        if (
            ! is_string( $field_name ) ||
            strpos( $field_name, 'relationship_' ) !== 0 ||
            'relationship_vacature_button_url' === $field_name
        ) {
            continue;
        }

        $value = $pod->field( $field_name );

        if ( empty( $value ) ) {
            continue;
        }

        /*
         * Eén Pods-resultaat naar lijst normaliseren.
         */
        if (
            is_numeric( $value ) ||
            is_object( $value ) ||
            (
                is_array( $value ) &&
                (
                    isset( $value['term_id'] ) ||
                    isset( $value['pod_item_id'] ) ||
                    isset( $value['id'] ) ||
                    isset( $value['ID'] )
                )
            )
        ) {
            $value = [ $value ];
        }

        $fallback_taxonomy = sanitize_key(
            substr(
                $field_name,
                strlen( 'relationship_' )
            )
        );

        foreach ( (array) $value as $relation ) {

            $term_id = 0;
            $taxonomy = '';

            if ( is_array( $relation ) ) {
                $term_id = (int) (
                    $relation['term_id']
                    ?? $relation['pod_item_id']
                    ?? $relation['id']
                    ?? $relation['ID']
                    ?? 0
                );

                $taxonomy = sanitize_key(
                    $relation['taxonomy'] ?? ''
                );

            } elseif ( is_object( $relation ) ) {
                $term_id = (int) (
                    $relation->term_id
                    ?? $relation->pod_item_id
                    ?? $relation->id
                    ?? $relation->ID
                    ?? 0
                );

                $taxonomy = sanitize_key(
                    $relation->taxonomy ?? ''
                );

            } elseif ( is_numeric( $relation ) ) {
                $term_id = (int) $relation;
            }

            if ( ! $taxonomy ) {
                $taxonomy = $fallback_taxonomy;
            }

            if (
                ! $term_id ||
                ! $taxonomy ||
                ! taxonomy_exists( $taxonomy )
            ) {
                continue;
            }

            $term = get_term(
                $term_id,
                $taxonomy
            );

            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }

            /* ID als key voorkomt duplicaten direct. */
            $groups[ $taxonomy ][ $term_id ] = $term_id;
        }
    }

    foreach ( $groups as $taxonomy => $ids ) {
        $groups[ $taxonomy ] = array_values( $ids );
    }

    return $groups;
}


/**
 * ============================================================
 * OPEN VACATURES
 * ============================================================
 */

function tfsc_taxrel_v6_vacancy_ids(
    array $groups
) {

    static $cache = [];

    if ( ! $groups ) {
        return [];
    }

    ksort( $groups );

    foreach ( $groups as &$ids ) {
        sort( $ids, SORT_NUMERIC );
    }
    unset( $ids );

    $key = md5( serialize( $groups ) );

    if ( isset( $cache[ $key ] ) ) {
        return $cache[ $key ];
    }

    $tax_query = [
        'relation' => 'AND',
    ];

    foreach ( $groups as $taxonomy => $ids ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $ids
        ) {
            continue;
        }

        $tax_query[] = [
            'taxonomy'         => $taxonomy,
            'field'            => 'term_id',
            'terms'            => $ids,
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    if ( count( $tax_query ) === 1 ) {
        return [];
    }

    if ( taxonomy_exists( TFSC_STATUS_TAXONOMY ) ) {
        $tax_query[] = [
            'taxonomy'         => TFSC_STATUS_TAXONOMY,
            'field'            => 'slug',
            'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
            'operator'         => 'IN',
            'include_children' => false,
        ];
    }

    $ids = get_posts( [
        'post_type'      => TFSC_VACANCY_POST_TYPE,
        'post_status'    => 'publish',
        'posts_per_page' => -1,
        'fields'         => 'ids',
        'no_found_rows'  => true,
        'tax_query'      => $tax_query,
    ] );

    return $cache[ $key ] =
        array_map( 'intval', $ids );
}


/**
 * ============================================================
 * TARGET TERMS + LEVEL
 * ============================================================
 */

function tfsc_taxrel_v6_target_terms(
    array $vacancy_ids,
    $taxonomy,
    $level
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }

    $ids = wp_get_object_terms(
        $vacancy_ids,
        $taxonomy,
        [ 'fields' => 'ids' ]
    );

    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }

    $level = (int) $level;
    $hierarchical = is_taxonomy_hierarchical( $taxonomy );
    $all = [];

    foreach ( $ids as $term_id ) {

        $term_id = (int) $term_id;

        if ( ! $term_id ) {
            continue;
        }

        $all[ $term_id ] = $term_id;

        if ( $hierarchical ) {
            foreach (
                get_ancestors(
                    $term_id,
                    $taxonomy,
                    'taxonomy'
                )
                as $ancestor_id
            ) {
                $ancestor_id = (int) $ancestor_id;
                $all[ $ancestor_id ] = $ancestor_id;
            }
        }
    }

    if ( ! $hierarchical ) {
        return 0 === $level
            ? array_values( $all )
            : [];
    }

    return array_values(
        array_filter(
            $all,
            static function( $term_id ) use (
                $taxonomy,
                $level
            ) {
                return count(
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === $level;
            }
        )
    );
}


/**
 * ============================================================
 * ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings['post_taxonomy_term_taxonomy_id']
            ??
            '';

        if (
            ! preg_match(
                '/^archive_relationship_level_([0-9]+)$/',
                (string) $query_id,
                $match
            ) ||
            ! tfsc_taxrel_v6_current_term()
        ) {
            return $args;
        }

        /*
         * Elementor Source bepaalt target taxonomy.
         */
        $taxonomy =
            $args['taxonomy']
            ??
            $settings['post_taxonomy_query_post_type']
            ??
            '';

        if ( is_array( $taxonomy ) ) {
            $taxonomy = reset( $taxonomy );
        }

        $taxonomy = sanitize_key( $taxonomy );

        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy ) ||
            TFSC_STATUS_TAXONOMY === $taxonomy
        ) {
            return $args;
        }

        $groups = tfsc_taxrel_v6_relationship_groups();

        if ( ! $groups ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $vacancy_ids =
            tfsc_taxrel_v6_vacancy_ids(
                $groups
            );

        if ( ! $vacancy_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        $target_ids =
            tfsc_taxrel_v6_target_terms(
                $vacancy_ids,
                $taxonomy,
                (int) $match[1]
            );

        if ( ! $target_ids ) {
            $args['include'] = [ 0 ];
            return $args;
        }

        unset( $args['term_taxonomy_id'] );

        $args['taxonomy']     = $taxonomy;
        $args['include']      = $target_ids;
        $args['hide_empty']   = false;
        $args['hierarchical'] = false;

        $args['tfsc_taxrel_v6'] = true;

        $GLOBALS[
            'tfsc_taxrel_v6_active_targets'
        ][ $taxonomy ] = true;

        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * SORTERING OP NAAM
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty( $args['tfsc_taxrel_v6'] ) ||
            ! is_array( $terms ) ||
            ! $terms ||
            (
                isset( $args['orderby'] ) &&
                strtolower( (string) $args['orderby'] ) !== 'name'
            )
        ) {
            return $terms;
        }

        $descending =
            strtoupper(
                (string) ( $args['order'] ?? 'ASC' )
            ) === 'DESC';

        usort(
            $terms,
            static function( $a, $b ) use ( $descending ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }

                $result = strnatcasecmp(
                    remove_accents( $a->name ),
                    remove_accents( $b->name )
                );

                return $descending
                    ? -$result
                    : $result;
            }
        );

        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * CENTRALE COMBO URL
 * ============================================================
 */

function tfsc_taxrel_v6_combo_url(
    WP_Term $target
) {

    if (
        ! function_exists( 'tfsc_urlcore_create_item' ) ||
        ! function_exists( 'tfsc_build_combo_url' )
    ) {
        return false;
    }

    $groups = tfsc_taxrel_v6_relationship_groups();

    if ( ! $groups ) {
        return false;
    }

    $combo = [];

    foreach ( $groups as $taxonomy => $ids ) {

        foreach ( $ids as $term_id ) {

            /* Target niet dubbel toevoegen. */
            if (
                $taxonomy === $target->taxonomy &&
                (int) $term_id === (int) $target->term_id
            ) {
                continue;
            }

            $term = get_term(
                $term_id,
                $taxonomy
            );

            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }

            $item = tfsc_urlcore_create_item( $term );

            if ( $item ) {
                $combo[] = $item;
            }
        }
    }

    $target_item =
        tfsc_urlcore_create_item(
            $target
        );

    if ( ! $target_item ) {
        return false;
    }

    $combo[] = $target_item;

    return tfsc_build_combo_url( $combo );
}


/**
 * ============================================================
 * TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty( $GLOBALS['tfsc_force_native_term_link'] ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! tfsc_taxrel_v6_current_term() ||
            TFSC_STATUS_TAXONOMY === $taxonomy ||
            empty(
                $GLOBALS[
                    'tfsc_taxrel_v6_active_targets'
                ][
                    $taxonomy
                ]
            )
        ) {
            return $termlink;
        }

        $url =
            tfsc_taxrel_v6_combo_url(
                $term
            );

        return $url ?: $termlink;
    },
    40,
    3
);

/**
 * TFSC - Combo Vacancy Sitemap
 * Version 6 - Compact
 *
 * - Alleen gepubliceerde + OPEN vacatures
 * - Alleen werkelijk bestaande combinaties
 * - Exact 2 taxonomies per combo
 * - tfsc_combo_should_index() bepaalt indexeerbaarheid
 * - URL's uitsluitend via tfsc_build_combo_url()
 * - lastmod per combo
 * - lastmod in sitemap index
 * - transient cache + automatische invalidatie
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS' ) ) {
    define( 'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS', 2 );
}

if ( ! defined( 'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS' ) ) {
    define( 'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS', 2 );
}

if ( ! defined( 'TFSC_COMBO_SITEMAP_CACHE_KEY' ) ) {
    define( 'TFSC_COMBO_SITEMAP_CACHE_KEY', 'tfsc_combo_sitemap_links_v6' );
}

if ( ! defined( 'TFSC_COMBO_SITEMAP_CACHE_TTL' ) ) {
    define( 'TFSC_COMBO_SITEMAP_CACHE_TTL', DAY_IN_SECONDS );
}


/**
 * ============================================================
 * TAXONOMY VOLGORDE
 * ============================================================
 *
 * Alleen voor generatie.
 * De URL Core bepaalt uiteindelijk zelf de URL-volgorde.
 */

function tfsc_combo_sitemap_order_taxonomies( array $taxonomies ) {

    $function = TFSC_COMBO_FUNCTION_TAXONOMY;

    usort(
        $taxonomies,
        static function( $a, $b ) use ( $function ) {

            if ( $a === $function ) {
                return -1;
            }

            if ( $b === $function ) {
                return 1;
            }

            return 0;
        }
    );

    return $taxonomies;
}


/**
 * ============================================================
 * LASTMOD
 * ============================================================
 */

function tfsc_combo_sitemap_post_lastmod( $post_id ) {

    $gmt = get_post_field( 'post_modified_gmt', $post_id );

    if (
        ! $gmt ||
        '0000-00-00 00:00:00' === $gmt
    ) {
        return '';
    }

    $time = strtotime( $gmt . ' GMT' );

    return $time
        ? gmdate( 'c', $time )
        : '';
}


function tfsc_combo_sitemap_newest_lastmod( $a, $b ) {

    if ( ! $a ) {
        return $b;
    }

    if ( ! $b ) {
        return $a;
    }

    $a_time = strtotime( $a );
    $b_time = strtotime( $b );

    return (
        $b_time &&
        (
            ! $a_time ||
            $b_time > $a_time
        )
    )
        ? $b
        : $a;
}


/**
 * ============================================================
 * TAXONOMY DIMENSIES VAN VACATURE
 * ============================================================
 */

function tfsc_combo_sitemap_dimensions(
    $post_id,
    array $taxonomies
) {

    $dimensions = [];

    foreach ( $taxonomies as $taxonomy ) {

        $terms = get_the_terms(
            $post_id,
            $taxonomy
        );

        if ( ! is_array( $terms ) ) {
            continue;
        }

        $object = get_taxonomy( $taxonomy );

        $include_ancestors =
            $object &&
            $object->hierarchical &&
            'AND' !== tfsc_get_combo_taxonomy_match_method( $taxonomy );

        $collected = [];

        foreach ( $terms as $term ) {

            if ( ! $term instanceof WP_Term ) {
                continue;
            }

            $collected[ $term->term_id ] = $term;

            if ( ! $include_ancestors ) {
                continue;
            }

            foreach (
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                )
                as $ancestor_id
            ) {
                $ancestor = get_term(
                    $ancestor_id,
                    $taxonomy
                );

                if (
                    $ancestor instanceof WP_Term &&
                    ! is_wp_error( $ancestor )
                ) {
                    $collected[ $ancestor->term_id ] = $ancestor;
                }
            }
        }

        if ( $collected ) {
            $dimensions[ $taxonomy ] = array_values( $collected );
        }
    }

    return $dimensions;
}


/**
 * ============================================================
 * TAXONOMY COMBINATIES
 * ============================================================
 */

function tfsc_combo_sitemap_sets(
    array $items,
    $size
) {

    $size = (int) $size;

    if (
        $size < 1 ||
        count( $items ) < $size
    ) {
        return [];
    }

    if ( 1 === $size ) {
        return array_map(
            static fn( $item ) => [ $item ],
            $items
        );
    }

    $result = [];
    $first  = array_shift( $items );

    foreach (
        tfsc_combo_sitemap_sets(
            $items,
            $size - 1
        )
        as $set
    ) {
        array_unshift( $set, $first );
        $result[] = $set;
    }

    return array_merge(
        $result,
        tfsc_combo_sitemap_sets(
            $items,
            $size
        )
    );
}


/**
 * ============================================================
 * TERM PRODUCTEN
 * ============================================================
 */

function tfsc_combo_sitemap_products(
    array $taxonomy_set,
    array $dimensions
) {

    $products = [ [] ];

    foreach (
        tfsc_combo_sitemap_order_taxonomies( $taxonomy_set )
        as $taxonomy
    ) {

        if ( empty( $dimensions[ $taxonomy ] ) ) {
            return [];
        }

        $next = [];

        foreach ( $products as $product ) {

            foreach (
                $dimensions[ $taxonomy ]
                as $term
            ) {

                if ( ! $term instanceof WP_Term ) {
                    continue;
                }

                $item = tfsc_urlcore_create_item( $term );

                if ( ! $item ) {
                    continue;
                }

                $next[] = array_merge(
                    $product,
                    [ $item ]
                );
            }
        }

        if ( ! $next ) {
            return [];
        }

        $products = $next;
    }

    return $products;
}


/**
 * ============================================================
 * SITEMAP LINKS
 * ============================================================
 */

function tfsc_combo_sitemap_generate_links() {

    if (
        ! function_exists( 'tfsc_get_allowed_combo_taxonomies' ) ||
        ! function_exists( 'tfsc_get_combo_taxonomy_match_method' ) ||
        ! function_exists( 'tfsc_combo_should_index' ) ||
        ! function_exists( 'tfsc_urlcore_create_item' ) ||
        ! function_exists( 'tfsc_build_combo_url' )
    ) {
        return [];
    }

    $cached = get_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY
    );

    if ( is_array( $cached ) ) {
        return $cached;
    }

    $taxonomies = tfsc_combo_sitemap_order_taxonomies(
        tfsc_get_allowed_combo_taxonomies()
    );

    if ( ! $taxonomies ) {
        return [];
    }

    $posts = get_posts( [
        'post_type'      => TFSC_VACANCY_POST_TYPE,
        'post_status'    => 'publish',
        'posts_per_page' => -1,
        'no_found_rows'  => true,
        'orderby'        => 'ID',
        'order'          => 'ASC',
        'tax_query'      => [
            [
                'taxonomy'         => TFSC_STATUS_TAXONOMY,
                'field'            => 'slug',
                'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
                'operator'         => 'IN',
                'include_children' => false,
            ],
        ],
    ] );

    if ( ! $posts ) {
        set_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            [],
            TFSC_COMBO_SITEMAP_CACHE_TTL
        );

        return [];
    }

    $links = [];

    foreach ( $posts as $post ) {

        if ( ! $post instanceof WP_Post ) {
            continue;
        }

        $dimensions = tfsc_combo_sitemap_dimensions(
            $post->ID,
            $taxonomies
        );

        if ( ! $dimensions ) {
            continue;
        }

        /*
         * Taxonomy-volgorde gelijk houden aan centrale lijst.
         */
        $ordered = [];

        foreach ( $taxonomies as $taxonomy ) {
            if ( isset( $dimensions[ $taxonomy ] ) ) {
                $ordered[ $taxonomy ] = $dimensions[ $taxonomy ];
            }
        }

        $dimensions = $ordered;
        $names      = array_keys( $dimensions );

        $min = max(
            2,
            (int) TFSC_COMBO_SITEMAP_MIN_DIMENSIONS
        );

        $max = min(
            count( $names ),
            max(
                $min,
                (int) TFSC_COMBO_SITEMAP_MAX_DIMENSIONS
            )
        );

        if ( $max < $min ) {
            continue;
        }

        $lastmod = tfsc_combo_sitemap_post_lastmod(
            $post->ID
        );

        for ( $size = $min; $size <= $max; $size++ ) {

            foreach (
                tfsc_combo_sitemap_sets(
                    $names,
                    $size
                )
                as $taxonomy_set
            ) {

                foreach (
                    tfsc_combo_sitemap_products(
                        $taxonomy_set,
                        $dimensions
                    )
                    as $combo
                ) {

                    if ( ! tfsc_combo_should_index( $combo ) ) {
                        continue;
                    }

                    $url = tfsc_build_combo_url( $combo );

                    if ( ! $url ) {
                        continue;
                    }

                    if ( ! isset( $links[ $url ] ) ) {
                        $links[ $url ] = [
                            'loc'     => $url,
                            'lastmod' => $lastmod,
                        ];

                        continue;
                    }

                    $links[ $url ]['lastmod'] =
                        tfsc_combo_sitemap_newest_lastmod(
                            $links[ $url ]['lastmod'] ?? '',
                            $lastmod
                        );
                }
            }
        }
    }

    ksort( $links, SORT_STRING );

    $links = array_values( $links );

    set_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY,
        $links,
        TFSC_COMBO_SITEMAP_CACHE_TTL
    );

    return $links;
}


/**
 * ============================================================
 * CACHE INVALIDATIE
 * ============================================================
 */

function tfsc_combo_sitemap_flush_cache() {

    foreach (
        [
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            'tfsc_combo_sitemap_links_v1',
            'tfsc_combo_sitemap_links_v2',
            'tfsc_combo_sitemap_links_v3',
            'tfsc_combo_sitemap_links_v4',
            'tfsc_combo_sitemap_links_v5',
        ]
        as $key
    ) {
        delete_transient( $key );
    }

    if (
        class_exists( '\RankMath\Sitemap\Cache' ) &&
        method_exists(
            '\RankMath\Sitemap\Cache',
            'invalidate_storage'
        )
    ) {
        \RankMath\Sitemap\Cache::invalidate_storage(
            'combo-vacatures'
        );
    }
}


