/**
 * ============================================================
 * RANK MATH PROVIDER
 * ============================================================
 */

add_filter(
    'rank_math/sitemap/providers',
    function( $providers ) {

        if (
            ! interface_exists(
                '\RankMath\Sitemap\Providers\Provider'
            )
        ) {
            return $providers;
        }

        if (
            ! class_exists(
                'TFSC_Combo_Vacancy_Sitemap_Provider',
                false
            )
        ) {
            class TFSC_Combo_Vacancy_Sitemap_Provider
                implements \RankMath\Sitemap\Providers\Provider {

                public function handles_type( $type ) {
                    return 'combo-vacatures' === $type;
                }

                public function get_index_links( $max_entries ) {

                    $links = tfsc_combo_sitemap_generate_links();

                    if ( ! $links ) {
                        return [];
                    }

                    $max_entries = max(
                        1,
                        (int) $max_entries
                    );

                    $pages = max(
                        1,
                        (int) ceil(
                            count( $links ) / $max_entries
                        )
                    );

                    $index = [];

                    for ( $page = 1; $page <= $pages; $page++ ) {

                        $page_links = array_slice(
                            $links,
                            ( $page - 1 ) * $max_entries,
                            $max_entries
                        );

                        $lastmod = '';

                        foreach ( $page_links as $link ) {
                            $lastmod =
                                tfsc_combo_sitemap_newest_lastmod(
                                    $lastmod,
                                    $link['lastmod'] ?? ''
                                );
                        }

                        $index[] = [
                            'loc' =>
                                \RankMath\Sitemap\Router::get_base_url(
                                    'combo-vacatures-sitemap'
                                    .
                                    ( $pages > 1 ? $page : '' )
                                    .
                                    '.xml'
                                ),

                            'lastmod' =>
                                $lastmod,
                        ];
                    }

                    return $index;
                }

                public function get_sitemap_links(
                    $type,
                    $max_entries,
                    $current_page
                ) {

                    if ( 'combo-vacatures' !== $type ) {
                        return [];
                    }

                    $links = tfsc_combo_sitemap_generate_links();

                    if ( ! $links ) {
                        return [];
                    }

                    $max_entries = max(
                        1,
                        (int) $max_entries
                    );

                    $page = max(
                        1,
                        (int) $current_page
                    );

                    return array_slice(
                        $links,
                        ( $page - 1 ) * $max_entries,
                        $max_entries
                    );
                }
            }
        }

        $providers['combo-vacatures'] =
            new TFSC_Combo_Vacancy_Sitemap_Provider();

        return $providers;
    }
);

/**
 * TFSC - Volledig dynamische vacature-archieven
 * Version 5 - Compact
 *
 * Vereist:
 * - TFSC - Combo Archive URLs
 *
 * Regelt:
 * - /vacatures/... combo archives
 * - pagination
 * - verschillende taxonomies = AND
 * - meerdere terms binnen taxonomy = OR
 * - kennisgebied = AND
 * - alleen OPEN vacatures
 * - native vacature-taxonomy archives
 * - Search & Filter Pro v3 sync
 * - Elementor archive conditions
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 */


/* ============================================================
 * CONFIG + COMPATIBILITEIT
 * ============================================================ */

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}

/*
 * Deze publieke functies blijven bestaan voor andere
 * TFSC-snippets, maar de URL Core bevat de echte logica.
 */
function tfsc_combo_taxonomy_allowed( $taxonomy ) {
    return function_exists( 'tfsc_urlcore_taxonomy_allowed' )
        && tfsc_urlcore_taxonomy_allowed( $taxonomy );
}

function tfsc_get_allowed_combo_taxonomies() {
    return function_exists( 'tfsc_urlcore_get_allowed_taxonomies' )
        ? tfsc_urlcore_get_allowed_taxonomies()
        : [];
}

function tfsc_resolve_term_path( $taxonomy, $segments ) {
    return function_exists( 'tfsc_urlcore_resolve_term_path' )
        ? tfsc_urlcore_resolve_term_path( $taxonomy, $segments )
        : false;
}


/* ============================================================
 * HELPERS
 * ============================================================ */

function tfsc_get_combo_taxonomy_match_method( $taxonomy ) {
    return 'kennisgebied' === $taxonomy ? 'AND' : 'OR';
}

function tfsc_combo_status_clause() {
    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}

function tfsc_is_combo_archive() {
    return (bool) get_query_var( 'tfsc_combo_archive' );
}

function tfsc_is_vacancy_seo_landing() {

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term = get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed( $term->taxonomy )
    );
}


/* ============================================================
 * QUERY VARS + REWRITES
 * ============================================================ */

add_filter( 'query_vars', function( $vars ) {
    $vars[] = 'tfsc_combo_archive';
    $vars[] = 'tfsc_combo_path';
    return $vars;
} );

add_action( 'init', function() {

    /*
     * Pagination moet voor de algemene combo-regel staan.
     */
    add_rewrite_rule(
        '^' . preg_quote( TFSC_COMBO_BASE, '/' ) . '/(.+?)/page/([0-9]+)/?$',
        'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]&paged=$matches[2]',
        'top'
    );

    add_rewrite_rule(
        '^' . preg_quote( TFSC_COMBO_BASE, '/' ) . '/(.+?)/?$',
        'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]',
        'top'
    );

}, 99 );


/* ============================================================
 * COMBO PARSER
 * ============================================================ */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;

    if ( $resolved ) {
        return $cache;
    }

    $resolved = true;

    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }

    $path = trim(
        (string) get_query_var( 'tfsc_combo_path' ),
        '/'
    );

    if ( ! $path ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            explode( '/', $path ),
            'strlen'
        )
    );

    if ( count( $segments ) < 2 ) {
        return false;
    }

    $allowed = tfsc_get_allowed_combo_taxonomies();

    if ( ! $allowed ) {
        return false;
    }

    $items = [];
    $count = count( $segments );
    $i     = 0;

    while ( $i < $count ) {

        $taxonomy = sanitize_key( $segments[ $i++ ] );

        if ( ! in_array( $taxonomy, $allowed, true ) ) {
            return false;
        }

        $term_segments = [];

        while ( $i < $count ) {

            $possible_taxonomy = sanitize_key(
                $segments[ $i ]
            );

            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }

            $term_segments[] = $segments[ $i++ ];
        }

        if ( ! $term_segments ) {
            return false;
        }

        $resolved_path = tfsc_resolve_term_path(
            $taxonomy,
            $term_segments
        );

        if ( ! $resolved_path ) {
            return false;
        }

        $items[] = [
            'taxonomy' => $taxonomy,
            'term'     => $resolved_path['term'],
            'path'     => $resolved_path['path'],
        ];
    }

    return $cache = ( $items ?: false );
}


/* ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================ */

function tfsc_group_combo_terms( $property = 'term_id' ) {

    $combo = tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    $grouped = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $term = $item['term'];

        switch ( $property ) {
            case 'name':
                $value = trim( $term->name );
                break;

            case 'slug':
                $value = $term->slug;
                break;

            default:
                $value = (int) $term->term_id;
        }

        if ( '' === $value || 0 === $value ) {
            continue;
        }

        /*
         * Value als key voorkomt dubbelen zonder in_array().
         */
        $key = is_int( $value )
            ? $value
            : (string) $value;

        $grouped[
            $item['taxonomy']
        ][ $key ] = $value;
    }

    foreach ( $grouped as $taxonomy => $values ) {
        $grouped[ $taxonomy ] = array_values( $values );
    }

    return $grouped;
}


/* ============================================================
 * COMBO TAX QUERY
 * ============================================================ */

function tfsc_build_combo_tax_query() {

    $groups = tfsc_group_combo_terms();

    if ( ! $groups ) {
        return false;
    }

    $tax_query = [
        'relation' => 'AND',
        tfsc_combo_status_clause(),
    ];

    foreach ( $groups as $taxonomy => $term_ids ) {

        if ( ! $term_ids ) {
            continue;
        }

        $object = get_taxonomy( $taxonomy );
        $method = tfsc_get_combo_taxonomy_match_method( $taxonomy );

        $tax_query[] = [
            'taxonomy' => $taxonomy,
            'field'    => 'term_id',
            'terms'    => $term_ids,

            'operator' =>
                'AND' === $method && count( $term_ids ) > 1
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                'AND' !== $method &&
                $object &&
                $object->hierarchical,
        ];
    }

    return $tax_query;
}


/* ============================================================
 * MAIN QUERY
 * ============================================================ */

add_action( 'pre_get_posts', function( $query ) {

    if (
        is_admin() ||
        ! $query->is_main_query()
    ) {
        return;
    }

    /*
     * Virtueel combo archive.
     */
    if ( tfsc_is_combo_archive() ) {

        $tax_query = tfsc_build_combo_tax_query();

        if ( ! $tax_query ) {
            return;
        }

        $query->set( 'post_type', TFSC_VACANCY_POST_TYPE );
        $query->set( 'post_status', 'publish' );
        $query->set( 'tax_query', $tax_query );
        $query->set( 'no_found_rows', false );

        return;
    }

    /*
     * Native vacature-taxonomy archive.
     */
    if ( ! $query->is_tax() ) {
        return;
    }

    $term = $query->get_queried_object();

    if (
        ! $term instanceof WP_Term ||
        ! tfsc_combo_taxonomy_allowed( $term->taxonomy )
    ) {
        return;
    }

    $tax_query = $query->get( 'tax_query' );

    if ( ! is_array( $tax_query ) ) {
        $tax_query = [];
    }

    $tax_query[]          = tfsc_combo_status_clause();
    $tax_query['relation'] = 'AND';

    $query->set( 'post_type', TFSC_VACANCY_POST_TYPE );
    $query->set( 'post_status', 'publish' );
    $query->set( 'tax_query', $tax_query );

}, 1 );


/* ============================================================
 * COMBO ARCHIVE STATUS + 404
