function tfsc_combo_heading_html( $rows ) {

    $rows = array_values(
        array_filter(
            (array) $rows,
            'strlen'
        )
    );

    if ( ! $rows ) {
        return '';
    }

    $html = '<span class="tfsc-heading">';

    foreach ( $rows as $i => $row ) {
        $html .= sprintf(
            '<span class="%s">%s</span>',
            0 === $i
                ? 'tfsc-heading__main'
                : 'tfsc-heading__row',
            esc_html( $row )
        );
    }

    return $html . '</span>';
}


