add_shortcode( 'combo_heading', function() {

    /*
     * Combo archive.
     */
    if ( tfsc_is_combo_archive() ) {

        $groups = tfsc_group_combo_terms( 'name' );

        if ( ! $groups ) {
            return '';
        }

        $rows      = [];
        $functions = $groups[
            TFSC_COMBO_FUNCTION_TAXONOMY
        ] ?? [];

        if ( $functions ) {

            if ( 1 === count( $functions ) ) {
                $rows[] = $functions[0] . ' vacatures';
            } else {
                $rows[] = 'Vacatures';
                $rows[] = implode( ', ', $functions );
            }

            unset(
                $groups[
                    TFSC_COMBO_FUNCTION_TAXONOMY
                ]
            );

        } else {
            $rows[] = 'Vacatures';
        }

        foreach ( $groups as $names ) {
            if ( $names ) {
                $rows[] = implode( ', ', $names );
            }
        }

        return tfsc_combo_heading_html( $rows );
    }

    /*
     * Native taxonomy archive.
     */
    $term = get_queried_object();

    if (
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed( $term->taxonomy )
    ) {

        $title = get_term_meta(
            $term->term_id,
            'pods_archive_title',
            true
        );

        $title = is_string( $title )
            ? trim(
                wp_strip_all_tags( $title )
            )
            : '';

        if ( '' === $title ) {
            $title = trim( $term->name );

            if ( '' === $title ) {
                return '';
            }

            $title .= ' vacatures';
        }

        return tfsc_combo_heading_html(
            [ $title ]
        );
    }

    /*
     * Hoofd vacaturearchive.
     */
    return is_post_type_archive(
        TFSC_VACANCY_POST_TYPE
    )
        ? tfsc_combo_heading_html(
            [ 'Vacatures' ]
        )
        : '';
} );


