/**
 * TFSC - Combo Archive SEO + Native Canonicals + Filter SEO
 * Version 4 - Compact
 *
 * Vereist:
 * - TFSC - Combo Archive URLs
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * Regelt:
 * - Combo title / description / canonical / robots
 * - Centrale indexeringslogica voor SEO + sitemap
 * - Native taxonomy canonical → combo
 * - Search & Filter URLs → noindex, follow
 * - Search & Filter canonical → schoon /vacatures/
 */


/* ============================================================
 * CONFIG
 * ============================================================ */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {
    define( 'TFSC_COMBO_SEO_BRAND', 'The Field Service Company' );
}

if ( ! defined( 'TFSC_COMBO_SEO_MAX_TAXONOMIES' ) ) {
    define( 'TFSC_COMBO_SEO_MAX_TAXONOMIES', 3 );
}


/* ============================================================
 * COMBO STATUS + ITEMS
 * ============================================================ */

function tfsc_combo_seo_is_active() {
    return (
        ! is_admin() &&
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    );
}

function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items = [];

    if ( $resolved ) {
        return $items;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return [];
    }

    $combo = tfsc_get_combo_archive();

    if ( function_exists( 'tfsc_urlcore_normalize_combo' ) ) {
        $combo = tfsc_urlcore_normalize_combo( $combo );
    }

    foreach ( (array) $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $name = trim(
            wp_strip_all_tags(
                $item['term']->name
            )
        );

        if ( '' === $name ) {
            continue;
        }

        $items[] = [
            'taxonomy' => (string) $item['taxonomy'],
            'term_id'  => (int) $item['term']->term_id,
            'slug'     => (string) $item['term']->slug,
            'name'     => $name,
        ];
    }

    return $items;
}


/* ============================================================
 * INDEXERINGSLOGICA
 * ============================================================ */

function tfsc_combo_count_taxonomies( $combo = null ) {

    if ( null === $combo ) {
        $combo = tfsc_combo_seo_is_active()
            ? tfsc_get_combo_archive()
            : [];
    }

    $taxonomies = [];

    foreach ( (array) $combo as $item ) {

        if ( empty( $item['taxonomy'] ) ) {
            continue;
        }

        $taxonomy = sanitize_key( $item['taxonomy'] );

        if ( $taxonomy ) {
            $taxonomies[ $taxonomy ] = true;
        }
    }

    return count( $taxonomies );
}

function tfsc_combo_has_function_name( $combo = null ) {

    if ( null === $combo ) {
        $combo = tfsc_combo_seo_is_active()
            ? tfsc_get_combo_archive()
            : [];
    }

    foreach ( (array) $combo as $item ) {

        if (
            ! empty( $item['taxonomy'] ) &&
            TFSC_COMBO_FUNCTION_TAXONOMY === $item['taxonomy']
        ) {
            return true;
        }
    }

    return false;
}

function tfsc_combo_get_current_result_count() {

    global $wp_query;

    return (
        tfsc_combo_seo_is_active() &&
        $wp_query instanceof WP_Query
    )
        ? max( 0, (int) $wp_query->found_posts )
        : 0;
}

function tfsc_combo_get_index_status( $combo = null ) {

    $frontend = null === $combo;

    if ( $frontend ) {

        if ( ! tfsc_combo_seo_is_active() ) {
            return [
                'index'      => false,
                'reason'     => 'not_combo',
                'results'    => 0,
                'taxonomies' => 0,
            ];
        }

        $combo = tfsc_get_combo_archive();
    }

    if ( ! is_array( $combo ) || ! $combo ) {
        return [
            'index'      => false,
            'reason'     => 'invalid_combo',
            'results'    => 0,
            'taxonomies' => 0,
        ];
    }

    $count = tfsc_combo_count_taxonomies( $combo );

    if ( $count > TFSC_COMBO_SEO_MAX_TAXONOMIES ) {
        return [
            'index'      => false,
            'reason'     => 'too_many_taxonomies',
            'results'    => null,
            'taxonomies' => $count,
        ];
    }

    if ( ! tfsc_combo_has_function_name( $combo ) ) {
        return [
            'index'      => false,
            'reason'     => 'no_function_name',
            'results'    => null,
            'taxonomies' => $count,
        ];
    }

    if ( $frontend ) {

        $results = tfsc_combo_get_current_result_count();
        $valid   = $results > 0;

        return [
            'index'      => $valid,
            'reason'     => $valid
                ? 'valid_function_combo'
                : 'no_results',
            'results'    => $results,
            'taxonomies' => $count,
        ];
    }

    return [
        'index'      => true,
        'reason'     => 'valid_sitemap_function_combo',
        'results'    => null,
        'taxonomies' => $count,
    ];
}

function tfsc_combo_should_index( $combo = null ) {
    return ! empty(
        tfsc_combo_get_index_status( $combo )['index']
    );
}


/* ============================================================
 * COMBO TITLE + DESCRIPTION
 * ============================================================ */

function tfsc_combo_seo_build_title() {

    $functions = [];
    $others = [];

    foreach ( tfsc_combo_seo_get_items() as $item ) {

        if ( TFSC_COMBO_FUNCTION_TAXONOMY === $item['taxonomy'] ) {
            $functions[ $item['name'] ] = $item['name'];
        } else {
            $others[ $item['name'] ] = $item['name'];
        }
    }

    $functions = array_values( $functions );
    $others = array_values( $others );

    if ( $functions ) {

        $title = implode( ' ', $functions ) . ' vacatures';

        if ( $others ) {
            $title .= ' ' . implode( ' ', $others );
        }

        return trim( $title );
    }

    return $others
        ? 'Field Service vacatures ' . implode( ' ', $others )
        : '';
}

function tfsc_combo_seo_build_description() {

    $title = tfsc_combo_seo_build_title();

    return $title
        ? sprintf(
            '%s bij %s.',
            $title,
            TFSC_COMBO_SEO_BRAND
        )
        : '';
}


/* ============================================================
 * COMBO SEO OBJECT
 * ============================================================ */

function tfsc_combo_seo_build_canonical() {

    if ( ! tfsc_combo_seo_is_active() ) {
        return '';
    }

    return tfsc_build_combo_url(
        tfsc_get_combo_archive(),
        max( 1, (int) get_query_var( 'paged' ) )
    );
}

function tfsc_get_combo_seo() {

    static $resolved = false;
    static $seo = false;

    if ( $resolved ) {
        return $seo;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return false;
    }

    $title = tfsc_combo_seo_build_title();

    if ( ! $title ) {
        return false;
    }

    $status = tfsc_combo_get_index_status();

    return $seo = [
        'title'        => $title,
        'description'  => tfsc_combo_seo_build_description(),
        'canonical'    => tfsc_combo_seo_build_canonical(),
        'index'        => ! empty( $status['index'] ),
        'index_reason' => $status['reason'],
        'results'      => $status['results'],
        'taxonomies'   => $status['taxonomies'],
    ];
}


/* ============================================================
 * NATIVE VACATURE TAXONOMY CANONICAL
 * ============================================================ */

function tfsc_native_canonical_is_target() {

    if (
        is_admin() ||
        ! is_tax() ||
        tfsc_is_combo_archive()
    ) {
        return false;
    }

    $term = get_queried_object();

    return (
        $term instanceof WP_Term &&
        tfsc_urlcore_taxonomy_allowed(
            $term->taxonomy
        )
    );
}

function tfsc_native_canonical_build_url() {

    if ( ! tfsc_native_canonical_is_target() ) {
        return '';
    }

    return tfsc_build_combo_url_for_term(
        get_queried_object(),
        null,
        max( 1, (int) get_query_var( 'paged' ) )
    );
}


/* ============================================================
 * SEARCH & FILTER SEO
 * ============================================================ */

function tfsc_vacancy_filter_seo_is_active() {

    if (
        is_admin() ||
        tfsc_is_combo_archive() ||
        ! is_post_type_archive( TFSC_VACANCY_POST_TYPE ) ||
        empty( $_GET )
    ) {
        return false;
    }

    foreach ( array_keys( $_GET ) as $key ) {

        $key = (string) $key;

        if (
            isset( $key[0] ) &&
            '_' === $key[0]
        ) {
            return true;
        }
    }

    return false;
}

function tfsc_vacancy_filter_clean_canonical() {

    $url = get_post_type_archive_link(
        TFSC_VACANCY_POST_TYPE
    );

    return $url
        ? trailingslashit( $url )
        : '';
}


/* ============================================================
 * RANK MATH - COMBO
 * ============================================================ */

function tfsc_combo_rankmath_title( $title ) {
    $seo = tfsc_get_combo_seo();

    return ! empty( $seo['title'] )
        ? $seo['title']
        : $title;
}

function tfsc_combo_rankmath_description( $description ) {
    $seo = tfsc_get_combo_seo();

    return ! empty( $seo['description'] )
        ? $seo['description']
        : $description;
}

function tfsc_combo_rankmath_canonical( $canonical ) {
    $seo = tfsc_get_combo_seo();

    return ! empty( $seo['canonical'] )
        ? $seo['canonical']
        : $canonical;
}

function tfsc_combo_rankmath_robots( $robots ) {

    $seo = tfsc_get_combo_seo();

    if ( ! is_array( $seo ) ) {
        return $robots;
    }

    if ( ! is_array( $robots ) ) {
        $robots = [];
    }

    $robots['index'] = ! empty( $seo['index'] )
        ? 'index'
        : 'noindex';

    $robots['follow'] = 'follow';

    return $robots;
}


/* ============================================================
 * RANK MATH - NATIVE
 * ============================================================ */

function tfsc_native_rankmath_canonical( $canonical ) {

    $url = tfsc_native_canonical_build_url();

    return $url ?: $canonical;
}


/* ============================================================
 * RANK MATH - SEARCH & FILTER
 * ============================================================ */

function tfsc_vacancy_filter_rankmath_canonical( $canonical ) {

    $clean = tfsc_vacancy_filter_clean_canonical();

    return $clean ?: $canonical;
}

function tfsc_vacancy_filter_rankmath_robots( $robots ) {

    if ( ! is_array( $robots ) ) {
        $robots = [];
    }

    $robots['index'] = 'noindex';
    $robots['follow'] = 'follow';

    return $robots;
}


/**
 * Rank Math krijgt hierboven de juiste canonical-waarde zodat
 * OG/schema hun volledige URL blijven behouden.
 *
 * Op noindex filterpagina's kan Rank Math de HTML canonical-tag
 * zelf weglaten. Daarom outputten we hier dezelfde canonical.
 */

function tfsc_vacancy_filter_output_canonical() {

    if ( ! tfsc_vacancy_filter_seo_is_active() ) {
        return;
    }

    $canonical = tfsc_vacancy_filter_clean_canonical();

    if ( ! $canonical ) {
        return;
    }

    printf(
        "<link rel=\"canonical\" href=\"%s\" />\n",
        esc_url( $canonical )
    );
}


