/**
 * TFSC - Combo Archive URLs
 *
 * Centrale data- en URL-supplier voor vacature combo archives.
 *
 * MIGRATIEVEILIG:
 * - kan naast de huidige Vac Combo Archives Base Code draaien;
 * - declareert GEEN bestaande Base Code functies opnieuw;
 * - verandert zelf GEEN rewrites;
 * - verandert zelf GEEN queries;
 * - verandert zelf GEEN canonicals;
 *
 * Uiteindelijk worden Base Code, SEO, Sitemap en interne links
 * allemaal consumers van deze centrale supplier.
 */


/**
 * ============================================================
 * CENTRALE CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_BASE' ) ) {
    define(
        'TFSC_COMBO_BASE',
        'vacatures'
    );
}

if ( ! defined( 'TFSC_VACANCY_POST_TYPE' ) ) {
    define(
        'TFSC_VACANCY_POST_TYPE',
        'vacature'
    );
}

if ( ! defined( 'TFSC_STATUS_TAXONOMY' ) ) {
    define(
        'TFSC_STATUS_TAXONOMY',
        'vac_status'
    );
}

if ( ! defined( 'TFSC_OPEN_STATUS_SLUG' ) ) {
    define(
        'TFSC_OPEN_STATUS_SLUG',
        'open'
    );
}

if ( ! defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) ) {
    define(
        'TFSC_COMBO_FUNCTION_TAXONOMY',
        'functienaam'
    );
}

if ( ! defined( 'TFSC_COMBO_DEFAULT_FUNCTION_SLUG' ) ) {
    define(
        'TFSC_COMBO_DEFAULT_FUNCTION_SLUG',
        'field-service-engineer'
    );
}


/**
 * ============================================================
 * CENTRALE TAXONOMY VALIDATIE
 * ============================================================
 *
 * LET OP:
 * bewust een nieuwe interne functienaam.
 *
 * Daardoor botst deze tijdens de migratie niet met:
 *
 * tfsc_combo_taxonomy_allowed()
 *
 * uit de huidige Base Code.
 */

function tfsc_urlcore_taxonomy_allowed(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );

    if (
        '' === $taxonomy
        ||
        TFSC_STATUS_TAXONOMY === $taxonomy
        ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return false;
    }


    $object =
        get_taxonomy(
            $taxonomy
        );


    if ( ! $object ) {
        return false;
    }


    return (
        ! empty(
            $object->publicly_queryable
        )
        &&
        in_array(
            TFSC_VACANCY_POST_TYPE,
            (array) $object->object_type,
            true
        )
    );
}


/**
 * ============================================================
 * ALLE TOEGESTANE COMBO TAXONOMIES
 * ============================================================
 */

function tfsc_urlcore_get_allowed_taxonomies() {

    static $allowed = null;


    if ( null !== $allowed ) {
        return $allowed;
    }


    $allowed = [];


    $taxonomies =
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        );


    foreach (
        $taxonomies
        as $taxonomy => $object
    ) {

        if (
            tfsc_urlcore_taxonomy_allowed(
                $taxonomy
            )
        ) {
            $allowed[] =
                $taxonomy;
        }
    }


    return $allowed;
}


/**
 * ============================================================
 * INKOMEND TERM-PAD OPLOSSEN
 * ============================================================
 *
 * Deze functie wordt later door de Base Code gebruikt.
 *
 * Voorbeeld:
 *
 * locatie
 * nederland
 * zuid-holland
 * leiden
 *
 * →
 *
 * [
 *     'path' => [ Nederland, Zuid-Holland, Leiden ],
 *     'term' => Leiden
 * ]
 */

function tfsc_urlcore_resolve_term_path(
    $taxonomy,
    $segments
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );


    if (
        ! tfsc_urlcore_taxonomy_allowed(
            $taxonomy
        )
    ) {
        return false;
    }


    $tax_object =
        get_taxonomy(
            $taxonomy
        );


    if (
        ! $tax_object
        ||
        ! is_array( $segments )
        ||
        ! $segments
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if ( ! $segments ) {
        return false;
    }


    if (
        ! $tax_object->hierarchical
        &&
        1 !== count( $segments )
    ) {
        return false;
    }


    $terms     = [];
    $parent_id = 0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term instanceof WP_Term
            ||
            is_wp_error( $term )
        ) {
            return false;
        }


        if (
            $index > 0
            &&
            (int) $term->parent
                !==
                $parent_id
        ) {
            return false;
        }


        $terms[] =
            $term;


        $parent_id =
            (int) $term->term_id;
    }


    return [
        'path' =>
            $terms,

        'term' =>
            end( $terms ),
    ];
}


/**
 * ============================================================
 * UITGAAND VOLLEDIG TERM-PAD
 * ============================================================
 *
 * Leiden:
 *
 * Nederland
 * → Zuid-Holland
 * → Leiden
 */

function tfsc_urlcore_get_term_path(
    WP_Term $term
) {

    if (
        ! tfsc_urlcore_taxonomy_allowed(
            $term->taxonomy
        )
    ) {
        return [];
    }


    $taxonomy =
        get_taxonomy(
            $term->taxonomy
        );


    if ( ! $taxonomy ) {
        return [];
    }


    if (
        ! $taxonomy->hierarchical
    ) {
        return [
            $term,
        ];
    }


    $path = [];


    $ancestor_ids =
        array_reverse(
            get_ancestors(
                $term->term_id,
                $term->taxonomy,
                'taxonomy'
            )
        );


    foreach (
        $ancestor_ids
        as $ancestor_id
    ) {

        $ancestor =
            get_term(
                $ancestor_id,
                $term->taxonomy
            );


        if (
            ! $ancestor instanceof WP_Term
            ||
            is_wp_error( $ancestor )
        ) {
            return [];
        }


        $path[] =
            $ancestor;
    }


    $path[] =
        $term;


    return $path;
}


/**
 * ============================================================
 * TERM → COMBO ITEM
 * ============================================================
 *
 * Maakt dezelfde datastructuur als de huidige combo-parser:
 *
 * [
 *     'taxonomy' => 'locatie',
 *     'term'     => WP_Term Leiden,
 *     'path'     => [
 *         WP_Term Nederland,
 *         WP_Term Zuid-Holland,
 *         WP_Term Leiden
 *     ]
 * ]
 */

function tfsc_urlcore_create_item(
    WP_Term $term
) {

    $path =
        tfsc_urlcore_get_term_path(
            $term
        );


    if ( ! $path ) {
        return false;
    }


    return [
        'taxonomy' =>
            $term->taxonomy,

        'term' =>
            $term,

        'path' =>
            $path,
    ];
}


/**
 * ============================================================
 * STANDAARD FUNCTIENAAM
 * ============================================================
 */

function tfsc_urlcore_get_default_function_term() {

    $term =
        get_term_by(
            'slug',
            TFSC_COMBO_DEFAULT_FUNCTION_SLUG,
            TFSC_COMBO_FUNCTION_TAXONOMY
        );


    if (
        ! $term instanceof WP_Term
        ||
        is_wp_error( $term )
    ) {
        return false;
    }


    return $term;
}


/**
 * ============================================================
 * COMBO NORMALISEREN
 * ============================================================
 *
 * functienaam komt altijd eerst.
 *
 * Andere taxonomies behouden hun bestaande onderlinge
 * volgorde.
 */

function tfsc_urlcore_normalize_combo(
    array $combo
) {

    $function_items = [];
    $other_items    = [];


    foreach (
        $combo
        as $item
    ) {

        if (
            ! is_array( $item )
            ||
            empty( $item['taxonomy'] )
        ) {
            return [];
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            '' === $taxonomy
            ||
            ! tfsc_urlcore_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return [];
        }


        $item['taxonomy'] =
            $taxonomy;


        if (
            TFSC_COMBO_FUNCTION_TAXONOMY
            ===
            $taxonomy
        ) {

            $function_items[] =
                $item;

        } else {

            $other_items[] =
                $item;
        }
    }


    return array_merge(
        $function_items,
        $other_items
    );
}


/**
 * ============================================================
 * CENTRALE COMBO URL-BUILDER
 * ============================================================
 *
 * Dit is de publieke functie die andere snippets straks
 * gebruiken.
 *
 * Alle daadwerkelijke combo-URL-opbouw hoort uiteindelijk
 * via deze functie te lopen.
 */

function tfsc_build_combo_url(
    array $combo,
    $paged = 1
) {

    $combo =
        tfsc_urlcore_normalize_combo(
            $combo
        );


    if ( ! $combo ) {
        return '';
    }


    $segments = [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty( $item['taxonomy'] )
            ||
            empty( $item['path'] )
            ||
            ! is_array( $item['path'] )
        ) {
            return '';
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            ! tfsc_urlcore_taxonomy_allowed(
                $taxonomy
            )
        ) {
            return '';
        }


        $segments[] =
            $taxonomy;


        foreach (
            $item['path']
            as $path_term
        ) {

            if (
                ! $path_term instanceof WP_Term
                ||
                $path_term->taxonomy
                    !==
                    $taxonomy
            ) {
                return '';
            }


            $slug =
                trim(
                    (string)
                    $path_term->slug
                );


            if ( '' === $slug ) {
                return '';
            }


            $segments[] =
                $slug;
        }
    }


    if ( ! $segments ) {
        return '';
    }


    $path =
        trim(
            TFSC_COMBO_BASE,
            '/'
        )
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    $url =
        trailingslashit(
            home_url(
                '/' . $path
            )
        );


    $paged =
        max(
            1,
            (int) $paged
        );


    if ( $paged > 1 ) {

        $url =
            trailingslashit(
                $url
                .
                'page/'
                .
                $paged
            );
    }


    return $url;
}


/**
 * ============================================================
 * TERM → COMBO URL
 * ============================================================
 *
 * FUNCTIENAAM
 *
 * Commissioning Engineer:
 *
 * /vacatures/functienaam/commissioning-engineer/
 *
 *
 * ANDERE TAXONOMY ZONDER EXPLICIETE FUNCTIENAAM
 *
 * Inbedrijfstellen:
 *
 * /vacatures/
 * functienaam/field-service-engineer/
 * functie-inhoud/inbedrijfstellen/
 *
 *
 * ANDERE TAXONOMY MET EXPLICIETE FUNCTIENAAM
 *
 * Commissioning Engineer + Inbedrijfstellen:
 *
 * /vacatures/
 * functienaam/commissioning-engineer/
 * functie-inhoud/inbedrijfstellen/
 */

function tfsc_build_combo_url_for_term(
    WP_Term $term,
    $function_term = null,
    $paged = 1
) {

    if (
        ! tfsc_urlcore_taxonomy_allowed(
            $term->taxonomy
        )
    ) {
        return '';
    }


    /**
     * Term is zelf functienaam.
     */
    if (
        TFSC_COMBO_FUNCTION_TAXONOMY
        ===
        $term->taxonomy
    ) {

        $item =
            tfsc_urlcore_create_item(
                $term
            );


        if ( ! $item ) {
            return '';
        }


        return tfsc_build_combo_url(
            [
                $item,
            ],
            $paged
        );
    }


    /**
     * Geen functienaam meegegeven:
     * standaard Field Service Engineer.
     */
    if (
        ! $function_term instanceof WP_Term
    ) {

        $function_term =
            tfsc_urlcore_get_default_function_term();
    }


    if (
        ! $function_term instanceof WP_Term
        ||
        TFSC_COMBO_FUNCTION_TAXONOMY
            !==
            $function_term->taxonomy
    ) {
        return '';
    }


    $function_item =
        tfsc_urlcore_create_item(
            $function_term
        );


    $term_item =
        tfsc_urlcore_create_item(
            $term
        );


    if (
        ! $function_item
        ||
        ! $term_item
    ) {
        return '';
    }


    return tfsc_build_combo_url(
        [
            $function_item,
            $term_item,
        ],
        $paged
    );
}

/**
 * TFSC - Combo Vacancy Sitemap
 * Version 6 - Compact
 *
 * - Alleen gepubliceerde + OPEN vacatures
 * - Alleen werkelijk bestaande combinaties
 * - Exact 2 taxonomies per combo
 * - tfsc_combo_should_index() bepaalt indexeerbaarheid
 * - URL's uitsluitend via tfsc_build_combo_url()
 * - lastmod per combo
 * - lastmod in sitemap index
 * - transient cache + automatische invalidatie
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS' ) ) {
    define( 'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS', 2 );
}

if ( ! defined( 'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS' ) ) {
    define( 'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS', 2 );
}

if ( ! defined( 'TFSC_COMBO_SITEMAP_CACHE_KEY' ) ) {
    define( 'TFSC_COMBO_SITEMAP_CACHE_KEY', 'tfsc_combo_sitemap_links_v6' );
}

if ( ! defined( 'TFSC_COMBO_SITEMAP_CACHE_TTL' ) ) {
    define( 'TFSC_COMBO_SITEMAP_CACHE_TTL', DAY_IN_SECONDS );
}


/**
 * ============================================================
 * TAXONOMY VOLGORDE
 * ============================================================
 *
 * Alleen voor generatie.
 * De URL Core bepaalt uiteindelijk zelf de URL-volgorde.
 */

function tfsc_combo_sitemap_order_taxonomies( array $taxonomies ) {

    $function = TFSC_COMBO_FUNCTION_TAXONOMY;

    usort(
        $taxonomies,
        static function( $a, $b ) use ( $function ) {

            if ( $a === $function ) {
                return -1;
            }

            if ( $b === $function ) {
                return 1;
            }

            return 0;
        }
    );

    return $taxonomies;
}


/**
 * ============================================================
 * LASTMOD
 * ============================================================
 */

function tfsc_combo_sitemap_post_lastmod( $post_id ) {

    $gmt = get_post_field( 'post_modified_gmt', $post_id );

    if (
        ! $gmt ||
        '0000-00-00 00:00:00' === $gmt
    ) {
        return '';
    }

    $time = strtotime( $gmt . ' GMT' );

    return $time
        ? gmdate( 'c', $time )
        : '';
}


function tfsc_combo_sitemap_newest_lastmod( $a, $b ) {

    if ( ! $a ) {
        return $b;
    }

    if ( ! $b ) {
        return $a;
    }

    $a_time = strtotime( $a );
    $b_time = strtotime( $b );

    return (
        $b_time &&
        (
            ! $a_time ||
            $b_time > $a_time
        )
    )
        ? $b
        : $a;
}


/**
 * ============================================================
 * TAXONOMY DIMENSIES VAN VACATURE
 * ============================================================
 */

function tfsc_combo_sitemap_dimensions(
    $post_id,
    array $taxonomies
) {

    $dimensions = [];

    foreach ( $taxonomies as $taxonomy ) {

        $terms = get_the_terms(
            $post_id,
            $taxonomy
        );

        if ( ! is_array( $terms ) ) {
            continue;
        }

        $object = get_taxonomy( $taxonomy );

        $include_ancestors =
            $object &&
            $object->hierarchical &&
            'AND' !== tfsc_get_combo_taxonomy_match_method( $taxonomy );

        $collected = [];

        foreach ( $terms as $term ) {

            if ( ! $term instanceof WP_Term ) {
                continue;
            }

            $collected[ $term->term_id ] = $term;

            if ( ! $include_ancestors ) {
                continue;
            }

            foreach (
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                )
                as $ancestor_id
            ) {
                $ancestor = get_term(
                    $ancestor_id,
                    $taxonomy
                );

                if (
                    $ancestor instanceof WP_Term &&
                    ! is_wp_error( $ancestor )
                ) {
                    $collected[ $ancestor->term_id ] = $ancestor;
                }
            }
        }

        if ( $collected ) {
            $dimensions[ $taxonomy ] = array_values( $collected );
        }
    }

    return $dimensions;
}


/**
 * ============================================================
 * TAXONOMY COMBINATIES
 * ============================================================
 */

function tfsc_combo_sitemap_sets(
    array $items,
    $size
) {

    $size = (int) $size;

    if (
        $size < 1 ||
        count( $items ) < $size
    ) {
        return [];
    }

    if ( 1 === $size ) {
        return array_map(
            static fn( $item ) => [ $item ],
            $items
        );
    }

    $result = [];
    $first  = array_shift( $items );

    foreach (
        tfsc_combo_sitemap_sets(
            $items,
            $size - 1
        )
        as $set
    ) {
        array_unshift( $set, $first );
        $result[] = $set;
    }

    return array_merge(
        $result,
        tfsc_combo_sitemap_sets(
            $items,
            $size
        )
    );
}


/**
 * ============================================================
 * TERM PRODUCTEN
 * ============================================================
 */

function tfsc_combo_sitemap_products(
    array $taxonomy_set,
    array $dimensions
) {

    $products = [ [] ];

    foreach (
        tfsc_combo_sitemap_order_taxonomies( $taxonomy_set )
        as $taxonomy
    ) {

        if ( empty( $dimensions[ $taxonomy ] ) ) {
            return [];
        }

        $next = [];

        foreach ( $products as $product ) {

            foreach (
                $dimensions[ $taxonomy ]
                as $term
            ) {

                if ( ! $term instanceof WP_Term ) {
                    continue;
                }

                $item = tfsc_urlcore_create_item( $term );

                if ( ! $item ) {
                    continue;
                }

                $next[] = array_merge(
                    $product,
                    [ $item ]
                );
            }
        }

        if ( ! $next ) {
            return [];
        }

        $products = $next;
    }

    return $products;
}


/**
 * ============================================================
 * SITEMAP LINKS
 * ============================================================
 */

function tfsc_combo_sitemap_generate_links() {

    if (
        ! function_exists( 'tfsc_get_allowed_combo_taxonomies' ) ||
        ! function_exists( 'tfsc_get_combo_taxonomy_match_method' ) ||
        ! function_exists( 'tfsc_combo_should_index' ) ||
        ! function_exists( 'tfsc_urlcore_create_item' ) ||
        ! function_exists( 'tfsc_build_combo_url' )
    ) {
        return [];
    }

    $cached = get_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY
    );

    if ( is_array( $cached ) ) {
        return $cached;
    }

    $taxonomies = tfsc_combo_sitemap_order_taxonomies(
        tfsc_get_allowed_combo_taxonomies()
    );

    if ( ! $taxonomies ) {
        return [];
    }

    $posts = get_posts( [
        'post_type'      => TFSC_VACANCY_POST_TYPE,
        'post_status'    => 'publish',
        'posts_per_page' => -1,
        'no_found_rows'  => true,
        'orderby'        => 'ID',
        'order'          => 'ASC',
        'tax_query'      => [
            [
                'taxonomy'         => TFSC_STATUS_TAXONOMY,
                'field'            => 'slug',
                'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
                'operator'         => 'IN',
                'include_children' => false,
            ],
        ],
    ] );

    if ( ! $posts ) {
        set_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            [],
            TFSC_COMBO_SITEMAP_CACHE_TTL
        );

        return [];
    }

    $links = [];

    foreach ( $posts as $post ) {

        if ( ! $post instanceof WP_Post ) {
            continue;
        }

        $dimensions = tfsc_combo_sitemap_dimensions(
            $post->ID,
            $taxonomies
        );

        if ( ! $dimensions ) {
            continue;
        }

        /*
         * Taxonomy-volgorde gelijk houden aan centrale lijst.
         */
        $ordered = [];

        foreach ( $taxonomies as $taxonomy ) {
            if ( isset( $dimensions[ $taxonomy ] ) ) {
                $ordered[ $taxonomy ] = $dimensions[ $taxonomy ];
            }
        }

        $dimensions = $ordered;
        $names      = array_keys( $dimensions );

        $min = max(
            2,
            (int) TFSC_COMBO_SITEMAP_MIN_DIMENSIONS
        );

        $max = min(
            count( $names ),
            max(
                $min,
                (int) TFSC_COMBO_SITEMAP_MAX_DIMENSIONS
            )
        );

        if ( $max < $min ) {
            continue;
        }

        $lastmod = tfsc_combo_sitemap_post_lastmod(
            $post->ID
        );

        for ( $size = $min; $size <= $max; $size++ ) {

            foreach (
                tfsc_combo_sitemap_sets(
                    $names,
                    $size
                )
                as $taxonomy_set
            ) {

                foreach (
                    tfsc_combo_sitemap_products(
                        $taxonomy_set,
                        $dimensions
                    )
                    as $combo
                ) {

                    if ( ! tfsc_combo_should_index( $combo ) ) {
                        continue;
                    }

                    $url = tfsc_build_combo_url( $combo );

                    if ( ! $url ) {
                        continue;
                    }

                    if ( ! isset( $links[ $url ] ) ) {
                        $links[ $url ] = [
                            'loc'     => $url,
                            'lastmod' => $lastmod,
                        ];

                        continue;
                    }

                    $links[ $url ]['lastmod'] =
                        tfsc_combo_sitemap_newest_lastmod(
                            $links[ $url ]['lastmod'] ?? '',
                            $lastmod
                        );
                }
            }
        }
    }

    ksort( $links, SORT_STRING );

    $links = array_values( $links );

    set_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY,
        $links,
        TFSC_COMBO_SITEMAP_CACHE_TTL
    );

    return $links;
}


/**
 * ============================================================
 * CACHE INVALIDATIE
 * ============================================================
 */

function tfsc_combo_sitemap_flush_cache() {

    foreach (
        [
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            'tfsc_combo_sitemap_links_v1',
            'tfsc_combo_sitemap_links_v2',
            'tfsc_combo_sitemap_links_v3',
            'tfsc_combo_sitemap_links_v4',
            'tfsc_combo_sitemap_links_v5',
        ]
        as $key
    ) {
        delete_transient( $key );
    }

    if (
        class_exists( '\RankMath\Sitemap\Cache' ) &&
        method_exists(
            '\RankMath\Sitemap\Cache',
            'invalidate_storage'
        )
    ) {
        \RankMath\Sitemap\Cache::invalidate_storage(
            'combo-vacatures'
        );
    }
}


/*
 * Vacature opgeslagen.
 */
add_action(
    'save_post_' . TFSC_VACANCY_POST_TYPE,
    function( $post_id ) {

        if ( ! wp_is_post_revision( $post_id ) ) {
            tfsc_combo_sitemap_flush_cache();
        }
    },
    20
);


/*
 * Term gekoppeld/verwijderd van vacature.
 */
add_action(
    'set_object_terms',
    function(
        $object_id,
        $terms,
        $tt_ids,
        $taxonomy
    ) {

        if (
            TFSC_VACANCY_POST_TYPE !== get_post_type( $object_id ) ||
            (
                TFSC_STATUS_TAXONOMY !== $taxonomy &&
                ! tfsc_urlcore_taxonomy_allowed( $taxonomy )
            )
        ) {
            return;
        }

        tfsc_combo_sitemap_flush_cache();
    },
    20,
    4
);


/*
 * Taxonomy term zelf gewijzigd.
 */
function tfsc_combo_sitemap_term_changed(
    $term_id,
    $tt_id = 0,
    $taxonomy = ''
) {

    if (
        ! $taxonomy ||
        (
            TFSC_STATUS_TAXONOMY !== $taxonomy &&
            ! tfsc_urlcore_taxonomy_allowed( $taxonomy )
        )
    ) {
        return;
    }

    tfsc_combo_sitemap_flush_cache();
}

add_action(
    'created_term',
    'tfsc_combo_sitemap_term_changed',
    20,
    3
);

add_action(
    'edited_term',
    'tfsc_combo_sitemap_term_changed',
    20,
    3
);

add_action(
    'delete_term',
    'tfsc_combo_sitemap_term_changed',
    20,
    3
);


/**
 * ============================================================
 * RANK MATH PROVIDER
 * ============================================================
 */

add_filter(
    'rank_math/sitemap/providers',
    function( $providers ) {

        if (
            ! interface_exists(
                '\RankMath\Sitemap\Providers\Provider'
            )
        ) {
            return $providers;
        }

        if (
            ! class_exists(
                'TFSC_Combo_Vacancy_Sitemap_Provider',
                false
            )
        ) {
            class TFSC_Combo_Vacancy_Sitemap_Provider
                implements \RankMath\Sitemap\Providers\Provider {

                public function handles_type( $type ) {
                    return 'combo-vacatures' === $type;
                }

                public function get_index_links( $max_entries ) {

                    $links = tfsc_combo_sitemap_generate_links();

                    if ( ! $links ) {
                        return [];
                    }

                    $max_entries = max(
                        1,
                        (int) $max_entries
                    );

                    $pages = max(
                        1,
                        (int) ceil(
                            count( $links ) / $max_entries
                        )
                    );

                    $index = [];

                    for ( $page = 1; $page <= $pages; $page++ ) {

                        $page_links = array_slice(
                            $links,
                            ( $page - 1 ) * $max_entries,
                            $max_entries
                        );

                        $lastmod = '';

                        foreach ( $page_links as $link ) {
                            $lastmod =
                                tfsc_combo_sitemap_newest_lastmod(
                                    $lastmod,
                                    $link['lastmod'] ?? ''
                                );
                        }

                        $index[] = [
                            'loc' =>
                                \RankMath\Sitemap\Router::get_base_url(
                                    'combo-vacatures-sitemap'
                                    .
                                    ( $pages > 1 ? $page : '' )
                                    .
                                    '.xml'
                                ),

                            'lastmod' =>
                                $lastmod,
                        ];
                    }

                    return $index;
                }

                public function get_sitemap_links(
                    $type,
                    $max_entries,
                    $current_page
                ) {

                    if ( 'combo-vacatures' !== $type ) {
                        return [];
                    }

                    $links = tfsc_combo_sitemap_generate_links();

                    if ( ! $links ) {
                        return [];
                    }

                    $max_entries = max(
                        1,
                        (int) $max_entries
                    );

                    $page = max(
                        1,
                        (int) $current_page
                    );

                    return array_slice(
                        $links,
                        ( $page - 1 ) * $max_entries,
                        $max_entries
                    );
                }
            }
        }

        $providers['combo-vacatures'] =
            new TFSC_Combo_Vacancy_Sitemap_Provider();

        return $providers;
    }
);

/**
 * TFSC - Combo Vacancy Sitemap
 * Version 6 - Compact
 *
 * - Alleen gepubliceerde + OPEN vacatures
 * - Alleen werkelijk bestaande combinaties
 * - Exact 2 taxonomies per combo
 * - tfsc_combo_should_index() bepaalt indexeerbaarheid
 * - URL's uitsluitend via tfsc_build_combo_url()
 * - lastmod per combo
 * - lastmod in sitemap index
 * - transient cache + automatische invalidatie
 */


/**
 * ============================================================
 * CONFIG
 * ============================================================
 */

if ( ! defined( 'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS' ) ) {
    define( 'TFSC_COMBO_SITEMAP_MIN_DIMENSIONS', 2 );
}

if ( ! defined( 'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS' ) ) {
    define( 'TFSC_COMBO_SITEMAP_MAX_DIMENSIONS', 2 );
}

if ( ! defined( 'TFSC_COMBO_SITEMAP_CACHE_KEY' ) ) {
    define( 'TFSC_COMBO_SITEMAP_CACHE_KEY', 'tfsc_combo_sitemap_links_v6' );
}

if ( ! defined( 'TFSC_COMBO_SITEMAP_CACHE_TTL' ) ) {
    define( 'TFSC_COMBO_SITEMAP_CACHE_TTL', DAY_IN_SECONDS );
}


/**
 * ============================================================
 * TAXONOMY VOLGORDE
 * ============================================================
 *
 * Alleen voor generatie.
 * De URL Core bepaalt uiteindelijk zelf de URL-volgorde.
 */

function tfsc_combo_sitemap_order_taxonomies( array $taxonomies ) {

    $function = TFSC_COMBO_FUNCTION_TAXONOMY;

    usort(
        $taxonomies,
        static function( $a, $b ) use ( $function ) {

            if ( $a === $function ) {
                return -1;
            }

            if ( $b === $function ) {
                return 1;
            }

            return 0;
        }
    );

    return $taxonomies;
}


/**
 * ============================================================
 * LASTMOD
 * ============================================================
 */

function tfsc_combo_sitemap_post_lastmod( $post_id ) {

    $gmt = get_post_field( 'post_modified_gmt', $post_id );

    if (
        ! $gmt ||
        '0000-00-00 00:00:00' === $gmt
    ) {
        return '';
    }

    $time = strtotime( $gmt . ' GMT' );

    return $time
        ? gmdate( 'c', $time )
        : '';
}


function tfsc_combo_sitemap_newest_lastmod( $a, $b ) {

    if ( ! $a ) {
        return $b;
    }

    if ( ! $b ) {
        return $a;
    }

    $a_time = strtotime( $a );
    $b_time = strtotime( $b );

    return (
        $b_time &&
        (
            ! $a_time ||
            $b_time > $a_time
        )
    )
        ? $b
        : $a;
}


/**
 * ============================================================
 * TAXONOMY DIMENSIES VAN VACATURE
 * ============================================================
 */

function tfsc_combo_sitemap_dimensions(
    $post_id,
    array $taxonomies
) {

    $dimensions = [];

    foreach ( $taxonomies as $taxonomy ) {

        $terms = get_the_terms(
            $post_id,
            $taxonomy
        );

        if ( ! is_array( $terms ) ) {
            continue;
        }

        $object = get_taxonomy( $taxonomy );

        $include_ancestors =
            $object &&
            $object->hierarchical &&
            'AND' !== tfsc_get_combo_taxonomy_match_method( $taxonomy );

        $collected = [];

        foreach ( $terms as $term ) {

            if ( ! $term instanceof WP_Term ) {
                continue;
            }

            $collected[ $term->term_id ] = $term;

            if ( ! $include_ancestors ) {
                continue;
            }

            foreach (
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                )
                as $ancestor_id
            ) {
                $ancestor = get_term(
                    $ancestor_id,
                    $taxonomy
                );

                if (
                    $ancestor instanceof WP_Term &&
                    ! is_wp_error( $ancestor )
                ) {
                    $collected[ $ancestor->term_id ] = $ancestor;
                }
            }
        }

        if ( $collected ) {
            $dimensions[ $taxonomy ] = array_values( $collected );
        }
    }

    return $dimensions;
}


/**
 * ============================================================
 * TAXONOMY COMBINATIES
 * ============================================================
 */

function tfsc_combo_sitemap_sets(
    array $items,
    $size
) {

    $size = (int) $size;

    if (
        $size < 1 ||
        count( $items ) < $size
    ) {
        return [];
    }

    if ( 1 === $size ) {
        return array_map(
            static fn( $item ) => [ $item ],
            $items
        );
    }

    $result = [];
    $first  = array_shift( $items );

    foreach (
        tfsc_combo_sitemap_sets(
            $items,
            $size - 1
        )
        as $set
    ) {
        array_unshift( $set, $first );
        $result[] = $set;
    }

    return array_merge(
        $result,
        tfsc_combo_sitemap_sets(
            $items,
            $size
        )
    );
}


/**
 * ============================================================
 * TERM PRODUCTEN
 * ============================================================
 */

function tfsc_combo_sitemap_products(
    array $taxonomy_set,
    array $dimensions
) {

    $products = [ [] ];

    foreach (
        tfsc_combo_sitemap_order_taxonomies( $taxonomy_set )
        as $taxonomy
    ) {

        if ( empty( $dimensions[ $taxonomy ] ) ) {
            return [];
        }

        $next = [];

        foreach ( $products as $product ) {

            foreach (
                $dimensions[ $taxonomy ]
                as $term
            ) {

                if ( ! $term instanceof WP_Term ) {
                    continue;
                }

                $item = tfsc_urlcore_create_item( $term );

                if ( ! $item ) {
                    continue;
                }

                $next[] = array_merge(
                    $product,
                    [ $item ]
                );
            }
        }

        if ( ! $next ) {
            return [];
        }

        $products = $next;
    }

    return $products;
}


/**
 * ============================================================
 * SITEMAP LINKS
 * ============================================================
 */

function tfsc_combo_sitemap_generate_links() {

    if (
        ! function_exists( 'tfsc_get_allowed_combo_taxonomies' ) ||
        ! function_exists( 'tfsc_get_combo_taxonomy_match_method' ) ||
        ! function_exists( 'tfsc_combo_should_index' ) ||
        ! function_exists( 'tfsc_urlcore_create_item' ) ||
        ! function_exists( 'tfsc_build_combo_url' )
    ) {
        return [];
    }

    $cached = get_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY
    );

    if ( is_array( $cached ) ) {
        return $cached;
    }

    $taxonomies = tfsc_combo_sitemap_order_taxonomies(
        tfsc_get_allowed_combo_taxonomies()
    );

    if ( ! $taxonomies ) {
        return [];
    }

    $posts = get_posts( [
        'post_type'      => TFSC_VACANCY_POST_TYPE,
        'post_status'    => 'publish',
        'posts_per_page' => -1,
        'no_found_rows'  => true,
        'orderby'        => 'ID',
        'order'          => 'ASC',
        'tax_query'      => [
            [
                'taxonomy'         => TFSC_STATUS_TAXONOMY,
                'field'            => 'slug',
                'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
                'operator'         => 'IN',
                'include_children' => false,
            ],
        ],
    ] );

    if ( ! $posts ) {
        set_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            [],
            TFSC_COMBO_SITEMAP_CACHE_TTL
        );

        return [];
    }

    $links = [];

    foreach ( $posts as $post ) {

        if ( ! $post instanceof WP_Post ) {
            continue;
        }

        $dimensions = tfsc_combo_sitemap_dimensions(
            $post->ID,
            $taxonomies
        );

        if ( ! $dimensions ) {
            continue;
        }

        /*
         * Taxonomy-volgorde gelijk houden aan centrale lijst.
         */
        $ordered = [];

        foreach ( $taxonomies as $taxonomy ) {
            if ( isset( $dimensions[ $taxonomy ] ) ) {
                $ordered[ $taxonomy ] = $dimensions[ $taxonomy ];
            }
        }

        $dimensions = $ordered;
        $names      = array_keys( $dimensions );

        $min = max(
            2,
            (int) TFSC_COMBO_SITEMAP_MIN_DIMENSIONS
        );

        $max = min(
            count( $names ),
            max(
                $min,
                (int) TFSC_COMBO_SITEMAP_MAX_DIMENSIONS
            )
        );

        if ( $max < $min ) {
            continue;
        }

        $lastmod = tfsc_combo_sitemap_post_lastmod(
            $post->ID
        );

        for ( $size = $min; $size <= $max; $size++ ) {

            foreach (
                tfsc_combo_sitemap_sets(
                    $names,
                    $size
                )
                as $taxonomy_set
            ) {

                foreach (
                    tfsc_combo_sitemap_products(
                        $taxonomy_set,
                        $dimensions
                    )
                    as $combo
                ) {

                    if ( ! tfsc_combo_should_index( $combo ) ) {
                        continue;
                    }

                    $url = tfsc_build_combo_url( $combo );

                    if ( ! $url ) {
                        continue;
                    }

                    if ( ! isset( $links[ $url ] ) ) {
                        $links[ $url ] = [
                            'loc'     => $url,
                            'lastmod' => $lastmod,
                        ];

                        continue;
                    }

                    $links[ $url ]['lastmod'] =
                        tfsc_combo_sitemap_newest_lastmod(
                            $links[ $url ]['lastmod'] ?? '',
                            $lastmod
                        );
                }
            }
        }
    }

    ksort( $links, SORT_STRING );

    $links = array_values( $links );

    set_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY,
        $links,
        TFSC_COMBO_SITEMAP_CACHE_TTL
    );

    return $links;
}


/**
 * ============================================================
 * CACHE INVALIDATIE
 * ============================================================
 */

function tfsc_combo_sitemap_flush_cache() {

    foreach (
        [
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            'tfsc_combo_sitemap_links_v1',
            'tfsc_combo_sitemap_links_v2',
            'tfsc_combo_sitemap_links_v3',
            'tfsc_combo_sitemap_links_v4',
            'tfsc_combo_sitemap_links_v5',
        ]
        as $key
    ) {
        delete_transient( $key );
    }

    if (
        class_exists( '\RankMath\Sitemap\Cache' ) &&
        method_exists(
            '\RankMath\Sitemap\Cache',
            'invalidate_storage'
        )
    ) {
        \RankMath\Sitemap\Cache::invalidate_storage(
            'combo-vacatures'
        );
    }
}


