/* ============================================================
 * TAXONOMY VOLGORDE
 * ============================================================ */

function tfsc_combo_sitemap_v7_order_taxonomies( array $taxonomies ) {

    $function = defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' )
        ? TFSC_COMBO_FUNCTION_TAXONOMY
        : 'functienaam';

    usort(
        $taxonomies,
        static function( $a, $b ) use ( $function ) {

            if ( $a === $function ) {
                return -1;
            }

            if ( $b === $function ) {
                return 1;
            }

            return 0;
        }
    );

    return $taxonomies;
}


/* ============================================================
 * LASTMOD
 * ============================================================ */

function tfsc_combo_sitemap_v7_post_lastmod( $post_id ) {

    $gmt = get_post_field( 'post_modified_gmt', $post_id );

    if (
        ! $gmt ||
        '0000-00-00 00:00:00' === $gmt
    ) {
        return '';
    }

    $time = strtotime( $gmt . ' GMT' );

    return $time
        ? gmdate( 'c', $time )
        : '';
}


function tfsc_combo_sitemap_v7_newest_lastmod( $current, $candidate ) {

    if ( ! $candidate ) {
        return $current;
    }

    if ( ! $current ) {
        return $candidate;
    }

    $current_time   = strtotime( $current );
    $candidate_time = strtotime( $candidate );

    return (
        $candidate_time &&
        (
            ! $current_time ||
            $candidate_time > $current_time
        )
    )
        ? $candidate
        : $current;
}


/* ============================================================
