    }

    $posts = get_posts( [
        'post_type'      => TFSC_VACANCY_POST_TYPE,
        'post_status'    => 'publish',
        'posts_per_page' => -1,
        'no_found_rows'  => true,
        'orderby'        => 'ID',
        'order'          => 'ASC',
        'tax_query'      => [
            [
                'taxonomy'         => TFSC_STATUS_TAXONOMY,
                'field'            => 'slug',
                'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
                'operator'         => 'IN',
                'include_children' => false,
            ],
        ],
    ] );

    if ( ! $posts ) {

        set_transient(
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            [],
            TFSC_COMBO_SITEMAP_CACHE_TTL
        );

        return [];
    }

    $links = [];

    foreach ( $posts as $post ) {

        if ( ! $post instanceof WP_Post ) {
            continue;
        }

        $dimensions = tfsc_combo_sitemap_v7_dimensions(
            $post->ID,
            $taxonomies
        );

        if ( ! $dimensions ) {
            continue;
        }

        $ordered = [];

        foreach ( $taxonomies as $taxonomy ) {

            if ( isset( $dimensions[ $taxonomy ] ) ) {
                $ordered[ $taxonomy ] = $dimensions[ $taxonomy ];
            }
        }

        $dimensions = $ordered;
        $names      = array_keys( $dimensions );

        $min = max(
            2,
            (int) TFSC_COMBO_SITEMAP_MIN_DIMENSIONS
        );

        $max = min(
            count( $names ),
            max(
                $min,
                (int) TFSC_COMBO_SITEMAP_MAX_DIMENSIONS
            )
        );

        if ( $max < $min ) {
            continue;
        }

        $lastmod = tfsc_combo_sitemap_v7_post_lastmod(
            $post->ID
        );

        for ( $size = $min; $size <= $max; $size++ ) {

            foreach (
                tfsc_combo_sitemap_v7_sets(
                    $names,
                    $size
                )
                as $taxonomy_set
            ) {

                foreach (
                    tfsc_combo_sitemap_v7_products(
                        $taxonomy_set,
                        $dimensions
                    )
                    as $combo
                ) {

                    if ( ! tfsc_combo_should_index( $combo ) ) {
                        continue;
                    }

                    $url = tfsc_build_combo_url( $combo );

                    if ( ! $url ) {
                        continue;
                    }

                    if ( ! isset( $links[ $url ] ) ) {

                        $links[ $url ] = [
                            'loc'     => $url,
                            'lastmod' => $lastmod,
                        ];

                        continue;
                    }

                    $links[ $url ]['lastmod'] =
                        tfsc_combo_sitemap_v7_newest_lastmod(
                            $links[ $url ]['lastmod'] ?? '',
                            $lastmod
                        );
                }
            }
        }
    }

    ksort( $links, SORT_STRING );

    $links = array_values( $links );

    set_transient(
        TFSC_COMBO_SITEMAP_CACHE_KEY,
        $links,
        TFSC_COMBO_SITEMAP_CACHE_TTL
    );

    return $links;
}


/* ============================================================
 * CACHE
 * ============================================================ */

function tfsc_combo_sitemap_v7_flush_cache() {

    foreach (
        [
            TFSC_COMBO_SITEMAP_CACHE_KEY,
            'tfsc_combo_sitemap_links_v1',
            'tfsc_combo_sitemap_links_v2',
            'tfsc_combo_sitemap_links_v3',
            'tfsc_combo_sitemap_links_v4',
            'tfsc_combo_sitemap_links_v5',
            'tfsc_combo_sitemap_links_v6',
        ]
        as $key
    ) {
        delete_transient( $key );
    }

    if (
        class_exists( '\RankMath\Sitemap\Cache' ) &&
        method_exists(
            '\RankMath\Sitemap\Cache',
            'invalidate_storage'
        )
    ) {
        \RankMath\Sitemap\Cache::invalidate_storage(
            'combo-vacatures'
        );
    }
}


