        $base =
            '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base';

        if ( ! class_exists( $base ) ) {
            return;
        }

        /*
         * Virtuele combo archives.
         */
        if (
            ! class_exists(
                'TFSC_Combined_Vacancy_Archive_Condition',
                false
            )
        ) {
            class TFSC_Combined_Vacancy_Archive_Condition
                extends \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type() {
                    return 'archive';
                }

                public static function get_priority() {
                    return 40;
                }

                public function get_name() {
                    return 'tfsc_combined_vacancy_archive';
                }

                public function get_label() {
                    return 'TFSC Combined Vacancy Archives';
                }

                public function check( $args ) {

                    return (
                        tfsc_is_combo_archive() &&
                        false !== tfsc_get_combo_archive()
                    );
                }
            }
        }

        /*
         * Native vacature taxonomy archives.
         */
        if (
            ! class_exists(
                'TFSC_Vacancy_Taxonomy_Term_Archive_Condition',
                false
            )
        ) {
            class TFSC_Vacancy_Taxonomy_Term_Archive_Condition
                extends \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type() {
                    return 'archive';
                }

                public static function get_priority() {
                    return 41;
                }

                public function get_name() {
                    return 'tfsc_vacancy_taxonomy_term_archives';
                }

                public function get_label() {
                    return 'TFSC Vacancy Taxonomy Term Archives';
                }

                public function check( $args ) {

                    if ( ! is_tax() ) {
                        return false;
                    }

                    $term = get_queried_object();

                    return (
                        $term instanceof WP_Term &&
                        tfsc_combo_taxonomy_allowed(
                            $term->taxonomy
                        )
                    );
                }
            }
        }

        $archive =
            $manager->get_condition( 'archive' );

        if ( ! $archive ) {
            return;
        }

        $archive->register_sub_condition(
            new TFSC_Combined_Vacancy_Archive_Condition()
        );

        $archive->register_sub_condition(
            new TFSC_Vacancy_Taxonomy_Term_Archive_Condition()
        );
    }
);


/* ============================================================
 * HEADING HELPER
 * ============================================================ */

function tfsc_combo_heading_html( $rows ) {

    $rows = array_values(
        array_filter(
            (array) $rows,
            'strlen'
        )
    );

    if ( ! $rows ) {
        return '';
    }

    $html = '<span class="tfsc-heading">';

    foreach ( $rows as $i => $row ) {

        $html .= sprintf(
            '<span class="%s">%s</span>',
            0 === $i
                ? 'tfsc-heading__main'
                : 'tfsc-heading__row',
            esc_html( $row )
        );
    }

    return $html . '</span>';
}


/* ============================================================
 * [combo_heading]
 * ============================================================ */

add_shortcode(
    'combo_heading',
    function() {

        if ( ! tfsc_combo_core_ready() ) {
            return '';
        }

        /*
         * Combo archive.
         */
        if ( tfsc_is_combo_archive() ) {

            $groups =
                tfsc_group_combo_terms( 'name' );

            if ( ! $groups ) {
                return '';
            }

            $rows = [];

            $functions =
                $groups[
                    TFSC_COMBO_FUNCTION_TAXONOMY
                ] ?? [];

            if ( $functions ) {

                if ( 1 === count( $functions ) ) {

                    $rows[] =
                        $functions[0] . ' vacatures';

                } else {

                    $rows[] = 'Vacatures';

                    $rows[] = implode(
                        ', ',
                        $functions
                    );
                }

                unset(
                    $groups[
                        TFSC_COMBO_FUNCTION_TAXONOMY
                    ]
                );

            } else {

                $rows[] = 'Vacatures';
            }

            foreach ( $groups as $names ) {

                if ( $names ) {
                    $rows[] = implode(
                        ', ',
                        $names
                    );
                }
            }

            return tfsc_combo_heading_html(
                $rows
            );
        }

        /*
         * Native taxonomy archive.
         */
        $term = get_queried_object();

        if (
            $term instanceof WP_Term &&
            tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {

            $title = get_term_meta(
                $term->term_id,
                'pods_archive_title',
                true
            );

            $title = is_string( $title )
                ? trim(
                    wp_strip_all_tags(
                        $title
                    )
                )
                : '';

            if ( '' === $title ) {

                $title = trim(
                    $term->name
                );

                if ( '' === $title ) {
                    return '';
                }

                $title .= ' vacatures';
            }

            return tfsc_combo_heading_html(
                [ $title ]
            );
        }

        /*
         * Hoofd vacaturearchive.
         */
        return is_post_type_archive(
            TFSC_VACANCY_POST_TYPE
        )
            ? tfsc_combo_heading_html(
                [ 'Vacatures' ]
            )
            : '';
    }
);


