add_shortcode(
    'combo_term',
    function( $atts ) {

        if ( ! tfsc_combo_core_ready() ) {
            return '';
        }

        $atts = shortcode_atts(
            [
                'taxonomy' => '',
                'separator' => ' • ',
            ],
            $atts,
            'combo_term'
        );

        $taxonomy = sanitize_key(
            $atts['taxonomy']
        );

        if ( ! $taxonomy ) {
            return '';
        }

        /*
         * Combo archive.
         */
        if ( tfsc_is_combo_archive() ) {

            $groups =
                tfsc_group_combo_terms( 'name' );

            return empty(
                $groups[ $taxonomy ]
            )
                ? ''
                : esc_html(
                    implode(
                        (string) $atts['separator'],
                        $groups[ $taxonomy ]
                    )
                );
        }

        /*
         * Native taxonomy archive.
         */
        $term = get_queried_object();

        return (
            $term instanceof WP_Term &&
            $term->taxonomy === $taxonomy &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        )
            ? esc_html( $term->name )
            : '';
    }
);

/**
 * TFSC - Combo Archive SEO + Native Canonicals + Filter SEO
 * Version 4.1 - Compact / Dependency Safe
 *
 * Vereist voor volledige werking:
 * - TFSC - Combo Archive URLs
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * Regelt:
 * - Combo title / description / canonical / robots
 * - Centrale indexeringslogica voor SEO + sitemap
 * - Native taxonomy canonical → combo
 * - Search & Filter URLs → noindex, follow
 * - Search & Filter canonical → schoon /vacatures/
 */


/* ============================================================
 * CONFIG
 * ============================================================ */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {
    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}

if ( ! defined( 'TFSC_COMBO_SEO_MAX_TAXONOMIES' ) ) {
    define(
        'TFSC_COMBO_SEO_MAX_TAXONOMIES',
        3
    );
}


/* ============================================================
 * DEPENDENCY CHECKS
 * ============================================================ */

/**
 * Base + URL Core beschikbaar.
 */
function tfsc_combo_seo_dependencies_ready() {

    return (
        defined( 'TFSC_VACANCY_POST_TYPE' ) &&
        defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) &&
        function_exists( 'tfsc_is_combo_archive' ) &&
        function_exists( 'tfsc_get_combo_archive' ) &&
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        function_exists( 'tfsc_build_combo_url' ) &&
        function_exists( 'tfsc_build_combo_url_for_term' )
    );
}


/**
 * Alleen de dependency die nodig is om tfsc_combo_should_index()
 * vanuit bijvoorbeeld de sitemap te kunnen gebruiken.
 */
function tfsc_combo_seo_index_dependencies_ready() {

    return (
        defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' )
    );
}


/* ============================================================
 * COMBO STATUS + ITEMS
 * ============================================================ */

function tfsc_combo_seo_is_active() {

    return (
        ! is_admin() &&
        tfsc_combo_seo_dependencies_ready() &&
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    );
}


function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];

    if ( $resolved ) {
        return $items;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return [];
    }

    $combo = tfsc_get_combo_archive();

    if (
        function_exists(
            'tfsc_urlcore_normalize_combo'
        )
    ) {
        $combo =
            tfsc_urlcore_normalize_combo(
                $combo
            );
    }

    foreach ( (array) $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $name = trim(
            wp_strip_all_tags(
                $item['term']->name
            )
        );

        if ( '' === $name ) {
            continue;
        }

        $items[] = [
            'taxonomy' =>
                (string) $item['taxonomy'],

            'term_id' =>
                (int) $item['term']->term_id,

            'slug' =>
                (string) $item['term']->slug,

            'name' =>
                $name,
        ];
    }

    return $items;
}


/* ============================================================
 * INDEXERINGSLOGICA
 * ============================================================ */

function tfsc_combo_count_taxonomies(
    $combo = null
) {

    if ( null === $combo ) {

        $combo =
            tfsc_combo_seo_is_active()
                ? tfsc_get_combo_archive()
                : [];
    }

    $taxonomies = [];

    foreach ( (array) $combo as $item ) {

        if ( empty( $item['taxonomy'] ) ) {
            continue;
        }

        $taxonomy = sanitize_key(
            $item['taxonomy']
        );

        if ( $taxonomy ) {
            $taxonomies[ $taxonomy ] = true;
        }
    }

    return count( $taxonomies );
}


function tfsc_combo_has_function_name(
    $combo = null
) {

    if (
        ! defined(
            'TFSC_COMBO_FUNCTION_TAXONOMY'
        )
    ) {
        return false;
    }

    if ( null === $combo ) {

        $combo =
            tfsc_combo_seo_is_active()
                ? tfsc_get_combo_archive()
                : [];
    }

    foreach ( (array) $combo as $item ) {

        if (
            ! empty( $item['taxonomy'] ) &&
            TFSC_COMBO_FUNCTION_TAXONOMY ===
            $item['taxonomy']
        ) {
            return true;
        }
    }

    return false;
}


function tfsc_combo_get_current_result_count() {

    global $wp_query;

    return (
        tfsc_combo_seo_is_active() &&
        $wp_query instanceof WP_Query
    )
        ? max(
            0,
            (int) $wp_query->found_posts
        )
        : 0;
}


function tfsc_combo_get_index_status(
    $combo = null
) {

    $frontend = null === $combo;

    if ( $frontend ) {

        if ( ! tfsc_combo_seo_is_active() ) {

            return [
                'index'      => false,
                'reason'     => 'not_combo',
                'results'    => 0,
                'taxonomies' => 0,
            ];
        }

        $combo = tfsc_get_combo_archive();

    } elseif (
        ! tfsc_combo_seo_index_dependencies_ready()
    ) {

        return [
            'index'      => false,
            'reason'     => 'dependencies_missing',
            'results'    => null,
            'taxonomies' => 0,
        ];
    }

    if (
        ! is_array( $combo ) ||
        ! $combo
    ) {
        return [
            'index'      => false,
            'reason'     => 'invalid_combo',
            'results'    => 0,
            'taxonomies' => 0,
        ];
    }

    $count =
        tfsc_combo_count_taxonomies(
            $combo
        );

    if (
        $count >
        TFSC_COMBO_SEO_MAX_TAXONOMIES
    ) {
        return [
            'index'      => false,
            'reason'     => 'too_many_taxonomies',
            'results'    => null,
            'taxonomies' => $count,
        ];
    }

    if (
        ! tfsc_combo_has_function_name(
            $combo
        )
    ) {
        return [
            'index'      => false,
            'reason'     => 'no_function_name',
            'results'    => null,
            'taxonomies' => $count,
        ];
    }

    if ( $frontend ) {

        $results =
            tfsc_combo_get_current_result_count();

        $valid =
            $results > 0;

        return [
            'index' =>
                $valid,

            'reason' =>
                $valid
                    ? 'valid_function_combo'
                    : 'no_results',

            'results' =>
                $results,

            'taxonomies' =>
                $count,
        ];
    }

    return [
        'index'      => true,
        'reason'     => 'valid_sitemap_function_combo',
        'results'    => null,
        'taxonomies' => $count,
    ];
}


function tfsc_combo_should_index(
    $combo = null
) {

    return ! empty(
        tfsc_combo_get_index_status(
            $combo
        )['index']
    );
}


/* ============================================================
 * COMBO TITLE + DESCRIPTION
 * ============================================================ */

function tfsc_combo_seo_build_title() {

    if (
        ! defined(
            'TFSC_COMBO_FUNCTION_TAXONOMY'
        )
    ) {
        return '';
    }

    $functions = [];
    $others    = [];

    foreach (
        tfsc_combo_seo_get_items()
        as $item
    ) {

        if (
            TFSC_COMBO_FUNCTION_TAXONOMY ===
            $item['taxonomy']
        ) {
            $functions[
                $item['name']
            ] = $item['name'];

        } else {

            $others[
                $item['name']
            ] = $item['name'];
        }
    }

    $functions =
        array_values( $functions );

    $others =
        array_values( $others );

    if ( $functions ) {

        $title =
            implode(
                ' ',
                $functions
            )
            .
            ' vacatures';

        if ( $others ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $others
                );
        }

        return trim( $title );
    }

    return $others
        ? 'Field Service vacatures '
            . implode( ' ', $others )
        : '';
}


function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();

    return $title
        ? sprintf(
            '%s bij %s.',
            $title,
            TFSC_COMBO_SEO_BRAND
        )
        : '';
}


/* ============================================================
 * COMBO SEO OBJECT
 * ============================================================ */

function tfsc_combo_seo_build_canonical() {

    if (
        ! tfsc_combo_seo_is_active() ||
        ! function_exists(
            'tfsc_build_combo_url'
        )
    ) {
        return '';
    }

    return tfsc_build_combo_url(
        tfsc_get_combo_archive(),
        max(
            1,
            (int) get_query_var( 'paged' )
        )
    );
}


function tfsc_get_combo_seo() {

    static $resolved = false;
    static $seo      = false;

    if ( $resolved ) {
        return $seo;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return false;
    }

    $title =
        tfsc_combo_seo_build_title();

    if ( ! $title ) {
        return false;
    }

    $status =
        tfsc_combo_get_index_status();

    return $seo = [
        'title' =>
            $title,

        'description' =>
            tfsc_combo_seo_build_description(),

        'canonical' =>
            tfsc_combo_seo_build_canonical(),

        'index' =>
            ! empty( $status['index'] ),

        'index_reason' =>
            $status['reason'],

        'results' =>
            $status['results'],

        'taxonomies' =>
            $status['taxonomies'],
    ];
}


/* ============================================================
 * NATIVE VACATURE TAXONOMY CANONICAL
 * ============================================================ */

function tfsc_native_canonical_is_target() {

    if (
        is_admin() ||
        ! tfsc_combo_seo_dependencies_ready() ||
        ! is_tax()
    ) {
        return false;
    }

    /*
     * Alleen aanroepen nadat we weten dat Base bestaat.
     */
    if ( tfsc_is_combo_archive() ) {
        return false;
    }

    $term = get_queried_object();

    return (
        $term instanceof WP_Term &&
        tfsc_urlcore_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


function tfsc_native_canonical_build_url() {

    if (
        ! tfsc_native_canonical_is_target() ||
        ! function_exists(
            'tfsc_build_combo_url_for_term'
        )
    ) {
        return '';
    }

    return tfsc_build_combo_url_for_term(
        get_queried_object(),
        null,
        max(
            1,
            (int) get_query_var( 'paged' )
        )
    );
}


/* ============================================================
 * SEARCH & FILTER SEO
 * ============================================================ */

function tfsc_vacancy_filter_seo_is_active() {

    if (
        is_admin() ||
        ! defined(
            'TFSC_VACANCY_POST_TYPE'
        )
    ) {
        return false;
    }

    /*
     * tfsc_is_combo_archive() bestaat mogelijk tijdelijk niet.
     */
    if (
        function_exists(
            'tfsc_is_combo_archive'
        ) &&
        tfsc_is_combo_archive()
    ) {
        return false;
    }

    if (
        ! is_post_type_archive(
            TFSC_VACANCY_POST_TYPE
        ) ||
        empty( $_GET )
    ) {
        return false;
    }

    foreach (
        array_keys( $_GET )
        as $key
    ) {

        $key =
            (string) $key;

        if (
            isset( $key[0] ) &&
            '_' === $key[0]
        ) {
            return true;
        }
    }

    return false;
}


function tfsc_vacancy_filter_clean_canonical() {

    if (
        ! defined(
            'TFSC_VACANCY_POST_TYPE'
        )
    ) {
        return '';
    }

    $url =
        get_post_type_archive_link(
            TFSC_VACANCY_POST_TYPE
        );

    return $url
        ? trailingslashit( $url )
        : '';
}


/* ============================================================
 * RANK MATH - COMBO
 * ============================================================ */

function tfsc_combo_rankmath_title(
    $title
) {

    $seo =
        tfsc_get_combo_seo();

    return ! empty(
        $seo['title']
    )
        ? $seo['title']
        : $title;
}


function tfsc_combo_rankmath_description(
    $description
) {

    $seo =
        tfsc_get_combo_seo();

    return ! empty(
        $seo['description']
    )
        ? $seo['description']
        : $description;
}


function tfsc_combo_rankmath_canonical(
    $canonical
) {

    $seo =
        tfsc_get_combo_seo();

    return ! empty(
        $seo['canonical']
    )
        ? $seo['canonical']
        : $canonical;
}


function tfsc_combo_rankmath_robots(
    $robots
) {

    $seo =
        tfsc_get_combo_seo();

    if ( ! is_array( $seo ) ) {
        return $robots;
    }

    if ( ! is_array( $robots ) ) {
        $robots = [];
    }

    $robots['index'] =
        ! empty( $seo['index'] )
            ? 'index'
            : 'noindex';

    $robots['follow'] =
        'follow';

    return $robots;
}


/* ============================================================
 * RANK MATH - NATIVE
 * ============================================================ */

function tfsc_native_rankmath_canonical(
    $canonical
) {

    $url =
        tfsc_native_canonical_build_url();

    return $url
        ?: $canonical;
}


/* ============================================================
 * RANK MATH - SEARCH & FILTER
 * ============================================================ */

function tfsc_vacancy_filter_rankmath_canonical(
    $canonical
) {

    $clean =
        tfsc_vacancy_filter_clean_canonical();

    return $clean
        ?: $canonical;
}


function tfsc_vacancy_filter_rankmath_robots(
    $robots
) {

    if ( ! is_array( $robots ) ) {
        $robots = [];
    }

    $robots['index']  = 'noindex';
    $robots['follow'] = 'follow';

    return $robots;
}


/**
 * Rank Math krijgt dezelfde canonical intern voor OG/schema.
 * Op noindex filterpagina's outputten we de HTML canonical
 * aanvullend zelf.
 */
function tfsc_vacancy_filter_output_canonical() {

    if (
        ! tfsc_vacancy_filter_seo_is_active()
    ) {
        return;
    }

    $canonical =
        tfsc_vacancy_filter_clean_canonical();

    if ( ! $canonical ) {
        return;
    }

    printf(
        "<link rel=\"canonical\" href=\"%s\" />\n",
        esc_url( $canonical )
    );
}


/* ============================================================
 * FILTERS REGISTREREN
 * ============================================================ */

add_action(
    'wp',
    function() {

        /*
         * Combo archive.
         */
        if (
            tfsc_combo_seo_is_active()
        ) {

            add_filter(
                'rank_math/frontend/title',
                'tfsc_combo_rankmath_title',
                99
            );

            add_filter(
                'rank_math/frontend/description',
                'tfsc_combo_rankmath_description',
                99
            );

            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_combo_rankmath_canonical',
                99
            );

            add_filter(
                'rank_math/frontend/robots',
                'tfsc_combo_rankmath_robots',
                99
            );

            return;
        }

        /*
         * Search & Filter resultaat-URL.
         */
        if (
            tfsc_vacancy_filter_seo_is_active()
        ) {

            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_vacancy_filter_rankmath_canonical',
                99
            );

            add_filter(
                'rank_math/frontend/robots',
                'tfsc_vacancy_filter_rankmath_robots',
                99
            );

            add_action(
                'wp_head',
                'tfsc_vacancy_filter_output_canonical',
                1
            );

            return;
        }

        /*
         * Native vacature taxonomy archive:
         * alleen canonical.
         */
        if (
            tfsc_native_canonical_is_target()
        ) {

            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_native_rankmath_canonical',
                99
            );
        }
    },
    20
);

/**
 * TFSC - Volledig dynamische vacature-archieven
 * Version 5.1 - Compact / Core Safe
 *
 * Vereist voor volledige werking:
 * - TFSC - Combo Archive URLs
 *
 * Regelt:
 * - /vacatures/... combo archives
 * - pagination
 * - verschillende taxonomies = AND
 * - meerdere terms binnen taxonomy = OR
 * - kennisgebied = AND
 * - alleen OPEN vacatures
 * - native vacature-taxonomy archives
 * - Search & Filter Pro v3 sync
 * - Elementor archive conditions
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 */


/* ============================================================
 * CONFIG + CORE CHECK
 * ============================================================ */

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}


/**
 * Controleert of de URL Core volledig beschikbaar is.
 *
 * Consumers mogen laden zonder Core, maar voeren dan
 * geen Core-afhankelijke logica uit.
 */
function tfsc_combo_core_ready() {

    return (
        defined( 'TFSC_COMBO_BASE' ) &&
        defined( 'TFSC_VACANCY_POST_TYPE' ) &&
        defined( 'TFSC_STATUS_TAXONOMY' ) &&
        defined( 'TFSC_OPEN_STATUS_SLUG' ) &&
        defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) &&
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        function_exists( 'tfsc_urlcore_get_allowed_taxonomies' ) &&
        function_exists( 'tfsc_urlcore_resolve_term_path' )
    );
}


/*
 * Publieke compatibiliteitsfuncties.
 * De URL Core bevat de daadwerkelijke logica.
 */
function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    return (
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        tfsc_urlcore_taxonomy_allowed( $taxonomy )
    );
}


function tfsc_get_allowed_combo_taxonomies() {

    return function_exists( 'tfsc_urlcore_get_allowed_taxonomies' )
        ? tfsc_urlcore_get_allowed_taxonomies()
        : [];
}


function tfsc_resolve_term_path( $taxonomy, $segments ) {

    return function_exists( 'tfsc_urlcore_resolve_term_path' )
        ? tfsc_urlcore_resolve_term_path( $taxonomy, $segments )
        : false;
}


/* ============================================================
 * HELPERS
 * ============================================================ */

function tfsc_get_combo_taxonomy_match_method( $taxonomy ) {
    return 'kennisgebied' === $taxonomy ? 'AND' : 'OR';
}


function tfsc_combo_status_clause() {

    if (
        ! defined( 'TFSC_STATUS_TAXONOMY' ) ||
        ! defined( 'TFSC_OPEN_STATUS_SLUG' )
    ) {
        return [];
    }

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_is_combo_archive() {
    return (bool) get_query_var( 'tfsc_combo_archive' );
}


function tfsc_is_vacancy_seo_landing() {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term = get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed( $term->taxonomy )
    );
}


/* ============================================================
 * QUERY VARS + REWRITES
 * ============================================================ */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';
        $vars[] = 'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        if (
            ! defined( 'TFSC_COMBO_BASE' ) ||
            '' === trim( (string) TFSC_COMBO_BASE )
        ) {
            return;
        }

        $base = preg_quote(
            trim( TFSC_COMBO_BASE, '/' ),
            '/'
        );

        /*
         * Pagination MOET vóór de algemene combo-regel staan.
         *
         * /vacatures/.../page/2/
         *
         * page/2 wordt hierdoor niet als taxonomy/term
         * onderdeel van tfsc_combo_path gezien.
         */
        add_rewrite_rule(
            '^' . $base . '/(.+?)/page/([0-9]+)/?$',
            'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]&paged=$matches[2]',
            'top'
        );

        /*
         * Normaal combo archive.
         */
        add_rewrite_rule(
            '^' . $base . '/(.+?)/?$',
            'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]',
            'top'
        );
    },
    99
);


/* ============================================================
 * COMBO PARSER
 * ============================================================ */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;

    if ( $resolved ) {
        return $cache;
    }

    $resolved = true;

    if (
        ! tfsc_combo_core_ready() ||
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }

    $path = trim(
        (string) get_query_var( 'tfsc_combo_path' ),
        '/'
    );

    if ( ! $path ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            explode( '/', $path ),
            'strlen'
        )
    );

    if ( count( $segments ) < 2 ) {
        return false;
    }

    $allowed = tfsc_get_allowed_combo_taxonomies();

    if ( ! $allowed ) {
        return false;
    }

    $items = [];
    $count = count( $segments );
    $i     = 0;

    while ( $i < $count ) {

        $taxonomy = sanitize_key(
            $segments[ $i++ ]
        );

        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }

        $term_segments = [];

        while ( $i < $count ) {

            $possible_taxonomy = sanitize_key(
                $segments[ $i ]
            );

            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }

            $term_segments[] = $segments[ $i++ ];
        }

        if ( ! $term_segments ) {
            return false;
        }

        $resolved_path = tfsc_resolve_term_path(
            $taxonomy,
            $term_segments
        );

        if ( ! $resolved_path ) {
            return false;
        }

        $items[] = [
            'taxonomy' => $taxonomy,
            'term'     => $resolved_path['term'],
            'path'     => $resolved_path['path'],
        ];
    }

    return $cache = ( $items ?: false );
}


/* ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================ */

function tfsc_group_combo_terms( $property = 'term_id' ) {

    $combo = tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    $grouped = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $term = $item['term'];

        switch ( $property ) {

            case 'name':
                $value = trim( $term->name );
                break;

            case 'slug':
                $value = $term->slug;
                break;

            default:
                $value = (int) $term->term_id;
        }

        if ( '' === $value || 0 === $value ) {
            continue;
        }

        $key = is_int( $value )
            ? $value
            : (string) $value;

        $grouped[
            $item['taxonomy']
        ][ $key ] = $value;
    }

    foreach ( $grouped as $taxonomy => $values ) {
        $grouped[ $taxonomy ] = array_values( $values );
    }

    return $grouped;
}


/* ============================================================
 * COMBO TAX QUERY
 * ============================================================ */

function tfsc_build_combo_tax_query() {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }

    $groups = tfsc_group_combo_terms();

    if ( ! $groups ) {
        return false;
    }

    $status = tfsc_combo_status_clause();

    if ( ! $status ) {
        return false;
    }

    $tax_query = [
        'relation' => 'AND',
        $status,
    ];

    foreach ( $groups as $taxonomy => $term_ids ) {

        if ( ! $term_ids ) {
            continue;
        }

        $object = get_taxonomy( $taxonomy );
        $method = tfsc_get_combo_taxonomy_match_method(
            $taxonomy
        );

        $tax_query[] = [
            'taxonomy' => $taxonomy,
            'field'    => 'term_id',
            'terms'    => $term_ids,

            'operator' =>
                'AND' === $method &&
                count( $term_ids ) > 1
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                'AND' !== $method &&
                $object &&
                $object->hierarchical,
        ];
    }

    return $tax_query;
}


