/* ============================================================
 * SEARCH & FILTER PRO V3
 * ============================================================ */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_combo_core_ready() ||
            ! tfsc_is_vacancy_seo_landing()
        ) {
            return;
        }

        $is_combo = tfsc_is_combo_archive();

        $values = $is_combo
            ? tfsc_group_combo_terms( 'slug' )
            : [];

        ?>
        <script>
        (() => {

            const ID =
                <?php echo (int) TFSC_SEARCH_FILTER_QUERY_ID; ?>;

            const IS_COMBO =
                <?php echo $is_combo ? 'true' : 'false'; ?>;

            const VALUES =
                <?php echo wp_json_encode( $values ); ?>;

            let ready = !IS_COMBO;
            let synced = false;
            let attached = false;
            let redirecting = false;

            const list = items => {

                if (!items) return [];

                if (items instanceof Map) {
                    return [...items.values()];
                }

                if (Array.isArray(items)) {
                    return items;
                }

                return typeof items === 'object'
                    ? Object.values(items)
                    : [];
            };

            const same = (a, b) => {

                a = Array.isArray(a)
                    ? a.map(String).sort()
                    : [];

                b = Array.isArray(b)
                    ? b.map(String).sort()
                    : [];

                return (
                    a.length === b.length &&
                    a.every((v, i) => v === b[i])
                );
            };

            const sync = () => {

                if (!IS_COMBO || synced) {
                    return;
                }

                const api =
                    window.searchAndFilter?.frontend?.fields;

                if (
                    !api ||
                    typeof api.getAll !== 'function'
                ) {
                    return;
                }

                let expected = 0;
                let correct = 0;

                list(api.getAll()).forEach(field => {

                    if (
                        !field ||
                        typeof field.getAttributes !== 'function' ||
                        typeof field.getValues !== 'function' ||
                        typeof field.setValues !== 'function'
                    ) {
                        return;
                    }

                    const a = field.getAttributes();

                    if (
                        !a ||
                        String(a.queryId) !== String(ID) ||
                        a.dataType !== 'taxonomy' ||
                        !Object.prototype.hasOwnProperty.call(
                            VALUES,
                            a.dataTaxonomy
                        )
                    ) {
                        return;
                    }

                    expected++;

                    const wanted = (
                        Array.isArray(VALUES[a.dataTaxonomy])
                            ? VALUES[a.dataTaxonomy]
                            : [VALUES[a.dataTaxonomy]]
                    ).map(String);

                    const current = (
                        Array.isArray(field.getValues())
                            ? field.getValues()
                            : []
                    ).map(String);

                    if (same(current, wanted)) {

                        correct++;

                    } else {

                        field.setValues(wanted);
                    }
                });

                if (
                    expected &&
                    correct === expected
                ) {
                    synced = true;
                    ready = true;

                    window.TFSC_SF_COMBO_READY = true;
                }
            };

            const resultUrl = query => {

                if (
                    !query ||
                    typeof query.getUrl !== 'function' ||
                    typeof query.getFields !== 'function'
                ) {
                    return null;
                }

                const base = query.getUrl();

                if (!base) {
                    return null;
                }

                const prefix =
                    window.searchAndFilterData?.urlPrefix || '_';

                const parts = [];

                list(
                    query.getFields()
                ).forEach(field => {

                    if (
                        !field ||
                        typeof field.getUrlName !== 'function' ||
                        typeof field.getUrlValues !== 'function'
                    ) {
                        return;
                    }

                    const name =
                        field.getUrlName();

                    let values =
                        field.getUrlValues();

                    if (!name) {
                        return;
                    }

                    if (
                        values !== null &&
                        values !== undefined &&
                        !Array.isArray(values)
                    ) {
                        values = [values];
                    }

                    values = Array.isArray(values)
                        ? values.filter(v =>
                            v !== null &&
                            v !== undefined &&
                            String(v) !== ''
                        )
                        : [];

                    if (!values.length) {
                        return;
                    }

                    parts.push(
                        encodeURIComponent(prefix + name)
                        + '='
                        + values.map(v =>
                            encodeURIComponent(String(v))
                        ).join(',')
                    );
                });

                if (
                    typeof query.getActiveUrlArg === 'function'
                ) {

                    const active =
                        query.getActiveUrlArg();

                    if (active) {
                        parts.push(
                            encodeURIComponent(active)
                        );
                    }
                }

                const clean = String(base)
                    .split('#')[0]
                    .split('?')[0];

                return parts.length
                    ? clean + '?' + parts.join('&')
                    : clean;
            };

            const attach = () => {

                if (attached) {
                    return true;
                }

                const queries =
                    window.searchAndFilter?.frontend?.queries;

                if (
                    !queries ||
                    typeof queries.get !== 'function'
                ) {
                    return false;
                }

                const query =
                    queries.get(ID);

                if (
                    !query ||
                    typeof query.on !== 'function'
                ) {
                    return false;
                }

                attached = true;

                query.on(
                    'get-results/start',
                    () => {

                        if (
                            redirecting ||
                            (IS_COMBO && !ready)
                        ) {
                            return;
                        }

                        const url =
                            resultUrl(query);

                        if (!url) {
                            return;
                        }

                        redirecting = true;

                        window.location.href = url;
                    }
                );

                return true;
            };

            const start = () => {

                [50, 250, 750, 1500].forEach(
                    t => setTimeout(sync, t)
                );

                [250, 750, 1500].forEach(
                    t => setTimeout(attach, t)
                );
            };

            document.addEventListener(
                'search-filter/mount',
                () => {

                    [0, 100].forEach(
                        t => setTimeout(sync, t)
                    );

                    [150, 400].forEach(
                        t => setTimeout(attach, t)
                    );
                }
            );

            if (
                document.readyState === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    start
                );

            } else {

                start();
            }

            window.addEventListener(
                'pageshow',
                e => {

                    if (e.persisted) {
                        window.location.reload();
                    }
                }
            );
        })();
        </script>
        <?php
    },
    90
);


