 * [combo_term taxonomy="..."]
 * ============================================================ */

add_shortcode(
    'combo_term',
    function( $atts ) {

        if ( ! tfsc_combo_core_ready() ) {
            return '';
        }

        $atts = shortcode_atts(
            [
                'taxonomy' => '',
                'separator' => ' • ',
            ],
            $atts,
            'combo_term'
        );

        $taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );

        if ( ! $taxonomy ) {
            return '';
        }

        if ( tfsc_is_combo_archive() ) {

            $groups =
                tfsc_group_combo_terms( 'name' );

            return empty(
                $groups[ $taxonomy ]
            )
                ? ''
                : esc_html(
                    implode(
                        (string) $atts['separator'],
                        $groups[ $taxonomy ]
                    )
                );
        }

        $term =
            get_queried_object();

        return (
            $term instanceof WP_Term &&
            $term->taxonomy === $taxonomy &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        )
            ? esc_html( $term->name )
            : '';
    }
);

