/* ============================================================
 * MAIN QUERY + SEARCH & FILTER COMBO INTEGRATIE
 * ============================================================ */

/**
 * Virtuele combo archives koppelen aan Search & Filter Query 1.
 *
 * De combo-code bepaalt alleen WELKE taxonomy-context verplicht is.
 * Search & Filter blijft eigenaar van:
 *
 * - posts_per_page
 * - sortering
 * - statusvoorwaarden
 * - indexer
 * - frontend filters
 * - pagination
 */
add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            ! tfsc_combo_core_ready() ||
            is_admin() ||
            ! $query->is_main_query() ||
            ! tfsc_is_combo_archive()
        ) {
            return;
        }

        /*
         * Officiële S&F custom-query koppeling.
         */
        $query->set(
            'search_filter_query_id',
            TFSC_SEARCH_FILTER_QUERY_ID
        );

        /*
         * Zorg dat WordPress deze virtuele archive
         * als vacature-query behandelt.
         *
         * Overige query-instellingen komen van S&F.
         */
        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );

        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


/**
 * Voeg de vaste combo-taxonomies rechtstreeks toe
 * aan de query arguments van Search & Filter.
 *
 * Dit werkt dus ook op de Elementor-widgetquery die
 * Search & Filter zelf aanmaakt.
 */
add_filter(
    'search-filter/query/query_args',
    function( $query_args, $search_filter_query ) {

        if (
            ! tfsc_combo_core_ready() ||
            ! tfsc_is_combo_archive() ||
            ! is_object( $search_filter_query ) ||
            ! method_exists( $search_filter_query, 'get_id' )
        ) {
            return $query_args;
        }

        /*
         * Alleen onze vacature-query aanpassen.
         */
        if (
            (int) $search_filter_query->get_id()
            !==
            (int) TFSC_SEARCH_FILTER_QUERY_ID
        ) {
            return $query_args;
        }

        $groups = tfsc_group_combo_terms();

        if ( ! $groups ) {
            return $query_args;
        }

        /*
         * Bestaande S&F tax_query behouden.
         *
         * Hier zit bijvoorbeeld:
         *
         * vac_status NOT IN gesloten-oud, ingevuld
         */
        $tax_query =
            isset( $query_args['tax_query'] ) &&
            is_array( $query_args['tax_query'] )
                ? $query_args['tax_query']
                : [];

        /*
         * S&F voorwaarden EN combo voorwaarden
         * moeten allemaal gelden.
         */
        $tax_query['relation'] = 'AND';

        foreach (
            $groups
            as $taxonomy => $term_ids
        ) {

            if ( ! $term_ids ) {
                continue;
            }

            $object =
                get_taxonomy(
                    $taxonomy
                );

            $method =
                tfsc_get_combo_taxonomy_match_method(
                    $taxonomy
                );

            $tax_query[] = [
                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    array_map(
                        'intval',
                        $term_ids
                    ),

                'operator' =>
                    (
                        'AND' === $method &&
                        count( $term_ids ) > 1
                    )
                        ? 'AND'
                        : 'IN',

                'include_children' =>
                    (
                        'AND' !== $method &&
                        $object &&
                        $object->hierarchical
                    ),
            ];
        }

        $query_args['tax_query'] =
            $tax_query;

        return $query_args;
    },
    20,
    2
);


/**
 * Native vacature-taxonomy archives.
