/**
 * TFSC - Volledig dynamische vacature-archieven
 * Version 5.6 - S&F Integrated / Core Safe / Pagination
 *
 * Vereist:
 * - TFSC - Combo Archive URLs
 *
 * Regelt:
 * - /vacatures/... combo archives
 * - combo pagination via /page/N/
 * - verschillende taxonomies = AND
 * - meerdere terms binnen taxonomy = OR
 * - kennisgebied = AND
 * - Search & Filter Query 1 als centrale vacature-query
 * - native vacature-taxonomy archives
 * - Search & Filter frontend sync
 * - Elementor archive conditions
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 */


/* ============================================================
 * CONFIG + CORE CHECK
 * ============================================================ */

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}


function tfsc_combo_core_ready() {

    return (
        defined( 'TFSC_COMBO_BASE' ) &&
        defined( 'TFSC_VACANCY_POST_TYPE' ) &&
        defined( 'TFSC_STATUS_TAXONOMY' ) &&
        defined( 'TFSC_OPEN_STATUS_SLUG' ) &&
        defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) &&
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        function_exists( 'tfsc_urlcore_get_allowed_taxonomies' ) &&
        function_exists( 'tfsc_urlcore_resolve_term_path' )
    );
}


/* ============================================================
 * COMPATIBILITEIT MET URL CORE
 * ============================================================ */

function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    return (
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        tfsc_urlcore_taxonomy_allowed( $taxonomy )
    );
}


function tfsc_get_allowed_combo_taxonomies() {

    return function_exists( 'tfsc_urlcore_get_allowed_taxonomies' )
        ? tfsc_urlcore_get_allowed_taxonomies()
        : [];
}


function tfsc_resolve_term_path( $taxonomy, $segments ) {

    return function_exists( 'tfsc_urlcore_resolve_term_path' )
        ? tfsc_urlcore_resolve_term_path( $taxonomy, $segments )
        : false;
}


/* ============================================================
 * HELPERS
 * ============================================================ */

function tfsc_get_combo_taxonomy_match_method( $taxonomy ) {

    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


function tfsc_combo_status_clause() {

    if (
        ! defined( 'TFSC_STATUS_TAXONOMY' ) ||
        ! defined( 'TFSC_OPEN_STATUS_SLUG' )
    ) {
        return [];
    }

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_is_combo_archive() {

    return (bool) get_query_var( 'tfsc_combo_archive' );
}


function tfsc_is_vacancy_seo_landing() {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term = get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed( $term->taxonomy )
    );
}


/* ============================================================
 * QUERY VARS + REWRITES
 * ============================================================ */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';
        $vars[] = 'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        if (
            ! defined( 'TFSC_COMBO_BASE' ) ||
            '' === trim( (string) TFSC_COMBO_BASE )
        ) {
            return;
        }

        $base = preg_quote(
            trim( TFSC_COMBO_BASE, '/' ),
            '/'
        );

        /*
         * Paginated combo archive.
         *
         * Moet vóór de algemene combo rewrite staan.
         */
        add_rewrite_rule(
            '^' . $base . '/(.+?)/page/([0-9]+)/?$',
            'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]&paged=$matches[2]',
            'top'
        );

        /*
         * Normaal combo archive.
         */
        add_rewrite_rule(
            '^' . $base . '/(.+?)/?$',
            'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]',
            'top'
        );
    },
    99
);


/* ============================================================
 * COMBO PARSER
 * ============================================================ */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;

    if ( $resolved ) {
        return $cache;
    }

    $resolved = true;

    if (
        ! tfsc_combo_core_ready() ||
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }

    $path = trim(
        (string) get_query_var( 'tfsc_combo_path' ),
        '/'
    );

    if ( '' === $path ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            explode( '/', $path ),
            'strlen'
        )
    );

    if ( count( $segments ) < 2 ) {
        return false;
    }

    $allowed = tfsc_get_allowed_combo_taxonomies();

    if ( ! $allowed ) {
        return false;
    }

    $items = [];
    $count = count( $segments );
    $i     = 0;

    while ( $i < $count ) {

        $taxonomy = sanitize_key(
            $segments[ $i++ ]
        );

        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }

        $term_segments = [];

        while ( $i < $count ) {

            $possible_taxonomy = sanitize_key(
                $segments[ $i ]
            );

            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }

            $term_segments[] =
                $segments[ $i++ ];
        }

        if ( ! $term_segments ) {
            return false;
        }

        $resolved_path =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );

        if ( ! $resolved_path ) {
            return false;
        }

        $items[] = [
            'taxonomy' => $taxonomy,
            'term'     => $resolved_path['term'],
            'path'     => $resolved_path['path'],
        ];
    }

    $cache = $items ?: false;

    return $cache;
}


/* ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================ */

function tfsc_group_combo_terms( $property = 'term_id' ) {

    $combo = tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    $grouped = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $term = $item['term'];

        switch ( $property ) {

            case 'name':
                $value = trim( $term->name );
                break;

            case 'slug':
                $value = $term->slug;
                break;

            default:
                $value = (int) $term->term_id;
                break;
        }

        if ( '' === $value || 0 === $value ) {
            continue;
        }

        $key = is_int( $value )
            ? $value
            : (string) $value;

        $grouped[
            $item['taxonomy']
        ][ $key ] = $value;
    }

    foreach ( $grouped as $taxonomy => $values ) {
        $grouped[ $taxonomy ] =
            array_values( $values );
    }

    return $grouped;
}


/* ============================================================
 * COMBO TAX QUERY BUILDER
 * ============================================================ */

function tfsc_build_combo_tax_query() {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }

    $groups = tfsc_group_combo_terms();

    if ( ! $groups ) {
        return false;
    }

    $tax_query = [
        'relation' => 'AND',
    ];

    foreach ( $groups as $taxonomy => $term_ids ) {

        if ( ! $term_ids ) {
            continue;
        }

        $object = get_taxonomy( $taxonomy );

        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );

        $tax_query[] = [
            'taxonomy' => $taxonomy,
            'field'    => 'term_id',
            'terms'    => array_map(
                'intval',
                $term_ids
            ),

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method &&
                    $object &&
                    $object->hierarchical
                ),
        ];
    }

    return count( $tax_query ) > 1
        ? $tax_query
        : false;
}


/* ============================================================
 * MAIN QUERY
 * ============================================================ */

/**
 * Virtuele combo archive koppelen aan Search & Filter Query 1.
 *
 * TFSC bepaalt hier NIET:
 * - posts_per_page
 * - sorting
 * - statusfilter
 * - offset
 *
 * Die blijven volledig bij Search & Filter.
 */
add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            ! tfsc_combo_core_ready() ||
            is_admin() ||
            ! $query->is_main_query() ||
            ! tfsc_is_combo_archive()
        ) {
            return;
        }

        $query->set(
            'search_filter_query_id',
            TFSC_SEARCH_FILTER_QUERY_ID
        );

        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );

        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


/* ============================================================
 * SEARCH & FILTER SERVER-SIDE COMBO CONTEXT
 * ============================================================ */

/**
 * Voeg combo-taxonomies rechtstreeks toe aan S&F Query 1.
 *
 * S&F blijft eigenaar van:
 * - posts_per_page
 * - sorting
 * - statusvoorwaarden
 * - indexer
 * - frontend filtering
 * - pagination
 *
 * TFSC voegt alleen de vaste combo-context toe.
 */
add_filter(
    'search-filter/query/query_args',
    function( $query_args, $search_filter_query ) {

        if (
            ! tfsc_combo_core_ready() ||
            ! tfsc_is_combo_archive() ||
            ! is_object( $search_filter_query ) ||
            ! method_exists(
                $search_filter_query,
                'get_id'
            )
        ) {
            return $query_args;
        }

        if (
            (int) $search_filter_query->get_id()
            !==
            (int) TFSC_SEARCH_FILTER_QUERY_ID
        ) {
            return $query_args;
        }

        $combo_tax_query =
            tfsc_build_combo_tax_query();

        if ( ! $combo_tax_query ) {
            return $query_args;
        }

        $tax_query =
            isset( $query_args['tax_query'] ) &&
            is_array( $query_args['tax_query'] )
                ? $query_args['tax_query']
                : [];

        $tax_query['relation'] = 'AND';

        foreach (
            $combo_tax_query
            as $key => $clause
        ) {

            if (
                'relation' === $key ||
                ! is_array( $clause )
            ) {
                continue;
            }

            /*
             * Niet dubbel toevoegen wanneer S&F deze
             * archive-context zelf al heeft overgenomen.
             */
            $exists = false;

            foreach (
                $tax_query
                as $existing_key => $existing
            ) {

                if (
                    'relation' === $existing_key ||
                    ! is_array( $existing )
                ) {
                    continue;
                }

                if (
                    empty( $existing['taxonomy'] ) ||
                    $existing['taxonomy']
                        !==
                        $clause['taxonomy']
                ) {
                    continue;
                }

                $existing_terms =
                    array_map(
                        'intval',
                        (array) (
                            $existing['terms']
                            ?? []
                        )
                    );

                $new_terms =
                    array_map(
                        'intval',
                        (array) (
                            $clause['terms']
                            ?? []
                        )
                    );

                sort( $existing_terms );
                sort( $new_terms );

                if (
                    $existing_terms === $new_terms &&
                    (
                        $existing['field']
                        ?? 'term_id'
                    ) === (
                        $clause['field']
                        ?? 'term_id'
                    ) &&
                    (
                        $existing['operator']
                        ?? 'IN'
                    ) === (
                        $clause['operator']
                        ?? 'IN'
                    )
                ) {
                    $exists = true;
                    break;
                }
            }

            if ( ! $exists ) {
                $tax_query[] = $clause;
            }
        }

        $query_args['tax_query'] =
            $tax_query;

        return $query_args;
    },
    20,
    2
);


/* ============================================================
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * ============================================================ */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            ! tfsc_combo_core_ready() ||
            is_admin() ||
            ! $query->is_main_query() ||
            tfsc_is_combo_archive() ||
            ! $query->is_tax()
        ) {
            return;
        }

        $term =
            $query->get_queried_object();

        if (
            ! $term instanceof WP_Term ||
            ! tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {
            return;
        }

        $status =
            tfsc_combo_status_clause();

        if ( ! $status ) {
            return;
        }

        $tax_query =
            $query->get( 'tax_query' );

        if ( ! is_array( $tax_query ) ) {
            $tax_query = [];
        }

        $tax_query[] = $status;
        $tax_query['relation'] = 'AND';

        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );

        $query->set(
            'post_status',
            'publish'
        );

        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
);


