add_shortcode(
    'combo_term',
    function( $atts ) {

        if ( ! tfsc_combo_core_ready() ) {
            return '';
        }

        $atts =
            shortcode_atts(
                [
                    'taxonomy'  => '',
                    'separator' => ' • ',
                ],
                $atts,
                'combo_term'
            );

        $taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );

        if ( ! $taxonomy ) {
            return '';
        }

        if ( tfsc_is_combo_archive() ) {

            $groups =
                tfsc_group_combo_terms(
                    'name'
                );

            return empty(
                $groups[
                    $taxonomy
                ]
            )
                ? ''
                : esc_html(
                    implode(
                        (string) $atts['separator'],
                        $groups[
                            $taxonomy
                        ]
                    )
                );
        }

        $term =
            get_queried_object();

        return (
            $term instanceof WP_Term &&
            $term->taxonomy === $taxonomy &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        )
            ? esc_html(
                $term->name
            )
            : '';
    }
);

/**
 * TFSC - Volledig dynamische vacature-archieven
 * Version 5.4.1 - S&F Native Integration / Match Any-All / Pagination
 *
 * Vereist:
 * - TFSC - Combo Archive URLs
 *
 * Architectuur:
 * - URL Core bepaalt geldige taxonomies en combo-URL's.
 * - Deze Base parseert virtuele combo archives.
 * - Search & Filter Query 1 beheert:
 *   - posts_per_page
 *   - sortering
 *   - statusvoorwaarden
 *   - indexer
 *   - filters
 *   - pagination
 * - TFSC voegt alleen de vaste combo-context toe aan S&F.
 * - Wanneer dezelfde taxonomy ook via S&F wordt gekozen:
 *   - Match Any => combo + gekozen termen = OR
 *   - Match All => combo + gekozen termen = AND
 *
 * Regelt verder:
 * - /vacatures/... combo archives
 * - /page/N/ pagination
 * - native vacature-taxonomy archives
 * - Search & Filter frontend sync
 * - Elementor archive conditions
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 */


/* ============================================================
 * CONFIG + CORE CHECK
 * ============================================================ */

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}


function tfsc_combo_core_ready() {

    return (
        defined( 'TFSC_COMBO_BASE' ) &&
        defined( 'TFSC_VACANCY_POST_TYPE' ) &&
        defined( 'TFSC_STATUS_TAXONOMY' ) &&
        defined( 'TFSC_OPEN_STATUS_SLUG' ) &&
        defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) &&
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        function_exists( 'tfsc_urlcore_get_allowed_taxonomies' ) &&
        function_exists( 'tfsc_urlcore_resolve_term_path' )
    );
}


/* ============================================================
 * COMPATIBILITEIT MET URL CORE
 * ============================================================ */

function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    return (
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        tfsc_urlcore_taxonomy_allowed( $taxonomy )
    );
}


function tfsc_get_allowed_combo_taxonomies() {

    return function_exists( 'tfsc_urlcore_get_allowed_taxonomies' )
        ? tfsc_urlcore_get_allowed_taxonomies()
        : [];
}


function tfsc_resolve_term_path( $taxonomy, $segments ) {

    return function_exists( 'tfsc_urlcore_resolve_term_path' )
        ? tfsc_urlcore_resolve_term_path(
            $taxonomy,
            $segments
        )
        : false;
}


/* ============================================================
 * ALGEMENE HELPERS
 * ============================================================ */

function tfsc_get_combo_taxonomy_match_method( $taxonomy ) {

    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


function tfsc_combo_status_clause() {

    if (
        ! defined( 'TFSC_STATUS_TAXONOMY' ) ||
        ! defined( 'TFSC_OPEN_STATUS_SLUG' )
    ) {
        return [];
    }

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_is_combo_archive() {

    return (bool) get_query_var(
        'tfsc_combo_archive'
    );
}


function tfsc_is_vacancy_seo_landing() {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term = get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


/* ============================================================
 * QUERY VARS + REWRITES
 * ============================================================ */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';
        $vars[] = 'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        if (
            ! defined( 'TFSC_COMBO_BASE' ) ||
            '' === trim(
                (string) TFSC_COMBO_BASE
            )
        ) {
            return;
        }

        $base = preg_quote(
            trim(
                TFSC_COMBO_BASE,
                '/'
            ),
            '/'
        );

        /*
         * Paginated combo archive.
         *
         * Deze regel MOET vóór de algemene
         * combo rewrite staan.
         */
        add_rewrite_rule(
            '^' . $base . '/(.+?)/page/([0-9]+)/?$',
            'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]&paged=$matches[2]',
            'top'
        );

        /*
         * Normaal combo archive.
         */
        add_rewrite_rule(
            '^' . $base . '/(.+?)/?$',
            'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]',
            'top'
        );
    },
    99
);


/* ============================================================
 * COMBO PARSER
 * ============================================================ */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;

    if ( $resolved ) {
        return $cache;
    }

    $resolved = true;

    if (
        ! tfsc_combo_core_ready() ||
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }

    $path = trim(
        (string) get_query_var(
            'tfsc_combo_path'
        ),
        '/'
    );

    if ( '' === $path ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            explode(
                '/',
                $path
            ),
            'strlen'
        )
    );

    if ( count( $segments ) < 2 ) {
        return false;
    }

    $allowed =
        tfsc_get_allowed_combo_taxonomies();

    if ( ! $allowed ) {
        return false;
    }

    $items = [];
    $count = count( $segments );
    $i     = 0;

    while ( $i < $count ) {

        $taxonomy = sanitize_key(
            $segments[ $i++ ]
        );

        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }

        $term_segments = [];

        while ( $i < $count ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[ $i ]
                );

            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }

            $term_segments[] =
                $segments[ $i++ ];
        }

        if ( ! $term_segments ) {
            return false;
        }

        $resolved_path =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );

        if ( ! $resolved_path ) {
            return false;
        }

        $items[] = [
            'taxonomy' => $taxonomy,
            'term'     => $resolved_path['term'],
            'path'     => $resolved_path['path'],
        ];
    }

    $cache = $items ?: false;

    return $cache;
}


/* ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================ */

function tfsc_group_combo_terms(
    $property = 'term_id'
) {

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    $grouped = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $term = $item['term'];

        switch ( $property ) {

            case 'name':
                $value =
                    trim( $term->name );
                break;

            case 'slug':
                $value =
                    $term->slug;
                break;

            default:
                $value =
                    (int) $term->term_id;
                break;
        }

        if (
            '' === $value ||
            0 === $value
        ) {
            continue;
        }

        $key = is_int( $value )
            ? $value
            : (string) $value;

        $grouped[
            $item['taxonomy']
        ][ $key ] = $value;
    }

    foreach (
        $grouped
        as $taxonomy => $values
    ) {

        $grouped[ $taxonomy ] =
            array_values( $values );
    }

    return $grouped;
}


/* ============================================================
 * COMBO TAX QUERY BUILDER
 * ============================================================ */

function tfsc_build_combo_tax_query() {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }

    $groups =
        tfsc_group_combo_terms();

    if ( ! $groups ) {
        return false;
    }

    $tax_query = [
        'relation' => 'AND',
    ];

    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        if ( ! $term_ids ) {
            continue;
        }

        $object =
            get_taxonomy(
                $taxonomy
            );

        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );

        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                array_values(
                    array_unique(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                ),

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method &&
                    $object &&
                    $object->hierarchical
                ),
        ];
    }

    return count( $tax_query ) > 1
        ? $tax_query
        : false;
}


/* ============================================================
 * MAIN QUERY
 * ============================================================ */

/**
