/* ============================================================
 * SEARCH & FILTER SERVER-SIDE HELPERS
 * ============================================================ */

/**
 * Zoek het S&F-field dat bij een taxonomy hoort.
 */

function tfsc_sf_get_taxonomy_field(
    $search_filter_query,
    $taxonomy
) {

    if (
        ! is_object( $search_filter_query ) ||
        ! method_exists(
            $search_filter_query,
            'get_fields'
        )
    ) {
        return false;
    }

    $fields =
        $search_filter_query->get_fields();

    if (
        ! is_array( $fields ) &&
        ! $fields instanceof Traversable
    ) {
        return false;
    }

    foreach ( $fields as $field ) {

        if (
            ! is_object( $field ) ||
            ! method_exists(
                $field,
                'get_attribute'
            )
        ) {
            continue;
        }

        if (
            'taxonomy' !==
            (string) $field->get_attribute(
                'dataType'
            )
        ) {
            continue;
        }

        if (
            $taxonomy !==
            (string) $field->get_attribute(
                'dataTaxonomy'
            )
        ) {
            continue;
        }

        return $field;
    }

    return false;
}


/**
 * Match Any / Match All uitlezen
 * uit het S&F-field.
 *
 * any = OR
 * all = AND
 */

function tfsc_sf_get_taxonomy_match_method(
    $search_filter_query,
    $taxonomy
) {

    $field =
        tfsc_sf_get_taxonomy_field(
            $search_filter_query,
            $taxonomy
        );

    if (
        $field &&
        method_exists(
            $field,
            'get_attribute'
        )
    ) {

        $method = strtolower(
            trim(
                (string)
                $field->get_attribute(
                    'multipleMatchMethod'
                )
            )
        );

        if ( 'all' === $method ) {
            return 'AND';
        }

        if ( 'any' === $method ) {
            return 'OR';
        }
    }

    /*
     * Fallback voor velden zonder
     * multipleMatchMethod, bijvoorbeeld
     * een single select.
     */
    return tfsc_get_combo_taxonomy_match_method(
        $taxonomy
    );
}


/**
 * Verschillende termwaarde-formaten
 * omzetten naar term IDs.
 *
 * Ondersteunt:
 * - WP_Term
 * - term_id
 * - taxonomy slug
 * - arrays met term_id/value
 */

function tfsc_sf_values_to_term_ids(
    $taxonomy,
    $values
) {

    $ids = [];

    foreach (
        (array) $values
        as $value
    ) {

        if ( $value instanceof WP_Term ) {

            if (
                $taxonomy ===
                $value->taxonomy
            ) {
                $ids[] =
                    (int) $value->term_id;
            }

            continue;
        }


        if ( is_array( $value ) ) {

            if (
                isset(
                    $value['term_id']
                )
            ) {

                $value =
                    $value['term_id'];

            } elseif (
                isset(
                    $value['value']
                )
            ) {

                $value =
                    $value['value'];

            } else {

                continue;
            }
        }


        if ( is_numeric( $value ) ) {

            $term =
                get_term(
                    (int) $value,
                    $taxonomy
                );

            if (
                $term instanceof WP_Term &&
                ! is_wp_error( $term )
            ) {

                $ids[] =
                    (int) $term->term_id;
            }

            continue;
        }


        $slug = sanitize_title(
            (string) $value
        );

        if ( '' === $slug ) {
            continue;
        }

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {

            $ids[] =
                (int) $term->term_id;
        }
    }

    return array_values(
        array_unique(
            array_filter(
                array_map(
                    'intval',
                    $ids
                )
            )
        )
    );
}


/**
 * Terms uit één bestaande tax_query-clause
 * omzetten naar IDs.
 */

function tfsc_sf_clause_term_ids(
    $taxonomy,
    array $clause
) {

    $values =
        (array) (
            $clause['terms']
            ?? []
        );

    $field = strtolower(
        (string) (
            $clause['field']
            ?? 'term_id'
        )
    );

    if (
        'term_id' === $field ||
        'id' === $field
    ) {

        return array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $values
                    )
                )
            )
        );
    }

    return tfsc_sf_values_to_term_ids(
        $taxonomy,
        $values
    );
}


/**
 * Positieve clauses voor één taxonomy uit
 * een tax_query halen en de gebruikte term IDs
 * teruggeven.
 *
 * IN / AND worden samengevoegd.
 *
 * Negatieve clauses zoals NOT IN blijven
 * volledig ongemoeid.
 */

function tfsc_sf_extract_positive_taxonomy_terms(
    &$tax_query,
    $taxonomy
) {

    $found_terms =
        [];

    $clean =
        [];

    $relation =
        isset(
            $tax_query['relation']
        )
            ? strtoupper(
                (string)
                $tax_query['relation']
            )
            : 'AND';

    foreach (
        $tax_query
        as $key => $clause
    ) {

        if ( 'relation' === $key ) {
            continue;
        }

        if ( ! is_array( $clause ) ) {
            continue;
        }

        /*
         * Nested/complexe tax_query:
         * ongemoeid laten.
         */
        if (
            empty(
                $clause['taxonomy']
            )
        ) {

            $clean[] =
                $clause;

            continue;
        }


        if (
            $taxonomy !==
            (string) $clause['taxonomy']
        ) {

            $clean[] =
                $clause;

            continue;
        }


        $operator = strtoupper(
            (string) (
                $clause['operator']
                ?? 'IN'
            )
        );


        /*
         * Alleen positieve selecties
         * worden samengevoegd.
         */
        if (
            ! in_array(
                $operator,
                [
                    'IN',
                    'AND',
                ],
                true
            )
        ) {

            $clean[] =
                $clause;

            continue;
        }


        $found_terms =
            array_merge(
                $found_terms,
                tfsc_sf_clause_term_ids(
                    $taxonomy,
                    $clause
                )
            );
    }


    $tax_query = [
        'relation' =>
            in_array(
                $relation,
                [ 'AND', 'OR' ],
                true
            )
                ? $relation
                : 'AND',
    ];


    foreach ( $clean as $clause ) {
        $tax_query[] = $clause;
    }


    return array_values(
        array_unique(
            array_filter(
                array_map(
                    'intval',
                    $found_terms
                )
            )
        )
    );
}

/* ============================================================
 * SEARCH & FILTER COMBO FIELD OPTIONS
 * ============================================================ */

/**
 * Op een combo archive moet een taxonomy die al onderdeel
 * van de combo is zijn andere keuzemogelijkheden blijven tonen.
 *
 * Voorbeeld:
 *
 * /vacatures/functienaam/field-service-engineer/
 *
 * Het functienaam-field moet dan niet alleen functienamen tonen
 * die binnen de huidige FSE-resultaatset voorkomen.
 *
 * Waarom:
 *
 * functienaam = Match Any
 *
 * De gebruiker moet dus bijvoorbeeld ook:
 *
 * Field Service Engineer + Site Manager
 *
 * kunnen selecteren.
 *
 * De uiteindelijke OR/AND-resultaatlogica blijft volledig in
 * search-filter/query/query_args staan.
 */
add_filter(
    'search-filter/fields/choice/options',
    function( $options, $field ) {

        if (
            ! tfsc_combo_core_ready() ||
            ! tfsc_is_combo_archive() ||
            ! tfsc_get_combo_archive() ||
            ! is_object( $field ) ||
            ! method_exists(
                $field,
                'get_attribute'
            )
        ) {
            return $options;
        }


        /*
         * Alleen taxonomy fields.
         */
        if (
            'taxonomy' !==
            (string) $field->get_attribute(
                'dataType'
            )
        ) {
            return $options;
        }


        /*
         * Alleen fields van onze vacaturequery.
         */
        $query_id =
            $field->get_attribute(
                'queryId'
            );

        if (
            null !== $query_id &&
            '' !== $query_id &&
            (int) $query_id !==
                (int) TFSC_SEARCH_FILTER_QUERY_ID
        ) {
            return $options;
        }


        $taxonomy =
            sanitize_key(
                (string) $field->get_attribute(
                    'dataTaxonomy'
                )
            );


        if (
            ! $taxonomy ||
            ! taxonomy_exists(
                $taxonomy
            )
        ) {
            return $options;
        }


        /*
         * Alleen ingrijpen wanneer deze taxonomy daadwerkelijk
         * onderdeel is van de huidige combo.
         *
         * Andere filters mogen gewoon hun normale dynamische
         * S&F hideEmpty/autocount gedrag houden.
         */
        $combo_groups =
            tfsc_group_combo_terms(
                'slug'
            );


        if (
            empty(
                $combo_groups[
                    $taxonomy
                ]
            )
        ) {
            return $options;
        }


        /*
         * Bestaande S&F options indexeren.
         *
         * Die behouden we volledig, inclusief de door S&F
         * berekende counts.
         */
        $existing =
            [];


        foreach (
            (array) $options
            as $option
        ) {

            if (
                ! is_array( $option ) ||
                ! isset(
                    $option['value']
                )
            ) {
                continue;
            }

            $value =
                (string) $option['value'];

            if ( '' === $value ) {
                continue;
            }

            $existing[
                $value
            ] = $option;
        }


        /*
         * Alle niet-lege terms van deze taxonomy ophalen.
         *
         * Hierdoor verdwijnen sibling/andere terms niet alleen
         * omdat de huidige combo-query al één term bevat.
         */
        $terms =
            get_terms(
                [
                    'taxonomy'   =>
                        $taxonomy,

                    'hide_empty' =>
                        true,

                    'orderby'    =>
                        'name',

                    'order'      =>
                        'ASC',
                ]
            );


        if (
            is_wp_error( $terms ) ||
            ! $terms
        ) {
            return $options;
        }


        foreach (
            $terms
            as $term
        ) {

            if (
                ! $term instanceof WP_Term
            ) {
                continue;
            }


            $value =
                (string) $term->slug;


            /*
             * Als S&F deze option al heeft:
             * niets veranderen.
             *
             * Daarmee behouden we S&F's eigen count,
             * depth en eventuele andere metadata.
             */
            if (
                isset(
                    $existing[
                        $value
                    ]
                )
            ) {
                continue;
            }


            /*
             * Ontbrekende option terugplaatsen.
             *
             * Alleen label/value zijn volgens de officiële
             * S&F API verplicht.
             */
            $existing[
                $value
            ] = [
                'label' =>
                    $term->name,

                'value' =>
                    $value,

                'count' =>
                    (int) $term->count,

                'depth' =>
                    0,
            ];
        }


        /*
         * Sortering op label zodat het field voorspelbaar blijft.
         */
        uasort(
            $existing,
            function( $a, $b ) {

                $label_a =
                    isset(
                        $a['label']
                    )
                        ? (string) $a['label']
                        : '';

                $label_b =
                    isset(
                        $b['label']
                    )
                        ? (string) $b['label']
                        : '';

                return strnatcasecmp(
                    $label_a,
                    $label_b
                );
            }
        );


        return array_values(
            $existing
        );
    },
    20,
    2
);

/* ============================================================
 * SEARCH & FILTER SERVER-SIDE COMBO CONTEXT
 * ============================================================ */

/**
 * Voeg de vaste combo-context toe aan S&F Query 1.
 *
 * Cruciaal:
 *
 * Als dezelfde taxonomy óók via het filter
 * geselecteerd wordt, combineren we die waarden
 * volgens de instelling van het S&F-field.
 *
 * Voorbeeld Match Any:
 *
 * URL:
 * Field Service Engineer
 *
 * Filter:
 * Service Engineer
 *
 * WordPress:
 * terms = [FSE, Service Engineer]
 * operator = IN
 *
 * Resultaat:
 * FSE OR Service Engineer
 *
 *
 * Voorbeeld Match All:
 *
 * URL:
 * Mechanisch
 *
 * Filter:
 * Elektrotechniek
 *
 * WordPress:
 * terms = [Mechanisch, Elektrotechniek]
 * operator = AND
 *
 * Resultaat:
 * Mechanisch AND Elektrotechniek
 */

add_filter(
    'search-filter/query/query_args',
    function(
        $query_args,
        $search_filter_query
    ) {

        if (
            ! tfsc_combo_core_ready() ||
            ! tfsc_is_combo_archive() ||
            ! is_object(
                $search_filter_query
            ) ||
            ! method_exists(
                $search_filter_query,
                'get_id'
            )
        ) {
            return $query_args;
        }


        if (
            (int)
            $search_filter_query->get_id()
            !==
            (int)
            TFSC_SEARCH_FILTER_QUERY_ID
        ) {
            return $query_args;
        }


        $groups =
            tfsc_group_combo_terms();

        if ( ! $groups ) {
            return $query_args;
        }


        $tax_query =
            isset(
                $query_args['tax_query']
            ) &&
            is_array(
                $query_args['tax_query']
            )
                ? $query_args['tax_query']
                : [];


        if (
            empty(
                $tax_query['relation']
            )
        ) {
            $tax_query['relation'] =
                'AND';
        }


        foreach (
            $groups
            as $taxonomy => $combo_term_ids
        ) {

            if ( ! $combo_term_ids ) {
                continue;
            }


            $combo_term_ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $combo_term_ids
                            )
                        )
                    )
                );


            /*
             * Bestaande positieve S&F clauses
             * voor dezelfde taxonomy ophalen
             * en uit de query halen.
             */
            $sf_term_ids =
                tfsc_sf_extract_positive_taxonomy_terms(
                    $tax_query,
                    $taxonomy
                );


            /*
             * Actieve field values rechtstreeks
             * uit Search & Filter meenemen.
             */
            $field =
                tfsc_sf_get_taxonomy_field(
                    $search_filter_query,
                    $taxonomy
                );


            if (
                $field &&
                method_exists(
                    $field,
                    'get_values'
                )
            ) {

                $field_values =
                    $field->get_values();

                if ( ! empty( $field_values ) ) {

                    $field_term_ids =
                        tfsc_sf_values_to_term_ids(
                            $taxonomy,
                            $field_values
                        );

                    $sf_term_ids =
                        array_merge(
                            $sf_term_ids,
                            $field_term_ids
                        );
                }
            }


            /*
             * Combo + actieve S&F waarden
             * samenvoegen.
             */
            $term_ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                array_merge(
                                    $combo_term_ids,
                                    $sf_term_ids
                                )
                            )
                        )
                    )
                );


            if ( ! $term_ids ) {
                continue;
            }


            /*
             * Match Any / Match All komt
             * rechtstreeks uit S&F.
             */
            $match_method =
                tfsc_sf_get_taxonomy_match_method(
                    $search_filter_query,
                    $taxonomy
                );


            $operator =
                'AND' === $match_method
                    ? 'AND'
                    : 'IN';


            $taxonomy_object =
                get_taxonomy(
                    $taxonomy
                );


            /*
             * Eén enkele positieve clause voor
             * deze taxonomy terugplaatsen.
             */
            $tax_query[] = [
                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    $term_ids,

                'operator' =>
                    $operator,

                'include_children' =>
                    (
                        'AND' !== $match_method &&
                        $taxonomy_object &&
                        $taxonomy_object->hierarchical
                    ),
            ];
        }


        $query_args['tax_query'] =
            $tax_query;


        return $query_args;
    },
    20,
    2
);


/* ============================================================
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * ============================================================ */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            ! tfsc_combo_core_ready() ||
            is_admin() ||
            ! $query->is_main_query() ||
            tfsc_is_combo_archive() ||
            ! $query->is_tax()
        ) {
            return;
        }


        $term =
            $query->get_queried_object();


        if (
            ! $term instanceof WP_Term ||
            ! tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {
            return;
        }


        $status =
            tfsc_combo_status_clause();


        if ( ! $status ) {
            return;
        }


        $tax_query =
            $query->get(
                'tax_query'
            );


        if ( ! is_array( $tax_query ) ) {
            $tax_query = [];
        }


        $tax_query[] =
            $status;


        $tax_query['relation'] =
            'AND';


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
);


