 * [combo_term taxonomy="..."]
 * ============================================================ */

add_shortcode(
    'combo_term',
    function( $atts ) {

        if (
            ! tfsc_combo_core_ready()
        ) {
            return '';
        }


        $atts =
            shortcode_atts(
                [
                    'taxonomy'  => '',
                    'separator' => ' • ',
                ],
                $atts,
                'combo_term'
            );


        $taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );


        if (
            ! $taxonomy
        ) {
            return '';
        }


        if (
            tfsc_is_combo_archive()
        ) {

            $groups =
                tfsc_group_combo_terms(
                    'name'
                );


            return empty(
                $groups[
                    $taxonomy
                ]
            )
                ? ''
                : esc_html(
                    implode(
                        (string)
                        $atts['separator'],
                        $groups[
                            $taxonomy
                        ]
                    )
                );
        }


        $term =
            get_queried_object();


        return (
            $term instanceof WP_Term &&
            $term->taxonomy
                ===
                $taxonomy &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        )
            ? esc_html(
                $term->name
            )
            : '';
    }
);

/**
 * TFSC - Volledig dynamische vacature-archieven
 * Version 5.5 - Native S&F Field Context / Pagination
 *
 * Vereist:
 * - TFSC - Combo Archive URLs
 *
 * Architectuur:
 *
 * 1. URL Core bepaalt geldige combo taxonomies / terms.
 * 2. Combo URL wordt geparsed.
 * 3. Combo terms worden intern als echte Search & Filter
 *    field values aangeboden.
 * 4. Search & Filter Query 1 beheert vervolgens zelf:
 *    - taxonomy filtering
 *    - Match Any / Match All
 *    - hideEmpty / counts
 *    - posts per page
 *    - sortering
 *    - statusfilter
 *    - indexer
 *    - pagination
 * 5. Elementor toont de S&F query.
 *
 * Er wordt dus GEEN harde combo tax_query meer bovenop
 * Search & Filter geplaatst.
 */


/* ============================================================
 * CONFIG
 * ============================================================ */

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}

if ( ! defined( 'TFSC_SEARCH_FILTER_URL_PREFIX' ) ) {
    define( 'TFSC_SEARCH_FILTER_URL_PREFIX', '_' );
}


/* ============================================================
 * CORE CHECK
 * ============================================================ */

function tfsc_combo_core_ready() {

    return (
        defined( 'TFSC_COMBO_BASE' ) &&
        defined( 'TFSC_VACANCY_POST_TYPE' ) &&
        defined( 'TFSC_STATUS_TAXONOMY' ) &&
        defined( 'TFSC_OPEN_STATUS_SLUG' ) &&
        defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) &&
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        function_exists( 'tfsc_urlcore_get_allowed_taxonomies' ) &&
        function_exists( 'tfsc_urlcore_resolve_term_path' )
    );
}


/* ============================================================
 * URL CORE COMPATIBILITEIT
 * ============================================================ */

function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    return (
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        tfsc_urlcore_taxonomy_allowed( $taxonomy )
    );
}


function tfsc_get_allowed_combo_taxonomies() {

    return function_exists( 'tfsc_urlcore_get_allowed_taxonomies' )
        ? tfsc_urlcore_get_allowed_taxonomies()
        : [];
}


function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    return function_exists( 'tfsc_urlcore_resolve_term_path' )
        ? tfsc_urlcore_resolve_term_path(
            $taxonomy,
            $segments
        )
        : false;
}


/* ============================================================
 * HELPERS
 * ============================================================ */

function tfsc_get_combo_taxonomy_match_method(
    $taxonomy
) {

    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


function tfsc_combo_status_clause() {

    if (
        ! defined( 'TFSC_STATUS_TAXONOMY' ) ||
        ! defined( 'TFSC_OPEN_STATUS_SLUG' )
    ) {
        return [];
    }

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_is_combo_archive() {

    return (bool) get_query_var(
        'tfsc_combo_archive'
    );
}


/* ============================================================
 * QUERY VARS + REWRITES
 * ============================================================ */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';
        $vars[] = 'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        if (
            ! defined( 'TFSC_COMBO_BASE' ) ||
            '' === trim(
                (string) TFSC_COMBO_BASE
            )
        ) {
            return;
        }

        $base = preg_quote(
            trim(
                TFSC_COMBO_BASE,
                '/'
            ),
            '/'
        );

        /*
         * Pagination MOET vóór de algemene
         * combo rewrite staan.
         */
        add_rewrite_rule(
            '^' . $base . '/(.+?)/page/([0-9]+)/?$',
            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]'
            . '&paged=$matches[2]',
            'top'
        );

        /*
         * Normaal combo archive.
         */
        add_rewrite_rule(
            '^' . $base . '/(.+?)/?$',
            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]',
            'top'
        );
    },
    99
);


/* ============================================================
 * PURE COMBO PATH PARSER
 * ============================================================ */

/**
 * Parse een combo pad zonder afhankelijk te zijn
 * van get_query_var().
 *
 * Hierdoor kan dezelfde parser al tijdens
 * parse_request gebruikt worden om S&F values klaar
 * te zetten.
 */
function tfsc_parse_combo_path( $path ) {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }

    $path = trim(
        (string) $path,
        '/'
    );

    if ( '' === $path ) {
        return false;
    }

    $segments = array_values(
        array_filter(
            explode(
                '/',
                $path
            ),
            'strlen'
        )
    );

    if ( count( $segments ) < 2 ) {
        return false;
    }

    $allowed =
        tfsc_get_allowed_combo_taxonomies();

    if ( ! $allowed ) {
        return false;
    }

    $items = [];
    $count = count( $segments );
    $i     = 0;

    while ( $i < $count ) {

        $taxonomy = sanitize_key(
            $segments[ $i++ ]
        );

        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }

        $term_segments = [];

        while ( $i < $count ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[ $i ]
                );

            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }

            $term_segments[] =
                $segments[ $i++ ];
        }

        if ( ! $term_segments ) {
            return false;
        }

        $resolved =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );

        if ( ! $resolved ) {
            return false;
        }

        $items[] = [
            'taxonomy' => $taxonomy,
            'term'     => $resolved['term'],
            'path'     => $resolved['path'],
        ];
    }

    return $items ?: false;
}


/* ============================================================
 * CURRENT COMBO
 * ============================================================ */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;

    if ( $resolved ) {
        return $cache;
    }

    $resolved = true;

    if (
        ! tfsc_combo_core_ready() ||
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }

    $cache = tfsc_parse_combo_path(
        get_query_var(
            'tfsc_combo_path'
        )
    );

    return $cache;
}


/* ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================ */

function tfsc_group_combo_items(
    array $combo,
    $property = 'term_id'
) {

    $grouped = [];

    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $term = $item['term'];

        switch ( $property ) {

            case 'name':
                $value = trim(
                    $term->name
                );
                break;

            case 'slug':
                $value = trim(
                    $term->slug
                );
                break;

            default:
                $value =
                    (int) $term->term_id;
                break;
        }

        if (
            '' === $value ||
            0 === $value
        ) {
            continue;
        }

        $key = is_int( $value )
            ? $value
            : (string) $value;

        $grouped[
            $item['taxonomy']
        ][ $key ] = $value;
    }

    foreach (
        $grouped
        as $taxonomy => $values
    ) {

        $grouped[ $taxonomy ] =
            array_values(
                $values
            );
    }

    return $grouped;
}


function tfsc_group_combo_terms(
    $property = 'term_id'
) {

    $combo =
        tfsc_get_combo_archive();

    if ( ! is_array( $combo ) ) {
        return [];
    }

    return tfsc_group_combo_items(
        $combo,
        $property
    );
}


/* ============================================================
 * LEGACY / CONSUMER TAX QUERY BUILDER
 * ============================================================ */

/**
 * Deze functie blijft bestaan voor eventuele andere
 * TFSC consumers.
 *
 * De S&F resultatenquery gebruikt hem NIET meer.
 */
function tfsc_build_combo_tax_query() {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }

    $groups =
        tfsc_group_combo_terms();

    if ( ! $groups ) {
        return false;
    }

    $status =
        tfsc_combo_status_clause();

    if ( ! $status ) {
        return false;
    }

    $tax_query = [
        'relation' => 'AND',
        $status,
    ];

    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        if ( ! $term_ids ) {
            continue;
        }

        $object =
            get_taxonomy(
                $taxonomy
            );

        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );

        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                array_map(
                    'intval',
                    $term_ids
                ),

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method &&
                    $object &&
                    $object->hierarchical
                ),
        ];
    }

    return $tax_query;
}


/* ============================================================
 * SEARCH & FILTER FIELD HELPERS
 * ============================================================ */

/**
 * Zoek alle fields van S&F Query 1.
 */
function tfsc_sf_get_query_fields() {

    static $fields = null;

    if ( null !== $fields ) {
        return $fields;
    }

    $fields = [];

    if (
        ! class_exists(
            '\Search_Filter\Queries\Query'
        )
    ) {
        return $fields;
    }

    $query =
        \Search_Filter\Queries\Query::find(
            [
                'id' =>
                    (int)
                    TFSC_SEARCH_FILTER_QUERY_ID,
            ]
        );

    if (
        is_wp_error( $query ) ||
        ! is_object( $query ) ||
        ! method_exists(
            $query,
            'get_fields'
        )
    ) {
        return $fields;
    }

    $query_fields =
        $query->get_fields();

    if (
        ! is_array( $query_fields ) &&
        ! $query_fields instanceof Traversable
    ) {
        return $fields;
    }

    foreach (
        $query_fields
        as $field
    ) {

        if ( is_object( $field ) ) {
            $fields[] = $field;
        }
    }

    return $fields;
}


/**
 * Zoek het S&F taxonomy field.
 */
function tfsc_sf_get_taxonomy_field(
    $taxonomy
) {

    foreach (
        tfsc_sf_get_query_fields()
        as $field
    ) {

        if (
            ! method_exists(
                $field,
                'get_attribute'
            )
        ) {
            continue;
        }

        if (
            'taxonomy'
            !==
            (string)
            $field->get_attribute(
                'dataType'
            )
        ) {
            continue;
        }

        if (
            $taxonomy
            !==
            (string)
            $field->get_attribute(
                'dataTaxonomy'
            )
        ) {
            continue;
        }

        return $field;
    }

    return false;
}


/**
 * URL name van het betreffende S&F field.
 *
 * Bijvoorbeeld:
 *
 * taxonomy  = functienaam
 * dataUrlName = functienaam
 *
 * Parameter:
 * _functienaam
 */
function tfsc_sf_get_taxonomy_url_name(
    $taxonomy
) {

    $field =
        tfsc_sf_get_taxonomy_field(
            $taxonomy
        );

    if (
        $field &&
        method_exists(
            $field,
            'get_attribute'
        )
    ) {

        $url_name = sanitize_key(
            (string)
            $field->get_attribute(
                'dataUrlName'
            )
        );

        if ( '' !== $url_name ) {
            return $url_name;
        }
    }

    /*
     * Fallback:
     * bij jouw huidige fields is dataUrlName
     * gelijk aan de taxonomy slug.
     */
    return sanitize_key(
        $taxonomy
    );
}


/* ============================================================
 * VIRTUELE SEARCH & FILTER FIELD VALUES
 * ============================================================ */

/**
 * Markering voor andere TFSC-code/debug.
 */
$GLOBALS['tfsc_sf_virtual_combo_values'] = [];


/**
 * Combo-terms als echte S&F requestwaarden aanbieden.
 *
 * BELANGRIJK:
 *
 * De browser-URL wordt NIET aangepast.
 * $_SERVER['QUERY_STRING'] blijft de werkelijke URL.
 *
 * Alleen gedurende deze WordPress request krijgt
 * Search & Filter dezelfde waarden alsof het field
 * normaal geselecteerd was.
 *
 * Daardoor kan S&F zelf:
 * - Match Any
 * - Match All
 * - counts
 * - hideEmpty
 * - indexer
 * correct uitvoeren.
 */
add_action(
    'parse_request',
    function( $wp ) {

        if (
            ! tfsc_combo_core_ready() ||
            is_admin() ||
            ! isset(
                $wp->query_vars[
                    'tfsc_combo_archive'
                ]
            ) ||
            ! $wp->query_vars[
                'tfsc_combo_archive'
            ]
        ) {
            return;
        }

        $path =
            $wp->query_vars[
                'tfsc_combo_path'
            ]
            ?? '';

        $combo =
            tfsc_parse_combo_path(
                $path
            );

        if ( ! is_array( $combo ) ) {
            return;
        }

        $groups =
            tfsc_group_combo_items(
                $combo,
                'slug'
            );

        if ( ! $groups ) {
            return;
        }

        foreach (
            $groups
            as $taxonomy => $combo_values
        ) {

            if ( ! $combo_values ) {
                continue;
            }

            $url_name =
                tfsc_sf_get_taxonomy_url_name(
                    $taxonomy
                );

            if ( '' === $url_name ) {
                continue;
            }

            $parameter =
                TFSC_SEARCH_FILTER_URL_PREFIX
                .
                $url_name;

            /*
             * Bestaande echte S&F URL-waarden
             * eventueel behouden en combineren.
             */
            $existing = [];

            if (
                isset(
                    $_GET[
                        $parameter
                    ]
                ) &&
                ! is_array(
                    $_GET[
                        $parameter
                    ]
                )
            ) {

                $existing =
                    array_filter(
                        array_map(
                            'sanitize_title',
                            explode(
                                ',',
                                wp_unslash(
                                    $_GET[
                                        $parameter
                                    ]
                                )
                            )
                        )
                    );
            }

            $values =
                array_values(
                    array_unique(
                        array_merge(
                            $combo_values,
                            $existing
                        )
                    )
                );

            if ( ! $values ) {
                continue;
            }

            $value =
                implode(
                    ',',
                    $values
                );

            /*
             * Alleen intern voor deze PHP request.
             */
            $_GET[
                $parameter
            ] = $value;

            $_REQUEST[
                $parameter
            ] = $value;

            $GLOBALS[
                'tfsc_sf_virtual_combo_values'
            ][ $parameter ] = $values;
        }
    },
    1
);


