        $tax_query['relation'] =
            'AND';

        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );

        $query->set(
            'post_status',
            'publish'
        );

        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
