/* ============================================================
 * SEARCH & FILTER FRONTEND
 * ============================================================ */

/**
 * Omdat combo-values server-side al echte S&F field
 * values zijn, hoeft JavaScript ze niet meer kunstmatig
 * via setValues() te injecteren.
 *
 * We houden alleen de redirect-logica:
 * zodra iemand interactief gaat filteren wordt de
 * normale S&F filter-URL gebruikt.
 */
add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_combo_core_ready() ||
            ! tfsc_is_vacancy_seo_landing()
        ) {
            return;
        }

        ?>
        <script>
        (() => {

            const ID =
                <?php echo (int) TFSC_SEARCH_FILTER_QUERY_ID; ?>;

            let attached = false;
            let redirecting = false;


            const list = items => {

                if (!items) {
                    return [];
                }

                if (items instanceof Map) {
                    return [...items.values()];
                }

                if (Array.isArray(items)) {
                    return items;
                }

                return typeof items === 'object'
                    ? Object.values(items)
                    : [];
            };


            const resultUrl = query => {

                if (
                    !query ||
                    typeof query.getUrl !== 'function' ||
                    typeof query.getFields !== 'function'
                ) {
                    return null;
                }

                const base =
                    query.getUrl();

                if (!base) {
                    return null;
                }

                const prefix =
                    window.searchAndFilterData
                        ?.urlPrefix || '_';

                const parts = [];

                list(
                    query.getFields()
                ).forEach(field => {

                    if (
                        !field ||
                        typeof field.getUrlName !== 'function' ||
                        typeof field.getUrlValues !== 'function'
                    ) {
                        return;
                    }

                    const name =
                        field.getUrlName();

                    let values =
                        field.getUrlValues();

                    if (!name) {
                        return;
                    }

                    if (
                        values !== null &&
                        values !== undefined &&
                        !Array.isArray(values)
                    ) {
                        values = [ values ];
                    }

                    values =
                        Array.isArray(values)
                            ? values.filter(
                                value =>
                                    value !== null &&
                                    value !== undefined &&
                                    String(value) !== ''
                            )
                            : [];

                    if (!values.length) {
                        return;
                    }

                    parts.push(
                        encodeURIComponent(
                            prefix + name
                        )
                        +
                        '='
                        +
                        values.map(
                            value =>
                                encodeURIComponent(
                                    String(value)
                                )
                        ).join(',')
                    );
                });

                if (
                    typeof query.getActiveUrlArg === 'function'
                ) {

                    const active =
                        query.getActiveUrlArg();

                    if (active) {
                        parts.push(
                            encodeURIComponent(
                                active
                            )
                        );
                    }
                }

                const clean =
                    String(base)
                        .split('#')[0]
                        .split('?')[0];

                return parts.length
                    ? clean + '?' + parts.join('&')
                    : clean;
            };


            const attach = () => {

                if (attached) {
                    return true;
                }

                const queries =
                    window.searchAndFilter
                        ?.frontend
                        ?.queries;

                if (
                    !queries ||
                    typeof queries.get !== 'function'
                ) {
                    return false;
                }

                const query =
                    queries.get(ID);

                if (
                    !query ||
                    typeof query.on !== 'function'
                ) {
                    return false;
                }

                attached = true;

                query.on(
                    'get-results/start',
                    () => {

                        if (redirecting) {
                            return;
                        }

                        const url =
                            resultUrl(query);

                        if (!url) {
                            return;
                        }

                        redirecting = true;

                        window.location.href =
                            url;
                    }
                );

                return true;
            };


            const start = () => {

                [
                    100,
                    300,
                    750,
                    1500
                ].forEach(
                    timeout =>
                        setTimeout(
                            attach,
                            timeout
                        )
                );
            };


            document.addEventListener(
                'search-filter/mount',
                () => {

                    [
                        50,
                        200,
                        500
                    ].forEach(
                        timeout =>
                            setTimeout(
                                attach,
                                timeout
                            )
                    );
                }
            );


            if (
                document.readyState === 'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    start
                );

            } else {

                start();
            }


            window.addEventListener(
                'pageshow',
                event => {

                    if (event.persisted) {
                        window.location.reload();
                    }
                }
            );

        })();
        </script>
        <?php
    },
    90
);


