/* ============================================================
 * DEPENDENCY CHECKS
 * ============================================================ */

function tfsc_combo_seo_dependencies_ready() {

    return (
        defined( 'TFSC_VACANCY_POST_TYPE' ) &&
        defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) &&
        function_exists( 'tfsc_is_combo_archive' ) &&
        function_exists( 'tfsc_get_combo_archive' ) &&
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        function_exists( 'tfsc_build_combo_url' ) &&
        function_exists( 'tfsc_build_combo_url_for_term' )
    );
}


function tfsc_combo_seo_index_dependencies_ready() {

    return defined(
        'TFSC_COMBO_FUNCTION_TAXONOMY'
    );
}


/* ============================================================
 * COMBO STATUS + ITEMS
 * ============================================================ */

function tfsc_combo_seo_is_active() {

    return (
        ! is_admin() &&
        tfsc_combo_seo_dependencies_ready() &&
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    );
}


function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];

    if ( $resolved ) {
        return $items;
    }

    $resolved = true;

    if ( ! tfsc_combo_seo_is_active() ) {
        return [];
    }

    $combo =
        tfsc_get_combo_archive();

    if (
        function_exists(
            'tfsc_urlcore_normalize_combo'
        )
    ) {

        $combo =
            tfsc_urlcore_normalize_combo(
                $combo
            );
    }

    foreach ( (array) $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }

        $name = trim(
            wp_strip_all_tags(
                $item['term']->name
            )
        );

        if ( '' === $name ) {
            continue;
        }

        $items[] = [
            'taxonomy' =>
                (string) $item['taxonomy'],

            'term_id' =>
                (int) $item['term']->term_id,

            'slug' =>
                (string) $item['term']->slug,

            'name' =>
                $name,
        ];
    }

    return $items;
}


/* ============================================================
 * INDEXERINGSLOGICA
 * ============================================================ */

function tfsc_combo_count_taxonomies(
    $combo = null
) {

    if ( null === $combo ) {

        $combo =
            tfsc_combo_seo_is_active()
                ? tfsc_get_combo_archive()
                : [];
    }

    $taxonomies = [];

    foreach ( (array) $combo as $item ) {

        if ( empty( $item['taxonomy'] ) ) {
            continue;
        }

        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );

        if ( $taxonomy ) {
            $taxonomies[
                $taxonomy
            ] = true;
        }
    }

    return count(
        $taxonomies
    );
}


function tfsc_combo_has_function_name(
    $combo = null
) {

    if (
        ! defined(
            'TFSC_COMBO_FUNCTION_TAXONOMY'
        )
    ) {
        return false;
    }

    if ( null === $combo ) {

        $combo =
            tfsc_combo_seo_is_active()
                ? tfsc_get_combo_archive()
                : [];
    }

    foreach ( (array) $combo as $item ) {

        if (
            ! empty( $item['taxonomy'] ) &&
            TFSC_COMBO_FUNCTION_TAXONOMY ===
                $item['taxonomy']
        ) {
            return true;
        }
    }

    return false;
}


function tfsc_combo_get_current_result_count() {

    global $wp_query;

    return (
        tfsc_combo_seo_is_active() &&
        $wp_query instanceof WP_Query
    )
        ? max(
            0,
            (int) $wp_query->found_posts
        )
        : 0;
}


function tfsc_combo_get_index_status(
    $combo = null
) {

    $frontend =
        null === $combo;

    if ( $frontend ) {

        if (
            ! tfsc_combo_seo_is_active()
        ) {
            return [
                'index'      => false,
                'reason'     => 'not_combo',
                'results'    => 0,
                'taxonomies' => 0,
            ];
        }

        $combo =
            tfsc_get_combo_archive();

    } elseif (
        ! tfsc_combo_seo_index_dependencies_ready()
    ) {

        return [
            'index'      => false,
            'reason'     => 'dependencies_missing',
            'results'    => null,
            'taxonomies' => 0,
        ];
    }


    if (
        ! is_array( $combo ) ||
        ! $combo
    ) {

        return [
            'index'      => false,
            'reason'     => 'invalid_combo',
            'results'    => 0,
            'taxonomies' => 0,
        ];
    }


    $count =
        tfsc_combo_count_taxonomies(
            $combo
        );


    if (
        $count >
        TFSC_COMBO_SEO_MAX_TAXONOMIES
    ) {

        return [
            'index'      => false,
            'reason'     => 'too_many_taxonomies',
            'results'    => null,
            'taxonomies' => $count,
        ];
    }


    if (
        ! tfsc_combo_has_function_name(
            $combo
        )
    ) {

        return [
            'index'      => false,
            'reason'     => 'no_function_name',
            'results'    => null,
            'taxonomies' => $count,
        ];
    }


    if ( $frontend ) {

        $results =
            tfsc_combo_get_current_result_count();

        $valid =
            $results > 0;

        return [
            'index' =>
                $valid,

            'reason' =>
                $valid
                    ? 'valid_function_combo'
                    : 'no_results',

            'results' =>
                $results,

            'taxonomies' =>
                $count,
        ];
    }


    return [
        'index'      => true,
        'reason'     => 'valid_sitemap_function_combo',
        'results'    => null,
        'taxonomies' => $count,
    ];
}


function tfsc_combo_should_index(
    $combo = null
) {

    $status =
        tfsc_combo_get_index_status(
            $combo
        );

    return ! empty(
        $status['index']
    );
}


/* ============================================================
 * COMBO TITLE + DESCRIPTION
 * ============================================================ */

function tfsc_combo_seo_build_title() {

    if (
        ! defined(
            'TFSC_COMBO_FUNCTION_TAXONOMY'
        )
    ) {
        return '';
    }

    $functions = [];
    $others    = [];

    foreach (
        tfsc_combo_seo_get_items()
        as $item
    ) {

        if (
            TFSC_COMBO_FUNCTION_TAXONOMY ===
                $item['taxonomy']
        ) {

            $functions[
                $item['name']
            ] = $item['name'];

        } else {

            $others[
                $item['name']
            ] = $item['name'];
        }
    }

    $functions =
        array_values(
            $functions
        );

    $others =
        array_values(
            $others
        );


    if ( $functions ) {

        $title =
            implode(
                ' ',
                $functions
            )
            .
            ' vacatures';

        if ( $others ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $others
                );
        }

        return trim(
            $title
        );
    }


    return $others
        ? 'Field Service vacatures '
            . implode(
                ' ',
                $others
            )
        : '';
}


function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();

    return $title
        ? sprintf(
            '%s bij %s.',
            $title,
            TFSC_COMBO_SEO_BRAND
        )
        : '';
}


/* ============================================================
 * COMBO SEO OBJECT
 * ============================================================ */

function tfsc_combo_seo_build_canonical() {

    if (
        ! tfsc_combo_seo_is_active() ||
        ! function_exists(
            'tfsc_build_combo_url'
        )
    ) {
        return '';
    }

    return tfsc_build_combo_url(
        tfsc_get_combo_archive(),
        max(
            1,
            (int) get_query_var(
                'paged'
            )
        )
    );
}


function tfsc_get_combo_seo() {

    static $resolved = false;
    static $seo      = false;

    if ( $resolved ) {
        return $seo;
    }

    $resolved = true;

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return false;
    }

    $title =
        tfsc_combo_seo_build_title();

    if ( ! $title ) {
        return false;
    }

    $status =
        tfsc_combo_get_index_status();

    $seo = [
        'title' =>
            $title,

        'description' =>
            tfsc_combo_seo_build_description(),

        'canonical' =>
            tfsc_combo_seo_build_canonical(),

        'index' =>
            ! empty(
                $status['index']
            ),

        'index_reason' =>
            $status['reason'],

        'results' =>
            $status['results'],

        'taxonomies' =>
            $status['taxonomies'],
    ];

    return $seo;
}


/* ============================================================
 * NATIVE VACATURE TAXONOMY CANONICAL
 * ============================================================ */

function tfsc_native_canonical_is_target() {

    if (
        is_admin() ||
        ! tfsc_combo_seo_dependencies_ready() ||
        ! is_tax()
    ) {
        return false;
    }

    if (
        tfsc_is_combo_archive()
    ) {
        return false;
    }

    $term =
        get_queried_object();

    return (
        $term instanceof WP_Term &&
        tfsc_urlcore_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


function tfsc_native_canonical_build_url() {

    if (
        ! tfsc_native_canonical_is_target() ||
        ! function_exists(
            'tfsc_build_combo_url_for_term'
        )
    ) {
        return '';
    }

    return tfsc_build_combo_url_for_term(
        get_queried_object(),
        null,
        max(
            1,
            (int) get_query_var(
                'paged'
            )
        )
    );
}


/* ============================================================
 * ECHTE URL QUERY PARAMETERS
 * ============================================================ */

/**
 * Geeft alleen query parameters terug die werkelijk
 * in de browser/request-URL stonden.
 *
 * Base 5.5 kan later virtueel S&F-values toevoegen aan:
 *
 * $_GET
 * $_REQUEST
 *
 * Die mogen SEO-technisch NIET worden aangezien
 * voor een echte filter-URL.
 */
function tfsc_seo_get_real_query_args() {

    static $resolved = false;
    static $args     = [];

    if ( $resolved ) {
        return $args;
    }

    $resolved = true;

    $query_string =
        isset(
            $_SERVER['QUERY_STRING']
        )
            ? (string)
                wp_unslash(
                    $_SERVER['QUERY_STRING']
                )
            : '';

    if ( '' === $query_string ) {
        return [];
    }

    parse_str(
        $query_string,
        $parsed
    );

    $args =
        is_array( $parsed )
            ? $parsed
            : [];

    return $args;
}


/* ============================================================
 * SEARCH & FILTER SEO
 * ============================================================ */

function tfsc_vacancy_filter_seo_is_active() {

    if (
        is_admin() ||
        ! defined(
            'TFSC_VACANCY_POST_TYPE'
        )
    ) {
        return false;
    }


    /*
     * Combo archive is altijd zijn eigen SEO landing.
     *
     * Ook wanneer Base intern virtuele S&F-values
     * heeft geïnjecteerd.
     */
    if (
        function_exists(
            'tfsc_is_combo_archive'
        ) &&
        tfsc_is_combo_archive()
    ) {
        return false;
    }


    if (
        ! is_post_type_archive(
            TFSC_VACANCY_POST_TYPE
        )
    ) {
        return false;
    }


    $real_args =
        tfsc_seo_get_real_query_args();


    if ( ! $real_args ) {
        return false;
    }


    foreach (
        array_keys(
            $real_args
        )
        as $key
    ) {

        $key =
            (string) $key;

        /*
         * S&F parameters gebruiken bij jouw setup
         * een underscore-prefix.
         */
        if (
            isset( $key[0] ) &&
            '_' === $key[0]
        ) {
            return true;
        }
    }


    return false;
}


function tfsc_vacancy_filter_clean_canonical() {

    if (
        ! defined(
            'TFSC_VACANCY_POST_TYPE'
        )
    ) {
        return '';
    }

    $url =
        get_post_type_archive_link(
            TFSC_VACANCY_POST_TYPE
        );

    return $url
        ? trailingslashit(
            $url
        )
        : '';
}


