) {

    $seo =
        tfsc_get_combo_seo();

    return ! empty(
        $seo['title']
    )
        ? $seo['title']
        : $title;
}


function tfsc_combo_rankmath_description(
    $description
) {

    $seo =
        tfsc_get_combo_seo();

    return ! empty(
        $seo['description']
    )
        ? $seo['description']
        : $description;
}


function tfsc_combo_rankmath_canonical(
    $canonical
) {

    $seo =
        tfsc_get_combo_seo();

    return ! empty(
        $seo['canonical']
    )
        ? $seo['canonical']
        : $canonical;
}


function tfsc_combo_rankmath_robots(
    $robots
) {

    $seo =
        tfsc_get_combo_seo();

    if ( ! is_array( $seo ) ) {
        return $robots;
    }

    if ( ! is_array( $robots ) ) {
        $robots = [];
    }

    $robots['index'] =
        ! empty(
            $seo['index']
        )
            ? 'index'
            : 'noindex';

    $robots['follow'] =
        'follow';

    return $robots;
}


/* ============================================================
 * RANK MATH - NATIVE
 * ============================================================ */

function tfsc_native_rankmath_canonical(
    $canonical
) {

    $url =
        tfsc_native_canonical_build_url();

    return $url
        ?: $canonical;
}


