 * RANK MATH - SEARCH & FILTER
 * ============================================================ */

function tfsc_vacancy_filter_rankmath_canonical(
    $canonical
) {

    $clean =
        tfsc_vacancy_filter_clean_canonical();

    return $clean
        ?: $canonical;
}


function tfsc_vacancy_filter_rankmath_robots(
    $robots
) {

    if ( ! is_array( $robots ) ) {
        $robots = [];
    }

    $robots['index'] =
        'noindex';

    $robots['follow'] =
        'follow';

    return $robots;
}


/**
 * Rank Math gebruikt dezelfde clean canonical
 * intern voor OG/schema.
 *
 * Op noindex filterpagina's kan Rank Math de
 * HTML canonical weglaten; daarom outputten we
 * hem aanvullend zelf.
 */
function tfsc_vacancy_filter_output_canonical() {

    if (
        ! tfsc_vacancy_filter_seo_is_active()
    ) {
        return;
    }

    $canonical =
        tfsc_vacancy_filter_clean_canonical();

    if ( ! $canonical ) {
        return;
    }

    printf(
        "<link rel=\"canonical\" href=\"%s\" />\n",
        esc_url(
            $canonical
        )
    );
}


