/* ============================================================
 * SEARCH & FILTER SERVER-SIDE COMBO CONTEXT
 * ============================================================ */

/**
 * Dit is het belangrijke koppelstuk.
 *
 * Search & Filter maakt de daadwerkelijke Elementor-query.
 * Daar voegen wij de combo-taxonomies aan toe.
 *
 * Voorbeeld:
 *
 * S&F:
 *
 * vac_status NOT IN gesloten-oud, ingevuld
 *
 * +
 *
 * TFSC combo:
 *
 * functienaam = Field Service Engineer
 *
 * =
 *
 * één uiteindelijke S&F/Elementor query.
 */
add_filter(
    'search-filter/query/query_args',
    function(
        $query_args,
        $search_filter_query
    ) {

        if (
            ! tfsc_combo_core_ready() ||
            ! tfsc_is_combo_archive() ||
            ! is_object(
                $search_filter_query
            ) ||
            ! method_exists(
                $search_filter_query,
                'get_id'
            )
        ) {
            return $query_args;
        }


        /*
         * Alleen vacature Query 1.
         */
        if (
            (int)
            $search_filter_query->get_id()
            !==
            (int)
            TFSC_SEARCH_FILTER_QUERY_ID
        ) {
            return $query_args;
        }


        $combo_tax_query =
            tfsc_build_combo_tax_query();


        if ( ! $combo_tax_query ) {
            return $query_args;
        }


        /*
         * Bestaande Search & Filter tax_query behouden.
         */
        $tax_query =
            isset(
                $query_args['tax_query']
            ) &&
            is_array(
                $query_args['tax_query']
            )
                ? $query_args['tax_query']
                : [];


        /*
         * Verschillende taxonomies moeten samen AND zijn.
         */
        $tax_query['relation'] =
            'AND';


        foreach (
            $combo_tax_query
            as $key => $combo_clause
        ) {

            if (
                'relation' === $key ||
                ! is_array(
                    $combo_clause
                ) ||
                empty(
                    $combo_clause['taxonomy']
                )
            ) {
                continue;
            }


            /*
             * Voorkom exact dubbele clauses.
             *
             * Dit is alleen deduplicatie.
             * Er wordt hier bewust NIET geprobeerd
             * S&F selections met combo clauses te mergen.
             */
            $already_exists =
                false;


            foreach (
                $tax_query
                as $existing_key => $existing_clause
            ) {

                if (
                    'relation' === $existing_key ||
                    ! is_array(
                        $existing_clause
                    ) ||
                    empty(
                        $existing_clause['taxonomy']
                    )
                ) {
                    continue;
                }


                if (
                    (string)
                    $existing_clause['taxonomy']
                    !==
                    (string)
                    $combo_clause['taxonomy']
                ) {
                    continue;
                }


                $existing_field =
                    (string) (
                        $existing_clause['field']
                        ?? 'term_id'
                    );


                $combo_field =
                    (string) (
                        $combo_clause['field']
                        ?? 'term_id'
                    );


                if (
                    $existing_field !==
                    $combo_field
                ) {
                    continue;
                }


                $existing_operator =
                    strtoupper(
                        (string) (
                            $existing_clause['operator']
                            ?? 'IN'
                        )
                    );


                $combo_operator =
                    strtoupper(
                        (string) (
                            $combo_clause['operator']
                            ?? 'IN'
                        )
                    );


                if (
                    $existing_operator !==
                    $combo_operator
                ) {
                    continue;
                }


                $existing_terms =
                    array_values(
                        array_unique(
                            array_map(
                                'strval',
                                (array) (
                                    $existing_clause['terms']
                                    ?? []
                                )
                            )
                        )
                    );


                $combo_terms =
                    array_values(
                        array_unique(
                            array_map(
                                'strval',
                                (array) (
                                    $combo_clause['terms']
                                    ?? []
                                )
                            )
                        )
                    );


                sort(
                    $existing_terms,
                    SORT_STRING
                );


                sort(
                    $combo_terms,
                    SORT_STRING
                );


                if (
                    $existing_terms ===
                    $combo_terms
                ) {

                    $already_exists =
                        true;

                    break;
                }
            }


            if ( ! $already_exists ) {

                $tax_query[] =
                    $combo_clause;
            }
        }


        $query_args['tax_query'] =
            $tax_query;


        return $query_args;
    },
    20,
    2
);


/* ============================================================
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * ============================================================ */

/**
 * Native taxonomy archives staan los van de virtuele
 * combo/S&F query.
 *
 * Hier behouden we de bestaande OPEN-statuslogica.
 */
add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            ! tfsc_combo_core_ready() ||
            is_admin() ||
            ! $query->is_main_query() ||
            tfsc_is_combo_archive() ||
            ! $query->is_tax()
        ) {
            return;
        }


        $term =
            $query->get_queried_object();


        if (
            ! $term instanceof WP_Term ||
            ! tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {
            return;
        }


        $status =
            tfsc_combo_status_clause();


        if ( ! $status ) {
            return;
        }


        $tax_query =
            $query->get(
                'tax_query'
            );


        if (
            ! is_array(
                $tax_query
            )
        ) {
            $tax_query = [];
        }


        $tax_query[] =
            $status;


        $tax_query['relation'] =
            'AND';


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
);


