add_action(
    'elementor/theme/register_conditions',
    function( $manager ) {

        if (
            ! tfsc_combo_core_ready()
        ) {
            return;
        }


        $base =
            '\ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base';


        if (
            ! class_exists(
                $base
            )
        ) {
            return;
        }


        /*
         * Virtuele combo archives.
         */
        if (
            ! class_exists(
                'TFSC_Combined_Vacancy_Archive_Condition',
                false
            )
        ) {

            class TFSC_Combined_Vacancy_Archive_Condition
                extends
                \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type() {
                    return 'archive';
                }


                public static function get_priority() {
                    return 40;
                }


                public function get_name() {
                    return 'tfsc_combined_vacancy_archive';
                }


                public function get_label() {
                    return 'TFSC Combined Vacancy Archives';
                }


                public function check( $args ) {

                    return (
                        tfsc_is_combo_archive() &&
                        false !==
                            tfsc_get_combo_archive()
                    );
                }
            }
        }


        /*
         * Native vacature taxonomy archives.
         */
        if (
            ! class_exists(
                'TFSC_Vacancy_Taxonomy_Term_Archive_Condition',
                false
            )
        ) {

            class TFSC_Vacancy_Taxonomy_Term_Archive_Condition
                extends
                \ElementorPro\Modules\ThemeBuilder\Conditions\Condition_Base {

                public static function get_type() {
                    return 'archive';
                }


                public static function get_priority() {
                    return 41;
                }


                public function get_name() {
                    return 'tfsc_vacancy_taxonomy_term_archives';
                }


                public function get_label() {
                    return 'TFSC Vacancy Taxonomy Term Archives';
                }


                public function check( $args ) {

                    if ( ! is_tax() ) {
                        return false;
                    }


                    $term =
                        get_queried_object();


                    return (
                        $term instanceof WP_Term &&
                        tfsc_combo_taxonomy_allowed(
                            $term->taxonomy
                        )
                    );
                }
            }
        }


        $archive =
            $manager->get_condition(
                'archive'
            );


        if ( ! $archive ) {
            return;
        }


        $archive->register_sub_condition(
            new TFSC_Combined_Vacancy_Archive_Condition()
        );


        $archive->register_sub_condition(
            new TFSC_Vacancy_Taxonomy_Term_Archive_Condition()
        );
    }
);


/* ============================================================
 * HEADING HELPER
 * ============================================================ */

function tfsc_combo_heading_html(
    $rows
) {

    $rows =
        array_values(
            array_filter(
                (array) $rows,
                'strlen'
            )
        );


    if ( ! $rows ) {
        return '';
    }


    $html =
        '<span class="tfsc-heading">';


    foreach (
        $rows
        as $index => $row
    ) {

        $html .=
            sprintf(
                '<span class="%s">%s</span>',
                0 === $index
                    ? 'tfsc-heading__main'
                    : 'tfsc-heading__row',
                esc_html(
                    $row
                )
            );
    }


    return $html
        .
        '</span>';
}


/* ============================================================
 * [combo_heading]
 * ============================================================ */

add_shortcode(
    'combo_heading',
    function() {

        if (
            ! tfsc_combo_core_ready()
        ) {
            return '';
        }


        /*
         * Combo archive.
         */
        if (
            tfsc_is_combo_archive()
        ) {

            $groups =
                tfsc_group_combo_terms(
                    'name'
                );


            if ( ! $groups ) {
                return '';
            }


            $rows =
                [];


            $functions =
                $groups[
                    TFSC_COMBO_FUNCTION_TAXONOMY
                ]
                ??
                [];


            if ( $functions ) {

                if (
                    1 ===
                    count(
                        $functions
                    )
                ) {

                    $rows[] =
                        $functions[0]
                        .
                        ' vacatures';

                } else {

                    $rows[] =
                        'Vacatures';


                    $rows[] =
                        implode(
                            ', ',
                            $functions
                        );
                }


                unset(
                    $groups[
                        TFSC_COMBO_FUNCTION_TAXONOMY
                    ]
                );

            } else {

                $rows[] =
                    'Vacatures';
            }


            foreach (
                $groups
                as $names
            ) {

                if ( $names ) {

                    $rows[] =
                        implode(
                            ', ',
                            $names
                        );
                }
            }


            return tfsc_combo_heading_html(
                $rows
            );
        }


        /*
         * Native taxonomy archive.
         */
        $term =
            get_queried_object();


        if (
            $term instanceof WP_Term &&
            tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {

            $title =
                get_term_meta(
                    $term->term_id,
                    'pods_archive_title',
                    true
                );


            $title =
                is_string(
                    $title
                )
                    ? trim(
                        wp_strip_all_tags(
                            $title
                        )
                    )
                    : '';


            if (
                '' === $title
            ) {

                $title =
                    trim(
                        $term->name
                    );


                if (
                    '' === $title
                ) {
                    return '';
                }


                $title .=
                    ' vacatures';
            }


            return tfsc_combo_heading_html(
                [ $title ]
            );
        }


        /*
         * Hoofd vacaturearchive.
         */
        return is_post_type_archive(
            TFSC_VACANCY_POST_TYPE
        )
            ? tfsc_combo_heading_html(
                [ 'Vacatures' ]
            )
            : '';
    }
);


/* ============================================================
 * [combo_term taxonomy="..."]
 * ============================================================ */

add_shortcode(
    'combo_term',
    function( $atts ) {

        if (
            ! tfsc_combo_core_ready()
        ) {
            return '';
        }


        $atts =
            shortcode_atts(
                [
                    'taxonomy'  => '',
                    'separator' => ' • ',
                ],
                $atts,
                'combo_term'
            );


        $taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );


        if ( ! $taxonomy ) {
            return '';
        }


        /*
         * Combo archive.
         */
        if (
            tfsc_is_combo_archive()
        ) {

            $groups =
                tfsc_group_combo_terms(
                    'name'
                );


            return empty(
                $groups[
                    $taxonomy
                ]
            )
                ? ''
                : esc_html(
                    implode(
                        (string)
                        $atts['separator'],
                        $groups[
                            $taxonomy
                        ]
                    )
                );
        }


        /*
         * Native taxonomy archive.
         */
        $term =
            get_queried_object();


        return (
            $term instanceof WP_Term &&
            $term->taxonomy ===
                $taxonomy &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        )
            ? esc_html(
                $term->name
            )
            : '';
    }
);

/**
 * TFSC - Volledig dynamische vacature-archieven
 * Version 5.3.1 - Stable S&F Integration / Pagination
 *
 * Vereist:
 * - TFSC - Combo Archive URLs
 *
 * Architectuur:
 * - URL Core bepaalt geldige taxonomies en combo-URL's.
 * - Deze Base parseert virtuele combo archives.
 * - Search & Filter Query 1 beheert:
 *   - posts_per_page
 *   - sortering
 *   - statusvoorwaarden
 *   - indexer
 *   - frontend filters
 *   - pagination
 * - TFSC voegt alleen de vaste combo-taxonomies toe aan
 *   de daadwerkelijke Search & Filter query.
 *
 * Regelt:
 * - /vacatures/... combo archives
 * - /page/N/ pagination
 * - verschillende taxonomies = AND
 * - meerdere combo-terms binnen taxonomy = OR
 * - kennisgebied = AND
 * - native vacature-taxonomy archives
 * - Search & Filter Pro v3 frontend sync
 * - Elementor archive conditions
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 */


/* ============================================================
 * CONFIG + CORE CHECK
 * ============================================================ */

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}


/**
 * Controleert of de centrale URL Core beschikbaar is.
 */
function tfsc_combo_core_ready() {

    return (
        defined( 'TFSC_COMBO_BASE' ) &&
        defined( 'TFSC_VACANCY_POST_TYPE' ) &&
        defined( 'TFSC_STATUS_TAXONOMY' ) &&
        defined( 'TFSC_OPEN_STATUS_SLUG' ) &&
        defined( 'TFSC_COMBO_FUNCTION_TAXONOMY' ) &&
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        function_exists( 'tfsc_urlcore_get_allowed_taxonomies' ) &&
        function_exists( 'tfsc_urlcore_resolve_term_path' )
    );
}


/* ============================================================
 * URL CORE COMPATIBILITEIT
 * ============================================================ */

function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    return (
        function_exists( 'tfsc_urlcore_taxonomy_allowed' ) &&
        tfsc_urlcore_taxonomy_allowed( $taxonomy )
    );
}


function tfsc_get_allowed_combo_taxonomies() {

    return function_exists( 'tfsc_urlcore_get_allowed_taxonomies' )
        ? tfsc_urlcore_get_allowed_taxonomies()
        : [];
}


function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    return function_exists( 'tfsc_urlcore_resolve_term_path' )
        ? tfsc_urlcore_resolve_term_path(
            $taxonomy,
            $segments
        )
        : false;
}


/* ============================================================
 * HELPERS
 * ============================================================ */

function tfsc_get_combo_taxonomy_match_method(
    $taxonomy
) {

    /*
     * Bestaande TFSC combo-logica:
     *
     * kennisgebied:
     * meerdere terms moeten allemaal aanwezig zijn.
     *
     * overige taxonomies:
     * meerdere terms zijn OR.
     */
    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


/**
 * Alleen gebruikt voor native taxonomy archives.
 *
 * Combo archives gebruiken de statusvoorwaarde uit
 * Search & Filter Query 1.
 */
function tfsc_combo_status_clause() {

    if (
        ! defined( 'TFSC_STATUS_TAXONOMY' ) ||
        ! defined( 'TFSC_OPEN_STATUS_SLUG' )
    ) {
        return [];
    }

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_is_combo_archive() {

    return (bool) get_query_var(
        'tfsc_combo_archive'
    );
}


function tfsc_is_vacancy_seo_landing() {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term =
        get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


/* ============================================================
 * QUERY VARS + REWRITES
 * ============================================================ */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';
        $vars[] = 'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        if (
            ! defined( 'TFSC_COMBO_BASE' ) ||
            '' === trim(
                (string) TFSC_COMBO_BASE
            )
        ) {
            return;
        }

        $base =
            preg_quote(
                trim(
                    TFSC_COMBO_BASE,
                    '/'
                ),
                '/'
            );


        /*
         * BELANGRIJK:
         *
         * pagination-regel moet vóór de algemene combo-regel.
         *
         * Anders wordt:
         *
         * /page/2/
         *
         * onderdeel van tfsc_combo_path.
         */
        add_rewrite_rule(
            '^' . $base . '/(.+?)/page/([0-9]+)/?$',
            'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]&paged=$matches[2]',
            'top'
        );


        add_rewrite_rule(
            '^' . $base . '/(.+?)/?$',
            'index.php?tfsc_combo_archive=1&tfsc_combo_path=$matches[1]',
            'top'
        );
    },
    99
);


/* ============================================================
 * COMBO PARSER
 * ============================================================ */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;

    if ( $resolved ) {
        return $cache;
    }

    $resolved = true;


    if (
        ! tfsc_combo_core_ready() ||
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    $path =
        trim(
            (string) get_query_var(
                'tfsc_combo_path'
            ),
            '/'
        );


    if ( '' === $path ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    $path
                ),
                'strlen'
            )
        );


    if (
        count( $segments ) < 2
    ) {
        return false;
    }


    $allowed =
        tfsc_get_allowed_combo_taxonomies();


    if ( ! $allowed ) {
        return false;
    }


    $items = [];
    $count = count( $segments );
    $i     = 0;


    while ( $i < $count ) {

        $taxonomy =
            sanitize_key(
                $segments[ $i++ ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }


        $term_segments = [];


        while ( $i < $count ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[ $i ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }


            $term_segments[] =
                $segments[ $i++ ];
        }


        if ( ! $term_segments ) {
            return false;
        }


        $resolved_path =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if ( ! $resolved_path ) {
            return false;
        }


        $items[] = [
            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved_path['term'],

            'path' =>
                $resolved_path['path'],
        ];
    }


    $cache =
        $items
            ? $items
            : false;


    return $cache;
}


/* ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================ */

function tfsc_group_combo_terms(
    $property = 'term_id'
) {

    $combo =
        tfsc_get_combo_archive();


    if ( ! is_array( $combo ) ) {
        return [];
    }


    $grouped = [];


    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }


        $term =
            $item['term'];


        switch ( $property ) {

            case 'name':

                $value =
                    trim(
                        $term->name
                    );

                break;


            case 'slug':

                $value =
                    $term->slug;

                break;


            default:

                $value =
                    (int) $term->term_id;

                break;
        }


        if (
            '' === $value ||
            0 === $value
        ) {
            continue;
        }


        $key =
            is_int( $value )
                ? $value
                : (string) $value;


        $grouped[
            $item['taxonomy']
        ][ $key ] = $value;
    }


    foreach (
        $grouped
        as $taxonomy => $values
    ) {

        $grouped[ $taxonomy ] =
            array_values(
                $values
            );
    }


    return $grouped;
}


/* ============================================================
 * COMBO TAX QUERY
 * ============================================================ */

/**
 * BELANGRIJK:
 *
 * Dit bevat uitsluitend de combo-taxonomies.
 *
 * Geen vac_status.
 *
 * Search & Filter Query 1 heeft zelf:
 *
 * vac_status NOT IN:
 * - gesloten-oud
 * - ingevuld
 *
 * Die voorwaarden mogen niet dubbel worden opgebouwd.
 */
function tfsc_build_combo_tax_query() {

    if ( ! tfsc_combo_core_ready() ) {
        return false;
    }


    $groups =
        tfsc_group_combo_terms();


    if ( ! $groups ) {
        return false;
    }


    $tax_query = [
        'relation' => 'AND',
    ];


    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        if ( ! $term_ids ) {
            continue;
        }


        $object =
            get_taxonomy(
                $taxonomy
            );


        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        if ( ! $term_ids ) {
            continue;
        }


        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method &&
                    $object &&
                    $object->hierarchical
                ),
        ];
    }


    return count( $tax_query ) > 1
        ? $tax_query
        : false;
}


/* ============================================================
 * MAIN COMBO QUERY → SEARCH & FILTER
 * ============================================================ */

/**
 * Virtuele combo archive koppelen aan Search & Filter Query 1.
 *
 * TFSC bepaalt hier bewust NIET:
 *
 * - posts_per_page
 * - orderby
 * - statusfilter
 * - offset
 *
 * Search & Filter blijft eigenaar van die instellingen.
 */
add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            ! tfsc_combo_core_ready() ||
            is_admin() ||
            ! $query->is_main_query() ||
            ! tfsc_is_combo_archive()
        ) {
            return;
        }


        $query->set(
            'search_filter_query_id',
            TFSC_SEARCH_FILTER_QUERY_ID
        );


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        /*
         * Pagination moet found_posts/max_num_pages
         * kunnen berekenen.
         */
        $query->set(
            'no_found_rows',
            false
        );
    },
    1
);


/* ============================================================
 * SEARCH & FILTER SERVER-SIDE COMBO CONTEXT
 * Version 5.3.2 - Merge Match Any / Match All
 * ============================================================ */


/**
 * Zoek het Search & Filter taxonomy-field
 * dat bij een taxonomy hoort.
 */
function tfsc_sf_get_taxonomy_field(
    $search_filter_query,
    $taxonomy
) {

    if (
        ! is_object( $search_filter_query ) ||
        ! method_exists(
            $search_filter_query,
            'get_fields'
        )
    ) {
        return false;
    }


    $fields =
        $search_filter_query->get_fields();


    if (
        ! is_array( $fields ) &&
        ! $fields instanceof Traversable
    ) {
        return false;
    }


    foreach ( $fields as $field ) {

        if (
            ! is_object( $field ) ||
            ! method_exists(
                $field,
                'get_attribute'
            )
        ) {
            continue;
        }


        if (
            'taxonomy' !==
            (string) $field->get_attribute(
                'dataType'
            )
        ) {
            continue;
        }


        if (
            $taxonomy !==
            (string) $field->get_attribute(
                'dataTaxonomy'
            )
        ) {
            continue;
        }


        return $field;
    }


    return false;
}


/**
 * Lees Match Any / Match All rechtstreeks
 * uit het betreffende S&F-field.
 *
 * any -> IN
 * all -> AND
 */
function tfsc_sf_get_match_operator(
    $search_filter_query,
    $taxonomy
) {

    $field =
        tfsc_sf_get_taxonomy_field(
            $search_filter_query,
            $taxonomy
        );


    if (
        $field &&
        method_exists(
            $field,
            'get_attribute'
        )
    ) {

        $method =
            strtolower(
                trim(
                    (string)
                    $field->get_attribute(
                        'multipleMatchMethod'
                    )
                )
            );


        if ( 'all' === $method ) {
            return 'AND';
        }


        if ( 'any' === $method ) {
            return 'IN';
        }
    }


    /*
     * Bestaande TFSC fallback.
     */
    return 'AND' ===
        tfsc_get_combo_taxonomy_match_method(
            $taxonomy
        )
            ? 'AND'
            : 'IN';
}


/**
 * Zet termwaarden uit een tax_query-clause
 * om naar term IDs.
 *
 * Ondersteunt:
 * - term_id
 * - id
 * - slug
 * - name
 */
function tfsc_sf_clause_get_term_ids(
    $taxonomy,
    array $clause
) {

    $field =
        strtolower(
            (string) (
                $clause['field']
                ?? 'term_id'
            )
        );


    $values =
        (array) (
            $clause['terms']
            ?? []
        );


    $ids = [];


    foreach ( $values as $value ) {

        if (
            'term_id' === $field ||
            'id' === $field
        ) {

            $id =
                (int) $value;


            if ( $id > 0 ) {
                $ids[] = $id;
            }


            continue;
        }


        if ( 'slug' === $field ) {

            $term =
                get_term_by(
                    'slug',
                    (string) $value,
                    $taxonomy
                );

        } elseif ( 'name' === $field ) {

            $term =
                get_term_by(
                    'name',
                    (string) $value,
                    $taxonomy
                );

        } else {

            $term = false;
        }


        if (
            $term instanceof WP_Term
        ) {
            $ids[] =
                (int) $term->term_id;
        }
    }


    return array_values(
        array_unique(
            array_filter(
                array_map(
                    'intval',
                    $ids
                )
            )
        )
    );
}


/**
 * Haal bestaande positieve S&F-clauses voor
 * dezelfde taxonomy uit de hoofd-tax_query.
 *
 * De terms uit die clauses worden teruggegeven.
 *
 * Negatieve clauses zoals NOT IN blijven altijd staan.
 */
function tfsc_sf_extract_taxonomy_terms(
    &$tax_query,
    $taxonomy
) {

    $found =
        [];


    $kept =
        [];


    $relation =
        isset(
            $tax_query['relation']
        )
            ? strtoupper(
                (string)
                $tax_query['relation']
            )
            : 'AND';


    foreach (
        $tax_query
        as $key => $clause
    ) {

        if ( 'relation' === $key ) {
            continue;
        }


        if (
            ! is_array( $clause ) ||
            empty(
                $clause['taxonomy']
            )
        ) {

            /*
             * Complex/nested clauses ongemoeid laten.
             */
            $kept[] =
                $clause;

            continue;
        }


        if (
            (string) $clause['taxonomy']
            !==
            (string) $taxonomy
        ) {

            $kept[] =
                $clause;

            continue;
        }


        $operator =
            strtoupper(
                (string) (
                    $clause['operator']
                    ?? 'IN'
                )
            );


        /*
         * Alleen positieve selectieclauses meenemen.
         */
        if (
            ! in_array(
                $operator,
                [
                    'IN',
                    'AND',
                ],
                true
            )
        ) {

            $kept[] =
                $clause;

            continue;
        }


        $found =
            array_merge(
                $found,
                tfsc_sf_clause_get_term_ids(
                    $taxonomy,
                    $clause
                )
            );
    }


    /*
     * Tax query opnieuw opbouwen zonder
     * de positieve clauses voor deze taxonomy.
     */
    $tax_query = [
        'relation' =>
            in_array(
                $relation,
                [
                    'AND',
                    'OR',
                ],
                true
            )
                ? $relation
                : 'AND',
    ];


    foreach ( $kept as $clause ) {

        if (
            is_array( $clause )
        ) {
            $tax_query[] =
                $clause;
        }
    }


    return array_values(
        array_unique(
            array_filter(
                array_map(
                    'intval',
                    $found
                )
            )
        )
    );
}


/**
 * Voeg de vaste combo-context toe aan de echte
 * Search & Filter / Elementor query.
 *
 * Cruciaal verschil met 5.3.1:
 *
 * Als S&F voor dezelfde taxonomy óók terms bevat,
 * maken we NIET twee losse clauses.
 *
 * We maken één gecombineerde clause.
 *
 * Voorbeeld:
 *
 * Combo:
 * Field Service Engineer
 *
 * S&F:
 * Site Manager
 *
 * multipleMatchMethod = any
 *
 * Wordt:
 *
 * terms = [FSE, Site Manager]
 * operator = IN
 *
 * Dus:
 * FSE OR Site Manager
 */
add_filter(
    'search-filter/query/query_args',
    function(
        $query_args,
        $search_filter_query
    ) {

        if (
            ! tfsc_combo_core_ready() ||
            ! tfsc_is_combo_archive() ||
            ! is_object(
                $search_filter_query
            ) ||
            ! method_exists(
                $search_filter_query,
                'get_id'
            )
        ) {
            return $query_args;
        }


        /*
         * Alleen Search & Filter Query 1.
         */
        if (
            (int)
            $search_filter_query->get_id()
            !==
            (int)
            TFSC_SEARCH_FILTER_QUERY_ID
        ) {
            return $query_args;
        }


        /*
         * Combo terms per taxonomy.
         */
        $groups =
            tfsc_group_combo_terms();


        if ( ! $groups ) {
            return $query_args;
        }


        /*
         * Bestaande S&F tax_query volledig behouden.
         */
        $tax_query =
            isset(
                $query_args['tax_query']
            ) &&
            is_array(
                $query_args['tax_query']
            )
                ? $query_args['tax_query']
                : [];


        $tax_query['relation'] =
            'AND';


        foreach (
            $groups
            as $taxonomy => $combo_term_ids
        ) {

            $combo_term_ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                (array) $combo_term_ids
                            )
                        )
                    )
                );


            if ( ! $combo_term_ids ) {
                continue;
            }


            /*
             * Zoek of S&F voor dezelfde taxonomy
             * al een positieve clause heeft gemaakt.
             *
             * Die halen we uit de query en verzamelen.
             */
            $sf_term_ids =
                tfsc_sf_extract_taxonomy_terms(
                    $tax_query,
                    $taxonomy
                );


            /*
             * Combo + huidige S&F-selectie samenvoegen.
             */
            $all_term_ids =
                array_values(
                    array_unique(
                        array_merge(
                            $combo_term_ids,
                            $sf_term_ids
                        )
                    )
                );


            if ( ! $all_term_ids ) {
                continue;
            }


            /*
             * Gebruik exact de Match Any/All instelling
             * van het S&F-field.
             */
            $operator =
                tfsc_sf_get_match_operator(
                    $search_filter_query,
                    $taxonomy
                );


            $taxonomy_object =
                get_taxonomy(
                    $taxonomy
                );


            /*
             * Eén enkele clause terugplaatsen.
             */
            $tax_query[] = [
                'taxonomy' =>
                    $taxonomy,

                'field' =>
                    'term_id',

                'terms' =>
                    $all_term_ids,

                'operator' =>
                    $operator,

                'include_children' =>
                    (
                        'AND' !== $operator &&
                        $taxonomy_object &&
                        $taxonomy_object->hierarchical
                    ),
            ];
        }


        $query_args['tax_query'] =
            $tax_query;


        return $query_args;
    },
    20,
    2
);


/* ============================================================
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * ============================================================ */

/**
 * Native taxonomy archives staan los van de virtuele
 * combo/S&F query.
 *
 * Hier behouden we de bestaande OPEN-statuslogica.
 */
add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            ! tfsc_combo_core_ready() ||
            is_admin() ||
            ! $query->is_main_query() ||
            tfsc_is_combo_archive() ||
            ! $query->is_tax()
        ) {
            return;
        }


        $term =
            $query->get_queried_object();


        if (
            ! $term instanceof WP_Term ||
            ! tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {
            return;
        }


        $status =
            tfsc_combo_status_clause();


        if ( ! $status ) {
            return;
        }


        $tax_query =
            $query->get(
                'tax_query'
            );


        if (
            ! is_array(
                $tax_query
            )
        ) {
            $tax_query = [];
        }


        $tax_query[] =
            $status;


        $tax_query['relation'] =
            'AND';


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
);


/* ============================================================
 * COMBO ARCHIVE STATUS + 404
 * ============================================================ */

add_action(
    'wp',
    function() {

        if (
            ! tfsc_combo_core_ready() ||
            ! tfsc_is_combo_archive() ||
            ! tfsc_get_combo_archive()
        ) {
            return;
        }


        global $wp_query;


        $wp_query->is_home =
            false;

        $wp_query->is_front_page =
            false;

