function tfsc_combo_heading_html(
    $rows
) {

    $rows =
        array_values(
            array_filter(
                (array) $rows,
                'strlen'
            )
        );


    if ( ! $rows ) {
        return '';
    }


    $html =
        '<span class="tfsc-heading">';


    foreach (
        $rows
        as $index => $row
    ) {

        $html .=
            sprintf(
                '<span class="%s">%s</span>',
                0 === $index
                    ? 'tfsc-heading__main'
                    : 'tfsc-heading__row',
                esc_html(
                    $row
                )
            );
    }


    return $html
        .
        '</span>';
}


/* ============================================================
 * [combo_heading]
 * ============================================================ */

add_shortcode(
    'combo_heading',
    function() {

        if (
            ! tfsc_combo_core_ready()
        ) {
            return '';
        }


        /*
         * Combo archive.
         */
        if (
            tfsc_is_combo_archive()
        ) {

            $groups =
                tfsc_group_combo_terms(
                    'name'
                );


            if ( ! $groups ) {
                return '';
            }


            $rows =
                [];


            $functions =
                $groups[
                    TFSC_COMBO_FUNCTION_TAXONOMY
                ]
                ??
                [];


            if ( $functions ) {

                if (
                    1 ===
                    count(
                        $functions
                    )
                ) {

                    $rows[] =
                        $functions[0]
                        .
                        ' vacatures';

                } else {

                    $rows[] =
                        'Vacatures';


                    $rows[] =
                        implode(
                            ', ',
                            $functions
                        );
                }


                unset(
                    $groups[
                        TFSC_COMBO_FUNCTION_TAXONOMY
                    ]
                );

            } else {

                $rows[] =
                    'Vacatures';
            }


            foreach (
                $groups
                as $names
            ) {

                if ( $names ) {

                    $rows[] =
                        implode(
                            ', ',
                            $names
                        );
                }
            }


            return tfsc_combo_heading_html(
                $rows
            );
        }


        /*
         * Native taxonomy archive.
         */
        $term =
            get_queried_object();


        if (
            $term instanceof WP_Term &&
            tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {

            $title =
                get_term_meta(
                    $term->term_id,
                    'pods_archive_title',
                    true
                );


            $title =
                is_string(
                    $title
                )
                    ? trim(
                        wp_strip_all_tags(
                            $title
                        )
                    )
                    : '';


            if (
                '' === $title
            ) {

                $title =
                    trim(
                        $term->name
                    );


                if (
                    '' === $title
                ) {
                    return '';
                }


                $title .=
                    ' vacatures';
            }


            return tfsc_combo_heading_html(
                [ $title ]
            );
        }


        /*
         * Hoofd vacaturearchive.
         */
        return is_post_type_archive(
            TFSC_VACANCY_POST_TYPE
        )
            ? tfsc_combo_heading_html(
                [ 'Vacatures' ]
            )
            : '';
    }
);


/* ============================================================
 * [combo_term taxonomy="..."]
 * ============================================================ */

add_shortcode(
    'combo_term',
    function( $atts ) {

        if (
            ! tfsc_combo_core_ready()
        ) {
            return '';
        }


        $atts =
            shortcode_atts(
                [
                    'taxonomy'  => '',
                    'separator' => ' • ',
                ],
                $atts,
                'combo_term'
            );


        $taxonomy =
            sanitize_key(
                $atts['taxonomy']
            );


        if ( ! $taxonomy ) {
            return '';
        }


        /*
         * Combo archive.
         */
        if (
            tfsc_is_combo_archive()
        ) {

            $groups =
                tfsc_group_combo_terms(
                    'name'
                );


            return empty(
                $groups[
                    $taxonomy
                ]
            )
                ? ''
                : esc_html(
                    implode(
                        (string)
                        $atts['separator'],
                        $groups[
                            $taxonomy
                        ]
                    )
                );
        }


        /*
         * Native taxonomy archive.
         */
        $term =
            get_queried_object();


        return (
            $term instanceof WP_Term &&
            $term->taxonomy ===
                $taxonomy &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        )
            ? esc_html(
                $term->name
            )
            : '';
    }
);

/**
 * TFSC - Search & Filter Native Behaviour Debug
 *
 * Alleen tijdelijk gebruiken.
 * Verandert geen enkele query.
 */

add_filter(
    'search-filter/query/query_args',
    function( $query_args, $sf_query ) {

        if (
            ! is_object( $sf_query ) ||
            ! method_exists( $sf_query, 'get_id' ) ||
            (int) $sf_query->get_id() !== 1
        ) {
            return $query_args;
        }

        $debug = [
            'request_uri' => isset( $_SERVER['REQUEST_URI'] )
                ? $_SERVER['REQUEST_URI']
                : '',

            'query_args' => $query_args,

            'fields' => [],
        ];

        if (
            method_exists(
                $sf_query,
                'get_fields'
            )
        ) {

            foreach (
                $sf_query->get_fields()
                as $field
            ) {

                if (
                    ! is_object( $field ) ||
                    ! method_exists(
                        $field,
                        'get_attribute'
                    )
                ) {
                    continue;
                }

                $data_type =
                    $field->get_attribute(
                        'dataType'
                    );

                if (
                    'taxonomy' !== $data_type
                ) {
                    continue;
                }

                $taxonomy =
                    $field->get_attribute(
                        'dataTaxonomy'
                    );

                $values = [];

                if (
                    method_exists(
                        $field,
                        'get_values'
                    )
                ) {
                    $values =
                        $field->get_values();
                }

                $debug['fields'][] = [
                    'taxonomy' =>
                        $taxonomy,

                    'url_name' =>
                        $field->get_attribute(
                            'dataUrlName'
                        ),

                    'multiple_match_method' =>
                        $field->get_attribute(
                            'multipleMatchMethod'
                        ),

                    'hide_empty' =>
                        $field->get_attribute(
                            'hideEmpty'
                        ),

                    'values' =>
                        $values,
                ];
            }
        }

        $GLOBALS[
            'tfsc_sf_native_debug'
        ] = $debug;

        return $query_args;
    },
    999,
    2
);


