 * QUERY VARS + REWRITES
 * ============================================================ */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] =
            'tfsc_combo_archive';

        $vars[] =
            'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        $base =
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            );


        /**
         * PAGINATION RULE
         *
         * MOET vóór de algemene combo-regel staan.
         *
         * Voorbeeld:
         *
         * /vacatures/functienaam/field-service-engineer/page/2/
         *
         * wordt:
         *
         * tfsc_combo_path =
         * functienaam/field-service-engineer
         *
         * paged = 2
         */
        add_rewrite_rule(
            '^'
            . $base
            . '/(.+?)/page/([0-9]+)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]'
            . '&paged=$matches[2]',

            'top'
        );


        /**
         * NORMALE COMBO RULE
         */
        add_rewrite_rule(
            '^'
            . $base
            . '/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/* ============================================================
 * TERMPAD OPLOSSEN
 * ============================================================ */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );

    if (
        ! $tax_object ||
        ! is_array( $segments ) ||
        ! $segments
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        ! $segments ||
        (
            ! $tax_object->hierarchical &&
            1 !== count( $segments )
        )
    ) {
        return false;
    }


    $terms =
        [];

    $parent_id =
        0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term ||
            is_wp_error( $term )
        ) {
            return false;
        }


        if (
            $index > 0 &&
            (int) $term->parent
                !==
                $parent_id
        ) {
            return false;
        }


        $terms[] =
            $term;

        $parent_id =
            (int) $term->term_id;
    }


    return [
        'path' =>
            $terms,

        'term' =>
            end( $terms ),
    ];
}


/* ============================================================
 * COMBO URL PARSEN
 * ============================================================ */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;


    if ( $resolved ) {
        return $cache;
    }


    $resolved =
        true;


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if ( ! $raw_path ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string) $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    if (
        count( $segments ) < 2
    ) {
        return false;
    }


    $allowed =
        tfsc_get_allowed_combo_taxonomies();


    if ( ! $allowed ) {
        return false;
    }


    $items =
        [];

    $count =
        count( $segments );

    $i =
        0;


    while ( $i < $count ) {

        $taxonomy =
            sanitize_key(
                $segments[ $i ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }


        $i++;


        $term_segments =
            [];


        while (
            $i < $count
        ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[ $i ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }


            $term_segments[] =
                $segments[ $i ];


            $i++;
        }


        if (
            ! $term_segments
        ) {
            return false;
        }


        $resolved_path =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if (
            ! $resolved_path
        ) {
            return false;
        }


        $items[] = [
            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved_path['term'],

            'path' =>
                $resolved_path['path'],
        ];
    }


    $cache =
        $items
            ? $items
            : false;


    return $cache;
}


/* ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================ */

function tfsc_group_combo_terms(
    $property = 'term_id'
) {

    $combo =
        tfsc_get_combo_archive();


    if (
        ! is_array( $combo )
    ) {
        return [];
    }


    $grouped =
        [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            ) ||
            empty(
                $item['term']
            ) ||
            ! $item['term']
                instanceof WP_Term
        ) {
            continue;
        }


        $taxonomy =
            $item['taxonomy'];


        if (
            'name' === $property
        ) {

            $value =
                trim(
                    $item['term']->name
                );

        } elseif (
            'slug' === $property
        ) {

            $value =
                $item['term']->slug;

        } else {

            $value =
                (int)
                $item['term']->term_id;
        }


        if (
            '' === $value ||
            0 === $value
        ) {
            continue;
        }


        if (
            ! isset(
                $grouped[
                    $taxonomy
                ]
            )
        ) {

            $grouped[
                $taxonomy
            ] = [];
        }


        if (
            ! in_array(
                $value,
                $grouped[
                    $taxonomy
                ],
                true
            )
        ) {

            $grouped[
                $taxonomy
            ][] =
                $value;
        }
    }


    return $grouped;
}


/* ============================================================
 * TAX QUERY
 * ============================================================ */

function tfsc_build_combo_tax_query() {

    $grouped =
        tfsc_group_combo_terms(
            'term_id'
        );


    if (
        ! $grouped
    ) {
        return false;
    }


    $tax_query = [
        'relation' =>
            'AND',

        tfsc_combo_status_clause(),
    ];


    foreach (
        $grouped
        as $taxonomy => $term_ids
    ) {

        if (
            ! $term_ids
        ) {
            continue;
        }


        $object =
            get_taxonomy(
                $taxonomy
            );


        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            /**
             * Meerdere functienamen:
             * IN = OR
             *
             * kennisgebied:
             * AND
             */
            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method &&
                    $object &&
                    $object->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/* ============================================================
 * MAIN QUERY
 * ============================================================ */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin() ||
            ! $query->is_main_query()
        ) {
            return;
        }


        /* ----------------------------------------------------
         * VIRTUEEL COMBO ARCHIVE
         * ---------------------------------------------------- */

        if (
            tfsc_is_combo_archive()
        ) {

            $tax_query =
                tfsc_build_combo_tax_query();


            if (
                ! $tax_query
            ) {
                return;
            }


            $query->set(
                'post_type',
                TFSC_VACANCY_POST_TYPE
            );


            $query->set(
                'post_status',
                'publish'
            );


            $query->set(
                'tax_query',
                $tax_query
            );


            /**
             * Nodig voor found_posts
             * en pagination.
             */
            $query->set(
                'no_found_rows',
                false
            );


            /**
             * Zorg dat WordPress paged gebruikt.
             *
             * De rewrite zet dit normaal al goed,
             * maar hiermee wordt het expliciet.
             */
            $paged =
                max(
                    1,
                    (int) get_query_var(
                        'paged'
                    )
                );


            $query->set(
                'paged',
                $paged
            );


            return;
        }


        /* ----------------------------------------------------
         * NATIVE VACATURE TAXONOMY ARCHIVE
         * ---------------------------------------------------- */

        if (
            ! $query->is_tax()
        ) {
            return;
        }


        $term =
            $query->get_queried_object();


        if (
            ! $term instanceof WP_Term ||
            ! tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {
            return;
        }


        $tax_query =
            $query->get(
                'tax_query'
            );


        if (
            ! is_array(
                $tax_query
            )
        ) {
            $tax_query =
                [];
        }


        $tax_query[] =
            tfsc_combo_status_clause();


        $tax_query['relation'] =
            'AND';


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
);


