/* ============================================================
 * HEADING HTML
 * ============================================================ */

function tfsc_combo_heading_html(
    $rows
) {

    $rows =
        array_values(
            array_filter(
                (array) $rows,
                'strlen'
            )
        );


    if (
        ! $rows
    ) {
        return '';
    }


    $html =
        '<span class="tfsc-heading">';


    foreach (
        $rows
        as $index => $row
    ) {

        $html .=
            '<span class="'
            .
            (
                0 === $index
                    ? 'tfsc-heading__main'
                    : 'tfsc-heading__row'
            )
            .
            '">'
            .
            esc_html(
                $row
            )
            .
            '</span>';
    }


    $html .=
        '</span>';


    return $html;
}


