                        .
                        ' vacatures';

                } else {

                    $rows[] =
                        'Vacatures';


                    $rows[] =
                        implode(
                            ', ',
                            $functions
                        );
                }


                unset(
                    $grouped[
                        'functienaam'
                    ]
                );

            } else {

                $rows[] =
                    'Vacatures';
            }


            foreach (
                $grouped
                as $names
            ) {

                if (
                    $names
                ) {

                    $rows[] =
                        implode(
                            ', ',
                            $names
                        );
                }
            }


            return tfsc_combo_heading_html(
                $rows
            );
        }


        $term =
            get_queried_object();


        if (
            $term instanceof WP_Term &&
            tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {

            $title =
                get_term_meta(
                    $term->term_id,
                    'pods_archive_title',
                    true
                );


            $title =
                is_string(
                    $title
                )
                    ? trim(
                        wp_strip_all_tags(
                            $title
                        )
                    )
                    : '';


            if (
                '' === $title
            ) {

                $name =
                    trim(
                        $term->name
                    );


                if (
                    '' === $name
                ) {
                    return '';
                }


                $title =
                    $name
                    .
                    ' vacatures';
            }


            return tfsc_combo_heading_html(
                [ $title ]
            );
        }


        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {

            return tfsc_combo_heading_html(
                [ 'Vacatures' ]
            );
        }


        return '';
    }
);


