add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',

                    'separator' =>
                        ' • ',
                ],
                $atts,
                'combo_term'
            );


        $taxonomy =
            sanitize_key(
                $atts[
                    'taxonomy'
                ]
            );


        if (
            ! $taxonomy
        ) {
            return '';
        }


        if (
            tfsc_is_combo_archive()
        ) {

            $grouped =
                tfsc_group_combo_terms(
                    'name'
                );


            if (
                empty(
                    $grouped[
                        $taxonomy
                    ]
                )
            ) {
                return '';
            }


            return esc_html(
                implode(
                    (string)
                    $atts[
                        'separator'
                    ],
                    $grouped[
                        $taxonomy
                    ]
                )
            );
        }


        $term =
            get_queried_object();


        if (
            $term instanceof WP_Term &&
            $term->taxonomy ===
                $taxonomy &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            return esc_html(
                $term->name
            );
        }


        return '';
    }
);

