/**
 * TFSC - Volledig dynamische vacature-archieven
 * Version 4.3 - Stable Legacy Logic + S&F Pagination Sync
 *
 * Gebaseerd op de oude werkende combo-architectuur.
 *
 * Regelt:
 * - Virtuele combo archives onder /vacatures/...
 * - Onbeperkt aantal taxonomies/terms
 * - Verschillende taxonomies = AND
 * - Meerdere terms binnen dezelfde taxonomy = OR
 * - kennisgebied = AND
 * - Alleen vac_status=open
 * - Search & Filter Pro v3 frontend sync
 * - Elementor archive condition
 * - Native vacature taxonomy archives
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 * - Correcte /page/N/ pagination rewrite
 * - Main query gebruikt dezelfde posts_per_page als S&F Query 1
 *
 * Belangrijk:
 * - Geen server-side Search & Filter query manipulation
 * - Geen search_filter_query_id koppeling
 * - Geen search-filter/query/query_args mutatie
 */


/* ============================================================
 * CONFIG
 * ============================================================ */

if ( ! defined( 'TFSC_COMBO_BASE' ) ) {
    define( 'TFSC_COMBO_BASE', 'vacatures' );
}

if ( ! defined( 'TFSC_VACANCY_POST_TYPE' ) ) {
    define( 'TFSC_VACANCY_POST_TYPE', 'vacature' );
}

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}

if ( ! defined( 'TFSC_STATUS_TAXONOMY' ) ) {
    define( 'TFSC_STATUS_TAXONOMY', 'vac_status' );
}

if ( ! defined( 'TFSC_OPEN_STATUS_SLUG' ) ) {
    define( 'TFSC_OPEN_STATUS_SLUG', 'open' );
}


/* ============================================================
 * HELPERS
 * ============================================================ */

function tfsc_get_combo_taxonomy_match_method( $taxonomy ) {

    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


function tfsc_combo_status_clause() {

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    return function_exists( 'tfsc_combo_policy_taxonomy_allowed' )
        ? tfsc_combo_policy_taxonomy_allowed( $taxonomy )
        : false;
}


function tfsc_get_allowed_combo_taxonomies() {

    return function_exists( 'tfsc_combo_policy_allowed_taxonomies' )
        ? tfsc_combo_policy_allowed_taxonomies()
        : [];
}


function tfsc_is_combo_archive() {

    return (bool) get_query_var(
        'tfsc_combo_archive'
    );
}


function tfsc_is_vacancy_seo_landing() {

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term = get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


/* ============================================================
 * SEARCH & FILTER POSTS PER PAGE
 * ============================================================
 *
 * Search & Filter Query 1 is de bron voor de paginagrootte.
 *
 * Als S&F bijvoorbeeld 10 resultaten per pagina gebruikt,
 * gebruikt de WordPress main query ook 10.
 *
 * Daardoor krijgen:
 *
 * - WordPress
 * - Rank Math
 * - combo pagination
 * - Search & Filter
 *
 * dezelfde page count.
 * ============================================================ */

function tfsc_get_search_filter_posts_per_page() {

    static $resolved = false;
    static $value    = null;

    if ( $resolved ) {
        return $value;
    }

    $resolved = true;


    if (
        ! class_exists(
            '\Search_Filter\Queries\Query'
        )
    ) {
        return null;
    }


    try {

        $sf_query =
            \Search_Filter\Queries\Query::find(
                [
                    'id' =>
                        (int) TFSC_SEARCH_FILTER_QUERY_ID,
                ]
            );

    } catch ( Throwable $e ) {

        return null;
    }


    if (
        is_wp_error( $sf_query ) ||
        ! is_object( $sf_query ) ||
        ! method_exists(
            $sf_query,
            'get_attribute'
        )
    ) {
        return null;
    }


    $posts_per_page =
        $sf_query->get_attribute(
            'postsPerPage'
        );


    if (
        null === $posts_per_page ||
        '' === $posts_per_page
    ) {
        return null;
    }


    $posts_per_page =
        (int) $posts_per_page;


    if ( -1 === $posts_per_page ) {
        return $value = -1;
    }


    if ( $posts_per_page < 1 ) {
        return null;
    }


    return $value =
        $posts_per_page;
}


/* ============================================================
 * QUERY VARS + REWRITES
 * ============================================================ */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';
        $vars[] = 'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        $base =
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            );


        /**
         * PAGINATION
         *
         * Deze regel MOET vóór de algemene combo-regel staan.
         *
         * /vacatures/functienaam/field-service-engineer/page/2/
         *
         * wordt:
         *
         * tfsc_combo_archive = 1
         * tfsc_combo_path    = functienaam/field-service-engineer
         * paged              = 2
         */

        add_rewrite_rule(
            '^'
            . $base
            . '/(.+?)/page/([0-9]+)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]'
            . '&paged=$matches[2]',

            'top'
        );


        /**
         * Normale combo archive.
         */

        add_rewrite_rule(
            '^'
            . $base
            . '/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/* ============================================================
 * TERMPAD OPLOSSEN
 * ============================================================ */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );

    if (
        ! $tax_object ||
        ! is_array( $segments ) ||
        ! $segments
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        ! $segments ||
        (
            ! $tax_object->hierarchical &&
            1 !== count( $segments )
        )
    ) {
        return false;
    }


    $terms     = [];
    $parent_id = 0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term ||
            is_wp_error( $term )
        ) {
            return false;
        }


        if (
            $index > 0 &&
            (int) $term->parent !== $parent_id
        ) {
            return false;
        }


        $terms[] =
            $term;

        $parent_id =
            (int) $term->term_id;
    }


    return [
        'path' => $terms,
        'term' => end( $terms ),
    ];
}


/* ============================================================
 * COMBO URL PARSEN
 * ============================================================ */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;


    if ( $resolved ) {
        return $cache;
    }


    $resolved = true;


    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if ( ! $raw_path ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string) $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    if (
        count( $segments ) < 2
    ) {
        return false;
    }


    $allowed =
        tfsc_get_allowed_combo_taxonomies();


    if ( ! $allowed ) {
        return false;
    }


    $items = [];
    $count = count( $segments );
    $i     = 0;


    while ( $i < $count ) {

        $taxonomy =
            sanitize_key(
                $segments[ $i ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }


        $i++;


        $term_segments = [];


        while ( $i < $count ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[ $i ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }


            $term_segments[] =
                $segments[ $i ];

            $i++;
        }


        if ( ! $term_segments ) {
            return false;
        }


        $resolved_path =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if ( ! $resolved_path ) {
            return false;
        }


        $items[] = [
            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved_path['term'],

            'path' =>
                $resolved_path['path'],
        ];
    }


    return $cache =
        $items
            ? $items
            : false;
}


/* ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================ */

function tfsc_group_combo_terms(
    $property = 'term_id'
) {

    $combo =
        tfsc_get_combo_archive();


    if ( ! is_array( $combo ) ) {
        return [];
    }


    $grouped = [];


    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }


        $taxonomy =
            $item['taxonomy'];


        if ( 'name' === $property ) {

            $value =
                trim(
                    $item['term']->name
                );

        } elseif ( 'slug' === $property ) {

            $value =
                $item['term']->slug;

        } else {

            $value =
                (int) $item['term']->term_id;
        }


        if (
            '' === $value ||
            0 === $value
        ) {
            continue;
        }


        if (
            ! isset(
                $grouped[ $taxonomy ]
            )
        ) {
            $grouped[ $taxonomy ] = [];
        }


        if (
            ! in_array(
                $value,
                $grouped[ $taxonomy ],
                true
            )
        ) {
            $grouped[ $taxonomy ][] =
                $value;
        }
    }


    return $grouped;
}


/* ============================================================
 * TAX QUERY
 * ============================================================ */

function tfsc_build_combo_tax_query() {

    $grouped =
        tfsc_group_combo_terms(
            'term_id'
        );


    if ( ! $grouped ) {
        return false;
    }


    $tax_query = [
        'relation' => 'AND',

        tfsc_combo_status_clause(),
    ];


    foreach (
        $grouped
        as $taxonomy => $term_ids
    ) {

        if ( ! $term_ids ) {
            continue;
        }


        $object =
            get_taxonomy(
                $taxonomy
            );


        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            /**
             * Bijvoorbeeld:
             *
             * functienaam:
             * FSE + Service Engineer + Servicemonteur
             *
             * operator IN
             * = OR
             *
             * kennisgebied:
             * Elektrotechniek + Mechanisch
             *
             * operator AND
             */

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method &&
                    $object &&
                    $object->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/* ============================================================
 * MAIN QUERY
 * ============================================================ */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin() ||
            ! $query->is_main_query()
        ) {
            return;
        }


        /* ----------------------------------------------------
         * VIRTUEEL COMBO ARCHIVE
         * ---------------------------------------------------- */

        if ( tfsc_is_combo_archive() ) {

            $tax_query =
                tfsc_build_combo_tax_query();


            if ( ! $tax_query ) {
                return;
            }


            $query->set(
                'post_type',
                TFSC_VACANCY_POST_TYPE
            );


            $query->set(
                'post_status',
                'publish'
            );


            $query->set(
                'tax_query',
                $tax_query
            );


            /**
             * ================================================
             * PAGINAGROOTTE UIT SEARCH & FILTER
             * ================================================
             *
             * Dit was het ontbrekende stuk.
             *
             * Voorheen:
             *
             * WordPress main query = 20
             * Search & Filter       = 10
             *
             * Daardoor:
             *
             * found_posts   = 20
             * max_num_pages = 1
             *
             * terwijl S&F twee pagina's had.
             *
             * Nu gebruikt de main query dezelfde instelling
             * als Search & Filter Query 1.
             */

            $posts_per_page =
                tfsc_get_search_filter_posts_per_page();


            if (
                null !== $posts_per_page
            ) {

                $query->set(
                    'posts_per_page',
                    $posts_per_page
                );
            }


            /**
             * WordPress moet found_posts en max_num_pages
             * daadwerkelijk berekenen.
             */

            $query->set(
                'no_found_rows',
                false
            );


            /**
             * Huidige combo-pagina.
             */

            $paged =
                max(
                    1,
                    (int) get_query_var(
                        'paged'
                    )
                );


            $query->set(
                'paged',
                $paged
            );


            return;
        }


        /* ----------------------------------------------------
         * NATIVE VACATURE TAXONOMY ARCHIVE
         * ---------------------------------------------------- */

        if ( ! $query->is_tax() ) {
            return;
        }


        $term =
            $query->get_queried_object();


        if (
            ! $term instanceof WP_Term ||
            ! tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {
            return;
        }


        $tax_query =
            $query->get(
                'tax_query'
            );


        if ( ! is_array( $tax_query ) ) {
            $tax_query = [];
        }


        $tax_query[] =
            tfsc_combo_status_clause();


        $tax_query['relation'] =
            'AND';


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
);


