/* ============================================================
 * SEARCH & FILTER PRO V3 FRONTEND SYNC
 * ============================================================ */

add_action(
    'wp_footer',
    function() {

        if (
            ! tfsc_is_vacancy_seo_landing()
        ) {
            return;
        }


        $is_combo =
            tfsc_is_combo_archive();


        $active_values =
            $is_combo
                ? tfsc_group_combo_terms(
                    'slug'
                )
                : [];


        ?>
        <script>
        (function () {

            const QUERY_ID =
                <?php echo (int) TFSC_SEARCH_FILTER_QUERY_ID; ?>;

            const IS_COMBO =
                <?php echo $is_combo ? 'true' : 'false'; ?>;

            const COMBO_VALUES =
                <?php echo wp_json_encode( $active_values ); ?>;


            let comboReady =
                !IS_COMBO;

            let comboDone =
                false;

            let redirectAttached =
                false;

            let redirectStarted =
                false;


            function normalize(items) {

                if (!items) {
                    return [];
                }

                if (items instanceof Map) {
                    return Array.from(
                        items.values()
                    );
                }

                if (Array.isArray(items)) {
                    return items;
                }

                if (typeof items === 'object') {
                    return Object.values(
                        items
                    );
                }

                return [];
            }


            function sameValues(a, b) {

                a = Array.isArray(a)
                    ? a.map(String).sort()
                    : [];

                b = Array.isArray(b)
                    ? b.map(String).sort()
                    : [];

                return (
                    a.length === b.length &&
                    a.every(
                        (value, index) =>
                            value === b[index]
                    )
                );
            }


            function syncCombo() {

                if (
                    !IS_COMBO ||
                    comboDone
                ) {
                    return;
                }


                const api =
                    window.searchAndFilter
                        ?.frontend
                        ?.fields;


                if (
                    !api ||
                    typeof api.getAll !==
                        'function'
                ) {
                    return;
                }


                const fields =
                    normalize(
                        api.getAll()
                    );


                let expected =
                    0;

                let correct =
                    0;


                fields.forEach(
                    field => {

                        if (
                            !field ||
                            typeof field.getAttributes !==
                                'function' ||
                            typeof field.getValues !==
                                'function' ||
                            typeof field.setValues !==
                                'function'
                        ) {
                            return;
                        }


                        const attributes =
                            field.getAttributes();


                        if (
                            !attributes ||
                            String(
                                attributes.queryId
                            ) !==
                                String(
                                    QUERY_ID
                                ) ||
                            attributes.dataType !==
                                'taxonomy'
                        ) {
                            return;
                        }


                        const taxonomy =
                            attributes.dataTaxonomy;


                        if (
                            !taxonomy ||
                            !Object.prototype
                                .hasOwnProperty
                                .call(
                                    COMBO_VALUES,
                                    taxonomy
                                )
                        ) {
                            return;
                        }


                        expected++;


                        const wanted =
                            (
                                Array.isArray(
                                    COMBO_VALUES[
                                        taxonomy
                                    ]
                                )
                                    ? COMBO_VALUES[
                                        taxonomy
                                    ]
                                    : [
                                        COMBO_VALUES[
                                            taxonomy
                                        ]
                                    ]
                            ).map(String);


                        const current =
                            (
                                Array.isArray(
                                    field.getValues()
                                )
                                    ? field.getValues()
                                    : []
                            ).map(String);


                        if (
                            sameValues(
                                current,
                                wanted
                            )
                        ) {

                            correct++;
                            return;
                        }


                        field.setValues(
                            wanted
                        );
                    }
                );


                if (
                    expected &&
                    correct === expected
                ) {

                    comboDone =
                        true;

                    comboReady =
                        true;

                    window.TFSC_SF_COMBO_READY =
                        true;
                }
            }


            function buildResultsUrl(query) {

                if (
                    !query ||
                    typeof query.getUrl !==
                        'function' ||
                    typeof query.getFields !==
                        'function'
                ) {
                    return null;
                }


                const baseUrl =
                    query.getUrl();


                if (!baseUrl) {
                    return null;
                }


                const prefix =
                    window.searchAndFilterData
                        ?.urlPrefix
                        ||
                        '_';


                const parts =
                    [];


                normalize(
                    query.getFields()
                ).forEach(
                    function(field) {

                        if (
                            !field ||
                            typeof field.getUrlName !==
                                'function' ||
                            typeof field.getUrlValues !==
                                'function'
                        ) {
                            return;
                        }


                        const name =
                            field.getUrlName();


                        let values =
                            field.getUrlValues();


                        if (!name) {
                            return;
                        }


                        if (
                            values !== null &&
                            values !== undefined &&
                            !Array.isArray(
                                values
                            )
                        ) {

                            values =
                                [ values ];
                        }


                        values =
                            Array.isArray(
                                values
                            )
                                ? values.filter(
                                    value =>
                                        value !== null &&
                                        value !== undefined &&
                                        String(value) !== ''
                                )
                                : [];


                        if ( ! values.length ) {
                            return;
                        }


                        parts.push(
                            encodeURIComponent(
                                prefix + name
                            )
                            +
                            '='
                            +
                            values
                                .map(
                                    value =>
                                        encodeURIComponent(
                                            String(value)
                                        )
                                )
                                .join(',')
                        );
                    }
                );


                if (
                    typeof query.getActiveUrlArg ===
                        'function'
                ) {

                    const active =
                        query.getActiveUrlArg();


                    if (active) {

                        parts.push(
                            encodeURIComponent(
                                active
                            )
                        );
                    }
                }


                const cleanBase =
                    String(baseUrl)
                        .split('#')[0]
                        .split('?')[0];


                return parts.length
                    ? cleanBase
                        +
                        '?'
                        +
                        parts.join('&')
                    : cleanBase;
            }


            function attachRedirect() {

                if (redirectAttached) {
                    return true;
                }


                const queries =
                    window.searchAndFilter
                        ?.frontend
                        ?.queries;


                if (
                    !queries ||
                    typeof queries.get !==
                        'function'
                ) {
                    return false;
                }


                const query =
                    queries.get(
                        QUERY_ID
                    );


                if (
                    !query ||
                    typeof query.on !==
                        'function'
                ) {
                    return false;
                }


                redirectAttached =
                    true;


                query.on(
                    'get-results/start',
                    function() {

                        if (
                            redirectStarted ||
                            (
                                IS_COMBO &&
                                !comboReady
                            )
                        ) {
                            return;
                        }


                        const url =
                            buildResultsUrl(
                                query
                            );


                        if (!url) {
                            return;
                        }


                        redirectStarted =
                            true;


                        window.location.href =
                            url;
                    }
                );


                return true;
            }


            function start() {

                [
                    50,
                    250,
                    750,
                    1500
                ].forEach(
                    delay =>
                        setTimeout(
                            syncCombo,
                            delay
                        )
                );


                [
                    250,
                    750,
                    1500
                ].forEach(
                    delay =>
                        setTimeout(
                            attachRedirect,
                            delay
                        )
                );
            }


            document.addEventListener(
                'search-filter/mount',
                function() {

                    setTimeout(
                        syncCombo,
                        0
                    );

                    setTimeout(
                        syncCombo,
                        100
                    );

                    setTimeout(
                        attachRedirect,
                        150
                    );

                    setTimeout(
                        attachRedirect,
                        400
                    );
                }
            );


            if (
                document.readyState ===
                    'loading'
            ) {

                document.addEventListener(
                    'DOMContentLoaded',
                    start
                );

            } else {

                start();
            }


            window.addEventListener(
                'pageshow',
                function(event) {

                    if (event.persisted) {
                        window.location.reload();
                    }
                }
            );

        })();
        </script>
        <?php
    },
    90
);


