 * HEADING HTML
 * ============================================================ */

function tfsc_combo_heading_html(
    $rows
) {

    $rows =
        array_values(
            array_filter(
                (array) $rows,
                'strlen'
            )
        );


    if ( ! $rows ) {
        return '';
    }


    $html =
        '<span class="tfsc-heading">';


    foreach (
        $rows
        as $index => $row
    ) {

        $html .=
            '<span class="'
            .
            (
                0 === $index
                    ? 'tfsc-heading__main'
                    : 'tfsc-heading__row'
            )
            .
            '">'
            .
            esc_html(
                $row
            )
            .
            '</span>';
    }


    $html .=
        '</span>';


    return $html;
}


/* ============================================================
 * [combo_heading]
 * ============================================================ */

add_shortcode(
    'combo_heading',
    function() {

        /**
         * Combo archive.
         */

        if ( tfsc_is_combo_archive() ) {
            /**
             * Een combo-URL met exact één term functioneert voor de bezoeker
             * als een gewoon termarchief. Respecteer daarom ook hier de
             * optionele Pods-archieftitel. Bij een leeg veld en bij echte
             * combinaties blijft de bestaande titelopbouw ongewijzigd.
             */
            $combo =
                tfsc_get_combo_archive();

            if (
                is_array( $combo ) &&
                1 === count( $combo ) &&
                ! empty( $combo[0]['term'] ) &&
                $combo[0]['term'] instanceof WP_Term
            ) {
                $single_title =
                    get_term_meta(
                        $combo[0]['term']->term_id,
                        'pods_archive_title',
                        true
                    );

                $single_title =
                    is_string( $single_title )
                        ? trim(
                            wp_strip_all_tags(
                                $single_title
                            )
                        )
                        : '';

                if ( '' !== $single_title ) {
                    return tfsc_combo_heading_html(
                        [ $single_title ]
                    );
                }
            }


            $grouped =
                tfsc_group_combo_terms(
                    'name'
                );


            if ( ! $grouped ) {
                return '';
            }


            $rows = [];


            if (
                ! empty(
                    $grouped[
                        'functienaam'
                    ]
                )
            ) {

                $functions =
                    $grouped[
                        'functienaam'
                    ];


                if (
                    1 === count(
                        $functions
                    )
                ) {

                    $rows[] =
                        $functions[0]
                        .
                        ' vacatures';

                } else {

                    $rows[] =
                        'Vacatures';


                    $rows[] =
                        implode(
                            ', ',
                            $functions
                        );
                }


                unset(
                    $grouped[
                        'functienaam'
                    ]
                );

            } else {

                $rows[] =
                    'Vacatures';
            }


            foreach (
                $grouped
                as $names
            ) {

                if ( $names ) {

                    $rows[] =
                        implode(
                            ', ',
                            $names
                        );
                }
            }


            return tfsc_combo_heading_html(
                $rows
            );
        }


        /**
         * Native taxonomy archive.
         */

        $term =
            get_queried_object();


        if (
            $term instanceof WP_Term &&
            tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {

            $title =
                get_term_meta(
                    $term->term_id,
                    'pods_archive_title',
                    true
                );


            $title =
                is_string(
                    $title
                )
                    ? trim(
                        wp_strip_all_tags(
                            $title
                        )
                    )
                    : '';


            if ( '' === $title ) {

                $name =
                    trim(
                        $term->name
                    );


                if ( '' === $name ) {
                    return '';
                }


                $title =
                    $name
                    .
                    ' vacatures';
            }


            return tfsc_combo_heading_html(
                [ $title ]
            );
        }


        /**
         * Vacature post type archive.
         */

        if (
            is_post_type_archive(
                TFSC_VACANCY_POST_TYPE
            )
        ) {

            return tfsc_combo_heading_html(
                [ 'Vacatures' ]
            );
        }


        return '';
    }
);


/* ============================================================
 * [combo_term taxonomy="..."]
 * ============================================================ */

add_shortcode(
    'combo_term',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'taxonomy' =>
                        '',

                    'separator' =>
                        ' • ',
                ],
                $atts,
                'combo_term'
            );


        $taxonomy =
            sanitize_key(
                $atts[
                    'taxonomy'
                ]
            );


        if ( ! $taxonomy ) {
            return '';
        }


        /**
         * Combo archive.
         */

        if ( tfsc_is_combo_archive() ) {

            $grouped =
                tfsc_group_combo_terms(
                    'name'
                );


            if (
                empty(
                    $grouped[
                        $taxonomy
                    ]
                )
            ) {
                return '';
            }


            return esc_html(
                implode(
                    (string)
                    $atts[
                        'separator'
                    ],
                    $grouped[
                        $taxonomy
                    ]
                )
            );
        }


        /**
         * Native taxonomy archive.
         */

        $term =
            get_queried_object();


        if (
            $term instanceof WP_Term &&
            $term->taxonomy ===
                $taxonomy &&
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {

            return esc_html(
                $term->name
            );
        }


        return '';
    }
);

/**
 * TFSC - Combo Archive SEO + Native Archive Canonicals + Filter SEO
 * Version 4.2 - Stable Legacy Combo + Pagination SEO
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * ============================================================
 * REGELT
 * ============================================================
 *
 * COMBO ARCHIVES
 * - SEO title
 * - Meta description
 * - Canonical
 * - Robots
 * - Correcte canonical voor /page/N/
 * - Correcte OpenGraph URL voor /page/N/
 * - Correcte CollectionPage schema URL voor /page/N/
 * - Correcte rel prev / next
 * - Centrale indexeringslogica voor SEO + sitemap
 *
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * - blijven bereikbaar
 * - robots blijven door Rank Math / WordPress bepaald
 * - canonical naar equivalente combo archive
 * - pagination blijft behouden
 *
 * SEARCH & FILTER URLS OP /vacatures/
 * - noindex, follow
 * - canonical naar schone /vacatures/
 */


