/**
 * v5.2: gedeelde actieve-relatie-terugval voor lijsten en knoppen;
 * zonder passende relatie tonen we uitsluitend gepubliceerde open vacatures.
 * TFSC - Taxonomy Archive Derived Relationship Terms
 * Version 4.1 - Match Logic Synced With Combo Base
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een taxonomy-term:
 *
 * huidige term
 * → alle ingevulde relationship_* velden op die term
 * → relevante OPEN vacatures
 * → terms uit Elementor Source taxonomy
 * → Elementor Taxonomy Loop
 *
 * Verschillende taxonomies = AND
 * Meerdere terms binnen dezelfde taxonomy = OR / IN
 * kennisgebied = AND
 *
 * relationship_vacature_button_url wordt bewust NIET gebruikt
 * voor de vacaturequery.
 *
 *
 * ELEMENTOR QUERY IDS
 * ============================================================
 *
 * archive_relationship_level_0
 * archive_relationship_level_1
 * archive_relationship_level_2
 *
 * De Elementor Source bepaalt de target taxonomy.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_taxrel_v4_vacancy_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_taxrel_v4_status_taxonomy() {

    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}


function tfsc_taxrel_v4_open_status() {

    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


function tfsc_taxrel_v4_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. HUIDIGE TAXONOMY TERM
 * ============================================================
 */

function tfsc_taxrel_v4_current_term() {

    static $cached = null;

    if ( null !== $cached ) {
        return $cached;
    }


    $object =
        get_queried_object();


    /**
     * Normaal taxonomy archive / preview iframe.
     */
    if (
        $object instanceof WP_Term &&
        ! empty( $object->term_id ) &&
        ! empty( $object->taxonomy ) &&
        taxonomy_exists( $object->taxonomy )
    ) {

        if ( is_user_logged_in() ) {

            set_transient(
                'tfsc_taxrel_v4_preview_' . get_current_user_id(),
                [
                    'term_id' =>
                        (int) $object->term_id,

                    'taxonomy' =>
                        $object->taxonomy,
                ],
                5 * MINUTE_IN_SECONDS
            );
        }


        return $cached =
            $object;
    }


    /**
     * Elementor admin-render.
     */
    if (
        is_admin() &&
        $object instanceof WP_Post &&
        is_user_logged_in()
    ) {

        $preview =
            get_transient(
                'tfsc_taxrel_v4_preview_' . get_current_user_id()
            );


        if (
            ! is_array( $preview ) ||
            empty( $preview['term_id'] ) ||
            empty( $preview['taxonomy'] ) ||
            ! taxonomy_exists(
                $preview['taxonomy']
            )
        ) {
            return $cached = false;
        }


        $settings =
            get_post_meta(
                $object->ID,
                '_elementor_page_settings',
                true
            );


        $preview_type =
            is_array( $settings )
                ? ( $settings['preview_type'] ?? '' )
                : '';


        if (
            $preview_type !==
            'taxonomy/' . $preview['taxonomy']
        ) {
            return $cached = false;
        }


        $term =
            get_term(
                (int) $preview['term_id'],
                $preview['taxonomy']
            );


        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            return $cached = $term;
        }
    }


    return $cached = false;
}


/**
 * ============================================================
 * 3. HUIDIGE TERM POD
 * ============================================================
 */

function tfsc_taxrel_v4_current_pod() {

    static $resolved = false;
    static $pod      = false;


    if ( $resolved ) {
        return $pod;
    }


    $resolved = true;


    if (
        ! function_exists( 'pods' )
    ) {
        return false;
    }


    $term =
        tfsc_taxrel_v4_current_term();


    if ( ! $term ) {
        return false;
    }


    $pod =
        pods(
            $term->taxonomy,
            (int) $term->term_id
        );


    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        $pod = false;
    }


    return $pod;
}


/**
 * ============================================================
 * 4. RELATIONSHIP DATA NORMALISEREN
 * ============================================================
 */

function tfsc_taxrel_v4_normalize_relationship(
    $value,
    $fallback_taxonomy = ''
) {

    $groups = [];


    if ( empty( $value ) ) {
        return [];
    }


    if (
        is_numeric( $value ) ||
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }


    foreach (
        (array) $value
        as $relation
    ) {

        $term_id  = 0;
        $taxonomy = '';


        if ( is_array( $relation ) ) {

            $term_id =
                (int) (
                    $relation['term_id']
                    ?? $relation['pod_item_id']
                    ?? $relation['id']
                    ?? $relation['ID']
                    ?? 0
                );


            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

        } elseif ( is_object( $relation ) ) {

            $term_id =
                (int) (
                    $relation->term_id
                    ?? $relation->pod_item_id
                    ?? $relation->id
                    ?? $relation->ID
                    ?? 0
                );


            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

        } elseif ( is_numeric( $relation ) ) {

            $term_id =
                (int) $relation;
        }


        if ( ! $taxonomy ) {

            $taxonomy =
                sanitize_key(
                    $fallback_taxonomy
                );
        }


        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }


        $term =
            get_term(
                $term_id,
                $taxonomy
            );


        if (
            ! $term instanceof WP_Term ||
            is_wp_error( $term )
        ) {
            continue;
        }


        $groups[
            $taxonomy
        ][] =
            (int) $term_id;
    }


    foreach (
        $groups
        as $taxonomy => $ids
    ) {

        $groups[
            $taxonomy
        ] =
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }


    return array_filter(
        $groups
    );
}


/**
 * ============================================================
 * 5. ALLE ACTIEVE RELATIONSHIPS OP DE TERM
 * ============================================================
 */

function tfsc_taxrel_v4_relationship_groups() {

    static $cache = null;


    if ( null !== $cache ) {
        return $cache;
    }


    $cache = [];


    $pod =
        tfsc_taxrel_v4_current_pod();


    if ( ! $pod ) {
        return [];
    }


    $fields =
        $pod->fields();


    if (
        ! is_array( $fields )
    ) {
        return [];
    }


    foreach (
        $fields
        as $field_name => $field_data
    ) {

        if (
            0 !== strpos(
                $field_name,
                'relationship_'
            ) ||
            'relationship_vacature_button_url'
            === $field_name
        ) {
            continue;
        }


        $value =
            $pod->field(
                $field_name
            );


        if (
            empty( $value )
        ) {
            continue;
        }


        $fallback_taxonomy =
            sanitize_key(
                substr(
                    $field_name,
                    strlen(
                        'relationship_'
                    )
                )
            );


        $groups =
            tfsc_taxrel_v4_normalize_relationship(
                $value,
                $fallback_taxonomy
            );


        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $cache[
                $taxonomy
            ] =
                array_merge(
                    $cache[
                        $taxonomy
                    ]
                    ?? [],
                    $ids
                );
        }
    }


    foreach (
        $cache
        as $taxonomy => $ids
    ) {

        $cache[
            $taxonomy
        ] =
            array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            );
    }


    return array_filter(
        $cache
    );
}


/**
 * ============================================================
 * 6. OPEN VACATURES
 * ============================================================
 *
 * Zelfde match-logica als de combo Base:
 *
 * verschillende taxonomies = AND
 *
 * binnen taxonomy:
 * - kennisgebied = AND
 * - overige = IN / OR
 */

/**
 * Archieven: volledige relatie, daarna actieve taxonomy/term, anders alle open
 * fieldservicevacatures. Lijst en knop delen deze resolver. Alleen ID-probes
 * (LIMIT 1), met request-cache per term; geen permanente/verouderde cache.
 */
function tfsc_taxrel_v4_effective_relationship_groups() {
    static $cache = [];
    $term = tfsc_taxrel_v4_current_term();
    if ( ! $term instanceof WP_Term ) { return []; }
    $key = $term->taxonomy . ':' . $term->term_id;
    if ( array_key_exists( $key, $cache ) ) { return $cache[$key]; }
    $groups = tfsc_taxrel_v4_relationship_groups();
    if ( $groups && tfsc_taxrel_v4_vacancy_ids( $groups, 1 ) ) {
        return $cache[$key] = $groups;
    }
    $priority = array_unique( array_merge(
        ['functienaam', 'kennisgebied', 'functie-inhoud', 'bedrijfssector',
         'werkgebied', 'opleidingsniveau', 'studierichting', 'locatie'], array_keys($groups)
    ) );
    foreach ( $priority as $taxonomy ) {
        if ( empty($groups[$taxonomy]) || $taxonomy === tfsc_taxrel_v4_status_taxonomy() ) { continue; }
        $candidate = [$taxonomy => $groups[$taxonomy]];
        if ( count($groups) > 1 && tfsc_taxrel_v4_vacancy_ids($candidate, 1) ) {
            return $cache[$key] = $candidate;
        }
        if ( count($groups[$taxonomy]) < 2 ) { continue; }
        foreach ( $groups[$taxonomy] as $id ) {
            $candidate = [$taxonomy => [(int) $id]];
            if ( tfsc_taxrel_v4_vacancy_ids($candidate, 1) ) { return $cache[$key] = $candidate; }
        }
    }
    return $cache[$key] = [];
}

function tfsc_taxrel_v4_vacancy_ids(
    $groups, $limit = -1
) {

    static $cache = [];
    $limit = 1 === (int) $limit ? 1 : -1;


    if (
        ! taxonomy_exists( tfsc_taxrel_v4_status_taxonomy() )
    ) {
        return [];
    }


    $cache_key =
        md5(
            serialize( [ $groups, $limit ] )
        );


    if (
        isset(
            $cache[
                $cache_key
            ]
        )
    ) {
        return $cache[
            $cache_key
        ];
    }


    $tax_query = [
        'relation' =>
            'AND',
    ];


    foreach (
        $groups
        as $taxonomy => $ids
    ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $ids
        ) {
            continue;
        }


        $ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $ids
                        )
                    )
                )
            );


        if ( ! $ids ) {
            continue;
        }


        /**
         * Zelfde centrale match-logica als Base.
         */
        $method =
            function_exists(
                'tfsc_get_combo_taxonomy_match_method'
            )
                ? tfsc_get_combo_taxonomy_match_method(
                    $taxonomy
                )
                : (
                    'kennisgebied' === $taxonomy
                        ? 'AND'
                        : 'OR'
                );


        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $ids,

            'operator' =>
                (
                    'AND' === $method &&
                    count( $ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                false,
        ];
    }


    if (
        count( $tax_query ) <= 1 && ! empty( $groups )
    ) {
        return [];
    }


    $status_taxonomy =
        tfsc_taxrel_v4_status_taxonomy();


    if (
        taxonomy_exists(
            $status_taxonomy
        )
    ) {

        $tax_query[] = [
            'taxonomy' =>
                $status_taxonomy,

            'field' =>
                'slug',

            'terms' => [
                tfsc_taxrel_v4_open_status(),
            ],

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    $ids =
        get_posts(
            [
                'post_type' =>
                    tfsc_taxrel_v4_vacancy_post_type(),

                'post_status' =>
                    'publish',

                'posts_per_page' =>
                    $limit,
                'update_post_meta_cache' => false,
                'update_post_term_cache' => false,

                'fields' =>
                    'ids',

                'no_found_rows' =>
                    true,

                'tax_query' =>
                    $tax_query,
            ]
        );


    return $cache[
        $cache_key
    ] =
        array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );
}


/**
 * ============================================================
 * 7. TARGET TERMS
 * ============================================================
 */

function tfsc_taxrel_v4_target_terms(
    $vacancy_ids,
    $taxonomy
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }


    $ids =
        wp_get_object_terms(
            array_map(
                'intval',
                $vacancy_ids
            ),
            $taxonomy,
            [
                'fields' =>
                    'ids',
            ]
        );


    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }


    $ids =
        array_map(
            'intval',
            $ids
        );


    if (
        is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        foreach (
            $ids
            as $term_id
        ) {

            $ids =
                array_merge(
                    $ids,
                    get_ancestors(
                        $term_id,
                        $taxonomy,
                        'taxonomy'
                    )
                );
        }
    }


    return array_values(
        array_unique(
            array_map(
                'intval',
                $ids
            )
        )
    );
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 */

function tfsc_taxrel_v4_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( ! $ids ) {
        return [];
    }


    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return (
            0 === (int) $level
        )
            ? array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            )
            : [];
    }


    return array_values(
        array_filter(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            ),
            function(
                $term_id
            ) use (
                $taxonomy,
                $level
            ) {

                return (
                    count(
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    )
                    ===
                    (int) $level
                );
            }
        )
    );
}


/**
 * ============================================================
 * 9. QUERY ID
 * ============================================================
 */

function tfsc_taxrel_v4_parse_query_id(
    $query_id
) {

    if (
        ! preg_match(
            '/^archive_relationship_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }


    return (int)
        $matches[1];
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings[
                'term_taxonomy_id'
            ]
            ??
            $settings[
                'post_taxonomy_term_taxonomy_id'
            ]
            ??
            '';


        $level =
            tfsc_taxrel_v4_parse_query_id(
                $query_id
            );


        if (
            false === $level ||
            ! tfsc_taxrel_v4_current_term()
        ) {
            return $args;
        }


        $taxonomy =
            $args['taxonomy']
            ??
            $settings[
                'post_taxonomy_query_post_type'
            ]
            ??
            '';


        if (
            is_array( $taxonomy )
        ) {
            $taxonomy =
                reset(
                    $taxonomy
                );
        }


        $taxonomy =
            sanitize_key(
                $taxonomy
            );


        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy ) ||
            $taxonomy ===
                tfsc_taxrel_v4_status_taxonomy()
        ) {
            return $args;
        }


        $groups =
            tfsc_taxrel_v4_effective_relationship_groups();


        $vacancy_ids =
            tfsc_taxrel_v4_vacancy_ids(
                $groups
            );


        $target_ids =
            tfsc_taxrel_v4_target_terms(
                $vacancy_ids,
                $taxonomy
            );


        $target_ids =
            tfsc_taxrel_v4_filter_level(
                $target_ids,
                $taxonomy,
                $level
            );


        if (
            ! $target_ids
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        unset(
            $args[
                'term_taxonomy_id'
            ]
        );


        $args['taxonomy'] =
            $taxonomy;

        $args['include'] =
            $target_ids;

        $args['hide_empty'] =
            false;

        $args['hierarchical'] =
            false;


        /**
         * Marker voor sortering.
         */
        $args[
            'tfsc_taxrel_v4'
        ] = 1;


        /**
         * Alleen deze target-taxonomy krijgt combo-links.
         */
        $GLOBALS[
            'tfsc_taxrel_v4_active_targets'
        ][ $taxonomy ] =
            true;


        return $args;
    },
    40,
    3
);


/**
 * ============================================================
 * 11. SORTERING OP NAAM
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty(
                $args[
                    'tfsc_taxrel_v4'
                ]
            ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }


        if (
            isset(
                $args['orderby']
            ) &&
            'name' !==
                strtolower(
                    (string)
                    $args['orderby']
                )
        ) {
            return $terms;
        }


        $order =
            strtoupper(
                (string) (
                    $args['order']
                    ?? 'ASC'
                )
            );


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }


                $compare =
                    strnatcasecmp(
                        remove_accents(
                            $a->name
                        ),
                        remove_accents(
                            $b->name
                        )
                    );


                return (
                    'DESC' === $order
                )
                    ? -$compare
                    : $compare;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 12. TERM PATH
 * ============================================================
 */

function tfsc_taxrel_v4_term_path(
    $term
) {

    if (
        ! $term instanceof WP_Term
    ) {
        return '';
    }


    $slugs =
        [];


    if (
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
    ) {

        foreach (
            array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            )
            as $ancestor_id
        ) {

            $ancestor =
                get_term(
                    $ancestor_id,
                    $term->taxonomy
                );


            if (
                $ancestor instanceof WP_Term &&
                ! is_wp_error(
                    $ancestor
                )
            ) {

                $slugs[] =
                    $ancestor->slug;
            }
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 13. COMBO URL
 * ============================================================
 *
 * URL-logica voorlopig bewust lokaal behouden.
 *
 * Alle actieve relationships
 * +
 * aangeklikte target term.
 */

function tfsc_taxrel_v4_combo_url(
    $target_term = null
) {

    $groups =
        tfsc_taxrel_v4_effective_relationship_groups();


    if (
        ! $groups && ! $target_term instanceof WP_Term
    ) {
        return false;
    }


    $parts = [
        tfsc_taxrel_v4_combo_base(),
    ];


    foreach (
        $groups
        as $taxonomy => $ids
    ) {

        foreach (
            $ids
            as $term_id
        ) {

            /**
             * Exact dezelfde target term
             * niet dubbel opnemen.
             */
            if (
                $target_term instanceof WP_Term &&
                $taxonomy ===
                    $target_term->taxonomy &&
                (int) $term_id ===
                    (int) $target_term->term_id
            ) {
                continue;
            }


            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }


            $path =
                tfsc_taxrel_v4_term_path(
                    $term
                );


            if (
                '' === $path
            ) {
                continue;
            }


            $parts[] =
                $taxonomy;

            $parts[] =
                $path;
        }
    }


    if (
        $target_term instanceof WP_Term
    ) {

        $target_path =
            tfsc_taxrel_v4_term_path(
                $target_term
            );


        if (
            '' === $target_path
        ) {
            return false;
        }


        $parts[] =
            $target_term->taxonomy;

        $parts[] =
            $target_path;
    }


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                static fn( $part ) =>
                    trim(
                        $part,
                        '/'
                    ),
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 14. TERM LINKS → COMBO URL
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! tfsc_taxrel_v4_current_term()
        ) {
            return $termlink;
        }


        if (
            empty(
                $GLOBALS[
                    'tfsc_taxrel_v4_active_targets'
                ][ $taxonomy ]
            )
        ) {
            return $termlink;
        }


        $url =
            tfsc_taxrel_v4_combo_url(
                $term
            );


        return $url
            ?: $termlink;
    },
    40,
    3
);

/**
 * TFSC - Generic Derived Relationship Taxonomy Terms
 * Version 3.1 - Match Logic Synced With Combo Base
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Toont in een Elementor Taxonomy Loop de taxonomy-terms die
 * voorkomen binnen OPEN vacatures die overeenkomen met alle
 * actieve Pods relationship_ velden van de huidige CPT/post.
 *
 *
 * ============================================================
 * ELEMENTOR
 * ============================================================
 *
 * Elementor Source bepaalt de taxonomy.
 *
 * Voorbeeld:
 *
 * Source:
 * locatie
 *
 * Query ID:
 * relationship_level_1
 *
 *
 * Of:
 *
 * Source:
 * kennisgebied
 *
 * Query ID:
 * relationship_level_0
 *
 *
 * De taxonomy hoeft dus NIET meer in de Query ID te staan.
 *
 *
 * ============================================================
 * RELATIONSHIP LOGICA
 * ============================================================
 *
 * Verschillende taxonomies:
 * AND
 *
 * Binnen dezelfde taxonomy:
 *
 * kennisgebied
 * → AND
 *
 * overige taxonomies
 * → IN / OR
 *
 *
 * ============================================================
 * UITGESLOTEN FIELD
 * ============================================================
 *
 * relationship_vacature_button_url
 *
 * wordt nooit gebruikt om vacatures te filteren.
 *
 *
 * ============================================================
 * LEVEL
 * ============================================================
 *
 * relationship_level_0
 * → alleen top-level terms
 *
 * relationship_level_1
 * → exact één ancestor
 *
 * relationship_level_2
 * → exact twee ancestors
 *
 * Elementor Filter by Depth kan UIT blijven.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_derived_rel_v3_vacancy_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_derived_rel_v3_status_taxonomy() {

    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}


function tfsc_derived_rel_v3_open_status() {

    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


function tfsc_derived_rel_v3_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. CPT / POST CONTEXT
 * ============================================================
 */

function tfsc_derived_rel_v3_get_context_post_id() {

    static $resolved = null;

    if ( null !== $resolved ) {
        return $resolved;
    }

    $resolved = 0;
    $object   = get_queried_object();


    /**
     * Normale frontend.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' !== get_post_type( $object->ID )
    ) {
        return $resolved = (int) $object->ID;
    }


    /**
     * Elementor Theme Builder.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' === get_post_type( $object->ID )
    ) {

        $template_id = (int) $object->ID;

        if (
            did_action( 'elementor/loaded' ) &&
            class_exists( '\Elementor\Plugin' )
        ) {
            try {

                $document =
                    \Elementor\Plugin::$instance
                        ->documents
                        ->get( $template_id );

                if ( $document ) {

                    $preview_id = absint(
                        $document->get_settings(
                            'preview_id'
                        )
                    );

                    if (
                        $preview_id &&
                        'elementor_library' !==
                        get_post_type( $preview_id )
                    ) {
                        return $resolved = $preview_id;
                    }
                }

            } catch ( Throwable $e ) {
                // Meta fallback hieronder.
            }
        }


        $settings = get_post_meta(
            $template_id,
            '_elementor_page_settings',
            true
        );

        if (
            is_array( $settings ) &&
            ! empty( $settings['preview_id'] )
        ) {

            $preview_id =
                absint(
                    $settings['preview_id']
                );

            if (
                $preview_id &&
                'elementor_library' !==
                get_post_type( $preview_id )
            ) {
                return $resolved = $preview_id;
            }
        }
    }


    /**
     * WordPress / Elementor preview fallback.
     */
    if ( ! empty( $_GET['preview_id'] ) ) {

        $preview_id = absint(
            wp_unslash(
                $_GET['preview_id']
            )
        );

        if (
            $preview_id &&
            'elementor_library' !==
            get_post_type( $preview_id )
        ) {
            return $resolved = $preview_id;
        }
    }


    /**
     * Laatste fallback.
     */
    global $post;

    if (
        $post instanceof WP_Post &&
        'elementor_library' !==
        get_post_type( $post->ID )
    ) {
        return $resolved = (int) $post->ID;
    }


    return 0;
}


/**
 * ============================================================
 * 3. HUIDIGE POD
 * ============================================================
 */

function tfsc_derived_rel_v3_get_current_pod() {

    static $resolved = false;
    static $pod      = false;

    if ( $resolved ) {
        return $pod;
    }

    $resolved = true;

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $post_id =
        tfsc_derived_rel_v3_get_context_post_id();

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        $pod = false;
    }

    return $pod;
}


/**
 * ============================================================
 * 4. RAW RELATIONSHIP NORMALISEREN
 * ============================================================
 */

function tfsc_derived_rel_v3_normalize_relationship(
    $value
) {

    if ( empty( $value ) ) {
        return [];
    }


    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }


    if ( ! is_array( $value ) ) {
        return [];
    }


    $result = [];


    foreach ( $value as $relation ) {

        $taxonomy = '';
        $term_id  = 0;


        if ( is_array( $relation ) ) {

            $taxonomy = sanitize_key(
                $relation['taxonomy']
                ?? ''
            );

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

        } elseif ( is_object( $relation ) ) {

            $taxonomy = sanitize_key(
                $relation->taxonomy
                ?? ''
            );

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

        } else {

            continue;
        }


        if (
            ! $taxonomy ||
            ! $term_id ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }


        $term = get_term(
            $term_id,
            $taxonomy
        );


        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {

            $result[] = [
                'taxonomy' => $taxonomy,
                'term_id'  => $term_id,
            ];
        }
    }


    return $result;
}


/**
 * ============================================================
 * 5. ALLE ACTIEVE RELATIONSHIPS
 * ============================================================
 */

function tfsc_derived_rel_v3_relationship_groups() {

    static $cache = null;

    if ( null !== $cache ) {
        return $cache;
    }

    $cache = [];

    $pod =
        tfsc_derived_rel_v3_get_current_pod();

    if ( ! $pod ) {
        return [];
    }


    $fields =
        $pod->fields();

    if (
        ! is_array( $fields ) ||
        ! $fields
    ) {
        return [];
    }


    foreach (
        $fields
        as $field_name => $definition
    ) {

        if (
            ! is_string( $field_name ) ||
            0 !== strpos(
                $field_name,
                'relationship_'
            ) ||
            'relationship_vacature_button_url'
            ===
            $field_name
        ) {
            continue;
        }


        $value =
            $pod->field(
                $field_name
            );


        $relationships =
            tfsc_derived_rel_v3_normalize_relationship(
                $value
            );


        foreach (
            $relationships
            as $relationship
        ) {

            $cache[
                $relationship['taxonomy']
            ][] =
                (int)
                $relationship['term_id'];
        }
    }


    /**
     * Dubbelen verwijderen.
     */
    foreach (
        $cache
        as $taxonomy => $ids
    ) {

        $ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            )
        );


        if ( $ids ) {

            $cache[ $taxonomy ] =
                $ids;

        } else {

            unset(
                $cache[ $taxonomy ]
            );
        }
    }


    return $cache;
}


/**
 * ============================================================
 * 6. OPEN VACATURES OP BASIS VAN ALLE RELATIONSHIPS
 * ============================================================
 *
 * Zelfde match-logica als de Combo Base.
 *
 * Verschillende taxonomies = AND.
 *
 * Binnen dezelfde taxonomy:
 *
 * kennisgebied = AND
 * overige = IN / OR
 */

function tfsc_derived_rel_v3_get_vacancy_ids(
    $relationship_groups
) {

    static $cache = [];

    if ( empty( $relationship_groups ) ) {
        return [];
    }


    /**
     * Stabiele cache-key.
     */
    ksort(
        $relationship_groups
    );

    foreach (
        $relationship_groups
        as &$ids
    ) {

        $ids = array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );

        sort( $ids );
    }

    unset( $ids );


    $key = md5(
        serialize(
            $relationship_groups
        )
    );


    if ( isset( $cache[ $key ] ) ) {
        return $cache[ $key ];
    }


    $post_type =
        tfsc_derived_rel_v3_vacancy_post_type();


    if ( ! post_type_exists( $post_type ) ) {
        return [];
    }


    $tax_query = [
        'relation' => 'AND',
    ];


    foreach (
        $relationship_groups
        as $taxonomy => $term_ids
    ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $term_ids
        ) {
            continue;
        }


        $term_ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );


        if ( ! $term_ids ) {
            continue;
        }


        /**
         * Match-methode uit de Combo Base gebruiken.
         *
         * Fallback:
         * kennisgebied = AND
         * overige = OR
         */
        $method =
            function_exists(
                'tfsc_get_combo_taxonomy_match_method'
            )
                ? tfsc_get_combo_taxonomy_match_method(
                    $taxonomy
                )
                : (
                    'kennisgebied' === $taxonomy
                        ? 'AND'
                        : 'OR'
                );


        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                false,
        ];
    }


    /**
     * Geen bruikbare relationship-query.
     */
    if ( count( $tax_query ) <= 1 ) {
        return [];
    }


    /**
     * Alleen OPEN vacatures.
     */
    $status_taxonomy =
        tfsc_derived_rel_v3_status_taxonomy();


    if ( taxonomy_exists( $status_taxonomy ) ) {

        $tax_query[] = [
            'taxonomy' =>
                $status_taxonomy,

            'field' =>
                'slug',

            'terms' => [
                tfsc_derived_rel_v3_open_status(),
            ],

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    $ids = get_posts( [
        'post_type' =>
            $post_type,

        'post_status' =>
            'publish',

        'posts_per_page' =>
            -1,

        'fields' =>
            'ids',

        'no_found_rows' =>
            true,

        'suppress_filters' =>
            false,

        'tax_query' =>
            $tax_query,
    ] );


    return $cache[ $key ] =
        array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );
}


/**
 * ============================================================
 * 7. TARGET TERMS UIT VACATURES
 * ============================================================
 */

function tfsc_derived_rel_v3_get_target_term_ids(
    $vacancy_ids,
    $taxonomy
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }


    $ids = wp_get_object_terms(
        array_map(
            'intval',
            $vacancy_ids
        ),
        $taxonomy,
        [
            'fields' => 'ids',
        ]
    );


    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }


    $ids =
        array_map(
            'intval',
            $ids
        );


    if (
        is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        foreach ( $ids as $id ) {

            $ids = array_merge(
                $ids,
                get_ancestors(
                    $id,
                    $taxonomy,
                    'taxonomy'
                )
            );
        }
    }


    return array_values(
        array_unique(
            array_filter(
                array_map(
                    'intval',
                    $ids
                )
            )
        )
    );
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 */

function tfsc_derived_rel_v3_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( ! $ids ) {
        return [];
    }


    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return 0 === (int) $level
            ? array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            )
            : [];
    }


    return array_values(
        array_filter(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            ),
            function( $id ) use (
                $taxonomy,
                $level
            ) {

                return count(
                    get_ancestors(
                        $id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === (int) $level;
            }
        )
    );
}


/**
 * ============================================================
 * 9. QUERY ID
 * ============================================================
 */

function tfsc_derived_rel_v3_parse_query_id(
    $query_id
) {

    if (
        ! preg_match(
            '/^relationship_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }


    return [
        'level' =>
            (int) $matches[1],
    ];
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings[
                'post_taxonomy_term_taxonomy_id'
            ]
            ??
            '';


        $parsed =
            tfsc_derived_rel_v3_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        /**
         * Elementor Source = target taxonomy.
         */
        $taxonomy =
            $args['taxonomy']
            ??
            $settings[
                'post_taxonomy_query_post_type'
            ]
            ??
            '';


        if ( is_array( $taxonomy ) ) {
            $taxonomy =
                reset(
                    $taxonomy
                );
        }


        $taxonomy =
            sanitize_key(
                $taxonomy
            );


        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy ) ||
            $taxonomy ===
            tfsc_derived_rel_v3_status_taxonomy()
        ) {
            return $args;
        }


        /**
         * Alle actieve relationship selections.
         */
        $relationship_groups =
            tfsc_derived_rel_v3_relationship_groups();


        if ( ! $relationship_groups ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /**
         * Alleen vacatures die voldoen aan de volledige
         * relationship-combinatie.
         */
        $vacancy_ids =
            tfsc_derived_rel_v3_get_vacancy_ids(
                $relationship_groups
            );


        if ( ! $vacancy_ids ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /**
         * Terms van Elementor Source uit deze vacatures.
         */
        $target_ids =
            tfsc_derived_rel_v3_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );


        /**
         * Exact level.
         */
        $target_ids =
            tfsc_derived_rel_v3_filter_level(
                $target_ids,
                $taxonomy,
                $parsed['level']
            );


        if ( ! $target_ids ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;

        $args['include'] =
            $target_ids;

        $args['hide_empty'] =
            false;

        $args['hierarchical'] =
            false;


        /**
         * Marker voor sorteerfix.
         */
        $args[
            'tfsc_derived_relationship_query'
        ] = 1;


        /**
         * Marker voor combo term-links.
         */
        $GLOBALS[
            'tfsc_derived_rel_v3_active_targets'
        ][ $taxonomy ] =
            true;


        return $args;
    },
    30,
    3
);


/**
 * ============================================================
 * 11. SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            is_admin() ||
            empty(
                $args[
                    'tfsc_derived_relationship_query'
                ]
            ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }


        if (
            isset( $args['orderby'] ) &&
            'name' !== strtolower(
                (string) $args['orderby']
            )
        ) {
            return $terms;
        }


        $order =
            strtoupper(
                (string) (
                    $args['order']
                    ?? 'ASC'
                )
            );


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {
            $order = 'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }


                $compare =
                    strnatcasecmp(
                        remove_accents(
                            wp_strip_all_tags(
                                $a->name
                            )
                        ),
                        remove_accents(
                            wp_strip_all_tags(
                                $b->name
                            )
                        )
                    );


                return 'DESC' === $order
                    ? -$compare
                    : $compare;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 12. TERMPAD
 * ============================================================
 */

function tfsc_derived_rel_v3_term_path(
    $term
) {

    if (
        ! $term instanceof WP_Term ||
        ! taxonomy_exists(
            $term->taxonomy
        )
    ) {
        return '';
    }


    $ids =
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
            ? array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            )
            : [];


    $slugs = [];


    foreach ( $ids as $id ) {

        $ancestor =
            get_term(
                $id,
                $term->taxonomy
            );


        if (
            $ancestor instanceof WP_Term &&
            ! is_wp_error( $ancestor )
        ) {
            $slugs[] =
                $ancestor->slug;
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 13. COMBO URL
 * ============================================================
 *
 * URL-logica bewust ongewijzigd behouden.
 */

function tfsc_derived_rel_v3_build_combo_url(
    $target_term
) {

    if (
        ! $target_term instanceof WP_Term
    ) {
        return false;
    }


    $groups =
        tfsc_derived_rel_v3_relationship_groups();


    if ( ! $groups ) {
        return false;
    }


    $parts = [
        tfsc_derived_rel_v3_combo_base(),
    ];


    /**
     * Alle actieve relationships toevoegen.
     */
    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        foreach (
            $term_ids
            as $term_id
        ) {

            /**
             * Exact dezelfde target-term niet dubbel toevoegen.
             */
            if (
                $taxonomy ===
                $target_term->taxonomy &&
                (int) $term_id ===
                (int) $target_term->term_id
            ) {
                continue;
            }


            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }


            $path =
                tfsc_derived_rel_v3_term_path(
                    $term
                );


            if ( ! $path ) {
                continue;
            }


            $parts[] =
                $taxonomy;

            $parts[] =
                $path;
        }
    }


    /**
     * Aangeklikte target term toevoegen.
     */
    $target_path =
        tfsc_derived_rel_v3_term_path(
            $target_term
        );


    if ( ! $target_path ) {
        return false;
    }


    $parts[] =
        $target_term->taxonomy;

    $parts[] =
        $target_path;


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                fn( $part ) =>
                    trim(
                        $part,
                        '/'
                    ),
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 14. TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! $taxonomy
        ) {
            return $termlink;
        }


        /**
         * Alleen CPT/post-context.
         */
        $object =
            get_queried_object();


        if (
            ! $object instanceof WP_Post
        ) {
            return $termlink;
        }


        if (
            $taxonomy ===
            tfsc_derived_rel_v3_status_taxonomy()
        ) {
            return $termlink;
        }


        /**
         * Alleen taxonomies die daadwerkelijk door deze
         * Elementor relationship-loop geactiveerd zijn.
         */
        if (
            empty(
                $GLOBALS[
                    'tfsc_derived_rel_v3_active_targets'
                ][ $taxonomy ]
            )
        ) {
            return $termlink;
        }


        $url =
            tfsc_derived_rel_v3_build_combo_url(
                $term
            );


        return $url
            ?: $termlink;
    },
    30,
    3
);

/**
 * TFSC - Vacancy Taxonomy Terms Loop
 * Version 1.1 - Base + Exact Level Query IDs
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Op een single vacature:
 *
 * huidige vacature
 * → Elementor Taxonomy Loop
 * → Elementor Source bepaalt taxonomy
 * → alleen terms tonen die aan deze vacature gekoppeld zijn
 * → optioneel exact taxonomy-level isoleren
 * → links wijzen naar TFSC vacature-archive URLs
 *
 *
 * ============================================================
 * ELEMENTOR QUERY IDS
 * ============================================================
 *
 * vacature_terms
 * → alle direct aan de vacature gekoppelde terms
 *
 * vacature_terms_level_0
 * → alleen terms met exact 0 ancestors
 *
 * vacature_terms_level_1
 * → alleen terms met exact 1 ancestor
 *
 * vacature_terms_level_2
 * → alleen terms met exact 2 ancestors
 *
 *
 * Elementor Source bepaalt volledig de taxonomy.
 *
 *
 * ============================================================
 * VOORBEELD LOCATIE
 * ============================================================
 *
 * Nederland
 * → level 0
 *
 * Zuid-Holland
 * → level 1
 *
 * Alphen aan den Rijn
 * → level 2
 *
 *
 * vacature_terms
 * → alle gekoppelde locatie-terms
 *
 * vacature_terms_level_2
 * → alleen Alphen aan den Rijn
 *
 *
 * ============================================================
 * URL STRUCTUUR
 * ============================================================
 *
 * Native:
 *
 * /locatie/nederland/zuid-holland/alphen-aan-den-rijn/
 *
 * Wordt:
 *
 * /vacatures/locatie/nederland/zuid-holland/alphen-aan-den-rijn/
 *
 *
 * Vlakke taxonomy:
 *
 * /vacatures/kennisgebied/elektrotechniek/
 *
 *
 * ============================================================
 * BELANGRIJK
 * ============================================================
 *
 * - Verandert NIET globaal alle term-links.
 * - Alleen terms uit deze specifieke Elementor-query worden
 *   aangepast.
 * - Elementor Source blijft leidend.
 * - Elementor eigen widgetinstellingen blijven zoveel mogelijk
 *   intact.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_vacancy_terms_v1_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_vacancy_terms_v1_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. HUIDIGE VACATURE
 * ============================================================
 *
 * Werkt op:
 *
 * - normale single vacature
 * - Elementor Theme Builder preview
 * - preview_id fallback
 */

function tfsc_vacancy_terms_v1_get_post_id() {

    static $resolved = null;


    if ( null !== $resolved ) {
        return $resolved;
    }


    $resolved = 0;

    $object =
        get_queried_object();


    /**
     * Normale vacature frontend.
     */
    if (
        $object instanceof WP_Post &&
        tfsc_vacancy_terms_v1_post_type()
            === get_post_type( $object->ID )
    ) {

        return $resolved =
            (int) $object->ID;
    }


    /**
     * Elementor Theme Builder preview.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library'
            === get_post_type( $object->ID )
    ) {

        $template_id =
            (int) $object->ID;


        if (
            did_action( 'elementor/loaded' ) &&
            class_exists( '\Elementor\Plugin' )
        ) {

            try {

                $document =
                    \Elementor\Plugin::$instance
                        ->documents
                        ->get( $template_id );


                if ( $document ) {

                    $preview_id =
                        absint(
                            $document->get_settings(
                                'preview_id'
                            )
                        );


                    if (
                        $preview_id &&
                        tfsc_vacancy_terms_v1_post_type()
                            === get_post_type( $preview_id )
                    ) {

                        return $resolved =
                            $preview_id;
                    }
                }

            } catch ( Throwable $e ) {
                // Meta fallback hieronder.
            }
        }


        $settings =
            get_post_meta(
                $template_id,
                '_elementor_page_settings',
                true
            );


        if (
            is_array( $settings ) &&
            ! empty( $settings['preview_id'] )
        ) {

            $preview_id =
                absint(
                    $settings['preview_id']
                );


            if (
                $preview_id &&
                tfsc_vacancy_terms_v1_post_type()
                    === get_post_type( $preview_id )
            ) {

                return $resolved =
                    $preview_id;
            }
        }
    }


    /**
     * WordPress / Elementor preview fallback.
     */
    if (
        ! empty( $_GET['preview_id'] )
    ) {

        $preview_id =
            absint(
                wp_unslash(
                    $_GET['preview_id']
                )
            );


        if (
            $preview_id &&
            tfsc_vacancy_terms_v1_post_type()
                === get_post_type( $preview_id )
        ) {

            return $resolved =
                $preview_id;
        }
    }


    /**
     * Laatste fallback.
     */
    global $post;


    if (
        $post instanceof WP_Post &&
        tfsc_vacancy_terms_v1_post_type()
            === get_post_type( $post->ID )
    ) {

        return $resolved =
            (int) $post->ID;
    }


    return 0;
}


/**
 * ============================================================
 * 3. QUERY ID PARSER
 * ============================================================
 *
 * vacature_terms
 *
 * vacature_terms_level_0
 * vacature_terms_level_1
 * vacature_terms_level_2
 */

function tfsc_vacancy_terms_v1_parse_query_id(
    $query_id
) {

    $query_id =
        (string) $query_id;


    /**
     * Base query.
     */
    if (
        'vacature_terms'
        === $query_id
    ) {

        return [
            'active' =>
                true,

            'level' =>
                null,
        ];
    }


    /**
     * Exact level query.
     */
    if (
        preg_match(
            '/^vacature_terms_level_([0-9]+)$/',
            $query_id,
            $matches
        )
    ) {

        return [
            'active' =>
                true,

            'level' =>
                (int) $matches[1],
        ];
    }


    return false;
}


/**
 * ============================================================
 * 4. EXACT LEVEL FILTER
 * ============================================================
 *
 * Niet-hiërarchische taxonomies hebben alleen level 0.
 */

function tfsc_vacancy_terms_v1_filter_level(
    $term_ids,
    $taxonomy,
    $level
) {

    if (
        null === $level
    ) {

        return array_values(
            array_unique(
                array_map(
                    'intval',
                    $term_ids
                )
            )
        );
    }


    if (
        ! $term_ids
    ) {

        return [];
    }


    /**
     * Vlakke taxonomy:
     *
     * level 0 = alles
     * hoger = niets
     */
    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return (
            0 === (int) $level
        )
            ? array_values(
                array_unique(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
            : [];
    }


    return array_values(
        array_filter(
            array_unique(
                array_map(
                    'intval',
                    $term_ids
                )
            ),
            function(
                $term_id
            ) use (
                $taxonomy,
                $level
            ) {

                return (
                    count(
                        get_ancestors(
                            $term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    )
                    ===
                    (int) $level
                );
            }
        )
    );
}


/**
 * ============================================================
 * 5. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 *
 * Elementor Source bepaalt taxonomy.
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings[
                'post_taxonomy_term_taxonomy_id'
            ]
            ??
            '';


        $parsed =
            tfsc_vacancy_terms_v1_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        $post_id =
            tfsc_vacancy_terms_v1_get_post_id();


        if ( ! $post_id ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /**
         * Elementor Source bepaalt taxonomy.
         */
        $taxonomy =
            $args['taxonomy']
            ??
            $settings[
                'post_taxonomy_query_post_type'
            ]
            ??
            '';


        if (
            is_array( $taxonomy )
        ) {

            $taxonomy =
                reset(
                    $taxonomy
                );
        }


        $taxonomy =
            sanitize_key(
                $taxonomy
            );


        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /**
         * Alleen terms die direct aan deze vacature hangen.
         */
        $term_ids =
            wp_get_object_terms(
                $post_id,
                $taxonomy,
                [
                    'fields' =>
                        'ids',
                ]
            );


        if (
            is_wp_error( $term_ids ) ||
            ! $term_ids
        ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        $term_ids =
            array_values(
                array_unique(
                    array_filter(
                        array_map(
                            'intval',
                            $term_ids
                        )
                    )
                )
            );


        /**
         * Exact level indien Query ID dit vraagt.
         */
        $term_ids =
            tfsc_vacancy_terms_v1_filter_level(
                $term_ids,
                $taxonomy,
                $parsed['level']
            );


        if ( ! $term_ids ) {

            $args['include'] =
                [ 0 ];

            return $args;
        }


        /**
         * Alleen geselecteerde vacatureterms tonen.
         */
        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;

        $args['include'] =
            $term_ids;

        $args['hide_empty'] =
            false;


        /**
         * Parent/child groepering door WP uitzetten.
         *
         * Exact level wordt hierboven al bepaald.
         */
        $args['hierarchical'] =
            false;


        /**
         * Marker voor sortering.
         */
        $args[
            'tfsc_vacancy_terms_v1'
        ] = 1;


        /**
         * Alleen exacte terms uit deze loop markeren
         * voor aangepaste term-links.
         */
        foreach (
            $term_ids
            as $term_id
        ) {

            $GLOBALS[
                'tfsc_vacancy_terms_v1_active_terms'
            ][ $taxonomy ][ $term_id ] =
                true;
        }


        return $args;
    },
    35,
    3
);


/**
 * ============================================================
 * 6. SORTERING
 * ============================================================
 *
 * Alleen deze loop.
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            empty(
                $args[
                    'tfsc_vacancy_terms_v1'
                ]
            ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {

            return $terms;
        }


        if (
            isset( $args['orderby'] ) &&
            'name'
                !== strtolower(
                    (string) $args['orderby']
                )
        ) {

            return $terms;
        }


        $order =
            strtoupper(
                (string) (
                    $args['order']
                    ?? 'ASC'
                )
            );


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {

            $order =
                'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {

                    return 0;
                }


                $compare =
                    strnatcasecmp(
                        remove_accents(
                            wp_strip_all_tags(
                                $a->name
                            )
                        ),
                        remove_accents(
                            wp_strip_all_tags(
                                $b->name
                            )
                        )
                    );


                return (
                    'DESC' === $order
                )
                    ? -$compare
                    : $compare;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 7. TERM PATH
 * ============================================================
 */

function tfsc_vacancy_terms_v1_term_path(
    $term
) {

    if (
        ! $term instanceof WP_Term ||
        ! taxonomy_exists(
            $term->taxonomy
        )
    ) {

        return '';
    }


    /**
     * Bestaande bewezen helper gebruiken indien beschikbaar.
     */
    if (
        function_exists(
            'tfsc_taxrel_v4_term_path'
        )
    ) {

        return tfsc_taxrel_v4_term_path(
            $term
        );
    }


    if (
        function_exists(
            'tfsc_derived_rel_v3_term_path'
        )
    ) {

        return tfsc_derived_rel_v3_term_path(
            $term
        );
    }


    $slugs =
        [];


    if (
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
    ) {

        $ancestor_ids =
            array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            );


        foreach (
            $ancestor_ids
            as $ancestor_id
        ) {

            $ancestor =
                get_term(
                    $ancestor_id,
                    $term->taxonomy
                );


            if (
                $ancestor instanceof WP_Term &&
                ! is_wp_error(
                    $ancestor
                )
            ) {

                $slugs[] =
                    $ancestor->slug;
            }
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 8. VACATURE ARCHIVE URL
 * ============================================================
 */

function tfsc_vacancy_terms_v1_archive_url(
    $term
) {

    if (
        ! $term instanceof WP_Term
    ) {

        return '';
    }


    $path =
        tfsc_vacancy_terms_v1_term_path(
            $term
        );


    if ( ! $path ) {
        return '';
    }


    return home_url(
        '/'
        .
        trim(
            tfsc_vacancy_terms_v1_combo_base(),
            '/'
        )
        .
        '/'
        .
        trim(
            $term->taxonomy,
            '/'
        )
        .
        '/'
        .
        trim(
            $path,
            '/'
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 9. TERM LINKS → VACATURE ARCHIVES
 * ============================================================
 *
 * Alleen exact gemarkeerde terms uit deze loop.
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        /**
         * Andere TFSC-snippets moeten native links
         * kunnen afdwingen.
         */
        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! $taxonomy
        ) {

            return $termlink;
        }


        /**
         * Alleen vacature-context.
         */
        if (
            ! tfsc_vacancy_terms_v1_get_post_id()
        ) {

            return $termlink;
        }


        /**
         * Alleen exacte terms uit vacature_terms-loop.
         */
        if (
            empty(
                $GLOBALS[
                    'tfsc_vacancy_terms_v1_active_terms'
                ][ $taxonomy ][ (int) $term->term_id ]
            )
        ) {

            return $termlink;
        }


        $url =
            tfsc_vacancy_terms_v1_archive_url(
                $term
            );


        return $url
            ?: $termlink;
    },
    35,
    3
);

/**
 * TFSC - Query Show More
 * Version 1.1 - Stable Item Heights
 *
 * Elementor widget class:
 * tfsc_query_show-more
 *
 * Custom attribute:
 * data_visible-items|8
 *
 * Werking:
 * - start met data_visible-items
 * - "Meer" toont telkens 20 extra items
 * - als alles zichtbaar is wordt knop "Minder"
 * - "Minder" reset naar originele hoeveelheid
 * - voorkomt dat Elementor Grid/Flex items steeds hoger maakt
 */

add_action(
    'wp_footer',
    function() {

        if ( is_admin() ) {
            return;
        }

        ?>
        <script>
        (function () {

            const STEP = 20;


            /**
             * ========================================================
             * INIT
             * ========================================================
             */

            function init(scope) {

                const root =
                    scope || document;

                const widgets = [];


                /**
                 * Scope zelf kan de widget zijn.
                 */
                if (
                    root.classList?.contains(
                        'tfsc_query_show-more'
                    )
                ) {
                    widgets.push(root);
                }


                /**
                 * Of widgets kunnen binnen scope zitten.
                 */
                if (root.querySelectorAll) {

                    widgets.push(
                        ...root.querySelectorAll(
                            '.tfsc_query_show-more'
                        )
                    );
                }


                widgets.forEach(
                    function(widget) {

                        /**
                         * Voorkom opnieuw initialiseren.
                         */
                        if (
                            widget.dataset
                                .tfscShowMoreInitialized
                            === '1'
                        ) {
                            return;
                        }


                        const loop =
                            widget.querySelector(
                                ':scope > .elementor-widget-container .elementor-loop-container'
                            );


                        if (!loop) {
                            return;
                        }


                        const items =
                            Array.from(
                                loop.querySelectorAll(
                                    ':scope > .e-loop-item'
                                )
                            );


                        if (!items.length) {
                            return;
                        }


                        widget.dataset
                            .tfscShowMoreInitialized =
                            '1';


                        /**
                         * Startaantal.
                         */
                        const initial =
                            parseInt(
                                widget.getAttribute(
                                    'data_visible-items'
                                ),
                                10
                            ) || 8;


                        let visibleCount =
                            Math.min(
                                initial,
                                items.length
                            );


                        /**
                         * ====================================================
                         * ITEMS RENDEREN
                         * ====================================================
                         *
                         * Eigen class gebruiken in plaats van inline display.
                         */

                        function renderItems() {

                            items.forEach(
                                function(
                                    item,
                                    index
                                ) {

                                    const visible =
                                        index <
                                        visibleCount;


                                    item.classList.toggle(
                                        'tfsc-query-show-more__item--hidden',
                                        !visible
                                    );


                                    item.setAttribute(
                                        'aria-hidden',
                                        visible
                                            ? 'false'
                                            : 'true'
                                    );
                                }
                            );
                        }


                        renderItems();


                        /**
                         * Geen knop nodig.
                         */
                        if (
                            items.length <=
                            initial
                        ) {
                            return;
                        }


                        /**
                         * ====================================================
                         * BUTTON
                         * ====================================================
                         */

                        const wrapper =
                            document.createElement(
                                'div'
                            );


                        wrapper.className =
                            'tfsc-query-show-more__wrapper';


                        wrapper.innerHTML = `
                            <button
                                type="button"
                                class="tfsc-query-show-more__button"
                                aria-expanded="false"
                            >
                                <span
                                    class="tfsc-query-show-more__label"
                                >
                                    Meer
                                </span>

                                <span
                                    class="tfsc-query-show-more__icon"
                                    aria-hidden="true"
                                ></span>
                            </button>
                        `;


                        loop.insertAdjacentElement(
                            'afterend',
                            wrapper
                        );


                        const button =
                            wrapper.querySelector(
                                '.tfsc-query-show-more__button'
                            );


                        const label =
                            wrapper.querySelector(
                                '.tfsc-query-show-more__label'
                            );


                        /**
                         * ====================================================
                         * CLICK
                         * ====================================================
                         */

                        button.addEventListener(
                            'click',
                            function() {

                                const allVisible =
                                    visibleCount >=
                                    items.length;


                                /**
                                 * ============================================
                                 * MINDER
                                 * ============================================
                                 */

                                if (allVisible) {

                                    visibleCount =
                                        Math.min(
                                            initial,
                                            items.length
                                        );


                                    renderItems();


                                    button.setAttribute(
                                        'aria-expanded',
                                        'false'
                                    );


                                    button.classList.remove(
                                        'tfsc-query-show-more__button--expanded'
                                    );


                                    label.textContent =
                                        'Meer';


                                    widget.scrollIntoView({
                                        behavior:
                                            'smooth',

                                        block:
                                            'start',
                                    });


                                    return;
                                }


                                /**
                                 * ============================================
                                 * MEER
                                 * ============================================
                                 */

                                visibleCount =
                                    Math.min(
                                        visibleCount +
                                        STEP,
                                        items.length
                                    );


                                renderItems();


                                const nowAllVisible =
                                    visibleCount >=
                                    items.length;


                                button.setAttribute(
                                    'aria-expanded',
                                    String(
                                        nowAllVisible
                                    )
                                );


                                button.classList.toggle(
                                    'tfsc-query-show-more__button--expanded',
                                    nowAllVisible
                                );


                                label.textContent =
                                    nowAllVisible
                                        ? 'Minder'
                                        : 'Meer';
                            }
                        );
                    }
                );
            }


            /**
             * ========================================================
             * NORMALE PAGINALOAD
             * ========================================================
             */

            document.addEventListener(
                'DOMContentLoaded',
                function() {

                    init(document);
                }
            );


            /**
             * ========================================================
             * ELEMENTOR
             * ========================================================
             */

            window.addEventListener(
                'elementor/frontend/init',
                function() {

                    if (
                        typeof elementorFrontend ===
                        'undefined'
                    ) {
                        return;
                    }


                    elementorFrontend.hooks.addAction(
                        'frontend/element_ready/global',
                        function(scope) {

                            init(
                                scope?.[0] ||
                                scope
                            );
                        }
                    );
                }
            );


            /**
             * ========================================================
             * AJAX / DYNAMISCH TOEGEVOEGDE CONTENT
             * ========================================================
             */

            new MutationObserver(
                function(mutations) {

                    mutations.forEach(
                        function(mutation) {

                            mutation.addedNodes.forEach(
                                function(node) {

                                    if (
                                        node.nodeType !==
                                        1
                                    ) {
                                        return;
                                    }


                                    init(node);
                                }
                            );
                        }
                    );
                }
            ).observe(
                document.documentElement,
                {
                    childList:
                        true,

                    subtree:
                        true,
                }
            );

        })();
        </script>


        <style>

        /**
         * ============================================================
         * LOOP HEIGHT / GRID FIX
         * ============================================================
         *
         * Belangrijk:
         *
         * voorkom dat Elementor/CSS Grid vrije verticale ruimte
         * over de grid-rijen verdeelt wanneer meer items zichtbaar
         * worden.
         */

        .tfsc_query_show-more
        .elementor-loop-container {
            align-content: start;
        }


        /**
         * Items zelf niet verticaal laten uitrekken.
         */
        .tfsc_query_show-more
        .elementor-loop-container
        > .e-loop-item {
            align-self: start;
            min-height: 0;
        }


        /**
         * Verborgen items volledig uit layout verwijderen.
         */
        .tfsc_query_show-more
        .elementor-loop-container
        > .e-loop-item.tfsc-query-show-more__item--hidden {
            display: none !important;
        }


        /**
         * ============================================================
         * BUTTON WRAPPER
         * ============================================================
         */

        .tfsc_query_show-more
        .tfsc-query-show-more__wrapper {
            width: 100%;
        }


        /**
         * ============================================================
         * BUTTON
         * ============================================================
         */

        .tfsc_query_show-more
        .tfsc-query-show-more__button {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            cursor: pointer;
        }


        /**
         * ============================================================
         * ICON
         * ============================================================
         */

        .tfsc_query_show-more
        .tfsc-query-show-more__icon {
            display: inline-block;

            width: 8px;
            height: 8px;

            border-right:
                2px solid currentColor;

            border-bottom:
                2px solid currentColor;

            transform:
                rotate(45deg)
                translateY(-2px);

            transition:
                transform 0.2s ease;
        }


        .tfsc_query_show-more
        .tfsc-query-show-more__button--expanded
        .tfsc-query-show-more__icon {
            transform:
                rotate(225deg)
                translateY(-2px);
        }

        </style>
        <?php
    },
    100
);

/**
 * TFSC - Base Taxonomies Related Posts
 *
 * Doel:
 * Toon op een virtuele taxonomy base archive alle posts
 * uit de in Elementor gekozen Source die minimaal één term
 * hebben binnen de actieve taxonomy.
 *
 * Voorbeeld:
 *
 * /beroepengids/functienamen/
 *
 * actieve taxonomy:
 * beroep_functienaam
 *
 * Elementor Source:
 * beroepengids
 *
 * resultaat:
 * alle beroepengids-posts die minimaal één
 * beroep_functienaam-term hebben.
 *
 * Elementor Query ID:
 *
 * base_taxonomies_related_posts
 */


/**
 * ============================================================
 * 1. ACTIEVE TAXONOMY BASE ARCHIVE
 * ============================================================
 */

function tfsc_base_taxonomies_related_posts_current_taxonomy() {

    if (
        ! function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {
        return '';
    }

    $taxonomy =
        tfsc_get_current_taxonomy_archive();

    if (
        is_object( $taxonomy ) &&
        ! empty( $taxonomy->name )
    ) {
        $taxonomy =
            $taxonomy->name;
    }

    $taxonomy =
        sanitize_key(
            (string) $taxonomy
        );

    if (
        ! $taxonomy ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return '';
    }

    return $taxonomy;
}


/**
 * ============================================================
 * 2. ELEMENTOR QUERY
 * ============================================================
 *
 * Query ID:
 * base_taxonomies_related_posts
 *
 * LET OP:
 * De Elementor Source blijft leidend.
 *
 * Deze query verandert dus NIET het post type.
 * Hij voegt alleen de actieve taxonomy base toe
 * als EXISTS-filter.
 */

add_action(
    'elementor/query/base_taxonomies_related_posts',
    function( $query ) {

        $taxonomy =
            tfsc_base_taxonomies_related_posts_current_taxonomy();

        if ( ! $taxonomy ) {

            $query->set(
                'post__in',
                [ 0 ]
            );

            return;
        }

        /**
         * Alleen posts tonen die minimaal één term
         * hebben binnen de actieve taxonomy.
         *
         * Het post type / de Source blijft volledig
         * door Elementor bepaald.
         */
        $query->set(
            'tax_query',
            [
                [
                    'taxonomy' =>
                        $taxonomy,

                    'operator' =>
                        'EXISTS',
                ],
            ]
        );
    },
    30
);

/**
 * TFSC - Combo Archive SEO + Native Archive Canonicals + Filter SEO
 * Version 4.4 - Phase 1: Maximaal 2 Taxonomieën
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * ============================================================
 * REGELT
 * ============================================================
 *
 * COMBO ARCHIVES
 * - SEO title
 * - Meta description
 * - Canonical
 * - Robots
 * - Correcte canonical voor /page/N/
 * - Correcte OpenGraph URL voor /page/N/
 * - Correcte CollectionPage schema URL voor /page/N/
 * - Correcte rel prev / next
 * - Centrale indexeringslogica voor SEO + sitemap
 *
 * INDEXERINGSLOGICA
 * - functienaam-combo: index/follow
 * - locatie-only combo: index/follow
 * - overige combo zonder functienaam: noindex/follow
 * - meer dan 2 taxonomies: noindex/follow
 * - minimaal 1 resultaat vereist
 *
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * - blijven bereikbaar
 * - index/follow
 * - functienaam → equivalente combo
 * - locatie → equivalente locatie-only combo
 * - overige taxonomies → legacy FSE-combo
 * - pagination blijft behouden
 *
 * SEARCH & FILTER URLS OP /vacatures/
 * - noindex, follow
 * - canonical naar schone /vacatures/
 */


/* ============================================================
 * CONFIG
 * ============================================================ */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {

    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}




if (
    ! defined(
        'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY'
    )
) {

    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY',
        'functienaam'
    );
}


if (
    ! defined(
        'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG'
    )
) {

    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG',
        'field-service-engineer'
    );
}


if (
    ! defined(
        'TFSC_COMBO_SEO_LOCATION_TAXONOMY'
    )
) {

    define(
        'TFSC_COMBO_SEO_LOCATION_TAXONOMY',
        'locatie'
    );
}


/* ============================================================
 * HUIDIGE PAGINA
 * ============================================================ */

function tfsc_combo_seo_get_paged() {

    return max(
        1,
        (int) get_query_var(
            'paged'
        )
    );
}


/* ============================================================
 * GELDIG COMBO ARCHIVE?
 * ============================================================ */

function tfsc_combo_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }


    if (
        ! function_exists(
            'tfsc_is_combo_archive'
        )
        ||
        ! function_exists(
            'tfsc_get_combo_archive'
        )
    ) {
        return false;
    }


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    return (
        false !==
        tfsc_get_combo_archive()
    );
}


/* ============================================================
 * COMBO VOLGORDE
 * ============================================================ */

function tfsc_combo_seo_order_combo(
    array $combo
) {

    $function = [];
    $others   = [];


    foreach (
        $combo
        as $item
    ) {

        if (
            ! empty(
                $item['taxonomy']
            )
            &&
            TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY
                ===
            $item['taxonomy']
        ) {

            $function[] =
                $item;

        } else {

            $others[] =
                $item;
        }
    }


    return array_merge(
        $function,
        $others
    );
}


/* ============================================================
 * COMBO ITEMS
 * ============================================================ */

function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];


    if ( $resolved ) {
        return $items;
    }


    $resolved =
        true;


    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return [];
    }


    $combo =
        tfsc_get_combo_archive();


    if (
        ! is_array(
            $combo
        )
    ) {
        return [];
    }


    $combo =
        tfsc_combo_seo_order_combo(
            $combo
        );


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['term']
            )
            ||
            ! $item['term']
                instanceof WP_Term
        ) {
            continue;
        }


        $name =
            trim(
                wp_strip_all_tags(
                    $item['term']->name
                )
            );


        if (
            '' === $name
        ) {
            continue;
        }


        $items[] = [
            'taxonomy' =>
                (string)
                $item['taxonomy'],

            'term_id' =>
                (int)
                $item['term']->term_id,

            'slug' =>
                (string)
                $item['term']->slug,

            'name' =>
                $name,
        ];
    }


    return $items;
}


/* ============================================================
 * AANTAL VERSCHILLENDE TAXONOMIES
 * ============================================================ */

function tfsc_combo_count_taxonomies(
    $combo = null
) {

    if (
        null === $combo
    ) {

        if (
            ! tfsc_combo_seo_is_active()
        ) {
            return 0;
        }


        $combo =
            tfsc_get_combo_archive();
    }


    if (
        ! is_array(
            $combo
        )
    ) {
        return 0;
    }


    $taxonomies =
        [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
        ) {
            continue;
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            '' === $taxonomy
        ) {
            continue;
        }


        $taxonomies[
            $taxonomy
        ] = true;
    }


    return count(
        $taxonomies
    );
}


/* ============================================================
 * HEEFT COMBO EEN FUNCTIENAAM?
