/* ============================================================
 * RESULTAAT-AANTAL HUIDIGE FRONTEND COMBO
 * ============================================================ */

function tfsc_combo_get_current_result_count() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return 0;
    }


    global $wp_query;


    if (
        ! $wp_query
            instanceof WP_Query
    ) {
        return 0;
    }


    return max(
        0,
        (int)
        $wp_query->found_posts
    );
}


/* ============================================================
 * CENTRALE INDEXERINGSSTATUS
 * ============================================================
 *
 * Regels:
 *
 * - combo met functienaam: toegestaan
 * - locatie-only combo: toegestaan
 * - overige combo zonder functienaam: noindex
 * - maximaal ingestelde aantal taxonomies
 * - frontend moet minimaal 1 resultaat hebben
 */

function tfsc_combo_get_index_status(
    $combo = null
) {

    $is_frontend_combo =
        null === $combo;


    if (
        $is_frontend_combo
    ) {

        if (
            ! tfsc_combo_seo_is_active()
        ) {

            return [
                'index' => false,
                'reason' => 'not_combo',
                'results' => 0,
                'taxonomies' => 0,
            ];
        }


        $combo =
            tfsc_get_combo_archive();
    }


    if (
        ! is_array(
            $combo
        )
        ||
        ! $combo
    ) {

        return [
            'index' => false,
            'reason' => 'invalid_combo',
            'results' => 0,
            'taxonomies' => 0,
        ];
    }


    $taxonomy_count =
        tfsc_combo_count_taxonomies(
            $combo
        );


    $max_taxonomies =
        function_exists( 'tfsc_combo_policy_max_taxonomies' )
            ? tfsc_combo_policy_max_taxonomies()
            : 2;


    if (
        $taxonomy_count
        >
        $max_taxonomies
    ) {

        return [
            'index' => false,
            'reason' => 'too_many_taxonomies',
            'results' => null,
            'taxonomies' => $taxonomy_count,
        ];
    }


    $has_function =
        tfsc_combo_has_function_name(
            $combo
        );


    $has_location =
        tfsc_combo_has_location(
            $combo
        );


    if (
        $taxonomy_count > 2
        &&
        (
            ! function_exists( 'tfsc_combo_policy_is_released' )
            ||
            ! tfsc_combo_policy_is_released( $combo )
        )
    ) {

        return [
            'index' => false,
            'reason' => 'not_released',
            'results' => null,
            'taxonomies' => $taxonomy_count,
        ];
    }


    $is_location_only =
        (
            1 === $taxonomy_count
            &&
            $has_location
        );


    if (
        ! $has_function
        &&
        ! $is_location_only
    ) {

        return [
            'index' => false,
            'reason' => 'no_function_name',
            'results' => null,
            'taxonomies' => $taxonomy_count,
        ];
    }


    if (
        $is_frontend_combo
    ) {

        $result_count =
            tfsc_combo_get_current_result_count();


        if (
            $result_count < 1
        ) {

            return [
                'index' => false,
                'reason' => 'no_results',
                'results' => $result_count,
                'taxonomies' => $taxonomy_count,
            ];
        }


        return [
            'index' => true,
            'reason' =>
                $is_location_only
                    ? 'valid_location_combo'
                    : 'valid_function_combo',

            'results' => $result_count,
            'taxonomies' => $taxonomy_count,
        ];
    }


    return [
        'index' => true,

        'reason' =>
            $is_location_only
                ? 'valid_sitemap_location_combo'
                : 'valid_sitemap_function_combo',

        'results' => null,
        'taxonomies' => $taxonomy_count,
    ];
}


/* ============================================================
 * CENTRALE TRUE/FALSE INDEXERINGSFUNCTIE
 * ============================================================ */

function tfsc_combo_should_index(
    $combo = null
) {

    $status =
        tfsc_combo_get_index_status(
            $combo
        );


    return ! empty(
        $status['index']
    );
}


/* ============================================================
 * SEO TITLE COMBO ARCHIVES
 * ============================================================ */

function tfsc_combo_seo_build_title() {

    $items =
        tfsc_combo_seo_get_items();


    if (
        ! $items
    ) {
        return '';
    }


    $function_names =
        [];

    $other_names =
        [];


    foreach (
        $items
        as $item
    ) {

        if (
            TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY
            ===
            $item['taxonomy']
        ) {

            if (
                ! in_array(
                    $item['name'],
                    $function_names,
                    true
                )
            ) {

                $function_names[] =
                    $item['name'];
            }


            continue;
        }


        if (
            ! in_array(
                $item['name'],
                $other_names,
                true
            )
        ) {

            $other_names[] =
                $item['name'];
        }
    }


    if (
        $function_names
    ) {

        $title =
            implode(
                ' ',
                $function_names
            )
            .
            ' vacatures';


        if (
            $other_names
        ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $other_names
                );
        }


        return trim(
            $title
        );
    }


    if (
        ! $other_names
    ) {
        return '';
    }


    return trim(
        'Field Service vacatures '
        .
        implode(
            ' ',
            $other_names
        )
    );
}


/* ============================================================
 * META DESCRIPTION COMBO ARCHIVES
 * ============================================================ */

function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();


    if (
        '' === $title
    ) {
        return '';
    }


    return sprintf(
        '%s bij %s.',
        $title,
        TFSC_COMBO_SEO_BRAND
    );
}


/* ============================================================
 * BASIS COMBO URL
 * ============================================================ */

function tfsc_combo_seo_build_base_url() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return '';
    }


    if (
        ! defined(
            'TFSC_COMBO_BASE'
        )
    ) {
        return '';
    }


    $combo =
        tfsc_get_combo_archive();


    if (
        ! is_array(
            $combo
        )
    ) {
        return '';
    }


    $combo =
        tfsc_combo_seo_order_combo(
            $combo
        );


    $segments =
        [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['path']
            )
            ||
            ! is_array(
                $item['path']
            )
        ) {
            return '';
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            '' === $taxonomy
        ) {
            return '';
        }


        $segments[] =
            $taxonomy;


        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term
                    instanceof WP_Term
                ||
                $term->taxonomy
                    !==
                $taxonomy
            ) {
                return '';
            }


            $segments[] =
                $term->slug;
        }
    }


    if (
        ! $segments
    ) {
        return '';
    }


    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


/* ============================================================
 * PAGINATED COMBO URL
 * ============================================================ */

function tfsc_combo_seo_build_page_url(
    $paged = 1
) {

    $base_url =
        tfsc_combo_seo_build_base_url();


    if (
        '' === $base_url
    ) {
        return '';
    }


    $paged =
        max(
            1,
            (int) $paged
        );


    if (
        1 === $paged
    ) {
        return $base_url;
    }


    return trailingslashit(
        $base_url
        .
        'page/'
        .
        $paged
    );
}


/* ============================================================
 * CANONICAL COMBO ARCHIVES
 * ============================================================ */

function tfsc_combo_seo_build_canonical() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return '';
    }


    return tfsc_combo_seo_build_page_url(
        tfsc_combo_seo_get_paged()
    );
}


/* ============================================================
 * CENTRAAL SEO OBJECT COMBO ARCHIVES
 * ============================================================ */

function tfsc_get_combo_seo() {

    static $resolved = false;
    static $seo      = false;


    if (
        $resolved
    ) {
        return $seo;
    }


    $resolved =
        true;


    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return false;
    }


    $title =
        tfsc_combo_seo_build_title();


    if (
        '' === $title
    ) {
        return false;
    }


    $index_status =
        tfsc_combo_get_index_status();


    $seo = [
        'title' =>
            $title,

        'description' =>
            tfsc_combo_seo_build_description(),

        'canonical' =>
            tfsc_combo_seo_build_canonical(),

        'index' =>
            ! empty(
                $index_status['index']
            ),

        'index_reason' =>
            $index_status['reason'],

        'results' =>
            $index_status['results'],

        'taxonomies' =>
            $index_status['taxonomies'],

        'paged' =>
            tfsc_combo_seo_get_paged(),
    ];


    return $seo;
}


/* ============================================================
 * COMBO MAX NUM PAGES
 * ============================================================ */

function tfsc_combo_seo_get_max_pages() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return 1;
    }


    global $wp_query;


    if (
        ! $wp_query
            instanceof WP_Query
    ) {
        return 1;
    }


    return max(
        1,
        (int)
        $wp_query->max_num_pages
    );
}


/* ============================================================
 * PREV URL
 * ============================================================ */

function tfsc_combo_seo_get_prev_url() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return '';
    }


    $paged =
        tfsc_combo_seo_get_paged();


    if (
        $paged <= 1
    ) {
        return '';
    }


    return tfsc_combo_seo_build_page_url(
        $paged - 1
    );
}


/* ============================================================
 * NEXT URL
 * ============================================================ */

function tfsc_combo_seo_get_next_url() {

    if (
        ! tfsc_combo_seo_is_active()
