/**
 * TFSC - Combo Archive SEO + Native Archive Canonicals + Filter SEO
 * Version 4.2 - Stable Legacy Combo + Pagination SEO
 *
 * Vereist:
 * - TFSC - Volledig dynamische vacature-archieven
 * - Rank Math SEO
 *
 * ============================================================
 * REGELT
 * ============================================================
 *
 * COMBO ARCHIVES
 * - SEO title
 * - Meta description
 * - Canonical
 * - Robots
 * - Correcte canonical voor /page/N/
 * - Correcte OpenGraph URL voor /page/N/
 * - Correcte CollectionPage schema URL voor /page/N/
 * - Correcte rel prev / next
 * - Centrale indexeringslogica voor SEO + sitemap
 *
 * NATIVE VACATURE TAXONOMY ARCHIVES
 * - blijven bereikbaar
 * - robots blijven door Rank Math / WordPress bepaald
 * - canonical naar equivalente combo archive
 * - pagination blijft behouden
 *
 * SEARCH & FILTER URLS OP /vacatures/
 * - noindex, follow
 * - canonical naar schone /vacatures/
 */


/* ============================================================
 * CONFIG
 * ============================================================ */

if ( ! defined( 'TFSC_COMBO_SEO_BRAND' ) ) {

    define(
        'TFSC_COMBO_SEO_BRAND',
        'The Field Service Company'
    );
}


if ( ! defined( 'TFSC_COMBO_SEO_MAX_TAXONOMIES' ) ) {

    define(
        'TFSC_COMBO_SEO_MAX_TAXONOMIES',
        3
    );
}


if (
    ! defined(
        'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY'
    )
) {

    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY',
        'functienaam'
    );
}


if (
    ! defined(
        'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG'
    )
) {

    define(
        'TFSC_NATIVE_CANONICAL_FUNCTION_SLUG',
        'field-service-engineer'
    );
}


/* ============================================================
 * HUIDIGE PAGINA
 * ============================================================
 */

function tfsc_combo_seo_get_paged() {

    return max(
        1,
        (int) get_query_var(
            'paged'
        )
    );
}


/* ============================================================
 * GELDIG COMBO ARCHIVE?
 * ============================================================ */

function tfsc_combo_seo_is_active() {

    if ( is_admin() ) {
        return false;
    }


    if (
        ! function_exists(
            'tfsc_is_combo_archive'
        )
        ||
        ! function_exists(
            'tfsc_get_combo_archive'
        )
    ) {
        return false;
    }


    if (
        ! tfsc_is_combo_archive()
    ) {
        return false;
    }


    return (
        false !==
        tfsc_get_combo_archive()
    );
}


/* ============================================================
 * COMBO VOLGORDE
 * ============================================================
 *
 * functienaam altijd eerst.
 *
 * De overige taxonomies behouden hun bestaande volgorde.
 */

function tfsc_combo_seo_order_combo(
    array $combo
) {

    $function = [];
    $others   = [];


    foreach (
        $combo
        as $item
    ) {

        if (
            ! empty(
                $item['taxonomy']
            )
            &&
            TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY
                ===
            $item['taxonomy']
        ) {

            $function[] =
                $item;

        } else {

            $others[] =
                $item;
        }
    }


    return array_merge(
        $function,
        $others
    );
}


/* ============================================================
 * COMBO ITEMS
 * ============================================================ */

function tfsc_combo_seo_get_items() {

    static $resolved = false;
    static $items    = [];


    if ( $resolved ) {
        return $items;
    }


    $resolved =
        true;


    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return [];
    }


    $combo =
        tfsc_get_combo_archive();


    if (
        ! is_array(
            $combo
        )
    ) {
        return [];
    }


    $combo =
        tfsc_combo_seo_order_combo(
            $combo
        );


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['term']
            )
            ||
            ! $item['term']
                instanceof WP_Term
        ) {
            continue;
        }


        $name =
            trim(
                wp_strip_all_tags(
                    $item['term']->name
                )
            );


        if (
            '' === $name
        ) {
            continue;
        }


        $items[] = [
            'taxonomy' =>
                (string)
                $item['taxonomy'],

            'term_id' =>
                (int)
                $item['term']->term_id,

            'slug' =>
                (string)
                $item['term']->slug,

            'name' =>
                $name,
        ];
    }


    return $items;
}


/* ============================================================
 * AANTAL VERSCHILLENDE TAXONOMIES
 * ============================================================ */

function tfsc_combo_count_taxonomies(
    $combo = null
) {

    if (
        null === $combo
    ) {

        if (
            ! tfsc_combo_seo_is_active()
        ) {
            return 0;
        }


        $combo =
            tfsc_get_combo_archive();
    }


    if (
        ! is_array(
            $combo
        )
    ) {
        return 0;
    }


    $taxonomies =
        [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
        ) {
            continue;
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            '' === $taxonomy
        ) {
            continue;
        }


        $taxonomies[
            $taxonomy
        ] = true;
    }


    return count(
        $taxonomies
    );
}


/* ============================================================
 * HEEFT COMBO EEN FUNCTIENAAM?
 * ============================================================ */

function tfsc_combo_has_function_name(
    $combo = null
) {

    if (
        null === $combo
    ) {

        if (
            ! tfsc_combo_seo_is_active()
        ) {
            return false;
        }


        $combo =
            tfsc_get_combo_archive();
    }


    if (
        ! is_array(
            $combo
        )
    ) {
        return false;
    }


    foreach (
        $combo
        as $item
    ) {

        if (
            ! empty(
                $item['taxonomy']
            )
            &&
            TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY
                ===
            $item['taxonomy']
        ) {
            return true;
        }
    }


    return false;
}


/* ============================================================
 * RESULTAAT-AANTAL HUIDIGE FRONTEND COMBO
 * ============================================================ */

function tfsc_combo_get_current_result_count() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return 0;
    }


    global $wp_query;


    if (
        ! $wp_query
            instanceof WP_Query
    ) {
        return 0;
    }


    return max(
        0,
        (int)
        $wp_query->found_posts
    );
}


/* ============================================================
 * CENTRALE INDEXERINGSSTATUS
 * ============================================================
 *
 * Regels:
 *
 * - functienaam verplicht
 * - maximaal ingestelde aantal taxonomies
 * - frontend moet minimaal 1 resultaat hebben
 *
 * Sitemap-combo's zijn al opgebouwd vanuit bestaande
 * open vacatures en hoeven daarom geen extra query.
 */

function tfsc_combo_get_index_status(
    $combo = null
) {

    $is_frontend_combo =
        null === $combo;


    if (
        $is_frontend_combo
    ) {

        if (
            ! tfsc_combo_seo_is_active()
        ) {

            return [
                'index' =>
                    false,

                'reason' =>
                    'not_combo',

                'results' =>
                    0,

                'taxonomies' =>
                    0,
            ];
        }


        $combo =
            tfsc_get_combo_archive();
    }


    if (
        ! is_array(
            $combo
        )
        ||
        ! $combo
    ) {

        return [
            'index' =>
                false,

            'reason' =>
                'invalid_combo',

            'results' =>
                0,

            'taxonomies' =>
                0,
        ];
    }


    $taxonomy_count =
        tfsc_combo_count_taxonomies(
            $combo
        );


    if (
        $taxonomy_count
        >
        TFSC_COMBO_SEO_MAX_TAXONOMIES
    ) {

        return [
            'index' =>
                false,

            'reason' =>
                'too_many_taxonomies',

            'results' =>
                null,

            'taxonomies' =>
                $taxonomy_count,
        ];
    }


    if (
        ! tfsc_combo_has_function_name(
            $combo
        )
    ) {

        return [
            'index' =>
                false,

            'reason' =>
                'no_function_name',

            'results' =>
                null,

            'taxonomies' =>
                $taxonomy_count,
        ];
    }


    if (
        $is_frontend_combo
    ) {

        $result_count =
            tfsc_combo_get_current_result_count();


        if (
            $result_count < 1
        ) {

            return [
                'index' =>
                    false,

                'reason' =>
                    'no_results',

                'results' =>
                    $result_count,

                'taxonomies' =>
                    $taxonomy_count,
            ];
        }


        return [
            'index' =>
                true,

            'reason' =>
                'valid_function_combo',

            'results' =>
                $result_count,

            'taxonomies' =>
                $taxonomy_count,
        ];
    }


    return [
        'index' =>
            true,

        'reason' =>
            'valid_sitemap_function_combo',

        'results' =>
            null,

        'taxonomies' =>
            $taxonomy_count,
    ];
}


/* ============================================================
 * CENTRALE TRUE/FALSE INDEXERINGSFUNCTIE
 * ============================================================
 *
 * Wordt ook door de sitemap gebruikt.
 */

function tfsc_combo_should_index(
    $combo = null
) {

    $status =
        tfsc_combo_get_index_status(
            $combo
        );


    return ! empty(
        $status['index']
    );
}


/* ============================================================
 * SEO TITLE COMBO ARCHIVES
 * ============================================================ */

function tfsc_combo_seo_build_title() {

    $items =
        tfsc_combo_seo_get_items();


    if (
        ! $items
    ) {
        return '';
    }


    $function_names =
        [];

    $other_names =
        [];


    foreach (
        $items
        as $item
    ) {

        if (
            TFSC_NATIVE_CANONICAL_FUNCTION_TAXONOMY
            ===
            $item['taxonomy']
        ) {

            if (
                ! in_array(
                    $item['name'],
                    $function_names,
                    true
                )
            ) {

                $function_names[] =
                    $item['name'];
            }


            continue;
        }


        if (
            ! in_array(
                $item['name'],
                $other_names,
                true
            )
        ) {

            $other_names[] =
                $item['name'];
        }
    }


    if (
        $function_names
    ) {

        $title =
            implode(
                ' ',
                $function_names
            )
            .
            ' vacatures';


        if (
            $other_names
        ) {

            $title .=
                ' '
                .
                implode(
                    ' ',
                    $other_names
                );
        }


        return trim(
            $title
        );
    }


    if (
        ! $other_names
    ) {
        return '';
    }


    return trim(
        'Field Service vacatures '
        .
        implode(
            ' ',
            $other_names
        )
    );
}


/* ============================================================
 * META DESCRIPTION COMBO ARCHIVES
 * ============================================================ */

function tfsc_combo_seo_build_description() {

    $title =
        tfsc_combo_seo_build_title();


    if (
        '' === $title
    ) {
        return '';
    }


    return sprintf(
        '%s bij %s.',
        $title,
        TFSC_COMBO_SEO_BRAND
    );
}


/* ============================================================
 * BASIS COMBO URL
 * ============================================================
 *
 * Bouwt de canonical combo URL zonder pagination.
 */

function tfsc_combo_seo_build_base_url() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return '';
    }


    if (
        ! defined(
            'TFSC_COMBO_BASE'
        )
    ) {
        return '';
    }


    $combo =
        tfsc_get_combo_archive();


    if (
        ! is_array(
            $combo
        )
    ) {
        return '';
    }


    $combo =
        tfsc_combo_seo_order_combo(
            $combo
        );


    $segments =
        [];


    foreach (
        $combo
        as $item
    ) {

        if (
            empty(
                $item['taxonomy']
            )
            ||
            empty(
                $item['path']
            )
            ||
            ! is_array(
                $item['path']
            )
        ) {
            return '';
        }


        $taxonomy =
            sanitize_key(
                $item['taxonomy']
            );


        if (
            '' === $taxonomy
        ) {
            return '';
        }


        $segments[] =
            $taxonomy;


        foreach (
            $item['path']
            as $term
        ) {

            if (
                ! $term
                    instanceof WP_Term
                ||
                $term->taxonomy
                    !==
                $taxonomy
            ) {
                return '';
            }


            $segments[] =
                $term->slug;
        }
    }


    if (
        ! $segments
    ) {
        return '';
    }


    $path =
        TFSC_COMBO_BASE
        .
        '/'
        .
        implode(
            '/',
            array_map(
                'rawurlencode',
                $segments
            )
        );


    return trailingslashit(
        home_url(
            '/' . $path
        )
    );
}


/* ============================================================
 * PAGINATED COMBO URL
 * ============================================================ */

function tfsc_combo_seo_build_page_url(
    $paged = 1
) {

    $base_url =
        tfsc_combo_seo_build_base_url();


    if (
        '' === $base_url
    ) {
        return '';
    }


    $paged =
        max(
            1,
            (int) $paged
        );


    if (
        1 === $paged
    ) {
        return $base_url;
    }


    return trailingslashit(
        $base_url
        .
        'page/'
        .
        $paged
    );
}


/* ============================================================
 * CANONICAL COMBO ARCHIVES
 * ============================================================
 *
 * Pagina 1:
 *
 * /vacatures/functienaam/field-service-engineer/
 *
 * Pagina 2:
 *
 * /vacatures/functienaam/field-service-engineer/page/2/
 */

function tfsc_combo_seo_build_canonical() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
