/* ============================================================
 * RANK MATH JSON-LD
 * ============================================================
 *
 * Zorgt dat CollectionPage en BreadcrumbList dezelfde
 * paginated URL gebruiken als canonical.
 */

function tfsc_combo_rankmath_json_ld(
    $data,
    $jsonld = null
) {

    if (
        ! tfsc_combo_seo_is_active()
        ||
        ! is_array(
            $data
        )
    ) {
        return $data;
    }


    $current_url =
        tfsc_combo_seo_build_canonical();


    $base_url =
        tfsc_combo_seo_build_base_url();


    if (
        '' === $current_url
        ||
        '' === $base_url
    ) {
        return $data;
    }


    foreach (
        $data
        as $key => &$entity
    ) {

        if (
            ! is_array(
                $entity
            )
        ) {
            continue;
        }


        $type =
            $entity['@type']
            ??
            '';


        /**
         * CollectionPage.
         */

        if (
            'CollectionPage'
            ===
            $type
        ) {

            $entity['url'] =
                $current_url;


            if (
                ! empty(
                    $entity['@id']
                )
            ) {

                $entity['@id'] =
                    $current_url
                    .
                    '#webpage';
            }


            if (
                isset(
                    $entity['breadcrumb']
                )
                &&
                is_array(
                    $entity['breadcrumb']
                )
                &&
                isset(
                    $entity['breadcrumb']['@id']
                )
            ) {

                $entity[
                    'breadcrumb'
                ][
                    '@id'
                ] =
                    $current_url
                    .
                    '#breadcrumb';
            }
        }


        /**
         * BreadcrumbList zelf.
         *
         * De breadcrumb ITEMS blijven hetzelfde.
         * Alleen de identifier van deze pagina verandert.
         */

        if (
            'BreadcrumbList'
            ===
            $type
        ) {

            $entity['@id'] =
                $current_url
                .
                '#breadcrumb';
        }
    }

    unset(
        $entity
    );


    return $data;
}


