/* ============================================================
 * CORRECTE COMBO PREV / NEXT
 * ============================================================
 *
 * Rank Math's standaard adjacent links gaan bij onze virtuele
 * combo archives uit van /vacatures/.
 *
 * Daarom schakelen we die alleen op combo archives uit
 * en schrijven we hier de correcte combo-links.
 */

function tfsc_combo_output_prev_next() {

    if (
        ! tfsc_combo_seo_is_active()
    ) {
        return;
    }


    $prev =
        tfsc_combo_seo_get_prev_url();


    $next =
        tfsc_combo_seo_get_next_url();


    if (
        '' !== $prev
    ) {

        echo '<link rel="prev" href="'
            .
            esc_url(
                $prev
            )
            .
            '" />'
            .
            "\n";
    }


    if (
        '' !== $next
    ) {

        echo '<link rel="next" href="'
            .
            esc_url(
                $next
            )
            .
            '" />'
            .
            "\n";
    }
}


/* ============================================================
 * RANK MATH FILTERS
 * ============================================================ */

add_action(
    'wp',
    function() {

        /* ----------------------------------------------------
         * COMBO ARCHIVE
         * ---------------------------------------------------- */

        if (
            tfsc_combo_seo_is_active()
        ) {

            add_filter(
                'rank_math/frontend/title',
                'tfsc_combo_rankmath_title',
                99
            );


            add_filter(
                'rank_math/frontend/description',
                'tfsc_combo_rankmath_description',
                99
            );


            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_combo_rankmath_canonical',
                99
            );


            add_filter(
                'rank_math/frontend/robots',
                'tfsc_combo_rankmath_robots',
                99
            );


            /**
             * OpenGraph URL.
             */
            add_filter(
                'rank_math/opengraph/url',
                'tfsc_combo_rankmath_og_url',
                99
            );


            /**
             * Extra specifieke Facebook OG URL fallback.
             */
            add_filter(
                'rank_math/opengraph/facebook/og_url',
                'tfsc_combo_rankmath_og_url',
                99
            );


            /**
             * Schema.
             */
            add_filter(
                'rank_math/json_ld',
                'tfsc_combo_rankmath_json_ld',
                99,
                2
            );


            /**
             * Rank Math standaard prev/next uitschakelen
             * voor deze virtuele combo archives.
             */
            add_filter(
                'rank_math/frontend/disable_adjacent_rel_links',
                '__return_true',
                99
            );


            /**
             * Zelf correcte combo prev/next schrijven.
             *
             * Priority 20: gewoon in wp_head.
             */
            add_action(
                'wp_head',
                'tfsc_combo_output_prev_next',
                20
            );


            return;
        }


        /* ----------------------------------------------------
         * SEARCH & FILTER RESULTAAT-URL
         * ---------------------------------------------------- */

        if (
            tfsc_vacancy_filter_seo_is_active()
        ) {

            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_vacancy_filter_rankmath_canonical',
                99
            );


            add_filter(
                'rank_math/frontend/robots',
                'tfsc_vacancy_filter_rankmath_robots',
                99
            );


            return;
        }


        /* ----------------------------------------------------
         * NATIVE VACATURE TAXONOMY ARCHIVE
         * ---------------------------------------------------- */

        if (
            tfsc_native_canonical_is_target()
        ) {

            add_filter(
                'rank_math/frontend/canonical',
                'tfsc_native_rankmath_canonical',
                99
            );
        }
    },
    20
);

/**
 * TFSC - Rank Math breadcrumbs
 *
 * Custom breadcrumb-logica uitsluitend voor:
 *
 * 1. Beroepengids taxonomy base archives
 * 2. Native vacature taxonomy term archives
 *
 * Alle andere taxonomies, CPT archives en singulars
 * blijven volledig aan Rank Math overgelaten.
 */

add_filter(
    'rank_math/frontend/breadcrumb/items',
    function( $crumbs, $class ) {

        /**
         * ====================================================
         * 1. BEROEPENGIDS TAXONOMY BASE ARCHIVES
         * ====================================================
         *
         * Dit is bewust een uitzondering.
         *
         * Alleen taxonomy base archives van de beroepengids
         * krijgen hier een zelf opgebouwde breadcrumb.
         *
         * Bijvoorbeeld:
         * beroep_functienaam
         */

        $base_taxonomy =
            get_query_var(
                'tfsc_taxonomy_archive'
            );

        if (
            $base_taxonomy &&
            taxonomy_exists( $base_taxonomy )
        ) {

            $base_taxonomy =
                sanitize_key(
                    $base_taxonomy
                );

            /**
             * Alleen beroepengids taxonomies.
             *
             * Alle andere taxonomy base archives
             * blijven ongemoeid.
             */
            $is_beroepengids_taxonomy =
                0 === strpos(
                    $base_taxonomy,
                    'beroep_'
                )
                ||
                0 === strpos(
                    $base_taxonomy,
                    'beroepengids_'
                );

            if ( ! $is_beroepengids_taxonomy ) {
                return $crumbs;
            }

            $taxonomy =
                get_taxonomy(
                    $base_taxonomy
                );

            if (
                ! $taxonomy ||
                empty( $taxonomy->rewrite['slug'] )
            ) {
                return $crumbs;
            }

            $segments =
                array_values(
                    array_filter(
                        explode(
                            '/',
                            trim(
                                (string) $taxonomy->rewrite['slug'],
                                '/'
                            )
                        )
                    )
                );

            if ( ! $segments ) {
                return $crumbs;
            }

            $result = [];

            /**
             * Home.
             */
            if ( ! empty( $crumbs[0] ) ) {
                $result[] = $crumbs[0];
            }

            $current = '';
            $last =
                count( $segments ) - 1;

            foreach (
                $segments
                as $index => $segment
            ) {

                $current .=
                    '/' . $segment;

                $label =
                    $index === $last
                        ? (
                            $taxonomy->labels->name
                            ?? ucfirst(
                                str_replace(
                                    [ '-', '_' ],
                                    ' ',
                                    $segment
                                )
                            )
                        )
                        : ucfirst(
                            str_replace(
                                [ '-', '_' ],
                                ' ',
                                $segment
                            )
                        );

                $result[] = [
                    $label,
                    $index === $last
                        ? ''
                        : home_url(
                            $current . '/'
                        ),
                ];
            }

            return $result;
        }


        /**
         * ====================================================
         * 2. NATIVE VACATURE TAXONOMY TERM ARCHIVES
         * ====================================================
         *
         * Alleen taxonomies die daadwerkelijk aan het
         * vacature CPT gekoppeld zijn.
         *
         * Voorbeeld:
         *
         * /locatie/nederland/noord-brabant/eindhoven/
         *
         * wordt:
         *
         * Home
         * > Vacatures
         * > Nederland
         * > Provincie Noord-Brabant
         * > Eindhoven
         *
         * Dus GEEN taxonomy base "Locaties".
         *
         * Andere CPT-taxonomies blijven volledig ongemoeid.
         */

        if ( is_tax() ) {

            $term =
                get_queried_object();

            if (
                ! $term instanceof WP_Term
            ) {
                return $crumbs;
            }

            /**
             * Vacature post type.
             */
            $vacancy_post_type =
                defined( 'TFSC_VACANCY_POST_TYPE' )
                    ? TFSC_VACANCY_POST_TYPE
                    : 'vacature';

            /**
             * Alleen taxonomies die daadwerkelijk
             * aan het vacature CPT gekoppeld zijn.
             */
            $vacancy_taxonomies =
                get_object_taxonomies(
                    $vacancy_post_type,
                    'names'
                );

            if (
                ! in_array(
                    $term->taxonomy,
                    $vacancy_taxonomies,
                    true
                )
            ) {
                return $crumbs;
            }

            /**
             * Alleen de echte native taxonomy URL.
             *
             * Combo archives onder /vacatures/...
             * blijven ongemoeid.
             */
            $term_url =
                get_term_link(
                    $term
                );

            if ( is_wp_error( $term_url ) ) {
                return $crumbs;
            }

            $native_path =
                untrailingslashit(
                    wp_parse_url(
                        $term_url,
                        PHP_URL_PATH
                    )
                );

            $current_path =
                wp_parse_url(
                    $_SERVER['REQUEST_URI'] ?? '',
                    PHP_URL_PATH
                );

            $current_path =
                preg_replace(
                    '#/page/[0-9]+/?$#',
                    '/',
                    $current_path
                );

            $current_path =
                untrailingslashit(
                    $current_path
                );

            if (
                $native_path !==
                $current_path
            ) {
                return $crumbs;
            }

            $taxonomy =
                get_taxonomy(
                    $term->taxonomy
                );

            if ( ! $taxonomy ) {
                return $crumbs;
            }

            /**
