 */

add_filter(
    'rank_math/frontend/breadcrumb/items',
    function( $crumbs, $class ) {

        /**
         * ====================================================
         * 1. BEROEPENGIDS TAXONOMY BASE ARCHIVES
         * ====================================================
         */

        $base_taxonomy =
            get_query_var(
                'tfsc_taxonomy_archive'
            );

        if (
            $base_taxonomy &&
            taxonomy_exists( $base_taxonomy )
        ) {

            $base_taxonomy =
                sanitize_key(
                    $base_taxonomy
                );

            $is_beroepengids_taxonomy =
                0 === strpos(
                    $base_taxonomy,
                    'beroep_'
                )
                ||
                0 === strpos(
                    $base_taxonomy,
                    'beroepengids_'
                );

            if ( ! $is_beroepengids_taxonomy ) {
                return $crumbs;
            }

            $taxonomy =
                get_taxonomy(
                    $base_taxonomy
                );

            if (
                ! $taxonomy ||
                empty( $taxonomy->rewrite['slug'] )
            ) {
                return $crumbs;
            }

            $segments =
                array_values(
                    array_filter(
                        explode(
                            '/',
                            trim(
                                (string) $taxonomy->rewrite['slug'],
                                '/'
                            )
                        )
                    )
                );

            if ( ! $segments ) {
                return $crumbs;
            }

            $result = [];

            if ( ! empty( $crumbs[0] ) ) {
                $result[] = $crumbs[0];
            }

            $current = '';
            $last =
                count( $segments ) - 1;

            foreach (
                $segments
                as $index => $segment
            ) {

                $current .=
                    '/' . $segment;

                $label =
                    $index === $last
                        ? (
                            $taxonomy->labels->name
                            ?? ucfirst(
                                str_replace(
                                    [ '-', '_' ],
                                    ' ',
                                    $segment
                                )
                            )
                        )
                        : ucfirst(
                            str_replace(
                                [ '-', '_' ],
                                ' ',
                                $segment
                            )
                        );

                $result[] = [
                    $label,
                    $index === $last
                        ? ''
                        : home_url(
                            $current . '/'
                        ),
                ];
            }

            return $result;
        }


        /**
         * ====================================================
         * 2. BEROEPENGIDS TAXONOMY TERM ARCHIVES
         * ====================================================
         *
         * Rank Math breadcrumb behouden.
         *
         * Alleen zorgen dat het taxonomy-base item
         * klikbaar wordt naar het bestaande base archive.
         */

        if ( is_tax() ) {

            $term =
                get_queried_object();

            if ( $term instanceof WP_Term ) {

                $taxonomy_name =
                    sanitize_key(
                        $term->taxonomy
                    );

                $is_beroepengids_taxonomy =
                    0 === strpos(
                        $taxonomy_name,
                        'beroep_'
                    )
                    ||
                    0 === strpos(
                        $taxonomy_name,
                        'beroepengids_'
                    );

                if ( $is_beroepengids_taxonomy ) {

                    $taxonomy =
                        get_taxonomy(
                            $taxonomy_name
                        );

                    if (
                        $taxonomy &&
                        ! empty( $taxonomy->rewrite['slug'] )
                    ) {

                        $base_url =
                            home_url(
                                '/'
                                . trim(
                                    $taxonomy->rewrite['slug'],
                                    '/'
                                )
                                . '/'
                            );

                        /**
                         * Rank Math geeft normaal:
                         *
                         * Home
                         * > Taxonomy base
                         * > Huidige term
                         *
                         * Het voorlaatste item is dus
                         * het taxonomy-base item.
                         */
                        if ( count( $crumbs ) >= 2 ) {

                            $base_index =
                                count( $crumbs ) - 2;

                            $crumbs[ $base_index ][1] =
                                $base_url;
                        }
                    }

                    return $crumbs;
                }
            }
        }


        /**
         * ====================================================
         * 3. NATIVE VACATURE TAXONOMY TERM ARCHIVES
         * ====================================================
         *
         * Alleen taxonomies die daadwerkelijk aan het
         * vacature CPT gekoppeld zijn.
         *
         * Voorbeeld:
         *
         * /locatie/nederland/noord-brabant/eindhoven/
         *
         * wordt:
         *
         * Home
         * > Vacatures
         * > Nederland
         * > Provincie Noord-Brabant
         * > Eindhoven
         *
         * Dus GEEN taxonomy base "Locaties".
         */

