                    ? 'WP_Error'
                    : ($result instanceof WP_User ? 'WP_User' : gettype($result)),

                'error_code' => is_wp_error($result)
                    ? $result->get_error_code()
                    : null,

                'error_message' => is_wp_error($result)
                    ? $result->get_error_message()
                    : null,

                'authenticated_user' => $result instanceof WP_User
                    ? $result->user_login
                    : null,
            ];
        },
    ]);
});

