            $post_type =
                get_query_var( 'post_type' );

            if ( is_array( $post_type ) ) {
                $post_type =
                    reset( $post_type );
            }

            if ( $post_type ) {

                $post_type_object =
                    get_post_type_object(
                        $post_type
                    );

                if (
                    $post_type_object &&
                    ! empty(
                        $post_type_object->has_archive
                    )
                ) {

                    $archive_url =
                        get_post_type_archive_link(
                            $post_type
                        );

                    if ( $archive_url ) {

                        $archive_path =
                            trim(
                                (string) wp_parse_url(
                                    $archive_url,
                                    PHP_URL_PATH
                                ),
                                '/'
                            );

                        if (
                            0 === strpos(
                                $archive_path,
                                'beroepengids/'
                            )
                        ) {

                            $result = [];

                            if ( ! empty( $crumbs[0] ) ) {
                                $result[] = $crumbs[0];
                            }

                            $result[] = [
                                'Beroepengids',
                                home_url(
                                    '/beroepengids/'
                                ),
                            ];

                            $result[] = [
                                $post_type_object
                                    ->labels
                                    ->name,
                                '',
                            ];

                            return $result;
                        }
                    }
                }
            }
        }


        /**
         * ====================================================
         * 2. BEROEPENGIDS SINGULAR ARTIKELEN
         * ====================================================
         *
         * Voorbeeld:
         *
         * /beroepengids/artikel/servicemonteur/
         *
         * Home
         * > Beroepengids
         * > Artikelen
         * > Servicemonteur
         */

        if ( is_singular() ) {

            $post_type =
                get_post_type();

            if ( $post_type ) {

                $post_type_object =
                    get_post_type_object(
                        $post_type
                    );

                if (
                    $post_type_object &&
                    ! empty(
                        $post_type_object->has_archive
                    )
                ) {

                    $archive_url =
                        get_post_type_archive_link(
                            $post_type
                        );

                    if ( $archive_url ) {

                        $archive_path =
                            trim(
                                (string) wp_parse_url(
                                    $archive_url,
                                    PHP_URL_PATH
                                ),
                                '/'
                            );

                        /**
                         * Alleen CPT's waarvan het archief
                         * onder /beroepengids/ staat.
                         */
                        if (
                            0 === strpos(
                                $archive_path,
                                'beroepengids/'
                            )
                        ) {

                            $result = [];

                            if ( ! empty( $crumbs[0] ) ) {
                                $result[] = $crumbs[0];
                            }

                            /**
                             * Beroepengids pagina.
                             */
                            $result[] = [
                                'Beroepengids',
                                home_url(
                                    '/beroepengids/'
                                ),
                            ];

                            /**
                             * CPT archief.
                             */
                            $result[] = [
                                $post_type_object
                                    ->labels
                                    ->name,
                                $archive_url,
                            ];

                            /**
                             * Huidig artikel.
                             */
                            $result[] = [
                                get_the_title(),
                                '',
                            ];

                            return $result;
                        }
                    }
                }
            }
        }


        /**
         * ====================================================
         * 3. BEROEPENGIDS TAXONOMY BASE ARCHIVES
         * ====================================================
         */

        $base_taxonomy =
            get_query_var(
                'tfsc_taxonomy_archive'
            );

        if (
            $base_taxonomy &&
            taxonomy_exists( $base_taxonomy )
        ) {

            $base_taxonomy =
                sanitize_key(
                    $base_taxonomy
                );

            $is_beroepengids_taxonomy =
                0 === strpos(
                    $base_taxonomy,
                    'beroep_'
                )
                ||
                0 === strpos(
                    $base_taxonomy,
                    'beroepengids_'
                );

            if ( ! $is_beroepengids_taxonomy ) {
                return $crumbs;
            }

            $taxonomy =
                get_taxonomy(
                    $base_taxonomy
                );

            if (
                ! $taxonomy ||
                empty( $taxonomy->rewrite['slug'] )
            ) {
                return $crumbs;
            }

            $segments =
                array_values(
                    array_filter(
                        explode(
                            '/',
                            trim(
                                (string) $taxonomy
                                    ->rewrite['slug'],
                                '/'
                            )
                        )
                    )
                );

            if ( ! $segments ) {
                return $crumbs;
            }

            $result = [];

            if ( ! empty( $crumbs[0] ) ) {
                $result[] = $crumbs[0];
            }

            $current = '';
            $last =
                count( $segments ) - 1;

            foreach (
                $segments
                as $index => $segment
            ) {

                $current .=
                    '/' . $segment;

                $label =
                    $index === $last
                        ? (
                            $taxonomy
                                ->labels
                                ->name
                            ?? ucfirst(
                                str_replace(
                                    [ '-', '_' ],
                                    ' ',
                                    $segment
                                )
                            )
                        )
                        : ucfirst(
                            str_replace(
                                [ '-', '_' ],
                                ' ',
                                $segment
                            )
                        );

                $result[] = [
                    $label,
                    $index === $last
                        ? ''
                        : home_url(
                            $current . '/'
                        ),
                ];
            }

            return $result;
        }


        /**
         * ====================================================
         * 4. BEROEPENGIDS TAXONOMY TERM ARCHIVES
         * ====================================================
         *
         * Rank Math breadcrumb behouden.
         *
         * Alleen taxonomy-base item klikbaar maken.
         */

        if ( is_tax() ) {

            $term =
                get_queried_object();

            if ( $term instanceof WP_Term ) {

                $taxonomy_name =
                    sanitize_key(
                        $term->taxonomy
                    );

                $is_beroepengids_taxonomy =
                    0 === strpos(
                        $taxonomy_name,
                        'beroep_'
                    )
                    ||
                    0 === strpos(
                        $taxonomy_name,
                        'beroepengids_'
                    );

                if ( $is_beroepengids_taxonomy ) {

                    $taxonomy =
                        get_taxonomy(
                            $taxonomy_name
                        );

                    if (
                        $taxonomy &&
                        ! empty(
                            $taxonomy->rewrite['slug']
                        )
                    ) {

                        $base_url =
                            home_url(
                                '/'
                                . trim(
                                    $taxonomy
                                        ->rewrite['slug'],
                                    '/'
                                )
                                . '/'
                            );

                        if ( count( $crumbs ) >= 2 ) {

                            $base_index =
                                count( $crumbs ) - 2;

                            $crumbs[
                                $base_index
                            ][1] =
                                $base_url;
                        }
                    }

                    return $crumbs;
                }
            }
        }


        /**
         * ====================================================
         * 5. NATIVE VACATURE TAXONOMY TERM ARCHIVES
         * ====================================================
         *
         * Voorbeeld:
         *
         * Home
         * > Vacatures
         * > Nederland
         * > Provincie Noord-Brabant
         * > Eindhoven
         */

        if ( is_tax() ) {

            $term =
                get_queried_object();

            if (
                ! $term instanceof WP_Term
            ) {
                return $crumbs;
            }

            $vacancy_post_type =
                defined(
                    'TFSC_VACANCY_POST_TYPE'
                )
                    ? TFSC_VACANCY_POST_TYPE
                    : 'vacature';

            $vacancy_taxonomies =
                get_object_taxonomies(
                    $vacancy_post_type,
                    'names'
                );

            if (
                ! in_array(
                    $term->taxonomy,
                    $vacancy_taxonomies,
                    true
                )
            ) {
                return $crumbs;
            }

            /**
             * Alleen echte native taxonomy URL.
             */
            $term_url =
                get_term_link(
                    $term
                );

            if ( is_wp_error( $term_url ) ) {
                return $crumbs;
            }

            $native_path =
                untrailingslashit(
                    wp_parse_url(
                        $term_url,
                        PHP_URL_PATH
                    )
                );

            $current_path =
                wp_parse_url(
                    $_SERVER[
                        'REQUEST_URI'
                    ] ?? '',
                    PHP_URL_PATH
                );

            $current_path =
                preg_replace(
                    '#/page/[0-9]+/?$#',
                    '/',
                    $current_path
                );

            $current_path =
                untrailingslashit(
                    $current_path
                );

            if (
                $native_path !==
                $current_path
            ) {
                return $crumbs;
            }

            $taxonomy =
                get_taxonomy(
                    $term->taxonomy
                );

            if ( ! $taxonomy ) {
                return $crumbs;
            }

            $combo_base =
                defined(
                    'TFSC_COMBO_BASE'
                )
                    ? trim(
                        TFSC_COMBO_BASE,
                        '/'
                    )
                    : 'vacatures';

            $taxonomy_slug =
                ! empty(
                    $taxonomy->rewrite['slug']
                )
                    ? trim(
                        $taxonomy->rewrite['slug'],
                        '/'
                    )
                    : $term->taxonomy;

            $result = [];

            /**
             * Home.
             */
            if ( ! empty( $crumbs[0] ) ) {
                $result[] = $crumbs[0];
            }

            /**
             * Vacatures.
             */
            $result[] = [
                'Vacatures',
                home_url(
                    '/' . $combo_base . '/'
                ),
            ];

            $term_path = [];

            if (
                is_taxonomy_hierarchical(
                    $term->taxonomy
                )
            ) {

                foreach (
                    array_reverse(
                        get_ancestors(
                            $term->term_id,
                            $term->taxonomy,
                            'taxonomy'
                        )
                    )
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $term->taxonomy
                        );

                    if (
                        ! $ancestor instanceof WP_Term ||
                        is_wp_error( $ancestor )
                    ) {
                        continue;
                    }

                    $term_path[] =
                        $ancestor->slug;

                    $result[] = [
                        $ancestor->name,
                        home_url(
                            '/'
                            . $combo_base
                            . '/'
                            . $taxonomy_slug
                            . '/'
                            . implode(
                                '/',
                                $term_path
                            )
                            . '/'
                        ),
                    ];
                }
            }

            /**
             * Huidige term.
             */
            $result[] = [
                $term->name,
                '',
            ];

            return $result;
        }


        /**
         * ====================================================
         * ALLES ANDERS
         * ====================================================
         */

        return $crumbs;
    },
    10,
    2
);

add_filter( 'wp_kses_allowed_html', function( $allowed, $context ) {

    if ( 'pre_term_description' !== $context ) {
        return $allowed;
    }

    $allowed['h2'] = array();
    $allowed['h3'] = array();
    $allowed['p'] = array();
    $allowed['strong'] = array();
    $allowed['em'] = array();
    $allowed['ul'] = array();
    $allowed['ol'] = array();
    $allowed['li'] = array();
    $allowed['br'] = array();

    return $allowed;

}, 10, 2 );

/**
 * TFSC - Generic Archive Settings Fields
 *
 * Pods:
 * pods_archief_instellingen
 *
 * TAXONOMY BASE ARCHIVE:
 * archive_{context}_{taxonomy}_{field}
 *
 * CPT ARCHIVE:
 * archive_cpt_{context}_{field}
 *
 * Voorbeelden:
 *
 * archive_beroep_functienaam_intro
 * archive_beroep_functienaam_description
 *
 * archive_cpt_beroep_intro
 * archive_cpt_beroep_description
 *
 * archive_cpt_kennisbank_intro
 * archive_cpt_kennisbank_description
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_archive_settings_pod_name() {
    return 'pods_archief_instellingen';
}


/**
 * ============================================================
 * 2. CPT → CONTEXT
 * ============================================================
 *
 * Voeg hier alleen uitzonderingen toe waarbij
 * CPT slug en gewenste context niet gelijk zijn.
 */

function tfsc_archive_settings_context_map() {

    return [
        'beroepengids' => 'beroep',

        /*
         * Voorbeeld:
         *
         * Als je echte CPT slug "kennisbankartikelen" is,
         * maar je Pods velden "kennisbank" gebruiken:
         *
         * 'kennisbankartikelen' => 'kennisbank',
         */
    ];
}


/**
 * ============================================================
 * 3. CONTEXT UIT CPT
 * ============================================================
 */

function tfsc_archive_settings_context_from_post_type( $post_type ) {

    $post_type = sanitize_key( $post_type );

    if ( ! $post_type ) {
        return '';
    }

    $map = tfsc_archive_settings_context_map();

    if ( isset( $map[ $post_type ] ) ) {
        return sanitize_key( $map[ $post_type ] );
    }

    return $post_type;
}


/**
 * ============================================================
 * 4. TAXONOMY BASE OPHALEN
 * ============================================================
 *
 * BELANGRIJK:
 *
 * Gebruikt jouw bestaande:
 *
 * tfsc_get_current_taxonomy_archive()
 *
 * Dit is dus NIET hetzelfde als is_tax().
 */

function tfsc_archive_settings_raw_taxonomy() {

    if (
        function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {

        $taxonomy =
            tfsc_get_current_taxonomy_archive();

        if (
            is_object( $taxonomy ) &&
            ! empty( $taxonomy->name )
        ) {
            $taxonomy = $taxonomy->name;
        }

        if ( $taxonomy ) {
            return sanitize_key( $taxonomy );
        }
    }


    /**
     * Fallback voor normale WordPress term archives.
     */

    if (
        is_tax() ||
        is_category() ||
        is_tag()
    ) {

        $object = get_queried_object();

        if (
            $object &&
            ! empty( $object->taxonomy )
        ) {
            return sanitize_key(
                $object->taxonomy
            );
        }
    }

    return '';
}


/**
 * ============================================================
 * 5. CPT VAN TAXONOMY BEPALEN
 * ============================================================
 */

function tfsc_archive_settings_post_type_from_taxonomy(
    $taxonomy
) {

    $taxonomy = sanitize_key( $taxonomy );

    if ( ! $taxonomy ) {
        return '';
    }


    /**
     * --------------------------------------------------------
     * Eerst prefix gebruiken.
     *
     * Dit is betrouwbaarder dan zomaar het eerste
     * gekoppelde object_type pakken.
     * --------------------------------------------------------
     */

    $context_map =
        tfsc_archive_settings_context_map();


    /**
     * Controleer mappings.
     *
     * beroep_ → beroepengids
     * beroepengids_ → beroepengids
     */

    foreach (
        $context_map as $post_type => $context
    ) {

        $prefixes = [
            $context . '_',
            $context . '-',
            $post_type . '_',
            $post_type . '-',
        ];

        foreach ( $prefixes as $prefix ) {

            if (
                0 === strpos(
                    $taxonomy,
                    $prefix
                )
            ) {
                return sanitize_key(
                    $post_type
                );
            }
        }
    }


    /**
     * --------------------------------------------------------
     * Daarna kijken naar geregistreerde object types.
     * --------------------------------------------------------
     */

    $taxonomy_object =
        get_taxonomy( $taxonomy );

    if (
        ! $taxonomy_object ||
        empty( $taxonomy_object->object_type )
    ) {
        return '';
    }

    $post_types =
        array_values(
            array_filter(
                (array)
                $taxonomy_object->object_type
            )
        );

    if ( empty( $post_types ) ) {
        return '';
    }

    return sanitize_key(
        $post_types[0]
    );
}


/**
 * ============================================================
 * 6. HUIDIGE CPT
 * ============================================================
 */

function tfsc_archive_settings_post_type() {

    /**
     * --------------------------------------------------------
     * CPT ARCHIVE
     * --------------------------------------------------------
     */

    if ( is_post_type_archive() ) {

        $post_type =
            get_query_var( 'post_type' );

        if ( is_array( $post_type ) ) {
            $post_type = reset( $post_type );
        }

        if ( $post_type ) {
            return sanitize_key(
                $post_type
            );
        }


        /**
         * Fallback.
         */

        $object =
            get_queried_object();

        if (
            $object &&
            ! empty( $object->name )
        ) {
            return sanitize_key(
                $object->name
            );
        }
    }


    /**
     * --------------------------------------------------------
     * TAXONOMY BASE / TERM ARCHIVE
     * --------------------------------------------------------
     */

    $taxonomy =
        tfsc_archive_settings_raw_taxonomy();

    if ( $taxonomy ) {

        return
            tfsc_archive_settings_post_type_from_taxonomy(
                $taxonomy
            );
    }


    return '';
}


/**
 * ============================================================
 * 7. CONTEXT
 * ============================================================
 */

function tfsc_archive_settings_context() {

    $post_type =
        tfsc_archive_settings_post_type();

    if ( ! $post_type ) {
        return '';
    }

    return
        tfsc_archive_settings_context_from_post_type(
            $post_type
        );
}


/**
 * ============================================================
 * 8. TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functienaam
 * → functienaam
 *
 * beroepengids_functienaam
 * → functienaam
 *
 * vacature_bedrijfssector
 * → bedrijfssector
 */

function tfsc_archive_settings_normalize_taxonomy(
    $taxonomy
) {

    $taxonomy =
        sanitize_key( $taxonomy );

    if ( ! $taxonomy ) {
        return '';
    }

    $post_type =
        tfsc_archive_settings_post_type();

    $context =
        tfsc_archive_settings_context();

    $prefixes = [];


    if ( $post_type ) {

        $prefixes[] =
            $post_type . '_';

        $prefixes[] =
            $post_type . '-';
    }


    if ( $context ) {

        $prefixes[] =
            $context . '_';

        $prefixes[] =
            $context . '-';
    }


    $prefixes =
        array_unique( $prefixes );


    usort(
        $prefixes,
        function( $a, $b ) {

            return
                strlen( $b )
                <=>
                strlen( $a );
        }
    );


    foreach ( $prefixes as $prefix ) {

        if (
            0 === strpos(
                $taxonomy,
                $prefix
            )
        ) {

            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen( $prefix )
                )
            );
        }
    }


    return $taxonomy;
}


/**
 * ============================================================
 * 9. HUIDIGE GENORMALISEERDE TAXONOMY
 * ============================================================
 */

function tfsc_archive_settings_taxonomy() {

    $taxonomy =
        tfsc_archive_settings_raw_taxonomy();

    if ( ! $taxonomy ) {
        return '';
    }

    return
        tfsc_archive_settings_normalize_taxonomy(
            $taxonomy
        );
}


/**
 * ============================================================
 * 10. PODS VELDNAAM
 * ============================================================
 */

function tfsc_archive_settings_field_name(
    $field
) {

    $field =
        sanitize_key( $field );

    if ( ! $field ) {
        return '';
    }


    $context =
        tfsc_archive_settings_context();

    if ( ! $context ) {
        return '';
    }


    /**
     * --------------------------------------------------------
     * TAXONOMY BASE / TERM ARCHIVE
     * --------------------------------------------------------
     */

    $taxonomy =
        tfsc_archive_settings_taxonomy();

    if ( $taxonomy ) {

        return sanitize_key(
            'archive_'
            . $context
            . '_'
            . $taxonomy
            . '_'
            . $field
        );
    }


    /**
     * --------------------------------------------------------
     * CPT ARCHIVE
     * --------------------------------------------------------
     */

    if ( is_post_type_archive() ) {

        return sanitize_key(
            'archive_cpt_'
            . $context
            . '_'
            . $field
        );
    }


    return '';
}


/**
 * ============================================================
 * 11. PODS VALUE
 * ============================================================
 */

function tfsc_archive_settings_value(
    $field
) {

    if ( ! function_exists( 'pods' ) ) {
        return '';
    }


    $field_name =
        tfsc_archive_settings_field_name(
            $field
        );

    if ( ! $field_name ) {
        return '';
    }


    $pod =
        pods(
            tfsc_archive_settings_pod_name()
        );

    if ( ! $pod ) {
        return '';
    }


    $value =
        $pod->field(
            $field_name
        );


    if (
        null === $value ||
        false === $value
    ) {
        return '';
    }


    if (
        ! is_array( $value ) &&
        ! is_object( $value )
    ) {

        $value =
            do_shortcode(
                wpautop(
                    (string)
                    $value
                )
            );

        $value =
            wp_kses_post(
                $value
            );
    }


    return $value;
}


/**
 * ============================================================
 * 12. SHORTCODE
 * ============================================================
 *
 * [tfsc_archive_field field="intro"]
 *
 * [tfsc_archive_field field="description"]
 */

add_shortcode(
    'tfsc_archive_field',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'field' => '',
                ],
                $atts,
                'tfsc_archive_field'
            );


        $value =
            tfsc_archive_settings_value(
                $atts['field']
            );


        if (
            is_array( $value ) ||
            is_object( $value )
        ) {
            return '';
        }


        return (string) $value;
    }
);


/**
 * ============================================================
 * 13. ELEMENTOR DYNAMIC TAG
 * ============================================================
 */

add_action(
    'elementor/dynamic_tags/register',
    function( $dynamic_tags ) {

        if (
            ! class_exists(
                '\Elementor\Core\DynamicTags\Tag'
            )
        ) {
            return;
        }


        class TFSC_Archive_Settings_Field_Tag
            extends
            \Elementor\Core\DynamicTags\Tag {

            public function get_name() {

                return
                    'tfsc-archive-settings-field';
            }


            public function get_title() {

                return
                    'TFSC Archive Settings Field';
            }


            public function get_group() {

                return 'site';
            }


            public function get_categories() {

                return [
                    \Elementor\Modules\DynamicTags\Module::TEXT_CATEGORY,
                ];
            }


            protected function register_controls() {

                $this->add_control(
                    'field',
                    [
                        'label' =>
                            'Field',

                        'type' =>
                            \Elementor\Controls_Manager::TEXT,

                        'placeholder' =>
                            'intro',
                    ]
                );
            }


            public function render() {

                $field =
                    $this->get_settings(
                        'field'
                    );


                if ( ! $field ) {
                    return;
                }


                $value =
                    tfsc_archive_settings_value(
                        $field
                    );


                if (
                    is_array( $value ) ||
                    is_object( $value )
                ) {
                    return;
                }


                echo (string) $value;
            }
        }


        $dynamic_tags->register(
            new TFSC_Archive_Settings_Field_Tag()
        );
    }
);

/**
 * ============================================================
 * TFSC - GENERIC ARCHIVE SETTINGS FIELDS
 * ============================================================
 *
 * Doel
 * ----
 * Deze snippet leest centrale archivevelden uit de Pods Settings Pod:
 *
 * pods_archief_instellingen
 *
 * en maakt deze beschikbaar als:
 *
 * - shortcode
 * - Elementor Dynamic Tag
 *
 *
 * ============================================================
 * HANDLEIDING
 * ============================================================
 *
 * 1. CPT'S TOEVOEGEN
 * ------------------------------------------------------------
 *
 * Iedere CPT krijgt hieronder een vaste "archive context".
 *
 * Voorbeeld:
 *
 * WordPress CPT:
 * beroepengids
 *
 * Archive context:
 * beroep
 *
 * Daardoor blijven bestaande velden werken:
 *
 * archive_cpt_beroep_intro
 * archive_cpt_beroep_description
 *
 *
 * Voor kennisbank:
 *
 * WordPress CPT:
 * kennisbankartikel
 *
 * Archive context:
 * kennisbankartikel
 *
 * Velden:
 *
 * archive_cpt_kennisbankartikel_intro
 * archive_cpt_kennisbankartikel_description
 *
 *
 * Nieuwe CPT toevoegen?
 *
 * Voeg hem alleen toe in:
 *
 * tfsc_archive_settings_config()
 *
 * Bijvoorbeeld:
 *
 * 'nieuwsartikelen' => [
 *     'context' => 'nieuwsartikel',
 * ],
 *
 *
 * ============================================================
 * 2. TAXONOMY TOEVOEGEN
 * ============================================================
 *
 * Taxonomies hoeven NIET apart in deze PHP-code geregistreerd
 * te worden.
 *
 * Ze moeten alleen gekoppeld zijn aan de juiste WordPress CPT.
 *
 *
 * AANBEVOLEN NAAMGEVING:
 *
 * {context}_{taxonomy}
 *
 *
 * Voor beroepengids:
 *
 * beroep_functienaam
 * beroep_bedrijfssector
 * beroep_opleiding
 *
 *
 * Voor kennisbankartikelen:
 *
 * kennisbankartikel_onderwerp
 * kennisbankartikel_techniek
 * kennisbankartikel_sector
 *
 *
 * De prefix wordt automatisch verwijderd.
 *
 * Dus:
 *
 * kennisbankartikel_onderwerp
 *
 * wordt:
 *
 * onderwerp
 *
 *
 * ============================================================
 * 3. PODS VELDEN VOOR TAXONOMY ARCHIVES
 * ============================================================
 *
 * Structuur:
 *
 * archive_{context}_{taxonomy}_{field}
 *
 *
 * Voorbeeld beroepengids:
 *
 * taxonomy:
 * beroep_functienaam
 *
 * velden:
 *
 * archive_beroep_functienaam_intro
 * archive_beroep_functienaam_description
 *
 *
 * Voorbeeld kennisbank:
 *
 * taxonomy:
 * kennisbankartikel_onderwerp
 *
 * velden:
 *
 * archive_kennisbankartikel_onderwerp_intro
 * archive_kennisbankartikel_onderwerp_description
 *
 *
 * ============================================================
 * 4. PODS VELDEN VOOR CPT ARCHIVES
 * ============================================================
 *
 * Structuur:
 *
 * archive_cpt_{context}_{field}
 *
 *
 * Beroepengids:
 *
 * archive_cpt_beroep_intro
 * archive_cpt_beroep_description
 *
 *
 * Kennisbank:
 *
 * archive_cpt_kennisbankartikel_intro
 * archive_cpt_kennisbankartikel_description
 *
 *
 * ============================================================
 * 5. ELEMENTOR
 * ============================================================
 *
 * Dynamic Tag:
 *
 * TFSC Archive Settings Field
 *
 *
 * Bij Field vul je alleen in:
 *
 * intro
 *
 * of:
 *
 * description
 *
 *
 * Elementor hoeft dus niet te weten:
 *
 * - welke CPT actief is
 * - welke taxonomy actief is
 * - welke context gebruikt moet worden
 *
 *
 * ============================================================
 * 6. SHORTCODE
 * ============================================================
 *
 * [tfsc_archive_field field="intro"]
 *
 * [tfsc_archive_field field="description"]
 *
 *
 * ============================================================
 * 7. BELANGRIJK
 * ============================================================
 *
 * De Pods GROUP NAME wordt nergens gebruikt.
 *
 * Dus bijvoorbeeld:
 *
 * archive_beroep_taxonomies
 * archive_kennisbankartikelen
 *
 * zijn alleen organisatorische groepsnamen in Pods.
 *
 * Alleen de daadwerkelijke FIELD NAME is belangrijk.
 *
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_archive_settings_pod_name() {

    return 'pods_archief_instellingen';
}


/**
 * Centrale CPT → archive context mapping.
 *
 * Dit is de belangrijkste configuratie van deze snippet.
 */

function tfsc_archive_settings_config() {

    return [

        /**
         * Legacy structuur bewust behouden.
         *
         * CPT:
         * beroepengids
         *
         * Archive context:
         * beroep
         */

        'beroepengids' => [
            'context' => 'beroep',
        ],


        /**
         * Kennisbank.
         *
         * CPT:
         * kennisbankartikel
         *
         * Archive context:
         * kennisbankartikel
         */

        'kennisbankartikel' => [
            'context' => 'kennisbankartikel',
        ],


        /**
         * Nieuwe CPT later toevoegen:
         *
         * 'voorbeeldartikelen' => [
         *     'context' => 'voorbeeldartikel',
         * ],
         */
    ];
}


/**
 * ============================================================
 * 2. CONTEXT UIT CPT HALEN
 * ============================================================
 */

function tfsc_archive_settings_context_from_post_type(
    $post_type
) {

    $post_type =
        sanitize_key(
            $post_type
        );

    if ( ! $post_type ) {
        return '';
    }

    $config =
        tfsc_archive_settings_config();

    /**
     * CPT staat expliciet in configuratie.
     */

    if (
        isset(
            $config[ $post_type ]['context']
        )
    ) {

        return sanitize_key(
            $config[ $post_type ]['context']
        );
    }

    /**
     * Fallback:
     *
     * CPT slug zelf gebruiken.
     *
     * Hierdoor blijft de code ook werken voor CPT's
     * waarvoor nog geen afwijkende context nodig is.
     */

    return $post_type;
}


/**
 * ============================================================
 * 3. RAW TAXONOMY BEPALEN
 * ============================================================
 *
 * Ondersteunt:
 *
 * - TFSC taxonomy base archives
 * - normale WordPress taxonomy term archives
 */

function tfsc_archive_settings_raw_taxonomy() {

    /**
     * --------------------------------------------------------
     * TFSC TAXONOMY BASE ARCHIVE
     * --------------------------------------------------------
     *
     * Deze functie bestaat al binnen TFSC en bepaalt
     * bijvoorbeeld:
     *
     * beroep_functienaam
     *
     * wanneer we ons op de functienaam-base bevinden.
     */

    if (
        function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {

        $taxonomy =
            tfsc_get_current_taxonomy_archive();

        if (
            is_object( $taxonomy ) &&
            ! empty( $taxonomy->name )
        ) {
            $taxonomy =
                $taxonomy->name;
        }

        if ( $taxonomy ) {

            return sanitize_key(
                $taxonomy
            );
        }
    }


    /**
     * --------------------------------------------------------
     * NORMAAL WORDPRESS TERM ARCHIVE
     * --------------------------------------------------------
     */

    if (
        is_tax() ||
        is_category() ||
        is_tag()
    ) {

        $object =
            get_queried_object();

        if (
            $object &&
            ! empty(
                $object->taxonomy
            )
        ) {

            return sanitize_key(
                $object->taxonomy
            );
        }
    }


    return '';
}


/**
 * ============================================================
 * 4. CPT VAN EEN TAXONOMY BEPALEN
 * ============================================================
 */

function tfsc_archive_settings_post_type_from_taxonomy(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );

    if ( ! $taxonomy ) {
        return '';
    }


    $config =
        tfsc_archive_settings_config();


    /**
     * --------------------------------------------------------
     * EERST CONTEXT / CPT PREFIX CONTROLEREN
     * --------------------------------------------------------
     *
     * Dit ondersteunt bijvoorbeeld:
     *
     * beroep_functienaam
     *
     * en:
     *
     * kennisbankartikel_onderwerp
     */

    foreach (
        $config
        as $post_type => $settings
    ) {

        $context =
            ! empty(
                $settings['context']
            )
                ? sanitize_key(
                    $settings['context']
                )
                : sanitize_key(
                    $post_type
                );


        $prefixes = [

            $context . '_',
            $context . '-',

            $post_type . '_',
            $post_type . '-',
        ];


        foreach (
            $prefixes
            as $prefix
        ) {

            if (
                0 === strpos(
                    $taxonomy,
                    $prefix
                )
            ) {

                return sanitize_key(
                    $post_type
                );
            }
        }
    }


    /**
     * --------------------------------------------------------
     * FALLBACK VIA WORDPRESS TAXONOMY REGISTRATIE
     * --------------------------------------------------------
     */

    $taxonomy_object =
        get_taxonomy(
            $taxonomy
        );

    if (
        ! $taxonomy_object ||
        empty(
            $taxonomy_object->object_type
        )
    ) {
        return '';
    }


    $post_types =
        array_values(
            array_filter(
                (array)
                $taxonomy_object->object_type
            )
        );


    if (
        empty(
            $post_types
        )
    ) {
        return '';
    }


    /**
     * Als taxonomy aan meerdere CPT's hangt,
     * proberen we eerst een CPT uit onze configuratie.
     */

    foreach (
        $post_types
        as $post_type
    ) {

        if (
            isset(
                $config[ $post_type ]
            )
        ) {

            return sanitize_key(
                $post_type
            );
        }
    }


    /**
     * Anders eerste geregistreerde CPT.
     */

    return sanitize_key(
        $post_types[0]
    );
}


/**
 * ============================================================
 * 5. HUIDIGE CPT BEPALEN
 * ============================================================
 */

function tfsc_archive_settings_post_type() {

    /**
     * --------------------------------------------------------
     * CPT ARCHIVE
     * --------------------------------------------------------
     */

    if (
        is_post_type_archive()
    ) {

        $post_type =
            get_query_var(
                'post_type'
            );


        if (
            is_array(
                $post_type
            )
        ) {

            $post_type =
                reset(
                    $post_type
                );
        }


        if ( $post_type ) {

            return sanitize_key(
                $post_type
            );
        }


        /**
         * Fallback via queried object.
         */

        $object =
            get_queried_object();


        if (
            $object &&
            ! empty(
                $object->name
            )
        ) {

            return sanitize_key(
                $object->name
            );
        }
    }


    /**
     * --------------------------------------------------------
     * TAXONOMY ARCHIVE
     * --------------------------------------------------------
     */

    $taxonomy =
        tfsc_archive_settings_raw_taxonomy();


    if ( $taxonomy ) {

        return
            tfsc_archive_settings_post_type_from_taxonomy(
                $taxonomy
            );
    }


    return '';
}


/**
 * ============================================================
 * 6. HUIDIGE ARCHIVE CONTEXT
 * ============================================================
 */

function tfsc_archive_settings_context() {

    $post_type =
        tfsc_archive_settings_post_type();


    if ( ! $post_type ) {
        return '';
    }


    return
        tfsc_archive_settings_context_from_post_type(
            $post_type
        );
}


/**
 * ============================================================
 * 7. TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functienaam
 * → functienaam
 *
 * beroepengids_functienaam
 * → functienaam
 *
 * kennisbankartikel_onderwerp
 * → onderwerp
 *
 * kennisbankartikelen_onderwerp
 * → onderwerp
 */

function tfsc_archive_settings_normalize_taxonomy(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );


    if ( ! $taxonomy ) {
        return '';
    }


    $post_type =
        tfsc_archive_settings_post_type();


    $context =
        tfsc_archive_settings_context();


    $prefixes = [];


    /**
     * CPT prefix.
     */

    if ( $post_type ) {

        $prefixes[] =
            $post_type . '_';

        $prefixes[] =
            $post_type . '-';
    }


    /**
     * Archive context prefix.
     */

    if ( $context ) {

        $prefixes[] =
            $context . '_';

        $prefixes[] =
            $context . '-';
    }


    $prefixes =
        array_unique(
            $prefixes
        );


    /**
     * Langste prefix eerst.
     */

    usort(
        $prefixes,
        function(
            $a,
            $b
        ) {

            return
                strlen( $b )
                <=>
                strlen( $a );
        }
    );


    foreach (
        $prefixes
        as $prefix
    ) {

        if (
            0 === strpos(
                $taxonomy,
                $prefix
            )
        ) {

            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen(
                        $prefix
                    )
                )
            );
        }
    }


    /**
     * Geen prefix gevonden.
     *
     * Dan taxonomy slug ongewijzigd gebruiken.
     */

    return $taxonomy;
}


/**
 * ============================================================
 * 8. HUIDIGE GENORMALISEERDE TAXONOMY
 * ============================================================
 */

function tfsc_archive_settings_taxonomy() {

    $taxonomy =
        tfsc_archive_settings_raw_taxonomy();


    if ( ! $taxonomy ) {
        return '';
    }


    return
        tfsc_archive_settings_normalize_taxonomy(
            $taxonomy
        );
}


/**
 * ============================================================
 * 9. PODS FIELD NAME OPBOUWEN
 * ============================================================
 */

function tfsc_archive_settings_field_name(
    $field
) {

    $field =
        sanitize_key(
            $field
        );


    if ( ! $field ) {
        return '';
    }


    $context =
        tfsc_archive_settings_context();


    if ( ! $context ) {
        return '';
    }


    /**
     * --------------------------------------------------------
     * TAXONOMY ARCHIVE
     * --------------------------------------------------------
     *
     * archive_{context}_{taxonomy}_{field}
     */

    $taxonomy =
        tfsc_archive_settings_taxonomy();


    if ( $taxonomy ) {

        return sanitize_key(

            'archive_'
            . $context
            . '_'
            . $taxonomy
            . '_'
            . $field

        );
    }


    /**
     * --------------------------------------------------------
     * CPT ARCHIVE
     * --------------------------------------------------------
     *
     * archive_cpt_{context}_{field}
     */

    if (
        is_post_type_archive()
    ) {

        return sanitize_key(

            'archive_cpt_'
            . $context
            . '_'
            . $field

        );
    }


    return '';
}


/**
 * ============================================================
 * 10. PODS VALUE OPHALEN
 * ============================================================
 */

function tfsc_archive_settings_value(
    $field
) {

    if (
        ! function_exists(
            'pods'
        )
    ) {
        return '';
    }


    $field_name =
        tfsc_archive_settings_field_name(
            $field
        );


    if ( ! $field_name ) {
        return '';
    }


    $pod =
        pods(
            tfsc_archive_settings_pod_name()
        );


    if ( ! $pod ) {
        return '';
    }


    $value =
        $pod->field(
            $field_name
        );


    if (
        null === $value ||
        false === $value
    ) {
        return '';
    }


    /**
     * Tekst / WYSIWYG formatteren.
     */

    if (
        ! is_array( $value ) &&
        ! is_object( $value )
    ) {

        $value =
            do_shortcode(
                wpautop(
                    (string)
                    $value
                )
            );


        $value =
            wp_kses_post(
                $value
            );
    }


    return $value;
}


/**
 * ============================================================
 * 11. SHORTCODE
 * ============================================================
 *
 * [tfsc_archive_field field="intro"]
 *
 * [tfsc_archive_field field="description"]
 */

add_shortcode(
    'tfsc_archive_field',
    function(
        $atts
    ) {

        $atts =
            shortcode_atts(
                [
                    'field' => '',
                ],
                $atts,
                'tfsc_archive_field'
            );


        $value =
            tfsc_archive_settings_value(
                $atts['field']
            );


        if (
            is_array( $value ) ||
            is_object( $value )
        ) {
            return '';
        }


        return (string)
            $value;
    }
);


/**
 * ============================================================
 * 12. ELEMENTOR DYNAMIC TAG
 * ============================================================
 *
 * Dynamic Tag:
 *
 * TFSC Archive Settings Field
 *
 * Field:
 *
 * intro
 *
 * of:
 *
 * description
 */

add_action(
    'elementor/dynamic_tags/register',
    function(
        $dynamic_tags
    ) {

        if (
            ! class_exists(
                '\Elementor\Core\DynamicTags\Tag'
            )
        ) {
            return;
        }


        class TFSC_Archive_Settings_Field_Tag
            extends
            \Elementor\Core\DynamicTags\Tag {


            public function get_name() {

                return
                    'tfsc-archive-settings-field';
            }


            public function get_title() {

                return
                    'TFSC Archive Settings Field';
            }


            public function get_group() {

                return 'site';
            }


            public function get_categories() {

                return [

                    \Elementor\Modules\DynamicTags\Module
                        ::TEXT_CATEGORY,

                ];
            }


            protected function register_controls() {

                $this->add_control(
                    'field',
                    [

                        'label' =>
                            'Field',

                        'type' =>
                            \Elementor\Controls_Manager
                                ::TEXT,

                        'placeholder' =>
                            'intro',

                    ]
                );
            }


            public function render() {

                $field =
                    $this->get_settings(
                        'field'
                    );


                if ( ! $field ) {
                    return;
                }


                $value =
                    tfsc_archive_settings_value(
                        $field
                    );


                if (
                    is_array( $value ) ||
                    is_object( $value )
                ) {
                    return;
                }


                echo (string)
                    $value;
            }
        }


        $dynamic_tags->register(

            new TFSC_Archive_Settings_Field_Tag()

        );
    }
);

/**
 * TFSC - Dynamische tekst shortcodes
 *
 * Shortcodes:
 *
 * [post_title]
 * [archive_title]
 * [tfsc_pods field="..."]
 *
 * ============================================================
 * CASE
 * ============================================================
 *
 * case="normal"
 * case="lower"
 * case="sentence"
 *
 *
 * ============================================================
 * [archive_title] MODES
 * ============================================================
 *
 * Term archives:
 *
 * current
 * parents
 * full
 * label_current
 * label_full
 *
 * Taxonomy base archives:
 *
 * taxonomy
 * taxonomy_plural
 *
 *
 * ============================================================
 * PODS OUTPUT
 * ============================================================
 *
 * [tfsc_pods] gebruikt voor normale Pods velden:
 *
 *     $pod->display()
 *
 * in plaats van:
 *
 *     $pod->field()
 *
 * Hierdoor worden de OUTPUT SETTINGS van het Pods veld gebruikt.
 *
 * Dit is met name belangrijk voor:
 *
 * - WYSIWYG velden
 * - wpautop
 * - HTML sanitizing
 * - shortcodes
 * - wptexturize
 * - convert_chars
 *
 * Relationship velden worden apart verwerkt omdat display()
 * daar niet altijd de gewenste losse namen oplevert.
 *
 * BELANGRIJK:
 *
 * case="lower" en case="sentence" worden NIET toegepast op
 * HTML/WYSIWYG output. Daarmee zouden namelijk ook HTML tags
 * en attributen kunnen worden aangepast.
 */


/**
 * ============================================================
 * 1. CONTEXT POST ID
 * ============================================================
 */

function tfsc_text_context_post_id() {

    /**
     * In een normale WordPress- of Elementor-loop wijst get_the_ID()
     * naar het item dat nu wordt gerenderd. Dit moet vóór gedeelde
     * archive-/previewhelpers komen: die helpers cachen hun uitkomst
     * en kunnen daardoor de ID van de eerste loopkaart blijven geven.
     */

    $loop_id = (int) get_the_ID();

    if (
        $loop_id &&
        'elementor_library' !== get_post_type( $loop_id )
    ) {
        return $loop_id;
    }


    /**
     * Enkel bericht buiten een actieve loop.
     */

    $object = get_queried_object();

    if (
        $object instanceof WP_Post &&
        'elementor_library' !== get_post_type( $object->ID )
    ) {
        return (int) $object->ID;
    }


    /**
     * Elementor Theme Builder-preview. De afgeleide helpers blijven
     * nuttig wanneer de huidige post het template zelf is.
     */

    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v3_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }


    if (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v2_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }


    return 0;
}


/**
 * ============================================================
 * 2. CONTEXT POD
 * ============================================================
 */

function tfsc_text_context_pod() {

    if (
        ! function_exists(
            'pods'
        )
    ) {
        return false;
    }


    $object =
        get_queried_object();


    /**
     * --------------------------------------------------------
     * TAXONOMY TERM
     * --------------------------------------------------------
     */

    if (
        $object instanceof WP_Term
    ) {

        $pod =
            pods(
                $object->taxonomy,
                (int) $object->term_id
            );


        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }


    /**
     * --------------------------------------------------------
     * POST / CPT / ELEMENTOR PREVIEW
     * --------------------------------------------------------
     */

    $post_id =
        tfsc_text_context_post_id();


    if ( ! $post_id ) {
        return false;
    }


    $post_type =
        get_post_type(
            $post_id
        );


    if ( ! $post_type ) {
        return false;
    }


    $pod =
        pods(
            $post_type,
            $post_id
        );


    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * 3. TAXONOMY BASE OBJECT
 * ============================================================
 */

function tfsc_text_taxonomy_archive_object() {

    if (
        ! function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {
        return false;
    }


    $taxonomy =
        tfsc_get_current_taxonomy_archive();


    if (
        $taxonomy instanceof WP_Taxonomy
    ) {

        return $taxonomy;
    }


    if (
        is_string(
            $taxonomy
        )
    ) {

        $taxonomy =
            get_taxonomy(
                sanitize_key(
                    $taxonomy
                )
            );


        return (
            $taxonomy instanceof WP_Taxonomy
        )
            ? $taxonomy
            : false;
    }


    return false;
}


/**
 * ============================================================
 * 4. TEXT CASE
 * ============================================================
 */

function tfsc_text_case(
    $text,
    $case = 'normal'
) {

    $text =
        (string) $text;


    if (
        '' === $text
    ) {
        return '';
    }


    switch (
        sanitize_key(
            $case
        )
    ) {

        /**
         * ----------------------------------------------------
         * LOWERCASE
         * ----------------------------------------------------
         */

        case 'lower':

            return
                mb_strtolower(
                    $text,
                    'UTF-8'
                );


        /**
         * ----------------------------------------------------
         * SENTENCE CASE
         * ----------------------------------------------------
         */

        case 'sentence':

            $text =
                mb_strtolower(
                    $text,
                    'UTF-8'
                );


            return

                mb_strtoupper(
                    mb_substr(
                        $text,
                        0,
                        1,
                        'UTF-8'
                    ),
                    'UTF-8'
                )

                .

                mb_substr(
                    $text,
                    1,
                    null,
                    'UTF-8'
                );


        /**
         * ----------------------------------------------------
         * NORMAL
         * ----------------------------------------------------
         */

        default:

            return $text;
    }
}


/**
 * ============================================================
 * 5. [post_title]
 * ============================================================
 *
 * Voorbeelden:
 *
 * [post_title]
 *
 * [post_title case="lower"]
 *
 * [post_title before="Vacature: "]
 */

add_shortcode(
    'post_title',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'before' => '',
                    'after'  => '',
                    'case'   => 'normal',
                ],
                $atts,
                'post_title'
            );


        $post_id =
            tfsc_text_context_post_id();


        if ( ! $post_id ) {
            return '';
        }


        $title =
            wp_strip_all_tags(
                get_the_title(
                    $post_id
                )
            );


        if (
            '' === $title
        ) {
            return '';
        }


        $title =
            tfsc_text_case(
                $title,
                $atts['case']
            );


        return
            (string) $atts['before']
            . $title
            . (string) $atts['after'];
    }
);


/**
 * ============================================================
 * 6. [archive_title]
 * ============================================================
 *
 * TERM ARCHIVE MODES
 *
 * [archive_title]
 * [archive_title mode="current"]
 * [archive_title mode="parents"]
 * [archive_title mode="full"]
 * [archive_title mode="label_current"]
 * [archive_title mode="label_full"]
 *
 *
 * TAXONOMY BASE ARCHIVE MODES
 *
 * [archive_title mode="taxonomy"]
 * [archive_title mode="taxonomy_plural"]
 */

add_shortcode(
    'archive_title',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'mode'            => 'current',
                    'separator'       => ' › ',
                    'label_separator' => ': ',
                    'before'          => '',
                    'after'           => '',
                    'case'            => 'normal',
                ],
                $atts,
                'archive_title'
            );


        $mode =
            sanitize_key(
                $atts['mode']
            );


        $object =
            get_queried_object();


        /**
         * ====================================================
         * TAXONOMY TERM ARCHIVE
         * ====================================================
         */

        if (
            $object instanceof WP_Term &&
            taxonomy_exists(
                $object->taxonomy
            )
        ) {

            $taxonomy =
                $object->taxonomy;


            $current =
                wp_strip_all_tags(
                    $object->name
                );


            $parents = [];


            /**
             * Hiërarchische parents verzamelen.
             */

            if (
                is_taxonomy_hierarchical(
                    $taxonomy
                )
            ) {

                foreach (
                    array_reverse(
                        get_ancestors(
                            $object->term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    )
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error(
                            $ancestor
                        )
                    ) {

                        $parents[] =
                            wp_strip_all_tags(
                                $ancestor->name
                            );
                    }
                }
            }


            /**
             * Taxonomy label.
             */

            $taxonomy_object =
                get_taxonomy(
                    $taxonomy
                );


            $label =
                (
                    $taxonomy_object &&
                    ! empty(
                        $taxonomy_object
                            ->labels
                            ->singular_name
                    )
                )
                    ? wp_strip_all_tags(
                        $taxonomy_object
                            ->labels
                            ->singular_name
                    )
                    : '';


            /**
             * Volledige parentstructuur.
             */

            $full =
                implode(
                    (string)
                    $atts['separator'],
                    array_merge(
                        $parents,
                        [ $current ]
                    )
                );


            switch (
                $mode
            ) {

                /**
                 * Parents zonder current term.
                 */

                case 'parents':

                    $output =
                        implode(
                            (string)
                            $atts['separator'],
                            $parents
                        );

                    break;


                /**
                 * Parents + current term.
                 */

                case 'full':

                    $output =
                        $full;

                    break;


                /**
                 * Taxonomy label + current term.
                 */

                case 'label_current':

                    $output =
                        $label
                            ? $label
                                . (string)
                                $atts['label_separator']
                                . $current
                            : $current;

                    break;


                /**
                 * Taxonomy label + volledige hiërarchie.
                 */

                case 'label_full':

                    $output =
                        $label
                            ? $label
                                . (string)
                                $atts['label_separator']
                                . $full
                            : $full;

                    break;


                /**
                 * Alleen huidige term.
                 */

                default:

                    $output =
                        $current;
            }


        /**
         * ====================================================
         * TAXONOMY BASE ARCHIVE
         * ====================================================
         */

        } else {

            $taxonomy_object =
                tfsc_text_taxonomy_archive_object();


            if (
                ! $taxonomy_object
            ) {
                return '';
            }


            switch (
                $mode
            ) {

                /**
                 * Meervoud taxonomy label.
                 */

                case 'taxonomy_plural':

                    $output =
                        $taxonomy_object
                            ->labels
                            ->name
                        ??
                        $taxonomy_object
                            ->label
                        ??
                        '';

                    break;


                /**
                 * Enkelvoud taxonomy label.
                 */

                case 'taxonomy':
                default:

                    $output =
                        $taxonomy_object
                            ->labels
                            ->singular_name
                        ??
                        $taxonomy_object
                            ->label
                        ??
                        '';
            }


            $output =
                wp_strip_all_tags(
                    (string)
                    $output
                );
        }


        if (
            '' === $output
        ) {
            return '';
        }


        $output =
            tfsc_text_case(
                $output,
                $atts['case']
            );


        return
            (string)
            $atts['before']
            . $output
            . (string)
            $atts['after'];
    }
);


/**
 * ============================================================
 * 7. [tfsc_pods]
 * ============================================================
 *
 * Voorbeelden:
 *
 * [tfsc_pods field="intro"]
 *
 * [tfsc_pods field="functie"]
 *
 * [tfsc_pods field="sector" separator=", "]
 *
 * [tfsc_pods field="plaats" case="lower"]
 *
 *
 * ============================================================
 * BELANGRIJK VOOR WYSIWYG
 * ============================================================
 *
 * Voor scalar / tekstvelden wordt:
 *
 * $pod->display()
 *
 * gebruikt.
 *
 * Hierdoor gebruikt Pods zelf de ingestelde Output Options
 * van het veld.
 *
 * Dus bijvoorbeeld bij WYSIWYG:
 *
 * - wpautop
 * - sanitize HTML
 * - wptexturize
 * - convert_chars
 * - shortcodes
 *
 * hoeven hier NIET opnieuw door PHP uitgevoerd te worden.
 */

add_shortcode(
    'tfsc_pods',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'field'     => '',
                    'before'    => '',
                    'after'     => '',
                    'separator' => ', ',
                    'case'      => 'normal',
                ],
                $atts,
                'tfsc_pods'
            );


        /**
         * ----------------------------------------------------
         * FIELD
         * ----------------------------------------------------
         */

        $field =
            sanitize_key(
                $atts['field']
            );


        if (
            ! $field
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * POD CONTEXT
         * ----------------------------------------------------
         */

        $pod =
            tfsc_text_context_pod();


        if (
            ! $pod
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * RAW VALUE
         * ----------------------------------------------------
         *
         * field() gebruiken we hier alleen om te bepalen
         * of het om een scalar of relationship/array gaat.
         */

        $value =
            $pod->field(
                $field
            );


        if (
            null === $value ||
            false === $value ||
            '' === $value
        ) {
            return '';
        }


        /**
         * ====================================================
         * SCALAR / TEKST / WYSIWYG
         * ====================================================
         */

        if (
            ! is_array(
                $value
            ) &&
            ! is_object(
                $value
            )
        ) {

            /**
             * Pods verzorgt zelf de frontend output.
             *
             * Voor WYSIWYG worden hierdoor de Output Options
             * van het veld gerespecteerd.
             */

            $output =
                $pod->display(
                    $field
                );


            if (
                null === $output ||
                false === $output
            ) {
                return '';
            }


            $output =
                (string)
                $output;


            if (
                '' === trim(
                    $output
                )
            ) {
                return '';
            }


            /**
             * ------------------------------------------------
             * CASE
             * ------------------------------------------------
             *
             * Alleen toepassen wanneer de output geen HTML
             * bevat.
             *
             * Dit voorkomt dat WYSIWYG HTML kapot wordt
             * gemaakt door strtolower/sentence case.
             */

            if (
                $output ===
                wp_strip_all_tags(
                    $output
                )
            ) {

                $output =
                    tfsc_text_case(
                        $output,
                        $atts['case']
                    );
            }


        /**
         * ====================================================
         * RELATIONSHIP / ARRAY / OBJECT
         * ====================================================
         */

        } else {

            /**
             * Eén relationship normaliseren naar array.
             */

            if (
                is_object(
                    $value
                )
                ||
                (
                    is_array(
                        $value
                    )
                    &&
                    (
                        isset(
                            $value['name']
                        )
                        ||
                        isset(
                            $value['post_title']
                        )
                        ||
                        isset(
                            $value['title']
                        )
                    )
                )
            ) {

                $value =
                    [ $value ];
            }


            $names = [];


            foreach (
                (array)
                $value
                as $relation
            ) {

                /**
                 * --------------------------------------------
                 * ARRAY RELATIONSHIP
                 * --------------------------------------------
                 */

                if (
                    is_array(
                        $relation
                    )
                ) {

                    $name =
                        $relation['name']
                        ??
                        $relation['post_title']
                        ??
                        $relation['title']
                        ??
                        '';


                /**
                 * --------------------------------------------
                 * OBJECT RELATIONSHIP
                 * --------------------------------------------
                 */

                } elseif (
                    is_object(
                        $relation
                    )
                ) {

                    $name =
                        $relation->name
                        ??
                        $relation->post_title
                        ??
                        $relation->title
                        ??
                        '';


                /**
                 * --------------------------------------------
                 * ONBEKEND
                 * --------------------------------------------
                 */

                } else {

                    $name = '';
                }


                $name =
                    wp_strip_all_tags(
                        (string)
                        $name
                    );


                if (
                    '' !== $name
                ) {

                    $names[] =
                        $name;
                }
            }


            /**
             * Dubbelen verwijderen en samenvoegen.
             */

            $names =
                array_values(
                    array_unique(
                        $names
                    )
                );


            $output =
                implode(
                    (string)
                    $atts['separator'],
                    $names
                );


            if (
                '' === $output
            ) {
                return '';
            }


            /**
             * Relationships zijn gewone tekst,
             * dus case kan hier veilig worden toegepast.
             */

            $output =
                tfsc_text_case(
                    $output,
                    $atts['case']
                );
        }


        /**
         * ====================================================
         * OUTPUT
         * ====================================================
         */

        return
            (string)
            $atts['before']
            . $output
            . (string)
            $atts['after'];
    }
);

/**
 * v3.2: termarchief-vacatures delen de actieve terugval met de vacatureknop.
 * Geen match: open vacatures; overige Sources en Elementor-filters blijven intact.
 * TFSC - Elementor Posts filteren via Pods taxonomy relationships
 *
 * Query ID:
 * relationship_posts
 *
 * Doel:
 * Filtert een Elementor Posts/Loop Grid automatisch op basis van de
 * Pods relationshipvelden van de huidige post, CPT of taxonomy-term.
 *
 * Belangrijk:
 * - RAW Pods relationshipdata is leidend.
 * - Verschillende taxonomies = AND.
 * - Meerdere terms binnen dezelfde taxonomy = IN / OR.
 * - Elementor Source blijft leidend.
 * - relationship_vacature_button_url wordt bewust genegeerd.
 * - Werkt ook in Elementor Theme Builder preview voor posts/CPT's.
 */


/**
 * ============================================================
 * CONTEXT + POD
 * ============================================================
 *
 * Bepaalt het Pods-object van de huidige context:
 *
 * - taxonomy archive → Pod van de huidige term;
 * - post / CPT → Pod van de huidige post;
 * - Elementor Theme Builder → gebruikt indien beschikbaar
 *   tfsc_derived_rel_v3_get_context_post_id() om de echte
 *   preview-post te vinden.
 */

function tfsc_relposts_v3_get_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();

    /*
     * Taxonomy term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /*
     * Post / CPT / Elementor preview.
     */
    $post_id = 0;

    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v3_get_context_post_id();

    } elseif (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v2_get_context_post_id();
    }

    if (
        ! $post_id &&
        $object instanceof WP_Post &&
        'elementor_library'
        !==
        get_post_type( $object->ID )
    ) {
        $post_id =
            (int) $object->ID;
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * RAW RELATIONSHIP NORMALISEREN
 * ============================================================
 *
 * Pods kan relationshipdata als array of object teruggeven.
 * Deze functie maakt daar steeds dit formaat van:
 *
 * [
 *     [
 *         'taxonomy' => 'functie-inhoud',
 *         'term_id'  => 220,
 *     ],
 * ]
 *
 * De taxonomy wordt dus NIET afgeleid uit de fieldnaam.
 * De daadwerkelijke RAW relationshipdata bepaalt welke taxonomy
 * en term gebruikt worden.
 */

function tfsc_relposts_v3_normalize_relationship(
    $value
) {

    if ( empty( $value ) ) {
        return [];
    }

    /*
     * Eén relationship normaliseren naar een lijst.
     */
    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['taxonomy'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    if ( ! is_array( $value ) ) {
        return [];
    }

    $result = [];

    foreach ( $value as $relation ) {

        if ( is_array( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

        } elseif ( is_object( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

        } else {

            continue;
        }

        /*
         * Alleen echte, bestaande taxonomy-terms accepteren.
         */
        if (
            ! $taxonomy ||
            ! $term_id ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            $result[] = [
                'taxonomy' => $taxonomy,
                'term_id'  => $term_id,
            ];
        }
    }

    return $result;
}


/**
 * ============================================================
 * TAXONOMY HOORT BIJ ELEMENTOR SOURCE?
 * ============================================================
 *
 * Een relationship wordt alleen gebruikt als de betreffende
 * taxonomy gekoppeld is aan het post type dat Elementor als
 * Source gebruikt.
 */

function tfsc_relposts_v3_taxonomy_matches_source(
    $taxonomy,
    $post_types
) {

    $object =
        get_taxonomy(
            $taxonomy
        );

    if ( ! $object ) {
        return false;
    }

    return (bool) array_intersect(
        (array) $post_types,
        (array) $object->object_type
    );
}


/**
 * ============================================================
 * ELEMENTOR QUERY
 * ============================================================
 *
 * Query ID in Elementor:
 *
 * relationship_posts
 */

add_action(
    'elementor/query/relationship_posts',
    function( $query ) {

        // Termarchief + uitsluitend vacature-source: dezelfde selectie als de knop.
        // Bestaande Elementor-filters blijven als extra AND-groep behouden.
        if ( get_queried_object() instanceof WP_Term &&
             array_values((array) $query->get('post_type')) === ['vacature'] &&
             function_exists('tfsc_taxrel_v4_effective_relationship_groups') ) {
            $groups = tfsc_taxrel_v4_effective_relationship_groups();
            $status = tfsc_taxrel_v4_status_taxonomy();
            if ( ! taxonomy_exists($status) ) { $query->set('post__in', [0]); return; }
            $selection = ['relation' => 'AND', [
                'taxonomy' => $status, 'field' => 'slug',
                'terms' => [tfsc_taxrel_v4_open_status()], 'include_children' => false,
            ]];
            foreach ( $groups as $taxonomy => $ids ) {
                $method = function_exists('tfsc_get_combo_taxonomy_match_method')
                    ? tfsc_get_combo_taxonomy_match_method($taxonomy)
                    : ('kennisgebied' === $taxonomy ? 'AND' : 'OR');
                $selection[] = ['taxonomy' => $taxonomy, 'field' => 'term_id',
                    'terms' => $ids, 'include_children' => false,
                    'operator' => 'AND' === $method && count($ids) > 1 ? 'AND' : 'IN'];
            }
            $existing = $query->get('tax_query');
            $query->set('tax_query', $existing ? ['relation' => 'AND', $existing, $selection] : $selection);
            return;
        }

        $pod =
            tfsc_relposts_v3_get_pod();

        if ( ! $pod ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Elementor Source.
         */
        $post_types =
            array_values(
                array_filter(
                    (array) $query->get( 'post_type' )
                )
            );

        if ( ! $post_types ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        $fields =
            $pod->fields();

        if ( ! is_array( $fields ) || ! $fields ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Relationship terms groeperen per taxonomy.
         */
        $groups = [];

        foreach ( $fields as $field_name => $definition ) {

            if (
                ! is_string( $field_name ) ||
                0 !== strpos(
                    $field_name,
                    'relationship_'
                ) ||
                'relationship_vacature_button_url'
                ===
                $field_name
            ) {
                continue;
            }

            /*
             * RAW Pods relationship uitlezen.
             */
            $relationships =
                tfsc_relposts_v3_normalize_relationship(
                    $pod->field(
                        $field_name
                    )
                );

            foreach (
                $relationships
                as $relationship
            ) {

                $taxonomy =
                    $relationship['taxonomy'];

                /*
                 * Alleen gebruiken als taxonomy bij de
                 * Elementor Source hoort.
                 */
                if (
                    ! tfsc_relposts_v3_taxonomy_matches_source(
                        $taxonomy,
                        $post_types
                    )
                ) {
                    continue;
                }

                $groups[ $taxonomy ][] =
                    (int) $relationship['term_id'];
            }
        }

        /*
         * Dubbele en ongeldige IDs verwijderen.
         */
        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $ids
                            )
                        )
                    )
                );

            if ( $ids ) {
                $groups[ $taxonomy ] = $ids;
            } else {
                unset( $groups[ $taxonomy ] );
            }
        }

        /*
         * Geen bruikbare relationships:
         * bewust geen posts tonen.
         */
        if ( ! $groups ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Verschillende taxonomies = AND.
         * Meerdere terms binnen taxonomy = IN.
         */
        $relationship_query = [
            'relation' => 'AND',
        ];

        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $relationship_query[] = [
                'taxonomy'         => $taxonomy,
                'field'            => 'term_id',
                'terms'            => $ids,
                'operator'         => 'IN',
                'include_children' => true,
            ];
        }

        /*
         * Elementor kan al tax_query-voorwaarden bevatten, bijvoorbeeld
         * vac_status = Ingevuld uitsluiten. Die mogen niet worden vervangen.
         * De relationshipvoorwaarden worden daarom als extra AND-groep
         * naast de bestaande Elementor-query geplaatst.
         */
        $existing_tax_query = $query->get( 'tax_query' );

        if (
            is_array( $existing_tax_query ) &&
            ! empty( $existing_tax_query )
        ) {
            $combined_tax_query = [
                'relation' => 'AND',
                $existing_tax_query,
                $relationship_query,
            ];
        } else {
            $combined_tax_query = $relationship_query;
        }

        $query->set(
            'tax_query',
            $combined_tax_query
        );
    },
    20,
    1
);

/**
 * TFSC - DEBUG relationship_posts context
 *
 * Shortcode:
 * [tfsc_relposts_debug]
 */

add_shortcode(
    'tfsc_relposts_debug',
    function() {

        if ( ! current_user_can( 'manage_options' ) ) {
            return '';
        }

        if ( ! function_exists( 'pods' ) ) {
            return '<pre>Pods niet beschikbaar.</pre>';
        }

        $debug = [];

        $object =
            get_queried_object();

        $debug['queried_object_class'] =
            is_object( $object )
                ? get_class( $object )
                : gettype( $object );

        if ( $object instanceof WP_Post ) {

            $debug['queried_object_id'] =
                (int) $object->ID;

            $debug['queried_object_post_type'] =
                get_post_type(
                    $object->ID
                );
        }

        if ( $object instanceof WP_Term ) {

            $debug['queried_term_id'] =
                (int) $object->term_id;

            $debug['queried_taxonomy'] =
                $object->taxonomy;
        }


        /**
         * Context ID via v3.
         */
        $post_id = 0;

        if (
            function_exists(
                'tfsc_derived_rel_v3_get_context_post_id'
            )
        ) {

            $post_id =
                (int)
                tfsc_derived_rel_v3_get_context_post_id();
        }

        $debug['v3_context_post_id'] =
            $post_id;


        if ( $post_id ) {

            $post_type =
                get_post_type(
                    $post_id
                );

            $debug['context_post_type'] =
                $post_type;


            $pod =
                pods(
                    $post_type,
                    $post_id
                );


            $debug['pod_exists'] =
                (
                    $pod &&
                    $pod->exists()
                );


            if (
                $pod &&
                $pod->exists()
            ) {

                $fields =
                    $pod->fields();

                $relationships = [];


                foreach (
                    (array) $fields
                    as $field_name => $definition
                ) {

                    if (
                        ! is_string( $field_name ) ||
                        0 !== strpos(
                            $field_name,
                            'relationship_'
                        )
                    ) {
                        continue;
                    }


                    $raw =
                        $pod->field(
                            $field_name
                        );


                    $relationships[
                        $field_name
                    ] = [
                        'raw' =>
                            $raw,
                    ];


                    if (
                        function_exists(
                            'tfsc_relposts_v3_normalize_relationship'
                        )
                    ) {

                        $relationships[
                            $field_name
                        ]['normalized'] =
                            tfsc_relposts_v3_normalize_relationship(
                                $raw
                            );
                    }
                }


                $debug['relationships'] =
                    $relationships;
            }
        }


        return
            '<pre style="white-space:pre-wrap;">'
            .
            esc_html(
                print_r(
                    $debug,
                    true
                )
            )
            .
            '</pre>';
    }
);

/**
 * TFSC - Post Terms Buttons
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Toont de taxonomy terms die aan de huidige post / CPT
 * gekoppeld zijn als klikbare buttons.
 *
 * Werkt ook in Elementor Theme Builder previews wanneer
 * tfsc_derived_rel_v3_get_context_post_id() beschikbaar is.
 *
 *
 * ============================================================
 * SHORTCODE
 * ============================================================
 *
 * Alle publieke taxonomies met gekoppelde terms:
 *
 * [tfsc_post_terms]
 *
 * Eén taxonomy:
 *
 * [tfsc_post_terms taxonomy="kennisgebied"]
 *
 * Meerdere taxonomies:
 *
 * [tfsc_post_terms taxonomy="functienaam,kennisgebied,locatie"]
 *
 *
 * ============================================================
 * LINKS
 * ============================================================
 *
 * Iedere term linkt naar zijn normale native taxonomy URL.
 *
 * De TFSC combo-link omzetting wordt bewust tijdelijk
 * uitgeschakeld via:
 *
 * tfsc_force_native_term_link
 *
 *
 * ============================================================
 * OUTPUT
 * ============================================================
 *
 * .tfsc-post-terms
 * .tfsc-post-terms__item
 * .tfsc-post-terms__item--{taxonomy}
 */
/**
 * ============================================================
 * CSS
 * ============================================================
 *
 * Voeg onderstaande CSS toe in Elementor Custom CSS,
 * Site Settings of je eigen stylesheet:
 *
 *
 * .tfsc-post-terms {
 *     display: flex;
 *     flex-wrap: wrap;
 *     gap: 8px;
 * }
 *
 * .tfsc-post-terms__item {
 *     display: inline-flex;
 *     align-items: center;
 *     padding: 8px 14px;
 *     border: 1px solid currentColor;
 *     border-radius: 999px;
 *     text-decoration: none;
 * }
 *
 *
 * ============================================================
 * TAXONOMY-SPECIFIEKE STYLING
 * ============================================================
 *
 * Iedere button krijgt ook een class met de taxonomy name.
 *
 * Bijvoorbeeld:
 *
 * .tfsc-post-terms__item--kennisgebied
 * .tfsc-post-terms__item--functienaam
 * .tfsc-post-terms__item--locatie
 *
 * Daardoor kun je taxonomies afzonderlijk stylen.
 *
 * Voorbeeld:
 *
 * .tfsc-post-terms__item--kennisgebied {
 *     font-weight: 600;
 * }
 *
 *
 * ============================================================
 * HOVER
 * ============================================================
 *
 * Eventueel:
 *
 * .tfsc-post-terms__item:hover {
 *     text-decoration: none;
 * }
 */

add_shortcode(
    'tfsc_post_terms',
    function( $atts ) {

        $atts = shortcode_atts(
            [
                'taxonomy' => '',
            ],
            $atts,
            'tfsc_post_terms'
        );


        /**
         * ====================================================
         * HUIDIGE POST / ELEMENTOR PREVIEW
         * ====================================================
         */

        $post_id = 0;

        if (
            function_exists(
                'tfsc_derived_rel_v3_get_context_post_id'
            )
        ) {
            $post_id =
                (int)
                tfsc_derived_rel_v3_get_context_post_id();

        } elseif (
            function_exists(
                'tfsc_derived_rel_v2_get_context_post_id'
            )
        ) {
            $post_id =
                (int)
                tfsc_derived_rel_v2_get_context_post_id();
        }

        if ( ! $post_id ) {

            $object =
                get_queried_object();

            $post_id =
                $object instanceof WP_Post
                    ? (int) $object->ID
                    : (int) get_the_ID();
        }

        if ( ! $post_id ) {
            return '';
        }

        $post_type =
            get_post_type(
                $post_id
            );

        if ( ! $post_type ) {
            return '';
        }


        /**
         * ====================================================
         * TAXONOMIES BEPALEN
         * ====================================================
         *
         * Zonder taxonomy="" worden automatisch alle publieke
         * taxonomies van het huidige post type gebruikt.
         */

        $taxonomies =
            $atts['taxonomy']
                ? array_filter(
                    array_map(
                        'sanitize_key',
                        preg_split(
                            '/\s*,\s*/',
                            $atts['taxonomy']
                        )
                    )
                )
                : get_object_taxonomies(
                    $post_type,
                    'names'
                );

        $taxonomies =
            array_filter(
                $taxonomies,
                function( $taxonomy ) use ( $post_type ) {

                    $object =
                        get_taxonomy(
                            $taxonomy
                        );

                    return (
                        $object &&
                        ! empty( $object->public ) &&
                        in_array(
                            $post_type,
                            (array) $object->object_type,
                            true
                        )
                    );
                }
            );

        if ( ! $taxonomies ) {
            return '';
        }


        /**
         * ====================================================
         * TERMS + BUTTONS
         * ====================================================
         *
         * Alleen terms die daadwerkelijk aan de huidige
         * post gekoppeld zijn worden weergegeven.
         */

        $buttons = [];

        foreach ( $taxonomies as $taxonomy ) {

            $terms =
                wp_get_post_terms(
                    $post_id,
                    $taxonomy
                );

            if (
                is_wp_error( $terms ) ||
                ! $terms
            ) {
                continue;
            }

            foreach ( $terms as $term ) {

                if ( ! $term instanceof WP_Term ) {
                    continue;
                }

                /**
                 * Native term URL forceren.
                 * Hierdoor maken andere TFSC term_link filters
                 * hier geen vacature-combo URL van.
                 */
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ] = true;

                $url =
                    get_term_link(
                        $term
                    );

                unset(
                    $GLOBALS[
                        'tfsc_force_native_term_link'
                    ]
                );

                if ( is_wp_error( $url ) ) {
                    continue;
                }

                $buttons[] =
                    sprintf(
                        '<a class="tfsc-post-terms__item tfsc-post-terms__item--%1$s" href="%2$s">%3$s</a>',
                        esc_attr(
                            sanitize_html_class(
                                $taxonomy
                            )
                        ),
                        esc_url( $url ),
                        esc_html( $term->name )
                    );
            }
        }

        if ( ! $buttons ) {
            return '';
        }

        return
            '<div class="tfsc-post-terms">'
            . implode( '', $buttons )
            . '</div>';
    }
);

/**
 * Pods Admin - extra filters op Manage Pods tabel
 *
 * Voegt toe:
 * - Zoekveld voor Label + Name
 * - Type filter
 * - Storage Type filter
 * - Connection filter
 * - Reset knop
 *
 * Filters werken gecombineerd met AND-logica.
 * Alles gebeurt alleen client-side in de Pods adminlijst.
 */

add_action('admin_footer', function () {

    // Alleen in wp-admin.
    if (!is_admin()) {
        return;
    }

    // Alleen op Pods Admin pagina's.
    if (
        empty($_GET['page']) ||
        strpos((string) $_GET['page'], 'pods') === false
    ) {
        return;
    }

    ?>
    <style>
        #tfsc-pods-filters {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            align-items: center;
            margin: 14px 0 12px;
            padding: 12px;
            background: #fff;
            border: 1px solid #ccd0d4;
            box-shadow: 0 1px 1px rgba(0, 0, 0, 0.04);
        }

        #tfsc-pods-filters input[type="search"],
        #tfsc-pods-filters select {
            min-width: 180px;
            height: 32px;
        }

        #tfsc-pods-filters input[type="search"] {
            min-width: 240px;
        }

        #tfsc-pods-filter-count {
            margin-left: 5px;
            color: #646970;
            font-size: 13px;
        }

        .tfsc-pods-hidden {
            display: none !important;
        }
    </style>

    <script>
    document.addEventListener('DOMContentLoaded', function () {

        /*
         * Zoek de Manage Pods tabel.
         * We bepalen hem op basis van de kolomnamen zodat de snippet
         * zo min mogelijk afhankelijk is van Pods classes/IDs.
         */
        const tables = Array.from(document.querySelectorAll('table'));

        let podsTable = null;

        for (const table of tables) {
            const headers = Array.from(
                table.querySelectorAll('thead th')
            ).map(th => th.textContent.trim().toLowerCase());

            if (
                headers.includes('label') &&
                headers.includes('name') &&
                headers.includes('type') &&
                headers.includes('storage type') &&
                headers.includes('connections')
            ) {
                podsTable = table;
                break;
            }
        }

        if (!podsTable) {
            return;
        }

        const headers = Array.from(podsTable.querySelectorAll('thead th'));

        const getColumnIndex = function (name) {
            return headers.findIndex(
                th => th.textContent.trim().toLowerCase() === name.toLowerCase()
            );
        };

        const columnIndex = {
            label: getColumnIndex('Label'),
            name: getColumnIndex('Name'),
            type: getColumnIndex('Type'),
            storage: getColumnIndex('Storage Type'),
            connections: getColumnIndex('Connections')
        };

        if (
            columnIndex.label === -1 ||
            columnIndex.name === -1 ||
            columnIndex.type === -1 ||
            columnIndex.storage === -1 ||
            columnIndex.connections === -1
        ) {
            return;
        }

        const tbody = podsTable.querySelector('tbody');

        if (!tbody) {
            return;
        }

        const rows = Array.from(tbody.querySelectorAll('tr'));

        if (!rows.length) {
            return;
        }

        /*
         * Lees tekst uit een specifieke kolom.
         */
        const getCellText = function (row, index) {
            const cells = row.querySelectorAll('td');

            if (!cells[index]) {
                return '';
            }

            return cells[index].textContent.trim();
        };

        /*
         * Unieke waarden verzamelen voor dropdowns.
         */
        const getUniqueValues = function (index) {
            const values = new Set();

            rows.forEach(function (row) {
                const value = getCellText(row, index);

                if (
                    value &&
                    value !== '-' &&
                    value !== '—'
                ) {
                    values.add(value);
                }
            });

            return Array.from(values).sort(function (a, b) {
                return a.localeCompare(b, undefined, {
                    numeric: true,
                    sensitivity: 'base'
                });
            });
        };

        /*
         * Filterbalk bouwen.
         */
        const filterBar = document.createElement('div');
        filterBar.id = 'tfsc-pods-filters';

        const searchInput = document.createElement('input');
        searchInput.type = 'search';
        searchInput.id = 'tfsc-pods-search';
        searchInput.placeholder = 'Zoek Label of Name…';

        const typeSelect = document.createElement('select');
        typeSelect.id = 'tfsc-pods-type';

        const storageSelect = document.createElement('select');
        storageSelect.id = 'tfsc-pods-storage';

        const connectionSelect = document.createElement('select');
        connectionSelect.id = 'tfsc-pods-connection';

        const resetButton = document.createElement('button');
        resetButton.type = 'button';
        resetButton.className = 'button';
        resetButton.textContent = 'Reset';

        const countLabel = document.createElement('span');
        countLabel.id = 'tfsc-pods-filter-count';

        /*
         * Dropdown vullen.
         */
        const populateSelect = function (select, label, values) {
            const defaultOption = document.createElement('option');
            defaultOption.value = '';
            defaultOption.textContent = label;

            select.appendChild(defaultOption);

            values.forEach(function (value) {
                const option = document.createElement('option');
                option.value = value;
                option.textContent = value;
                select.appendChild(option);
            });
        };

        populateSelect(
            typeSelect,
            'Alle types',
            getUniqueValues(columnIndex.type)
        );

        populateSelect(
            storageSelect,
            'Alle storage types',
            getUniqueValues(columnIndex.storage)
        );

        populateSelect(
            connectionSelect,
            'Alle connections',
            getUniqueValues(columnIndex.connections)
        );

        filterBar.appendChild(searchInput);
        filterBar.appendChild(typeSelect);
        filterBar.appendChild(storageSelect);
        filterBar.appendChild(connectionSelect);
        filterBar.appendChild(resetButton);
        filterBar.appendChild(countLabel);

        /*
         * Filterbalk direct boven de tabel zetten.
         */
        podsTable.parentNode.insertBefore(filterBar, podsTable);

        /*
         * Filterlogica.
         *
         * Alle actieve filters moeten tegelijk overeenkomen:
         * search AND type AND storage AND connection
         */
        const applyFilters = function () {

            const searchValue = searchInput.value
                .trim()
                .toLowerCase();

            const typeValue = typeSelect.value;
            const storageValue = storageSelect.value;
            const connectionValue = connectionSelect.value;

            let visibleCount = 0;

            rows.forEach(function (row) {

                const label = getCellText(
                    row,
                    columnIndex.label
                );

                const name = getCellText(
                    row,
                    columnIndex.name
                );

                const type = getCellText(
                    row,
                    columnIndex.type
                );

                const storage = getCellText(
                    row,
                    columnIndex.storage
                );

                const connection = getCellText(
                    row,
                    columnIndex.connections
                );

                const searchText = (
                    label + ' ' + name
                ).toLowerCase();

                const matchesSearch =
                    !searchValue ||
                    searchText.includes(searchValue);

                const matchesType =
                    !typeValue ||
                    type === typeValue;

                const matchesStorage =
                    !storageValue ||
                    storage === storageValue;

                const matchesConnection =
                    !connectionValue ||
                    connection === connectionValue;

                const visible =
                    matchesSearch &&
                    matchesType &&
                    matchesStorage &&
                    matchesConnection;

                row.classList.toggle(
                    'tfsc-pods-hidden',
                    !visible
                );

                if (visible) {
                    visibleCount++;
                }
            });

            countLabel.textContent =
                visibleCount + ' van ' + rows.length + ' pods';
        };

        /*
         * Live filtering.
         */
        searchInput.addEventListener('input', applyFilters);
        typeSelect.addEventListener('change', applyFilters);
        storageSelect.addEventListener('change', applyFilters);
        connectionSelect.addEventListener('change', applyFilters);

        /*
         * Reset.
         */
        resetButton.addEventListener('click', function () {
            searchInput.value = '';
            typeSelect.value = '';
            storageSelect.value = '';
            connectionSelect.value = '';

            applyFilters();
            searchInput.focus();
        });

        /*
         * Initiële teller.
         */
        applyFilters();
    });
    </script>
    <?php
});

/**
 * TFSC - Pods Admin Connecties + Filters
 *
 * Voor:
 * Pods Admin > Edit Pods
 *
 * Functies:
 * - voegt kolom "Connecties" toe
 * - toont gekoppelde post types bij taxonomies
 * - zoekveld voor Label + Name
 * - filter op Type
 * - filter op Storage Type
 * - filter op Connectie
 * - filters kunnen gecombineerd worden
 * - resetknop
 *
 * Verandert niets aan Pods of de database.
 */

add_action( 'admin_footer', function() {

    /*
     * Alleen:
     * Pods Admin > Edit Pods
     */
    if (
        ! isset( $_GET['page'] ) ||
        'pods' !== sanitize_key( $_GET['page'] )
    ) {
        return;
    }


    /*
     * Niet uitvoeren wanneer een individuele Pod
     * wordt geopend/bewerkt.
     */
    if (
        isset( $_GET['action'] ) &&
        ! in_array(
            sanitize_key( $_GET['action'] ),
            [ '', 'manage' ],
            true
        )
    ) {
        return;
    }


    /*
     * ============================================
     * TAXONOMY → POST TYPE CONNECTIES OPHALEN
     * ============================================
     */

    $taxonomies = get_taxonomies(
        [],
        'objects'
    );

    $connections = [];


    foreach ( $taxonomies as $taxonomy ) {

        if (
            empty( $taxonomy->name ) ||
            empty( $taxonomy->object_type )
        ) {
            continue;
        }


        $labels = [];


        foreach ( $taxonomy->object_type as $post_type_name ) {

            $post_type = get_post_type_object(
                $post_type_name
            );


            if (
                $post_type &&
                ! empty( $post_type->labels->name )
            ) {

                $labels[] =
                    $post_type->labels->name;

            } else {

                $labels[] =
                    $post_type_name;
            }
        }


        $connections[ $taxonomy->name ] =
            array_values(
                array_unique( $labels )
            );
    }

    ?>

    <style>

        /*
         * ============================================
         * FILTERBALK
         * ============================================
         */

        #tfsc-pods-filters {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            align-items: center;

            margin: 12px 0;
            padding: 12px;

            background: #fff;
            border: 1px solid #c3c4c7;

            box-sizing: border-box;
        }


        #tfsc-pods-filters input[type="search"] {
            min-width: 260px;
        }


        #tfsc-pods-filters select {
            min-width: 180px;
        }


