/**
 * TFSC - Virtuele Beroepengids-basearchieven in Rank Math sitemap
 *
 * WordPress Code Snippets ID: 215
 * Versie: 1.3
 *
 * DOEL
 * ============================================================
 * Snippet 113 maakt virtuele taxonomy-basearchieven zoals:
 *
 * /beroepengids/functienamen/
 * /beroepengids/functie-inhoud/
 * /beroepengids/opleidingsniveaus/
 * /beroepengids/studierichtingen/
 *
 * Deze URL's zijn geen pagina en geen echte taxonomyterm. Rank Math kan ze
 * daarom niet automatisch uit gewone WordPress-objecten afleiden. Deze
 * snippet voegt uitsluitend de toegestane, publieke Beroepengids-bases als
 * extra URL toe aan de eerste pagina van page-sitemap.xml.
 *
 * BELANGRIJK
 * ============================================================
 * Gewone taxonomy-sitemaps worden volledig door de Rank Math-instellingen
 * beheerd. Deze snippet voegt geen taxonomy-sitemap handmatig toe aan de
 * sitemap-index en omzeilt dus niet de instellingen "Include in Sitemap" en
 * "Include Empty Terms".
 *
 * AFBAKENING
 * ============================================================
 * - De allowlist en routing van snippet 113 blijven leidend.
 * - Alleen taxonomies met rewrite-prefix `beroepengids/` worden toegevoegd.
 * - Gewone taxonomytermarchieven en taxonomiesitemaps blijven aan Rank Math.
 * - Vacature-comboarchieven en hun dimensiediepte blijven aan de combo-snippet.
 * - Er worden geen combinaties aan page-sitemap.xml toegevoegd.
 */


/**
 * Geeft alle geldige virtuele Beroepengids-base-URL's terug.
 *
 * @return string[]
 */
function tfsc_beroepengids_base_sitemap_urls() {

	if ( ! function_exists( 'tfsc_taxonomy_base_archive_allowed' ) ) {
		return [];
	}

	$urls = [];

	foreach (
		get_taxonomies(
			[
				'public' => true,
			],
			'objects'
		)
		as $taxonomy
	) {

		if (
			! $taxonomy instanceof WP_Taxonomy ||
			! tfsc_taxonomy_base_archive_allowed( $taxonomy->name )
		) {
			continue;
		}

		$slug = trim(
			(string) (
				$taxonomy->rewrite['slug']
				?? ''
			),
			'/'
		);

		if (
			! $slug ||
			0 !== strpos( $slug, 'beroepengids/' )
		) {
			continue;
		}

		$urls[] = home_url( '/' . $slug . '/' );
	}

	$urls = array_values(
		array_unique(
			array_filter( $urls )
		)
	);

	sort( $urls, SORT_NATURAL | SORT_FLAG_CASE );

	return $urls;
}


/**
 * Voeg uitsluitend de virtuele bases toe aan page-sitemap.xml.
 * Rank Math past deze filter alleen op de eerste sitemap-pagina toe.
