	function( $content ) {

		foreach ( tfsc_beroepengids_base_sitemap_urls() as $url ) {

			$loc = esc_xml( $url );

			if (
				false !== strpos(
					(string) $content,
					'<loc>' . $loc . '</loc>'
				)
			) {
				continue;
			}

			$content .=
				"\n\t<url>\n"
				. "\t\t<loc>"
				. $loc
				. "</loc>\n"
				. "\t</url>";
		}

		return $content;
	},
	20
);


