/**
 * Houd alle tekstuitvoer schoon en voorspelbaar.
 */
function tfsc_filter_knowledge_archive_seo_value( $current, $key ) {
    $seo = tfsc_knowledge_archive_seo_data();

    if ( ! $seo || empty( $seo[ $key ] ) ) {
        return $current;
    }

    return wp_strip_all_tags( $seo[ $key ] );
}

