/**
 * TFSC - Virtuele Beroepengids-basearchieven in Rank Math sitemap
 *
 * WordPress Code Snippets ID: 215
 *
 * DOEL
 * ============================================================
 * Snippet 113 maakt virtuele taxonomy-basearchieven zoals:
 *
 * /beroepengids/functienamen/
 * /beroepengids/functie-inhoud/
 * /beroepengids/opleidingen/
 *
 * Deze URL's zijn geen pagina en geen echte taxonomyterm. Rank Math kan ze
 * daarom niet automatisch uit de gewone WordPress-objecten afleiden. Deze
 * snippet voegt uitsluitend de toegestane, publieke Beroepengids-bases als
 * extra URL toe aan de eerste pagina van page-sitemap.xml.
 *
 * AFBAKENING
 * ============================================================
 * - De allowlist van snippet 113 blijft leidend.
 * - Alleen taxonomies met rewrite-prefix `beroepengids/` worden toegevoegd.
 * - Gewone taxonomytermarchieven blijven aan Rank Math zelf.
 * - Vacature-comboarchieven blijven aan snippet 148.
 * - Er worden geen duizenden combinaties aan page-sitemap.xml toegevoegd.
 * - Het nieuwe beroep_opleiding-sitemapbestand wordt expliciet aan de index
 *   gekoppeld zolang Rank Math het door nul gekoppelde artikelen weglaat.
 */


/**
 * Geeft alle geldige virtuele Beroepengids-base-URL's terug.
 *
 * @return string[]
 */
function tfsc_beroepengids_base_sitemap_urls() {

    if ( ! function_exists( 'tfsc_taxonomy_base_archive_allowed' ) ) {
        return [];
    }

    $urls = [];

    foreach (
        get_taxonomies(
            [
                'public' => true,
            ],
            'objects'
        )
        as $taxonomy
    ) {

        if (
            ! $taxonomy instanceof WP_Taxonomy ||
            ! tfsc_taxonomy_base_archive_allowed( $taxonomy->name )
        ) {
            continue;
        }

        $slug = trim(
            (string) (
                $taxonomy->rewrite['slug']
                ?? ''
            ),
            '/'
        );

        if (
            ! $slug ||
            0 !== strpos( $slug, 'beroepengids/' )
        ) {
            continue;
        }

        $urls[] = home_url( '/' . $slug . '/' );
    }

    $urls = array_values(
        array_unique(
            array_filter( $urls )
        )
    );

    sort( $urls, SORT_NATURAL | SORT_FLAG_CASE );

    return $urls;
}


/**
 * Voeg de virtuele bases toe aan page-sitemap.xml.
 * Rank Math past deze filter uitsluitend op de eerste sitemap-pagina toe.
 */
add_filter(
    'rank_math/sitemap/page_content',
    function( $content ) {

        foreach ( tfsc_beroepengids_base_sitemap_urls() as $url ) {

            $loc = esc_url( $url );

            if (
                false !== strpos(
                    (string) $content,
                    '<loc>' . $loc . '</loc>'
                )
            ) {
                continue;
            }

            $content .=
                "\n\t<url>\n"
                . "\t\t<loc>"
                . $loc
                . "</loc>\n"
                . "\t</url>";
        }

        return $content;
    },
    20
);


/**
 * Rank Math kan een taxonomy-sitemap met `lege termen opnemen` correct
 * genereren, maar laat die sitemap uit de index zolang alle terms nog nul
 * gekoppelde Beroepengids-artikelen hebben. De sitemap zelf bevat al wel alle
 * 29 inhoudelijk gevulde termen. Daarom koppelen we hem expliciet aan de index.
 */
add_filter(
    'rank_math/sitemap/index',
    function( $xml ) {

        if ( ! taxonomy_exists( 'beroep_opleiding' ) ) {
            return $xml;
        }

        $url = home_url( '/beroep_opleiding-sitemap.xml' );
        $loc = esc_url( $url );

        if (
            false !== strpos(
                (string) $xml,
                '<loc>' . $loc . '</loc>'
            )
        ) {
            return $xml;
        }

        $xml .=
            "\n\t<sitemap>\n"
            . "\t\t<loc>"
            . $loc
            . "</loc>\n"
            . "\t</sitemap>";

        return $xml;
    },
    20
);


/**
 * Eenmalig de page-sitemapcache vernieuwen na invoering van deze versie.
 */
add_action(
    'init',
    function() {

        $version = '2026-10-18-v2';

        if (
            get_option( 'tfsc_beroep_base_sitemap_version' ) === $version
        ) {
            return;
        }

        if ( class_exists( '\\RankMath\\Sitemap\\Cache' ) ) {
            \RankMath\Sitemap\Cache::invalidate_storage();
        }

        update_option(
            'tfsc_beroep_base_sitemap_version',
            $version,
            false
        );
    },
    100
);

/**
 * ============================================================
 * TFSC - GENERIC ARCHIVE SETTINGS FIELDS
 * ============================================================
 *
 * Doel
 * ----
 * Deze snippet leest centrale archivevelden uit de Pods Settings Pod:
 *
 * pods_archief_instellingen
 *
 * en maakt deze beschikbaar als:
 *
 * - shortcode
 * - Elementor Dynamic Tag
 *
 *
 * ============================================================
 * HANDLEIDING
 * ============================================================
 *
 * 1. CPT'S TOEVOEGEN
 * ------------------------------------------------------------
 *
 * Iedere CPT krijgt hieronder een vaste "archive context".
 *
 * Voorbeeld:
 *
 * WordPress CPT:
 * beroepengids
 *
 * Archive context:
 * beroep
 *
 * Daardoor blijven bestaande velden werken:
 *
 * archive_cpt_beroep_intro
 * archive_cpt_beroep_description
 *
 *
 * Voor kennisbank:
 *
 * WordPress CPT:
 * kennisbankartikelen
 *
 * Archive context:
 * kennisbankartikel
 *
 * Velden:
 *
 * archive_cpt_kennisbankartikel_intro
 * archive_cpt_kennisbankartikel_description
 *
 *
 * Nieuwe CPT toevoegen?
 *
 * Voeg hem alleen toe in:
 *
 * tfsc_archive_settings_config()
 *
 * Bijvoorbeeld:
 *
 * 'nieuwsartikelen' => [
 *     'context' => 'nieuwsartikel',
 * ],
 *
 *
 * ============================================================
 * 2. TAXONOMY TOEVOEGEN
 * ============================================================
 *
 * Taxonomies hoeven NIET apart in deze PHP-code geregistreerd
 * te worden.
 *
 * Ze moeten alleen gekoppeld zijn aan de juiste WordPress CPT.
 *
 *
 * AANBEVOLEN NAAMGEVING:
 *
 * {context}_{taxonomy}
 *
 *
 * Voor beroepengids:
 *
 * beroep_functienaam
 * beroep_bedrijfssector
 * beroep_opleiding
 *
 *
 * Voor kennisbankartikelen:
 *
 * kennisbankartikel_onderwerp
 * kennisbankartikel_techniek
 * kennisbankartikel_sector
 *
 *
 * De prefix wordt automatisch verwijderd.
 *
 * Dus:
 *
 * kennisbankartikel_onderwerp
 *
 * wordt:
 *
 * onderwerp
 *
 *
 * ============================================================
 * 3. PODS VELDEN VOOR TAXONOMY ARCHIVES
 * ============================================================
 *
 * Structuur:
 *
 * archive_{context}_{taxonomy}_{field}
 *
 *
 * Voorbeeld beroepengids:
 *
 * taxonomy:
 * beroep_functienaam
 *
 * velden:
 *
 * archive_beroep_functienaam_intro
 * archive_beroep_functienaam_description
 *
 *
 * Voorbeeld kennisbank:
 *
 * taxonomy:
 * kennisbankartikel_onderwerp
 *
 * velden:
 *
 * archive_kennisbankartikel_onderwerp_intro
 * archive_kennisbankartikel_onderwerp_description
 *
 *
 * ============================================================
 * 4. PODS VELDEN VOOR CPT ARCHIVES
 * ============================================================
 *
 * Structuur:
 *
 * archive_cpt_{context}_{field}
 *
 *
 * Beroepengids:
 *
 * archive_cpt_beroep_intro
 * archive_cpt_beroep_description
 *
 *
 * Kennisbank:
 *
 * archive_cpt_kennisbankartikel_intro
 * archive_cpt_kennisbankartikel_description
 *
 *
 * ============================================================
 * 5. ELEMENTOR
 * ============================================================
 *
 * Dynamic Tag:
 *
 * TFSC Archive Settings Field
 *
 *
 * Bij Field vul je alleen in:
 *
 * intro
 *
 * of:
 *
 * description
 *
 *
 * Elementor hoeft dus niet te weten:
 *
 * - welke CPT actief is
 * - welke taxonomy actief is
 * - welke context gebruikt moet worden
 *
 *
 * ============================================================
 * 6. SHORTCODE
 * ============================================================
 *
 * [tfsc_archive_field field="intro"]
 *
 * [tfsc_archive_field field="description"]
 *
 *
 * ============================================================
 * 7. BELANGRIJK
 * ============================================================
 *
 * De Pods GROUP NAME wordt nergens gebruikt.
 *
 * Dus bijvoorbeeld:
 *
 * archive_beroep_taxonomies
 * archive_kennisbankartikelen
 *
 * zijn alleen organisatorische groepsnamen in Pods.
 *
 * Alleen de daadwerkelijke FIELD NAME is belangrijk.
 *
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_archive_settings_pod_name() {

    return 'pods_archief_instellingen';
}


/**
 * Centrale CPT → archive context mapping.
 *
 * Dit is de belangrijkste configuratie van deze snippet.
 */

function tfsc_archive_settings_config() {

    return [

        /**
         * Legacy structuur bewust behouden.
         *
         * CPT:
         * beroepengids
         *
         * Archive context:
         * beroep
         */

        'beroepengids' => [
            'context' => 'beroep',
        ],


        /**
         * Kennisbank.
         *
         * CPT:
         * kennisbankartikelen
         *
         * Archive context:
         * kennisbankartikel
         */

        'kennisbankartikelen' => [
            'context' => 'kennisbankartikel',
        ],


        /**
         * Nieuwe CPT later toevoegen:
         *
         * 'voorbeeldartikelen' => [
         *     'context' => 'voorbeeldartikel',
         * ],
         */
    ];
}


/**
 * ============================================================
 * 2. CONTEXT UIT CPT HALEN
 * ============================================================
 */

function tfsc_archive_settings_context_from_post_type(
    $post_type
) {

    $post_type =
        sanitize_key(
            $post_type
        );

    if ( ! $post_type ) {
        return '';
    }

    $config =
        tfsc_archive_settings_config();

    /**
     * CPT staat expliciet in configuratie.
     */

    if (
        isset(
            $config[ $post_type ]['context']
        )
    ) {

        return sanitize_key(
            $config[ $post_type ]['context']
        );
    }

    /**
     * Fallback:
     *
     * CPT slug zelf gebruiken.
     *
     * Hierdoor blijft de code ook werken voor CPT's
     * waarvoor nog geen afwijkende context nodig is.
     */

    return $post_type;
}


/**
 * ============================================================
 * 3. RAW TAXONOMY BEPALEN
 * ============================================================
 *
 * Ondersteunt:
 *
 * - TFSC taxonomy base archives
 * - normale WordPress taxonomy term archives
 */

function tfsc_archive_settings_raw_taxonomy() {

    /**
     * --------------------------------------------------------
     * TFSC TAXONOMY BASE ARCHIVE
     * --------------------------------------------------------
     *
     * Deze functie bestaat al binnen TFSC en bepaalt
     * bijvoorbeeld:
     *
     * beroep_functienaam
     *
     * wanneer we ons op de functienaam-base bevinden.
     */

    if (
        function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {

        $taxonomy =
            tfsc_get_current_taxonomy_archive();

        if (
            is_object( $taxonomy ) &&
            ! empty( $taxonomy->name )
        ) {
            $taxonomy =
                $taxonomy->name;
        }

        if ( $taxonomy ) {

            return sanitize_key(
                $taxonomy
            );
        }
    }


    /**
     * --------------------------------------------------------
     * NORMAAL WORDPRESS TERM ARCHIVE
     * --------------------------------------------------------
     */

    if (
        is_tax() ||
        is_category() ||
        is_tag()
    ) {

        $object =
            get_queried_object();

        if (
            $object &&
            ! empty(
                $object->taxonomy
            )
        ) {

            return sanitize_key(
                $object->taxonomy
            );
        }
    }


    return '';
}


/**
 * ============================================================
 * 4. CPT VAN EEN TAXONOMY BEPALEN
 * ============================================================
 */

function tfsc_archive_settings_post_type_from_taxonomy(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );

    if ( ! $taxonomy ) {
        return '';
    }


    $config =
        tfsc_archive_settings_config();


    /**
     * --------------------------------------------------------
     * EERST CONTEXT / CPT PREFIX CONTROLEREN
     * --------------------------------------------------------
     *
     * Dit ondersteunt bijvoorbeeld:
     *
     * beroep_functienaam
     *
     * en:
     *
     * kennisbankartikel_onderwerp
     */

    foreach (
        $config
        as $post_type => $settings
    ) {

        $context =
            ! empty(
                $settings['context']
            )
                ? sanitize_key(
                    $settings['context']
                )
                : sanitize_key(
                    $post_type
                );


        $prefixes = [

            $context . '_',
            $context . '-',

            $post_type . '_',
            $post_type . '-',
        ];


        foreach (
            $prefixes
            as $prefix
        ) {

            if (
                0 === strpos(
                    $taxonomy,
                    $prefix
                )
            ) {

                return sanitize_key(
                    $post_type
                );
            }
        }
    }


    /**
     * --------------------------------------------------------
     * FALLBACK VIA WORDPRESS TAXONOMY REGISTRATIE
     * --------------------------------------------------------
     */

    $taxonomy_object =
        get_taxonomy(
            $taxonomy
        );

    if (
        ! $taxonomy_object ||
        empty(
            $taxonomy_object->object_type
        )
    ) {
        return '';
    }


    $post_types =
        array_values(
            array_filter(
                (array)
                $taxonomy_object->object_type
            )
        );


    if (
        empty(
            $post_types
        )
    ) {
        return '';
    }


    /**
     * Als taxonomy aan meerdere CPT's hangt,
     * proberen we eerst een CPT uit onze configuratie.
     */

    foreach (
        $post_types
        as $post_type
    ) {

        if (
            isset(
                $config[ $post_type ]
            )
        ) {

            return sanitize_key(
                $post_type
            );
        }
    }


    /**
     * Anders eerste geregistreerde CPT.
     */

    return sanitize_key(
        $post_types[0]
    );
}


/**
 * ============================================================
 * 5. HUIDIGE CPT BEPALEN
 * ============================================================
 */

function tfsc_archive_settings_post_type() {

    /**
     * --------------------------------------------------------
     * CPT ARCHIVE
     * --------------------------------------------------------
     */

    if (
        is_post_type_archive()
    ) {

        $post_type =
            get_query_var(
                'post_type'
            );


        if (
            is_array(
                $post_type
            )
        ) {

            $post_type =
                reset(
                    $post_type
                );
        }


        if ( $post_type ) {

            return sanitize_key(
                $post_type
            );
        }


        /**
         * Fallback via queried object.
         */

        $object =
            get_queried_object();


        if (
            $object &&
            ! empty(
                $object->name
            )
        ) {

            return sanitize_key(
                $object->name
            );
        }
    }


    /**
     * --------------------------------------------------------
     * TAXONOMY ARCHIVE
     * --------------------------------------------------------
     */

    $taxonomy =
        tfsc_archive_settings_raw_taxonomy();


    if ( $taxonomy ) {

        return
            tfsc_archive_settings_post_type_from_taxonomy(
                $taxonomy
            );
    }


    return '';
}


/**
 * ============================================================
 * 6. HUIDIGE ARCHIVE CONTEXT
 * ============================================================
 */

function tfsc_archive_settings_context() {

    $post_type =
        tfsc_archive_settings_post_type();


    if ( ! $post_type ) {
        return '';
    }


    return
        tfsc_archive_settings_context_from_post_type(
            $post_type
        );
}


/**
 * ============================================================
 * 7. TAXONOMY NORMALISEREN
 * ============================================================
 *
 * beroep_functienaam
 * → functienaam
 *
 * beroepengids_functienaam
 * → functienaam
 *
 * kennisbankartikel_onderwerp
 * → onderwerp
 *
 * kennisbankartikelen_onderwerp
 * → onderwerp
 */

function tfsc_archive_settings_normalize_taxonomy(
    $taxonomy
) {

    $taxonomy =
        sanitize_key(
            $taxonomy
        );


    if ( ! $taxonomy ) {
        return '';
    }


    $post_type =
        tfsc_archive_settings_post_type();


    $context =
        tfsc_archive_settings_context();


    $prefixes = [];


    /**
     * CPT prefix.
     */

    if ( $post_type ) {

        $prefixes[] =
            $post_type . '_';

        $prefixes[] =
            $post_type . '-';
    }


    /**
     * Archive context prefix.
     */

    if ( $context ) {

        $prefixes[] =
            $context . '_';

        $prefixes[] =
            $context . '-';
    }


    $prefixes =
        array_unique(
            $prefixes
        );


    /**
     * Langste prefix eerst.
     */

    usort(
        $prefixes,
        function(
            $a,
            $b
        ) {

            return
                strlen( $b )
                <=>
                strlen( $a );
        }
    );


    foreach (
        $prefixes
        as $prefix
    ) {

        if (
            0 === strpos(
                $taxonomy,
                $prefix
            )
        ) {

            return sanitize_key(
                substr(
                    $taxonomy,
                    strlen(
                        $prefix
                    )
                )
            );
        }
    }


    /**
     * Geen prefix gevonden.
     *
     * Dan taxonomy slug ongewijzigd gebruiken.
     */

    return $taxonomy;
}


/**
 * ============================================================
 * 8. HUIDIGE GENORMALISEERDE TAXONOMY
 * ============================================================
 */

function tfsc_archive_settings_taxonomy() {

    $taxonomy =
        tfsc_archive_settings_raw_taxonomy();


    if ( ! $taxonomy ) {
        return '';
    }


    return
        tfsc_archive_settings_normalize_taxonomy(
            $taxonomy
        );
}


/**
 * ============================================================
 * 9. PODS FIELD NAME OPBOUWEN
 * ============================================================
 */

function tfsc_archive_settings_field_name(
    $field
) {

    $field =
        sanitize_key(
            $field
        );


    if ( ! $field ) {
        return '';
    }


    $context =
        tfsc_archive_settings_context();


    if ( ! $context ) {
        return '';
    }


    /**
     * --------------------------------------------------------
     * TAXONOMY ARCHIVE
     * --------------------------------------------------------
     *
     * archive_{context}_{taxonomy}_{field}
     */

    $taxonomy =
        tfsc_archive_settings_taxonomy();


    /**
     * --------------------------------------------------------
     * LEGACY PODS FIELD ALIAS
     * --------------------------------------------------------
     *
     * De actieve WordPress-taxonomie heet:
     *
     * beroep_opleidingsniveau
     *
     * De bestaande centrale Pods-velden gebruiken echter:
     *
     * archive_beroep_opleiding_intro
     * archive_beroep_opleiding_description
     *
     * Daarom wordt uitsluitend voor het opbouwen van de Pods-
     * veldnaam `opleidingsniveau` vertaald naar `opleiding`.
     * De taxonomie, URL's en termkoppelingen zelf veranderen niet.
     */

    $taxonomy_field_aliases = [
        'opleidingsniveau' => 'opleiding',
    ];


    if (
        isset(
            $taxonomy_field_aliases[ $taxonomy ]
        )
    ) {

        $taxonomy =
            sanitize_key(
                $taxonomy_field_aliases[ $taxonomy ]
            );
    }


    if ( $taxonomy ) {

        return sanitize_key(

            'archive_'
            . $context
            . '_'
            . $taxonomy
            . '_'
            . $field

        );
    }


    /**
     * --------------------------------------------------------
     * CPT ARCHIVE
     * --------------------------------------------------------
     *
     * archive_cpt_{context}_{field}
     */

    if (
        is_post_type_archive()
    ) {

        return sanitize_key(

            'archive_cpt_'
            . $context
            . '_'
            . $field

        );
    }


    return '';
}


/**
 * ============================================================
 * 10. PODS VALUE OPHALEN
 * ============================================================
 */

function tfsc_archive_settings_value(
    $field
) {

    if (
        ! function_exists(
            'pods'
        )
    ) {
        return '';
    }


    $field_name =
        tfsc_archive_settings_field_name(
            $field
        );


    if ( ! $field_name ) {
        return '';
    }


    $pod =
        pods(
            tfsc_archive_settings_pod_name()
        );


    if ( ! $pod ) {
        return '';
    }


    $value =
        $pod->field(
            $field_name
        );


    if (
        null === $value ||
        false === $value
    ) {
        return '';
    }


    /**
     * Tekst / WYSIWYG formatteren.
     */

    if (
        ! is_array( $value ) &&
        ! is_object( $value )
    ) {

        $value =
            do_shortcode(
                wpautop(
                    (string)
                    $value
                )
            );


        $value =
            wp_kses_post(
                $value
            );
    }


    return $value;
}


/**
 * ============================================================
 * 11. SHORTCODE
 * ============================================================
 *
 * [tfsc_archive_field field="intro"]
 *
 * [tfsc_archive_field field="description"]
 */

add_shortcode(
    'tfsc_archive_field',
    function(
        $atts
    ) {

        $atts =
            shortcode_atts(
                [
                    'field' => '',
                ],
                $atts,
                'tfsc_archive_field'
            );


        $value =
            tfsc_archive_settings_value(
                $atts['field']
            );


        if (
            is_array( $value ) ||
            is_object( $value )
        ) {
            return '';
        }


        return (string)
            $value;
    }
);


/**
 * ============================================================
 * 12. ELEMENTOR DYNAMIC TAG
 * ============================================================
 *
 * Dynamic Tag:
 *
 * TFSC Archive Settings Field
 *
 * Field:
 *
 * intro
 *
 * of:
 *
 * description
 */

add_action(
    'elementor/dynamic_tags/register',
    function(
        $dynamic_tags
    ) {

        if (
            ! class_exists(
                '\Elementor\Core\DynamicTags\Tag'
            )
        ) {
            return;
        }


        class TFSC_Archive_Settings_Field_Tag
            extends
            \Elementor\Core\DynamicTags\Tag {


            public function get_name() {

                return
                    'tfsc-archive-settings-field';
            }


            public function get_title() {

                return
                    'TFSC Archive Settings Field';
            }


            public function get_group() {

                return 'site';
            }


            public function get_categories() {

                return [

                    \Elementor\Modules\DynamicTags\Module
                        ::TEXT_CATEGORY,

                ];
            }


            protected function register_controls() {

                $this->add_control(
                    'field',
                    [

                        'label' =>
                            'Field',

                        'type' =>
                            \Elementor\Controls_Manager
                                ::TEXT,

                        'placeholder' =>
                            'intro',

                    ]
                );
            }


            public function render() {

                $field =
                    $this->get_settings(
                        'field'
                    );


                if ( ! $field ) {
                    return;
                }


                $value =
                    tfsc_archive_settings_value(
                        $field
                    );


                if (
                    is_array( $value ) ||
                    is_object( $value )
                ) {
                    return;
                }


                echo (string)
                    $value;
            }
        }


        $dynamic_tags->register(

            new TFSC_Archive_Settings_Field_Tag()

        );
    }
);

add_filter( 'elementor/utils/get_the_archive_title', function( $title ) {

    if ( is_category() ) {
        return single_cat_title( '', false );
    }

    if ( is_tag() ) {
        return single_tag_title( '', false );
    }

    if ( is_tax() ) {
        return single_term_title( '', false );
    }

    if ( is_post_type_archive() ) {
        return post_type_archive_title( '', false );
    }

    return $title;
});

/**
 * Tijdelijk alleen-lezen sitebreed Rank Math-overzicht.
 */

add_action(
    'rest_api_init',
    function() {
        register_rest_route(
            'tfsc-audit/v1',
            '/rank-math-sitewide',
            [
                'methods'             => 'GET',
                'permission_callback' => function() {
                    return current_user_can( 'manage_options' );
                },
                'callback'            => function() {
                    $titles  = get_option( 'rank-math-options-titles', [] );
                    $sitemap = get_option( 'rank-math-options-sitemap', [] );
                    $titles  = is_array( $titles ) ? $titles : [];
                    $sitemap = is_array( $sitemap ) ? $sitemap : [];

                    $taxonomies = [];

                    foreach ( get_taxonomies( [ 'public' => true ], 'objects' ) as $taxonomy ) {
                        $name       = $taxonomy->name;
                        $total      = wp_count_terms( [ 'taxonomy' => $name, 'hide_empty' => false ] );
                        $non_empty  = wp_count_terms( [ 'taxonomy' => $name, 'hide_empty' => true ] );
                        $total      = is_wp_error( $total ) ? null : (int) $total;
                        $non_empty  = is_wp_error( $non_empty ) ? null : (int) $non_empty;

                        $taxonomies[] = [
                            'name'            => $name,
                            'label'           => $taxonomy->label,
                            'object_type'     => array_values( (array) $taxonomy->object_type ),
                            'total_terms'     => $total,
                            'non_empty_terms' => $non_empty,
                            'empty_terms'     => null === $total || null === $non_empty ? null : $total - $non_empty,
                            'title'           => $titles[ 'tax_' . $name . '_title' ] ?? null,
                            'description'     => $titles[ 'tax_' . $name . '_description' ] ?? null,
                            'custom_robots'   => $titles[ 'tax_' . $name . '_custom_robots' ] ?? null,
                            'robots'          => $titles[ 'tax_' . $name . '_robots' ] ?? null,
                            'seo_controls'    => $titles[ 'tax_' . $name . '_add_meta_box' ] ?? null,
                            'sitemap'         => $sitemap[ 'tax_' . $name . '_sitemap' ] ?? null,
                            'include_empty'   => $sitemap[ 'tax_' . $name . '_include_empty' ] ?? null,
                        ];
                    }

                    $post_types = [];

                    foreach ( get_post_types( [ 'public' => true ], 'objects' ) as $post_type ) {
                        $name   = $post_type->name;
                        $counts = wp_count_posts( $name );

                        $post_types[] = [
                            'name'          => $name,
                            'label'         => $post_type->label,
                            'has_archive'   => (bool) $post_type->has_archive,
                            'published'     => isset( $counts->publish ) ? (int) $counts->publish : 0,
                            'title'         => $titles[ 'pt_' . $name . '_title' ] ?? null,
                            'description'   => $titles[ 'pt_' . $name . '_description' ] ?? null,
                            'custom_robots' => $titles[ 'pt_' . $name . '_custom_robots' ] ?? null,
                            'robots'        => $titles[ 'pt_' . $name . '_robots' ] ?? null,
                            'seo_controls'  => $titles[ 'pt_' . $name . '_add_meta_box' ] ?? null,
                            'sitemap'       => $sitemap[ 'pt_' . $name . '_sitemap' ] ?? null,
                        ];
                    }

                    return rest_ensure_response(
                        [
                            'noindex_empty_taxonomies' => $titles['noindex_empty_taxonomies'] ?? null,
                            'taxonomies'                => $taxonomies,
                            'post_types'                => $post_types,
                        ]
                    );
                },
            ]
        );
    }
);

/**
 * TFSC - Elementor Posts filteren via Pods taxonomy relationships
 *
 * Query ID:
 * relationship_posts
 *
 * Doel:
 * Filtert een Elementor Posts/Loop Grid automatisch op basis van de
 * Pods relationshipvelden van de huidige post, CPT of taxonomy-term.
 *
 * Belangrijk:
 * - RAW Pods relationshipdata is leidend.
 * - Verschillende taxonomies = AND.
 * - Meerdere terms binnen dezelfde taxonomy = IN / OR.
 * - Elementor Source blijft leidend.
 * - relationship_vacature_button_url wordt bewust genegeerd.
 * - Werkt ook in Elementor Theme Builder preview voor posts/CPT's.
 */


/**
 * ============================================================
 * CONTEXT + POD
 * ============================================================
 *
 * Bepaalt het Pods-object van de huidige context:
 *
 * - taxonomy archive → Pod van de huidige term;
 * - post / CPT → Pod van de huidige post;
 * - Elementor Theme Builder → gebruikt indien beschikbaar
 *   tfsc_derived_rel_v3_get_context_post_id() om de echte
 *   preview-post te vinden.
 */

function tfsc_relposts_v3_get_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();

    /*
     * Taxonomy term.
     */
    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /*
     * Post / CPT / Elementor preview.
     */
    $post_id = 0;

    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v3_get_context_post_id();

    } elseif (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id =
            (int)
            tfsc_derived_rel_v2_get_context_post_id();
    }

    if (
        ! $post_id &&
        $object instanceof WP_Post &&
        'elementor_library'
        !==
        get_post_type( $object->ID )
    ) {
        $post_id =
            (int) $object->ID;
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * RAW RELATIONSHIP NORMALISEREN
 * ============================================================
 *
 * Pods kan relationshipdata als array of object teruggeven.
 * Deze functie maakt daar steeds dit formaat van:
 *
 * [
 *     [
 *         'taxonomy' => 'functie-inhoud',
 *         'term_id'  => 220,
 *     ],
 * ]
 *
 * De taxonomy wordt dus NIET afgeleid uit de fieldnaam.
 * De daadwerkelijke RAW relationshipdata bepaalt welke taxonomy
 * en term gebruikt worden.
 */

function tfsc_relposts_v3_normalize_relationship(
    $value
) {

    if ( empty( $value ) ) {
        return [];
    }

    /*
     * Eén relationship normaliseren naar een lijst.
     */
    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['taxonomy'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    if ( ! is_array( $value ) ) {
        return [];
    }

    $result = [];

    foreach ( $value as $relation ) {

        if ( is_array( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

        } elseif ( is_object( $relation ) ) {

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

        } else {

            continue;
        }

        /*
         * Alleen echte, bestaande taxonomy-terms accepteren.
         */
        if (
            ! $taxonomy ||
            ! $term_id ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            $result[] = [
                'taxonomy' => $taxonomy,
                'term_id'  => $term_id,
            ];
        }
    }

    return $result;
}


/**
 * ============================================================
 * TAXONOMY HOORT BIJ ELEMENTOR SOURCE?
 * ============================================================
 *
 * Een relationship wordt alleen gebruikt als de betreffende
 * taxonomy gekoppeld is aan het post type dat Elementor als
 * Source gebruikt.
 */

function tfsc_relposts_v3_taxonomy_matches_source(
    $taxonomy,
    $post_types
) {

    $object =
        get_taxonomy(
            $taxonomy
        );

    if ( ! $object ) {
        return false;
    }

    return (bool) array_intersect(
        (array) $post_types,
        (array) $object->object_type
    );
}


/**
 * ============================================================
 * ELEMENTOR QUERY
 * ============================================================
 *
 * Query ID in Elementor:
 *
 * relationship_posts
 */

add_action(
    'elementor/query/relationship_posts',
    function( $query ) {

        $pod =
            tfsc_relposts_v3_get_pod();

        if ( ! $pod ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Elementor Source.
         */
        $post_types =
            array_values(
                array_filter(
                    (array) $query->get( 'post_type' )
                )
            );

        if ( ! $post_types ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        $fields =
            $pod->fields();

        if ( ! is_array( $fields ) || ! $fields ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Relationship terms groeperen per taxonomy.
         */
        $groups = [];

        foreach ( $fields as $field_name => $definition ) {

            if (
                ! is_string( $field_name ) ||
                0 !== strpos(
                    $field_name,
                    'relationship_'
                ) ||
                'relationship_vacature_button_url'
                ===
                $field_name
            ) {
                continue;
            }

            /*
             * RAW Pods relationship uitlezen.
             */
            $relationships =
                tfsc_relposts_v3_normalize_relationship(
                    $pod->field(
                        $field_name
                    )
                );

            foreach (
                $relationships
                as $relationship
            ) {

                $taxonomy =
                    $relationship['taxonomy'];

                /*
                 * Alleen gebruiken als taxonomy bij de
                 * Elementor Source hoort.
                 */
                if (
                    ! tfsc_relposts_v3_taxonomy_matches_source(
                        $taxonomy,
                        $post_types
                    )
                ) {
                    continue;
                }

                $groups[ $taxonomy ][] =
                    (int) $relationship['term_id'];
            }
        }

        /*
         * Dubbele en ongeldige IDs verwijderen.
         */
        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $ids =
                array_values(
                    array_unique(
                        array_filter(
                            array_map(
                                'intval',
                                $ids
                            )
                        )
                    )
                );

            if ( $ids ) {
                $groups[ $taxonomy ] = $ids;
            } else {
                unset( $groups[ $taxonomy ] );
            }
        }

        /*
         * Geen bruikbare relationships:
         * bewust geen posts tonen.
         */
        if ( ! $groups ) {
            $query->set( 'post__in', [ 0 ] );
            return;
        }

        /*
         * Verschillende taxonomies = AND.
         * Meerdere terms binnen taxonomy = IN.
         */
        $relationship_query = [
            'relation' => 'AND',
        ];

        foreach (
            $groups
            as $taxonomy => $ids
        ) {

            $relationship_query[] = [
                'taxonomy'         => $taxonomy,
                'field'            => 'term_id',
                'terms'            => $ids,
                'operator'         => 'IN',
                'include_children' => true,
            ];
        }

        $query->set(
            'tax_query',
            $relationship_query
        );
    },
    20,
    1
);

add_action(
    'rest_api_init',
    function() {
        register_rest_route(
            'tfsc/v1',
            '/one-time-studierichting-archive-titles',
            [
                'methods'             => [ 'GET', 'POST' ],
                'permission_callback' => function() {
                    return current_user_can( 'manage_options' );
                },
                'callback'            => function( WP_REST_Request $request ) {
                    $taxonomy = 'beroep_studierichting';
                    $terms = get_terms(
                        [
                            'taxonomy'   => $taxonomy,
                            'hide_empty' => false,
                            'orderby'    => 'term_id',
                            'order'      => 'ASC',
                        ]
                    );

                    if ( is_wp_error( $terms ) ) {
                        return $terms;
                    }

                    $mode = sanitize_key( (string) $request->get_param( 'mode' ) );
                    $restore_values = (array) $request->get_param( 'values' );
                    $rows = [];

                    foreach ( $terms as $term ) {
                        $before = (string) get_term_meta(
                            $term->term_id,
                            'pods_archive_title',
                            true
                        );
                        $target = 'Studierichting ' . $term->name;

                        if ( 'apply' === $mode ) {
                            update_term_meta(
                                $term->term_id,
                                'pods_archive_title',
                                $target
                            );
                        } elseif ( 'restore' === $mode ) {
                            $restore = isset( $restore_values[ $term->term_id ] )
                                ? (string) $restore_values[ $term->term_id ]
                                : '';
                            if ( '' === $restore ) {
                                delete_term_meta(
                                    $term->term_id,
                                    'pods_archive_title'
                                );
                            } else {
                                update_term_meta(
                                    $term->term_id,
                                    'pods_archive_title',
                                    $restore
                                );
                            }
                        }

                        $rows[] = [
                            'id'     => (int) $term->term_id,
                            'name'   => $term->name,
                            'before' => $before,
                            'target' => $target,
                            'after'  => (string) get_term_meta(
                                $term->term_id,
                                'pods_archive_title',
                                true
                            ),
                        ];
                    }

                    return rest_ensure_response( $rows );
                },
            ]
        );
    }
);

/**
 * TFSC - Volledig dynamische vacature-archieven
 * Version 4.3 - Stable Legacy Logic + S&F Pagination Sync
 *
 * Gebaseerd op de oude werkende combo-architectuur.
 *
 * Regelt:
 * - Virtuele combo archives onder /vacatures/...
 * - Onbeperkt aantal taxonomies/terms
 * - Verschillende taxonomies = AND
 * - Meerdere terms binnen dezelfde taxonomy = OR
 * - kennisgebied = AND
 * - Alleen vac_status=open
 * - Search & Filter Pro v3 frontend sync
 * - Elementor archive condition
 * - Native vacature taxonomy archives
 * - [combo_heading]
 * - [combo_term taxonomy="..."]
 * - Correcte /page/N/ pagination rewrite
 * - Main query gebruikt dezelfde posts_per_page als S&F Query 1
 *
 * Belangrijk:
 * - Geen server-side Search & Filter query manipulation
 * - Geen search_filter_query_id koppeling
 * - Geen search-filter/query/query_args mutatie
 */


/* ============================================================
 * CONFIG
 * ============================================================ */

if ( ! defined( 'TFSC_COMBO_BASE' ) ) {
    define( 'TFSC_COMBO_BASE', 'vacatures' );
}

if ( ! defined( 'TFSC_VACANCY_POST_TYPE' ) ) {
    define( 'TFSC_VACANCY_POST_TYPE', 'vacature' );
}

if ( ! defined( 'TFSC_SEARCH_FILTER_QUERY_ID' ) ) {
    define( 'TFSC_SEARCH_FILTER_QUERY_ID', 1 );
}

if ( ! defined( 'TFSC_STATUS_TAXONOMY' ) ) {
    define( 'TFSC_STATUS_TAXONOMY', 'vac_status' );
}

if ( ! defined( 'TFSC_OPEN_STATUS_SLUG' ) ) {
    define( 'TFSC_OPEN_STATUS_SLUG', 'open' );
}


/* ============================================================
 * HELPERS
 * ============================================================ */

function tfsc_get_combo_taxonomy_match_method( $taxonomy ) {

    return 'kennisgebied' === $taxonomy
        ? 'AND'
        : 'OR';
}


function tfsc_combo_status_clause() {

    return [
        'taxonomy'         => TFSC_STATUS_TAXONOMY,
        'field'            => 'slug',
        'terms'            => [ TFSC_OPEN_STATUS_SLUG ],
        'operator'         => 'IN',
        'include_children' => false,
    ];
}


function tfsc_combo_taxonomy_allowed( $taxonomy ) {

    if (
        ! $taxonomy ||
        TFSC_STATUS_TAXONOMY === $taxonomy ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return false;
    }

    $object = get_taxonomy( $taxonomy );

    return (
        $object &&
        $object->publicly_queryable &&
        in_array(
            TFSC_VACANCY_POST_TYPE,
            (array) $object->object_type,
            true
        )
    );
}


function tfsc_get_allowed_combo_taxonomies() {

    static $allowed = null;

    if ( null !== $allowed ) {
        return $allowed;
    }

    $allowed = [];

    foreach (
        get_object_taxonomies(
            TFSC_VACANCY_POST_TYPE,
            'objects'
        )
        as $taxonomy => $object
    ) {

        if (
            tfsc_combo_taxonomy_allowed(
                $taxonomy
            )
        ) {
            $allowed[] = $taxonomy;
        }
    }

    return $allowed;
}


function tfsc_is_combo_archive() {

    return (bool) get_query_var(
        'tfsc_combo_archive'
    );
}


function tfsc_is_vacancy_seo_landing() {

    if (
        tfsc_is_combo_archive() &&
        false !== tfsc_get_combo_archive()
    ) {
        return true;
    }

    $term = get_queried_object();

    return (
        is_tax() &&
        $term instanceof WP_Term &&
        tfsc_combo_taxonomy_allowed(
            $term->taxonomy
        )
    );
}


/* ============================================================
 * SEARCH & FILTER POSTS PER PAGE
 * ============================================================
 *
 * Search & Filter Query 1 is de bron voor de paginagrootte.
 *
 * Als S&F bijvoorbeeld 10 resultaten per pagina gebruikt,
 * gebruikt de WordPress main query ook 10.
 *
 * Daardoor krijgen:
 *
 * - WordPress
 * - Rank Math
 * - combo pagination
 * - Search & Filter
 *
 * dezelfde page count.
 * ============================================================ */

function tfsc_get_search_filter_posts_per_page() {

    static $resolved = false;
    static $value    = null;

    if ( $resolved ) {
        return $value;
    }

    $resolved = true;


    if (
        ! class_exists(
            '\Search_Filter\Queries\Query'
        )
    ) {
        return null;
    }


    try {

        $sf_query =
            \Search_Filter\Queries\Query::find(
                [
                    'id' =>
                        (int) TFSC_SEARCH_FILTER_QUERY_ID,
                ]
            );

    } catch ( Throwable $e ) {

        return null;
    }


    if (
        is_wp_error( $sf_query ) ||
        ! is_object( $sf_query ) ||
        ! method_exists(
            $sf_query,
            'get_attribute'
        )
    ) {
        return null;
    }


    $posts_per_page =
        $sf_query->get_attribute(
            'postsPerPage'
        );


    if (
        null === $posts_per_page ||
        '' === $posts_per_page
    ) {
        return null;
    }


    $posts_per_page =
        (int) $posts_per_page;


    if ( -1 === $posts_per_page ) {
        return $value = -1;
    }


    if ( $posts_per_page < 1 ) {
        return null;
    }


    return $value =
        $posts_per_page;
}


/* ============================================================
 * QUERY VARS + REWRITES
 * ============================================================ */

add_filter(
    'query_vars',
    function( $vars ) {

        $vars[] = 'tfsc_combo_archive';
        $vars[] = 'tfsc_combo_path';

        return $vars;
    }
);


add_action(
    'init',
    function() {

        $base =
            preg_quote(
                TFSC_COMBO_BASE,
                '/'
            );


        /**
         * PAGINATION
         *
         * Deze regel MOET vóór de algemene combo-regel staan.
         *
         * /vacatures/functienaam/field-service-engineer/page/2/
         *
         * wordt:
         *
         * tfsc_combo_archive = 1
         * tfsc_combo_path    = functienaam/field-service-engineer
         * paged              = 2
         */

        add_rewrite_rule(
            '^'
            . $base
            . '/(.+?)/page/([0-9]+)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]'
            . '&paged=$matches[2]',

            'top'
        );


        /**
         * Normale combo archive.
         */

        add_rewrite_rule(
            '^'
            . $base
            . '/(.+?)/?$',

            'index.php'
            . '?tfsc_combo_archive=1'
            . '&tfsc_combo_path=$matches[1]',

            'top'
        );
    },
    99
);


/* ============================================================
 * TERMPAD OPLOSSEN
 * ============================================================ */

function tfsc_resolve_term_path(
    $taxonomy,
    $segments
) {

    $tax_object =
        get_taxonomy(
            $taxonomy
        );

    if (
        ! $tax_object ||
        ! is_array( $segments ) ||
        ! $segments
    ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                array_map(
                    'sanitize_title',
                    $segments
                )
            )
        );


    if (
        ! $segments ||
        (
            ! $tax_object->hierarchical &&
            1 !== count( $segments )
        )
    ) {
        return false;
    }


    $terms     = [];
    $parent_id = 0;


    foreach (
        $segments
        as $index => $slug
    ) {

        $term =
            get_term_by(
                'slug',
                $slug,
                $taxonomy
            );


        if (
            ! $term ||
            is_wp_error( $term )
        ) {
            return false;
        }


        if (
            $index > 0 &&
            (int) $term->parent !== $parent_id
        ) {
            return false;
        }


        $terms[] =
            $term;

        $parent_id =
            (int) $term->term_id;
    }


    return [
        'path' => $terms,
        'term' => end( $terms ),
    ];
}


/* ============================================================
 * COMBO URL PARSEN
 * ============================================================ */

function tfsc_get_combo_archive() {

    static $resolved = false;
    static $cache    = false;


    if ( $resolved ) {
        return $cache;
    }


    $resolved = true;


    if ( ! tfsc_is_combo_archive() ) {
        return false;
    }


    $raw_path =
        get_query_var(
            'tfsc_combo_path'
        );


    if ( ! $raw_path ) {
        return false;
    }


    $segments =
        array_values(
            array_filter(
                explode(
                    '/',
                    trim(
                        (string) $raw_path,
                        '/'
                    )
                ),
                'strlen'
            )
        );


    if (
        count( $segments ) < 2
    ) {
        return false;
    }


    $allowed =
        tfsc_get_allowed_combo_taxonomies();


    if ( ! $allowed ) {
        return false;
    }


    $items = [];
    $count = count( $segments );
    $i     = 0;


    while ( $i < $count ) {

        $taxonomy =
            sanitize_key(
                $segments[ $i ]
            );


        if (
            ! in_array(
                $taxonomy,
                $allowed,
                true
            )
        ) {
            return false;
        }


        $i++;


        $term_segments = [];


        while ( $i < $count ) {

            $possible_taxonomy =
                sanitize_key(
                    $segments[ $i ]
                );


            if (
                in_array(
                    $possible_taxonomy,
                    $allowed,
                    true
                )
            ) {
                break;
            }


            $term_segments[] =
                $segments[ $i ];

            $i++;
        }


        if ( ! $term_segments ) {
            return false;
        }


        $resolved_path =
            tfsc_resolve_term_path(
                $taxonomy,
                $term_segments
            );


        if ( ! $resolved_path ) {
            return false;
        }


        $items[] = [
            'taxonomy' =>
                $taxonomy,

            'term' =>
                $resolved_path['term'],

            'path' =>
                $resolved_path['path'],
        ];
    }


    return $cache =
        $items
            ? $items
            : false;
}


/* ============================================================
 * COMBO TERMS GROEPEREN
 * ============================================================ */

function tfsc_group_combo_terms(
    $property = 'term_id'
) {

    $combo =
        tfsc_get_combo_archive();


    if ( ! is_array( $combo ) ) {
        return [];
    }


    $grouped = [];


    foreach ( $combo as $item ) {

        if (
            empty( $item['taxonomy'] ) ||
            empty( $item['term'] ) ||
            ! $item['term'] instanceof WP_Term
        ) {
            continue;
        }


        $taxonomy =
            $item['taxonomy'];


        if ( 'name' === $property ) {

            $value =
                trim(
                    $item['term']->name
                );

        } elseif ( 'slug' === $property ) {

            $value =
                $item['term']->slug;

        } else {

            $value =
                (int) $item['term']->term_id;
        }


        if (
            '' === $value ||
            0 === $value
        ) {
            continue;
        }


        if (
            ! isset(
                $grouped[ $taxonomy ]
            )
        ) {
            $grouped[ $taxonomy ] = [];
        }


        if (
            ! in_array(
                $value,
                $grouped[ $taxonomy ],
                true
            )
        ) {
            $grouped[ $taxonomy ][] =
                $value;
        }
    }


    return $grouped;
}


/* ============================================================
 * TAX QUERY
 * ============================================================ */

function tfsc_build_combo_tax_query() {

    $grouped =
        tfsc_group_combo_terms(
            'term_id'
        );


    if ( ! $grouped ) {
        return false;
    }


    $tax_query = [
        'relation' => 'AND',

        tfsc_combo_status_clause(),
    ];


    foreach (
        $grouped
        as $taxonomy => $term_ids
    ) {

        if ( ! $term_ids ) {
            continue;
        }


        $object =
            get_taxonomy(
                $taxonomy
            );


        $method =
            tfsc_get_combo_taxonomy_match_method(
                $taxonomy
            );


        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            /**
             * Bijvoorbeeld:
             *
             * functienaam:
             * FSE + Service Engineer + Servicemonteur
             *
             * operator IN
             * = OR
             *
             * kennisgebied:
             * Elektrotechniek + Mechanisch
             *
             * operator AND
             */

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                (
                    'AND' !== $method &&
                    $object &&
                    $object->hierarchical
                ),
        ];
    }


    return $tax_query;
}


/* ============================================================
 * MAIN QUERY
 * ============================================================ */

add_action(
    'pre_get_posts',
    function( $query ) {

        if (
            is_admin() ||
            ! $query->is_main_query()
        ) {
            return;
        }


        /* ----------------------------------------------------
         * VIRTUEEL COMBO ARCHIVE
         * ---------------------------------------------------- */

        if ( tfsc_is_combo_archive() ) {

            $tax_query =
                tfsc_build_combo_tax_query();


            if ( ! $tax_query ) {
                return;
            }


            $query->set(
                'post_type',
                TFSC_VACANCY_POST_TYPE
            );


            $query->set(
                'post_status',
                'publish'
            );


            $query->set(
                'tax_query',
                $tax_query
            );


            /**
             * ================================================
             * PAGINAGROOTTE UIT SEARCH & FILTER
             * ================================================
             *
             * Dit was het ontbrekende stuk.
             *
             * Voorheen:
             *
             * WordPress main query = 20
             * Search & Filter       = 10
             *
             * Daardoor:
             *
             * found_posts   = 20
             * max_num_pages = 1
             *
             * terwijl S&F twee pagina's had.
             *
             * Nu gebruikt de main query dezelfde instelling
             * als Search & Filter Query 1.
             */

            $posts_per_page =
                tfsc_get_search_filter_posts_per_page();


            if (
                null !== $posts_per_page
            ) {

                $query->set(
                    'posts_per_page',
                    $posts_per_page
                );
            }


            /**
             * WordPress moet found_posts en max_num_pages
             * daadwerkelijk berekenen.
             */

            $query->set(
                'no_found_rows',
                false
            );


            /**
             * Huidige combo-pagina.
             */

            $paged =
                max(
                    1,
                    (int) get_query_var(
                        'paged'
                    )
                );


            $query->set(
                'paged',
                $paged
            );


            return;
        }


        /* ----------------------------------------------------
         * NATIVE VACATURE TAXONOMY ARCHIVE
         * ---------------------------------------------------- */

        if ( ! $query->is_tax() ) {
            return;
        }


        $term =
            $query->get_queried_object();


        if (
            ! $term instanceof WP_Term ||
            ! tfsc_combo_taxonomy_allowed(
                $term->taxonomy
            )
        ) {
            return;
        }


        $tax_query =
            $query->get(
                'tax_query'
            );


        if ( ! is_array( $tax_query ) ) {
            $tax_query = [];
        }


        $tax_query[] =
            tfsc_combo_status_clause();


        $tax_query['relation'] =
            'AND';


        $query->set(
            'post_type',
            TFSC_VACANCY_POST_TYPE
        );


        $query->set(
            'post_status',
            'publish'
        );


        $query->set(
            'tax_query',
            $tax_query
        );
    },
    1
);


