/**
 * ============================================================
 * RANK MATH CUSTOM SITEMAP PROVIDER
 * ============================================================
 */

add_filter(
    'rank_math/sitemap/providers',

    function( $providers ) {

        if (
            ! interface_exists(
                '\RankMath\Sitemap\Providers\Provider'
            )
        ) {
            return $providers;
        }


        if (
            ! class_exists(
                'TFSC_Combo_Vacancy_Sitemap_Provider',
                false
            )
        ) {

            class TFSC_Combo_Vacancy_Sitemap_Provider
                implements
                \RankMath\Sitemap\Providers\Provider {


                public function handles_type(
                    $type
                ) {

                    return (
                        'combo-vacatures'
                        === $type
                    );
                }


                public function get_index_links(
                    $max_entries
                ) {

                    $links =
                        tfsc_combo_sitemap_generate_links();


                    $total =
                        count(
                            $links
                        );


                    if ( 0 === $total ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int) $max_entries
                        );


                    $pages =
                        max(
                            1,
                            (int) ceil(
                                $total
                                /
                                $max_entries
                            )
                        );


                    $index = [];


                    for (
                        $page = 1;
                        $page <= $pages;
                        $page++
                    ) {

                        $suffix =
                            $pages > 1
                                ? $page
                                : '';


                        $offset =
                            (
                                $page - 1
                            )
                            *
                            $max_entries;


                        $page_links =
                            array_slice(
                                $links,
                                $offset,
                                $max_entries
                            );


                        $page_lastmod = '';


                        foreach (
                            $page_links
                            as $page_link
                        ) {

                            if (
                                empty(
                                    $page_link[
                                        'lastmod'
                                    ]
                                )
                            ) {
                                continue;
                            }


                            $page_lastmod =
                                tfsc_combo_sitemap_newest_lastmod(
                                    $page_lastmod,
                                    $page_link[
                                        'lastmod'
                                    ]
                                );
                        }


                        $index[] = [
                            'loc' =>
                                \RankMath\Sitemap\Router::get_base_url(
                                    'combo-vacatures-sitemap'
                                    .
                                    $suffix
                                    .
                                    '.xml'
                                ),

                            'lastmod' =>
                                $page_lastmod,
                        ];
                    }


                    return $index;
                }


                public function get_sitemap_links(
                    $type,
                    $max_entries,
                    $current_page
                ) {

                    if (
                        'combo-vacatures'
                        !== $type
                    ) {
                        return [];
                    }


                    $links =
                        tfsc_combo_sitemap_generate_links();


                    if ( ! $links ) {
                        return [];
                    }


                    $max_entries =
                        max(
                            1,
                            (int) $max_entries
                        );


                    $page =
                        max(
                            1,
                            (int) $current_page
                        );


                    $offset =
                        (
                            $page - 1
                        )
                        *
                        $max_entries;


                    return array_slice(
                        $links,
                        $offset,
                        $max_entries
                    );
                }
            }
        }


        $providers[
            'combo-vacatures'
        ] =
            new TFSC_Combo_Vacancy_Sitemap_Provider();


        return $providers;
    }
);

