                            return new WP_Error('tfsc_plugin_missing', 'De actieve pluginbron is niet leesbaar.', ['status' => 404]);
                        }

                        $columns = $wpdb->get_col("SHOW COLUMNS FROM {$table}", 0);

                        return rest_ensure_response(
                            [
                                'target'         => $target,
                                'sha256'         => hash_file('sha256', $target),
                                'bytes'          => filesize($target),
                                'row_count'      => (int) $wpdb->get_var("SELECT COUNT(*) FROM {$table}"),
                                'columns'        => array_values(array_map('strval', (array) $columns)),
                                'schema_version' => (string) get_option('tfsc_crawler_log_version', ''),
                            ]
                        );
                    },
                ],
                [
                    'methods'             => 'POST',
                    'permission_callback' => $permission,
                    'callback'            => static function (WP_REST_Request $request) {
                        $target = WP_PLUGIN_DIR . '/tfsc-ai-crawler-log-main/tfsc-ai-crawler-log.php';
                        $body   = (array) $request->get_json_params();

                        if (!is_file($target) || !is_writable($target)) {
                            return new WP_Error('tfsc_plugin_not_writable', 'De actieve pluginbron is niet schrijfbaar.', ['status' => 500]);
                        }

                        $current_hash = hash_file('sha256', $target);
                        $expected_old = isset($body['expected_current_sha256']) ? strtolower((string) $body['expected_current_sha256']) : '';
                        if (!hash_equals($current_hash, $expected_old)) {
                            return new WP_Error(
                                'tfsc_source_changed',
                                'De live pluginbron is sinds de controle gewijzigd; uitrol afgebroken.',
                                ['status' => 409, 'current_sha256' => $current_hash]
                            );
                        }

                        $new_source = isset($body['content_b64']) ? base64_decode((string) $body['content_b64'], true) : false;
                        if (!is_string($new_source) || $new_source === '') {
                            return new WP_Error('tfsc_invalid_payload', 'De nieuwe pluginbron ontbreekt of is ongeldig.', ['status' => 400]);
                        }

                        $new_hash    = hash('sha256', $new_source);
                        $expected_new = isset($body['expected_new_sha256']) ? strtolower((string) $body['expected_new_sha256']) : '';
                        if (!hash_equals($new_hash, $expected_new)) {
                            return new WP_Error('tfsc_hash_mismatch', 'De hash van de nieuwe pluginbron klopt niet.', ['status' => 400]);
                        }

                        if (strpos($new_source, 'Version: 1.2.1') === false || strpos($new_source, "private const VERSION = '1.2.1';") === false) {
                            return new WP_Error('tfsc_wrong_version', 'Het pakket is niet de verwachte pluginversie 1.2.1.', ['status' => 400]);
                        }

                        $temp   = $target . '.codex-new';
                        $backup = trailingslashit(sys_get_temp_dir()) . 'tfsc-ai-crawler-log.codex-backup';

                        if (!copy($target, $backup)) {
                            return new WP_Error('tfsc_backup_failed', 'De live plugin kon niet worden geback-upt.', ['status' => 500]);
                        }

                        $written = file_put_contents($temp, $new_source, LOCK_EX);
                        if ($written !== strlen($new_source)) {
                            @unlink($temp);
                            @unlink($backup);
                            return new WP_Error('tfsc_write_failed', 'De nieuwe pluginbron kon niet volledig worden geschreven.', ['status' => 500]);
                        }

                        @chmod($temp, fileperms($target) & 0777);
                        if (!rename($temp, $target)) {
                            @unlink($temp);
                            @unlink($backup);
                            return new WP_Error('tfsc_replace_failed', 'De pluginbron kon niet atomair worden vervangen.', ['status' => 500]);
                        }

                        clearstatcache(true, $target);

                        return rest_ensure_response(
                            [
                                'updated' => true,
                                'sha256'  => hash_file('sha256', $target),
                                'bytes'   => filesize($target),
                                'backup'  => $backup,
                            ]
                        );
                    },
                ],
                [
                    'methods'             => 'DELETE',
                    'permission_callback' => $permission,
                    'callback'            => static function () {
                        $backup = trailingslashit(sys_get_temp_dir()) . 'tfsc-ai-crawler-log.codex-backup';
                        return rest_ensure_response(['backup_removed' => !is_file($backup) || unlink($backup)]);
                    },
                ],
            ]
        );
    }
);

