add_action('rest_api_init', function () {
    $permission = function () {
        return current_user_can('manage_options');
    };

    $plugin_root = function () {
        $root = realpath(WP_PLUGIN_DIR . '/advanced-cache-warmer');
        return $root && is_dir($root) ? $root : false;
    };

    register_rest_route('tfsc-plugin-export/v1', '/manifest', [
        'methods' => 'GET',
        'permission_callback' => $permission,
        'callback' => function () use ($plugin_root) {
            $root = $plugin_root();
            if (!$root) {
                return new WP_Error('plugin_not_found', 'Plugin directory not found.', ['status' => 404]);
            }

            $files = [];
            $iterator = new RecursiveIteratorIterator(
                new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS)
            );

            foreach ($iterator as $file) {
                if (!$file->isFile()) {
                    continue;
                }

                $path = $file->getRealPath();
                $relative = ltrim(substr($path, strlen($root)), DIRECTORY_SEPARATOR);
                $files[] = [
                    'path' => str_replace(DIRECTORY_SEPARATOR, '/', $relative),
                    'size' => $file->getSize(),
                    'sha256' => hash_file('sha256', $path),
                ];
            }

            usort($files, function ($a, $b) {
                return strcmp($a['path'], $b['path']);
            });

            return rest_ensure_response([
                'plugin' => 'advanced-cache-warmer',
                'file_count' => count($files),
                'total_bytes' => array_sum(array_column($files, 'size')),
                'files' => $files,
            ]);
        },
    ]);

    register_rest_route('tfsc-plugin-export/v1', '/file', [
        'methods' => 'GET',
        'permission_callback' => $permission,
        'args' => [
            'path' => [
                'required' => true,
                'type' => 'string',
            ],
        ],
        'callback' => function (WP_REST_Request $request) use ($plugin_root) {
            $root = $plugin_root();
            if (!$root) {
                return new WP_Error('plugin_not_found', 'Plugin directory not found.', ['status' => 404]);
            }

            $relative = ltrim(str_replace('\\', '/', (string) $request['path']), '/');
            $path = realpath($root . DIRECTORY_SEPARATOR . $relative);
            $root_prefix = rtrim($root, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR;

            if (!$path || !is_file($path) || strpos($path, $root_prefix) !== 0) {
                return new WP_Error('invalid_path', 'Invalid plugin file path.', ['status' => 400]);
            }

            $size = filesize($path);
            if ($size === false || $size > 5 * 1024 * 1024) {
                return new WP_Error('file_too_large', 'File exceeds the export limit.', ['status' => 413]);
            }

            $contents = file_get_contents($path);
            if ($contents === false) {
                return new WP_Error('read_failed', 'Could not read plugin file.', ['status' => 500]);
            }

            return rest_ensure_response([
                'path' => $relative,
                'size' => strlen($contents),
                'sha256' => hash('sha256', $contents),
                'base64' => base64_encode($contents),
            ]);
        },
    ]);
});

