add_action('rest_api_init', function () {
    register_rest_route('tfsc-cache-pop-audit/v1', '/probe', [
        'methods' => 'POST',
        'permission_callback' => function () {
            return current_user_can('manage_options');
        },
        'callback' => function () {
            $url = home_url('/');
            $started = microtime(true);
            $response = wp_remote_get($url, [
                'timeout' => 20,
                'redirection' => 3,
                'headers' => [
                    'User-Agent' => 'TFSC-Cache-Warmer-Audit/1.0',
                    'Cache-Control' => 'no-cache',
                ],
            ]);

            if (is_wp_error($response)) {
                return new WP_Error('probe_failed', $response->get_error_message(), ['status' => 502]);
            }

            $header_names = [
                'x-qc-pop',
                'x-qc-cache',
                'x-litespeed-cache',
                'cf-cache-status',
                'server',
            ];
            $headers = [];
            foreach ($header_names as $name) {
                $value = wp_remote_retrieve_header($response, $name);
                $headers[$name] = $value !== '' ? $value : null;
            }

            return rest_ensure_response([
                'url' => $url,
                'status' => wp_remote_retrieve_response_code($response),
                'elapsed_ms' => (int) round((microtime(true) - $started) * 1000),
                'headers' => $headers,
            ]);
        },
    ]);
});

