add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'tfsc-deploy/v1',
			'/crawler-log-menu-122',
			array(
				'methods'             => WP_REST_Server::CREATABLE,
				'permission_callback' => function () {
					return current_user_can( 'update_plugins' ) && current_user_can( 'activate_plugins' );
				},
				'callback'            => function () {
					$file = WP_PLUGIN_DIR . '/tfsc-ai-crawler-log-main/tfsc-ai-crawler-log.php';
					if ( ! is_file( $file ) || ! is_readable( $file ) || ! is_writable( $file ) ) {
						return new WP_Error( 'plugin_file_unavailable', 'Het vaste pluginbestand is niet leesbaar en schrijfbaar.', array( 'status' => 500 ) );
					}

					require_once ABSPATH . 'wp-admin/includes/plugin.php';
					$data = get_plugin_data( $file, false, false );
					if ( 'TFSC Crawler Log' !== $data['Name'] || '1.2.1' !== $data['Version'] ) {
						return new WP_Error( 'unexpected_plugin_version', 'Alleen TFSC Crawler Log 1.2.1 kan met deze updater worden aangepast.', array( 'status' => 409 ) );
					}

					$source = file_get_contents( $file );
					if ( false === $source ) {
						return new WP_Error( 'read_failed', 'Het pluginbestand kon niet worden gelezen.', array( 'status' => 500 ) );
					}

					$replacements = array(
						' * Version: 1.2.1' => ' * Version: 1.2.2',
						"private const VERSION = '1.2.1';" => "private const VERSION = '1.2.2';",
						"add_management_page(\n            'Crawler Log',\n            'Crawler Log'," => "add_management_page(\n            'TFSC Crawler Log',\n            'TFSC Crawler Log',",
						'<h1>Crawler Log</h1>' => '<h1>TFSC Crawler Log</h1>',
					);

					foreach ( $replacements as $before => $after ) {
						if ( 1 !== substr_count( $source, $before ) ) {
							return new WP_Error( 'unexpected_source', 'De verwachte broncode is niet exact één keer gevonden.', array( 'status' => 409 ) );
						}
						$source = str_replace( $before, $after, $source );
					}

					$temp = $file . '.tfsc-update';
					if ( strlen( $source ) !== file_put_contents( $temp, $source, LOCK_EX ) || ! rename( $temp, $file ) ) {
						@unlink( $temp );
						return new WP_Error( 'write_failed', 'De pluginupdate kon niet atomair worden opgeslagen.', array( 'status' => 500 ) );
					}

					clearstatcache( true, $file );
					$data = get_plugin_data( $file, false, false );
					return rest_ensure_response(
						array(
							'updated'  => true,
							'plugin'   => 'tfsc-ai-crawler-log-main/tfsc-ai-crawler-log.php',
							'version'  => $data['Version'],
							'checksum' => hash_file( 'sha256', $file ),
						)
					);
				},
			)
		);
	}
);

add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'tfsc-deploy/v1',
			'/server-location-test-probe-011',
			array(
				'methods'             => WP_REST_Server::CREATABLE,
				'permission_callback' => function () {
					return current_user_can( 'install_plugins' ) && current_user_can( 'activate_plugins' );
				},
				'callback'            => function ( WP_REST_Request $request ) {
					$package  = $request->get_body();
					$expected = 'e0b1b9686a0b32d24ca1c1b399675942af120c111ce81f4d0830b6f917782427';

					if ( '' === $package || strlen( $package ) > 2 * MB_IN_BYTES ) {
						return new WP_Error( 'invalid_package', 'Leeg of te groot installatiepakket.', array( 'status' => 400 ) );
					}

					if ( ! hash_equals( $expected, hash( 'sha256', $package ) ) ) {
						return new WP_Error( 'checksum_mismatch', 'De pakket-checksum klopt niet.', array( 'status' => 400 ) );
					}

					$temp = wp_tempnam( 'tfsc-server-location-test-probe-0.1.1.zip' );
					if ( ! $temp || strlen( $package ) !== file_put_contents( $temp, $package, LOCK_EX ) ) {
						return new WP_Error( 'temp_write_failed', 'Het installatiepakket kon niet tijdelijk worden opgeslagen.', array( 'status' => 500 ) );
					}

					require_once ABSPATH . 'wp-admin/includes/file.php';
					require_once ABSPATH . 'wp-admin/includes/class-wp-upgrader.php';
					require_once ABSPATH . 'wp-admin/includes/plugin.php';

					$skin     = new Automatic_Upgrader_Skin();
					$upgrader = new Plugin_Upgrader( $skin );
					$result   = $upgrader->install( $temp, array( 'overwrite_package' => true ) );
					unlink( $temp );

					if ( is_wp_error( $result ) ) {
						return $result;
					}

					if ( true !== $result ) {
						return new WP_Error( 'install_failed', $skin->get_upgrade_messages(), array( 'status' => 500 ) );
					}

					$plugin = 'server-location-test-probe/server-location-test-probe.php';
					if ( ! file_exists( WP_PLUGIN_DIR . '/' . $plugin ) ) {
						return new WP_Error( 'plugin_missing', 'De pluginmap ontbreekt na installatie.', array( 'status' => 500 ) );
					}

					$data = get_plugin_data( WP_PLUGIN_DIR . '/' . $plugin, false, false );
					return rest_ensure_response(
						array(
							'installed' => true,
							'plugin'    => $plugin,
							'version'   => $data['Version'],
							'checksum'  => hash_file( 'sha256', WP_PLUGIN_DIR . '/' . $plugin ),
						)
					);
				},
			)
		);
	}
);

