add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'tfsc-audit/v1',
			'/crawler-log-summary',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'permission_callback' => function () {
					return current_user_can( 'manage_options' );
				},
				'callback'            => function () {
					global $wpdb;
					$table = $wpdb->prefix . 'tfsc_ai_crawler_log';
					if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $table ) ) !== $table ) {
						return new WP_Error( 'crawler_log_missing', 'Crawler-logtabel ontbreekt.', array( 'status' => 404 ) );
					}

					$status_totals = $wpdb->get_results(
						"SELECT status_code, COUNT(*) AS total
						 FROM {$table}
						 GROUP BY status_code
						 ORDER BY status_code ASC",
						ARRAY_A
					);
					$bot_totals = $wpdb->get_results(
						"SELECT bot_name, verification_status, status_code, COUNT(*) AS total, MAX(created_at) AS last_seen
						 FROM {$table}
						 GROUP BY bot_name, verification_status, status_code
						 ORDER BY last_seen DESC",
						ARRAY_A
					);
					$sitemap_requests = $wpdb->get_results(
						"SELECT request_uri, bot_name, verification_status, status_code, COUNT(*) AS total, MAX(created_at) AS last_seen
						 FROM {$table}
						 WHERE request_uri LIKE '%sitemap%' OR request_uri LIKE '%.xml%'
						 GROUP BY request_uri, bot_name, verification_status, status_code
						 ORDER BY last_seen DESC
						 LIMIT 250",
						ARRAY_A
					);
					$recent_errors = $wpdb->get_results(
						"SELECT created_at, bot_name, verification_status, request_uri, status_code
						 FROM {$table}
						 WHERE status_code >= 400
						 ORDER BY id DESC
						 LIMIT 100",
						ARRAY_A
					);

					return rest_ensure_response(
						array(
							'total'            => (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$table}" ),
							'status_totals'    => $status_totals,
							'bot_totals'       => $bot_totals,
							'sitemap_requests' => $sitemap_requests,
							'recent_errors'    => $recent_errors,
						)
					);
				},
			)
		);
	}
);

