add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'tfsc-audit/v1',
			'/pods-sitemap',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'permission_callback' => function () {
					return current_user_can( 'manage_options' );
				},
				'callback'            => function () {
					$taxonomies = array();
					foreach ( get_taxonomies( array(), 'objects' ) as $name => $taxonomy ) {
						$haystack = strtolower( $name . ' ' . ( $taxonomy->label ?? '' ) );
						if ( false === strpos( $haystack, 'werkgebied' ) ) {
							continue;
						}

						$all_terms = wp_count_terms(
							array(
								'taxonomy'   => $name,
								'hide_empty' => false,
							)
						);
						$used_terms = wp_count_terms(
							array(
								'taxonomy'   => $name,
								'hide_empty' => true,
							)
						);

						$taxonomies[ $name ] = array(
							'label'              => sanitize_text_field( $taxonomy->label ?? '' ),
							'object_type'        => array_values( array_map( 'sanitize_key', (array) ( $taxonomy->object_type ?? array() ) ) ),
							'public'             => (bool) ( $taxonomy->public ?? false ),
							'publicly_queryable' => (bool) ( $taxonomy->publicly_queryable ?? false ),
							'show_ui'            => (bool) ( $taxonomy->show_ui ?? false ),
							'show_in_rest'       => (bool) ( $taxonomy->show_in_rest ?? false ),
							'rewrite'            => is_array( $taxonomy->rewrite ?? null ) ? array_map( 'sanitize_text_field', $taxonomy->rewrite ) : (bool) ( $taxonomy->rewrite ?? false ),
							'terms_total'        => is_wp_error( $all_terms ) ? null : (int) $all_terms,
							'terms_nonempty'     => is_wp_error( $used_terms ) ? null : (int) $used_terms,
						);
					}

					$rank_math = array();
					foreach ( (array) get_option( 'rank_math_options_sitemap', array() ) as $key => $value ) {
						if ( false !== stripos( (string) $key, 'werkgebied' ) ) {
							$rank_math[ sanitize_key( $key ) ] = is_scalar( $value ) ? sanitize_text_field( (string) $value ) : wp_json_encode( $value );
						}
					}

					$pods_records = array();
					$records = get_posts(
						array(
							'post_type'      => array( '_pods_pod', '_pods_field' ),
							'post_status'    => 'any',
							'posts_per_page' => 500,
							'orderby'        => 'ID',
							'order'          => 'ASC',
						)
					);
					foreach ( $records as $record ) {
						$haystack = strtolower( $record->post_name . ' ' . $record->post_title );
						if ( false === strpos( $haystack, 'werkgebied' ) ) {
							continue;
						}

						$relevant_meta = array();
						foreach ( get_post_meta( $record->ID ) as $meta_key => $meta_values ) {
							if ( ! preg_match( '/sitemap|public|query|rewrite|rest|object|type/i', (string) $meta_key ) ) {
								continue;
							}
							$relevant_meta[ sanitize_key( $meta_key ) ] = array_map( 'sanitize_text_field', array_slice( (array) $meta_values, 0, 5 ) );
						}
						$pods_records[] = array(
							'id'        => (int) $record->ID,
							'post_type' => sanitize_key( $record->post_type ),
							'name'      => sanitize_key( $record->post_name ),
							'title'     => sanitize_text_field( $record->post_title ),
							'parent'    => (int) $record->post_parent,
							'meta'      => $relevant_meta,
						);
					}

					return rest_ensure_response(
						array(
							'taxonomies'       => $taxonomies,
							'rank_math_options' => $rank_math,
							'pods_records'      => $pods_records,
						)
					);
				},
			)
		);
	}
);

add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'tfsc-audit/v1',
			'/beroep-taxonomies',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'permission_callback' => function () {
					return current_user_can( 'manage_options' );
				},
				'callback'            => function () {
					$result = array();
					foreach ( get_taxonomies( array(), 'objects' ) as $name => $taxonomy ) {
						if ( 0 !== strpos( $name, 'beroep_' ) ) {
							continue;
						}

						$terms = get_terms(
							array(
								'taxonomy'   => $name,
								'hide_empty' => false,
								'orderby'    => 'name',
								'order'      => 'ASC',
							)
						);
						$term_rows = array();
						if ( ! is_wp_error( $terms ) ) {
							foreach ( $terms as $term ) {
								$objects = get_objects_in_term( $term->term_id, $name );
								$post_statuses = array();
								$post_types = array();
								foreach ( array_slice( is_wp_error( $objects ) ? array() : $objects, 0, 200 ) as $object_id ) {
									$status = get_post_status( $object_id );
									$type   = get_post_type( $object_id );
									$post_statuses[ $status ?: 'missing' ] = ( $post_statuses[ $status ?: 'missing' ] ?? 0 ) + 1;
									$post_types[ $type ?: 'missing' ] = ( $post_types[ $type ?: 'missing' ] ?? 0 ) + 1;
								}
								$term_rows[] = array(
									'id'            => (int) $term->term_id,
									'name'          => sanitize_text_field( $term->name ),
									'slug'          => sanitize_title( $term->slug ),
									'count'         => (int) $term->count,
									'objects_total' => is_wp_error( $objects ) ? null : count( $objects ),
									'post_statuses' => $post_statuses,
									'post_types'    => $post_types,
								);
							}
						}

						$result[ $name ] = array(
							'label'       => sanitize_text_field( $taxonomy->label ?? '' ),
							'object_type' => array_values( array_map( 'sanitize_key', (array) ( $taxonomy->object_type ?? array() ) ) ),
							'public'      => (bool) ( $taxonomy->public ?? false ),
							'terms'       => $term_rows,
						);
					}

					return rest_ensure_response( $result );
				},
			)
		);
	}
);

add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'tfsc-audit/v1',
			'/sitemap-registration',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'permission_callback' => function () {
					return current_user_can( 'manage_options' );
				},
				'callback'            => function () {
					global $wp_filter;

					$options = array();
					foreach ( (array) get_option( 'rank_math_options_sitemap', array() ) as $key => $value ) {
						if ( false === stripos( (string) $key, 'beroep' ) ) {
							continue;
						}
						$options[ sanitize_key( $key ) ] = is_scalar( $value ) ? sanitize_text_field( (string) $value ) : wp_json_encode( $value );
					}

					$hooks = array();
					foreach ( (array) $wp_filter as $hook_name => $hook ) {
						if ( false === stripos( (string) $hook_name, 'sitemap' ) || ! is_object( $hook ) || empty( $hook->callbacks ) ) {
							continue;
						}

						foreach ( $hook->callbacks as $priority => $callbacks ) {
							foreach ( $callbacks as $callback ) {
								$function = $callback['function'] ?? null;
								$label    = 'unknown';
								$file     = '';
								$line     = 0;
								try {
									if ( $function instanceof Closure ) {
										$reflection = new ReflectionFunction( $function );
										$label      = 'Closure';
									} elseif ( is_string( $function ) ) {
										$reflection = new ReflectionFunction( $function );
										$label      = $function;
									} elseif ( is_array( $function ) && 2 === count( $function ) ) {
										$class      = is_object( $function[0] ) ? get_class( $function[0] ) : (string) $function[0];
										$label      = $class . '::' . (string) $function[1];
										$reflection = new ReflectionMethod( $function[0], $function[1] );
									} else {
										$reflection = null;
									}
									if ( $reflection ) {
										$file = (string) $reflection->getFileName();
										$line = (int) $reflection->getStartLine();
									}
								} catch ( Throwable $error ) {
									$label = 'reflection-error';
								}

								$hooks[] = array(
									'hook'     => sanitize_text_field( (string) $hook_name ),
									'priority' => (int) $priority,
									'callback' => sanitize_text_field( $label ),
									'file'     => sanitize_text_field( $file ),
									'line'     => $line,
								);
							}
						}
					}

					$taxonomies = array();
					foreach ( array( 'beroep_opleidingsniveau', 'beroep_studierichting', 'beroep_werkgebied' ) as $taxonomy_name ) {
						$taxonomy = get_taxonomy( $taxonomy_name );
						$taxonomies[ $taxonomy_name ] = $taxonomy ? array(
							'public'             => (bool) $taxonomy->public,
							'publicly_queryable' => (bool) $taxonomy->publicly_queryable,
							'show_ui'            => (bool) $taxonomy->show_ui,
							'show_in_rest'       => (bool) $taxonomy->show_in_rest,
							'object_type'        => array_values( (array) $taxonomy->object_type ),
