add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'tfsc-audit/v1',
			'/sitemap-registration',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'permission_callback' => function () {
					return current_user_can( 'manage_options' );
				},
				'callback'            => function () {
					global $wp_filter;

					$options = array();
					foreach ( (array) get_option( 'rank_math_options_sitemap', array() ) as $key => $value ) {
						if ( false === stripos( (string) $key, 'beroep' ) ) {
							continue;
						}
						$options[ sanitize_key( $key ) ] = is_scalar( $value ) ? sanitize_text_field( (string) $value ) : wp_json_encode( $value );
					}
					$title_options = array();
					foreach ( (array) get_option( 'rank_math_options_titles', array() ) as $key => $value ) {
						if ( false === stripos( (string) $key, 'beroep' ) ) {
							continue;
						}
						$title_options[ sanitize_key( $key ) ] = is_scalar( $value ) ? sanitize_text_field( (string) $value ) : wp_json_encode( $value );
					}

					$hooks = array();
					foreach ( (array) $wp_filter as $hook_name => $hook ) {
						if ( false === stripos( (string) $hook_name, 'sitemap' ) || ! is_object( $hook ) || empty( $hook->callbacks ) ) {
							continue;
						}

						foreach ( $hook->callbacks as $priority => $callbacks ) {
							foreach ( $callbacks as $callback ) {
								$function = $callback['function'] ?? null;
								$label    = 'unknown';
								$file     = '';
								$line     = 0;
								try {
									if ( $function instanceof Closure ) {
										$reflection = new ReflectionFunction( $function );
										$label      = 'Closure';
									} elseif ( is_string( $function ) ) {
										$reflection = new ReflectionFunction( $function );
										$label      = $function;
									} elseif ( is_array( $function ) && 2 === count( $function ) ) {
										$class      = is_object( $function[0] ) ? get_class( $function[0] ) : (string) $function[0];
										$label      = $class . '::' . (string) $function[1];
										$reflection = new ReflectionMethod( $function[0], $function[1] );
									} else {
										$reflection = null;
									}
									if ( $reflection ) {
										$file = (string) $reflection->getFileName();
										$line = (int) $reflection->getStartLine();
									}
								} catch ( Throwable $error ) {
									$label = 'reflection-error';
								}

								$hooks[] = array(
									'hook'     => sanitize_text_field( (string) $hook_name ),
									'priority' => (int) $priority,
									'callback' => sanitize_text_field( $label ),
									'file'     => sanitize_text_field( $file ),
									'line'     => $line,
