							}
						}
					}

					$taxonomies = array();
					foreach ( array( 'beroep_bedrijfssector', 'beroep_functie-inhoud', 'beroep_functienaam', 'beroep_kennisgebied', 'beroep_opleidingsniveau', 'beroep_studierichting', 'beroep_werkgebied' ) as $taxonomy_name ) {
						$taxonomy = get_taxonomy( $taxonomy_name );
						$term_robots = array();
						foreach ( (array) get_terms( array( 'taxonomy' => $taxonomy_name, 'hide_empty' => true ) ) as $term ) {
							if ( $term instanceof WP_Term ) {
								$term_robots[ $term->slug ] = get_term_meta( $term->term_id, 'rank_math_robots', true );
