						}
						$taxonomies[ $taxonomy_name ] = $taxonomy ? array(
							'public'             => (bool) $taxonomy->public,
							'publicly_queryable' => (bool) $taxonomy->publicly_queryable,
							'show_ui'            => (bool) $taxonomy->show_ui,
							'show_in_rest'       => (bool) $taxonomy->show_in_rest,
							'show_in_nav_menus'  => (bool) $taxonomy->show_in_nav_menus,
							'query_var'          => $taxonomy->query_var,
							'rewrite'            => $taxonomy->rewrite,
							'object_type'        => array_values( (array) $taxonomy->object_type ),
							'count_all'          => (int) wp_count_terms( array( 'taxonomy' => $taxonomy_name, 'hide_empty' => false ) ),
							'count_nonempty'     => (int) wp_count_terms( array( 'taxonomy' => $taxonomy_name, 'hide_empty' => true ) ),
							'term_robots'        => $term_robots,
							'rank_math_helper_sitemap' => class_exists( '\\RankMath\\Helper' ) ? \RankMath\Helper::get_settings( 'sitemap.tax_' . $taxonomy_name . '_sitemap' ) : null,
							'rank_math_helper_indexable' => class_exists( '\\RankMath\\Helper' ) ? \RankMath\Helper::is_taxonomy_indexable( $taxonomy_name ) : null,
						) : null;
					}

					return rest_ensure_response(
						array(
							'rank_math_options' => $options,
							'rank_math_title_options' => $title_options,
							'taxonomies'         => $taxonomies,
							'sitemap_hooks'      => $hooks,
						)
					);
				},
			)
		);
	}
);

