							return ! empty( $entry['missing_since'] );
						}
					);
					$candidates = TFSC_Cache_Warmer_Plugin::get_sitemap_candidates( $catalog );
					$url_state  = TFSC_Cache_Warmer_Plugin::get_url_state();
					$target_candidate = $candidates[ home_url( '/beroep_werkgebied-sitemap.xml' ) ] ?? array();
					$knowledge_candidate = $candidates[ home_url( '/beroep_kennisgebied-sitemap.xml' ) ] ?? array();
