					$plugin_source = '';
					$iterator = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( TFSC_CACHE_WARMER_DIR ) );
					foreach ( $iterator as $file ) {
						if ( $file->isFile() && 'php' === strtolower( $file->getExtension() ) ) {
							$plugin_source .= "\n" . file_get_contents( $file->getPathname() );
						}
					}
					$forbidden_patterns = array(
						'/CURLOPT_SSL_VERIFYPEER\s*,\s*false/i',
						'/CURLOPT_SSL_VERIFYHOST\s*,\s*[01]/i',
