						array( 'timeout' => 20, 'redirection' => 0, 'reject_unsafe_urls' => true, 'limit_response_size' => 2 * MB_IN_BYTES )
					);
					if ( ! is_wp_error( $index_response ) && 200 === (int) wp_remote_retrieve_response_code( $index_response ) ) {
						$xml = simplexml_load_string( wp_remote_retrieve_body( $index_response ), 'SimpleXMLElement', LIBXML_NONET );
						if ( false !== $xml ) {
							foreach ( $xml->xpath( '//*[local-name()="sitemap"]/*[local-name()="loc"]' ) ?: array() as $loc ) {
