							'asset_warming'        => (int) $settings['asset_warming'],
							'asset_seed_urls'       => $settings['asset_seed_urls'],
							'asset_choices'         => count( $choices ),
							'asset_groups'          => $groups,
							'werkgebied_sitemap'    => in_array( home_url( '/werkgebied-sitemap.xml' ), $catalog, true ),
							'beroep_werkgebied_sitemap' => in_array( home_url( '/beroep_werkgebied-sitemap.xml' ), $catalog, true ),
							'catalog_count'         => count( $catalog ),
							'catalog_matches_index' => $catalog === $index_catalog,
							'missing_history_count' => count( $missing_history ),
							'active_history_overlap' => count( array_intersect( $catalog, array_keys( $missing_history ) ) ),
							'history_panel'         => false !== strpos( $html, 'Niet meer in de huidige sitemap-index' ),
							'inactive_inventory'    => false !== strpos( $html, 'Geregistreerd maar niet actief' ),
							'compact_inventory'     => false !== strpos( $html, 'id="tfsc-sitemap-inventory"' ),
							'beroep_werkgebied_candidate' => ! empty( $target_candidate ),
							'beroep_werkgebied_reason' => $target_candidate['reason'] ?? '',
							'kennisgebied_candidate' => ! empty( $knowledge_candidate ),
							'kennisgebied_total'     => $knowledge_candidate['total'] ?? null,
							'kennisgebied_in_use'    => $knowledge_candidate['nonempty'] ?? null,
							'kennisgebied_rank_math' => $knowledge_candidate['rank_math_enabled'] ?? null,
							'kennisgebied_status'    => $knowledge_candidate['status'] ?? '',
							'url_state_count'       => count( $url_state ),
							'changed_only'          => (int) $settings['changed_only'],
							'batch_size'            => (int) $settings['batch_size'],
							'delay_ms'              => (int) $settings['delay_ms'],
							'freshness_minutes'     => (int) $settings['freshness_minutes'],
							'full_rebuild_action'   => false !== strpos( $html, 'tfsc_cache_warmer_rewarm_all' ),
							'asset_selector'        => false !== strpos( $html, 'id="tfsc-asset-seeds"' ),
							'asset_search'          => false !== strpos( $html, 'id="tfsc-asset-search"' ),
							'asset_overview'        => false !== strpos( $html, 'id="tfsc-asset-overview-list"' ),
							'asset_group_filter'    => false !== strpos( $html, 'id="tfsc-asset-group-filter"' ),
							'asset_group_full_width' => is_string( $admin_source ) && false !== strpos( $admin_source, '.tfsc-asset-filters select{display:block;width:100%!important;max-width:none!important;' ),
							'asset_filter_single_column' => is_string( $admin_source ) && false !== strpos( $admin_source, '.tfsc-asset-filters{display:grid;grid-template-columns:minmax(0,1fr);' ),
							'asset_selected_filter' => false !== strpos( $html, 'id="tfsc-asset-selected-only"' ),
							'asset_toggle'          => false !== strpos( $html, 'name="settings[asset_warming]"' ),
							'source_column'         => false !== strpos( $html, '>Bron <' ),
							'homepage_assets_found' => count( $assets ),
							'external_assets_found' => count( $external ),
							'security_forbidden_hits' => $security_hits,
							'security_pass'         => empty( $security_hits ),
						)
					);
				},
			)
		);
	}
);

