						$group = TFSC_Cache_Warmer_Admin::get_asset_choice_group( $choice['source'] ?? '' );
						$groups[ $group['label'] ] = ( $groups[ $group['label'] ] ?? 0 ) + 1;
					}
					ksort( $groups, SORT_NATURAL | SORT_FLAG_CASE );
					$catalog = TFSC_Cache_Warmer_Plugin::get_sitemap_catalog();
					$knowledge_sitemap = home_url( '/beroep_kennisgebied-sitemap.xml' );
					$study_sitemap = home_url( '/beroep_studierichting-sitemap.xml' );
					$counts_before_sync = $queue->get_counts();
					update_option(
						TFSC_Cache_Warmer_Plugin::OPTION_SITEMAP_CATALOG,
						array_values( array_diff( $catalog, array( $knowledge_sitemap ) ) ),
						false
					);
					do_action(
						'rank_math/settings/after_save',
						'sitemap',
						array( 'tax_beroep_kennisgebied_sitemap' => 'on' )
					);
					$direct_sync_catalog = TFSC_Cache_Warmer_Plugin::get_sitemap_catalog();
					update_option(
						TFSC_Cache_Warmer_Plugin::OPTION_SITEMAP_CATALOG,
						array_values( array_diff( $direct_sync_catalog, array( $study_sitemap ) ) ),
						false
					);
					do_action( 'set_object_terms', 1, array(), array(), 'beroep_studierichting', false, array() );
					TFSC_Cache_Warmer_Plugin::instance()->sync_sitemap_catalog_after_content_change();
					$relation_sync_catalog = TFSC_Cache_Warmer_Plugin::get_sitemap_catalog();
					$counts_after_sync = $queue->get_counts();
					$history = TFSC_Cache_Warmer_Plugin::get_sitemap_history();
					$missing_history = array_filter(
						$history,
						function ( $entry ) {
							return ! empty( $entry['missing_since'] );
						}
					);
					$candidates = TFSC_Cache_Warmer_Plugin::get_sitemap_candidates( $catalog );
					$url_state  = TFSC_Cache_Warmer_Plugin::get_url_state();
					$target_candidate = $candidates[ home_url( '/beroep_werkgebied-sitemap.xml' ) ] ?? array();
					$knowledge_candidate = $candidates[ home_url( '/beroep_kennisgebied-sitemap.xml' ) ] ?? array();
					$vac_status_candidate = $candidates[ home_url( '/vac_status-sitemap.xml' ) ] ?? array();
					$admin_source = file_get_contents( TFSC_CACHE_WARMER_DIR . 'includes/class-admin.php' );

					$plugin_source = '';
					$iterator = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( TFSC_CACHE_WARMER_DIR ) );
					foreach ( $iterator as $file ) {
						if ( $file->isFile() && 'php' === strtolower( $file->getExtension() ) ) {
							$plugin_source .= "\n" . file_get_contents( $file->getPathname() );
						}
					}
