						wp_remote_retrieve_body( $response ),
						home_url( '/' ),
						false,
						0
					);
					$external = array_filter(
						$assets,
						function ( $asset ) {
							return ! TFSC_Cache_Warmer_Discovery::is_same_site_url( $asset['url'] ?? '' );
						}
					);

					$index_catalog = array();
					$index_response = wp_safe_remote_get(
						home_url( '/sitemap_index.xml' ),
						array( 'timeout' => 20, 'redirection' => 0, 'reject_unsafe_urls' => true, 'limit_response_size' => 2 * MB_IN_BYTES )
