						if ( false !== $xml ) {
							foreach ( $xml->xpath( '//*[local-name()="sitemap"]/*[local-name()="loc"]' ) ?: array() as $loc ) {
								$url = TFSC_Cache_Warmer_Discovery::normalize_url( (string) $loc );
								if ( $url ) {
									$index_catalog[] = $url;
								}
							}
						}
					}
