add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'tfsc-deploy/v1',
			'/cache-warmer-056',
			array(
				'methods'             => WP_REST_Server::CREATABLE,
				'permission_callback' => function () {
					return current_user_can( 'install_plugins' ) && current_user_can( 'activate_plugins' );
				},
				'callback'            => function ( WP_REST_Request $request ) {
					$package = $request->get_body();
					$expected = 'b524db753b04cecb9a0ef4e9cd8646de5a46b260ce664899557ebb6f86df9b89';

					if ( '' === $package || strlen( $package ) > 5 * MB_IN_BYTES ) {
						return new WP_Error( 'invalid_package', 'Leeg of te groot installatiepakket.', array( 'status' => 400 ) );
					}

					if ( ! hash_equals( $expected, hash( 'sha256', $package ) ) ) {
						return new WP_Error( 'checksum_mismatch', 'De pakket-checksum klopt niet.', array( 'status' => 400 ) );
					}

					$temp = wp_tempnam( 'tfsc-cache-warmer-0.5.6.zip' );
					if ( ! $temp || strlen( $package ) !== file_put_contents( $temp, $package, LOCK_EX ) ) {
						return new WP_Error( 'temp_write_failed', 'Het installatiepakket kon niet tijdelijk worden opgeslagen.', array( 'status' => 500 ) );
					}

					$zip = new ZipArchive();
					if ( true !== $zip->open( $temp ) ) {
						unlink( $temp );
						return new WP_Error( 'invalid_zip', 'Het installatiepakket is geen geldige ZIP.', array( 'status' => 400 ) );
					}
					$plugin_source = '';
					try {
						for ( $index = 0; $index < $zip->numFiles; $index++ ) {
							$name = (string) $zip->getNameIndex( $index );
							if ( false !== strpos( $name, '../' ) || 0 === strpos( $name, '/' ) ) {
								throw new RuntimeException( 'Onveilig pad in installatiepakket.' );
							}
							if ( '.php' !== strtolower( substr( $name, -4 ) ) ) {
								continue;
							}
							$source = $zip->getFromIndex( $index );
							if ( false === $source ) {
								throw new RuntimeException( 'PHP-bestand kon niet worden gelezen.' );
							}
							token_get_all( $source, TOKEN_PARSE );
							$plugin_source .= "\n" . $source;
						}
					} catch ( Throwable $error ) {
						$zip->close();
						unlink( $temp );
						return new WP_Error( 'php_preflight_failed', $error->getMessage(), array( 'status' => 400 ) );
					}
					$zip->close();

					$forbidden = array(
						'/CURLOPT_SSL_VERIFYPEER\s*,\s*false/i',
						'/CURLOPT_SSL_VERIFYHOST\s*,\s*[01]/i',
						'/permission_callback[^\n]+__return_true/i',
						'/\b(?:eval|exec|system|passthru|shell_exec|proc_open|popen)\s*\(/i',
						'/\bunserialize\s*\(/i',
						'/BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY/i',
					);
					foreach ( $forbidden as $pattern ) {
						if ( preg_match( $pattern, $plugin_source ) ) {
							unlink( $temp );
							return new WP_Error( 'security_preflight_failed', 'Verboden codeconstructie gevonden.', array( 'status' => 400 ) );
						}
					}

					require_once ABSPATH . 'wp-admin/includes/file.php';
					require_once ABSPATH . 'wp-admin/includes/class-wp-upgrader.php';
					require_once ABSPATH . 'wp-admin/includes/plugin.php';

					$skin     = new Automatic_Upgrader_Skin();
					$upgrader = new Plugin_Upgrader( $skin );
					$result   = $upgrader->install( $temp, array( 'overwrite_package' => true ) );
					unlink( $temp );

					if ( is_wp_error( $result ) ) {
						return $result;
					}

					if ( true !== $result ) {
						return new WP_Error( 'install_failed', $skin->get_upgrade_messages(), array( 'status' => 500 ) );
					}

					$plugin = 'tfsc-cache-warmer/tfsc-cache-warmer.php';
					if ( ! file_exists( WP_PLUGIN_DIR . '/' . $plugin ) ) {
						return new WP_Error( 'plugin_missing', 'De pluginmap ontbreekt na installatie.', array( 'status' => 500 ) );
					}

					$data = get_plugin_data( WP_PLUGIN_DIR . '/' . $plugin, false, false );
					$settings = get_option( 'tfsc_cache_warmer_settings', array() );
					$settings = is_array( $settings ) ? $settings : array();
					$settings['changed_only']       = 1;
					$settings['batch_size']         = 3;
					$settings['delay_ms']           = 3000;
					$settings['run_budget_seconds'] = 25;
					$settings['freshness_minutes']  = 10080;
					update_option( 'tfsc_cache_warmer_settings', $settings, false );
					return rest_ensure_response(
						array(
							'installed' => true,
							'plugin'    => $plugin,
							'version'   => $data['Version'],
							'checksum'  => hash_file( 'sha256', WP_PLUGIN_DIR . '/' . $plugin ),
							'settings' => $settings,
						)
					);
				},
			)
		);
	}
);

