/**
 * Tijdelijke alleen-lezen audit van Rank Math redirects.
 */
add_action(
    'rest_api_init',
    function() {
        register_rest_route(
            'tfsc-audit/v1',
            '/rank-math-redirections',
            [
                'methods' => 'GET',
                'permission_callback' => function() {
                    return current_user_can( 'manage_options' );
                },
                'callback' => function() {
                    global $wpdb;
                    $table = $wpdb->prefix . 'rank_math_redirections';
                    $exists = $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $table ) );
                    if ( $exists !== $table ) {
                        return new WP_Error( 'table_not_found', 'Rank Math redirection table not found.', [ 'status' => 404 ] );
                    }
                    $rows = $wpdb->get_results(
                        "SELECT id, url_to, sources, header_code, status, hits, created, updated FROM {$table} ORDER BY id DESC",
                        ARRAY_A
                    );
                    return rest_ensure_response( [ 'rows' => $rows ] );
                },
            ]
        );
    }
);

