						GROUP BY source",
						ARRAY_A
					);
					$stale_asset_failures = (int) $wpdb->get_var(
						"SELECT COUNT(*) FROM {$table}
						WHERE status = 'failed'
						AND source IN ('asset_css', 'asset_js', 'asset_font', 'asset_image')
						AND last_http_status IN (404, 410)"
					);
					$archive_sources = $wpdb->get_results(
						"SELECT source, COUNT(*) AS total FROM {$table}
						WHERE LEFT(source, 18) = 'post_type_archive_' OR LEFT(source, 17) = 'taxonomy_archive_'
						GROUP BY source ORDER BY source",
						ARRAY_A
					);
					$catalog_names = array();
					foreach ( $catalog as $sitemap_url ) {
						$source = TFSC_Cache_Warmer_Discovery::source_for_sitemap( $sitemap_url );
						if ( 0 === strpos( $source, 'sitemap_' ) ) {
							$catalog_names[] = substr( $source, 8 );
						}
					}
					$orphan_archive_sources = array_values(
						array_filter(
							$archive_sources,
							function ( $row ) use ( $catalog_names ) {
								$name = preg_replace( '/^(?:post_type|taxonomy)_archive_/', '', $row['source'] );
								return ! in_array( str_replace( '-', '_', $name ), $catalog_names, true );
							}
						)
					);

					$internal = TFSC_Cache_Warmer_Plugin::get_sitemap_profile(
						home_url( '/nav_menu_item-sitemap.xml' ),
						array( 'status' => 200, 'kind' => 'urlset', 'item_count' => 2 )
					);
					$public = TFSC_Cache_Warmer_Plugin::get_sitemap_profile(
						home_url( '/page-sitemap.xml' ),
						array( 'status' => 200, 'kind' => 'urlset', 'item_count' => 2 )
					);
