					$admin_source = file_get_contents( WP_PLUGIN_DIR . '/tfsc-cache-warmer/includes/class-admin.php' );

					$syntax_files = 0;
					$security_hits = array();
					$forbidden = array(
						'/CURLOPT_SSL_VERIFYPEER\s*,\s*false/i',
						'/CURLOPT_SSL_VERIFYHOST\s*,\s*[01]/i',
						'/permission_callback[^\n]+__return_true/i',
						'/\b(?:eval|exec|system|passthru|shell_exec|proc_open|popen)\s*\(/i',
						'/\bunserialize\s*\(/i',
						'/BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY/i',
					);
					foreach ( new RecursiveIteratorIterator( new RecursiveDirectoryIterator( WP_PLUGIN_DIR . '/tfsc-cache-warmer' ) ) as $file ) {
						if ( ! $file->isFile() || 'php' !== strtolower( $file->getExtension() ) ) {
							continue;
						}
						$source = file_get_contents( $file->getPathname() );
						token_get_all( $source, TOKEN_PARSE );
						$syntax_files++;
						foreach ( $forbidden as $pattern ) {
							if ( preg_match( $pattern, $source ) ) {
								$security_hits[] = basename( $file->getPathname() ) . ':' . $pattern;
							}
						}
					}

					return rest_ensure_response(
						array(
							'version'                  => TFSC_CACHE_WARMER_VERSION,
							'catalog_count'            => count( $catalog ),
							'catalog_health_count'     => count( array_intersect_key( $health, array_fill_keys( $catalog, true ) ) ),
							'unwanted_source_rows'     => $unwanted_sources,
							'stale_asset_failures'     => $stale_asset_failures,
							'archive_sources'          => $archive_sources,
							'orphan_archive_sources'   => $orphan_archive_sources,
							'pop_count'                => count( $pops ),
							'pops'                     => $pops,
							'internal_recommended_off' => ! empty( $internal['recommended_off'] ),
							'public_recommended_off'   => ! empty( $public['recommended_off'] ),
							'public_profile'           => $public,
							'page_publicly_queryable'  => $page_registration->publicly_queryable ?? null,
							'pop_tab'                  => is_string( $admin_source ) && false !== strpos( $admin_source, 'data-tab-target="pops"' ),
							'recommendation_button'    => is_string( $admin_source ) && false !== strpos( $admin_source, 'id="tfsc-sitemap-clear-recommended"' ),
							'no_token_explanation'     => is_string( $admin_source ) && false !== strpos( $admin_source, 'verbruikt dus geen extra QUIC.cloud-verkeer of tokens' ),
							'syntax_files_checked'     => $syntax_files,
							'security_hits'            => $security_hits,
							'security_pass'            => empty( $security_hits ),
						)
					);
				},
			)
		);
	}
);

