add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'tfsc-audit/v1',
			'/plugins-php85',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'permission_callback' => function () {
					return current_user_can( 'manage_options' );
				},
				'callback'            => function () {
					require_once ABSPATH . 'wp-admin/includes/plugin.php';
					$all_plugins = get_plugins();
					$active      = (array) get_option( 'active_plugins', array() );
					$patterns    = array(
						'public_rest_permission' => '/[\'\"]permission_callback[\'\"]\s*=>\s*[\'\"]__return_true[\'\"]/i',
						'public_ajax'            => '/\bwp_ajax_nopriv_/i',
						'public_admin_post'       => '/\badmin_post_nopriv_/i',
						'command_execution'       => '/\b(?:eval|assert|exec|system|passthru|shell_exec|proc_open|popen)\s*\(/i',
						'unsafe_unserialize'      => '/(?<!maybe_)\bunserialize\s*\(/i',
						'dynamic_include'         => '/\b(?:include|require)(?:_once)?\s*\(?\s*\$/i',
						'direct_sql'              => '/\$wpdb\s*->\s*(?:query|get_results|get_var|get_row)\s*\(/i',
						'external_http'           => '/\bwp_remote_(?:get|post|request|head)\s*\(/i',
						'filesystem_mutation'     => '/\b(?:file_put_contents|fwrite|unlink|rename|copy)\s*\(/i',
						'rest_route'              => '/\bregister_rest_route\s*\(/i',
						'admin_post'              => '/\badmin_post_/i',
						'ajax_action'             => '/\bwp_ajax_/i',
						'nonce_check'             => '/\b(?:check_admin_referer|check_ajax_referer|wp_verify_nonce)\s*\(/i',
						'capability_check'        => '/\bcurrent_user_can\s*\(/i',
					);
					$reports = array();

					foreach ( $all_plugins as $plugin_file => $data ) {
						$name = isset( $data['Name'] ) ? (string) $data['Name'] : '';
						$slug = dirname( $plugin_file );
						if ( 0 !== stripos( $name, 'TFSC' ) && 0 !== stripos( basename( $slug ), 'tfsc-' ) ) {
							continue;
						}

						$root = '.' === $slug ? WP_PLUGIN_DIR : WP_PLUGIN_DIR . '/' . $slug;
						if ( ! is_dir( $root ) ) {
							continue;
						}

						$parse_errors = array();
						$findings     = array_fill_keys( array_keys( $patterns ), array() );
						$file_count   = 0;
						$iterator     = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $root ) );
						foreach ( $iterator as $file ) {
							if ( ! $file->isFile() || 'php' !== strtolower( $file->getExtension() ) ) {
								continue;
							}
							$file_count++;
							$path     = $file->getPathname();
							$relative = str_replace( $root . '/', '', $path );
							$code     = file_get_contents( $path );
							try {
								token_get_all( $code, TOKEN_PARSE );
							} catch ( Throwable $error ) {
								$parse_errors[ $relative ] = $error->getMessage();
							}

							foreach ( $patterns as $type => $pattern ) {
								if ( ! preg_match_all( $pattern, $code, $matches, PREG_OFFSET_CAPTURE ) ) {
									continue;
								}
								foreach ( array_slice( $matches[0], 0, 20 ) as $match ) {
									$findings[ $type ][] = $relative . ':' . ( substr_count( substr( $code, 0, $match[1] ), "\n" ) + 1 );
								}
							}
						}

						$reports[] = array(
							'name'         => $name,
							'version'      => isset( $data['Version'] ) ? (string) $data['Version'] : '',
							'plugin_file'  => $plugin_file,
							'active'       => in_array( $plugin_file, $active, true ),
							'files_parsed' => $file_count,
							'parse_errors' => $parse_errors,
							'findings'     => array_filter( $findings ),
						);
					}

					return rest_ensure_response(
						array(
							'php_version'    => PHP_VERSION,
							'php_version_id' => PHP_VERSION_ID,
							'plugin_count'   => count( $reports ),
							'plugins'        => $reports,
						)
					);
				},
			)
		);
	}
);

/**
 * Laat een handmatige Rank Math-description altijd voorgaan.
 * Is die leeg, gebruik dan de ingestelde description-template van het post type.
 * Geldt voor berichten, pagina's en alle custom post types.
 */
function tfsc_rank_math_default_description( $post ) {
	if (
		! $post instanceof \WP_Post ||
		! class_exists( '\RankMath\Helper' )
	) {
		return '';
	}

	$template = \RankMath\Helper::get_settings(
		"titles.pt_{$post->post_type}_description"
	);

	if ( ! is_string( $template ) || '' === trim( $template ) ) {
		return '';
	}

	$description = \RankMath\Helper::replace_vars( $template, $post );
	$description = wp_strip_all_tags( (string) $description );
	$description = preg_replace( '/\s+/u', ' ', $description );

	return trim( (string) $description );
}

function tfsc_rank_math_has_manual_description( $post_id ) {
	if ( ! class_exists( '\RankMath\Post' ) ) {
		return false;
	}

	$manual = \RankMath\Post::get_meta( 'description', $post_id );

	return is_string( $manual )
		? '' !== trim( $manual )
		: ! empty( $manual );
}

// Werkelijke meta-description op de voorkant van de website.
add_filter( 'rank_math/frontend/description', function ( $description ) {
	if ( ! is_singular() ) {
		return $description;
	}

	$post = get_queried_object();

	if ( ! $post instanceof \WP_Post ) {
		return $description;
	}

	// Een handmatig ingevulde SEO-description heeft altijd voorrang.
	if ( tfsc_rank_math_has_manual_description( $post->ID ) ) {
		return $description;
	}

	$default = tfsc_rank_math_default_description( $post );

	return '' !== $default ? $default : $description;
}, 20 );

// Correcte Rank Math-preview in wp-admin, zonder iets in postmeta op te slaan.
add_action( 'admin_enqueue_scripts', function ( $hook_suffix ) {
	if ( ! in_array( $hook_suffix, array( 'post.php', 'post-new.php' ), true ) ) {
		return;
	}

	$screen = get_current_screen();
	$post_id = isset( $_GET['post'] ) ? absint( wp_unslash( $_GET['post'] ) ) : 0;
	$post = $post_id ? get_post( $post_id ) : null;

	if (
		! $screen ||
		empty( $screen->post_type ) ||
		! $post instanceof \WP_Post ||
		! class_exists( '\RankMath\Helper' )
	) {
		return;
	}

	$template = \RankMath\Helper::get_settings(
		'titles.pt_' . $screen->post_type . '_description',
		''
	);

	if ( ! is_string( $template ) || '' === trim( $template ) ) {
		return;
	}

	$previous_post   = isset( $GLOBALS['post'] ) ? $GLOBALS['post'] : null;
	$GLOBALS['post'] = $post;
	setup_postdata( $post );
	rank_math()->variables->setup();

	$resolved = \RankMath\Helper::replace_vars( $template, $post );

	wp_reset_postdata();
	if ( $previous_post instanceof \WP_Post ) {
		$GLOBALS['post'] = $previous_post;
	} else {
		unset( $GLOBALS['post'] );
	}
	$resolved = preg_replace( '/\s+/u', ' ', wp_strip_all_tags( (string) $resolved ) );

	if ( '' === trim( (string) $resolved ) ) {
		return;
	}

	$script = <<<'JS'
(function ( wp, defaultTemplate, resolvedTemplate ) {
	if ( ! wp || ! wp.hooks ) {
		return;
	}

	var namespace = 'tfsc/default-description-preview';
	var applying = false;
	var timer = null;

	function hasManualDescription( value ) {
		return 'string' === typeof value && '' !== value.trim();
	}

	// Laat Rank Math zelf de templatevariabelen live verwerken waar mogelijk.
	wp.hooks.addFilter(
		'rankMath/description',
		namespace,
		function ( manualDescription ) {
			return hasManualDescription( manualDescription )
				? manualDescription
				: defaultTemplate;
		},
		5
	);

	function refreshPreview() {
		try {
			var store = wp.data && wp.data.select( 'rank-math' );
			var actions = wp.data && wp.data.dispatch( 'rank-math' );
			var manualDescription = store && store.getDescription
				? store.getDescription()
				: '';

			if (
				! store ||
				! actions ||
				hasManualDescription( manualDescription )
			) {
				return;
			}

			applying = true;

			// Alleen de tijdelijke previewstatus; dit maakt geen postmeta vuil.
			if ( 'function' === typeof actions.updateAppUi ) {
				actions.updateAppUi( 'serpDescription', resolvedTemplate );
			} else if ( 'function' === typeof actions.updateSerpDescription ) {
				actions.updateSerpDescription( manualDescription );
			}

			document.documentElement.setAttribute(
				'data-tfsc-rankmath-preview-fix',
				'applied'
			);
		} catch ( error ) {
			// Rank Math is nog niet volledig geïnitialiseerd.
		} finally {
			applying = false;
		}
	}

	function queueRefresh( delay ) {
		window.clearTimeout( timer );
		timer = window.setTimeout( refreshPreview, delay );
	}

	// Na Rank Math-initialisatie en na latere previewberekeningen opnieuw toepassen.
	wp.hooks.addAction( 'rank_math_loaded', namespace, function () {
		queueRefresh( 750 );
	}, 99 );

	wp.hooks.addAction( 'rank_math_update_app_ui', namespace, function ( key ) {
		if ( ! applying && 'serpDescription' === key ) {
			queueRefresh( 0 );
		}
	}, 99 );

	queueRefresh( 1500 );
})( window.wp, __TFSC_DEFAULT_TEMPLATE__, __TFSC_RESOLVED_TEMPLATE__ );
JS;

	$script = str_replace(
		array( '__TFSC_DEFAULT_TEMPLATE__', '__TFSC_RESOLVED_TEMPLATE__' ),
		array( wp_json_encode( $template ), wp_json_encode( trim( (string) $resolved ) ) ),
		$script
	);

	wp_enqueue_script( 'wp-hooks' );
	wp_add_inline_script( 'wp-hooks', $script, 'after' );
}, 1 );

// Voorkom een tweede meta-description vanuit het Hello Elementor-thema.
