/**
 * TFSC - Dynamische tekst shortcodes
 *
 * Shortcodes:
 *
 * [post_title]
 * [archive_title]
 * [tfsc_pods field="..."]
 *
 * ============================================================
 * CASE
 * ============================================================
 *
 * case="normal"
 * case="lower"
 * case="sentence"
 *
 *
 * ============================================================
 * [archive_title] MODES
 * ============================================================
 *
 * Term archives:
 *
 * current
 * parents
 * full
 * label_current
 * label_full
 *
 * Taxonomy base archives:
 *
 * taxonomy
 * taxonomy_plural
 *
 *
 * ============================================================
 * PODS OUTPUT
 * ============================================================
 *
 * [tfsc_pods] gebruikt voor normale Pods velden:
 *
 *     $pod->display()
 *
 * in plaats van:
 *
 *     $pod->field()
 *
 * Hierdoor worden de OUTPUT SETTINGS van het Pods veld gebruikt.
 *
 * Dit is met name belangrijk voor:
 *
 * - WYSIWYG velden
 * - wpautop
 * - HTML sanitizing
 * - shortcodes
 * - wptexturize
 * - convert_chars
 *
 * Relationship velden worden apart verwerkt omdat display()
 * daar niet altijd de gewenste losse namen oplevert.
 *
 * BELANGRIJK:
 *
 * case="lower" en case="sentence" worden NIET toegepast op
 * HTML/WYSIWYG output. Daarmee zouden namelijk ook HTML tags
 * en attributen kunnen worden aangepast.
 */


/**
 * ============================================================
 * 1. CONTEXT POST ID
 * ============================================================
 */

function tfsc_text_context_post_id() {

    /**
     * In een normale WordPress- of Elementor-loop wijst get_the_ID()
     * naar het item dat nu wordt gerenderd. Dit moet vóór gedeelde
     * archive-/previewhelpers komen: die helpers cachen hun uitkomst
     * en kunnen daardoor de ID van de eerste loopkaart blijven geven.
     */

    $loop_id = (int) get_the_ID();

    if (
        $loop_id &&
        'elementor_library' !== get_post_type( $loop_id )
    ) {
        return $loop_id;
    }


    /**
     * Enkel bericht buiten een actieve loop.
     */

    $object = get_queried_object();

    if (
        $object instanceof WP_Post &&
        'elementor_library' !== get_post_type( $object->ID )
    ) {
        return (int) $object->ID;
    }


    /**
     * Elementor Theme Builder-preview. De afgeleide helpers blijven
     * nuttig wanneer de huidige post het template zelf is.
     */

    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v3_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }


    if (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {

        $id =
            tfsc_derived_rel_v2_get_context_post_id();

        if ( $id ) {
            return (int) $id;
        }
    }


    return 0;
}


/**
 * ============================================================
 * 2. CONTEXT POD
 * ============================================================
 */

function tfsc_text_context_pod() {

    if (
        ! function_exists(
            'pods'
        )
    ) {
        return false;
    }


    $object =
        get_queried_object();


    /**
     * --------------------------------------------------------
     * TAXONOMY TERM
     * --------------------------------------------------------
     */

    if (
        $object instanceof WP_Term
    ) {

        $pod =
            pods(
                $object->taxonomy,
                (int) $object->term_id
            );


        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }


    /**
     * --------------------------------------------------------
     * POST / CPT / ELEMENTOR PREVIEW
     * --------------------------------------------------------
     */

    $post_id =
        tfsc_text_context_post_id();


    if ( ! $post_id ) {
        return false;
    }


    $post_type =
        get_post_type(
            $post_id
        );


    if ( ! $post_type ) {
        return false;
    }


    $pod =
        pods(
            $post_type,
            $post_id
        );


    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * 3. TAXONOMY BASE OBJECT
 * ============================================================
 */

function tfsc_text_taxonomy_archive_object() {

    if (
        ! function_exists(
            'tfsc_get_current_taxonomy_archive'
        )
    ) {
        return false;
    }


    $taxonomy =
        tfsc_get_current_taxonomy_archive();


    if (
        $taxonomy instanceof WP_Taxonomy
    ) {

        return $taxonomy;
    }


    if (
        is_string(
            $taxonomy
        )
    ) {

        $taxonomy =
            get_taxonomy(
                sanitize_key(
                    $taxonomy
                )
            );


        return (
            $taxonomy instanceof WP_Taxonomy
        )
            ? $taxonomy
            : false;
    }


    return false;
}


/**
 * ============================================================
 * 4. TEXT CASE
 * ============================================================
 */

function tfsc_text_case(
    $text,
    $case = 'normal'
) {

    $text =
        (string) $text;


    if (
        '' === $text
    ) {
        return '';
    }


    switch (
        sanitize_key(
            $case
        )
    ) {

        /**
         * ----------------------------------------------------
         * LOWERCASE
         * ----------------------------------------------------
         */

        case 'lower':

            return
                mb_strtolower(
                    $text,
                    'UTF-8'
                );


        /**
         * ----------------------------------------------------
         * SENTENCE CASE
         * ----------------------------------------------------
         */

        case 'sentence':

            $text =
                mb_strtolower(
                    $text,
                    'UTF-8'
                );


            return

                mb_strtoupper(
                    mb_substr(
                        $text,
                        0,
                        1,
                        'UTF-8'
                    ),
                    'UTF-8'
                )

                .

                mb_substr(
                    $text,
                    1,
                    null,
                    'UTF-8'
                );


        /**
         * ----------------------------------------------------
         * NORMAL
         * ----------------------------------------------------
         */

        default:

            return $text;
    }
}


/**
 * ============================================================
 * 4B. MAXIMUM AANTAL WOORDEN
 * ============================================================
 *
 * max_words="0" of weglaten betekent: geen limiet.
 * Zodra een limiet wordt gebruikt, wordt eventuele HTML uit de
 * ingekorte uitvoer verwijderd. Zonder limiet blijft WYSIWYG-HTML
 * volledig intact.
 */

function tfsc_text_limit_words(
    $text,
    $max_words = 0,
    $more = '…'
) {

    $max_words =
        absint(
            $max_words
        );


    if (
        0 === $max_words
    ) {
        return (string) $text;
    }


    return
        wp_trim_words(
            wp_strip_all_tags(
                (string) $text
            ),
            $max_words,
            (string) $more
        );
}


/**
 * ============================================================
 * 5. [post_title]
 * ============================================================
 *
 * Voorbeelden:
 *
 * [post_title]
 *
 * [post_title case="lower"]
 *
 * [post_title before="Vacature: "]
 */

add_shortcode(
    'post_title',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'before' => '',
                    'after'  => '',
                    'case'   => 'normal',
                ],
                $atts,
                'post_title'
            );


        $post_id =
            tfsc_text_context_post_id();


        if ( ! $post_id ) {
            return '';
        }


        $title =
            wp_strip_all_tags(
                get_the_title(
                    $post_id
                )
            );


        if (
            '' === $title
        ) {
            return '';
        }


        $title =
            tfsc_text_case(
                $title,
                $atts['case']
            );


        return
            (string) $atts['before']
            . $title
            . (string) $atts['after'];
    }
);


/**
 * ============================================================
 * 6. [archive_title]
 * ============================================================
 *
 * TERM ARCHIVE MODES
 *
 * [archive_title]
 * [archive_title mode="current"]
 * [archive_title mode="parents"]
 * [archive_title mode="full"]
 * [archive_title mode="label_current"]
 * [archive_title mode="label_full"]
 *
 *
 * TAXONOMY BASE ARCHIVE MODES
 *
 * [archive_title mode="taxonomy"]
 * [archive_title mode="taxonomy_plural"]
 */

add_shortcode(
    'archive_title',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'mode'            => 'current',
                    'separator'       => ' › ',
                    'label_separator' => ': ',
                    'before'          => '',
                    'after'           => '',
                    'case'            => 'normal',
                ],
                $atts,
                'archive_title'
            );


        $mode =
            sanitize_key(
                $atts['mode']
            );


        $object =
            get_queried_object();


        /**
         * ====================================================
         * TAXONOMY TERM ARCHIVE
         * ====================================================
         */

        if (
            $object instanceof WP_Term &&
            taxonomy_exists(
                $object->taxonomy
            )
        ) {

            $taxonomy =
                $object->taxonomy;


            $current =
                wp_strip_all_tags(
                    $object->name
                );


            $parents = [];


            /**
             * Hiërarchische parents verzamelen.
             */

            if (
                is_taxonomy_hierarchical(
                    $taxonomy
                )
            ) {

                foreach (
                    array_reverse(
                        get_ancestors(
                            $object->term_id,
                            $taxonomy,
                            'taxonomy'
                        )
                    )
                    as $ancestor_id
                ) {

                    $ancestor =
                        get_term(
                            $ancestor_id,
                            $taxonomy
                        );


                    if (
                        $ancestor instanceof WP_Term &&
                        ! is_wp_error(
                            $ancestor
                        )
                    ) {

                        $parents[] =
                            wp_strip_all_tags(
                                $ancestor->name
                            );
                    }
                }
            }


            /**
             * Taxonomy label.
             */

            $taxonomy_object =
                get_taxonomy(
                    $taxonomy
                );


            $label =
                (
                    $taxonomy_object &&
                    ! empty(
                        $taxonomy_object
                            ->labels
                            ->singular_name
                    )
                )
                    ? wp_strip_all_tags(
                        $taxonomy_object
                            ->labels
                            ->singular_name
                    )
                    : '';


            /**
             * Volledige parentstructuur.
             */

            $full =
                implode(
                    (string)
                    $atts['separator'],
                    array_merge(
                        $parents,
                        [ $current ]
                    )
                );


            switch (
                $mode
            ) {

                /**
                 * Parents zonder current term.
                 */

                case 'parents':

                    $output =
                        implode(
                            (string)
                            $atts['separator'],
                            $parents
                        );

                    break;


                /**
                 * Parents + current term.
                 */

                case 'full':

                    $output =
                        $full;

                    break;


                /**
                 * Taxonomy label + current term.
                 */

                case 'label_current':

                    $output =
                        $label
                            ? $label
                                . (string)
                                $atts['label_separator']
                                . $current
                            : $current;

                    break;


                /**
                 * Taxonomy label + volledige hiërarchie.
                 */

                case 'label_full':

                    $output =
                        $label
                            ? $label
                                . (string)
                                $atts['label_separator']
                                . $full
                            : $full;

                    break;


                /**
                 * Alleen huidige term.
                 */

                default:

                    $output =
                        $current;
            }


        /**
         * ====================================================
         * TAXONOMY BASE ARCHIVE
         * ====================================================
         */

        } else {

            $taxonomy_object =
                tfsc_text_taxonomy_archive_object();


            if (
                ! $taxonomy_object
            ) {
                return '';
            }


            switch (
                $mode
            ) {

                /**
                 * Meervoud taxonomy label.
                 */

                case 'taxonomy_plural':

                    $output =
                        $taxonomy_object
                            ->labels
                            ->name
                        ??
                        $taxonomy_object
                            ->label
                        ??
                        '';

                    break;


                /**
                 * Enkelvoud taxonomy label.
                 */

                case 'taxonomy':
                default:

                    $output =
                        $taxonomy_object
                            ->labels
                            ->singular_name
                        ??
                        $taxonomy_object
                            ->label
                        ??
                        '';
            }


            $output =
                wp_strip_all_tags(
                    (string)
                    $output
                );
        }


        if (
            '' === $output
        ) {
            return '';
        }


        $output =
            tfsc_text_case(
                $output,
                $atts['case']
            );


        return
            (string)
            $atts['before']
            . $output
            . (string)
            $atts['after'];
    }
);


/**
 * ============================================================
 * 7. [tfsc_pods]
 * ============================================================
 *
 * Voorbeelden:
 *
 * [tfsc_pods field="intro"]
 *
 * [tfsc_pods field="functie"]
 *
 * [tfsc_pods field="sector" separator=", "]
 *
 * [tfsc_pods field="plaats" case="lower"]
 *
 * [tfsc_pods field="intro" max_words="30"]
 *
 * [tfsc_pods field="intro" max_words="30" more="..."]
 *
 *
 * ============================================================
 * BELANGRIJK VOOR WYSIWYG
 * ============================================================
 *
 * Voor scalar / tekstvelden wordt:
 *
 * $pod->display()
 *
 * gebruikt.
 *
 * Hierdoor gebruikt Pods zelf de ingestelde Output Options
 * van het veld.
 *
 * Dus bijvoorbeeld bij WYSIWYG:
 *
 * - wpautop
 * - sanitize HTML
 * - wptexturize
 * - convert_chars
 * - shortcodes
 *
 * hoeven hier NIET opnieuw door PHP uitgevoerd te worden.
 */

add_shortcode(
    'tfsc_pods',
    function( $atts ) {

        $atts =
            shortcode_atts(
                [
                    'field'     => '',
                    'before'    => '',
                    'after'     => '',
                    'separator' => ', ',
                    'case'      => 'normal',
                    'max_words' => 0,
                    'more'      => '…',
                ],
                $atts,
                'tfsc_pods'
            );


        /**
         * ----------------------------------------------------
         * FIELD
         * ----------------------------------------------------
         */

        $field =
            sanitize_key(
                $atts['field']
            );


        if (
            ! $field
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * POD CONTEXT
         * ----------------------------------------------------
         */

        $pod =
            tfsc_text_context_pod();


        if (
            ! $pod
        ) {
            return '';
        }


        /**
         * ----------------------------------------------------
         * RAW VALUE
         * ----------------------------------------------------
         *
         * field() gebruiken we hier alleen om te bepalen
         * of het om een scalar of relationship/array gaat.
         */

        $value =
            $pod->field(
                $field
            );


        if (
            null === $value ||
            false === $value ||
            '' === $value
        ) {
            return '';
        }


        /**
         * ====================================================
         * SCALAR / TEKST / WYSIWYG
         * ====================================================
         */

        if (
            ! is_array(
                $value
            ) &&
            ! is_object(
                $value
            )
        ) {

            /**
             * Pods verzorgt zelf de frontend output.
             *
             * Voor WYSIWYG worden hierdoor de Output Options
             * van het veld gerespecteerd.
             */

            $output =
                $pod->display(
                    $field
                );


            if (
                null === $output ||
                false === $output
            ) {
                return '';
            }


            $output =
                (string)
                $output;


            if (
                '' === trim(
                    $output
                )
            ) {
                return '';
            }


            /**
             * ------------------------------------------------
             * CASE
             * ------------------------------------------------
             *
             * Alleen toepassen wanneer de output geen HTML
             * bevat.
             *
             * Dit voorkomt dat WYSIWYG HTML kapot wordt
             * gemaakt door strtolower/sentence case.
             */

            if (
                $output ===
                wp_strip_all_tags(
                    $output
                )
            ) {

                $output =
                    tfsc_text_case(
                        $output,
                        $atts['case']
                    );
            }


        /**
         * ====================================================
         * RELATIONSHIP / ARRAY / OBJECT
         * ====================================================
         */

        } else {

            /**
             * Eén relationship normaliseren naar array.
             */

            if (
                is_object(
                    $value
                )
                ||
                (
                    is_array(
                        $value
                    )
                    &&
                    (
                        isset(
                            $value['name']
                        )
                        ||
                        isset(
                            $value['post_title']
                        )
                        ||
                        isset(
                            $value['title']
                        )
                    )
                )
            ) {

                $value =
                    [ $value ];
            }


            $names = [];


            foreach (
                (array)
                $value
                as $relation
            ) {

                /**
                 * --------------------------------------------
                 * ARRAY RELATIONSHIP
                 * --------------------------------------------
                 */

                if (
                    is_array(
                        $relation
                    )
                ) {

                    $name =
                        $relation['name']
                        ??
                        $relation['post_title']
                        ??
                        $relation['title']
                        ??
                        '';


                /**
                 * --------------------------------------------
                 * OBJECT RELATIONSHIP
                 * --------------------------------------------
                 */

                } elseif (
                    is_object(
                        $relation
                    )
                ) {

                    $name =
                        $relation->name
                        ??
                        $relation->post_title
                        ??
                        $relation->title
                        ??
                        '';


                /**
                 * --------------------------------------------
                 * ONBEKEND
                 * --------------------------------------------
                 */

                } else {

                    $name = '';
                }


                $name =
                    wp_strip_all_tags(
                        (string)
                        $name
                    );


                if (
                    '' !== $name
                ) {

                    $names[] =
                        $name;
                }
            }


            /**
             * Dubbelen verwijderen en samenvoegen.
             */

            $names =
                array_values(
                    array_unique(
                        $names
                    )
                );


            $output =
                implode(
                    (string)
                    $atts['separator'],
                    $names
                );


            if (
                '' === $output
            ) {
                return '';
            }


            /**
             * Relationships zijn gewone tekst,
             * dus case kan hier veilig worden toegepast.
             */

            $output =
                tfsc_text_case(
                    $output,
                    $atts['case']
                );
        }


        /**
         * ====================================================
         * MAXIMUM AANTAL WOORDEN
         * ====================================================
         */

        $output =
            tfsc_text_limit_words(
                $output,
                $atts['max_words'],
                $atts['more']
            );


        /**
         * ====================================================
         * OUTPUT
         * ====================================================
         */

        return
            (string)
            $atts['before']
            . $output
            . (string)
            $atts['after'];
    }
);

/**
 * TFSC - Elementor Taxonomy Loop filters
 *
 * Query ID's:
 *
 * taxonomy_level_X
 *
 * current_taxonomy
 * current_taxonomy_level_X
 */


/**
 * Term IDs van exact taxonomy-level ophalen.
 */
function tfsc_taxonomy_level_term_ids(
    $taxonomy,
    $level
) {

    if ( ! taxonomy_exists( $taxonomy ) ) {
        return [];
    }

    $terms = get_terms( [
        'taxonomy'   => $taxonomy,
        'hide_empty' => false,
    ] );

    if (
        is_wp_error( $terms ) ||
        ! $terms
    ) {
        return [];
    }

    $ids = [];

    foreach ( $terms as $term ) {

        if (
            count(
                get_ancestors(
                    $term->term_id,
                    $taxonomy,
                    'taxonomy'
                )
            ) === (int) $level
        ) {
            $ids[] = (int) $term->term_id;
        }
    }

    return $ids;
}


/**
 * Elementor Taxonomy Loop.
 */
add_filter(
    'elementor/loop_taxonomy/args',
    function( $args, $settings, $display_settings ) {

        $query_id = sanitize_key(
            $settings['term_taxonomy_id']
            ?? ''
        );

        if ( ! $query_id ) {
            return $args;
        }


        /**
         * ====================================================
         * taxonomy_level_X
         * ====================================================
         */

        if (
            preg_match(
                '/^taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            )
        ) {

            $taxonomy =
                $args['taxonomy']
                ?? '';

            if ( is_array( $taxonomy ) ) {
                $taxonomy = reset( $taxonomy );
            }

            if ( ! taxonomy_exists( $taxonomy ) ) {
                return $args;
            }

            unset(
                $args['term_taxonomy_id']
            );

            $ids =
                tfsc_taxonomy_level_term_ids(
                    $taxonomy,
                    (int) $matches[1]
                );

            $args['include'] =
                $ids ?: [ 0 ];

            return $args;
        }


        /**
         * ====================================================
         * current_taxonomy
         * current_taxonomy_level_X
         * ====================================================
         */

        $is_current =
            'current_taxonomy' === $query_id;

        $has_level =
            preg_match(
                '/^current_taxonomy_level_([0-9]+)$/',
                $query_id,
                $matches
            );

        if (
            ! $is_current &&
            ! $has_level
        ) {
            return $args;
        }


        $taxonomy =
            get_query_var(
                'tfsc_taxonomy_archive'
            );

        if (
            ! $taxonomy &&
            isset( $GLOBALS['wp_query'] )
        ) {
            $taxonomy =
                $GLOBALS['wp_query']->get(
                    'tfsc_taxonomy_archive'
                );
        }

        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            $args['include'] = [ 0 ];
            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );

        $args['taxonomy']   = $taxonomy;
        $args['hide_empty'] = false;
        $args['orderby']    = 'name';
        $args['order']      = 'ASC';


        /**
         * current_taxonomy = alle terms.
         */
        if ( $is_current ) {
            return $args;
        }


        /**
         * current_taxonomy_level_X.
         */
        $ids =
            tfsc_taxonomy_level_term_ids(
                $taxonomy,
                (int) $matches[1]
            );

        $args['include'] =
            $ids ?: [ 0 ];

        return $args;
    },
    20,
    3
);

/**
 * TFSC - Generic Derived Relationship Taxonomy Terms
 * Version 3.4 - Cascading + All Open Vacancies Fallback
 *
 * ============================================================
 * DOEL
 * ============================================================
 *
 * Toont in een Elementor Taxonomy Loop de taxonomy-terms die
 * voorkomen binnen OPEN vacatures die overeenkomen met alle
 * actieve Pods relationship_ velden van de huidige CPT/post.
 *
 *
 * ============================================================
 * ELEMENTOR
 * ============================================================
 *
 * Elementor Source bepaalt de taxonomy.
 *
 * Voorbeeld:
 *
 * Source:
 * locatie
 *
 * Query ID:
 * relationship_level_1
 *
 *
 * Of:
 *
 * Source:
 * kennisgebied
 *
 * Query ID:
 * relationship_level_0
 *
 *
 * De taxonomy hoeft dus NIET meer in de Query ID te staan.
 *
 *
 * ============================================================
 * RELATIONSHIP LOGICA
 * ============================================================
 *
 * Verschillende taxonomies:
 * AND
 *
 * Binnen dezelfde taxonomy:
 *
 * kennisgebied
 * → AND
 *
 * overige taxonomies
 * → IN / OR
 *
 *
 * ============================================================
 * UITGESLOTEN FIELD
 * ============================================================
 *
 * relationship_vacature_button_url
 *
 * wordt nooit gebruikt om vacatures te filteren.
 *
 *
 * ============================================================
 * LEVEL
 * ============================================================
 *
 * relationship_level_0
 * → alleen top-level terms
 *
 * relationship_level_1
 * → exact één ancestor
 *
 * relationship_level_2
 * → exact twee ancestors
 *
 * Elementor Filter by Depth kan UIT blijven.
 */


/**
 * ============================================================
 * 1. CONFIG
 * ============================================================
 */

function tfsc_derived_rel_v3_vacancy_post_type() {

    return defined( 'TFSC_VACANCY_POST_TYPE' )
        ? TFSC_VACANCY_POST_TYPE
        : 'vacature';
}


function tfsc_derived_rel_v3_status_taxonomy() {

    return defined( 'TFSC_STATUS_TAXONOMY' )
        ? TFSC_STATUS_TAXONOMY
        : 'vac_status';
}


function tfsc_derived_rel_v3_open_status() {

    return defined( 'TFSC_OPEN_STATUS_SLUG' )
        ? TFSC_OPEN_STATUS_SLUG
        : 'open';
}


function tfsc_derived_rel_v3_combo_base() {

    return defined( 'TFSC_COMBO_BASE' )
        ? TFSC_COMBO_BASE
        : 'vacatures';
}


/**
 * ============================================================
 * 2. CPT / POST CONTEXT
 * ============================================================
 */

function tfsc_derived_rel_v3_get_context_post_id() {

    static $resolved = null;

    if ( null !== $resolved ) {
        return $resolved;
    }

    $resolved = 0;
    $object   = get_queried_object();


    /**
     * Normale frontend.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' !== get_post_type( $object->ID )
    ) {
        return $resolved = (int) $object->ID;
    }


    /**
     * Elementor Theme Builder.
     */
    if (
        $object instanceof WP_Post &&
        'elementor_library' === get_post_type( $object->ID )
    ) {

        $template_id = (int) $object->ID;

        if (
            did_action( 'elementor/loaded' ) &&
            class_exists( '\Elementor\Plugin' )
        ) {
            try {

                $document =
                    \Elementor\Plugin::$instance
                        ->documents
                        ->get( $template_id );

                if ( $document ) {

                    $preview_id = absint(
                        $document->get_settings(
                            'preview_id'
                        )
                    );

                    if (
                        $preview_id &&
                        'elementor_library' !==
                        get_post_type( $preview_id )
                    ) {
                        return $resolved = $preview_id;
                    }
                }

            } catch ( Throwable $e ) {
                // Meta fallback hieronder.
            }
        }


        $settings = get_post_meta(
            $template_id,
            '_elementor_page_settings',
            true
        );

        if (
            is_array( $settings ) &&
            ! empty( $settings['preview_id'] )
        ) {

            $preview_id =
                absint(
                    $settings['preview_id']
                );

            if (
                $preview_id &&
                'elementor_library' !==
                get_post_type( $preview_id )
            ) {
                return $resolved = $preview_id;
            }
        }
    }


    /**
     * WordPress / Elementor preview fallback.
     */
    if ( ! empty( $_GET['preview_id'] ) ) {

        $preview_id = absint(
            wp_unslash(
                $_GET['preview_id']
            )
        );

        if (
            $preview_id &&
            'elementor_library' !==
            get_post_type( $preview_id )
        ) {
            return $resolved = $preview_id;
        }
    }


    /**
     * Laatste fallback.
     */
    global $post;

    if (
        $post instanceof WP_Post &&
        'elementor_library' !==
        get_post_type( $post->ID )
    ) {
        return $resolved = (int) $post->ID;
    }


    return 0;
}


/**
 * ============================================================
 * 3. HUIDIGE POD
 * ============================================================
 */

function tfsc_derived_rel_v3_get_current_pod() {

    static $resolved = false;
    static $pod      = false;

    if ( $resolved ) {
        return $pod;
    }

    $resolved = true;

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $post_id =
        tfsc_derived_rel_v3_get_context_post_id();

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if ( ! $post_type ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    if (
        ! $pod ||
        ! $pod->exists()
    ) {
        $pod = false;
    }

    return $pod;
}


/**
 * ============================================================
 * 4. RAW RELATIONSHIP NORMALISEREN
 * ============================================================
 */

function tfsc_derived_rel_v3_normalize_relationship(
    $value
) {

    if ( empty( $value ) ) {
        return [];
    }


    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }


    if ( ! is_array( $value ) ) {
        return [];
    }


    $result = [];


    foreach ( $value as $relation ) {

        $taxonomy = '';
        $term_id  = 0;


        if ( is_array( $relation ) ) {

            $taxonomy = sanitize_key(
                $relation['taxonomy']
                ?? ''
            );

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

        } elseif ( is_object( $relation ) ) {

            $taxonomy = sanitize_key(
                $relation->taxonomy
                ?? ''
            );

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

        } else {

            continue;
        }


        if (
            ! $taxonomy ||
            ! $term_id ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }


        $term = get_term(
            $term_id,
            $taxonomy
        );


        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {

            $result[] = [
                'taxonomy' => $taxonomy,
                'term_id'  => $term_id,
            ];
        }
    }


    return $result;
}


/**
 * ============================================================
 * 5. ALLE ACTIEVE RELATIONSHIPS
 * ============================================================
 */

function tfsc_derived_rel_v3_relationship_groups() {

    static $cache = null;

    if ( null !== $cache ) {
        return $cache;
    }

    $cache = [];

    $pod =
        tfsc_derived_rel_v3_get_current_pod();

    if ( ! $pod ) {
        return [];
    }


    $fields =
        $pod->fields();

    if (
        ! is_array( $fields ) ||
        ! $fields
    ) {
        return [];
    }


    foreach (
        $fields
        as $field_name => $definition
    ) {

        if (
            ! is_string( $field_name ) ||
            0 !== strpos(
                $field_name,
                'relationship_'
            ) ||
            'relationship_vacature_button_url'
            ===
            $field_name
        ) {
            continue;
        }


        $value =
            $pod->field(
                $field_name
            );


        $relationships =
            tfsc_derived_rel_v3_normalize_relationship(
                $value
            );


        foreach (
            $relationships
            as $relationship
        ) {

            $cache[
                $relationship['taxonomy']
            ][] =
                (int)
                $relationship['term_id'];
        }
    }


    /**
     * Dubbelen verwijderen.
     */
    foreach (
        $cache
        as $taxonomy => $ids
    ) {

        $ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            )
        );


        if ( $ids ) {

            $cache[ $taxonomy ] =
                $ids;

        } else {

            unset(
                $cache[ $taxonomy ]
            );
        }
    }


    return $cache;
}


/**
 * ============================================================
 * 6. OPEN VACATURES OP BASIS VAN ALLE RELATIONSHIPS
 * ============================================================
 *
 * Zelfde match-logica als de Combo Base.
 *
 * Verschillende taxonomies = AND.
 *
 * Binnen dezelfde taxonomy:
 *
 * kennisgebied = AND
 * overige = IN / OR
 */

function tfsc_derived_rel_v3_get_vacancy_ids(
    $relationship_groups,
    $limit = -1
) {

    static $cache = [];

    $limit = ( 1 === (int) $limit )
        ? 1
        : -1;

    if ( empty( $relationship_groups ) ) {
        return [];
    }


    /**
     * Stabiele cache-key.
     */
    ksort(
        $relationship_groups
    );

    foreach (
        $relationship_groups
        as &$ids
    ) {

        $ids = array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );

        sort( $ids );
    }

    unset( $ids );


    $key = md5(
        serialize( [
            $relationship_groups,
            $limit,
        ] )
    );


    if ( isset( $cache[ $key ] ) ) {
        return $cache[ $key ];
    }


    $post_type =
        tfsc_derived_rel_v3_vacancy_post_type();


    if ( ! post_type_exists( $post_type ) ) {
        return [];
    }


    $tax_query = [
        'relation' => 'AND',
    ];


    foreach (
        $relationship_groups
        as $taxonomy => $term_ids
    ) {

        if (
            ! taxonomy_exists( $taxonomy ) ||
            ! $term_ids
        ) {
            continue;
        }


        $term_ids = array_values(
            array_unique(
                array_filter(
                    array_map(
                        'intval',
                        $term_ids
                    )
                )
            )
        );


        if ( ! $term_ids ) {
            continue;
        }


        /**
         * Match-methode uit de Combo Base gebruiken.
         *
         * Fallback:
         * kennisgebied = AND
         * overige = OR
         */
        $method =
            function_exists(
                'tfsc_get_combo_taxonomy_match_method'
            )
                ? tfsc_get_combo_taxonomy_match_method(
                    $taxonomy
                )
                : (
                    'kennisgebied' === $taxonomy
                        ? 'AND'
                        : 'OR'
                );


        $tax_query[] = [
            'taxonomy' =>
                $taxonomy,

            'field' =>
                'term_id',

            'terms' =>
                $term_ids,

            'operator' =>
                (
                    'AND' === $method &&
                    count( $term_ids ) > 1
                )
                    ? 'AND'
                    : 'IN',

            'include_children' =>
                false,
        ];
    }


    /**
     * Geen bruikbare relationship-query.
     */
    if ( count( $tax_query ) <= 1 ) {
        return [];
    }


    /**
     * Alleen OPEN vacatures.
     */
    $status_taxonomy =
        tfsc_derived_rel_v3_status_taxonomy();


    if ( taxonomy_exists( $status_taxonomy ) ) {

        $tax_query[] = [
            'taxonomy' =>
                $status_taxonomy,

            'field' =>
                'slug',

            'terms' => [
                tfsc_derived_rel_v3_open_status(),
            ],

            'operator' =>
                'IN',

            'include_children' =>
                false,
        ];
    }


    $ids = get_posts( [
        'post_type' =>
            $post_type,

        'post_status' =>
            'publish',

        'posts_per_page' =>
            $limit,

        'orderby' =>
            'none',

        'update_post_meta_cache' =>
            false,

        'update_post_term_cache' =>
            false,

        'fields' =>
            'ids',

        'no_found_rows' =>
            true,

        'suppress_filters' =>
            false,

        'tax_query' =>
            $tax_query,
    ] );


    return $cache[ $key ] =
        array_values(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            )
        );
}


/**
 * ============================================================
 * 6B. ALLE OPEN VACATURES VOOR DE ALGEMENE EIND-FALLBACK
 * ============================================================
 *
 * Wordt maximaal één keer per paginalaad uitgevoerd.
 */
function tfsc_derived_rel_v3_get_all_open_vacancy_ids() {

    static $cache = null;

    if ( null !== $cache ) {
        return $cache;
    }

    $post_type =
        tfsc_derived_rel_v3_vacancy_post_type();

    if ( ! post_type_exists( $post_type ) ) {
        return $cache = [];
    }

    $args = [
        'post_type' => $post_type,
        'post_status' => 'publish',
        'posts_per_page' => -1,
        'fields' => 'ids',
        'orderby' => 'none',
        'no_found_rows' => true,
        'suppress_filters' => false,
        'update_post_meta_cache' => false,
        'update_post_term_cache' => false,
    ];

    $status_taxonomy =
        tfsc_derived_rel_v3_status_taxonomy();

    if ( taxonomy_exists( $status_taxonomy ) ) {
        $args['tax_query'] = [
            [
                'taxonomy' => $status_taxonomy,
                'field' => 'slug',
                'terms' => [
                    tfsc_derived_rel_v3_open_status(),
                ],
                'operator' => 'IN',
                'include_children' => false,
            ],
        ];
    }

    $ids = get_posts( $args );

    return $cache = array_values(
        array_unique(
            array_map( 'intval', $ids )
        )
    );
}


/**
 * ============================================================
 * 6C. EFFECTIEVE RELATIONSHIPS MET VEILIGE FALLBACK
 * ============================================================
 *
 * 1. Probeer eerst de volledige combinatie.
 * 2. Probeer daarna iedere gekoppelde taxonomy afzonderlijk.
 * 3. Zonder bruikbare term gebruikt de Elementor-loop alle open
 *    vacatures en blijft de knop op /vacatures/.
 */
function tfsc_derived_rel_v3_effective_relationship_groups() {

    static $cache = null;

    if ( null !== $cache ) {
        return $cache;
    }

    $groups =
        tfsc_derived_rel_v3_relationship_groups();

    if ( ! $groups ) {
        return $cache = [];
    }

    /** Volledige combinatie heeft altijd voorrang. */
    if ( tfsc_derived_rel_v3_get_vacancy_ids( $groups, 1 ) ) {
        return $cache = $groups;
    }

    /**
     * Daarna iedere taxonomy afzonderlijk proberen.
     * Bekende inhoudelijke taxonomies krijgen een stabiele volgorde;
     * onbekende relationship-taxonomies worden automatisch toegevoegd.
     */
    $default_priority = [
        'functienaam',
        'kennisgebied',
        'functie-inhoud',
        'bedrijfssector',
        'werkgebied',
        'opleidingsniveau',
        'studierichting',
        'locatie',
    ];

    $fallback_taxonomies = apply_filters(
        'tfsc_derived_rel_v3_fallback_taxonomies',
        $default_priority,
        $groups
    );

    $fallback_taxonomies = array_values(
        array_unique(
            array_filter(
                array_map(
                    'sanitize_key',
                    array_merge(
                        (array) $fallback_taxonomies,
                        array_keys( $groups )
                    )
                )
            )
        )
    );

    foreach ( $fallback_taxonomies as $taxonomy ) {

        if (
            $taxonomy === tfsc_derived_rel_v3_status_taxonomy() ||
            empty( $groups[ $taxonomy ] )
        ) {
            continue;
        }

        $fallback = [
            $taxonomy => $groups[ $taxonomy ],
        ];

        if ( tfsc_derived_rel_v3_get_vacancy_ids( $fallback, 1 ) ) {
            return $cache = $fallback;
        }
    }

    /**
     * Zijn meerdere termen binnen één taxonomy samen te streng,
     * probeer dan iedere gekoppelde term nog afzonderlijk.
     */
    foreach ( $fallback_taxonomies as $taxonomy ) {

        if (
            $taxonomy === tfsc_derived_rel_v3_status_taxonomy() ||
            empty( $groups[ $taxonomy ] ) ||
            count( $groups[ $taxonomy ] ) < 2
        ) {
            continue;
        }

        foreach ( $groups[ $taxonomy ] as $term_id ) {

            $fallback = [
                $taxonomy => [ (int) $term_id ],
            ];

            if ( tfsc_derived_rel_v3_get_vacancy_ids( $fallback, 1 ) ) {
                return $cache = $fallback;
            }
        }
    }

    /** Geen enkele gekoppelde term heeft een open vacature. */
    return $cache = [];
}

/**
 * ============================================================
 * 7. TARGET TERMS UIT VACATURES
 * ============================================================
 */

function tfsc_derived_rel_v3_get_target_term_ids(
    $vacancy_ids,
    $taxonomy
) {

    if (
        ! $vacancy_ids ||
        ! taxonomy_exists( $taxonomy )
    ) {
        return [];
    }


    $ids = wp_get_object_terms(
        array_map(
            'intval',
            $vacancy_ids
        ),
        $taxonomy,
        [
            'fields' => 'ids',
        ]
    );


    if (
        is_wp_error( $ids ) ||
        ! $ids
    ) {
        return [];
    }


    $ids =
        array_map(
            'intval',
            $ids
        );


    if (
        is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        foreach ( $ids as $id ) {

            $ids = array_merge(
                $ids,
                get_ancestors(
                    $id,
                    $taxonomy,
                    'taxonomy'
                )
            );
        }
    }


    return array_values(
        array_unique(
            array_filter(
                array_map(
                    'intval',
                    $ids
                )
            )
        )
    );
}


/**
 * ============================================================
 * 8. EXACT LEVEL
 * ============================================================
 */

function tfsc_derived_rel_v3_filter_level(
    $ids,
    $taxonomy,
    $level
) {

    if ( ! $ids ) {
        return [];
    }


    if (
        ! is_taxonomy_hierarchical(
            $taxonomy
        )
    ) {

        return 0 === (int) $level
            ? array_values(
                array_unique(
                    array_map(
                        'intval',
                        $ids
                    )
                )
            )
            : [];
    }


    return array_values(
        array_filter(
            array_unique(
                array_map(
                    'intval',
                    $ids
                )
            ),
            function( $id ) use (
                $taxonomy,
                $level
            ) {

                return count(
                    get_ancestors(
                        $id,
                        $taxonomy,
                        'taxonomy'
                    )
                ) === (int) $level;
            }
        )
    );
}


/**
 * ============================================================
 * 9. QUERY ID
 * ============================================================
 */

function tfsc_derived_rel_v3_parse_query_id(
    $query_id
) {

    if (
        ! preg_match(
            '/^relationship_level_([0-9]+)$/',
            (string) $query_id,
            $matches
        )
    ) {
        return false;
    }


    return [
        'level' =>
            (int) $matches[1],
    ];
}


/**
 * ============================================================
 * 10. ELEMENTOR TAXONOMY LOOP
 * ============================================================
 */

add_filter(
    'elementor/loop_taxonomy/args',
    function(
        $args,
        $settings,
        $display_settings
    ) {

        $query_id =
            $settings['term_taxonomy_id']
            ??
            $settings[
                'post_taxonomy_term_taxonomy_id'
            ]
            ??
            '';


        $parsed =
            tfsc_derived_rel_v3_parse_query_id(
                $query_id
            );


        if ( ! $parsed ) {
            return $args;
        }


        /**
         * Elementor Source = target taxonomy.
         */
        $taxonomy =
            $args['taxonomy']
            ??
            $settings[
                'post_taxonomy_query_post_type'
            ]
            ??
            '';


        if ( is_array( $taxonomy ) ) {
            $taxonomy =
                reset(
                    $taxonomy
                );
        }


        $taxonomy =
            sanitize_key(
                $taxonomy
            );


        if (
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy ) ||
            $taxonomy ===
            tfsc_derived_rel_v3_status_taxonomy()
        ) {
            return $args;
        }


        /**
         * Alle actieve relationship selections.
         */
        $relationship_groups =
            tfsc_derived_rel_v3_effective_relationship_groups();


        /**
         * Met een bruikbare relationship-fallback: die selectie.
         * Zonder bruikbare relationship: alle open vacatures.
         */
        $vacancy_ids = $relationship_groups
            ? tfsc_derived_rel_v3_get_vacancy_ids(
                $relationship_groups
            )
            : tfsc_derived_rel_v3_get_all_open_vacancy_ids();


        if ( ! $vacancy_ids ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        /**
         * Terms van Elementor Source uit deze vacatures.
         */
        $target_ids =
            tfsc_derived_rel_v3_get_target_term_ids(
                $vacancy_ids,
                $taxonomy
            );


        /**
         * Exact level.
         */
        $target_ids =
            tfsc_derived_rel_v3_filter_level(
                $target_ids,
                $taxonomy,
                $parsed['level']
            );


        if ( ! $target_ids ) {

            $args['include'] = [ 0 ];

            return $args;
        }


        unset(
            $args['term_taxonomy_id']
        );


        $args['taxonomy'] =
            $taxonomy;

        $args['include'] =
            $target_ids;

        $args['hide_empty'] =
            false;

        $args['hierarchical'] =
            false;


        /**
         * Marker voor sorteerfix.
         */
        $args[
            'tfsc_derived_relationship_query'
        ] = 1;


        /**
         * Marker voor combo term-links.
         */
        $GLOBALS[
            'tfsc_derived_rel_v3_active_targets'
        ][ $taxonomy ] =
            true;


        return $args;
    },
    30,
    3
);


/**
 * ============================================================
 * 11. SORTERING
 * ============================================================
 */

add_filter(
    'get_terms',
    function(
        $terms,
        $taxonomies,
        $args,
        $term_query
    ) {

        if (
            is_admin() ||
            empty(
                $args[
                    'tfsc_derived_relationship_query'
                ]
            ) ||
            ! is_array( $terms ) ||
            ! $terms
        ) {
            return $terms;
        }


        if (
            isset( $args['orderby'] ) &&
            'name' !== strtolower(
                (string) $args['orderby']
            )
        ) {
            return $terms;
        }


        $order =
            strtoupper(
                (string) (
                    $args['order']
                    ?? 'ASC'
                )
            );


        if (
            ! in_array(
                $order,
                [
                    'ASC',
                    'DESC',
                ],
                true
            )
        ) {
            $order = 'ASC';
        }


        usort(
            $terms,
            function(
                $a,
                $b
            ) use (
                $order
            ) {

                if (
                    ! $a instanceof WP_Term ||
                    ! $b instanceof WP_Term
                ) {
                    return 0;
                }


                $compare =
                    strnatcasecmp(
                        remove_accents(
                            wp_strip_all_tags(
                                $a->name
                            )
                        ),
                        remove_accents(
                            wp_strip_all_tags(
                                $b->name
                            )
                        )
                    );


                return 'DESC' === $order
                    ? -$compare
                    : $compare;
            }
        );


        return $terms;
    },
    9999,
    4
);


/**
 * ============================================================
 * 12. TERMPAD
 * ============================================================
 */

function tfsc_derived_rel_v3_term_path(
    $term
) {

    if (
        ! $term instanceof WP_Term ||
        ! taxonomy_exists(
            $term->taxonomy
        )
    ) {
        return '';
    }


    $ids =
        is_taxonomy_hierarchical(
            $term->taxonomy
        )
            ? array_reverse(
                get_ancestors(
                    $term->term_id,
                    $term->taxonomy,
                    'taxonomy'
                )
            )
            : [];


    $slugs = [];


    foreach ( $ids as $id ) {

        $ancestor =
            get_term(
                $id,
                $term->taxonomy
            );


        if (
            $ancestor instanceof WP_Term &&
            ! is_wp_error( $ancestor )
        ) {
            $slugs[] =
                $ancestor->slug;
        }
    }


    $slugs[] =
        $term->slug;


    return implode(
        '/',
        array_map(
            'rawurlencode',
            $slugs
        )
    );
}


/**
 * ============================================================
 * 13. COMBO URL
 * ============================================================
 *
 * URL-logica bewust ongewijzigd behouden.
 */

function tfsc_derived_rel_v3_build_combo_url(
    $target_term
) {

    if (
        ! $target_term instanceof WP_Term
    ) {
        return false;
    }


    $groups =
        tfsc_derived_rel_v3_effective_relationship_groups();


    $parts = [
        tfsc_derived_rel_v3_combo_base(),
    ];


    /**
     * Alle actieve relationships toevoegen.
     */
    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        foreach (
            $term_ids
            as $term_id
        ) {

            /**
             * Exact dezelfde target-term niet dubbel toevoegen.
             */
            if (
                $taxonomy ===
                $target_term->taxonomy &&
                (int) $term_id ===
                (int) $target_term->term_id
            ) {
                continue;
            }


            $term =
                get_term(
                    $term_id,
                    $taxonomy
                );


            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }


            $path =
                tfsc_derived_rel_v3_term_path(
                    $term
                );


            if ( ! $path ) {
                continue;
            }


            $parts[] =
                $taxonomy;

            $parts[] =
                $path;
        }
    }


    /**
     * Aangeklikte target term toevoegen.
     */
    $target_path =
        tfsc_derived_rel_v3_term_path(
            $target_term
        );


    if ( ! $target_path ) {
        return false;
    }


    $parts[] =
        $target_term->taxonomy;

    $parts[] =
        $target_path;


    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                fn( $part ) =>
                    trim(
                        $part,
                        '/'
                    ),
                $parts
            )
        )
        .
        '/'
    );
}


/**
 * ============================================================
 * 14. TERM LINKS → COMBO ARCHIVES
 * ============================================================
 */

add_filter(
    'term_link',
    function(
        $termlink,
        $term,
        $taxonomy
    ) {

        if (
            ! empty(
                $GLOBALS[
                    'tfsc_force_native_term_link'
                ]
            ) ||
            is_admin() ||
            ! $term instanceof WP_Term ||
            ! $taxonomy
        ) {
            return $termlink;
        }


        /**
         * Alleen CPT/post-context.
         */
        $object =
            get_queried_object();


        if (
            ! $object instanceof WP_Post
        ) {
            return $termlink;
        }


        if (
            $taxonomy ===
            tfsc_derived_rel_v3_status_taxonomy()
        ) {
            return $termlink;
        }


        /**
         * Alleen taxonomies die daadwerkelijk door deze
         * Elementor relationship-loop geactiveerd zijn.
         */
        if (
            empty(
                $GLOBALS[
                    'tfsc_derived_rel_v3_active_targets'
                ][ $taxonomy ]
            )
        ) {
            return $termlink;
        }


        $url =
            tfsc_derived_rel_v3_build_combo_url(
                $term
            );


        return $url
            ?: $termlink;
    },
    30,
    3
);

/**
 * v5.4: archiefknoppen delen de actieve terugval met de vacaturelijst.
 * Expliciete archiefterm zonder open vacatures wordt overgeslagen;
 * zonder actieve relatie verwijst de knop naar /vacatures/.
 * TFSC - Vacature Button URL + Text
 *
 * Shortcodes:
 *
 * [vacature_button_url]
 * [vacature_button_text]
 *
 * ============================================================
 * WERKING
 * ============================================================
 *
 * 1. relationship_vacature_button_url gevuld?
 *
 *    → gebruik native taxonomy-term URL
 *    → buttontekst = naam van die term
 *
 * 2. relationship_vacature_button_url leeg?
 *
 *    CPT / post:
 *    → tfsc_derived_rel_v3_effective_relationship_groups() met fallback
 *
 *    Taxonomy / term:
 *    → tfsc_taxrel_v4_effective_relationship_groups()
 *
 *    → bouw één TFSC combo archive URL
 *    → buttontekst = "Bekijk vacatures"
 */


/**
 * ============================================================
 * 1. HUIDIGE POD
 * ============================================================
 */

function tfsc_vacature_button_v4_pod() {

    if ( ! function_exists( 'pods' ) ) {
        return false;
    }

    $object = get_queried_object();

    /**
     * Taxonomy-term.
     *
     * Gebruik indien mogelijk dezelfde resolver als
     * de taxonomy relationship-loop.
     */
    if (
        function_exists( 'tfsc_taxrel_v4_current_term' )
    ) {
        $term = tfsc_taxrel_v4_current_term();

        if ( $term instanceof WP_Term ) {

            $pod = pods(
                $term->taxonomy,
                (int) $term->term_id
            );

            return (
                $pod &&
                $pod->exists()
            )
                ? $pod
                : false;
        }
    }

    if ( $object instanceof WP_Term ) {

        $pod = pods(
            $object->taxonomy,
            (int) $object->term_id
        );

        return (
            $pod &&
            $pod->exists()
        )
            ? $pod
            : false;
    }

    /**
     * CPT / post / Elementor preview.
     */
    if (
        function_exists(
            'tfsc_derived_rel_v3_get_context_post_id'
        )
    ) {
        $post_id = (int)
            tfsc_derived_rel_v3_get_context_post_id();

    } elseif (
        function_exists(
            'tfsc_derived_rel_v2_get_context_post_id'
        )
    ) {
        $post_id = (int)
            tfsc_derived_rel_v2_get_context_post_id();

    } elseif (
        $object instanceof WP_Post
    ) {
        $post_id = (int) $object->ID;

    } else {
        $post_id =
            (int) get_queried_object_id();
    }

    if ( ! $post_id ) {
        return false;
    }

    $post_type =
        get_post_type(
            $post_id
        );

    if (
        ! $post_type ||
        'elementor_library' === $post_type
    ) {
        return false;
    }

    $pod = pods(
        $post_type,
        $post_id
    );

    return (
        $pod &&
        $pod->exists()
    )
        ? $pod
        : false;
}


/**
 * ============================================================
 * 2. EXPLICIETE BUTTON TERM
 * ============================================================
 *
 * relationship_vacature_button_url
 */

function tfsc_vacature_button_v4_explicit_term() {

    $pod =
        tfsc_vacature_button_v4_pod();

    if ( ! $pod ) {
        return false;
    }

    $value =
        $pod->field(
            'relationship_vacature_button_url'
        );

    if ( empty( $value ) ) {
        return false;
    }

    if (
        is_object( $value ) ||
        (
            is_array( $value ) &&
            (
                isset( $value['term_id'] ) ||
                isset( $value['pod_item_id'] ) ||
                isset( $value['id'] ) ||
                isset( $value['ID'] )
            )
        )
    ) {
        $value = [ $value ];
    }

    foreach ( (array) $value as $relation ) {

        $term_id  = 0;
        $taxonomy = '';

        if ( is_array( $relation ) ) {

            $term_id = (int) (
                $relation['term_id']
                ?? $relation['pod_item_id']
                ?? $relation['id']
                ?? $relation['ID']
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation['taxonomy']
                    ?? ''
                );

        } elseif ( is_object( $relation ) ) {

            $term_id = (int) (
                $relation->term_id
                ?? $relation->pod_item_id
                ?? $relation->id
                ?? $relation->ID
                ?? 0
            );

            $taxonomy =
                sanitize_key(
                    $relation->taxonomy
                    ?? ''
                );
        }

        if (
            ! $term_id ||
            ! $taxonomy ||
            ! taxonomy_exists( $taxonomy )
        ) {
            continue;
        }

        $term =
            get_term(
                $term_id,
                $taxonomy
            );

        if (
            $term instanceof WP_Term &&
            ! is_wp_error( $term )
        ) {
            if ( get_queried_object() instanceof WP_Term &&
                 function_exists('tfsc_taxrel_v4_vacancy_ids') &&
                 ! tfsc_taxrel_v4_vacancy_ids([$taxonomy => [$term_id]], 1) ) {
                continue;
            }
            return $term;
        }
    }

    return false;
}


/**
 * ============================================================
 * 3. ACTIEVE RELATIONSHIP GROUPS
 * ============================================================
 *
 * Taxonomy-term:
 * → tfsc_taxrel_v4_effective_relationship_groups()
 *
 * CPT / post:
 * → tfsc_derived_rel_v3_relationship_groups()
 */

function tfsc_vacature_button_v4_relationship_groups() {

    $object =
        get_queried_object();

    /**
     * Taxonomy context.
     */
    if (
        $object instanceof WP_Term ||
        (
            function_exists(
                'tfsc_taxrel_v4_current_term'
            ) &&
            tfsc_taxrel_v4_current_term()
            instanceof WP_Term
        )
    ) {

        return function_exists(
            'tfsc_taxrel_v4_effective_relationship_groups'
        )
            ? tfsc_taxrel_v4_effective_relationship_groups()
            : [];
    }

    /**
     * CPT / post context.
     * Gebruik de gevalideerde fallback-groepen wanneer beschikbaar.
     */
    if ( function_exists(
        'tfsc_derived_rel_v3_effective_relationship_groups'
    ) ) {
        return tfsc_derived_rel_v3_effective_relationship_groups();
    }

    return function_exists(
        'tfsc_derived_rel_v3_relationship_groups'
    )
        ? tfsc_derived_rel_v3_relationship_groups()
        : [];
}


/**
 * ============================================================
 * 4. TERM PATH
 * ============================================================
 */

function tfsc_vacature_button_v4_term_path(
    $term
) {

    if (
        function_exists(
            'tfsc_taxrel_v4_term_path'
        )
    ) {
        return tfsc_taxrel_v4_term_path(
            $term
        );
    }

    if (
        function_exists(
            'tfsc_derived_rel_v3_term_path'
        )
    ) {
        return tfsc_derived_rel_v3_term_path(
            $term
        );
    }

    if ( ! $term instanceof WP_Term ) {
        return '';
    }

    return rawurlencode(
        $term->slug
    );
}


/**
 * ============================================================
 * 5. COMBO BASE
 * ============================================================
 */

function tfsc_vacature_button_v4_combo_base() {

    if ( defined( 'TFSC_COMBO_BASE' ) ) {
        return TFSC_COMBO_BASE;
    }

    return 'vacatures';
}


/**
 * ============================================================
 * 6. COMBO URL
 * ============================================================
 */

function tfsc_vacature_button_v4_combo_url() {

    $groups =
        tfsc_vacature_button_v4_relationship_groups();

    if ( ! $groups ) {
        return '';
    }

    $parts = [
        tfsc_vacature_button_v4_combo_base(),
    ];

    foreach (
        $groups
        as $taxonomy => $term_ids
    ) {

        foreach (
            $term_ids
            as $term_id
        ) {

            $term =
                get_term(
                    (int) $term_id,
                    $taxonomy
                );

            if (
                ! $term instanceof WP_Term ||
                is_wp_error( $term )
            ) {
                continue;
            }

            $path =
                tfsc_vacature_button_v4_term_path(
                    $term
                );

            if ( ! $path ) {
                continue;
            }

            $parts[] =
                $taxonomy;

            $parts[] =
                $path;
        }
    }

    if ( count( $parts ) <= 1 ) {
        return '';
    }

    return home_url(
        '/'
        .
        implode(
            '/',
            array_map(
                static fn( $part ) =>
                    trim( $part, '/' ),
                $parts
            )
        )
        .
        '/'
    );
}


