/**
 * TFSC — Uitgelichte afbeelding met hoge laadprioriteit (LiteSpeed), versie 1.0.
 *
 * HANDLEIDING
 * ==========
 * Wat doet dit?
 * Op een afzonderlijke pagina, vacature of artikel zoekt deze regel automatisch
 * de afbeelding die in WordPress als 'Uitgelichte afbeelding' is ingesteld.
 * De EERSTE weergave van die afbeelding krijgt:
 *   - loading="eager": direct laden, niet wachten tot iemand scrollt;
 *   - fetchpriority="high": de browser geeft deze afbeelding voorrang;
 *   - data-no-lazy="1": LiteSpeed mag deze afbeelding niet uitgesteld laden.
 * data-tfsc-priority="featured" is alleen een herkenningspunt voor controles.
 *
 * Hoe gebruik je het?
 * 1. Stel zoals gewoonlijk een uitgelichte afbeelding in bij het bericht.
 * 2. Laat de pagina/template die afbeelding bovenaan tonen.
 * 3. Meer hoef je niet te doen: geen classes, IDs of LiteSpeed-lijsten bijhouden.
 * Verander je de uitgelichte afbeelding, dan volgt deze regel automatisch.
 * De homepage werkt ook wanneer de banner haar uitgelichte afbeelding is.
 *
 * Waar werkt het NIET?
 * Niet op zoekresultaten, categorie-/taxonomiearchieven of berichtenoverzichten.
 * Niet op alle vacaturekaartjes tegelijk. Niet op een willekeurige andere banner
 * of een CSS-achtergrond. Zonder ingestelde/weergegeven uitgelichte afbeelding
 * verandert er niets. De regel kan niet zien of je template de afbeelding pas
 * onderaan zet: gebruik de uitgelichte afbeelding daarom als hoofdbeeld bovenaan.
 * Een tweede kopie van dezelfde afbeelding op de pagina krijgt geen voorrang.
 *
 * Installatie en beheer
 * Sla dit op als PHP-snippet in Code Snippets, scope 'overal uitvoeren'.
 * In de Code Snippets-editor hoort de openingstag <?php er NIET bij.
 * Vereist LiteSpeed Cache en WordPress' ingebouwde HTML Tag Processor.
 * Elementor 'Optimized Image Loading' staat uit; LiteSpeed blijft lazy loading
 * voor de overige afbeeldingen verzorgen. Afbeeldingsmaten, srcset/sizes en
 * ALT/TITLE van de bestaande TFSC-snippet blijven behouden.
 *
 * Controle en terugdraaien
 * Na activeren moeten bestaande HTML-cachepagina's opnieuw worden opgebouwd.
 * Controleer in de paginabron het IMG-element met data-tfsc-priority="featured".
 * Deze regel versnelt alleen de laadkeuze; er wordt geen scorewinst gegarandeerd.
 * Uitschakelen: deactiveer deze snippet en vernieuw daarna de HTML-pagecache.
 * Browsercache, JavaScript, tracking en opgeslagen berichtinhoud veranderen niet.
 *
 * Techniek: één HTML-doorgang vóór LiteSpeed zijn optimalisaties uitvoert.
 * Op een server-cachehit wordt de bestaande HTML gebruikt zonder deze PHP-stap.
 */

if ( ! class_exists( 'TFSC_Featured_Image_Priority', false ) ) {
    final class TFSC_Featured_Image_Priority {
        /** Normalize an attachment URL without matching unrelated external paths. */
        private static function image_url( $url ) {
            return is_string( $url ) ? strtok( $url, '?#' ) : '';
        }

        public static function apply( $html ) {
            if ( ! is_string( $html ) || '' === $html || is_admin()
                || wp_doing_ajax() || ( defined( 'REST_REQUEST' ) && REST_REQUEST )
                || is_feed() || is_preview() || ! is_singular()
                || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
                return $html;
            }

            $post_id  = get_queried_object_id();
            $image_id = $post_id ? (int) get_post_thumbnail_id( $post_id ) : 0;
            if ( ! $image_id ) {
                return $html;
            }

            // The ID class covers Elementor Custom sizes; URLs cover core IMG tags.
            $image_class = 'wp-image-' . $image_id;
            $urls        = [];
            $original    = self::image_url( wp_get_attachment_url( $image_id ) );
            if ( $original ) {
                $urls[ $original ] = true;
            }
            $metadata = wp_get_attachment_metadata( $image_id );
            if ( is_array( $metadata ) && ! empty( $metadata['sizes'] ) ) {
                foreach ( array_keys( $metadata['sizes'] ) as $size ) {
                    $source = wp_get_attachment_image_src( $image_id, $size );
                    if ( is_array( $source ) && ! empty( $source[0] ) ) {
                        $urls[ self::image_url( $source[0] ) ] = true;
                    }
                }
            }

            $processor = new WP_HTML_Tag_Processor( $html );
            while ( $processor->next_tag( 'IMG' ) ) {
                // An already transformed image belongs to another loading pipeline.
                $src = $processor->get_attribute( 'src' );
                if ( ! is_string( $src ) || '' === $src || 0 === strpos( $src, 'data:' )
                    || null !== $processor->get_attribute( 'data-src' ) ) {
                    continue;
                }
                $classes = preg_split( '/\s+/', trim( (string) $processor->get_attribute( 'class' ) ) );
                if ( ! in_array( $image_class, $classes, true )
                    && ! isset( $urls[ self::image_url( $src ) ] ) ) {
                    continue;
                }

                $processor->set_attribute( 'loading', 'eager' );
                $processor->set_attribute( 'fetchpriority', 'high' );
                $processor->set_attribute( 'data-no-lazy', '1' );
                $processor->set_attribute( 'data-tfsc-priority', 'featured' );
                return $processor->get_updated_html();
            }

            return $html;
        }
    }
}

add_filter( 'litespeed_buffer_before', [ 'TFSC_Featured_Image_Priority', 'apply' ], 20 );

