add_action('rest_api_init', function () {
    $permission = function () { return current_user_can('manage_options') && current_user_can('upload_files'); };
    register_rest_route('tfsc-image-maintenance/v1', '/inventory', [
        'methods' => 'GET', 'permission_callback' => $permission,
        'callback' => function () {
            $options = [];
            foreach (['thumbnail_size_w','thumbnail_size_h','thumbnail_crop','medium_size_w','medium_size_h','large_size_w','large_size_h'] as $key) {
                $options[$key] = get_option($key);
            }
            $ids = get_posts(['post_type'=>'attachment','post_status'=>'inherit','posts_per_page'=>-1,'fields'=>'ids',
                'post_mime_type'=>['image/jpeg','image/png','image/webp','image/avif'], 'orderby'=>'ID','order'=>'ASC']);
            return rest_ensure_response(['registered'=>wp_get_registered_image_subsizes(),'options'=>$options,'photo_ids'=>$ids]);
        },
    ]);
    register_rest_route('tfsc-image-maintenance/v1', '/setup', [
        'methods'=>'POST', 'permission_callback'=>$permission,
        'callback'=>function () {
            $before=[];
            foreach (['medium_size_w','medium_size_h','large_size_w','large_size_h'] as $key) {
                $before[$key]=get_option($key);
            }
            if (array_map('intval',array_values($before)) !== [0,0,0,0]) {
                return new WP_Error('configuration_changed','Media settings changed since review.', ['status'=>409]);
            }
            update_option('medium_size_w',480); update_option('medium_size_h',0);
            update_option('large_size_w',1024); update_option('large_size_h',0);
            return rest_ensure_response(['before'=>$before,'configured'=>true]);
        },
    ]);
    register_rest_route('tfsc-image-maintenance/v1', '/backfill', [
        'methods'=>'POST', 'permission_callback'=>$permission,
        'callback'=>function ($request) {
            $ids=$request->get_param('ids');
            if (!is_array($ids) || count($ids)<1 || count($ids)>3) {
                return new WP_Error('invalid_batch','Use a batch of one to three attachment IDs.', ['status'=>400]);
            }
            require_once ABSPATH.'wp-admin/includes/image.php';
            $results=[];
            foreach ($ids as $id) {
                $id=absint($id);
                if (get_post_type($id)!=='attachment' || !in_array(get_post_mime_type($id),['image/jpeg','image/png','image/webp','image/avif'],true)) {
                    $results[]=['id'=>$id,'status'=>'unsupported']; continue;
                }
                $key='tfsc_image_backfill_'.$id;
                if (get_transient($key)) { $results[]=['id'=>$id,'status'=>'busy']; continue; }
                set_transient($key,1,120);
                try {
                    $before=wp_get_attachment_metadata($id);
                    $before_sizes=is_array($before)?($before['sizes']??[]):[];
                    $after=wp_update_image_subsizes($id);
                    if (is_wp_error($after)) {
                        $results[]=['id'=>$id,'status'=>'error','error_code'=>$after->get_error_code()]; continue;
                    }
                    $added=array_diff_key($after['sizes']??[],$before_sizes);
                    $sizes=[];
                    foreach ($added as $name=>$size) {
                        $sizes[$name]=['width'=>$size['width'],'height'=>$size['height'],'bytes'=>$size['filesize']??null];
                    }
                    $results[]=['id'=>$id,'status'=>'ok','added'=>$sizes,'source_width'=>$after['width']??null,'source_height'=>$after['height']??null];
                } finally { delete_transient($key); }
            }
            return rest_ensure_response(['results'=>$results]);
        },
    ]);
    register_rest_route('tfsc-image-maintenance/v1', '/finish', [
        'methods'=>'POST','permission_callback'=>$permission,
        'callback'=>function () { do_action('litespeed_purge_all');return rest_ensure_response(['page_cache_purge_requested'=>true]); },
    ]);
});
